INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'І був цар Соломон царем над усім Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'А оце його провідники́: Азарія, Садоків син, священик.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Еліхореф та Ахійя, сини Шіші, писарі. Йосафа́т, син Ахілудів, канцлер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'А Бена́я, Єгоядин син, — над військом, а Садо́к та Евіятар — священики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'А Азарія, Натанів син, — над намісниками, а Завуд, син Натанів — священик, товариш царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'А Ахішар — над домом, а Адонірам, Авдин син — над даниною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'А в Соломона було дванадцять намісників над усім Ізраїлем, і вони годували царя та дім його, — місяць на рік був на одно́го на годува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'А оце їхні імена: Бен-Гур — в Єфремових гора́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Бен-Декер — у Макаці, і в Шаалевімі, і в Бет-Шемеші, і в Елоні Бет-Ганану.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Бен-Гесед — в Арубботі, йому належали: Сохо та ввесь край Хеферу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Бен-Авінадав — уся околиця Дору; Тафат, Соломонова дочка́, була йому за жінку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Баана, Ахілудів син — Таанах і Меґіддо та ввесь Бет-Шеан, що при Цартані, нижче Їзреелу, від Бет-Шеану аж до Авел-Мехола, аж до того боку Йокмеаму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Бен-Ґевер — у ґілеадському Рамоті, йому належали: оселі Яїра, сина Манасії, що в Ґілеаді, йому околиця Арґову, що в Башані, — шістдеся́т міст великих, із муром та з мідя́ним засу́вом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ахінадав, син Іддо — в Маханаїмі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ахіма́ац — в Нефталимі; також він узяв Босмат, Соломонову дочку́, за жінку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Баана, Хушаїв син, в Асирі та в Бе-Алоті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Йосафа́т, Паруахів син, в Іссахарі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Шім\'ї, Елин син, — у Веніямині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Ґевер, — син Уріїв, — у ґілеадському кра́ї, у кра́ї Сигона, царя аморейського, та Оґа, царя башанського. А один намісник, що в усьому Кра́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Юда та Ізраїль були числе́нні, як пісок, що над морем, щодо многоти́. Вони їли й пили та тішилися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, '');
