INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 49, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 50, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 51, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 52, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 53, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 54, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'А ось чоловік Божий прийшов за Господнім словом із Юди до Бет-Елу. А Єровоам стояв при же́ртівнику, щоб кадити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'І кликнув чоловік Божий при жертівнику за словом Господнім і сказав: „Же́ртівнику, же́ртівнику, — так сказав Господь: Ось у Давидовому домі наро́диться син, Йосія ім\'я́ йому, і він на тобі принесе в жертву священиків па́гірків, що на тобі ка́дять, і кості лю́дські спа́ляться на тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'І дасть він того дня чудо, гово́рячи: Оце те чудо, про яке говорив Господь: Ось цей же́ртівник розпаде́ться, і ви́сиплеться попіл, що на ньому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'І сталося, як цар почув слова цього Божого чоловіка, що кликав до же́ртівника в Бет-Елі, то Єровоам простяг руку свою від же́ртівника, говорячи: „Схопі́ть його!“І всохла рука йому, яку він простяг до нього, і він не міг вернути її до себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'А же́ртівник розпався, і попіл висипався з жертівника, за тим чудом, що дав Божий чоловік за словом Господнім...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'А цар відповів і сказав до Божого чоловіка: „Умилости́в лице Господа, Бога твого, і помолися за мене, і нехай ве́рнеться рука моя до мене!“І чоловік Божий умилости́вив Господнє лице, і царська́ рука вернулася до нього, і була, як перед тим...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'І сказав цар до Божого чоловіка: „Увійди зо мною до дому й попоїж, і я дам тобі да́ра!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'А чоловік Божий сказав до царя: „Якщо ти даси мені пів дому свого, — не ввійду́ я з тобою, і не їстиму хліба, і не питиму води в цьому місці!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Бо так наказано мені за словом Господнім, говорячи: Ти не їстимеш хліба, і не питимеш води, і не ве́рнешся дорогою, якою пішов!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'І пішов він іншою дорогою, і не вернувся тією дорогою, що нею прийшов був до Бет-Елу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'А один старий пророк сидів у Бет-Елі. І прийшли його сини, і розповіли́ йому про ввесь чин, що зробив Божий чоловік сьогодні в Бет-Елі, про ті слова́, що він говорив до царя, — і оповіли́ їх своєму батькові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'I промовив до них їхній батько: „Де́ ж та дорога, якою він пішов?“А його сини бачили ту дорогу, якою пішов Божий чоловік, що прийшов був з Юди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'І сказав він до синів своїх: „Осідла́йте мені осла!“І вони осідлали йому осла, і він сів на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'І поїхав він за Божим чоловіком, і знайшов його, як сидів під дубом. І сказав він до нього: „Чи ти той Божий чоловік, що прийшов із Юди?“А той відказав: „Я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'І сказав він до нього: „Іди зо мною до дому та з\'їж хліба!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'А той відказав: „Не мо́жу вернутися з тобою та ввійти з тобою, і не їстиму хліба, і не питиму води з тобою в цьому місці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Бо було мені ска́зано за словом Господнім: Не їстимеш хліба й не питимеш там води, і не вернешся тією дорогою, якою ти йшов!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'А той відказав йому: „І я пророк, як ти! А Ангол говорив мені за Господнім словом, кажучи: Заверни його з собою до дому свого́, і нехай він їсть хліб і нехай п\'є во́ду“. Він же говорив йому неправду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'І він вернувся з ним, і їв хліб у його домі та пив воду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'І сталося, як сиділи вони при столі, то було Господнє слово до пророка, що вернув його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'І він кликнув до Божого чоловіка, що прийшов із Юди, говорячи: „Так сказав Господь: Тому́, що був ти неслухняний Господнім нака́зам, і не додержував тієї заповіді, що наказав тобі Господь, Бог твій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'і ти вернувся, і їв хліб та пив воду в місці, про яке Він говорив тобі: Не їж хліба й не пий води, — то не вві́йде твій, труп до гро́бу батьків твоїх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'І сталося, як той поїв хліба та напився, то він осідлав йому осла, тому проро́кові, що він вернув його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'І той подався, та спіткав його на дорозі лев, та й забив його. І був ки́нений труп його на дорозі, а осел стояв при ньому, а той лев стояв при тру́пі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Аж ось прихо́дять люди, і побачили того тру́па, ки́неного на дорозі, та лева, що стояв при трупі. І вони прийшли́ й говорили в тім місті, де сидів стари́й пророк.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'І почув про це той пророк, що вернув його з дороги, та й сказав: „Це той Божий чоловік, що був неслухня́ний Господнім наказам, і Господь дав його левові, і він роздер його та вбив його за Господнім словом, що говорив йому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'І сказав він до синів своїх, говорячи: „Осідлайте мені осла!“І осідлали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'І поїхав він, і знайшов його трупа, ки́неного на дорозі, й осла та лева, що стояли при трупі, — не з\'їв той лев трупа й не роздер осла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'І підняв той пророк трупа Божого чоловіка, і поклав його на осла, та й вернув його. І ввійшов стари́й пророк до міста, щоб оплакати та поховати того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'І поклав він його в своїм гробі, і плакали над ним: „Ой, брате мій!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'І сталося по його по́хороні, і сказав він до синів своїх, говорячи: „Коли я помру́, то поховаєте мене в гро́бі, що в ньому похований цей Божий чоловік. При костя́х його покладіть мої кості!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Бо конче збудеться те слово, що він кликнув був за Господнім словом над тим же́ртівником, що в Бет-Елі, та над усіма жертівнико́вими місцями на па́гірках, що в містах самарійских.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'По цій приго́ді Єровоа́м не зійшов зо своєї злої дороги, і настановля́в священиків па́гірків з усього народу, — хто хотів, той призначався, і ставав священиком па́гірків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'І стала та річ гріхом для Єровоамового дому, і на ви́гублення, і на ви́нищення з-над поверхні землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Того ча́су заслаб Авійя, Єровоамів син');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'І сказав Єровоам до своєї жінки: „Устань та переберися, і не пізнають, що ти Єровоамова жінка. І пі́деш до Шіло́, — ото там пророк Ахі́йя, який говорив про мене, що я буду царем над цим народом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'І візьми в свою руку десять хлібі́в і калачі та дзба́нок меду, і вві́йдеш до нього. Він скаже тобі, що́ буде хлопцеві“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'І зробила так Єровоамова жінка. І встала вона, та й пішла до Шіло́, і ввійшла до Ахійєвого дому. А Ахійя не міг бачити, бо очі йому стемні́ли через його старість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'І Господь сказав до Ахійї: „Ось приходить Єровоамова жінка, щоб запитати від тебе слово про сина свого, бо він слаби́й. Отак і так бу́деш їй говорити. І станеться, коли вона вві́йде, то вдаватиме чужу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'І сталося, як Ахійя почув шаруді́ння ніг її, як вона вхо́дила до входу, то сказав: „Увійди, Єровоамова жінко! Чому́ то ти вдаєш чужу́? А я по́сланий до тебе з твердо́ю звісткою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Іди, скажи Єровоамові: Так сказав Господь, Бог Ізраїлів: Тому́, що Я підніс тебе з-посеред народу, і дав тебе за кня́зя над Моїм наро́дом, Ізраїлем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'і відірвав царство від Давидового дому й дав його тобі, та ти не був, як Мій раб Давид, що додержував за́повідей Моїх, і що ходив за Мною всім серцем своїм, щоб робити тільки добре в оча́х Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'і робив ти гірше за всіх, хто був перед тобою, і ти пішов і наробив собі інших богі́в та литих бовва́нів, щоб гніви́ти Мене, а Мене ти відкинув геть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'тому́ ось Я наво́джу лихо на Єровоамів дім, і ви́гублю в Єровоама навіть те, що мочить на стіну, невільника й вільного в Ізраїлі, і ви́мету позостале по Єровоамовім домі, як вимітається сміття́, аж не зоста́неться нічо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Померлого в Єровоама в місті поїдять пси, а померлого на полі поїсть птаство небесне. Так сказав Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'А ти встань, іди до свого дому. Як но́ги твої входитимуть до міста, то помре той хлопець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'І буде його оплакувати ввесь Ізраїль, і поховають його, бо він — один в Єровоама вві́йде до гро́бу, бо тільки в ньому в Єровоамовім домі була́ знайдена добра річ для Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'А Господь поставить Собі царя над Ізраїлем, який ви́губить Єровоамів дім того дня. Та що станеться тепер?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'І поб\'є Господь Ізраїля, і він захитається, як хитається очерет на воді! І вирве Він Ізраїля з-над цієї хорошої землі, яку дав їхнім батькам, і порозкида́є їх по той бік Річки за те, що вони пороби́ли собі Астарти, що гнівають Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'І Він видасть Ізраїля через гріх Єровоа́ма, що грішив сам, і що ввів у гріх Ізраїля“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'І встала Єровоамова жінка, і пішла, і прийшла до Тірци́. Як вона вхо́дила до порога дому, то той хлопець помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'І поховали його, й оплакував його ввесь Ізраїль за словом Господа, що говорив через раба Свого пророка Ахійю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'А решта Єровоамових діл, як він воював та як він царював, ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'А час, який царював Єровоа́м, — двадцять і два роки. І спочив він із батька́ми своїми, а замість нього зацарював син його Нада́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'А Рехав\'ам, син Соломонів, царював у Юді. Рехав\'а́м був віку сорока й одного року, коли зацарюва́в, а царював він сімнадцять літ в Єрусалимі, у тому́ місті, яке вибрав Господь зо всіх Ізраїлевих племе́н, щоб покласти там Своє Йме́ння. А ім\'я́ його матері: аммонітка Наама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'А Юда робив зло в Господніх оча́х, і вони гніви́ли Його більш від усього того, що чинили їхні батьки своїм гріхо́м, яким гріши́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'І також вони будували собі же́ртівники на па́гірках, і стовпи́, і Астарти на кожному високому взгі́р\'ї та під кожним зеленим деревом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'І також були блудодії в тому́ кра́ї, — вони чинили всю гидо́ту тих людей, що Господь прогнав їх від Ізраїлевого обличчя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'І сталося п\'ятого року царя Рехав\'ама, пішов Шуша́к, єгипетський цар, на Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'І позабирав він скарби́ Господнього дому та скарби дому царе́вого, — і все забрав. І забрав він усі золоті щити́, що Соломон поробив був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'А цар Рехав\'а́м поробив замість них мідяні́ щити, і віддав їх на руки провідників бігуні́в, що стерегли́ вхід до царсько́го дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'І бувало, як тільки цар ішов до Господнього дому, бігуни́ носили їх, а потім вертали їх до комори бігунів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'А решта Рехав\'амових діл та все, що́ він зробив, ось вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'А війна між Рехав\'амом та між Єровоамом точи́лася по всі дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'І спочив Рехав\'ам зо своїми батька́ми, і був він похо́ваний зо своїми батька́ми в Давидовому Місті. А ім\'я́ його матері — аммонітя́нка Наама. А замість нього зацарював його син Авійям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'А вісімнадцятого року царя Єровоама, Неватового сина, над Юдою зацарював Авійя́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Три роки царював він в Єрусалимі. А ім\'я́ його матері — Мааха, Авесаломова дочка́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'І він ходив в усіх гріхах свого батька, які той робив перед ним, і серце його не було́ все з Господом, Богом своїм, як серце його батька Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Бо Господь, Бог його, ради Давида дав йому світи́льника в Єрусалимі, щоб поста́вити сина його по ньому та укріпи́ти Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Бо Давид робив добре в Господніх оча́х, і не відступав від усьо́го що Він наказав був йому, по всі дні життя свого, окрім справи хіття́нина Урі́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'А війна між Рехав\'а́мом та між Єровоа́мом точи́лася по всі дні життя його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'А решта Авійямових діл та все, що́ він зробив, ось вони написані в Книзі Хроніки Юдиних царів. І війна точи́лася між Авійямом та між Єровоамом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'І спочив Авійям зо своїми батька́ми, і поховали його в Давидовому Місті, а за́мість нього зацарюва́в син його Аса́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'А року двадцятого Єровоама, Ізраїлевого царя, зацарював Аса́, цар Юдин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'І він царював в Єрусалимі сорок і один рік. А ім\'я́ його матері — Мааха, Авесаломова дочка́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'І робив Аса́ добре в Господніх оча́х, як батько його Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'І вигнав він блудоді́їв із кра́ю, і повикидав усіх божкі́в, яких поробили були їхні батьки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'І на́віть матір свою Мааху, — і її він позбавив пра́ва бути царицею, бо вона зробила була́ і́дола для Астарти. І Аса порубав ідола її, та й спалив у долині Кедро́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'А па́гірки не минулися; тільки Асине серце було все з Господом по всі його дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'І вніс він до Господнього дому присвячені речі свого батька та присвячені речі свої, — срібло, і золото, і по́суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'А війна точи́лася між Асою та між Башою по всі їхні дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'І пішов Баша́, цар Ізраїлів, на Юду, і будував Раму́, щоб не дати нікому від Аси, царя Юдиного, вихо́дити та вхо́дити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'І взяв Аса́ все срібло та золото, позостале в скарбни́цях храму Господнього та дому царе́вого, та й дав його до руки́ своїх слуг. І послав їх цар Аса до Бен-Гадада, сина Тавримонна, сина Хезйонового, сирійського царя, що сидів у Дама́ску, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '„Є умова між мною та між тобою, між ба́тьком моїм та між батьком твоїм. Ось послав я тобі да́ра, срібла та золота, — іди, зламай умову свою з Башею, царем Ізраїлевим, і нехай він віді́йде від ме́не“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'І послухався Бен-Гаддад царя Аси, і послав провідників свойого війська на Ізра́їлеві міста, та й побив Іййона, і Дана, і Авела, Бат-Мааху, і всього Кінерота та всю землю Нефтали́мову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'І сталося, як Баша це почув, то перестав будувати Раму, й осівся в Тірці́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'А цар Аса́ закликав до по́слуху всього Юду, ніко́го не виключа́ючи, і вони повино́сили камі́ння Рами та її дерево, що з них будував був Баша. І цар Аса збудував з того Веніяминову Ґеву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'А решта діл Аси та вся лица́рськість його, і все, що́ він зробив був, і міста, які побудував, — ось вони напи́сані в Книзі Хроніки Юдиних царів; тільки на час ста́рости своєї він заслаб був на свої но́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'І спочив Аса з батька́ми своїми, і був похований з батька́ми своїми в Місті Давида, свого батька. А замість нього зацарював його син Йосафа́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'А над Ізраїлем зацарював Надав, Єровоамів син, у другому році Аси́, царя Юдиного, та й царюва́в над Ізраїлем два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'І робив він зле в Господніх оча́х, і ходив доро́гою батька свого та в гріху́ його, що вводив теж у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'І змо́вився на нього Баша, син Ахійї, з Іссаха́рового до́му, та й побив його Баша в Ґіббетоні филистимському. А Нада́в та ввесь Ізраїль обляга́ли Ґіббетон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'І вбив його Баша в третьому році Аси́, царя Юдиного, та й зацарював замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'І сталося, як зацарював він, то побив увесь Єровоамів дім, — не позоставив Єровоа́мові жодної душі, аж поки не ви́губив його, за словом Господа, що говорив через Свого раба шілонянина Ахійю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'за гріх Єровоа́ма, що грішив сам і що вводив у гріх Ізраїля, через свій гнів, яким гніви́в Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'А решта діл Надава та все, що́ він був зробив, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'А війна точилася між Асо́ю та між Баше́ю, Ізраїлевим царем, по всі дні їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Третього року Аси́, царя Юдиного, зацарював Баша́, син Ахійїн, над усім Ізраїлем у Тірці, на двадцять і чотири роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'І робив він зло в Господніх оча́х, і ходив дорогою Єровоама та в гріху́ його, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'І було Господнє слово до Єгу́, Хананієвого сина, про Башу́, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '„Тому́, що Я підні́с тебе з по́роху, і настановив тебе володарем над Моїм наро́дом, Ізраїлем, а ти пішов Єровоамовою доро́гою та вводив у гріх наро́д Мій, Ізраїля, щоб гніви́ти Мене гріха́ми їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'то ось Я ви́гублю по Баші та по домі його, — зроблю́ твій дім, як дім Єровоама, Неватового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Померлого в Баші в місті з\'їдять пси, а померлого йому на полі, — поїсть пта́ство небесне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'А решта діл Баші, і що́ він зробив був, і лица́рськість його, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'І спочив Баша́ зо своїми батька́ми, і був похований в Тірці, а замість нього зацарював син його Ела́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'І було слово Господнє через пророка Єгу, сина Хананієвого, до Баші та до дому його, а то через усе те зло, що ко́їв він у Господніх оча́х, щоб гніви́ти Його чином своїх рук, щоб бути, як Єровоамів дім, що Він побив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Двадцять і шостого року Аси, царя Юдиного, зацарював Ела, Башин син, над Ізраїлем у Тірці, на два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'І змовився на нього його раб Зімрі, провідни́к половини колесни́ць. І коли він, п\'я́ний, пив у домі Арци, що був над його домом У Тірці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'то прийшов Зімрі й убив його, і вбив його в двадцятому й сьомому році Аси, царя Юдиного, та й зацарював замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'І сталося, як він зацарював та сів на його троні, то він ви́бив увесь Башин дім, — не позоста́вив навіть того, що мочить на стіну, ані рідних його́, ані дру́зів його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'І ви́губив Зімрі ввесь Башин дім, за словом Господа, що промовляв був до Баші через пророка Єгу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'за всі гріхи́ Баші та гріхи Елі, його сина, що грішили самі, і що вво́дили в гріх Ізраїля, щоб гніви́ти Господа, Бога Ізраїлевого, своїми гидо́тами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'А решта діл Елі та все, що́ він робив, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'У році двадцятому й сьомому Аси, царя Юдиного, зацарював Зімрі в Тірці на сім день, коли наро́д обляга́в филистимський Ґіббетон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'І прочу́в наро́д, що облягав, таке: „Змо́вився Зімрі та й убив царя!“І ввесь Ізра́їль настанови́в царем над Ізраїлем Омрі, провідника́ війська, того дня в табо́рі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'І підняли́ся Омрі та ввесь Ізраїль із ним із Ґіббетону, і облягли́ Тірцу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'І сталося, як побачив Зімрі, що місто здобуте, то ввійшов до пала́цу царе́вого дому, та й спалив над собою царськи́й дім огнем, і помер');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'за гріх свій, що грішив ним, щоб робити зло в Господніх оча́х, щоб ходити дорогою Єровоама та в гріху́ його, який він чинив, щоб вводити в гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'А решта діл Зімрі та змова його, що вчинив був, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Тоді Ізраїлів народ поділи́вся пополовині: половина народу була за Тівні, Ґінатового сина, щоб настанови́ти його царем, а половина — за Омрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Та був сильніший наро́д, що стояв за Омрі, від наро́ду, що був за Тівні, Ґінатового сина. І помер Тівні, а зацарюва́в Омрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'У році тридцятому й першому Аси, царя Юдиного, над Ізраїлем зацарював на дванадцять літ Омрі. У Тірці царював він шість років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'І купив він від Шемера го́ру Шомеро́н за два тала́нти срібла, і забудував го́ру, і назвав ім\'я́ міста, яке збудував, іменем пана тієї гори: Шомерон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'І робив Омрі зло в Господніх оча́х, і чинив зло більше від усіх, хто був перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'І ходив він усією дорогою Єровоама, сина Неватового, та в гріхах його, якими вводив у гріх Ізраїля, щоб гніви́ти Господа, Бога Ізраїля, гидо́тами своїми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'А решта діл Омрі, що робив він, та лица́рськість його, яку він чинив був, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'І спочив Омрі з своїми батька́ми, і був похований у Самарії. А замість нього зацарював його син Аха́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Аха́в, син Омрі, зацарював над Ізраїлем у році тридцятому й восьмому Аси, царя Юдиного. І царював Ахав, син Омрі, над Ізраїлем у Самарії двадцять і два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'І робив Ахав, син Омрі, зло в Господніх оча́х більше від усіх, хто був перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'І було́ йому мало ходити в гріхах Єровоама, Неватового сина, — і він узяв за жінку Єзаве́ль, дочку́ Етбаала, сидонського царя. І він пішов, і служив Ваа́лові, і вклонявся йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'І він поставив же́ртівника для Ваа́ла в Вааловому домі, якого збудував у Шомероні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'І зробив Ахав Астарту. І Ахав далі чинив, щоб гнівити Господа, Бога Ізраїлевого, більше від усіх Ізраїлевих царі́в, що були перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'За його днів Хіїл з Бет-Елу відбудува́в Єрихо́на, — на перворіднім своїм Авірамові він заклав його фундаме́нти, а на наймолодшім своїм Сеґівові повставляв брами його, за словом Господа, що говорив через Ісуса, Нави́нового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 36, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 37, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 38, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 39, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 40, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 41, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 42, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'І сказав тішб\'я́нин Ілля́, з ґілеадських ме́шканців, до Ахава: „ Як живий Господь, Бог Ізраїлів, що перед лицем Його я стою́, — цими рока́ми не буде роси та дощу, але тільки за моїм словом!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'І було до нього слово Господнє, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '„Іди звідси, й обе́рнешся собі на схід, і сховаєшся при пото́ці Керіті, що навпроти Йорда́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'І станеться, — будеш ти пити з пото́ку, а кру́кам наказав Я годувати тебе там“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'І він пішов, і зробив за Господнім словом: і пішов, й осівся при потоці Кері́ті, що навпроти Йорда́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'А кру́ки прино́сили йому хліба та м\'яса вранці, і хліба та м\'яса вве́чорі, а з пото́ку він пив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'І сталося на кінці днів, і ви́сох поті́к, бо в краю́ не було дощу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'І було Господнє слово до нього, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '„Устань, іди до Саре́пти сидо́нської, й осядеш там. Ось наказав Я там одній вдові, щоб годувала тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'І він устав та й пішов до Саре́пти. І прибу́в він до входу міста, аж ось там збирає дро́ва одна вдова. І він кликнув до неї й сказав: Візьми мені трохи води до посу́дини, й я нап\'ю́ся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'І пішла вона взяти. А він кликнув до неї й сказав: „Візьми мені й шматок хліба в свою руку!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'А та відказала: „ Як живий Господь, Бог твій, — не маю я калача́, а тільки повну при́горщу бо́рощна в дзбанку́ та трохи олії в горня́ті. А оце я назбираю дві полінці дров, і піду́, і пригото́влю це собі та синові своєму. І з\'їмо́ ми, — та й помремо́“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'І сказав до неї Ілля: „Не бійся! Піди, зроби за своїм словом. Тільки споча́тку зроби мені з того малого калача́, і ви́несеш мені, а для себе та для сина свого зробиш по́тім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Бо так сказав Господь, Бог Ізраїлів: Дзба́нок муки́ не скінчи́ться, і не забра́кне в горня́ті олії аж до дня, як Господь дасть дощу на пове́рхню землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'І пішла вона, і зробила за словом Іллі, і їла вона й він та її дім довгі дні, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, '„дзба́нок муки не скінчи́вся, і не забра́кло в горня́ті олїї“, за словом Господа, що говорив через Іллю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'І сталося по тих приго́дах, — заслаб був син тієї жінки, господині того дому. І була його хвороба дуже тяжка́, аж духу не позосталося в ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'І сказала вона до Іллі: „Що́ тобі до мене, чоловіче Божий? Прийшов ти до мене, щоб згадувати мій гріх та щоб убити мого сина!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'І сказав він до неї: „Дай мені сина свого́!“І він узяв його з лоня її, і виніс його в го́рницю, де він сидів, і поклав його на своєму ліжку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'І кли́кнув він до Господа й сказав: „Господи, Боже мій, чи й цій удові́, що я в неї ме́шкаю, учиниш зло, щоб убити її сина?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'І витягся він тричі над дитиною, і кли́кав до Господа та казав: „Господи, Боже мій, нехай ве́рнеться душа цієї дитини в неї!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'І вислухав Господь голоса Іллі, і верну́лася душа дитини в неї, — і вона ожила́...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'І взяв Ілля дити́ну, і зніс її з го́рниці додо́лу, і віддав її матері її. І сказав Ілля: „Дивися, — твій син живий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'І сказала та жінка до Іллі: „Тепер то я знаю, що ти Божий чоловік, а Господнє слово в устах твоїх — правда!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'І минуло багато днів, і було Господнє слово до Іллі третього року, говорячи: „Іди, покажися до Аха́ва, а Я дам дощ на поверхню землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'І пішов Ілля показатися до Ахава. А в Асирії був сильний голод.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'І покликав Ахав Овді́я, що був над домом, а Овді́й був дуже богобі́йний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'І сталося, коли Єзаве́ль вигу́блювала Господніх пророків, то Овді́й узяв сотню пророків, та й сховав їх по п\'ятидесяти чоловіка в пече́рі, і годува́в їх хлібом та водою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'І сказав Ахав до Овдія: „Іди по кра́ю до всіх во́дних джере́л та до всіх потоків, — може зна́йдемо трави, і позоста́вимо при житті коня та мула, і не ви́губимо худоби“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'І поділили вони собі Край, щоб перейти по ньому, — Ахав пішов однією дорогою сам, Овді́й пішов сам другою дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'І був Овдій у дорозі, аж ось Ілля назу́стріч йому́. І пізнав він його, і впав на обличчя своє та й сказав: „Чи то ти, пане мій Іллє́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'А той відказав йому: „Я. Іди, скажи панові своєму: Ось тут Ілля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'А він сказав: „Чим я прогрішив, що ти віддаєш свого раба в Ахавову руку, щоб він убив мене?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Як живий Господь, Бог твій, — немає наро́ду та царства, що туди не посилав би пан мій шукати тебе. А коли говорили: Нема його, то він заприсяга́в те царство та той народ, що зна́йдуть тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'А тепер ти говориш: Іди, скажи своє́му панові: Ось тут Ілля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'І станеться, я піду́ від тебе, а Дух Господній понесе тебе на те місце, якого не знаю. І прийду́ я, щоб доне́сти Ахаву, а коли він не зна́йде тебе, то вб\'є мене. А раб твій боїться Господа від своєї мо́лодости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Чи ж не було сказано панові моєму те, що́ зробив я, коли Єзаве́ль побивала Господніх пророків, а я сховав був із Господніх пророків сотню чоловіка, по п\'ятидесяти чоловіка в печері, і годував їх хлібом та водою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'А тепер ти кажеш: Іди, скажи своєму панові: Ось тут Ілля, — і він мене вб\'є!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Та Ілля відказав: „ Як живий Господь Савао́т, що я стою́ перед Його лицем, — сьогодні я покажу́ся йому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'I пішов Овді́й назу́стріч Аха́ву, та й доніс йому те. І пішов Ахав навпро́ти Іллі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'І сталося, коли Ахав побачив Іллю, то Ахав сказав до нього: „Чи це ти, що непоко́їш Ізраїля?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'А той відказав: „Не я внещасли́вив Ізраїля, а тільки ти та дім твого батька через ваше недотри́мання Господніх за́повідей, та й ти пішов за Ваалами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'А тепер пошли, збери до мене на го́ру Карме́л усього Ізраїля та чотири сотні й п\'ятдесят Ваалових пророків, та чотири сотні пророків Астарти, що їдять зо сто́лу Єзаве́лі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'І послав Ахав по всіх Ізраїлевих синах, і зібрав пророків на го́ру Карме́л.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'І підійшов Ілля до всьо́го наро́ду й сказав: „Чи довго ви бу́дете скака́ти на двох галу́зках? Якщо Господь — Бог, ідіть за Ним, а якщо Ваал — ідіть за ним!“Та не відповів йому народ ані слова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'І сказав Ілля до наро́ду: „Я сам позоста́вся Господній пророк, а пророків Ваалових — чотири сотні й п\'ятдесят чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'І нехай дадуть нам двох бичкі́в, і нехай вони ви́беруть собі одно́го бичка́, і нехай заріжуть його, і нехай покладуть на дро́ва, а огню́ не покладу́ть. І я приготу́ю одного бичка́, і дам на дро́ва, а огню не покладу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'І ви покличете ім\'я́ бога вашого, а я покли́чу Ім\'я́ Господа. І станеться, той Вог, що відповість огнем, — Він Бог!“І відповів той наро́д та й сказав: „Це добре слово!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'І сказав Ілля до Ваалових пророків: „Виберіть собі одно́го бичка́, і приготу́йте перші, бо ви численні́ші, і покличте ім\'я́ свого́ бога, а огню́ не покладете“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'І взяли́ вони того бичка, що він дав їм, і вони приготува́ли й кли́кали Ваалове ім\'я́ від ра́нку й аж до полу́дня, говорячи: „Ваа́ле, почу́й нас!“Та не було ані голосу, ані ві́дповіді. І скакали вони біля же́ртівника, що зроби́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'І сталося опі́вдні, і сміявся з них Ілля й говорив: „Кличте голосом сильні́шим, бо він бог! Може він розду́мує, або відлучи́вся, або в дорозі! Може він спить, то проки́неться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'І стали вони кликати голосом сильні́шим, і коло́лися, за своїм зви́чаєм, меча́ми та ра́тищами, аж лила́ся з них кров.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'І сталося, як минувся пі́вдень, то вони пророкували аж до часу прине́сення хлібної жертви, — та не було́ ані голосу, ані відповіді, ані слуху...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'І сказав Ілля до всього наро́ду: „Підійдіть до ме́не!“І підійшов увесь наро́д до нього, а він поправив розбитого Господнього же́ртівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'І взяв Ілля дванадцятеро каміння, за числом племе́н синів Якова, до якого було слово Господнє, говорячи: „Ізра́їль буде їм\'я́ твоє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'і збудува́в із того камі́ння же́ртівника в Ім\'я́ Господнє, і зробив рова, площею на дві са́ті насіння, навколо же́ртівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'І наклав дров, і зарізав бичка та й поклав на дро́вах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'І він сказав: „Напо́вніть чотири відрі́ води, і нехай виллють на цілопа́лення та на дро́ва“. І сказав: „Повторіть!“І повтори́ли. І сказав: „Зробіть утре́тє!“І зробили втре́тє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'І потекла вода навколо же́ртівника, а також рів напо́внився водою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'І сталося в час прине́сення хлі́бної жертви, що підійшов пророк Ілля та й сказав: „Господи, Боже Авраамів, Ісаків та Ізраїлів! Сьогодні пізна́ють, що Ти Ізраїлів Бог, а я Твій раб, і що все оце я зробив Твоїм словом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Вислухай мене, Господи, вислухай мене, і нехай пізна́є цей наро́д, що Ти — Господь, Бог, і Ти обе́рнеш їхнє серце наза́д!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'І спав Господній огонь, та й поже́р цілопа́лення, і дро́ва, і камі́ння, і по́рох, і ви́лизав воду, що в рові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'І побачили це всі люди, та й попа́дали на обличчя свої й говорили: „Господь, — Він Бог, Господь, — Він Бог!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'І сказав до них Ілля: „Схопі́ть Ваалових пророків! Нехай ніхто не втече́ з них!“І похапа́ли їх, а Ілля звів їх до потоку Кішо́н, та й порізав їх...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'І сказав Ілля до Ахава: „Увійди, їж і пий, бо ось чути шум дощу́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'І пішов Ахав, щоб їсти та нити, а Ілля зійшов на верхі́в\'я Карме́лу, і нахили́вся до землі, і поклав обличчя своє між свої колі́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'І сказав він до свого хло́пця: „Вийди, подивися в на́прямі моря!“І той вийшов і подивився та й сказав: „Нема нічо́го“. Та він відказав: „Вернися сім раз!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'І сталося сьомого разу, і він сказав: „Ось мала хмара, немов долоня лю́дська, підійма́ється з моря“. А він сказав: „Піди, скажи Ахавові: Запрягай і зійди, і не затримає тебе дощ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'І сталося по недовгому ча́сі, і поте́мніло небо від хмар, і зірвався вітер, — і пішов великий дощ. А Ахав сів на воза, та й відправився в Їзреел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'А Господня рука була́ на Іллі. І він опереза́в свої сте́гна, та й побіг перед Ахавом аж до самого Їзреелу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'А Аха́в доніс Єзаве́лі все, що́ зробив був Ілля, і все те, що він повбивав усіх пророків мече́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'І послала Єзаве́ль посланця́ до Іллі, говорячи: „Отак нехай зро́блять мені бо́ги, і так нехай додадуть, якщо цього ча́су взавтра я не зроблю́ душі твоїй, як зро́блено душі кожного з них!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'І побачив він це, і встав та й пішов, боячи́сь за душу свою́. І прийшов він до Юдиної Беер-Шеви, і позоставив там свого хло́пця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'А сам пішов пустинею, дорогою одного дня, і сів під одним ялівце́м, і зажадав собі смерти, і сказав: „До́сить тепер, Господи! Візьми душу мою, бо я не ліпший від батькі́в своїх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'І поклався він, і заснув під одним ялівце́м. Аж ось Ангол діткнувся його та й сказав йому: „Устань та попоїж!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'І глянув він, аж ось у його голова́х кала́ч, спечений на вугіллі, та дзба́нок води. І він їв та пив, і зно́ву поклався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'І вернувся Ангол Господній удруге, і діткнувся його та й сказав: „Устань, попоїж, бо дорога тяжка́ перед тобою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'І він устав, і попоїв та напився. І він ішов, підкрі́плений тією їжею, сорок день та сорок ноче́й аж до Божої гори Хори́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'І прибу́в він туди до печери, і переночува́в там, аж ось Господнє слово до нього. І сказав Він йому: „Чого́ ти тут, Іллє́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'А той відказав: „Я був дуже горливий для Господа, Бога Савао́та, бо Ізраїлеві сини покинули заповіта Твого та порозбива́ли же́ртівники Твої, а пророків Твоїх повбивали мече́м, — і позостався я сам. І шукали вони душу мою, щоб узяти її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'А Він відказав: „Вийди, і станеш на горі перед Господнім лицем. Аж ось перехо́дитиме Господь, а перед Господнім лицем вітер великий та міцни́й, що зриває го́ри та скелі лама́є. Та не в вітрі Господь. А по вітрі — трус землі, та не в трусі Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'А по трусі огонь, — і не в огні Господь. А по огні — тихий ла́гідний голос“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'І сталося, як почув це Ілля, то закрив своє обличчя плаще́м своїм, та й ви́йшов, і став у входа печери. Аж ось до нього Голос, шо говорив: „Чого́ ти тут, Іллє́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'А він відказав: „Я був дуже горливий для Господа, Бога Савао́та, бо Ізраїлеві сини покинули заповіта Твого та порозбивали же́ртівники твої, а пророків Твоїх повбивали мече́м, — і позоста́вся я сам. І шукали вони душу мою, щоб узяти її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'І сказав до нього Господь: „Іди, вернися на свою доро́гу на Дамаську пустиню. І при́йдеш, і пома́жеш Хазаїла на царя над Сирією.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'А Єгу, Німшієвого сина, помажеш на царя над Ізраїлем, а Єлисе́я, Шафатового сина з Авел-Мехоли, помажеш на пророка замість се́бе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'І станеться, — хто втече від Хазаїлового меча, того вб\'є Єгу, а хто втече від меча Єгу, того вб\'є Єлисе́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'А в Ізраїлі Я позоста́вив сім тисяч, — усі коліна, що не схиля́лися перед Ваалом, та всі уста, що не цілували його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'І пішов він ізві́дти, і знайшов Єлисе́я, Шафатового сина, а він оре́. Дванадцять за́прягів перед ним, а він при дванадцятому. І підійшов до нього Ілля та й кинув йому свого плаща́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'І позоставив той волів, та й побіг за Іллею й сказав: „Нехай поцілую я батька свого́ та свою матір, — та й піду́ за тобою!“А той відказав йому: „Іди, але вернися, бо що́ я зробив тобі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'І вернувся він від нього, і взяв за́пряга волів та й прині́с його в жертву, а я́рмами волів зварив його м\'ясо, і дав народові, а ті їли. І він устав, і пішов за Іллею, та й служив йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'А Бен-Гада́д, цар сирі́йский, зібрав усе своє ві́йсько та тридцять і два царі з ним, і коні, і колесни́ці. І пішов він, і обліг Самарію та й воював проти неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'І послав він послів до Ахава, царя Ізраїлевого, до міста,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'та й сказав йому: „Так сказав Бен-Гада́д: Срібло твоє та золото твоє — моє воно, а жінки́ твої та сини́ твої, ці найліпші, — мої вони“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'І відповів Ізраїлів цар та й сказав: „ Буде за словом твоїм, пане мій ца́рю! Твій я та все, що моє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'І знову верну́лися ті посли та й сказали: „Так сказав Бен-Гада́д, говорячи: Я посилав до те́бе, говорячи: Ти даси мені срібло своє, і золото своє, і жіно́к своїх, і синів своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'А взавтра цього ча́су пошлю́ я своїх рабів до тебе, і вони перешука́ють дім твій та доми твоїх рабі́в. І станеться, — на все, що сподо́бається їм, вони накладуть свої руки, та й заберуть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'І скликав Ізраїлів цар усіх старши́х Кра́ю та й сказав: „Дові́дайтеся й побачите, що він шукає зла, бо послав до мене по жіно́к моїх, і по синів моїх, і по срібло моє, і по золото моє, — і я йому не відмовив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'І сказали до нього всі старші́ та ввесь народ: „Не слухай, і не пого́джуйся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'І сказав він до послів Бен-Гадада: „Скажіть моєму панові цареві: Усе, про що́ посилав ти до свого раба напоча́тку, я зроблю́, а цієї речі зробити не мо́жу“. І пішли посли, і відне́сли йому відповідь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'І послав до нього Бен-Гада́д та й сказав: „Нехай так зро́блять мені бо́ги, і нехай так додаду́ть, якщо самарійського по́роху вистачить по жмені всьому народо́ві, що стоїть при мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'І відповів Ізраїлів цар та й сказав: „Кажіть: Хай не хва́литься той, хто меча припина́є, а той, хто розв\'я́зує“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'І сталося, як почув він цю відповідь, — а він пив, він та царі в ша́трах, — то сказав до своїх рабів: „Пустіть тарани́!“І вони пустили тарани́, на місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Аж ось один пророк підійшов до Аха́ва, Ізраїлевого царя, та й сказав: „Так сказав Господь: Чи бачив ти ввесь оцей великий на́товп? Ось Я даю його сьогодні в руку твою, і ти пізна́єш, що Я — Господь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'І сказав Ахав: „Ким?“А той відказав: „Так сказав Господь: Слу́гами начальників округ“. І сказав: „Хто розпічне́ війну?“А той відказав: „Ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'І перелічив він слуг начальників судо́вих окру́г, і було дві сотні й тридцять два. А по них перелічив увесь наро́д, усіх Ізраїлевих синів, — сім тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'І вийшли вони опі́вдні, а Бен-Гадад пив п\'я́ний у ша́трах, він та царі, — тридцять і два царі, що допомагали йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'І вийшли напоча́тку слуги начальників округ. І послав Бен-Гадад, і доне́сли йому, кажучи: „Ось повихо́дили люди з Самарії.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'А він відказав: „Якщо на мир вийшли вони, — схопі́ть їх живих, а якщо на війну повихо́дили, — теж живими схопі́ть їх у неволю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'А то вийшли з міста слуги начальників округ та ві́йсько, що йшло за ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'І побива́ли вони один о́дного, і побігли сирі́яни, а Ізра́їль їх гнав. Та втік Бен-Гадад, сирійський цар, на коні та з верхівця́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'І вийшов Ізраїлів цар, та й побив коні та колесни́ці, і завдав в Сирії великої пора́зки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'І підійшов пророк до Ізраїлевого царя та й сказав йому: „Іди, тримайся мужньо, і пізнай та побач, що́ ти зробиш, бо, як мине рік, сирійський цар зно́ву пі́де на тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'А слуги сирійського царя сказали йому: „Бог гір — їхній Бог, тому́ вони були сильніші від нас. Але воюймо з ними на рівни́ні, — присягаємо, що бу́демо сильніші від них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'І зроби цю річ: Поскида́й тих царів, кожного з його місця, і понаставля́й намі́сників замість них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'А ти збереш собі ві́йсько, як те, що відпало від тебе, і ко́ней, скільки було ко́ней, і колесни́ць, скільки було колесни́ць, і бу́демо воювати з ними на рівни́ні. Присягаємо, що ми бу́демо сильніші від них!“І він послухався їхнього голосу, і зробив так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'І сталося по році, і Бен-Гада́д переглянув Сирію, і пішов до Афеку на війну з Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'А Ізраїлеві сини були перегля́нені й забезпечені живністю, та й вийшли навпроти них. І таборува́ли Ізраїлеві сини навпроти них, як дві отарі кіз, а сиріяни напо́внили Край.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'І підійшов Божий чоловік, і говорив до Ізраїлевого царя та й сказав: „Так сказав Господь: Тому́, що сказали сирі́яни: Господь — Бог гір, а не Бог долин Він, то дам увесь цей великий на́товп у твою руку, і ви пізна́єте, що Я — Господь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'І таборува́ли ті навпроти тих сім день. І сталося сьомого дня, і розпали́вся бій, — і побили Ізраїлеві сини Сирію, сто тисяч піхоти, одно́го дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'А позосталі повтікали до Афеку, до міста, та впав мур на двадцять і сім тисяч позосталих чоловіка. А Бен-Гадад утік і ввійшов до міста, до вну́трішньої кімнати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'І сказали до нього його слуги: „Ось ми чули, що царі Ізраїлевого дому — вони царі милости́ві. Покладім вере́тища на сте́гна свої, а шнури́ — на свої голови, і вийдім до Ізраїлевого царя, — може він пощади́ть твою душу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'І підпереза́ли вони вере́тищами сте́гна свої, а шнури — на свої голови, і прийшли до Ізраїлевого царя та й сказали: „Твій раб Бен-Гадад сказав: Нехай живе душа моя!“А той відказав: „Чи він іще живий? Він мій брат!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'А ті люди взяли́ це за натя́ка, і поспішили скориста́тися з того й сказали: „Брат твій Бен-Гадад!“І той відказав: „Підіть, приведіть його!“І вийшов до нього Бен-Гадад, а той посадив його на колесни́цю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'І сказав до нього Бен-Гадад: „Ті міста, що ба́тько мій був забрав від твого батька, я поверну́. І ти уря́диш собі в Дама́ску вулиці, як мій батько урядив був у Самарії“. „А я — сказав Ахав — по умові відпущу́ тебе“. І він склав з ним умову, та й відпустив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Тоді один чоловік із пророчих синів сказав до свого ближнього за Господнім словом: „Удар мене!“Та відмовився той чоловік ударити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'І сказав він йому: „За те, що ти не послухався Господнього голосу, то ось ти пі́деш від мене — і вб\'є тебе лев!“І пішов той від нього, і спіткав його лев та й забив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'І знайшов він іншого чоловіка та й сказав: „Удар мене!“І той чоловік ударив його, — ударив та й зранив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'І пішов той пророк, і став цареві на дорозі, і перебрався, і закрив хусткою очі свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'І сталося, цар прохо́див, а він кричав до царя й говорив: „Раб твій ввійшов у сере́дину бою. Аж ось один чоловік відійшов, і підвів до мене мужа й сказав: Пильнуй цього мужа! Якщо його не стане, то буде твоє життя замість його життя, або відважиш тала́нта срібла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'І сталося, раб твій робив тут та тут, а він зник“. І сказав до нього Ізраїлів цар: „Такий твій при́суд, — ти сам проказа́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'А той спішно зняв хустку з-над очей своїх, — і пізнав його Ізраїлів цар, що він із пророків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'А той йому сказав: „Так сказав Господь: Тому́, що ти ви́пустив із руки чоловіка, Мені призна́ченого, то буде життя твоє за його життя, а наро́д твій — за його народ!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'І пішов Ізраїлів цар до свого дому незадово́лений та гнівни́й, і прибув у Самарі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'І сталося по цих приго́дах таке. У їзрееля́нина Наво́та, що в Їзрее́лі, був виногра́дник при палаті Ахава, самарійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'І говорив Ахав до Навота, кажучи: „Дай мені свого виногра́динка, і він буде мені за яри́нного горо́да, бо він близьки́й до мого дому. А я дам тобі замість нього виногра́дника ліпшого від нього. Якщо це добре в оча́х твоїх, я дам тобі срібла, ціну́ його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'І сказав Навот до Ахава: „Заборо́нено мені від Господа, щоб я дав тобі спа́дщину моїх батьків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'І ввійшов Ахав до дому свого незадово́лений та гнівни́й через те слово, яке говорив йому їзрееля́нин Наво́т, бо той сказав: „Не дам тобі спа́дщини батьків моїх!“І ліг він на ліжку своїм, і відвернув своє обличчя, і не їв хліба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'І прийшла до нього жінка його Єзаве́ль та й сказала йому: „Чого́ це твій дух сумни́й, і ти не їси хліба?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'І сказав він до неї: „Бо я говорив до їзрееля́нина Наво́та. І сказав я йому: Дай мені свого виногра́дника за срібло, або, якщо ти хочеш, дам тобі замість нього виноградника ліпшого. Та він відказав: Не дам тобі свого́ виноградника!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'І сказала до нього його жінка Єзаве́ль: „Отепер ти зробишся царе́м над Ізраїлем. Устань, поїж хліба, і нехай буде веселе твоє серце. А виноградника їзреелянина Навота дам тобі я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'І понаписувала вона листи́ в імені Ахава, і позапеча́тувала їх його печа́ткою, та й порозсилала ті листи до старши́х та до вельмо́жних, що були в його місті, що сиділи з Навотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'А в тих листа́х вона понапи́сувала так: „Оголосіть піст, і посадіть Наво́та на чолі́ наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'І посадіть двох негідних людей навпроти нього, — нехай сві́дчать на нього, кажучи: Ти зневажив Бога й царя. І ви́ведіть його, і вкамену́йте його, — і нехай він помре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'І зроби́ли мужі його міста, старші та вельможні, що сиділи в його місті, так, як послала до них Єзаве́ль, як було́ напи́сано в листа́х, які вона порозсила́ла до них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Оголоси́ли вони піст, і посадили Навота на чолі́ народу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'І прийшли два чоловіки негідні, і сіли навпроти нього. І ті негідні люди сві́дчили на нього, на Навота, перед народом, говорячи: „Навот знева́жив Бога й царя!“І вивели його поза місто, та й укаменува́ли його камінням, — і він помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'І послали вони до Єзаве́лі, говорячи: „Наво́т укамено́ваний і помер“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'І сталося, як почула Єзаве́ль, що Наво́т укамено́ваний і помер, то сказала Єзавель до Ахава: „Устань, посядь виноградника їзреелянина Навота, що відмовив дати його тобі за срібло, бо Наво́т не живий, а помер“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'І сталося, як почув Ахав, що Навот помер, то Ахав устав, щоб зійти до виноградника їзреелянина Навота, щоб посісти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'І було Господнє слово до тішб\'я́нина Іллі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '„Устань, зійди назу́стріч Ахава, Ізраїлевого царя, що в Самарії, ось він у Навотовому винограднику, куди зійшов, щоб посісти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'І будеш говорити до нього, кажучи: Так сказав Господь: Ти вбив, а тепер хочеш посісти? І говоритимеш до нього, кажучи: Так сказав Господь: На тому місці, де пси лизали Навотову кров, пси лизатимуть і твою власну кров!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'І сказав Ахав до Іллі: „Ось ти знайшов мене, во́роже мій!“А той відказав: „Знайшов, бо ти запро́дався чинити зло в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Ось Я спрова́джую на тебе лихо, і ви́гублю все за тобою, і вигублю Ахавові навіть те, що мо́чить на стіну, і невільного та вільного в Ізраїлі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'І зроблю́ з твоїм домом, як із домом Єровоама, Неватового сина, й як із домом Баші, Ахієвого сина, за той гнів, яким розгніви́в ти Мене та ввів у гріх Ізраїля“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'І також до Єзавелі говорив Господь, кажучи: „Пси з\'їдять Єзавель на передму́р\'ї Їзрее́лу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Померлого в Ахава в місті поїдять пси, а померлого на полі — поїсть птаство небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Бо ще не було такого, як Ахав, що запро́дався чинити зло в Господніх оча́х, що його намовила жінка його Єзаве́ль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'І він чинив дуже гидке, ідучи за ідолами, усе так, як робили аморе́яни, що їх Господь повиганя́в перед Ізраїлевими сина́ми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'І сталося, як Аха́в почув ці слова, то розде́р він шати свої́, і зодягну́в на тіло своє вере́тище, і по́стив, і лежав у вере́тищі, і ходив сумови́то...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'І було Господнє слово до тішб\'янина Іллі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '„Чи ти спостері́г, що Ахав упокори́вся перед лицем Моїм? За те, що він упокори́вся перед Моїм лицем, не наведу́ Я лиха за його днів, — за днів його сина наведу́ Я те лихо на його дім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 30, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 31, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 32, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 33, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 34, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 36, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 37, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 38, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 39, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 40, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 41, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 42, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 43, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'І прожили́ вони три роки, і не було війни між Сирією та між Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'І сталося третього року, і зійшов Йосафа́т, цар Юдин, до Ізраїлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'І сказав Ізраїлів цар до своїх слуг: „Чи ви знаєте, що ґілеадський Рамот — наш? А ми мовчимо́, замість того, щоб забрати його з руки сирійського царя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'І сказав він до Йосафа́та: „Чи ти пі́деш зо мною на війну до ґілеадського Рамоту?“А Йосафа́т відказав: „Я — як ти, народ мій — як народ твій, мої коні — як твої коні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'І сказав Йосафа́т до Ізраїлевого царя: „Вивідай зараз слово Господнє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'І зібрав Ізраїлів цар пророків, близько чотирьох сотень чоловіка, та й сказав до них: „Чи йти мені на війну на ґілеадський Рамот, чи занеха́ти?“А ті відказали: „Іди, а Господь дасть його в цареву руку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'І сказав Йосафа́т: „Чи нема тут іще Господнього пророка, — і ви́відаємо від нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'І сказав Ізраїлів цар до Йосафата: „ Є ще один муж, щоб від нього вивідати Господа. Та я нена́виджу його, бо він не пророкує на мене добре, а тільки зле. Це Міхей, син Їмлин“. А Йосафа́т відказав: „Нехай цар не говорить так!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'І покликав Ізраїлів цар одного є́внуха, і сказав: „Приведи скоріш Міхея, Їмлиного сина!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'І цар Ізраїлів та цар Юдин сиділи кожен на троні своїм, повби́рані в ша́ти при вході до брами Самарії, а всі пророки пророкували перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'А Седекія, Кенаанин син, зробив собі залізні ро́ги й сказав: „Так сказав Господь: Оцим будеш побивати сиріян аж до ви́гублення їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'І всі пророки пророкували так, говорячи: Виходь до ґілеадського Рамоту, і пощастить тобі, — і Господь дасть його в цареву руку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'А той послане́ць, що пішов покликати Міхея, говорив до нього, кажучи: „Ось слова тих пророків, — одноусто звіщають цареві добро. Нехай же буде слово твоє, як слово кожного з них, і ти говори́тимеш добре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'І сказав Міхей: „ Як живий Господь, — те, що скаже мені Госпо́дь, я те говоритиму!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'І прийшов він до царя, а цар сказав до нього: „Міхе́ю, — чи пі́демо на війну́ до ґілеа́дського Рамо́ту, чи занеха́ємо?“А той відказав йому: „Вийди, і пощастить тобі, — і Господь дасть у цареву руку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'І сказав йому цар: „Аж скільки разі́в я заприсягав тебе, що ти не говоритимеш мені нічо́го, тільки правду в Ім\'я́ Господа?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'А той відказав: „Я бачив усього Ізраїля, розпоро́шеного по гора́х, немов ове́ць, що не мають пастуха́. І сказав Господь: Немає в них пана, — нехай ве́рнуться з миром кожен до дому свого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'І сказав Ізраїлів цар до Йосафа́та: „Чи ж не казав я тобі, — він не буде пророкувати мені доброго, а тільки лихе́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'А Міхей відказав: „Тому́ послухай Господнього слова: Бачив я Господа, що сидів на престолі Своїм, а все небесне ві́йсько стояло при Ньому з прави́ці Його та з ліви́ці Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'І сказав Господь: Хто́ намовить Ахава, і він вийде й упаде в ґілеадському Рамоті? І говорив той так, а той говорив так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'І вийшов дух, і став перед Господнім лицем та й сказав: Я намо́влю його! І сказав йому Господь: Чим?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'А той відказав: Я вийду й стану духом неправди в устах усіх його пророків. А Господь сказав: Ти намовиш, а також переможеш; вийди та й зроби так!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'А тепер оце Господь дав духа неправди в уста всіх оцих пророків, а Господь говорив на тебе лихе́“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'І підійшов Седекія, Кенаанин син, і вдарив Міхея по щоці та й сказав: „Кудою це перейшов Дух Господній від мене, щоб говорити з тобою?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'А Міхей сказав: „Ось ти побачиш це, коли вбіжиш до найдальшої кімна́ти, щоб схова́тися“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'І сказав Ізраїлів цар: „Візьми Міхея, і відведи до Амона, начальника міста, та до Йоаша, царевого сина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'та й скажеш: Отак сказав цар: Посадіть оцього до в\'язни́чного дому, і давайте йому їсти скупо хліба й скупо води, аж поки я не верну́ся з миром“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'А Міхей відказав: „Якщо справді ве́рнешся ти з миром, то не говорив Господь через мене!“І до того сказав: „Слухайте це, всі наро́ди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'І вийшов Ізраїлів цар та Йосафа́т, цар Юдин, до ґілеадського Рамо́ту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'І сказав Ізраїлів цар до Йосафата: „Я переберу́ся, і піду́ на бій, а ти вбери свої царські шати!“І перебрався Ізраїлів цар, і пішов на бій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'А сирійський цар наказав керівника́м своїх колесни́ць, тридцятьом і двом, говорячи: „Не бу́дете воювати з мали́м та з великим, а тільки з самим Ізраїлевим царем“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'І сталося, як керівники́ колесни́ць побачили Йосафа́та, то вони сказали: „Це дійсно Ізраїлів цар!“І зайшли на нього, щоб воювати, а Йосафа́т закричав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'І сталося, як керівники́ колесни́ць побачили, що це не Ізраїлів цар, то поверну́ли від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'А один чоловік зне́хотя натягнув лука, та й ударив Ізраїлевого царя між підв\'яза́нням пояса та між па́нцерем. А той сказав своєму візникові: „Поверни назад, і виведи мене з табо́ру, бо я ране́ний“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'І знявся бій того дня, а цар був поста́влений на колесни́ці проти Сирії, і помер уве́чорі. І кров із рани текла в колесни́цю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'А як сонце захо́дило, нісся крик у табо́рі такий: „Кожен — до міста свого́, і кожен — до кра́ю свого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'І помер цар, і був приве́зений до Самарії. І поховали царя в Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'І полоска́ли колесни́цю над ставом у Самарії, і пси лиза́ли його кров, а блудни́ці мили своє тіло, за словом Господнім, що Він говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'А решта Ахавових діл, і все, що́ він зробив був, і дім зо слоно́вої кости, що він збудував, і всі міста́, які він побудува́в, — отож вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'І спочив Ахав із батька́ми своїми, а замість нього зацарюва́в син його Ахазія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'А Йосафа́т, Асин син, зацарював над Юдою в четвертому році Ахава, царя Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Йосафат був віку тридцяти й п\'яти літ, коли він зацарював, і двадцять і п\'ять літ царював в Єрусалимі. А ім\'я́ його матері — Азува, дочка́ Шілхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'І ходив він усією дорогою батька свого Аси, і не збо́чував із неї, щоб чинити добре в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Тільки па́гірки не були пони́щені, — народ іще прино́сив жертви й кадив на па́гірках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'І Йосафат замирив з Ізраїлевим царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'А решта Йосафатових діл та лица́рськість його, що́ він чинив був та як воював, — отож вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'А решту блудоді́їв, що позостава́лися за днів його батька Аси, він вигубив із Кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'А царя не було в Едомі, — був намісник царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'А Йосафат наробив був таршіських кораблі́в, щоб піти до Офіру по золото, та не пішов, бо порозбива́лися кораблі при Ецйон-Ґевері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Тоді сказав Ахазія, син Ахавів, до Йосафата: „Нехай пі́дуть на корабля́х мої раби з рабами твоїми“. Та Йосафат не захотів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'І спочив Йосафат із своїми батьками. І був він похо́ваний в Місті Давида, свого батька, а замість нього зацарював син його Єгорам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ахазія, Ахавів син, зацарював над Ізраїлем у Самарії, в сімнадцятому році Йосафата, Юдиного царя, і царював над Ізраїлем два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'І робив він лихе́ в Господніх оча́х, і ходив дорогою ба́тька свого́ й дорогою своєї матері, та дорогою Єровоама, Неватового сина, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'І служив він Ваалові, і вклоня́вся йому, та й гніви́в Го́спода, Бога Ізраїлевого, — усе так, як робив його ба́тько.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'А по смерті Ахава збунтува́вся Моав на Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'А Аха́зія випав через ґрати в своїй го́рниці, що в Самарії, та й захворі́в. І послав він послів, і сказав до них: „Ідіть, запитайте Ваал-Зевува, екронського бога, чи ви́дужаю я з своєї цієї хвороби?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'А Ангол Господній говорив до тішб\'янина Іллі: „Устань, вийди назу́стріч послів самарійського царя та й скажи їм: Чи через те, що нема в Ізраїлі Бога, ви йдете питатися Ваал-Зевува, екронського бога?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Тому так сказав Господь: Із того ліжка, що на нього ти ліг, не встанеш із нього, бо напевно помреш!“І пішов Ілля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'І вернулися посли до царя, а він сказав до них: „Що́ це ви верну́лися?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'А вони відказали йому: „Назу́стріч нам вийшов один чоловік, і сказав нам: Ідіть, верніться до царя, що послав вас, і скажіть йому: Так сказав Господь: Чи через те, що нема в Ізраїлі Бога, ти посилаєш ви́відати Ваал-Зевува, екронського бога? Тому́ те ло́же, що на нього ти ліг, — не встанеш із нього, бо напевно помреш“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'А він їм сказав: „Якого ви́гляду той чоловік, що вийшов назу́стріч вас, і говорив вам оці слова?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Вони ж відказали: „ Де чоловік волоха́тий, а шкуряни́й пояс опере́заний на сте́гнах його“. А він сказав: „Це тішб\'янин Ілля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'І послав він до нього п\'ятдеся́тника та його п\'ятдеся́тку. І вийшов він до нього, аж ось він сидить на верхі́в\'ї гори. І сказав він до нього: „Чоловіче Божий, цар сказав: Зійди ж ізвідти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'А Ілля відповів і говорив до того п\'ятдесятника: „А якщо я Божий чоловік, нехай зі́йде з неба огонь, і нехай пожере́ тебе та п\'ятдесятку твою!“І зійшов із неба огонь, і поже́р його та його п\'ятдесятку...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'І цар знову послав до нього іншого п\'ятдесятника та його п\'ятдесятку. І він відповів і сказав до нього: „Чоловіче Божий, отак сказав цар: Зійди ж скоро!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'І відповів Ілля та й сказав до нього: „Якщо я Божий чоловік, нехай зі́йде з неба огонь, і нехай пожере́ тебе та твою п\'ятдесятку!“І зійшов із неба Божий огонь, і поже́р його та його п\'ятдесятку...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'І зно́ву послав він третього п\'ятдесятника та його п\'ятдесятку. І вийшов, і прийшов третій п\'ятдесятник, та й упав на коліна свої перед Іллею, і благав його та до нього говорив: „Чоловіче Божий, нехай же буде дорога́ душа моя та душа твоїх рабів, тих п\'ятидесяти́, в оча́х твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Ось зійшов був огонь із неба, та й поже́р тих двох перших п\'ятдеся́тників та їхні п\'ятдеся́тки; а тепер нехай буде дорога́ душа моя в оча́х твоїх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'А Ангол Господній сказав до Іллі: „Зійди з ним, не бійся його́!“І він устав, і зійшов з ним до царя́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Та й сказав до нього: „Так сказав Господь: Тому́, що ти посилав послів, щоб ви́відати від Ваал-Зевува, екронського бога, — ніби в Ізраїлі нема Бога, щоб ви́відати слова́ Його, — тому́ те ло́же, що на нього ти ліг, — не встанеш із нього, бо напевно помреш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'І той помер, за словом Господа, що говорив до Іллі, а замість нього зацарюва́в Єгора́м, другого року Єгорама, сина Йосафа́та, Юдиного царя, бо не було в нього сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'А решта діл Ахазії, що він зробив був, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 19, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 20, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 21, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 22, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'І сталося, коли Господь мав узяти Іллю в ви́хрі на небо, то йшов Ілля та Єлисе́й із Ґілґа́лу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'І сказав Ілля до Єлисея: „Сиди тут, бо Госпо́дь послав мене аж до Бет-Елу“. Та Єлисей відказав: „ Як живий Господь і жива́ душа твоя, — я не залишу́ тебе!“І зійшли вони до Бет-Елу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'І повихо́дили бет-ельські пророчі сини до Єлисе́я та й сказали до нього: „Чи ти знаєш, що сьогодні Господь бере пана твого́ від тебе?“А він відказав: „Я також знаю, — мовчіть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'І сказав йому́ Ілля: „Єлисею, сиди тут, бо Господь послав мене́ до Єрихо́ну“. Та той відказав: „ Як живий Господь і жива́ душа твоя́, — я не залишу́ тебе!“І прийшли вони до Єрихо́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'І підійшли́ єрихонські пророчі сини до Єлисея та й сказали до ньо́го: „Чи ти знаєш, що сьогодні Господь бере пана твого від тебе?“А він відказав: „Я також знаю, — мовчіть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'І сказав йому́ Ілля: „Сиди тут, бо Господь послав мене́ до Йорда́ну!“Та той відказав: „ Як живий Господь і жива душа твоя, — я не залишу́ тебе!“І пішли вони обо́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'І п\'ятдеся́т чоловіка пророчих синів також пішли, і стали навпро́ти зда́лека, а вони оби́два стали над Йорда́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'І взяв Ілля плаща свого, і згорнув, і вдарив по воді, — і вона розділи́лась пополовині туди́ та сюди́...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'І сталося, як вони перейшли, то Ілля сказав до Єлисе́я: „Проси, що маю зробити тобі, поки я бу́ду взятий від тебе!“І сказав Єлисе́й: „Нехай же буде на мені подві́йний твій дух!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'А той відказав: „Тяжко́го зажадав ти! Якщо ти побачиш мене, що буду взятий від тебе, — буде тобі так, а якщо ні — не бу́де“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'І сталося, як вони все йшли та говорили, аж ось появився огняни́й віз та огняні́ коні, і розлучи́ли їх одного від о́дного. І возні́сся Ілля в ви́хрі на небо...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'А Єлисей це бачив, і він закричав: „Ба́тьку мій, ба́тьку мій, во́зе Ізраїлів та верхівці́ його!“Та вже не побачив його... І схопи́вся він сильно за одежу свою та й роздер її на дві части́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'І підняв він Ілле́вого плаща́, що спав із нього, і вернувся, і став на бе́резі Йорда́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'І взяв він Ілле́вого плаща́, що спав із нього, і вдарив по воді та сказав: „Де Господь, Бог Іллі?“І також він ударив по воді, — і вона розділи́лася пополови́ні туди та сюди!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'І побачили його знавпро́ти єрихо́нські пророчі сини, та й сказали: „На Єлисеї спочи́в дух Іллів!“І пішли́ вони назу́стріч йому́, і попа́дали перед ним до землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'та й сказали до нього: „Ось із твоїми рабами є п\'ятдеся́т чоловіка хоробрих, — нехай вони пі́дуть та пошукають твого пана, — а ну ж забра́в його Дух Господній, і ки́нув його на одну з гір або в одну з долин!“А той відказав: „Не посилайте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Та вони сильно благали його, аж доку́чили йому, то він сказав: „Посилайте!“І посла́ли вони п\'ятдеся́т чоловіка, і шукали три дні, та не знайшли його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'І вони верну́лися до нього (а він ме́шкав в Єрихо́ні). І сказав він до них: „Чи ж не казав я вам: Не йдіть“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'І сказали люди того міста Єлисеєві: „Ось поло́ження цього міста хороше, як пан бачить, та вода нехороша, а земля неплі́дна“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'А він сказав: „Подайте мені ново́го дзба́нка, і покладіть туди со́ли“. І вони подали́ йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'І він вийшов до джерела́ води, і кинув туди со́ли й сказав: „Так сказав Господь: Уздоро́вив Я цю воду, — не бу́де вже звідти смерти, ані неплі́ддя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'І була́ ви́лікувана та вода, і так є аж до цього дня, за словом Єлисея, яке він говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'І відійшов він звідти до Бет-Елу. А коли він ішов дорогою, то малі́ хлопці вихо́дили з того міста й насміхалися з нього, і казали йому: „Ходи, лисий! Ходи, лисий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'І він оберну́вся назад і побачив їх, та й прокля́в їх Іменем Господнім. І вийшли дві ведмеди́ці з лі́су, і розірва́ли з них сорок і двоє дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'А він пішов звідти до гори Карме́л, а звідти вернувся до Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'А Єгора́м, Ахавів син, зацарював над Ізраїлем у Самарії, у вісімнадцятому році Йосафа́та, Юдиного царя, і царював дванадцять років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'І чинив він лихо в Господніх оча́х, тільки не так, як ба́тько його та мати його, — він викинув Ваалового бовва́на, що зробив був батько його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Проте гріхів Єровоама, Неватового сина, що вво́див у гріх Ізраїля, він трима́вся, і не відставав від них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'А Меша, цар моавський, розво́див дрібну́ худобу, і давав Ізраїлевому цареві сто тисяч ягнят та сто тисяч ру́нних барані́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'І сталося, як помер Ахав, то збунтувався моавський цар проти Ізра́їлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'І вийшов того дня цар Єгорам із Самарії, і перелічи́в усього Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'І пішов він, і послав до Йосафа́та, царя Юдиного, говорячи: „Збунтувався проти мене цар моавський. Чи пі́деш зо мною на війну до Моаву?“А той відказав: „Ви́йду. Я — як ти, мій народ — як твій народ, мої коні — як твої коні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'І сказав: „Котро́ю дорогою пі́демо?“А той відказав: „Дорогою едомської пустині“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'І пішов цар Ізраїлів, і цар Юдин, і цар едомський, і йшли обхідно́ю доро́гою сім день. І не було води табо́рові та худобі, що була при них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'І сказав Ізраїлів цар: „Ах, Госпо́дь ви́кликав трьох оцих царів, щоб віддати їх у руку Моава“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'І сказав Йосафа́т: „Чи нема тут Господнього пророка, щоб через нього вивідати слово Господа?“І відповів один із слуг Ізраїлевого царя й сказав: „Тут є Єлисей, Шафатів син, що служив Іллі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'І сказав Йосафа́т: „Слово Господнє з ним!“І зійшли до нього цар Ізраїлів, і Йосафат, і цар едомський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'І сказав Єлисей до Ізраїлевого царя: „Що́ тобі до мене? Іди до пророків батька свого та до пророків своєї матері!“А Ізраїлів цар відказав йому: „Ні, бо Госпо́дь покли́кав трьох цих царів, щоб віддати їх у руку Моава“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'І сказав Єлисей: „ Як живий Госпо́дь Савао́т, що я стою́ перед лицем Його, — коли б я не зважа́в на Йосафата, Юдиного царя, не спогля́нув би на тебе, і не побачив би я тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'А тепер приведіть мені гусляра́“. І сталося, коли грав гусля́р, то на Єлисеї була Господня рука,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'і він сказав: „Так сказав Господь: Накопайте на цій долині яму за ямою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Бо так сказав Господь: Не побачите вітру, і не побачите дощу́, а поті́к цей бу́де напо́внений водою. І бу́дете пити ви, та че́реди ваші, та ваша худо́ба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Та буде цього мало в Господніх оча́х, — і Він видасть і Моава в вашу руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'І ви поб\'є́те всяке укріплене місто та всяке місто ви́бране, і всяке добре дерево повалите, і всі водні джере́ла зага́тите, і всяку добру полеву́ діля́нку завалите камі́нням“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'І сталося ра́нком, коли прино́ситься хлі́бна жертва, аж ось полила́ся вода з едомської дороги. І напо́внилася земля водою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'А ввесь Моав почув, що ті царі вийшли воювати з ними. І вони скли́кали всіх, хто но́сить по́яса й старше, і постава́ли на границі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'І повстава́ли вони рано вранці, і сонце засвітило над водою. І побачили моавляни навпроти воду, червону, як кров.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'І казали вони: „Це кров, — рубаючися, поруба́лися царі меча́ми, і позабива́ли один о́дного. А тепер на здо́бич, Моаве!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'І прийшли вони до Ізраїлевого табо́ру. І встав Ізраїль та й побив моавля́н, і ті повтіка́ли перед ними. І вони ввійшли до них, і били моавля́н,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'а міста руйнува́ли, і на всяку добру польову́ діля́нку — усі ки́дали свого ка́меня й закида́ли її, і всяке джерело́ води зага́чували, і вали́ли всяке добре дерево, й аж тільки в Кір-Харешеті позоста́вили камі́ння його. І оточи́ли тарани́, та й били його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'І побачив моавський цар, що бій перемага́є його́, і взяв він сім сотень чоловіка, що орудують мече́м, щоб проде́ртися до едомського царя́, та не зміг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'І він узяв свого перворі́дного сина, що мав царюва́ти замість нього, і приніс його цілопа́ленням на мурі. І повстав великий гнів на Ізраїля, — і вони відступи́ли від нього, і верну́лися до свого кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'А одна з жінок пророчих синів кли́кала до Єлисей, говорячи: „Помер раб твій, мій чоловік! А ти знаєш, що раб твій боявся Господа. А позича́льник прийшов ось, щоб забрати собі двоє дітей моїх за рабів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'І сказав до неї Єлисей: „Що́ я зроблю тобі? Розкажи мені, що́ є в тебе в домі“. А та відказала: „Нічого нема в домі твоєї невільниці, — є тільки горня́ оливи“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'А він сказав: „Іди, позич собі настороні́ по́суд від усіх сусі́док твоїх, по́суд порожній. Не бери мало!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'І вві́йдеш, і замкне́ш двері за собою та за синами своїми, і поналива́єш у всі ті посу́дини, а повні повідставля́й“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'І пішла вона від нього, і замкну́ла двері за собою та за синами своїми. Вони подава́ли їй по́суд, а вона налива́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'І сталося, коли понапо́внювано по́суд, то сказала вона до сина свого: „Подай мені ще по́суду!“А він відказав їй: „Нема вже по́суду“. І спини́лася олива.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'І вона прийшла, і доне́сла Божому чоловікові. І він сказав: „Іди, продай ту оливу, та й заплати своєму позича́льникові. А ти та сини́ твої будете жити на позоста́ле“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'І сталося певного дня, і прийшов Єлисе́й до Шуна́му, а там була багата жінка, — і вона сильно просила його до себе поїсти хліба. І бувало, скільки разів прихо́див він, захо́див туди їсти хліб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'І сказала вона до чоловіка свого: „Ось я познала, що Божий чоловік, який за́вжди прихо́дить до нас, він святий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Зробім же малу муровану го́рницю, і поставимо йому там ліжко, і стола, і стільця́, і свічника́. І коли він прихо́дитиме до нас, то захо́дитиме туди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Одно́го ра́зу прийшов він туди, і зайшов до горниці та й ліг там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'І сказав він до свого слуги Ґехазі: „Поклич оцю шунамі́тянку!“І той покли́кав її, і вона стала перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'І сказав він до нього: „Скажи їй: Ось ти старанно піклува́лася про всі наші потреби. Що́ зробити тобі за це! Чи є що, щоб сказати про тебе цареві або начальникові війська?“А вона відказала: „ Ні,— я сиджу́ серед народу свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'І сказав він: „Що́ ж зробити їй?“А Ґехазі відказав: „Та вона не має сина, а чоловік її стари́й“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'А він сказав: „Поклич її“. І він покликав її, і вона стала при вході.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'І він сказав: „На цей озна́чений час, коли саме цей час ве́рнеться, ти обійма́тимеш сина!“А вона відказала: „Ні, пане, чоловіче Божий, не говори неправди своїй невільниці!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Та зачала́ та жінка, і породи́ла сина на той озна́чений час, того саме ча́су, про який говорив до неї Єлисей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'І росло те дитя. А одно́го ра́зу вийшло воно до свого́ ба́тька до женці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'І сказало воно до свого батька: „Голова моя, голова моя!“А той сказав слузі: „Занеси́ його до його матері!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'І той поніс його, і приніс його до його матері. І сиділо воно на її колінах аж до полу́дня, та й померло...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'І ввійшла вона, і поклала його на ліжко Божого чоловіка, і замкну́ла за ним двері та й вийшла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'І покликала вона свого чоловіка та й сказала: „Пришли мені одно́го із слуг та одну з ослиць, і я поїду до Божого чоловіка й вернуся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'А він сказав: „Чому ти їдеш до нього? Сьогодні не новомісяччя й не субота“. А вона відказала: „Добре!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'І осідла́ла вона ослицю, і сказала до свого слуги: „Поганяй та йди. Не затримуй мені в їзді, аж поки не скажу́ тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'І поїхала вона, і приїхала до Божого чоловіка, до гори Карме́л. І сталося, як Божий чоловік побачив її зда́лека, то сказав до слуги свого Ґехазі: „Ось та шунамі́тянка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Побіжи ж назу́стріч їй та й скажи їй: Чи все гара́зд тобі, чи гаразд чоловікові твоєму, чи гаразд дитині?“А та відказала: „Усе гаразді“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'І прийшла вона до Божого чоловіка на го́ру, і сильно схопи́ла за но́ги його. А Ґехазі підійшов, щоб відіпхну́ти її, та Божий чоловік сказав: „Позостав її, бо затурбо́вана душа її, а Господь затаїв це передо мною й не сказав мені“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'А вона сказала: „Чи я жадала сина від пана? Чи я не говорила: Не впрова́джуй мене в обма́ну?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'І він сказав до Ґехазі: „Опережи сте́гна свої, і візьми мою па́лицю в руку свою та й іди. Коли спітка́єш кого, не повітаєш його, а коли хто повітає тебе, не відповіси́ йому. І покладеш мою палицю на хло́пцеве обличчя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'А мати того хлопця сказала: „ Як живий Господь і жива душа твоя, — я не полишу́ тебе!“І він устав і пішов за нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'А Ґехазі пішов перед ними, і поклав ту палицю на хлопцеве обличчя, та не було ані голосу, ані чуття. І вернувся він навпроти нього, і доніс йому, говорячи: „Не збуди́вся той хлопець!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'І ввійшов Єлисей у дім, аж ось той хлопець лежить мертвий на ліжку його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'І ввійшов він, і замкнув двері за ними обома́, та й молився до Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'І ввійшов він, і ліг на того хло́пця, і поклав уста свої на уста його, а очі свої на очі його, і долоні свої на долоні його. І схилився над ним, і стало тепле тіло тієї дитини!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'І він зно́ву ходив по дому раз сюди́, а раз туди́. І ввійшов він, і знову схилився над ним, — і чхнув той хлопець аж до семи раз. І розплю́щив той хлопець очі свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'І покликав він Ґехазі та й сказав: „Поклич ту шунамі́тянку!“І той покликав її. І прийшла вона до нього, і він сказав: „Забери свого сина!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'І ввійшла вона, і впала до його ніг, і вклони́лася до землі. І взяла́ вона сина свого та й вийшла...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'І вернувся Єлисей до Ґілґалу. А в Краю́ був голод, і пророчі сини сиділи перед ним. І сказав він до свого хлопця: „Пристав великого горшка́, і звари їжу для пророчих синів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'І вийшов один на поле, щоб назбирати ярини́, і знайшов там витку́ рослину, і назбирав із неї повну свою одежу диких огіркі́в. І він прийшов, і накриши́в до горшка́ ї́жі, бо вони не знали того́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'І поналива́ли вони лю́дям їжі. І сталося, як вони їли ту їжу, то закричали й сказали: „Смерть у горшку, чоловіче Божий!“І не могли вони їсти...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'А він сказав: „Дайте муки́!“І він всипав її до горшка і сказав: „Наливай наро́дові, і нехай їдять!“І вже не було́ нічого злого в горшку́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'І прийшов один чоловік із Баал-Шалішу, і приніс Божому чоловікові хліб первопло́ду, — двадцять ячмінних хлібці́в та зе́рна в колоска́х у своїй торбі. І сказав Єлисе́й: „Дай наро́дові, і нехай вони їдять!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'А слуга його сказав: „Що оце покладу я перед сотнею чоловіка?“Та він відказав: „Дай наро́дові, і нехай їдять, бо так сказав Господь: їжте й позоставте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'І він поклав перед ними, і вони їли й позоставили, за словом Господнім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'А Наама́н, нача́льник війська сирійського царя, був муж великий перед своїм паном, вельмиповажа́ний, бо через нього Господь дав перемогу Сирії. І був це муж дуже хоробрий, але прокаже́ний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'А сирійці вийшли були́ о́рдами, і взяли́ до неволі з Ізраїлевого кра́ю малу́ дівчину, і вона услуго́вувала жінці Наамана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'І сказала вона до своєї пані: „Ох, коли б пан мій побував у того пророка, що в Самарії, то він вилікував би його від прока́зи його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'А Нааман прийшов, і доніс своєму панові, говорячи: „Отак і отак говорила та ді́вчина, що з Ізраїлевого кра́ю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'І сказав сирійський цар: „Тож піди, а я пошлю́ свого листа до Ізраїлевого царя“. І той пішов, і взяв із собою десять талантів срібла та шість тисяч шеклів золота, і десять змін оде́жі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'І він приніс до Ізраїлевого царя такого листа: „Ось тепер, як при́йде оцей лист до тебе, то знай: ото послав я до тебе свого раба Наамана, а ти ви́лікуєш його від прока́зи його.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'І сталося, як Ізраїлів цар перечита́в цього листа, то роздер свої ша́ти й сказав: „Чи я Бог, щоб убивати чи лишати при житті, що той посилає до мене, щоб я ви́лікував чоловіка від прока́зи його? Тож зна́йте й дивіться — це він шукає проти мене за́чіпки“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'І сталося, як почув Єлисей, Божий чоловік, що Ізраїлів цар роздер шати свої, то послав до царя, говорячи: „Нащо розде́р ти шати свої? Нехай той при́йде до мене, і пізнає, що є пророк ув Ізраїлі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'І прибув Нааман зо своїми кі́ньми та з колесни́цею своєю, і став при вході Єлисеєвого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'І послав Єлисей до нього посла, говорячи: „Іди, і ви́миєшся сім раз у Йорда́ні, і вигоїться тіло твоє тобі, — й очи́стишся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'І розгнівася Нааман, і пішов і сказав: „Ось я подумав був: він ви́йде до мене, і стане, і закличе Ім\'я́ Господа, Бога свого, і покладе́ свою́ руку на те місце, і вилікує прокаже́ного...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Чи ж не ліпші Авана та Парпар, дама́ські річки́, від усіх Ізраїлевих вод? Чи не міг я ви́митися в них, і стати чистим?“І повернувся він, і пішов у гніві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'І підійшли його раби, і говорили до нього, і сказали: „Батьку мій, коли б велику річ говорив тобі той пророк, чи ж ти не зробив би? А що ж, коли він сказав тобі тільки: Умийся — і будеш чистий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'І зійшов він, і зану́рився в Йорда́ні сім раз, за словом Божого чоловіка. І сталося тіло його, як тіло мало́го хлопця, — і став він чистий!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'І верну́вся до Божого чоловіка він та ввесь та́бір його. І прийшов він, і став перед ним та й сказав: „Оце пізнав я, що на всій землі нема Бога, а тільки в Ізраїлі! А тепер візьми́ дару́нка від свого раба“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Та Єлисей відказав: „ Як живий Господь, що стою́ перед лицем Його, — я не візьму́!“А той сильно просив його взяти, та він відмо́вився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'І сказав Наама́н: „А як ні, то нехай буде да́но твоєму рабові землі, скільки понесу́ть два мули, бо твій раб не буде вже прино́сити цілопа́лення та жертву іншим богам, а тільки Господе́ві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Тільки оцю річ нехай про́стить Господь твоєму рабові: коли мій пан при́йде до Ріммонового дому, щоб там поклоня́тися, і опира́тиметься на мою руку, то й я схилю́ся в Ріммоновім домі. Коли я кла́нятимуся в Ріммоновім домі, то нехай про́стить Госпо́дь твоєму рабові цю річ!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'А той відказав: „Іди з миром!“І відійшов від нього на невелику ві́дстань.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'І сказав Ґеха́зі, слуга Єлисея, чоловіка Божого: „Ось мій пан стримав цього сирі́янина Наамана, щоб нічого не взяти з руки його, що він приніс. „ Як живий Господь, — побіжу́ за ним і візьму́ щось від нього!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'І погнався Ґеха́зі за Наама́ном. І побачив Нааман бігуна за собою, і зіскочив із воза навпроти нього й сказав: „Чи все гаразд?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'А той відказав: „Гаразд! Пан мій послав мене, говорячи: Ось тепер прийшли до мене з Єфремових гір двоє юнакі́в, пророчі сини. Дай їм талант срібла та дві зміні одежі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'А Нааман відказав: „Будь ласкав, — візьми два тала́нти!“І він упро́шував його. І зав\'язав він два тала́нти срібла в дві то́рбі, та дві змі́ні одежі, і дав своїм слу́гам, а вони поне́сли перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'І прийшов він до згі́р\'я, і взяв з їхньої руки, і вмістив у домі, а тих людей відпустив, і вони пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'А він прийшов та й став перед паном своїм. І сказав до нього Єлисей: „Звідки ти, Ґеха́зі?“А той відказав: „ Нікуди не ходи́в твій раб, — ані туди, ані сюди“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'І сказав Єлисей до нього: „ Чи моє серце не ходило з тобою, коли оберну́вся той муж зо свого воза назу́стріч тобі? Чи час бра́ти срібло та бра́ти одежі, і оливки, і виноградинка, і худобу дрібну́ та худобу велику, і рабів, і невільниць?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Тож Нааманова прока́за нехай прилі́питься до тебе та до насіння твого навіки!“І той вийшов від нього прокаже́ний, побілівши, як сніг!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'І сказали пророчі сини до Єлисея: „Ось те місце, де ми сидимо перед тобою, затісне́ для нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Ходім аж до Йорда́ну, і візьмі́мо звідти кожен по одній дереви́ні, і зробимо собі місце, щоб сидіти там“. А він сказав: „Ідіть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'І сказав один: „Будь же ласка́вий, і ходи зо своїми рабами!“А він сказав: „Я піду́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'І пішов він із ними, і вони прийшли до Йорда́ну, і руба́ли дерево.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'І сталося, коли один вали́в дереви́ну, то впала сокира до води. А той скрикнув і сказав: „Ох, пане мій, таж вона пози́чена!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'І сказав Божий чоловік: „Куди вона впала?“А той показав йому те місце. І він відрубав кусок дерева й кинув туди, — і ви́пливла сокира!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'І він сказав: „Витягни собі!“А той простя́г свою руку і взяв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Сирійський цар воював з Ізраїлем. І радився він зо слу́гами своїми, говорячи: „На такому то й такому то місці буде моє таборува́ння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'А Божий чоловік послав до Ізраїлевого царя, говорячи: „Стережися перехо́дити оце місце, бо там схо́дяться сирі́яни!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'І послав Ізраїлів цар до того місця, про яке говорив йому Божий чоловік та остеріга́в його; і він стері́гся там не раз і не два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'І сильно занепоко́їлося серце сирійського царя про ту річ, і він покликав своїх слуг та й сказав до них: „Чи не розповісте́ мені, хто з наших зраджує перед Ізраїльським царем?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'І сказав один з його слуг: „Ні, пане мій ца́рю, це не наш, а це Єлисей, той пророк, що в Ізраїлі, доно́сить Ізраїлевому цареві ті слова, що ти гово́риш у спальні своїй!“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'А він відказав: „Ідіть, і подивіться, де́ він, — і я пошлю́ й візьму́ його!“І доне́сено йому, кажучи: „Ось він у Дотані!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'І послав він туди коні, і колесни́ці та ві́йсько. І прийшли вони вночі й оточили те місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'А слуга Божого чоловіка встав рано і вийшов, аж ось ві́йсько ото́чує місто, і коні, і колесни́ці! І сказав його слуга до нього: „Ох, пане мій, що́ бу́демо робити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'А той відказав: „Не бійся, бо ті, що з нами, численні́ші від тих, що з ними“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'І молився Єлисе́й і говорив: „Господи, розкрий йому очі, і нехай він побачить!“І відкрив Господь очі того слуги́, і він побачив, аж ось гора́ повна ко́ней та огняни́х колесни́ць навко́ло Єлисе́я!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'І зійшли сирійці до ньо́го, а Єлисей помолився до Господа й сказав: „Удар цей люд сліпото́ю!“І Він ударив їх сліпото́ю за Єлисеєвим словом...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'І сказав до них Єлисей: „Це не та доро́га й не те місто. Ідіть за мною, й я проведу́ вас до того чоловіка, якого ви шукаєте“. І він завів їх у Самарі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'І сталося, як прийшли вони до Самарії, то Єлисей сказав: „Го́споди, відкрий оці очі, і нехай вони побачать!“І Господь відкрив їхні очі, і вони побачили, — аж ось вони в сере́дині Самарії!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'І сказав Ізраїлів цар до Єлисея, коли побачив їх: „Чи побити їх, чи побити, мій ба́тьку?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'А той відказав: „Не вбивай! Чи ти повбиваєш тих, кого ти взяв до неволі своїм мече́м та своїм списо́м? Поклади хліб та воду перед ними, і нехай вони їдять та п\'ють, і нехай ідуть до свого пана“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'І справив цар для них велику гости́ну, і вони їли й пили; і він відпустив їх, і вони пішли до свого пана. І сирійські о́рди вже більш не вхо́дили до Ізраїлевого Кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'І сталося по тому, і зібрав Бен-Гадад, сирійський цар, увесь свій та́бір, і він зійшов і облі́г Самарію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'І був великий голод у Самарії. І ось ті обляга́ли їх, а осляча голова коштувала вісімдеся́т шеклів срібла, а чвертка каву голуби́ного поме́ту п\'ять шеклів срібла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'І сталося, прохо́див Ізраїлів цар по мурі, а одна жінка крикнула до нього, говорячи: „Поможи, пане ца́рю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'А він відказав: „Як тобі не поможе Господь, звідки я поможу́ тобі? Чи з то́ку, або з чави́ла?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'І сказав до неї цар: „Що тобі?“А та відказала: „Оця жінка сказала мені: Дай свого сина, і ми з\'їмо́ його сьогодні, а мого сина з\'їмо́ взавтра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'І зварили ми мого́ сина та й з\'їли його... І сказала я до неї дру́гого дня: Дай сина свого, і ми з\'їмо́ його, та вона сховала свого сина“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'І сталося, як цар почув слова цієї жінки, то роздер шати свої, і він ходив по мурі. І наро́д побачив, — аж ось вере́тище на тілі його зо спо́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'І він сказав: „Отак нехай зробить мені Бог, і так нехай додасть, якщо позоста́неться голова Єлисея, Шафатового сина, на ньому сьогодні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'А Єлисей сидів у своєму домі, а з ним сиділи старші́. І послав цар чоловіка від себе. Поки прийшов посол до нього, то він сказав до старши́х: „Чи ви бачите, що цей син уби́вника послав зняти мою го́лову? Глядіть, як при́йде цей посол, то замкніть двері, — і прити́снете його в две́рях. Ось і шаруді́ння ніг пана його за ним“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Ще він говорив із ними, аж ось прихо́дить до нього послане́ць. І він сказав: „Отаке зло від Господа! Чого ще чекати від Господа?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 34, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'І сказав Єлисей: „Послухайте слово Господнє: Так сказав Господь: Цього ча́су взавтра буде се́я пшеничної муки — за ше́кля, і дві сеї ячме́ню — за шекля в брамі Самарії“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'І відповів Божому чоловікові вельможа царя, що він на його руку спирався, і сказав: „Якби Господь поробив отво́ри в небі, чи сталася б ця річ?“А той відказав: „Ось ти побачиш своїми очи́ма, — та їсти звідти не бу́деш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'І були при вході до брами чотири прокаже́ні чоловіки. І сказали вони один до о́дного: „Чого ми сидимо́ тут, аж поки не помремо́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Якщо ми скажемо: Увійді́мо до міста, а в місті голод, то помремо́ там; а якщо сиді́тимемо тут, то теж помремо́. Отож, ходіть, і перейді́мо до сирійського табо́ру, — якщо там позоставлять нас при житті, бу́демо жити, а якщо заб\'ють нас, то помремо́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'І встали вони на́двечір, щоб іти до сирійського табо́ру. І прибули́ вони до кра́ю сирійського табо́ру, аж ось — нема там ніко́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Бо Господь учинив, що сирійський та́бір почув стуко́тняву колесни́ць і їржа́ння ко́ней, та га́лас великого ві́йська. І сказали вони один до о́дного: „Ось Ізраїлів цар найняв на нас хіттейських царів та царів єгипетських, щоб пішли на нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'І встали вони, і повтікали надвечір, і полишили свої намети, й осли свої, і та́бір, як він був, та й повтікали, спасаючи життя своє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'І прийшли ті прокаже́ні аж до краю табо́ру, і ввійшли до одно́го намету, — і їли й пили, і повино́сили звідти срібло й золото та вбрання́, і пішли й захова́ли. І вони зно́ву ввійшли до іншого намету, і повино́сили звідти, і пішли та й схова́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'І сказали вони один до о́дного: „Неслушно ми ро́бимо. Цей день — він день доброї звістки, а ми мовчимо́. Як ми бу́демо чекати аж до ранішнього сві́тла, то впаде́ на нас провина. А тепер ході́мо, і ввійді́мо й донесі́мо царевому дому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'І прийшли вони, і покликали міськи́х воротарі́в, та й доне́сли їм, говорячи: „Увійшли ми до сирійського табо́ру, а там нема ані люди́ни, ані лю́дського голосу, а тільки поприв\'я́зувані коні та поприв\'язувані осли, та намети, як вони були!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'І воротарі́ покликали, і доне́сли про це до самого царсько́го дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'І встав цар уночі й сказав своїм слу́гам: „Розкажу́ я вам, що́ нам зробили сирійці. Вони знають, що ми голодні, і повихо́дили з табо́ру, щоб схова́тися на полі, говорячи: „Коли ті повихо́дять із міста, то ми схо́пимо їх живих, та й уві́йдемо до міста!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'І відповів один із його слуг і сказав: „Нехай ві́зьмуть п\'я́теро позосталих ко́ней, що лишилися в ньому, у місті. Ось вони, — (із усього війська Ізраїлевого тільки й лишилися, із усього війська Ізраїля, що згинуло), — і пошле́мо, і побачимо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'І взяли́ вони дві колесни́ці з кі́ньми, і цар послав їх услід за сирійським табо́ром, говорячи: „Ідіть і подивіться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'І пішли вони за ними аж до Йорда́ну, аж ось уся дорога повна вбрання́ та рече́й, що поки́дали сирійці, як поспішали! І верну́лися ці посли, і доне́сли цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'І вийшов наро́д, і розграбува́ли сирійський та́бір. І ко́штувала се́я пшеничної муки по шеклю, і дві сеї ячме́ню по шеклю за словом Господнім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'І цар призна́чив того вельможу, що на його руку він опирався, доглядати над брамою. Та затопта́в його наро́д у брамі, і він помер, як казав був Божий чоловік, який говорив, коли прихо́див до нього цар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'І сталося, коли Божий чоловік говорив до царя, кажучи: „Дві сеї ячменю по шеклю, і сея пшеничної муки́ по шеклю буде того ча́су взавтра в брамі Самарії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'то цей вельможа відповів Божому чоловікові й сказав: „Якби Господь поробив отво́ри в небі, чи сталася б ця річ?“А той відказав: „Ось ти побачиш своїми очи́ма, — та їсти звідти не бу́деш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'І сталося йому так, і затоптав його наро́д у брамі, і він помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'А Єлисей говорив до жінки, що її сина він воскреси́в, кажучи: „Устань та й іди ти та дім твій, і мешкай дебудь, бо Господь прикликав голод, і він прийшов до кра́ю на сім літ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'І встала та жінка, і зробила за словом Божого чоловіка. І пішла вона та її дім, і заме́шкала в филистимському кра́ї сім літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'І сталося напри́кінці семи років, вернулася та жінка з филистимського кра́ю, і пішла до царя благати за свій дім та за своє поле.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'А цар говорив до Ґехазі, слуги Божого чоловіка, кажучи: „Розкажи мені про все те велике, що́ зробив Єлисей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'І сталося, як він оповідав цареві, що той воскресив померлого, аж ось та жінка, що він воскресив сина її, благає царя за свій дім та за своє поле.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'І сказав Ґехазі: „Пане мій ца́рю, оце та жінка, і це той син її, що воскресив Єлисей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'І прийшов Єлисей до Дамаску, а Бен-Гадад, сирійський цар, хворий. І доне́сено йому, кажучи: „Божий чоловік прийшов аж сюди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'І сказав цар до Газаїла: „Візьми в свою руку подару́нка, та й іди зустріти чоловіка Божого. І запитайся Господа через нього, кажучи: „Чи ви́дужаю я від оцієї хвороби?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'І пішов Газаїл спіткати його, і взяв подару́нка в руку свою́, та зо всього добра́ Дамаску тягару́ на сорок верблю́дів. І прийшов, і став перед ним та й сказав: „Син твій Бен-Гадад, цар сирійський, послав мене до тебе, питаючи: Чи видужаю я з оцієї хвороби?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'І сказав до нього Єлисей: „Іди, скажи йому: Жити — жи́тимеш, та Господь показав мені, що напевно помре він“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'І наставив він обличчя своє на нього, і довго вдивлявся, аж той збенте́жився. І заплакав Божий чоловік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'А Газаїл сказав: „Чого плаче мій пан?“А той відказав: „Бо знаю, що ти зробиш лихо Ізраїлевим синам: їхні тверди́ні пустиш з огнем, і їхніх воякі́в позабива́єш мече́м, і дітей їхніх порозбиваєш, а їхнє вагітне́ — посічеш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'А Газаїл сказав: „Та що таке твій раб, цей пес, що зробить таку велику річ?“І сказав Єлисей: „Господь показав мені тебе царем над Сирією!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'І пішов він від Єлисея, і прийшов до свого пана. А той сказав йому: „Що́ говорив тобі Єлисей?“І він сказав: „Говорив мені: жити — жи́тимеш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'I сталося другого дня, і взяв він покрива́ло, і намочив у воді, і поклав на його обличчя, — і той помер. І зацарював Газаїл замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'А п\'ятого року Йорама, Ахавого сина, Ізраїлевого царя, за Йосафата, Юдиного царя, зацарював Єгорам, син Йосафатів, цар Юдин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Він був віку тридцяти й двох літ, коли зацарював, а царював вісім літ в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'І ходив він дорогою Ізраїлевих царів, як робив Ахавів дім, бо Ахавова дочка́ була йому за жінку. І робив він зло в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Та не хотів Господь погубити Юду ради раба Свого Давида, як обіцяв був йому дати світильника йому та синам його по всі дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'За його днів збунтува́вся був Едом, — вийшли з-під Юдиної руки, і настанови́ли над собою царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'І пішов Йорам до Цаіру, а з ним усі колесни́ці. І сталося, коли він уночі встав і побив Едома, що оточив був його, і керівникі́в колесни́ць, то народ повтікав до наметів своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'І збунтувався Едом, і вийшов з-під Юдиної руки, і так є аж до цього дня. Тоді того ча́су збунтувалася й Лівна.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'А решта діл Йорама, та все, що́ він зробив, ось вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'І спочив Йорам із батька́ми своїми, і був похо́ваний із батьками своїми в Давидовому Місті, а замість нього зацарював син його Аха́зія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'У дванадцятому році Йорама, Ахавого сина, Ізраїлевого царя, зацарював Ахазія, син Єгорама, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ахазія був віку двадцяти і двох літ, коли він зацарював, і царював він один рік в Єрусалимі. А ім\'я́ його матері — Аталія, дочка́ Омрі, Ізраїлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'І ходив він дорогою Ахавого дому, і робив зло в Господніх оча́х, як і Ахавів дім, бо він був зять Ахавого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'І пішов він з Йорамом, Ахавовим сином, на війну з Газаїлом, сирійським царем, до ґілеадського Рамоту, та побили сирі́яни Йорама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'І вернувся цар Йорам лікуватися в Їзрее́лі від тих ран, що вчинили йому сирі́яни в Рамі, як він воював з Газаїлом, сирійським царем. А Ахазія, Єгорамів син, цар Юдин, зійшов побачити Йорама, Ахавового сина, в Їзреелі, бо той був слаби́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'А пророк Єлисей покликав одно́го з пророчих синів і сказав йому: „Підпережи́ свої сте́гна, і візьми це горня́ оливи в свою руку, і йди до ґілеа́дського Рамо́ту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'І при́йдеш туди, і побач там Єгу́, сина Йосафа́та, Німшієвого сина. І ти вві́йдеш, і ві́зьмеш його з-між братів його, і введеш його до вну́трішньої кімна́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'І ві́зьмеш горня́ цієї оливи, і ви́ллєш на його голову та й скажеш: Так сказав Господь: Пома́зую тебе на царя над Ізраїлем! А по тому відчи́ниш двері й утечеш, і не будеш чекати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'І пішов той слуга, слуга пророка, до ґілеадського Рамоту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'І прийшов він, аж ось сидять керівники́ ві́йська. І він сказав: „Слово мені до тебе, о керівнику!“А Єгу відказав: „До ко́го з усіх нас?“І той сказав: „До тебе, о керівнику!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'І він устав, і вийшов до дому, а той вилив оливу на його голову. І сказав він йому: „Так сказав Господь, Бог Ізраїля: Пома́зую тебе на царя над народом Господнім, над Ізраїлем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'І ти поб\'єш дім Ахава, пана свого, і помстиш за кров Моїх рабів пророків, і за кров усіх Господніх рабів від руки Єзаве́лі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'І згине ввесь Ахавів дім, і ви́гублю Ахавові навіть те, що мочиться на стіну́, і невільного та вільного в Ізраїлі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'І зроблю́ Ахавів дім, як дім Єровоама, Неватового сина, і як дім Баші, сина Ахійїного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'А Єзаве́лю з\'їдять пси в Їзрее́левій діля́нці, і не буде, хто б її поховав“. І відчини́в він двері та й утік...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'А Єгу́ вийшов до слуг свого пана, і вони сказали йому: „Чи все гаразд? Чого прихо́див той несамови́тий до тебе?“А він відказав: „Ви знаєте того чоловіка та його мову“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'А вони відказали: „Неправда! Розкажи ж нам!“І той сказав: „Отак і так сказав він до мене, говорячи: Так сказав Господь: Пома́зую тебе на царя над Ізраїлем!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'А ті поспішно взяли́ кожен шати свої, і постели́ли під ним на верху́ сходів. І засурми́ли вони в сурму́, і сказали: „Зацарював Єгу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'І змовився Єгу, син Йосафа́та, Німшієвого сина, проти Йорама. А Йорам стеріг ґілеадського Рамота, він та ввесь Ізраїль перед Газаїлом, сирійським царе́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'І вернувся цар Єгора́м лікуватися в Їзреелі від ран, що вчинили йому сирі́яни, як він воював з Газаїлом, сирійським царем. І сказав Єгу: „Якщо згода ваша на те, нехай не вийде жо́ден утікач із міста, щоб піти доне́сти в Їзреелі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'І сів ве́рхи Єгу, і поїхав до Їзреелу, бо Йорам лежав там. А Ахазія, цар Юдин, зійшов побачити Йорама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'А на башті в Їзрее́лі стояв вартови́й. І побачив він на́товп Єгуїв, як він ішов, і сказав: „Я бачу на́товп!“А Єгорам відказав: Візьми верхівця́, і пошли назу́стріч їм, і нехай він скаже: Чи все гаразд?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'І відправився верхіве́ць назу́стріч йому, і сказав: „Так сказав цар: Чи все гара́зд?“А Єгу́ відказав: „Що́ тобі до того? Повертай за мною!“І доніс вартови́й, говорячи: „Прийшов той посо́л аж до них, та не вернувся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'І послав він другого верхівця́, і він прийшов до них та й сказав: „Так сказав цар: Чи все гара́зд?“А Єгу відказав: „Що тобі до гара́зду? Повертай за мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'І доніс вартови́й, говорячи: „Прийшов він аж до них, та не вернувся. А кі́нна їзда́, як їзда Єгу, Німшієвого сина, бо їде несамовито“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'І сказав Єгорам: „Запрягай!“І запріг його колесни́цю. І відправився Єгорам, Ізраїлів цар, та Ахазія, Юдин цар, кожен своєю колесни́цею, щоб зустріти Єгу, — і спітка́ли його в діля́нці їзреелянина Навота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'І сталося, як Єгорам побачив Єгу, то сказав: „Чи все гаразд, Єгу?“А той відказав: „Який гаразд при пере́любі твоєї матері Єзавелі та її багатьох чарів?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'І обернув Єгорам руки свої та й утік. І сказав він Ахазії: „Зра́да, Ахазіє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'А Єгу взяв лука в руку свою, і вдарив Єгорама між його раме́нами, — і проби́ла стріла його серце, і він похили́вся на колесни́ці своїй...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'І сказав Єгу до Бідкара, вельможі свого́: „Візьми, кинь його на діля́нці поля їзреелянина Навота. Бо пам\'ятай, — я й ти ї́хали вдвох за Ахавом, батьком його, а Господь прорік на нього оце пророцтво:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Поправді кажу, що бачив Я вчора кров Навота та кров синів його, говорить Господь, і відплачу́ тобі на цій же діля́нці, говорить Господь. А тепер кинь його на цій діля́нці за словом Господнім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'А Ахазія, Юдин цар, побачив це, і втікав дорогою на Бет-Гаґґан, а Єгу́ погна́вся за ним і сказав: „Убийте й його на колесни́ці!“І поранили його в Маале-Ґурі, що при Ївлеамі, а він утік до Меґіддо та й помер там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'А раби його відве́зли його ве́рхи до Єрусалиму, та й поховали його в його гро́бі з батька́ми його в Давидовому Місті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'А в одина́дцятому році Йорама, Ахавового сина, над Юдою зацарював Ахазія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'І прийшов Єгу до Їзрее́ля, а Єзаве́ль почула про це, і нафарбувала очі свої, і прикра́сила голову свою, та й виглянула через вікно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'А Єгу входить до брами. І сказала вона: „Чи все гаразд, Зімрі, убивце пана свого́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'І підняв він обличчя своє до вікна та й сказав: „Хто зо мною, хто?“І виглянули до нього два-три є́внухи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'А він сказав: „Скиньте її!“І викинули її, — і бри́знула кров її на стіну́ та на коні. І він топтав її...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'І він увійшов, і їв та пив, та й сказав: „Підіть до тієї прокля́тої, і поховайте її, бо все ж таки вона царева дочка́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'І пішли поховати її, та не знайшли з неї нічо́го, а тільки че́репа, та ноги, та долоні рук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'І вони вернулися, і доне́сли йому про це. А він відказав: „Це слово Господа, що казав був через раба Свого тішб\'янииа Іллю, говорячи: В Їзрее́левій діля́нці пси з\'їдять Єзаве́лине тіло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'І буде Єзаве́лин труп, як погні́й на пове́рхні поля в Їзреелевій діля́нці, так що не скажуть: Це Єзаве́ль“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'А Аха́в мав сімдеся́т синів у Самарії. І понапи́сував Єгу листи, і порозсила́в до Самарії, до провідників Їзреелу, до старши́х і до вихо́вників Ахавових синів, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '„Як тільки при́йде лист цей до вас, — а з вами сини вашого пана, і з вами колесни́ці, і коні, і тверди́ні, і збро́я, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'то виберіть найліпшого та найвідповідні́шого з синів вашого пана, і посадіть його на трон вашого батька, та й воюйте за дім вашого пана!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'А вони дуже-дуже налякалися й сказали: „Ось два царі́ не всто́яли перед ним, якже встоїмо́ ми?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'І послали ті, що були над домом та над тим містом, і старші́, і виховники до Єгу, говорячи: „Ми раби твої, і зро́бимо все, що ти нам скажеш. Та ми не настано́вимо царем ніко́го, — що добре в оча́х твоїх, те роби!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'А він написав до них другого листа, пишучи: „Якщо ви мої, і слухня́ні моєму го́лосові, візьміть го́лови мужів, синів вашого пана, і прийдіть до мене цього ча́су взавтра до Їзреелу“(а царськи́х синів було сімдеся́т чоловіка, при міськи́х вельможах, що ви́ховали їх).');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'І сталося, як прийшов той лист до них, то побрали вони царських синів, та й позабивали сімдеся́т чоловіка. І посклада́ли вони їхні го́лови в ко́шики, та й послали до нього в Їзреел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'І прибув посо́л, і доніс йому, кажучи: „Прине́сли го́лови царськи́х синів!“А він сказав: „Покладіть їх на дві купі при вході до брами до ра́нку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'І сталося вранці, і він вийшов і став, і сказав до всьо́го наро́ду: „Ви неви́нні. Я вчинив змову на свого пана й убив його. А хто повбивав усіх цих?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Знайте ж тепер, що з Господнього слова не промине́ться нічо́го, що́ Господь говорив на Ахавів дім, і Господь зробив те, що говорив був через раба Свого Іллю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'І Єгу повбивав усіх позосталих з Ахавого дому в Їзреелі, і всіх вельмож його, і знайо́мих його, і священиків його, так, що не позоста́вив йому і врятованого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'І встав він і відійшов, і пішов до Самарії. А коли він був на дорозі при Бет-Екед-Гароімі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'то спіткав братів Ахазії, Юдиного царя, і сказав: „Хто ви?“А ті відказали: „Ми Ахазієві брати, а йдемо́ запитати про гаразд царе́вих синів та синів цариці!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'А він сказав: „Схопі́ть їх живих!“І схопи́ли їх живих, і позабивали їх до ями Бет-Екеду, сорок і два чоловіка, — і він не позоставив ані одно́го з них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'І пішов він ізвідти, і спіткав Єгонадава, Рехавового сина, що йшов навпроти нього, і привітав його та й сказав до нього: „Чи твоє серце щире до мене, як моє серце до те́бе?“А Єгонадав відказав: „Так! Дай же свою́ ру́ку!“І той дав руку свою, і підняв його до себе до колесни́ці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'і сказав: „Іди ж зо мною, і приглянься до моєї запопа́дливости для Господа!“І посадили його в колесни́цю його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'І прибув він до Самарії, і повбивав усіх позосталих в Ахава в Самарії, і ви́бив аж до кінця його, за словом Господа, що говорив був до Іллі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'І зібрав Єгу ввесь наро́д і сказав до них: „Ахав мало служив Ваалові, — Єгу служи́тиме йому більше!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'А тепер покличте до мене всіх пророків Ваала, усіх, хто служить йому, та всіх священиків. Нехай нікого не бракува́тиме, бо в мене велика жертва для Ваала. Кожен, хто буде відсутній, не буде живи́й!“А Єгу зробив це пі́дступом, щоб вигубити тих, хто служить Ваалові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'І сказав Єгу́: „Оголосіть святочні збори для Ваала!“І вони оголосили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'І послав Єгу по всьому Ізраїлю. І посхо́дилися всі, хто служить Ваалові, і не позостався ніхто, хто не прийшов би. І прибули́ вони до Ваалового дому, — і перепо́внився Ваалів дім від входу до входу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'І сказав він тому, хто над царсько́ю шатнею: „Винеси одежу для всіх тих, хто служить Ваалові“. І той виніс їм ту одежу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'І ввійшов Єгу та Єгонадав, Рехавів син, до Ваалового дому, і сказав до Ваалових служи́телів: „Пошукайте й подивіться, щоб не був тут із вами ніхто з Господніх слуг, а тільки самі ті, хто служить Ваалові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'І ввійшли вони, щоб прине́сти жертви та цілопа́лення. А Єгу́ поставив собі назо́вні вісімдеся́т чоловіка й сказав: „Кожен, у кого втече хто з тих людей, що я ввів на ваші руки, — життя його буде за життя того́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'І сталося, як скінчи́в він приря́джувати цілопа́лення, то Єгу сказав до бігунів та до старши́н: „Увійдіть, повбивайте їх, — нехай ніхто не вийде!“І повбивали їх ві́стрям меча́, і поскидали їх ті бігуни́ та старши́ни. Потому пішли до міста Ваалового дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'І повино́сили вони бовванів Ваалового дому, і попали́ли те.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'І розбили вони Ваалового боввана, і розбили Ваалів дім, та й зробили з нього нечисте місце, і так є аж до сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'І ви́губив Єгу Ваала з Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Тільки не відступив він від гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля, від золотих тельці́в, що в Бет-Елі та що в Дані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'І сказав Госпо́дь до Єгу: „Тому́, що ти добре зробив угодне в оча́х Моїх, зробив Ахавовому домові все, що було на серці Моєму, — сиді́тимуть сини твої на Ізраїлевому троні аж до четвертого покоління “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Та Єгу не пильнував ходити за Зако́ном Господа, Бога Ізраїля, усім своїм серцем, не відступив від гріхів Єровоама, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'За тих днів розпочав Господь відру́бувати від Ізраїля частини, — і побив їх Газаїл в усій Ізраїлевій країні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'від Йорда́ну на схід сонця, увесь край Ґілеаду, Ґадів, Рувимів та Манасіїн, від Ароеру, що над потоком Арнон, і Ґілеад та Башан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'А решта діл Єгу, і все, що́ він зробив, і вся лица́рськість його́, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'І спочив Єгу зо своїми батька́ми, і поховали його в Самарії, а замість нього зацарював син його Єгоахаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'А дні, що царював Єгу над Ізраїлем у Самарії, були двадцять і вісім літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'А коли Аталія, мати Ахазії, побачила, що помер її син, то встала та й вигубила все цареве насіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'А Єгошева, дочка́ царя Йорама, сестра Ахазії, взяла Йоаша, сина Ахазії, та й викрала його з-поміж вби́ваних царськи́х синів, його та няньку його, і сховала в спальній кімна́ті. І схова́ли його від Аталії, і він не був забитий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'І ховався він із нею в Господньому домі шість років, а Аталія царювала над краєм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'А сьомого року послав Єгоя́да, і взяв сотників із карійців та бігунів, і привів їх до себе до Господнього дому, і склав із ними умову, і заприсягнув їх у Господньому домі, і показав їм царсько́го сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'І він наказав їм, говорячи: „Оце та річ, яку зро́бите. Третина з вас, що прихо́дите в суботу, будете виконувати сторо́жу царсько́го дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'А третина буде в брамі Сур, а третина — у брамі за бігуна́ми, — і будете виконувати сторо́жу дому на зміну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'А дві частині з вас, усі, що відходять у суботу, будуть виконувати сторо́жу Господнього дому при цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'І оточите царя навколо, кожен із своєю зброєю в руці своїй; а хто ввійшов би до рядів, нехай буде забитий. І будете ви з царем при виході його та при вході його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'І зроби́ли сотники все, що наказав священик Єгояда. І взяли́ кожен людей своїх, що прихо́дять у суботу та виходять у суботу, і прийшли до священика Єгояди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'І дав священик сотникам списи́ та щити́, що нале́жали цареві Давидові, що були в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'І постава́ли бігуни́, кожен зо зброєю своєю в руці своїй, від правого боку дому аж до лівого боку дому, при же́ртівнику та при домі, навколо біля царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'А він вивів царе́вого сина, і поклав на нього корону та нараме́нники. І зробили вони його царем, і пома́зали його, і вдарили в долоні та й крикнули: „Нехай живе цар!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'І почула Аталія голос бігунів та наро́ду, і прийшла до народу до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'І побачила вона, аж ось цар стоїть за зви́чаєм на помо́сті, а при царі зверхники та су́рми, а ввесь народ кра́ю тішиться та сурми́ть у су́рми. І роздерла Аталія шати свої та й крикнула: „Зрада, зрада!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'А священик Єгояда наказав сотникам, поставленим над ві́йськом, і сказав до них: „Ви́провадьте її поза ряди́, а хто пі́де за нею, того́ забийте мечем!“Бо священик сказав: „Нехай вона не буде забита в Господньому домі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'І зробили їй про́хід, і вона прийшла Кінським входом до царсько́го дому, і там була́ забита.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'І склав Єгояда заповіта між Господом та між царем і між народом, щоб був народом Господнім, і між царем та між народом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'І ввійшов увесь наро́д Кра́ю до Ваалового дому, та й прозбива́ли його та же́ртівники його, і бовва́нів його зовсі́м полама́ли, а Маттана, Ваалового священика, убили перед же́ртівниками. А при Господньому домі священик поставив ва́рти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'І взяв він сотників і карійців, і бігунів та ввесь народ кра́ю, і ви́вели царя з Господнього дому. І ввійшли вони через браму бігунів до царсько́го дому, і той сів на царсько́му троні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'І тішився ввесь народ кра́ю, а місто заспоко́їлось. А Аталію вбили мечем у царсько́му домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Єгоаш був віку семи років, коли зацарював.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Сьомого року Єгу зацарював Єгоаш, і сорок років царював він в Єрусалимі. А ім\'я́ його матері — Ців\'я, з Беер-Шеви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'І робив Єгоаш угодне в Господніх оча́х по всі дні, коли вказував йому священик Єгояда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Тільки па́гірки не були понищені, — народ ще прино́сив жертви та кадив на па́гірках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'І сказав Єгоаш до священика: „Усе посвячене срібло, що буде вне́сене до Господнього дому, срібло перелічених людей, срібло за душі за вартістю їх, усе срібло, скільки люди́ні спаде́ на серце прине́сти до Господнього дому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'ві́зьмуть собі священики, кожен від знайо́мого свого, і вони зро́блять напра́ву Господнього дому в усьому, що буде зна́йдене там на напра́ву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'І сталося двадцятого й третього року царя Єгоаша, священики не напра́вили ушкодження храму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'І покликав цар Єгоаш священика Єгояду й священиків, та й сказав їм: „Чому ви не направля́єте ушкодження храму? А тепер не беріть срібла від ваших знайо́мих, а на напра́ву ушкодження храму віддасте́ його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'І погоди́лися священики не брати срібла від народу, і не направля́ти ушкодження храму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'І взяв священик Єгояда одну скриньку, і продовба́в дірку на віку її, і поставив її при же́ртівнику право́руч, як входити до Господнього дому. І давали туди священики, що стерегли́ порога, усе срібло, що прино́силося до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'І бувало, як вони бачили, що намно́жилося те срібло в скрині, то прихо́див царськи́й писар та великий священик, і вони в\'язали в мішки та рахували срібло, знайдене в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'I давали те перелічене срібло на руки робітника́м праці, поставленим до Господнього дому, а вони давали його те́слям та будівни́чим, що робили в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'І муляра́м, і каменяра́м, і на за́куп де́рева та те́саного каменя, та на направу ушко́дження Господнього дому, та на все, що йшло на храм для направи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Тільки не робилися для Господнього дому срібні чаші, ножиці, кропи́льниці, су́рми, усяка річ золота та річ срібна з того срібла, що прино́силося до Господнього дому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'бо його давали робітника́м праці та направляли ним дім Господній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'І не облічували тих людей, яким давали те срібло до їхніх рук, щоб вони давали робітника́м праці, бо ті робили чесно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Срібло ж жертви за провину та жертов за гріх не вно́силося до Господнього дому, — воно було для священиків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Вийшов тоді Газаїл, сирійський цар, та й воював з Ґатом, — і здобув його. І намірився Газаїл іти на Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'І взяв Єгоаш, Юдин цар, усі святі речі, що присвятили були Йосафа́т, і Єгорам, і Ахазія, батьки́ його, царі Юдині, та святі речі свої, і все золото, що знайшлося в скарбни́цях Господнього дому та дому царсько́го, та й послав Газаїлові, цареві сирійському, — і той відійшов від Єрусалиму...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'А решта діл Йоаша, і все, що́ він зробив, — он вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'І встали його слуги, і вчинили змову, та й забили Йоаша в Бет-Мілло, де йдеться до Сілли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Йозахар, Шім\'атів син, та Єгозавад, Шомерів син, його слуги, забили його, і він помер. І поховали його з батька́ми його в Давидовім Місті, а замість нього зацарював син його Амаці́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Двадцятого й третього року Йоаша, сина Ахазії, Юдиного царя, зацарював над Ізраїлем у Самарії Єгоахаз, син Єгу, на сімнадцять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'І робив він зло в Господніх оча́х, і ходив у гріхах Єровоама, Неватового сина, що вводив у гріх Ізраїля, і не відхиля́вся від того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'І запалився гнів Господа на Ізраїля, і Він дав їх у руку Газаїла, царя сирійського, та в руку Бен-Гадада, Газаїлового сина, на всі ті дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Та вблагав Єгоахаз лице Господнє, — і Господь його вислухав, бо бачив Він горе Ізраїля, бо тиснув їх сирійський цар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'І дав Господь Ізраїлеві спаси́теля, і вони вийшли з-під руки Сирії. І сиділи Ізраїлеві сини в своїх наметах, як давніш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Тільки не відійшли вони з гріхів дому Єровоама, що вводив у гріх Ізраїля, і сам у тому ходив, і Астарта стояла в Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'А Сирія не позоставила Єгоахазові наро́ду, як тільки п\'ятдеся́т верхівці́в та десять возів, та десять тисяч піхоти, бо їх вигубив сирійський цар, і зробив їх порохом на топта́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'А решта діл Єгоахаза, і все, що́ він робив, та його лица́рськість, он вони написані в Книзі Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'І спочив Єгоахаз з батька́ми своїми, і поховали його в Самарії, а замість нього зацарював син його Йоаш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Тридцятого й сьомого року Йоаша, Юдиного царя, зацарював над Ізраїлем у Самарії Йоаш, Єгоахазів син, на шістнадцять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'І робив він зле в Господніх оча́х, і не відходив від усіх гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля, і в тому́ ходив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'А решта діл Йоаша, і все, що він робив, і лица́рськість його́, як він воював з Амацією, Юдиним царем, — он вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'І спочив Йоаш з батьками своїми, а Єровоам сів на троні його. І був похований Йоаш у Самарії, з Ізраїлевими царями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'А Єлисей заслаб на неду́гу, що з неї й поме́р. І зійшов до нього Йоаш, Ізраїлів цар, і плакав над ним і говорив: „Ба́тьку мій, батьку мій, колесни́це Ізра́їлева та верхівці́ його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'І сказав йому Єлисей: „Візьми лука та стрі́ли“. І приніс той до нього лука та стріли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'А він сказав Ізраїлевому цареві: „Поклади свою руку на лука!“І той поклав свою руку. А Єлисей поклав свої руки на руки цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'І він сказав: „Відчини вікно на схід!“І той відчинив. І сказав Єлисей: „Стріляй!“І той вистрілив, а він сказав: „Стріла́ спасі́ння Господнього, і стріла спасіння проти Сирії. І поб\'єш ти Сирію в Афеку аж до кінця!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'І він сказав: „Візьми стрі́ли!“І той узяв, а він сказав до Ізраїлевого царя: „Удар по землі!“І він ударив три рази та й став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'І розгнівався на нього Божий чоловік і сказав: „Щоб ти був ударив п\'ять або шість раз, тоді побив би Сирію аж до кінця! А тепер тільки три рази поб\'єш ти Сирію“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'І спочи́в Єлисей, і поховали його. А моавські о́рди прийшли до Кра́ю наступного року.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'І сталося, як ховали одно́го чоловіка, то погребальники побачили ті о́рди, та й кинули того чоловіка до Єлисеєвого гро́бу. А коли впав і доторкнувся той чоловік до Єлисеєвих косте́й, то воскрес, і встав на ноги свої...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'А Газаїл, сирійський цар, тиснув Ізраїля всі дні Єгоахаза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Та Господь був милости́вий до них, і змилувася над ними, і звернувся до них ради заповіта Свого з Авраамом, Ісаком та Яковом, і не хотів ви́губити їх, і не відкинув їх від Свого лиця аж дотепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'І спочи́в Газаїл, сирійський цар, а замість нього зацарював син його Бен-Гадад.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'І Йоаш, Єгоахазів син, узяв назад ті міста з руки Бен-Гадада, Газаїлового сина, що взяв був із руки Єгоахаза, свого батька, у війні. Три ра́зи побив його Йоаш, і вернув Ізраїлеві міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Другого року Йоаша, Йоахазового сина, Ізраїлевого царя, зацарював Амація, Йоашів син, цар Юдин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Він був віку двадцяти й п\'яти літ, коли зацарював, і царював в Єрусалимі двадцять і дев\'ять років. А ім\'я́ його матері Єгоаддан, з Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'І робив він угодне в Господніх оча́х, тільки не так, як його батько Давид, — він робив усе, що робив його батько Йоаш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Тільки пагірки не були знищені, — народ прино́сив жертву та кадив на па́гірках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'І сталося, як зміцнилося царство в руці його, то він повбивав своїх слуг, що забили його батька царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'А синів убійників він не позабивав, як написано в Книзі Мойсеєвого Зако́ну, що наказав був Господь, говорячи: „Не будуть забиті батьки за синів, а сини не будуть забиті за батьків, а тільки кожен за гріх свій буде забитий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Він побив Едома в Соляній долині, десять тисяч, і взяв у війні Селу, і назвав ім\'я́ їй: Йоктеїл, і так вона зветься аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Тоді Амація послав послів до Йоаша, сина Єгоахаза, сина Єгу, Ізраїлевого царя, говорячи: „Іди ж, поміряємось!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'І послав Йоаш, Ізраїлів цар, до Амації, Юдиного царя, говорячи: „Терен, що на Ливані, послав до кедри́ни, що на Ливані, кажучи: Дай же дочку́ свою моєму синові за жінку! Та перейшла́ польова́ звірина́, що на Ливані, і ви́топтала той те́рен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Побити — побив ти Едома, і підне́сло тебе твоє серце. Пишайся собі та сиди в своїм домі! І пощо бу́деш ти дрочи́тися зо злом, бо впадеш ти та Юда з тобою?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Та не послухався Амація. І вийшов Йоаш, Ізраїлів цар, і помірялися він та Амація, цар Юдин, у Юдиному Бет-Шемеші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'І був розбитий Юда Ізраїлем, і повтікали кожен до намету свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'А Йоаш, цар Ізраїлів, схопи́в Амацію, Юдиного царя, сина Йоаша, сина Ахазії, у Бет-Шемеші, і прибув до Єрусалиму, і зруйнував єрусалимський мур від Єфремової брами аж до брами нарі́жної, чотири сотні ліктів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'І забрав він усе золото й срібло, та ввесь по́суд, що знахо́дився в Господньому домі та в скарбни́цях дому царе́вого, та запоручників, і вернувся в Самарію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'А решта діл Йоаша, що зробив він, та лица́рськість його, і як воював з Амацією, Юдиним царем, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'I спочив Йоаш зо своїми батьками, і був похований у Самарії з Ізраїлевими царями, а замість нього зацарював син його Єровоа́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'І жив Амація, Йоашів сии, цар Юдин, по смерті Йоаша, Єгоахазового сина, Ізраїлевого царя, п\'ятнадцять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'А решта діл Амації, — ось вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'І вчинили на нього змову в Єрусалимі, та він утік до Лахішу. І послали за ним до Лахішу, — і вбили його там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'І пове́зли його на ко́нях, і він був похований з батька́ми своїми в Давидовому Місті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'І взяв ввесь Юдин наро́д Азарію, — а він був віку шістнадцяти літ, — і настановили його царем замість батька його Амації.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Він збудував Елат, і вернув його Юді, як цар спочив зо своїми батьками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'П\'ятнадцятого року Амації, сина Йоаша, Юдиного царя, зацарював Єровоа́м, син Йоаша, Ізраїлевого царя, у Самарії, на сорок і один рік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'І робив він зло в Господніх оча́х, не відступався від усіх гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Він вернув Ізраїлеву границю відти, де йдеться до Гамату, аж до степово́го моря, за словом Господа, Бога Ізраїля, що говорив через раба Свого Йону, сина пророка Амміттая, що з Ґат-Гахеферу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'бо Господь побачив Ізраїлеву біду, дуже гірку́, і не було вже невільного та вільного, і не було помічника́ Ізраїлеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Та не говорив Госпо́дь знищити Ізраїлеве ім\'я́ з-під неба, і споміг їх рукою Єровоама, Йоашового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'А решта діл Єровоама та лица́рськість його, як воював, і як вернув Юді Дамаск та Хамат в Ізраїлі, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'І спочив Єровоам із батька́ми своїми та з Ізраїлевими царями, а замість нього зацарював син його Захарій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Двадцятого й сьомого року Єровоама, Ізраїлевого царя, зацарював Аза́рія, син Амації, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Він був віку шістнадцяти літ, коли зацарював, і царював в Єрусалимі п\'ятдеся́т і два роки. А ім\'я́ його матері — Єхолія, з Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'І робив він угодне в Господніх оча́х, усе так, як робив його батько Амація.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Тільки па́гірки не були знищені, — народ ще прино́сив жертву та кадив на па́гірках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'І вдарив Господь царя, і він був прокаже́ний аж до дня своєї смерти, і сидів ув осібному домі. А над домом був Йотам, царів син, — він судив народ Кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'А решта діл Азарії та все, що він робив, — ось вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'І спочив Азарія з своїми батьками, і його поховали з його батьками в Давидовому Місті, а замість нього зацарював син його Йотам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Тридцятого й восьмого року Азарії, Юдиного царя, зацарював над Ізраїлем у Самарії Захарій, син Єровоама, на шість місяців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'І робив він зле в Господніх оча́х, як робили батьки його, — не відступився від гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'І вчинив змову на нього Шаллум, Явешів син, і бив його перед наро́дом і вбив його, і зацарював замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'А решта діл Захарія, — ось вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Оце Господнє слово, що Він промовляв до Єгу, говорячи: „Сини чотирьох поколінь будуть сидіти тобі на Ізраїлевому троні“. І сталося так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Шаллу́м, Явешів син, зацарював тридцятого й дев\'ятого року Уззійї, Юдиного царя, і царював місяць ча́су в Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'І пішов Менахе́м, Ґадіїв син, з Тірци, і прибув у Самарію, та й побив Шаллума, Явешового сина, в Самарії, і вбив його, і зацарював замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'А решта днів Шаллума та змова його, яку він учинив був, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Тоді побив Менахем місто Тіфсах та все, що в ньому, і границі його від Тірци, бо не відчини́ло воно брами. І він вибив його, а все вагітне́ повитина́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Тридцятого й дев\'ятого року Азарії, Юдиного царя, зацарював над Ізраїлем у Самарії Менахем, Ґадіїв син, на десять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'І робив він зле в Господніх оча́х, не вступився від гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля. За його днів');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'прийшов Пул, асирійський цар, на край. І дав Менахем Пулові тисячу талантів срібла, щоб його руки були з ним, щоб зміцнити царство в його руці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'А Менахем розклав це срібло на Ізраїля, на всіх воякі́в, щоб дати асирійському цареві, по п\'ятдесят шеклів срібла від кожного чоловіка. І вернувся асирійський цар, і не стояв там у Краю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'А решта діл Менахема та все, що він робив, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'І спочив Менахем з батька́ми своїми, а замість нього зацарював син його Пекахія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'П\'ятдесятого року Азарії, Юдиного царя, зацарював над Ізраїлем у Самарії Пекахія, син Менахемів, на два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'І робив він зло в Господніх оча́х, — не відступався від гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'І вчинив на нього змову Пе́ках, син Ремалії, старшина́ його, і забив його в палаті царсько́го дому, з Арґовом та з Ар\'єм, а з ним було п\'ятдесят чоловіка з ґілеадян. І він убив його, і зацарював замість нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'А решта діл Пекахії та все, що він робив, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'П\'ятдесятого й другого року Азарії, Юдиного царя, зацарював у Самарії над Ізраїлем Пеках, син Ремалії, на двадцять років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'І робив він зло в Господніх оча́х, — не відступався від гріхів Єровоама, Неватового сина, що вводив у гріх Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'За днів Пекаха, Ізраїлевого царя, прийшов Тіґлат-Піл\'есер, цар асирійський, і взяв Іййона, і Авел-Бет-Мааху, і Йоноаха, і Кедеша, і Хацора, і Ґілеада, і Ґаліла, увесь край Нефталимів, та й вигнав їх до Асирії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'А Осі́я, син Елин, склав змову на Пекаха, сина Ремалії, і вдарив його та й убив його, і зацарював замість нього двадцятого року Йотама, Уззійїного сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'А решта діл Пекаха та все, що́ він зробив, — ото вони написані в Книзі Хроніки Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Другого року Пекаха, сина Ремалії, Ізраїлевого царя, зацарював Йотам, син Уззійї, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Він був віку двадцяти й п\'яти років, коли зацарював, і шістнадцять літ царював в Єрусалимі. А ім\'я́ його матері — Єруша, Садокова дочка́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'І робив він угодне в Господніх оча́х, — усе, що робив був його батько Уззійя, робив він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Тільки па́гірки не були знищені, — наро́д іще прино́сив жертви та кадив на па́гірках. Він збудував горі́шню браму Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'А решта діл Йотама та все, що́ він зробив, — ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'За тих днів зачав Господь посилати на Юду Реціна, сирійського царя, та Пекаха, сина Ремалії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'І спочив Йотам із своїми батька́ми, і був похований з батьками своїми в Місті Давида, свого батька, а замість нього зацарював син його Ахаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Сімнадцятого року Пекаха, сина Ремалії, зацарював Ахаз, син Йотама, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Ахаз був віку двадцяти літ, коли він зацарював, і царював в Єрусалимі шістнадцять років, і не робив угодного в оча́х Господа, Бога свого, як батько його Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'І ходив він дорогою Ізраїлевих царів, і навіть сина свого провів через огонь для Молоха, за гидо́тою тих народів, що Господь вигнав їх перед Ізраїлевими синами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'І прино́сив він жертву та кадив на па́гірках, і на згі́р\'ях, та під усяким зеленим деревом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Тоді прийшов Реці́н, сирійський цар, та Пеках, син Ремалії, Ізраїлів цар, на війну до Єрусалиму. І облягли́ вони Ахаза, та не змогли́ звоювати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Того ча́су Рецін, сирійський цар, вернув Едомові Елата, і вигнав юдеїв з Елоту. І едо́мляни прибули́ до Елату, й осілися там, і живуть тут аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'І послав Ахаз послів до Тіґлат-Пелесера, асирійського царя, говорячи: „Я твій раб та син твій, — вийди й спаси мене з руки сирійського царя та з руки царя Ізраїлевого, що повстають на ме́не“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'І взяв Ахаз срібло та золото, зна́йдене в Господньому домі та в скарбницях дому царе́вого, і послав дару́нка до асирійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'І послухав його асирійський цар. І пішов асирійський цар на Дамаск і взяв його, а його мешканців вигнав до Кіру, а Реціна вбив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'І пішов цар Ахаз назу́стріч Тіґлат-Піл\'есера, асирійського царя, до Дамаску, і побачив дамаського же́ртівника. І послав цар Ахаз до священика Урії подобу же́ртівника та взір його всієї його будови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'І збудував священик Урі́я же́ртівника, — як усе, що послав був цар Ахаз із Дамаску, так зробив священик Урія до прихо́ду царя Ахаза з Дамаску.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'І прибув цар із Дамаску, і побачив цар того жертівника, і приступив цар до жертівника, і приніс на ньому жертву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'І спалив він своє цілопа́лення та свою жертву хлі́бну, і вилив свою ливну жертву, і покропив кров\'ю своїх мирних жертов того же́ртівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'А мідяно́го же́ртівника, що перед Господнім лицем, він переставив із переднього боку храму, з-поміж жертівника та з-поміж Господнього дому, і поставив його на бік жертівника на північ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'I наказав цар Ахаз священикові Урії, говорячи: „На великому жертівнику пали ра́нішнє цілопа́лення та вечірню хлібну жертву, і цілопа́лення цареве та хлібну його жертву, і цілопа́лення всього народу Кра́ю та хлібну їхню жертву, і їхні ливні жертви. І всю кров цілопа́лення та всю кров жертви покро́пиш на нього. А щодо мідяно́го жертівника, то я розва́жу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'І зробив священик Урія все так, як наказав був цар Ахаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'А цар Ахаз повідрубував рами підстав, і відсунув із них умивальницю, і зняв море з мідяни́х волів, що під ним, і поставив його на камінну підло́гу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'І закритий суботній перехі́д, що збудували при храмі, і зо́внішній царськи́й вхід він обернув до Господнього дому задля асирійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'А решта діл Ахаза, що́ він зробив, ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'І спочив Ахаз із батьками своїми, і був похований з батька́ми своїми в Давидовому Місті, а замість нього зацарював син його Хізкійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Дванадцятого року Ахаза, Юдиного царя, зацарював над Ізраїлем у Самарії Осі́я, син Елин, на дев\'ять років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'І робив він зле в Господніх оча́х, тільки не так, як ті Ізраїлеві царі, що були перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'На нього вийшов Салманасар, цар асирійський, і Осі́я став йому за раба́, і давав йому дани́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Та асирійський цар знайшов в Осі́ї змову, що він посилав послів до Со, єгипетського царя, та не прино́сив асирійському цареві данини, як рік-у-рік те робив був. І замкнув його асирійський цар, і зв\'язав його в в\'язни́чому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'І вийшов асирійський цар на ввесь Край, і прийшов до Самарії, й обляга́в її три роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Дев\'ятого року Осі́ї асирійський цар здобув Самарію, та й вигнав Ізраїля до Асирії, і осадив їх у Халаху, і в Хаворі над річкою Ґозан, і в містах Мідії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'І сталося, коли Ізраїлеві сини грішили проти Господа, Бога свого, що ви́провадив їх з єгипетського кра́ю з руки фараона, єгипетського царя, і боя́лися інших богів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'і ходили уставами тих народів, що Госпо́дь повиганяв їх перед Ізраїлевими синами, та Ізраїлевих царів, які вони встановили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'а Ізраїлеві сини вимишляли на Господа, Бога свого, слова́, що не були слушні, і будували собі па́гірки по всіх своїх містах, від вартово́ї башти аж до тверди́нного міста,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'і ставили собі стовпи для богів та Астарти на кожному високому взгі́р\'ї та під усяким зеленим деревом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'і кадили там на всіх па́гірках, як ті люди, що Господь повиганяв перед ними, і робили злі речі, щоб гніви́ти Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'і служили бовва́нам, про яких Господь говорив їм: „Не бу́дете робити цієї речі“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'то Господь засві́дчив в Ізраїлі та в Юді через усіх Своїх пророків та всіх прозорли́вців, говорячи: „Верніться з ваших злих доріг, і додержуйте Моїх заповідей, уставів Моїх, згідно зо всім Зако́ном, якого Я наказав був вашим батькам, і якого послав до вас через Моїх рабів пророків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Та не слухали вони, і робили твердо́ю свою шию, як шия їхніх батькі́в, що не вірили в Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'І не́хтували вони постанови Його, і заповіта Його, що склав з їхніми батька́ми, і свідо́цтва Його, що засві́дчив на них, і пішли за гидо́тою й марно́тами, та за наро́дами, що були навколо них, про яких Господь наказав був їм не робити, як вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'І полишили вони всі заповіді Господа, Бога свого, і зробили собі литого бовва́на, двох телят, і зробили Астарту, і вклонялися всьому небесному ві́йськові та служили Ваалові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'І вони перево́дили через огонь своїх синів та дочо́к своїх, і чарува́ли ча́рами, і ворожили, і віддавалися робити зло в Господніх оча́х, щоб гнівити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'І сильно розгнівався Господь на Ізраїля, і відкинув їх від Свого лиця, — не позостало ніко́го, тільки саме Юдине пле́м\'я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Та й Юда не додержував заповідей Господа, Бога свого, — і ходили вони Ізраїлевими постановами, які вони встанови́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'І відвернувся Господь від усього Ізраїлевого насіння, і впокоря́в їх, і давав їх у руку грабі́жників, аж поки не кинув їх від лиця Свого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'бо Ізраїль розірвав з Давидовим домом, і вони зробили царем Єровоама, Неватового сина, а Єровоам відвернув Ізраїля від Господа, і вводив їх у великий гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'І ходили Ізраїлеві сини в усіх Єровоамових гріхах, які він робив, не відсту́палися з того,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'аж поки Господь не відкинув Ізраїля від лиця Свого, як говорив був через усіх Своїх рабів пророків. І пішов Ізраїль на вигна́ння з своєї землі до Асирії, і він там аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'І спрова́див асирійський цар людей з Вавилону, і з Кути, і з Авви, і з Гамоту, і з Сефарваїму, й осели́в по містах Самарії замість Ізраїлевих синів. І посіли вони Самарію, й осілися по містах її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'І сталося, на поча́тку пробува́ння їх там не боялися вони Господа, — і Господь послав на них левів, і вони нищили їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'І сказали вони до асирійського царя, говорячи: „Ті люди, яких ти вигнав та осели́в по містах Самарії, не знають прав Бога цього Кра́ю, і Він послав на них оцих левів, і ось вони нищать їх, бо вони не знають права Бога цього Кра́ю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'І наказав асирійський цар, говорячи: „Відведіть туди одно́го зо священиків, яких вигнали звідти, і пі́дуть, і осядуть там, і він навчатиме їх пра́ва Бога цього кра́ю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'І прибув один із священиків, яких вигнали з Самарії, й осівся в Бет-Елі, і він навчав їх, як мають боятися Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Та крім того кожен народ робив свого бога, і ставили їх у па́гірковому місці, що робили попередні самаряни, кожен народ по своїх містах, де вони сиділи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'А вавилоняни зробили Суккот-Бенота, а кутяни зробили Нереґала, а гаматяни зробили Ашіму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'а авв\'яни зробили Нівхаза та Тартака, а ме́шканці Сефарваїму палили синів своїх ув огні Адраммелехові й Анаммелехові, сефарваїмським богам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'І при тому вони боялися Господа, і настанови́ли собі з-серед себе священиків па́гірків, і вони прино́сили їм жертви в пагірковому місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Вони боялися Господа, і богам своїм служили за правом тих народів, звідки повиганя́ли їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Аж до цього дня вони роблять за колишнім правом, — вони не бояться Господа, і не роблять за уставами своїми та за правом своїм, ані за Зако́ном, ані за заповіддю, як наказав був Господь синам Якова, якому дав ім\'я́ Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'І склав Господь із ними заповіта, і наказав їм, говорячи: „Не будете боятися інших богів, і не будете вклонятися їм, і не будете служити їм, і не будете прино́сити жертов їм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'а тільки Господа, що вивів вас із єгипетського кра́ю великою силою та ви́тягненим раме́ном, Його будете боятися, і Йому будете вклонятися, і Йому будете прино́сити жертви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'І устави, і права́, і Зако́на, і заповідь, які написав вам, бу́дете доде́ржувати, щоб вико́нувати по всі дні, а богів інших не будете боятися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'А заповіта, що Я склав із вами, не забудете, і не будете боятися інших богів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'а тільки Господа, Бога вашого, будете боятися, і Він вирятує вас із руки всіх ваших ворогів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Та не послухали вони, бо все робили за своїм попереднім зви́чаєм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'І ті народи все боялися Господа, але служили бовва́нам своїм. Так само сини їхні та сини їхніх синів, — як робили батьки їхні, так роблять вони аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'І сталося третього року Осі́ї, сина Елиного, Ізраїлевого царя, зацарював Єзекія, син Ахазів, цар Юдин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Він був віку двадцяти й п\'яти літ, коли зацарював, і царював в Єрусалимі двадцять і дев\'ять літ. А ім\'я́ його матері — Аві, дочка́ Захарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'І робив він угодне в Господніх оча́х, усе так, як робив був його батько Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Він понищив па́гірки, і поламав стовпи для богів, і стяв Астарту, і розбив мідяно́го змія, якого зробив був Мойсей, бо аж до цих днів Ізраїлеві сини все кадили йому й кликали його: Нехушта́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Він наді́явся на Господа, Бога Ізраїля, і такого, як він, не було між усіма́ царями Юдиними, ані між тими, що були перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'І міцно тримався він Господа, не відступався від Нього, і додержував заповіді Його, що наказав був Господь Мойсеєві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'І був Господь із ним, — у всьому, куди він ходив, він мав пово́дження. І збунтувався він на асирійського царя, і не служив йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Він побив филисти́млян аж до Аззи́ та границі її від вартово́ї башти аж до тверди́нного міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'І сталося четвертого року царя Єзекії, — це сьомий рік Осі́ї, Елиного сина, Ізраїлевого царя, — пішов Салманаса́р, цар асирійський, на Самарію, та й обліг її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'І здобув він її по трьох рока́х: шостого року Єзекії, — це дев\'ятий рік Осі́ї, Ізраїлевого царя, — була здобута Самарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'І вигнав асирійський цар Ізраїля до Асирії, і попровадив їх у Халах, і в Хавор, над річку Ґазан, та до мідійських міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Це за те, що не слухалися вони голосу Господа, Бога свого, і переступали заповіта Його; усього, що наказав був Мойсей, раб Господній, вони ані не слухали, ані не робили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'А чотирнадцятого року царя Єзекії прийшов Санхері́в, цар асирійський, на всі укріплені Юдині міста́, та й захопи́в їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'І послав Єзекія, цар Юдин, до царя асирійського, до Лахішу, говорячи: „Згрішив я! Відійди від мене, а що накладе́ш на мене, понесу́.“І наклав асирійський цар на Єзекію, Юдиного царя, три сотні талантів срібла та тридцять талантів золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'І віддав Єзекія все срібло, зна́йдене в Господньому домі та в царе́вих скарбни́цях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Того ча́су Єзекія відрубав золото з дверей Господнього дому та зо стовпів, що покрив був Єзекія, Юдин цар, золотом, і дав його́ асирійському цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'А асирійський цар послав із Лахішу до царя Єзекії головного кома́ндувача, і великого є́внуха та великого ча́шника з великим ві́йськом до Єрусалиму. І пішли вони, і прийшли та й стали над водотя́гом горі́шнього ставу, що на битій дорозі до поля Валю́шників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'І кли́кнули вони до царя, і до них вийшов Еліяким, син Хілкійї, начальник палати, і писар Шевна, та Йоах, син Асафів, ка́нцлер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'І сказав до них великий ча́шник: „Скажіть Єзекії: Отак сказав великий цар, цар асирійський: Що́ це за надія, на яку ти наді́єшся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Чи думаєш ти, що слово уст, то вже рада та сила до війни? На ко́го тепер наді́єшся, що збунтувався проти мене?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Тепер оце ти надієшся собі опе́ртися на оту пола́ману очерети́ну, на Єгипет, що коли хто опирається на неї, то вона вхо́дить у долоню йому й продіря́влює її. Отакий фараон, цар єгипетський, для всіх, хто надіється на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'А коли ви скажете мені: Ми наді́ємось на Господа, Бога нашого, то чи ж Він не Той, що Єзекія понищив па́гірки Його та же́ртівники Його, і сказав Юді та Єрусалимові: перед оцим тільки же́ртівником будете вклонятися в Єрусалимі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'А тепер піди в за́клад із моїм паном, ассирійським царем, і я дам тобі дві тисячі ко́ней, якщо ти зможеш собі дати на них верхівці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'І як же ти проженеш хоч одно́го намісника з найменших слуг мого пана? А ти собі наді́єшся на Єгипет ради колесни́ць та верхівців!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Тепер же, чи без Господа прийшов я на це місце, щоб знищити його? Господь сказав був мені: Піди на той край та знищ його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'І сказав Еліяким, син Хілкійї, і Шевна та Йоах до великого ча́шника: „Говори до своїх рабів по-араме́йському, бо ми розуміємо, і не говори з нами по-юде́йському в слух тих людей, що на мурі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'І сказав до них великий ча́шник: „Чи пан мій послав мене говорити ці слова́ до твого пана та до тебе? Хіба не до цих людей, що сидять на мурі, щоб із вами їсти вій кал та пити свою се́чу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'І став великий чашник, і кликнув гучним голосом по-юдейському, і говорив і сказав: „Послухайте слово великого царя, царя асирійського:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Так сказав цар: Нехай не ду́рить вас Єзекія, бо він не зможе врятува́ти вас від руки його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'І нехай не запевня́є вас Єзекія Господом, говорячи: Рятуючи, врятує вас Господь, і не буде да́но цього міста в руку царя асирійського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Не слухайте Єзекії, бо так сказав цар асирійський: Примиріться зо много, та й ви́йдіть до мене, та й їжте кожен свій виноград та кожен фіґу свою, і пийте кожен воду зо своєї ко́панки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'аж поки я не прийду́ й не візьму́ вас до краю такого ж, як ваш Край, до кра́ю збіжжя та виноградного соку, до краю хліба та виноградників, до краю оливки, оливного соку та меду, — щоб ви жили й не вмирали! І не слухайте Єзекії, коли він намовляє вас, говорячи: Господь порятує нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Чи справді врятували боги тих народів, кожен свій край від руки асирійського царя?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Де боги Гамату та Арпаду? Де боги Сефарваїму, Гени та Івви? Чи врятува́ли вони Самарію від моєї руки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Котрий з-поміж усіх богів цих краї́в урятував свій край від моєї руки, — то невже ж Господь уряту́є Єрусалим від моєї руки?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'І мовчав той наро́д, і не відповів йому ані сло́ва, бо це був нака́з царя, що сказав: „Не відповідайте йому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'І прийшов Еліяким, син Хілкійї, начальник палати, і писар Шевна, і Йоах, Асафів син, ка́нцлер, із роздертими шатами, до Єзекії, і доне́сли йому слова́ великого чашника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'І сталося, як почув це цар Єзекі́я, то розде́р свої шати та накрився вере́тою, і ввійшов до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'І послав він Еліякима, начальника палати, і писаря Шевну, та старши́х із священиків, покритих вере́тами, до пророка Ісаї, Амосового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'І сказали вони до нього: „Так сказав Єзекія: Цей день — це день горя й карта́ння та нару́ги! Бо підійшли діти аж до виходу утро́би, та немає сили породити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Може почує Господь, Бог твій, всі слова́ великого чашника, що його послав асирійський цар, пан його, на обра́зу Живого Бога, і Господь, Бог твій, покарає за слова́, які чув, а ти принесе́ш молитву за рештку, що ще знахо́диться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'І прийшли раби царя Єзекії до Ісаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'І сказав їм Іса́я: „Так скажете вашому панові: Так сказав Господь: Не бійся тих слів, що почув ти, якими ображали Мене слуги асирійського царя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Ось Я дам в нього духа, і він почує звістку, — і ве́рнеться до свого краю. І Я вражу́ його мече́м у його кра́ї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'І вернувся великий чашник, і знайшов асирійського царя, що воював проти Лівни, бо почув, що той рушив із Лахішу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'А коли він почув про Тіргаку, царя етіопського, таке: „Ось він вийшов воювати з тобою!“то вернувся, і послав послів до Єзекії, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '„Так скажете до Єзекії, Юдиного царя, говорячи: „Нехай не зво́дить тебе Бог твій, що ти наді́єшся на Нього, кажучи: Не буде да́ний Єрусалим у руку асирійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Ось ти чув, що́ зроби́ли асирійські царі всім края́м, щоб учинити їх закляттям, а ти будеш урято́ваний?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Чи врятували їх боги тих народів, яких понищили батьки мої: Гозана, і Харана, і Рецефа, і синів Едена, що в Телассарі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Де він, цар Гамату, і цар Арпаду, і цар міста Сефарваїму, Гени та Івви?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'І взяв Єзекія ті листи з руки послів, і прочитав їх, і ввійшов у Господній дім. І Єзекія розгорну́в одного листа перед Господнім лицем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'І Єзекія молився перед Господнім лицем і сказав: „Господи, Боже Ізраїлів, що сидиш на херуви́мах! Ти Той єдиний Бог для всіх царств землі, Ти створив небеса́ та землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Нахили́, Господи, ухо Своє та й почуй! Відкрий, Господи, очі Свої та й побач, і почуй слова Санхеріва, що прислав ображати Живого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Справді, Господи, асирійські царі попусто́шили ті народи та їхній край.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'І кинули вони їхніх богів на огонь, бо не боги вони, а тільки чин лю́дських рук, дерево та камінь, і понищили їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'А тепер, Господи, Боже наш, спаси нас від руки його, і нехай знають усі царства землі, що Ти Господь, Бог єдиний!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'І послав Ісая, Амосів син, до Єзекії, говорячи: „Так сказав Госпо́дь, Бог Ізраїлів: Я почув те, про що ти молився до Мене, про Санхеріва, царя асирійського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Ось те слово, яке Господь говорив про нього: Горду́є тобою, сміється із тебе діви́ця, сіонська дочка́, вслід тобі головою хитає дочка́ Єрусалиму!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Кого лаяв ти та ображав, і на ко́го пови́щив ти голос та вго́ру підніс свої очі? — На Святого Ізраїлевого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Через послів своїх Господа ти ображав та казав: Із бе́зліччю своїх колесни́ць я вийшов на го́ри високі, на боки Ливану, і позру́бую ке́дри високі його, добі́рні його кипари́си, і ви́йду аж на вершо́к його на нічліг, — у гущину́ його саду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Я копаю та п\'ю чужу воду, і стопо́ю своєї ноги повису́шую я всі єгипетські рі́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Хіба ти не чув, що віддавна зробив Я оце, що за днів стародавніх Я це був створи́в? Тепер же спровадив Я це, що ти нищиш міста поукріплювані, на купу румо́вищ обертаєш їх...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'А ме́шканці їхні безсилі, настрашені та побенте́жені. Вони стали, як зілля оте польове́, мов трава зеленіюча, як трава на даха́х, як попа́лене збіжжя, яке не доспіло...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'І сидіння твоє, і твій вихід та вхід твій Я знаю, і твоє проти Мене обу́рення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'За твоє проти Мене обу́рення, що горди́ня твоя надійшла до ушей Моїх, то на ні́здрі твої Я сережку привішу, а вуди́ло Моє — в твої у́ста, і тебе поверну́ Я тією дорогою, якою прийшов ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'А оце тобі знак: їжте цього року збіжжя самосі́йне, а другого року — саморо́сле, а третього року — сійте та жніть, і садіть виноградники, та й їжте їх плід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'А врятоване Юдиного дому, що лишилося, пустить корі́ння додолу, і свого плода́ дасть уго́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Бо з Єрусалиму вийде позоста́ле, а рештки — від гори Сіону. Ревність Господа Саваота зробить це!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Тому́ так сказав Господь про асирійського царя: Він не вві́йде до міста оцього, і туди він не кине стріли́, і щито́м її не попере́дить, і ва́ла на нього не ви́сипле!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Якою дорогою при́йде, то нею пове́рнеться, у місто ж оце він не вві́йде, говорить Господь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'І це місто Я обороню́ на спасі́ння його ради Себе та ради Давида, Мойого раба“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'І сталося тієї ночі, і вийшов Ангол Господній, і забив в асирійському табо́рі сто й вісімдеся́т і п\'ять тисяч. І повставали вони рано вранці, аж ось — усі мертві тру́пи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'А Санхерів, асирійський цар, рушив та й пішов, і вернувся й осівся в Ніневі́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'І сталося, коли він молився в домі Нісроха, свого бога, то Адраммелех та Шар\'ецер убили його мече́м, а самі втекли́ до кра́ю Арара́т. А замість нього зацарював син його Есар-Хаддон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Тими днями смертельно захворі́в був Єзекія. І прийшов до нього Іса́я, Амо́сів син, пророк, і сказав до нього: „Так сказав Господь: Заряди своїм домом, бо ти вмреш, а не ви́дужаєш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'А той відвернув обличчя своє до стіни, і помолився до Господа, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '„О, Господи, згадай же, що я ходив перед лицем Твоїм правдою та ці́лим серцем, і робив я добре в оча́х Твоїх“. І заплакав Єзекія ревним плаче́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'І сталося, Ісая не вийшов ще з сере́дини міста, а до нього було Господнє слово, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '„Вернися, і скажеш до Єзекії, володаря Мого народу: Так сказав Господь, Бог батька твого Давида: Почув Я молитву твою, побачив Я сльозу́ твою! Ось Я вилікую тебе, — третього дня зі́йдеш ти до Господнього дому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'І до днів твоїх Я дода́м п\'ятнадцять літ, і з руки асирійського царя врятую тебе та це місто, й обороню́ це місто ради Себе та ради раба Свого Давида“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'А Ісая сказав: „Візьміть грудку фіґ“. І взяли́ й поклали на того гнояка́, — і він ви́дужав...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'І сказав Єзекія до Ісаї: „Який знак, що Господь мене ви́лікує, і що я третього дня зійду́ до Господнього дому?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'І сказав Ісая: „Ось тобі знак той від Господа, що Господь зробить ту річ, про яку говорив: Чого хочеш, — щоб пішла тінь уперед на десять ступені́в, чи щоб верну́лася на десять ступені́в?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'І сказав Єзекія: „Легко тіні похили́тися вперед на десять ступені́в; ні, — а нехай тінь ве́рнеться назад на десять ступені́в!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'І кли́кнув пророк Ісая до Господа, і Він заверну́в тінь на ступеня́х, де вона спускалася на ступені́ Ахазові, на десять ступені́в...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Того ча́су послав Беродах-Бал\'адан, син Бал\'аданів, вавилонський цар, листа́ та дару́нка до Єзекії, бо прочув був, що Єзекія захворі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'І вислухав їх Єзекія, і показав їм усю скарбни́цю свою, — і срібло, і золото, і па́хощі, і добру оливу, і всю зброївню свою, і все, що знахо́дилося в його скарбницях. Не було речі, якої не показав би їм Єзекія в домі своїм та в усім володі́нні своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'І прийшов пророк Іса́я до царя Єзекії та й сказав до нього: „Що́ говорили ці люди? І звідки вони прийшли до тебе?“А Єзекія сказав: „Вони прийшли з далекого кра́ю, з Вавилону“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'І той сказав: „Що́ вони бачили в домі твоїм?“І Єзекія сказав: „Усе, що в домі моїм, вони бачили, — не було речі, якої не показав би я їм у скарбни́цях своїх“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'I сказав Ісая до Єзекії: „Послухай Господнього слова:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Ось прихо́дять дні, і все, що́ в домі твоєму, і що були зібрали батьки твої аж до цього дня, буде ви́несене до Вавилону. Нічого не позоста́неться, говорить Господь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'А з синів твоїх, що вийдуть із тебе, яких ти поро́диш, де́кого заберуть, — і вони будуть є́внухами в палатах вавилонського царя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'І сказав Єзекія до Ісаї: „Добре Господнє слово, яке ти сказав!“І подумав собі: „Так, мир та безпека буде за моїх днів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'А решта діл Єзекії та вся лица́рськість його, і як він зробив ста́ва та водотя́га, і впровадив воду до міста, — ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'І спочив Єзекія зо своїми батьками, а замість нього зацарював син його Манасі́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Манасі́я був віку дванадцяти літ, коли він зацарював, і царював в Єрусалимі п\'ятдесят і п\'ять літ. А ім\'я́ його матері — Хевці-Ваг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'І робив він зло в Господніх оча́х, за гидо́тою тих народів, яких Господь повиганяв з-перед обличчя Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'І він зно́ву побудував па́гірки, що їх винищив був його батько Єзекія, і понаставля́в же́ртівників Ваалові, і зробив Аста́рту, як зробив був Ахав, Ізраїлів цар, і вклонявся всім небесним світи́лам та служив їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'І побудував він же́ртівники в Господньому домі, про якого сказав був Господь: „В Єрусалимі покладу́ Я Ім\'я́ Своє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'І побудував він жертівники для всіх небесних світил на обо́х подві́р\'ях Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'І він перепрова́див свого сина через огонь, і гадав, і ворожив, і настанови́в викликувачів духів померлих та духів віщих, і багато робив зла в оча́х Господа, щоб гнівити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'І поставив він бовва́на Астарти, якого зробив, у домі, про якого Господь сказав був до Давида та до сина його Соломона: „У цьо́му домі та в Єрусалимі, що його Я вибрав зо всіх Ізраїлевих племен, покладу́ Я Ім\'я́ Своє навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'І більше не мандрува́тиме Ізраїлева нога з тієї землі, яку Я дав їхнім батькам, якщо тільки вони бу́дуть пильнува́ти робити все так, як наказав Я їм, та ввесь Зако́н, що наказав їм Мій раб Мойсей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Та не послухалися вони. І Манасія звів їх до того, щоб робити гірше від тих народів, яких Господь вигубив з-перед обличчя Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'І говорив Господь через Своїх рабів пророків, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '„За те, що Манасія, цар Юдин, зробив ці гидо́ти, учинив гірше від усього, що́ робили були аморе́яни, що були перед ним, і ввів у гріх також Юду божка́ми своїми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'тому так сказав Господь, Бог Ізраїлів: Ось Я наво́джу таке зло на Єрусалим та на Юду, що в кожного, хто почує про це, задзвени́ть в обох ву́хах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'І протягну́ Я на Єрусалим мірку Самарії, та вагу Ахавого дому, і ви́тру Єрусалим, як витира́ють миску: витер і перевернув її догори́ дном!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'І Я покину останок наді́лу Мого, і дам їх у руку їхнім ворогам, і вони будуть на грабі́ж та на здо́бич для всіх їхніх ворогів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'тому́, що вони робили зло в Моїх оча́х, і все гніви́ли Мене він дня, коли вийшли їхні батьки з Єгипту, й аж до дня цього“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'А також Манасі́я пролив дуже багато невинної кро́ви, аж напо́внив нею Єрусалим від входу до входу, окрім свого гріха́, що ввів у гріх Юду, щоб чинити зле в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'А решта діл Манасії, та все, що́ він зробив, і гріх його, яким він грішив, ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'І спочив Манасія з батьками своїми, і був похований в садку́ свого дому, в Уззиному садку́, а замість нього зацарював син його Амо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Амо́н був віку двадцяти й двох років, коли він зацарював, і царював він в Єрусалимі два роки. А ім\'я́ його матері — Мешуллемет, дочка́ Харуца з Йотви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'І робив він зло в Господніх оча́х, як робив його батько Манасія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'І ходив він усією тією дорогою, якою ходив його ба́тько, і служив тим бовва́нам, яким служив батько його, і вклонявся їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'І покинув він Господа, Бога батьків своїх, і не ходив Господньою дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'І вчинили змову слу́ги Амона на нього, і вбили царя в його домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Та наро́д Краю перебив усіх змо́вників на царя Амона. І народ настановив царем Кра́ю замість нього сина його Йосі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'А решта діл Амона, усе, що́ робив він, ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'І поховали його в його гробі в Уззиному садку́, а замість нього зацарював син його Йосія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Йосі́я був віку восьми літ, коли він зацарював, і царював в Єрусалимі тридцять і один рік. А ім\'я́ його матері Єдида, дочка́ Адаї з Боцкату.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'І робив він угодне в Господніх оча́х, і ходив усією дорогою свого батька Давида, і не вступався ані праворуч, ані ліворуч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'І сталося вісімнадцятого року царя Йосії, послав цар Шафана, сина Ацалії, Мешулламового сина, писаря, до Господнього дому, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '„Піди до Хілкійї, первосвященика, і нехай перелі́чить те срібло, що зне́сене до Господнього дому, що зібрали від народу сторожі́ поро́га.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'І нехай дадуть його на руку викона́вцям роботи, поставленим у Господньому домі, а ті нехай дадуть його тим, хто працює в Господньому домі, щоб направляти ушко́дження хра́му, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'тесляра́м, і будівни́чим, і муляра́м, щоб купувати дерево та те́сане каміння на направу хра́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Тільки нехай не облічуються з ними про те срібло, що да́не на їхню руку, бо чесно вони роблять“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'І сказав Хілкійя, первосвященик, до писаря Шафана: „Я знайшов у Господньому домі Книгу Зако́ну!“І дав Хілкійя ту Книгу Шафанові, і той перечитав її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'І ввійшов писар Шафан до царя, і приніс цареві вістку, і сказав: „Раби твої ви́сипали те срібло, що зна́йдене в домі, і дали́ його на руку виконавцям робо́ти, поставленим у Господньому домі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'І доніс писар Шафан цареві, говорячи: „Священик Хілкійя дав мені книгу“. І Шафан перечитав її перед царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'І сталося, як цар почув слова Книги Зако́ну, то роздер свої шати...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'І наказав цар священикові Хілкійї, і Ахікамові, Шафановому синові, і Ахборові, Міхаїному синові, і писареві Шафанові, і Асаї, царе́вому слузі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '„Ідіть, зверніться до Господа про мене й про народ, та про всього Юду, про слова цієї зна́йденої книги. Великий бо гнів Господній, що запалився на нас за те, що батьки наші не слухалися слів цієї книги, щоб робити все, що написано про нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'І пішов священик Хілкійя, і Ахікам, і Ахбор, і Шафан, і Асая до пророчиці Хулди, жінки Шаллума, сина Тікви, сина Хархасового, сто́рожа шат, — вона сиділа в Єрусалимі, на Ново́му Місті, — і говорили до неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'А вона сказала до них: „Так говорить Господь, Бог Ізраїлів: Скажіть чоловікові, що послав вас до мене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Так говорить Господь: Ось Я наведу́ лихо на оце місце та на ме́шканців його, усі слова́ тієї книги, що читав Юдин цар,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'за те, що вони покинули Мене, і кадили іншим богам, щоб гніви́ти Мене всім ді́лом своїх рук. І розпали́вся Мій гнів на це місце, — і він не погасне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'А Юдиному цареві, що послав вас звернутися до Господа, скажете йому так: Так говорить Господь, Бог Ізраїлів, — ті слова́, які ти чув:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'За те, що зм\'я́кло твоє серце, і ти впокори́вся перед Господнім лицем, коли почув, що́ Я говорив про це місце та про ме́шканців його, що вони стануть спусто́шенням та прокля́ттям, і що ти роздер шати свої та плакав перед Моїм лицем, то Я також почув, — говорить Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Тому́ то Я прилучу́ тебе до батьків твоїх, і ти будеш прилу́чений до гробів своїх у мирі, і очі твої не побачать усього того лиха, що Я наво́джу на оце місце“. І вони прине́сли цю вістку цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'А цар послав, і зібрали до нього всіх старши́х Юди та Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'І ввійшов до Господнього дому цар та кожен муж Юди, а з ним усі мешканці Єрусалиму, і священики, і пророки, і ввесь народ від мало́го й аж до великого, і він прочитав до їхніх ушей усі слова́ Книги Заповіту, зна́йденої в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'І став цар на підвищенні, і склав заповіта перед Господнім лицем, щоб ходити за Господом та доде́ржувати заповіді Його, і сві́дчення Його, і постанови Його всім серцем та всією душею, щоб виконати слова́ того заповіту, що написані в тій книзі. І ввесь народ пристав до заповіту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'І наказав цар Хілкійї, великому священикові, й іншим священикам та сторожа́м поро́га, щоб повино́сили з Господнього храму всі речі, зро́блені для Ваала та для Аста́рти, та для всіх небесних світил. І він попали́в їх поза Єрусалимом на кедро́нських поля́х, а їхній по́рох відніс до Бет-Елу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'І він поскидав жерці́в, що їх понаставля́ли були Юдині царі, і що вони кадили на па́гірках по Юдиних містах та в око́лицях Єрусалиму, і кадили для Ваала, і для сонця, і для місяця, і для планет, і для всіх небесних світил.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'І він виніс Астарту з Господнього дому поза Єрусалим до кедро́нської долини, та й спалив її в кедро́нській долині, і стер на по́рох, а її по́рох кинув на гроби́ звичайних людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'І він порозбива́в доми культу блудодійників, що були при Господньому домі, де жінки́ ткали завісу для Аста́рти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'І він ви́провадив усіх священиків з Юдиних міст, і опога́нив па́гірки, де священики кадили, від Ґеви аж до Беер-Шеви, і порозбивав па́гірки брам, що були при вході брами Ісуса, зверхника міста, що ліво́руч тому́, хто вхо́див до брами міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Але священики па́гірків не вхо́дили до Господнього же́ртівника в Єрусалимі, а тільки їли прісне́ серед своїх братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'І він опога́нив місце ста́влення на огні, що в долині Гінномового сина, щоб ніхто не перево́див через огонь сина свого та дочку́ свою для Молоха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'І він повідставляв коні, яких давали Юдині царі для сонця, від входу до Господнього дому, при кімна́ті є́внуха Нетан-Мелеха, що був у Парварімі, а колесни́ці сонця попали́в ув огні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'А же́ртівники, що були на даху́ Ахазової го́рниці, що пороби́ли Юдині царі, та жертівники, що пороби́в Манасія на двох подві́р\'ях Господнього дому, цар порозбива́в. І він звідти побіг, і кинув їхній по́рох до кедро́нського пото́ку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'А па́гірки, що навпроти Єрусалиму, право́руч гори Згуби, які побудува́в був Соломон, Ізраїлів цар, для Астарти, гидо́ти сидо́нської, і для Кемота, гидо́ти моавської, і для Мілкома, гидо́ти Аммонових синів, цар поопога́нював.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'І він порозбивав стовпи для богів, і постинав посвя́чені дере́ва, а їхнє місце напо́внив лю́дськими кістка́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'А також жертівника, що в Бет-Елі, па́гірка, що зробив був Єровоам, син Неватів, що ввів у гріх Ізраїля, також же́ртівника цього та цього па́гірка він розбив, і спалив того па́гірка та стер на по́рох, і Аста́рту спалив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'І оберну́вся Йосі́я, та й побачив гроби́, що були там на горі. І послав він, і позабирав кості з гробі́в, і попали́в на жертівнику, — і опога́нив його, за словом Господнім, яке кли́кав був Божий чоловік, що проріка́в оці речі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'І сказав цар: „Що́ це за надгро́бок, що я бачу?“А люди того міста сказали йому: „Це надгро́бок Божого чоловіка, що прийшов з Юдеї й прорік оці речі, які зробив ти на же́ртівнику в Бет-Елі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'А він сказав: „Дайте йому спо́кій, — нехай ніхто не рухає косте́й його“. І зберегли його кості, кості того пророка, що прийшов був із Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'А також усі доми́ па́гірків, що по самарійських містах, що поробили були Ізраїлеві царі, щоб гніви́ти Господа, Йосія понищив, і зробив з ними те саме, що зробив у Бет-Елі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'І порізав він усіх священиків па́гірків, що були там, на жертівниках, і попалив на них лю́дські кості, та й вернувся до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'І наказав цар усьому наро́дові, говорячи: „Справте Пасху для Господа, вашого Бога, як написано в оцій Книзі Заповіту“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Бо не справля́лася ця Пасха від днів суддів, що судили Ізраїля, по всі дні царів Ізраїлевих та царів Юдиних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'І тільки вісімнадцятого року царя Йосії справлялася Пасха для Господа в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'А також викликачів духів померлих, і духів віщих, і домови́х божків, і бовва́нів, і всякі гидо́ти, що появилися в Юдинім кра́ї та в Єрусалимі, повини́щував Йосія, щоб поставити слова Зако́ну, написані в книзі, що знайшов священик Хілкійя в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'А такого царя, як він, не було перед ним, що наверну́вся б до Господа всім своїм серцем, і всією душею своєю, і всією силою своєю, за всім Мойсеєвим Зако́ном, і по ньому не повставав такий, як він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Тільки не спинився Господь від ре́вности Свого великого гніву, яким запалився Його гнів на Юду за всі огі́рчення, якими гніви́в Його Манасія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'І сказав Господь: „Також Юду відкину Я від лиця Свого, як відкинув Я Ізраїля, і відкину це місто, яке вибрав, Єрусалим, та цей храм, про який Я сказав: Ім\'я́ Моє буде там!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'А решта діл Йосії та все, що́ він робив, — ото вони написані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'За його днів пішов фараон Нехо́, єгипетський цар, на асирійського царя, на річку Єфра́т. І вийшов цар Йосія навпроти нього, та той убив його в Меґіддо, коли він побачив його...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'І його раби пове́зли його мертвого з Меґіддо, і приве́зли його до Єрусалиму, і поховали його в гробівці́ його́. А народ кра́ю взяв Єгоахаза, сина Йосії, і пома́зали його, та й настанови́ли його царем замість його батька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Єгоахаз був віку двадцяти й трьох літ, коли він зацарював, і царював в Єрусалимі три місяці. А ім\'я́ його матері — Хамуталь, дочка́ Єремі́ї, з Лівни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'І робив він зло в Господніх оча́х, усе так, як робили його батьки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'І фараон Нехо́ зв\'язав його в Рівлі, в гаматському кра́ї, щоб він не царював в Єрусалимі, і наклав ка́ру на цей край, — сто талантів срібла та талант золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'А царем настанови́в фараон Нехо Ел\'якима, сина Йосії, замість батька його Йосії, і змінив ім\'я́ його на Єгояким. А Єгоахаза він узяв, і той прибув до Єгипту та й помер там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'І Єгояким давав фараонові срібла та золота; тільки розклав це на край, щоб давати те срібло на фараонів наказ, — він стягав те срібло та золото з наро́ду кра́ю за оцінкою землі кожного, щоб віддати фараонові Нехо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Єгояки́м був віку двадцяти й п\'яти літ, коли він зацарював, і одинадцять років царював в Єрусалимі. А ім\'я́ його матері — Зевуда, дочка Педаї, з Руми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'І робив він зло в Господніх оча́х, усе так, як робили батьки́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'За його днів прийшов Навуходоно́сор, цар вавилонський, а Єгояки́м був йому три роки невільником, та пото́му збунтувався на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'А Господь послав на нього о́рди халде́їв, і о́рди сирійські, і о́рди моавські, та о́рди синів Аммона. І він послав їх на Юду, щоб ви́губити їх за словом Господа, що Він говорив через рабів Своїх пророків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Тільки на нака́з Господа сталося це на Юду, щоб відкинути його від лиця Його за гріхи Манасії, за все, що́ він робив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'а також за непови́нну кров, яку він пролив, і напо́внив Єрусалим непови́нною кров\'ю; і не хотів Господь простити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'А решта Єгояки́мових діл, та все, що́ він робив, — ото вони описані в Книзі Хроніки Юдиних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'І спочив Єгояким зо своїми батьками, а замість нього зацарював син його Єгояхі́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'І більше вже не вихо́див єгипетський цар зо свого кра́ю, бо вавилонський цар забрав усе від Єгипетського потоку аж до річки Ефра́ту, усе, що належало єгипетському цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Єгояхін був віку вісімнадцяти літ, коли він зацарював, і царював в Єрусалимі три місяці. А ім\'я́ його матері — Нехушта, дочка́ Елнатана, з Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'І робив він зло в Господніх оча́х, усе так, як робив його батько.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Того ча́су прийшли до Єрусалиму раби Навуходоно́сора, царя вавилонського, і місто попало в обло́гу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'І прийшов Навуходоно́сор, вавилонський цар, на місто, а його раби обляга́ли його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'І вийшов Єгояхін, цар Юдин, до вавилонського царя, він та мати його, і слуги його, і князі́ його, і є́внухи його, — і вавилонський цар узяв його восьмого року свого царюва́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'І позабирав він звідти всі скарби́ Господнього дому та скарби́ дому царе́вого, і повідру́бував всі золоті речі, які поробив був Соломо́н, цар Ізраїлів, у Господньому храмі, як говорив Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'І повиво́див він увесь Єрусалим, і всіх князі́в, і всіх ли́царів військо́вих, — десять тисяч пішло до неволі, — і всіх те́слів та ковалі́в. Не позоставив нікого, окрім нужде́нного народу Краю...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'І він вивів до Вавилону Єгояхіна та царе́ву матір, і царськи́х жіно́к, і його є́внухів, і видатних у кра́ї, — усіх ви́провадив у неволю з Єрусалиму до Вавило́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'І всіх військо́вих, сім тисяч, і теслів та ковалів тисячу, усіх ли́царів, що займалися війною, — вивів їх вавилонський цар у неволю до Вавилону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'А царем настанови́в вавилонський цар Маттанію, дядька Єгояхіна, замість нього, і переміни́в ім\'я́ його на Седекі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Седекі́я був віку двадцяти й одно́го року, коли він зацарював, і він царював в Єрусалимі одинадцять років. А ім\'я́ його матері — Хамуталь, дочка́ Єремії з Лівни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'І робив він зло в Господніх очах, усе так, як робив був Єгояким.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Бо за Господній гнів сталося це на Єрусалим та на Юду, і Він відкинув їх від Свого лиця. І Седекія збунтувався проти вавилонського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'І сталося дев\'ятого року його царюва́ння, десятого місяця, десятого дня місяця, прийшов Навуходоно́сор, цар вавилонський, він та все ві́йсько його, на Єрусалим, і розта́борився проти нього, і побудува́ли проти нього вала навко́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'І було́ місто в обло́зі аж до одинадцятого року царя Седекії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Дев\'ятого дня місяця настав сильний голод у місті, і не було хліба для народу кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'І пробитий був пролі́м у му́рі міста, і всі вояки́ повтікали вночі дорогою брами між двома му́рами, що при царсько́му садку́, бо халдеї були при місті навколо. А цар утік дорогою в степ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'А халдейське ві́йсько погналося за царем, та й догнали його в єрихо́нських степа́х, а все його ві́йсько розпоро́шилося від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'І схопи́ли царя, і відвели́ його до вавилонського царя до Рівли, і там його той засудив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'А синів Седекії зарізали на його оча́х, а очі Седекії він вибрав, і скував його двома́ мідяни́ми кайданами, та й відвів його до Вавило́ну...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'А п\'ятого місяця, сьомого дня місяця, — це дев\'ятнадцятий рік царя Навуходоно́сора, вавилонського царя, — прийшов до Єрусалиму Невузар\'адан, начальник царсько́ї сторожі, слуга вавилонського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'І він спалив дім Господній та дім царе́вий, і всі доми́ в Єрусалимі, і кожен великий дім спалив огнем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'І мури навколо Єрусалиму порозбива́ло все халдейське ві́йсько, що було з начальником царсько́ї сторожі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'А решту народу, що позостався в місті, і тих, що перебігли до вавилонського царя, і решту про́стого люду повиганяв Невузар\'адан, начальник царсько́ї сторожі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'А з бідноти́ Кра́ю начальник царсько́ї сторо́жі позоставив декого за винярі́в та за рільникі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'А мідяні́ стовпи́, що в Господньому домі, і підста́ви, і мідяне море, що в Господньому домі, халдеї поламали, і відне́сли їхню мідь до Вави лону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'І го́рнята, і лопа́тки, і ножі, і ложки, і ввесь мідяний по́суд, що вживається при службі, позабира́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'І кади́льниці, і ча́ші, усе, що було золоте — забрав золото, а що було́ срібне — срібло взяв начальник царсько́ї сторожі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Два стовпи́, одне море та ті підстави, що Соломон поробив був для Господнього дому, — не було й ваги для всіх цих рече́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Вісімнадцять ліктів високість одного стовпа й одна мідяна ма́ковиця, а високість ма́ковиці — три лікті, та мере́жка, і грана́тові яблука на ма́ковиці навколо, усе мідь. І для другого стовпа́ з мере́жкою — так само.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'І начальник царсько́ї сторожі взяв Сераю, первосвященика, і Цефанію, другого священика, та трьох сторожів поро́га.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'А з міста взяв він одного є́внуха, що був начальником над військо́вими, та п\'ять чоловіка з тих, що бачать цареве обличчя, що були зна́йдені в місті, і писаря, зверхника військо́вих відділів, що записував народ краю до військо́вих відділів, і шістдеся́т чоловіка з народу кра́ю, що знахо́дилися в місті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'І позабирав їх Невузар\'адан, начальник царсько́ї сторожі, і відвів їх до вавилонсього царя, до Рівли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'І вдарив їх вавилонський цар, і повбивав їх у Рівлі, у гаматовому кра́ї. І пішов Юда на вигна́ння з своєї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'А народ, що позостався в Юдиному кра́ї, якого позоставив Навуходоно́сор, вавилонський цар, то настанови́в над ним Ґедалію, сина Ахікама, Шафанового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'І почули всі військо́ві зверхники, вони та люди, що вавилонський цар настанови́в Ґедалію, то поприхо́дили до Ґедалії до Міцпи і Ізмаїл, син Нетаніїн, і Йоханан, син Кареахів, і Серая, син нетофатянина Танхумета, і Яазанія, син маахатянина, вони та їхні люди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'І присягну́в Ґедалія їм та їхнім лю́дям, і сказав їм: „Не бійтеся бути підда́ними халдейцям, осядьте в Кра́ї та служіть вавилонському цареві, — і буде вам добре!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'І сталося сьомого місяця, прийшов Ізмаїл, син Нетанії, Елішамового сина, з царсько́го насіння, та десять мужів із ним, і вдарили вони Ґедалію, — і він помер, і юдеїв, і халдеїв, що були з ними в Міцпі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'І знявся ввесь наро́д, від мало́го й аж до великого, та зверхники військ, і пішов до Єгипту, бо боявся халдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'І сталося тридцятого й сьомого року неволі Єгояхіна, Юдиного царя, дванадцятого місяця, двадцять сьомого дня місяця, Евіл-Меродах, цар вавилонський, у році свого запарюва́ння, змилувався над Єгояхіном, Юдиним царем, і вивів його з дому ув\'я́знення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'І він говорив із ним ласка́во, і поставив тро́на його понад трона царів, що були з ним у Вавилоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'І змінив в\'язни́чну одежу його, і він за́вжди їв хліб перед ним по всі дні свого життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'А ї́жа його, їжа стала, видавалася йому від царя, щоденне щоденно, по всі дні його життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Адам, Сиф, Енош,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Кенан, Магалал\'їл, Яред,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Енох, Метушелах, Ламех,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Ной, Сим, Хам та Яфет.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Сини Яфетові: Ґомер, і Маґоґ, і Мадай, і Яван, і Тувал, і Мешех, і Тірас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'А сини Ґомерові: Ашкеназ і Діфат, і Тоґарма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'А сини Яванові: Еліша й Таршіша, кіттяни й роданяни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Сини Хамові: Куш і Міцра́їм, Пут і Ханаан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'А сини Кушеві: Шева, і Хавіла, і Савта, і Раама, і Савтеха. А сини Рамині: Шева й Дедан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'А Куш породи́в Німрода, — він зачав бути ве́летом на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'А Міцраїм породив лудян, і анам\'ян, і легав\'ян, і нафтух\'ян,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'і патрусян, і каслух\'ян, що вийшли звідти филисти́мляни, і кафторян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'А Ханаан породив Сидона, свого первородженого, і Хета,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'і євусеянина, і амореянина, і ґірґашеянина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'і хіввеянина, і аркеянина, і сінеянина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'і арвадянина, і цемарянина, і хаматянина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Сини Симові: Елам, і Ашшу́р, і Арпахшад, і Луд, і Ара́м. Сини Арамові: і Уц, і Хул, і Ґетер, і Мешех.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'А Арпахшад породив Шалаха, а Шалах породив Евера.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'А Еверові народилося двоє синів, — ім\'я́ одно́му Пелеґ, бо за його днів була поділена земля, а ім\'я́ брата його — Йоктан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'А Йоктан породи́в Алмодада, і Шелефа, і Хацармавета, і Єраха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'і Гадорама, і Узала, і Діклу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'і Евала, і Авімаїла, і Шеву,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'і Офіра, і Хавілу, і Йовава, — усі вони сини Йоктанові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Сим, Арпахшад, Шелах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Пелеґ, Реу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Серуґ, Нахор, Терах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Аврам, він же Авраа́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Сини Авраамові: Ісак та Ізмаї́л.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Оце їхні наща́дки: первороджений Ізмаї́лів Невайот, і Кедар, і Адбеїл, і Мівсам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Мішма, і Дума, Масса, Хадад, і Тема,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Єтур, Нафіш, і Кедема, — оце вони сини Ізмаї́лові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'А сини Кетури, Авраамової наложниці: вона породила Зімрана, і Йокшана, і Медана, і Мідіяна, і Їшбака, і Шуаха. А Йокшанові сини: Шева й Дедан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'А Мідіянові сини: Ефа, і Ефер, і Ханох, і Авіда, і Елдаа, — ці всі сини Кетури.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'А Авраа́м породив Ісака. Ісакові сини: Ісав і Ізра́їль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Ісавові сини: Еліфаз, Реуїл, і Єуш, і Йалам, і Кора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Сини Еліфазові: Теман і Омар, Цефі й Ґатам, Кеназ і Тімна, і Амалик.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Сини Реуїлові: Нахат, Зерах, Шамма й Мізза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'А сини Сеїрові: Лотан, і Шовал, і Ців\'он, і Ана, і Дішон, і Ецер, і Дішан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'А сини Лотанові: Хорі, і Гомам, і Ахот, Лотан, Тімна.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Сини Шовалові: Ал\'ян, і Манахат, і Евал, Шефі, і Онам. А сини Ців\'онові: Айя й Ана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'А сини Анині: Дішон. А сини Дішонові: Хамран, і Ешбан, і Їтран, і Керан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Сини Ецерові: Білган, і Зааван, Яакан. Сини Дішонові: Уц та Аран.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'А оце царі, що царювали в Едо́мовому кра́ї перед зацарюванням царя в Ізраїлевих синів: Бела, Беорів син, а ім\'я́ його міста — Дінгава.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'І помер Бела, а замість нього зацарював Йовав, Зерахів син з Боцри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'І помер Йовав, а замість нього зацарював Хушам із кра́ю теманянина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'І помер Хушам, а замість нього зацарював Гадад, Бедадів син, що побив був Мідіяна на Моавському полі, а ім\'я́ місту його Авіт.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'І помер Гадад, а замість нього зацарював Самла з Масреки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'І помер Самла, а замість нього зацарював Саул з Рехевот-Ганнагару.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'І помер Саул, а замість нього зацарював Баал-Ханан, син Ахборів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'І помер Баал-Ханан, а замість нього зацарював Гадад, а ім\'я́ його міста — Раї, а ім\'я́ жінки його — Мегетав\'їл, дочка Матреда, дочки́ Ме-Загавової.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'І помер Гадад. І були потому провідники́ Едому: провідни́к Тімна, провідник Ал\'я, провідник Єтет,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'провідник Оголівама, провідник Ела, провідник Пінон,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'провідник Кеназ, провідник Теман, провідник Мівцар,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'провідни́к Маґдіїл, провідник Ірам, — оце провідники́ Едому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Оце Ізраїлеві сини: Руви́м, Симео́н, Леві́й, і Юда, Іссаха́р, і Завуло́н,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Дан, Йо́сип, Веніями́н, Нефтали́м, Ґад і Аси́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Юдині сини: Ер, і Онан, і Шела, — троє народилися йому від ханаане́янки Бат-Шуї. І був Ер, Юдин перворо́джений, нечестивий в оча́х Господа, — і Він забив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'А Тамар, невістка його, породила йому Пе́реца та Зе́ваха, — усіх Юдиних синів п\'я́теро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Сини Перецові: Хецрон та Хамул.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'А сини Зерахові: Зімрі, і Етан, і Геман, і Калкол, і Дера, — усіх їх п\'я́теро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'А Кармієві сини: Ахар, що напровадив біду на Ізраїля, що спроневі́рився в заклятті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'А сини Етанові: Азарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'А сини Хецронові, що народилися йому: Єрахмеїл, і Рам, і Келувай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'А Рам породи́в Аммінадава, а Аммінадав породив Нахшона, начальника синів Юдиних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'А Нахшон породив Салму, а Салма породив Боаза,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'а Боаз породив Оведа, а Овед породив Єссе́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'А Єссе́й породив свого перворо́дженого Еліава, і Авінадава другого, і Шім\'у третього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Натаніїла четвертого, Раддая п\'ятого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Оцема шостого, Давида сьомого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'А їхні сестри: Церуя й Авідаїл. А Церуїні сини: Авшай, і Йоав, і Аса-Ел, — усіх троє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'А Авігаїл породила Амасу, а батько Амасин — їшмеелянин Єтер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'А Калев, Хецронів син, породив зо своєю жінкою Азувою та з Еріот дітей. А оце сини її: Єшер, і Шовав, і Ардон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'І померла Азува, а Калев узяв собі Ефрату, і вона породила йому Хура.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'А Хур породив Урі, а Урі породив Бецаліїла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'А потому прийшов Хецрон до дочки́ Махіра, Ґілеадового батька, і він узяв її, — а він був віку шостидесяти років, — і вона породила йому Сеґува.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'А Сеґув породив Яіра, і він мав двадцять і три місті в ґілеадському кра́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Але Ґешур та Арам забрали від них Яірові оселі, Кенат та залежні від нього міста, шістдеся́т міст. Усе це сини Махіра, Ґілеадового батька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'А по Хецроновій смерті прийшов Калев до Єфрати, і Хецронова жінка Авійя породила йому Ашхура, батька Текої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'А сини Єрахмеїла, Хецронового перворо́дженого, були́: перворо́джений Рам, і Буна, і Орен, і Оцем, Ахійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'І була́ в Єрахмеїла інша жінка, а ім\'я́ їй Атара, — вона мати Онама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'А сини Рама, Єрахмеїлового перворо́дженого, були: Маац, і Ямін, і Екер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'А сини Онамові були́: Шаммай, і Яда. А сини Шаммая: Надав та Авішур.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'А ім\'я́ Авішуровій жінці — Авіхаїл, і вона породила йому Ахбана та Моліда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'А сини Надавові: Селед та Аппаїм, а Селед помер без дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'А сини Аппаїмові: Їш\'ї, А сини Їш\'ї: Шешан. А сини Шешанові: Ахлай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'А сини Яди, Шаммаєвого брата: Єтер і Йонатан. І помер Єтер без дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'А Йонатанові сини: Пелет, і Заза, — оце були сини Єрахмеїлові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'А в Шешана не було синів, а тільки до́чки. Був у Шешана раб єги́птянин, а ім\'я́ йому Ярха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'І дав Шешан рабові своєму Ярсі свою дочку́ за жінку, і вона породила йому Аттая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'А Аттай породив Натана, а Натан породив Завада,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'А Завад породив Ефлала, а Ефлал породив Оведа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'А Овед породив Єгу, а Єгу породив Азарію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'а Азарія породив Хелеца, а Хелец породив Ел\'асу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'А Ел\'аса породив Сісмая, а Сісмай породив Шаллума.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'А Шаллум породив Єкамію, а Єкамія породив Елішаму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'А сини Калева, Єрахмеїлового брата: Меша, його перворо́джений, він ба́тько Зіфа. І сини Мареші, Хевронового батька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'А Хевронові сини: Корах, і Таппуах, і Рекем, і Шама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'А Шама породив Рахама, Єракеамового батька, а Рекем породив Шаммая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'А сини Шаммаєві: Маон, а Маон був основник Бет-Цуру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'А Ефа, нало́жниця Калева, породила Харана, і Моцу, і Ґазеза. А Харан породив Ґазеза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'А сини Єгдаєві: Реґем, і Йотам, і Ґешан, і Фелет, і Ефа, і Шааф.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Калевова нало́жниця Мааха породила Шевера та Тірхату.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'І породила вона Шаафа, батька Мадманни, Шеву, батька Махбени, та батька Ґів\'и. А дочка Калевова — Ахса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Оце були сини Калева, сина Гура, первородженого Ефрати: Шовал, ба́тько Кір\'ят-Єаріму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Салма, батько Вифлеєма, Гареф, ба́тько Бе-Ґадеру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'У Шовала, батька Кір\'ят-Єаріму, були сини: Гарое, Хаці-Гамменухот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'А ро́ди Кір\'ят-Єаріма: їтряни, путяни, шуматяни, мішраяни, — від них пішли цор\'атяни та ештауляни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Сини Салмині: Бет-Лехем, і нетофаляни, Атрот, Бет-Иоав, і хаці-гаммонахтяни, цоряни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'А роди писарів, ме́шканців Ябецу, тір\'атяни, шім\'атяни, сухатяни, — вони кіняни, що похо́дять від Хамата, батька Бет-Рехавового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'А оце були́ Дави́дові сини, що народилися йому в Хевро́ні: перворо́джений — Амно́н, від їзреелі́тянки Ахіноам; другий — Даниїл, від кармелі́тянки Авіґаїл;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'третій — Авесало́м, син Маахи, дочки́ Талмая, царя ґешурського; четвертий — Адонійя, син Хаґґіт;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'п\'ятий — Шефатія, від Авітал; шостий — Їтреам, від жінки його Еґли;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'шестеро наро́джено йому в Хевроні. І царював він там сім років і шість місяців, а тридцять і три роки царював в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'А оці народи́лися йому в Єрусалимі: Шім\'а, і Шовав, і Натан, і Соломон, — четверо від Вірсаві́ї, Амміїлової дочки́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'і Ївхар, і Елішама, і Еліфалет,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'і Ноґаг, і Нефеґ, і Яфія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'і Елішама, і Еліяда, і Еліфелет, — де́в\'ятеро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Усе це Давидові сини́, окрім синів нало́жниць та сестри́ їх Тамари.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'А син Соломонів — Рехав\'ам, його син Авійя, його син — Аса, його син — Йосафат,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'його син — Йорам, його син — Ахазія, його син — Йоаш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'його син — Амація, його син — Азарія, його син — Йотам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'його син — Ахаз, його син — Хізкійя, його син Манасія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'його син — Амон, його син — Йосія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'А сини Йосії: перворо́джений — Йоханан, другий — Єгояким, третій — Седекія, четвертий — Шаллум.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'А сини Єгоякимові: Єхонія — син його, та син його Седекія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'А сини Єхонії: Ассір, Шеал\'тіїл, син його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'і Малкірам, і Педая, і Шен\'аццар, Єкам\'я, Гошама, і Недав\'я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'А сини Педаї: Зоровавель і Шім\'ї. А сини Зоровавеля: Мешуллам, і Хананія, і сестра їхня Шеломіт,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'і Хашува, і Огел, і Верех\'я, і Хасад\'я, Юшав-Хесед, п\'я́теро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'А син и Хананії: Пелатія та Єшая, сини Рефаї, сини Арнонові, сини Овадії, сини Шеханії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'А сини́ Шеханії: Шемая. А сини́ Шемаї: Хаттиш, і Їґ\'ал, і Баріах, і Неарія, і Шафат, — ше́стеро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'А син и Неарії: Ел\'йоенай, і Хізкійя, і Азрікам, — троє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'А сини Ел\'йоенаєві: Годав\'я, і Ел\'яшів, і Пелая, і Аккув, і Йоханан, і Делая, і Анані, — се́меро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Сини Юдині: Перец, Хецрон, і Кармі, і Хур, і Шовал.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'А Реая, син Шовалів, породив Яхата, а Яхат породив Ахуман та Лахада, — оце ро́ди цор\'атян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'А оці Аві-Етамові: Їзреел, і Їшма, і Їдбаш, а ім\'я́ їхній сестрі — Гаццелелпоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'А Пенуїл — батько Ґедора, а Езер — батько Хуші. Оце сини Хура, Єфремового перворо́дженого, батька Віфлеєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'А в Ашхура, батька Текої, були́ дві жінки: Хел\'а та Наара.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'І породила йому Наара Ахуззама, і Хефера, і Темені, і Ахаштарі, — оце сини́ Наарині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'А сини Хел\'ині: Церет, і Цохар, і Етнан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'А Коц породив Анува, і Гаццовеву, і роди Ахархела, сина Гарумового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'А Ябец був поважа́ний більше від своїх братів, і мати його назвала йому́ ім\'я́ Ябец, говорячи: Я породила його в болісті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'І кликнув Ябец до Бога Ізраїлевого, говорячи: „Коли б Ти, благословляючи, поблагословив мене, і побільши́в границю мою, і рука Твоя була зо мною, і зробив охорону від ли́ха, щоб не засмучувати мене!“І Бог послав, чого він просив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'А Келув, брат Шухи, породив Мехіра, — він батько Ештона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'А Ештон породив Бет-Рафу, і Пасеаха, і Техінну, батька міста Нахаша. Це люди Рехи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'А сини Кеназа: Отніїл та Серая. А сини Отніїлові: Хатат.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'А Меонотай породив Офру, а Серая породив Яава, батька Ремісничої Долини, бо вони були ремісники́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'А сини Калева, Єфуннеєвого сина: Іру, Ела та Наам. А Елин син — Кеназ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'А сини Єгаллел\'їлові: Зіф і Зіфа, Тір\'я й Асар\'їл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'А сини Езри: Єтер, і Меред, і Ефер, і Ялон. А оце сини Біт\'ї, фараонової дочки́, що взяв Меред; і вона зачала́ й породила Мір\'яма, і Шаммая, і Їшбаха, батька Ештемої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'А жінка його юде́янка породила Єреда, батька Ґедору, і Хевера, батька Сохо, і Єкутіїла, батька Заноаха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'А сини жінки Годійї, сестри Нахама, батька ґарм\'янина Кеїли та маахатянина Ештемоа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'а сини Симеонові: Амнон, і Рінна, Бен-Ханан, і Тілон. А сини Їш\'ї: Зохет та Бен-Зохет.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Сини Шели, Юдиного сина: Ер, ба́тько Лехи, і Лада, батько Мареші, і ро́ди дому робітникі́в віссону, з дому Ашбеа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'І Йокін, і люди Козеви, і Йоаш, і Сараф, що володіли Моавом, і Яшуві-Лехем. Та це справи старода́вні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Вони були ганчарі́, і заме́шкували садки́ та горо́ди; вони жили там у царя для його роботи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Сини Симеонові: Немуїл, і Ямім, Ярів, Зерах, Саул,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'його син — Шаллум, його син — Мівсам, його син — Мішма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'А сини Мішми: Хаммуїл — син його, його син — Заккур, його син — Шім\'ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'А в Шім\'ї було шістнадцять синів та шість дочо́к, а брати його не мали багатьо́х синів, і не помно́жили ввесь свій рід так, як сини Юдині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'І осілися вони в Беер-Шеві, і в Моладі, і в Хацар-Шуалі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'і в Білзі, і в Ецемі, і в Толаді,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'і в Бетуїлі, і в Хормі, і в Ціклаґу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'і в Бет-Маркавоті, і в Хацар-Сусімі, і в Бет-Бір\'і, і в Шаараїмі, — оце їхні міста аж до запарюва́ння Давидового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'А їхні осади: Етам, і Аїн, Ріммон, і Тохен, і Ашан, — п\'я́теро міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'А всі їхні оса́ди, що навколо тих міст, аж до Баалу; це місця їх осе́лення та родоводи їх про них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'А Мешовав, і Ямлех, і Йоша, син Амаці́ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'і Йоїл, і Єгу, син Йошів\'ї, сина Сераї, сина Асіїлового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'і Елйоенай, і Яко́ва, і Шохая, і Асая, і Адіїл, і Єсіміїл, і Беная,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'і Зіза, син Шіф\'і, сина Аллона, сина Єдаї, сина Шімрі, сина Шемаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Це ті, що входять в імена́ князів у свої ро́ди, а дім своїх батьків сильно розмно́жили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'І пішли вони до Мево-Ґедору, аж до схі́днього боку долини, щоб пошукати пасови́ська для своїх ота́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'І знайшли вони пасови́сько сите та добре, а той край був просто́рий, і тихий та спокійний, бо від Хама похо́дили ті, що сиділи там колись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'І пішли ці, записані імена́ми за днів Єзекії, царя Юдиного, і розби́ли їхні намети там, і побили меінітів, що були зна́йдені там, що їх учинили закля́ттям аж до цього дня, й осілися замість них, бо там пасови́сько для їхньої дрібно́ї худоби.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'А з них, з Симеонових синів, пішли на го́ру Сеїр п\'ять сотень чоловіка, а Пелатія, і Неарія, і Рефая, і Уззіїл, сини Їш\'ї, були на чолі́ їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'І вони побили оста́нок урято́ваних Амали́ка, й осі́лися там аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'А сини Руви́ма, Ізраїлевого перворо́дженого, — бо він первороджений, та за збезче́щення ним ложа свого батька перворі́дство було дане синам Йо́сипа, сина Ізраїлевого, та вони не могли приписатися до перворі́дства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Бо Юда став найсильнішим серед братів своїх, і кня́зем, сильнішим від нього, а перворі́дство дісталося Йо́сипові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Сини Руви́ма, Ізраїлевого первородженого: Ханох і Паллу, Хецрон і Кармі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Йоїлові сини: Шемая — син його, його син Ґоґ, син його — Шім\'ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'син його Міха, син його — Реая, син його — Баал,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'син його Беера, якого вигнав Тіллеґат-Пілнеесер, цар асирійський. Він був начальником Руви́мівців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'А брати́ його, за його ро́дами, у приписувані за пото́мством їх, були: голова Єіїл, і Захарій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'і Бела, син Азаза, сина Шеми, Йоїлового сина, — він сидів в Ароері й аж по Нево та Баал-Меон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'А на схід він сидів аж до ви́ходу на пустиню від річки Ефра́т, бо їхні че́реди в ґілеадському краї стали числе́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'А за Саулових днів вони провадили війну з агарянами, і ті впали в їхні руки, а вони сиділи в їхніх наме́тах на всім просто́рі на схід від Ґілеаду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'А Ґадові сини сиділи навпроти них у баша́нському кра́ї аж до Салхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Йоїл — голова, а Шафам — другий, і Янай, і Шафат у Башані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'А їхні бра́ття за дома́ми своїх батьків: Михаїл, і Мешуллам, і Шева, і Йорай, і Якан, і Зія, і Евер, — се́меро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Оце сини Авіхаїла, сина Хурі, сина Яроаха, сина Ґілеада, сина Михаїла, сина Єшішая, сина Єхдо, сина Буза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ахі, син Авдіїла, сина Ґунієвого, голови́ дому батькі́в їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'І сиділи вони в Ґілеаді, в Башані та в залежних від нього містах, та в усіх пасови́ськах Шарону, на місцях виходу їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Усі вони були́ переписані в днях Йотама, Юдиного царя, та в днях Єровоама, царя Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Синів Рувима, і ґадян, і половини Манасіїного племени, людей військо́вих, що носять щита й меча та натягують лука, та ви́практикуваних у війні — було сорок і чотири тисячі і сім сотень і шістдеся́т, що вихо́дили з ві́йськом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'І прова́дили вони війну з агарянами, і з Ітуром, і з Нафішем, і з Нодавом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'І да́на була їм поміч на них, і ві́ддані були в їхню руку ті агаряни та всі, що з ними, бо вони кликали до Бога в бою́, і Він був убла́ганий, бо вони наді́ялися на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'І вони зайняли їхні че́реди: їхніх верблю́дів п\'ятдеся́т тисяч, і дрібно́ї худоби двісті й п\'ятдесят тисяч, і ослів дві тисячі, а лю́дських душ — сто тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Бо трупів попадало багато, бо від Бога була ця війна. І сиділи вони на своєму місці аж до неволі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'А сини половини Манасіїного племени сиділи в краю́ від Башану аж до Баал-Хермону й Сеніру та гори́ Гермо́ну. Вони розмно́жилися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'А оце го́лови домів їхніх батьків: і Ефер, і Їш\'ї, і Еліїл, і Азріїл, і Їрмея, і Годавія, і Яхдіїл, — мужі відважні, мужі славні, го́лови домів їхніх батькі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Та спроневі́рилися вони Богові своїх батьків, і блуди́ли за богами народів Кра́ю, яких Бог вигубив перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'І Бог Ізраїлів збудив духа Пула, царя асирійського, і духа Тілленат-Піл\'несера, царя асирійського, і він ви́селив їх, Рувимівців і Ґадівців та половину Манасіїного племени, і запровадив їх у Халах, і Хавор, і Хару, та до річки Ґозан, і вони там аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Левієві сини: Ґершон, Кегат і Мерарі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'А сини Кегатові: Амрам, Їцхар, Хеврон, і Уззіїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'А сини́ Амрамові: Ааро́н, і Мойсе́й, і Мірія́м. А сини Ааронові: Надав і Авігу, Елеазар і Ітамар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Елеазар породив Пінхаса, Пінхас породив Авішую,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'а Авішуя породив Буккі, а Буккі породив Уззі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'А Уззі породив Зерахію, а Зерахія породив Мерайота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Мерайот породив Амарію, а Амарія породив Ахітува.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'А Ахітув породив Садока, а Садок породив Ахімааца.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'А Ахімаац породив Азарію, а Азарія породив Йоханана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'А Йоханан породив Азарію, — це той, що був священиком у Господньому домі, якого вибудував Соломо́н в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'І Азарія породив Амарію, а Амарія породив Ахітува.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'А Ахітув породив Садока, а Садок породив Шаллума.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'А Шаллум породив Хілкійю, а Хілкійя породив Азарію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'А Азарія породив Сераю, а Серая породив Єгоцадака.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'А Єгоцадак пішов до неволі, коли Господь вивів Юду та Єрусалим через Навуходоно́сора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Сини Леві́єві: Ґершом, Кегат та Мерарі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'А оце йме́ння Ґершомових синів: Лівні та Шім\'ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'А сини Кегатові: Амрам, і Їцхар, і Хеврон, і Уззіїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Сини Мерарієві: Махлі та Муші. А оце Левієві ро́ди за їхніми батьками:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'у Ґершома: Лівні його син, син його Яхат, його син — Зімма,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'його син — Йоах, його син — Іддо, його син — Зерах, його син — Єатрай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Сини Кегатові: Аммінадав — син його, його син — Корах, син його — Ассір,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'син його — Елкана, син його — Ев\'ясаф, син його — Ассір,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'син його — Тахат, син його — Уріїл, син його Уззійя та Саул — син його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'А сини Елкани: Амасай та Ахімот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Елкана — його син, Цофай — син його, і Нахат — син його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Еліяв — син його, Єрохам — син його, Елкана — син його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'А Самуїлові сини: перворо́джений Йоїл, а другій Авійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Сини Мерарієві: Махлі, його син — Лівні, його син — Шім\'ї, його син Узза,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'син його — Шім\'а, син його — Хаґґійя, син його — Асая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'А оце ті, яких Давид поставив для співа́ння в Господньому домі, від часу ми́ру ковчега.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'І вони служили перед скинією, скинією заповіту, піснею, аж поки Соломон не збудував Господнього дому в Єрусалимі. І вони ставали, за уставом своїм, на свою службу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'А оце ті, що стояли, та їхні сини: співа́к Геман, син Йоїла, сина Самуїла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'сина Елкани, сина Єрохама, сина Еліїла, сина Тоаха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'сина Цуфа, сина Елкани, сина Махата, сина Амасая,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'сина Алкани, сина Йоїла, сина Азарії, сина Цефанії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'сина Тахата, сина Ассіра, сина Ев\'ясафа, сина Кораха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'сина Їцхара, сина Кегата, сина Леві, сина Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'А брат його Асаф, що стояв на правиці його: Асаф був сином Берехії, сина Шім\'ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'сина Михаїла, сина Баасеї, сина Малкійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'сина Етні, сина Зераха, сина Адаї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'сина Етана, сина Зіммі, сина Шім\'ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'сина Йахата, сина Ґершома, сина Леві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'А сини Мерарі, брати їхні на лівиці: Етам, син Кіші, сина Авді, сина Маллуха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'сина Хашав\'ї, сина Амації, сина Хілкійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'сина Амці, сина Бані, сина Шамері');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'сина Махті, сина Муші, сина Мерарі, сина Леві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'А брати їх Левити дані на всяку роботу скинії Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'А Ааро́н та сини його палили на жертівнику цілопа́лення та на кадильному жертівнику, і були на всяку роботу Святого Святих, та на очи́щення Ізраїля, згідно зо всім тим, що наказав був Мойсей, раб Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'А оце Ааро́нові сини: Елеазар — син його, його син — Пінхас, його син — Авішуя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'його син — Буккі, його син — Уззі, його син — Зерахія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'його син — Мерайот, його син — Амарія, його син — Ахітув,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'його син — Садо́к, його син — Ахімаац.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'А оце місце їхнього сидіння за їхніми оса́дами, в їхніх границях, синам Аароно́вим, з роду Кегатівців, бо для них був такий жеребо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'І дали́ їм Хевро́н в Юдиному кра́ї, та пасови́ська його навколо нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'А міське поле та осади його дали Калеву, синові Ефунне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'А Аароновим синам дали міста схо́вища: Хевро́н, і Лівну та її пасови́ська, і Яттір, і Ештемоа та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'і Хілен та пасови́ська його́, Девір та пасови́ська його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'і Ашон та пасови́ська його, і Бет-Шемеш та пасови́ська його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'А з племени Веніяминового: Ґеву та пасови́ська її, і Алемет та пасови́ська його, і Анатот та пасови́ська його, — усіх їхніх міст в їхніх родах — тринадцять міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'А Кегатовим синам, позоста́лим із роду племени, дано з половини племени, племени Манасіїного, жеребко́м десять міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'А Ґершомовим синам, за їхніми ро́дами, з племени Іссаха́рового, і з племени Аси́рового, і з племени Нефтали́мового, і з племени Манасі́їного в Баша́ні дано тринадцять міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Синам Мерарієвим за ро́дами їх із племени Руви́мового, і з племени Ґадового, і з племени Завуло́нового дано за жеребко́м дванадцять міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'І дали Ізраїлеві сини Левитам ті міста та їхні пасови́ська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Вони дали жеребко́м із племени Юдиних синів, і з племени Симеонових синів, і з племени Веніяминових синів ті міста, що їх вони назвали імена́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'А щодо тих, що з родів Кегатових синів, то міста границь їх були́ від Єфремового племени.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'І дали їм міста схо́вища: Сихе́м та пасови́ська його, в Єфремових горах, і Ґезер та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'і Йокмеам та пасови́ська його, і Бет-Хорон та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'і Айялон та пасови́ська його, і Ґат-Ріммон та пасови́ська його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'А з половини Манасіїного племени: Анер та пасови́ська його, і Біл\'ам та пасови́ська його, за ро́дами позосталих Кегатових синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Ґершомовим синам із роду половини Манасіїного племени: Ґолан у Башані та пасови́ська його, і Аштарот та пасови́ська його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'А з Іссаха́рового племени: Кедеш та пасови́ська його́, і Доврат та пасови́ська його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'і Рамот та пасови́ська його́, і Анем та пасови́ська його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'А з Аси́рового племени: Машал та пасови́ська його, і Авдон та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'і Хукок та пасови́ська його, і Рехов та пасови́ська його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'А з племени Нефтали́мового: Кедеш у Ґалілі та пасови́ська його, і Хаммон та пасови́ська його, і Кір\'ятаїм та пасови́ська його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'А позоста́лим Мерарієвим синам із Завулонового племени: Ріммон та пасови́ська його, Фавор та пасови́ська його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'А з другого боку Йорда́ну при Єрихо́ні, на схід від Йорда́ну, з Рувимового племени: Бецер на пустині та пасови́ська його, і Ягца та пасови́ська її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'і Кедемот та пасови́ська його, і Мефаат та пасови́ська його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'А з Ґадового племени: Рамот у Ґілеаді та пасови́ська його, і Маханаїм та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'і Хешбон та пасови́ська його, і Яазір та пасови́ська його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'А Іссаха́рові сини: Тола, і Пуа, Яшув і Шімрон, — четверо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'А Толині сини: Уззі, і Рефая, і Єріїл, і Яхмай, і Ївсам, і Самуїл, — го́лови їхніх ба́тьківських домі́в Толи, хоробрі вояки́ своїх ро́дів. Число їх за Давидових днів — двадцять і дві тисячі і шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'А сини Уззі: Їзрахія. А сини Їзрахії: Михаїл, і Овадія, і Йоїл, Їшшійя, — п\'я́теро, вони всі го́лови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'А в них, за їхніми наща́дками, за домом їхніх батькі́в, були бойові військо́ві вата́ги, тридцять і шість тисяч, бо вони мали багато жіно́к та синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'А їхніх братів по всіх Іссаха́рових ро́дах, хоробрих воякі́в, було вісімдеся́т і сім тисяч, — усі вони перепи́сані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Веніями́н: Бела, і Бекер, і Єдіяїл, — троє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'А сини Белині: Ецбон, і Уззі, і Уззіїл, і Єрімот, і Ірі, — п\'я́теро голі́в ба́тьківських домів, хоробрі вояки́. А в родово́дах їх — двадцять і дві тисячі тридцять і чотири.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'А сини Бехерові: Земіра, і Йоаш, і Еліезер, і Елйоенай, і Омрі, і Єремот, і Авійя, і Анатот, і Алемет, — усе це Бехерові сини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'А в родово́дах їх, за їхніми наща́дками, го́ловами дому їхніх батьків, хоробрих вояків, — двадцять тисяч і двісті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'А сини Єдіяїлові: Білган. А сини Білганові: Єуш, і Веніямин, і Егуд, і Кенаана, і Зетан, і Таршіш, і Ахішахар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Усіх цих Едіяїлових синів, за головами дому батьків, хоробрих вояків, було сімнадцять тисяч і двісті, що виходили з військо́вим відділом на війну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'І Шуппім, і Хуппім, сини Іра, Хушім — син Ахера.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Сини Нефталимові: Яхціїл, і Ґуні, і Єцер, і Шаллум, — сини Білги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Сини Манасіїні: Асріїл, якого породила його наложниця арамітка; вона породила й Махіра, Ґілеадового батька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'А Махір узяв жінку для Хуппіма та Шуппіма, а ім\'я́ його сестрі Мааха, а ім\'я́ другому — Целофхад. А в Целофхада були тільки до́чки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'І породила Мааха, Махірова жінка, сина, і назвала ім\'я́ йому Переш, а ім\'я́ братові його — Шареш. А його сини — Улам і Рекем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'А Уламові сини: Бедан. Оце сини Ґілеада, сина Махіра, сина Манасіїного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'А сестра його Молехет породила Ішгода, і Авіезера, і Махлу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'А сини Шеміди були: Ахіян, і Шехем, і Лікхі, і Аніям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'А сини Єфремові: Шутелах, і Веред, син його, і син його Тахат, і син його Ел\'ада, і син його Тахат,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'і син його Завад, і син його Шутелах, і Езер, і Ел\'ад. І повбивали їх люди Ґату, наро́джені в Краю́, бо вони зійшли були забрати їхні че́реди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'І був у жало́бі їх ба́тько Єфрем числе́нні дні, а брати його прихо́дили розважа́ти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'І ввійшов він до жінки своєї, і зачала́ вона, і породила сина, а він назвав ім\'я́ йому: Берія, бо зло було́ в домі його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'А дочка́ його — Шеера. І вона збудувала Бет-Хорон до́лішній і горі́шній та Уззен-Шееру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'І син його Рефах, і Решеф, і син його Телах, і син його Тахан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'син його Ладан, син його Аммігуд, син його Елішама,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'син його Нон, син його Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'А їхня посі́лість та місця їхнього осе́лення — Бет-Ел та нале́жні йому міста, а на схід — Нааран, а на захід — Ґезер та нале́жні йому міста, і Сихем та належні йому міста, аж до Айї та належних йому міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'А на руки Манасіїних синів: Бет-Шеан та нале́жні йому́ міста, Танах та належні йому міста, Меґіддо та належні йому міста, Дор та належні йому міста, — у них сиділи сини Йо́сипа, Ізраїлевого сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Сини Асирові: Їмна, і Їшва, і Їшві, і Берія, та сестра їх Серах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'А сини Беріїні: Хевер і Малкіїл, — він батько Бірзаіта.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'А Хевер породив Яфлета, і Шомера, і Хотама, і сестру́ їх Шую.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'А сини Яфлетові: Пасах, і Бімхал, і Ашват, — оце сини Яфлетові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'А сини Шемерові: Ахі і Рогаґґа, Яхебба та Арам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'А сини Гелема, його брата: Цофах, і Їмна, і Шелеш, і Амал.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Сини Цофахові: Суах, і Харнефер, і Шуал, і Бері, і Їмра,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Бецер, і Год, і Шамма, і Шілша, і Їтран, і Беера.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'А сини Єтерові: Єфунне, і Піспа, і Ара.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'А сини Улли: Арах, і Ханніїл, і Ріція.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Усе це Аси́рові сини, го́лови ба́тьківських домі́в, ви́брані ли́царі вояки́, го́лови начальників. А в родовідних книгах військо́вих записано, число їхніх людей було — двадцять і шість тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'А Веніямин породив перворо́дженого свого Белу, дру́гого — Ашбелу, і третього — Ахраха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'четвертого — Наху, і п\'ятого — Рафу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'А в Бели були сини: Аддар, і Ґера, і Авігуд,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'і Авішуя, і Нааман, і Ахоах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'і Ґера, і Шефуфан, і Хурам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'А оце сини́ Ехудові, — вони були го́лови дому батькі́в, ме́шканців Ґеви, та переселено їх до Манахату:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'і Нааман, і Ахійя, і Ґера, — він їх пересели́в, і породив Уззу та Ахіхуда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'А Шахараїм породив дітей на моавському полі по то́му, як він відіслав своїх жінок Хушім та Баару.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'І породив він від Ходеш, своєї жінки: Йовава, і Цівію, і Мешу, і Малкам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'і Єуц, і Сохію, і Мірму, — це сини його, го́лови ба́тьківських домів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'А від Хушім він породив Авітува та Елпаала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'А сини Елпаалові: Евер, і Міш\'ам, і Шемер, — він збудував Оно й Лод та належні йому міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'А Берія та Шема — вони го́лови дому батькі́в, ме́шканців Айялону; вони вигнали мешканців Ґату.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'А Ахйо, Шашак і Єремот,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'і Зевадія, і Арад, і Адер,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'і Михаїл, і Їшна, і Йоха — сини Берії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'А Зевадія, і Мешуллам, і Хізкі, і Хевер,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'і Їшмерай, і Їзлія, і Йовав, — сини Елпаалові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'А Яким, і Зіхрі, і Завді,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'і Еліенай, і Ціллетай, і Еліїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'і Адая, і Берая, і Шімрат, — сини Шімеієві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'А Їшпан, і Евер, і Еліїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'і Авдон, і Зіхрі, і Ханан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'і Хананія, і Елам, і Антотійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'і Їфдея, і Пенуїл, — сини Шашакові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'А Шамшерай, і Шехарія, і Аталія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'і Яарешія, і Елійя, і Зіхрі, — сини́ Єрохамові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Оце го́лови дому батькі́в за їхніми наща́дками, голови, що вони сиділи в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'А в Ґів\'оні сиділи: ба́тько Ґів\'ону, а ім\'я́ його жінці — Мааха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'і перворо́джений син його Авдон, і Цур, і Кіш, і Баал, і Надав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'і Ґедор, і Ахйо, і Зехер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'А Міклот породив Шім\'у. І вони теж сиділи в Єрусалимі, при брата́х своїх, зо своїми брата́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'А Нер породив Кіша. А Кіш породив Саула, а Сау́л породив Йоната́на, і Малкі-Шуя, і Авінадава, і Ешбаала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'А син Йонатанів — Мерів-Баал, а Мерів-Баал породив Міху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'А сини Міхи: Пітон, і Мелех, і Тареа, і Ахаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'А Ахаз породив Єгоадду, а Єгоадда породив Алемета, і Азмавета, і Зімрі; а Зімрі породив Моцу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'А Моца породив Бін\'ю, його син — Рафа, його син — Ел\'аса, його син — Ацел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'А в Ацела було ше́стеро синів, а оце їхні імена́: Азрікам, Бохеру, і Ізмаїл, і Шеар\'я, і Овадія, і Ханан, — усі вони сини Ацелові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'А сини Ешека, брата його: перворо́джений його Улам, другий — Єуш, третій — Еліфелет.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'А Уламові сини були мужі хоробрі вояки́, що натягували лука й що мали багато синів та онуків, — сотню й п\'ятдеся́т. Усі вони з Веніяминових синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'А ввесь Ізраїль був перепи́саний, й ось вони були запи́сані в книзі Ізраїлевих царів. А Юда був пересе́лений до Вавилону за своє спроневі́рення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'А перші ме́шканці, що сиділи в своїй посілості, по своїх містах, були: Ізраїль, священики, Левити та слуги храму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'А в Єрусалимі сиділи з Юдиних синів, і з Веніяминових синів, і з синів Єфремових та Манасіїних:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Утай, син Аммігуда, сина Омрі, сина Імрі, сина Бані, з синів Переца, Юдиного сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'А з шілонян: перворо́джений Асая та сини́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'А з синів Зерахових: Єуїл та брати їх, — шість сотень і дев\'ятдеся́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'А з синів Веніяминових: Саллу, син Мешуллама, сина Годавії, сина Сенуї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'і Ївнея, син Єрохамів; і Ела, син Уззі, сина Міхрі, і Мешуллам, син Шефатії, сина Реуїла, сина Ївнійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'і брати їхні за їхніми наща́дками, — дев\'ять сотень і п\'ятдеся́т і шість. Усі ці мужі — го́лови батькі́в, дому батьків своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'А із священиків: Єдая, і Єгоярів, і Яхін.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'А Азарія, син Хілкійї, сина Мешуллама, сина Садока, сина Мерайота, сина Ахітава, — управи́тель Божого дому;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'і Адая, син Єрохама, сина Нашхура, сина Малкійї; і Масай, син Адіїла, сина Яхзери, сина Мешуллама, сина Мешіллеміта, сина Іммера;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'і брати їх, го́лови дому своїх батьків — тисяча й сім сотень і шістдеся́т, дуже добрі мужі на працю в ділі Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'А з Левитів: Шемая, син Хассува, сина Азрікама, сина Хашав\'ї, з синів Мерарі;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'і Бакбаккар, Хереш, і Балал, і Маттанія, син Міхи, сина Зіхрі, сина Асафа;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'і Авадія, син Шемаї, сина Ґалала, сина Єдутуна; і Берехія, син Аси, сина Елкани, що сидів в осадах нетоф\'ян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'А придве́рні: Шаллум, і Аккув, і Талмон, і Ахіман, і брати їхні; Шаллум був голова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'І аж дотепе́р вони в царські́й брамі на схід, вони придве́рні табо́рів Левієвих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'А Шаллум, син Коре, сина Ев\'ясафа, сина Кораха, і брати його з дому його батька, корахівці, на праці служби, стерегли́ пороги скинії, а їхні батьки були над Господнім табо́ром, стерегли вхід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'І Пінхас, син Елеазарів, був над ними колись зве́рхником, і Господь був із ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Захарій, син Мешелемії, був придве́рний при вході скинії заповіту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Усіх їх, ви́браних на придве́рних при поро́гах, було двісті й дванадцять. Вони переписані по своїх оса́дах. Їх поставив Давид та прозорли́вець Самуїл за їх вірність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'І вони та їхні сини були при брамах Господнього дому, дому скинії, за ва́ртами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'На чотири боки були придве́рні: на схід, на за́хід, на пі́вніч, на пі́вдень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'А брати їхні були по се́лах, мусіли прихо́дити на сім день, від ча́су до ча́су, щоб бути з ними на службі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'бо в службі були чотири перші придве́рні, вони Левити; вони ж доглядали поме́шкань та скарбів Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'І вони всю ніч перебува́ли навколо Божого дому, бо на них був обов\'я́зок ва́рти, і вони щоранку відмикали двері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'І з них були дехто коло службо́вого по́суду, бо за числом його прино́сили, і за числом його вино́сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'І з них дехто були призначені до по́суду та до всяких святих речей: і над пшеничною мукою, і над вином, і над оливою, і над ладаном, і над па́хощами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'А з священичих синів були ті, що мішали запашне́ на кадило.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'А Маттітія з Левитів, — він перворо́джений корахівця Шаллума, — був у службі над справою сковорід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'А з синів кегатівців, з їхніх браті́в, були над хлібом показни́м, щоб приготовля́ти щосуботи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'А оце співаки́, го́лови ба́тьківських домів Левитів, по кімна́тах, були вільні від іншої праці, бо вдень та вночі були́ вони при своїй роботі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Оце го́лови ба́тьківських домів Левитів за їхніми наща́дками, го́лови, що сиділи в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'А в Ґів\'оні сиділи: ба́тько Ґів\'ону Єіїл, а ім\'я́ його жінці Мааха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'і перворо́джений син його Авдон, і Цур, і Кіш, і Баал, і Нер, і Надав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'і Ґедор, і Ахйо, і Захарій, і Міклот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'А Міклот породив Шім\'ама. І вони теж сиділи в Єрусалимі при брата́х своїх, зо своїми брата́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'А Нер породив Кіша, а Кіш породив Саула, а Саул породив і Йонатана, і Малкі-Шую, і Авінадава, і Ешбаала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'А син Йонатанів — Мерів-Баал, а Мерів-Баал породив Міху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'А сини Міхи: Пітон, і Мелех, і Тахрея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'А Ахаз породив Яру, а Яра, породив Алмета, і Азмавета, і Зімрі. А Зімрі породив Моцу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'А Моца породив Бін\'ю, його син — Рефая, його син — Ел\'аса, його син — Ацел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'А в Ацела було ше́стеро синів, а оце їхні імена: Азрікам, Бохеру, і Ізмаїл, і Шеар\'я, і Овадія, і Ханан, — оце сини Ацелові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'А филисти́мляни воювали з Ізраїлем. І побігли Ізраїлеві мужі перед филисти́млянами, і па́дали тру́пами на горі Ґілбоа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'І гналися филисти́мляни за Саулом та за його сина́ми. І повбивали филисти́мляни Йоната́на, і Авінадава, і Малкі-Шуя, Сау́лових синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'І став бій тяжки́й для Саула, і лу́чники ки́нулися на нього, — і він злякався тих лу́чників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'І сказав Саул до свого зброєно́ші: „Ви́тягни меча свого, і пробий мене ним, щоб не прийшли ці необрі́зані, і не знущалися на до мною!“Та не хотів зброєно́ша, бо дуже боявся. Тоді взяв Сау́л меча́ — та й упав на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'І побачив зброєно́ша, що помер Сау́л, і впав і він на меча, та й помер...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'І помер Саул і троє синів його, та ввесь його дім поме́рли ра́зом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'І побачили всі ізра́їльтяни, що мешкали в долині, що всі втікають, та що помер Саул та сини його, то поки́дали свої міста́ й повтікали, а филисти́мляни поприхо́дили, й осі́лися в них...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'І сталося другого дня, і прийшли филисти́мляни, щоб пообдира́ти тру́пи, — та й знайшли Саула та синів його, що лежали на горі Ґілбоа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'І вони пообдира́ли його, і поне́сли го́лову його та збро́ю його, і послали в филистимські краї навко́ло, щоб сповістити в домах своїх божкі́в та наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'І вони поклали збро́ю його в домі свого бога, а го́лову його прибили в домі Даґона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'І почув увесь ґілеадський Явеш про все, що́ филисти́мляни зробили Саулові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'і встали всі хоробрі, і поне́сли Саулове тіло та тіла́ синів його, і прине́сли до Явешу, та й похова́ли їхні ко́сті під дубом в Явеші, і по́стили сім день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'І помер Саул за своє беззако́ння, що він ним спроневі́рився проти Господа через Господнє слово, якого не тримався, а також через те, що питався віщого духа, щоб ви́відати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'а не виві́дував від Господа. І Він убив його, а царство його передав Дави́дові, Єссе́євому синові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'І зібрався ввесь Ізра́їль до Давида в Хевро́н, говорячи: „Оце ми кість твоя та тіло твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'І давніш, коли Саул був царем, ти водив та приво́див Ізраїля на війну. І сказав Господь, Бог твій, тобі: Ти бу́деш пасти́ наро́да Мого, Ізраїля, і ти будеш князе́м над наро́дом Моїм, Ізраїлем“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'І прийшли всі Ізраїлеві старші́ в Хевро́н, а Давид склав із ними умову в Хевроні перед Господнім лицем. І пома́зали вони Давида царем над Ізраїлем, за Господнім словом через Самуїла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'І пішов Давид та ввесь Ізра́їль до Єрусалиму, — він Євус, і там були євусе́яни, ме́шканці того кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'І сказали ме́шканці Євусу до Давида: „Ти не вві́йдеш сюди!“Та здобу́в Дави́д тверди́ню Сіо́н, — він Місто Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'І сказав Давид: „Кожен, хто найперше поб\'є євусе́янина, той стане за го́лову та за зве́рхника“. І ввійшов найперше Йоа́в, син Церуїн, і став за го́лову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'І осівся Дави́д у тверди́ні, тому́ назвав ім\'я їй: Дави́дове Мі́сто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'І він збудува́в місто навко́ло, від Мілло́ й аж навко́ло, а Йоав віднови́в решту міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'І Давид ставав усе більшим, а Госпо́дь Савао́т був із ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'А оце го́лови Давидових ли́царів, що хоробро труди́лися з ним у його царстві, з усім Ізраїлем, щоб настанови́ти його царем, за Господнім словом, над Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'А оце число Давидових ли́царів: Яшов\'ам, син Гахмоні, голова тридцяти, — він махнув своїм списо́м — і побив за один раз три сотні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'А за ним Елеазар, син Додо, ахох\'янин, — він один із трьох ли́царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Він був із Давидом у Пас-Дамімі, а филисти́мляни зібралися там на бій. І була там діля́нка поля, повна ячме́ню, а наро́д утікав перед филисти́млянами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Та вони стали посеред діля́нки, і врятували її та й побили филисти́млян. І Господь подав велику перемогу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'І зійшли троє з тих тридцяти на пе́реді на скелю до Давида, до печери Адуллам. А филистимський та́бір таборува́в у долині Рефаїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Давид же був тоді в тверди́ні, а филистимська зало́га була тоді в Віфлеємі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'І спра́гнув Давид та й сказав: „Хто напо́їть мене водою з віфлеємської крини́ці, що в брамі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'І проде́рлися ці троє до филистимського табо́ру, і зачерпну́ли води з віфлеємської криниці, що в брамі. І вони ви́несли й прине́сли до Давида, та Давид не схотів її пити, — і вилив її для Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'та й сказав: „Борони мене, Боже мій, чинити таке! Чи я буду пити кров цих мужів, що ходили, наражаючи життя своє? Бо життям своїм вони прине́сли її!“І не хотів він пити її. Оце зробили троє цих ли́царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'А Авшай, Йоавів брат, — він голова тих трьох. І він махнув своїм списо́м — і побив три сотні! І він мав найславніше ім\'я́ серед трьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'З тих трьох серед двох він був найшановні́ший, і став їм за провідника́. А до тих трьох не дося́г.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Беная, син Єгоядин, син хороброго мужа, великий у діла́х, з Кавцеїлу, — він побив двох синів Аріїла моавського. І він зійшов і забив лева в сере́дині ями сніжного дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'І він побив одно́го єги́птянина, мужа поставно́го, на п\'ять ліктів, а в руці єги́птянина був спис, як тка́цький вал. І зійшов він до нього з києм, і вирвав списа́ з руки того єги́птянина, — та й його забив його списо́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Оце зробив Беная, син Єгоядин, і його ім\'я́ було серед тих трьох хоробрих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'З тих тридцяти він був найповажні́ший, а до тих трьох не дося́г. І Давид призна́чив його до своєї прибі́чної сторо́жі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'А хоробрі му́жі були ці: Асаїл, Йоавів брат, Елханан, син Додо, із Віфлеєму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'гарор\'янин Шаммот, пелонянин Хелес,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Іра, син Іккешів, текоянин, антотянин Авіезер,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'хушатянин Сіббехай, ахох\'янин Ілай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'нетофатянин Магарай, Хелед, син Баанин, нетофатянин,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ітай, син Ріваїв, з Гів\'ї Веніяминової, пір\'атонянин Беная,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Хурай з Нахале-Ґаашу, арв\'янин Авіїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'бахарум\'янин Азмавет, шаалвонянин Ел\'яхба,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'сини ґізонянина Гашема, Йонатан, син Шаґе, гарар\'янин,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ахійям, син Сахарів, гарар\'янин, Еліфал, син Урів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'мехар\'янин Хефер, пелонянин Ахійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'кармелянин Хіцро, Наарай, син Езлаїв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Йоїл, брат Натанів, Мівхар, син Гаґрі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'аммонітянин Целек, беротянин Нахрай, зброєно́ша Йоава, Церуїного сина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'їтрянин Іра, їтрянин Ґарев,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'хіттеянин Урійя, Завад, син Ахлая,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Адіна, син Шізин, Руви́мівець, голова Рувимівців і над тридцятьма́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Ханан, син Маахин, і мітнянин Йосафат,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'аштерянин Уззійя, Шама, і Еуїл, сини ароерянина Хотама,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Єдіаїл, син Шімрі, і Йоха, його брат, тіцянин,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'махав\'янин Еліїл, і Єрівай, і Йошав\'я, сини Ел\'наамові, і моавітянин Їтма,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Етіїл, і Овед, і Яасіїл із Цови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'А це ті, що поприхо́дили до Давида в Ціклаґ, коли він ще ховався перед Саулом, сином Кішевим, і вони були серед ли́царів, що допомагали в війні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'що були озбро́єні лу́ком, що кидали правицею та лівицею камі́ння та стріли з лука, з Саулових братів, від Веніямина:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'голова Ахіезер та Йоаш, сини ґів\'янина Шемаї, і Єзіїл та Пелет, Азмаветові сини, і Бераха, і аннетотянин Єгу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'і ґів\'онянин Їшмая, ли́цар серед тридцятьох та старши́й над тридцятьма́, і Їрмея, і Яхазіїл, і Йоханан, і ґедерянин Йозавад,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Ел\'узай, і Єрімот, і Беал\'я, і Шемарія, і гаріф\'янин Шефатія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Елкана, і Їшшійя, і Азареїл, і Йоезер, і Яхов\'ам, хорх\'яни,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'і Йоїла та Зевадія, сини Єрохамові, з Ґедору.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'А з ґадян відділилися до Давида до твердині в пустиню лицарі вояки́, мужі відважні, на війні, озбро́єні великим щито́м та списо́м. А їхні обличчя — то обличчя ле́в\'ячі, а щодо швидкости — вони були, як са́рни на гора́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Голова — Езер, другий — Овадія, третій — Еліав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'четвертий — Мішманна, п\'ятий — Їрмея,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'шо́стий — Аттай, сьо́мий — Еліїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'во́сьмий — Йоханан, дев\'ятий — Елзавад,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'десятий — Єремія, одина́дцятий — Махбанай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Оці були з Ґадових синів, голови військо́вих відділів, мали́й — один на сотню, а великий — на тисячу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Це ті, що перейшли Йорда́н першого місяця, коли він був перепо́внений понад усі береги свої, і порозганя́ли всіх ме́шканців долин на схід та на за́хід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'І прийшли з синів Веніяминових та Юдиних аж до твердині до Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'А Давид вийшов перед них, і, відповіда́ючи, сказав їм: „Якщо ви прийшли до мене з миром, щоб допомагати мені, буде моє серце з вами за одне, а якщо зрадите мене супроти ворогів моїх, коли нема обмани в руках моїх, то побачить це Бог наших батьків, і покарає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'І зійшов Дух на Амасая, голову тридцяти, і він проказав: „Мир, Давиде, тобі, і з тобою, о сину Єссе́їв! Мир тобі, і мир то́му, хто тобі помагає, бо тобі помагає твій Бог!“І прийняв їх Давид, і поставив на чолі́ війська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'І з Манасії перебігли до Давида, коли він ішов із филисти́млянами проти Саула на війну, — а він не поміг їм, бо филистимські князі́, порадившись, відіслали його, говорячи: „За ціну наших голів він хоче перейти до свого пана Саула!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Коли він ішов до Ціклаґу, збігли до нього з Манасії: Аднах, і Йозавад, і Єдіаїл, і Михаїл, і Йозавад, і Елігу, і Ціллетай, — го́лови Манасіїних тисячок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'І вони допомагали Давидові проти юрби́, бо вони всі — хоробрі вояки́, і поставали провідника́ми військо́вих ві́дділів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Бо день-у-день прихо́дили вони до Давида помагати йому, аж став та́бір великий, як та́бір Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'А оце число головни́х озбро́єних військо́вих відділів, — вони прийшли до Давида в Хевро́н, щоб передати Саулове царство йому, за Господнім словом:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Юдиних синів, що носили великого щита́ та списа́, — шість тисяч і вісім сотень озбро́єного ві́йська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'З Симеонових синів хоробрих воякі́в військово́го відділу — сім тисяч і сто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'З Левієвих синів — чотири тисячі й шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'І Єгояда, проводи́р синів Ааронових, а з ним три тисячі й сім сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'І юна́к Садо́к, хоробрий воя́к, та дім його батька, — зверхників двадцять і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'А з Веніяминових синів, Саулових братів, — три тисячі, а більша частина їх аж дотепе́р трималися Саулового дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'А з Єфремових синів — двадцять тисяч і вісім сотень хоробрих воякі́в, мужів славних дому їхніх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'А з половини Манасіїного племени — вісімнадцять тисяч, що були́ докладно зазна́чені за і́менем, щоб прийти настанови́ти Давида царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'А з Іссаха́рових синів, що мали розумі́ння ча́су, щоб знати, що́ буде робити Ізра́їль, їх голів було двісті, а всі їхні брати́ робили за їхнім нака́зом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Із Завулона тих, що виходять на війну, що ставляться в бойово́му поря́дку зо всякими військо́вими речами, — п\'ятдесят тисяч, щоб допомагати з ці́лим серцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'А з Нефтали́му — тисяча зверхників, а при них зо щито́м та списо́м — тридцять і сім тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'А з Данян тих, що ставляться в бойово́му поря́дку — двадцять і вісім тисяч і шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'А з Аси́ра тих, що виходять на війну, щоб ставитися в бойові́м поря́дку, — сорок тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'А з того бо́ку Йорда́ну з Руви́мівців, і Ґа́дівців, і з полови́ни Манасі́ї, зо всякими військо́вими знаря́ддями для бою — сто й двадцять тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Усі ці люди — військо́ві, що ставилися в бойово́му поря́дку, ці́лим серцем поприхо́дили до Хевро́ну, щоб настанови́ти Давида царем над усім Ізра́їлем. Та й решта Ізраїля були односе́рді, щоб настанови́ти Давида царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'І були́ вони там із Давидом три дні, їли та пили, бо їхні брати́ нагото́вили їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'А також ті, що були близькі́ до них, аж до Іссаха́ра, і Завуло́на, і Нефтали́ма, спрова́джували хліб ослами, і верблю́дами, і му́лами, і худобою великою, їжу мучну́, спресо́вані фіґі, і родзи́нки, і вино, і оливу, і худобу велику, і худобу дрібну́, дуже багато, бо радість була в Ізраїлі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'І ра́дився Давид із тисячниками та з сотниками, зо всіма́ значни́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'І сказав Давид до всієї Ізраїлевої грома́ди: „Якщо вам це добре, а від Господа, Бога нашого вподо́бане, пошлі́мо до наших братів, позосталих по всіх Ізраїлевих края́х, а з ними до священиків та Левитів, по містах та по їхніх пасовиськах, і нехай зберу́ться до нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'І вернімо ковчега нашого Бога до нас, бо не зверта́лися ми до нього за Саулових днів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'І сказала вся громада, щоб зробити так, бо слу́шна була та річ в оча́х усього народу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'І зібрав Давид усього Ізраїля від єгипетського Шіхору й аж туди, де йде́ться до Хамату, щоб спрова́дити Божого ковчега з Кір\'ят-Єаріму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'І пішов Давид та ввесь Ізра́їль у Баалу, в Юдин Кір\'ят-Єарім, щоб ви́нести звідти ковчега Бога, Господа, що сидить на херувимах, що ім\'я́ Його приклика́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'І пове́зли Божого ковчега на ново́му возі з Авінадавового дому, а Узза та Ахйо прова́дили того воза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'А Давид та ввесь Ізраїль грали перед Божим лицем з усієї сили, — із пісня́ми, і на ци́трах, і на а́рфах, і на бу́бнах, і на цимба́лах, і на су́рмах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'І прийшли вони аж до Кідонового то́ку, і простяг Узза свою руку, щоб підхопи́ти ковчега, бо воли нахили́ли його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'І запалився на Уззу гнів Господній, і Він убив його за те, що простяг руку свою до ковчега. І помер він там перед Господнім лицем...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'І зажури́вся Давид тим, що Господь убив Уззу, і він назвав ім\'я тому місцю: Перец-Узза, і так воно зветься аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'І того дня Давид злякався Бога, говорячи: „Як я внесу́ до се́бе Божого ковчега?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'І не повіз Давид ковчега до се́бе, до Давидового Міста, а напра́вив його до дому гатянина Овед-Едома.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'І пробува́в Божий ковчег із домом Овед-Едома в його домі три місяці. А Господь поблагослови́в дім Овед-Едома, та все, що було його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'А Хіра́м, цар тирський, послав до Давида послів, і ке́дрового дерева, каменярі́в та теслярі́в, щоб збудувати йому дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'І пізнав Дави́д, що Госпо́дь міцно поставив його́ царем над Ізраїлем, бо царство його було підне́сене ви́соко ради народу його, Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'І взяв Давид іще жіно́к в Єрусалимі, — і Давид породив іще сині́в та дочо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'А оце імена́ наро́джених йому в Єрусалимі: Шаммуа і Шовав, Натан і Соломон,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'і Ївхар, і Елішуя, і Елпелет,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'і Ноґах, і Нефеґ, і Яфія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'і Елішама, і Ел\'яда, і Еліфелет.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'І почули филисти́мляни, що Давид був пома́заний на царя над усім Ізраїлем, — і підняли́ся всі филисти́мляни, щоб шукати Давида. А Давид почув про це, і вийшов проти них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'А филисти́мляни прийшли й стали табо́рами в долині Рефаїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'І питався Давид у Бога, говорячи: „Чи вихо́дити на филисти́млян, і чи даси Ти їх в руку мою?“І відказав йому Господь: „Вийди, — і Я дам їх у руку твою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'І зійшли́ вони до Баал-Пераціму, — і Давид побив їх там. І сказав Давид: „Розбив Бог ворогів моїх рукою моєю, як прори́в води!“Тому назвали ім\'я́ того місця: Баал-Перацім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'А вони позоста́вили там богів своїх, і Давид наказав, — і вони були спа́лені в огні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'А филисти́мляни ще ота́борилися в долині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'А Давид іще питався Бога, і Бог йому сказав: „Не пі́деш за ними, а поверни́ від них, і прибу́деш до них з-навпроти бальза́мового ліска́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'І станеться, як ти почуєш шелест ніби кроків на верхові́ттях бальза́мових дерев, тоді ви́йдеш на бій, бо то вийшов Бог перед тебе, щоб побити филисти́мський та́бір“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'І зробив Давид так, як наказав йому Бог, і вони побили филисти́мський та́бір від Ґів\'ону аж до Ґезеру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'І не́слося Дави́дове ім\'я́ по всіх края́х, а Госпо́дь дав, що всі наро́ди боялись його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'І пороби́в він собі доми́ в Давидовому Місті, і пригото́вив місце на Божого ковче́га, і розтягнув для нього ски́нію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Тоді Давид сказав, щоб ніхто не носив Божого ковчега, окрім Левитів, бо їх вибрав Господь носити ковчега Господа та служити Йому́ аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'І Давид зібрав усього Ізраїля до Єрусалиму, щоб ви́нести Господнього ковче́га на його місце, яке пригото́вив йому́ він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'І зібрав Давид Ааро́нових синів та Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Від Кегатових синів: зверхник Уріїл, а братів його — сотня й двадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Від синів Мерарі: зверхник Асая, а братів його — двісті й двадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Від Ґершомових синів: зверхник Йоїл, а братів його — сотня й тридцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Від Еліцафанових синів: зверхник Шемая, а братів його — двісті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Від Хевронових синів: зверхник Еліїл, а братів його — вісімдесят.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Від Уззіїлових синів: зверхник Аммінадав, а братів його — сотня й дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'І покликав Давид священиків Садо́ка та Евіятара, та Левитів: Уріїла, Асаю, і Йоїла, Шемаю і Еліїла, і Аммінадава');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'та й сказав до них: „Ви го́лови родів Левитів. Освяті́ться ви та ваші брати, і перенесе́те ковчега Господа, Бога Ізраїлевого, до місця, яке пригото́вив я йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Бо через те, що споча́тку не ви це робили, то вдарив нас Господь, Бог наш, бо ми не шукали Його так, як належало“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'І освятилися священики та Левити, щоб перене́сти ковчега Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'І поне́сли сини Левитів Божого ковчега, як наказав був Мойсей за Господнім словом, на пле́чах своїх, на держака́х, на собі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'І сказав Давид зверхникам Левитів, щоб поставили своїх братів співакі́в на прила́ддях пісні, на ци́трах, а́рфах, та тих, що грають на цимба́лах, щоб підне́сти голос на радість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'І поставили Левити Гемана, Йоїлового сина, а з братів його — Асафа, сина Берехії, а з сині́в Мерарі, їхніх братів — Етана, сина Кушаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'А з ними їхніх братів других: Захарія, і Яазіїла, і Шемірамота, і Єхіїла, і Унні, Еліава, і Бенаю, і Маасею, і Маттітію, і Еліфлея, і Мікнею, і Овед-Едома, і Єіїла, — придве́рних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'А співаків: Гемана, Асафа та Етана — грати на мідяни́х цимба́лах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'А Захарія, і Азіїла, і Шемірамота, і Єхіїла, і Унні, і Еліава, і Маасею, і Бенаю — на ци́трах, на аламот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'А Маттітію, і Еліфелегу, і Мікнею, і Овед-Едома, і Єїла, і Азазію — на а́рфах, на окта́ві, щоб починати гру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'А Кенанію, зверхника Левитів, — над но́шенням; він навчав носити, бо вмів того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'А Берехія та Елкана — придве́рні при ковчезі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'А Шеванія, І Йосафат, і Натанаїл, і Амасай, і Захарій, і Беная, і Еліезер, священики, — сурми́ли в су́рми перед Божим ковчегом, а Овед-Едом та Єхійя — придве́рні для ковчега.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'І пішов Давид і Ізраїлеві старші́ та тисячники, щоб перене́сти ковчега Господнього заповіту з Овед-Едомового дому з радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'І сталося, коли Бог допомагав Левитам, що не́сли ковчега Господнього заповіту, то вони прине́сли в жертву сім биків та сім баранів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'А Давид був зодя́гнений в одежу з вісо́ну, як і всі Левити, що не́сли ковчега, і співаки́, і Кенанія, зверхник но́шення і співакі́в, а на Давиді був ще й льняни́й ефо́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'І ввесь Ізраїль ніс ковчега Господнього заповіту з радісним криком, і зо звуком рога, і з су́рмами, і з цимба́лами, гра́ючи на ци́трах та на а́рфах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'І сталося, коли ковчег Господнього заповіту прийшов аж до Давидового Міста, то Мелхо́ла, Саулова дочка́, виглядала через вікно. І побачила вона царя Давида, що танцював та грав, і знева́жила його в своєму серці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'І прине́сли вони Божого ковчега, і поставили його в сере́дині скинії, що розтягну́в для нього Давид, і прине́сли цілопа́лення та мирні жертви перед Божим лицем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'І покінчи́в Давид прино́сити цілопа́лення та мирні же́ртви, та й поблагослови́в наро́д Ім\'я́м Господнім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'І він поділив для всякого Ізраїлевого му́жа, від чоловіка й аж до жінки, кожному по буханце́ві хліба, і по кава́лкові м\'яса та по виноградному калаче́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'І він попризна́чував перед Господнім ковчегом із Левитів слу́жачих, щоб вони визнава́ли, і прославляли, і хвалили Господа, Бога Ізраїлевого:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Асаф був головою, а другий по ньому — Захарій, Єіїл, і Шемірамот, і Хіїл, і Маттітія, і Еліяв, і Беная, і Овед-Едом, і Єіїл — на знаря́ддях цитр та на арфах, а Асаф голосно грав на цимба́лах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'А священики Беная та Яхазіїл — на су́рмах, за́вжди перед ковчегом Божого заповіту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Того дня, тоді Давид дав уперше псалма на подя́ку Господе́ві через Асафа та братів його:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '„Дякуйте Господу, кличте Ім\'я́ Його, серед наро́дів звіщайте про вчи́нки Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Співайте Йому́, грайте Йому́, говоріть про всі чу́да Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Хваліться святим Його Йме́нням, хай ті́шиться серце шукаючих Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Пошу́куйте Господа й силу Його́, лице Його́ за́вжди шукайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Пам\'ятайте про чу́да Його, які Він учинив, про озна́ки Його та про при́суди уст Його');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'ви, насіння Ізраїля, раба Його, сини Яковові, вибра́нці Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Він — Госпо́дь, Бог наш, по ці́лій землі Його при́суди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Пам\'ятайте наві́ки Його заповіта, слово, яке наказав Він на тисячу ро́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'що склав Він Його з Авраамом, і прися́гу Його — для Ісака.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'І Він поставив його за Зако́на для Якова, Ізра́їлеві — заповітом навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'говорячи: „Дам тобі край ханаа́нський, як наділ спна́дщини для вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Тоді їх було невелике число, нечисле́нні були та прихо́дьки на і́ншій землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'і від наро́ду ходили вони до наро́ду, і від царства до іншого люду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Не дозво́лив ніко́му Він кри́вдити їх, і за них Він царям докоря́в:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '„Не дото́ркуйтеся до Моїх помаза́нців, а пророкам Моїм не робіте лихо́го!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Господе́ві співайте, вся зе́мле, з дня-на-день сповіщайте спасі́ння Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Розповідайте про славу Його між пога́нами, про чу́да Його — між усіма наро́дами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Бо великий Господь і просла́влений ве́льми, і Він найгрізні́ший над бо́гів усіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Бо всі бо́ги наро́дів — божки́, а Господь небеса́ сотворив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Слава та ве́лич — перед лицем Його, сила та радість — на місці Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Дайте Господу, ро́ди наро́дів, дайте Господу славу та силу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'дайте Господу славу Йме́ння Його, прино́сьте дарунка й прихо́дьте перед лице Його! Кланяйтеся Господе́ві в вели́ччі святому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Перед лицем Його затремти́, уся зе́мле, — бо міцно поста́влений все́світ, щоб не захита́вся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Хай небо радіє, і хай весели́ться земля, і хай серед наро́дів говорять: „Царю́є Госпо́дь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Нехай гримить море й його повнота́, нехай поле радіє та все, що на ньо́му!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Тоді перед Господнім лицем дере́ва лісні́ заспівають, бо землю судити йде Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Дякуйте Господу, добрий бо Він, бо навіки Його милосе́рдя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'І промовте: Спаси нас, о Боже спасі́ння нашого, і збери нас, і нас урятуй від наро́дів, щоб дякувати Йме́нню святому Твоє́му, щоб Твоєю хвалитися славою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Благослове́нний Господь, Бог Ізраїлів, від віку й навіки!“А наро́д увесь сказав: „Амінь“і „Хвала́ Господе́ві!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'І Давид позоставив там перед ковчегом Господнього заповіту Асафа та братів його, щоб за́вжди служили перед ковчегом, що́ в якій день треба було́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'і Овед-Едома та братів його, шістдеся́т і вісьмо́х; а Овед-Едома, Єдутунового сина, та Хоса — за придве́рних;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'а священика Садока та братів його священиків — перед Господнім наметом на па́гірку, що в Ґів\'оні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'щоб прино́сити цілопа́лення для Господа на же́ртівнику цілопа́лення, за́вжди ра́нком та вве́чорі, та на все інше, що написане в Зако́ні Господа, що наказав був Ізраїлеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'А з ними Геман та Єдутун, та решта ви́браних, що були́ докла́дно зазначені поіменно, щоб „Дякувати Господе́ві, бо навіки Його милосе́рдя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'А з ними су́рми та цимба́ли для тих, що грають, та знаря́ддя для Божої пісні. А сини Єдутунові — сторожі до брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'І порозхо́дився ввесь народ, кожен до дому свого. А Давид вернувся, щоб поблагословити свій дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'І сталося, як Давид сидів був у домі своїм, то сказав Давид до пророка Натана: „Ось я сиджу́ в ке́дровому домі, а ковчег Господнього заповіту — під занаві́сами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'I сказав Ната́н до Давида: „Зроби все, що в серці твоєму, бо Бог із тобою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'І сталося тієї ночі, і було́ Боже слово до Натана, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '„Іди, і скажеш Моєму рабові Давидові: Так сказав Господь: Не ти збудуєш Мені цього храма на перебува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Бо Я не сидів у храмі від дня, коли вивів Ізраїля, аж до дня цього, і ходив від шатра́ до шатра́, і від намету до намету.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Скрізь, де тільки ходив Я між усім Ізраїлем, чи сказав Я хоч слово котро́му з Ізраїлевих су́ддів, яким наказав Я па́сти народа Мого: Чому́ ви не збудували Мені ке́дрового храма?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'А тепер так скажеш рабові Моєму Давидові: Так сказав Господь Савао́т: Я взяв тебе з пасови́ська від ота́ри, щоб став ти володарем над Моїм народом, Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'І був Я з тобою скрізь, де́ ти ходив, і ви́нищив Я всіх ворогів Твоїх перед тобою, і зробив Я тобі ім\'я́, як ім\'я́ тих великих, що на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'І дав Я місце Моє́му наро́дові Ізраїлеві, і посадив його так, що він перебува́тиме на тому́ самому місці. І він уже не тремті́тиме, а кри́вдники не будуть нищити його, як перше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'А від днів, коли Я настанови́в су́ддів над Своїм наро́дом, Ізраїлем, то пони́зив усіх ворогів твоїх. І звіщаю тобі, що Господь збудує тобі дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'І станеться, коли ви́повняться твої дні, щоб піти до батькі́в своїх, то Я поста́влю по тобі твоє насіння, що буде з синів твоїх, і поставлю міцно його царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Він збудує Мені храм, а Я поста́влю його тропа міцно аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Я бу́ду йому за батька, а він буде Мені за сина, а милости Своєї Я не відійму́ від нього, як відняв Я від того, що був перед тобою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'І поставлю його в храмі Своїм та в царстві Своїм аж навіки, і трон його буде міцно стояти навіки“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'За всіма́ цими словами, за всім цим виді́нням, — так говорив Ната́н до Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'І прийшов цар Давид, і сів перед Господнім лицем та й промовив: „Хто́ я, Господи, Боже, і що́ таке дім мій, що Ти довів мене аж сюди?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Та й це було мале в оча́х Твоїх, Боже, і Ти говорив про дім Свого раба на майбутнє, і Ти показав мені покоління лю́дське, і підніс мене, Господи Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Що́ Давид додасть ще до Твого на вшанува́ння Твого раба? А Ти Свого раба знаєш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Господи, ради Свого раба та за серцем Своїм зробив Ти все це велике, щоб завідо́мити про всі ті великі речі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Господи, нема Такого, як Ти, і нема Бога, окрім Тебе, за всім тим, що́ ми чули своїми уши́ма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'І який є ще один люд на землі, як Твій наро́д, Ізраїль, щоб Бог приходив ви́купити його Собі за наро́да, і щоб установити Собі ймення великих та страшни́х рече́й, щоб ви́гнати наро́ди перед наро́дом Своїм, якого Ти ви́купив із Єгипту?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'І зробив Ти наро́д Свій, Ізраїля, Собі за наро́да аж навіки, і Ти, Господи, став йому́ за Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'А тепер, Господи, нехай стане певним аж навіки те слово, яке говорив Ти про Свого раба, і зроби, як говорив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'А Твоє Ім\'я́ нехай буде міцне́, і нехай буде велике аж навіки, щоб казали: Господь Савао́т, Бог Ізраїлів — Бог для Ізраїля, а дім Твого раба Давида поста́влений міцно перед лицем Твоїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Бо Ти, Боже мій, об\'явив Своєму рабові, що Ти збудуєш йому дім, тому раб Твій знайшов потребу молитися перед лицем Твоїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'А тепер, Господи, Ти Той Бог, і сказав про Свого раба оце добре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'А тепер був Ти ласка́вий поблагословити дім Свого раба, щоб бути навіки перед лицем Твоїм, бо Ти, Господи, поблагословив, — і він поблагосло́влений навіки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'І сталося по то́му, і побив Давид филисти́млян та поконав їх; і взяв він Ґат та належні йому міста з руки филисти́млян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'І побив він Моава, — і стали моавітяни Давидовими рабами, що прино́сили да́ри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'І побив Давид Гадад\'езера, царя цовського, в Хаматі, коли той ішов, щоб поставити вла́ду свою на річці Ефра́ті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'І здобу́в Давид від нього тисячі колесни́ць і сім тисяч верхівці́в та двадцять тисяч пі́шого лю́ду. І попідрі́зував Давид жили коням усіх колесни́ць, і позоста́вив із них тільки сотню для колесни́ць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'І прийшов Арам із Дамаску на поміч Гадад\'езерові, цареві цовському, та Давид вибив серед сирі́ян двадцять і дві тисячі чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'І поставив Давид у Сирії Дама́ській зало́гу, і сирі́яни стали для Давида рабами, що прино́сили да́ри. А Господь допомагав Давидові скрізь, де́ він ходив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'І позабирав Давид золоті щити́, що були на Гадад\'езерових раба́х, і позно́сив їх до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'А з Тівхату та з Куну, Гадад\'езерових міст, позабирав Давид дуже багато міді, — з неї поробив Соломо́н мідяне море й стовпи́, та мідяні ре́чі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'І прочув Тоу, цар хамотський, що Давид побив усе ві́йсько Гадад\'езера, царя цовського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'І послав він сина свого Гадорама до царя Давида, щоб привітати його, та щоб поблагословити його за те, що воював із Гадад\'езером та й побив його, — бо Гадад\'езер прова́див війну з Тоу, — а з ним послав всякі речі золоті, і срібні, і мідяні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'І Давид присвятив їх Господе́ві ра́зом із тим сріблом та золотом, що повино́сив від усіх наро́дів з Едому, і з Моаву, і від Аммонових синів та від Амали́ка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'А Авшай, син Церуїн, побив Едома в Соляній долині, вісімнадцять тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'І поставив він в Едомі зало́гу, і став увесь Едом Давидовими раба́ми. А Госпо́дь допомагав Давидові скрізь, де́ він ходив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'І царював Давид над усім Ізраїлем, і чинив суд та справедливість усьо́му своє́му наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'А Йоав, син Церуїн, був над ві́йськом, а Йосафат, син Ахілудів, — ка́нцлер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'А Садо́к, син Ахітувів, та Авіме́лех, син Ев\'ятарів, були священики, а Шавша — писар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'А Беная, син Єгоядин, був над керетянином та над пелетянином, а Давидові сини — перші при царе́вій руці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'І сталося по то́му, і помер Нахаш, цар аммонітський, а замість нього зацарював син його Ханун.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'І сказав Давид: „Зроблю́ я ми́лість Ханунові, Нахашевому синові, як ба́тько його зробив був ми́лість мені“. І Давид послав послів, щоб потішити його за його ба́тька. І прибули́ Давидові раби до аммонітського кра́ю, до Хануна, щоб потішити його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'А начальники аммонітян сказали до Хануна: „Чи Давид ша́нує батька твого в оча́х твоїх тим, що послав тобі потіши́телів? Чи ж раби його прийшли до тебе не на те, щоб ви́відати, і щоб зни́щити, і щоб ви́шпигувати край?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'І взяв Ханун Давидових рабів та й оголив їх, й обрізав їхню оде́жу в половині аж до сиді́ння, та й відпустив їх...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'І пішли й доне́сли Давидові про тих мужів, а він послав навпро́ти них, бо ті мужі були дуже осоро́млені. І цар їм сказав: „Сидіть в Єрихо́ні, аж поки відросте́ вам борода, потім пове́рнетесь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'І побачили аммоні́тяни, що вони знена́виджені в Давида. І послав Ханун та аммоні́тяни тисячу тала́нтів срібла, щоб ви́найняти собі колесни́ці та верхівці́в з Араму двох річок і з Араму Маахи та з Цови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'І найняли вони собі тридцять і дві тисячі колесни́ць, і царя Мааих та наро́д його, — і прийшли й таборува́ли перед Медевою. Також аммоні́тяни зібралися зо своїх міст і прийшли до бо́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'А коли Давид прочув про це, то послав Йоава та все ві́йсько ли́царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'І повихо́дили аммоні́тяни, і вставилися до бо́ю при вході до міста. А царі, що прийшли, — вони самі були на полі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'І побачив Йоа́в, що бойови́й фронт став на нього спе́реду та поза́ду, то вибрав зо всього ви́браного в Ізраїлі, та й установи́в їх навпроти сирі́ян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'А решту наро́ду дав під ру́ку свого брата Ав\'шая, й їх установи́ли навпроти аммоні́тян,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'і сказав: „Якщо сирі́яни бу́дуть сильніші від мене, то будеш мені на поміч, а якщо аммоні́тяни будуть сильніші від тебе, то допоможу́ тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Будь мужній, і стіймо міцно за наро́д наш та за міста́ нашого Бога, а Господь нехай зробить, що́ добре в оча́х Його́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'А коли Йоав та народ, що був із ним, підійшов перед сирі́ян до бо́ю, то ті повтікали перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'А аммоні́тяни побачили, що повтікали сирі́яни, то й вони повтікали перед братом його Ав\'шаєм, і ввійшли до міста, а Йоа́в прибув до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'А коли побачили сирі́яни, що вони побиті Ізраїлем, то послали послів, і привели́ сиріян, що з другого боку Річки, а Шофах, зверхник Гадад\'езерового ві́йська, був перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'І було доне́сено Давидові, і він зібрав усього Ізраїля, і перейшов Йорда́н та прийшов до них, і вста́вився проти них. І встанови́вся Давид на бій проти сиріян, і вони воювали з ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'І побігли сирі́яни перед Ізраїлем, а Давид повбивав із сирі́ян сім тисяч колесни́ць та сорок тисяч пішого люду. І вбив він Шофаха, зверхника ві́йська...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'А коли Гадад\'езерові раби побачили, що вони побиті Ізраїлем, то замири́лися з Давидом і служили йому. І сиріяни вже не хотіли допомагати аммоні́тянам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'І сталося по році, того ча́су, як царі вихо́дили на війну, то Йоав повів військо́ву силу, та й нищив аммонітський край. І прийшов він і обліг Раббу, а Давид сидів в Єрусалимі. І побив Йоав Раббу, і зруйнував її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'І зняв Давид корону їхнього царя з голови його, і знайшов, що вага́ її́ талант золота, а на ній камі́ння дорогоцінне, — і була покладена вона на голову Давидову! І він виніс дуже багато здо́бичі з того міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'А наро́д, що був у ньому, повиво́див, і перетина́в їх пи́лками, і забивав залі́зними доло́тами та сокирами... І так робив Давид усім аммонітським міста́м. І вернувся Давид та ввесь наро́д до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'І сталося по то́му, і була війна в Ґезері з филисти́млянами. Тоді хуша́нин Сіббехай убив Сіппая, з Рефаєвих наща́дків, і вони були поко́нані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'І була ще війна з филисти́млянами, і Елханан, син Яірів, побив Лахмі, брата ґатя́нина Ґоліята, — а держа́к списа́ його був, як ткацький вал!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'І була́ ще війна в Ґаті. А там був чоловік великого зро́сту, що мав по шість пальців, — усього двадцять і чотири. І він також був із наща́дків Рефая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'І зневажа́в він Ізраїля, — та забив його Йонатан, син Шім\'ї, Давидового брата.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ці також похо́дили від Рефая в Ґаті, — і попа́дали вони від руки Давида та від руки його слуг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'І повстав сатана́ на Ізраїля, і намо́вив Давида перелічи́ти Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'І сказав Давид до Йоава та до начальників народу: „Ідіть, перелічіть Ізраїля від Беер-Шеви й аж до Дану, і донесіть мені, — і я знатиму число їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'І сказав Йоа́в: „Нехай Господь додасть до наро́ду Свого в сто раз стільки, скільки є! Чи не всі вони, пане мій ца́рю, раби мого пана? На́що буде шукати цього пан мій, нащо це буде за провину для Ізраїля?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Та цареве слово перемогло Йоава. І вийшов Йоав, і ходив по всьо́му Ізраїлі, і вернувся до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'І дав Йоав Давидові число пере́ліку наро́ду. І було́ всього Ізраїля тисяча тисяч і сто тисяч чоловіка, що витяга́ють меча, а Юди — чотири сотні й сімдеся́т тисяч чоловіка, що витягають меча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'А Левія та Веніямина він не перерахува́в серед них, бо царське́ слово було огидою для Йоа́ва...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'І було зло в Божих оча́х на ту річ, — і Він ударив Ізраїля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'І сказав Давид до Бога: „Я дуже згрішив, що зробив оцю річ! А тепер прости ж гріх Свого раба, бо я зробив дуже нерозумно!“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'І сказав Господь до Ґада, Давидового прозорли́вця, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '„Іди, і бу́деш говорити Давидові, кажучи: Так говорить Госпо́дь: Три карі кладу́ Я на те́бе, — вибери собі одну з них, і Я зроблю́ тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'І прийшов Ґад до Давида та й сказав йому́: „Так сказав Госпо́дь: Ви́ бери собі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'чи три роки голоду, чи теж три місяці твого втіка́ння перед ворогами твоїми, а меч ворогів твоїх доганя́тиме тебе́, чи три дні Господнього меча та морови́ці в Краю́, і Ангол Господній бу́де нищити по всій Ізраїлевій границі. А тепер розваж, яке слово верну́ Я Тому́, Хто послав мене“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'І сказав Давид до Ґада: „Тяжко мені дуже! Нехай же впаду́ я в руку Господа, бо дуже велике Його милосе́рдя, а в руку лю́дську нехай я не впаду́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'І дав Господь морови́цю в Ізраїлі, — і впало з Ізраїля сімдеся́т тисяч чоловіка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'І послав Бог Ангола до Єрусалиму, щоб зни́щити його. А коли він нищив, Господь побачив і пожалував про це ли́хо. І сказав Він до Ангола, що вигублював: „Забагато тепер! Попусти свою ру́ку!“А Ангол Господній стояв при то́ці євусе́янина Орнана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'I підняв Давид очі свої та й побачив Господнього Ангола, що стояв між землею та між небом, а в руці його був ви́тягнений меч, скеро́ваний на Єрусалим. І впав Давид та ті старші́, покриті вере́тами, на обличчя свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'І сказав Давид до Бога: „Чи ж не я сказав рахувати в народі? І я той, хто згрішив, і вчинити зло — я вчинив зло, а ці ві́вці — що́ зробили вони, Господи, Боже мій? Нехай же рука Твоя буде на мені та на домі батька мого, а не на наро́ді Твоє́му, щоб погубити його “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'А Ангол Господній говорив до Ґада, — сказати Давидові, щоб Давид пішов поставити же́ртівника для Господа на току євусе́янина Орнана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'І пішов Давид за словом Ґада, що говорив в Господньому Імені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'І обернувся Орнан, і побачив Ангола, а чотири сини його, що були з ним, похова́лися. А Орнан молотив пшеницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'І прийшов Давид до Орнана. І виглянув Орнан, і побачив Давида, — і вийшов із то́ку, і поклонився Дави́дові обличчям до землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'І сказав Давид до Орнана: „Дай же мені місце цього то́ку, й я збудую на ньому же́ртівника для Господа. Дай мені його за срібло повної ваги, — і буде стри́мана морови́ця від наро́ду“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'І сказав Орнан до Давида: „Візьми собі, і нехай зробить мій пан цар, що добре в оча́х його. Дивися, — я даю цю худобу на цілопа́лення, а молота́рки — на дро́ва, а пшеницю на хлібну жертву. Усе я даю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'І сказав цар Давид до Орнана: „Ні, бо купу́ючи, куплю́ за срібло повної ваги, бо не піднесу́ твого в жертві для Господа, і не спалю́ цілопа́лення да́рмо!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'І дав Давид Орнанові за місце золота вагою шість сотень ше́клів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'І збудував там Давид же́ртівника для Господа, і приніс цілопа́лення та мирні жертви. І кликнув він до Господа, і Він відповів йому́ огнем із небе́с на же́ртівник цілопа́лення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'І сказав Господь до Ангола, і він уклав меча свого до пі́хов його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Того ча́су, як Давид побачив, що Господь відповів йому на току́ євусе́янина Орнана, то прино́сив там жертву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'А Господня скинія, яку зробив був Мойсей у пустині, та же́ртівник цілопа́лення були того ча́су на па́гірку в Ґів\'оні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Та не міг Давид піти перед нього, щоб запитатися в Бога, бо настра́шився меча Господнього Ангола.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'І Давид сказав: „Це той дім Господа Бога, і це же́ртівник на цілопа́лення для Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'І сказав Давид, щоб зібрати прихо́дьків, що були в Ізраїлевому Кра́ї, і поставив каменярі́в теса́ти бри́ли каміння, щоб збудувати Божого дома.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'І загото́вив Давид силу заліза на цвяхи для брамних дверей та на клямри, і таку силу міді, що їй не було ваги,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'і ке́дрового дерева без числа, бо сидо́няни та тиря́ни спрова́дили Давидові силу ке́дрового дерева.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'І сказав Давид: „Мій син Соломон ще юна́к та тенді́тний, — приготую ж йому все на цей храм на збудува́ння для Господа, щоб підне́сти його ви́соко на славу та на ве́лич для всіх краї́в. Приготую ж я все для нього!“І Давид заготовив бе́зліч усього перед своєю смертю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'І він покликав сина свого Соломо́на, і наказав йому збудувати храм для Господа, Бога Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'І сказав Давид до Соломона: „Сину мій, я мав на своєму серці ви́будувати храм для Ймення Господа, Бога мого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Та було про мене Господнє слово, кажучи: Бе́зліч крови пролив ти та війни великі прова́див. Не збудуєш ти храма для Мого Ймення, бо багато крови пролив ти на зе́млю перед лице́м Моїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Ось наро́диться тобі син, — він буде муж мирний, і Я дам йому мир від усіх ворогів його навко́ло, бо Соломон буде ім\'я́ йому, і Я дам на Ізраїля за його днів мир та ти́шу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Він збудує храм для Мого Ймення, і він буде Мені за сина, а Я йому за Батька, і Я міцно поставлю трона царства його над Ізраїлем аж навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Тепер, сину мій, нехай Госпо́дь буде з тобою, і буде щасти́ти тобі, і збудуєш ти дім для Го́спода, Бога свого, як говорив Він про тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Тільки нехай дасть тобі Господь розум та розважність, і нехай поставить тебе над Ізраїлем, і ти будеш стерегти́ Зако́н Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Тоді буде щасти́ти тобі, якщо бу́деш доде́ржувати, щоб чинити устави та права, які наказав був Господь Мойсеєві про Ізраїля. Будь сильний та міцни́й, не бійся й не страха́йся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'І ось я в скудо́ті своїй загото́вив для Господнього дому сто тисяч талантів золота та тисячу тисяч талантів срібла, а для міді та для заліза — нема ваги, бо бе́зліч того; і де́рева, і каміння заготовив я, а ти до них додаси́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'А в тебе бе́зліч робітникі́в для праці, — теслярі́в і каменярі́в та деревору́бів, та всяких здібних на всяку роботу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Зо́лоту, сріблу, і міді та залізу — нема числа. Стань і зроби, і нехай Господь буде з тобою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'I наказав Давид усім Ізраїлевим князя́м, щоб допомага́ли синові його Соломо́нові:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '„Чи Господь, Бог ваш, не з вами? І Він дав вам мир навко́ло, бо дав у мою руку мешканців цієї землі, — і була́ здобута ця земля перед лицем Господа та перед наро́дом Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Тепер прихиліть серце ваше та душу вашу, щоб шукати Господа, Бога вашого. І встаньте, і збудуйте святиню Господа Бога, щоб перене́сти ковчега Господнього заповіту та святі Божі речі до храму, збудо́ваного для Господнього Ймення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'А коли Давид постарів і наси́тився днями, то він поставив царем над Ізраїлем сина свого Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'І зібрав він усіх Ізраїлевих князі́в, і священиків та Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'І були перелі́чені Левити від віку тридцяти років і вище, і було число їх, за їхніми го́ловами, за мужчинами — тридцять і вісім тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Із них для керува́ння над роботою Господнього дому — двадцять і чотири тисячі, а урядників та суддів — шість тисяч,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'і чотири тисячі придве́рних, і чотири тисячі тих, що славлять Господа на музичних знаря́ддях, „які я зробив на сла́влення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'І поділив їх Давид на черги за синами Левія, — для Ґершона, Кегата та Мерарі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'З Ґершонівців — Ладан і Шім\'ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ладанові сини: голова Єгіїл, і Зетам, і Йоїл, троє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Сини Шім\'ї: Шеломіт, і Хазаїл, і Гаран, троє, вони го́лови ба́тьківських домів Ладана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'А сини Шім\'ї: Яхат, Зіза, і Єуш, і Берія, — оце сини Шім\'ї, четверо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'І був Яхат головою, а Зіза другий, а Єуш та Берія не мали багато синів, і стали за один ба́тьківський дім при переліченні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Кегатові сини: Амрам, Іцгар, Хеврон та Уззіїл, четверо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Амрамові сини: Аарон та Мойсей. І був відді́лений Аарон, щоб посвятити його до Святого Святих, його та синів його аж навіки, щоб кадити перед лицем Господа, щоб служити Йому та щоб благословляти Ім\'ям Його аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'А Мойсей — Божий чоловік, сини його полі́чені до Левієвого племени.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Сини Мойсеєві: Ґершом та Еліезер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Сини Ґершомові: Шевуїл, голова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'А сини Еліезерові були́: Рехавія, голова; і не було́ в Еліезера інших синів, а сини Рехавії сильно помно́жились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Сини Їцгарові: Шеломіт, голова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Сини Хевронові: Єрійя — голова, Амарія — другий, Яхазіїл — третій, і Єкам\'ам — четвертий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Сини Уззіїлові: Міхал — голова, а Їшшійя — другий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Сини Мерарієві: Махлі й Муші. Сини Махлі: Елеазар і Кіш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'І помер Елеазар, і не було в нього сині́в, бо тільки до́чки, і їх побрали собі Кішові сини, їхні брати́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Сини́ Мушієві: Махлі, і Едер, і Єремот, — троє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Оце сини́ Левієві за домом батьків їх, голови дому батьків за перегля́ненням їхнім, числом іме́н за особами їх, що чинили роботу для будо́ви Господнього дому, від віку двадцяти років і вище.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Бо Давид сказав: Господь, Бог Ізраїля, дав мир Своєму наро́дові, і він осівся в Єрусалимі аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'І також Левитам не треба носити скинії та всіх рече́й її для служби їй“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'бо за останніми наказами Давида вони становлять число Левієвих сині́в від віку двадцяти літ і вище.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Бо їхнє стано́вище — при руці Ааронових синів для служби Господнього дому над подві́р\'ями, і над кімна́тами, і над чистістю усіх святощів та роботи служби Господнього дому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'і при хлібі виставні́м, і при пшеничній муці на хлі́бну жертву та на прісні́ коржі, і при ско́вородах, і при пра́женні, і при всякій мірі ваги та мірі довжини́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'І щоб ставати щора́нку на подяку та на хвалу Господа, і так і на вечір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'І при всякому спа́ленні цілопа́лень для Господа на суботи, на молодики́, і на свята в числі за правом на них, за́вжди перед лицем Господнім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'І чини́ли вони охорону скинії заповіту, і сторо́жу святині, і охорону Ааронових синів, своїх братів, при службі Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'А в Ааро́нових синів такі їхні че́рги: Ааро́нові сини: Надав і Авігу, Елеазар і Ітамар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Та повмирали Надав та Авігу за життя їхнього батька, і не мали вони сині́в, тому священноді́яли Елеазар та Ітамар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'І поділив їх Давид і Садо́к, з Елеазарових синів, та Ахіме́лех, з Ітамарових синів, за їхнім уря́дом в їхній службі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'І були зна́йдені Елеаза́рові сини численні́шими, щодо голів чоловіків, від синів Ітамарових. І вони поділили їх: для Елеаза́рових синів голів дому батьків було шістнадцять, а для Ітамарових синів для дому батьків їх — вісім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'І поділили їх жеребка́ми, тих з тими, бо головними в святині та головними перед Богом були з синів Елеазарових та серед синів Ітамарових.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'І записав їх Шемая, син Натанаїлів, писар із Левитів, перед царем, і головни́ми, і священиком Садо́ком, і Ахіме́лехом, сином Евіятаровим, і го́ловами дому батьків священиків та Левитів. Один ба́тьківський дім був узятий для Елеазара, а один був узятий для Ітамара.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'І вийшов перший жеребо́к для Єгояріва, другий — для Єдаї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'третій — для Харіма, четвертий — для Сеоріма,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'п\'ятий — для Малкійї, шо́стий — для Мійяміна,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'сьо́мий для Гаккоца, во́сьмий — для Авійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'дев\'ятий — для Єшуї, десятий — для Шеханії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'одина́дцятий — для Ел\'яшіва, дванадцятий — для Якіма,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'тринадцятий — для Хуппи, чотирна́дцятий — для Єшев\'ава,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'п\'ятнадцятий — для Білґи, шістнадцятий — для Іммера,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'сімнадцятий — для Хезіра, вісімнадцятий — для Гаппіццеца,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'дев\'ятнадцятий — для Петах\'ї, двадцятий — для Єхезкела,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'двадцять і перший — для Яхіна, двадцять і другий — для Ґамула,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'двадцять і третій — для Делаї, двадцять і четвертий — для Маазії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Оце поря́док їхньої служби, щоб прихо́дити до Господнього дому за їхньою постановою через Ааро́на, їхнього батька, як йому наказав був Господь, Бог Ізраїлів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'А від позосталих Левієвих синів: від Амрамових синів — Шуваїл, від синів Шуваїлових — Єхедія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Від Рехавії, від синів Рехавії: голова Їшшійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Від Їцгарівців: Шеломот, від Шеломотових синів: Яхат.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'А сини Хевронові: Єрійя, другий — Амарія, третій — Яхазіїл, четвертий — Єкам\'ам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Сини Уззіїлові: Міха, сини Міхині: Шамір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Брат Міхи — Їшшійя, сини Їшшійїні — Захарій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Сини Мерарієві: Махлі та Муші, сини Яазійї — Бено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Сини Мерарієві, від Яазійї: Бено, і Шогам, і Заккур, і Іврі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'У Махлі: Елеазар, у нього не було синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Від Кіша, сини Кішові: Єрахмеїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'А сини Мушієві: Махлі, і Едер, і Єрімот. Оце сини Левитів, за домом їхніх батькі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'І кидали жеребки́ і вони відповідно до братів своїх, Ааро́нових синів, перед царем Давидом, і Садо́ком, і Ахімелехом, і го́ловами дому батьків священиків та Левитів, го́лови родин нарівні зо своїм меншим братом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'І відділи́в Давид та зверхники війська на службу синів Асафа, і Гемана, і Єдутуна, що прові́щували на ци́трах, і на а́рфах, і на цимба́лах. А число їх, людей праці до служби, було таке:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'від Асафових синів: Заккур, і Йосип, і Нетанія, і Асар\'їла, Асафові сини, при Асафі, що пророкував при царі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Від Єдутуна, Єдутунові сини: Ґедалія, і Цері, і Ісая, Хашавія, і Маттітія, — ше́стеро при своєму батькові Єдутуні, що пророкував на цитрі на дяку та на хвалу Господе́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Від Гемана, Геманові сини: Буккійя, Маттанія, Уззіїл, Шевуїл, і Єрімот, Хананія, Ханані, Еліата, Ґіддалті, і Ромамті, Езер, Йошбекаша, Маллоті, Готір, Махазіот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Усі ці — сини́ Гемана, царсько́го прозорли́вця в Божих слова́х, щоб підви́щувати силу. І дав Бог Геманові чотирна́дцять синів та три дочки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Усі вони були при своє́му батькові, на співі Господнього дому, на цимба́лах, на а́рфах та ци́трах для служби в Божому домі; при царі — Асаф, Єдутун та Геман.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'І було їхнє число з їхніми брата́ми, ви́вченими співу для Господа, усіх розуміючих, — двісті й вісімдеся́т і вісім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'І кинули вони жеребки́, черга́ відповідно черзі, як мали́й, так і великий, учитель з у́чнем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'І вийшов перший жеребо́к від Асафа для Йо́сипа, другий — Ґедалія, він і брати́ його та сини́ його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Третій Заккур, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Четвертий — для Їцрі, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'П\'ятий — Нетанія, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Шо́стий — Буккійя, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Сьо́мий — Єсар\'їла, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Во́сьмий — Іса́я, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Дев\'ятий — Маттанія, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Десятий — Шім\'ї, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Одинадцятий — Азаріїл, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Дванадцятий — для Хашав\'ї, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Тринадцятий — для Шуваїла, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Чотирна́дцятий — для Маттітії, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'П\'ятнадцятий — для Єремота, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Шістнадцятий — для Хананії, сини його брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Сімнадцятий — для Йошбекаші, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Вісімнадцятий — для Ханані, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Дев\'ятнадцятий — для Маллоті, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Двадцятий — для Елійяти, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Двадцять і перший — для Готіра, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Двадцять і другий — для Ґіддалті, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Двадцять і третій — для Махазіота, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Двадцять і четвертий — для Ромамті-Езера, сини його та брати його, дванадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Че́рги придве́рних, від Кора́хівців: Мешелемія, син Коре, з Асафових синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'А в Мешелемії сини: перворо́джений — Захарій, другий — Єдіаїл, третій — Зевадія, четвертий — Ятніїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'п\'ятий — Елам, шостий — Єгоханан, сьомий — Ел\'єгоенай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'А в Овед-Едома сини: перворо́джений — Шемая, другий — Єгозавад, третій — Йоах, четвертий — Сахар, і п\'ятий — Натанаїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'шо́стий — Амміїл, сьо́мий — Іссахар, во́сьмий — Пеуллетай, бо поблагословив його Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'У сина його Шемаї народи́лися сини, що панували над домом їхнього батька, бо вони — хоробрі вояки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Сини Шемаї: Отні, і Рефаїл, і Овед, Елзавад; його брати, мужі хоробрі, — Елігу та Шемахія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Усі ці — з Оведових сині́в; вони й сини та брати їхні — кожен хоробрий муж у силі до праці, шістдеся́т і два для Овед-Едома.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'А в Мешелемії було синів та братів, мужів хоробрих, вісімнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'А в Хоси, з синів Мерарі, сини: голова — Шімрі, бо хоч не був він перворо́джений, та батько його настановив його за голову:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'другий — Хілкійя, третій — Тевалія, четвертий Захарій; усіх синів та братів у Хоси — тринадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'У цих були че́рги придве́рних, за головами мужчин, че́рги відповідно до їхніх братів на слу́ження в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'І кинули вони жеребки́, як малий, так і великий, за домом їхніх батьків, для кожної брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'І впав жеребо́к на схід для Шелемії. І кинули жеребки́ для сина його Захарія, мудрого дорадника, і вийшов жеребок його на пі́вніч,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'для Овед-Едома, — на пі́вдень, а для синів його — комо́ри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Для Шуппіма та для Хоси — на за́хід, ра́зом із брамою Шаллехет, де підійма́ється битий шлях, ва́рта навпроти ва́рти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'На схід — шість Левитів, на північ — четверо на день, на пі́вдень — четверо на день, а для комори — по двоє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Для Парбару на за́хід — четверо для битого шля́ху, двоє для Парбару.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Оце че́рги придве́рних із синів Корахівців та з синів Мерарі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'А Левити: Ахійя був над ска́рбами Божого дому та до скарбів святині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Сини Ладана, сини Ґершонівців, від Ладана, голови дому батьків, від Ладана Ґершонівця: Єхилі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Сини Єхіїлі: Зетам та Йоїл, брат його, над ска́рбами Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Для Амрамівців, для Їцгарівців, для Хевронівців, для Аззіїлівців:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Шевуїл, син Ґершома, сина Мойсея, — володар над скарбами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'А брати його від Еліезера: його син — Рехавія, і його син Ісая, і його син — Йорам, і його син — Зіхрі, і його син — Шеломіт.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Цей Шеломіт та брати його були над усіма́ ска́рбами святині, які посвятив цар Давид та голови дому батьків, і тисячники, і сотники та зверхники війська, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'з во́єн та зо здо́бичі вони присвячували на підтри́мання Господнього дому, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'і все, що посвятив прозорли́вець Самуїл, і Саул, син Кішів, і Авнер, син Нерів, і Йоав, син Церуїн, — усе посвячене було в руці Шеломіта та братів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Від Їцгарівців: Кенанія та сини його — на зо́внішню роботу над Ізраїлем, на писарі́в та на су́ддів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Від Хевронівців: Хашавія та брати його, мужі хоробрі, тисяча й сім сотень, — над пере́глядом Ізраїля з другого боку Йорда́ну на за́хід, для всякої Господньої праці та для роботи царсько́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Від Хевронівців: Єрійя — голова для Хевронівця, для його наща́дків, за домом батьків. У сороковому році Давидового царюва́ння вони були досліджені, і серед них зна́йдено хоробрих мужів в гілеадському Язері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'А брати його — мужі хоробрі, дві тисячі й сім сотень, го́лови дому батьків. І цар Давид настанови́в їх над Руви́мівцями і над Ґадівцями та над половиною племени Манасіїного для всякої Божої справи та справи царсько́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'А Ізра́їлеві сини, за їхнім число́м, го́лови ба́тьківських родів і тисячники, і сотники та їхні уря́дники служили царе́ві щодо всякої справи відділів, що прихо́див та відхо́див місяць у місяць для всіх місяців року; один ві́дділ мав двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Над першим відділом, на перший місяць — Яшов\'ам, син Завдіїлів, а на відділ його — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Він був з Перецових синів, голова всіх військо́вих зверхників на перший місяць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'А над відділом другого місяця — Ахохівець Додай, а володар його відділу — Міклот; а на його відділ ішло двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Третій зверхник війська на третій місяць — священик Беная, голова, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Цей Беная — ли́цар із тридцяти й над тридцятьма́; а над його ві́дділом був син його Аммізавад.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Четвертий на місяць четвертий — Асаїл, брат Йоавів, а по ньо́му син його Зевадія; а на його ві́дділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'П\'ятий на місяць п\'ятий — зверхник ізрах\'янин Шамут, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Шо́стий на місяць шостий — Іра, син текоянина Іккеша, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Сьо́мий на місяць сьомий — пелонянин Хелец з Єфремових синів, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Во́сьмий на місяць восьмий — хушанин Сіббехай з Зерахівців, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Дев\'ятий на місяць дев\'ятий — анатонянин Авіезер з Веніяминівців, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Десятий на місяць десятий — нетоф\'янин Магарай з Зерахівців, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Одина́дцятий на одина́дцятий місяць — пір\'атонянин Беная з Єфремових синів, а на його ві́дділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Дванадцятий на дванадцятий місяць — нетоф\'янин Хелдай з Отніїла, а на його відділ — двадцять і чотири тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'А над Ізраїлевими племе́нами були: для Руви́мівців — володар Еліезер, син Зіхрі; для Симеонівців — Шефатія, син Маахи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Для Левія — Хашавія, син Кемуїла, для Ааро́на — Садо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Для Юди — Елігу, з Давидових братів, для Іссаха́ра — Омрі, син Михаїлів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Для Завуло́на — Їшмая, син Овадії, для Нефталима — Єрімот син Азріїлів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Для Єфремових синів — Осі́я, син Азазії, для половини Манасіїного племени — Йоїл, син Педаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Для половини Манасії в Ґілеаді — Їддо, син Захарія, для Веніямина — Яасіїл, син Авнерів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Для Дана — Азаріїл, син Єрохамів. Оце зве́рхникн Ізраїлевих племен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'А Давид не перелічи́в їхнього числа від віку двадцяти літ і нижче, бо Господь сказав був, що розмно́жить Ізраїля, як зорі небесні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Йоа́в, син Церуїн, зачав був лічи́ти, та не скінчив. І був за те гнів на Ізраїля, і не ввійшло те число в число хроніки царя Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'А над ска́рбами царськи́ми — Азмавет, Адіїлів син, а над ска́рбами на полі, у міста́х, і в се́лах та в ба́штах — Єгонатан, син Уззійї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'А над тими, що робили польову́ роботу, для праці, на землі — Езрі, син Келувів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'А над виноградниками — рам\'янин Шім\'ї, а над тим, що в виноградниках для запа́сів вина — шефам\'янин Завді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'А над оливками та над сикомо́рами, що в Шефелі, — ґедерянии Баал-Ханан; а над ска́рбами оливи — Йоаш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'А над великою худобою, що пасеться в Шароні, — шаронянин Шітрай, а над великою худобою в доли́нах — Шафат, син Адлаїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'А над верблю́дами — їзмаїльтянин Овіл, а над осли́цями — меронотянин Єхдея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'А над дрібно́ю худобою — гаґрянин Язіз. Усі оці — зверхники мастку, що мав цар Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'А Йонатан, Давидів дядько, був радник, він чоловік розумний та писар. А Єхіїл, син Нахмоніїв, був із царськи́ми сина́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'А Ахітофель — радник цареві, а арк\'янин Хушай — при́ятель царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'А по Ахітофелю — Єгояда, син Бенаї, та Евіятар, а зве́рхник царсько́го ві́йська — Йоав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'І зібрав Давид усіх Ізра́їлевих князі́в, зверхників племе́н, і зверхників відділів, що служать цареві, і тисячників, і сотників, і зверхників усякого маєтку та добутку царя та синів його ра́зом з е́внухами та ли́царями, та всякого хороброго вояка до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'І встав цар Давид на но́ги свої та й сказав: „Послухайте мене, брати мої та наро́де мій! Я серцем своїм був за те, щоб збудувати храм миру для ковчега Господнього заповіту та на підні́жок ніг нашого Бога, й я пригото́вив потрібне на збудува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'А Бог сказав мені: Ти не збудуєш храма для Мого Йме́ння, бо ти муж во́єн і кров проливав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Та вибрав Господь, Бог Ізраїлів, мене з усього дому батька мого, щоб бути царем над Ізраїлем навіки, бо Юду вибрав Він на володаря, а серед Юдиного дому — дім батька мого, а серед синів мого батька — мене уподо́бав Собі, щоб настанови́ти царем над усім Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'А зо всіх моїх синів, — бо багатьо́х сині́в дав мені Господь — то Він вибрав сина мого Соломона, щоб сидів на троні Господнього царства над Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'І Він сказав мені: Соломон, син твій, — він збудує храма Мого та двори́ Мої, бо його Я вибрав Собі за сина, а Я бу́ду йому за Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'І міцно поставлю Я царство його аж навіки, якщо він буде си́льний, щоб вико́нувати заповіді Мої та постано́ви Мої, як цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'А тепер на оча́х усього Ізраїля, Господнього збо́ру, та в ушах нашого Бога говорю́ вам: Додержуйте й досліджуйте всі заповіді Господа, Бога вашого, щоб ви посіли цей добрий Край і віддали його в спа́дщину по собі синам вашим аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'А тепер, сину мій Соломо́не, знай Бога, Отця твого, і служи Йому всім серцем та всією душею, бо Господь вивідує всі серця та знає всякий витвір думо́к. Якщо будеш шукати Його, то ти зна́йдеш Його, а якщо залишиш Його, Він залишить тебе наза́вжди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Тепер дивися, що Господь вибрав тебе збудувати дім на святиню. Будь міцни́й та роби!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'І Давид дав своєму синові Соломо́нові взори Господнього дому: притво́ру, і домів його, і скарбниць його, і го́рниць його, і кімна́т його внутрішніх, і дому для ковчегу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'і взір усього, що було в дусі його́ для подвір\'я Господнього дому, і для всіх кімна́т навко́ло, для ска́рбів Божого дому та для ска́рбів святині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'і для ві́дділів священиків та Левитів, і для всякої праці служби Господнього дому, і для всяких рече́й для служби Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'І дав він золота — вагою для золота, для всіх речей кожної служби; і срібла для всіх срібних речей — вагою, для всіх речей кожної служби;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'і вагу для золотих свічників та золотих їхніх лямпа́док, — вагою кожного свічника та лямпадок його, і для срібних свічників, — вагою для свічника́ та лямпадок його, за роботою кожного свічника́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'І дав золота вагою для столі́в хлібі́в показни́х, для кожного сто́лу і срібла для срібних столі́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'і виде́льця, і кропи́льниці, і чарки́ — чисте золото, і для золотих ке́ліхів — вагою для кожного ке́ліха, і для ке́ліхів срібних, — вагою для кожного келіха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'А для кадильного жертівника — дав очищеного золота вагою, і на подобу воза, для золотих херувимів, що простягають крила свої й покривають над ковчегом Господнього заповіту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Усе це він зрозумів із письма з Господньої руки, що була́ над ним, усі роботи взору.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'І сказав Давид до сина свого Соломона: „Будь си́льний і будь відважний, і роби, не бійся та не лякайся, бо Господь Бог, Бог мій, з тобою, — Він не покине тебе й не позоста́вить тебе аж до закі́нчення всієї праці роботи Господнього дому...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'А оце че́рги священиків та Левитів для всякої служби Божого дому. І будуть з тобою в усякій праці ре́вні люди, зді́бні на всяку службу, а начальники та ввесь наро́д, — на всі нака́зи твої“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'І сказав цар Давид до всього збору: „Син мій Соломон, що його одного Бог вибрав, ще молодий та тенді́тний, а ця праця — велика, бо не для люди́ни ця будова, а для Господа Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'А я всією своєю силою пригото́вив для храму свого Бога золото на золоті речі, і срібло — на срібні, і мідь — на мідяні, і залізо — на залізні, і дерево — на дерев\'я́ні, камі́ння шога́мське та до оправ, каміння нофе́хське та кольоро́ве, і всякий дорогий камінь та бе́зліч мармуро́вого камі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'І ще, через моє зами́лування до дому Бога мого, є в мене скарб власного золота та срібла, — і його я віддав для дому свого Бога, понад усе, що я заготовив для святого храму:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'три тисячі талантів золота, офі́рського золота, і сім тисяч очи́щеного срібла на покриття́ стін тих домів;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'на кожну золоту річ та на кожну срібну, і на всяку працю рукою майстрів. І хто ще же́ртвує, щоб сьогодні напо́внити свою́ ру́ку поже́ртвою для Господа?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'І стали же́ртвувати начальники ба́тьківських ро́дів та начальники Ізраїлевих племе́н, і тисячники та сотники, і начальники праці для царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'І дали́ вони на роботу Божого дому золота п\'ять тисяч тала́нтів та десять тисяч даре́йків, і срібла десять тисяч талантів, і міді десять тисяч і вісім тисяч талантів, а заліза сто тисяч талантів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'А в кого знайшло́ся при ньому дорогоцінне каміння, ті дали його до скарбни́ці Господнього дому, до руки Ґершонівця Єхіїла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'І раді́в народ за їхню жертву, бо вони же́ртвували Господе́ві з ці́лого серця, а також цар Давид радів великою радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'І поблагослови́в Давид Господа на оча́х усього збору. І сказав Давид: „Благословенний Ти, Господи, Боже Ізраїля, нашого батька, від віку й аж до віку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Твоя, Господи, могу́тність і сила, і ве́лич, і вічність, і слава, і все на небеса́х та на землі! Твої, Господи, ца́рства, і Ти підне́сений над усім за Голову!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'І бага́тство та слава — від Те́бе, і Ти пануєш над усім, і в руці Твоїй сила та хоро́брість, і в руці Твоїй — побільши́ти та зміцни́ти все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'А тепер, Боже наш, ми дякуємо Тобі, і славимо Ім\'я́ Твоєї ве́личі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'І хто бо я, і хто народ мій, що маємо силу так же́ртвувати, як це? Бо все це — від Тебе, і з Твоєї руки дали́ ми Тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Бо ми прихо́дьки перед лицем Твоїм та чужи́нці, як усі наші батьки́! Наші дні на землі — мов та тінь, і немає трива́лого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Господи, Боже наш, уся ця бе́зліч, яку ми нагото́вили на збудува́ння Тобі храму для Ймення Твоєї святости, — із Твоєї руки́ вона, і все це — Твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'І я знаю, Боже мій, що Ти виві́дуєш серце й любиш щирість. У щирості серця свого я поже́ртвував це все, а тепер бачу я з радістю наро́д Твій, який знахо́диться тут, що жертвує себе Тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Господи, Боже Авраама, Ісака та Якова, наших батькі́в, — збережи ж навіки цей на́прямок думо́к серця наро́ду Твого, і міцно скеру́й їхнє серце до Себе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'А моєму синові Соломонові дай серце ці́ле, щоб вико́нувати за́повіді Твої, свідо́цтва Твої та устави Твої, і щоб чинити все, і щоб збудувати цю тверди́ню, яку я пригото́вив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'І сказав Давид до всього збору: „Поблагословіть же Господа, вашого Бога!“І ввесь збір поблагословив Господа, Бога своїх батькі́в, — і нахили́лися, і вклонилися всі до землі Господе́ві й царе́ві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'І прине́сли вони для Господа жертви, і спалили цілопа́лення для Господа другого дня від того дня, — тисячу бичків, тисячу барані́в, тисячу ове́чок, і ливні їхні жертви, і бе́зліч жертов за всього Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'І вони їли й пили́ перед Господом того дня з великою радістю, і вдруге настанови́ли Соломона, Давидового сина, і пома́зали його́ Господе́ві на володаря, а Садо́ка на священика.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'І сів Соломо́н на Господньому тро́ні за царя на місці свого батька Давида, і щасти́ло йому, і його слухався ввесь Ізра́їль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'І всі князі́ та ли́царі, а також усі сини́ царя Давида піддали́ся під Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'І Господь ви́соко звели́чив Соломона на оча́х усього Ізраїля, і дав на нього вели́чність царства, якої не було перед ним ані на жодному царе́ві над Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'І Давид, син Єссе́їв, царюва́в над усім Ізра́їлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'А дні, що він царював над Ізраїлем, були сорок літ: у Хевро́ні царював він сім років, а в Єрусалимі царював тридцять і три.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'І поме́р він у добрій сивині́, ситий днями, бага́тством та славою, а замість нього зацарював син його Соломо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'А діла́ царя Давида, перші й останні, ось вони описані в історії прови́дця Самуїла, і в історії пророка Ната́на, і в історії прозорли́вця Ґада,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'ра́зом з усім царством його, і лица́рськістю його́ та часами, що перейшли над ним і над Ізраїлем, та над усіма́ царствами тих країв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'І зміцнився Соломо́н, син Давидів, над царством своїм, а Господь, Бог його, був із ним та ви́соко звели́чив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'І сказав Соломон до всього Ізраїля, до тисячників та сотників, і до су́ддів, і до всіх начальників, до всього Ізраїля, до голі́в ба́тьківських родів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'І пішли Соломон та ввесь збір із ним до па́гірка, що в Ґів\'оні, бо там була скинія Божого заповіту, яку зробив Мойсей, раб Господній, у пустині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Але Божого ковчега Давид переніс із Кір\'ят-Єаріму туди, де пригото́вив йому місце Давид, бо він поставив йому скинію в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'А мідяно́го же́ртівника, що зробив був Веселії́л, син Урії, сина Хурового, він поставив перед скинією Господньою. І звертався до нього Соломон та збір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'І зійшов Соломон туди перед Господнє лице на мідяний же́ртівник, що належав до скинії заповіту, і приніс на ньому тисячу цілопа́лень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Тієї ночі явився Бог Соломонові та й сказав йому: „Зажадай, чого дати тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'І сказав Соломон до Бога: „Ти зробив був велику милість з батьком моїм Давидом, і настановив царем мене замість ньо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Тепер, Господи, Боже, нехай буде ви́повнене слово Твоє до батька мого Давида, бо Ти настанови́в мене царем над народом числе́нним, як порох землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Дай тепер мені мудрість та знання́, щоб умів я вихо́дити й входити перед цим народом, бо хто зможе судити цей великий Твій наро́д?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'І сказав Бог до Соломона: „За те, що оце було на серці твоїм, і ти не жадав багатства, маєтків та слави, ані душі ворогів своїх, а також довгих днів не жадав ти, а жадав для себе мудрости та знання́, щоб судити народ Мій, над яким Я настанови́в тебе царем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'то дасться тобі мудрість та знання, а багатство, і маєтки та славу Я дам тобі такі, яких не було́ між царями перед тобою, і по тобі не бу́де таких!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'І прийшов Соломон із па́гірка, що в Ґів\'оні, до Єрусалиму, від скинії заповіту, і зацарював над Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'І зібрав Соломон колесни́ць та верхівці́в, — і було в нього тисяча й чотири сотні колесни́ць та дванадцять тисяч верхівці́в, і він порозмі́щував їх по колесни́чних містах та при царі в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'І цар зібрав в Єрусалимі срібла та золота, мов камі́ння, а ке́дрів зібрав, щодо числе́нности, як сикомо́р, що в Шефелі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'А ко́ней, що були в Соломона, приво́дили з Єгипту та з Кеве; царські купці́ купували їх з Кеве.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'І ходили вони, і вивозили з Єгипту колесни́цю за шість сотень срібла, а коня — за сотню й п\'ятдесят. І так вони виво́зили все це своєю рукою для всіх царів хіттійських та царів сирійських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'І Соломон наказав будувати дім для Господнього Ймення та дім царськи́й для се́бе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'І відлічив Соломон сімдеся́т тисяч чоловіка носії́в та вісімдеся́т тисяч чоловіка каменоте́сів у гора́х, а керівникі́в над ними — три тисячі й шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'І послав Соломон до Хірама, царя тирського, говорячи: „Як зробив ти у батьком моїм Давидом, і послав був йому ке́дри на будову дому його, щоб сидіти в ньому, так зроби й мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Ось я будую храм для Ймення Господа, Бога мого, щоб присвятити Йому́, щоб кадити перед Його лицем запашне́ кадило, і для постійного покла́дення хліба та для цілопа́лення на ранок і на вечір, на суботи й на молодики́ та на свята Господа, Бога нашого. Навіки це над Ізраїлем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'А храм, якого я будую, великий, бо Бог наш більший від усіх богів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'А хто має силу збудувати Йому храма, коли небо й небеса небес не обіймають Його? І хто я, що збудую Йому храма? Хіба тільки на каді́ння перед лицем Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'А тепер пошли мені чоловіка, здібного до роботи в золоті, і в сріблі, і в міді, і в залізі, і в пу́рпурі, і в че́рвені, і в блаки́ті, і що вміє вирізувати рі́зьби, ра́зом із тими мистця́ми, що зо мною в Юді та в Єрусалимі, яких пригото́вив батько мій Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'І пошли мені з Ливану де́рева ке́дрового, кипари́сового та санда́лового, бо я знаю, що твої раби вміють рубати дере́ва ливанські. І оце мої раби будуть рабами твоїми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'щоб нагото́вити мені бе́зліч дерева, бо цей храм, що я будую, буде великий та пишний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'А ось деревору́бам, що стинають дере́ва, рабам твоїм, дав я пшениці, як поживи, двадцять тисяч ко́рів, та ячменю двадцять тисяч ко́рів, і вина двадцять тисяч ба́тів, і оливи двадцять тисяч батів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'І сказав Хірам, цар тирський, листом і послав до Соломона: „Через любов Господа до народу Свого поставив Він тебе над ними за царя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'І сказав Хірам: „Благослове́нний Господь, Бог Ізраїлів, що вчинив небеса́ та землю, що дав цареві Давидові сина мудрого, який має розум та багатий на знання́, що збудує дім Господній та дім царський для се́бе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'А тепер я посилаю мудрого чоловіка, що має знання́, Хурам-Аві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'сина жінки з Данових дочо́к, — а батько його тиря́нин, — що вміє робити в золоті та в сріблі, в міді, в залізі, в каміннях та в дере́вах, у пу́рпурі й у блакиті, і в віссо́ні, і в че́рвені, і різати всяку різьбу, і вико́нувати всяку думку, що буде да́на йому з мистця́ми твоїми та з мистцями пана мого Давида, батька твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'А тепер пшеницю й ячмінь, оливу та вино, про які казав мій пан, нехай посилає своїм рабам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'А ми наруба́ємо дере́в із Ливану за всякою твоєю потребою, і спровадимо їх тобі плота́ми морем до Яфи, а ти спровадиш їх до Єрусалиму“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'І перелічи́в Соломон усіх людей прихо́дьків, що в Ізраїлевому Кра́ї, за переліком, що перелічив був їх його батько Давид, і було зна́йдено їх сто й п\'ятдесят тисяч і три тисячі й шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'І він зробив із них сімдеся́т тисяч носіїв та вісімдеся́т тисяч каменотесів у гора́х, та три тисячі й шість сотень керівників, що спону́кували той наро́д до праці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'І зачав Соломон будувати Господній дім в Єрусалимі на горі Морі́йя, що вказана була батькові його Давидові, на місці, яке пригото́вив Давид на то́ці євусеянина Орнана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'І зачав він будувати другого місяця, другого дня, четвертого року свого царюва́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'А це основа будови Божого дому: довжина́ — шістдеся́т лі́ктів старою мірою, а ширина́ — двадцять ліктів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'А притво́р, щодо довжини, був за шириною храму, двадцять ліктів, а вишина́ — сто й двадцять. І покрив він його зсере́дини чистим золотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'А великий храм він покрив кипари́совим деревом, і покрив його добрим золотом, і наробив на ньому пальм та ланцюгі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'І покрив він той храм дорогим ка́менем на оздо́бу, а золото — золото було з Парваїму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'І покрив він золотом храм, балки, пороги, і стіни його та його двері, а на стінах повирі́зував херувимів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'І зробив дім Святого Святих: довжина його за шириною храму — двадцять ліктів, і ширина його — двадцять ліктів. І покрив він його добрим золотом, на таланти — шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'А вага цвяхів на шеклі золота — п\'ятдеся́т; і го́рниці покрив золотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'І зробив він у домі Святого Святих двох херувимів різьб\'яно́ю роботою, і покрив їх золотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'А кри́ла херувимів: довжина їх — двадцять ліктів, крило́ одно́го — на п\'ять ліктів, дотика́лося стіни храму, а крило інше — п\'ять ліктів, дотикалося крила другого херувима.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'А крило́ другого херувима — п\'ять ліктів, дотика́лося стіни́ храму, а крило інше — п\'ять ліктів, прилягало до крила іншого херувима.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Розтягнені крила цих херувимів — двадцять ліктів; і вони стояли на нога́х своїх, а їхні обличчя — до храму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'І зробив він завісу, — блаки́ть, і пу́рпур, і че́рвень, і віссо́н, і наробив на ній херувимів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'І зробив він перед храмом два стовпи́, тридцять і п\'ять ліктів завдо́вжки, а ма́ковиці, що на верху́ його, п\'ять ліктів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'І поробив ланцюги́, як у девірі, і дав їх на верхи́ тих стовпі́в. І зробив сотню грана́тових яблук, і дав на ланцюги́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'І поставив стовпи́ перед храмом, — один з правиці, а один з лівиці. І назвав ім\'я́ правому: Яхін, а ім\'я лівому — Боаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'І зробив мідяного же́ртівника, двадцять ліктів довжина́ йому і двадцять ліктів ширина́ йому, і десять ліктів височина́ йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'І зробив він лите море, десять на міру ліктем від кра́ю його до краю його, навколо кругля́сте, і п\'ять на міру ліктем височина́ йому. А шнур — тридцять на міру ліктем — ото́чував його навко́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'А під ним — постать волі́в, що зо всіх сторін ото́чують його, на десять ліктів на міру ліктем оточують море навко́ло; два ряди волів відлиті при відлива́нні його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Воно стояло на дванадцятьо́х вола́х, — три обе́рнені на пі́вніч, і три обернені на за́хід, і три обернені на пі́вдень, і три обернені на схід. А море на них зве́рху, а всі зади їх — до нутра́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'А грубина́ його — долоня, а край його — як робота кра́ю ке́ліха, квітки ліле́ї. Містило воно три тисячі ба́тів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'І зробив десять умива́льниць, і поставив п\'ять з правиці, а п\'ять з лівиці, щоб мити в них, — пригото́влене на цілопа́лення поло́щуть у них, а море — для священиків, щоб митися в ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'І зробив десять золотих свічникі́в, як нале́жалося, і поставив їх у храмі п\'ять з правиці, а п\'ять з лівиці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'І зробив десять столів, і поставив у храмі, — п\'ять з правиці, а п\'ять з лівиці. І зробив сто золотих кропи́льниць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'І зробив священиче подві́р\'я та подвір\'я велике, і двері до подвір\'я, і їхні двері покрив міддю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'А море поставив з правого боку на південний схід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'І поробив Хурам го́рнята, і лопа́тки, і кропильниці. І покінчи́в Хурам робити працю, яку зробив для царя Соломона в Божому домі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'два стовпи́, і ку́лі, і дві ма́ковиці на верху́ тих стовпі́в, і дві мере́жки на покриття́ оби́двох куль ма́ковиць, що на верха́х стовпів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'і чотири сотні грана́тових яблук для обох мере́жок, два ряди грана́тових яблук для однієї мережки, щоб покрити оби́дві кулі ма́ковиць, що на пе́реді тих стовпі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'І поробив підста́ви, і поробив умива́льниці на тих підста́вах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'одне море, і дванадцять волів під ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'і горня́та, і лопа́тки, і виде́льця, і всі їхні речі поробив Хурам-Авів цареві Соломонові для Господнього дому з ви́поліруваної міді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'На Йорда́нській рівни́ні повідлива́в їх цар у гли́нистій землі між Суккотом та між Цередою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'І наробив Соломон усіх цих речей дуже багато, бо не дослі́джена була вага міді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'І поробив Соломон усі речі, що в Божому домі, та золотого же́ртівника й столи, а на них — хліб показни́й,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'і свічники́, і їхні лямпа́дки, щоб запалювати їх за постановою перед девіром, — зо щирого золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'А квітки́, і лямпа́дки, і щи́пчики — із золота, з доскона́лого золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'А но́жиці, і кропильниці, і ло́жки, і кадильниці — зо щирого золота; а вхід до дому, його внутрішні двері до Святого Святих та двері дому до храму — із золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 23, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'І була закі́нчена вся праця, яку зробив Соломон для Господнього дому. І Соломон повно́сив освячені речі свого батька Давида, і срібло́, і золото, і всі ці речі дав до скарбни́ці Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Тоді Соломон зібрав до Єрусалиму Ізраїлевих старши́х, і всіх голі́в племе́н, начальників ба́тьківських родів Ізраїлевих синів, щоб перене́сти ковчега Господнього заповіту з Давидового Міста, воно — Сіо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'І були зі́брані до царя всі ізра́їльтяни в свято, воно — сьо́мого місяця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'І поприхо́дили всі Ізраїлеві старші́, і Левити поне́сли ковчега.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'І поне́сли ковчега та скинію заповіту, і всі святі речі, що в скинії, — не́сли їх священики та Левити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'А цар Соломон та вся Ізраїлева громада, що зібралася при ньому перед ковчегом, прино́сили в жертву худобу дрібну́ та худобу велику, що через многоту́ не була ані запи́сувана, ані лі́чена!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'І священики внесли ковчега Господнього заповіту до його місця, до девіру дому, до Святого Святих, під кри́ла херувимів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'А херувими простяга́ли крила над місцем ковчега, і затінювали херувими над ковчегом та над його держака́ми зве́рху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'А ті держаки́ були довгі, і головки тих держакі́в були видні з ковчегу, що перед девіром, а назо́вні не були видні. І були вони там аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'У ковчезі не було нічого, тільки дві табли́ці, що поклав Мойсей на Хори́ві, коли Господь склав був заповіта з Ізраїлевими синами при виході їх із Єгипту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'І сталося, як священики вихо́дили із святині, — а всі священики, що були там, освятилися, без доде́ржання черг, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'а Левитн співаки́, — усі вони, аж до Асафа, Гемана, Єдутуна, і синів їхніх та братів їхніх, — убрані в віссо́н, з цимба́лами, із а́рфами та з ци́трами, стояли на схід від же́ртівиика, а з ними сто й двадцять священиків, що сурми́ли на су́рмах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'і було воно для сурмачі́в та співаків як одне, щоб подати один голос на хвалу́ та дяку Господе́ві, і як загримів голос на су́рмах, і на цимба́лах, і на музичних знаря́ддях, і як хвалили Господа: „Добрий бо Він, бо навіки Його милосе́рдя!“, — то дім, дім Господній наповнився хмарою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'І не могли священики стояти й служити через ту хмару, бо слава Господня напо́внила дім Божий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Тоді Соломон проказав: „„Промовив Господь, що Він пробува́тиме в мряці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'А я збудува́в храм оселі Твоєї, і місце Твого́ пробува́ння навіки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'І повернув цар обличчя своє, та й поблагословив увесь Ізраїлів збір, увесь же Ізраїлів збір стояв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'А він сказав: „Благословенний Госпо́дь, Бог Ізраїлів, що Своїми устами говорив був із моїм батьком Давидом, і руками Своїми ви́конав, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Від того дня, коли Я вивів Свій народ з єгипетського кра́ю, Я не вибрав Собі міста зо всіх Ізраїлевих племе́н, щоб збудувати храм на пробува́ння Мого Імени там. І не вибрав Я ніко́го, щоб був володарем над народом Моїм, Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Та вибрав Я Єрусали́м на пробува́ння Мого Імени там, і вибрав Я Давида, щоб був над народом Моїм, Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'І було на серці мого батька Давида збудува́ти храм для Ймення Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Та сказав Господь до мого батька Давида: За те, що на твоє́му серці було збудувати храм для Ймення Мого, ти зробив добре, що було тобі на серці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Тільки ти не збудуєш цього храму, але син твій, що вийде із сте́гон твоїх, — він збудує цей храм для Ймення Мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'І спо́внив Госпо́дь Своє слово, що Він говорив. І став я замість батька свого Давида та й сів на Ізраїлевому троні, як говорив був Господь, і я збудував оцей храм для Ймення Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'І поставив я там ковчега, що в ньому Господній заповіт, якого Він склав з Ізраїлевими сина́ми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'І став він перед Господнім же́ртівником навпроти всього Ізраїлевого збору, і простяг свої ру́ки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'А Соломон зробив був мідяне́ стоя́ло, і поставив його на сере́дину подві́р\'я, — п\'ять ліктів довжина йому, і п\'ять ліктів ширина йому, а три лікті вишина йому. І став він на ньому, і став на коліна свої навпроти всього Ізраїлевого збору, і простяг свої руки до неба,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'та й сказав: „Господи, Боже Ізраїлів! Нема подібного Тобі Бога на небі та на землі! Ти стереже́ш заповіта та милість для Своїх рабів, що ходять перед Твоїм лицем усім своїм серцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ти спо́внив Своєму рабові Давидові, батькові моєму, те, що говорив йому. І говорив Ти йому Своїми устами, а рукою Своєю ви́повнив, як цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'А тепер, Господи, Боже Ізраїлів, спо́вни для Свого раба Давида, мого батька, те, що говорив Ти йому, кажучи: Не переведе́ться з-перед лиця Мого ніхто з тих, що мають сидіти на Ізраїлевому троні, якщо тільки сини твої будуть доде́ржувати своїх доріг, щоб ходити в Зако́ні Моїм, як ти ходив перед лицем Моїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'А тепер, Господи, Боже Ізраїлів, нехай буде запе́внене слово Твоє, яке Ти говорив рабові Своєму Давидові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Бо чи ж справді Бог сидить з люди́ною на землі? Ось небо та небо небе́с не обіймають Тебе, — що́ ж тоді храм цей, що я збудував?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'І Ти зве́рнешся до молитви Свого раба та до його блага́ння, Господи, Боже мій, щоб почути по́клик та молитву, якою раб Твій мо́литься перед лицем Твоїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'щоб очі Твої були відкриті на цей храм удень та вночі, на те місце, про яке Ти сказав, що покладе́ш Ім\'я́ Своє там, щоб почути молитву, якою буде моли́тися Твій раб на цьому місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'І Ти бу́деш прислуха́тися до блага́нь Свого раба та Свого народу, Ізраїля, що будуть молитися на цьому місці. І Ти почуєш із місця Свого пробува́ння, із небе́с — і почуєш, і пробачиш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Якщо згрішить люди́на проти свого бли́жнього, і буде примушена прине́сти клятву, щоб присягнути, і клятва при́йде перед Твоїм же́ртівником у цьому храмі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'то Ти почуєш із небе́с, і зробиш, і розсу́диш Своїх рабів, — обвинува́тиш несправедливого, щоб дати його дорогу на його го́лову, й усправедли́виш справедливого, щоб дати йому за його справедливістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'А якщо Твій наро́д, Ізра́їль, бу́де вда́рений ворогом, бо прогрішив Тобі, і коли вони зве́рнуться, і бу́дуть хвалити Ім\'я́ Твоє, і будуть молитися, і будуть благати Тебе в цьому храмі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'то Ти почуєш із небе́с, і про́стиш гріх народу Свого, Ізраїля, і ве́рнеш їх до землі, яку дав Ти їм та їхнім батькам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Коли затримається небо, і не буде дощу, бо прогріша́ться Тобі, то вони помоляться на цьому місці, і будуть сла́вити Ім\'я́ Твоє, — і з гріха́ свого наве́рнуться, бо Ти будеш їх впокоря́ти, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'то Ти почу́єш на небеса́х, і пробачиш гріх Своїх рабів та народу Свого, Ізраїля, бо покажеш їм ту добру дорогу, якою вони пі́дуть, і Ти даси дощ на Край Свій, якого Ти дав Своєму наро́дові на спа́дщину!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Голод коли бу́де в Краю́, морови́ця коли буде, посу́ха, жовта́чка, сарана́, черва́ коли буде, коли його вороги гноби́тимуть його́ в Краї міст його, коли буде яка пора́за, яка хвороба, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'усяка молитва, усяке блага́ння, що буде від якої люди́ни чи від усього наро́ду Твого́, Ізраїля, коли кожен буде знати пора́зу свою та горе своє, і простя́гне руки свої до цього храму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'то Ти почуєш із небе́с, із місця постійного пробува́ння Свого́, — і пробачиш, і даси тому чоловікові за всіма́ його дорогами, бо Ти знаєш серце його, бо Ти один знаєш серце лю́дських синів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'щоб вони боялися Тебе, і ходили Твоїми дорогами по всі дні, які вони житимуть на поверхні землі, яку Ти дав батька́м нашим!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Також і чужи́нця, який не з наро́ду Твого, Ізраїля, і він при́йде з далекого кра́ю ради Йме́ння Твого́ великого, і руки́ Твоєї Сильної та раме́на Твого ви́тягненого, і при́йде, і помо́литься в цьому храмі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'то Ти почуєш це з небе́с, місця постійного пробува́ння Свого, і зробиш усе, про що буде кликати до Тебе той чужи́нець, щоб усі наро́ди землі пізнали Ім\'я́ Твоє, та щоб боялися Тебе, як народ Твій, Ізра́їль, і щоб пізнали вони, що Ім\'я́ Твоє покликане над оцім храмом, що я збудував!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Коли народ Твій ви́йде на війну на своїх ворогів, доро́гою, якою Ти пошле́ш їх, і помо́ляться вони до Тебе в напрямі до цього міста, що Ти вибрав його, та храму, що я збудував для Ймення Твого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'то почуєш Ти з небе́с їхню молитву та їхнє блага́ння, — і вчиниш їм суд!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Коли вони згріша́ть Тобі, — бо немає люди́ни, щоб вона не згріши́ла, — і Ти розгніваєшся на них, і даси їх во́рогові, а їхні поневі́льники ві́зьмуть їх до неволі до кра́ю далекого чи близько́го,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'і коли вони при́йдуть до розуму в краю́, куди взяті до неволі, і наве́рнуться, і бу́дуть блага́ти Тебе в краю́ своєї неволі, говорячи: Ми згрішили, скривили дорогу свою, і були ми несправедливі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'і коли вони наве́рнуться до Те́бе всім своїм серцем і всією́ душею своєю в краю́ своєї неволі, куди їх понево́лили, і помоляться в напрямі до свого Кра́ю, що Ти дав їхнім батькам, і в напрямі міста, яке Ти вибрав, та храму, що я збудував для Ймення Твого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'то Ти почуєш із небе́с, із постійного місця пробува́ння Свого́, їхню молитву та їхні блага́ння, і вчи́ниш їм суд, і про́стиш Своє́му наро́дові, що вони згрішили Тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Тепер, Боже мій, благаю, нехай будуть очі Твої відкриті, а уші Твої наста́влені на слу́хання молитви цього місця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'А тепер, — Устань же, о Господи, Боже, на Свій відпочи́нок, Ти й ковчег сили Твоєї! Священики Твої, о Господи Боже, нехай у спасі́ння зодя́гнуться, а побо́жні Твої хай добром веселя́ться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Господи Боже, не відве́ртай лиця від Свого́ помазанця, згадай же про милість Своєму рабові Давиду!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'А коли Соломон закінчи́в молитися, то зійшов огонь із небе́с, поїв цілопа́лення та жертви, а слава Господня напо́внила храм той!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'І священики не могли ввійти до Господнього дому, бо слава Господня напо́внила дім Господній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'А всі Ізраїлеві сини бачили, як схо́див огонь та Господня слава на храм той, і вони попа́дали обли́ччям до землі на підло́гу з камінних плит, і вклони́лися до землі, і дякували Господе́ві: „Добрий бо Він, бо навіки Його милосе́рдя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'А цар та ввесь народ прино́сили жертву перед Господнім лицем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'І приніс цар Соломон на жертву худоби великої двадцять і дві тисячі, а худоби дрібно́ї — сто й двадцять тисяч. І ви́конали обряд освя́чення Божого дому цар та ввесь наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'А священики стояли на ва́ртах своїх, а Левити — зо знаря́ддями Господньої пісні, що поробив цар Давид на подяку Господе́ві, „Бо навіки Його милосердя“, коли Давид хвалив ними; і священики сурми́ли навпроти них, а ввесь Ізраїль стояв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'І посвятив Соломон сере́дину подві́р\'я, що перед Господнім домом, бо приніс там цілопа́лення та лій мирних жертв, бо мідяний же́ртівник, якого зробив Соломон, не міг умістити цілопа́лення й хлібної жертви та лою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'І справив Соломон того ча́су те свято на сім день, а ввесь Ізра́їль був з ним, дуже великий збір, що зійшовся звідти, де йдеться до Хамату, аж до єгипетського потоку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'А восьмого дня спра́вили відда́ння свята, бо обряд освя́чення же́ртівника справляли сім день, і свято сім день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'А дня двадцятого й третього сьо́мого місяця відпустив він народ до їхніх наметів, радісних та веселосердих через усе те добро, що Господь учинив Давидові й Соломонові, та народові Своєму Ізраїлеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'І закінчив Соломон дім Господній та дім царськи́й, та все, що прихо́дило Соломонові на серце, щоб зробити в Господньому домі та в домі своєму, пощасти́ло йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'І явився Господь Соломонові вночі та й сказав йому: „Вислухав Я моли́тви твої, та вибрав оце місце для Себе на храм жертви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Якщо Я замкну́ небеса́, і не буде дощу, і якщо накажу́ сарані́ поїсти землю, і якщо нашлю́ морови́цю на наро́д Мій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'і впокоря́ться люди Мої, що над ними кличеться Ім\'я́ Моє, і помо́ляться, і бу́дуть шукати Ім\'я́ Мого́, і повернуть зо злих своїх доріг, то Я вислухаю з небе́с, і прощу́ їхній гріх, та й вилікую їхній Край!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Тепер очі Мої будуть відкриті, а уші Мої наста́влені на слу́хання моли́тви цього місця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'І тепер Я вибрав, і освятив цей храм, щоб Ім\'я́ Моє було там аж навіки, Мої ж очі та серце Моє бу́дуть там по всі дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'А тепер, якщо бу́деш ходити перед лицем Моїм, як ходив був ба́тько твій Давид, щоб зробити все, що наказа́в Я тобі, і якщо бу́деш дотри́муватися уставів Моїх та прав Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'то поста́влю певно трона царства твого, як склав Я заповіта з батьком твоїм Давидом, говорячи: Не буде в тебе перево́ду ніко́му з пануючих в Ізраїлі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'А якщо ви відве́рнетеся та покинете устави Мої й заповіді Мої, що Я дав вам, і пі́дете, і будете служити іншим бога́м, і бу́дете вклонятися їм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'то Я повирива́ю їх з Моєї землі, яку дав їм, а цей храм, що Я освятив для Ймення Свого, відкину від лиця Свого, і дам його за припові́стку та за посміхо́вище серед усіх наро́дів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'А храм цей, що був найвищий, — кожен, хто прохо́дитиме біля нього, скам\'яні́є та й скаже: За що́ Господь зробив так цьому Кра́єві та храму цьому?...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'І відкажуть: За те, що вони покинули Господа, Бога батьків своїх, Який вивів їх з єгипетського кра́ю, і держа́лися міцно інших богі́в, і вклоня́лися їм, і служили їм, — тому́ Він навів на них усе оце ли́хо!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'І сталося по двадцятьо́х ро́ках, коли Соломо́н будував дім Господній та свій дім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'то міста́, які дав Хура́м Соломо́нові, Соломон розбудува́в їх, і осади́в там Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'І пішов Соломон до Хават-Цови, і переміг її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'І збудував він Тадмора в пустині, та всі міста для запа́сів, що побудував у Хаматі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'І побудував він Бет-Хорон горі́шній та Бет-Хорон до́лішній, тверди́нні міста́, — му́ри, двері та за́суви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'і Баалат, і всі міста для запа́сів, що були в Соломона, і всі міста́ для колесни́ць, і міста́ для верхівці́в, і всяке пожада́ння Соломона, що жадав він збудувати в Єрусалимі й на Ливані, та в усьому Кра́ї його панува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Увесь наро́д, позоста́лий з хітте́ян, і з аморе́ян, і з періззе́ян, і з хівве́ян, і з євусе́ян, що вони не з Ізраїля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'з їхніх сині́в, що зоста́лися по них у Краї, що їх не повигу́блювали Ізраїлеві сини, то їх Соломон узяв на дани́ну, і це позоста́лося аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'А Ізра́їлевих синів Соломон не робив рабами для своєї праці, але́ вони були військо́ві, і зве́рхники сторо́жі його, і зве́рхники колесни́ць його та його верхівці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'І оце вони були зве́рхники намі́сники царя Соломона, — двісті і п\'ятдеся́т, що панували над наро́дом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'А фараонову дочку́ перевів Соломон із Давидового Міста до дому, що збудував для неї, як сказав: „Не буде сидіти мені жінка в домі Давида, Ізраїлевого царя, бо святий він, бо Господній ковчег увійшов у нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Тоді Соломон прині́с цілопа́лення для Господа на Господньому же́ртівнику, якого він збудував перед притво́ром,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'щоб за потребою кожного дня прино́сити жертву за Мойсеєвим нака́зом, на суботи, і на молодики́, і на свята три ра́зи в році: в свято Опрі́сноків, і в свято Тижнів, і в свято Кучок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'І поставив він, за розпоря́дком Давида, батька свого, че́рги священиків на їхню службу, і Левитів на їхніх ва́ртах на хвалу́ та на службу відповідно до священиків за потребою кожного дня, і придве́рних в їхніх черга́х для кожної брами, бо такий був нака́з Давида, Божого чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'І не відступали вони від нака́зів царя про священиків та Левитів, щодо всякої речі й щодо ска́рбів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'І була зро́блена вся Соломонова праця аж до цього дня, від зало́ження Господнього дому й аж до закі́нчення його, коли був закі́нчений дім Господній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Тоді пішов Соломон до Ецйон-Ґеверу та до Елоту над мо́рським берегом в едо́мському кра́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'І прислав йому Хура́м через своїх рабів кораблі́ та рабів, що знали море. І прийшли вони з Соломоновими рабами до Офіру, і взяли́ звідти чотири сотні й п\'ятдеся́т талантів золота, і приве́зли до царя Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'А цариця Шеви почула була́ про славу Соломонову, і прийшла ви́пробувати Соломона зага́дками в Єрусалимі. Прийшла вона з дуже великим бага́тством, — із верблю́дами, що не́сли па́хощі та бе́зліч золота й дорогого камі́ння. І прийшла вона до Соломона, і говорила з ним про все, що було́ на серці її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'І Соломон вияснив їй усі її за́пити, і не було за́питу, незна́ного Соломонові, якого не порішив би він їй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'І побачила цариця Шеви всю Соломонову мудрість та дім, що він збудува́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'і їжу сто́лу його, і ме́шкання рабів його, і поставу слуг його та їхні одежі, і ча́шників його, та їхні одежі, і вхід його, яким він ухо́дить до Господнього дому, — і не могла вона з дива вийти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'І сказала вона до царя: „Правдою було те, що я чула в своїм кра́ї про твої діла та про твою мудрість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'І не повірила я їхнім слова́м, аж поки сама́ не прийшла та не побачили мої очі, — і ось не була́ предста́влена мені й половина великости твоєї мудрости: ти переви́щив славу, про яку я чула!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Щасливі люди твої, і щасливі оці твої слу́ги, що за́вжди стоять перед обличчям твоїм та слухають твою мудрість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Нехай буде благослове́нний Госпо́дь, Бог твій, що вподо́бав тебе́, щоб посадити тебе́ на Свого тро́на за царя у Го́спода, Бога твого, через любов Бога твого до Ізра́їля, щоб утверди́ти його навіки. І Він настанови́в тебе над ними царем, щоб чинити право та справедливість!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'І дала́ вона царе́ві сто й двадцять талантів золота, і дуже багато па́хощів та дороге́ камі́ння. І більш уже не було таких па́хощів, як ті, що цариця Шеви дала́ царе́ві Соломо́нові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'І також Хура́мові раби та раби Соломонові, що дово́зили золото з Офіру, спрова́джували алму́ґове дерево та дороге́ камі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'І пороби́в цар з алмуґового де́рева схо́ди для Господнього дому та для дому царсько́го, і гу́сла, і а́рфи для співакі́в. І такі речі, як вони, не ба́чені перед тим в юдейському Кра́ї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'А цар Соломон дав цариці Шеви все бажа́ння її, чого вона бажа́ла, окрім такого, що вона приве́зла до царя. І пішла вона назад до свого кра́ю, вона та слу́ги її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'І була вага того золота, що прихо́дило для Соломона в одно́му році, шість сотень і шістдеся́т і шість талантів золота,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'окрім того, що прихо́дило від купців та з торго́влі ходя́чих. І всі царі ара́бські та намі́сники Кра́ю дово́зили золото й срібло Соломо́нові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'І зробив цар Соломон дві сотні великих щитів із кутого золота, — шість сотень шеклів кутого золота йшло на одно́го щита,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'та три сотні щитів менших із кутого золота, — три сотні шеклів золота йшло на одно́го щита. І цар віддав їх до дому Ливанського Лісу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'І зробив цар великого тро́на зо слоно́вої кости, і покрив його чистим золотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'У тро́на було шість схі́дців та підні́жжя з золота позад трону, та пору́ччя з цього й з того боку при місці сиді́ння, та два леви, що стояли при пору́ччях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'І дванадцять левів стояли там на шости ступеня́х з того й з того боку. По всіх царствах не було так зро́бленого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'І ввесь по́суд на пиття́ царя Соломона — золото, і всі речі дому Ливанського Лісу — щире золото, нічого з срібла, — воно за Соломонових днів не рахувалося за щось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Бо царе́ві кораблі ходили до Таршішу з Хурамовими рабами. Раз на три роки прихо́дили таршіські кораблі, що дово́зили золото та срібло, слоно́ву кість, і ма́вп та па́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'І став цар Соломон найбільшим від усіх зе́мних царів, щодо багатства та щодо мудрости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'І всі земні царі хотіли бачити Соломона, щоб послу́хати його мудрости, що Бог дав у його серце.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'І вони прино́сили кожен свого да́ра, — речі срібні та речі золоті, й одежу, збро́ю та па́хощі, коні та мули, — що́ на рік припада́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'І було в Соломона чотири тисячі кі́нських жо́лобів та колесни́ць, і дванадцять тисяч верхівці́в, і він порозмі́щував їх по колесни́чних містах та при царі в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'І він панував над усіма́ царями від Річки й аж до кра́ю филисти́млян, і аж до єгипетської границі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'І Соломон наскладав в Єрусалимі срібла, мов того камі́ння, а кедрів наскладав, щодо числе́нности, як сикомо́ри, що в Шефелі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'А ко́ней приво́дили Соломонові з Єгипту та з усіх країв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'А решта Соломонових діл, перших та останніх, — ото вони описані в історії пророка Натана, і в пророцтві шілонянина Ахійї, і в виді́ннях прозорли́вця Єді на Єровоама, Неватового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'І царював Соломон в Єрусалимі над усім Ізраїлем сорок літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'І спочив Соломон зо своїми батька́ми, і поховали його в Місті Давида, батька його, а замість нього зацарював син його Рехав\'ам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'І пішов Рехав\'ам до Сихе́му, бо до Сихему зійшовся ввесь Ізраїль, щоб настанови́ти його царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'І сталося, як почув це Єровоа́м, Неватів син, — він був в Єгипті, куди втік від царя Соломона, — то вернувся Єровоам з Єгипту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'І послали й покликали його. І прийшов Єровоам та ввесь Ізра́їль, і вони говорили до Рехав\'ама, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '„Твій батько вчинив був тяжки́м наше ярмо́, а ти полегши́ жорсто́ку роботу батька свого та тяжке́ його ярмо, що наклав він був на нас, і ми бу́демо служити тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'А він відказав їм: „ Ідіть ще на три дні, і верніться до ме́не“. І пішов той наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'І радився цар Рехав\'а́м зо старши́ми, що стояли перед обличчям його батька Соломона, коли він був живий, говорячи: „Як ви радите відповісти́ цьому́ наро́дові?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'І вони говорили йому, кажучи: „Якщо ти будеш добрим для цього наро́ду, і зробиш за волею їх, і говори́тимеш їм добрі слова́, то вони будуть тобі раба́ми по всі дні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Та він відкинув пораду старши́х, що радили йому, і радився з молодика́ми, що ви́росли ра́зом із ним, що стояли перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'І сказав він до них: „Що́ ви радите, і що́ відповімо́ цьому́ наро́дові, який говорив мені, кажучи: Полегши́ ярмо́, яке твій ба́тько наклав був на нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'І говорили з ним ті молодики́, що виросли з ним, кажучи: „Так скажеш тому наро́дові, що промовляв до тебе, говорячи: „Твій ба́тько вчинив був тяжки́м наше ярмо́, а ти дай поле́гшу нам.“Отак скажеш до них: Мій мізи́нець грубілий за сте́гна мого батька!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'А тепер: мій батько наклав був на вас тяжке́ ярмо, а я доба́влю до вашого ярма! Батько мій карав вас бича́ми, а я би́тиму скорпіо́нами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'І прийшов Єровоам та ввесь народ до Рехав\'ама третього дня, як цар говорив, кажучи: „Верніться до мене третього дня“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'І цар жорсто́ко відповів їм. І відкинув цар Рехав\'ам пораду старши́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'і говорив до них за порадою тих молодикі́в, кажучи: „Мій батько вчинив був тяжки́м ваше ярмо, а я добавлю до нього! Батько мій карав вас бичами, а я — скорпіонами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'І не послухався цар наро́ду, бо це спричи́нене було від Бога, — щоб спра́вдити Господе́ві слово Своє, яке Він говорив був через шілонянина Ахійю, Неватового сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'І побачив увесь Ізраїль, що цар не послухався їх, і народ відповів царе́ві, кажучи: „Яка нам части́на в Давиді? І спа́дщини нема нам у сині Єссе́я! Усі до наметів своїх, о Ізраїлю! Позна́й тепер дім свій, Давиде!“І пішов увесь Ізраїль до наметів своїх...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'А Ізраїлеві сини, що сиділи в Юдиних містах, — то над ними зацарюва́в Рехав\'ам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'І послав цар Рехав\'ам Гадорама, що був над дани́ною, та Ізра́їлеві сини закидали його камі́нням, і він помер. А цар Рехав\'ам поспішив сісти на колесни́цю та втекти́ до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'І відпав Ізраїль від Давидового дому, і так є аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'І прийшов Рехав\'а́м до Єрусалиму, і зібрав дім Юдин та Веніяминів, сто й вісімдесят тисяч ви́браних військо́вих, щоб воювати з Ізраїлем, щоб вернути царство Рехав\'амові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'І було Господнє слово до Шемаї, чоловіка Божого, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '„Скажи Рехав\'амові, Соломо́нову синові, царе́ві Юдиному, та всьому Ізраїлеві в Юді та в Веніямині, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Так сказав Господь: Не йдіть і не воюйте з своїми брата́ми! Верніться кожен до дому свого́, бо ця річ сталася від Мене!“І вони послу́халися Господніх слів, і вернулися з похо́ду на Єровоама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'І осівся Рехав\'ам в Єрусалимі, і побудував тверди́нні міста в Юді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'І збудував він Віфлеєма, і Етама, і Текою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'і Бет-Цура, і Сохо, і Адуллама,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'і Ґата, і Марешу, і Зіфа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'і Адораїма, і Лахіша, і Азеку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'і Цор\'у, і Айялона, і Хеврона, що в Юді та в Веніямині, міста тверди́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'І зміцнив він ті тверди́ні, і дав у них начальників, і запаси, і оливи, і вина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'а до кожного окремого міста — великі щити́ та ра́тища, і дуже сильно їх позмі́цнював. І був його Юда та Веніямин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'А священики та Левити, що були в усьому Ізраїлі, зібралися до нього з усієї їхньої границі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Бо Левити кидали пасови́ська свої та власність свою, і прихо́дили до Юди та до Єрусалиму, бо Єровоам та сини його усунули їх від священичого служі́ння Господе́ві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'і понаставля́ли собі священиків для па́гірків та демонів, та для тельці́в, що він понаро́блював.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'А за ними, зо всіх Ізраїлевих племе́н ті, що віддавали своє серце шукати Господа, Бога Ізраїля, прихо́дили до Єрусалиму прино́сити жертви Господе́ві, Богові батьків своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'І зміцни́ли вони Юдине царство, і підси́лили Рехав\'а́ма, Соломонового сина, на три роки, бо вони ходили три роки дорогою Давида та Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'І взяв собі Рехав\'ам жінку Махалат, дочку́ Єрімота, Давидового сина, та Авіхаїл, дочку́ Еліава, Ісаєвого сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'І вона породила йому синів: Єуша, і Шемарію, Загама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'А по ній він узяв Мааху, дочку́ Авесаломову, і вона породила йому Авійю, і Аттая, і Зізу, і Шеломіта.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'І покохав Рехав\'ам Мааху, Авесаломову дочку́, над усіх жіно́к своїх та наложниць своїх, бо він узяв вісімнадцять жіно́к та шістдеся́т наложниць, і породив двадцять і вісім синів та шістдеся́т дочо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'А за го́лову Рехав\'ам поставив Авійю, Маахиного сина, за володаря серед братів його, бо він хотів настанови́ти його царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'І мудро він чинив, і порозсилав усіх синів своїх до всіх країв Юди й Веніямина, до всіх тверди́нних міст, і дав їм багате утри́мання, і підшукав їм багато жіно́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'І сталося, як зміцніло Рехав\'амове царство й став він си́льний, то покинув він, і ввесь Ізраїль із ним, Господнього Зако́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'І сталося п\'ятого року царя Рехав\'ама, пішов Шішак, єгипетський цар, на Єрусали́м, — бо вони спроневі́рилися Господе́ві, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'з тисячею й двомаста́ми колесни́ць та з шістдесятьма́ тисячами верхівці́в: і не було числа для наро́ду, що прийшов із ним з Єгипту, — ливіянам, суккійянам та кушанам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'І здобув він тверди́нні міста, що в Юді, і прийшов аж до Єрусали́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'А пророк Шемая прийшов до Рехав\'ама та Юдиних зверхників, що зібралися до Єрусалиму, утікаючи перед Шішаком, та й сказав до них: „Так сказав Госпо́дь: Ви залишили Мене, а тому Я залишив вас і видав у Шішакову руку“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'І впокори́лися Ізраїлеві зверхники та цар і сказали: „Справедливий Господь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'А коли Господь побачив, що вони впокори́лися, то було Господнє слово до Шемаї, говорячи: „Упокори́лися вони, — не нищитиму їх, але́ дам їм трохи людей на порятунок, і не виллється гнів Мій на Єрусали́м через Шішака.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Бо вони стануть йому за рабів, та й пізнають тоді службу Мені та службу царствам зе́мним“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'І вийшов Шішак, єгипетський цар, на Єрусалим, і забрав ска́рби Господнього дому та ска́рби дому царе́вого, — і все позабирав. І забрав він золоті щити́, що Соломон поробив був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'А цар Рехав\'ам поробив замість них мідяні щити́, і склав їх на руки зверхника сторожі́в, що стерегли́ вхід до царсько́го дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'І бувало, як тільки цар ішов до Господнього дому, прихо́дили бігуни́, та й носили їх, а потім вертали їх до комори бігуні́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'А коли він впокори́вся, то відвернувся від нього Господній гнів, і не знищив його аж до вигу́блення. Та й у Юдеї були ще справи добрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'І зміцнився цар Рехав\'ам в Єрусалимі й царював. А Рехав\'ам був віку сорока́ й одного року, коли зацарював, і царював він сімнадцять літ в Єрусалимі, у тому́ місті, яке вибрав Господь зо всіх Ізраїлевих племе́н, щоб покласти там Своє Ймення. А ім\'я́ його матері — аммонітка Наама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'І робив він лихе́, бо не схиляв свого серця, щоб звертатися до Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'А Рехав\'амові діла́, перші й останні, ото вони описані в історії пророка Шемаї та прозорливця Іддо: „Родословні книги“. І точилися ві́йни поміж Рехав\'амом та Єровоамом по всі дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'І спочив Рехав\'ам зо своїми батька́ми, і був він похований у Давидовому Місті, а замість нього зацарюва́в його син Авійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Вісімнадцятого року царя Єровоама та зацарював Авійя над Юдою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Три роки царював він в Єрусалимі. А ім\'я́ його матері — Міхая, дочка́ Уріїла з Ґів\'ї. І війна́ точилася між Авійєю та між Єровоамом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'I зачав Авійя війну́ з ві́йськом хоробрих воякі́в, — чотири сотні тисяч ви́браних мужів, а Єровоам приготовився до війни з ним з вісьмома́ сотнями тисяч ви́браних мужів, хоробрих воякі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'І встав Авійя з-над гори Цемараїм, що в Єфремових гора́х, та й сказав: „Послухайте мене, Єровоаме, та ввесь Ізраїлю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Чи ж не вам знати, що Господь, Бог Ізраїлів, дав Давидові царство над Ізраїлем навіки, йому́ та синам його, соляною умовою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Та встав Єровоам, Неватів син, раб Соломона, Давидового сина, і збунтувався на пана свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'І зібралися до нього люди пусті, нікчемні, і стали міцніші від Рехав\'ама, Соломонового сина. А Рехав\'ам був юнак та м\'якосердий, — і не був сильним проти них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'А тепер ви говорите, щоб бути сильними проти Господнього царства в руці Давидових синів, а вас велика кількість, і з вами золоті тельці, яких Єровоам понаро́блював вам за богів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Чи ж ви не повиганяли Господніх священиків, Ааро́нових синів, та Левитів? І понаставля́ли ви собі священиків, як ставлять наро́ди цих країв, — кожен, хто при́йде, щоб посвятитися молодим бичком та сімома́ баранами, то стає священиком для того, що не є Богом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'А ми, Бог наш — Господь, і ми не полишили Його, а наші священики, що служать Господе́ві, це Ааронові сини, а Левити — при службі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'І ми прино́симо Господе́ві цілопа́лення кожного ранку та кожного вечора, і запашне́ кадило, і уклада́ння хліба на чистому столі, і золотий свічник та лямпа́ди його, щоб запалювати кожного вечора, бо ми стереже́мо службу Господа, нашого Бога, а ви полишили Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'І ось з нами на чолі Бог, і священики Його, і голосні су́рми, щоб сурми́ти на вас. Ізраїлеві сини, — не воюйте з Господом, Богом вашим, бо вам не поведе́ться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'А Єровоам вирядив за́сідку, щоб пішла позад них, — і були вони перед Юдою, а за́сідка — позад них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'І обернулися юдеї, аж ось у них бій спе́реду та зза́ду! І кли́кали вони до Господа, а священики сурми́ли в су́рми...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'І закричали юдеї. І сталося, як юдеї закричали, то Бог ударив Єровоама та всього Ізраїля перед Авійєю та перед Юдою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'І повтікали ізра́їльтяни перед Юдою, і Бог дав їх в їхню руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'І вдарили в них Авійя та народ його великою по́разою, і попа́дали трупи з Ізраїля, — п\'ять сотень тисяч ви́браних мужів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'І впокорилися Ізраїлеві сини того ча́су, а Юдині сини зміцніли, — бо опиралися на Господа, Бога їхніх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'І гнався Авійя за Єровоамом, і здобув від нього міста́: Бет-Ел та залежні його міста, і Єшану та залежні її міста, і Ефрон та залежні його міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'І Єровоам не затримав сили вже за днів Авійї. І вдарив його Господь, і він помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'І зміцнився Авійя, і взяв собі чотирна́дцять жіно́к, і породив двадцять і двоє синів та шістнадцятеро дочо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'А решта Авійєвих діл, і дороги його та слова́ його описані в історії пророка Іддо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'І спочив Авійя зо своїми батька́ми, і поховали його в Давидовому Місті, а замість нього зацарював син його Аса. За його днів заспоко́ївся Край на десять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'І робив Аса добре та вгодне в оча́х Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'І повсував він же́ртівники чужих богів та па́гірки, і порозбивав камінні стовпи́ для божків, і постинав святі дере́ва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'І наказав він Юді звертатися до Господа, Бога батькі́в своїх, і виконувати Його Зако́на та заповідь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'І повсував він зо всіх Юдиних міст па́гірки та подо́би сонця. І заспоко́їлося царство при ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'І побудував він тверди́нні міста в Юді, бо заспоко́ївся край, і не було на нього війни за тих років, бо Господь дав йому мир.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'І сказав він до Юди: „Побудуймо ці міста, й оточі́мо муром та ба́штами, ворітьми́ та засу́вами. Іще він, цей край, наш, бо зверта́лися ми до Господа, нашого Бога. Зверта́лися ми, і Він дав нам мир навко́ло“. І побудува́ли, і їм щасти́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'І було в Аси ві́йська: носіїв великих щиті́в та ра́тищ з Юди — три сотні тисяч, а з Веніямина таких, що носять мало́го щита́, та лу́чників — двісті й вісімдеся́т тисяч. Усі вони — хоробрі вояки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'І вийшов на них кушеянин Зерах із ві́йськом у тисячу тисяч та з трьома́ сотнями колесни́ць, і прибув аж до Мареші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'І вийшов Аса проти нього, і вони вста́вилися до бо́ю в долині Цефат при Мареші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'І кликнув Аса до Господа, Бога свого, та й сказав: „Господи, нема кому, крім Те́бе, допомогти числе́нному або безси́лому. Допоможи нам, Господи, Боже наш, бо ми на Тебе опира́ємося, і в Ім\'я́ Твоє ми прийшли на цю бе́зліч. Господи, Ти Бог наш, нехай люди́на не має сили проти Тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'І побив Господь кушеян перед Асою та перед Юдою, — і кушеяни повтікали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'І гнав їх Аса та народ, що був з ним, аж до Ґерару. І попа́дало з кушеян багато, так що ніхто з них не залишився живий, бо вони були поторощені перед Господнім лицем та перед табором Його. І поне́сли вони дуже багато здо́бичі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'І побили вони всі міста навколо Ґерару, бо Господній страх був на них. І пограбували вони всі ті міста, бо в них було багато здо́бичі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Порозбивали вони також намети чередникі́в, і зайняли дуже багато дрібно́ї худоби та верблю́дів, та й вернулися до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'А Азарія, син Оведів, — злинув на нього Дух Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'І вийшов він перед Асу та й сказав йому: „Послухайте мене, Асо та ввесь Юдо й Веніямине! Господь з вами, якщо бу́дете з Ним, і якщо бу́дете Його шукати, дасть вам знайти Себе. А якщо ви полишите Його, — полишить Він вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'У Ізраїля було́ багато днів, коли був він без правдивого Бога, і без священика-вчителя та без Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'І вернувся він в утиску своєму до Господа, Бога Ізраїлевого, і вони шукали Його, і Він дав їм знайти Себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'А тими часа́ми не було споко́ю ані тому́, хто виходить, ані тому, хто входить, бо були великі неспоко́ї в усіх ме́шканців кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'І воював народ проти народу та місто проти міста, бо Бог побенте́жив їх усяким лихом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'А ви будьте міцні, і нехай не слабнуть ваші ру́ки, бо є нагоро́да для вашої чи́нности!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'А коли Аса почув оці слова та пророцтво, яке говорив пророк Азарія, син Оведів, то зміцни́вся, і повикидав поганські гидо́ти зо всього кра́ю Юдиного та Веніяминового, та з міст, які він здобув з Єфремових гір, і відновив Господнього же́ртівника, що перед Господнім притво́ром.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'І зібрав він усього Юду й Веніямина та тих, що ме́шкали часо́во з ними з Єфрему, і з Манасії, і з Симеона, бо дуже багато поперебіга́ли до нього з Ізраїля, коли побачили, що з ним Господь, його Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'І вони зібралися до Єрусалиму третього місяця, п\'ятнадцятого року царюва́ння Аси.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'І прине́сли вони того дня в жертву для Господа зо здо́бичі, яку поприво́дили: худоби великої — сім сотень, а худоби дрібно́ї — сім тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'І ввійшли вони в умову, щоб звертатися до Господа, Бога їхніх батьків, усім своїм серцем та всією своєю душею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'А кожен, хто не буде звертатися до Господа, Бога Ізраїля, буде забитий від мало́го й аж до великого, від чоловіка й аж до жінки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'І заприсягли́ся вони Господе́ві голосом сильним, і окликом, і су́рмами, і рога́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'І тішився ввесь Юда тією прися́гою, бо вони заприсягли́ся всім серцем своїм, і всією своєю волею шукали Його, і Він дав їм знайти Себе. І Господь дав їм мир навколо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'І навіть Мааху, матір царя Аси, й її він позбавив права бути царицею, бо вона зробила була́ ідола Астарти. І Аса порубав бовва́на її, і розтер, і спалив у долині Кедро́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Та па́гірки не минулися в Ізраїля, але́ Асине серце було все з Господом по всі його дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'І вніс він до Божого дому святі речі свого батька та святі речі свої, — срібло, і золото, і по́суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'А війни́ не було́ аж до тридцять й п\'ятого року царюва́ння Аси.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Тридцятого й шостого року царюва́ння Аси пішов Баша, Ізраїлів цар, проти Юди, і будував Раму, щоб не дати ніко́му від Аси, царя Юдиного, вихо́дити та вхо́дити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'І виніс Аса срібло та золото із скарбни́ць Господнього дому та дому царе́вого, і послав до Бен-Гадада, царя сирійського, що сидів у Дамаску, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '„ Є умова між мною та між тобою, і між батьком моїм та батьком твоїм. Ось послав я тобі срібла та золота, — іди, зламай умову свою з Башею, царем Ізраїлевим, і нехай він віді́йде від мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'І послухався Бен-Гадад царя Аси, і послав зверхників свого ві́йська на Ізраїлеві міста, і вони поруйнува́ли Іййона, і Дана, і Авел-Маїма та всі запаси міст Нефтали́мових.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'І сталося, як Баша це почув, то перестав будувати Раму, і спинив свою працю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'А цар Аса взяв усього Юду, і вони повино́сили каміння Рами та її дерево, що з них будував був Баша, і побудува́в з того Ґеву та Міцпу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'А того ча́су прийшов прозорли́вець Ханані до Аси, Юдиного царя, та й сказав до нього: „Через те, що ти спирався на сирійського царя, а не сперся на Господа, Бога свого, тому втекло з твоєї руки ві́йсько сирійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Чи ж не були́ кушеяни та ливіяни ві́йськом дуже великим, колесни́цями й верхівця́ми дуже числе́нними? Та коли ти сперся на Господа, Він дав їх у твою руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Бо очі Господні дивляться по всій землі, щоб зміцни́ти тих, у кого все їхнє серце до Нього. Тому́ зробив ти нерозумно, бо відтепе́р будуть у тебе ві́йни!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'І розгні́вався Аса на прозорли́вця, і дав його до в\'язни́ці, бо був у гніві на нього за це. І Аса тиснув декого з наро́ду того ча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'І оце Асині діла́, перші та останні, — ось вони описані в книзі Юдиних та Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'І занеду́жав Аса тридцятого й дев\'ятого року свого царюва́ння на свої но́ги, і хвороба його була́ тяжка́. Та й у хворобі своїй не звертався він до Господа, але до лікарі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'І спочив Аса з своїми батька́ми, і помер сорокового й першого року свого царюва́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'І поховали його в його гробни́цях, які він ви́копав собі в Давидовому Місті. І поклали його на ложі, що він напо́внив па́хощами та різними, по-містецькому зро́бленими, мастя́ми. І спалили йому дуже велике палі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'А замість нього зацарював син його Йосафа́т, та зміцни́вся над Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'І поставив він ві́йсько по всіх укрі́плених Юдиних містах, і дав зало́ги в Юдиному кра́ї та в Єфремових міста́х, які був здобув його батько Аса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'І був Господь з Йосафа́том, бо він ходив першими дорогами батька свого Давида, і не шукав Ваалів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Бо він звертався до Бога свого батька, і ходив за Його заповідями, а не за чином Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'І Господь зміцнив його царство в руці його, і вся Юдея давала дару́нка Йосафатові, і було в нього багато багатства та слави.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'І пови́щилось серце його на Господніх дорогах, і він іще повсовував па́гірки та Астарти з Юди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'А третього року свого царюва́ння послав він до своїх зверхників, до Бен-Хаїла, і до Овадії, і до Захарія, і до Натанаїла, і до Міхаї, щоб вони навчали в Юдиних міста́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'А з ними були Левити: Шемая, і Натанія, і Зевадія, і Асаїл, і Шемірамот, і Єгонатан, і Адонійя, і Товійя, і Тов-Адонійя, Левити, а з ними Елішама та Єгорам, священики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'І навчали вони в Юдеї, а з ними була книга Зако́ну Господнього. І ходили вони довко́ла по всіх Юдиних містах, і навчали серед наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'І був страх Господній на всіх царствах кра́ю, що навко́ло Юди, і вони не воювали з Йосафатом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'А від филисти́млян прино́сили Йосафатові да́ри та срібло данини; також араби приво́дили йому дрібну́ худобу: сім тисяч і сім сотень баранів та сім тисяч і сім сотень козлів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'І Йосафат усе зростав уго́ру. І побудував він в Юді тверди́ні та міста на запа́си.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'І мав він багато добра по Юдиних містах, і мужів військо́вих, хоробрих воякі́в в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'А оце їхній пере́гляд, за домами їхніх батьків. Від Юди тисячники: зверхник Адна, а з ним три сотні тисяч хоробрих воякі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'А при ньому зверхник Єгоханан, а з ним — двісті й вісімдесят тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'А при ньому Амасія, син Зіхрі, що присвятив себе Господе́ві, а з ним двісті тисяч хоробрих воякі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'А від Веніямина: хоробрий воя́к Ел\'яда, а з ним двісті тисяч узбро́єних луком та щито́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'А при ньому Єгозавад, а з ним сто й вісімдеся́т тисяч узбро́єного ві́йська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Оці служили цареві, опріч тих, яких цар умістив по тверди́нних містах по всьо́му Юді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'І було́ в Йосафата багато багатства та слави, і він посвоя́чився з Ахавом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'А по кількох ро́ках пішов він до Ахава до Самарії. І Ахав нарізав багато худоби дрібно́ї та худоби великої йому́ та наро́дові, що з ним, і намовив його піти на ґілеадський Рамот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'І сказав Ахав, цар Ізраїлів, до Йосафата, царя Юдиного: „Чи пі́деш зо мною до ґілеадського Рамоту?“А той відказав йому: „Я — як ти, народ мій — як твій народ, і буду з тобою на війні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'І сказав Йосафат до Ізраїлевого царя: „Ви́відай зараз слово Господнє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'І зібрав Ізраїлів цар пророків, чотири сотні чоловіка, та й сказав до них: „Чи йти нам на війну на ґілеадський Рамот, чи занеха́ти?“А ті сказали: „Іди, і Бог дасть його в цареву руку!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'І сказав Йосафат: „Чи нема тут іще Господнього пророка, — і зверні́мось до нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'І сказав Ізраїлів цар до Йосафата: „ Є ще один муж, щоб через нього звернутися до Господа. Та я нена́виджу його, бо він не пророкує на мене добре, а по всі дні свої тільки лихе. Це Міхе́й, син Їмлин“. А Йосафат відказав: „Нехай цар не говорить таке!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'І покликав Ізраїлів цар одного е́внуха й сказав: „Приведи скоріше Міхе́я, Їмлиного сина!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'А цар Ізраїлів та Йосафат, цар Юдин, сиділи кожен на троні своїм, повби́рані в шати; а сиділи вони при вході брами Самарії, а всі пророки пророкува́ли перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'А Цідкійя, Кенаанин син, зробив собі залізні ро́ги й сказав: „Так сказав Господь: Оцим будеш бода́ти сиріян аж до ви́гублення їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'І всі пророки пророкува́ли так, говорячи: „Вихо́дь до ґілеадського Рамоту, і май успіх, — і Господь дасть його в цареву руку!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'А той послане́ць, що пішов покликати Міхе́я, говорив до ньо́го, кажучи: „Ось слова тих пророків, — одноу́сно звіщають цареві добро. Нехай же буде слово твоє таке, як кожного з них, — і ти говори́тимеш добре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'І сказав Міхе́й: „ Як живий Господь, — те, що́ скаже Господь, тільки те говоритиму!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'І прийшов він до царя, а цар сказав до нього: „Міхе́ю, чи йти на війну до ґілеадського Рамоту, чи занеха́ти?“А той відказав: „Вийдіть, і будете мати успіх, — і вони будуть дані в вашу руку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'І сказав йому цар: „Аж скільки разі́в я заприсягав тебе, що ти не говори́тимеш мені нічо́го, тільки правду в Ім\'я́ Господа?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'А той відказав: „Я бачив усього Ізраїля, розпоро́шеного по гора́х, немов вівці, що не мають пастуха. І сказав Господь: Немає в них пана, — нехай ве́рнуться з ми́ром кожен до дому свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'І сказав Ізраїлів цар до Йосафата: „Чи ж не казав я тобі, — він не буде пророкувати мені доброго, а тільки лихе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'А Міхе́й відказав: „Тому́ послухайте Господнього слова: Бачив я Господа, що сидів на престолі Своїм, а все небесне ві́йсько стояло по правиці Його та по лівиці Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'І сказав Господь: Хто намовить Ахава, Ізраїлевого царя, і він вийде й упаде́ в ґілеадському Рамоті? І говорили: той говорив так, а той говорив так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'І вийшов дух, і став перед Господнім лицем та й сказав: Я намо́влю його! І сказав йому Господь: Чим?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'А той відказав: Я вийду й стану духом неправди в устах усіх його пророків. А Господь сказав: Ти намовиш, а також переможеш; вийди та й зроби так!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'А тепер оце Господь дав духа неправди в уста оцих твоїх пророків, і Господь говорив на тебе недобре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'І підійшов Цідкійя, Кенаанин син, і вдарив Міхея по щоці́ та й сказав: „Кудою це перейшов Дух Господній від мене, щоб говорити з тобою?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'А Міхей відказав: „Ось ти побачиш це того дня, коли вві́йдеш до внутрішньої кімна́ти, щоб схова́тися“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'І сказав Ізраїлів цар: „Візьміть Міхе́я, і відведіть його до Амона, зверхника міста, та до Йоаша, царевого сина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'та й скажете: Отак сказав цар: Посадіть оцього до в\'язни́чного дому, і давайте йому їсти скупо хліба й скупо води, аж поки я не верну́ся з миром“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'А Міхе́й відказав: „Якщо справді ве́рнешся ти з миром, то не говорив Господь через мене“. І до того сказав: „Слухайте це, усі люди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'І вийшов Ізраїлів цар та Йосафат, цар Юдин, до ґілеадського Рамоту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'І сказав Ізраїлів цар до Йосафата: „Я переберуся й піду́ на бій, а ти вбери свої шати!“І перебрався Ізраїлів цар, і пішли на бій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'А сирійський цар наказав зверхникам своїх колесни́ць, говорячи: „Не воюйте ні з мали́м, ні з великим, а тільки з сами́м Ізраїлевим царем!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'І сталося, як зверхники колесни́ць побачили Йонатана, то вони сказали: „Це Ізраїлів цар!“І вони оточи́ли його, щоб воювати. І закричав Йосафат, і Господь допоміг йому, і Бог звабив їх від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'І сталося, як зверхники колесни́ць побачили, що це не Ізраїлів цар, то повернули від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'А один чоловік зне́хотя натягнув лука, та й ударив Ізраїлевого царя між підв\'я́занням пояса та між па́нцерем. А той сказав візникові: „Заверни назад, і випровадь мене від війська, бо я ра́нений“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'І збільшився бій того дня, а Ізраїлів цар був поста́влений на колесни́ці проти сирі́ян аж до вечора. І помер він під час за́ходу сонця...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'І вернувся Йосафа́т, цар Юдин, із ми́ром до дому свого́ до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'І вийшов перед нього прозорли́вець Єгу, син Ханані, та й сказав до царя Йосафата: „Чи бу́деш допомагати несправедливому, а тих, хто нена́видить Господа, бу́деш любити? І за це на тобі гнів від Господнього лиця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Але й добрі речі знайшлися при тобі, бо ти повигу́блював Аста́рти з Кра́ю, і нахилив своє серце, щоб шукати Господа“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'І осівся Йосафат в Єрусалимі, і він зно́ву вихо́див між народ від Беер-Шеви аж до Єфремових гір, і наверта́в їх до Господа, Бога їхніх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'І понаставля́в він суддів у Краю́, по всіх укрі́плених Юдиних містах, для кожного міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'І сказав він до суддів: „Дивіться, що́ ви робите, бо не для люди́ни ви судите, але для Господа, і Він з вами в справі суду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'А тепер нехай буде Господній страх на вас. Стережіться й робіть, бо нема в Господа, Бога нашого, кривди, ані огляду на особу, ані брання́ дару́нка“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'А також в Єрусалимі понаставля́в Йосафат з Левитів і з священиків та з голів ба́тьківських домів Ізраїля для Господнього су́ду та для супере́чок. І вернулися вони до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'І він наказав їм, говорячи: „Отак чині́ть у страху́ Господньому, вірністю та ці́лим серцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'А щодо всякої супере́чки, що при́йде до вас від ваших братів, що сидять по містах своїх, де треба розсудити чи то за кров, чи то за Зако́н, чи то за заповідь, устави, чи за права́, то остережете їх, і вони не згрішать Господе́ві, і не буде гніву на вас та на ваших братів. Так робіть, і не згрішите!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'А ось священик Амарія — голова над вами до всяких Господніх рече́й, а Завадія, син Ізмаїлів, володар Юдиного дому, — до всякої царевої речі, і писарі Левити — перед вами. Будьте міцні й зробіть, — і нехай буде Господь з добрим!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'І сталося по тому, пішли моаві́тяни та аммоні́тяни, а з ними деякі з меунян, проти Йосафата на війну́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'І прийшли, і доне́сли Йосафатові, говорячи: „Прийшла на тебе сила силенна з того боку моря, з Сирії, і ось вони в Хаццон-Тамарі, воно — Ен-Ґеді“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'І злякався Йосафа́т, і постановив зверну́тися до Господа. І він проголосив піст на всю Юдею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'І зібралися юде́яни просити допомоги від Господа, також поприхо́дили зо всіх Юдиних міст просити Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'І став Йосафа́т у зборі Юдиному та єрусали́мському в Господньому домі, перед нови́м подві́р\'ям,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'та й сказав: „Господи, Боже батьків наших! Чи ж не Ти Бог на небеса́х? І Ти пануєш над усіма́ царствами наро́дів, і в руці Твоїй — сила та міць, і немає такого, хто б став проти Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Чи ж не Ти, Боже наш, повиганя́в ме́шканців цього Кра́ю перед наро́дом Твоїм, Ізраїлем, і дав його Авраамовому насінню, Твоє́му при́ятелеві навіки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'І вони осілися в ньому, і збудували Тобі в ньому святиню для Ймення Твого, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Якщо при́йде на нас зло, — меч укара́ння, чи морови́ця, чи голод, то ми станемо перед цим храмом та перед лицем Твоїм, бо Ім\'я́ Твоє в цьому храмі, і бу́демо кли́кати до Тебе з нашого у́тиску, — і Ти почуєш, і спасеш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'А тепер ось сини Аммонові й Моавові та ме́шканці гори́ Сеїр, що через них Ти не дав ізра́їльтянам іти, коли вони вихо́дили були з єгипетського кра́ю, і вони минули їх, і не ви́губили їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'і оце вони відплачують нам нава́лою, щоб вигнати нас із спа́дку Твого, який Ти віддав нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Боже наш, чи ж Ти не осу́диш їх? Нема бо в нас сили перед цією силою силе́нною, що прихо́дить на нас, і ми не знаємо, що́ зробимо, бо наші очі — на Тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'А всі юде́яни стояли перед Господнім лицем, також діти їхні, жінки їхні та їхні сини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'А Яхазіїл, син Захарія, сина Бенаї, Єіїла, сина Маттанії, Левит із Асафових синів, — був на ньому Дух Господній серед збору,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'і він сказав: „Послухайте, ввесь Юдо й ме́шканці Єрусалиму та ца́рю Йосафате! Так говорить до вас Господь: Не бійтеся та не жахайтеся перед цією силе́нною силою, бо не ваша ця війна, але Божа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Узавтра зійдіть на них, — ось вони входять збі́ччям Ціцу, і ви їх зна́йдете на кінці долини, навпроти пустині Єруїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Не вам воювати в цьому, — поставтеся й станьте, і побачите, що Господнє спасі́ння з вами, Юдо й Єрусалиме! Не бійтеся й не жахайтеся, — узавтра вихо́дьте перед них, а Господь буде з вами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'І вклонився Йосафат обличчям до землі, а ввесь Юда та ме́шканці Єрусалиму попа́дали перед Господнім лицем, щоб уклони́тися Господе́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'І встали Левити з синів Кегатівців та з синів Корахівців, щоб хвалити Господа, Бога Ізраїлевого сильним голосом, високим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'І повставали вони рано вранці, і вийшли до пустині Текоя. А як вони вихо́дили, став Йосафа́т та й сказав: „Послухайте мене, Юдо та ме́шканці Єрусалиму! Віруйте в Господа, вашого Бога, і будете запе́внені, — ві́рте пророкам Його, і пощасти́ться вам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'І радився він з наро́дом, і поставив співакі́в для Господа, і вони хвалили вели́чність святости, коли йшли перед озбро́єними, і говорили: „Дякуйте Господу, бо навіки Його милосе́рдя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'А того ча́су, коли зачали́ вони співати та хвалити, дав Господь за́сідку на синів Аммонових і Моавових та на ме́шканців гори Сеїр, що прийшли були проти Юди, — і були вони побиті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'бо повстали аммоні́тяни та моаві́тяни на ме́шканців гори Сеїр, щоб учинити їх закля́ттям, і щоб вигубити. А коли вони покінчи́ли це з ме́шканцями Сеїру, стали помагати один проти о́дного, щоб ви́губити себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'І коли Юда прийшов на вартівню́ до пустині, і поглянули вони на на́товп, аж ось тру́пи, що попа́дали на землю, і не було урято́ваного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'І прийшов Йосафат та наро́д його́, щоб пограбувати їхню здо́бич, і знайшли серед них душе багато і маєтку, і одежі, і кошто́вностей, і понабира́ли собі стільки, що не могли не́сти. І вони три дні все грабували ту здо́бич, бо числе́нна була вона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'А четвертого дня зібралися вони до долини Бераха, бо там благословляли Господа; тому назвали ім\'я́ тому місцю: долина Бераха, і так воно зветься аж до сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'І вернулися всі юде́яни та єрусалимляни, а Йосафат на чолі́ їх, щоб вернутися до Єрусалиму з радістю, бо звесели́в їх Господь спасінням від їхніх ворогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'І прибули́ вони до Єрусалиму з а́рфами й з ци́трами та су́рмами до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'І був Божий страх на всі царства країв, коли вони почули, що Господь воював з Ізраїлевими ворогами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'І заспоко́їлося Йосафатове царство, і дав йому його Бог мир навколо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'І царював Йосафа́т над Юдою. Він був віку тридцяти й п\'яти років, коли зацарював, а двадцять і п\'ять літ царював в Єрусалимі. А ім\'я́ його матері — Азука, дочка́ Шілхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'І ходив він дорогою свого батька Аси, і не уступа́вся з неї, щоб робити вгодне в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Тільки па́гірки не минулися, і народ іще не вчинив свого серця міцни́м для Бога своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'А решта Йосафатових діл, перші й останні, — ото вони описані в записах Єгу, сина Ханані, що внесене до книги Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'А по то́му поєднався Йосафат, цар Юдин, з Ахазією, Ізраїлевим царем, що робив несправедливо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'І поєднався він із ним, щоб поробити кораблі, щоб ходити до Таршішу. І поробили вони кораблі в Ецйон-Ґевері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Та Елієзер, син Додави, з Мареші, пророкував на Йосафата, говорячи: „За те, що ти поєднався з Ахазією, поруйнував Господь чи́ни твої!“І порозбивалися ті кораблі, і не могли йти до Таршішу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'І спочив Йосафат із своїми батька́ми. І був він похований із своїми батьками в Давидовому Місті, а замість нього зацарював син його Єгора́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'І були в нього брати, Йосафатові сини: Азарія, і Єхіїл, і Захарій, і Азарія, і Михаїл, і Шефатія, — усі вони сини Йосафата, Ізраїлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'І дав їм їхній батько великі подару́нки срібла, і золота, і кошто́вності з тверди́нними містами в Юді, а царство дав Єгорамові, бо він перворо́джений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'І став Єгорам на царстві батька. І зміцни́вся він, і позабивав усіх братів своїх мече́м, а також декого з Ізраїлевих зверхників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Єгорам був віку тридцяти й двох літ, коли зацарював, і царював вісім літ в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'І ходив він дорогою Ізраїлевих царів, як робив Ахавів дім, бо Ахавова дочка́ була йому за жінку. І робив він зло в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Та не хотів Господь погубити Давидів дім ради заповіту, що склав був із Давидом, і як говорив дати світильника йому та синам його по всі дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'За його днів відпав був Едом з-під Юдиної руки, і настанови́ли над собою царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'І пішов Єгорам зо своїми зверхниками, і всі колесни́ці з ним. І сталося, що він устав уночі та й побив Едома, що оточив був його, та зверхників колесни́ць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'І відпав Едом з-під Юдиної руки, і так є аж до цього дня. Тоді того ча́су відпала й Лівна з-під руки його, бо він поки́нув Господа, Бога своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Також він наробив па́гірків по Юдиних містах, і вчинив пере́любами єрусалимських ме́шканців, а Юду звів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'І прийшов до нього лист від пророка Іллі такого змісту: „Так говорить Господь, Бог Давида, твого батька: За те, що не ходив ти дорогами Йосафата, свого батька, і дорогами Аси, Юдиного царя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'а ходив дорогою Ізраїлевого царя, і вчинив перелю́бниками Юду та ме́шканців Єрусалиму, як чинив перелю́бниками дім Ахавів, а також братів своїх, дім свого батька, ліпших від тебе, ти позабивав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'то ось ударить Господь великою пора́зою в народі твоїм, і в синах твоїх, і в жінках твоїх, і в усьому маєтку твоєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'А ти бу́деш у великих хворобах, у хворобі нутра́ свого́, аж вийдуть ну́трощі твої через довгочасну хворобу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'I збудив Господь на Єгорама духа филисти́млян та арабів, що при етіо́пах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'І вийшли вони на Юду, і ввірвалися до нього, і позабирали ввесь маєток, що знахо́дився в царсько́му домі, а також синів його та жіно́к його. І не позоста́лося в нього сина, окрім Єгоахаза, наймолодшого з синів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'А по всьому тому вдарив його Госпо́дь у ну́трощах його невиду́жною хворобою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'І сталося по певному ча́сі, коли надійшов кінець двох років, вийшли його ну́трощі від хвороби його, і він помер у тяжки́х бо́лях. А народ його не зробив для нього спа́лення па́хощів, як робили спа́лення батькам його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Він був віку тридцяти й двох літ, коли зацарював, а царював вісім літ в Єрусалимі. І відійшов він, і ніхто за ним не жа́лував; і поховали його в Давидовому Місті, та не в царськи́х гроба́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'А мешканці Єрусалиму настанови́ли царем замість нього Ахазію, його найменшого сина, бо всіх перших позабива́ла та вата́га, що прихо́дила з арабами на та́бір. І зацарював Ахазія, син Єгорама, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ахазія був віку сорока й двох літ, коли зацарював, і царював він в Єрусалимі один рік. А ім\'я́ його матері — Аталія, дочка Омрієва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Також він ходив дорогою Аха́вого дому, бо його мати була йому дора́дниця, щоб чинити беззако́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'І чинив він зло в Господніх оча́х, як Аха́вів дім, бо вони були йому дорадниками по смерті його батька, на поги́біль йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Також за їхньою порадою він ходив. І пішов він з Єгорамом, сином Ахава, Ізраїлевого царя, на війну на Хазаїла, сирійського царя, в ґілеадський Рамот. І побили сирі́яни Йорама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'І вернувся він лікува́тися в Їзреелі від тих ран, що завдали́ йому в Рамі, як він воював із Хазаїлом, сирійським царем. А Азарія, Єгорамів син, цар Юдин, зійшов побачити Єгорама, Ахавого сина, в Їзреелі, бо він був слаби́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'І від Бога було на погибіль Ахазії, щоб прийти до Єгорама, бо як прийшов, вийшов з Єгорамом на Єгу, сина Німші, що Господь пома́зав його ви́губити Ахавів дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'І сталося, коли Єгу чинив суд над Ахавовим домом, то знайшов він Юдиних зверхників та синів Ахазієвих братів, що служили Ахазієві, і позабивав їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'І відшукав він Ахазію, і схопи́ли його́, а він ховався в Самарії. І привели́ його до Єгу та й забили його; і поховали його, бо сказали: „Він син Йосафата, що всім серцем своїм звертався до Господа“. І не було в домі Ахазії нікого, хто мав би силу царювати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'А коли Аталія, мати Ахазії, побачила, що помер її син, то встала й ви́губила все цареве насіння Юдиного дому...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'А Єгосав\'ат, дочка царя, взяла Йоаша, сина Ахазії, та й викрала його з-поміж вби́ваних царськи́х синів, і дала́ його та няньку його до спальної кімна́ти. І схова́ла його Єгосав\'ат, дочка царя Єгорама, жінка священика Єгояди, — бо вона була сестра Ахазії, — перед Аталією, і та не забила його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'І він був з ними в Божому домі, хова́ючися шість років, а Аталія царювала над краєм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'А сьо́мого року зміцнився Єгояда й прийняв сотників: Азарію, Єрохамового сина, і Ізмаїла, сина Єгохананового, і Азарію, сина Оведового, і Маасею, сина Адаї, і Елісафата, сина Зіхрієвого, — в умову з собою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'І обійшли вони Юду, і зібрали зо всіх Юдиних міст Левитів та голів Ізраїлевих домів, і прийшли до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'І ввесь збір склав у Божому домі умову з царем. І сказав їм Єгояда: „Оце царськи́й син буде царювати, як говорив Господь про Давидових синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Оце та річ, яку зробите: третина з вас, що прихо́дите в суботу, із священиків та з Левитів, будете за придве́рних біля порогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'А третина — при царсько́му домі, а третина — при брамі Єсод, а ввесь наро́д — у подві́р\'ях Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'І нехай не входить до Господнього дому ніхто, окрім священиків та тих, хто прислуго́вує із Левитів, — вони вві́йдуть, бо освя́чені вони, а ввесь народ буде пильнувати Господньої сторо́жі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'І оточать Левити царя навко́ло, кожен із своєю зброєю в руці своїй; а хто чужий увійшов би до дому, нехай буде забитий! І будете ви з царем при вході його та при виході його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'І зробили Левити та ввесь Юда все, що наказав священик Єгояда. І взяли кожен людей своїх, що приходять у суботу та відходять у суботу, бо священик Єгояда не звільнив черг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'І дав священик Єгояда сотникам ра́тища, і малі щити́, і інші щити́, що належали цареві Давидові, що були в Божому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'І поставив він увесь народ, а кожен мав свою зброю в руці своїй, від правого боку дому аж до лівого боку дому, при же́ртівнику та при домі, навко́ло біля царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'І ви́вели вони царсько́го сина, і поклали на нього корону та звої Зако́ну. І зробили вони його царем, і пома́зали його Єгояда та сини його, та й крикнули: „Нехай живе цар!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'І почула Аталія голос наро́ду, що бігав та сла́вив царя, і прийшла до наро́ду до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'І побачила вона, аж ось цар стоїть на помо́сті своїм при вході, а при царі зверхники та су́рми, а ввесь народ краю радіє та сурми́ть у су́рми, а співаки — з музичними знаря́ддями, що подавали до ві́дома знаки́ на хвалу́. І роздерла Аталія шати свої та й крикнула: „Змова, змова!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'А священик Єгояда наказав сотникам, поставленим над ві́йськом, і сказав до них: „Виведіть її поміж шере́ги, а хто інший пі́де за нею, — нехай буде забитий мече́м!“Бо священик сказав: „Не заб\'єте її в Господньому домі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'І зробили їй про́хід, і вона вийшла входом Кінської брами до царсько́го дому, і там забили її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'І склав Єгояда умову між собою й між усім наро́дом та між царем, щоб бути народом Господнім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'І ввійшов увесь наро́д до Ваалового дому, та й порозбива́ли його та же́ртівники його, і бовва́нів його зо́всім полама́ли, а Маттана, Ваалового священика, убили перед же́ртівниками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'А в Господньому домі Єгояда віддав уря́ди на руку священиків та Левитів, яких поділив Давид над Господнім домом, щоб прино́сити Господні цілопа́лення, як написано в Мойсеєвім Зако́ні, з радістю та зо співом, за уста́вом Давидовим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'А при брамах Господнього дому поставив він придве́рних, щоб не ввійшов хто будь-чим нечистий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'І взяв він сотників, і вельмож, і тих, що старшину́ють над наро́дом, та ввесь наро́д кра́ю, і відвели́ царя з Господнього дому. І ввійшли вони через горі́шню браму до царсько́го дому, і посадили царя на троні царства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'І радів увесь народ кра́ю, а місто заспоко́їлося. А Аталію вбили мече́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Йоаш був віку семи́ років, коли зацарював, і сорок років царював він в Єрусалимі. А ім\'я́ його матері — Цівія, з Беер-Шеви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'І робив Йоаш вгодне в Господніх оча́х по всі дні священика Єгояди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'І взяв йому Єгояда дві жінки, а той породи́в синів та дочо́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'І сталося по тому, було́ в Йоашевому серці віднови́ти Господній дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'І зібрав він священиків та Левитів, і сказав до них: „Підіть по Юдиних міста́х, і збирайте з усього Ізра́їля срібло на направу храму вашого Бога рік-річно, і ви бу́дете спіши́ти в цій справі!“Та не спіши́лися Левити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'І покликав цар Єгояду, голову священиків, і сказав до нього: „Чому ти не жада́єш від Левитів, щоб прино́сили з Юди та з Єрусалиму дару́нки, за постановою Мойсея, раба Господнього, та Ізраїлевого збору — на скинію свідо́цтва?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Бо сини нечестивої Аталії вломи́лися були до Божого дому, і всі святощі Господнього дому вжили для Ваалів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'І сказав цар, і зробили одну скри́ньку, і поставили її в брамі Господнього дому назо́вні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'І проголоси́ли в Юді та в Єрусалимі прино́сити для Господа да́ток, що його встановив на Ізраїля в пустині Мойсей, Божий раб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'І раділи всі зве́рхники та ввесь наро́д, і прино́сили й ки́дали до скриньки, аж поки вона напо́внилася.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'І бувало того ча́су, коли Левити прино́сили скриньку на царськи́й перегляд, і як вони бачили, що числе́нне те срібло, то прихо́див царськи́й писар та призна́чений від священика-голови, і вони випоро́жнювали скриньку. Потім відно́сили її, і поверта́ли її на її місце. Так робили вони день-у-день, і зібрали дуже багато срібла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'А цар та Єгояда давали його тим, що робили працю роботи Господнього дому, і все наймали каменярі́в та те́слів, щоб відно́влювати дім Господній, а також тим, що обробля́ли залізо та мідь на змі́цнення Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'І працювали робітники́, і чинилася направа працею їхньої руки. І поставили вони Божий дім на міру його, і зміцнили його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'А коли покінчи́ли, вони прине́сли перед царя та Єгояду решту срібла. І поробили вони з нього речі для Господнього дому, речі для служби та для жертвоприно́шення, і ложки, і по́суд золотий та срібний. І прино́сили цілопа́лення в Господньому домі за́вжди, по всі дні Єгояди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'І постарі́в Єгояда, і наситився днями й помер. Він був віку ста й тридцяти́ літ, коли помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'І поховали його в Давидовому Місті з царями, бо робив він добро в Ізраїлі і для Бога, і для Його храму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'А по Єгоядиній смерті прийшли князі́ Юдині, і поклонилися цареві. Тоді цар їх послухав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'І покинули вони дім Господа, Бога своїх батькі́в, та й служили Аста́ртам та божка́м. І був Божий гнів на Юду та Єрусалим за цю їхню провину.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'І послав Він між них пророків, щоб приверну́ти їх до Господа, і вони сві́дчили проти них, та ті не слу́хались.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'А Дух Господній огорну́в Захарія, сина священика Єгояди, і він став перед наро́дом та й сказав до них: „Так сказав Бог: Чому ви переступаєте Господні заповіти? Ви не ма́тимете у́спіху, бо ви покинули Господа, то й Він покинув вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'І змо́вилися вони на нього, і заки́дали його камінням з царсько́го наказу в подві́р\'ї Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'І не пам\'ята́в цар Йоаш тієї ми́лости, яку зробив був із ним батько того Єгояда, але вбив сина його. А як той умирав, то сказав: „Нехай побачить Господь, і нехай покарає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'І сталося наприкінці року, прийшло на нього сирійське військо, і прибули́ до Юди та до Єрусалиму, і позабивали всіх зверхників народу, а всю здо́бич із них послали цареві в Дама́ск.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Хоч з мало́ю кількістю людей прийшло сирійське військо, проте Господь дав в їхню руку дуже велику силу, бо ті покинули Господа, Бога батьків своїх. А над Йоашем вони виконали присуд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'А коли вони відійшли від нього, позоставивши його в тяжки́х хворобах, змо́вилися на нього його раби за кров синів священика Єгояди, — і забили його на ліжку його, і він помер. І поховали його в Давидовому Місті, та не поховали його в гроба́х царськи́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'А оце змовники на нього: Завад, син аммонітянки Шім\'ат, і Єгозавад, син моавітянки Шімріт.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'А сини його, і великість тягару, покладеного на нього, і відбудова Божого дому, — ото вони описані в викладі Книги Царів. А замість нього зацарював син його Амація.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'У віці двадцяти й п\'яти літ зацарював Амація, і двадцять і п\'ять літ царював він в Єрусалимі. А ім\'я́ його матері — Єгоаддан, з Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'І робив він угодне в Господніх оча́х, тільки не з ці́лим серцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'І сталося, як зміцнилося царство за ним, то він повбивав своїх рабів, що забили царя свого, його батька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'А синів їх він не позабивав, як написано в книзі Мойсеєвого Зако́ну, що наказав був Господь, говорячи: „Не помруть батьки за синів, а сини не помруть за батьків, бо кожен за гріх свій помре́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'І зібрав Амація Юду, і поставив їх за домом їхніх батькі́в, за тисячниками та за сотниками для всього Юди та Веніямина; і він перелічив їх від віку двадцяти́ років і вище, і знайшов їх три сотні тисяч ви́браного, здатного до війська, хто тримає ра́тище та великого щита́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'І найняв він із Ізраїля сотню тисяч хоробрих воякі́в за сотню талантів срібла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'І прийшов до нього Божий чоловік, говорячи: „О ца́рю, нехай не вихо́дить з тобою Ізраїлеве ві́йсько, бо Господь не з Ізраїлем, ні з жодним із синів Єфрема.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Але йди тільки ти, роби, будь відважний на війні! Інакше вчи́нить Бог, що ти спіткне́шся перед ворогом, бо в Бога є сила допомагати, або робити, щоб спіткну́тися“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'І сказав Амація до Божого чоловіка: „А що́ робити з тією сотнею талантів, що я дав Ізраїлевому ві́йську?“А Божий чоловік відказав: „Господь може дати тобі більше від цьо́го!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'І відділив Амація їх, те ві́йсько, що прийшло з краю Єфремового, щоб ішло на своє місце. І дуже запали́вся їхній гнів на Юду, і вони вернулися на своє місце в запа́леному гніві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'А Амація зміцни́вся, і попровадив свій наро́д, і пішов до Соляної долини, і побив десять тисяч Сеїрових синів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'а десять тисяч живих узяли́ Юдині сини до неволі. І привели́ їх на верхі́в\'я скелі, і поскида́ли їх з верхі́в\'я тієї скелі, — і всі вони позабивалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'А люди того ві́йська, що Амація вернув, щоб не йшли з ним на війну, розси́палися по Юдиних містах від Самарії й аж до Бет-Хорону, і повбива́ли з них три тисячі, і пограбували велику здо́бич.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'І сталося по то́му, як прийшов Амація, побивши едо́млян, то він приніс богів Сеїрових синів, і поставив їх собі за богів, і перед ними вклоня́вся, і їм кадив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'І запали́вся Господній гнів на Амацію, і Він послав до нього пророка, а той сказав йому́: „На́що ти звертався до богі́в цього народу, богів, що не врятували народу свого від твоєї руки?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'І сталося, як він говорив це до нього, сказав йому цар: „Чи я поставив тебе за царевого дора́дника? Перестань собі, нащо вбивати тебе?“І перестав той пророк, але сказав: „Я знаю, що Бог постановив погубити тебе, бо зробив ти це, і не слухав моєї поради“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'І радився Амація, цар Юдин, і послав до Йоаша, сина Єгоахаза, сина Єгу, Ізраїлевого царя, говорячи: „Іди но, поміряємось!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'І послав Йоаш, Ізраїлів цар, до Амації, Юдиного царя, говорячи: „Терни́на, що на Лива́ні, послала до кедри́ни, що на Ливані, кажучи: Дай но дочку́ свою́ моєму синові за жінку! Та перейшла польова́ звірина́, що на Ливані, і витоптала ту терни́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Ти сказав: Ось побив ти Едома, і підне́сло тебе серце твоє, щоб пиша́тися. Тепер сиди ж у своєму домі. На́що будеш дрочи́тися зо злом, і впадеш ти та Юда з тобою?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Та не послухався Амація, бо від Бога було це, щоб віддати їх у руку ворога, бо зверта́лися вони до едо́мських богів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'І вийшов Йоаш, Ізраїлів цар, і зустрі́лися він та Амація, цар Юдин, у Юдиному Бет-Шемеші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'І був побитий Юда перед Ізраїлем, і повтікали кожен до намету свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'А Йоаш, цар Ізраїлів, схопи́в Амацію, Юдиного царя, сина Йоаша, сина Єгоахаза, у Бет-Шемеші, і привів його до Єрусалиму, і зробив пролі́м в єрусалиському мурі, від Єфремової брами аж до брами Нарі́жної, чотири сотні ліктів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'І забрав він усе золото й срібло, та ввесь по́суд, що знахо́дився в Божому домі в Овед-Едома, та ска́рби царевого дому, та закла́дників, і вернувся в Самарію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'І жив Амація, Йоашів син, цар Юдин, по смерті Йоаша, Єгоахазового сина, Ізраїлевого царя, п\'ятнадцять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'А решта діл Амації, перші та останні, ото вони написані в Книзі Царів Юдиних та Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'А від ча́су, коли Амація відступив від Господа, то склали на нього змову в Єрусалимі, та він утік до Лахішу. І послали за ним до Лахішу, — і вбили його там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'І пове́зли його на ко́нях, і поховали його з батька́ми його в Давидовому Місті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'І взяв увесь Юдин народ Уззійю, — а він був шістнадцяти літ, — і настанови́ли його царем замість батька його Амації.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Він збудував Елота, і вернув його Юді, як цар спочив зо своїми батьками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Уззійя був віку шістнадцяти літ, коли він зацарював, а п\'ятдеся́т і два роки царював в Єрусалимі. А ім\'я́ його матері — Єхолія, з Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'І робив він угодне в Господніх оча́х, усе, що́ робив батько його Амація.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'І став він звертатися до Бога за днів Заха́рія, що розумів Божі виді́ння. А за днів, коли він звертався до Господа, Бог давав йому у́спіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'І він вийшов, і воював із филисти́млянами, і поруйнував мур міста Ґату, і мур Явне, і мур Асдоду, і побудував міста́ в Асдоді та в филисти́млян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'І допоміг йому Бог над филисти́млянами, і над арабами, що живуть у Ґур-Баалі, та над мецнітами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'І давали аммоні́тяни дани́ну для Уззійї, а ім\'я́ його проне́слося аж туди, де йдеться до Єгипту, бо він сильно зміцни́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'І збудував Уззійя башту в Єрусалимі над брамою Пінна, і над брамою Ґай, і над Мікцоа, і позмі́цнював їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'І побудував він ба́шти в пустині, і повисі́кував багато ям для води, бо мав великі че́реди і на долині, і на рівни́ні, рільників, і виноградарів у гора́х, і садки́, бо він любив хліборо́бство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'І було́ в Уззійї ві́йсько, що прова́дило війну, яке вихо́дило на війну відділом за числом їхнього пере́ліку через писаря Єіїла та урядника Маасею, під рукою Хананії з царе́вих зверхників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Усе число голів ба́тьківських родів, хоробрих воякі́в, дві тисячі й шість сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'А при них ві́йська, — три сотні тисяч і сім тисяч і п\'ять сотень тих, що провадять війну великою силою, щоб допомагати царе́ві на ворога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'І нагото́вив для них Уззійя для всього ві́йська щити́ малі́ й ра́тища, і шоло́ми, і па́нцери, і лу́ки, і пра́щного камі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'І наробив він в Єрусалимі військо́вих маши́н, майстерно приду́маних, щоб були́ вони на баштах і на ро́гах на стріля́ння стрі́лами та великим камінням. І проне́слося ім\'я́ його аж надто дале́ко, бо він дивно зробив, щоб допомогти собі, так що став си́льним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'А як він зміцні́в, запиша́лося його серце аж до зіпсуття́, і він спроневі́рився Господе́ві, Богові своєму. І ввійшов він до храму Господнього, щоб кадити на кади́льному же́ртівнику.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'А за ним пішов священик Азарія, а з ним Господні священики, вісімдеся́т хоробрих мужів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'І стали вони проти царя Уззійї та й сказали йому: „Не тобі, Уззійє, кадити для Господа, а священикам, синам Аароновим, посвяченим на кадіння... Вийди зо святині, бо ти спроневі́рився, і не за честь це бу́де тобі від Господа Бога!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'І розгнівався Уззійя, — а в руці його була кади́льниця на каді́ння. А коли він розгнівався на священиків, то на чолі́ його показа́лася прока́за, перед священиками в Господньому домі, при кади́льному же́ртівнику...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'І глянув на нього первосвященик Азарія та всі священики, аж ось він прокаже́ний на чолі́ своїм! І вони поспішно ви́гнали його звідти, та й сам він поспішив вийти, бо вра́зив його Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'І був цар Уззійя прокаже́ний аж до дня своєї смерти, і сидів в осібному домі прокаже́ний, бо був ви́лучений від Господнього дому. А над царськи́м домом був син його Йотам, — він судив наро́д Кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'А решту діл Уззійї, перші й останні, описав пророк Ісая, син Амосів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'І спочив Уззійя з своїми батька́ми, і поховали його з батьками його на погребовому царсько́му полі, бо сказали: „Він прокаже́ний“. А замість нього зацарював син його Йота́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Йота́м був віку двадцяти й п\'яти років, коли зацарював, і шістнадцять літ царював в Єрусалимі. А ім\'я́ його матері — Єруша, Садокова дочка́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'І робив він уго́дне в Господніх оча́х, усе, що робив був його батько Уззійя. Тільки він не вхо́див до Господнього храму, та народ іще грішив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Він збудував горі́шню браму Господнього дому, і багато побудував на му́рі Офел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'І побудува́в він міста́ в Юдиних гора́х, а в лісах побудував тверди́ні та ба́шти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'І він воював з царем аммоні́тян, і був сильніший від них. І дали́ йому аммоні́тяни того року сотню талантів срібла, і десять тисяч ко́рів пшениці та десять тисяч ячме́ню. Це дава́ли йому́ аммоні́тяни й року другого та третього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'І став сильний Йота́м, бо поправив дороги свої перед лицем Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'А решта Йотамових діл, і всі ві́йни його та доро́ги його, — ось вони описані в Книзі Царів Ізраїлевих та Юдиних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Він був віку двадцяти й п\'яти літ, коли зацарював, і шістнадцять літ царював в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'І спочив Йотам із своїми батька́ми, і поховали його́ в Давидовому Місті, а замість нього зацарював син його Ахаз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Аха́з був віку двадцяти літ, коли він зацарював, і шістнадцять літ царював в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'І ходив він доро́гами Ізра́їлевих царів, а також робив литих бовванів Ваалів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'І він кадив у долині Бен-Гіннома, і палив своїх синів огнем за гидо́тами тих народів, що Господь повиганяв їх перед Ізраїлевими синами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'І він прино́сив же́ртви та кадив на па́гірках і на висо́тах, та під кожним зеленим деревом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'І дав його Господь, Бог його, в руку сирійського царя, і вони повбивали з його війська та взяли́ до неволі від нього багатьох полоне́них, і спровадили до Дама́ску. Крім то́го, він був ви́даний і в руку Ізраїлевого царя, і той ура́зив його великою пора́зою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'І побив Пеках, син Ремалії, в Юді сто й двадцять тисяч одного дня, все мужів хоро́брих, за те, що залишили вони Господа, Бога їхніх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'А Зіхрі, лицар Єфремів, забив Маасею, царсько́го сина, й Азрікама, володаря дому, й Елкану, другого по царі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'І Ізраїлеві сини взяли́ до неволі зо своїх братів двісті тисяч жіно́к, синів та дочо́к, а також пограбува́ли від них велику здо́бич, і спрова́дили ту здобич до Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'А там був Господній пророк, Одед ім\'я́ йому. І він вийшов перед ві́йсько, що вхо́дило до Самарії, та й сказав їм: „Ось Господь, Бог ваших батькі́в, у гніві на Юду, віддав їх у вашу руку, а ви повибива́ли між ними з лютістю, яка досягла́ аж до небе́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'А тепер ви заду́муєте здобути собі за рабів та за неві́льниць дітей Юди та Єрусалиму. Чи ж за вами самими нема провин проти Господа, Бога вашого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Отож, послухайте мене тепер, і верніть тих полоне́них, яких взяли́ ви до неволі з ваших братів, бо на вас ре́вність Господнього гніву!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'І встали дехто з голів Єфремових синів: Азарія, син Єгоханана, Берехія, син Мешіллемотів, і Єхізкійя, син Шаллумів, і Амаса, син Хадлаїв, проти тих, що прихо́дили з ві́йська,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'та й сказали до них: „Не приво́дьте цих полоне́них сюди, бо на провину нам проти Господа ви заду́муєте додати це до наших гріхів та до нашої прови́ни. Бо велика наша прови́на та жар гніву Господнього на Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'І озбро́єні покинули тих полоне́них та ту здо́бич перед зверхниками та всім збором.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'І встали ті мужі, що були́ озна́чені імена́ми, і взяли́ полоне́них, і всіх їхніх наги́х позодяга́ли зо здо́бичі, і зодягну́ли їх, і обу́ли їх, і нагодува́ли їх, і напоїли їх, і намасти́ли їх, і кожного слабо́го з них пове́зли на ослах. І припрова́дили їх до Єрихо́ну, мі́ста пальм, до їхніх братів, а самі вернулися до Самарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Того ча́су послав цар Аха́з до асирійських царів, щоб допомогли́ йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Прийшли ще й едо́мляни, і побили багатьо́х між Юдою, і взяли до неволі полоне́них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'А филисти́мляни розси́палися по містах Шефелі та Юдиного Неґеву, і здобули́ Бет-Шемеш, і Айялон, і Ґедерот, і Сохо та зале́жні міста його, і Тімну та залежні міста її, і Ґімзо та залежні міста його, й осі́лися там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Бо Господь прини́зив Юду через Ахаза, Ізраїлевого царя, бо завільно поступав він щодо Юди, і спроневі́рився великим гріхом проти Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'І прийшов на нього Тіґлат Пілнеесер, цар асирійський, й утискав його, і не допоміг йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Бо Аха́з пограбував був Господній дім, і дім царів, і зверхників, і дав це асирійському царе́ві, та не було це на по́міч йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'А в ча́сі утиску його́, то продовжував спроневі́рюватися Господе́ві він, той цар Аха́з.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'І прино́сив він жертви дама́ським бога́м, що його поби́ли, і говорив: „Через те, що боги сирійських царів допомагають їм, то бу́ду прино́сити їм жертви, і вони будуть допомагати мені!“А вони були йому на те, щоб спотикався він та ввесь Ізраїль!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'І Ахаз зібрав по́суд Божого дому, і порубав по́суд Божого дому. І позамикав він двері Господнього дому, і поробив собі же́ртівники в кожному куті́ в Єрусалимі...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'І в кожному місті Юдиному пороби́в він па́гірки, щоб кадити іншим богам, — і розгні́вав Господа, Бога батьків своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'А решта його діл та всі доро́ги його, перші й останні, ото вони описані в Книзі Царів Юдиних та Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'І спочив Аха́з зо своїми батька́ми, і поховали його в місті, в Єрусалимі, бо не вне́сли його до гробі́в Ізраїлевих царів, а замість нього зацарював син його Єзекі́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Єзекі́я зацарював у віці двадцяти́ й п\'яти́ літ, а двадцять і дев\'ять літ царював він в Єрусалимі. А ім\'я́ його матері — Авійя, дочка́ Захарії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'І робив він угодне в Господніх оча́х, як усе, що робив був його ба́тько Давид.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Він першого року свого царюва́ння, місяця першого відчини́в двері Господнього дому, і попра́вив їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'І привів він священиків та Левитів, і зібрав їх на схі́дню пло́щу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'та й сказав їм: „Послухайте мене, Левити! Освяті́ться тепер, і освятіть дім Господа, Бога ваших батьків, і ви́несіть нечисть із святині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Бо наші батьки сироневі́рилися, і робили лихе́ в оча́х Господа, Бога нашого, і залишили Його, і відвернули своє обличчя від Господньої скинії, й обернулися спи́ною до неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Також замкну́ли вони двері притво́ру, і погасили лямпа́дки, а кадила не кадили, і цілопа́лення не прино́сили в святині для Ізраїлевого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'І був Господній гнів на Юду та на Єрусалим, і Він дав їх на га́ньбу, і на спусто́шення, і на посміхо́вище, як ви бачите своїми очи́ма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'І ось попа́дали наші батьки від меча, а наші сини, і наші до́чки, і жінки наші в неволі за це!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Тепер на моєму серці лежить скла́сти заповіта з Господом, Ізра́їлевим Богом, — і нехай Він відве́рне від нас жар гніву Свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Сини мої, не будьте недбалі тепер, бо вас Господь вибрав ставати перед лицем Його на службу Йому, та щоб служити Йому й кадити Йому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'І встали Левити: Махат, син Амасаїв, і Йоїл, син Азарії, від синів Кегатових; а від синів Мерарієвих: Кіш, син Авдіїв, і Азарія, син Єгаллел\'їлів; а від Ґершонівців: Йоах, син Зіммин, і Еден, син Йоахів;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'а від синів Еліцафанових: Шімрі, і Єіїл; а від синів Асафових: Захарій та Маттанія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'А від Геманових синів: Єхіїл, і Шім\'ї; а від синів Єдутунових: Шемая та Уззіїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'І зібрали вони братів своїх, і освятилися, і пішли за нака́зом царськи́м у справах Господніх, щоб очистити Господній дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'І повхо́дили священики до сере́дини Господнього дому на очи́щення. І повино́сили вони всю нечистість, яку знайшли в Господньому храмі, до подвір\'я Господнього дому, а Левити взяли́ це, щоб винести назо́вні до долини Кедро́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'І зачали́ вони першого дня першого місяця освящати, а восьмого дня того місяця ввійшли до Господнього притво́ру. І освятили вони Господній дім за вісім день, а шістнадцятого дня першого місяця закінчи́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'І ввійшли вони в сере́дину дому до царя Єзекії та й сказали: „Очистили ми ввесь Господній дім, і же́ртівника цілопа́лення, та всі його речі, і стіл укладання хлібі́в та всі його речі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'А всі ті речі, які цар Ахаз занеха́в був за свого царюва́ння, коли спроневі́рився, ми приготовили та освятили, і ось вони перед Господнім же́ртівником“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'І встав рано цар Єзекія, і зібрав зверхників міста та й увійшов до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'І привели́ вони сім биків, і сім барані́в, і сім ове́чок, і сім козлів на жертву за гріх: за царство, і за святиню, і за Юду, а він звелів Ааро́новим синам, священикам, прине́сти це в жертву на Господньому же́ртівнику.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'І порізали ту велику худобу, а священики прийняли́ кров і покропи́ли на жертівника; і порізали баранів, і покропили ту кров на жертівника; і порізали ове́чок, і покропили ту кров на жертівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'І привели́ козлів жертви за гріх перед царя та збори, і вони поклали свої руки на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'І зарізали їх священики, а їхньою кров\'ю очи́стили жертівника, щоб очистити всього Ізраїля, бо за всього Ізраїля звелів цар принести це цілопа́лення та цю жертву за гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'І поставив він Левитів Господнього дому з цимба́лами, з а́рфами та з ци́трами, за нака́зом Давида та Ґада, царе́вого прозорли́вця, та пророка Ната́на, бо в руці Господа наказ, що йде через пророків Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'І постава́ли Левити з Давидовим знаря́ддям, а священики — із су́рмами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'І сказав Єзекі́я принести цілопа́лення на жертівника. А коли розпочали́ цілопа́лення, зачався спів Господе́ві та звуки су́рем і музи́чного знаря́ддя Давида, Ізраїлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'І ввесь збір вклонився, і співаки́ співали, а су́рми сурми́ли, — це все аж до кінця цілопа́лення!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'А як скінчи́ли прино́сити жертву, попа́дали навко́лішки цар та всі, що були з ним, і вклони́лися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'І сказав цар Єзекія та зверхники до Левитів, щоб вони хвалили Господа словами Давида та прозорли́вця Асафа, — і вони хвалили з великою радістю, і схилялися, і вклоня́лися до землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'І відпові́в Єзекі́я й сказав: „Тепер ви освя́чені для Господа. Підійдіть, і приведі́ть жертви та при́носи вдячні для Господнього дому“. І привів збір жертви та при́носи вдячні, і кожен, хто мав жертве́нне серце, — прино́сив цілопа́лення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'І було число цілопа́лення, що спрова́див збір: худоби великої — сімдеся́т, барані́в — сотня, ове́чок — двісті, для цілопа́лення Господе́ві все це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'А для святости: худоби великої — шість сотень, а худоби дрібно́ї — три тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Тільки священиків було мало, і не могли́ вони обдира́ти шкур зо всіх цілопа́лень; і допомага́ли їм їхні брати Левити аж до скі́нчення праці, і поки освятилися священики, бо Левити були простосердіші на освя́чення, аніж священики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'І також було багато па́лень серед мирних жертов і серед жертов литих до цілопа́лення. І так була відновлена служба Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'І радів Єзекі́я та ввесь народ тим, що́ Бог приготовив для народу, бо та річ сталася несподі́вано!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'І послав Єзекія по всьому Ізраїлю та по Юдеї, а також написав листи́ до країв Єфрема та Манасії, щоб прийшли до Господнього дому в Єрусалимі, щоб спра́вити Пасху для Господа, Ізраїлевого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'І радився цар і зверхники його та ввесь збір в Єрусалимі, щоб справити Пасху другого місяця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Бо не могли справити її того ча́су, бо священики не освятилися в потрі́бному числі, а наро́д не зібрався до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'І була вгодна та річ в оча́х царевих та в оча́х усього збору.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'І вони постанови́ли оголоси́ти по всьому Ізраїлю від Беер-Шеви й аж до Дана, щоб прихо́дили справити Пасху для Господа, Ізраїлевого Бога, в Єрусалим, бо не часто робили її так, як написано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'І пішли бігуни́ з листа́ми від царя та його зверхників по всьому Ізраїлі та Юдеї, та за нака́зом царя говорили: „Ізра́їлеві сини, верніться до Господа, Бога Авраамового, Ісакового та Ізраїлевого, — і Він пове́рнеться до останку, позосталого вам із руки асирійських царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'І не будьте такі, як ваші батьки та як ваші брати, що спроневі́рилися Господе́ві, Богові їхніх батьків, — і Він дав їх на спусто́шення, як ви бачите.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Тепер не будьте твердоши́ї, як ваші батьки. Покоріться Господе́ві, і ввійдіть до святині Його, яку Він освятив навіки, і служіть Господе́ві, Богові вашому, і Він відве́рне від вас жар гніву Свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Бо як ви наве́рнетесь до Господа, то брати́ ваші та ваші сини зна́йдуть милосердя в своїх поневі́льників, і зможуть вернутися до цього Кра́ю, — бо милости́вий і милосердний Господь, Бог ваш, і Він не відве́рне лиця від вас, якщо ви наве́рнетеся до Нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'І сторожі́ все перехо́дили з міста до міста по кра́ю Єфремовому та Манасіїному й аж до Завуло́на. Та люди глузува́ли з них, і висміювали їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Тільки люди з Асира, і Манасії та з Завулона впокори́лися, і поприхо́дили до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Також в Юдеї була Божа рука, щоб дати їм одне серце для ви́конання наказу царя та зверхників за Господнім словом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'I зібрався до Єрусалиму числе́нний народ, щоб справити свято Опрі́сноків другого місяця, збір дуже числе́нний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'І встали вони, і повикида́ли і́дольські же́ртівники, що були в Єрусалимі, і повикида́ли всі кадильниці, та й повкидали до долини Кедро́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'І зарізали пасха́льне ягня чотирнадцятого дня другого місяця, а священики та Левити засоро́милися й освятилися, і прине́сли цілопа́лення до Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'І постава́ли вони на своє́му місці за їхнім правом, за Зако́ном Мойсея, чоловіка Божого. Священики кропили кров, беручи́ з руки Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Багато бо було в зборі, що не освятилися, тому Левити були для рі́зання пасха́льних ягнят за кожного нечистого, щоб посвятити для Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Бо бе́зліч наро́ду, багато з Єфрема та Манасії, Іссахара та Завулона не очи́стилися, але їли Пасху, не так, як написано. Та Єзекія молився за них, говорячи: „Добрий Господь про́стить кожному,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'хто все своє серце міцно встанови́в, щоб звертатися до Бога, Господа, Бога батьків своїх, хоч не зробив він за правилами чистости святині“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'І послухав Господь Єзекію, і прости́в народ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'І справля́ли Ізраїлеві сини, що знахо́дилися в Єрусалимі, свято Опрісноків сім день з великою радістю, а Левити та священики день-у-день сла́вили Господа всією силою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'І промовляв Єзекія до серця всіх Левитів, що мали добре розуміння для Господа. І їли святко́ву жертву сім день, і прино́сили мирні жертви, і сповіда́лися Господе́ві, Богові батьків своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'І ввесь збір нара́дився справити свято ще другі сім день, — і справля́ли сім день в радості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Бо Єзекія, цар Юдин, дав для збору тисячу биків і сім тисяч худоби дрібно́ї, а зверхники дали́ для збору тисячу биків і десять тисяч худоби дрібно́ї. І освятилося багато священиків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'І радів увесь Юдин збір, і священики та Левити, і ввесь збір, що прийшов з Ізраїля, і прихо́дьки, що поприхо́дили з Ізраїлевого Краю, та ті, що сиділи в Юдеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'І була велика радість в Єрусалимі, бо від днів Соломона, Давидового сина, Ізраїлевого царя, не було такого, як оце в Єрусалимі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'І встали священики та Левити, і поблагословили наро́д. І почутий був їхній голос, а їхня молитва дійшла до оселі святости Його́, — до небе́с!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'А коли це все скінчи́лося, вийшов увесь Ізраїль, що знахо́дився там, до Юдиних міст, і полама́ли стовпи́ для божків, і постина́ли посвячені дере́ва, і порозбивали па́гірки та же́ртівники в усьому Юді й Веніямині, і в Єфремі та Манасії аж до кінця. Пото́му верну́лися всі Ізра́їлеві сини, кожен до своєї посілости, до своїх міст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'І Єзекі́я поставив че́рги священиків та Левитів за їхніми ві́дділами, кожного за його слу́женням, зо священиків та з Левитів, на цілопа́лення, і на мирні жертви, — на слу́ження й на подяку, і на хвалу в брамах Господніх таборів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'А царева частка зо здобу́тку його приділена була на цілопа́лення: на цілопалення ранішні та вечірні, і на цілопалення на суботи й на молодики́ та на свята, як написано в Зако́ні Господньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'І наказа́в він наро́дові, ме́шканцям Єрусалиму, давати частку священичу та левитську, щоб вони були ревними в Зако́ні Господньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'А як поши́рився той нака́з, поназно́сили Ізраїлеві сини багато первопло́дів збіжжя, виноградного соку, і ново́ї оливи, і меду, і всякого полевого врожа́ю; і як десятину того всього багато поназно́сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'А Ізраїлеві та Юдині сини, що сиділи по Юдиних містах, також вони поприно́сили десятину худоби великої та худоби дрібно́ї, і десятину святих рече́й, посвя́чених Господе́ві, їхньому Богові, і понадава́ли того багато куп.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Третього місяця зачали́ складати ті купи, а місяця сьомого закінчи́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'І прийшли Єзекія та зверхники, і побачили ті купи, — і поблагослови́ли Господа та наро́д Його, Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'І виві́дував Єзекія священиків та Левитів про ті купи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'І говорив до нього священик Азарія, голова Садокового дому, і сказав: „Відко́ли зачали́ прино́сити прино́шення до Господнього дому, ми їли й були ситі, і багато позоста́лося, бо Господь поблагословив наро́д Свій. А з останків скла́дено оцю многоту́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Тоді Єзекія наказав пригото́вити комо́ри в Господньому домі, — і пригото́вили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'І вірно перене́сли туди прино́шення, і десятину, і святощі, а над ними володарем був Левит Конанія, а брат його Шім\'ї — дру́гим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'А Єхіїл, і Азазія, і Нахат, і Асагел, і Єрімот, і Йозавад, і Еліїл, і Їсмахія, і Махат, і Беная були урядо́вцями під рукою Конанії та брата його Шім\'ї, призна́чені царем та Азарієм, володарем при Божому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'А Коре, син Їмни, Левит, придве́рний зо схі́днього боку, був над добровільними жертвами Богові, щоб видавати Господні приношення та речі найсвятіші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'А при ньому були: Еден, і Мін\'ямін, і Єшуа, і Шемая, Амарія, і Шеханія по священичих містах, щоб вірно роздавати їхнім братам за че́ргами, як великому, так і мало́му,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'окрім їхніх позапи́суваних: для мужчин від віку трьох літ і вище, для кожного, хто прихо́див до Господнього дому на щоденне ді́ло, на їхнє слу́ження, за їхніми сторо́жами та за їхніми че́ргами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'і приписаним священикам до дому їхніх батьків, та Левитам — від віку двадцяти літ і вище, у сторо́жах їхніх та в че́ргах їхніх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'і їхнім припи́саним з усіма́ їхніми ді́тьми, їхніми жінка́ми, і їхніми синами, і їхніми до́чками, для всього збору, бо вони в вірності своїй посвящаються на святість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'А синам священика Ааро́на, на поля́х пасови́ська їхніх міст, у кожному місті поставлені були мужі, що зазначені поіме́нно, щоб давати частки кожному мужчи́ні серед священиків та всякому приписаному серед Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'І зробив Єзекія так, як це, по всій Юдеї. І робив він добре й угодне та справедливе перед лицем Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'І в усякому ді́лі, яке він зачинав, — у роботі Божого дому, і в Зако́ні, і в заповіді, щоб звертатися до Бога свого, робив він усім своїм серцем, і мав успіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'По цих справах та по цій вірності прийшов Санхері́в, цар асирійський, і ввійшов в Юдею, і розклався табо́ром проти укрі́плених міст, і ду́мав здобути їх собі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'І побачив Єзекі́я, що прийшов Санхері́в, і що він заду́мує війну на Єрусалим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'то він нара́дився зо своїми зверхниками та своїми ли́царями позатика́ти джере́льні во́ди, що назовні міста. І вони допомогли йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'І було зі́брано багато народу, і вони позатика́ли всі джере́ла й поті́к, що плив у Краю́, говорячи: „На́що б мали так багато води асирійські царі, коли при́йдуть?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'І він підбадьорився, і забудував увесь ви́ломаний мур, і поставив на нього ба́шту, а поза тим муром — інший мур, і зміцни́в Мілло в Давидовому Місті, і наробив багато ра́тищ та щиті́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'І понаставляв він над народом військо́вих зверхників, і зібрав їх до себе, на майда́н біля місько́ї брами, і промовляв до їхнього серця, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '„Будьте міцні́ та будьте мужні, не бійтеся й не жахайтеся перед асирійським царем та перед усім тим на́товпом, що з ним, бо з нами більше, ніж із ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'З ним раме́но тіле́сне, а з нами Господь, Бог наш, щоб допомагати нам та воюва́ти наші ві́йни!“І оперся народ на слова Єзекії, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'По цьому послав Санхері́в, асирійський цар, своїх рабів до Єрусалиму, — а він сам таборува́в проти Лахішу, і вся сила його була́ з ним, — до Єзекії, Юдиного царя, і до всього Юди, що в Єрусалимі, сказати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '„Так говорить Санхері́в, цар асирійський: На що́ ви сподіва́єтесь і сидите в обло́зі в Єрусалимі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Оце Єзекія намовляє вас, щоб дати вас на смерть від голоду та від спра́ги, кажучи: Господь, Бог наш, урятує нас від руки асирійського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Чи ж не він, Єзекія, поруйнував па́гірки його та же́ртівники його, і сказав до Юди та до Єрусалиму, говорячи: Перед одним же́ртівником будете вклонятися й на ньому бу́дете кадити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Чи ж ви не знаєте, що́ зробив я та батьки мої всім наро́дам земель? Чи справді могли бо́ги наро́дів тих країв урятувати свій край від моєї руки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Хто́ з-поміж усіх богів цих народів, яких мої батьки вчинили закляттям, міг урятувати свій народ від моєї руки? Як зможе Бог ваш урятувати вас від моєї руки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'А тепер нехай не обманює вас Єзекія, і нехай не зво́дить вас, як оце. І не вірте йому, бо не зміг жо́ден бог жо́дного наро́ду та царства врятувати свого народу від моєї руки та від руки батьків моїх, то тим більше ваші бо́ги не врятують вас від моєї руки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'І ще говорили його раби на Господа, Бога, та на Його раба Єзекію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'І писав він листи́ з ла́йкою на Господа, Ізраїлевого Бога, і говорив на Нього таке: „Як бо́ги народів тих країв не спасли свого народу від моєї руки, так не спасе Єзекіїн Бог народу Свого від моєї руки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'І кли́кали вони сильним голосом по-юде́йському до єрусалимського народу, що був на мурі, щоб настраши́ти їх та налякати їх, щоб здобути місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'І говорили вони на Бога єрусалимського, як на богі́в землі, чин лю́дських рук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'І молився цар Єзекія та пророк Ісая, син Амосів, про це, і кликали до неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'І послав Господь Ангола, і він вигубив кожного хороброго вояка́, і володаря, і зве́рхника в табо́рі царя асирійського, і той вернувся з со́ромом обличчя до кра́ю свого. А коли він прийшов до дому бога свого, то дехто з тих, що вийшли з нутра́ його, вбили його там мече́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'І спас Господь Єзекію та єрусалимських ме́шканців від руки Санхеріва, царя асирійського, та від руки всякого, і дав їм мир навко́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'І багато-хто прино́сили да́ра для Господа до Єрусалиму та дорогоцінні речі для Єзекії, Юдиного царя. І він по цьо́му піднісся в оча́х усіх наро́дів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Тими днями занеду́жав Єзекія смертельно. І він молився до Господа, — і Він відповів йому, і дав йому знака.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Та Єзекія не віддав так, як було зро́блено йому, бо запишни́лося серце його. І був гнів Божий на нього, і на Юдею, та на Єрусали́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Але впокори́вся Єзекія в пишноті серця свого, він та ме́шканці Єрусалиму, — і не прийшов на них Господній гнів за днів Єзекії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'І було в Єзекії дуже багато багатства та слави, і він поробив собі скарбни́ці на срібло й на золото, та на камінь дорогий, і на па́хощі, і на щити́, і на всякі дорогі речі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'і клуні́ на врожай збі́жжя, і виноградного соку, і свіжої оливи, і жолоби́ для всякої худоби, і жолоби́ для чері́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'І побудував він собі міста́, і мав великий набу́ток худоби дрібно́ї та худоби великої, бо Бог дав йому́ дуже великий маєток.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'І він, Єзекія, заткнув вихід води горі́шнього Ґіхону, і вивів її вдоли́ну на за́хід від Давидового Міста. І мав Єзекія у́спіх в усіх своїх діла́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Тільки при посла́х вавилонських зверхників, посланих до нього, щоб вивідати про чудо, що було в Краю́, залишив був його Бог, щоб ви́пробувати його, щоб пізнати все в його серці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'А решта діл Єзекії та його чесно́ти, — ото вони описані в видіннях пророка Ісаї, Амосового сина, у Книзі Царів Юдиних та Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'І спочив Єзекія з батьками своїми, і поховали його на узбі́ччях гробі́в Давидових синів, і віддали́ йому честь по смерті його, — уся Юдея та ме́шканці Єрусалиму. А замість нього зацарював син його Манасі́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Манасі́я був віку дванадцяти літ, коли він зацарював, і царював в Єрусалимі п\'ятдеся́т і п\'ять літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'І робив він лихе́ в Господніх оча́х, за поганською гидо́тою тих наро́дів, яких вигнав Господь з-перед Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'І він зно́ву побудував па́гірки, які порозбивав був його батько Єзекія, і понаставля́в же́ртівники для Ваалів, і поробив Аста́рти, і вклонявся всім небе́сним си́лам, і служив їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'І побудував він же́ртівники в Господньому домі, про якого сказав був Господь: „В Єрусалимі буде Ім\'я́ Моє навіки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'І побудував він же́ртівники для всіх небесних сил на обох подві́р\'ях Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'І він перепроваджував своїх синів через огонь у долині Гінномового сина, і гадав, і ворожив, і чарував, і настановля́в викликувачів ду́хів померлих і ду́хів віщих, і багато робив зла в оча́х Господа, щоб гніви́ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'І поставив він рі́заного бовва́на, якого зробив, у Божому домі, про якого Бог сказав був до Давида та до сина його Соломона: „У цьому домі та в Єрусалимі, що його Я вибрав зо всіх міст Ізраїлевих племен, покладу Я Ім\'я́ Своє навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'І більше не виступить Ізраїлева нога з тієї землі, яку Я дав вашим батька́м, якщо тільки вони бу́дуть пильнувати робити все так, як наказав Я їм, увесь Зако́н, і устави, і постанови, дані через Мойсея“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Та Манасі́я робив блудли́вими Юдею та ме́шканців Єрусалиму, щоб робити гірше від тих народів, яких Господь вигубив з-перед Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'І говорив Господь до Манасії та до народу його, та не слухались вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'І Господь навів на них зверхників війська асирійського царя, а вони схопи́ли Манасію на по́від, і скували його мідяни́ми кайда́нами та й повели́ його до Вавило́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'А як був він ути́скуваний, благав він лице Господа, Бога свого, і дуже впокори́вся перед лицем Бога своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'І молився він до Нього, і Він був убла́ганий, і вислухав блага́ння його, і вернув його до Єрусалиму, до царства його. І пізнав Манасія, що Господь — Він Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'По цьому збудував він зо́внішній мур для Давидового Міста на за́хід від Ґіхону, в долині, до входу в Рибну браму, й оточив Офела й дуже ви́соко підняв його. І понаставля́в він військо́вих зверхників по всіх укрі́плених містах Юдеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'І повикида́в він чужих богі́в та подобу бовва́на з Господнього дому, і всі же́ртівники, що він побудував був на горі Господнього дому та в Єрусалимі, і викинув те поза місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'І збудував він Господнього же́ртівника, і приніс на ньому жертви приносів мирних та вдячних, і звелів юдеям служити Господе́ві, Богові Ізраїлевому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Але народ прино́сив жертви ще на па́гірках, тільки вже Господеві, Богові своєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'А решта діл Манасії, і його молитва до Бога його, і слова прозорли́вців, що говорили до нього Ім\'ям Господа, Бога Ізраїлевого, — ото вони описані в історії Ізраїлевих царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'А молитва його, і як Він був убла́ганий, і ввесь його гріх та його спроневі́рення, і місця́, що побудував на них па́гірки й поставив Аста́рти та бовва́ни перед своїм упоко́ренням, — ось вони описані в словах його прозорли́вців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'І спочив Манасія з батька́ми своїми, і поховали його в домі його, а замість нього зацарював син його Амо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Амон був віку двадцяти́ й двох років, коли він зацарював, і царював він в Єрусалимі два роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'І робив він зло в Господніх оча́х, як робив його батько Манасі́я. А всім бовва́нам, яких наробив його ба́тько Манасія, Амо́н прино́сив жертви та служив їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'І не впокори́вся він перед Господнім лице́м, як упокори́вся був його батько Манасія, і він, Амон, побільши́в провину.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'І змо́вилися раби його на нього, і забили його в його домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Та наро́д Краю перебив усіх змо́вників на царя Амона. І настановив народ Краю царем замість нього сина його Йосі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Йосі́я був віку восьми́ літ, коли він зацарював, і царював в Єрусалимі тридцять і один рік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'І робив він угодне в Господніх оча́х, і ходив дорогами свого батька Давида, і не вступався ані право́руч, ані ліво́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'І восьмого року царюва́ння свого, бувши ще юнако́м, розпоча́в він зверта́тися до Бога батька свого Давида, а дванадцятого року розпочав очищати Юду та Єрусалим від па́гірків, і Аста́рт, і бовва́нів рі́заних та литих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'І порозбивали перед ним Ваалові же́ртівники, а стовпи́ сонця, що були на них, він повиру́бував, а Астарти, і бовва́ни різані та литі полама́в і розтер, і розкидав на гроби́ тих, хто прино́сив їм жертви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'А кості жерців попалив на їхніх же́ртівниках, і очи́стив Юдею та Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'А по містах Манасії, і Єфрема, і Симеона, і аж до Нефталима по їхніх руїнах навко́ло');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'порозбива́в же́ртівники та Аста́рти, і потовк бовва́ни на порох, а всі ідоли сонця повиру́бував в усьому Ізраїлевому кра́ї, і вернувся до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'А вісімнадцятого року царюва́ння його́, по очи́щенні Кра́ю та Божого дому, послав він Шафана, сина Ацалії, і Маасею, зверхника міста, та Йоаха, та ка́нцлера Йоаха, сина Йохазового, щоб напра́вити дім Господа, Бога його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'І прийшли вони до первосвященика Хілкійї, і дали срібло, що було зне́сене до Господнього дому, яке зібрали Левити, що стерегли́ поро́га, з руки Манасії й Єфрема, та з усієї решти Ізраїля, і з усього Юди й Веніямина та ме́шканців Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'I дали́ на руку робітникі́в праці, приста́влених до Господнього дому, а робітники тієї праці, що робили в Господньому домі, віддали́ на відбудову та на направу Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'І дали́ вони те́слям, і будівни́чим, щоб купувати те́сане камі́ння та дере́ва на зв\'я́зування та на покриття́ домів, що їх понищили Юдині царі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'А ті люди чесно вико́нували працю, а над ними були́ поста́влені Яхат та Овадія, Левити з синів Мерарієвих, і Захарій та Мешуллам із синів Кегатівців для керува́ння. А всі ті Левіти, що розумілися на музичних знаря́ддях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'були над носія́ми, і керували всіма́ робітника́ми на кожну роботу; а з Левитів були писарі́ й уря́дники та придве́рні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'А коли вони виймали срібло, прине́сене до Господнього дому, священик Хілкійя знайшов книгу Господнього Зако́ну, даного через Мойсея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'І відповів Хілкійя й сказав до пи́саря Шафана: „Я знайшов у Господньому домі книгу Зако́ну!“І дав Хілкійя ту книгу Діафанові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'І приніс Шафан ту книгу до царя, і приніс царе́ві ще відповідь, говорячи: „Усе, що да́но через твоїх рабів, вони роблять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'І вони ви́сипали те срібло, що зна́йдене в Господньому домі, і дали його на руку приста́влених та на руку робітникі́в праці“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'І доніс писар Шафан цареві, говорячи: „Священик Хілкійя дав мені книгу“. І Шафан перечитав з неї перед царем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'І сталося, як цар почув слова́ книги Зако́ну, то розде́р свої шати...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'І наказав цар Хілкійї, і Ахікамові, Шафановому синові, і Авдонові, Міхиному синові, і писареві Шафанові, і Асаї, царевому рабові, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '„Ідіть, зверніться до Господа про мене та про позосталих в Ізраїлі та в Юдеї, про слова́ цієї книги, що зна́йдена. Великий бо гнів Господній, що вилився на нас за те, що батьки наші не дотри́мували Господнього слова, щоб робити все, як написано в цій книзі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'І пішов Хілкійя та ті, кому́ звелів цар, до пророчиці Хулди, жінки Шаллума, сина Токегата, сина Хасриного, сто́рожа шат, а вона сиділа в Єрусалимі на Ново́му Місті, — і говорили до неї про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'А вона сказала до них: „Так говорить Господь, Бог Ізраїлів: Скажіть чоловікові, що послав вас до мене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Так говорить Господь: Ось Я наведу́ лихо на оце місце та на ме́шканців його, усі ті прокля́ття, що написані в книзі, яку читали перед Юдиним царем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'за те, що вони поки́нули Мене й кадили іншим бога́м, щоб гніви́ти Мене всіма́ ділами своїх рук. І вилився гнів Мій на це місце, — і він не погасне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'А Юдиному царе́ві, що послав вас звернутися до Господа, скажете йому так: Так говорить Господь, Бог Ізраїлів, — про ті слова́, які ти чув:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'За те, що зм\'якло твоє серце, і ти впокори́вся перед лицем Бога свого, коли ти почув слова́ Його на це місце та на ме́шканців його, і ти впокори́вся перед лицем Моїм, і розде́р свої шати та плакав перед Моїм лицем, то Я також почув, — говорить Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Ось Я прилучу́ тебе до батькі́в твоїх, і ти бу́деш прилу́чений до гробі́в своїх у споко́ї, і очі твої не побачать усього того лиха, що Я наведу́ на оце місце та на ме́шканців його!“І вони прине́сли відповідь цареві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'А цар послав, і зібрав усіх старши́х Юдеї та Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'І ввійшов до Господнього дому цар, і кожен муж Юдеї, і ме́шканці Єрусалиму, і священики, і Левити, і ввесь народ від великого й аж до мало́го, і він прочитав уго́лос слова́ книги Заповіту, зна́йденої в Господньому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'І став цар на своєму місці, і склав заповіта перед Господнім лицем, щоб ходити за Господом та додержувати заповіді Його, і сві́дчення Його, і устави Його всім серцем своїм та всім життям своїм, щоб вико́нувати слова́ того заповіту, що написані в тій книзі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'І наставив він кожного, хто знахо́дився в Єрусалимі та в Веніямині, до того. І ме́шканці Єрусалиму робили за заповітом Бога, Бога своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'І Йосі́я повикидав усі поганські гидо́ти з усіх країв, що в Ізраїлевих синів, і змусив кожного, хто знахо́дився в Ізраїлі, служити Господе́ві, їхньому Богові. За всіх днів його вони не відступали від Господа, Бога своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'І справив Йосія в Єрусалимі Пасху для Господа, і зарізали пасхальне ягня чотирнадцятого дня першого місяця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'І поставив він священиків на їхні стано́вища, і підбадьо́рував їх на службу Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'І сказав він Левитам, наста́вникам усього Ізра́їля, посвя́ченим для Господа: „Дайте святого ковчега до храму, що його збудува́в Соломон, син Давидів, цар Ізраїлів. Нема пощо вам носити його на раме́нах, — служіть тепер Господе́ві, вашому Богові, та Його наро́дові, Ізраїлеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'І приготу́йтеся за родом ваших батьків, за вашими че́ргами, за писа́нням Давида, Ізраїлевого царя, та за писа́нням його сина Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'І станьте в святині за ві́дділами ба́тьківських ро́дів ваших браті́в, синів народу, — а по́діл за ба́тьківськими домами в Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'І заріжте пасха́льне ягня́, й освятіться, і приготу́йте для ваших братів, щоб робити за Господнім словом, даним через Мойсея“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'І дав Йосі́я для лю́дських синів худоби дрібно́ї, ове́чок та молодих кіз, це все на пасха́льне ягня́ для кожного, хто знахо́дився в Єрусалимі, числом тридцять тисяч, а худоби великої — три тисячі. Це з набу́тку царе́вого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'А його зве́рхники дали́ на жертву для народу, для священиків та для Левитів: Хілкійя, і Захарій, і Єхіїл, старші́ в Божому домі, дали́ священикам на пасха́льні же́ртви дві тисячі й шість сотень худо́би дрібно́ї, а худоби великої — три тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'А Конанія, і Шемая, і брат його Натанаїл, і Хашавія, і Єіїл, і Йозавад, зверхники Левитів, дали́ для Левитів на пасхальні же́ртви п\'ять тисяч худо́би дрібно́ї, а худоби великої — п\'ять сотень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'І була́ міцно встано́влена служба, — і стали священики на своїм стано́вищі, а Левити — при своїх че́ргах, за нака́зом царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'І різали пасхальне ягня, а священики кропи́ли кров\'ю, беручи́ з їхньої руки, а Левити здирали шкуру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'І відділи́ли, що було на цілопа́лення, щоб дати їх за ві́дділами, по ба́тьківських дома́х сина́м народу на прино́шення Господе́ві, як написано в Мойсеєвій книзі. І так зробили й з худобою великою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'І пекли пасхальне ягня на огні, за постановою, а святі жертви варили в горшка́х, і в котла́х, і в горня́тах, і швидко не́сли всім синам народу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'А потім навари́ли собі та священикам, бо священики, Ааро́нові сини, були зайняті прино́шенням цілопа́лення та ло́ю аж до ночі, то Левити нагото́вили ї́жі собі та священикам, Ааро́новим синам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'А співаки́, Асафові сини, були на своїх місцях за нака́зом Давида, і Асафа, і Гемана, і Єдутуна, царе́вого прозорли́вця, а придве́рні були при кожній брамі, — їм не треба було відхо́дити від своїх робі́т, бо їхні брати́ Левити нагото́вили їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'I була міцно встано́влена вся Господня служба того дня, щоб спра́вити Па́сху й прине́сти цілопа́лення на Господньому же́ртвінику, за нака́зом царя Йосії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'І Ізра́їлеві сини, що знахо́дилися там, справля́ли того ча́су Па́сху та свято Опрі́сноків сім день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'І не справля́лася Па́сха, як ця, в Ізраїлі від днів пророка Самуїла, а всі Ізраїлеві царі не справляли такої, як ця Па́сха, що справив Йосія, і священики, і Левити, і ввесь Юда та Ізраїль, що знахо́дився там, та ме́шканці Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Вісімнадцятого року царюва́ння Йосі́ї справля́лася ця Па́сха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'По всьому цьому, коли Йосі́я пригото́вив дім Божий, прийшов Нехо́, цар єгипетський, щоб воювати в Каркеміші над Ефратом, а Йосія вийшов навпроти нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'І послав той до нього послів, говорячи: „Що́ мені до тебе, ца́рю Юдин? Не проти тебе прихо́джу я сьогодні, але проти дому, що воює зо мною. А Бог наказав мені спіши́ти. Не протився Богові, що зо мною, і нехай Він не знищить тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Та Йосія не відвернувся від нього, але перебрався, щоб воювати з ним, і не послухався слів Нехо, що були з Божого нака́зу, і прийшов воювати в долині Меґіддо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'І ви́стрілили стрільці́ на царя Йосію. І сказав цар до своїх рабів: „Відведіть мене, бо я си́льно ра́нений“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'І перевели́ його його раби з військової колесниці на його другий по́віз, і відве́зли його до Єрусалиму. І помер він, і був похований у гроба́х своїх батьків, а вся Юдея та Єрусалим були в жало́бі по Йосії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'І Єремія співав жало́бну пісню по Йосії. А всі співаки́ та співа́чки оповіда́ли в жало́бних своїх пісня́х про Йосію, і так є аж до сьогодні, і дали їх за уставу для Ізраїля, і ось вони написані в „Жало́бних Пісня́х“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'А решта діл Йосії та його чесно́ти, за написаним у Господнім Зако́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'і дії його перші та останні, — ото вони описані в Книзі Царів Ізраїлевих та Юдиних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 28, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 29, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 30, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 31, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'А наро́д кра́ю взяв Йоаха́за, сина Йосії, і настанови́в його царем в Єрусалимі замість ба́тька його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Йоаха́з був віку двадцяти й трьох літ, коли він зацарював, і царював в Єрусалимі три місяці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'I скинув його єгипетський цар в Єрусалимі, і наклав ка́ру на цей край, — сто талантів срібла та талант золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'І єгипетський цар настанови́в царем над Юдеєю та Єрусалимом брата його Ел\'якима, і змінив ім\'я́ йому на Єгояким. А брата його Йоахаза узяв Нехо й відвів його до Єгипту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Єгояки́м був віку двадцяти й п\'яти літ, коли він зацарював, і одина́дцять років царював в Єрусалимі. І робив він зло в оча́х Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'На нього пішов Навуходоно́сор, цар вавилонський, і він закував його в мідяні кайда́ни, щоб відве́сти його до Вавило́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'А дещо з по́суду Господнього дому Навуходоно́сор відправив до Вавилону, і дав його до храму свого в Вавилоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'А решта Єгоякимових діл та гидо́ти його, які він робив, і що зна́йдено проти нього, — ото вони описані в Книзі Царів Ізраїлевих та Юдиних. А замість нього зацарював син його Єгояхі́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Єгояхі́н був віку восьми літ, коли він зацарював, і царював в Єрусалимі три місяці й десять день. І робив він лихе́ в Господніх оча́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'А по році послав цар Навуходоно́сор, і привів його до Вавилону з дорогим по́судом Господнього дому, а царем над Юдеєю та Єрусалимом настановив брата його Седекі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Седекі́я був віку двадцяти й одно́го року, коли він зацарював, і він царював в Єрусалимі одина́дцять років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'І робив він зло в оча́х Господа, Бога свого, — не впокори́вся перед пророком Єремією, що говорив із нака́зу Господнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'І він також відкинувся від царя Навуходоно́сора, що був заприсягнув його Господом, — і вчинив твердо́ю свою шию, і став запе́клим, щоб не наверта́тися до Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Також усі зве́рхники священиків та наро́ду ще більше грішили, шануючи гидо́ти поган, і вони занечи́стили Господній дім, якого Він освятив в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'А Господь, Бог їхніх батьків, усе посилав до них через Своїх послів слова остороги, бо Він змилосе́рдився над народом Своїм та над осе́лею Своєю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Та вони соро́мили Божих послів, і пого́рджували їхніми слова́ми, і насміха́лися з Його пророків, аж поки не піднісся гнів Господа на народ Його так, що не було вже ліку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'І Він навів на них халдейського царя, і той позабива́в мече́м їхніх ви́браних у домі їхньої святині, і не змилосе́рдився ані над юнако́м, ані над ді́вчиною, ані над стари́м, ані над старе́зним, — усе дав в його руку...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'І всі речі Божого дому, вели́кі та малі́, і ска́рби дому Господнього та дому царя й його зверхників, — усе переніс до Вавилону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'І спали́ли вони Божий дім, і порозбива́ли мур Єрусалиму, і всі пала́ти його попали́ли огнем, а всі дорогі́ речі його пони́щили...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'І пішло́ на вигна́ння до Вавилону позоста́ле від меча́, і стали йому та синам його за рабів аж до зацарювання перського царства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'щоб ви́повнилося Господнє слово, проре́чене Єреміїними устами, аж поки вподо́бає собі земля свої суботи, — по всі дні її спусто́шення святкува́ла вона суботи, щоб спо́внилися сімдеся́т літ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'А першого року Кіра, царя перського, коли спо́внилось слово Господнє, проре́чене устами Єреміїними, збудив Господь духа Кі́ра, царя перського, і він оголосив по всьому царству своє́му, а також на письмі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '„Так говорить Кір, цар перський: Усі зе́мні царства дав мені Госпо́дь, Бог Небесний, і Він наклав на мене збудувати Йому храма в Єрусалимі, що в Юдеї. Хто між вами з усьо́го Його наро́ду, — нехай буде Госпо́дь, Бог його, з ним, і нехай він іде до Єрусалиму!“');
