INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'А першого року Кіра, царя перського, щоб спо́внилось слово Господнє, проре́чене устами Єреміїними, збудив Господь духа Кіра, царя перського, і він оголоси́в по всьому царству своєму, а також на письмі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, '„Так говорить Кір, цар перський: Усі зе́мні царства дав мені Господь, Бог Небесний, і Він наказав мені збудувати Йому храма в Єрусалимі, що в Юдеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Хто між вами з усього Його наро́ду, — неха́й буде Бог його з ним, і нехай він іде до Єрусалиму, що в Юдеї, і нехай будує дім Господа, Бога Ізраїлевого. Це той Бог, що в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'А кожному позоста́лому по всіх тих містах, хто мешкає там, нехай допоможуть йому люди його місця сріблом, і золотом, і маєтком, і худо́бою, з добровільною жертвою для дому Божого, що в Єрусалимі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'І повставали го́лови ба́тьківських родів Юди та Веніямина, і священики, і Левити, аж до всякого, що Бог збудив духа його, щоб піти будувати дім Господа, що в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'А все їхнє довкі́лля зміцни́ло їм руки речами срібними та золотими, маєтком, і худобою, і кошто́вностями, окрім того, що хто поже́ртвував був добровільно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'А цар Кір повино́сив речі Господнього дому, які забрав був Навуходоно́сор з Єрусалиму, і дав їх до дому бога свого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'і повиносив їх Кір, цар перський, рукою скарбника́ Мітредата, а той відрахував їх Шешбаццарові, Юдиному начальникові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'I оце їхнє число: мисо́к золотих — тридцять, мисо́к срібних тисяча, ножі́в — двадцять і дев\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'ке́ліхів золотих — тридцять, келіхів срібних подвійних — чотири сотні й десять, по́суду іншого — тисяча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Усього золотого й срібного по́суду — п\'ять тисяч і чотири сотні. Усе це завіз Шешбаццар, коли вигна́нці верта́лися з Вавило́ну до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'А оце вихо́дьки з округи, що прийшли з поло́ну вигна́ння, яких вигнав був Навуходоно́сор, цар вавило́нський, до Вавило́ну, і вони повернулися до Єрусалиму та Юдеї, кожен до міста свого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'ті, що прийшли були з Зоровавелем, Ісусом, Неємією, Сераєю, Реелаєю, Мордехаєм, Білшаном, Міспаром, Біґваєм, Рехумом, Бааною. Число людей Ізраїлевого народу:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'синів Пар\'ошових — дві тисячі сто сімдеся́т і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'синів Шефатіїних — три сотні сімдеся́т і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'синів Арахових — сім сотень сімдеся́т і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'синів Пахат-Моавових, із синів Ісусових та Йоавових — дві тисячі вісім сотень і дванадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'синів Еламових — тисяча двісті п\'ятдеся́т і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'синів Заттуєвих — дев\'ять со́тень і сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'синів Заккеєвих — сім сотень і шістдеся́т,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'синів Банієвих — шість со́тень сорок і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'синів Беваєвих — шість со́тень двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'синів Азґадових — тисяча двісті двадцять і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'синів Адонікамових — шість со́тень шістдесят і шість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'синів Біґваєвих — дві тисячі п\'ятдесят і шість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'синів Адінових — чотири сотні п\'ятдесят і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'синів Атерових, від Єзекії — дев\'ятдесят і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'синів Бецаєвих — три сотні двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'синів Йориних — сто й дванадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'синів Хашумових — двісті двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'синів Ґіббарових — дев\'ятдеся́т і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 21, 'вихо́дьків з Віфлеєму — сто двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 22, 'людей з Нетофи — п\'ятдеся́т і шість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 23, 'людей з Анатоту — сто двадцять і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 24, 'вихо́дьків з Азмавету — сорок і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 25, 'вихо́дьків з Кір\'ят-Аріму, Кефіри та Беероту — сім сотень і сорок і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 26, 'вихо́дьків з Рами та Ґеви: шість сотень двадцять і один,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 27, 'людей з Міхмасу — сто двадцять і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 28, 'людей з Бет-Елу та Аю — двісті двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 29, 'виходьків з Нево — п\'ятдесят і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 30, 'виходьків з Магбішу — сто п\'ятдесят і шість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 31, 'виходьків з Еламу Другого — тисяча двісті п\'ятдесят і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 32, 'виходьків з Харіму — три сотні й двадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 33, 'виходьків з Лоду, Хадіду та Оно — сім сотень двадцять і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 34, 'виходьків з Єрихону — три сотні сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 35, 'виходьків з Сенаї — три тисячі і шість сотень і тридцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 36, 'Священиків: синів Єдаєвих з Ісусового дому — дев\'ять сотень сімдеся́т і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 37, 'синів Іммерових — тисяча п\'ятдесят і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 38, 'синів Пашхурових — тисяча двісті сорок і сім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 39, 'синів Харімових — тисяча й сімнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 40, 'Левитів: синів Ісусових і Кадміїлових, з синів Гадавії — сімдеся́т і чотири.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 41, 'Співакі́в: синів Асафових — сто двадцять і вісім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 42, 'Синів придве́рних: синів Шаллумових, синів Атерових, синів Талмонових, синів Аккувових, синів Хатітиних, синів Шоваєвих, — усіх сто тридцять і дев\'ять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 43, 'Храмових підда́нців: синів Ціхіних, синів Хасуфіних, синів Таббаотових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 44, 'синів Керосових, синів Сіагіних, синів Падонових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 45, 'синів Леваниних, синів Хаґавиних, синів Аккувових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 46, 'синів Хаґавових, синів Самлаєвих, синів Хананових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 47, 'синів Ґідделових, синів Ґахарових, синів Реаїних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 48, 'синів Рецінових, синів Некодиних, синів Ґаззамових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 49, 'синів Уззиних, синів Пасеахових, синів Бесаєвих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 50, 'синів Асниних, синів Меунімових, синів Нефусімових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 51, 'синів Бакбукових, синів Хакуфиних, синів Хархурових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 52, 'синів Бацлутових, синів Мехідиних, синів Харшиних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 53, 'синів Баркосових, синів Сісриних, синів Темахових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 54, 'синів Незіхових, синів Хатіфиних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 55, 'синів Соломонових рабів: синів Сотаєвих, сині́в Соферетових, синів Терудиних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 56, 'Синів Яалиних, синів Дарконових, синів Ґідделових,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 57, 'синів Шефатіїних, синів Хаттілових, синів Похерет-Гаццеваїмових, синів Амієвих, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 58, 'усього цих храмових підда́нців та синів Соломо́нових рабів — три сотні дев\'ятдесят і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 59, 'А оце ті, що прийшли з Тел-Мелаху, з Тел-Харші, Керув-Аддану та Іммеру, та не могли дове́сти роду батьків своїх та свого насіння, чи вони з Ізраїля:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 60, 'синів Делаїних, синів Товійїних, синів Некодиних — шість сотень п\'ятдесят і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 61, 'І з синів священичих: сини Ховайїні, сини Коцові, сини Барзіллая, що взяв жінку з дочо́к ґілеадянина Барзіллая, і звався їхнім ім\'я́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 62, 'Вони шукали свого за́пису родоводу, та не знайшли, і були́ вони ви́лучені зо священства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 63, 'а намісник сказав їм, щоб вони не їли зо Святого Святих, аж поки не стане священик до урі́му та туммі́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 64, 'Усього збору ра́зом сорок дві тисячі три со́тні шістдесят,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 65, 'окрім їхніх рабів та невільниць, — цих було сім тисяч три сотні тридцять і сім; а їхніх співаків та співачок — двісті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 66, 'Їхніх ко́ней було сім сотень тридцять і шість, їхніх мулів — двісті сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 67, 'їхніх верблю́дів — чотири сотні тридцять і п\'ять, ослів — шість тисяч сім сотень і двадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 68, 'А з голів батьківських родів, коли вони прийшли до Господнього дому, що в Єрусалимі, то вони же́ртвували до Божого дому, щоб поставити його на його стано́вищі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 69, 'За своєю спромо́жністю вони дали́ до ска́рбу на працю: золота шістдесят одну тисячу даре́йків, а срібла — п\'ять тисяч мін, а священичих убра́нь — сто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 70, 'І осілися священики й Левити, та з народу, і співаки́, і придве́рні, і храмові підда́нці по своїх міста́х, і ввесь Ізраїль по своїх містах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'А коли настав сьо́мий місяць, і Ізраїлеві сини були по містах, то зібрався наро́д, як один чоловік, до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'І встав Ісус, син Йоцадаків, та брати його священики, і Зоровавель, син Шеалтіїлів, та брати його, і збудува́ли же́ртівника Бога Ізраїля, щоб прино́сити на ньому цілопа́лення, як написано в Зако́ні Мойсея, Божого чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'І поставили міцно же́ртівника на його основі, бо були вони в страху́ від наро́дів краї́в, і прино́сили на ньо́му цілопа́лення для Господа, цілопа́лення на ра́нок та на вечір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'І справили свято Ку́чок, як написано, і щоденні цілопа́лення в кількості за постановою щодо жертов на кожен день,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'а по то́му — цілопа́лення стале, і на молодики́, і на всі присвячені Господе́ві свята, і для кожного, хто жертвує добровільну жертву для Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Від першого дня сьомого місяця зачали́ прино́сити цілопа́лення для Господа. А під Господній храм не були ще покладені основи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'І дали́ срібла каменяра́м та те́слям, і їжі, і питва́ та оливи, сидонянам та тирянам, щоб достача́ли ке́дрові дере́ва з Ливану до Яфського моря за до́зволом їм Кіра, царя перського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'А другого року по своєму прихо́ді до Божого дому до Єрусалиму, дру́гого місяця, почали́ робити Зоровавель, син Шеалтіїлів, і Ісус, син Йоцадаків, і решта їхніх братів, священики та Левити, і всі, хто поприхо́див з неволі в Єрусалим, а Левитів від віку двадцяти років і вище поставили керува́ти над працею Господнього дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'І став Ісус, сини його та брати його, Кадміїл та сини його, сини Юдині, як один чоловік, на до́гляд над робітника́ми праці в Божому домі, сини Хенададові, сини їх та їхні брати, Левити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'А коли клали осно́ву Господнього храму, то поставили облаче́нних священиків із су́рмами, а Левитів, Асафових синів, із цимба́лами, щоб сла́вити Господа за уставом Давида, Ізраїлевого царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'І відповіли вони хвало́ю та подякою Господе́ві, — „Добрий бо Він, бо навіки Його милосердя“на Ізраїля. А ввесь народ викли́кував гучни́м по́кликом, сла́влячи Господа за основу Господнього дому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'А багато-хто зо священиків і Левитів та з голів ба́тьківських родів, старші, що бачили перший храм, при заснува́нні його, того храму, своїми очи́ма, плакали ре́вним голосом, а багато-хто покли́кували підне́сеним голосом у радості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'І не міг наро́д розпізнати голосу по́клику радости від голосу плачу́ народу, бо наро́д сильно викли́кував, а голос був чутий аж далеко.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'І почули Юдині та Веніяминові вороги́, що вигна́нці будують храма Господе́ві, Богові Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'І прийшли вони до Зорова́веля та до голів ба́тьківських родів, та й сказали їм: І ми бу́демо будува́ти з вами, бо ми зверта́ємось, як ви, до вашого Бога, і ми прино́симо Йому жертви від днів Есар-Хаддона, царя асирійського, що привів нас сюди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'І сказав їм Зоровавель і Ісус, та решта голів батьківських родів Ізраїлевих: „Не вам і нам разом будувати храм для Бога! Самі бо ми бу́демо будувати для Господа, Бога Ізраїлевого, як наказа́в нам цар Кір, цар перський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'І став народ тієї землі осла́блювати руки Юдиного наро́ду та страха́ти їх при будува́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'І підку́плювали вони проти них дора́дників царськи́х, щоб залама́ти їхній за́дум, по всі дні Кіра, царя перського, й аж до царюва́ння Да́рія, царя перського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'А за царя Ахашвероша, на поча́тку його царюва́ння, написали вони оска́рження на ме́шканців Юдеї та Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'А за днів Артаксеркса написав Бішлам, Мітредат, Товеїл та решта товаришів його до Артаксеркса, царя перського. А лист був написаний по-араме́йськи, а перекладений по-перськи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Начальник Рехум та писар Шімай написали одно́го листа проти Єрусалиму до царя Артаксеркса отак.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Тоді начальник Рехум та писар Шімшай та решта товариші́в його, судді й урядники, писарчуки, писарі, аркев\'я́ни, вавило́няни, шушаня́ни, цебто еламі́ти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'та решта наро́дів, яких повиганяв Аснаппар, великий та славний, й осадив їх у місті Самарії та в решті Заріччя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Оце ві́дпис листа, що послали до нього: „До царя Артаксеркса твої раби, люди Зарі́ччя. І ось');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'щоб було відо́ме цареві, що Юдеї, які вийшли від тебе до нас, прибули́ до Єрусалиму. Вони будують місто бунтівни́че та шкідли́ве, і вдоскона́люють мури, а підва́лини поліпши́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'А тепер щоб було відо́ме цареві, що коли тільки це місто буде збудо́ване, а мури закі́нчаться, вони не будуть давати ані дани́ни, ані пода́тку, ані мита, а це буде шкодити царсько́му прибу́ткові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'І ото, беручи́ на увагу, що сіль царського пала́цу — сіль наша, а царськи́й сором не випадає нам бачити, тому ми посилаємо й завідомля́ємо царя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'щоб пошукали в книзі споминів батьків твоїх, і ти зна́йдеш у книзі споминів, і знатимеш, що місто це — місто бунтівни́че та шкідли́ве царям та окру́гам, і що в ньому підійма́ли бунт від праві́ку, чому́ місто це було зруйно́ване.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Ми сповіщаємо царя, що коли тільки місто це буде добудо́ване, а мури закі́нчаться, то через те не бу́де тобі частки в Зарі́ччі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Цар послав відповідь: „Начальникові Рехумові, і писареві Шімшаєві, та решті їхніх товаришів, що сидять у Самарії, і решта Заріччя: Мир вам! А тепер, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'лист, якого ви послали до нас, вира́зно прочи́таний передо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'І був ви́даний від мене нака́з, і шукали та й знайшли, що місто це з да́вніх-даве́н підійма́лося на царів, і повста́ння та бунт робилися в ньо́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'І могу́тні царі були́ над Єрусалимом, і панували в усьо́му Зарі́ччі, а дани́на, пода́ток та мито давалися їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'А тепер видайте нака́за, щоб спини́лися ці люди, а місто це не будува́лося, поки від мене не буде ви́даний новий нака́з.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'І будьте бе́режні, щоб через це не зробити по́милки. На́що рости́ме зло на шкоду царям?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Тоді, як тільки був прочи́таний ві́дпис листа царя Артаксеркса перед Рехумом і писарем Шімшаєм та їхніми товариша́ми, пішли вони поспішно до Єрусалиму, і спини́ли роботу їх зброєю та насиллям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 24, 'Тим спинилася робота Божого дому, що в Єрусалимі, і спини́лася вона аж до другого року царюва́ння Дарія, царя перського...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'І пророкува́в пророк Огій та Заха́рій, син Іддо, пророки, на юдеїв, що в Юдеї та в Єрусалимі, в Ім\'я́ Бога Ізраїля, що над ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Тоді встали Зоровавель, син Шеалтіїлів, та Ісус, син Йоцадаків, і зачали́ будувати Божий дім, що в Єрусалимі, а з ними Божі пророки, що допомагали їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Того ча́су прийшов до них Таттенай, намі́сник Зарі́ччя, і Шетар-Бозенай та їхні товариші́, і сказали їм так: „Хто́ видав вам нака́за будувати цей храм і кінча́ти цю будову?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Тоді ми сказали їм імена́ тих мужів, що будують цього будинка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Та око їхнього Бога було на юдейських старши́х, і вони не спинили їх, аж поки не пі́де доне́сення до Дарія, і тоді дадуть писе́мну відповідь про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Ось ві́дпис листа, що послав Таттенай, намісник Зарі́ччя, і Шетар-Бозенай, та товари́ство його, і перси, що в Заріччі, до царя Дарія, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'вони послали йому доне́сення, а в ньому писано так: „Цареві Дарієві — усякого миру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Щоб було відо́ме цареві, що ми ходили до Юдейської окру́ги, до дому великого Бога, а він будується з великого ка́меня, і дерево кладеться в стіни. А робота та робиться докла́дно, і у́спіх у їхній руці́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Тоді ми питалися тих старши́х, і сказали їм так: Хто видав вам нака́за будувати цей храм і кінча́ти цю святиню?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'А також питалися ми їх про їхні імена́, щоб повідо́мити тебе, що запишемо ім\'я́ тих мужів, які за голову в них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'А вони так відповіли нам та сказали: Ми — то раби Бога небе́с та землі, і будуємо храма, що був збудований за багато літ перед цим, а збудував його й докінчи́в його великий Ізра́їлів цар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Але зго́дом, коли наші батьки́ розгніви́ли були Бога небе́с, Він віддав їх у руку Навуходоно́сора, царя вавило́нського, халдея, а храм той — він зруйнува́в його, а наро́д вигнав до Вавилону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Але першого року Кіра, царя вавилонського, цар Кір видав нака́за будувати цей дім Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'А також по́суд Божого дому, золотий та срібний, що Навуходоно́сор був виніс із єрусалимського храму й заніс його до храму вавилонського, виніс його цар Кір із вавилонського храму й дав мужеві, ім\'я́ його Шешбаццар, якого він настанови́в намі́сником.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'І сказав він йому: Візьми цей по́суд, іди, віднеси́ його до храму, що в Єрусалимі, а дім Божий нехай буду́ється на своєму місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Тоді той Шешбаццар прийшов, заклав підва́лини Божого дому в Єрусалимі, і відтоді́ й аж до цього ча́су він будується, і не скі́нчений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'І ось, якщо це цареві добре, нехай пошука́ється в домі царськи́х скарбів там, у Вавилоні, чи справді від царя Кіра ви́даний був нака́з будувати цей Божий дім в Єрусалимі, а царську́ волю про це нехай пошлють до нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Тоді цар Да́рій видав нака́за, і шукали в домі, де складають ска́рби книжо́к у Вавилоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'І був зна́йдений один звій в за́мку Ахметі, що в мідійській окру́зі, а в ньому написано так: „ На пам\'ять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Першого року царя Кіра цар Кір видав наказа: Дім Божий в Єрусалимі — дім той нехай будується на місці, де прино́сять жертви, а його підва́лини зало́жені. Вишина́ його — шістдеся́т ліктів, ширина́ його — шістдеся́т ліктів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Три ряди́ з великого ка́меню, й один ряд з дерева, а вида́тки будуть да́ні з царсько́го дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'А по́суд Божого дому, золотий та срібний, що Навуходоно́сор виніс був із храму, що в Єрусалимі, і переніс до Вавилону, нехай пове́рнуть, і нехай він пі́де до храму, що в Єрусалимі, на своє місце, і покладе́ш те в Божому домі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, '„Тепер же ти, Таттенаю, наміснику Заріччя, ти, Шетор-Бозенаю з товаришами своїми, перси, що в Заріччі, — віддалі́ться звідти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Позоставте працю цього Божого дому, — юдейський намісник та юдейські старші́ збудують той Божий дім на його місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'А від мене да́ний нака́з про те, що́ ви будете робити з тими юдейськими старши́ми, щоб збудувати цей Божий дім, а з царсько́го добра́, з данини Заріччя, нехай докладно дається вида́ток тим лю́дям, щоб не спиняти роботи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'А що́ буде потрібне, чи телят, чи баранів, чи овечок на прине́сення Небе́сному Бо́гові, пшеницю, сіль, вино та оливу, що скажуть священики, які в Єрусалимі, щоб без ома́ни видавалося їм день-удень,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'щоб вони за́вжди прино́сили па́хощі в жертву Небесному Богові та молилися за життя царя та синів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'А від мене ви́даний нака́з, що коли який чоловік змінить це моє слово, то буде ви́рване дерево з дому його, і буде поста́влене, а він бу́де прибитий на ньому, а дім його буде обе́рнений за це в руїну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'А Бог, що вчинив, щоб там пробува́ло Ім\'я́ Його, знищить кожного царя та наро́д, що простя́гне свою руку, щоб змінити це, щоб ушко́дити той Божий дім, що в Єрусалимі! Я, Да́рій, видав цього нака́за, — нехай він докладно буде ви́конаний!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Тоді Таттенай, намісник Заріччя, Шетар-Бозенай та їхні товариші́ докладно зробили згідно з тим, як послав цар Да́рій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'А юдейські старші́ будували, і щастило їм за проро́цтвом пророка Огія та Захарія, сина Іддо. І вони збудували й закінчи́ли з нака́зу Бога Ізраїлевого та з наказу Кіра, і Дарія, і Артаксеркса, царя перського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'І закі́нчений був цей храм до третього місяця адара, що він місяць дванадцятий, шостого року царюва́ння царя Дарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'І справили Ізраїлеві сини, священики й Левити та решта вигна́нців свято відно́влення того Божого дому а радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'I прине́сли в жертву на свято відно́влення того Божого дому: волів — сотню, баранів — двісті, ягнят — чотири сотні, а козлят у жертву за гріх за всього Ізраїля — дванадцять, за числом Ізраїлевих племе́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'І поставили священиків за їхніми частинами, а Левитів — за че́ргами їхніми на службу Божого дому, що в Єрусалимі, як написано в книзі Мойсея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'А пове́рненці справили Па́сху чотирнадцятого дня першого місяця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 20, 'бо очи́стилися священики та Левити, як один, — усі вони чисті. І вони зарізали пасха́льне ягня́ для всіх пове́рненців, для своїх братів священиків та для себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 21, 'І їли Ізраїлеві сини, що верну́лися з вигна́ння, і також усі, хто відділився до них від иечистости народів землі, щоб звертатися до Господа, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 22, 'І справляли вони свято Опрі́сноків сім день у радості, бо Господь їх потішив і обернув до них серце асирійського царя, щоб зміцнити їхні руки при праці дому Бога, Бога Ізраїлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'А по цих приго́дах, за царюва́ння Артаксеркса, царя перського, Е́здра, син Азарії, сина Хійлкійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'сина Шаллуна, сина Садока, сина Ахітуви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'сина Амарії, сина Азарії, сина Мерайота,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'сина Захарія, сина Уззі, сина Буккі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'сина Авішуї, сина Пінхаса, сина Елеазара, сина Аарона, первосвященика, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'цей Ездра вийшов із Вавилону, а він був учитель, знаве́ць Мойсеєвого Зако́ну, що його дав Господь, Бог Ізраїлів. І дав йому цар згідно з тим, як була́ на ньому рука Господа, Бога його, всяке його пожада́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'І пішли з ним дехто з Ізраїлевих синів, і з священиків, і Левитів, і співаків, і придве́рних, і храмови́х підда́нців до Єрусалиму сьомого року царя Артаксе́ркса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'І прибув він до Єрусалиму п\'ятого місяця, а то сьомий рік царюва́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Бо першого дня місяця першого був поча́ток ви́ходу з Вавилону, а першого дня п\'ятого місяця він прийшов до Єрусалиму, бо рука його Бога була добра на ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Бо Ездра пригото́вив своє серце дослі́джувати Господнього Зако́на, і виконувати його, і навчати в Ізраїлі устава та права.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'А оце ві́дпис писа́ння, що цар Артаксе́ркс дав священикові Ездрі, учителеві, що пише слова́ заповідей Господа та Його устави над Ізраїлем:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, '„Артаксе́ркс, цар над царями, до священика Ездри, доскона́лого вчителя Зако́ну Бога Небесного, і так далі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'А ось ви́даний від мене нака́з, щоб кожен, хто в моїм царстві з Ізраїлевого наро́ду, і їхніх священиків, і Левитів з доброї волі бажає йти до Єрусалиму з тобою, нехай іде,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'через те, що ти по́сланий від царя та семи його дора́дників, щоб дослідити про Юдею та про Єрусалим за правом твого Бога, правом, що в руці твоїй,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'і щоб відпра́вити срібло та золото, що цар та дорадники його поже́ртвували для Бога Ізраїлевого, Якого місце перебування в Єрусалимі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'і все срібло та золото, яке ти зна́йдеш у всій вавилонській окру́зі ра́зом із пожертвами народу та священиків, які же́ртвують для дому їхнього Бога, що в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Тому́ ти невідкладно купиш за це срібло биків, баранів, овечок, і їх жертви хлі́бні та їх жертви ливні, і принесе́ш їх на же́ртівнику дому вашого Бога, що в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'А що тобі та браттям твоїм буде добре вчинити з рештою срібла та золота, те зробі́ть за вподо́банням вашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'А по́суд, що даний тобі на слу́ження дому твого Бога, віддай у цілості перед Богом Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'А решта потрібного для дому Бога твого, що випаде тобі дати, буде да́на з дому царськи́х скарбів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'А від мене — я цар Артаксеркс — ви́даний нака́з для всіх скарбникі́в, що в Заріччі, що все, чого зажадає від вас священик Ездра, учитель Зако́ну Бога Небесного, нехай буде докладно зро́блене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'срібла — аж до сотні тала́нтів, і пшениці аж до сотні ко́рів, і вина аж до сотні ба́тів, і оливи аж до сотні батів, а соли — без за́пису.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Усе, що з нака́зу Небесного Бога, нехай буде горливо зро́блене для дому Небесного Бога, бо на́що був би гнів на царство царя та на синів його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'І вас завідомля́ємо, що всі священики та Левити, співаки́, придве́рні, храмові́ підда́нці та працівники того Божого дому вільні, — дани́ни, пода́тку, чи ми́та не належить накладати на них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'А ти, Ездро, за мудрістю Бога твого, яка в руці твоїй, попризнача́й су́ддів та викона́вців Зако́ну, щоб судили для всього народу, що в Заріччі, для всіх, хто знає зако́ни твого Бога, а хто не знає, тих навчите́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'А кожен, хто не буде виконувати Зако́на твого Бога та зако́на царсько́го докладно, щоб чинився над ним суд: чи то на смерть, чи то на вигна́ння, чи то на кару маєткову, чи то на ув\'я́знення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Благословенний Господь, Бог наших батьків, що вклав у царе́ве серце, щоб оздо́бити дім Господній, що в Єрусалимі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'а на мене нахили́в милість перед царем та його дора́дниками, та всіма́ хоробрими царе́вими зве́рхниками! А я зміцни́вся, бо рука Господа, Бога, була надо мною, і я зібрав провідни́х людей з Ізраїля, щоб вони пішли зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'А оце го́лови їхніх батьків та їх родові́д, що пішли зо мною, за царю́вання царя Артаксе́ркса, з Вавилону:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'з Пінхасових синів: Ґершом, з Ітамарових синів: Даніїл, з Давидових синів: Хаттуш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'З Шеханіїних синів, з Пар\'ошових синів: Захарій, а з ним за родово́дом — сто й п\'ятдеся́т мужчи́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'З Пахат-Моавових синів: Ел\'єгоенай, син Зерахі́їн, а з ним двісті мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'З синів Затту: Шеханія, син Яхазіїлів, а з ним три сотні мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'А з Адінових синів: Евед, син Йонатанів, а з ним п\'ятдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'А з Еламових синів: Єшая, син Аталіїн, а з ним сімдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'А з Шефатіїних синів: Зевадія, син Михаїлів, а з ним вісімдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'З Йоавових синів: Овадія, син Єгіїлів, а з ним двісті й вісімнадцять мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'А з синів Бані: Шеломіт, син Йосіфіїн, а з ним сотня й шістдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'А з Беваєвих синів: Захарій, син Беваїв, а з ним двадцять і вісім мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'А з Азґадових синів: Йоханан, син Катанів, а з ним сотня й десять мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'А з Адонікамових синів — останні, а оце їхні імена́: Еліфелет, Єіїл, і Шемая, а з ними шістдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'А з Біґваєвих синів: Утай і Заввуд, а з ними сімдеся́т мужчин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'І зібрав я їх до рі́чки, що впадає до Агави, і ми таборува́ли там три дні. І перегля́нув я народ та священиків, і не знайшов там ніко́го з Левієвих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'І послав я по Еліезера, по Аріїла, по Шемаю, по Елнатана, і по Яріва, і по Елнатана, і по Натана, і по Захарія, і по Мешуллама, голів, і по Йойаріва, і по Елнатана, учителів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'І відправив я їх до Іддо, голови в місцевості Касіф\'я, і вклав в їхні уста слова́, щоб говорити до Іддо та братів його, підда́них у місцевості Касіф\'я, щоб вони привели́ нам служи́телів для дому нашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'I привели́ вони нам, — бо рука нашого Бога була добра до нас, — чоловіка розумного з синів Махлі, сина Левія, Ізраїлевого сина, та Шеревею й синів його та братів його, — вісімнадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 19, 'та Хашавію, а з ним Єшаю, з синів Мерарієвих, братів його та синів його — двадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 20, 'а з підда́нців храму, яких дав Давид та зверхники на роботу Левитам, — двісті й двадцять підда́нців: усі вони були́ озна́чені поіме́нно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 21, 'І проголосив я там піст, над річкою Агавою, щоб упокоря́тися нам перед лице́м нашого Бога, щоб просити від Нього щасливої дороги для нас і для дітей наших та для всього нашого маєтку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 22, 'бо я соро́мився просити від царя ві́йська та верхівці́в, щоб помагали нам у дорозі проти ворога, бо сказали ми цареві, говорячи: „Рука нашого Бога на добро для всіх, хто шукає Його, а сила Його та гнів Його — на всіх, хто кидає Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 23, 'І по́стили ми, і просили нашого Бога про це, і Він дав нам ублага́ти Себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 24, 'І я відділив із священичих зверхників дванадцять до Шеревеї, Хашавії, і до десятьо́х їхніх братів з ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 25, 'І відва́жив я їм срібло й золото та по́суд прине́сення нашого Божого дому, що прине́сли цар, і його дорадники, і його зверхники та ввесь Ізраїль, що знахо́дився там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 26, 'І відважив я на їхню руку шість сотень і п\'ятдеся́т тала́нтів срібла, а срібних речей — сто талантів, золота — сто талантів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 27, 'а золотих чаш — двадцять на тисячу даре́йків, а посу́дин з золо́ченої й доброї міді — дві, дорогі́, як золото.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 28, 'І сказав я до них: „Ви святість для Господа, і цей по́суд — святість, а те срібло та золото — добровільна жертва для Господа, Бога ваших батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 29, 'Пильнуйте й бережіть це, аж поки не відва́жите його перед зверхниками священиків і Левитів та зверхниками ба́тьківських родів Ізраїлевих в Єрусалимі до кімна́т Господнього дому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 30, 'І прийняли́ священики та Левити вагу того срібла та золота та того по́суду, щоб відне́сти до Єрусалиму, до дому нашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 31, 'І рушили ми з річки Агави двадцятого дня першого місяця, щоб іти до Єрусалиму. А рука нашого Бога була над нами, і Він урятував нас з руки ворога та чатівника́ на дорозі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 32, 'І прийшли ми до Єрусалиму, і сиділи там три дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 33, 'А четвертого дня відважили ми те срібло й золото та той по́суд у домі нашого Бога на руку священика Меремота, сина Урійїного, а з ним був Елеазар, син Пінхасів, а з ними Йозавад, син Єшуїн, та Ноадія, син Біннуїв, Левити, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 34, 'за числом, за вагою на все. І того ча́су була́ записана вся та вага.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 35, 'Ті, що прийшли з поло́ну, сини вигнання, прине́сли цілопа́лення для Бога Ізраїля: дванадцять биків за всього Ізраїля, дев\'ятдеся́т і шість баранів, сімдеся́т і сім овець, дванадцять козлів на жертву за гріх, — це все цілопа́лення для Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 36, 'І віддали́ цареві нака́зи царськи́м сатра́пам та намісникам Зарі́ччя, а ті підтримували наро́д та Божий дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'А як скінчи́лося це, підійшли до мене зверхники, говорячи: „Цей народ, Ізраїль, і священики та Левити не відділи́лися від народів цих країв з їхніми гидо́тами, від ханане́ян, періззе́ян, євусе́ян, аммоне́ян, моаві́тян, єги́птян та аморе́ян,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'бо побрали з їхніх дочо́к собі та своїм сина́м, змішалося святе насіння з наро́дами цих країв, а рука зве́рхників та предста́вників була́ перша в цьому спроневі́ренні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'А коли я почув це слово, то розде́р я одежу свою та плаща́ свого, і рвав воло́сся з голови своєї та з бороди своєї, і сидів остовпі́лий...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'І зібра́лися до ме́не всі тремтя́чі перед словами Бога Ізраїлевого за спроневі́рення пове́рненців, а я сидів остовпі́лий аж до жертви вечірньої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'А за вечірньої жертви встав я з упоко́рення свого, і, роздерши шату свою та плаща́ свого, упав я на коліна свої, і простягну́в ру́ки свої до Господа, Бога мого...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'І сказав я: „Боже мій, соро́млюся я та стидаюся підне́сти, Боже мій, обличчя своє до Те́бе, бо беззако́ння наші помно́жилися понад голову, а наша провина виросла аж до неба!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Від днів наших батьків ми в великій провині аж до дня цього, а за наші беззако́ння були́ ві́ддані ми, наші царі, наші священики в руку царів цих краї́в на меча́, на поло́н, і на грабі́ж, і на посоро́млення обличчя, як цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'А тепер на малу́ хвилю ста́лася нам милість від Господа, Бога нашого, щоб позоста́вити нам оста́нок, і дати нам затверди́тися на місці святині Його, щоб освітити очі наші, Боже наш, і дати нам трохи ожити в нашій неволі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Бо раби ми, та в нашій неволі не покинув нас Бог наш, і прихилив до нас милість перед пе́рськими царями, щоб дати нам ожити, щоб підне́сти дім нашого Бога й щоб відбудува́ти руїни його, та щоб дати нам за́хист в Юдеї та в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'А тепер що ска́жемо, Боже наш, по цьо́му? Бо ми поки́нули заповіді Твої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'які Ти наказа́в через Своїх рабів пророків, говорячи: Цей Край, що ви йдете посісти, він край нечистий через нечистість наро́ду цих країв, через їхні гидо́ти, що напо́внили його від кра́ю до кра́ю своєю нечи́стістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'А тепер дочо́к своїх не давайте їхнім синам, а їхніх дочо́к не беріть для своїх синів, і не питайте їх про мир та про добро їх аж навіки, щоб ви стали сильні, та спожива́ли добро цієї землі, і віддали́ на спа́док вашим синам аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'А по то́му всьому, що прийшло на нас за наші злі чи́ни та за нашу велику провину, — бо Ти, Боже наш, стримав кару більше від гріха́ нашого, і дав нам таку рештку, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'чи зно́ву ми лама́тимемо заповіді Твої, і бу́демо посвоя́чуватися з оцими мерзо́тними наро́дами? Чи ж Ти не розгні́ваєшся на нас аж до ви́гублення нас, так що ніхто не позоста́вси б і не врятува́вся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Господи, Боже Ізраїлів, Ти праведний, бо ми позоста́лися останком, як цього дня. Ось ми в провині своїй перед лицем Твоїм, бо не всто́яти нам за це перед лицем Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'А коли Ездра молився та сповіда́вся, плакав та припада́в перед Божим домом, зібрався до нього з Ізраїля дуже великий збір, — чолові́ки, і жінки́ та діти, бо наро́д плакав ре́вним плаче́м...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'І відпові́в Шеханія, Єхіїлів син, з Еламових синів, та й сказав до Ездри: „Ми спроневі́рилися нашому Богові, бо взяли ми чужи́нок із наро́дів цього кра́ю за жіно́к. Але є ще наді́я для Ізраїля в цьо́му!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'А тепер складімо заповіта нашому Богові, що випровадимо від себе всіх жінок та наро́джене від них, за радою пана нашого, та тих, хто тремти́ть перед заповіддю нашого Бога, і буде зро́блене за Зако́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Устань, бо на тобі ця річ, а ми з тобою. Будь му́жній і дій!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'І встав Ездра, і заприсяг зверхників, священиків і Левитів та всього Ізраїля, щоб робити за цим словом. І вони заприсягли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'І Ездра встав з-перед Божого дому й пішов до кімна́ти Єгохонана, Ел\'яшівового сина, і ночував там. Хліба він не їв і води не пив, бо був у жало́бі за спроневі́рення пове́рненців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'І оголоси́ли в Юдеї та в Єрусалимі до всіх пове́рненців, щоб зібратися до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'А кожен, хто не при́йде до трьох день, за порадою зверхників та старши́х, — увесь маєток того буде зро́блений закляттям, а він буде ви́лучений із громади пове́рненців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'І зібралися всі люди Юди та Веніямина до Єрусалиму до трьох день, — це був дев\'ятий місяць, двадцятого дня місяця. І сидів увесь народ на площі Божого дому, тремтячи́ від цієї справи та від дощу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'І встав священик Ездра та й сказав до них: „Ви спроневі́рилися, і взяли чужи́нних жінок, щоб побільши́ти Ізраїлеву прови́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'А тепер повині́ться Господе́ві, Богові ваших батьків, і чиніть Його волю! І віддаліться від наро́дів цього кра́ю та від тих чужих жіно́к!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'І відповіла́ вся громада, і сказали гучним голосом: „Так, за словом твоїм, ми повинні зробити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Але наро́д числе́нний, і час дощів, і нема сили стояти на вулиці. Та й праці не на один день і не на два, бо ми багато нагрішили в цій справі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Нехай же стануть наші зверхники за ввесь збір, а кожен, хто є в наших містах, хто взяв чужи́нних жіно́к, нехай при́йде на означені часи́, а з ними старші́ кожного міста та су́дді його, аж поки не відве́рнеться від нас жар гніву нашого Бога за цю річ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Особливо стали над цим Йонатан, син Асагелів, та Яхзея, син Тіквин, а Мешуллам та Левит Шеббетай допомагали їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'І зробили так пове́рненні. І відділи́в собі священик Ездра людей, голів батьків за родом їхніх батьків, і всі вони поіме́нно. І сіли вони першого дня десятого місяця, щоб дослідити цю справу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'І скінчи́ли до першого дня першого місяця справи про всіх тих людей, що взяли були чужи́нних жіно́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'І знайшлися поміж священичими синами, що взяли́ чужи́нних жіно́к, із синів Єшуї, сина Йоцадакового, та братів його: Моасея, і Еліезер, і Ярів, і Ґедалія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'І дали́ вони руку свою, що повипрова́джують жіно́к своїх, а винні прине́сли в жертву барана́ з отари за прови́ну свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'А з синів Іммерових: Ханані та Зевадія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'І з синів Харімових: Массея, і Елійя, і Шемая, і Єхіїл, і Уззійя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Із синів Пашхурових: Ел\'йоенай, Маасея, Ізмаїл, Натанаїл, Йозавад та Ел\'аса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'А з Левитів: Йозавад, і Шім\'ї, і Келая, він Келіта, Петахія, Юда та Еліезер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'А з співакі́в: Ел\'яшів. А з придве́рних: Шаллум, і Телем, та Урі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'А з Ізраїля, з синів Пар\'ошових: Рам\'я, і Їззійя, і Малкійя, і Мійямін, і Елеазар, і Малкійя та Беная.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'А з синів Еламових: Маттанія, Захарій, і Єхіїл, і Авді, і Єремот, і Елійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'І з синів Затту: Ел\'йоенай, Ел\'яшів, Маттанія, і Еремот, і Завад та Азіза.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'А з синів Беваєвих: Єгоханан, Хананія, Заббай, Атлай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'І з синів Банієвих: Мешуллам, Маллух, і Адая, Яшув, і Шеал та Рамот.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'І з синів Пахатових: Моав, Адна, і Хелал, Беная, Маасея, Маттанія, Веселії́л, і Біннуй та Манасія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'І з синів Харімових: Еліезер, Їшшійя, Малкійя, Шемая, Шімон,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Веніямин, Маллух, Шемарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'З синів Хашумових: Маттенай, Маттатта, Завад, Еліфелет, Єремай, Манасія, Шім\'ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'З синів Банаєвих: Маадай, Амрам, і Уїл,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Беная, Бедея, Келугу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Ванія, Меремот, Ел\'ятів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Маттанія, Маттенай, і Яасай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'і Бані, і Бійнуй, Шім\'ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'і Шелемія, і Натан, і Адая,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Махнадвай, Шашай, Шарай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 41, 'Азаріїл, і Шелемія, Шемарія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 42, 'Шаллум, Амарія, Йо́сип.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 43, 'А з синів Нево: Єіїл, Маттітія, Завад, Зевіна, Яддай, і Йоїл, Беная.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 44, 'Усі оці взяли́ були́ чужи́нних жіно́к, а деякі з цих жіно́к і дітей породили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Слова́ Неемі́ї, Гахаліїного сина: „І сталося в місяці кіслеві двадцятого року, і був я в за́мку Шуша́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'І прийшов Ханані, один із братів моїх, він та люди з Юдеї. І запитався я їх про юдеїв, що врятува́лися, що позостали від поло́ну, та про Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'А вони сказали мені: „Позосталі, що лишилися з полону, там в окрузі, живуть у великій біді та в га́ньбі, а мур Єрусалиму поруйно́ваний, а брами його попа́лені огнем“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'І сталося, як почув я ці слова́, сів я та й плакав, і був у жало́бі кілька днів, і по́стив, і молився перед лицем Небесного Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'I сказав я: „Молю Тебе, Господи, Боже Небесний, Боже великий та грізни́й, що дотри́муєш заповіта та милість для тих, хто любить Тебе та дотримуєш заповіді Свої, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'нехай же буде ухо Твоє чутке́, а очі Твої відкриті, щоб прислу́хуватися до молитви раба Твого, якою я молюся сьогодні перед Твоїм лицем день та ніч за Ізраїлевих синів, Твоїх рабів, і сповіда́юся в гріха́х Ізраїлевих синів, якими грішили ми проти Тебе, — і я і дім батька мого грішили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Ми сильно провинилися перед Тобою, і не дотримували заповідей, і уставів, і прав, які наказав Ти Мойсеєві, рабові Своєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Пам\'ятай же те слово, що Ти наказав був Мойсеєві, Своє́му рабові, говорячи: як ви спроневі́ритеся, — Я розпоро́шу вас поміж наро́дами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Та коли наве́рнетеся до Мене, і будете дотримувати заповіді Мої й виконувати їх, то якщо будуть ваші вигна́нці на краю небес, — то й звідти позбираю їх, і приведу́ до того місця, яке Я вибрав, щоб там перебувало Ім\'я́ Моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'А вони — раби Твої та народ Твій, якого Ти викупив Своєю великою силою та міцною Своєю рукою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Молю Тебе, Господи, нехай же буде ухо Твоє чутке́ до молитви Твойого раба та до молитви Твоїх рабів, що пра́гнуть боятися Ймення Твого! І дай же сьогодні успіху Своєму рабові, і дай знайти милосердя перед оцим мужем!“А я був ча́шником царевим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'І сталося в місяці ніса́ні, двадцятого року царя Артаксе́ркса, було раз вино перед ним. І взяв я те вино й дав цареві. І я, здавалося, не був сумни́й перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Та сказав мені цар: „Чому́ обличчя твоє сумне́, — чи ти не хворий? Це не інше що, як тільки сум серця“. І я ве́льми сильно злякався!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'І сказав я до царя: „Нехай цар живе навіки! Чому́ не буде сумне́ обличчя моє, коли місто дому гробі́в батьків моїх поруйноване, а брами його попа́лені огнем!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'І сказав мені цар: „Чого ж ти просиш?“І я помолився до Небесного Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'і сказав цареві: Якщо це цареві вгодне, і якщо раб твій уподо́баний перед обличчям твоїм, то пошли мене до Юдеї, до міста гробі́в батьків моїх, — і я відбуду́ю його“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'І сказав мені цар (а цариця сиділа при ньо́му): „Скільки ча́су буде дорога твоя, і коли ти пове́рнешся?“І сподо́балось це цареві, і він послав мене, а я призна́чив йому час.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'І сказав я цареві: „Якщо це цареві вгодне, нехай дадуть мені листи́ до намісників Зарі́ччя, щоб прова́дили мене, аж поки не прийду́ до Юдеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'і листа до Асафа, дозо́рця царевого лісу, щоб дав мені де́рева на бру́сся для замко́вих брам, що належать до Божого дому, і для місько́го муру, і для дому, що до нього ввійду́“. І дав мені цар в міру того, як добра була Божа рука надо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'І прибув я до намісників Заріччя, і дав їм цареві листи́. А цар послав зо мною зверхників ві́йська та верхівці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'І почув про це хоронянин Санваллат та раб аммоні́тянин Товія, і було їм прикро, дуже прикро, що прийшов чоловік клопота́тися про добро для Ізраїлевих синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'І прийшов я до Єрусалиму, і був там три дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'І встав я вночі, я та трохи людей зо мною, і не розповів я ніко́му, що Бог мій дав до мого серця зробити для Єрусалиму. А худоби не було зо мною, окрім тієї худоби, що я нею їздив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'І вийшов я Долинною брамою вночі, і пішов до джерела́ Таннін, і до брами Смітникової. І я докладно огля́нув мури Єрусалиму, що були́ поруйно́вані,а брами його були попа́лені огнем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'І перейшов я до Джерельної брами та до царсько́го ставу, та там не було місця для перехо́ду худоби, що була́ підо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'І йшов я долиною вночі, і докладно оглядав мура. Потім я вернувся, і ввійшов Долинною брамою, і вернувся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'А заступники не знали, куди я пішов та що́ я роблю́, а юдеям, і священикам, і шляхті, і заступникам, і решті тих, що робили працю, я доти нічо́го не розповіда́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'I сказав я до них: „Ви бачите біду́, що ми в ній, що Єрусалим зруйно́ваний, а бра́ми його попа́лені огнем. Ідіть, і збудуйте мура Єрусалиму, і вже не бу́демо ми га́ньбою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'І розповів я їм про руку Бога мого, що вона добра до мене, а також слова царя, які сказав він мені. І сказали вони: „Станемо й збудуємо!“І зміцнили вони руки свої на добре ді́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'І почув це хоронянин Санваллат та аммоні́тянин раб Товія, і араб Ґешем, і сміялися з нас, і пого́рджували нами й говорили: „Що це за річ, яку ви робите? Чи проти царя ви бунтуєтесь?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'А я їм відповів і сказав до них: „Небесний Бог — Він дасть нам у́спіх, а ми, Його раби, станемо й збудуємо! А вам нема ані частки, ані права, ані пам\'ятки в Єрусалимі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'І встав Еліяші́в, первосвященик, та брати його священики, і збудували Овечу браму. Вони освятили її, і повставля́ли її двері, й аж до башти Меа освятили її, аж до башти Ханан\'їла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'А поруч нього будували єрихо́няни, а поруч них будував Заккур, син Імріїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'А браму Рибну збудували сини Сенаїні, і вони покрили її бру́ссями, і повставляли двері її, замки́ її та за́суви її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'А поруч них направляв Меремот, син Урії, Коцового сина, а поруч них направляв Мешуллам, син Берехії, Мешав\'їлового сина, а поруч них направляв Садок, Баанин син.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'А поруч них направляли текояни, але́ їхні вельмо́жі не схилили своєї шиї в службу свого Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'А браму Стару направляли Йояда, син Пасеахів, та Мешуллам, син Бесодеїн, — вони покрива́ли бру́ссями, і вставляли двері її, і замки́ її та за́суви її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'А поруч них направляв ґів\'онеянин Мелатія та меронотеянин Ядон, люди Ґів\'ону та Міцпи, що належали до володі́ння намісника Заріччя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Поруч нього направляв Уззіїл, син Хархаїн, з золотарів, а поруч нього направляв Хананія, син Раккахімів, — і вони віднови́ли Єрусалима аж до Широкого муру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'А поруч нього направляв Рефая, син Хурів, зверхник половини єрусалимської округи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'А поруч нього направляв Єдая, син Харумафів, а то навпроти дому свого, а при його руці направляв Хаттуш, син Хашавнеїн.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Другу міру направляв Малкійя, син Харімів, та Хашшув, син Пахат-Моавів, та башту Печей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'А поруч нього направляв Шаллум, син Лохеша, зверхник половини єрусалимської окру́ги, він та дочка́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Браму Долинну направляв Ханун та ме́шканці Заноаху, — вони збудували її, і повставляли двері її, замки́ її та за́суви її, і тисячу ліктів у мурі аж до Смітнико́вої брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'А Смітнико́ву браму направив Малкійя, син Рехавів, зверхник бет-керемської округи, — він збудував її, і повставля́в її двері, замки́ її та за́суви її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'А Джерельну браму направив Шаллум, син Кол-Хезеїв, зверхник округи Міцпи, — він збудував її, і покри́в її, і повставля́в її двері, замки́ її та за́суви її, і направив мура ставу Шелах до царсько́го садка́, і аж до ступені́в, що спускаються з Давидового Міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 16, 'За ним направляв Неемія, син Азбуків, зверхник половини бетцурської окру́ги аж до місця навпроти Давидових гробі́в і аж до зробленого ста́ву, і аж до дому Лицарів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 17, 'За ним направляли Левити: Рехум, син Баніїв, поруч нього направляв зверхник половини округи Кеїла, для своєї окру́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 18, 'За ним направляли їхні брати: Баввай, син Хенададів, зверхник половини окру́ги Кеїла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 19, 'І направляв поруч нього Езер, син Єшуїн, зверхник округи, міру другу, від місця навпроти виходу до зброя́рні наріжника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 20, 'За ним ревно направляв Барух, Заббаїв син, міру другу, від наріжника аж до входу до дому первосвященика Еліяшіва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 21, 'За ним направляв Меремот, син Урійї, сина Коцового, міру другу, від входу до Еліяшівового дому й аж до кінця Еліяшівового дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 22, 'А за ним направляли священики, люди йорданської окру́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 23, 'За ним направляв Веніямин, син Хашшувів, навпроти свого дому; за ним направляв Азарія, син Маасеї, сина Ананіїного, при своєму домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 24, 'За ним направляв Біннуй, син Хенададів, міру другу, від Азаріїного дому аж до нарі́жника й аж до ро́гу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 25, 'Палал, син Узаїв, — від місця навпроти наріжника та в горі́шній башті, що вихо́дить із царсько́го дому, що при в\'язни́чному подві́р\'ї. За ним Педая, син Пар\'ошів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 26, 'А підда́нці храму сиділи в Офелі аж до місця навпроти Водної брами на схід та навпро́ти виступа́ючої башти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 27, 'За ним направляли техояни, міру другу, від місця навпроти великої виступаючої башти й аж до офельського му́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 28, 'З-над Кінської брами направляли священики, кожен навпроти дому свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 29, 'За ним и направляв Садо́к, син Іммерів, навпроти свого дому, а за ним направляв Шемая, син Шеханіїн, сторож Схі́дньої брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 30, 'За ним направляв Хананія, син Шелеміїн, та Ханун, шо́стий син Цалафів, міру другу; за ним направляв Мешуллам, син Берехіїн, навпроти своєї кімна́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 31, 'За ним направляв Малкійя, син золотаря́, аж до дому храмови́х підда́нців та крамарі́в, навпроти брами Міфкад і аж до наріжної го́рниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 32, 'А між наріжною го́рницею до Овечої брами направляли золотарі́ та крамарі́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 33, 'І сталося, як почув Санваллат, що ми будуємо того мура, то він запалився гнівом, і дуже розгнівався, і сміявся з юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 34, 'І говорив він перед своїми брата́ми та самарійським ві́йськом і сказав: „Що́ це роблять ці мізерні юдеї? Чи їм це позоставлять? Чи бу́дуть вони прино́сити жертву? Чи закі́нчать цього дня? Чи ожи́влять вони ці камі́ння з куп по́роху, а вони ж — попа́лені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 35, 'А аммоні́тянин Товійя був при ньому й сказав: „Та й що́ вони будують? Якщо вийде лисиця, то вона зробить дірку в їхній камінній стіні́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 36, '„Почуй, Боже наш, що ми стали пого́рдою, і поверни їхню га́ньбу на голову їхню, і дай їх на здо́бич у край поло́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 37, 'І не закрий їхньої провини, а їхній гріх нехай не буде стертий з-перед лиця Твого, бо вони обра́зили будівничих!“І збудува́ли ми того мура, і був пов\'я́заний увесь той мур аж до половини його́. А серце народу було, щоб да́лі робити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'І сталося, як почув Санвалла́т, і Товійя, і араби, і аммонітяни, і ашдодяни, що направляється єрусалимський мур, що ви́ломи в стіні стали затарасо́вуватися, то дуже запали́лися гнівом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'І змо́вилися вони всі ра́зом, щоб іти воювати з Єрусалимом, та щоб учинити йому замі́шання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'І ми молилися до нашого Бога, і поставили проти них сторо́жу вдень та вночі, перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'І сказав Юда: „Осла́бла сила носія́, а зва́лищ багато, — і ми не зможемо да́лі будувати мура!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'А наші нена́висники говорили: „Вони не знатимуть і не побачать, як ми при́йдемо до сере́дини їх, і позабива́ємо їх, та її спи́нимо працю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'І сталося, як прихо́дили ті юде́яни, що сиділи при них, то говорили нам про це разі́в десять, зо всіх місць, де вони пробува́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Тоді поставив я сторо́жу здо́лу того місця за муром у пече́рах. І поставив я народ за їхніми ро́дами, з їхніми меча́ми, їхніми ра́тищами та їхніми лу́ками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'І розглянув я це, і встав і сказав я до шляхе́тних, і до заступників, і до решти наро́ду: „Не бійтеся перед ними! Згадайте Господа великого та грізно́го, і воюйте за ваших братів, ваших синів, дочо́к ваших, жіно́к ваших та за доми́ ваші!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'І сталося, як почули наші вороги́, що нам те відо́ме, то Господь зламав їхній за́дум, і всі ми верну́лися до муру, кожен до праці своєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'І було́ від того дня, що половина моїх юнакі́в робили працю, а половина їх міцно тримала списи, щити́, і луки та па́нцері, а зверхники стояли позад Юдиного дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Будівни́чі працювали на мурі, а носії́ наладо́вували тяга́р, — вони однією рукою робили працю, а однією міцно тримали списа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'А в кожного будівничого його меч був прив\'я́заний на сте́гнах його, і так вони будували, а біля мене був сурма́ч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'І сказав я до шляхе́тних, до заступників та до решти наро́ду: „Праця велика й просто́ра, а ми повідді́лювані на мурі, дале́ко один від о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Тому то в місце, де почуєте голос сурми́, туди негайно збирайтеся до нас. Бог наш буде воювати для нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'І так ми робили працю, і половина їх міцно тримала списи від сходу ранньої зорі аж до поя́влення зір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Також того ча́су сказав я до наро́ду: „Кожен з юнако́м своїм нехай ночують у сере́дині Єрусалиму, і бу́дуть вони для нас уночі — сторо́жею, а вдень — на працю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'І ні я, ані брати мої, ані юнаки́ мої, ані сторожі́, що були за мною, ми не здіймали своєї оде́жі, — кожен мав свою зброю при своє́му стегні́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 18, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 19, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 20, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 21, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 22, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 23, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'І був великий крик наро́ду та їхніх жіно́к на своїх братів юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'І були такі, що говорили: „Ми даємо́ в заста́ву синів своїх та дочо́к своїх, і беремо́ збіжжя, і їмо й живемо́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'І були такі, що говорили: „Ми заставля́ємо поля свої, і виноградники свої, і доми́ свої, і беремо́ збіжжя в цьому голоді!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'І були́ такі, що говорили: „Ми позичаємо срібло на податок царськи́й за наші поля та наші виноградники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'А наше ж тіло таке, як тіло наших братів, наші сини — як їхні сини. А ось ми ти́снемо наших синів та наших дочо́к за рабів, і є з наших дочо́к ути́скувані. Ми не в силі робити, а поля́ наші та виноградники наші належать іншим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'І сильно запала́в у мені гнів, коли я почув їхній крик та ці слова́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'А моє серце дало́ мені раду, і я спереча́вся з шляхе́тними та з заступниками та й сказав їм: „Ви заста́вою ти́снете один о́дного!“І скликав я на них великі збори.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'І сказав я до них: „Ми викупо́вуємо своїх братів юдеїв, про́даних пога́нам, за нашою спромогою, а ви бу́дете продавати своїх братів, і вони продаються нам?“І мовчали вони, і не знахо́дили слова...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'І сказав я: „Не добра це річ, що ви робите! Чи ж не в бо́язні нашого Бога ви маєте ходити, через га́ньбу від тих поганів, наших ворогів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Також і я, брати мої та юнаки́ мої були позикода́вцями срібла та збіжжя. Опустімо ж ми оцей борг!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Верніть їм зараз їхні поля́, їхні виноградники, їхні оли́вки, й їхні доми́ та відсо́ток срібла, і збіжжя, виноградний сік та нову́ оливу, що ви дали їм у заста́ву за них!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'І вони сказали: „Пове́рнемо, і не бу́демо жадати від них! Зро́бимо так, як ти говориш!“І покликав я священиків, і заприсягну́в їх зробити за цим словом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Витрусив я й свою па́зуху та й сказав: „Нехай отак ви́трусить Бог кожного чоловіка, хто не спо́внить цього слова, з дому його та з труду його, і нехай бу́де такий ви́трушений та поро́жній!“І сказали всі збори: „Амі́нь!“І сла́вили вони Господа, і наро́д зробив за цим словом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Також від дня, коли цар наказав мені бути їхнім намі́сником в Юдиному кра́ї від року двадцятого й аж до року тридцять другого царя Артаксе́ркса, — дванадцять літ не їв намі́сничого хліба ані я, ані брати мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 15, 'А намі́сники попере́дні, що були́ передо мною, чинили тяжке́ над наро́дом, і брали від них хлібом та вином одно́го дня сорок шеклів срібла; також їхні слу́ги панували над наро́дом. А я не робив так через страх Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 16, 'А також у праці того муру я підтри́мував, і по́ля не купували ми, а всі мої слу́ги були зібрані там над працею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 17, 'А за столом моїм були юдеї та заступники, — сто й п\'ятдеся́т чоловіка, та й ті, хто прихо́див до нас із народів, що навколо нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 18, 'А що гото́вилося на один день, було: віл один, худоби дрібної — шестеро ви́браних, і птиця готува́лася в мене, а за десять день вихо́дило багато всякого вина. А при то́му я не жадав намісничого хліба, бо та робота направи мурів була тяжка́ на тому народі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 19, 'Запам\'ятай же мені, Боже мій, на добре все те, що́ я робив для цього народу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'І сталося, коли почув Санваллат, і Товійя, і араб Ґешем та решта наших ворогів, що я збудував мура, і що не позоста́лося в ньому ви́лому, — але до цього ча́су дверей у брамах я не повставля́в, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'то послав Санваллат та Ґешем до мене, говорячи: „Приходь, і вмовимося ра́зом у Кефірімі в долині Оно!“А вони замишляли зробити мені зло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'І послав я до них послів, говорячи: „Я роблю́ велику працю, і не мо́жу прийти. На́що буде перервана ця праця, як кину її та піду́ до вас?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'І посилали до мене так само чотири ра́зи, а я відповідав їм так само.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'І так само Санваллат п\'ятий раз прислав до ме́не слугу́ свого́, а в руці його був відкритий лист.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'А в ньому написане: „Чується серед наро́дів, і Ґашму говорить: Ти та юдеї замишляєте відділитися, тому́ то ти будуєш того мура, і хочеш бути їм за царя, за тими слова́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Та й пророків ти понаставля́в, щоб викри́кували про тебе в Єрусалимі, говорячи: Цар в Юді! А тепер цар почує оці речі. Отож, — приходь, і пора́дьмося ра́зом!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'І послав я до ньо́го, говорячи: „Не було́ таких речей, про які ти говориш, бо з серця свого ти їх повимишля́в!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Бо всі вони лякали нас, говорячи: „Нехай осла́бнуть їхні руки з цієї праці, — і не буде вона зро́блена!“Та тепер, о Боже, зміцни́ мої ру́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'І я ввійшов до дому Шемаї, сина Делаї, Мегетав\'їлового сина, а він був заде́ржаний. І він сказав: „Умовмося піти до Божого дому, до сере́дини храму, і замкне́мо храмові двері, бо при́йдуть забити тебе, — власне вночі при́йдуть забити тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Та я відказав: „Чи такий чоловік, як я, має втікати? І хто́ є такий, як я, що вві́йде до храму й буде жити? Не ввійду́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'І пізнав я, що то не Бог послав його, коли він говорив на мене те пророцтво, а то Товійя та Санваллат підкупи́ли його́...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Бо він був підку́плений, щоб я боявся, — і зробив так, і згрішив. Це було для них на злий погові́р, щоб обра́зити мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Запам\'ятай же, Боже мій, Товійї та Санваллатові за цими вчинками його́, а також пророчиці Ноадії та решті пророків, що страха́ли мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 15, 'І був закі́нчений мур двадцятого й п\'ятого дня місяця елула, за п\'ятдеся́т і два дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 16, 'І сталося, як почули про це всі наші вороги, та побачили всі народи, що були навко́ло нас, то вони впали в оча́х своїх та й пізнали, що ця праця була зро́блена від нашого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 17, 'Тими днями також шляхе́тні юдеї писали багато своїх листів, що йшли до Товійї, а Товійїні прихо́дили до них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 18, 'Бо багато-хто в Юдеї були заприся́женими при́ятелями йому, бо він був зять Шеханії, Арахового сина, а син його Єгоханан узяв дочку́ Мешуллама, Берехіїного сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 19, 'І говорили передо мною добре про нього, а слова́ мої передавали йому. Товійя посилав листи́, щоб настраха́ти мене́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'І сталося, як був збудо́ваний мур, то повставля́в я двері, і були понаста́влювані придве́рні, співаки́ та Левити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'І призна́чив я над Єрусалимом свого брата Ханані та зверхника тверди́ні Хананію, бо він був чоловік правдивий, і Бога боявся більше від багатьох інших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'І сказав я до них: „Нехай не відчиня́ються єрусалимські брами аж до спе́ки сонця. І поки вони самі стоять, нехай позамика́ють двері, і так тримайте. І поста́вити ва́рти з єрусалимських ме́шканців, кожного на його сторожі, і кожного навпроти його дому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'А місто було широко-просто́ре й велике, та народу в ньо́му мало, і доми не були побудо́вані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'І поклав мені Бог мій на серце моє зібрати шляхе́тних, і заступників та наро́д, щоб переписати. І знайшов я книжку пе́репису тих, хто прийшов перше, а в ній я знайшов написане таке:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Оце вихо́дьки з округи, що прийшли з поло́ну вигна́ння, яких вигнав був Навуходоно́сор, цар вавилонський, і вони повернулися до Єрусалиму та до Юдеї, кожен до міста свого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'ті, що прийшли були з Зоровавелем, Ісусом, Неемією, Азарією, Раамією, Нахаманієм, Мордехаєм, Білшаном, Місперетом, Біґваєм, Нехумом, Бааною. Число людей Ізраїлевого наро́ду:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'синів Пар\'ошових — дві тисячі сто й сімдеся́т і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'синів Шеватіїних — три сотні і сімдесят і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'синів Арахових — шість сотень п\'ятдеся́т і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 11, 'синів Пахат-Моавових, із синів Ісусових та Йоавових — дві тисячі й вісім сотень вісімнадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 12, 'синів Еламових — тисяча двісті п\'ятдеся́т і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 13, 'синів Заттуєвих — вісім сотень сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 14, 'синів Заккаєвих — сім сотень і шістдеся́т,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 15, 'синів Біннуєвих — шість сотень сорок і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 16, 'синів Беваєвих — шість сотень двадцять і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 17, 'синів Азґадових — дві тисячі три сотні двадцять і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 18, 'синів Адонікамових — шість сотень шістдеся́т і сім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 19, 'синів Біґваєвих — дві тисячі шістдесят і сім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 20, 'синів Адінових — шість сотень п\'ятдеся́т і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 21, 'синів Атерових, — з синів Хізкійїних — дев\'ятдеся́т і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 22, 'синів Хашумових — три сотні двадцять і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 23, 'синів Бецаєвих — три сотні двадцять і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 24, 'синів Харіфових — сто дванадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 25, 'синів Ґів\'онових — дев\'ятдеся́т і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 26, 'людей з Віфлеєму та Нетофи — сто вісімдеся́т і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 27, 'людей з Анототу — сто двадцять і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 28, 'людей з Бет-Азмавету — сорок і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 29, 'людей з Кір\'ят-Єаріму, Кефіри та Беероту — сім сотень сорок і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 30, 'людей з Рами та Ґави — шість сотень двадцять і один,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 31, 'людей з Міхмасу — сто двадцять і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 32, 'людей з Бет-Елу та Аю — сто двадцять і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 33, 'людей з Нево Другого — п\'ятдеся́т і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 34, 'вихо́дьків з Еламу Другого — тисяча двісті п\'ятдесят і чотири,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 35, 'виходьків з Харіму — три сотні й двадцять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 36, 'виходьків з Єрихону — три сотні сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 37, 'виходьків з Лоду, Хадіду й Оно — сім сотень і двадцять і один,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 38, 'вихо́дьків з Сенаї — три тисячі дев\'ять сотень і тридцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 39, 'Священиків: синів Єдаїних з Ісусового дому — дев\'ять сотень сімдеся́т і три,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 40, 'синів Іммерових — тисяча п\'ятдесят і два,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 41, 'синів Пашхурових — тисяча двісті сорок і сім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 42, 'синів Харімових — тисяча сімнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 43, 'Левитів: синів Ісусових з Кадміїлового дому, з Годевиних синів — сімдеся́т і чотири.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 44, 'Співакі́в: синів Асафових — сто сорок і вісім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 45, 'Придве́рних: синів Шаллумових, синів Атерових, синів Талмонових, синів Аккувових, синів Хатітиних, синів Шоваєвих — сто тридцять і вісім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 46, 'Храмови́х підда́нців: сини Ціхині, сини Хасуфині, сини Таббаотові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 47, 'сини Керосові, сини Сіїні, сини Падонові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 48, 'сини Леванині, сини Хаґавині, сини Салмаєві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 49, 'сини Хананові, сини Ґідделові, сини Ґахарові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 50, 'сини Реаїні, сини Рецінові, сини Некодині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 51, 'сини Ґаззамові, сини Уззині, сини Пасеахові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 52, 'сини Бесаєві, сини Меунімові, сини Нефішесінові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 53, 'сини Бакбутові, сини Хакуфині, сини Хархурові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 54, 'сини Бацлітові, сини Мехидині, сини Харшині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 55, 'сини Баркосові, сини Сісерині, сини Темахові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 56, 'сини Неціяхові, сини Хатіфині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 57, 'Синів Соломонових рабів: сини Сотаєві, сини Соферетові, сини Перідині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 58, 'сини Яалині, сини Дарконові, сини Ґідделові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 59, 'сини Шефатіїні, сини Хаттілові, сини Похерет-Гаццеваїмові, сини Амонові, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 60, 'усього цих храмови́х підда́нців та синів Соломонових рабів — три сотні дев\'ятдеся́т і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 61, 'А оце ті, що прийшли з Тел-Мелаху, з Тел-Харші, Керув-Аддону та Іммеру, та не могли дове́сти роду батьків своїх та свого насіння, чи вони з Ізраїля:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 62, 'синів Делаїних, синів Товійїних, синів Некодиних — шість сотень сорок і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 63, 'А з священиків: сини Ховаїні, сини Коцові, сини Барзіллая, що взяв жінку з дочо́к ґілеадянина Барзіллая, і став зватися їхнім ім\'ям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 64, 'Вони шукали за́пису свого родово́ду, але він не знайшовся, — і були вони ви́лучені зо свяще́нства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 65, 'а намісник сказав їм, щоб вони не їли зо Святого Святих, аж поки не стане священик до урі́му та туммі́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 66, 'Усього збору ра́зом — сорок дві тисячі триста й шістдеся́т,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 67, 'окрім їхніх рабів та їхніх невільниць, — цих було сім тисяч триста тридцять і сім; а в них співакі́в та співа́чок — двісті й сорок і п\'ять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 68, 'Їхніх ко́ней було сім сотень тридцять і шість, їхніх мулів — двісті сорок і п\'ять,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 69, 'верблю́дів — чотири сотні тридцять і п\'ять, ослів — шість тисяч і сім сотень і двадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 70, 'А частина голі́в ба́тьківських ро́дів дали́ на працю: намісник дав до скарбниці: золота тисячу даре́йків, кропи́льниць — п\'ятдеся́т, священичих шат — п\'ятсот і тридцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 71, 'А з голів ба́тьківських родів дали до скарбниці на працю: золота — двадцять тисяч дарейків, а срібла — дві тисячі й двісті мін.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 72, 'А що дала́ ре́шта наро́ду: золота — двадцять тисяч дарейків, а срібла — дві тисячі мін, а священичих шат — шістдеся́т і сім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 73, 'І осілися священики, і Левити, і придве́рні, і співаки, і дехто з наро́ду, і храмові підда́нці, і ввесь Ізраїль по своїх міста́х. Як настав сьомий місяць, то Ізраїлеві сини були по своїх містах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'І зібрався ввесь наро́д, як один чоловік, на майда́н, що перед Водною брамою, і сказали учителеві Ездрі прине́сти книги Мойсеєвого Зако́ну, що наказав був Господь Ізра́їлеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'І приніс священик Ездра Зако́на перед збори з чоловіків та аж до жіно́к, і всіх, хто розумів чуте, першого дня сьомого місяця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'І читав він у нім на майда́ні, що перед Водною брамою, від світанку аж до полу́дня, перед чоловіками й жінка́ми та тими, хто розуміє, а уші всього народу були звернені до книги Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'І стояв учитель Ездра на дерев\'я́ному підви́щенні, що зробили для цієї справи, а при ньому стояв Маттітія, і Шема, і Аная, і Урійя, і Хілкійя, і Маасея на прави́ці його, а на ліви́ці його: Педая, і Мішаїл, і Малкійя, і Хашум, і Хашбаддана, Захарій, Мешуллам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'І розгорнув Ездра цю книгу на оча́х усього народу, бо він був вище від усього народу, а коли він розгорнув, увесь наро́д устав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'І поблагословив Ездра Господа, Бога великого, а ввесь народ відповів: „Амі́нь, Амі́нь!“з підне́сенням своїх рук. І всі схиля́лися, і вклонялися Господе́ві обличчям до землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'А Ісус, і Бані, і Шеревея, Ямін, Аккув, Шаббетай, Годійя, Маасея, Келіта, Азарія, Йозавад, Ханан, Пелая та Левити пояснювали наро́дові Зако́на, а народ був на своєму місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'І читали в книзі, у Божому Зако́ні вира́зно, і вияснювали зна́чення, і робили зрозумілим чи́тане.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'І сказав намісник Неемія, і священик учитель Ездра й Левити, що вияснювали наро́дові, до всього наро́ду: „День цей — святий він для Господа, Бога вашого, — не будьте в жало́бі й не плачте!“Бо плакав увесь наро́д, як почув слова Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'І сказав він до них: „Ідіть, їжте сите та пийте солодке, і посилайте ча́стки тому́, в кого нема нагото́вленого. Бо святий цей день для нашого Господа, і не сумуйте, бо радість у Господі — це ваша сила!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'І Левити потіша́ли ввесь наро́д, говорячи: „Мовчіть, бо цей день святий, — і не сумуйте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'І пішов увесь наро́д їсти та пити, і посилати ча́стки та чинити велику радість, бо розумів ті слова, що розповіли́ йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'А другого дня зібра́лися го́лови ба́тьківських родів усього народу, священики та Левити, до вчителя Ездри, щоб він виясня́в їм слова́ Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'І знайшли напи́сане в Зако́ні, що наказав був Господь через Мойсея, щоб Ізраїлеві сини сиділи в ку́чках у свято сьомого місяця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'і щоб розголоси́ли й оголосили по всіх своїх міста́х та в Єрусалимі, говорячи: „Вийдіть на го́ру, і понано́сьте галу́ззя оли́вкового, і галу́ззя дерева оли́вкового, і галуззя ми́ртового, і галуззя па́льмового, і галуззя густоли́стого дерева, щоб поробити ку́чки, як написано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'І вийшов народ, і поназно́шували, і пороби́ли собі ку́чки кожен на даху́ своїм, і в подві́р\'ях своїх, і в подві́р\'ях Божого дому, і на майда́ні Водної брами, і на майда́ні брами Єфремової.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'І поробила ку́чки вся громада, що вернулася з поло́ну, і сиділа в ку́чках, бо не робили так Ізраїлеві сини від днів Ісуса, Нави́нового сина, аж до дня цього. І була дуже велика радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 18, 'І читал и в книзі Божого Зако́ну щоденно, від першого дня аж до дня останнього. І справля́ли свято сім день; а восьмого дня — відда́ння, за уста́вом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'А двадцятого й четвертого дня того місяця зібра́лися Ізраїлеві сини в по́сті та в вере́тищах, а на них — по́рох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'А Ізраїлеве насіння відділи́лося від усіх чужи́нців, і поставали й визнавали гріхи свої та провини своїх батьків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'І стали на місті своїм, і чверть дня читали з книги Зако́ну Господа, Бога свого, а чверть сповіда́лися і вклонялися Господе́ві, Богові своєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'І стали на леви́тському підви́щенні Ісус, і Бані, Кадміїл, Шеванія, Бунні, Шеревея, Бані, Кенані, і кли́кали сильним голосом до Господа, Бога свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'І сказали Левити: Ісус, і Кадміїл, Бані, Хашавнея, Шеревея, Годійя, Шеванія, Петахія: „Устаньте, поблагословіть Господа, Бога свого́, від віку аж до віку! І нехай благословляють Ім\'я́ слави Твоєї, і нехай воно буде звели́чене над усяке благослове́ння та славу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Ти Господь єдиний! Ти вчинив небо, небеса небе́с, і все їхнє ві́йсько, землю та все, що на ній, моря та все, що в них, і Ти оживля́єш їх усіх, а небесне ві́йсько Тобі вклоня́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Ти — то Господь, Бог, що вибрав Авра́ма, і вивів його́ з халдейського Уру, і дав йому ім\'я́ Авраа́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'І Ти знайшов серце його вірним перед лицем Своїм, і склав був із ним заповіта, щоб дати край хананеян, хіттеян, амореян, періззеян, євусеян, ґірґасеян, щоб дати насінню його. І Ти ви́конав слова́ Свої, бо Ти праведний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'І побачив Ти біду наших батьків ув Єгипті, а їхній зойк Ти почув над Червоним морем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'І дав Ти знаки́ та чу́да на фараоні та на всіх його раба́х, і на всім наро́ді краю його, бо пізнав Ти, що вони гордо пово́дилися з ними, і зробив Ти Собі Ім\'я́, як видно цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'І море Ти розсі́к перед ними, і вони перейшли́ серед моря по суходо́лу, а тих, хто гнався за ними, Ти кинув до глиби́н, як камінь до бурхли́вої води.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'І Ти прова́див їх стовпо́м хмари вдень, а стовпо́м огню́ вночі, щоб освітлювати їм ту дорогу, якою мали йти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'І Ти зійшов був на го́ру Сіна́й, і говорив з ними з небе́с, і дав їм справедливі права́ та правдиві зако́ни, устави та заповіді добрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'І святу Свою суботу Ти вказав їм, а заповіді, й устави та право наказав Ти їм через раба Свого Мойсея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'І хліб із небе́с дав Ти був їм на їхній голод, і воду зо скелі Ти вивів був їм на їхню спра́гу. І Ти сказав їм, щоб ішли посі́сти край, який Ти присягну́в дати їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Та вони й наші батьки́ були вперті, і робили твердо́ю свою шию, і не слухали Твоїх за́повідей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'І відмовля́лися вони слухати, і не пам\'ятали чуд Твоїх, які Ти чинив був із ними, і стали твердоши́ї, і настанови́ли собі го́лову, щоб вернутися до своєї неволі в непо́слуху. Та Ти Бог, що прощаєш, Ти ласка́вий та милосе́рдний, довготерпели́вий та багатомилости́вий, — і Ти не покинув їх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Хоч вони зробили були́ собі ли́того тельця́ та сказали: Оце бог твій, що ви́вів тебе з Єгипту, і робили великі обра́зи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'та Ти в великім Своїм милосерді не залишив їх у пустині, — стовп хмари не відходив від них удень, щоб ве́сти їх дорогою, а стовп огню́ вночі, щоб освітлювати їм дорогу, якою мали йти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'І Духа Свого доброго Ти давав, щоб зробити їх мудрими, і ма́нни Своєї не стри́мував від їхніх уст, і во́ду Ти їм давав на їхнє пра́гнення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'І сорок літ живив Ти їх у пустині. Не було недоста́тку ні в чо́му, — одежі їхні не де́рлися, а но́ги їхні не пу́хли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'І дав Ти їм царства та наро́ди, які призна́чив на по́діл, — і вони посіли край Сиго́на, і край царя хешбонського, і край Оґа, царя башанського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'А їхніх синів Ти помно́жив, як зо́рі небесні, і ввів їх до кра́ю, що про нього казав Ти їхнім батька́м, щоб ішли посісти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'І ввійшли сини, і посіли той край, і Ти впокори́в перед ними ме́шканців того кра́ю ханаане́ян, і дав у їхню руку їх та царів їхніх, та наро́ди того кра́ю, щоб чинити з ними за своєю волею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'І поздобува́ли вони міста́ укрі́плені, та землю ситу, і посі́ли доми, повні всякого добра́, повите́сувані в ске́лях водозбо́ри, виноградники, і оливки, і багато овоче́вих дере́в. І вони їли й наси́тилися, і постава́ли товсті́, і насоло́джувалися Твоїм великим добро́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'І стали вони неслухня́ні, і побунтува́лися проти Тебе, і кинули Зако́на Твого геть за свою спи́ну, і позабивали пророків Твоїх, що сві́дчили між ними, щоб навернути їх до Те́бе. І чинили вони великі обра́зи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'І дав Ти їх у руку їхніх ворогів, а ті утиска́ли їх. А в ча́сі горя свого вони кли́кали до Тебе, а Ти з неба чув, і за Своїм великим милосе́рдям давав їм спаси́телів, і вони спасали їх з руки́ їхніх ворогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Та коли був їм мир, вони зно́ву чинили зло перед лицем Твоїм, і Ти давав їх у ру́ку їхніх ворогів, і ті панува́ли над ними. І вони зно́ву кли́кали до Тебе, а Ти з неба їх вислухо́вував, і спаса́в їх за милосе́рдям Своїм довгий час.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'І сві́дчив Ти проти них, щоб наверну́ти їх до Зако́ну Твого, та вони чинили лихе́, і не слу́халися за́повідей Твоїх, і грішили проти Твоїх прав, — які коли б люди́на чинила, то жила́ б ними, — і ставало раме́но їх неслухня́не, а шию свою робили твердо́ю, і не слухалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'І зволіка́в Ти їм довгі ро́ки, і сві́дчив проти них Своїм Духом через Своїх пророків, та вони не слу́хали того, і Ти дав їх у ру́ку народів цих країв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'І через велике Своє милосердя Ти не ви́губив і не покинув їх, бо Ти Бог ласка́вий та милосе́рдний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'А тепер, Боже наш, Боже великий, сильний та страшни́й, що бережеш заповіта та милість, — нехай не буде мало́ю перед лицем Твоїм уся та му́ка, що спіткала нас, наших царів, наших зверхників, і священиків наших, і пророків наших, і батьків наших, і ввесь Твій наро́д від днів асирійських царів аж до цього дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 33, 'А ти справедливий у всьо́му, що прихо́дить на нас, бо Ти правду робив, а ми були несправедли́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 34, 'А наші царі, наші зверхники, наші священики та наші батьки́ не вико́нували Зако́на Твого, і не слухалися за́повідей Твоїх та свідо́цтв Твоїх, що Ти сві́дчив проти них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 35, 'І вони в царстві своїм та в великім добрі Твоїм, яке Ти їм давав, і в то́му просто́рому та си́тому кра́ї, що Ти дав перед ними, не служили Тобі, і не відверну́лися від своїх злих чинів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 36, 'Ось ми сьогодні раби, а цей Край, що Ти дав його́ нашим батькам, щоб їсти плід його та добро́ його, — ось ми раби в ньому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 37, 'І він мно́жить свій урожа́й для царів, яких Ти дав над нами за наші гріхи, і вони панують над нашими тіла́ми та над нашою худобою за своїм уподо́банням, і ми в великому у́тискові!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 38, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Через те все ми складаємо певну умову, і підписуємо, а печа́тки кладуть наші зверхники, наші Левити, наші священики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'А між тих, що поклали печа́тки, були: намісник Неемія, син Хахаліїн, і Цідкійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Серая, Азарія, Єремія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 4, 'Пашхур, Амарія, Малкійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 5, 'Хаттуш, Шеванія, Маллух,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 6, 'Харім, Меремот, Овадія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 7, 'Даніїл, Ґіннетон, Барух,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 8, 'Мешуллам, Авійя, Мійямін,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 9, 'Маазія, Білґай, Шемая, — оце священики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 10, 'А Леви́ти: Ісус, син Азаніїн, Біннуй, з Хенададових синів, Кадміїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 11, 'А їхні брати: Шеванія, Годійя, Келіта, Пелая, Ханан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 12, 'Міха, Рехов, Хашавія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 13, 'Заккур, Шеревія, Шеванія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 14, 'Годійя, Бані, Беніну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 15, 'Го́лови наро́ду: Пар\'ош, Пахат-Моав, Елам, Затту, Бані,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 16, 'Бунні, Аз\'дад, Бевай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 17, 'Адонійя, Біґвай, Адін,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 18, 'Атер, Хізкійя, Аззур,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 19, 'Годійя, Хашум, Бецай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 20, 'Харіф, Анатот, Невай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 21, 'Маґпіяш, Мешуллам, Хезір,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 22, 'Мешезав\'їл, Садок, Яддуя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 23, 'Пелатія, Ханан, Аная,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 24, 'Осі́я, Хананія, Хашшув,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 25, 'Галлохеш, Пілха, Шовек,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 26, 'Рехум, Хашавна, Маасея,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 27, 'і Ахійя, Ханан, Анан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 28, 'Маллух, Харім, Баана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 29, 'І решта наро́ду, священики, Левити, придве́рні, співаки́, храмові́ підда́нці, і кожен, відділений від наро́дів кра́ю до Божого Зако́ну, їхні жінки́, їхні сини́, та їхні до́чки, кожен знаю́чий та розуміючий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 30, 'зміцня́ють прися́гу при браттях своїх, при своїх шляхе́тних, і вступили в клятву та прися́гу, щоб ходити в Божому Зако́ні, що був да́ний через Мойсея, Божого раба, і щоб дотри́муватися, і щоб вико́нувати всі заповіді Господа, нашого Бога, і права Його, і постано́ви Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 31, 'і що не дамо́ наших синів наро́дам кра́ю, а їхніх дочо́к не ві́зьмемо для наших синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 32, 'А від наро́дів цього Кра́ю, що спрова́джують това́ри та всяке збі́жжя в день субо́тній на про́даж, не ві́зьмемо від них у суботу та в святі дні, і сьо́мого року понеха́ємо землю та всякого роду борги́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 33, 'І поставили ми собі за обов\'я́зок, щоб давати нам третину шекля в рік на службу дому нашого Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 34, 'на хліб показни́й, і на пості́йний дар, і на пості́йне цілопа́лення, на суботи, на молодики́, на свята, і на освячені речі, і на же́ртви за гріх на оку́плення за Ізраїля, і на всяку працю дому нашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 35, 'І кинули ми жеребки́ про пожертву дров, священики, Левити та наро́д, щоб прино́сити до дому нашого Бога, за домом наших батьків, на озна́чені часи́ рік-річно, щоб палити на же́ртівнику Господа, нашого Бога, як напи́сано в Зако́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 36, 'і щоб прино́сити первопло́ди нашої землі та первопло́ди всякого пло́ду зо всякого де́рева рік-річно до Господнього до́му,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 37, 'і перворо́джених синів наших та нашої худоби, як написано в Зако́ні, і перворо́джених худоби нашої великої та худоби нашої дрібно́ї, щоб прино́сити до дому нашого Бога до священиків, що служать у домі нашого Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 38, 'і первопоча́ток наших діж, і наші прино́шення, і плід усякого де́рева, молоде́ вино та оливу спрова́димо священикам до кімна́т дому нашого Бога, а десятину нашої землі — Левитам. А вони, Левити, будуть збирати десятину по всіх містах нашої роботи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 39, 'І буде священик, син Ааронів, із Левитами, коли Левити будуть збирати десятину, і Левити віднесу́ть десятину від десятини до дому нашого Бога до комір, до скарбни́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 40, 'Бо до комір будуть зно́сити сини Ізраїлеві та сини Левитів прино́шення збіжжя, молодо́го вина та оливи, і там є речі святині, служачі священики, і придве́рні, і співаки́. І ми не опу́стимо дому нашого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 1, 'І сиділи зверхники наро́ду в Єрусалимі, а решта народу кинули жеребки, щоб приве́сти одно́го з десяти сидіти в Єрусалимі, місті святому, а дев\'ять частин зостаються по і́нших містах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 2, 'І поблагословив народ усіх тих людей, що поже́ртвувалися сидіти в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 3, 'А оце го́лови окру́ги, що сиділи в Єрусалимі, а по Юдиних міста́х сиділи, кожен у своїй посі́лості, по своїх міста́х, Ізра́їль, священики, і Левити, і храмові підда́нці, і сини Соломонових рабів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 4, 'А в Єрусалимі сиділи оці з синів Юдиних та з синів Веніяминових. Із синів Юдиних: Атая, син Уззійї, сина Захарія, сина Амарії, сина Шефатії, сина Магаліїла, із синів Перецових.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 5, 'І Маасея, син Баруха, сина Кол-Хозе, сина Хазаї, сина Адаї, сина Йояріва, сина Захарія, сина Шілоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 6, 'Усіх синів Перецових, що сиділи в Єрусалимі, було чотири сотні шістдесят і вісім хоро́брих людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 7, 'А оце Веніяминові сини: Саллу, син Мешуллама, сина Йоеда, сина Педаї, сина Кадаї, сина Маасеї, сина Ітіїла, сина Ісаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 8, 'А по ньому: Ґаббай, Саллай, — дев\'ять сотень двадцять і вісім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 9, 'А Йоїл, син Зіхрі, був провіднико́м над ними, а Юда, син Сенуїн, дру́гий над містом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 10, 'Із священиків: Єдая, син Йоярів, Яхін,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 11, 'Серая, син Хілкійї, сина Мешуллама, сина Садока, сина Мерайота, сина Ахітува, нача́льник у Божому домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 12, 'А їхніх братів, що робили службу для Божого дому, — вісім сотень і двадцять і два. І Адая, син Єрохама, сина Пелалії, сина Амці, сина Захарія, сина Пашхура, сина Малкійї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 13, 'а їхніх братів, голів ба́тьківських родів у двісті сорок і два. І Амашсай, син Азаріїла, сина Ахезая, сина Мешіллемота, сина Іммера,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 14, 'а їхніх братів, хоробрих воякі́в, сто двадцять і вісім, а провідни́к над ними — Завдіїл, син Ґедоліма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 15, 'А з Левитів: Шемая, син Хашшува, сина Азрікама, сина Хашавії, сина Бунні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 16, 'А Шаббетай та Йозавад були над зо́внішньою службою для Божого дому, з голів Левитів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 17, 'А Матанія, син Міхи, сина Завді, сина Асафового, був головою, що починав славосло́вити при молитві, і Бакбукія, другий з братів його, і Авда, син Шаммуї, сина Ґалала, сина Єдутунового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 18, 'Усіх Левитів у святому місті було двісті вісімдеся́т і чотири.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 19, 'А придве́рні: Аккув, Талмон та їхні брати, що сторожи́ли при брамах, — сто сімдеся́т і два.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 20, 'А решта Ізраїля, священики, Левити були по всіх Юдиних містах, кожен у наді́лі своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 21, 'А храмові підда́нці сиділи в Офелі, а Ціха та Ґішпа були над підда́нцями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 22, 'А провіднико́м Левитів в Єрусалимі був Уззі, син Бані, сина Хашавії, сина Маттанії, сина Міхи, з Асафових синів, співакі́в при службі Божого дому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 23, 'бо був царі́в нака́з про них та певна оплата на співаків про кожен день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 24, 'А Петахія, син Мешезав\'їла, із синів Зераха, сина Юдиного, був при руці царя́ для всіх справ наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 25, 'А по двора́х на поля́х своїх з Юдиних синів сиділи: в Кір\'ят-Арбі та зале́жних її містах, і в Дівоні та залежних його містах, і в Єкавцеїлі та залежних його містах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 26, 'і в Єшуї, і в Моладі, і в Бет-Пелеті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 27, 'і в Хасар-Шуалі, і в Беер-Шеві та залежних його містах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 28, 'і в Ціклаґу, і в Мехоні та в залежних її містах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 29, 'і в Ен-Ріммоні, і в Цор\'ї, і в Ярмуті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 30, 'Заноаху, Адулламі та двора́х її, в Лахішу та поля́х його, в Азці та залежних її містах. І таборува́ли вони від Беер-Шеви аж до долини Гінном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 31, 'А Веніяминові сини, починаючи від Ґеви, заселили оці міста: Міхмаш, і Айя, і Бет-Ел та залежні його міста,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 32, 'Анатот, Нов, Ананія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 33, 'Хацор, Рама, Ґіттаїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 34, 'Хадід, Цевоїм, Неваллат,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 35, 'Лод і Оно, долина Харашім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 36, 'А з Левитів Юдині відділи жили в краю́ Веніямина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 1, 'А оце священики та Левити, що прийшли з Зоровавелем, сином Шеалтіїловим, та з Ісусом: Серая, Їрмея, Ездра,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 2, 'Амарія, Маллух, Хаттуш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 3, 'Шеханія, Рехум, Меремот,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 4, 'Іддо, Ґіннетой, Авійя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 5, 'Мійямін, Маадія, Білґа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 6, 'Шемая, і Йоярів, Єдая,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 7, 'Саллу, Амок, Хілкійя, Єдая. Це го́лови священиків та брати́ їхні за днів Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 8, 'А Левити: Ісус, Біннуй, Кадміїл, Шеревея, Юда, Матанія, головний над славосло́в\'ям він та брати́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 9, 'І Бакбукія та Унні, їхні брати, були навпроти них на сторо́жі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 10, 'А Ісус породив Йоякима, а Йояким породив Ел\'яшіва, а Ел\'яшів породив Йояду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 11, 'а Йояда породив Йонатана, а Йонатан породив Яддуя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 12, 'А за Йоякимових днів були священики, го́лови ба́тьківських родів: з роду Сераїного — Мерая, з Їрмеїного — Хананія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 13, 'з Ездриного — Мешуллам, з Амаріїного — Єгоханан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 14, 'з Меліхового — Йонатан, з Шеваніїного — Йо́сип,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 15, 'з Харімового — Адна, з Мерайотового — Хелкай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 16, 'з Іддового — Захарій, з Ґіннетонового — Мешуллам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 17, 'з Авійїного — Зіхрі, з Мін\'ямінового та з Моадеїного — Пілтай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 18, 'з Білґиного — Шаммуя, з Шемаїного — Йонатан,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 19, 'а з Йоярівового — Маттенай, з Єдаїного — Уззі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 20, 'з Саллаєвого — Каллай, з Амокового — Евер,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 21, 'з Хілкійїного — Хашавія, з Єдаїного — Натанаїл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 22, 'Левити, го́лови ба́тьківських ро́дів, були записані за днів Ел\'яшіва, Йояди, і Йоханана, і Яддуя, а священики — за царюва́ння Дарія перського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 23, 'Сини Леві́я, го́лови ба́тьківських родів, записані в Книгу Хронік, і аж до днів Йоханана, сина Ел\'яшівового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 24, 'А го́лови Левитів: Хашавія, Шеревія, і Ісус, син Кадміїлів, та брати́ їхні були навпроти них, щоб хвалити та сла́вити за нака́зом Давида, Божого чоловіка, черга́ за черго́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 25, 'Матанія, і Бакбукія, Овадія, Мешуллам, Талмон, Аккув, придве́рні, сторо́жа в бра́мних скла́дах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 26, 'Вони були за днів Йоякима, сина Ісуса, сина Йоцадакового, та за днів намісника Неемії та священика вчителя Ездри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 27, 'А в свято освя́чення єрусалимського муру шукали Левитів по всіх їхніх місця́х, щоб приве́сти їх до Єрусалиму спра́вити свято освя́чення та радости з похвала́ми, із піснею, цимба́лами, а́рфами та з ци́трами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 28, 'І позбира́лися сини́ співаків та з окру́ги навко́ло Єрусалиму та з осель нетофатян,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 29, 'і з Бет-Гаґґілґала, і з піль Ґеви та Азмавету, бо співаки́ побудува́ли собі двори́ навко́ло Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 30, 'І очи́стилися священики та Левити, і вони очи́стили народ, і брами та мур.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 31, 'І повво́див я Юдиних зверхників на мур, і поставив два великі збори славосло́вників та похо́ди, з них один пішов право́руч по муру до Смітнико́вої брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 32, 'А за ними йшов Гошая та половина Юдиних зверхників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 33, 'і Азарія, Ездра, і Мешуллам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 34, 'Юда, і Веніямин, Шемая, і Ірмея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 35, 'А з священичих синів із су́рмами: Захарій, син Йонатана, сина Шемаї, сина Маттанії, сина Міхаї, сина Заккура, сина Асафового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 36, 'а брати його: Шемая, і Азаріїл, Мілай, Ґілалай, Маай, Натанаїл, і Юда, Ханані з музи́чними знаря́ддями Давида, Божого чоловіка, а вчитель Ездра — перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 37, 'А при Джерельній брамі, навпроти них, вони йшли ступеня́ми Давидового Міста, входом на стіну́ над Давидовим домом і аж до Водної брами на схід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 38, 'А другий збір славосло́вників ішов ліво́руч, а за ним я та половина наро́ду, зве́рху по муру вище башти Печей та аж до Широкого муру,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 39, 'і від Єфремової брами та до брами Старо́ї, і до брами Ри́бної, і башти Ханан\'їла, і башти Меа, і аж до брами Овечої, і спини́лися біля брами Ув\'я́знення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 40, 'І стали оби́два збо́ри славосло́вників біля Божого дому, і я, і половина заступників зо мною,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 41, 'і священики: Ел\'яким, Маасея, Мін\'ямин, Міхая, Елйоенай, Захарій, Хананія з су́рмами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 42, 'і Маасея, і Шемая, і Елеазар, і Уззі, і Єгоханан, і Малкійя, і Елам, і Езер. І співаки́ співали, а Їзрахія був провіднико́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 43, 'І вони прино́сили того дня великі жертви та раділи, бо Бог порадував їх великою радістю. І раділи також жінки́ та діти, і аж дале́ко чута була радість Єрусалиму!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 44, 'І того дня були попризна́чувані люди над коморами для ска́рбів, для прино́шень, для первопло́дів та для десятин, щоб зно́сити в них з міськи́х піль зако́нні ча́стки священикам та Левитам, бо радість Юдеї була — дивитися на священиків та на Левитів, що стояли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 45, 'І вони стерегли́ постано́ви свого Бога, і постанови про очи́щення, і були співака́ми та придве́рними за нака́зом Давида та сина його Соломона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 46, 'Бо відда́вна, за днів Давида та Асафа, були го́лови співаків та пісні́ хвали́ й збори славосло́вників для Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 47, 'І ввесь Ізраїль за днів Зоровавеля та за днів Неемії давав ча́стки співа́цькі та придве́рничі, щодня належне, і освячував це Левитам, а Левити освячували Ааро́новим синам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 1, 'Того дня читане було з Мойсеєвої книги вголос наро́ду, і було зна́йдене написане в ній, що Аммоні́тянин та Моаві́тянин не вві́йде до Божої громади, і так бу́де аж навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 2, 'бо вони не стріли були Ізраїлевих синів хлібом та водою, і найняли́ були на нього Валаама прокля́сти його, та Бог наш обернув те прокляття на благослове́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 3, 'І сталося, як почули вони Зако́н, то відділили від Ізраїля все чуже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 4, 'А перед тим священик Ел\'яшів, призна́чений до комори дому нашого Бога, близьки́й Товійїн,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 5, 'то зробив йому велику комору, а туди давали колись жертву хлі́бну, ла́дан, і по́суд, і десятину збіжжя, молоде вино та оливу, призначені за́повіддю для Левитів, і співаків, і придве́рних, і священичі прине́сення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 6, 'А за ввесь цей час не був я в Єрусалимі, бо в тридцять другому році Артаксе́ркса, царя вавилонського, я прийшов був до царя, та по певному ча́сі ви́просився я від царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 7, 'І прийшов я до Єрусалиму, і розглянувся в тому злі, що зробив Єл\'яшів Товійї, ро́блячи йому комору на подві́р\'ях Божого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 8, 'І було мені дуже зле, й я всі домашні Товійїні речі повикида́в геть із комори.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 9, 'І я сказав, і очи́стили комори, а я вернув туди по́суд Божого дому, хлі́бну жертву та ла́дан.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 10, 'І дові́дався я, що левитські ча́стки не давалися, а вони повтікали кожен на поле своє, ті Левити та співаки́, що робили свою працю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 11, 'І докоряв я заступникам та й сказав: „Чого опу́щений дім Божий?“І зібрав я їх, і поставив їх на їхніх місця́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 12, 'І вся Юдея прино́сила десятину збіжжя, і молодого вина, і оливи до скарбни́ць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 13, 'І настанови́в я над скарбни́цями священика Шелемію й книжника Садока та Педаю з Левитів, а на їхню руку — Ханана, сина Заккура, сина Маттаніїного, бо вони були уважа́ні за вірних. І на них покладено — діли́ти частки для їхніх братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 14, 'Пам\'ятай же мене, Боже, за це, і не зітри́ моїх добродійств, які я зробив у Божому домі та в сторо́жах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 15, 'Тими днями бачив я в Юдеї таких, що топта́ли в суботу чави́ла, і носи́ли снопи́, і нав\'ю́чували на ослів вино, виноград, і фіґі, і всілякий тяга́р, і ве́зли до Єрусалиму суботнього дня. І я при свідках остеріг їх того дня, коли вони продавали живність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 16, 'А тиряни ме́шкали в ньому, і постача́ли рибу й усе на про́даж, і продавали в суботу Юдиним синам та в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 17, 'I докоряв я Юдиним шляхе́тним та й сказав їм: „Що́ це за річ, яку ви робите, і безчестите суботній день?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 18, 'Чи ж не так робили ваші батьки, а наш Бог спровадив усе це зло на нас та на це місто? А ви побі́льшуєте жар гніву на Ізраїля зневажа́нням суботи“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 19, 'І бувало, як падала вечерова тінь на єрусалимські брами перед суботою, то я наказував, — і були зами́кувані брами. І звелів я, щоб не відчиняли їх, а тільки аж по суботі. А біля брам я поставив слуг своїх, — щоб тяга́р не входив суботнього дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 20, 'І ночували крамарі́ та продавці всього продажного раз і два поза Єрусалимом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 21, 'І остеріг я їх при свідках та й сказав їм: „Чого ви ночуєте навпроти муру? Якщо ви повто́рите це, я простягну́ руку на вас!“Від того ча́су вони не прихо́дили в суботу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 22, 'І сказав я Левитам, щоб вони очи́стилися й прихо́дили стерегти брами, щоб освятити суботній день. Також це запам\'ятай мені, Боже мій, і змилуйся надо мною за великістю милости Твоєї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 23, 'Тими днями бачив я також юдеїв, що брали собі за жіно́к ашдо́дянок, аммоні́тянок, моаві́тянок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 24, 'А їхні сини говорили наполовину по-ашдо́дському, і не вміли говорити по-юдейському, а говорили мовою того чи того наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 25, 'І докоряв я їм, і проклинав їх, і бив декого з них, і рвав їм волосся, і заприсягав їх Богом, ка́жучи: „Не давайте ваших дочо́к їхнім синам, і не беріть їхніх дочо́к для ваших синів та для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 26, 'Чи ж не цим згрішив був Соломон, Ізраїлів цар, — а між багатьма́ наро́дами не було такого царя, як він, і був уподо́баний Богові своєму, і Бог настанови́в його царем над усім Ізраїлем, — і його ввели́ в гріх ті чужі жінки́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 27, 'І тому́ чи ж чуте було́ таке, щоб чинити все це велике лихо на спроневі́рення проти нашого Бога, щоб брати чужих жіно́к?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 28, 'А один із синів Йояди, сина Ел\'яшіва, великого священика, був зятем хоронянина Санваллата, — і я вигнав його від себе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 29, 'Запам\'ята́й же їм, Боже мій, за спля́млення свяще́нства та заповіту свяще́ничого та леви́тського!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 30, 'І очистив я їх від усього чужого, і встановив че́рги для священиків та для Левитів, кожного в службі їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 31, 'і для пожертви дров в озна́чених часа́х, і для первопло́дів. Запам\'ятай же мене, Боже мій, на добро́!“');
