INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'І сталося за днів Ахашверо́ша, це той Ахашверо́ш, що царював від Індії аж до Етіопії, сто й двадцять і сім окру́г, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'за тих днів, коли цар Ахашверош засів на троні свого царства, на замку Су́зи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Третього року свого царюва́ння справив він гости́ну для всіх своїх князі́в та для своїх слуг ві́йська перського та мідійського, старши́х та прави́телів округ,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'показуючи ба́гатство слави царства свого й пишну славу своєї вели́чности довгі дні, сто й вісімдесят день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'А по скінченні цих днів справив цар для всього наро́ду, що знахо́дився в за́мку Су́зи, від великого й аж до мало́го, гости́ну на сім день на садко́вому подві́р\'ї царсько́го пала́цу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Біла, зелена та блаки́тна ткани́на, три́мана віссо́новими та пурпу́ровими шну́рами, ви́сіла на срібних стовпця́х та мармуро́вих коло́нах. Золоті та срібні ло́жа стояли на підлозі з пли́ток з зеленого, білого, жовтого й чорного ма́рмуру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'А напо́ї подавали в золотому по́суді, в посуді все різному, і царсько́го вина було ве́льми щедро, за великою спромо́жністю царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'А пиття було за встановленим порядком, — ніхто не приму́шував, бо цар так установи́в усім значни́м свого дому, щоб чинили за вподо́бою кожного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Також цариця Ва́шті спра́вила гости́ну для жіно́к в царсько́му домі царя Ахашверо́ша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Сьо́мого дня, коли цареві стало ве́село на серці від вина, він сказав Мегуманові, Біззеті, Харвоні, Біґті, і Аваґті, Зетарові та Каркасові, сімо́м е́внухам, які служили перед обличчям царя Ахашвероша,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'приве́сти царицю Вашті перед цареве обличчя в короні царські́й, щоб показати наро́дам та зверхникам її красу́, бо була вона вродли́вого ви́гляду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Та цариця Ва́шті відмо́вилася прийти за царськи́м словом, що було передане їй через е́внухів. І сильно загні́вався цар, і в ньому горіла його лю́тість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'І сказав цар до мудреців, що знають часи́ (бо так царська́ справа йшла перед усіма́, що знали зако́на та право,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'а близьки́ми до нього були: Каршена, Шетар, Адмата, Паршіш, Мерес, Марсена, Мемухан, сім князів перськи́х та мідійських, які бачать царе́ве обличчя й сидять перші в царстві):');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, '„Як велить зако́н, щоб зробити з царицею Вашті за те, що не виконала сло́ва царя Ахашвероша, переданого їй через євнухів?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'І сказав Мемухан перед царем та князя́ми: „Не перед сами́м царе́м провини́лася цариця Вашті, але й перед усіма́ князя́ми та перед усіма́ народами, що по всіх окру́гах царя Ахашвероша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Бо цари́цин учи́нок ді́йде до всіх жіно́к, і спричи́ниться до пого́рдження їхніх чолові́ків в їхніх оча́х, бо бу́дуть говорити: Цар Ахашверо́ш сказав був приве́сти царицю перед обличчя своє, та вона не прийшла́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'І цього дня казатимуть те саме княгині перські та мідійські, що почують про цари́цин учи́нок, до всіх царськи́х князі́в, — і бу́де багато пого́рди та гніву!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Якщо цареві це добре, нехай ви́йде царськи́й нака́з від нього й нехай буде записане в зако́нах Персії та Мідії, і нехай не поминеться, щоб Вашті більш не прихо́дила перед обличчя царя Ахашвероша, а її царюва́ння цар дасть іншій, ліпшій від неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'А коли почується царськи́й нака́з, який цар зробить відо́мим у всім своїм царстві, хоч яке велике воно, то всі жінки́ віддадуть честь своїм чоловікам, від великого й аж до мало́го“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'І була приємна ця рада в оча́х царя та князі́в, і цар зробив за Мемухановим словом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'І порозсила́в він листи до всіх царськи́х окру́г, до кожної округи — письмо́м її, і до кожного наро́ду — мовою його́, щоб кожен чоловік був па́ном у домі своєму, і говорив про це мовою свого наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'По цих подіях, коли затихла лютість царя Ахашверо́ша, згадав він про Ва́шті, і що́ вона зробила, і що́ було заря́джене про неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'І сказали царські о́троки, його слу́ги: „Нехай пошукають для царя дівчат, уродли́вих на ви́гляд панні́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'і нехай цар призна́чить уря́дників по всіх окру́гах свого царства, і нехай вони зберуть усіх дівчат, панні́в уродли́вого ви́гляду, до за́мку Сузи, до дому жіно́к під руку Геґа́я, царсько́го є́внуха, сто́рожа жіно́к, і дати їм потрібне для їхнього причепу́рення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'А та ді́вчина, що бу́де найкраща в царськи́х оча́х, буде царювати замість Ва́шті“. І була приємна ця рада у царе́вих оча́х, — і він зробив так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'А в замку Су́зи був один юде́янин, а ім\'я́ йому Мордеха́й, син Яіра, сина Шім\'ї, сина Кішового, муж Веніями́нівець,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'що був узятий з Єрусалиму з тим поло́ном, який був узятий ра́зом з Єхонією, царем Юдиним, якого взяв був Навуходоно́сор, цар вавило́нський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'І він вихо́вував Гадассу, вона ж Есте́р, дочку́ свого дя́дька, бо не мала вона ні батька, ні матері. А ця ді́вчина була хорошої поста́ви та вродли́вого ви́гляду, а коли помер її ба́тько та мати її, Мордеха́й узяв її собі за дочку́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'І сталося, коли був оголо́шений царськи́й нака́з та зако́н його́, і коли збирали багато дівча́т до за́мку Су́зи під руку Геґая, то взята була́ й Есте́р до царсько́го дому під руку Геґая, сто́рожа жіно́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'І була́ та ді́вчина хороша в його оча́х, і мала ласку перед ним, і він приспіши́в видати їй потрібне для її причепу́рення й її ча́стки, та дати їй сімо́х відповідних дівча́т із царсько́го дому. І він перемістив її та дівча́т її до найкращого місця в домі жіно́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Есте́р не ви́явила ні про наро́д свій, ні про місце свого наро́дження, бо Мордеха́й наказа́в їй, щоб цього вона не виявля́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'А кожного дня Мордеха́й ходив до подві́р\'я дому жіно́к, щоб дові́датись, як мається Есте́р та що́ вона робить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'А коли прихо́дила черга́ для кожної ді́вчини вхо́дити до царя Ахашверо́ша, коли кінча́лися дванадцять місяців устано́вленого поря́дку для жіно́к, — бо так виповня́лися дні їхнього причепу́рювання: шість місяців — мирровою оливою, а шість місяців па́хощами та іншим потрібним для причепурювання жіно́к, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'то з тим ді́вчина прихо́дила до царя́: давалося їй усе, що вона скаже, щоб воно йшло з нею з дому жіно́к до дому царсько́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Ввечорі вона прихо́дила, а ра́нком вона верта́лася до другого дому жіно́к під руку Шаазґаза, царсько́го е́внуха, сто́рожа нало́жниць. Вона вже не вхо́дила до царя, хіба б що цар пожадав її, і вона була покли́кана за ім\'я́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'А коли настала черга́ для Есте́ри, — дочки́ Авіхая, Мордеха́євого дядька, що взяв її собі за дочку́, — щоб іти до царя, вона нічого не жада́ла, як тільки того, що казав Геґай, царськи́й е́внух, сторож жінок. І Естер мала ласку в очах усіх, хто її бачив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'І була́ взя́та Есте́р до царя Ахашвероша, до царсько́го дому його, десятого місяця, він місяць тевет, сьомого року царюва́ння його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'І цар покоха́в Естер понад усіх жіно́к, і вона мала прихи́льність та ласку перед його обличчям понад усіх дівча́т, — і він поклав царську́ корону на її го́лову, і зробив її цари́цею замість Ва́шті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'І спра́вив цар велику гости́ну для всіх своїх князі́в та своїх слуг, гостину для Есте́ри, і зробив поле́гшення для окру́г, і дав дару́нка за царсько́ю спроможністю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'А коли збирали дівчат другий раз, то Мордеха́й сидів при царські́й брамі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Есте́р же не виявляла місця свого наро́дження та народу свого, як наказав був їй Мордеха́й, бо Есте́р вико́нувала Мордехаєве слово так, як коли була́ в нього на ви́хованні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Тими днями, коли Мордеха́й сидів у царські́й брамі, розгнівалися Біґтан та Тереш, два царські́ е́внухи зо сторожі́в поро́гів, — і заду́мували простягну́ти руку на царя Ахашверо́ша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'І стала відо́ма ця річ Мордехаєві, і він доніс про це цариці Есте́р, а Есте́р переказала цареві в імені Мордехая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 23, 'І була́ розві́дана ця справа, і зна́йдено так, і ті обоє були́ пові́шені на ши́бениці. І було записане це в хро́ніці перед обличчям царськи́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'По цих подіях цар Ахашверо́ш звеличив Га́мана, сина Гаммедатового, аґаґ\'янина, і пови́щив його, і поставив його крісло понад усіх князі́в, що були з ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'А всі цареві раби, що були в царські́й брамі, падали на коліна та вклонялися Га́манові, бо так про нього наказав цар. А Мордеха́й не падав на коліна й не вклоня́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'І сказали царські́ раби, що були в царські́й брамі, до Мордеха́я: „Чого ти переступа́єш царе́вого нака́за?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'І сталося, як вони говорили до нього день-у-день, а він не слу́хався їх, то вони доне́сли Га́манові, щоб побачити, чи втри́мається Мордеха́й у своїм слові, бо він виявив їм, що він юде́янин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'І побачив Га́ман, що Мордеха́й не падає на коліна й не вклоняється йому́, — і Га́ман перепо́внився лю́тістю...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'І пого́рджував він у своїх оча́х простягну́ти руку свою не тільки на Мордехая, самого його, бо доне́сли йому про Мордеха́їв наро́д, і Га́ман шукав випадку ви́губити всіх юде́ян, що були в усьому Ахашверо́шевому царстві, наро́д Мордеха́їв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Першого місяця, він місяць нісан, дванадцятого року царя Ахашверо́ша, ки́дано пу́ра, цебто жеребка́, перед Га́маном із дня на день та з місяця на місяць, і жереб упав на дванадцятий місяць, він місяць адар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'І сказав Га́ман до царя Ахашверо́ша: „Є один наро́д, розпоро́шений та поді́лений між наро́дами в усіх окру́гах твого царства, а зако́ни їх рі́зняться від зако́нів усіх наро́дів і зако́нів царськи́х вони не вико́нують, — і цареві не варто позоставля́ти їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Якщо це цареві вгодне, нехай бу́де написано ви́губити їх, а я відва́жу десять тисяч талантів срібла на руки робітникі́в, щоб уне́сли до царськи́х скарбни́ць“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'І зняв цар пе́рсня свого́ зо своєї руки, і дав його Га́манові, синові Гаммедатовому, аґаґ\'янинові, нена́висникові юде́їв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'І сказав цар до Га́мана: „Це срібло віддаю́ тобі, і дається тобі й той наро́д, щоб робити з ним, як угодно в оча́х твоїх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'І були́ покликані царські́ писарі́ першого місяця тринадцятого дня в ньому, і було написано все так, як наказав Га́ман до царськи́х сатра́пів та до намі́сників, що були над кожною окру́гою, і до князі́в кожного наро́ду, до кожної окру́ги письмо́м його, і до кожного наро́ду мовою його; в імені царя Ахашвероша було написано, і припеча́тано було́ царськи́м пе́рснем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'І були́ послані листи через гінці́в до всіх царськи́х окру́г, щоб були повигу́блювані, побиті та понищені всі юдеї від хлопця й аж до старо́го, діти та жінки́ одного тринадцятого дня місяця дванадцятого, він місяць адар, а здо́бич по них пограбува́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Ві́дпис із цього листа щоб був виданий як зако́н, у кожній окру́зі, і оголо́шений для всіх наро́дів, щоб були́ готові на цей день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Гінці́ вийшли, пі́гнані царе́вим словом. А зако́н був ви́даний в за́мку Су́зи. А цар та Га́ман сіли до пиття́, а місто Сузи було в замі́шанні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'А Мордеха́й дові́дався про все, що було зро́блено. І розде́р Мордехай одежу свою, і зодягнув вере́тище та посипався по́пелом, і вийшов на сере́дину міста, та й кричав криком сильним та гірки́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'І прийшов він аж під царську́ браму, бо не можна було вхо́дити в царську́ браму в вере́тищному убранні́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'А в кожній окру́зі та місці, куди дохо́дило слово царя та його зако́н, були для юдеїв велика жало́ба, і піст, і плач, і голосі́ння, а вере́тище та по́пел були́ ло́жем для багатьох...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'І прийшли дівчата Есте́рині й е́внухи її, та й доне́сли їй про це. І дуже затремті́ла цариця, і послала одежу зодягнути Мордеха́я та зняти з нього його вере́тище, та він не прийня́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'І покликала Есте́р Гатаха, одного з е́внухів царя, якого він приста́вив до неї, і наказала йому дові́датися про Мордехая, що́ то з ним, і чого то жало́ба?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'I вийшов Гатах на міську́ пло́щу, що перед царсько́ю брамою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'І виявив йому Мордеха́й усе, що спіткало його, і про суму срібла, яку Га́ман сказав відва́жити до царсько́ї скарбни́ці за юдеїв, щоб ви́губити їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'І він дав йому відписа листа зако́ну, що був ви́даний у Су́зах на ви́гублення їх, щоб показав Есте́рі, та щоб доніс їй, і щоб наказа́в їй піти до царя блага́ти його та просити перед його обличчям за її наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'І прийшов Гатах, і доніс Есте́рі Мордехаєві слова́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'I сказала Есте́р до Гатаха, і наказала йому переказати Мордехаєві:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, '„Усі царські́ раби та народ царськи́х окру́г знають, що кожен чоловік та жінка, що при́йде до царя до вну́трішнього подві́р\'я непокликаний, один йому зако́н, — убити його, окрім того, кому цар простягне́ золоте бе́рло, — і буде він жити. А мене не кличуть вхо́дити до царя от уже тридцять день“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'І переказали Мордехаєві Есте́рині слова́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'І сказав Мордехай відпові́сти Естері: „Не ду́май в душі своїй, що втечеш до царсько́го дому одна з усіх юдеїв...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Бо якщо справді бу́деш ти мовча́ти цього ча́су, то поле́гшення та врятува́ння при́йде для юдеїв з іншого місця, а ти та дім твого батька погинете. А хто знає, чи не на час, як оцей, досягла́ ти царства!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'І сказала Есте́р відпові́сти Мордехаєві:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, '„Іди, збери всіх юдеїв, що знахо́дяться в Су́зах, і по́стіть за мене, і не їжте й не пийте три дні, ніч та день. Також я та дівча́та мої бу́демо по́стити так, і так прийду́ до царя, хоч це не буде за зако́ном. А якщо я загину, то загину“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'І пішов Мордеха́й, і зробив усе, як звеліла йому Есте́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'І сталося третього дня, і вбрала Естер царські́ шати, та й стала на вну́трішньому подві́р\'ї царсько́го дому, навпроти царсько́го дому. А цар сидів на тро́ні свого ца́рства в царсько́му домі навпроти входу до дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'І сталося, як цар побачив царицю Есте́р, що стоїть у брамі, то знайшла́ вона ласку в оча́х його. І цар простягну́в Естері золоте бе́рло, що в руці його, а Есте́р підійшла й доторкнулася до кінця бе́рла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'І сказав до неї цар: „Що́ тобі, царице Есте́р? І яке проха́ння твоє? Якщо побажаєш аж до половини царства, то бу́де да́не тобі́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'А Есте́р відказала: „Якщо це цареві вгодне, нехай при́йде цар та Га́ман сьогодні на гости́ну, яку я вчиню йому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'I сказав цар: „Скоріше покличте Га́мана, щоб виконати Есте́рині слова́!“І прийшов цар та Га́ман у гости́ну, що вчинила Есте́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'І сказав цар до Есте́ри при питті вина: „Яке жада́ння твоє? І буде тобі да́не. І яке проха́ння твоє? Якщо побажаєш аж до полови́ни царства, то буде зро́блене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'І відповіла́ Есте́р та й сказала: „Моє жада́ння та моє проха́ння таке:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Якщо знайшла́ я ласку в царевих оча́х, і якщо це цареві вгодне, щоб вво́лити жада́ння моє й щоб ви́конати проха́ння моє, — нехай при́йде цар та Га́ман на гости́ну, що зроблю́ їм, і взавтра я зроблю́ за царевим словом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'І вийшов Га́ман того дня радісний та добросе́рдий. Та коли Гаман побачив Мордехая в царські́й брамі, і він не встав і не затремтів перед ним, то Га́ман перепо́внився лютістю на Мордехая.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Та стримався Гаман, і прийшов до свого дому. І послав він покли́кати своїх при́ятелів та жінку свою Зереш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'І розповів їм Гаман про славу свого багатства, та про числе́нність синів своїх, та про все, як звеличив його цар, і як підняв його понад князі́в та слуг царе́вих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'І сказав Гаман: „А цариця Естер не привела́ з царем на гости́ну, яку зробила, нікого, крім ме́не. І також наза́втра я покли́каний до неї з царем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Та все це нічого не варте мені цього ча́су, доки я бачу того юдея Мордехая, що сидить у царські́й брамі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'І сказала до нього жінка його Зе́реш та всі його при́ятелі: „Нехай приготують ши́беницю, високу на п\'ятдеся́т ліктів, а ра́нком скажи царе́ві, і нехай повісять на ній Мордехая, і пі́деш з царем радісний на гостину“! І була приємна та рада для Гамана, і́ зробив він ту ши́беницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Тієї ночі втік був сон від царя, і він сказав прине́сти Книгу пам\'яток, Хроніки, — і вони читалися перед обличчям царськи́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'І зна́йдене було́ написане, що Мордехай доніс на Біґдана та Тереша, двох царськи́х е́внухів, зо сторо́жів поро́га, що заду́мували були простягнути руку на царя́ Ахашверо́ша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'І сказав цар: „Яка честь та гі́дність зро́блена Мордеха́єві за це?“І сказали ца́реві о́троки, що прислуго́вували йому: „Нічо́го йому́ не зро́блено“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'І спита́в цар: „Хто́ на подві́р\'ї?“А Га́ман прийшов на зо́внішнє подві́р\'я царсько́го дому, щоб сказати цареві пові́сити Мордехая на тій ши́бениці, яку пригото́вив для нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'І сказали о́троки царя до нього: „Ось Га́ман стоїть на подві́р\'ї“. І сказав цар: „Нехай уві́йде!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'І Гаман увійшов, а цар йому сказав: „Що́ зробити з чоловіком, якому цар хоче чести?“І подумав Гаман у серці своїм: „Кому ж цар зажадає вчинити честь більше, як мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'І відповів Гаман царе́ві: „Тому чоловікові, якому цар жадає чести,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'нехай принесу́ть цареву одежу, яку цар зодягав, та коня, що цар їздив на ньому, і щоб була да́на царська́ корона на його го́лову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'І дати цю одежу та цього коня на руку котро́гось із старших князі́в царе́вих. І нехай зодя́гнуть того чоловіка, якому цар жадає чести, і нехай во́зять його на коні на міські́й площі, і нехай кличуть перед ним: „Так ро́биться му́жеві, якому цар жадає чести!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'І сказав цар до Гамана: „Поспіши, візьми́ одежу та коня, як казав ти, і зроби так юдеєві Мордеха́єві, що сидить у царській брамі. Не пропусти нічого зо всього, що́ ти говорив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'І взяв Гаман одежу та коня, і зодягнув Мордехая, і возив його на міські́й площі, і кричав перед ним: „Так ро́биться му́жеві, якому цар жадає чести!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'I вернувся Мордеха́й до царсько́ї брами, а Га́ман поспішив до дому свого сумни́й та закривши го́лову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'І розповів Гаман жінці своїй Зереші та всім при́ятелям своїм усе, що спіткало його. І сказали йому мудреці його та жінка його Зе́реш: „Якщо з юдейського насіння Мордехай, перед яким зачав ти падати, то не переможеш його, бо дійсно впаде́ш перед ним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Ще вони говорили з ним, а е́внухи царські́ прибули́ й поспішили відве́сти Гамана на гости́ну, яку зробила Есте́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'І прийшов цар та Га́ман на гостину цариці Есте́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'І сказав цар до Есте́ри також другого дня при питті вина: „Яке жада́ння твоє? І буде тобі да́не. І яке проха́ння твоє? Якщо побажаєш аж до половини царства, то бу́де зро́блено!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'І відповіла́ цариця Есте́р та й сказала: „Якщо знайшла́ я ласку в оча́х твоїх, о ца́рю, і якщо це царе́ві вгодне, нехай бу́де да́не мені життя моє на жада́ння моє, а наро́д мій — на проха́ння моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Бо про́дані ми, я та наро́д мій, на ви́гублення, на забі́й та на поги́біль... Та коли б ми були про́дані на рабів та на невільниць, мовчала б я, бо цей у́тиск був би не вартий царе́вого занепоко́єння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Тоді сказав цар Ахашверо́ш, і повів до цариці Есте́ри: „Хто́ то він, і де то́й, що його серце напо́внило його відвагою чинити так?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'І сказала Есте́р: „Нена́висник та ворог — це злий Гаман!“І Гаман перелякався перед обличчям царя та цариці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'А цар у своїй лютості устав від гости́ни, і вийшов до палацового са́ду. А Га́ман став просити царицю Естер за життя своє, бо побачив, що загрожує йому лихо від царя...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'І цар вернувся з палацового са́ду до дому пиття́ вина, а Гаман припав до ліжка, що на ньому була Есте́р. І цар сказав: „Чи хочеш також збезче́стити царицю в мене в домі?“Як тільки це слово вийшло з царевих уст, то закрили Гаманове обличчя...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'І сказав Харвона, один з е́внухів перед царевим обличчям: „Та ось ши́бениця, яку зробив Га́ман для Мордехая, що говорив добре на царя, яка стоїть у Гамановому домі, висока на п\'ятдеся́т ліктів“. І сказав цар: „Пові́сьте його на ній!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'І пові́сили Га́мана на ши́бениці, яку він пригото́вив був для Мордехая, а лютість царе́ва втихла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Того дня цар Ахашверо́ш віддав цариці Есте́рі дім Га́мана, нена́висника юдеїв, а Мордеха́й став перед цареве обличчя, бо Есте́р виявила, хто́ він для неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'І зняв цар свого пе́рсня, що забрав від Га́мана, та й дав його Мордеха́єві, а Есте́р настановила Мордехая над Гамановим домом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'І Есте́р далі говорила перед обличчям царя. І впала вона перед його ногами, і плакала та блага́ла його відвернути лихо аґаґ\'янина Гамана та за́думи його, які заду́мував був на юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'І простягнув цар до Есте́ри золоте бе́рло, а Есте́р устала й стала перед царе́вим обличчям,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'та й сказала: „Якщо це цареві вго́дне, й якщо знайшла́ я ласку перед обличчям його, і вгодна ця річ перед царевим обличчям та вгодна я в оча́х його, нехай буде написано, щоб були́ пове́рнені ті листи́ за́думів аґаґ\'янина Гамана, Гаммедатового сина, що написав був повигу́блювати юдеїв, які є в царевих окру́гах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Бо як я могла б дивитися на лихо, що спітка́є наро́д мій, і як я могла б дивитися на заги́біль ро́ду свого́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'І сказав цар Ахашверо́ш до цариці Есте́ри та до юде́янина Мордеха́я: „Ось я дав Есте́рі дім Гамана, а його повісили на ши́бениці за те, що простя́г був руку свою на юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'А ви пишіть до юдеїв, як добре в ваших оча́х, в імені царя́, і припеча́тайте царськи́м пе́рснем, бо листа́, що був написаний в імені царя та був припеча́таний царськи́м пе́рснем, не можна відмінити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'І були покли́кані царські́ писарі́ того ча́су, місяця третього, — він місяць сіван, двадцять і третього дня в ньому, і було написане все, як наказав був Мордеха́й, до юдеїв, і до сатра́пів, і намісників, і зверхників округ, що від Году й аж до Кушу, — сто й двадцять і сім окру́г, і до кожної окру́ги письмо́м її, і до кожного народу мовою його, та до юдеїв їхнім письмо́м та їхньою мовою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'І понапи́сував він листи́ в імені царя Ахашвероша, і поприпеча́тував пе́рснем царськи́м, і послав через гінці́в на ко́нях, які їздять на держа́вних ко́нях, ко́нях баски́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'що цар дав право юдеям, які живуть у кожному місті, зібратися й стати за своє життя, ви́губити, забити та погубити всяке ві́йсько наро́ду та окру́ги, що нена́видять їх, дітей та жінок, а здо́бич по них — розграбува́ти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'одно́го дня по всіх окру́гах царя Ахашвероша, — тринадцятого дня дванадцятого місяця, — він місяць ада́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Відпис цього листа́ щоб був ви́даний, як зако́н, у кожній окрузі, по́сланий був відкри́тий для всіх наро́дів, і щоб юдеї були гото́ві на той день помсти́тися на своїх ворогах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Гінці́, що поїхали ве́рхи на швидки́х конях, вийшли, приспі́шені та пі́гнані царськи́м словом. А цей нака́з був да́ний у за́мку Су́зи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'А Мордехай вийшов з-перед царе́вого обличчя в царські́й одежі, блакитній та білій, а на ньому велика золота корона та віссо́нний і пурпу́ровий заві́й. І місто Су́зи раділо та тішилося!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Юдеям було тоді світло, і радість, і веселість, і честь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'І в кожній окру́зі та в кожному місті, куди досяга́є слово царя та зако́н його, була́ юдеям радість та веселість, бе́нкет та свято! І багато-хто з наро́дів кра́ю стали юде́ями, бо на них напав страх перед юде́ями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'А дванадцятого місяця, — він місяць ада́р, — тринадцятого дня в ньому, коли нака́з царя та зако́н його мали бути ви́конані, дня, коли вороги́ юдеїв сподівалися запанува́ти над ними, поверну́лося те так, що вони, юдеї, запанува́ли над нена́висниками своїми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'зібра́лися юдеї в своїх міста́х по всіх окру́гах царя Ахашвероша, щоб простягну́ти руку на тих, що заду́мували їм лихо, та ніхто́ не став перед ними, бо страх перед ними напав на всі наро́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'А всі зверхники округ, і сатрапи, і намісники, і викона́вці царсько́ї праці підтри́мували юдеїв, бо напав на них страх перед Мордехаєм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Бо Мордеха́й став великим у царсько́му домі, а вістка про нього покоти́лась по всіх окру́гах, бо той чоловік, Мордехай, усе ріс.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'І били юдеї всіх своїх ворогі́в, побива́ючи мече́м, і забиваючи та вигу́блюючи їх, і робили з своїми ворогами за своєю волею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'А в за́мку Су́зи юдеї позабивали та повигу́блювали п\'ять сотень чоловіка,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'і Паршандату, і Далфона, і Аспату,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'і Пората, і Адалію, і Арідата,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'і Пармашту, і Арісая, і Арідая, і Вайзата,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'десятьо́х синів Га́мана, Гаммедатового сина, нена́висника юдеїв, забили, а на грабу́нок не простягли своєї руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Того дня число забитих у за́мку Су́зи прийшло перед цареве обличчя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'І сказав цар до цариці Есте́ри: „У за́мку Су́зи юдеї позабива́ли та повигу́блювали п\'ять сотень чоловіка та десятьох Гаманових синів. Що вони зробили в решті царевих окру́г? І яке жада́ння твоє? І бу́де тобі вво́лене. І яке ще проха́ння твоє? І бу́де зро́блене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'І відповіла Есте́р: „Якщо це цареві вгодне, нехай бу́де да́не юдеям, що в Су́зах, також узавтра вчинити за зако́ном цього дня, а десятьох Гаманових синів нехай повісять на ши́бениці“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'І сказав цар, щоб було зро́блено так, — і був да́ний зако́н у Сузах, а десятоьх Га́манових синів повісили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'І зібра́лися юдеї, що в Су́зах, також чотирна́дцятого дня місяця ада́р, і ви́били в Су́зах три сотні чоловіка, а на грабу́нок не простигли своєї руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'А решта юдеїв, що жили по царськи́х окру́гах, зібралися та й стали до бо́ю за своє життя, і відпочи́ли від ворогів своїх. І позабива́ли вони між своїми нена́висниками сімдеся́т і п\'ять тисяч, а на грабу́нок не простягли́ своєї руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Це було трина́дцятого дня місяця адара, а чотирна́дцятого в ньому настав мир, — і зробили його днем гости́ни та радости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'А юдеї, що в Су́зах, збиралися тринадцятого дня в ньому та чотирна́дцятого в ньому, а мир мали п\'ятнадцятого дня в ньому, — і зробили його днем гости́ни та радости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 19, 'Тому́ то юдеї неогоро́джених селищ, що сидять по неогоро́джених містах, роблять чотирна́дцятий день місяця адара днем радости й гостини та свята, та днем посила́ння дару́нків один о́дному.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 20, 'А Мордехай описав ці події, і порозсилав листи́ до всіх юдеїв, що по всіх окру́гах царя Ахашвероша, до близьки́х та далеких,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 21, 'щоб вони постанови́ли святкува́ти чотирна́дцятий день місяця ада́ра та п\'ятнадцятий день у ньому кожного року,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 22, 'як ті дні, коли юдеї відпочи́ли від ворогів своїх, і як той місяць, коли їм сум оберну́вся на радість, жало́ба — на свято, щоб зробити їх днями гости́ни та радости, і посила́ння дару́нків один о́дному та дару́нків убогим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 23, 'І прийняли́ юдеї це, що зачали́ робити, і про що́ написав їм Мордеха́й,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 24, 'що аґаґ\'янин Га́ман, син Гаммедатів, нена́висник усіх юдеїв, замишля́в був на юдеїв, щоб ви́губити їх, і кидав пу́ра, цебто жеребка́, на збенте́ження їх та на згубу їхню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 25, 'Та коли прийшла вона, Естер, перед обличчя, царя́ він наказав листом: „Нехай обе́рнеться його злий за́дум, якого він заду́мав був на юдеїв, на його го́лову!“І повісили його та синів його на ши́бениці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 26, 'Тому́ то й назвали ці дні: Пурі́м, від імени „пур“. Тому то згідно зо всіма́ словами цього листа, і що вони бачили про це й що тра́пилося з ними,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 27, 'юдеї постанови́ли й прийняли́ на себе й на наща́дків своїх, та на всіх, хто поєдна́ється з ними, і не відсту́плять, але́ щоб святкува́ти два ті дні кожного року згідно з напи́саним про них та згідно з їхнім ча́сом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 28, 'А дні ці мають спомина́тися та святкува́тися в кожному поколінні, у кожному ро́ді, у кожній окру́зі, у кожному місті. А ці дні, Пурі́м, не минуться між юде́ями, а пам\'ять про них не скінчи́ться з їхнього насіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 29, 'І написала цариця Есте́р, дочка Авіхаїлова, та юдеянин Мордехай з сильним домага́нням другий раз про те, щоб вико́нувати цього листа́ про Пурім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 30, 'І порозсила́в він листи́ до всіх юдеїв, до ста й двадцяти́ й семи окру́г Ахашверо́шового ца́рства, зо словами миру та правди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 31, 'щоб вони вико́нували ті дні Пурім у їх озна́чених часа́х, як постанови́в про них юде́янин Мордеха́й та цариця Есте́р, і як вони самі постанови́ли на себе та на наща́дків своїх при́писи пості́в та їхнього голосі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 32, 'А Есте́рин нака́з стве́рдив ці при́писи про Пурі́м, і було́ це запи́сане в книгу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 33, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 34, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'І наклав цар Ахашверо́ш дани́ну на землю та на морські острови́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'А ввесь чин його сили та його лица́рских діл, і вира́зний о́пис вели́чности Мордеха́я, що звели́чив його цар, — ось вони опи́сані в Книзі Хронік царів мідійських та перських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Бо юде́янин Мордеха́й був другий по царі Ахашверо́ші, і великий для юдеїв, і милий для багатьох братів своїх, який шукав добра для наро́ду свого й говорив „мир!“для всіх наща́дків своїх.');
