INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Блажен муж, що за радою несправедливих не ходить, і не стоїть на дорозі грішних, і не сидить на сиді́нні злорі́ків,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'та в Зако́ні Господнім його насоло́да, і про Зако́н Його вдень та вночі він роздумує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'І він буде, як дерево, над во́дним потоком поса́джене, що ро́дить свій плід своєдчасно, і що листя не в\'яне його, — і все́, що він чинить, — щасти́ться йому́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Не так ті безбожні, — вони як полова, що вітер її розвіває!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Ось тому́ то не всто́ять безбожні на су́ді, ані грішники у зборі праведних, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'дорогу бо праведних знає Госпо́дь, а дорога безбожних загине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Чого то племе́на бунтують, а наро́ди задумують ма́рне?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Зе́мні царі повстають, і князі нара́джуються ра́зом на Господа та на Його Помаза́нця:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, '„Позриваймо ми їхні кайда́ни, і поскидаймо із себе їхні пу́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Але Той, Хто на небеса́х пробува́є — посміється, Владика їх висміє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Він тоді в Своїм гніві промовить до них, і настра́шить їх Він у Своїм пересе́рді:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, '„Я ж помазав Свого Царя на Сіон, святу го́ру Свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Я хочу звістити постанову: Промовив до Мене Господь: Ти Мій Син, Я сьогодні Тебе породив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Жадай Ти від Мене, — і дам Я наро́ди Тобі, як спадщину Твою, володі́ння ж Твоє — аж по кі́нці землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Ти їх повбиваєш залізним жезло́м, потовчеш їх, як по́суд ганча́рський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'А тепер — помудрійте, царі, навчіться ви, су́дді землі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Служіть Господе́ві зо стра́хом, і радійте з тремті́нням!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Шануйте Сина, щоб Він не розгнівався, і щоб вам не загинути в дорозі, бо гнів Його незаба́ром запа́литься. Блаженні усі, хто на Нього наді́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Псалом Давидів, як він утікав був перед Авесало́мом, своїм сином.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Господи, — як багато моїх ворогів, як багато стають проти ме́не!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Багато-хто кажуть про душу мою: „Йому в Бозі спасі́ння нема!“Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Але, Господи, — щит Ти для мене та слава моя, і мою го́лову Ти підійма́єш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Своїм голосом кличу до Господа, — і Він озве́ться зо свято́ї Своєї гори. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Я лягаю і сплю, і пробуджуюся, бо Господь підпирає мене, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'і я не побоюсь десяти тисяч люду, які проти мене навко́ло ота́борились!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Устань же, о Господи! Спаси мене, Боже мій, бо Ти ра́зиш усіх ворогів моїх в що́ку, зуби грішникам кру́шиш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Спасіння від Господа, і над наро́дом Твоїм — Твоє благослове́ння! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Для дириґе́нта хору. На струнних знаря́ддях. Псало́м Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Коли кли́чу, — озвися до мене, Боже правди моєї, Ти про́стір для мене робив у тісноті́ ... Помилуй мене, і почу́й молитву мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Лю́дські сини, — доки слава моя буде га́ньбитись? Доки будете марне любити, шукати неправди? Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'І знайте, що святого для Себе Господь відділив, почує Господь, як я кликати буду до Нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Гнівайтеся, та не грішіть; на ложах своїх розмишляйте у ваших серця́х, та й мовчіть! Села.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Жертви правди прино́сьте, і наді́йтесь на Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Багато-хто кажуть: „Хто нам покаже добро́?“Підійми ж на нас, Господи, світло Свого лиця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Ти даєш більшу радість у серці моїм, ніж у них, як помно́жилося їхнє збіжжя та їхнє вино молоде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'У споко́ї я ляжу, і засну́, бо Ти, Господи, єдиний даєш мені жити безпе́чно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Для дириґента хору. До флейти. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Почуй, Господи, мову мою, стогна́ння моє зрозумій');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Прислу́хайсь до голосу зо́йку мого́, о мій Ца́рю та Боже Ти мій, як до Тебе молитися бу́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Ти слухаєш, Господи, ра́нком мій голос, — ра́нком молитися буду до Тебе та буду чекати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'бо Бог Ти не той, що несправедливости хоче, — зло не буде в Тобі пробува́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Перед очима Твоїми не втримаються гультяї́, всіх злочинців нена́видиш Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Погу́биш Ти неправдомо́вців, кровоже́рну й підступну люди́ну обри́дить Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'А я в ласці великій Твоїй до дому Твого ввійду́, до Храму святого Твого вклонюся в страху́ Твоїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Провадь мене, Господи, в правді Своїй задля моїх ворогів, і ви́рівняй передо мною дорогу Свою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'бо в їхніх уста́х нема пра́вди, нутро їхнє прино́сить нещастя, гріб відкритий — їхнє горло, свій язик вони роблять гладе́ньким!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Признай їх за винних, о Боже, через свої за́міри хай упаду́ть, за їхні великі злочи́нства відкинь їх від Себе, бо вони проти Тебе бунтують!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'А всі, хто наді́ю на Тебе складають, хай ті́шаться, — будуть вічно співати вони, і Ти їх охоро́ниш, і будуть радіти Тобою, хто любить Ім\'я́ Твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Бо Ти, Господи, благословля́тимеш праведного, милістю вкриєш його, як щито́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Для дириґента хору. На струнних знаря́ддях. На октаву. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Не карай мене, Господи, в гніві Своїм, не завдава́й мені кари в Своїм пересе́рді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Помилуй мене, Господи, я ж бо слаби́й, уздоро́в мене, Господи, бо тремтять мої кості,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'і душа моя сильно стривожена, а ти, Господи, доки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Вернися, о Господи, ви́зволи душу мою, ради ласки Своєї спаси Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Бож у смерті нема пам\'ята́ння про Тебе, у шео́лі ж хто буде хвалити Тебе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Зму́чився я від стогна́ння свого́, щоночі постелю свою обмиваю слізьми́, сльозами своїми окроплюю ложе своє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Моє око зів\'я́ло з печалі, поста́ріло через усіх ворогів моїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Відступіться від мене, усі беззако́нники, бо почув Господь голос мого плачу́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Блага́ння моє Господь ви́слухає, молитву мою Господь при́йме, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'усі мої вороги посоро́млені бу́дуть, і будуть настра́шені дуже: хай ве́рнуться, — і будуть вони посоро́млені за́раз!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Жало́бна пісня Давидова, яку він співав Господе́ві в справі веніями́нівця Ку́ша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Господи, Боже мій, — я до Тебе вдаю́ся: спаси Ти мене від усіх моїх напасникі́в, і визволь мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'щоб ворог моєї душі не розша́рпав, як лев, що кості ламає, й ніхто не рятує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Господи, Боже мій, коли я таке учинив, коли є беззаконня в доло́нях моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'коли я доброчи́нцеві злом відплатив, і без причини ограбува́в свого противника, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'во́рог нехай переслідує душу мою, і нехай дожене́, і нехай до землі він потопче життя моє, — і хай мою славу обе́рне на порох! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Устань же, о Господи, в гніві Своїм, понеси́ся на лютість моїх ворогів, і до мене скеру́й постанову Свою, яку Ти заповів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'І громада народів ото́чить Тебе, і над нею верни́ся на висоту́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Господь судить людей, — суди ж мене, Господи, за моєю правото́ю й за моєю неви́нністю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Нехай зло́ба безбожних скінчи́ться, а Ти зміцни праведного, бо виві́дуєш Ти серця й нирки, о праведний Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Щит мій у Бозі, Який чистих серцем спасає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Бог Суддя справедливий, і щоденно на злого Бог гнівається,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'коли хто не наве́рнеться, — буде гострити меча Свого Він, Свого лука натя́гне й наста́вить його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'і йому пригото́вив смертельні знаря́ддя, — Він зробить огнистими стріли Свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Ото, беззако́ння зачне нечестивий, і завагітні́є безправ\'ям, — і породить неправду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Він рова копав, і його викопав, і впав сам до ями, яку пригото́вив, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'обе́рнеться зло його на його голову, і на ма́ківку зі́йде його беззако́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Я ж Господа буду хвали́ти за Його правдою, і буду ви́співувати Ймення Всеви́шнього Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Для дириґента хору. На інструме́нті ґатійськім. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Господи, Владико наш, — яке то величне на ці́лій землі Твоє Йме́ння, — Слава Твоя понад небесами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'З уст дітей й немовля́т учинив Ти хвалу́ ради Своїх ворогів, щоб зни́щити проти́вника й ме́сника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Коли бачу Твої небеса́ — діло пальців Твоїх, місяця й зо́рі, що Ти встанови́в, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'то що є люди́на, що Ти пам\'ятаєш про неї, і син лю́дський, про якого Ти зга́дуєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'А однак учинив Ти його мало меншим від Бога, і славою й ве́личчю Ти корону́єш його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Учинив Ти його воло́дарем тво́рива рук Своїх, все під но́ги йому вмісти́в:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'худобу дрібну́ та биків, їх усіх, а також степови́х звірів диких,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'птаство небесне та риби морські́, і все, що морськи́ми доро́гами ходить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Господи, Боже наш, — яке то вели́чне на ці́лій землі Твоє Йме́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Для дириґента хору. На спів: „На смерть сина“. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Хвали́тиму Господа усім серцем своїм, розповім про всі чу́да Твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Я буду радіти, і ті́шитись буду Тобо́ю, і бу́ду виспі́вувати Ймення Твоє, о Всевишній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Як будуть назад відступати мої вороги́, то спіткну́ться і ви́гинуть перед обличчям Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Бо суд мій і справу мою розсудив Ти, Ти на троні судде́вім сидів, Судде праведний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Докори́в Ти народам, безбожного зни́щив, ім\'я́ їхнє Ти витер навічні віки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'О во́роже мій, руйнува́ння твої закінчи́лись на вічність, — ти й міста́ повалив був, і згинула з ними їхня пам\'ять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Та буде Господь пробува́ти навіки, Він для су́ду поставив престола Свого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'і вселенну Він буде судити по правді, справедливістю буде судити наро́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'І тверди́нею буде Господь для пригні́ченого, в час недолі — приту́лком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'І на Тебе наді́ятись бу́дуть усі, що Ім\'я́ Твоє знають, бо не кинув Ти, Господи, тих, хто шукає Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Співайте Господе́ві, що сидить на Сіоні, між наро́дами розповідайте про чи́ни Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'бо карає Він чинки крива́ві, про них пам\'ятає, і не забуває Він зо́йку убогих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Помилуй мене, Господи, поглянь на стражда́ння моє від моїх ненави́сників, Ти, що мене підійма́єш із брам смерти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'щоб я розповідав про всю славу Твою, у брамах Сіонської до́ні я буду радіти спасі́нням Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Наро́ди попа́дали в яму, яку самі ви́копали, до па́стки, яку захова́ли, нога їхня схо́плена.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Господь зна́ний, Він суд учинив, — спіткну́всь нечестивий у вчинку своєї руки́! Гра на струнах. Села.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Попряму́ють безбожні в шео́л, всі наро́ди, що Бога забули,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'бож не навіки забу́деться бідний, надія убогих не згине наза́вжди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Устань же, о Господи, — хай люди́на не перемагає, нехай перед лицем Твоїм засуджені будуть наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Накинь, Господи, по́страх на них, — нехай знають наро́ди, що вони тільки люди! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Для чо́го стоїш Ти, о Господи, зда́лека, в час недолі ховаєшся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Безбожний в своїм гордува́нні женеться за вбогим, — хай схо́плені будуть у пі́дступах, які замишляли вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Бо жада́нням своєї душі нечестивий пишається, а ласу́н проклинає, зневажає він Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'У го́рдощах каже безбожний, що „Він не слідку́є“, бо „Бога нема“, — оце всі його по́мисли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Сильні дороги його повсякча́сно, від нього суди́ Твої ви́соко, — тим то віддму́хує він ворогів своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 27, 'Сказав він у серці своєму: „Я не захита́юсь, бо ли́ха навіки не буде мені“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 28, 'Уста́ його повні прокля́ття й обма́ни та зради, під його язиком — злочи́нство й пере́ступ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 29, 'Причаївшись, сидить на подві́р\'ях, мордує невинного, його очі слідкують за вбогим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 30, 'В укритті́ він чату́є, як лев той у за́рості, чатує схопи́ти убогого, хапа́є убогого й тягне його в свою сі́тку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 31, 'Припадає, знижається він, — і попада́ють убогі в його міцні кігті ...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 32, 'Безбожний говорить у серці своїм: „Бог забув, заховав Він обличчя Своє, не побачить ніко́ли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 33, 'Устань же, о Господи Боже, руку Свою підійми, не забудь про убогих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 34, 'Чому́ нечестивий обра́жує Бога і говорить у серці своїм, що Ти не слідкуєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 35, 'Але́ Ти все бачиш, бо спостеріга́єш злочинство та у́тиск, щоб віддати Своєю рукою! На Тебе слаби́й опира́ється, Ти сироті помічни́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 36, 'Зламай же раме́но безбожному, і злого скарай за неправду його, — аж більше не зна́йдеш його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 37, 'Господь — Цар на вічні віки́, із землі Його згинуть погани!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 38, 'Бажа́ння пони́жених чуєш Ти, Господи, серця́ їх зміцня́єш, їх вислухо́вує ухо Твоє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 39, 'щоб дати суд сироті та пригні́ченому, щоб більш не страши́в чоловік із землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 40, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Для дириґента хору. Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Я наді́юсь на Господа, — як же кажете ви до моєї душі: „Відлітай ти на го́ру свою, немов птах?“Бо ось нечестиві натя́гують лу́ка, міцно ставлять стрілу́ свою на тятиву́, щоб у те́мряві до простосердих стріляти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Як основи зруйновано, — що́ тоді праведний зробить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Госпо́дь у святім Своїм храмі, Господь — престол Його на небеса́х, бачать очі Його, повіки Його випробо́вують лю́дських синів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Господь випробо́вує праведного, а безбожного й того, хто любить наси́лля, — ненави́дить душа Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Він спу́стить дощем на безбожних горю́че вугі́лля, огонь, і сірку, і вітер гарячий, — це частка їхньої чаші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Бо Господь справедливий, кохає Він правду, — праведний бачить обли́ччя Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Для дириґента хору. На окта́ву. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Спаси мене, Господи, бо нема вже побожного, з-поміж лю́дських синів позника́ли вже вірні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Марно́ту говорять один до одно́го, їхні уста обле́сні, і серцем подвійним говорять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Нехай підітне́ Господь уста обле́сливі та язика чванькува́того');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'тим, хто говорить: „Своїм язиком будем си́льні, наші уста при нас, — хто ж буде нам пан?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Через утиск убогих, ради сто́гону бідних тепер Я повстану, — говорить Господь, — поставлю в безпе́ці того, на ко́го розтя́гують сітку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Господні слова — слова чисті, як срі́бло, очищене в глинянім го́рні, сім раз перето́плене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Ти, Господи, їх пильнува́тимеш, і будеш навіки нас стерегти́ перед родом оцим!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Безбожні кружля́ють навко́ло, бо нікче́мність між лю́дських синів підійма́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Доки, Господи, бу́деш мене забувати наза́вжди, доки будеш ховати від ме́не обличчя Своє?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Як довго я буду складати в душі своїй болі, у серці своїм — щодня сму́ток? Як довго мій ворог підно́ситись буде над мене?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Зглянься, озвися до мене, о Господи, Боже мій! Просвітли мої очі, щоб на смерть не заснув я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Щоб мій не́приятель не сказав: „Я його переміг!“Щоб мої вороги не раділи, як я захита́юсь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Я надію на милість Твою поклада́ю, моє серце радіє спасі́нням Твоїм! Я буду співати Господе́ві, бо Він доброді́йство для мене вчинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Для дириґента хору. Давидів. Безу́мний говорить у серці своїм: „Нема Бога!“Зіпсу́лись вони, і обри́дливий чинять учинок, нема доброчи́нця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Господь дивиться з неба на лю́дських синів, щоб побачити, чи є там розумний, що Бога шукає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Усе повідступа́ло, разом стали бридки́ми вони, нема доброчинця, нема ні одно́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Чи ж не розуміють всі ті, хто чинить безпра́в\'я, хто мій люд поїдає? Вони хліб Господній їдять, та не кличуть Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Тоді настраши́лися стра́хом вони, бо Бог в праведнім роді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Раду вбогого га́ньбите ви, та Госпо́дь охорона йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Аби то Він дав із Сіону спасі́ння Ізраїлеві! Як долю Своєму наро́ду пове́рне Господь, то радітиме Яків, втіша́тися буде Ізра́їль!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Псало́м Давидів. Го́споди, хто може перебувати в наме́ті Твоїм? Хто ме́шкати може на святій Твоїй горі? —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Той, хто в невинності ходить, і праведність чинить, і правду говорить у серці своїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'хто не обмовля́є своїм язиком, і злого не чинить для друга свого, і свого ближнього не зневажає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Обридли́вий погорджений в очах його, і він богобі́йних шанує, присягає, для себе хоча б і на зло, — і дотримує;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'не дає свого срі́бла на ли́хву, і не бере на невинного пі́дкупу. Хто чинить таке, — ніко́ли той не захита́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Золота пісня Дави́дова. Хорони́ мене, Боже, — я бо до Тебе вдаю́ся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Я сказав Господе́ві: „Ти Бог мій і — добро моє тільки в Тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'До святих, які на землі, що шляхе́тні вони, — до них все жада́ння моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Нехай мно́жаться сму́тки для тих, хто набув собі інших богів, — я не буду прино́сить їм ли́вної жертви із крови, і їхніх іме́н не носитиму в устах своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Господь — то частина спа́дку мого та чаші моєї, Ти долю мою підпира́єш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Ча́стки припали для мене в хороших місцях, і гарна для мене спа́дщина моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Благословляю я Господа, що радить мені, на́віть ноча́ми навчають мене мої ни́рки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Уявляю я Господа перед собою постійно, бо Він по правиці моїй, — й я не буду захитаний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Через те моє серце радіє та дух весели́ться, — і тіло моє спочиває безпечно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Бо Ти не опу́стиш моєї душі до шео́лу, не попу́стиш Своєму святому побачити тлі́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Дорогу життя Ти покажеш мені: радість велика з Тобою, за́вжди блаженство в прави́ці Твоїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Молитва Дави́дова. Вислухай, Го́споди, правду мою, послухай блага́ння моє! Почуй молитву мою із уст необлу́дних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Від Твого лиця нехай вирок мій ви́йде, а очі Твої нехай бачать мою правоту́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Ти ви́пробував моє серце, навісти́в уночі, перетопи́в Ти мене, — й не знайшов чогось злого. І розду́мував я, щоб лихе з моїх уст не вихо́дило,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'а в лю́дських діла́х, за словом уст Твоїх, я стерігся доріг гнобителя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Зміцняй сто́пи мої на доро́гах Твоїх, щоб кро́ки мої не хита́лися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Я кли́чу до Тебе, бо відповіси́ мені, Боже, — нахили Своє ухо до мене, вислухай мову мою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'покажи дивну милість Свою, Спасителю тих, хто вдає́ться до Тебе від заколо́тників проти прави́ці Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Хорони Ти мене, як зіни́цю Свою, дочку ока, у тіні Своїх крил заховай Ти мене');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'від безбожних, що гублять мене, — смертельні мої вороги оточили мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'То́вщем замкнули вони своє серце, уста їхні говорять бундю́чно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Вороги оточили тепер наші кро́ки, наставили очі свої, щоб мене повалити на землю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Із них кожен подібний до лева, що ша́рпати прагне, й як левчук, що сидить в укритті́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Устань же, о Господи, — його попере́дь, кинь його на коліна! Мечем Своїм душу мою збережи від безбожного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'від людей рукою Своєю, Господи, від людей цього світу, що частка їхня в цьому житті, що Ти скарбом Своїм наповня́єш їхнє че́рево! Ситі їхні сини, останок же свій для дітей вони ли́шать.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'А я в правді побачу обли́ччя Твоє, і, збудившись, наси́чусь Твоєю подо́бою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Для дириґента хору. Раба Господнього Давида, коли він промовив до Господа слова́ цієї пісні того дня, як Господь урятував його з руки всіх його ворогів та від руки Саула,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'то він проказав: Полюблю́ Тебе, Господи, сило моя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Господь моя ске́ля й тверди́ня моя, і Він мій Спаси́тель! Мій Бог — моя ске́ля, сховаюсь я в ній, Він щит мій, і ріг Він спасі́ння мого́, Він башта моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Я кли́чу: Преславний Госпо́дь, і я ви́зволений від своїх ворогів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Тене́та смерте́льні мене оточили, і пото́ки велійяа́ла лякають мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Тене́та шео́лу мене оточили, і па́стки смертельні мене попере́дили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'В тісноті́ своїй кличу до Господа, і до Бога свого я взива́ю, — Він почує мій голос із храму Свого́, і доходить мій зойк до лиця Його в уші Йому́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Захиталась земля й затремтіла, і затрясли́сь і хитались підва́лини гір, — бо Він запали́вся від гніву:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'із ні́здер Його бухнув дим, з Його ж уст — пожиру́щий огонь, і жар запалився від Нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Він небо простяг — і спустився, а хмара густа́ під ногами Його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Усівся Він на херувима й летів, і на ві́трових кри́лах понісся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Поклав те́мряву Він — як засло́ну Свою, довкі́лля Його — то те́мрява вод, а мешка́ння Його — густі хмари!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Від блиску, що був перед Ним, град і жар огняни́й пройшли хмари Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'І Господь загримів у небеса́х, і Всевишній Свій голос подав, град і жар огняни́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Він послав Свої стріли, — та їх розпоро́шив, і стрі́лив Він бли́скавками, — та їх побенте́жив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Показалися рі́чища водні, і відкри́лись осно́ви вселе́нної, — від сварі́ння Твого, о Господи, від по́диху вітру із ні́здер Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Він простя́г з висоти Свою руку, узяв Він мене, витяг мене з вод великих, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'він мене врятував від мого потужного ворога, і від моїх ненави́сників, — бо сильніші від мене вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Напали на мене вони в день нещастя мого́, — та Господь був моїм опертя́м, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'і на місце розло́ге Він вивів мене, Він мене врятував, — бо вподо́бав мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Нехай Господь зро́бить мені за моєю справедливістю, хай заплатить мені згідно з чи́стістю рук моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'бо беріг я дороги Господні, і від Бога свого я не відступив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'бо всі Його при́суди передо мною, і не відкидав я від себе Його постано́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'І був я із Ним непорочний, і стерігся своєї провини,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'і Господь заплатив був мені за моєю справедливістю, згідно з чистістю рук моїх перед очима Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Із справедливим пово́дишся Ти справедливо, із че́сним — по-че́сному,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'із чистим — пово́дишся чисто, а з лукавим — за лукавством його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 28, 'бо наро́д із біди Ти спасаєш, а очі зухва́лі принижуєш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 29, 'бо Ти світиш мого світильника, Господь — Бог мій, освітлює Він мою те́мряву!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 30, 'Бо з Тобою поб\'ю я ворожого відділа, і з Богом своїм проберусь через мур.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 31, 'Бог — непорочна дорога Його, слово Господнє очи́щене, щит Він для всіх, хто вдає́ться до Ньо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 32, 'Бо хто Бог, окрім Господа? і хто скеля, крім нашого Бога?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 33, 'Цей Бог мене силою опереза́в, і дорогу мою учинив непорочною,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 34, 'Він зробив мої но́ги, мов у ла́ні, і ставить мене на висо́тах моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 35, 'мої руки навчає до бо́ю, і на раме́на мої лука мі́дяного напина́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 36, 'І дав Ти мені щит спасі́ння Свого́, а прави́ця Твоя підпирає мене, і чинить великим мене Твоя поміч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 37, 'Ти чиниш широким мій крок підо мною, — і сто́пи мої не спіткну́ться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 38, 'Женуся я за ворогами своїми, — і їх дожену́, і не верну́ся, аж поки не ви́нищу їх, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 39, 'я їх потрощу́, — й вони встати не зможуть, повпадають під ноги мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 40, 'Ти ж для бо́ю мене підпері́зуєш силою, ва́лиш під мене моїх ворохо́бників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 41, 'Повернув Ти до мене плечима моїх ворогів, — і понищу нена́висників я своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 42, 'Кричали вони, — та немає спасителя, взивали до Господа, — і не відповів їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 43, 'І я їх зітру́, як той по́рох на вітрі, як болото на вулицях, їх потопчу́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 44, 'Ти від бунту народу мене бережеш, Ти робиш мене головою племе́нам, мені будуть служити наро́ди, яких я не знав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 45, 'На вістку про мене — слухня́ні мені, до мене чужи́нці підле́щуються,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 46, 'в\'януть чужи́нці і тремтять у тверди́нях своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 47, 'Живий Господь, — і благословенна будь, скеле моя, і нехай Бог спасі́ння мойого звели́читься,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 48, 'Бог, що помсти за мене дає, і що наро́ди під мене підбив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 49, 'що рятує мене від моїх ворогів, — Ти звели́чив мене над повста́нців на мене, спасаєш мене від наси́льника!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 50, 'Тому́ то хвалю Тебе, Господи, серед наро́дів, і Йме́нню Твоє́му співаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 51, 'Ти Своє́му цареві спасі́ння побільшуєш, і милість вчиняєш Своє́му пома́занцеві Давиду й насінню його аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Для дириґента хору. Псало́м Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Небо звіщає про Божую славу, а про чин Його рук розказує небозві́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Оповіщує день дневі слово, а ніч ночі показує думку, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'без мови й без слів, не чутни́й їхній голос,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'та по ці́лій землі пішов ві́дголос їхній, і до кра́ю вселе́нної їхні слова́! Для сонця наме́та поставив у них, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'а воно, немов той молоди́й, що вихо́дить із-під балдахи́ну свого, — воно ті́шиться, мов той герой, щоб пробігти дорогу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Вихід його́ з краю неба, а о́біг його — аж на кі́нці його, і від спеки його ніщо не захова́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Господній Зако́н досконалий, — він змі́цнює душу. Свідчення Господа певне, — воно недосві́дченого умудряє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Справедливі Господні накази, бо серце вони звеселя́ють. Заповідь Господа чиста, — вона очі просвітлює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Страх Господа чистий, — він навіки стоїть. При́суди Господа — правда, вони справедливі всі ра́зом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'дорожчі вони понад золото і понад бе́зліч щирого золота, і солодші за мед і за сік щільнико́вий, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'і раб Твій у них бережки́й, а в дотри́манні їх — нагорода велика.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'А по́милки хто зрозуміє? Від таємних очисть Ти мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'і від сваві́льців Свого раба захова́й, нехай не панують вони надо мною, тоді непорочним я буду, і від провини великої буду очи́щений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Нехай бу́дуть із волі Твоє́ї слова́ моїх уст, а думки́ мого серця — перед лицем Твоїм, Господи, скеле моя й мій Спасителю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Для дириґента хору. Псало́м Дави́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'В день недолі озве́ться до тебе Госпо́дь, Ім\'я́ Бога Якового зробить си́льним тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Він пошле тобі по́міч із святині, і з Сіону тебе підіпре́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Усі жертви твої пам\'ятати Він буде, і буде вважати твоє цілопа́лення ситим. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Він дасть тобі, як твоє серце бажає, і ви́повнить ці́лий твій за́дум!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Ми бу́дем радіти спасі́нням Твоїм, і піді́ймемо пра́пор в Ім\'я́ Бога нашого, — нехай Господь виконає всі проха́ння твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Тепер я пізнав, що спасає Господь помаза́нця Свого́, дає йому ві́дповідь з неба святого Свого́ могу́тніми чи́нами помічно́ї прави́ці Своєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Одні колесни́цями хва́ляться, а інші кі́ньми, а ми бу́дем хвалитись Ім\'я́м Господа, нашого Бога:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'вони похилились і впали, а ми стоїмо́ та росте́мо на силах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Господи, спаси! Хай озве́ться нам Цар у день нашого кли́кання!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Господи, силою Твоєю весели́ться цар, і спасі́нням Твоїм — як він сильно радіє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Ти йому дав бажа́ння серця його, і проха́ння уст його не відмо́вив. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Бо Ти його ви́передив благослове́ннями добра́, на голову йому поклав корону зо щирого золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Життя він у Те́бе просив, — і дав Ти йому довголі́ття на вічні віки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Слава велика його при Твоїй допомозі, хвалу́ та величність кладеш Ти на нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'бо Ти вчи́ниш його благословенням вічним, звесели́ш його радістю, як буде він ра́зом з Тобою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Цар має наді́ю на Господа, у ласці Всеви́шнього не захитається він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Зна́йде рука Твоя всіх ворогів Твоїх, зна́йде прави́ця Твоя Твоїх ненави́сників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'На час гніву Свого Ти їх учи́ниш огне́нною піччю, Господь гнівом Своїм їх понищить, і огонь пожере́ їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Ти ви́губиш плід їхній із землі, а їхнє насіння з-поміж синів лю́дських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Бо нещастя на Тебе вони простягли́, замишляли злу думку, якої здійсни́ти не зможуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'бо Ти їх обе́рнеш плечи́ма до нас, на тяти́вах Своїх міцно стріли поставиш на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Піднеси́ся ж, о Господи, в силі Своїй, а ми бу́дем співати й хвалити могу́тність Твою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Для дириґента хору. На спів: „Ланя зорі́ досві́тньої“. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Боже мій, Боже мій, — на́що мене Ти покинув? Далекі слова́ мого зо́йку від спасі́ння мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Мій Боже, взиваю я вдень, — та Ти не озве́шся, і кли́чу вночі, — і споко́ю немає мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Та Ти — Святий, пробува́єш на хва́лах Ізраїлевих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'На Тебе наді́ялись наші батьки́, надіялися — і Ти ви́зволив їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'До Тебе взива́ли вони — і спасе́ні були́, на Тебе наді́ялися — і не посоро́мились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'А я — червяк, а не чоловік, посміхо́вище лю́дське й погорда в наро́ді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Всі, хто бачить мене, — насміхаються з мене, розкривають роти́, головою хита́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, '„Поклада́вся на Господа він, — хай же рятує його́, нехай Той його ви́зволить, — він бо Його уподо́бав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Бо з утро́би Ти вивів мене, Ти безпе́чним мене учинив був на пе́рсах матері моєї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'На Тебе з утро́би я зда́ний, від утроби матері моєї — Ти мій Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Не віддаля́йся від мене, бо горе близьке́, бо нема мені помічника́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Багато бикі́в оточи́ли мене, баша́нські бугаї́ обступи́ли мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'на мене розкрили вони свої па́щі, як лев, що шмату́є й ричи́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 15, 'Я розлитий, немов та вода, і всі кості мої поділи́лись, стало серце моє, немов віск, розтопи́лось в моє́му нутрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 16, 'Висохла сила моя, як лушпи́ння, і прили́п мій язик до мого піднебі́ння, і в по́рох смерте́льний поклав Ти мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 17, 'Бо пси оточи́ли мене, обліг мене на́товп злочи́нців, проколо́ли вони мої руки та но́ги мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 18, 'Я висох, рахую всі ко́сті свої, а вони придивля́ються й бачать нещастя в мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 19, 'Вони ді́лять для се́бе одежу мою, а про ша́ту мою жеребка́ вони кидають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 20, 'А Ти, Господи, не віддаляйся, — Допомо́го моя, поспіши ж мені на оборо́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 21, 'Від меча збережи мою душу, одина́чку мою з руки пса!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 22, 'Спаси мене від пащі ле́в\'ячої, а вбогу мою — від рогів бу́йволів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 23, 'Я звіщатиму Ймення Твоє своїм бра́ттям, буду хвалити Тебе серед збо́ру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 24, 'Хто боїться Господа, прославляйте Його, увесь Яковів роде — шануйте Його, страхайтесь Його, все насіння Ізраїлеве,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 25, 'бо Ві́н не пого́рдував і не знева́жив стражда́ння убогого, і від нього обличчя Свого́ не сховав, а почув, як він кликав до Ньо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 26, 'Від Тебе повста́не хвала́ моя в зборі великім, — принесу́ свої жертви в присутності тих, хто боїться Його, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 27, 'будуть їсти покірні — і си́тими ста́нуть, хвали́тимуть Господа ті, хто шукає Його, буде жить серце ваше навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 28, 'Усі кі́нці землі спам\'ята́ють, і до Господа ве́рнуться, і вкло́няться перед обличчям Його́ всі племе́на наро́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 29, 'бо царство Господнє, — і Він Пан над наро́дами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 30, 'Будуть їсти й покло́няться всі багачі́ на землі, перед обличчям Його на коліна попа́дають всі, хто до по́роху схо́дить і не може себе оживи́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 31, 'Бу́де пото́мство служити Йому́, — й залі́чене буде навіки у Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 32, 'При́йдуть і будуть звіщать Його правду наро́дові, який буде наро́джений, що Він це вчинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Псалом Давидів. Господь — то мій Па́стир, тому́ в недоста́тку не буду, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'на пасови́ськах зелених осе́лить мене́, на тихую воду мене запрова́дить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Він душу мою відживля́є, прова́дить мене́ ради Йме́ння Свого́ по стежка́х справедливости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Коли я піду́ хоча б навіть долиною смертної те́мряви, то не буду боятися злого, бо Ти при мені, — Твоє же́зло й Твій по́сох — вони мене вті́шать!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Ти передо мною трапе́зу згото́вив при моїх ворогах, мою го́лову Ти намасти́в був оливою, моя чаша — то на́дмір пиття́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Ті́льки добро́ й милосердя мене супрово́дити будуть по всі дні мого життя, а я пробува́тиму в домі Господньому довгі часи́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Псалом Давидів. Господня земля, і все, що на ній, вселе́нна й мешка́нці її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'бо заклав Він її на моря́х, і на річках її встанови́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Хто зі́йде на го́ру Господню, і хто бу́де стояти на місці святому Його? —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'У кого́ чисті руки та щиреє серце, і хто не нахиля́в на марно́ту своєї душі, і хто не присягав на обма́ну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'нехай но́сить він благослове́ння від Господа, а праведність — від Бога спасі́ння свого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Таке поколі́ння усіх, хто шукає Його́, хто пра́гне обличчя Твого́, Боже Яковів! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Піднесі́те верхи́ свої, брами, і будьте відчи́нені, вхо́ди відві́чні, — і вві́йде Цар слави!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Хто ж то Цар слави? — Господь си́льний й могу́тній, Господь, що поту́жний в бою́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Піднесіте верхи́ свої, брами, і піднесіте, вхо́ди відві́чні, — і вві́йде Цар слави!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Хто ж то Він, той Цар слави? Господь Савао́т — Він Цар слави! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Давидів. До Тебе підно́шу я, Господи, душу свою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Боже мій, я на Тебе наді́юсь, — нехай же я не засоро́млюсь, нехай не радіють мої вороги ради мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Не будуть також посоро́млені всі, хто на Тебе наді́ється, та нехай посоромляться ті, хто на Те́бе встає надаре́мно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Доро́ги Твої дай пізнати мені, Го́споди, стежка́ми Своїми мене попрова́дь,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'провадь мене в правді Своїй і навчи Ти мене, бо Ти Бог спасі́ння мого́, кожен день я на Тебе наді́юсь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Пам\'ятай милосердя Своє, о мій Господи, і ласки Свої, бо відвічні вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Гріхи молоде́чого віку мого́ та провини мої не прига́дуй, — пам\'ятай мене, Господи, в ласці Своїй через добрість Свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Господь добрий та праведний, тому грішних навчає в дорозі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Він прова́дить покірних у правді, і лагі́дних навчає дороги Своєї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Всі Господні стежки́ — милосе́рдя та правда для тих, хто Його́ заповіта й свідоцтва доде́ржує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 11, 'Ради Йме́ння Свого, о Господи, прости мені про́гріх, великий бо він!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 12, 'Хто то́й чоловік, що боїться він Господа? — Він наставить його на доро́гу, котру має ви́брати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 13, 'душа його жи́тиме в щасті, і насіння його вспадку́е землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 14, 'При́язнь Господня до тих, хто боїться Його́, і Сві́й заповіт Він звісти́ть їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 15, 'Мої очі постійно до Господа, бо Він з па́стки витягує но́ги мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 16, 'Оберни́ся до мене й помилуй мене, — я ж бо самі́тний та бідний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 17, 'Муки серця мого поширились, — ви́зволь мене з моїх у́тисків!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 18, 'Подивися на горе моє та на му́ку мою, — і прости всі гріхи́ мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 19, 'Подивись на моїх ворогів, — як їх стало багато, вони лютою ненавистю ненави́дять мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 20, 'Пильнуй же моєї душі та мене хорони́, — щоб не бути мені засоро́мленим, бо наді́юсь на Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 21, 'Невинність та правда нехай оточа́ють мене, бо наді́юсь на Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 22, 'Визволи, Боже, Ізраїля від усіх його у́тисків!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Давидів. Суди мене, Господи, бо ходив я в своїй непоро́чності, і надіявсь на Господа, — тому не спіткну́ся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Перевір мене, Господи, і ви́пробуй мене, перетопи́ мої ни́рки та серце моє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'бо перед очима моїми Твоє милосердя, і в правді Твоїй я ходив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Не сидів я з людьми́ неправдивими, і не бу́ду ходити з лукавими,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'я громаду злочи́нців знена́видів, і з грішниками я сидіти не буду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Умию в неви́нності руки свої, й обійду́ Твого, Господи, же́ртівника,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'щоб хвалу́ Тобі го́лосно ви́голосити, та звісти́ти про всі чу́да Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Господи, — полюбив я оселю дому Твого́, і місце перебува́ння слави Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Не губи Ти моєї душі з нечестивими, та мого життя з кровоже́рами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'що в руках їх злоді́йство, що їхня прави́ця напо́внена пі́дкупом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'А я бу́ду ходити в своїй непоро́чності, — визволь мене та помилуй мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Нога моя стала на рівному місці, — на збо́рах я благословля́тиму Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Давидів. Господь моє світло й спасі́ння моє, — кого бу́ду боятись? Господь — то тверди́ня мого життя, — кого буду ляка́тись?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Коли будуть зближа́тись до ме́не злочи́нці, щоб жерти їм тіло моє, мої напасники́ та мої вороги, — вони спотикну́ться й попа́дають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'коли проти мене розло́житься та́бір, то серце моє не злякається, коли проти мене повста́не війна, — я наді́ятись буду на те́, — на по́міч Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Одно́го прошу́ я від Господа, буду жадати того́, — щоб я міг пробува́ти в Господньому домі по всі дні свого життя, щоб я міг оглядати Господню приємність і в храмі Його пробува́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'бо Він заховає мене дня нещастя в Своїй ски́нії, сховає мене потає́мно в Своєму наме́ті, на скелю мене проведе́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'А тепер піднесе́ться моя голова понад ворогами моїми навко́ло мене, і я в Його ски́нії буду прино́сити жертви при ві́дзвуках сурм, і я буду співати та грати Господе́ві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Почуй, Господи, голос мій, коли кли́чу, і помилуй мене, і озви́ся до мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'За Тебе промовило серце моє: „Шукайте Мого лиця!“тому, Господи, буду шукати обличчя Твого́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'не ховай же від мене обличчя Свого́, у гніві Свого раба не відкинь! Ти був мені по́міч, — не кидай мене, і не лишай мене, Боже спасі́ння мого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'бо мій батько та мати моя мене кинули, — та Господь прийме́ мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Дорогу Свою покажи мені, Господи, і провадь мене сте́жкою рівною, ради моїх ворогів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Не видай мене на сваво́лю моїх ворогів, бо повстали на мене ті свідки облу́дні та неправдомо́вці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'немов би не вірував я, що в країні життя я побачу Господнє добро́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Наді́йся на Господа, будь си́льний, і хай буде міцне́ твоє серце, і надійся на Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Давидів. До Тебе я кли́чу, о Господи ске́ле моя, — не будь же безмо́вним до мене, — бо коли Ти замо́вкнеш до мене, я стану подібний до тих, що сходять до гро́бу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Почуй голос блага́ння мого, як я кли́чу до Тебе, коли руки свої я підно́шу до храму святого Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Не хапай мене з грішними й тими, хто чинить безпра́вство, хто плете́ своїм ближнім про мир, — але зло в їхнім серці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Віддай їм за їхнім учинком, і за злом їхніх учинків, згідно з ді́лом їхні́х рук Ти їм дай, верни їм заслу́жене ними,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'бо вони не вдивля́ються в чинність Господню й діла́ Його рук, — нехай їх поруйнує, й нехай не будує Він їх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Благослове́нний Господь, — бо Він почув голос блага́ння мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Госпо́дь моя сила та щит мій, на нього наді́ялось серце моє, — й Він мені допоміг, і вті́шилося моє серце, і співом своїм я прославлю Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Господь сила наро́ду Свого́, і за́хист спасі́ння Свого пома́занця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Спаси Свій наро́д, і поблагослови спадщину Свою, і паси їх, і підно́сь їх навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Псалом Давидів. Дайте Господу, Божі сини, дайте Господу славу та силу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Дайте Господу славу Іме́ння Його, у препи́шній святині впадіть перед Господом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Голос Господній над во́дами, Бог слави гримить, Господь над великими во́дами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Голос Господній із силою, голос Господній з вели́чністю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Голос Господній ламає кедри́ни, голос Господній торо́щить кедри́ни лива́нські.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Він примусить скака́ти Лива́н як теля́, та Си́ріон, мов молоду антило́пу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Голос Господній викре́шує по́лум\'я огняне́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'голос Господній пустиню тремтіти примушує, Господь чинить пустелю Каде́ша тремтячою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Голос Господній примушує ла́ні тремтіти, й ліси́ обнажає, а в храмі Його все належне Йому виголо́шує: „Слава!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Господь пробува́в в час пото́пу, і буде Господь пробува́ти повік ві́ку Царем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Господь подасть силу наро́ду Своє́му, Господь поблагосло́вить ми́ром наро́д Свій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Псалом Давидів. Пісня освя́чення дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Буду Тебе величати, о Господи, бо Ти з глибини́ мене ви́тяг, і не потішив моїх ворогів ради мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Господи, Боже мій, я кликав до Тебе, — і мене вздорови́в Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Господи, вивів Ти душу мою із шео́лу, — Ти мене оживи́в, щоб в могилу не схо́дити мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Співайте Господе́ві, святії Його, й славте пам\'ять святині Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Бо хвилю триває Він у гніві Своїм, все життя — в Своїй ласці: буває увечорі плач, а радість на ра́нок!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'А я говорив був у ми́рі своєму: „Я не захита́юсь навіки“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Господи, в ласці Своїй Ти поставив мене на горі́ моїх сил. Як лице Своє Ти захова́в, то збенте́жився я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'До Тебе я кличу, о Господи, і блага́ю я Господа:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, '„Яка ко́ристь із кро́ви моєї, коли́ я до гро́бу зійду́? Чи хвалити Тебе буде по́рох? Чи він ви́явить правду Твою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Почуй, Господи, і помилуй мене, Господи, бу́дь мені помічнико́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Ти перемінив мені плач мій на радість, жало́бу мою розв\'яза́в, і підпереза́в мене радістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'щоб славу співала люди́на Тобі й не замо́вкла! Господи, Боже мій, — повік сла́вити буду Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'На Тебе наді́юсь я, Господи, хай не буду повік засоро́млений, ви́зволь мене в Своїй правді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Нахили Своє ухо до ме́не, скоро мене поряту́й, стань для мене могу́тньою ске́лею, домом тверди́ні, щоб спас Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Бо ти ске́ля моя та тверди́ня моя, і ради Йме́ння Свого Ти будеш провадити мене́ й керувати мене́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Ти ви́тягнеш з па́стки мене, що на мене тає́мно поста́вили, — бо Ти сила моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'У руку Твою доруча́ю я духа свого́, — і Ти мене ви́зволиш, Господи, Боже правди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Я знена́видив всіх, хто шанує бовва́нів марни́х, я ж наді́юсь на Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Я буду радіти та ті́шитися в Твоїй ми́лості, що побачив Ти горе моє, що пригля́нувся Ти до скорбо́ти моєї душі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'і мене не віддав в руку ворога, на місці розло́гім поставив Ти ноги мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Помилуй мене, Господи, бо тісно мені, — від горя вже ви́снажилось моє око, душа моя й нутро моє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'бо скінчи́лось життя моє в сму́тку, а роки мої — у квилі́нні, моя сила спіткну́лася через мій гріх, і ви́снажились мої кості!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Я в усіх ворогів своїх став посміхо́вищем, надто сусідам своїм, і страхі́ттям — знайо́мим моїм, хто бачить надво́рі мене — утікають від мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Я забутий у серці, немов той небі́жчик, став я немов та розбита посу́дина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Бо чую багато шепта́ння, страха́ння навко́ло, як змовляються ра́зом на мене, — вони замишляють забрати мою душу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'а я покладаю наді́ю на Тебе, о Господи, я кажу́: „Ти мій Бог!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'В Твою руку кладу́ свою долю, — Ти ж ви́зволь мене від руки ворогів моїх і моїх переслі́дників!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Хай засяє обличчя Твоє на Твого раба, та спаси мене в ласці Своїй,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Господи, щоб не бути мені посоро́мленим, що кличу до Тебе! Нехай посоро́млені будуть безбожні, хай замовкнуть та йдуть до шео́лу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'нехай заніміють облу́дні уста́, що гидо́ту говорять на праведного із пихо́ю й погордою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Яка величе́зна Твоя доброта́, яку заховав Ти для тих, хто боїться Тебе, яку пригото́вив для тих, хто на Тебе наді́ється перед лю́дськими синами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Ти їх у засло́ні обличчя Свого́ заховаєш від лю́дських тене́т, Ти їх від лихих язиків у наметі сховаєш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Благослове́нний Госпо́дь, що вчинив мені милість чудо́вну Свою в оборо́нному місті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'А я говорив у своїм побенте́женні: „Я відрі́заний з-перед оче́й Твоїх!“Та дійсно Ти вислухав голос блага́ння мого, коли я до Тебе взива́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Любіть Господа, усі святії Його, — стереже́ Господь вірних, а гордому з лишком відплачує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 25, 'Будьте сильні, і хай буде міцне́ ваше серце, усі, хто наді́ю поклада́є на Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Давидів. Пісня навча́льна. Блаже́нний, кому подаро́ваний зло́чин, кому гріх закрито,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'блаженна люди́на, що Госпо́дь їй гріха́ не залічить, що нема в її дусі лука́вства!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Коли я мовчав, спорохня́віли кості мої в цілоде́нному зо́йку моєму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'бо рука Твоя вдень та вночі надо мною тяжи́ть, і воло́га моя обернулась на літню посу́ху! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Я відкрив Тобі гріх свій, і не сховав був провини своєї. Я сказав був: „Признаю́ся в просту́пках своїх перед Господом!“і провину мого гріха Ти простив. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Тому кожен побожний відпові́дного ча́су молитися буде до Тебе, і навіть велика нава́ла води не дося́гне до нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Ти покро́ва моя, Ти від у́тиску бу́деш мене стерегти́, Ти обго́рнеш мене радістю спасі́ння! Се́ла. 8 „Я зроблю́ тебе мудрим, і буду навчати тебе у доро́зі, якою ти будеш ходи́ти, Я дам тобі раду, Моє око вважає на те́бе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Не будьте, як кінь, як той мул нерозумні, що їх треба прибо́ркати оздо́бою їхньою — вуди́лом і вузде́чкою, як до тебе вони не зближа́ються“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Багато хворі́б — на безбожного, хто ж наді́ю свою покладає на Господа — того милість ото́чує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Веселі́тесь у Го́споді, і тіштеся, праведні, і співайте із радістю, всі щиросе́рді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Співайте із радістю, праведні в Господі, — бо щи́рим лицю́є хвала́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Хваліть Господа гу́слами, співайте Йому з десятистру́нною а́рфою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'заспівайте Йому нову пісню, гарно заграйте Йому з гуком су́рем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'бо щире Господнєє слово, і кожен чин Його вірний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Правду та суд Він коха́є, і Господньої милости повна земля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Словом Господнім учи́нене небо, а подихом уст Його все його ві́йсько.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Воду мо́рську збирає Він, мов би до мі́ху, безо́дні складає в комо́рах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Буде боятися Господа ці́ла земля, всі ме́шканці все́світу бу́дуть лякатись Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'бо сказав Він — і сталось, наказав — і з\'явилось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Госпо́дь ра́ду пога́нів пони́щить, поні́вечить ми́слі наро́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'а за́дум Господній навіки стоятиме, думки́ Його серця — на вічні віки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Блаженний той люд, що Богом у нього Госпо́дь, блаженний наро́д, що Він вибрав його на спа́док Собі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Господь споглядає з небе́с, і бачить усіх синів лю́дських,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'приглядається з місця оселі Своєї до всіх, хто замешкує землю:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Хто створив серце кожного з них, наглядає всі їхні діла́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Немає царя, що його многість ві́йська спасає, не врятується ве́летень вели́кістю сили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'для спасі́ння той кінь ненадійний, і великістю сили своєї він не збереже, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'ось око Господнє на тих, хто боїться Його, хто наді́ю на милість Його поклада́є,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'щоб рятувати життя їхнє від смерти, і щоб за час голоду їх оживляти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Душа наша наді́ю склада́є на Господа, — Він наша поміч і щит наш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'бо Ним радується наше серце, бо на Ймення святеє Його ми надію кладемо́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Нехай Твоя милість, о Господи, буде на нас, коли поклада́ємо наді́ю на Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Давидів, коли він удавав був причи́нного перед Авімелехом, що вигнав його, і той пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Я благословля́тиму Господа кожного ча́су, хвала́ Йому за́всіди в у́стах моїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Душа моя буде хвалитися Господом, — хай це почують слухня́ні, і нехай звеселяться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Зо мною звели́чуйте Господа, і підносьте Ім\'я́ Його ра́зом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Шукав я був Господа, — і Він озвався до мене, і від усіх небезпе́к мене ви́зволив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Приглядайтесь до Нього — й зася́єте, і не посоро́мляться ваші обличчя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Цей убогий взивав, — і Господь його ви́слухав, і від усіх його бід його ви́зволив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Ангол Господній табо́ром стає кругом тих, хто боїться його́, — і визво́лює їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Скушту́йте й побачте, який добрий Госпо́дь, блаженна люди́на, що надію на Нього кладе́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Бійтеся Господа, всі святії Його, бо ті, що бояться Його, недостатку не мають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Левчуки́ бідні й голодні, а ті, хто пошукує Господа, недостатку не чують в усьому добрі́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Ходіть, діти, послухайте мене, — стра́ху Господнього я вас навчу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Хто та людина, що хоче життя, що любить дні довгі, щоб бачити добро́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Свого язика́ бережи від лихого, а уста свої — від гово́рений пі́дступу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Відступися від злого і добре чини, миру шукай і женися за ним!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Очі Господні на праведних, уші ж Його — на їхній зойк,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Господнє лице — на злочинців, щоб ви́нищити їхню пам\'ять з землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Коли пра́ведні кли́чуть, то їх чує Господь, і з усіх утисків їхніх визво́лює їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Господь зламаносе́рдим близьки́й, і впоко́рених духом спасає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Багато лихого для праведного, та його визволя́є Господь з них усіх:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Він пильнує всі кості його, — із них жо́дна не зламається!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Зло безбожному смерть заподіє, і винними будуть усі, хто нена́видить праведного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Господь ви́зволить душу рабів Своїх, і винні не будуть усі, хто вдається до Нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Давидів. Судися, о Господи, з тими, хто су́диться зо мною воюй з тими, хто зо мною воює,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'візьми мало́го й великого щита́, — і встань мені на допомогу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Дістань списа, і дорогу замкни моїм напасника́м, скажи до моєї душі: „Я — спасі́ння твоє“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Нехай засоро́мляться й будуть пога́ньблені ті, хто чатує на душу мою; хай відступлять назад і нехай посоро́мляться ті, хто лихо мені замишляє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Бодай вони стали, немов та поло́ва на вітрі, і Ангол Господній нехай їх жене;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'нехай буде доро́га їхня те́мна й сковзька́, і Ангол Господній нехай їх жене, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'бо вони безпричинно тене́та свої розставляють на мене, яму копають безвинно на душу мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Нехай на́гла загибіль, якої не знає, на нього спаде, і сітка його, яку він наставив, хай зловить його у на́гле нещастя, — бодай він до нього упав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'А душа моя в Господі буде радіти, звеселиться Його допомогою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Скажуть усі мої кості: „Господи, хто подібний до Тебе?“Ти рятуєш убогого від сильнішого над нього, покірного та бідаря́ — від його дерія́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Свідки встають неправдиві, чого я не знав — питають мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'віддають мені злом за добро, осиро́чують душу мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'А я, як вони хворували були́, зодягався в вере́ту, душу свою мучив по́стом, молитва ж моя поверталась на лоно моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Як при́ятель, бу́цім то брат він для мене, — так я ходив, ніби був я в жало́бі по матері, був я засму́чений, схи́лений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'А вони, як упав я, радіють та схо́дяться, напасники́ проти мене збираються, я ж не знаю про те; кричать, і не вмовка́ють,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'з дармоїдами та пересмі́шниками скрего́чуть на мене своїми зубами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Господи, — чи довго Ти бу́деш дивитись на це? Відверни́ мою душу від їхніх зубі́в, від отих левчуків одина́чку мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Я буду Тебе прославляти на збо́рах великих, буду Тебе вихваляти в числе́ннім наро́ді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Нехай з мене не ті́шаться ті, хто ворогує на мене безви́нно, нехай ті не морга́ють очима, хто мене без причини нена́видить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'бо говорять вони не про мир, але на спокі́йних у кра́ї облу́дні слова́ вимишляють,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'свої уста на мене вони розкрива́ють, говорять: „Ага, ага! Наші очі це бачили!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Ти бачив це, Господи, — не помовчи́ ж, Господи, — не віддаляйся від мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 23, 'Устань, і збудися на суд мій, Боже мій і Господи мій, на супере́чку мою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 24, 'розсуди Ти мене по Своїй справедливості, Господи, Боже мій, і нехай через мене не тішаться,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 25, 'нехай не говорять у серці своїм: „Ага, — його маємо ми“, хай не кажуть вони: „Ми його проковтну́ли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 26, 'Нехай посоромляться та застидаються ра́зом, хто з мого нещастя радіє, бодай вбрались у сором та в га́ньбу, хто рота свого розкриває на мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 27, 'Хай співають та звесе ляються ті, хто бажає мені правоти́, і нехай кажуть за́вжди: „Хай буде великий Господь, що миру бажає Своєму рабові!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 28, 'А язик мій звіщатиме правду Твою, славу Твою кожен день!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Для дириґента хору. Раба Господнього Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Грішне слово безбожного в серці моїм: „Нема страху́ Божого перед очима його“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'бо в очах своїх він до себе підлещується, щоб бу́цім то гріх свій знайти, щоб знена́видіти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Слова́ його уст — то марно́та й обма́на, перестав він бути мудрим, щоб чинити добро́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Беззако́нство заду́мує він на посте́лі своїй, стає на дорозі недобрій, не цурається злого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Господи, — аж до небе́с милосердя Твоє, аж до хмар Твоя вірність,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Твоя справедливість — немов гори Божі, Твої суди — безо́дня велика, люди́ну й худо́бу спасаєш Ти, Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Яка дорога́ Твоя милість, о Боже, і ховаються лю́дські сини в тіні́ Твоїх крил:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'вони з ситости дому Твого напо́юються, і Ти їх напува́єш з потока Своїх солодо́щів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'бо в Тебе джере́ло життя, в Твоїм світлі побачимо світло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Продовж Свою милість на тих, хто знає Тебе, а правду Свою — на людей щиросердих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Нога пи́шних нехай не наступить на мене, і безбожна рука нехай не викидає мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Попа́дали там беззако́нники, пова́лено їх — і встати не змо́жуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Давидів. Не розпалюйся гнівом свої́м на злочинців, не май за́здрости до беззаконних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'бо вони, як трава, будуть скоро поко́шені, і мов та зелена били́на — пов\'я́нуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Надійся на Господа й добре чини, землю заме́шкуй та правди дотримуй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Хай Господь буде розкіш твоя, — і Він спо́внить тобі твого серця бажа́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'На Господа здай доро́гу свою, і на Нього надію клади, і Він зробить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'і Він ви́провадить, немов світло, твою справедливість, а правду твою — немов пі́вдень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Жди Господа мо́вчки й на Нього наді́йся, не розпалюйся гнівом на того, хто щасливою чинить дорогу свою, на люди́ну, що виконує за́думи злі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Повстри́майсь від гніву й покинь пересе́рдя, не розпа́люйся лютістю, щоб чини́ти лиш зло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'бо ви́тяті будуть злочинці, а ті, хто вповає на Господа — землю вспадку́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'А ще тро́хи — й не буде безбожного, і будеш дивитись на місце його — і не буде його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'а покірні вспадку́ють землю, — і зарозкошу́ють ми́ром великим!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Лихе замишляє безбожний на праведного, і скрего́че на нього своїми зубами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'та Господь посміється із нього, — бачить бо Він, що набли́жується його день!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Безбожні меча добува́ють та лука свого натягають, щоб звали́ти нужде́нного й бідного, щоб порізати людей простої дороги, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'та вві́йде їхній меч до їхнього власного серця, і пола́мані будуть їхні лу́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Краще мале справедливого, ніж велике багатство безбожних, і то багатьох,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'бо зла́мані будуть раме́на безбожних, а справедливих Господь підпира́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Знає Господь дні неви́нних, а їхня спадщина пробуде навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'за лихолі́ття не будуть вони посоро́млені, і за днів голоду ситими бу́дуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Бо загинуть безбожні, і Господні вороги, як овечий той лій, зани́кнуть, у димі заникнуть вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Позичає безбожний — і не віддає, а праведний милість висві́дчує та роздає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'бо благословенні від Нього вспадку́ють землю, а прокля́ті від Нього — пони́щені будуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Від Господа кроки люди́ни побожної ставляться міцно, і Він любить дорогу її;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'коли ж упаде́, то не буде поки́нена, бо руку її підпирає Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Я був молодий і поста́рівся, та не бачив я праведного, щоб опу́щений був, ні нащадків його, щоб хліба просили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Кожен день виявляє він милість та позичає, і над пото́мством його благословення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Ухиляйся від злого та добре чини, та й навіки живи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Бо любить Господь справедливість, і Він богобі́йних Своїх не покине, — вони будуть навіки бере́жені, а насіння безбожних загине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Успадку́ють праведні землю, і повік будуть жити на ній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Уста праведного кажуть мудрість, язик же його промовляє про право,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Закон Бога його — в його серці, кроки його не спіткну́ться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'А безбожний чату́є на праведного, і пильнує забити його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 33, 'та Господь не зоставить його в руках того, і несправедливим не вчи́нить його, коли буде судити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 34, 'Надійся на Господа, та держися дороги Його, — і піднесе Він тебе, щоб успадкува́ти землю, ти бачитимеш, як пони́жені будуть безбожні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 35, 'Я бачив безбожного, що збуджував по́страх, що розкорени́вся, немов саморосле зелене те дерево,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 36, 'та він промину́в, — й ось немає його, і шукав я його, — й не знайшов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 37, 'Бережи непови́нного та дивися на праведного, бо люди́ні споко́ю належить майбу́тність,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 38, 'переступники ж ра́зом понищені будуть, — майбутність безбожних загине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 39, 'А спасі́ння праведних — від Господа, Він їхня тверди́ня за ча́с лихолі́ття,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 40, 'і Господь їм поможе та їх порятує, ви́зволить їх від безбожних і їх збереже, — бо вдавались до Нього вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Псалом Давидів. На па́м\'ятку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Господи, не карай мене в гніві Своїм, і не завдава́й мені кари в Своїм пересе́рді,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'бо проши́ли мене Твої стріли, і рука Твоя тяжко спусти́лась на мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Від гніву Твого нема ці́лого місця на тілі моїм, немає споко́ю в костя́х моїх через мій гріх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'бо провини мої переросли́ мою го́лову, як великий тяга́р, вони тяжчі над сили мої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'смердять та гниють мої рани з глупо́ти моєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Ско́рчений я, і над міру похи́лений, цілий день я тиняюсь сумни́й,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'бо нутро́ моє повне запа́лення, і в тілі моїм нема ці́лого місця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Обезси́лений я й перемучений тяжко, рида́ю від сто́гону серця свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Господи, всі бажа́ння мої — перед Тобою, зідха́ння ж моє не сховалось від Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Сильно тріпо́четься серце моє, опустила мене моя сила, навіть ясність оче́й моїх — і вона не зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Дру́зі мої й мої при́ятелі поставали здаля́ від моєї біди, а ближні мої поставали опо́даль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Тене́та розставили ті, хто чатує на душу мою, а ті, хто бажає нещастя мені, говорять прокля́ття, і ввесь день вимишляють зрадли́ве!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'А я, мов глухий, вже не чую, і мов той німий, який уст своїх не відкриває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'I я став, мов люди́на, що нічо́го не чує і в у́стах своїх оправда́ння не має,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'бо на Тебе наді́юся я, Господи, Ти відповіси́, Господи, Боже мій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Бо сказав я: „Нехай не поті́шаться з мене, нехай не несуться вони понад мене, коли послизне́ться нога моя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Бо я до упадку готовий, і передо мною постійно недуга моя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'бо провину свою визнаю́, журюся гріхом своїм я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'А мої вороги проживають, міцні́ють, і без причини помно́жилися мої не́други.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Ті ж, хто відплачує злом за добро, обчо́рнюють мене, бо женусь за добром.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 22, 'Не покинь мене, Господи, Боже мій, не віддаляйся від мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 23, 'поспіши мені на допомогу, Господи, — Ти спасі́ння моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Для дириґента хору. Єдуту́на. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Я сказав: „Пильнувати я буду доро́ги свої, щоб своїм язико́м не грішити, накладу я вузде́чку на уста свої, поки передо мною безбожний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Занімів я в мовча́нні, замовк про добро, а мій біль був подра́жнений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Розпалилося серце моє у моє́му нутрі, палає огонь від мого розду́мування. Я став говорити своїм язико́м:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, '„Повідоми́ мене, Господи, про кінець мій та про днів моїх міру, яка то вона, — нехай знаю, коли я помру́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Ось відмі́ряв долонею Ти мої дні, а мій вік — як ніщо́ проти Тебе, і тільки марно́та сама — кожна люди́на жива! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'У темно́ті лиш ходить люди́на, клопо́четься тільки про ма́рне: грома́дить вона, — та не знає, хто зво́зити буде оте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'А тепер на що́ маю наді́ятись, Господи? Надія моя — на Тебе вона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Від усіх моїх про́гріхів ви́зволи мене, не чини мене по́сміхом для нерозумного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Занімі́в я та уст своїх не відкриваю, бо Ти те вчинив, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'забери Ти від мене Свій до́торк, від порази Твоєї руки я кінчаюсь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Ти караєш люди́ну докорами за беззако́ння, Ти знищив, як міль, прива́бність її, — кожна люди́на — направду марно́та! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Вислухай, Господи, молитву мою, і почуй блага́ння моє, не будь мовчазни́й до моєї сльози́, бо прихо́дько я в Тебе, мандрівни́к, як батьки́ мої всі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Відверни гнів від мене — і я підкріплю́ся, перше ніж відійду́, — і не буде мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Непохитно наді́юсь на Господа, і Він прихилився до мене, і блага́ння моє Він почув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Витяг мене Він із згу́бної ями, із багна́ болоти́стого, і поставив на скелі ноги мої, і зміцнив мої сто́пи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'і дав пісню нову́ в мої уста, для нашого Бога хвалу́, — нехай бачать багато-хто й по́страх хай мають, і хай вони мають надію на Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Блаженна люди́на, що Бога вчинила своєю тверди́нею, і не зверта́лась до пи́шних та тих, що вони до неправди схиляються!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Багато вчинив Ти, о Господи, Боже мій, Твої чу́да й думки Твої — тільки про нас, нема Тобі рівного! Я хотів би все це показати й про це розказати, та воно численні́ше, щоб можна його розпові́сти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Жертви й прино́шення Ти не схотів, Ти розкрив мені уші, цілопа́лення й жертви покутної Ти не жадав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Тоді я сказав: „Ось я прийшов із зво́єм книжки, про мене написаної“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Твою волю чини́ти, мій Боже, я хо́чу, і Зако́н Твій — у мене в се́рці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Я проповідував правду в великому зборі, — ото, своїх уст не ув\'я́знюю я, Господи, знаєш Ти, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'справедливість Твою не ховав я в сере́дині серця свого, про вірність Твою та спасі́ння Твоє я звіщав, не таїв я про милість Твою та про правду Твою на великім зібра́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Тому, Господи, не ув\'язни́ милосердя Свого від мене, а милість та правда Твоя нехай за́вжди мене стережу́ть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'бо нещастя без ліку мене оточи́ли, беззако́ння мої досягли́ вже мене, так що й бачити не мо́жу, — вони численнішими стали за воло́сся на моїй голові, і серце моє опустило мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Зволь спасти мене, Господи, Господи, поспіши ж бо на поміч мені, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'нехай посоро́млені будуть, і хай зга́ньблені будуть усі, хто шукає моєї душі, щоб схопи́ти її! Нехай подадуться назад, і нехай посоро́млені бу́дуть, хто бажає для мене лихого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Бодай скам\'яні́ли від со́рому ті, хто говорить до мене: „Ага! Ага!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Нехай ті́шаться та веселя́ться Тобою всі ті, хто шукає Тебе та хто любить спасі́ння Твоє, нехай за́вжди говорять: „Хай буде великий Госпо́дь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'А я вбогий та бідний, — за мене подбає Господь: моя поміч і мій оборо́нець — то Ти, Боже мій, — не спізня́йся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Блаже́нний, хто дбає про вбогого, — в день нещастя Господь порятує його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Господь берегти́ме його та його оживля́тиме, буде блаженний такий на землі, і Він не видасть його на пота́лу його ворогам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'На ложі неду́ги подасть йому сили Госпо́дь, — усе ложе йому перемінить в неду́зі його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Я промовив був: „Господи, май же Ти ми́лість до мене, ви́лікуй душу мою, бо я перед Тобою згрішив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Вороги мої кажуть на мене лихе́: „Коли вмре та загине іме́ння його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'А коли хто прихо́дить відві́дати, — мовить марне́: його серце збирає для себе лихе, і як вийде надві́р, то говорить про те.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Всі мої вороги між собою шепо́чуться ра́зом на мене, на ме́не лихе́ замишля́ють:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, '„Негі́дна річ тисне його, а що́ він поклався — то більше не встане!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Навіть при́ятель мій, на якого наді́явся я, що мій хліб споживав, — підняв проти мене п\'яту́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Але, Господи, помилуй мене, і мене підійми́, — і я їм відплачу́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'із то́го довідаюся, що Ти любиш мене, коли надо мною сурми́ти не буде мій ворог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'А я — через неви́нність мою Ти підси́лиш мене, і перед обличчям Своїм ти поста́виш навіки мене́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Благословенний Господь, Бог Ізраїлів, від віку й до віку! Амі́нь і амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Для дириґента хору. Псало́м навча́льний, синів Коре́євих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Як ли́не той о́лень до водних потоків, так лине до Тебе, о Боже, душа моя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'душа моя спра́гнена Бога, Бога Живого! Коли я прийду́ й появлю́сь перед Божим лицем?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Сльоза́ моя стала для мене пожи́вою вдень та вночі, коли кажуть мені цілий день: „Де твій Бог?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Як про це пригадаю, то душу свою виливаю, як я в многолю́дді ходив, і водив їх до Божого дому, із голосом співу й подяки святко́вого на́товпу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Чого, душе моя, ти сумуєш, і чого́ ти в мені непоко́їшся? Май надію на Бога, бо я Йому бу́ду ще дя́кувати за спасі́ння Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Мій Боже, душа моя ту́жить в мені, бо я пам\'ята́ю про Тебе з країни Йорда́ну й Гермо́ну, із гори із Міц\'а́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Приклика́є безо́дня безо́дню на гу́ркіт Твоїх водоспа́дів, усі вали́ Твої й хвилі Твої перейшли́ надо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Удень виявляє Господь Свою милість, уночі ж Його пісня зо мною, молитва до Бога мого життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Повім я до Бога: „Ти Скеле моя, чому́ Ти про мене забув? Чого я блукаю сумни́й через у́тиск ворожий?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Ніби кості ламають мені, коли вороги мої лають мене, коли кажуть мені цілий день: „Де твій Бог?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Чого, душе моя, ти суму́єш, і чого́ ти в мені непоко́їшся? Май надію на Бога, бо я Йому бу́ду ще дя́кувати за спасі́ння Його, мого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Розсуди́ мене, Боже, й справу́йся за справу мою із людьми́ небогобі́йними, визволь мене від люди́ни обмани та кривди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Бож Бог Ти моєї тверди́ні, чого́ ж Ти покинув мене? Чого́ я блукаю сумни́й через у́тиск ворожий?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Пошли Своє світло та правду Свою, — вони мене бу́дуть прова́дити, вони запрова́дять мене до Твоєї святої гори та до місць пробува́ння Твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'I нехай я дістанусь до Божого же́ртівннка, до Бога розради п потіхи моєї, — і буду на а́рфі хвали́ти Тебе, Боже, Боже Ти мій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Чого, душе́ моя, ти сумуєш, і чого́ ти в мені непоко́їшся? Май наді́ю на Бога, бо я Йому буду ще дя́кувати за спасіння Його, мого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Для дириґента хору. Синів Коре́євих. Псало́м навча́льний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Боже, своїми ушима ми чули, наші батьки́ нам оповіда́ли: велике Ти ді́ло вчинив за їхніх днів, за днів старода́вніх:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Ти вигнав пога́нів Своєю рукою, а їх осади́в, понищив народи, а їх Ти поши́рив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Не мече́м бо своїм вони землю посі́ли, і їхнє раме́но їм не помогло́, — а прави́ця Твоя та раме́но Твоє, та Світло обличчя Твого́, бо Ти їх уподо́бав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Ти Сам — Цар мій, о Боже, звели ж про спасі́ння для Якова:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Тобою поб\'ємо своїх ворогів, Ім\'я́м Твоїм будемо топта́ти повсталих на нас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'бо я буду наді́ятися не на лу́ка свого́, і мій меч не поможе мені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'але Ти нас спасеш від противників наших, і наших нена́висників засоро́миш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Ми хва́лимось Богом щодня́, і пові́ки Ім\'я́ Твоє сла́вимо, Се́ла, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'та однак Ти покинув і нас засоро́мив, і вже не вихо́диш із нашими ві́йськами:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Ти вчинив, що від ворога ми оберну́лись назад, а наші нена́висники грабува́ли собі наш маєток.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Ти віддав нас на по́їд, немов тих ове́чок, і нас розпоро́шив посеред наро́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Ти за бе́зцін продав Свій наро́д, і ціни́ йому не побільши́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 14, 'Ти нас нашим сусідам віддав на знева́гу, на нару́гу та по́сміх для наших око́лиць,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 15, 'Ти нас учинив за прислі́в\'я пога́нам, і головою хита́ють наро́ди на нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 16, 'Передо мною щоденно безче́стя моє, і сором вкриває обличчя моє, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 17, 'через голос того, хто лає мене й проклинає, через ворога й ме́сника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 18, 'Прийшло було все це на нас, та ми не забу́ли про Тебе, й заповіту Твого не пору́шили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 19, 'не вступи́лось назад наше серце, і не відхили́вся наш крок від Твоєї доро́ги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 20, 'Хоч у місце шака́лів Ти ви́пхнув був нас, і прикрив був нас сме́ртною тінню, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 21, 'чи й тоді ми забули Ім\'я́ Бога нашого, і руки свої простягну́ли до Бога чужого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 22, 'Таж про те Бог дові́дається, бо Він знає тає́мності серця, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 23, 'що нас побива́ють за Тебе щоденно, пораховано нас, як овечок жерто́вних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 24, 'Прокинься ж, — для чо́го Ти, Господи, спиш? Пробуди́ся, — не кидай наза́вжди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 25, 'Для чо́го обличчя Своє Ти ховаєш, забуваєш про нашу недолю та нашу тісно́ту?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 26, 'Бо душа наша зни́жилася аж до по́роху, а живіт наш приліг до землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 27, 'Устань же, о По́моче наша, і ви́купи нас через милість Свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Для дириґента хору. На „Лілеї“. Синів Коре́євих. Псалом навча́льний. Пісня любови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Моє серце брини́ть добрим словом, проказую я: Для Царя мої тво́ри, мій язик — мов перо скоропи́сця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Ти кращий від лю́дських синів, в Твоїх устах розлита краса́ та добро́, тому благослови́в Бог навіки Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Прив\'яжи до стегна́ Свого, Сильний, Свого меча, красу́ Свою́ та вели́чність Свою́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'і в вели́чності Своїй сідай, та й ве́рхи помчися за справи правди, і ла́гідности та справедливости, — і на́вчить Тебе страшних чинів прави́ця Твоя́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Твої стрі́ли наго́стрені, — а від них під Тобою наро́ди попа́дають, — у серце Царськи́х ворогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Престол Твій, о Боже, на вічні віки́, берло правди — берло Царства Твого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Ти полюбив справедливість, а беззако́ння знена́видів, тому́ намасти́в Тебе Бог, Твій Бог, оливою радости понад друзів Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Ми́ро, ало́е й кассі́я — всі ша́ти Твої, а з палат із слоно́вої кости — струни Тебе звесели́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Серед ска́рбів Твоїх — царські до́чки, по правиці Твоїй стала цариця в офі́рському щирому золоті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Слухай, до́чко, й побач, і нахили своє ухо, — і забудь свій наро́д і дім батька свого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'А Цар буде жадати твоєї краси́, бо Він — твій Госпо́дь, а ти до землі Йому кланяйся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'А Ти́рська дочка́ прийде з да́ром, будуть благати тебе найбагатші з наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Вся оздо́ба царсько́ї дочки́ — усере́дині, шата ж її погапто́вана золотом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'У ша́ти гапто́вані вбрану прова́дять її до Царя, за нею дівча́та, подру́ги її, до Тебе прова́джені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Провадять їх з ра́дощами та поті́хою, — у палату царську́ вони ві́йдуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Замість батькі́в Твоїх бу́дуть сини́ Твої, — їх по ці́лій землі Ти поставиш воло́дарями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Я буду Ім\'я́ Твоє зга́дувати по всіх поколіннях, тому́ то наро́ди по вічні віки Тебе сла́вити будуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Для дириґента хору. Синів Коре́євих. На спів „Аламот“. Пісня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Бог для нас — охоро́на та сила, допомо́га в недолях, що часто трапляються,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'тому́ не лякаємось ми, як трясе́ться земля, і коли го́ри зсува́ються в серце морі́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Шумлять і киплять Його во́ди, через ве́лич Його тремтя́ть го́ри. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Річка, — відно́ги її веселя́ть місто Боже, найсвятіше із місць пробува́ння Всеви́шнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 6, 'Бог серед нього, — нехай не хитається, Бог поможе йому́, коли ра́нок настане.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 7, 'Шуміли наро́ди, хиталися ца́рства, а Він голос подав Свій — і земля розпливла́ся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 8, 'З нами Господь Савао́т, наша тверди́ня — Бог Яковів. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 9, 'Ідіть, оглядайте Господні діла, — які руйнува́ння вчинив на землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 10, 'Аж до кра́ю землі припиняє Він ві́йни, ламає Він лука й торо́щить списа, палить огнем колесни́ці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 11, '„Вгамуйтесь та знайте, що Бог Я, піднесу́сь між наро́дами, піднесу́сь на землі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 12, 'З нами Господь Савао́т, наша тверди́ня — Бог Яковів! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Для дириґента хору. Синів Коре́євих, Псалом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Всі наро́ди, — плещі́ть у долоні, покли́куйте Богові голосом ра́дости,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'грізни́й бо Всевишній Госпо́дь, Цар великий всієї землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Він наро́ди під нас підбиває, а поган — нам під но́ги,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Він нашу спа́дщину для нас вибирає, вели́чність для Якова, що його полюбив. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Бог виступає при радісних о́криках, Господь — при голосі ро́га.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Співайте Богові нашому, співайте, співайте Царе́ві нашому, співайте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'бо Бог — Цар усієї землі, співайте навча́льний псало́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Бог зацарюва́в над наро́дами, Бог сів на святому Своєму престо́лі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Зібрались влади́ки народів, народ Бога Авраамового, як Божі щити́ на землі, — між ними Він сильно звели́чений!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Пісня. Псалом синів Коре́євих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Великий Госпо́дь і просла́влений ве́льми в місті нашого Бога, на святій Своїй горі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Препи́шна країна, розра́да всієї землі, — то Сіонська гора, на півні́чних око́лицях, місто Царя можновла́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Бог у хра́мах Своїх, за твердиню Він зна́ний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Бо царі ось зібрались, ішли вони ра́зом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'але, як побачили, то здивува́лись, полякалися та й розпоро́шились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Обгорнув їх там страх, немов біль породі́ллю;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 8, 'Ти східнім вітром розбив кораблі ті Тарші́ські.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 9, 'Як ми чули, так бачили в місті Господа Савао́та, у місті нашого Бога, — Бог міцно поставить навіки його́! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 10, 'Розмишля́ли ми, Боже, про ми́лість Твою серед храму Твого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 11, 'Як Ім\'я́ Твоє, Боже, так слава Твоя — аж по кі́нці землі, справедли́вости повна прави́ця Твоя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 12, 'Нехай весели́ться Сіонська гора, Юдині до́чки хай тішаться через Твої правосу́ддя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 13, 'Оточі́те Сіо́н й обступі́те його́, полічіть його ба́шти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 14, 'зверні́те увагу на ва́ла його, високість палати його пообмірюйте, щоб розповісти́ поколі́нню насту́пному,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 15, 'бо Цей Бог — то наш Бог на вічні віки́, Він буде прова́дити нас аж до смерти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Для дириґента хору. Синів Коре́євих. Псалом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Слухайте це, всі наро́ди, візьміть до ушей, усі ме́шканці все́світу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'і лю́дські сини й сини му́жів, ра́зом багатий та вбогий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, '— мої уста казатимуть мудрість, думка ж се́рця мого — розумність,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'нахилю́ своє ухо до при́казки, розв\'яжу́ свою за́гадку лі́рою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Чому маю боятись у день лихолі́ття, як стане круг мене неправда моїх ошука́нців,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'які на бага́тство своє покладають надію, і своїми доста́тками хва́ляться?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Але жодна люди́на не ви́купить брата, не дасть його ви́купу Богові, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'бо ви́куп їхніх душ дорогий, і не перестане навіки, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'щоб міг він ще жити навіки й не бачити гро́бу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Та люди побачать, що мудрі вмирають так само, як гинуть невіглас та не́ук, і лиша́ють для інших багатство своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Вони ду́мають, ніби доми́ їхні навіки, місця́ їхнього заме́шкання — з роду до роду, імена́ми своїми звуть землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'та не зостається в пошані люди́на, — подібна худобі, що гине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Така їхня дорога — глупо́та для них, та за ними йдуть ті, хто кохає їхню думку. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Вони зі́йдуть в шеол, — і смерть їх пасе, немов вівці, а праведники запанують над ними від ра́ння; подоба їхня знищиться, шео́л буде мешканням для них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Та визволить Бог мою душу із влади шео́лу, бо Він мене ві́зьме! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Не лякайся, коли багатіє люди́на, коли збі́льшується слава дому її,—');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'бо, вмираючи, не забере вона всьо́го, її слава не пі́де за нею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Хоч вона свою душу за життя свого хва́лить, і славлять тебе, як для себе ти чиниш добро, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'вона при́йде до роду батьків своїх, що світла вони не побачать навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Люди́на в пошані, але нерозумна, — подібна худобі, що гине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Псалом Асафів. Прорік Бог над богами — Госпо́дь, і землю покликав від схід сонця і аж до захо́ду його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Із Сіону, корони краси́, Бог явився в промі́нні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Прихо́дить наш Бог, — і не буде мовчати: палю́чий огонь перед Ним, а круг Нього все бу́риться сильно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Він покличе згори́ небеса́, і землю — наро́д Свій судити:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, '„Позбирайте для Мене побожних Моїх, що над жертвою склали заповіта зо Мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'І небеса́ звістять правду Його, що Бог — Він суддя. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, '„Слухай же ти, Мій наро́де, бо буду ось Я говорити, Ізра́їлеві, і буду сві́дчить на тебе: Бог, Бог твій Я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Я бу́ду карта́ти тебе не за жертви твої, — бо все передо Мною твої цілопа́лення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'не візьму́ Я бичка з твого дому, ні козлів із коша́р твоїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'бо належить Мені вся лісна́ звірина́ та худоба із тисячі гір,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Я знаю все пта́ство гірське́, і звір польови́й при Мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Якби був Я голодний, тобі б не сказав, — бо Моя вся вселе́нна й усе, що на ній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Чи Я м\'ясо бичкі́в спожива́ю, і чи п\'ю кров козлів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Принось Богові в жертву подя́ку, і виконуй свої обітниці Всеви́шньому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'і до Мене поклич в день недолі, — Я тебе порятую, ти ж просла́виш Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'А до грішника Бог промовляє: „Чого́ про устави Мої розповідаєш, і чого́ заповіта Мого на уста́х своїх но́сиш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Ти ж науку знена́видів, і поза себе слова́ Мої ви́кинув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Як ти злодія бачив, то бі́гав із ним, і з перелюбниками накладав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Свої уста пускаєш на зло, і язик твій ома́ну плете́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Ти сидиш, проти брата свого нагово́рюєш, поголо́ски пускаєш про сина своєї матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Оце ти робив, Я ж мовчав, і ти ду́мав, що Я такий са́мий, як ти. Тому буду картати тебе, і ви́ложу все перед очі твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Зрозумійте ж це ви, що забуваєте Бога, щоб Я не схопи́в, — бо не буде кому рятува́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Хто жертву подяки прино́сить, той шанує Мене; а хто на дорогу Свою уважа́є, Боже спасі́ння йому покажу́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Для дириґента хору. Псалом Давидів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'коли до нього прийшов пророк Ната́н, як Давид увійшов був до Вірсаві́ї');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Помилуй мене, Боже, з великої милости Твоєї, і з великого милосердя Свого загла́дь беззако́ння мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Обмий мене зо́всім з мого беззако́ння, й очи́сти мене від мого гріха́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'бо свої беззако́ння я знаю, а мій гріх передо мною пості́йно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Тобі, одно́му Тобі я згрішив, і перед очима Твоїми лука́ве вчинив, тому́ справедливий Ти будеш у мові Своїй, бездога́нний у су́ді Своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Отож я в беззако́нні наро́джений, і в гріху́ зачала́ мене мати моя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Ото, полюбив єси правду в глиби́нах, і в таємних реча́х виявляєш премудрість мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Очи́сти ісо́пом мене, — і буду я чистий, обмий Ти мене — і я стану біліший від снігу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Дай почути мені втіху й радість, — і раді́тимуть кості, що Ти покруши́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Обличчя Своє заховай від гріхів моїх, і всі беззако́ння мої позагла́джуй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Серце чисте створи мені, Боже, і трива́лого духа в моєму нутрі́ віднови́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Не відки́нь мене від Свого лиця, й не бери Свого Духа Святого від мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Верни мені радість спасі́ння Твого́, і зла́гідним духом підтримай мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Я буду навча́ти беззако́нців доріг Твоїх, — і наве́рнуться грішні до Те́бе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Визволь мене від пере́ступу кро́вного, Боже, Боже спасі́ння мого, мій язик нехай сла́вить Твою справедливість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Господи, відкрий мої уста, і язик мій звістить Тобі хвалу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'бо Ти жертви не пра́гнеш, а дам цілопа́лення, — то не любе воно Тобі буде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Жертва Бо́гові — зла́маний Дух; серцем зла́маним та упоко́реним Ти не погордуєш, Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Ущасли́в Своїм благоволі́нням Сіон, збудуй му́ри для Єрусали́му, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'тоді Ти полюбиш Собі жертви правди, цілопа́лення та прино́шення, тоді покладуть на Твій ві́втар тельців!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Для дириґента хору. Псалом навча́льний Давидів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'як прийшов був ідуме́янин Доеґ та й Саулові був оповів, і до нього сказав: „Давид увійшов до дому Ахіме́леха“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Чого хва́лишся злом, о могу́тній? Цілий де́нь Божа милість зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Замишляє лукавство язик твій, як та бритва наго́стрена ти, що чиниш обману!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Ти зло полюбив над добро, а неправду — більш, як правду казати, — Се́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'ти любиш усякі шкідливі слова́, ти язи́ку обманний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Отож, Бог зруйнує наза́вжди тебе, тебе викине й вирве з намету тебе, й тебе викоренить із країни життя. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'І побачать це пра́ведні, й будуть боятись, і будуть сміятися з нього:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '„Ось муж, що Бога не чинить своєю тверди́нею, та на великість багатства свого покладає надію, втікає до злого свого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'А я — як зелена оли́вка у Божому домі, наді́юсь на Божую милість на вічні віки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Буду сла́вити вічно Тебе, що вчинив Ти оце, і про йме́ння Твоє буду звіщати побожним Твоїм, що добре воно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Для дириґента хору. На „Махалат“. Навча́льний псало́м. Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Безумний говорить у серці своїм: „Нема Бога“! Зіпсу́лись вони, і несправедливість обри́дливу чинять, нема доброчи́нця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Бог зо́рить із неба на лю́дських синів, щоб поба́чити, чи є там розумний, що Бога шукає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Усі повідступа́ли, разом стали оги́дними, нема доброчи́нця, нема ні одно́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Чи ж не розуміють оті, хто беззако́ння вчиняє, що мій люд поїдають? Вони спожива́ють хліб Божий, та не кличуть Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Тоді настраши́лися стра́хом вони, хоч страху не було, бо розсипав Бог кості того, хто тебе оточив був, — ти їх посоро́мив, бо ними пого́рдував Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Аби то Він дав із Сіону спасі́ння Ізраїлеві! Як долю Свого народу поверне Господь, то радітиме Яків, утіша́тися буде Ізра́їль!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 1, 'Для дириґента хору. На неґінах. Псало́м навча́льний Давидів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 2, 'як зіфе́яни прийшли були та сказали Саулові: „Ось Давид поміж нами ховається!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 3, 'Спаси мене, Боже, Іме́нням Своїм, і міццю Своєю мене оправда́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 4, 'Вислухай, Боже, молитву мою, нахили Своє ухо до слів моїх уст,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 5, 'бо чужи́нці повстали на мене, розбиша́ки ж шукають моєї душі, — вони Бога не ставили перед собою. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 6, 'Ось Бог помагає мені, Господь серед тих, хто підтримує душу мою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 7, 'Хай пове́рнеться зло на моїх ворогів, Своєю правдою ви́нищи їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 8, 'В доброві́льному да́рі я жертву Тобі принесу́, Ім\'я́ Твоє, Господи, сла́вити буду, що добре воно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 53, 9, 'бо мене воно визволило від усяких нещасть, і я бачу зане́пад моїх ворогів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 1, 'Для дириґента хору. На неґінах. Навчальний Давидів псалом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 2, 'Вислухай, Боже, молитву мою й від блага́ння мого не ховайся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 3, 'Прислу́хайсь до мене й подай мені відповідь, — я блукаю у сму́тку своїм і стогну́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 4, 'від крику воро́жого, від у́тисків грішного, бо гріх накида́ють на мене вони, і в гніві мене переслі́дують.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 5, 'Тремтить моє серце в мені, і стра́хи смерте́льні напали на мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 6, 'страх та тремті́ння на мене найшли́, і тривога мене обгорну́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 7, 'І сказав я: „Коли б я мав крила, немов та голубка, то я полетів би й спочив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 8, 'Отож, помандру́ю дале́ко, пробува́тиму я на пустині. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 9, 'Поспішу́ собі, щоб утекти́ перед вітром бурхли́вим та бурею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 10, 'Вигуби, Господи, та погуби язика́ їхнього, бо в місті я бачив наси́льство та сва́рку,—');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 11, 'вони ходять удень та вночі коло нього на му́рах його, а гріх та неправда всере́дині в ньому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 12, 'нещастя всере́дині в ньому, а з вулиць його не вихо́дять наси́лля й обма́на,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 13, 'бож не ворог злорі́чить на мене, — це я переніс би, — і не нена́висник мій побільши́всь надо мною, я сховався б від нього, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 14, 'але ти, — чоловік мені рі́вня, мій прия́тель близьки́й і знайо́мий мені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 15, 'з яким со́лодко щиру розмову прова́димо, і ходимо до Божого дому серед бурхли́вого на́товпу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 16, 'Нехай же впаде на них смерть, нехай зі́йдуть вони до шео́лу живими, — бо зло в їхнім ме́шканні, у їхній сере́дині!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 17, 'Я кличу до Бога, і Госпо́дь урятує мене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 18, 'уве́чорі, вра́нці й опі́вдні я скаржусь й зідхаю, — і Він ви́слухає мого го́лосу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 19, 'У мирі Він викупить душу мою, щоб до мене вони не зближа́лись, бо багато було їх на мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 20, 'Бог ви́слухає, і їм Той відпові́сть, Хто відві́ку сидить на престо́лі, Се́ла, бо немає у них перемін, і Бога вони не боя́ться, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 21, 'во́рог ви́тягнув ру́ки свої проти тих, що в споко́ї жили́ з ним, він зганьби́в заповіта свого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 22, 'його уста гладе́нькі, як масло, — та сва́рка у серці його, від оливи м\'які́ші слова́ його, та вони — як мечі́ ті ого́лені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 23, 'Свого тягара́ поклади ти на Господа, — і тебе Він підтри́має, Він ніко́ли не дасть захита́тися праведному!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 54, 24, 'А Ти їх, Боже мій, поскида́єш до ями поги́белі! Люди чи́нів кривавих й обмани, — бода́й своїх днів вони не дожили навіть до половини, а я поклада́ю надію на Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 1, 'Для дириґента хору. На „Німа голубка вдалечині“. Золотий Давидів псалом, коли филисти́мляни захопи́ли були його в Ґа́ті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 2, 'Помилуй мене, Боже, бо то́пче мене чоловік, — цілий день він воює та ти́сне мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 3, 'Чату́ють мої вороги цілий день, бо багато таких, що воюють завзя́то на мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 4, 'Того дня, коли страх обгорта́є мене, я надію на Тебе кладу́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 5, 'я в Бозі хвали́тиму слово Його, на Бога надію кладу, й не боюся, — що тіло учи́нить мені?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 6, 'Цілий день біль прино́сять слова́ мої, усі їхні думки́ проти мене на зло:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 7, 'слідкують, ховаються, пильнують вони мої сто́пи... Як чатують на душу мою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 8, 'так Ти через гріх віджени́ їх, пониж, Боже, людей в Своїм гніві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 9, 'Полічив Ти тиня́ння моє, помісти́ ж мої сльози перед Собою, чи ж вони не запи́сані в книзі Твоїй?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 10, 'Тоді то мої вороги́ повтікають назад, того дня, як я кли́кати буду. Те я знаю, що Бог при мені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 11, 'і в Бозі я справу свою докінчу́, докінчу́ я в Господі справу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 12, 'На Бога надію кладу́ й не боюсь, — що́ люди́на учи́нить мені?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 13, 'На мені зостаються, о Боже, прися́ги Тобі, та для Тебе я ви́повню жертви хвали́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 55, 14, 'Як Ти спас мою душу від смерти, то хіба ж не спасеш моїх ніг від паді́ння, щоб у світлі життя я ходив перед Богом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 1, 'Для дириґента хору. На спів: „Не вигуби“. Золотий псалом Давидів, коли він утікав від Саула в пече́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 2, 'Помилуй мене, Боже, помилуй мене, бо до Тебе вдається душа моя, і в тіні́ Твоїх крил я сховаюсь, аж поки нещастя мине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 3, 'Я кличу до Бога Всевишнього, до Бога, що чинить для мене добро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 4, 'Він пошле з небес — і врятує мене, Він пога́ньбить того, хто чату́є на мене. Се́ла. Бог пошле Свою милість та правду Свою');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 5, 'на душу мою. Знахо́джуся я серед ле́вів, що лю́дських синів пожирають, їхні зуби — як спис той та стрі́ли, а їхній язик — гострий меч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 6, 'Піднеси́ся ж, о Боже, над небо, — а слава Твоя над всією землею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 7, 'Вороги пригото́вили па́стку для стіп моїх, душу мою нахи́лили, вони ви́копали вовчу яму для мене, — і попа́дали в неї самі! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 8, 'Моє серце зміцни́лося, Боже, зміцни́лося серце моє, — я буду співати та сла́вити Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 9, 'Збудися ж ти, хва́ло моя, пробудися ж ти, а́рфо та ци́тро, — я буду буди́ти досві́тню зорю́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 10, 'Я буду Тебе вихваляти, о Господи, серед наро́дів, я буду співати Тобі між племе́нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 11, 'бо Твоє милосердя велике — воно аж до неба, а правда Твоя — аж до хмар!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 56, 12, 'Піднеси́ся ж, о Боже, над небо, а слава Твоя — над всією землею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 1, 'Для дириґента хору. На спів: „Не вигуби“. Золотий псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 2, 'Чи ж то справді ви, можні, говорите правду, чи лю́дських синів слушно судите?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 3, 'Отже, у серці ви чините кривди, дорогу наси́льства рук ваших тору́єте ви на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 4, 'Від лоня ще матернього — вже відда́лені несправедливі, з утро́би ще матерньої заблуди́лися неправдомо́вці, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 5, 'їхня отрута така, як отрута зміїна, як отрута глухої гадюки, що ухо своє затуля́є,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 6, 'що не слухає голосу заклиначі́в, чарівника́, в чарах впра́вного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 7, 'Поруйнуй, Боже, зуби їхні в їхніх уста́х, левчука́м розбий, Господи, ще́лепи, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 8, 'нехай розпливуться, немов та вода, що собі розтіка́ється, хай пов\'я́нуть вони, як трава по дорозі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 9, 'бодай стали, немов той слима́к, що в своїй слизоті́ розпускається, щоб сонця не бачили, як мертвий отой плід у жінки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 10, 'Поки почують терни́ну запа́лену ваші горшки, — нехай буря її рознесе, чи свіжу, чи спа́лену!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 11, 'А праведний ті́шитись буде, бо помсту побачить, у кро́ві безбожного сто́пи свої він обмиє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 57, 12, 'І скаже люди́на: „Поправді є плід справедливому, справді є Бог, — суддя на землі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 1, 'Для дириґента хору. На спів: „Не вигуби“. Золотий псалом Давидів, коли послав був Саул, і стерегли́ його дім, щоб убити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 2, 'Ви́зволь мене від моїх ворогі́в, о мій Боже, від напасникі́в моїх охорони́ Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 3, 'Ви́зволь мене від злочи́нців, і спаси мене від кровоже́рних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 4, 'бо ось причаї́лись на душу мою, на мене збираються сильні, — не моя в тім провина, о Господи, і не мій гріх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 5, 'Без моєї провини вони он збігаються та готу́ються, — устань же назу́стріч мені та побач!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 6, 'І Ти, Господи, Боже Саваоте, Боже Ізраїлів, збудися, щоб покара́ти всіх поган, — і не помилуй ніко́го із зра́дників злих! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 7, 'На́двечір вони поверта́ються, ски́глять, як пес, і перебігають по місту,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 8, 'й ось слова виверга́ють уста́ми своїми, мечі в їхніх губах, — та хто це почує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 9, 'Але посмієшся з них, Господи, і всіх поган засоро́миш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 10, 'Тверди́не моя, я Тебе пильнува́тиму, — бо Бог оборо́на моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 11, 'Мій Бог, — Його милість мене попере́дила, Бог учинить мені, що побачу паді́ння своїх ворогів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 12, 'Не вбива́й їх, щоб наро́д мій цього не забув, — міццю Своєю розвій їх і зниж їх, о щите наш, Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 13, 'Гріх їхніх уст — слово губ їхніх, і нехай вони схо́плені будуть своєю пихо́ю, і за клятву й брехню, яку кажуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 14, 'У гніві їх знищ, знищ — і хай їх не буде, і хай знають вони, що царю́є Бог в Якові, аж до кі́нців землі! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 15, 'А на́двечір вони поверта́ються, ски́глять, як пес, і перебігають по місту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 16, 'Вони ве́штатись будуть, щоб їсти, коли ж не наїдя́ться, то ска́ржитись будуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 17, 'А я буду співати про силу Твою, буду радісно вра́нці хвалити Твою милісти, бо для мене Ти був в день недолі моєї тверди́нею й за́хистом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 18, 'Тверди́не моя, — до Тебе співати я буду, бо Бог оборо́на моя, милости́вий мій Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 58, 19, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 1, 'Для дириґента хору. На спів: „Лілея свідчення“. Золотий псалом Давидів для навча́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 2, 'коли він підпалив був Ара́м двох річо́к і Ара́м Цови́, і коли вернувся Йоав і побив Едо́ма в Соляній долині, дванадцять тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 3, 'Боже, покинув Ти нас, розпоро́шив Ти нас, Ти нагні́вався був, — поверни́ся ж до нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 4, 'Ти землею затряс, і її розірвав, — уздоров же ула́мки її, бо вона захита́лась!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 5, 'Ти вчинив, що наро́д Твій побачив тяжке́, напоїв нас отру́тним вином.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 6, 'Ти дав пра́пора тим, хто боїться Тебе, щоб збирались вони перед правдою. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 7, 'Щоб любі Твої були ви́зволені, Своєю правицею допоможи́, й обізви́ся до нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 8, 'У святині Своїй Бог промовив: „Нехай розвеселю́сь, — розділю́ Я Сихе́м і долину Сукко́тську поміряю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 9, 'Належить Мені Ґілеа́д, Мені Манасі́я, а Єфрем — охоро́на Моїй голові́, Юда — бе́рло Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 10, 'Моа́в — то мідни́ця Мого миття́, на Едо́м узуття́м Своїм кину, филисте́ю, — вигукуй для Мене із радістю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 11, 'Хто мене запрова́дить до міста тверди́нного, хто́ до Едо́му мене попрова́дить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 12, 'Хіба́ ж Ти покинув нас, Боже, і серед нашого війська не ви́йдеш вже, Боже?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 13, 'Подай же нам поміч на ворога, лю́дська бо поміч — марно́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 59, 14, 'Ми мужність ви́явимо в Бозі, — і Він пото́пче противників наших!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 1, 'Для дириґента хору. На струннім інструменті. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 2, 'Вислухай, Боже, блага́ння моє, почуй же молитву мою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 3, 'я кли́чу до Тебе від краю землі, коли серце моє омліва́є! На ске́лю, що вища від мене, мене попрова́дь,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 4, 'бо для мене Ти став пристано́вищем, ба́штою сильною супроти ворога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 5, 'Хай я оселю́ся наві́ки в наме́ті Твоїм, в укритті́ Твоїх крил захова́юся, Се́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 6, 'бо Ти, Боже, почув обітниці мої, Ти дав спа́дщину тим, хто Йме́ння Твого боїться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 7, 'Царе́ві примно́ж дні до днів, продовж ро́ки йому — немов вічні віки́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 8, 'нехай він перед Божим лицем пробува́є навіки, хай милість та правда його стережу́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 60, 9, 'Отак буду співати я за́вжди про Ймення Твоє, виконувати буду щоде́нно обі́ти свої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 1, 'Для дириґента хору. Для Єдуту́на. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 2, 'Тільки від Бога чекай у мовча́нні, о душе́ моя, від Нього спасі́ння моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 3, 'Тільки Він моя ске́ля й спасі́ння моє, Він тверди́ня моя, — тому́ не захита́юся дуже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 4, 'Доки бу́дете ви напада́ти на люди́ну? Усі хочете ви розтрощи́ти її, немов мур той похи́лений, мов би парка́н той валю́щий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 5, 'Вони́ тільки й ду́мають, я́к би зіпхнути її з висоти, вони полюбили непра́вду: благословляють своїми уста́ми, в своєму ж нутрі́ проклинають! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 6, 'Тільки від Бога чекай у мовча́нні, о душе́ моя, бо від Нього надія моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 7, 'Тільки Він моя скеля й спасі́ння моє, Він тверди́ня моя, — тому́ не захитаюсь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 8, 'У Бозі спасі́ння моє й моя слава, скеля сили моєї, моє пристано́вище в Бозі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 9, 'Мій наро́де, — кожного ча́су наді́йтесь на Нього, серце своє перед Ним вилива́йте, Бог для нас — пристано́вище! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 10, 'Справді, лю́дські сини́ — як та па́ра, сини́ й вищих му́жів — обма́на: як узяти на вагу́ — вони легші від пари всі ра́зом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 11, 'Не наді́йтесь на у́тиск, і не пишайтесь грабу́нком; як багатство росте, — не приклада́йте свого серця до нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 12, 'Один раз Бог сказав, а двічі я чув, — що сила — у Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 61, 13, 'І в Тебе, о Господи, милість, бо відпла́чуєш кожному згідно з діла́ми його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 1, 'Псалом Давидів, коли був він у пустині юдейській.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 2, 'Боже — Ти Бог мій, я шукаю від ра́ння Тебе, душа моя пра́гне до Тебе, тужить тіло моє за Тобою в країні пусте́льній і ви́мученій без води.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 3, 'Я так пригляда́вся до Тебе в святині, щоб бачити силу Твою й Твою славу, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 4, 'ліпша бо милість Твоя над життя, й мої уста Тебе прославля́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 5, 'Так я буду в житті своїм благословля́ти Тебе, ради Йме́ння Твого́ буду руки свої підіймати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 6, 'Наси́чується, ніби лоєм і товщем, душа моя, а уста́ мої хвалять губа́ми співни́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 7, 'Як згадаю Тебе на посте́лі своїй, розмишля́ю про Тебе в сторо́жах нічни́х:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 8, 'що став Ти на поміч для мене, в тіні́ ж Твоїх крил я співатиму!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 9, 'Пригорну́лась до Тебе душа моя, прави́ця Твоя підпирає мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 10, 'Вороги ж мою душу шукають для згуби, — нехай западу́ться до спо́ду землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 11, 'нехай помордо́вані бу́дуть мече́м, бодай стали шака́лам пожи́вою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 62, 12, 'А цар звесели́ться у Бозі, буде хва́лений кожен, хто йому присягає, будуть бо за́мкнені уста лжемо́вцям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 2, 'Вислухай, Боже, мій голос, як ска́ржуся я, від стра́ху ворожого душу мою хорони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 3, 'Заховай мене від потає́много збору злочинців, від крику сваві́льців,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 4, 'які нагостри́ли свого язика́, як меча, натягнули стрілу́ свою словом гірки́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 5, 'щоб таємно стріляти в невинного, — вони нагло стріля́тимуть в нього, і не бу́дуть боятись!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 6, 'У злій справі зміцня́ють себе, змовля́ються па́стки таємно розста́вити, кажуть: „Хто бу́де їх бачити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 7, 'Вони кривди ховають. Загинемо, як за́дум їхній спо́вниться, бо нутро́ чоловіка та серце — глибоке!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 8, 'Але́ вчинить Бог, що стріла́ на них стрі́лить, — і на́гло пора́нені будуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 9, 'і вчинить, що їхній язик допаде́ться до них, — і будуть хита́ти головою усі, хто спогля́не на них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 10, 'І всі люди боятися будуть, і будуть розказувати про чин Бога, і ді́ло Його зрозуміють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 63, 11, 'І праведний Господом бу́де раді́ти, і буде вдава́тись до Нього, і бу́дуть похва́лені всі простосе́рді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 1, 'Для дириґента хору. Псалом Давидів. Пісня. Уся земле, — покли́куйте Богові:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 2, 'Тобі, Боже, належиться слава в Сіоні, і Тобі́ має ві́дданий бути обі́т!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 3, 'Ти, що моли́тви вислу́хуєш, всяке тіло до Тебе прихо́дить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 4, 'Справи грішні зробились сильніші від нас, — Ти наші гріхи пробача́єш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 5, 'Блаженний, кого вибираєш Ти та наближа́єш, — в осе́лях Твоїх спочива́ти той буде! наси́тимось ми добром дому Твого́, найсвятішим із храму Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 6, 'Грізні ре́чі Ти відповіда́єш нам правдою, Боже, Спасителю наш, надіє всіх кі́нців землі та су́щих далеко на морі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 7, 'що гори ставиш Своєю силою, підпере́заний міццю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 8, 'що втихоми́рюєш гу́ркіт морів, їхніх хвиль та га́лас наро́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 9, 'І будуть боятись озна́к Твоїх ме́шканці кі́нців землі. Ти розвеселяєш країну, де вихід пора́нку й де вечір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 10, 'Ти відві́дуєш землю та по́їш її, Ти збагачуєш щедро її, — по́вний води потік Божий, Ти збіжжя готуєш її, — бо Ти так пригото́вив її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 11, 'Ти ріллю її наси́чуєш во́гкістю, вирі́внюєш гру́ддя її, розпускаєш дощами її, Ти благословляєш росли́нність її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 12, 'Ти добром Своїм рік вкороно́вуєш, і стежки́ Твої кра́плями то́вщу течу́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 13, 'Пасови́ська пустині сплива́ються кра́плями, і радістю підпереза́лись узгі́р\'я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 64, 14, 'Луги́ зодягнулись ота́рами, а долини покрилися збіжжям, — гука́ють вони та співають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 1, 'Для дириґента хору. Пісня. Псалом. Уся зе́мле, покли́куйте Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 2, 'виспівуйте честь Його Йменню, честь для слави Його покладіть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 3, 'Скажіть Богу: „Які Твої вчинки грізні́! Через силу велику Твою — Твої вороги піддаду́ться Тобі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 4, 'вся земля буде падати до ніг Твоїх, і співати Тобі буде, оспівувати Ймення Твоє!“Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 5, 'Ідіть і погляньте на Божі діла́, — Він грізни́й у діла́х проти лю́дських сині́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 6, 'Він на суході́л змінив море, — й перехо́дили рі́чку ногою, — там раділи ми в Ньому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 7, 'Він царю́є навіки Своєю могу́тністю, очі Його між наро́дами зо́рять, — нехай не несуться відсту́пники! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 8, 'Благословляйте, народи, нашого Бога, і голос слави Його розголо́шуйте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 9, 'що зберіг при житті нашу душу, і не дав нозі нашій спіткну́тись,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 10, 'бо Ти, Боже, нас випробо́вував, Ти нас перетопи́в, як срібло́ перето́плюється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 11, 'Ти нас до в\'язни́ці впровадив, Ти пута поклав нам на сте́гна,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 12, 'Ти їздити дав був люди́ні по го́ловах наших, ми ввійшли до огню́ й до води, — але на широкі місця Ти нас вивів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 13, 'Увійду́ я до дому Твого́ з цілопа́леннями, обі́ти свої Тобі ви́плачу ті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 14, 'що їх вимовили мої губи й сказали були мої уста в тісно́ті моїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 15, 'Цілопа́лення ситих тельці́в піднесу́ Тобі з димом кади́льним бара́нячим, приготу́ю биків із козла́ми. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 16, 'Ідіть, і послухайте, всі богобі́йні, а я розкажу́, що́ Він учинив для моєї душі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 17, 'До Нього я кли́кав уста́ми своїми, і хва́ли Йому — під моїм язико́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 18, 'Коли б беззако́ння я бачив у серці своїм, то Госпо́дь не почув би мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 19, 'але́ Бог почув, — і вислухав голос моєї молитви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 65, 20, 'Благословенний Бог, Який не відкинув моєї молитви й Свого́ милосердя від мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 1, 'Для дириґента хору. На струнних знаряддях. Псалом. Пісня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 2, 'Нехай Бог помилує нас, і хай поблагосло́вить, хай засяє над нами обличчям Своїм, Се́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 3, 'щоб пізнати дорогу Твою на землі, посеред наро́дів усіх — спасі́ння Твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 4, 'Хай Тебе вихваля́ють наро́ди, о Боже, хай сла́влять Тебе всі наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 5, 'Нехай веселя́ться й співають племе́на, бо Ти правдою су́диш наро́ди й племе́на ведеш на землі! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 6, 'Хай Тебе вихваля́ють наро́ди, о Боже, хай сла́влять Тебе всі наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 7, 'Земля врожай свій дала́, — Бог поблагослови́в нас, наш Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 66, 8, 'Нехай благословля́є нас Бог, і всі кі́нці землі хай бояться Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 1, 'Для дириґента хору. Псалом Давидів. Пісня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 2, 'Нехай воскре́сне Бог, — і розпоро́шаться вороги́ Його, і нехай від лиця Його повтіка́ють Його ненави́сники!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 3, 'Як дим розвіва́ється, так їх розві́й, як то́питься віск від огню́, отак несправедли́ві заги́нуть перед Божим лице́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 4, 'А пра́ведні будуть раді́ти, і будуть ті́шитися перед Богом, і весели́тися в радості будуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 5, 'Співайте Богові, виспівуйте Йме́нню Його, рівняйте дорогу Тому́, Хто їде на хмарах, — Господь Йому Йме́ння, — та перед Ним веселі́ться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 6, 'Си́ротам батько й вдови́цям суддя́, — то Бог у святому мешка́нні Своїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 7, 'Бог самі́тних уводить до дому, витягує в\'я́знів з кайда́нів, — тільки відсту́пники ме́шкати будуть у спа́леній сонцем землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 8, 'Боже, коли перед наро́дом Своїм Ти вихо́див, коли йшов Ти пустинею, — Се́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 9, 'то трясла́ся земля, також ка́пало небо було перед Богом, Сіна́й затремті́в перед Богом, Богом Ізраїля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 10, 'Дощ добродійний спускаєш Ти кра́плями, Боже, на спа́док Свій перему́чений — міцно поставив його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 11, 'У ньому сиділо Твоє многолю́ддя, у Своїй доброті́ все готуєш Ти бідному, Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 12, 'Господь дає слово; прові́сниць велика много́та:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 13, '„Царі військ утікають, утікають, па́ні ж до́му розділює здо́бич“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 14, 'Коли ви спочиваєте між обійстя́ми — то кри́ла голубки покриті сріблом, а пе́ра її — зеленка́вістю золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 15, 'Коли Всемогу́тній царів розпоро́шував в Кра́ї, то сніг Ти спускав на Цалмо́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 16, 'Гора Божа — Баша́нська гора, гора верхогі́р\'я — гора та Баша́нська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 17, 'Верхогі́р\'я, — чого за́здрісно ди́витеся на ту го́ру, що Бог зажадав на мешка́ння Своє, і Госпо́дь буде ме́шкати там за́вжди?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 18, 'Колесни́ць Божих дві десятьти́сячки, тисячі багатокра́тні, — Господь із Сіна́ю прибув до святині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 19, 'Ти піднявся був на висоту́, полоне́них набрав, узяв дари ради люди́ни, — і відсту́пники ме́шкати будуть у Господа Бога також.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 20, 'Благословенний Господь, — тягарі́ Він щоденно нам носить, Бог — наше спасіння! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 21, 'Бог для нас — Бог спасіння, і в Господа Владики ви́ходи смерти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 22, 'Але розторо́щить Бог го́лову Своїх ворогів, ма́ківку, вкриту волоссям, того, хто в гріха́х своїх ходить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 23, 'Промовив Господь: „Я спрова́джу з Баша́ну тебе́, з глибин моря спрова́джу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 24, 'щоб ти но́гу свою мив у кро́ві, щоб язик твоїх псів мав частину свою в ворогів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 25, 'Похо́ди Твої, Боже, ба́чено, похо́ди Бога мого у святині мого Царя:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 26, 'Попе́реду йшли співаки́, пото́му грачі́, посеред дівчат, що бряжча́ли на бу́бнах:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 27, '„Благословляйте на зборах Бога, Господа, ви, хто від джерел Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 28, 'Там Веніями́н молодий, їхній воло́дар, князі Юди, їхні полки́, князі Завуло́на, князі Нефтали́ма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 29, 'Твій Бог наказав тобі силу, — будь силою, Боже, того́, кого нам учинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 30, 'Із храму Твого на Єрусалимі царі привезуть Тобі дара.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 31, 'Погрози́ звірині́ в очере́ті, череді волів ра́зом з телятами лю́дськими, понищ тих, хто кава́лками срі́бла ми́лується, розпоро́ш ті наро́ди, що воєн бажають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 32, 'При́йдуть з Єгипту посли, і руки свої Куш простягне до Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 33, 'Царства землі, — співайте Богові, виспівуйте Господа, — Се́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 34, 'що їздить в відвічному небі небес. Ось Він загримить Своїм голосом, голосом сильним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 35, 'Ви́знайте Богові силу, величність Його над Ізраїлем, а в хмарах потуга Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 67, 36, 'Бог грізни́й у святинях Своїх, Бог Ізраїлів Він, що наро́дові дає силу й міць, Бог благослове́нний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 1, 'Для дириґента хору. На спів „Лелії“. Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 2, 'Спаси мене, Боже, бо во́ди вже аж до душі підійшли́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 3, 'Я загруз у глибокім багні́, і нема на чім стати, ввійшов я до водних глиби́н, — і мене залила́ течія́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 4, 'Я змучився в крику своїм, ви́сохло го́рло моє, очі мої затума́нились від вигляда́ння надії від Бога мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 5, 'Тих, хто мене без причини нена́видить, стало більш, як воло́сся на моїй голові, набра́лися сили мої вороги, що безви́нно мене переслідують, — чого не грабував, те вертаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 6, 'Боже, Ти знаєш глупо́ту мою, а гріхі́ мої перед Тобою не схо́вані!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 7, 'Неха́й через мене не ма́тимуть сти́ду оті́, хто на Тебе наді́ється, Господи, Господи Саваоте; нехай через мене не матимуть со́рому ті, хто шукає Тебе, Боже Ізраїлів, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 8, 'бо я ради Тебе знева́гу ношу́, га́ньба покрила обличчя моє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 9, 'Для братів своїх став я відчу́жений, і чужи́й для синів своєї матері,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 10, 'бо ре́вність до дому Твойо́го з\'їдає мене, і знева́ги Твоїх зневажа́льників спада́ють на мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 11, 'і по́стом я ви́плакав душу свою, а це сталось мені на знева́гу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 12, 'За одежу надів я вере́ту, — і за при́казку став я для них:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 13, 'про мене бала́кають ті, хто в брамі сидить, і пісні тих, хто п\'янке́ попива́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 14, 'А я — молитва моя до Тебе, Господи, в часі Твоєї зичли́вости; в многоті́ милосердя Твойо́го подай мені відповідь про певність спасі́ння Твого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 15, 'визволь з болота мене, щоб я не втопи́вся, щоб я урято́ваний був від своїх ненави́сників та від глибо́кости вод!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 16, 'Хай мене не заллє́ водяна́ течія́, і хай глибі́нь мене не проковтне́, і нехай своїх уст не замкне́ надо мною безо́дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 17, 'Обізви́ся до мене, о Господи, в міру доброї ласки Своєї, в міру вели́кости Свого милосердя зверни́ся до мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 18, 'і обличчя Свого не ховай від Свого раба, бо ті́сно мені, — озви́ся ж неба́ром до мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 19, 'наблизи́сь до моєї душі, порятуй же її, ради моїх ворогів відкупи́ Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 20, 'Ти знаєш нару́гу мою, і мій сором та га́ньбу мою, — перед Тобою всі мої вороги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 21, 'Моє серце злама́ла нару́га, і невиго́йний мій сором: я чекав співчуття́ — та немає його, і потіши́телів — та не знайшов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 22, 'І жо́вчі покла́ли у мій хліб поті́шення, а в спра́зі моїй оцтом мене напува́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 23, 'Бодай па́сткою стала їм їхня трапе́за, а їхні у́чти — тене́тами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 24, 'бодай їхні очі поте́мніли, щоб їм не бачити, а їхні клу́би хай за́вжди хитаються!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 25, 'Вилий на них Свою ре́вність, а по́лум\'я гніву Твого нехай їх доганяє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 26, 'Нехай їхнє село́ опусто́шене буде, хай ме́шканця в їхніх наме́тах не буде!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 27, 'Бо кого Ти був збив, — вони ще́ переслідують, і побі́льшують му́ки ране́ним Тобою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 28, 'Додай же гріха на їхній гріх, щоб вони не ввійшли в справедливість Твою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 29, 'нехай скре́слені будуть із книги життя, і хай не будуть запи́сані з праведними!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 30, 'А я бідний та хворий, але, Боже, — спасі́ння Твоє мене чинить могу́тнім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 31, 'і я піснею буду хвалити Ім\'я́ Боже, співом вдя́чним Його велича́тиму!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 32, 'І буде для Господа краща вона від вола́, від бика, що ро́ги він має, що копи́та роздво́єні має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 33, 'Побачать слухня́ні, — і бу́дуть раді́ти, хто ж Бога шукає — нехай оживе́ ваше серце,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 34, 'бо до вбогих Госпо́дь прислуха́ється, і в\'язня́ми Своїми не гордує Він!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 35, 'Нехай хвалять Його небеса́ та земля, море й усе, що́ в них ру́хається,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 36, 'бо спасе́ Бог Сіо́на, і збудує для Юди міста́, — і заме́шкають там, і вспадку́ють його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 68, 37, 'і наща́дки рабів Його пося́дуть його, й ті, хто любить Ім\'я́ Його, жи́тимуть в нім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 1, 'Для дириґента хору. Давидів. На пам\'ятку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 2, 'Поква́пся спасти́ мене, Боже, Господи, поспіши́ся ж на поміч мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 3, 'Нехай посоро́млені будуть, і хай застида́ються ті, хто шукає моєї душі, щоб схопи́ти її! Нехай подаду́ться назад, і нехай посоро́млені будуть усі, хто бажає для мене лихо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 4, 'Бодай поверну́лися з со́ромом ті, хто говорить на мене: „Ага!.. Ага!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 5, 'Нехай ті́шаться та веселя́ться Тобою усі, хто шукає Тебе, та хто любить спасі́ння Твоє, і хай за́вжди говорять: „Хай буде великий Господь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 6, 'А я вбогий та бідний, — поспіши ж Ти до Мене, о Боже: моя поміч і мій оборо́нець — то Ти, Боже мій, — не спізня́йся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 69, 7, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 1, 'До Те́бе вдаюся я. Господи, — хай же не бу́ду повік засоро́млений! —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 2, 'ви́зволь мене через правду Свою, і звільни́ мене, нахили Своє ухо до мене, й спаси́ мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 3, 'стань для мене за скелю мешка́льну, куди міг би я за́вжди ховатись! Ти наказав рятува́ти мене, бо Ти скеля моя та тверди́ня моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 4, 'Бо́же мій, визволь мене від руки беззако́нного, від руки́ того, хто кривдить та гно́бить мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 5, 'Ти бо, Влади́ко, наді́я моя, Господи, Ти охоро́на моя від юна́цького віку мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 6, 'На Тебе опе́рся я був від наро́дження, від утроби моєї матері — Ти охоро́на моя, в Тобі моя слава постійно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 7, 'Я став багатьо́м, як диво́вище, — та Ти си́льна моя охоро́на!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 8, 'Уста́ мої повні Твоєї хвали́, уве́сь день — Твоєї вели́чности!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 9, 'Не кидай мене на час ста́рости, коли зме́ншиться сила моя, не лиши Ти мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 10, 'бо мої вороги проти мене змовля́ються, а ті, що чату́ють на душу мою — нараджа́ються ра́зом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 11, 'гово́рячи: „Бог покинув його, — доганяйте й хапа́йте його, бо нема, хто б його врятува́в!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 12, 'Не відда́люйся, Боже, від мене, Боже мій — поспіши́ся ж на поміч мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 13, 'Нехай посоро́мляться, хай позника́ють усі, хто нена́видить душу мою, бодай зодягли́ся в нару́гу та в со́ром усі, хто пра́гне для мене лихо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 14, 'А я буду постійно наді́ятись, і славу Твою над усе я помно́жу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 15, 'Уста́ мої оповіда́тимуть правду Твою, про спасі́ння Твоє — увесь день, бо числа́ їх не знаю, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 16, 'буду сла́вити вчи́нки великі всевла́дного Господа, згада́ю про правду Твою, єди́но Твою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 17, 'Боже, навчав Ти мене від юна́цтва мого, — і аж дотепе́р я звіщаю про чу́да Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 18, 'А Ти, Боже, не кидай мене аж до ста́рости та сивини́, поки я не звіщу́ про раме́но Твоє поколі́нню, і кожному, хто́ тільки при́йде — про чи́ни великі Твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 19, 'Бо Твоя справедли́вість, о Боже, сягає аж до високо́сти, Боже, що речі великі вчини́в, — хто рівний Тобі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 20, 'Ти мені показав був великі та люті нещастя, та знов Ти ожи́виш мене, і з безо́день землі мене зно́ву Ти ви́тягнеш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 21, 'Ти збі́льшиш величність мою, і знову поті́шиш мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 22, 'А я буду на а́рфі хвалити Тебе, Твою правду, мій Боже, із гу́слами буду співати Тобі, Святий Ти Ізраїлів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 23, 'Нехай співом раді́ють уста́ мої, бо буду співати Тобі я та душа моя, яку Ти врятува́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 70, 24, 'Шепо́че про правду Твою мій язик ці́лий день, бо посоро́млені, бо пога́ньблені всі, хто шукає лихо́го для мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 1, 'Соломонів. Боже, Свої су́ди царе́ві подай, а свою справедливість — для сина царе́вого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 2, 'хай він правдою судить наро́да Твого, а вбогих Твоїх — справедливістю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 3, 'Нехай гори прино́сять наро́дові мир, а па́гірки — правду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 4, 'Він судитиме вбогих наро́ду, помага́тиме бідним, і ти́снути буде гноби́теля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 5, 'Будуть боятись Тебе, поки сонця, і поки місяця, — з ро́ду до ро́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 6, 'Він зі́йде, як дощ на покіс, немов кра́плі, що зро́шують землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 7, 'Праведний буде цвісти́ в його дні, а спо́кій великий — аж поки світи́тиме місяць, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 8, 'і він запанує від моря до моря, і від Ріки́ аж до кі́нців землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 9, 'Мешканці пустинь на коліна попа́дають перед обличчям його, а його вороги будуть по́рох лиза́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 10, 'Царі Тарші́шу та острові́в дадуть да́ри, принесуть царі Ше́ви та Се́ви дару́нки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 11, 'І впадуть перед ним усі царі, і будуть служити йому всі наро́ди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 12, 'бо ви́зволить він бідаря́, що голо́сить, та вбогого, що немає собі допомоги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 13, 'Він змилується над убогим та бідним, і спасе́ душу бідних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 14, 'від кривди й наси́лля врятує їхню душу, їхня кров дорога́ буде в о́чах його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 15, 'І буде він жити, і дасть йому з золота Ше́ви, і за́вжди молитися буде за нього, буде благословля́ти його кожен день!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 16, 'На землі буде збіжжя багато, на гірсько́му верху́ зашумить, як Лива́н, його плід, і наро́д зацвіте по міста́х, як трава на землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 17, 'Хай ім\'я́ його бу́де навіки, хай росте, поки сонця, найме́ння його, нехай благословля́ються ним, — будуть хвали́ти його всі наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 18, 'Благословен Госпо́дь Бог, Бог Ізраїлів, єдиний, що чу́да вчиня́є,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 19, 'і благослове́нне навіки Ім\'я́ Його слави, і хай Його слава всю землю напо́внить! Амі́нь і амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 71, 20, 'Скінчи́лись молитви Давида, сина Єссе́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 1, 'Псалом Аса́фів. Поправді Бог добрий Ізра́їлеві, Бог — для щиросе́рдих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 2, 'А я, — мало не послизну́лися но́ги мої, мало не посковзну́лися сто́пи мої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 3, 'бо лихим я зави́дував, бачивши спо́кій безбожних, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 4, 'бо не мають стражда́ння до смерти своєї, і здорове їхнє тіло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 5, 'на лю́дській роботі нема їх, і ра́зом із іншими лю́дьми не зазнаю́ть вони вда́рів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 6, 'Тому́ то пиха їхню шию оздо́блює, зодяга́є їх ша́та наси́лля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 7, 'вилазять їм очі від жи́ру, бажа́ння їхнього серця збули́ся,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 8, 'сміються й злосли́во говорять про у́тиск, говорять бундю́чно:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 9, 'свої уста до неба підно́сять, — а їхній язик по землі походжа́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 10, 'Тому́ то туди Його люди зверта́ються, і щедро беруть собі воду');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 11, 'та й кажуть: „Хіба́ Бог те знає, і чи має Всеви́шній відо́мість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 12, 'як он ті безбожні й безпечні на світі збільши́ли бага́тство своє?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 13, 'Направду, нада́рмо очи́стив я серце своє, і в неви́нності вимив ру́ки свої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 14, 'і ввесь день я побитий, і щора́нку пока́раний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 15, 'Коли б я сказав: „Буду так говори́ть, як вони“, то спроневі́рився б я поколі́нню синів Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 16, 'І розду́мував я, щоб пізна́ти оте, — та трудне́ воно в о́чах моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 17, 'аж прийшов я в Божу святиню, — і кінець їхній побачив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 18, 'направду, — Ти їх на слизько́му поставив, на спусто́шення кинув Ти їх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 19, 'Як вони в одній хвилі спусто́шені, згинули, пощеза́ли від стра́хів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 20, 'Немов сном по обу́дженні, Господи, о́бразом їхнім пого́рдиш, мов сном по обу́дженні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 21, 'Бо болить моє серце, і в нутрі́ моїм коле,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 22, 'а я немов бидло й не знаю, — я перед Тобою худо́бою став!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 23, 'Та я за́вжди з Тобою, — Ти де́ржиш мене за правицю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 24, 'Ти Своєю порадою во́диш мене, і пото́му до слави Ти ві́зьмеш мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 25, 'Хто є мені на небеса́х, окрім Тебе? А я при Тобі на землі не бажаю нічо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 26, 'Гине тіло моє й моє серце, та Бог — скеля серця мого й моя доля навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 27, 'бо погинуть ось ті, хто боку́є від Тебе, пони́щиш Ти кожного, хто відсту́пить від Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 72, 28, 'А я, — бли́зькість Бога для мене добро́, — на Владику, на Господа свою певність складаю, щоб звіща́ти про всі Твої чи́ни!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 1, 'Псалом навча́льний, Аса́фів. На́що, Боже, наза́вжди Ти нас опусти́в, чого розпали́вся Твій гнів на отару Твого пасови́ська?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 2, 'Спогадай про громаду Свою, яку Ти відда́вна набув, про племе́но спа́дку Свого, що його Ти був ви́купив, про ту го́ру Сіон, що на ній осели́вся, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 3, 'підійми ж Свої сто́пи до вічних руї́н, бо во́рог усе зруйнував у святині!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 4, 'Ревіли Твої вороги́ у святині Твоїй, умісти́ли знаки́ за озна́ки свої, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 5, 'виглядало то так, якби хто догори́ підійма́в був соки́ри в гуща́вині де́рева.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 6, 'А тепер її рі́зьби ура́з розбивають вони молотко́м та соки́рами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 7, 'Святиню Твою на огонь віддали́, осе́лю Твого Йме́ння аж доще́нту збезче́стили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 8, 'Сказали вони в своїм серці: „Зруйнуймо їх ра́зом!“і спали́ли в краю́ всі місця Божих зборів...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 9, 'Наших озна́к ми не бачимо, нема вже пророка, і між нами немає такого, хто знає, аж доки це буде...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 10, 'Аж доки, о Боже, гноби́тель знуща́тися буде, зневажа́тиме ворог навіки Ім\'я́ Твоє?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 11, 'Для чого притри́муєш руку Свою та прави́цю Свою? З сере́дини ло́ня Свого їх пони́щ!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 12, 'А Ти, Боже, відда́вна мій Цар, Ти чиниш спасі́ння посе́ред землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 13, 'Розділив Ти був море Своєю поту́гою, побив го́лови змі́ям на во́дах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 14, 'Ти левіята́нові го́лову був поторо́щив, його Ти віддав був на їжу наро́дові пустині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 15, 'Ти був розділи́в джерело́ та поті́к, Ти ви́сушив рі́ки великі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 16, 'Твій день, а також Твоя ніч, приготовив Ти світло та сонце,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 17, 'всі грани́ці землі Ти поставив, Ти літо та зи́му створи́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 18, 'Пам\'ятай же про це: во́рог знуща́ється з Господа, а наро́д нерозумний знева́жує Йме́ння Твоє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 19, 'Не віддай звірині́ душі Своєї го́рлиці, живої Твоїх бідарі́в не забудь же наза́вжди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 20, 'Споглянь же на Свій заповіт, бо темно́ти землі повні ме́шкань насилля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 21, 'Нехай не відхо́дить пригно́блений посоро́мленим, бідний та вбогий нехай прославля́ють Іме́ння Твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 22, 'Встань же, о Боже, суди́ся за справу Свою, пам\'ятай про щоде́нну нару́гу Свою від безумного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 73, 23, 'Не забудь же про ве́реск Своїх ворогів, про га́лас бунтівникі́в проти Тебе, що за́вжди зростає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 1, 'Для дириґента хору. „Не вигуби!“Псалом Аса́фів. Пісня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 2, 'Прославляємо, Боже, Тебе, прославляєм, бо близьке́ Твоє Ймення! Оповідають про чу́да Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 3, '„Коли при́йде година озна́чена, то Я буду суди́ти справедливо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 4, 'Розтопи́лась земля, і всі її ме́шканці, та стовпи́ її змі́цнюю Я. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 5, 'Я сказав до лихих: Не шалійте, а безбожним: Не підіймайте ви ро́га!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 6, 'Не підійма́йте ви рога свого́ догори́, не говоріть твердоши́йно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 7, 'бо не від сходу, і не від за́ходу, і не від пусти́ні наді́йде пови́щення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 8, 'але́ судить Бог: того Він пони́жує, а того повищує, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 9, 'бо чаша в Господній руці, а шумли́ве вино повне мі́шаного, — і наливає Він з нього, усі ж безза́конні землі виссуть та вип\'ють лиш дрі́жджі її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 10, 'А я буду звіща́ти навіки, співатиму Богові Якова,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 74, 11, 'відрубаю всі ро́ги безбожних, — роги праведного піднесу́ться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 1, 'Для дириґента хору. На неґінах. Псалом Аса́фів. Пісня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 2, 'Бог знаний у Юді, Його Йме́ння велике в Ізраїлі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 3, 'У Сали́мі намет Його, а мешка́ння Його на Сіоні, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 4, 'Він там полама́в стріли лу́ку, щита́ та меча, та війну́! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 5, 'Ти осяйни́й, потужніший за го́ри відві́чні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 6, 'Обдерто людей сильносе́рдих, задріма́ли вони своїм сном, — і не знайшли своїх рук усі мужі військо́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 7, 'Від сварі́ння Твого́, Боже Яковів, оглу́шується колесни́ця та кінь:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 8, 'Ти — Ти грізний, і хто перед обличчям Твоїм устоїть ча́су гніву Твого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 9, 'Як звіщаєш Ти суд із небе́с, то боїться й стиха́є земля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 10, 'як встає Бог на суд, щоб спасти́ всіх покі́рних землі! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 11, 'Бо й гнів лю́дський Тебе вихваля́є, решту ж гніву Ти по́ясом в\'я́жеш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 12, 'Присягайте й виконуйте Господу, Богові вашому, усі, хто Його оточа́є, хай прино́сять дарунка Грізно́му:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 75, 13, 'Він духа вельмож впокоря́є, страшни́й Він для зе́мних царів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 1, 'Для дириґента хору. Для Єдуту́на. Псалом Асафів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 2, 'Мій голос до Бога, — й я кли́кати буду, мій голос до Бога, — й почує мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 3, 'В день недолі моєї шукаю я Господа, до Нього рука моя ви́тягнена вночі й не зомлі́є, не хоче душа моя бути поті́шена:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 4, 'згадаю про Бога й зідха́ю, розважа́ю — й мій дух омліва́є! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 5, 'Ти де́ржиш пові́ки оче́й моїх, я побитий і не говорю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 6, 'Пригадую я про дні давні, про роки відві́чні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 7, 'свою пісню вночі я прига́дую, говорю́ з своїм серцем, а мій дух розважа́є:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 8, 'Чи навіки покине Господь, і вже більш не вподо́бає?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 9, 'Чи навіки спини́лася милість Його́? Чи скінчи́лося слово Його в рід і рід?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 10, 'Чи Бог ми́лувати позабу́в? Чи гнівом замкнув Він Своє милосе́рдя? Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 11, 'І промовив був я: „То стражда́ння моє — переміна прави́ці Всевишнього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 12, 'Пригада́ю я вчинки Господні, як чудо Твоє я згадаю відда́вна,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 13, 'і буду я ду́мати про кожен Твій чин, і про вчинки Твої опові́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 14, 'Боже, — святая доро́га Твоя, котри́й бог великий, як Бог наш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 15, 'Ти Той Бог, що чу́да вчиняє, Ти ви́явив силу Свою між наро́дами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 16, 'Ти ви́зволив люд Свій раме́ном, — синів Якова й Йо́сипа! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 17, 'Тебе бачили води, о Боже, Тебе бачили во́ди — й тремтіли, затряслися й безо́дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 18, 'Лила́ся струмко́м вода з хмар, тучі ви́дали грім, тако́ж там і сям Твої стрі́ли літали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 19, 'Гуркіт грому Твого на небесному колі, й блискавки́ освіти́ли вселе́нну, тремті́ла й трясла́ся земля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 20, 'Через море доро́га Твоя, а сте́жка Твоя — через во́ди великі, і не видно було́ Твоїх стіп.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 76, 21, 'Ти прова́див наро́д Свій, немов ту ота́ру, рукою Мойсея та Ааро́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 1, 'Пісня навча́льна Асафова. Послухай, мій люду, науки моєї, нахиліть своє ухо до слів моїх уст, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 2, 'нехай я відкрию уста́ свої при́казкою, нехай старода́вні прислі́в\'я я ви́словлю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 3, 'Що́ ми чули й пізнали, і що́ розповідали батьки́ наші нам, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 4, 'того не сховаємо від їхніх сині́в, будемо розповіда́ти про славу Господню аж до покоління оста́ннього, і про силу Його та про чу́да Його, які Він учинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 5, 'Він поставив засві́дчення в Якові, а Зако́на поклав ув Ізраїлі, про які наказав був Він нашим батька́м завідо́мити про них синів їхніх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 6, 'щоб знало про це поколі́ння майбу́тнє, сини, що наро́джені будуть, — уста́нуть і будуть розповідати своїм дітям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 7, 'І положать на Бога надію свою, і не забудуть діл Божих, Його ж заповіді берегти́муть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 8, 'І не стануть вони, немов їхні батьки́, поколі́нням непокі́рливим та бунтівни́чим, поколінням, що серця свого́ не поста́вило міцно, і що дух його Богу невірний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 9, 'Сини Єфрема, озбро́єні лу́чники, повернулися взад у день бо́ю:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 10, 'вони не берегли́ заповіту Божого, а ходити в Зако́ні Його відреклися,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 11, 'і забули вони Його чи́ни та чу́да Його, які їм показав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 12, 'Він чудо вчинив був для їхніх батькі́в ув єгипетськім кра́ї, на полі Цоа́нськім:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 13, 'Він море розсік, і їх перепрова́див, а воду поставив, як вал;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 14, 'і прова́див їх хмарою вдень, а ся́йвом огню́ цілу ніч;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 15, 'на пустині Він скелі розсік, і щедро усіх напоїв, як з безо́дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 16, 'Він витягнув із скелі пото́ки, і во́ди текли, немов ріки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 17, 'Та гріши́ли вони проти Нього ще да́лі, і в пустіші гніви́ли Всевишнього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 18, 'і Бога вони випробо́вували в своїм серці, для душ своїх ї́жі бажаючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 19, 'І вони говорили насу́проти Бога й казали: „Чи Бог зможе в пустині трапе́зу згото́вити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 20, 'Тож ударив у скелю — і во́ди лину́ли, і полили́ся пото́ки! „Чи Він зможе також дати хліба? Чи Він наготує м\'яси́ва наро́дові Своє́му?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 21, 'Тому́ то почув це Господь та й розгні́вався, — і огонь запалав проти Якова, і проти Ізраїля теж знявся гнів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 22, 'бо не ві́рували вони в Бога, і на спасі́ння Його не наді́ялись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 23, 'А Він хмарам згори наказав, — і відчинив двері неба,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 24, 'і спустив, немов дощ, на них ма́нну для їжі, — і збі́жжя небесне їм дав:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 25, 'Хліб а́нгольський їла люди́на, Він послав їм поживи до си́тости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 26, 'Крім цього, Він схі́днього вітра пору́шив на небі, і міццю Своєю привів полудне́вого вітра, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 27, 'і дощем на них м\'ясо пустив, немов по́рох, а птаство крила́те, як мо́рський пісо́к,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 28, 'і спустив його серед табо́ру його́, коло наметів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 29, 'І їли вони та й наси́тились ду́же, — Він їм їхнє бажа́ння приніс!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 30, 'Та ще не вдовольни́ли жада́ння свого́, ще їхня ї́жа була в їхніх уста́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 31, 'а гнів Божий підня́вся на них, та й побив їхніх ситих, і вибра́нців Ізраїлевих повали́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 32, 'Проте́ ще й далі грішили вони та не вірили в чу́да Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 33, '— і Він докінчи́в у марно́ті їхні дні, а їхні літа́ — у страху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 34, 'Як Він їх побива́в, то бажали Його, — і верта́лися, й Бога шукали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 35, 'і прига́дували, що Бог — їхня скеля, і Бог Всевишній — то їхній Викупите́ль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 36, 'І своїми уста́ми вле́щували Його, а своїм язико́м лжу спліта́ли Йому́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 37, 'бо їхнє серце не міцно стояло при Нім, і не були́ вони вірні в Його заповіті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 38, 'Та він, Милосердний, гріх проща́в і їх не губив, і часто відве́ртав Свій гнів, і не буди́в усю Свою лютість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 39, 'і Він пам\'ятав, що вони тільки тіло, вітер, який перехо́дить і не поверта́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 40, 'Скільки вони прогнівля́ли Його на пустині, зневажа́ли Його на степу́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 41, 'І все знову та знов випробо́вували вони Бога, і зневажа́ли Святого Ізра́їлевого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 42, 'вони не пам\'ята́ли руки Його з дня, як Він ви́бавив їх із недолі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 43, 'як в Єгипті чинив Він знаме́на Свої, а на полі Цоа́нському чу́да Свої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 44, 'і в кров оберну́в річки їхні та їхні пото́ки, щоб вони не пили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 45, 'Він послав був на них рої мух, — і їх же́рли вони, і жаб — і вони їх губили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 46, 'А врожай їхній віддав був Він гу́сені, а їхню пра́цю — сарані́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 47, 'Виноград їхній Він гра́дом побив, а при́морозком — їхні шовко́виці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 48, 'І Він градові віддав їхній скот, а бли́скавкам — че́реди їхні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 49, 'Він послав був на них Свій гнів запальни́й, і лютість, й обу́рення, й у́тиск, насла́ння злих анголі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 50, 'Він дорогу зрівня́в був для гніву Свого, їхні душі не стримав від смерти, життя ж їхнє віддав морови́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 51, 'І побив Він усіх перворі́дних в Єгипті, пе́рвістків сили в наметах Ха́мових.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 52, 'І повів Він, немов ту отару, наро́д Свій, і їх попрова́див, як стадо, в пустині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 53, 'І провадив безпечно Він їх, і вони не боялись, а море накри́ло було́ ворогів їхніх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 54, 'І Він їх привів до границі святині Своєї, до тієї гори, що прави́ця Його набула́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 55, 'І наро́ди Він повиганя́в перед їхнім обличчям, і кинув для них жеребка́ про спа́док, — і в їхніх наме́тах племе́на Ізраїлеві осели́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 56, 'Та й далі вони випробо́вували та гніви́ли Всевишнього Бога, і Його постано́в не доде́ржували,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 57, 'і відступали та зраджували, немов їхні батьки відверну́лись, як обма́нливий лук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 58, 'І же́ртівниками своїми гніви́ли Його, і дрочи́ли Його своїми фіґу́рами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 59, 'Бог почув усе це — і розгні́вався, і сильно обри́дивсь Ізраїлем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 60, 'і покинув осе́лю в Шіло́, скинію ту, що вмістив був посеред людей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 61, 'і віддав до неволі Він силу Свою, а вели́чність Свою — в руку во́рога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 62, 'І віддав для меча Свій наро́д, і розгнівався був на спа́дщину Свою:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 63, 'його юнакі́в огонь пожира́в, а дівча́там його не співали весі́льних пісе́нь,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 64, 'його священики від меча полягли́, — і не плакали вдови його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 65, 'Та небавом збудився Господь, немов зо́ сну, як той ве́лет, що ніби вином був підко́шений,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 66, 'і вдарив Своїх ворогів по оза́дку, — вічну га́ньбу їм дав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 67, 'Та Він погорди́в намет Йо́сипів, і племе́на Єфремового не обрав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 68, 'а вибрав Собі плем\'я Юдине, го́ру Сіон, що її полюбив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 69, 'І святиню Свою збудував Він, як місце високе, як землю, що навіки її вґрунтува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 70, 'І вибрав Давида, Свого раба, і від коша́р його взяв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 71, 'від кі́тних ове́чок його Він привів, щоб Якова пас він, народа Свого, та Ізраїля, спа́док Свій, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 77, 72, 'і він пас їх у щирості серця свого́, і прова́див їх мудрістю рук своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 1, 'Псалом Аса́фів. Боже, погани ввійшли до спа́дку Твого́, занечи́стили храм Твій святий, Єрусалим на руїни змінили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 2, 'Рабів Твоїх трупи вони віддали́ на пожи́ву для птаства небесного, тіло Твоїх богобійних — звіри́ні земні́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 3, 'Вони розливали їхню кров, немов воду, в око́лицях Єрусалиму, — і не було́ погреба́льників!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 4, 'Ми стали за га́ньбу для наших сусідів, за нару́гу та по́сміх для наших око́лиць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 5, 'Аж до́ки, о Господи, гні́ватись будеш наза́вжди, доки буде пала́ти Твій гнів, як огонь?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 6, 'Вилий Свій гнів на людей, що Тебе не пізнали, і на ца́рства, що Йме́ння Твого не кличуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 7, 'бо вони з\'їли Якова, а мешка́ння його опусто́шили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 8, 'Не пам\'ята́й гріхів пре́дківських нам, — нехай попере́дить нас скоро Твоє милосердя, бо ми зо́всім осла́бли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 9, 'Поможи нам, Боже нашого спасі́ння, ради слави Йме́ння Твого, і збережи́ нас, і прости наші гріхи ради Ймення Свого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 10, 'Чого будуть казати пога́ни: „Де їхній Бог?“Нехай в наших оча́х між наро́дами стане відо́мою помста за проли́ту кров Твоїх рабів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 11, 'нехай перед лице Твоє ді́йде стогін в\'я́зня! За великістю сили раме́на Твого збережи на смерть прироко́ваних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 12, 'А нашим сусідам верни семикра́тно на лоно їхнє їхню нару́гу, якою Тебе зневажа́ли, о Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 78, 13, 'А ми, Твій наро́д і отара Твого пасови́ська, будем дя́кувати Тобі вічно, будем оповіда́ти про славу Твою з роду в рід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 1, 'Для дириґента хору. На „Лілеї“. Свідо́цтво. Псалом Асафів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 2, 'Па́стирю Ізраїлів, — послухай же, Ти, що прова́диш, немов ту отару, Йо́сипа, що на Херувимах сидиш, — появися');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 3, 'перед обличчям Єфре́ма, і Веніями́на, і Манасі́ї! Пробуди Свою силу, і прийди, щоб спасти нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 4, 'Боже, приверни нас, і хай засяє обличчя Твоє, — й ми спасе́мось!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 5, 'Господи, Боже Савао́те, — доки будеш Ти гні́ватися на молитву наро́ду Свого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 6, 'Ти вчинив був, що їли вони слізний хліб, і їх напоїв Ти сльоза́ми великої міри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 7, 'Ти нас положи́в супере́чкою нашим сусідам, і насміхаються з нас неприя́телі наші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 8, 'Боже Савао́те, — приверни́ нас, і хай засяє обличчя Твоє, — й ми спасемось!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 9, 'Виногра́дину Ти переніс із Єгипту, Ти вигнав наро́ди — й її посадив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 10, 'Ти ви́порожнив перед нею,— і закорени́ла коріння своє, й перепо́внила край,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 11, 'гори покрилися тінню її, а ві́ття її — Божі ке́дри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 12, 'аж до моря галу́зки її посилаєш, а па́рості її — до ріки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 13, 'Але́ нащо вилім зробив Ти в горо́жі її, — і всі нищать її, хто прохо́дить дорогою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 14, 'Гризе її вепр лісови́й, і звіри́на польова́ виїдає її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 15, 'Боже Саваоте, — вернися ж, споглянь із небе́с і побач, і відві́дай цього́ виногра́дника,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 16, 'і охорони його, якого насадила прави́ця Твоя, і галу́зку, яку Ти для Себе зміцни́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 17, 'В огні виногра́дина спалена, відтята, гинуть від сва́ру обличчя Твого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 18, 'нехай буде рука Твоя над мужем Твоєї прави́ці, на лю́дському сині, якого зміцнив Ти Собі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 19, 'А ми не відступимо від Тебе, Ти нас оживи́ш, і ми будемо Ім\'я́ Твоє кликати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 79, 20, 'Господи, Боже Саваоте, приверни́ нас, і хай засяє обличчя Твоє, — й ми спасе́мось!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 1, 'Для дириґента хору. На ґітійськім знарядді. Аса́фів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 2, 'Співайте Богові, нашій тверди́ні, покли́куйте Богові Якова,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 3, 'заспівайте пісню, і заграйте на бу́бні, на ци́трі приємній із гу́слами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 4, 'засурмі́ть у сурму́ в новомі́сяччя, на по́вні в день нашого свята,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 5, 'бо це право Ізраїлеві, Зако́н Бога Якова!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 6, 'На сві́дчення в Йо́сипі Він учинив його, як пішов був на землю єгипетську. Почув був там мову, якої не знав:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 7, '„Раме́на його Я звільнив з тягару́, від коша́ його ру́ки звільнились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 8, 'Ти був кликав у недолі, — й я ви́дер тебе, Я відповідаю тобі в укритті громові́м, Я ви́пробував був тебе над водою Мери́ви. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 9, 'Слухай же ти, Мій наро́де, і хай Я засві́дчу тобі, о Ізраїлю, — коли б ти послухав Мене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 10, 'нехай бога чужого у тебе не буде, і не кланяйся богу сторонньому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 11, 'Я — Господь, Бог твій, що з кра́ю єгипетського тебе вивів, відчини свої уста — і Я їх напо́вню!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 12, 'Але́ Мій народ не послухався був Мого голосу, не згодився зо Мною Ізра́їль, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 13, 'і Я їх пустив ради впе́ртости їхнього серця, — нехай вони йдуть за своїми пора́дами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 14, 'Коли б Мій наро́д був послухав Мене, коли б був Ізраїль ходив по доро́гах Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 15, 'ще мало — і Я похили́в би був їхніх ворогів, і руку Свою поверну́в би був Я на проти́вників їхніх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 16, 'Ненави́сники Господа йому б покори́лись, — і був би навіки їхній час,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 80, 17, 'і Я жи́ром пшениці його годува́в би, і медом із скелі тебе б насища́в!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 1, 'Псалом Аса́фів. Бог на Божім зібра́нні стоїть, серед богів Він судить:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 2, '„Аж доки ви будете несправедливо судити, і доки бу́дете ви підіймати обличчя безбожних? Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 3, 'Розсуді́те нужде́нного та сироту́, оправдайте убогого та бідаря́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 4, 'порятуйте нужде́нного та бідака́, збережіть з руки несправедливих!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 5, 'Не пізнали та не зрозуміли, у те́мряві ходять вони. Всі основи землі захита́лись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 6, 'Я сказав був: „Ви — боги, і сини ви Всевишнього всі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 7, 'та однак повмира́єте ви, як люди́на, і попа́даєте, як кожен із вельмо́ж“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 81, 8, 'Устань же, о Боже, та землю суди, бо у вла́ді Твоїй всі наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 1, 'Пісня. Псалом Аса́фів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 2, 'Боже, не будь мовчазни́м, не мовчи, і не будь Ти спокійним, о Боже, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 3, 'бо ось зашуміли Твої вороги́, а Твої ненави́сники го́лови попідійма́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 4, 'Вони проти народу Твого хитрий за́дум видумують, і нара́джуються проти тих, кого Ти береже́ш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 5, 'Вони кажуть: „Ходіть но, та знищимо їх з-між наро́дів,- і згадуватись більш не буде іме́ння Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 6, 'Бо вони одноду́шно нара́дилися, проти Тебе умови склада́ють, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 7, 'намети Едо́ма й ізмаїльтя́н, Моа́в та агаря́ни,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 8, 'Ґева́л і Аммо́н, і Амали́к, Филисте́я з мешка́нцями Ти́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 9, 'І Ашшу́р поєднався був з ними, — вони синам Ло́товим стали раме́ном. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 10, 'Зроби їм, як Мідія́нові, як Сісе́рі, як Явінові в долині Кішо́н, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 11, 'при Ен-До́рі вони були зни́щені, стали погно́єм землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 12, 'Поклади їх та їхніх вельмож, як Оре́ва, й як Зе́ева, й як Зе́ваха, й як Цалму́нну, усіх їхніх князі́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 13, 'що казали були́: „Візьмі́мо на спа́док для себе поме́шкання Боже“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 14, 'Боже мій, — бодай стали вони, немов по́рох у вихрі, як солома на вітрі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 15, 'Як огонь па́лить ліс, й як запалює полу́м\'я го́ри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 16, 'так Ти їх пожени Своїм ви́хром, і настра́ш Своєю бурею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 17, 'Напо́вни обличчя їхнє со́ромом, і хай шукають вони Твоє Ймення, о Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 18, 'Нехай будуть вони засоро́млені, й за́вжди хай будуть настра́шені, і хай застида́ються, й хай вони зги́нуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 82, 19, 'І нехай вони знають, що Ти, — Твоє Ймення Госпо́дь, Сам Ти, Всевишній, на цілій землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 1, 'Для дириґента хору. На ґі́тійськім знарядді. Синів Коре́євих. Псало́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 2, 'Які любі осе́лі Твої, Господи Савао́те!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 3, 'Зату́жена та омліва́є душа моя за подві́р\'ями Господа, моє серце та тіло моє линуть до Бога Живо́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 4, 'І пташка знахо́дить домі́вку, і кубло́ собі ла́стівка, де кладе пташеня́та свої, при жертівниках Твоїх, Господи Саваоте, Ца́рю мій і Боже мій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 5, 'Блаже́нні, хто ме́шкає в домі Твоїм, — вони будуть пові́ки хвали́ти Тебе́! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 6, 'Блаже́нна люди́на, що в Тобі має силу свою́, блаженні, що в їхньому серці дороги до Те́бе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 7, 'ті, що через долину Плачу́ перехо́дять, чинять її джерело́м, — і дощ ранній дає благослове́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 8, 'Вони ходять від сили до сили, і показуються перед Богом у Сіоні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 9, 'Господи, Боже Саваоте, — послухай молитву мою, почуй, Боже Яковів! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 10, 'Щите наш, — поглянь же, о Боже, і придиви́сь до обличчя Свого помаза́нця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 11, 'Ліпший бо день на подві́р\'ях Твоїх, аніж тисяча в іншому місці, — я б вибрав сиді́ти при порозі дому Бога мого, аніж жити в наме́тах безбожности!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 12, 'Бо сонце та щит — Господь, Бог! Господь дає ми́лість та славу, добра не відмовля́є усім, хто в неви́нності хо́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 83, 13, 'Господи Савао́те, — блаже́нна люди́на, що на Тебе наді́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 1, 'Для дириґента хору. Синів Коре́євих. Псалом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 2, 'Ти вподо́бав Собі Свою землю, о Го́споди, долю Якову Ти поверну́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 3, 'Ти провину наро́ду Свого прости́в, увесь гріх їхній покри́в! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 4, 'Ти гнів Свій увесь занеха́в, Ти повстри́мав Свій гнів від палю́чої лю́тости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 5, 'Поверни нас до Себе, о Боже нашого спасі́ння, а Свій гнів проти нас поторо́щ!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 6, 'Чи навіки Ти гні́ватись будеш на нас, і протя́гнеш Свій гнів з роду в рід?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 7, 'Отож, Ти ожи́виш нас зно́ву, — і буде радіти наро́д Твій Тобою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 8, 'Покажи нам, о Господи, милість Свою, і подай нам спасі́ння Своє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 9, 'нехай я почую, що каже Бог, Господь, бо говорить Він „Мир!“наро́дові Своєму й Своїм святим, і нехай до безу́мства вони не верта́ються!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 10, 'Справді, спасі́ння Його близьке́ тим, хто боїться Його, щоб слава Його́ була в нашій землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 11, 'Милість та правда спіткаються, справедливість та мир поцілуються,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 12, 'правда з землі вироста́є, а справедливість із небе́с визира́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 13, 'І Господь дасть добро, а земля наша дасть урожай свій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 84, 14, 'Справедливість ходитиме перед обличчям Його, і кро́ки свої на дорогу поставить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 1, 'Молитва Давидова. Нахили, Господи, ухо Своє і вислухай мене, — бо я бідний та вбогий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 2, 'Бережи мою душу, бо я богобі́йний, спаси Ти, мій Боже, Свого раба, що на Тебе наді́ю кладе́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 3, 'Змилосе́рдься до мене, о Господи, бо я кличу до Тебе ввесь день,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 4, 'потіш душу Свого раба, бо до Тебе підно́шу я, Господи, душу мою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 5, 'бо Ти, Господи, добрий і вибачли́вий, і многомилости́вий для всіх, хто кли́че до Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 6, 'Почуй же, о Господи, молитву мою, і вислухай голос блага́ння мого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 7, 'в день недолі своєї я кличу до Тебе, бо Ти обізве́шся до мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 8, 'Нема, Господи, поміж бога́ми такого, як Ти, і чинів нема, як чи́ни Твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 9, 'Всі наро́ди, яких Ти створи́в, поприхо́дять і попадають перед лице́м Твоїм, Господи, та Ім\'я́ Твоє сла́вити будуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 10, 'великий бо Ти, та чу́да вчиняєш, Ти — Бог єдиний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 11, 'Дорогу Свою покажи мені, Господи, і я бу́ду ходити у правді Твоїй, приєдна́й моє серце боятися Йме́ння Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 12, 'Я буду всім серцем своїм вихваля́ти Тебе, Господи, Боже Ти мій, і сла́вити буду повіки Ім\'я́ Твоє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 13, 'велика бо милість Твоя надо мною, і вирвав Ти душу мою від шео́лу глибокого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 14, 'Боже, злочинці повстали на мене, а на́товп гноби́телів прагне моєї душі, і перед собою не ставлять Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 15, 'А Ти, Господи, Бог щедрий і милосердний, довготерпели́вий і многомилости́вий, і справедли́вий, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 16, 'зглянься на мене, й помилуй мене, подай же Своєму рабові Свою силу, і спаси сина Своєї неві́льниці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 85, 17, 'Учини мені знака на добре, — і нехай це побачать мої ненави́сники, і хай засоро́млені будуть, бо Ти, Господи, мені допоміг та мене звесели́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 1, 'Синів Коре́євих. Псалом, Пісня. Основа його — на го́рах святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 2, 'Госпо́дь любить брами Сіону понад усі се́лища Яковові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 3, 'Славне розповіда́ють про тебе, місто Боже! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 4, '„Тим, хто знає мене, нагадаю про Ра́гав та про Вавило́н; ось Филисте́я та Тир з Ку́шем кажуть: Отой народився був там“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 5, 'І про Сіон говори́тимуть: „Той і той народився був у ньому, й Сам Всевишній зміцняє його́“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 6, 'Господь буде лічити у книзі наро́дів: „Оцей народився був там“! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 86, 7, 'І співають, і грають вони: „У Тобі — всі джере́ла мої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 1, 'Пісня. Псалом. Синів Кореєвих. Для дириґента хору. На „Махалат леаннот“. Пісня навча́льна Ге́мана езрахе́янина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 2, 'Господи, Боже спасі́ння мого́, вдень я кли́чу й вночі Я перед Тобою:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 3, 'хай молитва моя дійде перед обличчя Твоє, нахили Своє ухо до зо́йку мого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 4, 'душа бо моя насити́лась нещастями, а життя моє збли́зилося до шео́лу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 5, 'Я до тих прирахований став, що в могилу відхо́дять, я став, немов муж той безсилий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 6, 'Я кинений серед померлих, немов оті тру́пи, що в гро́бі лежать, що про них Ти не згадуєш більш, і потя́ті вони від Твоєї руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 7, 'Умісти́в Ти мене в глибоче́зну могилу, до пітьми́ в глибина́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 8, 'На мене лягла́ Твоя лють, і Ти всіма́ Своїми лама́ннями мучив мене. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 9, 'Віддалив Ти від мене знайо́мих моїх, учинив Ти мене за оги́ду для них, Я за́мкнений і не вихо́джу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 10, 'стемні́ло з біди моє око. Я кожного дня Тебе кличу, о Господи, простяга́ю до Тебе ру́ки свої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 11, 'Чи Ти чудо вчиниш померлим? Чи тру́пи встануть і будуть хвали́ти Тебе? Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 12, 'Хіба милість Твоя буде в гро́бі звіща́тись, а вірність Твоя в аввадо́ні?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 13, 'Чи позна́ється в те́мряві чудо Твоє, а в краю́ забуття́ — справедливість Твоя?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 14, 'Та я кличу до Тебе, о Господи, і вранці молитва моя Тебе випере́джує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 15, 'Для чо́го, о Господи, кидаєш душу мою, ховаєш від мене обличчя Своє?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 16, 'Нужде́нний я та помираю відма́лку, перено́шу страхіття Твої, я осла́блений став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 17, 'Перейшли́ надо мною Твої пересе́рдя, страхіття Твої зруйнува́ли мене, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 18, 'вони оточа́ють мене, як вода, увесь день, вони ра́зом мене обляга́ють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 87, 19, 'друга й при́ятеля віддалив Ти від мене, знайо́мі мої — як та те́мрява!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 1, 'Навчальна пісня Ета́на езрахе́янина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 2, 'Про милості Господа буду співати пові́ки, я буду звіща́ти уста́ми своїми про вірність Твою з роду в рід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 3, 'Бо я був сказав: „Буде наві́ки збудо́вана милість, а небо — Ти вірність Свою встановля́єш на нім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 4, '„Я склав заповіта з вибра́нцем Своїм, присягнув Я Давидові, Моєму рабо́ві:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 5, 'Встановлю́ Я наві́ки насі́ння твоє, а твій трон Я збудую на вічні віки́“! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 6, 'І небо хвалитиме, Господи, чудо Твоє, також вірність Твою на зібра́нні святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 7, 'бо хто в небі поді́бний до Господа? Хто подібний до Господа серед Божих синів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 8, 'Бог дуже страшни́й у зібра́нні святих, і грізни́й Він на ці́ле довкі́лля Своє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 9, 'Господи, Боже Саваоте, — хто си́льний, як Ти, Господи? А вірність Твоя — на довкі́ллі Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 10, 'Ти пануєш над силою моря, коли підіймаються хви́лі, Ти їх втихоми́рюєш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 11, 'Ти стиснув Рага́ва, як трупа, і сильним раме́ном Своїм розпоро́шив Своїх ворогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 12, 'Твої небеса́, Твоя теж земля, вселе́нна і все, що на ній, — Ти їх заложив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 13, 'Північ та південє — Ти їх створив, Фаво́р та Хермо́н співають про Йме́ння Твоє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 14, 'Могутнє раме́но Твоє, рука Твоя си́льна, висока прави́ця Твоя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 15, 'Справедливість та право — підста́ва престо́лу Твого, милість та правда — обличчя Твоє випере́джують!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 16, 'Блаже́нний наро́д, що знає він поклик святковий, — Господи, вони ходять у світлі обличчя Твого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 17, 'Радіють вони цілий день Твоїм Іменням, і підви́щуються Твоєю справедливістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 18, 'бо окра́са їхньої сили — то Ти, а Твоєю зичли́вістю ріг наш підно́ситься,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 19, 'бо щит наш — Господній, а цар наш — від Святого Ізраїлевого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 20, 'Тоді богобійним Своїм про мовляв Ти в об\'я́вленні та говорив: „Я поклав допомогу на сильного, Я вибра́нця підніс із наро́ду:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 21, 'знайшов Я Давида, Свого раба, — Я його намасти́в Своєю святою оливою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 22, 'щоб із ним була си́льна рука Моя, а раме́но Моє вміцни́ло його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 23, 'Ворог на нього не нападе́, а син беззаконня не буде його переслі́дувати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 24, '— його ворогів поб\'ю́ перед обличчям його, і вда́рю його ненави́сників!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 25, 'Із ним Моя вірність та милість Моя, а Йме́нням Моїм його ріг піднесе́ться, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 26, 'і Я покладу́ його ру́ку на море, і на рі́ки — прави́цю його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 27, 'Він Мене буде звати: „Отець Ти мій, Бог мій, і скеля спасі́ння мого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 28, 'Я вчиню́ його теж перворі́дним, найвищим над зе́мних царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 29, 'Свою милість для нього наві́ки схова́ю, і Мій заповіт йому вірний,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 30, 'і насіння його покладу́ Я наві́ки, а трона його — як дні неба!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 31, 'Коли ж його діти покинуть Зако́на Мого, і не будуть держа́тись нака́зів Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 32, 'коли ізнева́жать Мої постано́ви, і не бу́дуть держатись нака́зів Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 33, 'тоді па́лицею навіщу́ їхню прови́ну, та пора́зами — їхнє беззако́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 34, 'А ласки Своєї від ньо́го Я не заберу́, і не зра́джу його в Своїй вірності,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 35, 'не збезче́щу Свого заповіту, а що́ було з уст Моїх вийшло, того не зміню́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 36, 'Одне в Своїй святості Я присягнув, — не пові́м Я неправди Давидові:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 37, 'повік буде насі́ння його, а престол його передо Мною — як сонце,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 38, 'як місяць, він буде стояти пові́ки, і Сві́док на хмарі — правди́вий“. Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 39, 'А Ти опустив та обри́див, розгнівався Ти на Свого пома́занця, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 40, 'Ти неважливим зробив запові́та Свого раба, Ти скинув на землю корону його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 41, 'всю горо́жу його полама́в, тверди́ні його оберну́в на руїну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 42, 'Всі грабують його, хто прохо́дить дорогою, — він став для сусідів своїх посміхо́вищем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 43, 'Підніс Ти правицю його переслі́дувачів, усіх його ворогів Ти поті́шив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 44, 'і Ти відвернув вістря ша́блі його, у війні ж не підтри́мав його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 45, 'Ти слави позбавив його, а трона його повалив був на землю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 46, 'скоротив Ти був дні його мо́лодости, розтягнув над ним сором! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 47, 'Доки, Господи, бу́деш хова́тись наза́вжди, доки буде палати Твій гнів, як огонь?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 48, 'Пам\'ятай же про мене, — яка довгота́ життя лю́дського? Для чого створив Ти всіх лю́дських синів на ніщо́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 49, 'Котри́й чоловік буде жити, а смерти не ба́читиме, збереже свою душу від сили шео́лу? Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 50, 'Де Твої перші милості, Господи, що їх присягав Ти Давидові у Своїй вірності?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 51, 'Згадай, Господи, про га́ньбу рабів Своїх, яку я ношу́ в своїм лоні від усіх великих наро́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 52, 'якою Твої вороги зневажають, о Господи, і кроки Твого́ помазанця безславлять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 88, 53, 'Благослове́нний навіки Господь! Амі́нь і амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 1, 'Молитва Мойсея, чоловіка Божого. Господи, пристано́вищем нашим Ти був з роду в рід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 2, 'Пе́рше ніж го́ри наро́джені, і поки Ти витворив землю та світ, то від віку й до віку — Ти Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 3, 'Ти люди́ну вертаєш до по́роху, і кажеш: „Вернітеся, лю́дські сини!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 4, 'Бо в оча́х Твоїх тисяча літ, — немов день той вчорашній, який проминув, й як сторо́жа нічна́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 5, 'Пустив Ти на них течію́, вони стали, як сон, вони, як трава, що мина́є:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 6, 'уранці вона розцвітає й росте, — а на вечір зів\'я́не та со́хне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 7, 'Бо від гніву Твого ми ги́немо, і пересердям Твоїм перестра́шені, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 8, 'Ти наші прови́ни поклав перед Себе, гріхи ж нашої мо́лодости — на світло Свого лиця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 9, 'Бо всі наші дні промайну́ли у гніві Твоїм, скінчи́ли літа́ ми свої, як зідха́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 10, 'Дні літ наших — у них сімдеся́т літ, а при силах — вісімдеся́т літ, і го́рдощі їхні — стражда́ння й марно́та, бо все швидко минає, і ми відліта́ємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 11, 'Хто відає силу гніву Твого́? А Твоє пересе́рдя — як страх перед Тобою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 12, 'Навчи нас лічи́ти отак наші дні, щоб ми набули́ серце мудре!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 13, 'Привернися ж, о Господи, — доки терпі́тимемо? — і пожалій Своїх рабів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 14, 'Насити́ нас ура́нці Своїм милосердям, і ми бу́демо співати й радіти по всі наші дні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 15, 'Порадуй же нас за ті дні, коли Ти впокоря́в нас, за ті ро́ки, що в них ми зазнали лихого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 16, 'Нехай ви́явиться Твоє ді́ло рабам Твоїм, а вели́чність Твоя — їхнім сина́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 89, 17, 'і хай буде над нами благоволі́ння Господа, Бога нашого, і ді́ло рук наших утверди́ нам, і діло рук наших — утверди́ його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 1, 'Хто живе під покровом Всевишнього, хто в тіні́ Всемогутнього мешкає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 2, 'той скаже до Господа: „Охоро́но моя та тверди́не моя, Боже мій“, — я наді́юсь на Нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 3, 'Бо Він тебе вирве з тене́т птахоло́ва, з морови́ці згубно́ї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 4, 'Він перо́м Своїм вкриє тебе, і під кри́льми Його заховаєшся ти! Щит та лук — Його правда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 5, 'Не будеш боятися стра́ху нічно́го, ані стріли, що вдень пролітає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 6, 'ані зарази, що в те́мряві ходить, ані морови́ці, що нищить опі́вдні, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 7, 'впаде тисяча з боку від тебе, і десять тисяч право́руч від тебе, до тебе ж не ді́йде!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 8, 'Тільки своїми очима поди́вишся, — і заплату безбожним попобачиш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 9, 'бо Господа, охорону мою, Всевишнього ти учини́в за своє пристано́вище!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 10, 'Тебе зло не спітка́є, і до наме́ту твого вдар не набли́зиться,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 11, 'бо Своїм Ангола́м Він накаже про тебе, щоб тебе пильнували на всіх дорогах твоїх, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 12, 'на руках вони будуть носити тебе, щоб не вдарив об камінь своєї ноги́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 13, 'На лева й вужа́ ти наступиш, левчука́ й крокодила ти будеш топта́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 14, '„Що бажав він Мене, то його збережу́, зроблю́ його сильним, — бо знає Ім\'я́ Моє він;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 15, 'як він Мене кли́катиме, то йому відповім, Я з ним буду в недолі, врятую його та просла́влю його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 90, 16, 'і довгістю днів Я наси́чу його, і він бачити буде спасі́ння Моє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 1, 'Псалом. Пісня на день суботній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 2, 'То добре, щоб дякувати Господе́ві й виспі́вувати Йме́ння Твоє, о Всевишній,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 3, 'вранці розповіда́ти про милість Твою, а ночами — про правду Твою —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 4, 'на десятистру́нній й на а́рфі, на лю́тні та гу́слах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 5, 'бо потішив мене Ти, о Господи, вчинком Своїм, — про діла́ Твоїх рук я співаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 6, 'Які то вели́чні діла Твої, Господи, дуже глибокі думки́ Твої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 7, '— нерозумна люди́на не знає, а недо́умок не зрозуміє того́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 8, 'Коли несправедливі ростуть, як трава, і цвітуть всі злочи́нці, то на те, щоб навіки були вони знищені, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 9, 'а Ти, Господи, на висоті повік-віку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 10, 'Бо ось вороги Твої, Господи, бо ось вороги Твої згинуть, розпоро́шаться всі беззако́нники!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 11, 'І Ти ро́га мого підні́с немов в одноро́жця, мене намастив Ти оливою свіжою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 12, 'І дивилося око моє на зане́пад моїх ворогів, тих злочинців, що на мене встають, — почують про це мої уші!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 13, 'Зацвіте́ справедливий, як па́льма, і ви́женеться, немов кедр на Лива́ні, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 14, 'посаджені в домі Господнім цвітуть на подві́р\'ях нашого Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 15, 'іще в сивині́ вони будуть цвісти́, будуть ситі та свіжі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 91, 16, 'щоб розповідати, що щирий Господь, моя скеля, і в Ньому неправди нема!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 92, 1, 'Царю́є Госпо́дь, — зодягну́вся у ве́лич, зодягнувся Господь, опереза́вся Він силою, — і міцно поставлений все́світ, щоб не захитався!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 92, 2, 'Престол Твій поста́влений міцно спрада́вна, від вічности Ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 92, 3, 'Ріки підне́сли, о Господи, ріки підне́сли свій гу́ркіт, ріки бу́дуть підно́сити шум від уда́ру їхніх хвиль, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 92, 4, 'та над гу́ркіт великих тих вод, над мо́рські потужнії хвилі, — могутні́ший Господь у висоті́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 92, 5, 'Свідо́цтва Твої дуже певні, а дому Твоєму нале́житься святість, о Господи, на довгії дні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 1, 'Бог помсти — Господь, Бог помсти з\'явився, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 2, 'піднеси́ся, о Су́дде землі, бундю́чним запла́ту віддай!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 3, 'Аж доки безбожні, о Господи, аж доки безбожні втіша́тися будуть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 4, 'Доки бу́дуть верзти́, говорити бундю́чно, доки будуть пиша́тись злочинці?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 5, 'Вони тиснуть наро́д Твій, о Господи, а спадок Твій вони му́чать.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 6, 'Вдову́ та чужи́нця вбивають вони, і мордують сирі́т');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 7, 'та й говорять: „Не бачить Господь, і не завва́жить Бог Яковів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 8, 'Зрозумійте це ви, нерозумні в наро́ді, а ви, убогі на розум, коли набере́теся глу́зду?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 9, 'Хіба Той, що ухо щепи́в, — чи Він не почує? Хіба Той, що око створи́в, — чи Він не побачить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 10, 'Хіба Той, що карає наро́ди, — чи Він не скарта́є, Він, що навчає люди́ну знання́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 11, 'Господь знає всі лю́дські думки́, що марно́та вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 12, 'Блаженний той муж, що його Ти караєш, о Господи, і з Зако́ну Свого навчаєш його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 13, 'щоб його заспоко́їти від лиходе́ння, аж поки не ви́копана буде яма безбожному,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 14, 'бо Господь не опустить наро́ду Свого, а спа́дку Свого не поли́шить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 15, 'бо до праведности суд пове́рнеться, а за ним — всі невинного серця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 16, 'Хто встане зо мною навпроти злости́вих, хто встане зо мною навпроти злочинців?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 17, 'Коли б не Господь мені в поміч, то душа моя тро́хи була́ б не лягла́ в царство смерти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 18, 'Коли я кажу: „Похитнулась нога моя“, то, Господи, милість Твоя підпира́є мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 19, 'Коли мої думки́ болючі в нутрі́ моїм мно́жаться, то розради Твої веселять мою душу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 20, 'Чи престол беззако́ния з Тобою з\'єдна́ється, той, що гріх учиняє над право?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 21, 'Збираються проти душі справедли́вого, і чисту кров винува́тять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 22, 'І Господь став для мене тверди́нею, і мій Бог став за скелю приту́лку мого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 93, 23, 'і Він їхню силу на них повернув, і злом їхнім їх нищить, їх нищить Господь, Бог наш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 1, 'Ходіть, заспіваймо Господе́ві, покли́куймо радісно скелі спасі́ння нашого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 2, 'хвалою обличчя Його випере́джуймо, співаймо для Нього пісні́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 3, 'бо Господь — Бог великий, і великий Він Цар над богами всіма́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 4, 'що в Нього в руці глиби́ни землі, і Його верхогі́р\'я гірські́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 5, 'що море Його, і вчинив Він його, і руки Його суході́л уформува́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 6, 'Прийдіть, поклоні́мося, і припаді́м, на коліна впаді́м перед Господом, що нас учинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 7, 'Він наш Бог, а ми люди Його пасови́ська й отара руки Його. Сьогодні, коли Його голос почуєте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 8, '„не робіте твердим серця вашого, мов при Мери́ві, немов на пустині в день спро́би,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 9, 'коли ваші батьки́ Мене брали на спро́бу, Мене випробо́вували, також бачили ді́ло Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 10, 'Сорок літ був оги́дним мені оцей рід, й Я сказав: Цей наро́д — блудосерді вони, й не пізнали доріг Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 94, 11, 'тому́ заприсягся Я в гніві Своїм, що до місця Мого відпочинку не вві́йдуть вони!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 1, 'Співайте для Господа пісню нову́, уся зе́мле, — співайте для Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 2, 'Співайте для Господа, благословля́йте Ім\'я́ Його, з дня на день сповіщайте спасі́ння Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 3, 'Розповідайте про славу Його між пога́нами, про чу́да Його — між усі́ми наро́дами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 4, 'бо великий Господь і просла́влений ве́льми, Він грізни́й понад богів усіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 5, 'Бо всі боги наро́дів — божки́, а Госпо́дь створив небеса́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 6, 'перед лицем Його слава та велич, сила й краса — у святині Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 7, 'Дайте Господу, ро́ди наро́дів, дайте Господу славу та силу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 8, 'дайте Господу славу йме́ння Його, жертви прино́сьте і вхо́дьте в подві́р\'я Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 9, 'Додолу впадіть ув оздо́бі святій перед Господом, тремтіть перед обличчям Його, уся зе́мле,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 10, 'сповістіть між наро́дами: „Царю́є Госпо́дь! Він вселе́нну зміцни́в, щоб не захита́лась, Він бу́де судити людей справедли́во“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 11, 'Хай небо радіє, і хай весели́ться земля, нехай гримить море й усе, що у нім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 12, 'нехай поле радіє та все, що на ньому! Нехай заспівають тоді всі дере́ва лісні́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 95, 13, 'перед Господнім лицем, бо гряде́ Він, бо зе́млю судити гряде́,е́ — Він за справедливістю буде судити вселе́нну, і наро́ди — по правді Своїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 1, 'Царю́є Господь: хай радіє земля, нехай веселя́ться числе́нні острови́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 2, 'Хмара та мо́рок круг Нього, справедливість та право — підстава престолу Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 3, 'Огонь іде перед лицем Його́, і ворогів Його па́лить навко́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 4, 'Освітили вселе́нну Його блискави́ці, — те бачить земля та тремти́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 5, 'Гори, як віск, розтопи́лися перед обличчям Господнім, перед обличчям Господа всієї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 6, 'Небо розповідає про правду Його, й бачать славу Його всі наро́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 7, 'Нехай посоро́млені будуть усі, хто і́долам служить, хто божка́ми вихва́люється! Додо́лу впадіть перед Ним, усі бо́ги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 8, 'Почув і звесели́вся Сіон, і поті́шились Юдині до́чки через Твої при́суди, Господи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 9, 'бо над усією землею Найви́щий Ти, Господи, над бога́ми всіма́ Ти піднесе́ний сильно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 10, 'Хто Господа любить, — нена́видьте зло! Хто рятує душі святих Своїх, Той ви́зволить їх із руки несправедли́вих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 11, 'Світло сі́ється для справедливого, а для простосердих — розра́да.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 96, 12, 'Радійте, праведні, Господом, і славте Його святу па́м\'ять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 1, 'Псалом. Співайте для Господа пісню нову́, бо Він чу́да вчинив! Йому помогла́ прави́ця Його та святе раме́но Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 2, 'Спасі́ння Своє Господь ви́явив, перед очима наро́дів відкрив Свою правду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 3, 'Пам\'ятає Він Якову милість Свою, й Свою вірність для дому Ізра́їля. Бачать всі кі́нці землі те спасі́ння, що чинить наш Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 4, 'Уся зе́мле, викли́куйте Господу, покли́куйте радісно, і співайте та грайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 5, 'Грайте Господе́ві на гу́слах, на гу́слах і піснопі́нням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 6, 'на су́рмах і голосом рогу викликуйте перед обличчям Царя Цього й Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 7, 'Нехай шумить море й усе, що у ньому, вселе́нна й мешка́нці її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 8, 'ріки хай плещуть в долоні, ра́зом радіють хай го́ри');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 97, 9, 'перед обличчям Господнім, бо Він землю судити гряде́: Він за справедливістю буде судити вселе́нну, і народи по правді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 1, 'Царює Господь, — і наро́ди тремтя́ть, сидить на Херуви́мах, і трясе́ться земля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 2, 'Великий Госпо́дь на Сіоні, і підне́сений Він над усі́ма наро́дами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 3, 'Хай Ім\'я́ Твоє сла́влять, — велике й грізне́ воно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 4, 'А сила Царя любить право, справедливість Ти міцно поста́вив, Ти Якову право та правду вчинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 5, 'Звели́чуйте Господа, нашого Бога, і вклоняйтесь підні́жкові ніг Його, — Він бо Святий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 6, 'Мойсей й Ааро́н — серед священиків Його, а Самуїл серед тих, що кличуть Іме́ння Його. Вони кликали до Господа, — і Він вислухав їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 7, 'у стовпі хмари до них говорив. Вони зберіга́ли свідо́цтва Його й постано́ви, що Він дав був для них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 8, 'Господи, Боже наш, — Ти вислухо́вував їх, Ти був для них Богом виба́чливим, але мстився за їхні діла́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 98, 9, 'Звеличуйте Господа, нашого Бога, і вклоня́йтеся перед горою святою Його, — бо Святий Господь, Бог наш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 99, 1, 'Вдя́чний псало́м. Уся зе́мле, покли́куйте Господу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 99, 2, 'Служіть Господе́ві із радістю, перед обличчя Його підійдіте зо співом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 99, 3, 'Знайте, що Господь — Бог Він, Він нас учини́в, і Його́ ми, — Його ми народ та отара Його пасови́ська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 99, 4, 'Увійдіть в Його бра́ми з подя́куванням, на подві́р\'я Його́ з похвало́ю! Виславляйте Його, Ім\'я́ Його благословля́йте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 99, 5, 'бо добрий Господь, Його милість навіки, а вірність Його — з роду в рід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 1, 'Псалом Давидів. Я виспі́вувати буду про милість та суд, я буду співати до Тебе, о Господи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 2, 'придивля́тимуся до доро́ги невинного. Коли при́йдеш до мене? Я буду ходити в неви́нності серця свого́ серед дому мого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 3, 'не поставлю я перед очи́ма своїми речі нікче́мної, діло відступства нена́виджу, — не приляже до мене воно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 4, 'перекі́рливе серце відхо́дить від мене, лихого не знаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 5, 'Хто таємно обчо́рнюв бли́жнього свого, — я зни́щу того́, високоо́кого й гордосе́рдого, — його не стерплю́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 6, 'Мої очі — на вірних землі, щоб сиділи зо мною. Хто хо́дить дорогою невинного, той буде служити мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 7, 'Обма́нець не сяде в сере́дині дому мого, і міцно не стане навпроти очей моїх неправдомо́вець!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 100, 8, 'Всіх безбожних землі буду ни́щити кожного ра́нку, щоб з міста Господнього ви́губити всіх злочинців!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 1, 'Молитва вбогого, коли він слабне та перед Господнім лицем виливає мову свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 2, 'Господи, ви́слухай молитву мою, і блага́ння моє нехай ді́йде до Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 3, 'Не ховай від мене обличчя Свого́, в день недолі моєї — схили Своє ухо до ме́не, в день блага́ння озвися неба́вом до мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 4, 'Бо минають, як дим, мої дні, а кості мої — немов ви́сохли в о́гнищі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 5, 'Як трава та — поби́те та ви́сохло серце моє, так що я забував їсти хліб свій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 6, 'Від зо́йку стогна́ння мого прили́пли до тіла мого мої кості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 7, 'Уподо́бився я пелика́нові пустині, я став, як той пу́гач руїн!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 8, 'Я безсонний, і став, немов пташка само́тня на да́сі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 9, 'Увесь день ображають мене вороги́ мої, ті, хто з мене кепку́є, заприсяглись проти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 10, 'І по́піл я їм, немов хліб, а напо́ї свої із плаче́м перемі́шую, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 11, 'через гнів Твій та лютість Твою, бо підняв був мене Ти та й кинув мене́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 12, 'Мої дні — як похи́лена тінь, а я сохну, немов та трава!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 13, 'А Ти, Господи, бу́деш повік пробува́ти, а пам\'ять Твоя — з роду в рід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 14, 'Ти встанеш та змилуєшся над Сіо́ном, бо час учини́ти йому милосердя, бо прийшов речене́ць,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 15, 'бо раби Твої покоха́ли й камі́ння його́, і порох його полюбили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 16, 'І будуть боятись наро́ди Господнього Йме́ння, а всі зе́мні царі — слави Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 17, 'Бо Господь побудує Сіона, поя́виться в славі Своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 18, 'До молитви забутих зве́рнеться Він, і моли́тви їхньої не осоро́мить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 19, 'Запишеться це поколі́нню майбу́тньому, і наро́д, який ство́рений буде, хвали́тиме Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 20, 'бо споглянув Він із високо́сти святої Своєї, Господь зо́рив на землю з небе́с,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 21, 'щоб почути зідха́ння ув\'я́зненого, щоб на смерть прироко́ваних ви́зволити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 22, 'щоб розповіда́ти про Йме́ння Господнє в Сіоні, а в Єрусалимі — про славу Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 23, 'коли ра́зом зберу́ться наро́ди й держа́ви служи́ти Господе́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 24, 'Мою силу в дорозі Він ви́снажив, дні мої скороти́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 25, 'Я кажу́: „Боже мій, — не бери Ти мене в половині днів моїх! Твої ро́ки — на вічні віки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 26, 'Колись землю Ти був закла́в, а небо — то чин Твоїх рук, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 27, 'позникають вони, а Ти бу́деш стояти. І всі вони, як оде́жа, загинуть, Ти їх зміниш, немов те вбрання́, — і мину́ться вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 28, 'Ти ж — Той Самий, а роки Твої не закі́нчаться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 101, 29, 'Сини Твоїх рабів будуть жити, а їхнє насіння стоя́тиме міцно перед обличчям Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 1, 'Давидів. Благослови́, душе́ моя, Господа, і все нутро моє — святе Йме́ння Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 2, 'Благослови, душе моя, Господа, і не забувай за всі доброді́йства Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 3, 'Всі провини Твої Він прощає, всі неду́ги твої вздоровля́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 4, 'Від могили життя твоє Він визволя́є, Він милістю та милосердям тебе корону́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 5, 'Він бажа́ння твоє насича́є добром, — відно́виться, мов той орел, твоя ю́ність!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 6, 'Господь чинить правду та суд для всіх переслі́дуваних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 7, 'Він дороги Свої об\'явив був Мойсе́єві, діла́ Свої — ді́тям Ізра́їлевим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 8, 'Щедрий і милосердний Господь, довготерпели́вий і многомилости́вий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 9, 'Не за́вжди на нас ворогує, і не навіки захо́вує гнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 10, 'Не за нашими про́гріхами Він пово́диться з нами, і відплачує нам не за прови́нами нашими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 11, 'Бо як ви́соко небо стоїть над землею, — велика така Його милість до тих, хто боїться Його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 12, 'як далекий від за́ходу схід, так Він віддали́в від нас наші провини!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 13, 'Як жалує ба́тько дітей, так Господь пожалі́вся над тими, хто боїться Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 14, 'бо знає Він ство́рення наше, пам\'ятає, що ми — по́рох:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 15, 'чоловік — як трава дні його, немов цвіт польови́й — так цвіте він,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 16, 'та вітер пере́йде над ним — і немає його, і вже місце його не пізна́є його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 17, 'А милість Господня від віку й до віку на тих, хто боїться Його, і правда Його — над синами синів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 18, 'що Його заповіта доде́ржують, і що пам\'ята́ють нака́зи Його, щоб виконувати їх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 19, 'Господь міцно поставив на Небі престо́ла Свого́, а Ца́рство Його над усім володі́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 20, 'Благослові́ть Господа, Його Анголи́, ве́летні сильні, що вико́нуєте Його слово, щоб слухати голосу слів Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 21, 'Благословіть Господа, усі сили небесні Його́, слу́ги Його, що чините волю Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 102, 22, 'Благословіть Господа, всі діла́ Його, на всіх місця́х царюва́ння Його! Благослови, душе моя, Го́спода!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 1, 'Благослови, душе моя, Господа! Господи, Боже мій, Ти ве́льми великий, зодягну́вся Ти в ве́лич та в славу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 2, 'Зодягає Він світло, як ша́ти, небеса́ простягає, немов би заві́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 3, 'Він ставить на во́дах пала́ти Свої, хма́ри кладе за Свої колесни́ці, ходить на кри́лах вітро́вих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 4, 'Він чинить вітри́ за Своїх посланці́в, палю́чий огонь — за Своїх слуг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 5, 'Землю Ти вгрунтува́в на осно́вах її, щоб на вічні віки вона не захита́лась,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 6, 'безо́днею вкрив Ти її, немов шатою. Стала вода над гора́ми, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 7, 'від погро́зи Твоєї вона втекла́, від гу́ркоту грому Твого побігла вона, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 8, 'виходить на го́ри та схо́дить в доли́ни, на місце, що Ти встанови́в був для неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 9, 'Ти границю поклав, щоб її вона не перейшла́, щоб вона не верну́лася землю покрити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 10, 'Він джере́ла пускає в пото́ки, що пливуть між гора́ми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 11, 'напува́ють вони всю пільну́ звірину́, ними дикі осли́ гасять спра́гу свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 12, 'Птаство небесне над ними живе, видає воно голос з-посе́ред галу́зок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 13, 'Він напоює горн з пала́ців Своїх, із плоду чи́нів Твоїх земля си́титься.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 14, 'Траву для худоби виро́щує, та зелени́ну для праці люди́ні, щоб хліб добува́ти з землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 15, 'і вино, що серце люди́ні воно звеселя́є, щоб більш від оливи блищало обличчя, і хліб, що серце люди́ні зміцня́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 16, 'Насичуються Господні дере́ва, ті ке́дри лива́нські, що Ти насади́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 17, 'що там ку́бляться пта́хи, бузько́, — кипари́си мешка́ння його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 18, 'Го́ри високі — для диких кози́ць, скелі — схо́вище ске́льним звіри́нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 19, 'і місяця Він учинив для озна́чення ча́су, сонце знає свій за́хід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 20, 'Темноту́ Ти наво́диш — і ніч настає, в ній пору́шується вся звіри́на лісна́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 21, 'рича́ть левчуки́ за здоби́чею та шукають від Бога своєї пожи́ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 22, 'Сонце ж засвітить — вони повтікають, та й кладуться по но́рах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 23, 'Люди́на виходить на працю свою, й на роботу свою аж до ве́чора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 24, 'Які то числе́нні діла Твої, Господи, — Ти мудро вчинив їх усіх, Твого тво́рива повна земля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 25, 'Ось море велике й розло́го-широ́ке, — там повзю́че, й числа їм немає, звіри́на мала́ та велика!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 26, 'Ходять там кораблі, там той левіята́н, якого створив Ти, щоб ба́витися йому в мо́рі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 27, 'Вони всі чекають Тебе, — щоб Ти ча́су свого поживу їм дав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 28, 'Даєш їм — збирають вони, руку Свою розкрива́єш — добром насича́ються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 29, 'Ховаєш обличчя Своє — то вони переля́кані, забираєш їм духа — вмирають вони, та й верта́ються до свого по́роху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 30, 'Посилаєш Ти духа Свого — вони тво́ряться, і Ти відновля́єш обличчя землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 31, 'Нехай буде слава Господня навіки, хай діла́ми Своїми радіє Господь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 32, 'Він погляне на землю — й вона затремти́ть, доторкне́ться до гір — і диму́юти вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 33, 'Я буду співати Господе́ві в своє́му житті, буду грати для Бога мого, аж поки живу́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 34, 'Буде приємна Йому моя мова, — я Господом буду радіти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 35, 'Неха́й згинуть грі́шні з землі,а безбожні — немає вже їх! Благослови, душе моя, Господа! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 103, 36, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 1, 'Дякуйте Господу, кличте Ім\'я́ Його́, серед наро́дів звіщайте про чи́ни Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 2, 'Співайте Йому, грайте Йому, говоріть про всі чу́да Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 3, 'Хваліться святим Його Йме́нням, хай ті́шиться серце шука́ючих Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 4, 'Пошу́куйте Господа й силу Його, лице Його за́вжди шукайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 5, 'Пам\'ятайте про чу́да Його, які Він учинив, про озна́ки Його та про при́суди уст Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 6, 'ви, насіння Авраама, раба Його, сини Яковові, вибра́нці Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 7, 'Він — Госпо́дь, Бог наш, по ці́лій землі Його при́суди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 8, 'Він пам\'ятає наві́ки Свого заповіта, те слово, яке наказав був на тисячу родів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 9, 'що склав Він його з Авраа́мом, і прися́гу Свою — для Ісака.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 10, 'Він поставив її за Зако́на для Якова, Ізраїлеві — заповітом навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 11, 'говорячи: „Я дам тобі Край ханаа́нський, частину спа́дщини для вас“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 12, 'Тоді їх було́ невелике число, нечисле́нні були та прихо́дьки на ній,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 13, 'і ходили вони від наро́ду до наро́ду, від царства до іншого лю́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 14, 'Не дозво́лив ніко́му Він кри́вдити їх, і за них Він царям докоря́в:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 15, '„Не дото́ркуйтеся до Моїх помаза́нців, а пророкам Моїм не робі́те лихого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 16, 'І покликав Він голод на землю, всяке хлі́бне стебло́ полама́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 17, 'Перед їхнім обличчям Він мужа послав, — за раба Йо́сип про́даний був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 18, 'Кайда́нами му́чили но́ги його, залізо пройшло в його тіло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 19, 'аж до ча́су випо́внення сло́ва Його, — слово Господнє його було ви́явило.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 20, 'Цар послав — і його розв\'яза́в, воло́дар народів — і його був звільни́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 21, 'Він настанови́в його паном над домом своїм, і воло́дарем над усім маєтком своїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 22, 'щоб в\'язни́в він його можновла́дців по волі своїй, а старших його умудря́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 23, 'І Ізраїль прибув до Єги́пту, і Яків заме́шкав у Ха́мовім кра́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 24, 'А наро́д Свій Він сильно розмно́жив, і зробив був рясні́шим його від його ворогів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 25, 'Він переміни́в їхнє серце, щоб народа Його ненави́діли, щоб брались на хи́трощі проти рабів Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 26, 'Він послав був Мойсея, Свого раба, Аарона, що вибрав його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 27, '— вони положили були серед них Його ре́чі знаме́нні, та чу́да у Ха́мовім кра́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 28, 'Він темно́ту наслав — і поте́мніло, і вони не проти́вились слову Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 29, 'Він перемінив їхню воду на кров, і вмори́в їхню рибу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 30, 'Їхній край зарої́вся був жа́бами, навіть в поко́ях царів їхніх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 31, 'Він сказав — й прибули́ рої мух, воші в ці́лому о́бширі їхньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 32, 'Він градом зробив їхній дощ, палю́чий огонь — на їхню землю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 33, 'І Він повибивав виноград їхній та фіґове дерево їхнє, і дереви́ну на о́бширі їхньому повило́млював.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 34, 'Він сказав — і найшла сарана́ та гу́сінь без ліку, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 35, 'усю ярину́ в їхнім кра́ї поже́рла, і плід землі їхньої з\'їла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 36, 'I Він повбивав усіх пе́рвістків в їхньому краї, поча́ток усякої їхньої сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 37, 'І Він ви́провадив їх у срі́блі та в золоті, і серед їхніх племе́н не було́, хто б спіткну́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 38, 'Єгипет радів, коли вийшли вони, бо страх перед ними напа́в був на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 39, 'Він хмару простяг на заслону, а огонь — на осві́тлення ночі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 40, 'Зажадав був Ізраїль — і Він перепели́ці наслав, і хлібом небесним Він їх годува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 41, 'Відчинив був Він скелю — й лину́ла вода, потекли́ були ріки в пустинях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 42, 'бо Він пам\'ятав за святе Своє слово, за Авраама, Свого раба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 43, 'І Він з радістю вивів наро́д Свій, зо співом — вибра́нців Своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 44, 'І їм землю наро́дів роздав, і посі́ли вони працю лю́дів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 104, 45, 'щоб вико́нували Його за́повіді, та зако́ни Його берегли́! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 1, 'Алілу́я! Дякуйте Господу, добрий бо Він, бо наві́ки Його милосе́рдя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 2, 'Хто розка́же про ве́лич Господню, розповість усю славу Його́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 3, 'Блаженні, хто де́ржиться права, хто чинить правду кожного ча́су!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 4, 'Згадай мене, Господи, в ласці Своїй до народу Свого́, відві́дай мене спасі́нням Своїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 5, 'щоб побачити добре вибра́нців Твоїх, щоб я ті́шився радощами Твого наро́ду, і хвалився зо спа́дком Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 6, 'Ми згрішили з батька́ми своїми, скриви́ли, неправди́ве чинили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 7, 'Не зважа́ли на чу́да Твої батьки наші в Єгипті, многоти́ Твоїх ласк не прига́дували й бунтува́лись над морем, над морем Черво́ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 8, 'Та Він ради Ймення Свого їх спас, щоб виявити Свою силу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 9, 'Він кли́кнув на море Червоне — і ви́сохло, і Він їх повів через мо́рські глиби́ни, немов по пустині!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 10, 'І Він спас їх з руки неприя́теля, визволив їх з руки ворога,—');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 11, 'і закрила вода супроти́вників їхніх, жоден з них не зоста́вся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 12, 'Тоді то в слова́ Його вві́рували, виспі́вували Йому славу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 13, 'Та скоро забули вони Його чин, не чекали пора́ди Його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 14, 'і пала́ли в пустині жада́нням, і Бога в пустині ізнов випробо́вували,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 15, 'і Він їхнє жада́ння їм дав, але худість послав в їхню душу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 16, 'Та Мойсею поза́здрили в та́борі, й Ааронові, святому Господньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 17, 'Розкрилась земля — і Дата́на погли́нула, Авіро́нові збори накрила,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 18, 'і огонь запалав на їхніх збо́рах, — і по́лум\'я те попали́ло безбожних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 19, 'Зробили тельця́ на Хори́ві, і били поклони бовва́нові ви́литому, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 20, 'і змінили вони свою славу на образ вола́, що траву пожирає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 21, 'забули про Бога, свого Спасителя, що велике в Єгипті вчинив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 22, 'у землі Ха́мовій чу́да, страшні ре́чі над морем Червоним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 23, 'І сказав Він пони́щити їх, коли б не Мойсей, вибра́нець Його, що став був у ви́ломі перед обличчям Його — відверну́ти Його гнів, щоб не шкодив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 24, 'Погордили землею жада́ною, не повірили сло́ву Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 25, 'і ре́мствували по наме́тах своїх, неслухня́ні були́ до Господнього голосу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 26, 'І Він підійняв Свою ру́ку на них, щоб їх повали́ти в пустині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 27, 'і щоб повалити їхнє пото́мство посеред наро́дів, та щоб розпоро́шити їх по країнах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 28, 'І служили Ваа́лові пео́рському, й їли вони жертви мертвих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 29, 'і діла́ми своїми розгні́вали Бога, — тому вдерлась зара́за між них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 30, 'І встав тоді Пі́нхас та й розсуди́в, — і зара́за затри́малась,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 31, 'і йому порахо́вано в праведність це, з роду в рід аж навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 32, 'І розгні́вали Бога вони над водою Мері́ви, і через них стало зле для Мойсея,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 33, 'бо духа його засмути́ли, і він говорив нерозва́жно уста́ми своїми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 34, 'Вони не позни́щували тих наро́дів, що Господь говорив їм про них, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 35, 'і поміша́лись з пога́нами, та їхніх учинків навчи́лись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 36, 'І бо́жищам їхнім служили, а ті па́сткою стали для них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 37, 'І прино́сили в жертву синів своїх, а дочо́к своїх — де́монам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 38, '— і кров чисту лили́, кров синів своїх і дочо́к своїх, що їх у жертву прино́сили бо́жищам ханаа́нським. І через кривавий пере́ступ земля поскверни́лась,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 39, 'і стали нечисті вони через учи́нки свої, і пере́люб чинили діла́ми своїми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 40, 'І проти наро́ду Свого запалав гнів Господній, і спа́док Його Йому став оги́дним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 41, 'і віддав їх у руку наро́дів, — і їхні нена́висники панували над ними,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 42, 'і їхні вороги їх гноби́ли, і вони впокори́лися під їхню руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 43, 'Багато разі́в Він визво́лював їх, але вони вперті були́ своїм за́думом, — і пригно́блено їх через їхню прови́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 44, 'Та поба́чив Він їхню тісно́ту, коли почув їхні блага́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 45, 'і Він пригадав їм Свого заповіта, і пожалував був за Своєю великою милістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 46, 'і збудив милосердя до них між усі́ма, що їх полони́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 47, 'Спаси́ нас, о Господи, Боже наш, і нас позбирай з-між наро́дів, щоб дя́кувати Йме́нню святому Твоєму, щоб Твоєю хвали́тися славою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 105, 48, 'Благословенний Господь, Бог Ізраїлів звіку й наві́ки! І ввесь наро́д нехай скаже: Амі́нь! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 1, '„Дякуйте Господу, добрий бо Він, бо наві́ки Його милосердя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 2, 'хай так скажуть ті всі, що Госпо́дь урятував їх, що ви́зволив їх з руки ворога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 3, 'і з країв їх зібрав, — від сходу й захо́ду, від пі́вночі й моря!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 4, 'Блудили вони по пустині дорогою голою, осілого міста не знахо́дили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 5, 'голодні та спра́гнені, і в них їхня душа омліва́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 6, 'І в недолі своїй вони Го́спода кли́кали, і Він визволяв їх від у́тисків їхніх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 7, 'І Він їх попрова́див дорогою про́стою, щоб до міста осілого йшли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 8, 'Нехай же подя́ку складу́ть Господе́ві за милість Його, та за чу́да Його синам лю́дським,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 9, 'бо наси́тив Він спра́гнену Душу, а душу голодну напо́внив добром!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 10, 'Ті, хто перебував був у те́мряві та в сме́ртній ті́ні, то в\'я́зні біди та заліза,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 11, 'бо вони спротивля́лися Божим слова́м, і відки́нули раду Всевишнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 12, 'Та Він упокори́в їхнє серце терпі́нням, спіткну́лись вони — і ніхто не поміг,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 13, 'і в недолі своїй вони Господа кли́кали, і Він визволя́в їх від у́тисків їхніх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 14, 'І Він вивів їх з те́мряви й мо́року, їхні ж кайда́ни сторо́щив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 15, 'Нехай же подяку складуть Господе́ві за милість Його, та за чу́да Його синам лю́дським,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 16, 'бо Він полама́в мідні двері, і засу́ви залізні зрубав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 17, 'Нерозумні страждали за грішну дорогу свою й за свої беззаконня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 18, 'Душа їхня від усякої їжі відве́рталася, — і дійшли вони аж до брам смерти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 19, 'і в недолі своїй вони Господа кли́кали, і Він визволяв їх від у́тисків їхніх, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 20, 'Він послав Своє слово та їх уздоро́вив, і їх урятував з їхньої хвороби!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 21, 'Нехай же подяку складуть Господе́ві за милість Його та за чу́да Його синам лю́дським,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 22, 'і хай жертви подяки прино́сять, і хай розповіда́ють зо співом про чи́ни Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 23, 'Ті, хто по морю пливе́ корабля́ми, хто чинить зайняття своє на великій воді, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 24, 'вони бачили чи́ни Госпо́дні та чу́да Його в глибині!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 25, 'Він скаже — і буря зривається, і підно́сяться хвилі Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 26, 'до неба вони підійма́ються, до безодні спада́ють, — у небезпеці душа їхня хвилюється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 27, 'Вони крутяться й ходять вперед та назад, як п\'яни́й, і вся́ їхня мудрість бенте́житься!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 28, 'Та в недолі своїй вони Господа кликали, і Він визволяв їх від у́тисків їхніх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 29, 'Він змінює бурю на ти́шу, — і стихають їхні хвилі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 30, 'і раділи, що вти́хли вони, і Ві́н їх привів до бажа́ної при́стані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 31, 'Нехай же подяку складуть Господе́ві за милість, та за чу́да Його синам лю́дським!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 32, 'Нехай величають Його на наро́дньому зборі, і нехай вихваля́ють Його на засі́данні старших!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 33, 'Він обе́ртає рі́чки в пустиню, а водні джере́ла — на суході́л,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 34, 'плодю́чу землю — на солонча́к через зло́бу мешка́нців її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 35, 'Він пустиню обе́ртає в водне болото, а землю суху́ — в джерело́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 36, 'і голодних садо́вить Він там, а вони ставлять місто на ме́шкання,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 37, 'і поля́ засіва́ють, і виногра́дники са́дять, — і отримують плід урожа́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 38, 'І благословляє Він їх, — і сильно розмно́жуються, і оде́ржують плід урожа́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 39, 'Та змаліли вони й похили́лися з утиску злого та з сму́тку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 40, 'Виливає Він га́ньбу на можних, — і блу́дять вони без дороги в пустині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 41, 'а вбогого Він підіймає з убо́зтва, і розмно́жує роди, немов ту ота́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 42, 'Це бачать правдиві й радіють, і закриває уста́ свої всяке безправ\'я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 106, 43, 'Хто мудрий, той все це завва́жить, — і пізна́ють вони́ милосердя Господнє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 1, 'Пісня. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 2, 'Моє серце зміцни́лося, Боже, — я буду співати та сла́вити ра́зом з своєю хвало́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 3, 'Збудися ж ти, а́рфо та ци́тро, — я буду будити досві́тню зорю́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 4, 'Я буду Тебе вихваля́ти, о Господи, серед наро́дів, і буду співати Тобі між племе́нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 5, 'бо більше від неба Твоє милосердя, а правда Твоя — аж до хмар!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 6, 'Піднеси́ся ж, о Боже, над небо, а слава Твоя — над усією землею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 7, 'Щоб любі Твої були ви́зволені, Своєю прави́цею допоможи́ й обізви́ся до нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 8, 'У святині Своїй Бог промовив: „Нехай Я звеселю́ся, — розділю́ Я Сихе́м, і долину Сукко́тську помі́ряю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 9, 'Належить Мені Ґілеа́д, і Мені Манасі́я, а Єфре́м — охорона Моєї голови, Юда — бе́рло Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 10, 'Моа́в — то мідни́ця Мого миття́, на Едо́м узуття́м Своїм кину, над Филисте́єю буду погу́кувати!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 11, 'Хто мене запрова́дить до міста тверди́нного, хто до Едо́му мене приведе́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 12, 'Хіба ж Ти покинув нас, Боже, і серед нашого ві́йська не ви́йдеш вже, Боже?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 13, 'Подай же нам поміч на ворога, лю́дська бо поміч — марно́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 107, 14, 'Ми мужність пока́жемо в Бозі, — і Він пото́пче проти́вників наших!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 1, 'Для дириґента хору. Псалом Давидів. Боже слави моєї, не будь мовчазли́вий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 2, 'бо мої вороги́ порозкрива́ли на мене уста́ нечести́ві та пе́льки лукаві, язиком неправди́вим говорять зо мною!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 3, 'І вони оточили мене словами нена́висти, і без причини на мене воюють,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 4, 'обмовля́ють мене за любов мою, а я — молюся за них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 5, 'вони віддають мені злом за добро, і не́навистю — за любов мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 6, 'Постав же над ним нечестивого, і по правиці його сатана́ нехай стане!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 7, 'Як буде суди́тись — нехай вийде винним, молитва ж його бодай стала гріхом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 8, 'Нехай дні його будуть коро́ткі, хай інший маєток його забере́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 9, 'Бодай діти його стали си́ротами, а жінка його — удовою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 10, 'І хай діти його все мандру́ють та же́брають, і нехай вони просять у тих, хто їх руйнував!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 11, 'Бодай їм тене́та розставив лихва́р на все, що його, і нехай розграбу́ють чужі його працю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 12, 'Щоб до нього ніхто милосердя не виявив, і бодай не було його си́ротам милости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 13, 'Щоб на зни́щення стали наща́дки його, бодай було скре́слене в другому роді ім\'я́ їхнє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 14, 'Беззаконня батькі́в його хай пам\'ята́ється в Господа, і хай не стирається гріх його матері!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 15, 'Нехай будуть вони перед Господом за́вжди, а Він нехай вирве з землі їхню пам\'ять, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 16, 'во́рог бо не пам\'ятав милосердя чини́ти, і напастува́в був люди́ну убогу та бідну, та серцем засму́чену, щоб убивати її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 17, 'Полюбив він прокля́ття, бодай же на нього воно надійшло! — і не хотів благослове́ння, — щоб воно віддалилось від нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 18, 'Зодягнув він прокляття, немов свою одіж, прося́кло воно, як вода, в його ну́тро, та в кості його, мов олива!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 19, 'Бодай воно стало йому за одежу, в яку зодягне́ться, і за пояс, що за́вжди він ним підпере́жеться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 20, 'Це заплата від Господа тим, хто мене обмовля́є, на душу мою нагово́рює зло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 21, 'А Ти Господи, Владико, зо мною зроби ради Йме́ння Свого́, що добре Твоє милосердя, — мене порятуй,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 22, 'бо я вбогий та бідний, і зра́нене серце моє в моїм ну́трі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 23, 'Я ходжу́, мов та тінь, коли хи́литься день, немов сарана́ — я відки́нений!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 24, 'Коліна мої знеси́лилися з по́сту, і ви́худло тіло моє з недостачі оливи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 25, 'і я став для них за посміхо́вище, коли бачать мене, — головою своєю хитають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 26, 'Поможи мені, Господи, Боже мій, за Своїм милосердям спаси Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 27, 'І нехай вони знають, що Твоя це рука, що Ти, Господи, все це вчини́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 28, 'Нехай проклинають вони, Ти ж поблагослови́! Вони повстають, та нехай засоро́млені бу́дуть, а раб Твій раді́тиме!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 29, 'Хай зодя́гнуться га́ньбою ті, хто мене обмовля́є, і хай вони сором свій вдягнуть, як шату!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 30, 'Я уста́ми своїми хвали́тиму голосно Господа, і між багатьма́ Його сла́вити буду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 108, 31, 'бо стоїть на правиці убогого Він для спасі́ння від тих, хто осуджує душу його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 1, 'Псалом Давидів. Промовив Господь Господе́ві моєму: „Сядь право́руч Мене, доки не покладу́ Я Твоїх ворогів за підні́жка ногам Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 2, 'Госпо́дь із Сіону пошле бе́рло сили Своєї, — пануй Ти поміж ворога́ми Своїми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 3, 'Наро́д Твій готовий у день військово́го побо́ру Твого, — в оздо́бах святині із ло́ня зірни́ці прилине для Тебе, немов та роса, Твоя молодість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 4, 'Поклявся Господь, — і не буде жаліти: „Ти священик навіки за чином Мелхиседе́ковим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 5, 'По прави́ці Твоїй розторо́щить Владика царів у день гніву Свого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 6, 'Він буде суди́ти між наро́дами, землю ви́повнить тру́пами, розторо́щить Він голову в кра́ї великім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 109, 7, 'Буде пити з струмка́ на дорозі, тому́ то піді́йме Він го́лову!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 1, 'Алілу́я! Буду сла́вити Господа з повного серця, — в колі праведних та на згрома́дженні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 2, 'Великі Господні діла́, — вони пожада́ні для всіх, хто їх любить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 3, 'Його діло — краса́ та вели́чність, а правда Його пробува́є навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 4, 'Він па́м\'ятку чудам Своїм учинив, — милости́вий та щедрий Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 5, 'Пожи́ву дає Він для тих, хто боїться Його, заповіта Свого пам\'ятає пові́к!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 6, 'Силу чи́нів Своїх об\'явив Він наро́дові Своє́му, щоб спа́дщину наро́дів їм дати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 7, 'Діла́ рук Його — правда та право, всі нака́зи Його справедли́ві, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 8, 'вони крі́пкі на вічні віки́, вони зро́блені вірністю і правотою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 9, 'Послав Він Своєму наро́дові визво́лення, заповіта Свого поставив наві́ки, святе та грізне́ Його Йме́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 110, 10, 'Поча́ток премудрости — страх перед Господом, — добрий розум у тих, хто вико́нує це, Його слава навіки стоїть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 1, 'Алілу́я! Блажен муж, що боїться Господа, що заповіді Його любить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 2, 'Буде си́льним насі́ння його на землі, буде поблагосло́влений рід безневи́нних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 3, 'Багатство й достаток у домі його, а правда його пробува́є навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 4, 'Світло схо́дить у те́мряві для справедливих, — Він ласка́вий, і милости́вий, і праведний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 5, 'Добрий муж милости́вий та позичає, уде́ржує справи свої справедливістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 6, 'і наві́ки він не захита́ється, — у вічній па́м\'яті праведний бу́де!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 7, 'Не боїться він зві́стки лихої, його серце міцне́, наді́ю складає на Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 8, 'Умі́цнене серце його не боїться, бо він бачить нещастя поміж ворога́ми своїми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 9, 'Він щедро убогим дає, його правда наві́ки стоїть, його ріг підіймається в славі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 111, 10, 'Це бачить безбожний та гні́вається, скрего́че зубами своїми та та́не. Бажа́ння безбожних загине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 1, 'Алілуя! Хваліте, Господні раби, хваліть Ім\'я́ Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 2, 'Нехай буде благословенне Господнє Ім\'я́ відтепе́р і навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 3, 'Від сходу сонця аж до захо́ду його — прославляйте Господнє Ім\'я́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 4, 'Господь підіймається над усі наро́ди, Його слава понад небеса́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 5, 'Хто подібний до Господа, нашого Бога, що ме́шкає на висоті́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 6, 'та знижується, щоб побачити те, що на небеса́х і на землі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 7, 'Бідаря́ Він підво́дить із по́роху, зо сміття́ підіймає нужде́нного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 8, 'щоб його посади́ти з вельмо́жними, з вельмо́жними люду Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 112, 9, 'Він неплідну в домі садо́вить за радісну матір дітей! Алілуя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 1, 'Як виходив Ізраїль з Єгипту, від наро́ду чужого дім Яковів, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 2, 'Юда став за святиню Йому, а Ізраїль — Його панува́нням!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 3, 'Побачило море все це — і побі́гло, Йорда́н повернувся наза́д!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 4, 'Го́ри скака́ли, немов баранці́, а пагі́рки — немов ті ягня́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 5, 'Що́ тобі, море, що ти втікаєш? Йорда́не, що ти поверну́вся наза́д?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 6, 'Чого ска́чете, гори, немов баранці́, а па́гірки — мов ті ягня́та?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 7, 'Тремти, зе́мле, перед Господнім лицем, перед лицем Бога Якова,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 8, 'що скелю обе́ртає в озеро водне, а кремінь — на водне джере́ло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 9, 'Не нам, Господи, не нам, але Йменню Своє́му дай славу за милість Твою, за правду Твою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 10, 'Пощо мають казати наро́ди: „Де́ ж то їхній Бог?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 11, 'А Бог наш на небі, — усе, що хотів, учинив');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 12, 'Їхні божки́ — срібло й золото, ді́ло рук лю́дських:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 13, 'вони мають уста́ — й не гово́рять, очі мають вони — і не бачать,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 14, 'мають уші — й не чують, мають носа — й без ню́ху,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 15, 'мають руки — та не дотика́ються, мають ноги — й не ходять, своїм го́рлом вони не говорять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 16, 'Нехай стануть такі, як вони, ті, хто їх виробля́є, усі, хто наді́ю на них поклада́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 17, 'Ізраїлю, — наді́ю складай лиш на Господа: Він їм поміч та щит їм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 18, 'Ааро́новий доме, — наді́йтесь на Господа: Він їм поміч та щит їм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 19, 'Ті, що Господа боїте́ся, — наді́йтесь на Господа: Він їм поміч та щит їм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 20, 'Господь пам\'ятає про нас, — нехай поблагосло́вить! Нехай поблагосло́вить Ізраїлів дім, нехай поблагосло́вить Він дім Ааро́нів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 21, 'Нехай поблагосло́вить Він тих, хто має до Господа страх, мали́х та великих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 22, 'Нехай вас розмножить Госпо́дь, — вас і ваших діте́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 23, 'Благословенні ви в Господа, що вчинив небо й землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 24, 'Небо, — небо для Господа, а землю віддав синам лю́дським!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 25, 'Не мертві хвалитимуть Господа, ані ті всі, хто сходить у місце мовча́ння, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 113, 26, 'а ми благословля́тимемо Господа — відтепе́р й аж навіки! Алілуя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 1, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 2, 'бо Він нахилив Своє ухо до мене, і я кли́катиму в свої дні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 3, 'Болі смерти мене оточи́ли і знайшли мене му́ки шео́лу, нещастя та сму́ток знайшов я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 4, 'А я в Ім\'я́ Господа кличу: „О Господи, ви́зволи ж душу мою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 5, 'Господь милости́вий та справедливий, і наш Бог милосердний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 6, 'Пильнує Господь недосві́дчених, — став я нужде́нний, та Він допомо́же мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 7, 'Вернися, о душе́ моя, до свого відпочи́нку, бо Госпо́дь робить добре тобі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 8, 'бо від смерти Ти ви́зволив душу мою, від сльози́ — моє око, ногу мою від спотика́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 9, 'Я ходитиму перед обличчям Господнім на землях живих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 10, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 11, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 12, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 13, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 14, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 15, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 16, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 17, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 114, 18, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 1, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 2, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 3, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 4, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 5, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 6, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 7, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 8, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 9, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 10, 'Я вірив, коли говорив: „Я сильно пригні́чений!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 11, 'Я сказав був у по́спіху: Кожна люди́на говорить неправду!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 12, 'Чим я відплачу́ Господе́ві за всі доброді́йства Його на мені?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 13, 'Я чашу спасі́ння прийму́, і прикли́чу Господнє Ім\'я́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 14, 'Прися́ги свої Господе́ві я ви́конаю перед усім наро́дом Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 15, 'Дорога́ в очах Господа смерть богобі́йних Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 16, 'О Господи, я бо Твій раб, я Твій раб, син Твоєї неві́льниці, — Ти кайда́ни мої розв\'яза́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 17, 'Я жертву подяки Тобі принесу́, і Господнім Ім\'я́м буду кли́кати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 18, 'Прися́ги свої Господе́ві я виконаю перед усім наро́дом Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 115, 19, 'на подві́р\'ях Господнього Дому, посеред тебе, о Єрусалиме! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 116, 1, 'Хваліть Господа, всі племена, прославляйте Його, всі наро́ди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 116, 2, 'бо зміцни́лось Його милосердя над нами, а правда Господня наві́ки! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 1, 'Дякуйте Господу, добрий бо Він, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 2, 'Нехай скаже Ізраїль, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 3, 'Нехай скаже дім Ааро́нів, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 4, 'Нехай скажуть ті, хто бої́ться Господа, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 5, 'У тісно́ті я кли́кав до Господа, — і просто́ром озвався до мене Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 6, 'Зо мною Господь — не боюся ніко́го, що зро́бить люди́на мені?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 7, 'Господь серед тих, що мені помагають, — і побачу загибіль своїх ненави́сників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 8, 'Краще вдаватись до Господа, ніж наді́ятися на люди́ну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 9, 'краще вдаватись до Господа, ніж наді́ятися на вельмо́жних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 10, 'Всі наро́ди мене оточи́ли, — я ж Господнім Ім\'я́м їх понищив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 11, 'Оточи́ли мене й обступили мене, — я ж Господнім Ім\'я́м їх понищив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 12, 'Оточили мене немов бджо́ли, та погасли вони, як терно́вий огонь, — я бо Господнім Ім\'я́м їх понищив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 13, 'Дошкульно попхну́в ти мене на паді́ння, — та Господь спас мене́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 14, 'Господь моя сила та пісня, і став Він спасі́нням мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 15, 'Голос співу й спасі́ння в наметах між пра́ведників: „Госпо́дня прави́ця виконує чу́да!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 16, 'Правиця Господня підно́ситься, прави́ця Господня вико́нує чу́да!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 17, 'Не помру́, але жи́тиму, і буду звіщати про чи́ни Господні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 18, 'Покара́ти мене — покарав був Госпо́дь, та смерти мені не завдав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 19, 'Відчиніте мені брами правди, — я ними ввійду́, буду сла́вити Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 20, '„Це брама Господня, — праведники в неї вхо́дять“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 21, 'Я буду хвалити Тебе, бо озвався до мене, і став Ти спасі́нням мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 22, 'Камінь, що його будівни́чі відки́нули, той нарі́жним став каменем, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 23, 'від Господа ста́лося це, і дивне воно в очах наших!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 24, 'Це день, що його́ створи́в Господь, — радіймо та тішмося в нім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 25, 'Про́симо, Господи, — спаси! Про́симо, Господи, — пощасти́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 26, 'Благословен, хто гряде́ у Господнє Ім\'я́! Благословляємо вас із Господнього дому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 27, 'Господь — Бог, і зася́яв Він нам. Прив\'яжі́те святковую жертву шнура́ми аж до нарі́жників же́ртівника!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 28, 'Ти мій Бог, і я бу́ду Тебе прославля́ти, мій Боже, я буду Тебе велича́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 117, 29, 'Дякуйте Господу, добрий бо Він, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 1, 'Блаже́нні непоро́чні в доро́зі, що ходять Зако́ном Господнім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 2, 'Блаженні, хто держить свідо́цтва Його, хто шукає Його́ всім серцем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 3, 'і хто кривди не робить, хто ходить путя́ми Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 4, 'Ти видав нака́зи Свої, щоб вико́нувати пильно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 5, 'Коли б же доро́ги мої були пе́вні, щоб держа́тиси Твоїх постано́в, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 6, 'не бу́ду тоді засоро́млений я, як буду дивитись на всі Твої за́повіді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 7, 'Щирим серцем я буду Тебе прославля́ти, як навчу́ся зако́нів Твоїх справедливих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 8, 'Я буду держа́тись Твоїх постано́в, — не кидай же зо́всім мене́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 9, 'Чим доде́ржить юнак у чистоті свою сте́жку? — Як держа́тиметься Твоїх слів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 10, 'Цілим серцем своїм я шукаю Тебе, — не дай же мені заблуди́тися від Твоїх заповідей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 11, 'Я в серці своїм заховав Твоє слово, щоб мені не гріши́ти проти Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 12, 'Благослове́н єси́, Господи, навчи мене постано́в Своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 13, 'Уста́ми своїми я розповідаю про всі при́суди уст Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 14, 'З дороги свідо́цтв Твоїх раді́ю я, як маєтком великим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 15, 'Про нака́зи Твої розмовлятиму я, і на стежки́ Твої буду дивитись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 16, 'Я буду радіти Твоїми постано́вами, сло́ва Твого не забуду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 17, 'Своє́му рабові пощасти́, щоб я жив, — і я буду держатися сло́ва Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 18, 'Відкрий мої очі, і хай чу́да Зако́ну Твого я побачу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 19, 'На землі я прихо́дько, — Своїх заповідей не ховай Ти від мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 20, 'Омліва́є душа моя з ту́ги за Твоїми зако́нами кожного ча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 21, 'Насвари́в Ти прокля́тих отих гордуні́в, що вхиля́ються від Твоїх заповідей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 22, 'Відверни́ Ти від ме́не знева́гу та сором, бо держу́ся свідо́цтв Твоїх я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 23, 'Теж вельмо́жі сидять та на мене змовля́ються, та Твій раб про постано́ви Твої розмовля́є,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 24, 'і свідо́цтва Твої — то потіха моя, то для мене дора́дники!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 25, 'Душа моя гнеться до по́роху, — за словом Своїм оживи Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 26, 'Про доро́ги свої я каза́в, і почув Ти мене, — навчи Ти мене постано́в Своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 27, 'Дай мені розуміти доро́гу нака́зів Твоїх, — і про чу́да Твої я звіща́тиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 28, 'Розплива́є зо сму́тку душа моя, постав мене згідно зо словом Своїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 29, 'Дорогу неправди від мене відсу́нь, і дай мені з ласки Своєї Зако́на!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 30, 'Я вибрав путь правди, зако́ни Твої біля себе поставив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 31, 'До свідо́цтв Твоїх я приєдна́вся, — Господи, не посоро́м же мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 32, 'Буду бігти шляхо́м Твоїх заповідей, бо поши́риш Ти серце моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 33, 'Путь Своїх постано́в покажи мені, Господи, — і я буду держа́тись її до кінця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 34, 'Дай мені зрозуміти, і нехай я держу́ся Зако́ну Твого́, і всім серцем я буду трима́тись його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 35, 'Провадь мене сте́жкою Твоїх за́повідей, бо в ній я знайшов уподо́бу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 36, 'Серце моє прихили́ до свідо́цтв Твоїх, а не до ко́ристи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 37, 'Відверни мої очі, щоб марно́ти не бачили, — на дорозі Своїй оживи́ Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 38, 'Для Свого раба сповни слово Своє, що на страх Твій воно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 39, 'Відверни Ти від мене знева́гу, якої боюся, бо добрі зако́ни Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 40, 'Ось я прагну нака́зів Твоїх, — оживи́ мене правдою Своєю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 41, 'І хай зі́йде на мене, о Господи, милість Твоя, спасі́ння Твоє, згідно з словом Твоїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 42, 'і нехай відпові́м я тому́, хто словом ганьби́ть мене, бо наді́юсь на слово Твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 43, 'І не відійма́й з моїх уст слова правди ніко́ли, бо я жду Твоїх при́судів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 44, 'А я бу́ду держа́тися за́вжди Зако́ну Твого́, на вічні віки́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 45, 'І бу́ду ходити в широ́кості, бо нака́зів Твоїх я шукаю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 46, 'І бу́ду я перед царя́ми звіща́ти про свідо́цтва Твої, — й не зазнаю я со́рому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 47, 'І буду я розкошува́ти Твоїми заповідями, бо їх полюбив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 48, 'і я руки свої простягну́ до Твоїх заповідей, бо їх полюбив, і буду розду́мувати про Твої постано́ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 49, 'Пам\'ятай про те слово Своє́му рабові, що його наказав Ти чекати мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 50, 'Це розра́да моя в моїм горі, як слово Твоє оживля́є мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 51, 'Гордуни́ насміхалися з мене зана́дто, та я не відступив від Зако́ну Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 52, 'Твої при́суди я пам\'ята́ю відвіку, о Господи, — і раді́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 53, 'Буря мене обгорну́ла через нечестивих, що Зако́на Твого опускають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 54, 'Спі́ви для мене — Твої постано́ви у домі моєї мандрі́вки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 55, 'Я вночі пам\'ятаю Ім\'я́ Твоє, Господи, і держу́ся Зако́ну Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 56, 'Оце сталось мені, бо нака́зів Твоїх я держу́ся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 57, 'Я сказав: „Моя доля, о Господи, щоб держа́тись мені Твоїх слів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 58, 'Я благаю Тебе цілим серцем: Учини мені милість за словом Своїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 59, 'Я розва́жив доро́ги свої, й до свідо́цтв Твоїх но́ги свої зверну́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 60, 'Я спішу́ й не барю́ся вико́нувати Твої заповіді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 61, 'Тене́та безбожних мене оточи́ли, та я не забув про Зако́на Твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 62, 'Опівно́чі встаю я, щоб скласти подяку Тобі за при́суди правди Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 63, 'Я при́ятель всім, хто боїться Тебе́, й хто нака́зи Твої береже́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 64, 'Милосердя Твого, о Го́споди, повна земля, — навчи Ти мене Своїх постано́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 65, 'Ти з рабом Своїм добре зробив, Господи, за словом Своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 66, 'Навчи мене доброго розуму та пізнава́ння, бо в заповіді Твої ві́рую я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 67, 'Доки я не стражда́в, блудив був, та тепер я держусь Твого слова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 68, 'Ти добрий, і чиниш добро́, — навчи Ти мене Своїх постано́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 69, 'Гордуни́ вимишляють на мене неправду, — а я цілим серцем держуся нака́зів Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 70, 'Зробилось нечуле, як лій, їхнє серце, — а я розкошу́ю з Зако́ну Твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 71, 'Добре мені, що я зму́чений був, — щоб навчитися Твоїх постано́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 72, 'Ліпший для мене Зако́н Твоїх уст, аніж тисячі золота й срібла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 73, 'Руки Твої створи́ли мене й збудува́ли мене́, — подай мені розуму, й хай я навчу́сь Твоїх за́повідей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 74, 'Хто боїться Тебе, ті побачать мене та й зрадіють, бо я Твого сло́ва чекаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 75, 'Знаю я, Господи, що справедли́ві були́ Твої при́суди, і справедли́во мене понижа́в Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 76, 'Нехай буде милість Твоя на розра́ду мені, — за словом Твоїм до Свого раба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 77, 'Нехай зі́йде на мене Твоє милосердя, — й я жи́тиму, бо Зако́н Твій — розра́да моя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 78, 'Нехай гордуни́ посоро́млені будуть, бо робили нечесно, а я буду розду́мувати про нака́зи Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 79, 'До ме́не пове́рнуться ті, хто боїться Тебе, — і пізна́ють свідо́цтва Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 80, 'Нехай серце моє буде чисте в Твоїх постано́вах, щоб я не посоро́мився!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 81, 'Душа моя слабне від ту́ги за спасі́нням Твоїм, — чекаю я слова Твого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 82, 'За словом Твоїм га́снуть очі мої та питають: „Коли Ти потішиш мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 83, 'Хоч я став, як той міх у диму́, та Твоїх постано́в не забув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 84, 'Скільки днів для Твого раба? Коли при́суда зробиш моїм переслі́дникам?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 85, 'Гордуни́ покопа́ли були мені я́ми, що не за Зако́ном Твоїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 86, 'Усі Твої за́повіді справедливі; неправдиво мене переслі́дують, — допоможи́ Ти мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 87, 'Ма́лощо не погуби́ли мене на землі, — та я не покинув нака́зів Івоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 88, 'Оживи́ Ти мене за Своїм милосердям, — і я буду триматися свідчення уст Твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 89, 'Навіки, о Господи, слово Твоє в небеса́х пробува́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 90, 'З роду в рід Твоя правда; Ти землю поставив — і стала вона, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 91, 'усі за Твоїми суда́ми сьогодні стоять, бо раби Твої всі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 92, 'Коли б не Зако́н Твій, розра́да моя, то я був би загинув в недолі своїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 93, 'Я повік не забу́ду нака́зів Твоїх, бо Ти ними мене оживля́єш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 94, 'Твій я, спаси Ти мене, бо нака́зів Твоїх я шукаю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 95, 'Чека́ють безбожні забити мене, а я про свідо́цтва Твої розважаю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 96, 'Я бачив кінець усього́ доскона́лого, але́ Твоя заповідь ве́льми широка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 97, 'Як я коха́ю Зако́на Твого́, цілий день він — розмова моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 98, 'Твоя за́повідь робить мудрішим мене від моїх ворогів, — вона бо навіки моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 99, 'Я став розумніший за всіх своїх учителі́в, — бо свідо́цтва Твої — то розмова моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 100, 'Став я мудріший за ста́рших, — бо держуся нака́зів Твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 101, 'Я від кожної злої дороги повстри́мую но́ги свої, щоб держа́тися сло́ва Твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 102, 'Я не ухиляюся від Твоїх при́судів, Ти бо навчаєш мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 103, 'Яке то солодке слово Твоє для мого піднебі́ння, солодше від меду воно моїм у́стам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 104, 'Від нака́зів Твоїх я мудріший стаю, тому́ то нена́виджу всяку дорогу неправди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 105, 'Для моєї ноги Твоє слово світи́льник, то світло для сте́жки моєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 106, 'Я прися́г — і дотримаю, що бу́ду держа́тися при́судів правди Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 107, 'Перему́чений я аж зана́дто, — за словом Своїм оживи́ мене, Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 108, 'Хай же бу́дуть приємні Тобі жертви уст моїх, Господи, і навчи Ти мене Своїх при́судів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 109, 'У небезпеці душа моя за́вжди. але́ я Зако́ну Твого́ не забув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 110, 'Безбожні поставили па́стку на мене, та я не зблуди́в від нака́зів Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 111, 'Я навіки свідо́цтва Твої вспадкува́в, бо вони — радість серця мого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 112, 'Я серце своє нахили́в, щоб чинити Твої постано́ви, — повік, до кінця́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 113, 'Сумнівне нена́виджу я, а Зако́на Твого покоха́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 114, 'Ти моя охоро́на та щит мій, — чека́ю я сло́ва Твого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 115, 'Відступі́ться від мене, злочи́нці, і я бу́ду держатися заповідей мого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 116, 'За словом Своїм підіпри́ Ти мене, і я жи́тиму, і в надії моїй не завдай мені со́рому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 117, 'Підкріпи Ти мене — і спасуся, і я бу́ду дивитися за́вжди в Твої постано́ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 118, 'Ти пого́рджуєш усіма́, хто від Твоїх постано́в відступа́є, бо хи́трощі їхні — неправда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 119, 'Всіх безбожних землі відкидаєш, як жу́жель, тому́ покохав я свідо́цтва Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 120, 'Зо стра́ху Твого моє тіло тремти́ть, й я боюсь Твоїх при́судів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 121, 'Я право та правду чиню, щоб мене не віддав Ти моїм переслі́дникам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 122, 'Поручи́ Ти на добре Свого раба, щоб мене гордуни́ не гноби́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 123, 'Гаснуть очі мої за спасі́нням Твоїм та за словом правди Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 124, 'Учини ж Ти Своєму рабові за Своїм милосердям, і навчи Ти мене Своїх постано́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 125, 'Я раб Твій, і зроби мене мудрим, — і свідо́цтва Твої буду знати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 126, 'Це для Господа час, щоб дія́ти: Зако́на Твого унева́жнили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 127, 'Тому́ я люблю́ Твої заповіді більш від золота й щи́рого золота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 128, 'Тому́ всі нака́зи Твої уважаю за слу́шні, а кожну доро́гу неправди нена́виджу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 129, 'Чудо́ві свідо́цтва Твої, тому́ то душа моя де́ржиться їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 130, 'Вхід у слова́ Твої світло дає, недосві́дчених мудрими робить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 131, 'Я у́ста свої розкриваю й повітря ковта́ю, бо чую жадо́бу до Твоїх заповідей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 132, 'Оберни́ся до мене та будь милости́вий мені, Як чи́ниш Ти тим, хто кохає Іме́ння Твоє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 133, 'Своїм словом зміцни мої кро́ки, — і не дай панува́ти надо мною нія́кому про́гріхові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 134, 'Від лю́дського утиску ви́зволь мене, — і нехай я держу́ся нака́зів Твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 135, 'Хай зася́є лице Твоє на Твого раба, і навчи Ти мене уста́вів Своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 136, 'Пливуть во́дні пото́ки з оче́й моїх, бо Твого Зако́ну не доде́ржують.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 137, 'Ти праведний, Господи, і прямі́ Твої при́суди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 138, 'бо Ти наказа́в справедливі свідо́цтва Свої й щиру правду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 139, 'Ни́щить мене моя ре́вність, бо мої вороги́ позабува́ли слова́ Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 140, 'Ве́льми очи́щене слово Твоє, і Твій раб його любить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 141, 'Я мали́й і пого́рджений, та не забуваю нака́зів Твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 142, 'Праведність Твоя — праведність вічна, а Зако́н Твій — то правда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 143, 'Недоля та у́тиск мене обгорну́ли, — але́ Твої заповіді — моя ро́зкіш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 144, 'Правда свідо́цтв Твоїх вічна, — подай мені розуму, й бу́ду я жити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 145, 'Цілим серцем я кличу: почуй мене, Господи, і я бу́ду держа́тись уста́вів Твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 146, 'Я кличу до Тебе, — спаси Ти мене, і я бу́ду держа́тись свідо́цтв Твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 147, 'Світа́нок я ви́передив та й вже кличу, Твого сло́ва чека́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 148, 'Мої очі сторо́жі нічні́ випере́джують, щоб про слово Твоє розмовляти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 149, 'Почуй же мій голос з Свого милосердя, о Господи, оживи Ти мене́ з Свого при́суду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 150, 'Набли́жаться ті, що за чином гане́бним ганя́ють, від Зако́ну Твого далекі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 151, 'та близьки́й Ти, о Господи, а всі Твої за́повіді — справедливість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 152, 'Відда́вна я знаю свідо́цтва Твої, бо навіки Ти їх закла́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 153, 'Подивись на недолю мою та мене поряту́й, бо я не забуваю Зако́ну Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 154, 'Вступи́ся за справу мою й мене ви́зволи, за словом Своїм оживи Ти мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 155, 'Від безбожних спасі́ння дале́ке, бо вони не шукають Твоїх постано́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 156, 'Велике Твоє милосердя, о Господи, оживи́ Ти мене з Свого при́суду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 157, 'Багато моїх переслі́дників та ворогів моїх, — але від свідо́цтв Твоїх не відхиля́юсь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 158, 'Бачив я зрадників й бри́дився ними, бо не де́ржать вони Твого сло́ва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 159, 'Подивися: люблю́ я накази Твої, — за милосердям Своїм оживи́ мене, Господи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 160, 'Правда — підва́лина слова Твого, а при́суди правди Твоєї — навіки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 161, 'Безневи́нно вельмо́жі мене переслі́дують, та серце моє Твого слова боїться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 162, 'Радію я словом Твоїм, ніби здо́бич велику знайшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 163, 'Я неправду нена́виджу й бри́джуся нею, — покохав я Зако́на Твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 164, 'Сім раз денно я сла́влю Тебе через при́суди правди Твоєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 165, 'Мир великий для тих, хто кохає Зако́на Твого, — і не мають вони спотика́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 166, 'На спасі́ння Твоє я наді́юся, Господи, і Твої заповіді вико́ную.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 167, 'Душа моя де́ржить свідо́цтва Твої, і я сильно люблю́ їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 168, 'Я держу́ся нака́зів Твоїх та свідо́цтв Твоїх, бо перед Тобою мої всі доро́ги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 169, 'Блага́ння моє хай набли́зиться перед лице Твоє, Господи, за словом Своїм подай мені розуму!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 170, 'Нехай при́йде молитва моя перед лице Твоє, — за словом Своїм мене ви́зволь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 171, 'Нехай у́ста мої вимовля́ють хвалу́, бо уста́вів Своїх Ти навчаєш мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 172, 'Хай язик мій звіща́тиме слово Твоє, бо всі Твої за́повіді — справедли́вість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 173, 'Нехай буде рука Твоя в поміч мені, бо я вибрав нака́зи Твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 174, 'Я пра́гну спасі́ння Твого, о Господи, а Зако́н Твій — то ро́зкіш моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 175, 'Хай душа моя буде жива́, і хай сла́вить Тебе, а Твій при́суд нехай допоможе мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 118, 176, 'Я блукаю, немов та овечка загу́блена, — пошукай же Свого раба, бо я не забув Твоїх за́повідей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 1, 'Пісня проча́н. Я кликав до Господа в го́рі своїм, — і Він мене ви́слухав, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 2, 'Господи, ви́зволь же душу мою від губи́ неправди́вої, від язика́ зрадли́вого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 3, 'Що́ Тобі дасть, або що́ для Тебе дода́сть лукавий язик? —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 4, 'Заго́стрені стрі́ли поту́жного із ялівце́вим вугі́ллям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 5, 'Горе мені, що заме́шкую в Ме́шеху, що живу́ із шатра́ми Кеда́ру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 6, 'Довго душа моя перебува́ла собі разом з тими, хто нена́видить мир:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 119, 7, 'я — за мир, та коли говорю́, то вони — за війну́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 1, 'Пісня проча́н. Свої очі я зво́джу на го́ри, звідки при́йде мені допомо́га, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 2, 'мені допомо́га від Господа, що вчинив небо й зе́млю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 3, 'Він не дасть захита́тись нозі́ твоїй, не здріма́є твій Сто́рож:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 4, 'оце не дріма́є й не спить Сторож Ізра́їлів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 5, 'Госпо́дь — то твій Сторож, Госпо́дь — твоя тінь при прави́ці твоїй, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 6, 'удень сонце не вда́рить тебе, ані місяць вночі́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 7, 'Господь стерегти́ме тебе від усякого зла, стерегти́ме Він душу твою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 120, 8, 'Господь стерегти́ме твій ви́хід та вхід відтепе́р аж наві́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 1, 'Пісня проча́н. Давидова. Я радів, як каза́ли мені: „Ході́мо до дому Господнього!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 2, 'Ноги наші стояли в воро́тях Твоїх, Єрусали́ме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 3, 'Єрусалиме, збудо́ваний ти як те місто, що злу́чене ра́зом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 4, 'куди схо́дять племе́на, племе́на Господні, — щоб сві́дчити Ізра́їлеві, щоб Іме́нню Господньому дя́кувати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 5, 'Бо то там на престо́лах для суду сидять, на престолах дому Дави́дового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 6, 'Миру бажайте для Єрусалиму: „Нехай бу́дуть безпе́чні, хто любить тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 7, 'Нехай буде мир у твоїх передму́р\'ях, безпе́ка в пала́тах твоїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 8, 'Ради бра́тті моєї та дру́зів моїх я буду каза́ти: „Мир тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 121, 9, 'Ради дому Господа, нашого Бога, я буду шукати для тебе добра́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 122, 1, 'Пісня проча́н. Свої о́чі я зво́джу до Тебе, що на небеса́х пробува́єш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 122, 2, 'Ото бо, як очі рабів до руки́ їх панів, як очі неві́льниці — до руки́ її пані, отак наші очі до Го́спода, нашого Бога, аж поки не зми́лується Він над нами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 122, 3, 'Помилуй нас, Господи, помилуй нас, бо пого́рди ми до́сить наси́тились!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 122, 4, 'Душа наша наси́тилась до́сить собі: від безпе́чних — нару́ги, від пи́шних — пого́рди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 1, 'Пісня проча́н. Давидова. Коли б не Госпо́дь, що був з нами — нехай но Ізраїль пові́сть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 2, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 3, 'то нас поковта́ли б живце́м, коли розпали́вся на нас їхній гнів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 4, 'то нас позалива́ла б вода, душу нашу поті́к перейшов би.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 5, 'душу нашу тоді перейшла б та бурхли́ва вода!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 6, 'Благослове́нний Госпо́дь, що не дав нас на здо́бич для їхніх зубі́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 7, 'Душа наша, як птах, урятува́лась із сільця́ птахоло́вів, — сільце́ розірва́лось, а ми врятува́лись!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 123, 8, 'Наша поміч — ув Імені Господа, що вчинив небо й землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 124, 1, 'Пісня проча́н. Ті, хто наді́ю складає на Господа́, вони як Сіо́нська гора́, яка не захита́ється, яка буде стоя́ти пові́к!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 124, 2, 'Єрусали́м, — го́ри круг ньо́го, а Госпо́дь круг наро́ду Свого відтепе́р й аж наві́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 124, 3, 'Не спочине бо бе́рло нече́стивих на долі пра́ведних, щоб пра́ведні не простягли́ своїх рук до неправди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 124, 4, 'Зроби ж, Господи, до́бре для добрих, та для простосе́рдих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 124, 5, 'Тих же, що збо́чують на свої манівці́, — нехай їх прова́дить Господь разом із беззако́нцями! Мир на Ізра́їля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 1, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 2, 'Як вертався Госпо́дь із поло́ном Сіону, то були́ ми немо́в би у сні. Наші у́ста тоді були́ повні весе́лощів, а язик наш — співа́ння! Казали тоді між наро́дами: Велике вчини́в Господь з ними!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 3, 'Велике вчини́в Господь з нами, — були ра́дісні ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 4, 'Вернися ж із нашим поло́ном, о Господи, немо́в ті джере́ла, на пі́вдень!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 5, 'Хто сіє з слізьми́, зо спі́вом той жне:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 6, 'все хо́дить та плаче, хто но́сить торби́ну насіння на по́сів, — та ве́рнеться з співом, хто но́сить снопи́ свої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 125, 7, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 126, 1, 'Пісня проча́н. Соломо́нова. Коли дому Госпо́дь не буду́є, даре́мно працюють його будівни́чі при ньому! Коли мі́ста Господь не пильну́є, — даремно сторо́жа чува́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 126, 2, 'Даре́мно вам ра́но вставати, допі́зна сидіти, їсти хліб загорьо́ваний, — Він і в спанні́ подасть другові Своє́му!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 126, 3, 'Діти — спа́дщина Господнє, плід утро́би — нагоро́да!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 126, 4, 'Як стрі́ли в руках того ве́летня, так і сини́ молоді́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 126, 5, 'блаженний той муж, що сагайдака́ свого ними напо́внив, — не бу́дуть такі посоро́млені, коли в брамі вони говори́тимуть із ворога́ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 1, 'Пісня проча́н. Блаже́н кожен, хто боїться Господа, хто хо́дить путя́ми Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 2, 'Коли труд своїх рук будеш їсти, — блаже́н ти, і до́бре тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 3, 'Твоя жінка в кута́х твого дому — як та виногра́дина плі́дна, твої діти навко́ло твого стола́ — немов саджанці́ ті оли́вкові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 4, 'Оце так буде поблагосло́влений муж, що боїться він Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 5, 'Нехай поблагосло́вить тебе Господь із Сіо́ну, — і побачиш добро́ Єрусалиму по всі́ дні свого життя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 127, 6, 'і побачиш ону́ків своїх! Мир на Ізраїля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 1, 'Пісня проча́н. Багато гноби́ли мене від юна́цтва мого́, — нехай но Ізраїль пові́сть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 2, 'Багато гноби́ли мене від юна́цтва мого́, та мене не поду́жали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 3, 'Ора́ли були́ на хребті́ моїм плугатарі́, поклали вони довгі бо́розни,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 4, 'та Господь справедливий, — Він шну́ри безбожних порва́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 5, 'Нехай посоро́млені бу́дуть, і хай повідступа́ють назад усі ті, хто Сіона нена́видить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 6, 'Бодай стали вони, як трава на даха́х, що всихає вона, поки ви́росте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 7, 'що нею жмені своєї жнець не напо́внить, ані обере́мка свого в\'яза́льник,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 128, 8, 'і не скаже прохо́жий до них: „Благослове́ння Господнє на вас, благословля́ємо вас Ім\'я́м Господа!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 1, 'Пісня проча́н. З глибини́ я взива́ю до Тебе, о Господи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 2, 'Господи, ночуй же мій голос! Нехай уші Твої будуть чу́лі на голос блага́ння мого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 3, 'Якщо, Господи, бу́деш зважа́ти на беззако́ння, — хто всто́їть, Влади́ко?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 4, 'Бо в Тебе проба́чення, щоб боятись Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 5, 'Я наді́юсь на Господа, має надію душа моя, і на слово Його я впова́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 6, 'Виглядає душа моя Господа більш, ніж пора́нку сторо́жа, що до ранку вона стереже́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 7, 'Хай наді́ю складає Ізра́їль на Господа, бо з Господом милість, і велике визво́лення з Ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 129, 8, 'і Ізра́їля ви́зволить Він від усіх його про́гріхів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 130, 1, 'Пісня прочан. Давидова. Господи, серце моє не пишни́лось, і очі мої не підно́сились, і я не ганя́всь за реча́ми, що більші й дивніші над мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 130, 2, 'Таж я втихоми́рював і заспоко́ював душу свою, як дитя, від перс мами своєї відлу́чене, як дити́на відлу́чена в мене душа моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 130, 3, 'Хай наді́ю складає Ізраїль на Господа відтепе́р аж наві́ки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 1, 'Пісня проча́н. Згадай, Господи, про Давида, про всі його му́ки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 2, 'що клявсь Господе́ві, присяга́вся був Сильному Якова:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 3, '„Не ввійду́ я в наме́т свого дому, не зійду́ я на ложе постелі своєї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 4, 'не дам сну своїм о́чам, дріма́ння пові́кам своїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 5, 'аж поки не знайду́ я для Господа місця, місця перебува́ння для Сильного Якова“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 6, 'Ось ми чули про Нього в Ефра́фі, на Яа́рських полях ми знайшли Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 7, 'Увійдім же в мешка́ння Його, поклоні́мось підні́жкові ніг Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 8, 'Встань же Господи, йди до Свого відпочи́нку, Ти й ковчег сили Твоєї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 9, 'Священики Твої хай зодя́гнуться в правду, і будуть співати Твої богобі́йні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 10, 'Ради Давида, Свого раба, не відве́ртай лиця́ від Свого́ помаза́нця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 11, 'Господь присягнув був Давидові правду, і не відступить від неї: „Від пло́ду утро́би твоєї Я посаджу́ на престолі твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 12, 'Якщо бу́дуть сино́ве твої пильнува́ти Мого́ заповіта й свідо́цтва Мого, що його Я навча́тиму їх, то й сини їхні на вічні віки́ будуть сидіти на троні твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 13, 'Бо вибрав Сіо́на Госпо́дь, уподо́бав його на осе́лю Собі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 14, '„То місце Мого відпочинку на вічні віки́, пробуватиму тут, бо його уподо́бав, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 15, 'пожи́ву його щедро благословлю́, і хлібом убогих його нагоду́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 16, 'Священиків його зодягну́ у спасі́ння, а його богобійні співатимуть радісно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 17, 'Я там ви́рощу рога Давидового, для Свого помаза́нця вготую світи́льника, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 131, 18, 'ворогів його со́ромом позодяга́ю, а на ньому корона його буде ся́яти“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 132, 1, 'Пісня проча́н. Давидова. Оце яке добре та гарне яке, — щоб жи́ти братам одноку́пно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 132, 2, 'Воно — як та добра оли́ва на го́лову, що сплива́є на бо́роду, Ааро́нову бо́роду, що спливає на кі́нці одежі його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 132, 3, 'Воно — як хермо́нська роса́, що спадає на го́ри Сіо́ну, бо там наказав Господь благослове́ння, повікві́чне життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 133, 1, 'Пісня проча́н. Поблагослові́ть оце Господа, всі раби Господні, що по но́чах у домі Господньому ви стоїте́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 133, 2, 'Ваші руки здіймі́ть до святині, і Господа благослові́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 133, 3, 'Нехай поблагосло́вить тебе із Сіону Госпо́дь, що вчини́в небо й землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 1, 'Алілу́я! Хваліте Господнє Ім\'я́, хваліте, Господні раби,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 2, 'що стоїте́ в домі Господньому, на подві́р\'ях дому нашого Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 3, 'Хваліть Господа, — бо добрий Госпо́дь, співайте Іме́нню Його, — бо приємне воно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 4, 'бо вибрав Господь собі Якова, Ізраїля — на власність Свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 5, 'Знаю бо я, що Господь і Владика наш більший від богів усіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 6, 'Все, що хоче Господь, те Він чинить на небі та на землі, на моря́х та по всяких глиби́нах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 7, 'Підіймає Він хмари від кра́ю землі, блискави́ці вчинив для дощу́, випрова́джує вітер з запа́сів Своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 8, 'Він позабива́в перворідних Єгипту, від люди́ни аж до скотини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 9, 'Він послав між Єгипет озна́ки та чу́да, — на фараона і на рабів всіх його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 10, 'Він ура́зив багато наро́дів, і поту́жних царів повбива́в:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 11, 'Сиго́на, царя аморе́ян, і Оґа, Баша́ну царя, та всіх ханаа́нських царів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 12, 'І Він дав їхню землю спадщиною, на спа́док Ізра́їлеві, Своєму наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 13, 'Господи, Йме́ння Твоє вікові́чне, Господи, — пам\'ять Твоя з роду в рід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 14, 'Бо буде суди́ти Господь Свій наро́д, та змилосе́рдиться Він над Своїми раба́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 15, 'Божки лю́дів — то срі́бло та золото, ді́ло рук лю́дських:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 16, 'вони мають уста́ — й не говорять, очі мають вони — і не бачать,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 17, 'мають уші — й не чують, в їхніх уста́х нема ві́ддиху!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 18, 'Нехай стануть такі, як вони, ті, хто їх виробля́є, усі, хто надію на них покладає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 19, 'Доме Ізраїлів, — благословіть Господа! Ааро́новий доме, — благословіть Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 20, 'Доме Леві́їв, — благословіть Господа! Хто боїться Господа, — благословіть Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 134, 21, 'Благослове́нний Господь від Сіону, що ме́шкає в Єрусалимі! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 1, 'Дя́куйте Господу, — добрий бо Він, бо навіки Його милосе́рдя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 2, 'Дя́куйте Богу богі́в, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 3, 'Дя́куйте Влади́ці влади́к, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 4, 'Тому, хто чу́да великі Єди́ний вчиня́є, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 5, 'Хто розумом небо вчинив, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 6, 'Хто землю простя́г над водою, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 7, 'Хто світи́ла великі вчинив, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 8, 'сонце, щоб вдень панува́ло воно, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 9, 'місяця й зорі, щоб вони панува́ли вночі, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 10, 'Хто Єгипет побив був у їхніх перворі́дних, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 11, 'і Ізраїля вивів з-між них, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 12, 'рукою міцно́ю й раме́ном простя́гненим, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 13, 'Хто море Червоне розтя́в на части́ни, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 14, 'і серед нього Ізраїля перепрова́див, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 15, 'і фараона та ві́йсько його вкинув у море Червоне, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 16, 'Хто провадив наро́д Свій в пустині, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 17, 'Хто великих царів повбива́в, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 18, 'і поту́жних царів переби́в, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 19, 'Сиго́на, царя аморе́ян, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 20, 'і О́ґа, Баша́ну царя, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 21, 'і Хто землю їхню дав на спа́дщину, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 22, 'на спа́док Ізра́їлеві, Своєму рабові, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 23, 'Хто про нас пам\'ята́в у пони́женні нашім, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 24, 'і від ворогів наших ви́зволив нас, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 25, 'Хто кожному тілові хліба дає, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 135, 26, 'Дя́куйте Богу небесному, бо навіки Його милосердя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 1, 'Над рі́чками Вавило́нськими, — там ми сиділи та й плакали, коли зга́дували про Сіо́на!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 2, 'На ве́рбах у ньому повісили ми свої а́рфи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 3, 'спі́ву бо пісні від нас там жада́ли були́ понево́лювачі наші, а весе́лощів — наші мучи́телі: „Заспівайте но нам із Сіонських пісе́нь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 4, 'Як же зможемо ми заспівати Господнюю пісню в землі чужинця́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 5, 'Якщо́ я забу́ду за тебе, о Єрусалиме, — хай забуде за мене прави́ця моя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 6, 'Нехай мій язик до мого піднебі́ння прили́пне, якщо́ я не бу́ду тебе пам\'ята́ти, якщо́ не поставлю я Єрусалима над радість найвищу свою́!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 7, 'Пам\'ятай же, о Господи, едо́мським синам про день Єрусалиму, як кричали вони: „Руйнуйте, руйнуйте аж до підва́лин його́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 8, 'Вавилонськая до́чко, що маєш і ти ограбо́вана бути, — блажен, хто заплатить тобі за твій чин, що ти нам заподі́яла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 136, 9, 'Блажен, хто ухо́пить та порозбиває об скелю і твої немовля́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 1, 'Давидів. Прославляю Тебе цілим серцем своїм, перед богами співаю Тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 2, 'Вклоняюсь до храму святого Твого, і сла́влю Іме́ння Твоє за Твоє милосердя й за правду Твою, бо звели́чив Ти був над усе Своє Йме́ння та слово Своє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 3, 'Удень, як взива́ю, почуєш мене, підбадьо́рюєш силою душу мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 4, 'Усі зе́мні царі прославля́ть Тебе, Господи, бу́дуть, бо почують вони слово уст Твоїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 5, 'і бу́дуть співати про Господні доро́ги, бо слава Господня велика,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 6, 'бо високий Госпо́дь, — але бачить низько́го, а гордого Він пізнає́ іздале́ка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 7, 'Якщо серед тісно́ти піду́, — Ти ожи́виш мене, на лютість моїх ворогів пошлеш руку Свою, і прави́ця Твоя допоможе мені, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 137, 8, 'для мене Господь оце виконає! Твоя милість, о Господи, вічна, — чи́нів Своєї руки не полиш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 1, 'Для дириґента хору. Псалом Давидів. Господи, — ви́пробував Ти мене та й пізнав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 2, 'Ти знаєш сиді́ння моє та встава́ння моє, думку мою розумієш здале́ка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 3, 'Доро́гу мою та лежа́ння моє виміря́єш, і Ти всі путі́ мої знаєш, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 4, 'бо ще сло́ва нема на моїм язиці́, а вже, Господи, знаєш те все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 5, 'Оточи́в Ти мене ззаду й спере́ду, і руку Свою надо мною поклав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 6, 'Дивне знання́ над моє розумі́ння, високе воно, — я його не подола́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 7, 'Куди я від Духа Твого піду́, і куди я втечу́ від Твого лиця?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 8, 'Якщо я на небо зійду́, — то Ти там, або постелю́ся в шео́лі — ось Ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 9, 'Понесу́ся на кри́лах зірни́ці, спочи́ну я на кінці моря,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 10, '— то рука Твоя й там попрова́дить мене, і мене буде трима́ти прави́ця Твоя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 11, 'Коли б я сказав: „Тільки те́мрява вкриє мене, і ніч — світло для мене“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 12, 'то мене не закриє від Тебе і те́мрява, і ніч буде світити, як день, і темно́та — як світло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 13, 'Бо Ти вчинив нирки мої, Ти ви́ткав мене в утро́бі матері моєї, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 14, 'Прославляю Тебе, що я дивно утво́рений! Дивні діла́ Твої, і душа моя відає ве́льми про це!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 15, 'І кості мої не сховались від Тебе, бо я вчи́нений був в укритті́, я ви́тканий був у глиби́нах землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 16, 'Мого за́родка бачили очі Твої, і до книги Твоєї записані всі мої члени та дні, що в них були вчи́нені, коли жодного з них не було́...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 17, 'Які дорогі́ мені стали думки́ Твої, Боже, як побі́льшилося їх число,-');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 18, 'перелі́чую їх, — численні́ші вони від піску́! Як пробу́джуюся, — то я ще з Тобою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 19, 'Якби, Боже, врази́в Ти безбожника, а ви, кровожерці, відступітесь від мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 20, 'Вони називають підсту́пно Тебе, Твої вороги на марно́ту пускаються!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 21, 'Отож, ненави́джу Твоїх ненави́сників, Господи, і Твоїх заколо́тників бри́джусь:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 22, 'повною не́навистю я нена́виджу їх, вони стали мені ворогами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 23, 'Ви́пробуй, Боже, мене, — і пізнай моє серце, досліди́ Ти мене, — і пізнай мої за́думи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 138, 24, 'і побач, чи не йду я дорогою злою, і на вічну дорогу мене попрова́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 1, 'Для дириґента хору. Псалом Давидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 2, 'Ви́зволь мене від люди́ни лихо́ї, о Господи, бережи мене від наси́льника,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 3, 'що в серці своїм замишляють злі речі, що ві́йни щодня виклика́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 4, 'Вони го́стрять свого язика́, як той вуж, отру́та гадю́ча під їхніми у́стами! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 5, 'Пильнуй мене, Господи, від рук нечести́вого, бережи мене від наси́льника, що заду́мали сто́пи мої захита́ти»');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 6, 'Чванли́ві сховали на мене тене́та та шну́ри, розтягли́ свою сі́тку при сте́жці, сільця́ розмістили на ме́не! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 7, 'Я сказав Господе́ві: „Ти Бог мій, — почуй же, о Господи, голос блага́ння мого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 8, 'Господи, Владико мій, сило мого спасі́ння, що в день бо́ю покрив мою го́лову, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 9, 'не виконай, Господи, бажань безбожного, не здійсни́ його за́думу! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 10, 'Бода́й голови́ не підне́сли всі ті, хто мене оточи́в, бодай зло їхніх уст їх покрило!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 11, 'Хай при́сок на них упаде́, нехай кине Він їх до огню́, до прова́лля, щоб не встали вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 12, 'Злоязи́чна люди́на — щоб міцно́ю вона не була́ на землі, люди́на насильства — бодай лихо спійма́ло її, щоб попхну́ти на поги́біль!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 13, 'Я знаю, що зробить Господь правосу́ддя убогому, при́суд правдивий для бідних, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 14, 'тільки праведні дя́кувати будуть Іме́нню Твоєму, невинні сидітимуть перед обличчям Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 139, 15, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 1, 'Псалом Давидів. Господи, кли́чу до Тебе, — поспіши́ся до мене, почуй же мій голос, як кли́чу до Тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 2, 'Нехай ста́не молитва моя як кади́ло перед лицем Твоїм, підно́шення рук моїх — як жертва вечі́рня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 3, 'Поклади, Господи, сторо́жу на у́ста мої, стережи́ двері губ моїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 4, 'Не дай нахиля́тися серцю моєму до речі лихо́ї, — щоб учи́нки робити безбо́жністю, із людьми, шо чинять пере́ступ, і щоб не ласува́вся я їхніми присма́ками!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 5, 'Як праведний вра́зить мене, — то це милість, а доко́рить мені, — це оли́ва на го́лову, її не відкине моя голова, бо ще і молитва моя проти їхнього зла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 6, 'Їхні су́дді по скелі розки́дані, та слова́ мої вчують, бо приємні вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 7, 'Як дро́ва руба́ють й розко́люють їх на землі, так розки́дані наші кістки́ над отво́ром шео́лу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 8, 'Бо до Тебе, о Господи, Владико, мої очі, на Тебе наді́юсь — не зруйно́вуй мого життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 9, 'Бережи Ти від па́стки мене, що на мене поставили, та від тене́т переступників!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 140, 10, 'Хай безбожні попа́дають ра́зом до сі́тки своєї, а я промину́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 1, 'Псалом навча́льний, Давида, коли він був у печері. Молитва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 2, 'Мій голос до Господа, — я кличу, мій голос до Господа, — я блага́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 3, 'Перед обличчям Його вилива́ю я мову свою, про недолю свою я розка́зую перед обличчям Його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 4, 'коли́ омліва́є мій дух у мені. А Ти знаєш дорогу мою: на дорозі, якою ходжу́, па́стку для мене сховали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 5, 'Право́руч поглянь і побач: немає ніко́го знайо́мого, загинув приту́лок від мене, ніхто не питає за душу мою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 6, 'Я кличу до Тебе, о Господи, я кажу́: „Ти моє пристано́вище, доля моя у країні живих!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 7, 'Прислу́хайся ж Ти до блага́ння мого́, бо зробився я зо́всім нужде́нний! Визволь мене від моїх переслі́дників, бо стали сильніші від мене вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 141, 8, 'Ви́веди душу мою із в\'язни́ці, щоб сла́вити Йме́ння Твоє! Праведні ото́чать мене, як учи́ниш добро надо мною!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 1, 'Псалом Давидів. Господи, вислухай молитву мою, почуй блага́ння моє в Своїй вірності, у правді Своїй обізви́ся до мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 2, 'І на суд не вступай із рабом Своїм, — бо жоден живий перед обличчям Твоїм справедли́вим не буде!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 3, 'Бо неприятель переслідує душу мою, то́пче живую мою до землі. Посадив мене в те́мряву, як мерці́в цього світу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 4, 'Омліває мій дух у мені, кам\'яні́є в нутрі́ моїм серце моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 5, 'Я згадую дні старода́вні, над усі́ми Твоїми чинами розду́мую, говорю́ про діла́ Твоїх рук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 6, 'Я ру́ки свої простягаю до Тебе, душа моя пра́гне Тебе, як ́ пересо́хла земля! Се́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 7, 'Поспіши́ мене ви́слухати, Господи, — дух мій кінча́ється! Не ховай Ти від мене обличчя Свого́, і нехай я не бу́ду подібний до тих, хто схо́дить до гро́бу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 8, 'Об\'яви́ мені вранці Своє милосердя, бо на Тебе наді́юсь, повідо́м Ти мене про дорогу, якою я маю ходи́ти, бо до Тебе підно́шу я душу свою́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 9, 'Урятуй мене, Господи, від моїх ворогів, бо до Тебе вдаю́ся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 10, 'Навчи мене волю чинити Твою́, бо Ти Бог мій, — добрий Дух Твій нехай попрова́дить мене по рі́вній землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 11, 'Ради Ймення Свого, о Господи, оживи мене, Своєю правдою ви́веди душу мою від недолі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 142, 12, 'А в Своїм милосерді понищ моїх ворогів, і ви́губи всіх, хто нена́видить душу мою, бо я — раб Твій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 1, 'Давидів. Благослове́нний Господь, моя ске́ля, що руки мої Він навчає до бо́ю, пальці мої — до війни́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 2, 'Він моє милосердя й тверди́ня моя, форте́ця моя та моя охоро́на мені, Він мій щит, і я до Нього вдаю́ся, Він мій наро́д підбиває під мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 3, 'Господи, що́ то люди́на, що знаєш її, що́ то син лю́дський, що зважаєш на нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 4, 'Люди́на стала до па́ри поді́бна, її дні — як та тінь промину́ща!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 5, 'Господи, нахили Своє небо, — й зійди́, доторкни́ся до гір, — і вони задиму́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 6, 'Заблищи́ блискави́цею, й їх розпоро́ш, пошли Свої стрі́ли, і їх побенте́ж!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 7, 'Пошли з висоти́ Свою руку, й мене поряту́й, і визволь мене з вод великих, від руки чужинці́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 8, 'що їхні уста́ промовляють неправду, а їхня прави́ця — прави́ця зрадли́ва!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 9, 'Боже, я пісню нову́ заспіваю Тобі, на а́рфі десятистру́нній заграю Тобі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 10, 'що Ти перемогу царям подає́ш, що рятуєш Давида, Свого раба, від лихого меча́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 11, 'Порятуй же мене й збережи Ти мене від руки чужинці́в, що їхні уста́ промовляють марно́ту, а їхня прави́ця — правиця зрадли́ва,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 12, 'щоб були́ сини наші, немов саджанці́, ви́плекані в їхній мо́лодості, наші до́чки — немов ті нарі́жні стовпи́, ви́тесані на окра́су палати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 13, 'Повні наші комо́ри, — вони видають найрізні́ше, ко́тяться тисячами наші ві́вці та ко́зи, десятками тисяч по наших подві́р\'ях розпло́джуються!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 14, 'Ситі наші бики́, немає приго́д і немає хворо́би, і на ву́лицях наших нема наріка́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 143, 15, 'Блаженний наро́д, що йому так веде́ться, блаженний наро́д, що Господь — йому Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 1, 'Хвала́ Давидова. Я буду Тебе велича́ти, о Боже мій, Ца́рю, і благословля́тиму Ймення Твоє повік-віку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 2, 'Я кожного дня Тебе благословля́тиму, і хвалитиму Йме́ння Твоє повік-віку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 3, 'Великий Господь і просла́влений ве́льми, і недосліди́ме вели́ччя Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 4, 'Рід ро́дові буде хвалити діла́ Івої, і будуть могу́тність Твою виявляти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 5, 'Про пишну славу вели́ччя Твого, про справи чудо́вні Твої розпові́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 6, 'Будуть казати про силу грізни́х Твоїх чи́нів, а про ве́лич Твою — розпові́м я про неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 7, 'Па́м\'ять про добрість велику Твою сповіща́тимуть, і будуть співати про правду Твою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 8, 'Ще́дрий і милосердний Господь, довготерпели́вий й многомилости́вий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 9, 'Господь добрий до всіх, а Його милосердя — на всі Його тво́рива!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 10, 'Тебе, Господи, сла́вити будуть усі Твої тво́рива, а святі Твої Тебе благословля́тимуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 11, 'про славу Царства Твого звіща́тимуть, про могутність Твою говори́тимуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 12, 'щоб лю́дським синам об\'яви́ти про могутність Його́ та про славу вели́ччя Царства Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 13, 'Царство Твоє — царство всіх віків, а вла́да Твоя — по всі роди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 14, 'Господь підпира́є всіх па́даючих, усіх зі́гнутих Він випросто́вує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 15, 'Очі всіх упова́ють на Те́бе, і Ти їм пожи́ву даєш своєча́сно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 16, 'Ти руку Свою відкрива́єш, — і все, що живе, Ти зичли́во году́єш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 17, 'Господь справедливий на кожній дорозі Своїй, і милости́вий у всіх Своїх учи́нках,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 18, 'Господь близьки́й всім, хто взива́є до Нього, хто правдою кличе Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 19, 'Волю тих, хто боїться Його, Він сповня́є, і блага́ння їх чує та їм помагає, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 20, 'Госпо́дь береже́ тих усіх, хто любить Його, а безбожних усіх Він понищить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 21, 'Славу Господню уста́ мої будуть звіща́ти, і благословля́тиме кожне тіло святе Його Ймення на віки вікі́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 144, 22, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 1, 'Алілуя! Хвали, душе моя, Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 2, 'хвалитиму Господа, поки живу́, співатиму Богу моє́му, аж поки існую!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 3, 'Не наді́йтесь на князів, на лю́дського сина, бо в ньому спасі́ння нема:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 4, 'вийде дух його — і він до своєї землі поверта́ється, — того дня його за́думи гинуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 5, 'Блаженний, кому́ його поміч — Бог Яковів, що надія його — на Господа, Бога його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 6, 'що небо та землю вчинив, море й усе, що є в них, що правди пильнує навіки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 7, 'правосу́ддя вчиняє покри́вдженим, що хліба голодним дає! Госпо́дь в\'язнів розв\'язує,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 8, 'Господь очі сліпим відкриває, Господь випросто́вує зі́гнутих, Господь милує праведних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 9, 'Господь обороняє прихо́дьків, сироту́ та вдови́цю підтримує, а дорогу безбожних викри́влює!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 145, 10, 'Хай царю́є навіки Господь, Бог твій, Сіоне, із роду у рід! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 1, 'Хваліть Господа, — добрий бо Він, виспівуйте нашому Богу, — приємний бо Він, — Йому подоба́є хвала́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 2, 'Господь Єрусалима будує, збирає вигна́нців Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 3, 'Він зламаносе́рдих лікує, і їхні рани болю́чі обв\'я́зує,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 4, 'вирахо́вує Він число зо́рям, і кожній із них дає йме́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 5, 'Великий Господь наш, та дужий на силі, Його мудрости міри нема!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 6, 'Господь підіймає слухня́них, безбожних понижує аж до землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 7, 'Дайте відповідь Господу нашому вдячною піснею, заграйте для нашого Бога на гу́слах:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 8, 'Він хмарами небо вкриває, пригото́влює дощ для землі, обро́щує гори травою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 9, 'худобі дає її корм, вороня́там — чого вони кличуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 10, 'Не в силі коня уподо́ба Його, і не в чле́нах люди́ни Його закоха́ння, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 146, 11, 'Госпо́дь любить тих, хто боїться Його, хто наді́ю склада́є на милість Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 1, 'Хвали Господа, Єрусалиме, прославляй Свого Бога, Сіоне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 2, 'бо зміцняє Він за́суви брам твоїх, синів твоїх благословляє в тобі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 3, 'чинить мир у границі твоїй, годує тебе пшеницею щирою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 4, 'посилає на землю нака́за Свого, — дуже швидко летить Його Слово!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 5, 'Дає сніг, немов во́вну, розпоро́шує па́морозь, буцім то по́рох,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 6, 'Він кидає лід Свій, немов ті кришки́, — і перед морозом Його хто усто́їть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 7, 'Та Він пошле́ Своє слово, — та й розто́пить його, Своїм вітром повіє, — вода потече!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 8, 'Своє слово звіщає Він Якову, постано́ви Свої та Свої правосуддя — Ізраїлю:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 9, 'для жодного люду Він так не зробив, — той не знають вони правосуддя Його! Алілуя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 10, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 11, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 12, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 13, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 14, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 15, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 16, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 17, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 18, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 19, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 147, 20, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 1, 'Алілуя! Хвалі́те Господа з небе́с, хваліте Його в висоті́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 2, 'Хваліте Його, всі Його Анголи́, хваліте Його, усі ві́йська Його́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 3, 'Хваліте Його, сонце й місяцю, хваліте Його, усі зо́рі ясні́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 4, 'Хваліте Його, небеса́ із небе́с, та води, що над небеса́ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 5, 'Нехай Господа хвалять вони, бо Він наказа́в, — і створились вони,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 6, 'Він їх поставив на вічні віки́, дав нака́за, — і не пересту́плять його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 7, 'Хваліть Господа та́кож з землі: риби великі й безо́дні усі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 8, 'огонь та град, сніг та туман, вітер бурхли́вий, що виконує слово Його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 9, 'го́ри та па́гірки всі, плідне дерево та всі кедри́ни,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 10, 'звірина́ й вся худо́ба, все плазу́юче та пта́ство крилате,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 11, 'зе́мні царі й всі наро́ди, князі та всі су́дді землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 12, 'юнаки́ та дівиці, старі ра́зом із ді́тьми, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 13, 'нехай усі хвалять Господнє Ім\'я́, бо Його́ тільки Йме́ння звели́чилось, вели́чність Його на землі й небеса́х!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 148, 14, 'Він рога народу Своє́му підні́с! Слава всім богобійним Його́, ді́тям Ізра́їлевим, наро́дові, що до Нього близьки́й! Алілуя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 1, 'Алілу́я! Заспівайте для Господа пісню нову́, Йому слава на збо́рах святих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 2, 'Хай Ізраїль радіє Творце́м своїм, хай Царем своїм тішаться діти Сіону!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 3, 'Нехай славлять Ім\'я́ Його та́нцем, нехай виграва́ють для Нього на бу́бні та гу́слах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 4, 'бо знахо́дить Господь уподо́бу в наро́ді Своїм, прикраша́є покірних спасі́нням!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 5, 'Хай радіють у славі святі, хай співають на ло́жах своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 6, 'просла́влення Бога — на їхніх уста́х, а меч обосі́чний — ув їхніх рука́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 7, 'щоб чинити між племе́нами по́мсту, між наро́дами — ка́ри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 8, 'щоб їхніх царів пов\'язати кайда́нами, а їхніх вельмо́ж — ланцюга́ми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 149, 9, 'щоб між ними чини́ти суд написаний! Він — вели́чність для всіх богобі́йних! Алілу́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 1, 'Алілуя! Хваліть Бога в святині Його, хваліте Його на могу́тнім Його небозво́ді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 2, 'Хвалі́те Його за чи́ни могутні Його, хваліте Його за могу́тню вели́чність Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 3, 'Хваліте Його звуком тру́бним, хваліте Його на арфі та гу́слах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 4, 'Хваліте Його на бу́бні та та́нцем, хваліте Його на стру́нах та флейті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 5, 'Хваліте Його на цимба́лах дзвінки́х, хваліте Його на цимба́лах гучни́х!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 150, 6, 'Все, що ди́хає, — хай Господа хва́лить! Алілу́я!');
