INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, '');
