INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 74, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 75, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 76, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 77, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 1, 'І оце Соломо́нові при́повісті, що зібрали люди Єзекі́ї, Юдиного царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 2, 'Слава Божа — щоб справу схова́ти, а слава царів — щоб розві́дати справу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 3, 'Небо висо́кістю, і земля глибино́ю, і серце царі́в — недосліди́мі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 4, 'Як відкинути жу́жель від срі́бла, то золотаре́ві виходить посу́дина, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 5, 'коли віддалити безбожного з-перед обличчя царе́вого, то справедливістю міцно поста́виться трон його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 6, 'Перед царем не пиша́йся, а на місці великих не стій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 7, 'бо ліпше, як скажуть тобі: „Ходи вище сюди!“аніж тебе зни́зити перед шляхе́тним, що бачили очі твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 8, 'Не спіши́ся ставати до по́зову, бо що́ будеш робити в кінці його, як тебе засоро́мить твій ближній?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 9, 'Судися за сварку свою з своїм ближнім, але не виявляй таємни́ці іншого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 10, 'щоб тебе не обра́зив, хто слухати буде, і щоб не вернулась на тебе обмо́ва твоя́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 11, 'Золоті яблука на срібнім таре́лі — це слово, прока́зане ча́су свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 12, 'Золотая сере́жка й оздоба зо щи́рого золота — це мудрий карта́ч для уважного уха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 13, 'Немов снігова́ прохоло́да в день жнив — посол вірний для тих, хто його посилає, і він душу пана свого оживля́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 14, 'Хмари та вітер, а немає дощу це люди́на, що чва́ниться да́ром, та його не дає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 15, 'Воло́дар зм\'я́кшується терпели́вістю, а м\'яке́нький язик ломить кістку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 16, 'Якщо мед ти знайшов, то спожий, скільки до́сить тобі, щоб ним не переси́титися та не звернути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 17, 'Здержуй но́гу свою від дому твого товариша, щоб тобою він не переси́тивсь, і не зненави́дів тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 18, 'Молот, і меч, і гостра стріла́ — люди́на, що говорить на ближнього свого, як свідок брехливий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 19, 'Гнилий зуб та кульга́ва нога — це наді́я на зрадли́вого радника в день твого у́тиску.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 20, 'Що здіймати одежу холодного дня, що лити о́цет на со́ду, — це — співати пісні серцю засмученому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 21, 'Якщо голодує твій ворог — нагодуй його хлібом, а як спра́гнений він — водою напі́й ти його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 22, 'бо цим пригорта́єш ти жар на його го́лову, і Господь надолу́жить тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 23, 'Вітер північний народжує дощ, а таємний язик — сердите обличчя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 24, 'Ліпше жити в куті́ на даху́, ніж з сварливою жінкою в спільному домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 25, 'Добра звістка з далекого кра́ю — це холодна водиця на спра́гнену душу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 26, 'Джерело́ скаламу́чене чи зіпсутий поті́к — це праведний, що схиляється перед безбожним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 27, 'Їсти меду багато — не добре, так досліджувати власну славу — не слава.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 28, 'Люди́на, що стри́му немає для духу свого, — це зруйно́ване місто без му́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 29, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 30, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 31, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 1, 'Як літом той сніг, і як дощ у жнива́, — та́к не лицю́є глупце́ві пошана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 2, 'Як пташка літає, як ла́стівка лине, так невинне прокля́ття не спо́вниться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 3, 'Батіг на коня, обро́ть на осла, а різка на спи́ну глупці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 4, 'Нерозумному відповіді не дава́й за нерозум його, щоб і ти не став рівний йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 5, 'Нерозумному відповідь дай за безумством його, щоб він в о́чах своїх не став мудрим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 6, 'Хто через глупця́ посилає слова́, той ноги собі обтинає, отру́ту він п\'є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 7, 'Як воло́чаться но́ги в кульга́вого, так у безумних уста́х припові́стка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 8, 'Як прив\'я́зувати камінь коштовний до пра́щі, так глупце́ві пошану давати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 9, 'Як те́рен, що влізе у руку, отак припові́стка в уста́х нерозумного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 10, 'Як стрілець, що все ра́нить, так і той, хто наймає глупця́, і наймає усяких прохо́жих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 11, 'Як вертається пес до своєї блюво́тини, так глупо́ту свою повторяє глупа́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 12, 'Чи ти бачив люди́ну, що мудра в очах своїх? Більша надія глупце́ві, ніж їй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 13, 'Лінивий говорить: „Лев на дорозі! Лев на майда́ні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 14, 'Двері обе́ртаються на своєму чопі́, а лінивий — на лі́жку своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 15, 'Свою руку лінивий стромля́є до миски, — та підне́сти до рота її йому тяжко.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 16, 'Лінивий мудріший ув очах своїх за сімох, що відповідають розумно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 17, 'Пса за ву́ха хапає, хто, йдучи́, устрява́є до сварки чужої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 18, 'Як той, хто вдає божевільного, ки́дає і́скри, стрі́ли та смерть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 19, 'так і люди́на, що обманює друга свого та каже: „Таж це́ я жартую!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 20, 'З браку дров огонь гасне, а без пліткаря́ мовкне сварка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 21, 'Вугі́лля для жару, а дро́ва огне́ві, а люди́на сварли́ва — щоб сварку розпа́лювати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 22, 'Слова́ обмо́вника — мов ті присма́ки, й у нутро́ живота вони схо́дять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 23, 'Як срі́бло з жу́желицею, на горшкові накла́дене, так полу́м\'яні уста, а серце лихе, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 24, 'устами своїми маску́ється ворог, і ховає оману в своє́му нутрі́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 25, 'коли він говорить лагі́дно — не вір ти йому, бо в серці його сім оги́д!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 26, 'Як нена́висть прикрита ома́ною, — її зло відкривається в зборі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 27, 'Хто яму копа́є, той в неї впаде́, а хто ко́тить камі́ння — на нього воно поверта́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 28, 'Брехливий язик нена́видить своїх ути́скуваних, і уста гладе́нькі до згуби прова́дять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 29, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 1, 'Не вихва́люйся за́втрашнім днем, бо не знаєш, що день той поро́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 2, 'Нехай інший тебе вихваля́є, а не уста твої, чужий, а не губи твої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 3, 'Камі́ння — тяга́р, і пісок — важка річ, та гнів нерозумного тяжчий від них від обох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 4, 'Лютість — жорстокість, а гнів — то зато́плення, та хто перед заздрістю всто́їть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 5, 'Ліпше відкрите карта́ння, ніж таємна любов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 6, 'Побої коханого вірність показують, а в нена́висника поцілу́нки числе́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 7, 'Сита душа топче й мед щільнико́вий, а голодній душі все гірке́ — то солодке.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 8, 'Як птах, що гніздо́ своє кинув, так і люди́на, що з місця свого мандру́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 9, 'Олива й кадило поті́шують серце, і солодкий нам друг за душевну пораду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 10, 'Друга свого й друга батька свого не кидай, а в дім брата свого не прихо́дь в день нещастя свого́, — ліпший сусіда близьки́й за далекого брата!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 11, 'Будь мудрий, мій сину, й потіш моє серце, і я матиму що відповісти́, як мені докоря́тиме хто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 12, 'Мудрий бачить лихе — і ховається, а безумні йдуть — і караються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 13, 'Візьми його одіж, бо він поручивсь за чужого, і за чужи́нку заста́ву візьми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 14, 'Хто сильним голосом благословляє із ра́ннього ранку свого товариша, — за прокля́ття залічується це йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 15, 'Ри́нва, постійно теку́ча слотли́вого дня та жінка сварли́ва — одна́кове:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 16, 'хто хоче сховати її — той вітра ховає, чи оливу паху́чу правиці своєї, що видасть себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 17, 'Як гострить залізо залізо, так гострить люди́на лице свого друга.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 18, 'Сторож фіґо́вниці пло́ди її споживає, а хто пана свого стереже, той шанований.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 19, 'Як лице до лиця у воді, так серце люди́ни до серця люди́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 20, 'Шео́л й Аваддо́н не наси́тяться, — не наси́тяться й очі люди́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 21, 'Що для срі́бла топи́льна посу́дина, і го́рно — для золота, те для людини уста́, які хвалять її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 22, 'Хоч нерозумного будеш товкти́ товкаче́м поміж зе́рнами в сту́пі, — не віді́йде від нього глупо́та його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 23, 'До́бре знай вигляд своєї отари, поклади своє серце на че́реди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 24, 'бо багатство твоє не навіки, і чи корона твоя з роду в рід?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 25, 'Появилася зе́лень, і трава показалась, і збирається сіно із гір, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 26, 'будуть ві́вці тобі на вбрання́, і козли́ — ціна поля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 27, 'і молока твоїх кіз буде до́сить на ї́жу тобі, на їду́ твого дому, і на життя для служни́ць твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 28, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 29, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 1, 'Безбожні втіка́ють, коли й не жену́ться за ними, а справедливий безпечний, немов той левчу́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 2, 'Коли край провини́ться, то має багато воло́дарів, коли ж є люди́на розумна й знаю́ча, то де́ржиться довго.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 3, 'Люди́на убога, що гно́бить нужде́нних, це зли́ва рвучка́, що хліба по ній не буває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 4, 'Ті, хто Зако́н залиша́є, хвалять безбожних, а ті, хто Зако́н береже, на них бу́ряться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 5, 'Люди лихі правосу́ддя не розуміють, а шукаючі Господа все розуміють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 6, 'Ліпше убогий, що ходить в своїй неповинності, ніж криводоро́гий, хоч він і бага́ч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 7, 'Хто Зако́н береже́, розумний той син, а хто во́диться із гультяя́ми, засоро́млює ба́тька свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 8, 'Хто мно́жить лихва́рським відсо́тком багатство своє, той для то́го грома́дить його, хто ласкавий для бідних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 9, 'Хто відхи́лює вухо своє, щоб не слухати Зако́на, то буде оги́дна й молитва того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 10, 'Хто про́стих доводить блуди́ти дорогою зла, сам до ями своєї впаде́, а невинні пося́дуть добро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 11, 'Багата люди́на в оча́х своїх мудра, та розумний убогий розслі́дить її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 12, 'Велика пишно́та, як ті́шаться праведні, коли ж несправедливі зростають, то треба шукати люди́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 13, 'Хто ховає провини свої, тому́ не веде́ться, а хто признається та кидає їх, той буде поми́луваний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 14, 'Блаженна люди́на, що завжди оба́чна, а хто ожорсто́чує серце своє, той впадає в лихе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 15, 'Лев ричу́чий й ведмі́дь ненаже́рливий — це безбожний володар над людом убогим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 16, 'Володар, позбавлений розуму, тисне дошкульно, а ненави́сник заже́рливости буде мати дні довгі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 17, 'Люди́на, обтя́жена за душогу́бство, втікає до гро́бу, — нехай її не підпира́ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 18, 'Хто ходить невинний, той буде спасе́ний, а криводоро́гий впаде́ на одній із дорі́г.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 19, 'Хто землю свою обробля́є, той наси́титься хлібом, а хто за марно́тним жене́ться, наси́титься вбогістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 20, 'Вірна люди́на багата на благослове́ння, а хто спішно збагачується, непокараним той не зали́шиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 21, 'Увагу звертати на особу — не добре, бо й за кус хліба люди́на згріши́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 22, 'Завидю́ща люди́на спішить до багатства, і не знає, що при́йде на неї нужда́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 23, 'Хто напоумля́є люди́ну, той знахо́дить вкінці більшу ласку, ніж той, хто лести́ть язиком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 24, 'Хто батька свого й свою матір грабує і каже: „Це не гріх“, той розбійнику друг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 25, 'Захла́нний викликує сварку, хто ж має наді́ю на Господа, буде наси́чений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 26, 'Хто надію кладе на свій розум, то він нерозумний, а хто мудрістю ходить, той буде врято́ваний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 27, 'Хто дає немаю́чому, той недостатку не знатиме, хто́ ж свої очі ховає від нього, той зазна́є багато проклять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 28, 'Коли підійма́ються лю́ди безбожні, люди́на ховається, а як гинуть вони, то мно́жаться праведні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 29, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 30, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 1, 'Чоловік остере́жуваний, та твердошиїй, буде зламаний нагло, і ліку не буде йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 2, 'Коли мно́жаться праведні, радіє наро́д, як панує ж безбожний — то сто́гне наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 3, 'Люди́на, що мудрість кохає, поті́шує батька свого, а хто попасає блудни́ць, той губить маєток.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 4, 'Цар утримує край правосу́ддям, а люди́на хаба́рна руйнує його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 5, 'Люди́на, що другові своєму підле́щує, на сто́пах його па́стку ставить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 6, 'У провині люди́ни лихої знахо́диться па́стка, а справедливий радіє та ті́шиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 7, 'Праведний знає про право вбогих, безбожний же не розуміє пізна́ння про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 8, 'Люди глузли́ві підбу́рюють місто, а мудрі утишують гнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 9, 'Мудра люди́на, що праву́ється із нерозумним, то чи гні́вається, чи сміється, — споко́ю не знає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 10, 'Кровоже́рці нена́видять праведного, справедливі ж шукають спасти його душу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 11, 'Глупа́к уесь свій гнів увиявляє, а мудрий назад його стри́мує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 12, 'Володар, що слухає сло́ва брехливого, — безбожні всі слу́ги його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 13, 'Убогий й гноби́тель стрічаються, — їм обом Господь очі освітлює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 14, 'Як цар правдою судить убогих, стоя́тиме трон його за́вжди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 15, 'Різка й поу́ка премудрість дають, а дити́на, зали́шена тільки собі, засоро́млює матір свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 16, 'Як мно́жаться несправедливі — провина розмно́жується, але праведні бачитимуть їхній упа́док.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 17, 'Карай сина свого — й він тебе заспоко́їть, і приє́мнощі дасть для твоєї душі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 18, 'Без пророчих виді́нь люд розбе́щений, коли ж стереже він Зако́на — блаженний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 19, 'Раб словами не буде пока́раний, — хоч він розуміє, але́ не послу́хає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 20, 'Чи бачив люди́ну, квапли́ву в словах своїх? — Більша надія глупце́ві, ніж їй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 21, 'Хто розпе́щує зма́лку свого раба, то кінець його буде невдячний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 22, 'Гнівли́ва люди́на викли́кує сварку, а лютий вчиняє багато провин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 23, 'Горди́ня люди́ни її понижає, а чести набуває покірливий духом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 24, 'Хто ді́литься з зло́дієм, той нена́видить душу свою, — він чує прокля́ття, та не виявляє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 25, 'Страх перед люди́ною па́стку дає, хто ж наді́ю складає на Господа, буде безпечний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 26, 'Багато шукають для себе обличчя володаря, та від Господа суд для люди́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 27, 'Наси́льник — оги́да для праведних, а простодоро́гий — оги́да безбожному.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 28, '');
