INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 36, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 37, '');
