INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 44, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 45, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 46, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 47, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 48, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 49, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 1, 'Слова́ Агу́ра, Яке́євого сина, массе́янина: „Слово мужчи́ни: Трудився я, Боже, трудився я, Боже, — і змучився я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 2, 'Бо ду́маю, що немудріший за кожного я, і не маю я лю́дського розуму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 3, 'і не навчився я мудрости, і не знаю пізна́ння святих....');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 4, 'Хто на небо ввійшов — і зійшов? Хто у жме́ні Свої зібрав вітер? Хто воду в одежу зв\'язав? Хто поставив усі кі́нці землі? Яке Йме́ння Його, і яке Йме́ння Сина Його, коли знаєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 5, 'Кожне Боже слово очи́щене, щит Він для тих, хто в Нім пристановище має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 6, 'До слів Його не додавай, щоб тебе не скартав Він, і щоб неправдомо́вцем не став ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 7, 'Двох речей я від Тебе просив, — не відмов мені, поки помру́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 8, 'віддали́ Ти від мене марно́ту та слово брехли́ве, убо́зтва й багатства мені не давай! Годуй мене хлібом, для ме́не призна́ченим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 9, 'щоб я не переси́тився та й не відрікся, і не сказав: „Хто Госпо́дь?“і щоб я не збіднів і не крав, і не знева́жив Ім\'я́ мого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 10, 'Раба не обмовля́й перед паном його, щоб тебе не прокляв він, і ти винуватим не став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 11, 'Оце поколі́ння, що батька свого проклинає, і не́ньки своєї не благословляє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 12, 'покоління, що чисте в оча́х своїх, та від бруду свого не обмите,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 13, 'покоління, — які го́рдісні очі його, а пові́ки його як підне́слися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 14, 'Покоління, що в нього мечі — його зуби, а гострі ножі — його ще́лепи, щоб поже́рти убогих із кра́ю й нужде́нних з землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 15, 'Дві дочки́ в кровоже́рця: „Дай, дай!“Оці три не наси́тяться, чотири не скажуть „до́сить\":');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 16, 'шео́л та утро́ба неплідна, водою земля не наси́титься, і не скаже „до́сить“огонь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 17, 'Око, що з батька сміється й пого́рджує по́слухом матері, — нехай ви́дзьобають його кру́ки пото́чні, і нехай орленя́та його пожеру́ть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 18, 'Три речі оці дивови́жні для мене, і чотири, яких я не знаю:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 19, 'дорога орли́на в повітрі, дорога змії́на на скелі, корабельна дорога в сере́дині моря, і дорога мужчи́ни при дівчині!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 20, 'Така ось дорога блудли́вої жінки: наїлась та витерла уста свої й повіла́: „Не вчинила я злого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 21, 'Трясе́ться земля під трьома, і під чотирма́, яких зне́сти не може вона:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 22, 'під рабом, коли він зацарю́є, і під нерозумним, як хліба наїсться,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 23, 'під розпу́стницею, коли взята за жінку, і неві́льницею, коли вижене пані свою́!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 24, 'Оці ось чотири малі на землі, та вони ве́льми мудрі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 25, 'мура́шки, — не сильний наро́д, та пожи́ву свою загото́влюють літом;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 26, 'борсуки́, — люд не сильний, та в скелі свій дім вони ставлять;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 27, 'немає царя в сарани́, — але вся вона в стро́ї бойо́вім вихо́дить;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 28, 'паву́к тільки ла́пками пнеться, та він і в пала́тах царськи́х!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 29, 'Добре ступають ці троє, і добре хо́дять чотири:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 30, 'лев, найсильніший поміж звірино́ю, який не вступа́ється ні перед ким,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 31, 'осі́дланий кінь, і козел, та той цар, що з ним ві́йсько!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 32, 'Якщо ти допусти́вся глупо́ти пихою, й якщо заміря́єш лихе, — то руку на уста!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 33, 'Бо збива́ння молока дає масло, і дає кров вдар по носі, тиск же на гнів дає сварку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 34, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 35, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 1, 'Слова Лемуїла, царя Масси́, що ними навчала його його мати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 2, '„Що, сину мій, і що, сину утро́би моєї, і що, сину обі́тниць моїх?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 3, 'Не давай жінкам сили своєї, ні доріг своїх для руйнува́льниць царів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 4, 'Не царя́м, Лемуїле, вино, не царям, і на́пій той п\'янки́й не князя́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 5, 'щоб не впився він та не забув про Зако́на, і щоб не змінив для всіх гно́блених пра́ва!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 6, 'Дайте напо́ю п\'янко́го тому, хто гине, а вина — гіркоду́хим:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 7, 'він вип\'є й забуде за бідність свою, і му́ки своєї вже не пам\'ята́тиме!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 8, 'Відкривай свої уста немо́ві, для суда́ всім нещасним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 9, 'Відкрива́й свої уста, й суди справедливо, і правосу́ддя зроби для убогого та для нужде́нного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 10, 'Хто жінку чесно́тну зна́йде? а ціна її більша від пе́рел:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 11, 'довіря́є їй серце її чоловіка, і йому не забра́кне прибутку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 12, 'Вона чинить для нього добро, а не зло, по всі́ дні свого життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 13, 'Шукає вона вовни й льо́ну, і робить охоче своїми руками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 14, 'Вона, немов кораблі́ ті купе́цькі, здале́ка спроваджує хліб свій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 15, 'І встане вона ще вночі, і видасть для дому свого поживу, а поря́док служни́цям своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 16, 'Про поле вона намишляла, і його набула́, із пло́ду долоней своїх засадила вона виноградинка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 17, 'Вона підпері́зує силою сте́гна свої та зміцня́є раме́на свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 18, 'Вона розуміє, що добра робота її, і світильник її не пога́сне вночі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 19, 'Вона ру́ки свої простя́гає до пря́дки, а долоні її верете́но тримають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 20, 'Долоню свою відкриває для вбогого, а руки свої простягає до бідного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 21, 'Холоду в домі своїм не боїться вона, бо подвійно одя́гнений ввесь її дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 22, 'Килими́ поробила собі, віссо́н та кармази́н — убра́ння її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 23, 'Чоловік її зна́ний при брамах, як сидить він із старшими краю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 24, 'Тонку ту́ніку робить вона й продає, і купце́ві дає пояси́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 25, 'Сила та пи́шність — одежа її, і сміється вона до прийде́щнього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 26, 'Свої уста вона відкриває на мудрість, і милости́ва наука їй на язиці́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 27, 'Доглядає вона ходи дому свого́, і хліба з ліни́вства не їсть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 28, 'Устають її діти, і хвалять її, чоловік її — й він похваля́є її:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 29, '„Багато було́ тих чесно́тних дочо́к, та ти їх усіх переви́щила!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 30, 'Краса — то ома́на, а врода — марно́та, жінка ж богобоя́зна — вона буде хва́лена!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 31, 'Дайте їй з плоду рук її, і нехай її вчи́нки її вихваляють при брамах!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Книга Пропові́дника, сина Давидового, царя в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Наймарні́ша марно́та, сказав Пропові́дник, наймарні́ша марно́та, — марно́та усе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Яка ко́ристь люди́ні в усім її тру́ді, який вона робить під сонцем?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Поколі́ння відхо́дить, й поколі́ння приходить, а земля вікові́чно стоїть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'І со́нечко схо́дить, і сонце заходить, і поспішає до місця свого́, де схо́дить воно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Віє вітер на пі́вдень, і на північ верта́ється, кру́титься, крутиться він та й іде, і на круг свій верта́ється вітер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Всі пото́ки до моря пливуть, але море — воно не напо́внюється: до місця, ізві́дки пливуть, ті потоки вони поверта́ються, щоб зно́ву плисти́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Повні тру́ду всі ре́чі, — люди́на сказати всього́ не потра́пить! Не наси́титься ба́ченням око, і не напо́вниться слу́ханням ухо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Що було́, воно й бу́де, і що робилося, бу́де робитись воно, — і немає нічо́го ново́го під сонцем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Буває таке, що про нього говорять: „Дивись, — це нове́!“Та воно вже було́ від вікі́в, що були́ перед нами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Нема згадки про перше, а тако́ж про насту́пне, що бу́де, — про них згадки не бу́де між тими, що бу́дуть пото́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 12, 'Я, Проповідник, був царем над Ізраїлем в Єрусалимі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 13, 'І поклав я на серце своє, щоб шукати й дослі́джувати мудрістю все, що робилось під небом. Це праця тяжка́, яку дав Бог для лю́дських синів, щоб мозо́литись нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 14, 'Я бачив усі справи, що чини́лись під сонцем: й ось усе це — марно́та та ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 15, 'Покри́вленого не напра́виш, а неісну́ючого не полі́чиш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 16, 'Говорив я був з серцем своїм та казав: Ось я велику премудрість набув, Найбільшу за всіх, що до ме́не над Єрусалимом були́. І бачило серце моє всяку мудрість і знання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 17, 'І поклав я на серце своє, щоб пізнати премудрість, і пізнати безу́мство й глупо́ту, — і збагну́в я, що й це все — то ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 18, 'Бо при мно́гості мудрости мно́житься й кло́піт, хто ж пізна́ння побільшує, той побільшує й біль!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Сказав був я в серці своє́му: Іди но, хай ви́пробую тебе радістю, і придивись до добра́, — та й воно ось марно́та.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'На сміх я сказав: „Нерозумний“, а на радість: „Що́ робить вона?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Задумав я в серці своє́му вином оживля́ти своє тіло, і прова́дити мудрістю серце своє, і що буду держатись глупо́ти, аж поки побачу, що́ ж добре для лю́дських синів, що робили б під небом за короткого ча́су свого життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Поробив я великі діла́: поставив для себе доми́, задля се́бе садив виноградники,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'запрова́див для себе садки́ та гаї́, і понаса́джував в них усіля́ких дерев овоче́вих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Наробив я для себе ставі́в, щоб полива́ти із них ліс дере́в, що виро́стали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Набував я для себе рабів та неві́льниць, були в мене й домі́вники. А худо́би великої та худоби дрібно́ї було в мене більше, ніж у всіх, що в Єрусалимі до ме́не були́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Назбирав я собі також срі́бла та золота, і ска́рбів царів та прові́нцій, завів я собі співакі́в та співа́чок, і всякі приє́мнощі лю́дських синів, жінок — нало́жниць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'І звели́чувавсь я усе більше та більше, над усіх, що в Єрусалимі до мене були́, моя мудрість стояла також при мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'І всього́, чого очі мої пожада́ли, я їм не відмо́влював: я не стримував се́рця свого від жодної втіхи, бо ті́шилось серце моє від усякого тру́ду мого́, — і це була частка моя від усякого тру́ду свого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Та коли́ я зверну́вся до всіх своїх чи́нів, що їх поробили були́ мої ру́ки, і до тру́ду, що я потрудився був, ро́блячи, — й ось усе це марно́та та ло́влення вітру, і немає під сонцем нічого кори́сного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'І звернувсь я, щоб бачити мудрість, і бе́зум, і ду́рощі. Бо що зро́бить люди́на, що при́йде вона по царі? Тільки те, що вона вже зробила!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'І я побачив, що є перева́га у мудрости над глупото́ю, як є перевага у світла над те́мрявою:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'у мудрого очі його в голові́ його, а безглу́здий у те́мряві ходить; та теж я пізнав, що доля одна всім їм тра́питься!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'І промовив я в серці своє́му: Коли доля, яка нерозумному трапиться, трапиться також мені, то на́що тоді я мудрі́шим ставав? І я говорив був у серці своїм, що марно́та й оце.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Не лишається пам\'яти про мудрого, як і про нерозумного, на вічні віки́, — в днях насту́пних зовсім все забу́деться, і мудрий вмирає так са́мо, як і нерозумний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'І життя я знена́видів, бо проти́вний мені кожен чин, що під сонцем він чи́ниться, — бо все це марно́та та ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'І знена́видів я ввесь свій труд, що під сонцем труди́вся я був, — бо його позоста́влю люди́ні, що буде вона по мені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'а хто знає, чи мудрий той буде чи нерозумний, хто запанує над цілим трудом моїм, над яким я трудився й змудрі́в був під сонцем? Це марно́та також.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'І я обернувся чини́ти, щоб серце моє прийшло в ро́зпач від усього труда́, що чинив я під сонцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Бо буває люди́на, що тру́диться з мудрістю, зо знання́м та із хи́стом, та все полишає на долю люди́ні, яка не трудила́ся в то́му: Марно́та й оце й зло велике!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Та й що має люди́на зо всього свойого труда́ та із кло́поту серця свого, що під сонцем працює вона?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Бо всі дні її — муки, а смуток — робо́та її, і навіть вночі її серце споко́ю не знає, — теж марно́та й оце!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'Нема ліпшого зе́мній люди́ні над те, щоб їсти та пити, і щоб душа її бачила добре із тру́ду свого́. Та й оце все, я бачив, воно з руки Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Бо хто буде їсти, і хто спожива́ти спроможе без Нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 26, 'Бо люди́ні, що перед лицем Його до́бра, дає Він премудрість, і пізна́ння, і радість; а грішникові Він роботу дає, щоб збирати й грома́дити, — щоб пізніше віддати тому́, хто добрий перед Божим лицем. Марно́та і це все та ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Для всього свій час, і година своя́ кожній справі під небом:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'час роди́тись і час помирати, час садити і час виривати поса́джене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'час вбивати і час лікувати, час руйнувати і час будувати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'час плакати й час регота́ти, час ридати і час танцювати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'час розкида́ти каміння і час каміння грома́дити, час обіймати і час ухилятись обі́ймів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 6, 'час шукати і час розгубити, час збирати і час розкида́ти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 7, 'час дерти і час зашивати, час мовчати і час говорити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 8, 'час кохати і час ненави́діти, час війні і час миру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 9, 'Яка ко́ристь трудя́щому в тім, над чим тру́диться він?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 10, 'Я бачив роботу, що Бог був дав лю́дським синам, щоб труди́лись над нею,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 11, '— усе Він прега́рним зробив свого ча́су, і вічність поклав їм у серце, хоч не розуміє люди́на тих діл, що Бог учинив, від поча́тку та аж до кінця́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 12, 'Я знаю, немає нічо́го в них кращого, як тільки радіти й робити добро́ у своєму житті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 13, 'I отож, як котри́й чоловік їсть та п\'є і в усім своїм тру́ді радіє добром, — це дар Божий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 14, 'Я знаю, що все, що Бог робить, воно зостається навіки, — до того не можна нічого додати, — і з того не можна нічого відня́ти, і Бог так зробив, щоб боялись Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 15, 'Що є, то було́ вже воно, і що статися має — було вже, бо минуле відно́влює Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 16, 'І я бачив під сонцем іще: місце су́ду, — а в нім беззако́ння, і місце правди, — у ньому ж неправда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 17, 'Я сказав був у серці своє́му: Судитиме Бог справедливого й несправедливого, бо для кожної справи є час, і на всяке там ді́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 18, 'Я сказав був у серці своє́му: Це для лю́дських синів, щоб Бог випробо́вував їх, і щоб бачити їм, що вони як ті зві́рі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 19, 'бо доля для лю́дських синів і доля звіри́ни — однакова доля для них: як оці помирають, так само вмирають і ті, і для всіх один по́дих, і нема над твариною ви́щости людям, — марно́та бо все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 20, 'Все до місця одно́го йде: все постало із по́роху, і ве́рнеться все знов до пороху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 21, 'Хто те знає, чи дух лю́дських синів підійма́ється вго́ру, і чи спуска́ється вділ до землі дух скотини?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 22, 'І я бачив, — нема чоловікові кращого, як діла́ми своїми радіти, бо це доля його́! Бо хто поведе́ його гля́нути, що́ буде по ньому?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'І знов я побачив всі у́тиски, що чинились під сонцем, — і сльоза́ ось ути́скуваних, та немає для них потіши́теля, і наси́лля з руки, що їх гно́блять, і немає для них потіши́теля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'І я похвалив тих померлих, що давно повмирали, більш від живих, що живуть дотепе́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'А краще від них від обох тій люди́ні, що досі іще не була́, що не бачила чину лихого, що робився під сонцем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'І я бачив ввесь труд та ввесь у́спіх учи́нку, виклика́є заздрість одно́го до о́дного, — і це все марно́та та ло́влення вітру!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Нерозумний сидить, склавши руки свої, та жере́ своє тіло, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'краща повна долоня споко́ю за повні дві жмені кло́поту та за ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'І зно́ву я бачив марно́ту під сонцем:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Буває само́тній, і не має ніко́го він іншого, сина чи брата у ньо́го нема, та немає кінця всьому зуси́ллю його, і не наси́титься око багатством його, і він не пові́сть: „Та для кого дба́ю і позбавляю добра свою душу?“Марно́та й оце, і даремна робота воно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Краще двом, як одному, бо мають хорошу заплату за труд свій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'і якби вони впали, піді́йме одне́ свого друга! Та горе одно́му, як він упаде́, й нема дру́гого, щоб підве́сти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Також коли вдвох покладу́ться, то тепло їм буде, а я́к же зогрі́тись одно́му?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'А коли б хто напав на одно́го, то вдвох вони стануть на нього, — і нитка потрійна не скоро пірве́ться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Ліпший убогий та мудрий юна́к, аніж цар стари́й та нерозумний, що вже осторо́г не приймає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'бо виходить юнак і з в\'язни́ці, щоб зацарюва́ти, хоч у царстві своїм народивсь він убогим!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Я бачив усіх живих, що ходять під сонцем, на боці цього́ юнака́, — цього дру́гого, що став він на місце його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Немає кінця всьому лю́дові, всьо́му, що був перед ним, та й насту́пні не втішаться ним, — бо й це теж марно́та та ло́влення вітру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Пильнуй за ногою своєю, як до Божого дому йдеш, бо прийти, щоб послухати, — це краще за жертву безглуздих, бо не знають нічо́го вони, окрім чи́нення зла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Не квапся своїми уста́ми, і серце твоє нехай не поспішає казати слова́ перед Божим лицем, — Бог бо на небі, а ти на землі, тому́ то нехай нечисле́нними будуть слова́ твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Бо як сон наступає через велику роботу, так багато слів має і голос безглу́здого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Коли зробиш обі́тницю Богові, то не зволікай її виповнити, бо в Нього нема уподо́бання до нерозумних, а що́ ти обі́туєш, спо́вни!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Краще не дати обі́ту, ніж дати обіт — і не спо́внити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Не давай своїм у́стам впроваджувати своє тіло у гріх, і не говори перед Анголом Божим: „Це помилка!“Пощо Бог буде гні́ватися на твій голос, і діла́ твоїх рук буде нищити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Бо марно́та в числе́нності снів, як і в мно́гості слів, але ти бійся Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Якщо ти побачиш у кра́ї якому ути́скування бідаря́ та пору́шення права та правди, не дивуйся тій речі, бо високий пильнує згори́ над високим, а над ними Всевишній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'І пожи́ток землі є для всіх, бо поле й сам цар обробляє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Хто срі́бло кохає, той не наси́титься сріблом, хто ж кохає багатство з прибу́тком, це марно́та також!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Як маєток примно́жується, то мно́жаться й ті, що його поїдають, і яка ко́ристь його власникові, як тільки, щоб бачили очі його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Сон солодкий в трудя́щого, чи багато, чи мало він їсть, а ситість багатого спати йому не дає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Є лихо болюче, я бачив під сонцем його: багатство, яке береже́ться його власнико́ві на лихо йому, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'і гине багатство таке в нещасли́вім випа́дку, а ро́диться син — і немає нічого у нього в руці:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'як він вийшов наги́й із утро́би матері своєї, так відхо́дить ізнов, як прийшов, і нічо́го не винесе він з свого тру́ду, що можна б узяти своєю рукою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'І це те́ж зло болюче: так само, як він був прийшов, так віді́йде, — і яка йому ко́ристь, що трудився на вітер?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 16, 'А до того всі дні свої їв у темно́ті, і багато мав смутку, й хвороби та люті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 17, 'Оце, що я бачив, як добре та гарне: щоб їла люди́на й пила, і щоб бачила добре в усьо́му своє́му труді́, що під сонцем ним тру́диться в час нечисле́нних тих днів свого віку, які Бог їй дав, — бо це доля її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 18, 'Також кожна люди́на, що Бог дав їй багатство й маєтки, і вла́ду їй дав спожива́ти із то́го, та брати свою частку та тішитися своїм тру́дом, — то це Божий дару́нок!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 19, 'Бо вона днів свого життя небагато на пам\'яті матиме, — то Бог в її серце шле радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 20, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Є ще зло, що я бачив під сонцем, і багато його між людьми́:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Ось люди́на, що Бог їй багатство дає, і маєтки та славу, і недостатку ні в чо́му, чого́ зажадає, не чує вона для своєї душі, але Бог не дав вла́ди їй те спожива́ти, — бо чужа люди́на те поїсть: Це марно́та й неду́га тяжка́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Якби сотню дітей наплоди́в чоловік, і прожи́в пречисле́нні літа́, і дні віку його були довгі, але не наси́тилась добрим душа його, а до того не мав би й належного по́хорону, то кажу́: недоно́скові краще від нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Бо в марно́ті прийшов він, і в те́мряву йде, і в те́мряві сховане буде іме́ння його, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'ані сонця не бачив він, ані пізнав: йому́ спокійніше від того!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'А коли б він жив дві́чі по тисячі літ, та не бачив добра́, — то хіба не до місця одно́го все йде?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Увесь труд люди́ни — для рота її, і пожада́ння її не випо́внюються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Бо що більшого має мудрець, ніж безглуздий, що має убогий над те, що перед живими уміє ходити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Краще бачити очима, аніж мандрува́ти жада́ннями, — і тако́ж це марно́та та ло́влення вітру...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Що було́, тому йме́ння його вже нада́не давно, і відо́ме, що він чоловік, і він не може правува́тися з сильнішим від нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'бо багато рече́й, що марно́ту примно́жують, але яка ко́ристь від них для люди́ни?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 12, 'Бо хто знає, що́ добре люди́ні в житті, за небагатьох днів марно́го життя її, які пробуває вона, немов тінь? Та й що́ хто розкаже люди́ні, що́ буде під сонцем по ній?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Краще добре ім\'я́ від оливи хорошої, а день смерти люди́ни — від дня її вро́дження!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Краще ходити до дому жало́би, ніж ходити до дому бенке́ту, бо то — кінець кожній люди́ні, і живий те до серця свого бере!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Кращий смуток від смі́ху, бо при обличчі сумні́м добре серце!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Серце мудрих — у домі жало́би, а серце безглу́здих — у домі весе́лощів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Краще слухати до́кір розумного, аніж слу́хати пісні безумних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'бо як трі́скот терни́ни під горщиком, такий сміх нерозу́много. Теж марно́та й оце!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Коли мудрий кого утискає, то й сам нерозумним стає, а хаба́р губить серце.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Кінець ді́ла ліпший від поча́тку його; ліпший терпеливий від чванькува́того!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Не спіши в своїм дусі, щоб гні́ватися, бо гнів спочиває у на́драх глупці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Не кажи: „Що́ це сталось, що перші дні були кращі за ці?“, бо не з мудрости ти запитався про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Добра мудрість з багатством, а прибу́ток для тих, хто ще сонечко бачить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'бо в тіні мудрости — як у тіні срі́бла, та ко́ристь пізна́ння у то́му, що мудрість життя зберігає тому́, хто має її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Розваж Божий учинок, — бо хто́ може те ви́простати, що Він покриви́в?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'За доброго дня користай із добра́, за злого ж — розважуй: Одне й друге вчинив Бог на те, щоб люди́на нічо́го по собі не знайшла́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'В днях марно́ти своєї я всьо́го набачивсь: буває справедливий, що гине в своїй справедливості, буває й безбожний, що довго живе в своїм злі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Не будь справедливим занадто, і не роби себе мудрим над міру: пощо нищити маєш себе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 17, 'Не будь несправедливим занадто, і немудрим не будь: пощо маєш померти в неча́сі своїм?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 18, 'Добре, щоб ти ухопи́вся за це, але й з того своєї руки не спускай, бо богобоя́зний втече від усього того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 19, 'Мудрість робить мудрого сильнішим за десятьох володарів, що в місті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 20, 'Немає люди́ни праведної на землі, що робила б добро́ й не грішила,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 21, 'тому́ не клади свого серця на всякі слова́, що гово́рять, щоб не чути свого раба, коли він лихосло́вить тебе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 22, 'знає бо серце твоє, що багато разі́в також ти лихосло́вив на інших!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 23, 'Усе́ це я в мудрості ви́пробував, і сказав: „Стану мудрим!“Та дале́ка від мене вона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 24, 'Дале́ке оте, що було́, і глибо́ке, глибо́ке, — хто зна́йде його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 25, 'Звернувся я серцем своїм, щоб пізна́ти й розві́дати, та шукати премудрість і розум, та щоб пізнати, що безбожність — глупо́та, а нерозум — безу́мство!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 26, 'І знайшов я річ гіршу від смерти — то жінку, бо па́стка вона, її ж серце — тене́та, а руки її — то кайда́ни! Хто добрий у Бога — врято́ваний буде від неї, а грішного схо́пить вона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 27, 'Подивися, оце я знайшов, сказав Пропові́дник: рівняймо одне до одно́го, щоб знайти зрозумі́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 28, 'Чого ще шукала душа моя, та не знайшла: я люди́ну знайшов одну з тисячі, але жінки між ними всіма́ не знайшов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 29, 'Крім то́го, поглянь, що знайшов я: що праведною вчинив Бог люди́ну, та ви́гадок усяких шукають вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 30, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Хто, як той мудрий, і зна́чення речі хто знає? Розсвітлює мудрість люди́ни обличчя її, і суворість лиця її змінюється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Я раджу: Наказа царсько́го виконуй, і то ради прися́ги перед Богом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Не квапся від нього відходити, не стій при злій справі, бо все, що захоче, він зробить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'бо слово царе́ве — то вла́да, і хто йому скаже: „Що́ робиш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Хто виконує заповідь, той не пізна́є нічого лихого, серце ж мудрого знає час і право.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Бо для кожної речі час і право своє, бо лихо люди́ни числе́нне на ній,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'бо не знає, що буде, і я́к саме буде, хто їй розпові́сть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Немає люди́ни, яка панувала б над вітром, щоб стримати вітер, і вла́ди нема над днем смерти, і на війні нема зві́льнення, і пана свого́ не врятує безбожність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Усе це я бачив, і серце своє прикладав я до кожного чину, що відбувався під сонцем. І був час, коли запанувала люди́на над люди́ною на лихо для неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'І я бачив безбожних похо́ваних, і до їхнього гро́бу прихо́дили, а ті, що чинили добро́, повики́дані з місця святого, і в місті забуті. Марно́та й о це!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Що скоро не чиниться при́суд за вчинок лихий, тому́ серце лю́дських синів повне ними, щоб чинити лихе́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Хоч сто раз чинить грішний лихе́, а Бог суд відкладає йому, однако я знаю, що ти́м буде добре, хто Бога боїться, хто перед обличчям Його має страх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'А безбожному добре не буде, і мов тінь, довгих днів він не матиме, бо він перед Божим лицем стра́ху не має!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Є марно́та, яка на землі ді́ється, — що є справедливі, що лихо спадає на них, мов за вчинок безбожних, а є безбожні, що добрео спадає на них, мов за чин справедливих! Я сказав, що марно́та й оце!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 15, 'І радість я похваляв: що немає люди́ні під сонцем добра́, хіба тільки щоб їсти, та пити та ті́шитися, і оце супрово́дить її в її праці за ча́су життя її, що під сонцем Бог дав був їй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 16, 'Коли я поклав своє серце, щоб мудрість пізнати, і побачити чин, що діється він на землі, бо ні вдень ні вночі сну не бачить люди́на своїми очима,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 17, 'і коли я побачив усякий чин Бога, тоді я пізнав, що не може люди́на збагнути чину, під сонцем учи́неного! Тому скільки люди́на не тру́диться, щоб дошукатись цього, то не зна́йде, і коли й мудрий скаже, що знає, — не зможе знайти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ото ж бо все це я до серця свого взяв, і бачило серце моє все оце, що праведні й мудрі та їхні учи́нки — у Божій руці, так само любов чи нена́висть: Люди́на не знає нічого, що є перед нею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Однакове всім випадає: праведному і безбожному, доброму й чистому та нечистому, і тому́, хто жертву прино́сить, і тому, хто жертви не приносить, як доброму, так і грішникові, тому, хто кляне́ться, як і тому, хто клятви боїться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Оце зле у всім, що під сонцем тим ді́ється, — що одна́кове всім випада́є, і серце лю́дських синів повне зла, і за життя їхнього безу́мство в їхньому серці, а по то́му до мертвих відходять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Хто знахо́диться поміж живих, той має надію, бо краще собаці живому, ніж ле́вові ме́ртвому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Бо знають живі, що помруть, а померлі нічо́го не знають, і заплати немає вже їм, — бо забута і пам\'ять про них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'і їхнє коха́ння, і їхня нена́висть, та за́здрощі їхні загинули вже, і нема вже їм ча́стки навіки ні в чо́му, що під сонцем тим ді́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Тож іди, їж із радістю хліб свій, та з серцем веселим вино своє пий, коли Бог уподо́бав Собі твої вчинки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Нехай кожного ча́су одежа твоя буде біла, і нехай на твоїй голові не бракує оли́ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Заживай життя з жінкою, яку ти кохаєш, по всі́ дні марно́ти твоєї, що Бог дав для тебе під сонцем на всі́ дні марно́ти твоєї,— бо оце твоя доля в житті та в твоєму труді́, що під сонцем ним тру́дишся ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Все, що всилі чинити рука твоя, теє роби, бо немає в шео́лі, куди ти йде́ш, ні роботи, ні ро́здуму, ані знання́, ані мудрости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Зно́ву я бачив під сонцем, що біг не у ско́рих, і бій не в хоро́брих, а хліб не в премудрих, і не в розумних багатство, ні ласка — у знавців, — а від ча́су й наго́ди залежні вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Бо ча́су свого люди́на не знає, мов риби, поло́влені в па́губну сітку, і мов пта́хи, захо́плені в сі́льце, — так хапа́ються лю́дські сини за час лиха, коли воно на́гло спадає, на них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Також оцю мудрість я бачив під сонцем, і велика для мене здавалась вона:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Було мале місто, і було в ньому мало людей. І раз прийшов цар великий до нього, й його оточи́в, і побудува́в проти нього велику обло́гу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Але в ньому знайшлася люди́на убога, та мудра, і вона врятувала те місто своєю премудрістю, — та пізніше ніхто не згадав про цю вбогу люди́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'І я говорив: Краща мудрість за силу; одна́ко пого́рджується мудрість бідного, і не слухаються його слів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Слова мудрих, почуті в споко́ї, кращі від крику володаря поміж безглу́здими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 18, 'Мудрість краща від зброї військо́вої, але один грішник погубить багато добра́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Мертві мухи псують та зашумовують оливу мирова́рника, — так трохи глупо́ти псує мудрість та славу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Серце мудрого тягне право́руч, а серце безумного — ліво́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Коли нерозумний і прямою дорогою йде, йому серця бракує, і всім він говорить, що він нерозумний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Коли гнів володаря стане на тебе, не лишай свого місця, — бо лагі́дність доводить до про́щення навіть великих провин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Є зло, що я бачив під сонцем, мов по́милка, що повстає від володаря:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'на великих висо́тах глупо́та буває поста́влена, а багаті сидять у низині́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Я бачив на ко́нях рабів, князі́ ж пішки ходили, немов ті раби.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Хто яму копає, той в неї впаде́, а хто валить мура, того га́дина вкусить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Хто зно́сить камі́ння, пора́ниться ним; хто дро́ва рубає, загро́жений ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Як залізо ступіє, й хтось ле́за не ви́гострить, той мусить напру́жити свою силу, — та мудрість зара́дить йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Коли вкусить гадюка перед закля́ттям, тоді ворожби́т не потрібний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Слова́ з уст премудрого — милість, а губи безумного нищать його:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'поча́ток слів його уст — глупо́та, а кінець його уст — зле шале́нство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Нерозумний говорить багато, та не знає люди́на, що́ буде; а що буде по ньому, хто скаже йому?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Втомляє безумного праця його, бо не знає й дороги до міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 16, 'Горе, кра́ю, тобі, коли цар твій — хлопчи́на, а влади́ки твої спозара́нку їдять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 17, 'Щасливий ти, кра́ю, коли син шляхе́тних у тебе царем, а влади́ки твої своєча́сно їдять, як ті му́жі, а не як п\'яни́ці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 18, 'Від лі́нощів ва́литься стеля, а з опу́щення рук тече дах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 19, 'Гости́ну справляють для радощів, і вином весели́ться життя, а за срі́бло все це можна мати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 20, 'Навіть у ду́мці своїй не злосло́в на царя, і в спа́льні своїй не кляни багача́, — небесний бо птах віднесе́ твою мову, а крила́тий розкаже про слово твоє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Хліб свій пускай по воді, бо по багатьох днях знов зна́йдеш його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Давай частку на сім чи й на вісім, бо не знаєш, яке буде зло на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Коли́ перепо́вняться хмари дощем, то виллють на землю його. А коли дереви́на на пі́вдень впаде́ чи на пі́вніч, зали́шитьсяна місці, куди дереви́на впаде́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Хто вважає на вітер, не буде той сі́яти, а хто споглядає на хмари, не буде той жати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Як не ві́даєш ти, яка то путь вітру, як кості зроста́ють в утро́бі вагі́тної, так не ві́даєш ти чину Бога, що робить усе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Сій ра́нком насіння своє, та й під вечір хай не спочиває рука твоя, не знаєш бо ти, котре ви́йде на краще тобі, — оце чи оте, чи обо́є одна́ково добрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'І світло солодке, і добре оча́м сонце бачити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'і коли б люди́на жила́ й довгі роки́, хай за всіх їх вона ті́шиться, і хай пам\'ятає дні те́мряви, бо їх бу́де багато, — усе, що надійде, марно́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Ті́шся, юначе, своїм молоде́цтвом, а серце твоє нехай буде веселе за днів молодо́щів твоїх! І ходи ти доро́гами серця свого й виді́нням оче́й своїх, але знай, що за все це впрова́дить тебе Бог до су́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Тому́ жени смуток від серця свого́, і віддаляй зле від тіла твого, бо й дити́нство, і рання життє́ва зоря́ — то марно́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'І пам\'ята́й в днях юна́цтва свого́ про свого Творця́, аж поки не при́йдуть злі дні, й не наступлять літа́, про які говорити ти бу́деш: „Для мене вони неприємні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'аж поки не сте́мніє сонце, і світло, і місяць, і зо́рі, і не ве́рнуться хмари густі́ за доще́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'у день, коли затремтя́ть ті, хто дім стереже, і зі́гнуться мужні, і спи́нять роботу свою млинарі́, бо їх стане мало, і поте́мніють ті, хто в вікно визирає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'і двері подвійні на вулицю за́мкнені бу́дуть, як зме́ншиться гу́ркіт млина́, і голос пташи́ни замовкне, і затихнуть всі до́чки співучі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'і будуть боятись високого місця, і жа́хи в дорозі їм бу́дуть, і мигда́ль зацвіте, й обтяжі́є коби́лка, і загине бажа́ння, бо люди́на відхо́дить до вічного дому свого́, а по вулиці будуть ходити довко́ла голосі́льники,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'аж поки не пі́рветься срібний шнуро́к, і не зло́миться кругла посу́дина з золота, і при джерелі́ не розі́б\'ється глек, і не зламається ко́ло, й не ру́не в крини́цю...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'І ве́рнеться порох у землю, як був, а дух ве́рнеться зно́ву до Бога, що дав був його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Наймарні́ша марно́та, — сказав Пропові́дник, — марно́та — усе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Крім того, що Пропові́дник був мудрий, він навчав ще наро́д знання́. Він важив та досліджував, склав багато при́повістей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Проповідник пильнував знахо́дити потрібні слова, і вірно писав правдиві слова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Слова мудрих — немов оті ле́за в ґірли́зі, і мов позаби́вані цвя́хи, складачі́ ж таких слів, — вони да́ні від одного Па́стиря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'А понад те, сину мій, будь обере́жний: складати багато книжо́к — не буде кінця́, а багато навчатися — мука для тіла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Підсумок усьо́го почутого: Бога бійся, й чини́ Його за́повіді, бо належить це кожній люди́ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Бо Бог приведе́ кожну справу на суд, і все потаємне, — чи добре воно, чи лихе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Соломонова Пісня над піснями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, '„Нехай він цілує мене поцілу́нками уст своїх, — бо ліпші коха́ння твої від вина!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'На запах оливи твої запашні́, твоє йме́ння — неначе олива розлита, тому діви кохають тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Потягни ти мене за собою, біжім! Цар впровадив мене у пала́ти свої, — ми радіти та ті́шитись будемо тобою, згадаємо коха́ння твої, від вина приємніші, — поправді кохають тебе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Дочки єрусалимські, — я чорна та гарна, немов ті намети кеда́рські, мов за́навіси Соломонові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Не дивіться на те, що смугля́венька я, бож сонце мене опали́ло, — сини неньки моєї на мене розгні́валися, настанови́ли мене сторожи́ти виноградники, — та свого виноградника власного не встерегла я!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, '„Скажи ж мені ти, кого покохала душа моя: Де́ ти пасеш? Де даєш ти спочи́ти у спе́ку ота́рі? Пощо́ біля стад твоїх друзів я буду, немов та причи́нна?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, '„Якщо ти не знаєш цього́, вродливі́ша посеред жіно́к, то вийди собі за слідами отари, і випа́суй при ша́трах пасту́ших козля́тка свої“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, '„Я тебе прирівня́в до лошиці в воза́х фараонових, о моя ти подру́женько!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Гарні щі́чки твої поміж шну́рами пе́рел, а шийка твоя — між разка́ми намиста!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Ланцюжки́ золоті ми поробимо тобі разом із срібними ку́льками!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, '„Доки цар при своє́му столі, то мій нард видає́ свої па́хощі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Мій коханий для мене — мов ки́тиця ми́рри: спочиває між пе́рсами в мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Мій коханий для мене — мов ки́прове гроно в ен-ґе́дських сада́х-виноградах“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '„Яка ти прекрасна, моя ти подру́женько, яка ти хороша! Твої очі немов голуби́ні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, '„Який ти прекрасний, о мій ти коханий, який ти приємний! а ложе нам — зе́лень!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Бруси наших домів — то кедри́ни, стелі в нас — кипари́си!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '„Я — саро́нська троя́нда, я доли́нна ліле́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Як ліле́я між те́реном, так подру́га моя поміж ді́вами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, '„Як та яблуня між лісови́ми дере́вами, так мій коханий поміж юнака́ми, — його ті́ні жадала й сиділа я в ній, і його плід для мого піднебі́ння солодкий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Він впровадив мене до виня́рні, а пра́пор його надо мною — любов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Підкріпіте мене виногра́довим пе́чивом, освіжі́ть мене яблуками, — бо я хвора з любови!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Ліва рука його — під головою моєю, прави́ця ж його — пригорта́є мене!..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Заклинаю я вас, дочки єрусалимські, газе́лями чи польови́ми оленями, — щоб ви не споло́хали, й щоб не збудили любови, аж доки йому́ до вподо́би!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, '„Голос мого коханого! Ось він іде, ось він скаче гора́ми, по пагі́рках вистри́бує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Мій коханий подібний до са́рни чи до молодого оленя. Он стоїть він у нас за стіною, зазирає у ві́кна, заглядає у ґра́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Мій коханий озвався й промовив до мене: „Уставай же, подру́го моя, моя кра́сна, й до мене ходи́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Бо оце промину́ла пора дощова́, дощ ущу́х, перейшов собі він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Показались квітки́ на землі, пора солове́йка настала, і голос го́рлиці в нашому кра́ї луна́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Фіґа ви́пустила свої ранні плоди́, і розцвілі виногра́дини па́хощі ви́дали. Уставай же, подру́го моя, моя красна, й до ме́не ходи́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, '„Голубко моя у розщі́линах ске́льних, у бе́скіднім схо́вку, — дай побачити мені твоє ли́чко, дай почути мені голосо́к твій, бо голос твій милий, а личко твоє уродли́ве!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, '„Ловіть нам лисиці, лисиня́та маленькі, що ушко́джують нам виногра́дники, виноградники ж наші — у цві́ті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Мій коханий — він мій, я ж його́, він пасе між ліле́ями!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Поки день прохоло́ду наві́є, а ті́ні втечу́ть, — вернись, мій коханий, стань подібний до са́рни чи до молодого оленя в паху́чих гора́х!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '„По но́чах на ложі своїм я шукала того́, кого́ полюбила душа моя. Шукала його, — та його не знайшла́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Хай устану й нехай я пройду́ся по місті, хай на ву́лицях та на майда́нах того пошукаю, кого полюбила душа моя! Шукала його, — та його не знайшла́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Спітка́ли мене сторожі́, що по місті прохо́дять. „Чи не бачили ча́сом того, кого полюбила душа моя?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Небагато пройшла я від них, — та й знайшла́ я того́, кого́ полю́била душа моя: схопи́ла його, — й не пустила його, аж по́ки його не ввела́ у дім неньки своєї, та в кімна́ту тієї, що в утро́бі носила мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Заклинаю я вас, дочки єрусалимські, газе́лями чи польови́ми оленями, щоб ви не споло́хали, щоб не збуди́ли любови, аж доки йому до вподо́би!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, '„Хто вона, що вихо́дить із пустині, немов стовпи диму, оку́рена ми́ррою й ла́даном, всіля́кими па́хощами продавця?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, '„Ось ло́же його, Соломонове, — шістдесят лицарів навколо нього, із лицарів славних Ізраїлевих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Усі вони мають меча, усі вправні в бою́, кожен має свого меча при своєму стегні́ проти стра́ху нічно́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Но́ші зробив собі цар Соломон із лива́нських дере́в:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'стовпці їхні зробив він із срі́бла, а їхне опертя́ — золоте, пурпуро́ве сиді́ння, їхня сере́дина ви́стелена коха́нням дочо́к єрусалимських!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Підіть і побачте, о до́чки сіо́нські, царя Соломона в вінку́, що ним мати його увінча́ла його в день весілля його та в день радости серця його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, '„Яка ти прекрасна, моя ти подру́женько, яка ти хоро́ша! Твої оченя́тка, немов ті голу́бки, глядя́ть з-за серпа́нку твого́! Твої ко́си — немов стадо кіз, що хви́лями схо́дять з гори Гілеа́дської!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'Твої зу́бки — немов та отара овець пообстри́ганих, що з ку́пелю вийшли, що ко́тять близня́та, і між ними немає неплі́дної,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'Твої гу́бки — немов кармази́нова нитка, твої у́стонька красні, мов частина грана́тного яблука — скро́ня твоя за серпа́нком твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Твоя шия — немов та Давидова башта, на збро́ю збудо́вана: тисяча щитів повішена в ній, усе щити ли́царів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'Два пе́рса твої — мов ті двоє близнят молодих у газе́лі, що випа́суються між ліле́ями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'Поки день прохоло́ду навіє, а ті́ні втечуть, піду́ я собі на ту ми́ррину го́ру й на па́гірок ладану“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, '„Уся ти прекрасна, моя ти подру́женько, і пля́ми нема на тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'Зо мною з Лівану, моя нарече́на, зо мною з Лівану ти пі́деш! Спогля́неш з вершини Ама́ни, з вершини Сені́ру й Гермо́ну, з лего́вища левів, з леопа́рдових гір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Забра́ла ти серце мені, моя се́стро, моя нарече́на, забра́ла ти серце мені самим о́чком своїм, разо́чком одне́ньким намиста свого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Яке любе коха́ння твоє, о сестрице моя, нарече́на! Скільки ліпша любов твоя за вино, а запа́шність олив твоїх — за всі па́хощі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Уста твої кра́пають мед щільнико́вий, моя наречена, мед і молоко — під твоїм язичко́м, а па́хощ одежі твоє́ї — як ліва́нські ті па́хощі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, '„Замкне́ний садок — то сестриця моя, наречена моя — замкне́ний садок, джерело́ запеча́тане.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Лоно твоє — сад грана́тових яблук з плодо́м доскона́лим, ки́при із на́рдами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'нард і шафра́н, пахуча трости́на й кори́ця з усіма деревами ла́дану, ми́рра й ало́е зо всіма́ найзапашні́шими па́хощами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'ти джерело́ садкове́, криниця живої води, та тієї, що пли́не з Лива́ну“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, '„Прокинься, о вітре з півно́чі, і прили́нь, вітре з полу́дня, — повій на садок мій: нехай потечуть його па́хощі! Хай коха́ний мій при́йде до са́ду свого́, і нехай споживе́ плід найкращий його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 1, '„Прийшов я до са́ду свого, о се́стро моя, наречена! Збираю я мирру свою із бальза́мом своїм, спожива́ю свого стільника́ разом із медом своїм, п\'ю вино я своє зо своїм молоком! Споживайте, співдру́зі, — пийте до схо́чу, кохані!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 2, '„Я сплю, — моє ж серце чува́є. Ось голос мого коханого! Стукає. „Відчини мені, се́стро моя, о моя ти подру́женько, голубко моя, моя чиста, — бо росою покри́лася вся моя голова, мої ку́чері — кра́плями ночі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 3, '„Зняла я одежу свою, — як зно́ву її надягну́? Помила я ні́жки свої, — як же їх занечи́щу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 4, 'Мій коханий простя́г свою руку крізь о́твір, — і нутро моє схвилюва́лось від нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 5, 'Встала я відчини́ти своє́му коханому, — а з рук моїх ка́пала ми́рра, і мирра текла́ на засу́вки замка́ з моїх пальців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 6, 'Відчинила своє́му коханому, — а коханий мій зник, відійшов! Душі не става́ло в мені, як він говорив. Я шукала його, та його не знайшла́. Я гука́ла його, та він не відізва́вся до мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 7, 'Стріли мене сторожі́, що ходять по місті, — набили мене, завдали́ мені ра́ни. Здерли з мене моє покрива́ло, сторожі́ міських мурів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 8, '„Заклинаю я вас, дочки єрусалимські, — як мого коханого стрінете ви, що йому повісте́? — Що я хвора з коха́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 9, '„Чим коханий твій кращий від інших коханих, вродливі́ша з жіно́к? Чим коха́ний твій кращий від іншіх коханих, що так заклина́єш ти нас?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 10, '„Коханий мій білий й рум\'я́ний, визначні́ший він від десяти тисяч інших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 11, 'Голова його — щиреє золото, його ку́чері — па́льмове віття, чорні, як во́рон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 12, 'Його очі — немов голубки́ над джере́лами во́дними, у молоці повими́вані, що над повним струмко́м посіда́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 13, 'Його ли́чка — як гря́дка бальза́му, немов квітники́ запашні́! Його губи — ліле́ї, з яких ка́пає ми́рра теку́ча!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 14, 'Його руки — стовпці́ золоті, повиса́джувані хризолі́том, а ло́но його — твір мисте́цький з слоно́вої кости, покритий сапфі́рами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 15, 'Його сте́гна — стовпи мармуро́ві, поста́влені на золотії підста́ви! Його вигляд — немов той Лива́н, він юна́к — як ті ке́дри!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 16, 'Уста його — солодо́щі, і він увесь — пожада́ння. Оце мій коханий, й оце мій дружо́к, дочки єрусали́мські!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 17, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 1, '„Куди твій коха́ний пішов, о найвродливі́ша з жінок? Куди спрямува́в твій коха́ний? Бо ми пошукаємо його із тобою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 2, '„Мій коханий пішов до садо́чка свого́, в квітники́ запашні́, щоб па́сти в садка́х і збирати ліле́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 3, 'Я належу своєму коханому, а мені — мій коханий, що пасе між ліле́ями!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 4, '„Ти прекрасна, моя ти подру́женько, мов та Тірца́, ти хороша, як Єрусалим, ти грізна́, як війська́ з прапора́ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 5, 'Відверни́ ти свої оченя́та від мене, бо вони непоко́ять мене! Твої коси — немов стадо кіз, що хви́лями сходять з того́ Гілеа́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 6, 'Твої зуби — немов та отара ове́ць, що з ку́пелю вийшли, що ко́тять близня́та, і між ними немає неплідної!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 7, 'Мов частина грана́тного яблука — скро́ня твоя за серпа́нком твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 8, 'Шістдеся́т є цариць, і вісімдеся́т є нало́жниць, а дівчатам немає числа, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 9, 'та єдина вона — ця голубка моя, моя чиста! У не́ньки своєї вона одина́чка, обра́на вона у своєї роди́тельки! Як бачили до́чки Сіону її, то щасливою звали її, цариці й нало́жниці — то вихваля́ли її:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 10, 'Хто це така, що вона виглядає, немов та досві́тня зоря́, прекрасна, як місяць, як сонце — ясна́, як полки́ з прапора́ми — грізна́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 11, '„Зійшла я в орі́ховий сад, щоб погля́нути на пу́п\'яночки при пото́ці, щоб побачити там, чи зацвів виноград, чи грана́тові яблуні порозцвіта́ли?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 12, 'І не зчу́лася я, як мене посадила душа моя між колесни́ці моєї дружи́ни боя́р“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 6, 13, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 1, '„Верни́ся, вернись, Суламі́тко! Вернися, вернися, — нехай ми на тебе нади́вимось!“„Чого вам дивитися на Суламітку, немов би на та́нець військо́вий?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 2, '„Хороші які стали ноги твої в черевичках, князі́вно моя́! Заокру́глення сте́гон твоїх — мов намисто, руками мисте́цькими ви́точене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 3, 'Твоє лоно — немов круглото́чена чаша, в якій не забра́кне вина запашно́го! Твій живіт — сніп пшениці, ото́чений тими ліле́ями!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 4, 'Два пе́рса твої — немов двоє сарня́ток близня́т!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 5, 'Твоя шия — як ба́шта із кости слоно́вої, твої очі — озе́рця в Хешбо́ні при брамі того Бат-Рабі́му, в тебе ніс — немов башта лива́нська, що ди́виться все в бік Дама́ску!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 6, 'Голі́вка твоя на тобі — мов Карме́л, а коса́ на голі́вці твоїй — немов пу́рпур, — поло́нений цар тими ку́черями!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 7, 'Яка ти прекрасна й приємна яка, о любов в розко́шах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 8, 'Став подібний до па́льми твій стан, твої ж пе́рса — до грон виногра́дних!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 9, 'Я поду́мав: ви́беруся на цю па́льму, схоплю́ся за ві́ття її, — і нехай стануть пе́рса твої, немов виноградні ті грона, а па́хощ диха́ння твого — як яблука!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 10, '„А у́ста твої — як найліпше вино: просту́є воно до мого коханого, чинить промо́вистими й уста сплячих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 11, 'Я належу своєму коханому, а його пожада́ння — до мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 12, 'Ходи ж, мій коханий, та ви́йдемо в поле, переночу́ємо в се́лах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 13, 'Устанемо рано, й ходім у сади - виногради, поди́вимося, чи зацвів виноград, чи квітки́ розцвіли́сь, чи грана́тові яблуні порозцвіта́ли? Там любов свою тобі дам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 7, 14, 'Видадуть пах мандраго́ри, при наших же вхо́дах — всіля́кі коштовні плоди́, нові́ та старі, що я їх заховала для тебе, коханий ти мій!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 1, '„О, коли б ти мені був за брата, що пе́рса ссав в нені моєї, коли б стріла тебе я на вулиці, цілувала б тебе,— і ніхто мені не докоря́в би!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 2, 'Повела́ б я тебе й привела́ б у дім нені своєї: ти навчав би мене, я б тебе напоїла вином запашни́м, со́ком грана́тових яблук своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 3, 'Ліва рука його — під головою моєю, прави́ця ж його — пригорта́є мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 4, 'Заклинаю я вас, дочки єрусалимські, — нащо б споло́хали, й нащо б збудили любови, аж доки йому до вподо́би!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 5, '„Хто вона, що вихо́дить із пустині, спира́ючися на свого коханого? Під яблунею я збуди́ла тебе, — там повила́ тебе мати твоя, там тебе повила́ твоя породи́телька!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 6, '„Поклади ти мене, як печатку на серце своє, як печать на раме́но своє, бо сильна любов, як смерть, за́здрощі неперемо́жні, немов той шео́л, — його жар — жар огню, воно по́лум\'я Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 7, 'Во́ди великі не зможуть згаси́ти коха́ння, ані рі́ки його не заллю́ть! Коли б хто давав за любов маєток увесь свого дому, то ним погорди́ли б зовсі́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 8, '„Є сестра в нас мала, й перс у неї нема ще. Що зробимо нашій сестри́чці в той день, коли сва́тати бу́дуть її? —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 9, 'Якщо вона мур, — заборо́ло із срібла збудуємо на ній, а якщо вона двері — обкладе́мо кедро́вою до́шкою їх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 10, '„Я мур, мої ж пе́рса — як ба́шти, — тоді я була́ в його о́чах мов та, яка спо́кій прова́дить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 11, '„Виноградинка мав Соломон у Баал-Гамо́ні, виноградника він віддава́в сторожа́м, — щоб кожен прино́сив за плід його тисячу срі́бла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 12, 'Але мій виногра́дник, що маю його, при мені! Тобі, Соломо́не, хай буде та тисяча, а сторожа́м його пло́ду — дві сотні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 13, 'О ти, що сидиш у садка́х, — друзі твої прислуха́ються до твого голосу: дай почути його і мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 14, '„Утікай, мій коха́ний, і станься подібний до са́рни собі, чи до молодого оленя у бальза́мових го́рах!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 8, 15, '');
