INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 38, 40, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 1, 'Дев\'ятого року Седекії, царя Юдиного, місяця десятого, прийшов Навуходоно́сор, цар вавилонський, та все його ві́йсько до Єрусалиму та й облягли́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 2, 'Одина́дцятого року Седекії, місяця четвертого, дев\'ятого дня місяця, був пробитий про́лім до міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 3, 'І поприхо́дили всі зверхники вавилонського царя, і посідали в Середу́щій брамі: Нерґал-Сар\'ецер, Самгар, Нево, Сарсехім, ста́рший е́внух, Нерґал-Сар\'ецер, старший маг, і вся решта зверхників вавилонського царя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 4, 'І сталося, як побачив їх Седекія, цар Юдин, та всі вояки́, то вони повтікали, і повихо́дили вночі з міста дорогою царсько́го садка́, брамою між обома́ му́рами, і вийшли дорогою в степ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 5, 'І погналося халдейське ві́йсько за ними, і догнали Седекію в єрихо́нських степа́х. І взяли́ вони його, і завели його до Навуходоно́сора, царя вавилонського, до Рівли, в краю́ Хамат, і той засудив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 6, 'І цар вавилонський порізав Седекіїних синів в Рівлі на оча́х його; і всіх шляхе́тних Юдиних порізав вавилонський цар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 7, 'А очі Седекії він ви́брав, і скував його мідяни́ми кайда́нами, щоб відве́сти його до Вавилону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 8, 'А дім царя та дому наро́ду халдеї попалили огнем, і порозбивали му́ри Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 9, 'А решту наро́ду, позосталих у місті, та перебі́жців, що поперехо́дили до нього, і решту народу, що позоста́лися, вигнав Невузар\'адан, начальник царсько́ї сторо́жі, до Вавилону.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 10, 'А з бідноти́ народу, що не мали нічого, Невузар\'адан, начальник царсько́ї сторожі, позоставив декого в Юдиному краї, і дав їм того дня виноградники та поля́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 11, 'І наказав Навуходоносор, цар вавилонський, про Єремію, через начальника царсько́ї сторожі, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 12, '„Візьми його, і зверни на нього свої очі, і не зроби йому нічого злого, і тільки я́к він скаже тобі, та́к з ним зроби!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 13, 'І послав Невузар\'адан, начальник царсько́ї сторожі, і Невушазбан, старший е́внух, і Нерґал-Сар\'ецер, старший маг, та всі начальники вавилонського царя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 14, 'і послали вони, і взяли́ Єремію з подвір\'я в\'язни́ці, і дали́ його до Ґедалі́ї, сина Ахікама, сина Шафанового, щоб ви́вести його до дому. І осівся він серед наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 15, 'А до Єремії було Господнє слово, коли він був затри́маний в подвір\'ї в\'язни́ці, таке:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 16, '„Іди, і скажеш до му́рина Евед-Мелеха, говорячи: Так говорить Господь Саваот, Бог Ізраїлів: Ось Я наво́джу Свої слова́ на це місто на зло, а не на добро, і вони будуть ді́ятися перед тобою цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 17, 'Але тебе врятую цього дня, — говорить Господь, — і ти не бу́деш ві́дданий в руку цих людей, яких ти боїшся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 39, 18, 'Бо конче врятую тебе, і від меча не впаде́ш ти, і буде тобі душа твоя за здо́бич, бо ти наді́явся на Мене, говорить Господь“.');
