INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 47, 13, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 47, 14, '');
