INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Як самі́тно сидить колись велелю́дне це місто, немов удова́ воно стало! Могутнє посе́ред наро́дів, княгиня посеред країн — воно стало данни́цею!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Гірко плаче по но́чах вона, і сльо́зи гарячі на що́ках у неї. Нема потіши́теля в неї зо всіх, що кохали її, — її зрадили всі її дру́зі, вони ворогами їй стали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Юдея пішла на вигна́ння з біди та з роботи тяжко́ї, вона оселилася поміж пога́нами, спочи́нку собі не знайшла! Догнали її всі її переслі́дники серед тісно́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Доро́ги сіонської до́ньки сумні́, бо немає на свято проча́н! Усі брами її попусті́ли, зідхає свяще́нство її, посумні́лі дівчата її, а вона — гірко їй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Її грабівники́ взяли го́ру над нею, і добре веде́ться її ворогам, бо їй завдав смутку Госпо́дь за числе́нність у неї гріхів: Немовлята її до поло́ну пішли перед ворогом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'І відійшла від сіонської до́ньки вся вели́чність її. Її князі́ стали, немов о́лені ті, що паші собі́ не знахо́дять, — і йдуть у безси́ллі перед переслі́дником.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'У дні лиха свого та стражда́ння свого́ дочка єрусалимська спога́дує всі свої ска́рби, — що були від днів давніх, як наро́д її впав був у руку ворожу, і не було́, хто б їй поміч подав. Вороги спогляда́ли на неї, і сміялись з руїни її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Дочка єрусалимська гріхом прогріши́лась, тому́ то нечистою стала, усі, що її шанували, пого́рджують нею, наготу́ бо її вони бачили! І зідхає вона, й відверта́ється взад.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Нечистість її на подо́лках у неї. Вона не згадала свого кінця, та й упала преди́вно, і ніко́го нема, хто б потішив її. „Побач, Господи, горе моє, бо звели́чився ворог!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Гноби́тель простяг свою руку на всі її ска́рби, і бачить вона, що в святиню її увіходять пога́ни, про яких наказав Ти: „Не вві́йдуть вони в твої збо́ри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Увесь наро́д її сто́гне, шукаючи хліба, свої ска́рби кошто́вні за їжу дають, аби́ тільки душу свою проживи́ти. „Зглянься, Господи, і подивися, яка стала пого́рджена я!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Не вам ка́жучи, гляньте й побачте, усі, хто дорогою йде: чи є такий біль, як мій біль, що завда́ний мені, що Госпо́дь засмути́в ним мене у день лютого гніву Свого́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Із височини́ Він послав в мої кості огонь, і над ними він запанува́в! Розтяг сітку на но́ги мої, повернув мене взад, учинив Він мене́ спустоші́лою, увесь день боля́щою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Ярмо́ моїх про́гріхів зв\'я́зане міцно рукою Його, плету́ться вони та прихо́дять на шию мою! Він зробив, що спіткну́лася сила моя, Господь передав мене в руки такого, що й зве́стись не мо́жу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Усіх моїх сильних Господь поскида́в серед мене, мов на свято зібра́ння, Він скликав на мене, щоб моїх юнакі́в поторо́щити, як у чави́лі, стоптав Господь ді́вчину, Юдину до́ньку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'За оцим плачу я, око моє, — моє око слізьми́ заплива́є! бо дале́ко від мене втіши́тель, що душу мою оживив би; мої діти поне́хтувані, бо поси́лився ворог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Сіонська дочка́ простягла свої руки, — немає розра́дника їй: Госпо́дь наказав проти Якова довкола ньо́го його ворогам, донька єрусали́мська нечистою стала між ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, '„Справедливий Господь, а я слову Його неслухня́на була́. Послухайте но, всі наро́ди, і побачте мій біль: дівчата мої та мої юнаки́ у неволю пішли́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Взивала до дру́зів своїх, та вони обману́ли мене! Свяще́нство моє й мої ста́рші вмирають у місті, шукаючи їжі собі, щоб душу свою поживи́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Зглянься, Господи, — тісно мені! Моє нутро бенте́житься, переверта́ється серце моє у мені, бо була́ зовсі́м неслухня́на. На вулиці меч осиро́чував, а в до́мі — смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Почули, що я ось стогну́, й немає мені потіши́теля, вчули про лихо моє всі мої вороги́, — та й зраді́ли, що Ти це зроби́в. Спровадив Ти день, що його запові́в, — бодай ста́лося їм, як мені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Бодай перед обличчя Твоє прийшло все їхнє лихо, — і вчини їм, як Ти учинив ось мені за гріхи мої всі, — бо числе́нні стогна́ння мої, моє ж серце боля́ще“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Як захма́рив Господь в Своїм гніві сіо́нську дочку́! Він кинув із неба на зе́млю пишно́ту Ізраїля, і не згадав у день гніву Свого́ про підні́жка ногам Своїм, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'понищив Господь, не помилував жи́тла всі Яковові. Він позбу́рював у гніві Своїм у дочки́ Юди тверди́ні, на землю звали́в, збезче́стив Він ца́рство й князі́в усіх його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'В люті гніву відтяв увесь Ізраїлів ріг, прави́цю Свою відверну́в Він від во́рога, та й запала́в проти Якова, мов той палю́чий огонь, що навко́ло жере́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Він нап\'я́в Свого лу́ка, як ворог, проти́вником стала прави́ця Його́, і Він вибив усе, що для ока було пожада́не, у скинії до́ньки сіонської вилив запе́клість Свою, як огонь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Господь став, як той во́рог, пони́щив Ізраїля Він, всі пала́ти його зруйнува́в, тверди́ні його попусто́шив, — і Юдиній до́ньці примно́жив зідха́ння та сто́гін!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Понищив горо́жу Свою, немов у садка́, місце зборів Своїх попусто́шив, Госпо́дь учинив, що забу́ли в Сіоні про свято й суботу, і відки́нув царя́ та священика в лю́тості гніву Свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Покинув Господь Свого же́ртівника, допусти́в побезче́стити святиню Свою́, передав в руку во́рога му́ри пала́ців її, — вороги́ зашуміли в Господньому домі, немов би святко́вого дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Задумав Госпо́дь зруйнува́ти мур сіо́нської до́ньки, Він ви́тягнув шнура, Своєї руки не вернув, щоб не нищити, сумни́ми вчинив передму́р\'я та мур, — вони ра́зом осла́бли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'її брами запа́лися в зе́млю, пони́щив Він та полама́в її за́суви. Її цар і князі́ її серед поганів. Немає навча́ння Зако́ну, і пророки її не знахо́дять виді́ння від Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Сидять на землі та мовчать старші́ до́ньки сіо́нської, по́рох посипали на свою голову, підпереза́лись вере́тами, аж до землі свою го́лову єрусалимські дівчата схили́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Повиплива́ли від сліз мої очі, моє ну́тро клеко́че, на землю печінка моя вилива́ється через зане́пад дочки́ мого люду, коли немовля́ й сосуне́ць умліва́ють голодні на пло́щах міськи́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Вони кви́лять своїм матеря́м: „Де пожи́ва й вино?“І ску́люються, як ране́ний, на пло́щах міськи́х, коли ду́ші свої випускають на лоні своїх матері́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Що засві́дчу тобі, що вподо́блю до тебе, о єрусалимськая до́чко? Що вчиню́ тобі рі́вним, щоб тебе звесели́ти, о діво, о до́чко сіонська? Бо велика, як море, руїна твоя́, — хто тебе поліку́є?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Пророки твої провіща́ли для тебе марно́ту й фальши́ве, і не відкривали твого гріха́, щоб долю твою відверну́ти, — для тебе вбачали пророцтва марно́ти й вигна́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Усі, що проходять дорогою, плещуть у долоні на тебе, і посви́стують та головою своє́ю хита́ють над до́нькою Єрусалиму та кажуть: „Хіба це те місто, що про ньо́го казали: Корона пишно́ти, розра́да всієї землі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Усі вороги твої па́щу на тебе роззя́влюють, сви́щуть й зубами скрего́чуть та кажуть: „Ми поже́рли її. Оце справді той день, що чекали його, — знайшли ми і бачимо його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Учинив Господь те, що заду́мав, Він ви́повнив слово Своє, що його наказав від днів да́вніх: усе зруйнував, і милосердя не мав, і ворога втішив тобою, Він ро́га підійняв супроти́вних твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 18, 'Їхнє серце до Господа крик підіймає, о муре, о до́чко Сіону! Проливай, як потік, сльози вдень та вночі, не давай відпочи́нку собі, нехай не спочи́не зіни́ця твоя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 19, 'Уставай, голоси уночі на поча́тку сторо́жі! Виливай своє серце, мов во́ду, навпроти обли́ччя Господнього! Підійми ти до Нього доло́ні свої за душу своїх немовля́т, що від голоду мліють на розі всіх вулиць!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 20, 'Споглянь, Господи, і подивися, кому́ Ти зробив отаке? Чи конечним було, щоб жінки́ їли плід свій, свої́х немовля́т, яких ви́плекали? Щоб був у святині Господній заби́тий священик і пророк?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 21, 'Лежать на землі на вулицях ря́дом юнак та стари́й. Попа́дали діви мої та мої парубки́ від меча́, — Ти побив їх в день гніву Свого́, порізав, не мав милосердя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 22, 'Ти викли́кував, мов на день свята, жахо́ти мої із довкі́лля, — і врято́ваного не було́, і позоста́льця в день гніву Господнього, — повигублював ворог мій тих, кого ви́плекала та зрости́ла була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Я той муж, який бачив біду́ від жезла́ Його гніву, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Він прова́див мене й допрова́див до те́мряви, а не до світла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Лиш на мене все зно́ву обе́ртає руку Свою́ цілий день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Він ви́снажив тіло моє й мою шкіру, мої кості сторо́щив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'обгородив Він мене, і мене оточи́в гіркото́ю та му́кою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'у темно́ті мене посадив, мов померлих давно́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Обгороди́в Він мене — і не ви́йду, тяжки́ми вчинив Він кайда́ни мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'І коли я кричу́ й голошу́, затикає Він вуха Свої на молитву мою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Камінням обте́саним обгородив Він доро́ги мої, повикри́влював стежки́ мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Він для мене ведме́дем чату́ючим став, немов лев той у схо́вищі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Поплутав доро́ги мої та розша́рпав мене́, учинив Він мене опусто́шеним!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Натягнув Свого лука й поставив мене, наче ціль для стріли́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'пустив стрі́ли до ни́рок моїх з Свого сагайдака́');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Для всього наро́ду свого я став посміхо́виськом, глумли́вою піснею їхньою цілий день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Наси́тив мене гіркото́ю, мене напоїв полино́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'І стер мені зу́би жорство́ю, до по́пелу кинув мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'і душа моя спо́кій згубила, забув я добро́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'І сказав я: Загублена сила моя, та моє сподіва́ння на Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 19, 'Згадай про біду́ мою й му́ку мою, про поли́н та отру́ту, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 20, 'душа моя згадує безпереста́нку про це, і гнеться в мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 21, 'Оце я нага́дую серцеві своєму, тому то я маю надію:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 22, 'Це милість Господня, що ми не поги́нули, бо не нокінчи́лось Його милосердя, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 23, 'нове́ воно кожного ра́нку, велика бо вірність Твоя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 24, 'Господь — це мій у́діл, — говорить душа моя, — тому́ я надію на Нього склада́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 25, 'Господь добрий для тих, хто наді́ю на Нього кладе́, для душі, що шукає Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 26, 'Добре, коли люди́на в мовча́нні надію кладе́ на спасі́ння Господнє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 27, 'Добре для мужа, як носить ярмо́ в своїй мо́лодості, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 28, 'нехай він самі́тно сидить і мовчить, як поклав Він на нього його́;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 29, 'хай закриє він по́рохом у́ста свої, може є ще надія;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 30, 'хай що́ку тому підставля́є, хто його б\'є, своєю ганьбою наси́чується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 31, 'Бо Господь не наві́ки ж покине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 32, 'Бо хоч Він і засму́тить кого, проте зми́лується за Своєю великою ми́лістю,—');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 33, 'бо не мучить Він з серця Свого́, і не засмучує лю́дських синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 34, 'Щоб топта́ти під своїми ногами всіх в\'я́знів землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 35, 'щоб перед обличчям Всевишнього право люди́ни зігнути,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 36, 'щоб гноби́ти люди́ну у справі судо́вій його́, — оцьо́го не має на оці Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 37, 'Хто то скаже — і станеться це, як Господь того не наказав?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 38, 'Хіба не виходить усе з уст Всевишнього, — зле та добре?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 39, 'Чого ж нарікає люди́на жива? Нехай ска́ржиться кожен на гріх свій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 40, 'Пошукаймо доріг своїх та досліді́мо, і верні́мось до Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 41, 'підіймі́мо своє серце та руки до Бога на небі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 42, 'Спроневі́рились ми й неслухня́ними стали, тому́ не пробачив Ти нам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 43, 'закрився Ти гнівом і гнав нас, убивав, не помилував,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 44, 'закрив Себе хмарою, щоб до Тебе молитва моя не дійшла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 45, 'Сміття́м та оги́дою нас Ти вчинив між наро́дами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 46, 'наші всі вороги́ пороззявля́ли на нас свого рота,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 47, 'страх та яма на нас поприхо́дили, руїна й погибіль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 48, 'Моє око сплива́є пото́ками во́дними через нещастя дочки́ мого люду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 49, 'Виливається око моє безупи́нно, нема бо пере́рви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 50, 'аж поки не згля́неться та не побачить Госпо́дь із небе́с, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 51, 'моє око вчиняє журбу́ для моєї душі через до́чок усіх мого міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 52, 'Ло́влячи, ло́влять мене, немов птаха, мої вороги безпричи́нно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 53, 'життя моє в яму замкну́ли вони, і камі́ннями кинули в мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 54, 'Пливуть мені во́ди на го́лову, я говорю́: „ Вже погу́блений я!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 55, 'Кликав я, Господи, Йме́ння Твоє́ із найглибшої ями,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 56, 'Ти чуєш мій голос, — не захо́вуй же ву́ха Свого від зо́йку мого́, від блага́ння мого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 57, 'Ти близьки́й того дня, коли кличу Тебе, Ти говориш: „Не бійся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 58, 'За душу мою Ти змагався, о Господи, життя моє викупив Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 59, 'Ти бачиш, о Господи, кривду мою, — розсуди ж Ти мій суд!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 60, 'Усю їхню по́мсту ти бачиш, всі за́думи їхні на мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 61, 'Ти чуєш, о Господи, їхні нару́ги, всі за́думи їхні на ме́не,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 62, 'мову повста́нців на мене та їхнє буркоті́ння на мене ввесь день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 63, 'Побач їхнє сиді́ння та їхнє встава́ння, — як за́вжди глумли́ва їхня пісня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 64, 'Заплати їм, о Господи, згідно з чином їхніх рук!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 65, 'Подай їм темно́ту на серце, прокля́ття Твоє нехай буде на них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 66, 'Своїм гнівом жени їх, і ви́губи їх з-під Господніх небе́с!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Як поте́мніло золото, як відмінилося щире те золото добре, як на ро́зі всіх вулиць камі́ння святе порозки́дане!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Кошто́вні сіонські сини, щирим золотом важені, як тепер ось за гли́няний по́суд полі́чені, за чин рук ганча́рських!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'На́віть шакали витя́гують пе́рса, годують своїх молодя́т, а до́ня народу мого жорсто́ка, мов струсі в пустині:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'язик сосунця́ до його піднебі́ння від спра́ги прилип. Хліба жадають собі немовля́та, — й немає ніко́го, хто б їм відломи́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Ті, що їли присма́ки, — на вулицях з голоду мліють; ті, що ви́плекані на пурпу́рі, — тепер смітники́ обійма́ють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'І більшою стала вина доньки люду мого́ за про́гріх Содо́му, що був переве́рнений вмить, — і не торка́лися руки до нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Її можновла́дці чистіші від снігу були́, біліші від молока, їхнє тіло червоне, мов пе́рли, їхній вигляд — сапфі́р, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'а тепер їхній вигляд чорніший за са́жу, не розпізнаю́ть їх на вулицях, їхня шкіра стягнулась на їхній кості́, зробилась сухою, як дерево.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Забитим мечем стало ліпше, ніж повби́ваним голодом, що гинуть проко́лені, за браком плоді́в польови́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Руки жінок милосе́рдних варили своїх діточо́к, які стали пожи́вою їм під час руйнува́ння дочки́ мого лю́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Закінчи́в Господь лю́тість Свою, вилив жар Свого гніву, — і запали́в на Сіоні огонь, і поже́р він осно́ви його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Не вірили зе́мні царі та всі ме́шканці ці́лого світу, що вві́йде противник та ворог до брам Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Усе ста́лося це за провини пророків його́, за неправду свяще́нства його, що кров праведників серед нього лили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'По вулицях бродять, немов ті сліпці́, поплямо́вані кров\'ю, так що люди не можуть діткну́тись до о́дягу їхнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, '„Уступі́ться, нечисті!“кричали до них, „уступі́ться, збо́чуйте, не дото́ркуйтеся!“І повтікали вони й мандрува́ли, і казали між лю́дьми: „Ме́шкати в нас більш не бу́дуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Господнє лице розпоро́шило їх, не ди́виться більше на них, — бо вони не зверта́ли уваги на обли́ччя священиків, до стари́х вони ласки не мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Уже прогляділи ми очі свої, даре́мно чека́вши на поміч собі, — на варті своїй ми чекали наро́ду, який нас не спас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Чатують вони наші кро́ки, щоб ходи́ти не могли ми по пло́щах своїх. Кінець наш набли́зився, спо́внилися наші дні, бо прийшов нам кінець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 19, 'Гноби́телі наші скоріші були за орлів піднебе́сних, — вони уганя́лись за нами по го́рах, на нас чатува́ли в пустині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 20, 'Попав в ями живу́щий наш Дух, Господній пома́занець, що ми говорили про ньо́го: „Ми бу́демо жити в тіні́ його серед наро́дів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 21, 'Веселися та тішся, о до́чко Едому, що сидиш в краю Уц, — також над тобою пере́йде злий ке́ліх, уп\'єшся й ого́лишся й ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 22, 'Скінчи́лася кара твоя, до́чко Сіону, — не буде Він більше тебе виганяти, — та твоє беззако́ння скарає Він, до́чко Едому, відкриє провини твої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Згадай, Господи, що́ з нами сталося, — зглянься й побач нашу га́ньбу, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'наша спа́дщина діста́лась чужим, доми наші — чужи́нцям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Поставали ми си́ротами: нема ба́тька, а ма́тінки наші — неначе ті вдо́ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Свою воду за срі́бло ми п\'ємо́, наші дро́ва за гроші оде́ржуємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'У поти́лицю нас поганяють, помучені ми, і споко́ю не маємо!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'До Єгипту й Асирії ру́ку витя́гуємо, — щоб наси́титись хлібом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Батьки наші грішили, але їх нема, — а ми двигаємо їхні прови́ни!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Раби запанува́ли над нами, і немає ніко́го, хто б ви́рятував з їхньої руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Нара́жуючи свою душу на меч у пустині, достаємо свій хліб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Шкіра наша, мов піч, — попали́лась з пекучого голоду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Жінок на Сіоні безче́стили, дівчат — по Юдейських містах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Князі їхньою рукою пові́шені, лиця стари́х не пошано́вані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Юнаки́ носять камінь млино́вий, а хлопці під ношею дров спотика́ються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Перестали сиді́ти старші́ в брамі, юнаки́ — свою пісню співати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'втіха нашого серця спини́лась, наш та́нець змінивсь на жало́бу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Спа́ла корона у нас з голови́, о горе, бо ми прогріши́лись, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'тому́ наше серце боля́ще, тому́ наші очі поте́мніли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'через го́ру Сіон, що спусто́шена, бро́дять лисиці по ній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Пробува́єш Ти, Господи, вічно, Твій престо́л з роду в рід:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Нащо ж на́с забуваєш навік, покидаєш на довгі дні нас?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Приверни́ нас до Себе, о Господи, — і ве́рнемось ми, віднови́ наші дні, як давні́ше було́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 22, 'Хіба́ Ти цілко́м нас відкинув, прогні́вавсь занадто на нас?');
