INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Книга родово́ду Ісуса Христа, Сина Давидового, Сина Авраамового:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Авраа́м породив Ісака, а Ісак породив Якова, а Яків породив Юду й братів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Юда ж породив Фаре́са та За́ру від Тама́ри. Фаре́с же породив Есро́ма, а Есро́м породив Арама.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'А Ара́м породив Амінадава, Амінада́в же породив Наассона, а Наассо́н породив Салмона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Салмо́н же породив Воо́за від Раха́ви, а Воо́з породив Йовіда від Рути, Йовід же породив Єссея.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'А Єссе́й породив царя Давида, Давид же породив Соломона від Урі́євої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Соломо́н же породив Ровоама, а Ровоа́м породив Авію, а Аві́я породив Асафа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Аса́ф же породив Йосафата, а Йосафа́т породив Йорама, Йора́м же породив Озію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Озі́я ж породив Йоатама, а Йоата́м породив Ахаза, Аха́з же породив Єзекію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'А Єзекі́я породив Манасію, Манасі́я ж породив Амоса, а Амо́с породив Йосію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Йосі́я ж породив Йояки́ма, Йояки́м породи́в Єхонію й братів його за вавилонського пересе́лення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'А по вавилонськім пересе́ленні Єхо́нія породив Салатіїля, а Салатіїль породив Зорова́веля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Зорова́вель же породив Авіюда, а Авію́д породив Еліякима, а Еліяки́м породив Азора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Азо́р же породив Садока, а Садо́к породив Ахіма, а Ахі́м породив Еліюда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Елію́д же породив Елеазара, а Елеаза́р породив Маттана, а Матта́н породив Якова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'А Яків породив Йо́сипа, мужа Марі́ї, що з неї родився Ісу́с, зва́ний Христо́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'А всіх поколінь від Авраама аж до Давида — чотирна́дцять поколінь, і від Давида аж до вавилонського пересе́лення — чотирна́дцять поколінь, і від вавилонського пересе́лення до Христа — поколінь чотирна́дцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Наро́дження ж Ісуса Христа сталося так. Коли Його матір Марію заручено з Йо́сипом, то перш, ніж зійшлися вони, ви́явилося, що вона має в утро́бі від Духа Святого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'А Йо́сип, муж її, бувши праведний, і не бажавши осла́вити її, хотів тайкома́ відпустити її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Коли ж він те поду́мав, ось з\'явивсь йому а́нгол Господній у сні, промовляючи: „Йо́сипе, сину Давидів, не бійся прийняти Марію, дружи́ну свою, бо зача́те в ній — то від Духа Святого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'І вона вродить Сина, ти ж даси Йому йме́ння Ісус, бо спасе Він людей Своїх від їхніх гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 22, 'А все оце сталось, щоб збуло́ся ска́зане пророком від Господа, який провіщає:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 23, '„Ось діва в утробі зачне́, і Сина породить, і назвуть Йому Йме́ння Еммануїл“, що в перекладі є: З нами Бог“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 24, 'Як прокинувся ж Йо́сип зо сну, то зробив, як звелів йому ангол Господній, — і прийняв він дружи́ну свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 25, 'І не знав він її, аж Сина свого первородженого вона породила, а він дав Йому йме́ння Ісу́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Коли ж народився Ісус у Вифлеємі Юдейськім, за днів царя І́рода, то ось мудреці прибули́ до Єрусалиму зо сходу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'і питали: „Де́ наро́джений Цар Юдейський? Бо на сході ми бачили зо́рю Його́, і прибули́ поклонитись Йому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'І, як зачув це цар І́род, занепоко́ївся, і з ним увесь Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'І, зібравши всіх первосвящеників і книжників лю́дських, він випитував у них, де́ має Христос народитись?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Вони ж відказали йому́: „У Вифлеємі Юдейськім, бо в пророка написано так:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, '„І ти, Вифлеє́ме, земле Юдина, не менший нічим між осадами Юдиними, бо з тебе з\'я́виться Вождь, що буде Ві́н па́сти наро́д Мій ізраїльський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Тоді Ірод покликав таємно отих мудреців, і докладно випи́тував їх про час, коли з\'явилась зоря́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'І він відіслав їх до Вифлеєму, говорячи: „Ідіть, і пильно розвідайтеся про Дитя́тко; а як зна́йдете, сповістіть мене, щоб і я міг піти й поклонитись Йому́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Вони ж царя вислухали й відійшли. І ось зоря́, що на сході вони її бачили, ішла перед ними, аж прийшла й стала зве́рху, де Дитя́тко було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'А бачивши зо́рю, вони надзвичайно зраділи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'І, ввійшовши до дому, знайшли там Дитятко з Марією, Його матір\'ю. І вони впали ницьма, і вклонились Йому́. І, відчини́вши скарбниці свої, підне́сли Йому свої да́ри: золото, ладан та смирну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'А вві сні остережені, щоб не верта́тись до Ірода, відійшли вони іншим шляхо́м до своєї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Як вони ж відійшли, ось ангол Господній з\'явивсь у сні Йо́сипові та й сказав: „Уставай, візьми Дитя́тко та матір Його, і втікай до Єгипту, і там зоставайся, аж поки скажу́ тобі, бо Дитя́тка шукатиме Ірод, щоб Його́ погубити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'І він устав, узяв Дитятко та матір Його вночі, та й пішов до Єгипту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'І він там зоставався аж до смерти Іродової, щоб збуло́ся сказане від Господа пророком, який провіщає: „Із Єгипту покликав Я Сина Свого́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'Спостеріг тоді Ірод, що ті мудреці насміялися з нього, та й розгнівався дуже, і послав повбивати в Вифлеємі й по всій тій околиці всіх дітей від двох років і менше, за ча́сом, що його в мудреців він був ви́питав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, 'Тоді спра́вдилось те, що сказав Єремі́я пророк, промовляючи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 18, '„Чути голос у Рамі, плач і рида́ння та голосі́ння велике: Рахиль плаче за ді́тьми своїми, і не дається розважити себе, бо нема їх “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 19, 'Коли ж Ірод умер, ось ангол Господній з\'явився в Єгипті вві сні Йо́сипові, та й промовив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 20, '„Уставай, візьми Дитя́тко та матір Його́, та йди в землю Ізраїлеву, бо вимерли ті, хто шука́в душу Дитини“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 21, 'І він устав, узяв Дитя́тко та матір Його́, і прийшов у землю Ізраїлеву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 22, 'Та прочувши, що царю́є в Юдеї Архела́й, — замість Ірода, батька свого, — побоявся піти туди він. А вві сні остере́жений, відійшов до країв галілейських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 23, 'А прибувши, оселився у місті, на ім\'я́ Назаре́т, щоб збулося пророками сказане, що Він Назаряни́н буде зва́ний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Тими ж днями прихо́дить Іван Христитель, і проповідує в пустині юдейській,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'та й каже: „Покайтесь, бо набли́зилось Царство Небесне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Бо він той, що про нього сказав Ісая пророк, промовляючи: „Голос того, хто кличе: В пустині готуйте дорогу для Господа, рівняйте стежки Йому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Сам же Іван мав одежу собі з верблю́жого во́лосу, і пояс ремінний на сте́гнах своїх; а пожива для нього була́ сарана́ та мед польови́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Тоді до нього вихо́див Єрусалим, і вся Юдея, і вся йорда́нська око́лиця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'і в річці Йорда́ні христились від нього, і визнавали гріхи свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Як побачив же він багатьох фарисе́їв та саддуке́їв що приходять на хрищення, то промовив до них: „Роде зміїний, — хто вас надоуми́в утікати від гніву майбутнього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Отож, — учиніть гідний плід покая́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'І не ду́майте говорити в собі: „Ми маємо отця Авраама“. Кажу́ бо я вам, що Бог може піднести дітей Авраамові з цього камі́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Бо вже до корі́ння дерев і сокира прикла́дена: кожне ж дерево, що доброго пло́ду не родить, буде зрубане та й в огонь буде вкинене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Я хрищу́ вас водою на покая́ння, але Той, Хто йде по мені, поту́жніший від мене: я недосто́йний понести взуття́ Йому! Він христитиме вас Святим Духом й огнем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'У руці Своїй має Він ві́ячку, і перечистить Свій тік: пшеницю Свою Він збере до засі́ків, а полову попа́лить ув огні невгаси́мім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Тоді прибуває Ісус із Галілеї над Йорда́н до Івана, щоб христитись від ньо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Але перешкоджа́в він Йому й говорив: „Я повинен христитись від Тебе, і чи Тобі йти до мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'А Ісус відповів і сказав йому: „Допусти це тепер, бо так годи́ться нам ви́повнити усю праведність“. Тоді допустив він Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'І охристившись, Ісус зараз вийшов із води. І ось небо розкрилось, і побачив Іван Духа Божого, що спускався, як голуб, і схо́див на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'І ось голос почувся із неба: „Це Син Мій Улю́блений, що Його Я вподо́бав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Потому Ісус був пове́дений Духом у пустиню, щоб диявол Його спокуша́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'І по́стив Він сорок день і сорок ноче́й, а вкінці зголодні́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'І ось приступив до Нього споку́сник, і сказав: „Коли Ти Син Божий, скажи, щоб камі́ння це стало хліба́ми!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'А Він відповів і промовив: „Написано: Не хлібом самим буде жити люди́на, але кожним словом, що походить із уст Божих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Тоді забирає диявол Його в святе місто, і ставить Його на нарі́жника храму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'та й каже Йому: „Коли Ти Син Божий, то кинься додолу, бо ж написано: „Він накаже про Тебе Своїм Ангола́м, і вони на руках понесу́ть Тебе, щоб об камінь коли не спіткнув Ти Своєї ноги́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Ісус відказав йому: „Ще написано: Не спокушуй Господа Бога свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Знов диявол бере Його на височе́зную го́ру, і показує Йому всі царства на світі та їхню славу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'та й каже до Нього: „Це все Тобі дам, якщо впаде́ш і мені Ти покло́нишся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Тоді каже до нього Ісус: „Відійди, сатано! Бо ж написано: Господеві Богові своєму вклоняйся, і служи Одно́му Йому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Тоді позоставив диявол Його. І ось анголи́ приступили, і служили Йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Як довідавсь Ісус, що Івана ув\'я́знено, перейшов у Галілею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'І, покинувши Він Назаре́та, прийшов й оселився в Капернау́мі примо́рськім, на границі країн Завуло́нової й Нефтали́мової,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'щоб спра́вдилось те, що сказав Іса́я пророк, промовляючи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, '„Завуло́нова зе́мле, і Нефтали́мова зе́мле, за Йорда́ном при мо́рській дорозі, Галіле́є поганська!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Наро́д, що в темно́ті сидів, світло велике побачив, а тим, хто сидів у країні смертельної тіні, засяяло світло“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'Із того ча́су Ісус розпочав проповідувати й промовляти: „Покайтеся, бо набли́зилось Царство Небесне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'Як прохо́див же Він поблизу́ Галілейського моря, то побачив двох братів: Си́мона, що зветься Петром, та Андрія, його брата, що не́вода в море закида́ли, — бо рибалки були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 19, 'І Він каже до них: „Ідіть за Мною, — Я зроблю́ вас ловця́ми людей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 20, 'І вони зараз покинули сі́ті, та й пішли вслід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 21, 'І, далі пішовши звідти, Він побачив двох інших братів, — Зеведе́євого сина Якова та Івана, його брата, із Зеведе́єм, їхнім ба́тьком, що ла́годили свого не́вода в чо́вні, — і покликав Він їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 22, 'Вони зараз залиши́ли чо́вна та батька свого́, — та й пішли вслід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 23, 'І ходив Він по всій Галілеї, по їхніх синаго́гах навчаючи, та Єва́нгелію Царства проповідуючи, і вздоро́влюючи всяку неду́гу, і всяку неміч між людьми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 24, 'А чутка про Нього пішла по всій Си́рії. І водили до Нього недужих усіх, хто терпів на різні хвороби та муки, і біснуватих, і сновид, і розсла́блених, — і Він їх уздоровля́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 25, 'І багато людей ішло за Ним і з Галілеї, і з Десятимістя, і з Єрусалиму, і з Юдеї, і з Зайорда́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'І, побачивши на́товп, Він вийшов на го́ру. А як сів, підійшли Його у́чні до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'І, відкривши уста́ Свої, Він навчати їх став, промовляючи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, '„Блаже́нні вбогі духом, бо їхнє Царство Небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Блаженні засму́чені, бо вони будуть утішені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Блаженні ла́гідні, бо землю вспадку́ють вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Блаженні голодні та спра́гнені праведности, бо вони нагодо́вані будуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Блаженні милости́ві, бо помилувані вони будуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Блаженні чисті́ серцем, бо вони будуть бачити Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Блаженні миротво́рці, бо вони синами Божими стануть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Блаженні ви́гнані за праведність, бо їхнє Ца́рство Небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Блаженні ви, як ганьби́ти та гнати вас бу́дуть, і будуть облу́дно на вас нагово́рювати всяке слово лихе ради Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Радійте та веселі́ться, — нагорода бо ваша велика на небеса́х! Бо так гнали й пророків, що були перед вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Ви — сіль землі. Коли сіль ізвітрі́є, то чим насолити її? Не придасться вона вже ніна́що, хіба щоб надвір була висипана та потоптана людьми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Ви світло для світу. Не може сховатися місто, що стоїть на верхови́ні гори.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'І не запалюють світла, щоб поставити його під посу́дину, але на світи́льник, — і світить воно всім у домі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Отак ваше світло нехай світить перед людьми́, щоб вони бачили ваші добрі діла, та прославляли Отця вашого, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Не подумайте, ніби Я руйнувати Закон чи Пророків прийшов, — Я не руйнувати прийшов, але ви́конати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Попра́вді ж кажу́ вам: доки небо й земля не мине́ться, — ані йота єдина, ані жоден значок із Зако́ну не мине́ться, аж поки не збудеться все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Хто ж порушить одну з найменших цих заповідей, та й людей так навчи́ть, той буде найменшим у Царстві Небеснім; а хто виконає та й навчи́ть, той стане великим у Царстві Небеснім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Кажу́ бо Я вам: коли праведність ваша не буде рясніша, як книжників та фарисеїв, то не вві́йдете в Царство Небесне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ви чули, що було́ стародавнім наказане: „Не вбивай, а хто вб\'є, підпадає він су́дові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'А Я вам кажу́, що кожен, хто гнівається на брата свого, підпадає вже судові. А хто скаже на брата свого: „рака́“, підпадає верховному су́дові, а хто скаже „дурний“, підпадає геєнні огне́нній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Тому́, коли принесеш ти до же́ртівника свого да́ра, та тут ізгадаєш, що брат твій щось має на тебе, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'залиши́ отут да́ра свого перед же́ртівником, і піди, примирись перше з братом своїм, — і тоді поверта́йся, і принось свого да́ра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Зо своїм супроти́вником швидко мирися, доки з ним на дорозі ще ти, щоб тебе супроти́вник судді́ не віддав, а суддя́ щоб прислужникові тебе не передав, і щоб тебе до в\'язни́ці не вкинули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 26, 'Поправді кажу́ тобі: Не вийдеш ізвідти, поки не віддаси́ ти й останнього ше́ляга!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 27, 'Ви чули, що сказано: „Не чини пере́любу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 28, 'А Я вам кажу́, що кожен, хто на жінку поди́виться із пожадли́вістю, той уже вчинив із нею пере́люб у серці своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 29, 'Коли праве око твоє спокуша́є тебе, — його ви́бери, і кинь від себе: бо краще тобі, щоб загинув один із твоїх членів, аніж до геєнни все тіло твоє було вки́нене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 30, 'І як прави́ця твоя спокуша́є тебе, — відітни́ її й кинь від себе: бо краще тобі, щоб загинув один із твоїх членів, аніж до геєнни все тіло твоє було вки́нене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 31, 'Також сказано: „Хто дружи́ну свою відпускає, нехай дасть їй листа розводо́вого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 32, 'А Я вам кажу́, що кожен, хто пускає дружи́ну свою, крім провини розпу́сти, той доводить її до пере́любу. І хто з відпущеною побере́ться, той чинить пере́люб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 33, 'Ще ви чули, що було́ стародавнім наказане: „Не клянись неправдиво“, але „вико́нуй клятви свої перед Господом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 34, 'А Я вам кажу́ не клясти́ся зовсі́м: ані небом, бо воно престол Божий;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 35, 'ні землею, бо підні́жок для ніг Його це; ані Єрусалимом, бо він місто Царя Великого;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 36, 'не клянись головою своєю́, — бо навіть однієї волоси́нки ти не можеш учинити білою чи чорною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 37, 'Ваше ж слово хай бу́де: „так-так“, „ні-ні“. А що більше над це, то те від лукавого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 38, 'Ви чули, що сказано: „Око за око, і зуб за зуба“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 39, 'А Я вам кажу́ не проти́витись злому. І коли вдарить тебе хто у праву щоку́ твою, — підстав йому й другу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 40, 'А хто хоче тебе позива́ти й забрати сорочку твою, — віддай і плаща йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 41, 'А хто силувати тебе бу́де відбу́ти подорожнє на милю одну, — іди з ним навіть дві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 42, 'Хто просить у тебе — то дай, а хто хоче пози́чити в тебе — не відве́ртайсь від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 43, 'Ви чули, що сказано: „Люби свого ближнього, і нена́видь свого ворога“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 44, 'А Я вам кажу́: Любіть ворогів своїх, благословляйте тих, хто вас проклинає, творіть добро тим, хто нена́видить вас, і моліться за тих, хто вас переслідує,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 45, 'щоб вам бути синами Отця вашого, що на небі, що наказує схо́дитн сонцю Своєму над злими й над добрими, і дощ посилає на праведних і на неправедних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 46, 'Коли бо ви любите тих, хто вас любить, то яку нагороду ви маєте? Хіба не те саме й ми́тники роблять?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 47, 'І коли ви вітаєте тільки братів своїх, то що́ ж особливого робите? Чи й пога́ни не чинять отак?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 48, 'Отож, будьте досконалі, як досконалий Отець ваш Небесний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Стережіться виставляти свою ми́лостиню перед людьми́, щоб бачили вас; а як ні, то не матимете нагороди від Отця вашого, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Отож, коли чиниш ти ми́лостиню, не сурми́ перед себе, як то роблять оті лицеміри по синагогах та вулицях, щоб хвалили їх люди. Поправді кажу́ вам: вони мають уже нагороду свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'А як ти чиниш ми́лостиню, — хай не знатиме ліва рука твоя, що́ робить прави́ця твоя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'щоб таємна була твоя милостиня, а Отець твій, що бачить таємне, віддасть тобі явно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'А як мо́литеся, то не будьте, як ті лицеміри, що люблять ставати й молитися по синагогах та на перехре́стях, щоб їх бачили люди. Поправді кажу́ вам: вони мають уже нагороду свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'А ти, коли мо́лишся, „увійди до своєї комі́рчини, зачини свої двері, і помолися“Отцеві своєму, що в таїні́; а Отець твій, що бачить таємне, віддасть тобі явно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'А як молитеся, не прока́зуйте за́йвого, як ті погани, — бо ду́мають, ніби вони бу́дуть ви́слухані за своє велемо́вство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Отож, не вподобля́йтеся їм, бо знає Отець ваш, чого потребу́єте, ще раніше за ваше проха́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Ви ж моліться отак: „Отче наш, що на небі! Нехай святиться Ім\'я́ Твоє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'нехай при́йде Царство Твоє, нехай буде воля Твоя, як на небі, так і на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Хліба нашого щоденного дай нам сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'І прости нам довги́ наші, як і ми прощаємо винуватцям нашим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'I не введи нас у випробо́вування, але визволи нас від лукавого. Бо Твоє є царство, і сила, і слава навіки. Амі́нь “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Бо як лю́дям ви про́стите про́гріхи їхні, то про́стить і вам ваш Небесний Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'А коли ви не бу́дете лю́дям прощати, то й Отець ваш не простить вам про́гріхів ваших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'А як по́стите, то не будьте сумні́, як оті лицеміри: вони бо зміняють обличчя свої, щоб бачили люди, що по́стять вони. Поправді кажу́ вам: вони мають уже нагороду свою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'А ти, коли по́стиш, намасти́ свою голову, і лице своє вмий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'щоб ти по́сту свого не виявив лю́дям, а Отцеві своєму, що в таїні́; і Отець твій, що бачить таємне, віддасть тобі явно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Не складайте ска́рбів собі на землі, де нищить їх міль та іржа, і де злоді́ї підко́пуються й викрадають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Складайте ж собі ска́рби на небі, де ні міль, ні іржа їх не нищить, і де злодії до них не підко́пуються та не кра́дуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Бо де скарб твій, — там бу́де й серце твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 22, 'Око — то світи́льник для тіла. Тож як око твоє буде здорове, то й усе тіло твоє буде світле.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 23, 'А коли б твоє око лихе було, то й усе тіло твоє буде темне. Отож, коли світло, що в тобі, є те́мрява, — то яка ж то велика та те́мрява!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 24, 'Ніхто двом панам служити не може, — бо або одно́го знена́видить, а дру́гого буде любити, або буде трима́тись одно́го, а другого зне́хтує. Не можете Богові служити й мамо́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 25, 'Через те вам кажу́: Не журіться про життя́ своє́ — що́ будете їсти та що́ будете пити, ні про тіло своє, — у що́ зодягне́теся. Чи ж не більше від їжі життя́, а від одягу тіло?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 26, 'Погляньте на птахі́в небесних, що не сіють, не жнуть, не збирають у клуні, та проте ваш Небесний Отець їх годує. Чи ж ви не багато вартніші за них?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 27, 'Хто ж із вас, коли жу́риться, зможе дода́ти до зро́сту свого бодай ліктя одно́го?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 28, 'І про одяг чого ви клопочетесь? Погляньте на польові́ ліле́ї, як зроста́ють вони, — не працюють, ані не пряду́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 29, 'А Я вам кажу́, що й сам Соломо́н у всій славі своїй не вдягався отак, як одна з них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 30, 'І коли польову́ ту траву, що сьогодні ось є, а взавтра до пе́чі вкидається, Бог отак зодягає, — скільки ж краще зодягне Він вас, маловірні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 31, 'Отож, не журіться, кажучи: Що́ ми будемо їсти, чи: Що́ будемо пити, або: У що́ ми зодя́гнемось?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 32, 'Бож усьо́го того́ погани шука́ють; але знає Отець ваш Небесний, що всього того вам потрібно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 33, 'Шукайте ж найперш Царства Божого й праведности Його́, — а все це́ вам додасться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 34, 'Отож, не журіться про за́втрашній день, — бо завтра за себе само́ поклопо́четься. Кожний день має до́сить своєї турбо́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'Не судіть, щоб і вас не судили;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'бо яким судо́м судити бу́дете, таким же осу́дять і вас, і якою мірою будете міряти, такою відмі́ряють вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'І чого́ в оці брата свого́ ти за́скалку бачиш, коло́ди ж у вла́сному оці не чуєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'Або як ти скажеш до брата свого́: „Давай вийму я за́скалку з ока твого́“, коли он колода у вла́сному оці?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'Лицеміре, — вийми перше коло́ду із вла́сного ока, а по́тім побачиш, я́к вийняти за́скалку з ока брата твого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'Не давайте святого псам, і не розсипайте пе́рел своїх перед свиньми́, щоб вони не потопта́ли їх ногами своїми, і, обернувшись, щоб не розшматува́ли й вас...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'Просіть — і бу́де вам да́но, шукайте — і зна́йдете, стукайте — і відчинять вам;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'бо кожен, хто просить — оде́ржує, хто шукає — знахо́дить, а хто стукає — відчинять йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'Чи ж то серед вас є люди́на, що подасть своєму синові каменя, коли хліба проситиме він?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'Або коли риби проситиме, то подасть йому га́дину?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Тож як ви, бувши злі, потра́пите добрі дари́ своїм дітям давати, — скільки ж більше Отець ваш Небесний подасть добра́ тим, хто проситиме в Нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Тож усе, чого тільки бажаєте, щоб чинили вам люди, те саме чиніть їм і ви. Бо в цьому Зако́н і Пророки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'Увіходьте тісни́ми ворітьми, бо просто́рі воро́та й широка дорога, що веде до погибелі, — і нею багато-хто ходять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'Бо тісні́ ті ворота, і вузька́ та дорога, що веде до життя́, — і мало таких, що знахо́дять її!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'Стережі́ться фальшиви́х пророків, що приходять до вас ув одежі овечій, а всере́дині — хижі вовки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'По їхніх плода́х ви пізнаєте їх. Бо хіба ж виноград на терни́ні збирають, або фіґи — із будякі́в?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 17, 'Так ото родить добрі плоди́ кожне дерево добре, а дерево зле плоди родить лихі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 18, 'Не може роди́ть добре дерево пло́ду лихого, ані дерево зле плодів добрих родити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 19, 'Усяке ж дерево, що доброго пло́ду не родить, — зру́бується та в огонь укидається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 20, 'Ото ж бо, — по їхніх плода́х ви пізна́єте їх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 21, 'Не кожен, хто каже до Ме́не: „Господи, Господи!“увійде в Царство Небесне, але той, хто виконує волю Мого Отця, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 22, 'Багато-хто скажуть Мені того дня: „Господи, Господи, хіба ми не Ім\'я́м Твоїм пророкува́ли, хіба не Ім\'я́м Твоїм де́монів ми виганяли, або не Ім\'я́м Твоїм чуда великі творили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 23, 'І їм оголошу́ Я тоді: „Я ніко́ли не знав вас. Відійдіть від Мене, хто чинить беззаконня!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 24, 'Отож, кожен, хто слухає цих Моїх слів і виконує їх, подібний до чоловіка розумного, що свій дім збудував на камені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 25, 'І ли́нула злива, і розлили́ся річки́, і буря зняла́ся, і на дім отой кинулась, — та не впав, бо на камені був він засно́ваний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 26, 'А кожен, хто слухає цих Моїх слів, та їх не виконує, — подібний до чоловіка того необа́чного, що свій дім збудував на піску́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 27, 'І ли́нула злива, і розлили́ся річки́, і буря зняла́ся й на дім отой кинулась, — і він упав. І велика була та руїна його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 28, 'І ото, як Ісус закінчи́в ці слова, то наро́д дивувався з науки Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 29, 'Бо навчав Він їх, як можновла́дний, а не як ті книжники їхні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'А коли Він зійшов із гори, услід за Ним ішов на́товп великий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'І ось підійшов прокаже́ний, уклонився Йому та й сказав: „Коли, Господи, хочеш, — Ти можеш очистити мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'А Ісус простяг руку, і доторкнувся до нього, говорячи: „Хо́чу, — будь чистий!“І тієї хвилини очистився той від своєї прокази.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'І гово́рить до нього Ісус: „Гляди, — не розповіда́й ніко́му. Але йди, покажися священикові, та дар принеси́, якого Мойсей заповів, їм на свідо́цтво “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'А коли Він до Капернау́му ввійшов, то до Нього набли́зився сотник, та й благати зачав Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'кажучи: „Господи, мій слуга лежить удома розсла́блений, і тяжко страждає“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'Він говорить йому: „Я прийду́ й уздоро́влю його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'А сотник Йому відповів: „Недостойний я, Господи, щоб зайшов Ти під стрі́ху мою. Та промов тільки слово, — і ви́дужає мій слуга!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Бо й я — люди́на підвла́дна, і воякі́в під собою я маю; і одному кажу: піди — то йде він, а тому: прийди́ — і приходить, або рабо́ві своєму: зроби те — і він зро́бить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Почувши таке, Ісус здивувався, і промовив до тих, хто йшов услід за Ним: „Поправді кажу вам: навіть серед Ізраїля Я не знайшо́в був такої великої віри!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'Кажу́ ж вам, що багато-хто при́йдуть від сходу та за́ходу, і засядуть у Царстві Небеснім із Авраамом, Ісаком та Яковом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Сини ж Царства — повки́дані бу́дуть до те́мряви зо́внішньої — буде там плач і скре́гіт зубів“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'I сказав Ісус сотникові: „Іди, і як повірив ти, нехай так тобі й станеться!“І тієї ж години одужав слуга його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'Як прийшов же Ісус до Петрового дому, то побачив тещу його, що лежала в гарячці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'І Він доторкнувся руки її, — і гарячка покинула ту... І встала вона, та й Йому прислуго́вувала!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'А коли настав вечір, привели́ багатьох біснуватих до Нього, — і Він словом Своїм вигнав ду́хів, а недужих усіх уздорови́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'щоб спра́вдилося, що сказав був Ісая пророк, промовляючи: „Він узяв наші немочі, і неду́ги поніс“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'А як угледів Ісус навко́ло Себе багато наро́ду, наказав перепли́нути на то́й бік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'І приступив один книжник та й до Нього сказав: „Учителю, я піду́ за Тобою, хоч би куди ти пішов!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'Промовляє до нього Ісус: „Мають но́ри лисиці, а гні́зда небесні пташки́, — Син же Лю́дський не має де й голови́ прихили́ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'А і́нший із у́чнів промовив до Ньо́го: „Дозволь мені, Господи, перше піти та ба́тька свого похова́ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'А Ісус йому каже: „Іди за Мною, і зостав мертвим ховати мерців своїх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'І коли Він до чо́вна вступив, за Ним увійшли Його у́чні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'І ось буря велика зірва́лась на морі, аж чо́вен зачав залива́тися хви́лями. А Він спав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 25, 'І кинулись учні, і збудили Його та й благали: Рятуй, Господи, — ги́немо!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 26, 'А Він відповів їм: „Чого полохливі ви, маловірні?“Тоді встав, заказав бурі й морю, — і тиша велика настала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 27, 'А народ дивувався й казав: „Хто ж це такий, що ві́три та море слухня́ні Йому́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 28, 'І, як прибув Він на то́й бік, до землі Гадари́нської, перестріли Його два біснуваті, що вийшли з могильних пече́р, дуже люті, так що ніхто не міг перехо́дити тією дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 29, 'І ось, вони стали кричати, говорячи: „Що́ Тобі, Сину Божий, до нас? Прийшов Ти сюди передчасно нас мучити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 30, 'А опо́даль від них пасся гурт великий свине́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 31, 'І просилися де́мони, кажучи: „Коли виженеш нас, то пошли нас у той гурт свине́й“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 32, 'А Він відповів їм: „Ідіть“. І вийшли вони, і пішли в гурт свиней. І ось кинувся з кручі до моря ввесь гурт, — і потопи́вся в воді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 33, 'Пастухи ж повтікали; а коли прибули́ вони в місто, то про все розповіли́, і про біснуватих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 34, 'І ось, усе місто вийшло назу́стріч Ісусові. Як Його ж угледіли, то стали благати, щоб пішов Собі з їхнього кра́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'І, сівши до чо́вна, Він перепли́нув, і до міста Свого прибув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'І ото, прине́сли до Нього розсла́бленого, що на ложі лежав. І, як побачив Ісус їхню віру, сказав розсла́бленому: „Будь бадьо́рий, сину! Прощаються тобі гріхи твої́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'І ось, дехто із книжників стали казати про себе: „Він богозневажає“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'Ісус же думки́ їхні знав і сказав: „Чого ду́маєте ви лукаве в серцях своїх?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Що́ легше, — сказати: „Прощаються тобі гріхи“, чи сказати: „Уставай та й ходи“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Але щоб ви знали, що прощати гріхи на землі має вла́ду Син Лю́дський, — тож каже Вій розсла́бленому: „Уставай, візьми ложе своє, та й іди у свій дім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'Той устав і пішов у свій дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'А на́товп, побачивши це, налякався, — і славив Бога, що лю́дям Він дав таку вла́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'А коли Ісус звідти прохо́див, побачив чоловіка, на йме́ння Матвія, що сидів на митниці, та й каже йому: „Іди за Мною!“Той устав, і пішов услід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'І сталось, як Ісус сиді́в при столі́ у домі, ось зійшлося багато митників і грішників, і вони посідали з Ним та з Його у́чнями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'Як побачили ж те фарисеї, то сказали до учнів Його: „Чому́ то Вчитель ваш їсть із ми́тниками та із грішниками?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'А Він це почув та й сказав: „Лікаря не потребу́ють здорові, а слабі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'Ідіть же, і навчіться, що́ то є: „Милости хо́чу, а не жертви“. Бо Я не прийшов кликати праведних, але грішників до покая́ння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'Тоді приступили до Нього Іванові у́чні та й кажуть: „Чому́ по́стимо ми й фарисеї, а учні Твої не по́стять?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Ісус же промовив до них: „Хіба можуть гості весільні сумувати, поки з ними ще є молодий? Але при́йдуть ті дні, коли заберуть молодого від них, — тоді й по́стити бу́дуть вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 16, 'До одежі ж старої ніхто не вставляє латки з сукна сирово́го, — бо збіжи́ться воно, і дірка стане ще гірша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 17, 'І не вливають вина молодого в старі бурдюки́, а то бурдюки́ розірву́ться, і вино розіллє́ться, і бурдюки́ пропадуть; а вливають вино молоде до нових бурдюкі́в, — і одне й друге збере́жене бу́де“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 18, 'Коли Він говорив це до них, підійшов ось один із старши́х, уклонився Йому та й говорить: „Дочка моя хвилі цієї померла. Та прийди, поклади Свою руку на неї, — і вона оживе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 19, 'I підвівся Ісус, і пішов услід за ним, також у́чні Його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 20, 'І ото одна жінка, що дванадцять літ хворою на кровоте́чу була́, приступила зза́ду, і доторкнулась до кра́ю одежі Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 21, 'Бо вона говорила про себе: „Коли хоч доторкнуся одежі Його, то одужаю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 22, 'Ісус, обернувшись, побачив її та й сказав: „Будь бадьо́рою, до́чко, — твоя віра спасла тебе!“І одужала жінка з тієї години.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 23, 'А Ісус, як прибув до госпо́ди старшо́го, і вздрів дударів та юрбу́ голосі́льників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 24, 'то сказав: „Відійдіть, бо не вмерло дівча́, але спить“. І насміхалися з Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 25, 'А коли наро́д випроваджено, Він увійшов, узяв за руку її, — і дівчина вста́ла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 26, 'І вістка про це розійшлася по всій тій країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 27, 'Коли ж Ісус звідти вертався, ішли за Ним два сліпці, що кричали й казали: „Змилуйсь над нами, Сину Давидів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 28, 'І коли Він додому прийшов, приступили до Нього сліпці. А Ісус до них каже: „Чи ж вірите ви, що Я мо́жу вчинити оце?“Говорять до Нього вони: „Так, Господи“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 29, 'Тоді Він доторкнувся до їхніх оче́й і сказав: „Нехай станеться вам згідно з вашою вірою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 30, 'І очі відкрилися їм. А Ісус наказав їм суво́ро, гово́рячи: „Глядіть, — щоб ніхто не дові́давсь про це!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 31, 'А вони відійшли, та й розголосили про Нього по всій тій країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 32, 'Коли ж ті вихо́дили, то ось привели́ до Нього чоловіка німого, що був біснуватий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 33, 'І як де́мон був вигнаний, німий заговорив. І дивувався наро́д і казав: „Ніко́ли таке не траплялося серед Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 34, 'Фарисеї ж казали: „Виганяє Він де́монів силою князя де́монів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 35, 'І обхо́див Ісус всі міста́ та оселі, навчаючи в їхніх синагогах, та Єва́нгелію Царства проповідуючи, і вздоро́влюючи всяку неду́гу та не́міч усяку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 36, 'А як бачив людей, змилосе́рджувався Він над ними, бо були вони змучені та розпоро́шені, „як ті вівці, що не мають пастуха“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 37, 'Тоді Він казав Своїм учням: „Жни́во справді велике, та робі́тників мало;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 38, 'тож благайте Госпо́даря жни́ва, щоб на жни́во Своє Він робі́тників вислав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'І закли́кав Він дванадцятьо́х Своїх у́чнів, і вла́ду їм дав над нечистими ду́хами, щоб їх виганяли вони, і щоб уздоровля́ли всіляку неду́гу та неміч всіляку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'А ймення апо́столів дванадцятьо́х отакі: перший Си́мон, що Петро́м прозивається, і Андрій, брат його; Яків, син Зеведе́їв, та Іван, брат його;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'Пилип і Вартоломе́й, Хома́ й ми́тник Матвій; Яків, син Алфе́їв, і Таде́й;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Си́мон Кананіт, та Юда Іскаріо́тський, що й видав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'Цих Дванадцятьо́х Ісус вислав, і їм наказав, промовляючи: „На путь до поган не ходіть, і до самаря́нського міста не входьте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'але йдіть радніш до овечок загинулих дому Ізра́їлевого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'А ходячи, проповідуйте та говоріть, що набли́зилось Царство Небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'Уздоровляйте недужих, воскрешайте померлих, очищайте прокаже́них, виганяйте де́монів. Ви да́рмо дістали, дармо й давайте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Не беріть ані золота, ані срі́бла, ані мідякі́в до своїх поясів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'ані торби в дорогу, ані двох одеж, ні санда́ль, ані палиці. Бо вартий робі́тник своєї поживи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'А як за́йдете в місто якесь чи в село, то розві́дайте, хто́ там достойний, — і там перебудьте, аж поки не ви́йдете.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'А входячи в дім, вітайте його, промовляючи: „Мир дому цьому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'І коли буде достойний той дім, — нехай зі́йде на нього ваш мир; а як недостойний він буде, то мир ваш нехай до вас ве́рнеться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'А як хто вас не прийме, і ваших слів не послу́хає, то, вихо́дячи з дому чи з міста того́, обтрусіть порох із ніг своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Поправді кажу́ вам: легше буде країні содомській й гоморській дня судного, аніж місту тому́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'Оце посилаю Я вас, як овець між вовки́. Будьте ж мудрі, як змі́ї, і невинні, як голу́бки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Стережіться ж людей, бо вони на суди́ видаватимуть вас, та по синагогах своїх бичува́ти вас бу́дуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'І до правителів та до царів поведуть вас за Мене, на сві́дчення їм і пога́нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 19, 'А коли видава́тимуть вас, не журі́ться, я́к або що́ говорити: тієї години буде вам да́не, що́ маєте ви говорити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 20, 'бо не ви промовля́тимете, але Дух Отця вашого в вас промовля́тиме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 21, 'І видасть на смерть брата брат, а батько — дитину. І „діти повстануть супроти батьків“, і їх повбивають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 22, 'І за Ім\'я́ Моє будуть усі вас нена́видіти. А хто ви́терпить аж до кінця, той буде спасе́ний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 23, 'А коли будуть вас переслідувати в однім місті, утікайте до іншого. Поправді кажу́ вам, — не всти́гнете ви обійти́ міст Ізраїлевих, як при́йде Син Лю́дський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 24, 'Учень не більший за вчителя, а раб — понад пана свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 25, 'Дово́лі для учня, коли буде він, як учитель його, а раб — як госпо́дар його. Коли Вельзеву́лом назвали господаря дому, — скільки ж більше назвуть так домашніх його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 26, 'Але́ не лякайтеся їх. Немає нічого захованого, що воно не відкриється, ані потаємного, що не ви́явиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 27, 'Що́ кажу Я вам по́темки, — говоріть те при світлі, що ж на вухо ви чуєте — проповідуйте те на даха́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 28, 'І не лякайтеся тих, хто тіло вбиває, а душі́ вбити не може; але бійтеся більше того, хто може й душу, і тіло вам занапасти́ти в геєнні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 29, 'Чи не два горобці продаються за гріш? А на землю із них ні один не впаде́ без волі Отця вашого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 30, 'А вам і волосся все на голові пораховано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 31, 'Отож, не лякайтесь, — бо вартніші ви за багатьох горобців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 32, 'Отже, кожного, хто Мене ви́знає перед людьми́, того перед Небесним Отцем Моїм визнаю й Я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 33, 'Хто ж Мене відцурається перед людьми́, того й Я відцураюся перед Небесним Отцем Моїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 34, 'Не ду́майте, що Я прийшов, щоб мир на землю прине́сти, — Я не мир прине́сти прийшов, а меча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 35, 'Я ж прийшов „порізни́ти чоловіка з батьком його, дочку́ з її матір\'ю, і невістку з свекру́хою її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 36, 'І: „вороги́ чоловікові — домашні його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 37, 'Хто більш, як Мене, любить батька чи матір, той Мене недостойний. І хто більш, як Мене, любить сина чи дочку, той Мене недостойний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 38, 'І хто не ві́зьме свого хреста, і не пі́де за Мною слідом, той Мене недостойний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 39, 'Хто душу свою́ зберігає, той погубить її, хто ж за Ме́не погубить душу свою́, — той зна́йде її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 40, 'Хто вас приймає — приймає Мене, хто ж приймає Мене, — приймає Того, Хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 41, 'Хто приймає пророка, як пророка, той дістане нагоро́ду проро́чу, хто ж приймає праведника, як праведника, той дістане нагоро́ду пра́ведничу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 42, 'І хто напо́їть, як у́чня, кого з мали́х цих бодай ку́хлем водиці холодної, поправді кажу́ вам, — той не згубить нагоро́ди своєї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'І сталось, коли Ісус перестав навчати дванадцятьо́х Своїх учнів, Він звідти пішов, щоб учити, і по їхніх містах проповідувати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'Прочувши ж Іван у в\'язни́ці про дії Христові, послав через учнів своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'щоб Його запитати: „Чи Ти Той, Хто має прийти, чи чекати нам Іншого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Ісус же промовив у відповідь їм: „Ідіть, і перекажіть Іванові, що́ ви чуєте й бачите:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, '„Сліпі прозріва́ють“, і криві ходять, стають чистими прокаже́ні, і чують глухі, і померлі встають, а „вбогим звіщається Добра Нови́на“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'І блаженний, хто через Мене споку́си не ма́тиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Як вони ж відійшли, Ісус про Івана почав говорити наро́дові: „На що́ ви ходили в пустиню дивитися? Чи на очерет, що вітер гойда́є його́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Та на що́ ви дивитись ходили? Може на чоловіка, у м\'які шати одя́гненого? Аджеж ті, хто носить м\'яке́, — по палатах царськи́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'По що́ ж ви ходили? Може бачити пророка? Так, кажу вам, — навіть більш, як пророка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Бо це ж той, що про нього написано: „Ось перед обличчя Твоє посилаю Свого посланця́, який перед Тобою дорогу Твою приготує!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Поправді кажу вам: Між наро́дженими від жінок не було більшого над Івана Христителя! Та найменший у Царстві Небеснім — той більший від нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'Від днів же Івана Христителя й досі Царство Небесне здобува́ється силою, і ті, хто вживає зусилля, хапа́ють його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Усі бо Пророки й Зако́н до Івана прові́щували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'Коли ж хочете знати, — то Ілля він, що має прийти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Хто́ має ву́ха, — нехай слухає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'До кого ж цей рід прирівняю? — До хлоп\'ят він подібний, що на ринку сидять та вигукують іншим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'і кажуть: „Ми вам грали, а ви не танцювали, ми співали вам жа́лібно, та не плакали ви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Бо прийшов був Іван, що не їв і не пив, вони ж кажуть: „Він де́мона має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Прийшов же Син Лю́дський, що їсть і п\'є, вони ж кажуть: „Чоловік ось, ласу́н і п\'яни́ця, Він при́ятель ми́тників і грішників“. І виправдалася мудрість своїми діла́ми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Ісус тоді став докоряти містам, де́ відбуло́ся найбільш Його чуд, що вони не покаялись:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, '„Горе тобі, Хоразі́не, горе тобі, Вефсаї́до! Бо коли б то в Ти́рі й Сидо́ні були відбули́ся ті чу́да, що сталися в вас, то давно б вони ка́ялися в волосяни́ці та в по́пелі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Але кажу́ вам: Легше буде дня судного Тиру й Сидону, ніж вам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'А ти, Капернау́ме, що „до неба піднісся, — аж до аду ти зі́йдеш“. Бо коли б у Содомі були відбули́ся ті чу́да, що в тобі вони стались, то лишився б він був по сього́днішній день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'Але кажу́ вам, що содо́мській землі буде легше дня судного, аніж тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Того ча́су, навчаючи, промовив Ісус: „Прославляю Тебе, Отче, Господи неба й землі, що втаїв Ти оце від премудрих і розумних, та його немовля́там відкрив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'Так, Отче, — бо Тобі так було до вподо́би!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'Передав Мені все Мій Отець. І Сина не знає ніхто, крім Отця, і Отця не знає ніхто, окрім Сина, та кому Син захоче відкрити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'Прийдіть до Мене, усі стру́джені та обтя́жені, — і Я вас заспоко́ю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Візьміть на себе ярмо́ Моє, і навчіться від Мене, бо Я тихий і серцем покі́рливий, — і „зна́йдете спо́кій ду́шам своїм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Бож ярмо Моє любе, а тяга́р Мій легки́й!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'Того ча́су Ісус перехо́див лана́ми в суботу. А у́чні Його зголодніли були, і стали зривати колосся та їсти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'Побачили ж це фарисеї, та й кажуть Йому: „Он учні Твої роблять те, чого не годиться робити в суботу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'А Він відповів їм: „Чи ж ви не читали, що́ зробив був Давид, коли сам зголоднів і ті, хто був із ним?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'Як він увійшов до Божого дому, і спожив хліби́ показні́, яких їсти не можна було ні йому, ані тим, хто був із ним, а тільки самим священикам?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'Або ви не читали в Зако́ні що в суботу священики пору́шують суботу у храмі, — і невинні вони?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'А Я вам кажу́, що тут Більший, як храм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'Коли б знали ви, що́ то є: „Милости хо́чу, а не жертви“, то ви не судили б невинних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Бо Син Лю́дський Госпо́дь і суботі“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, 'І, вийшовши звідти, прибув Він до їхньої синагоги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'І ото, був там чоловік, що мав суху руку. І, щоб обвини́ти Ісуса, запитали Його: „Чи вздоровляти годи́ться в суботу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'А Він їм сказав: „Чи зна́йде́ться між вами люди́на, яка, одну мавши вівцю́, не пі́де по неї, і не врятує її, як вона впаде в яму в суботу?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'А скільки ж люди́на вартніша за тую овечку! Тому́ можна чинити добро й у суботу“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'І каже тоді чоловікові: „Простягни свою руку!“Той простяг, — і стала здорова вона, як і друга.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 14, 'Фарисеї ж пішли, і зібрали нараду на Нього, — я́к би Його погубити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 15, 'А Ісус, розізнавши, пішов Собі звідти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 16, 'А Він наказав їм суво́ро Його не виявляти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 17, 'щоб спра́вдилось те, що́ сказав був Ісая пророк, промовляючи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 18, '„Ото Мій Слуга, що Я вибрав Його, Мій Улю́блений, що Його полюбила душа Моя! Вкладу́ Свого Духа в Нього, — і Він суд проголо́сить поганам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 19, 'Він не буде змагатися, ані кричати, і на вулицях чути не буде ніхто Його голосу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 20, 'Він очерети́ни надло́мленої не доло́мить, і ґнота́ догасаючого не пога́сить, поки не допровадить при́суду до перемоги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 21, 'І погани наді́ятись будуть на Йме́ння Його“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 22, 'Тоді привели́ до Ньо́го німого сліпця́, що був біснуватий, — і Він уздоро́вив його, так що німий став говорити та бачити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 23, 'І дивувались усі люди й казали: „Чи ж не Син це Давидів?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 24, 'Фарисеї ж, почувши, сказали: „Він де́монів не виганяє інакше, тільки як Вельзеву́лом, князем де́монів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 25, 'А Він знав думки їхні, і промовив до них: „Кожне царство, поділене супроти себе, запусті́є. І кожне місто чи дім, поділені супроти себе, не втри́маються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 26, 'І коли сатана́ сатану́ виганяє, то ділиться супроти себе; як же втри́мається царство його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 27, 'І коли Вельзевулом виганя́ю Я де́монів, то ким виганя́ють сини ваші? Тому́ вони стануть вам су́ддями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 28, 'А коли ж Духом Божим виго́ню Я де́монів, то настало для вас Царство Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 29, 'Або я́к то хто може вде́ртися в дім дужого, та пограбувати добро́ його, якщо перше не зв\'яже дужого? І аж тоді він госпо́ду його пограбує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 30, 'Хто не зо Мною, той супроти Мене; і хто не збирає зо Мною, той розкида́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 31, 'Тому́ то кажу́ вам: усякий гріх, навіть богозневага, про́ститься лю́дям, але богозневага на Духа не про́ститься!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 32, 'І як скаже хто слово на Лю́дського Сина, то йому́ проститься те; а коли скаже проти Духа Святого, — не про́ститься того йому ані в цім віці, ані в майбу́тнім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 33, 'Або ви́ростіть дерево добре, то й плід його добрий, або ви́ростіть дерево зле, то й плід його злий. Пізнається бо дерево з пло́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 34, 'Ро́де змії́ний! Як ви можете мовити добре, бувши злі? Бо чим серце напо́внене, те говорять уста́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 35, 'Добра люди́на з доброго ска́рбу добре виносить, а лукава люди́на зо скарбу лихого виносить лихе́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 36, 'Кажу́ ж вам, що за кожне слово пусте, яке скажуть люди, дадуть вони відповідь судного дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 37, 'Бо зо слів своїх будеш випра́вданий, і зо слів своїх будеш засу́джений“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 38, 'Тоді дехто із книжників та фарисеїв озвались до Нього й сказали: „Учителю, — хочемо побачити озна́ку від Те́бе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 39, 'А Ісус відповів їм: „Рід лукавий і перелю́бний шукає ознаки, — та ознаки йому не дадуть, окрім ознаки пророка Йо́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 40, 'Як Йо́на перебув у сере́дині китовій три дні і три ночі, так перебу́де три дні та три ночі й Син Лю́дський у серці землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 41, 'Ніневі́тяни стануть на суд із цим родом, — і осудять його, вони бо покаялися через Йо́нину проповідь. А тут ото Більший, ніж Йо́на!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 42, 'Цариця з пі́вдня на суд стане з родом оцим, — і засу́дить його, бо вона з кінця світу прийшла Соломонову мудрість послу́хати. А тут ото Більший, аніж Соломон!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 43, 'А коли дух нечистий виходить із люди́ни, то блукає місцями безвідними, відпочинку шукаючи, та не знахо́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 44, 'Тоді він говорить: „Вернуся до дому свого́, звідки вийшов“. А як ве́рнеться він, то хату знахо́дить порожню, заметену й при́брану.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 45, 'Тоді він іде, та й приводить сімох духів інших, лютіших за себе, — і входять вони та й живуть тут. І буде останнє люди́ні тій гірше за перше... Так буде й лукавому родові цьому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 46, 'Коли Він іще промовляв до наро́ду, аж ось мати й брати Його о́сторонь стали, бажаючи з Ним говорити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 47, 'І сказав хтось Йому́: „Ото мати Твоя й Твої бра́ття стоять онде о́сторонь, і говорити з Тобою бажають“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 48, 'А Він відповів тому́, хто Йому говорив, і сказав: „Хто́ мати Моя? І хто́ браття Мої?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 49, 'І, показавши рукою Своєю на у́чнів Своїх, Він промовив: „Ото Моя мати та браття Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 50, 'Бо хто волю Мого Отця, що на небі, чини́тиме, той Мені брат, і сестра, і мати!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 1, 'Того ж дня Ісус вийшов із дому, та й сів біля моря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 2, 'І бе́зліч наро́ду зібралась до Нього, так що Він увійшов був до чо́вна та й сів, а ввесь на́товп стояв понад берегом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 3, 'І багато навчав Він їх при́тчами, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 4, 'І як сіяв він зе́рна, упали одні край дороги, — і пташки́ налетіли, та їх повидзьо́бували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 5, 'Другі ж упали на ґрунт кам\'яни́стий, де не мали багато землі, — і негайно посхо́дили, бо земля неглибо́ка була́;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 6, 'а як сонце зійшло, — то зів\'яли, і коріння не мавши, — посохли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 7, 'А інші попа́дали в те́рен, — і вигнався терен, і їх поглуши́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 8, 'Інші ж упали на добрую землю — і зродили: одне в сто раз, друге в шістдеся́т, а те втри́дцятеро.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 9, 'Хто має ву́ха, щоб слухати, нехай слухає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 10, 'І учні Його приступили й сказали до Нього: „Чому́ при́тчами Ти промовляєш до них?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 11, 'А Він відповів і промовив: „Тому́, що вам да́но пізнати таємни́ці Царства Небесного, — їм же не да́но.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 12, 'Бо хто має, то дасться йому́ та дода́сться, хто ж не має, — забереться від нього й те, що́ він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 13, 'Я тому́ говорю́ до них при́тчами, що вони, ди́влячися, не бачать, і слухаючи, не чують, і не розуміють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 14, 'І над ними збувається пророцтво Ісаї, яке промовляє: „Почуєте слухом, — і не зрозумієте, дивитися бу́дете оком, — і не побачите.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 15, 'Затовсті́ло бо серце людей цих, тяжко чують ву́хами вони, і зажму́рили очі свої, щоб коли не побачити очима й не почути ву́хами, і не зрозуміти їм серцем, і не наверну́тись, щоб Я їх уздоро́вив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 16, 'Очі ж ваші блаженні, що бачать, і ву́ха ваші, що чують.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 17, 'Бо поправді кажу́ вам, що багато пророків і праведних бажали побачити, що́ бачите ви, — та не бачили, і почути, що́ чуєте ви, — і не чули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 18, 'Послухайте ж притчу про сіяча́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 19, 'До кожного, хто слухає слово про Царство, але не розуміє, приходить лукавий, і кра́де посіяне в серці його; це те, що посіяне понад дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 20, 'А посіяне на кам\'яни́стому ґрунті, — це той, хто слухає слово, і з радістю зараз приймає його;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 21, 'але кореня в ньому нема, тому він непостійний; коли ж у́тиск або переслідування настають за слово, то він зараз споку́шується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 22, 'А між те́рен посіяне, — це той, хто слухає слово, але кло́поти віку цього́ та омана багатства заглу́шують слово, — і воно зостається без пло́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 23, 'А посіяне в добрій землі, — це той, хто слухає слово й його розуміє, і плід він прино́сить, і дає один у сто раз, другий у шістдеся́т, а той утри́дцятеро“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 24, 'Іншу притчу подав Він їм, кажучи: „Царство Небесне подібне до чоловіка, що посіяв був добре насіння на полі своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 25, 'А коли люди спали, прийшов ворог його, і куколю між пшеницю насіяв, та й пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 26, 'А як виросло збіжжя та кинуло колос, тоді показався і кукі́ль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 27, 'І прийшли господаре́ві раби, та й кажуть йому: „Пане, чи ж не добре насіння ти сіяв на полі своїм? Звідки ж узявся кукіль?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 28, 'А він їм відказав: „Чоловік супроти́вник нако́їв оце“. А раби відказали йому́: „Отож, — чи не хочеш, щоб пішли ми і його повипо́лювали?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 29, 'Але він відказав: „Ні, — щоб, випо́люючи той кукіль, ви не вирвали ра́зом із ним і пшеницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 30, 'Залиші́ть, — хай ра́зом обоє ростуть аж до жнив; а в жнива́ накажу́ я женця́м: Зберіть перше кукі́ль і його пов\'яжіть у снопки́, щоб їх попали́ти; пшеницю ж спровадьте до клуні моєї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 31, 'Іншу притчу подав Він їм, кажучи: „Царство Небесне подібне до зе́рна гірчи́чного, що взяв чоловік і посіяв на полі своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 32, 'Воно найдрібніше з усьо́го насіння, але́, коли ви́росте, більше воно за зілля, і стає деревом, так що птаство небесне злітається, і ку́блиться в ві́ттях його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 33, 'Іншу притчу Він їм розпові́в: „Царство Небесне подібне до ро́зчини, що її бере жінка, і кладе на три мірі муки, аж поки все вки́сне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 34, 'Це все в при́тчах Ісус говорив до людей, і без при́тчі нічо́го Він їм не казав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 35, 'щоб спра́вдилось те, що сказав був пророк, промовляючи: „Відкрию у при́тчах уста́ Свої, розповім таємни́ці від по́чину світу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 36, 'Тоді відпустив Він наро́д і додому прийшов. І підійшли Його учні до Нього й сказали: „Поясни́ нам при́тчу про кукі́ль польови́й“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 37, 'А Він відповів і промовив до них: „Хто добре насіння посіяв був, — це Син Лю́дський,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 38, 'а поле — це світ, добре ж насіння — це сини Царства, а кукі́ль — сини лукавого;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 39, 'а ворог, що всіяв його — це диявол, жнива́ — кінець віку, а женці — анголи́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 40, 'І як збирають кукі́ль, і як па́лять в огні, так буде й напри́кінці віку цього́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 41, 'Пошле Лю́дський Син Своїх анголів, і вони позбирають із Царства Його всі спокуси, і тих, хто чинить беззако́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 42, 'і їх повкида́ють до пе́чі огне́нної, — буде там плач і скре́гіт зубів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 43, 'Тоді праведники, немов сонце, засяють у Царстві свого Отця. Хто має ву́ха, нехай слухає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 44, 'Царство Небесне подібне ще до захо́ваного в полі ска́рбу, що люди́на, знайшовши, ховає його, і з радости з того йде, та й усе, що має, продає та купує те поле.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 45, 'Подібне ще Царство Небесне до того купця, що пошу́кує пе́рел до́брих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 46, 'а як зна́йде одну дорогоцінну перли́ну, то йде, і все продає, що має, і купує її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 47, 'Подібне ще Царство Небесне до не́вода, у море заки́неного, що зібрав він усячину.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 48, 'Коли він напо́вниться, тягнуть на берег його, і, сівши, вибирають до по́суду добре, непо́тріб же геть викидають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 49, 'Так буде й напри́кінці віку: анголи́ повиходять, і вилучать злих з-поміж праведних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 50, 'і їх повкидають до пе́чі огне́нної, — буде там плач і скре́гіт зубів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 51, 'Чи ви зрозуміли це все?“— „Так!“відказали Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 52, 'І Він їм сказав: „Тому́ кожен книжник, що навче́ний про Царство Небесне, подібний до того госпо́даря, що з скарбниці своєї виносить нове́ та старе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 53, 'І сталось, як скінчи́в Ісус притчі оці, Він зві́дти пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 54, 'І прийшов Він до Своєї ба́тьківщини, і навчав їх у їхнїй синаго́зі, так що стали вони дивуватися й питати: „Звідки в Нього ця мудрість та си́ли чудоді́йні?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 55, 'Чи ж Він не син те́слі? Чи ж мати Його не Марією зветься, а брати Його — Яків, і Йо́сип, і Симон та Юда?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 56, 'І чи ж се́стри Його не всі з нами? Звідки ж Йому́ все оте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 57, 'І вони спокуша́лися Ним. А Ісус їм сказав: „Пророка нема без пошани, — хіба тільки в вітчи́зні своїй та в домі своїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 58, 'І Він не вчинив тут чуд багатьо́х через їхню невіру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 1, 'Того ча́су прочув Ірод чотиривла́сник чутки́ про Ісуса,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 2, 'і сказав своїм слу́гам: „Це Іван Христитель, — він із мертвих воскрес, і тому́ чуда тво́ряться ним“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 3, 'Бо Ірод схопи́в був Івана, і зв\'язав його, і посадив у в\'язни́цю через Іродія́ду, дружи́ну брата свого Пилипа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 4, 'Бо до нього Іван говорив: „Не годи́ться тобі її мати! “');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 5, 'І хотів Ірод смерть заподі́яти йому, та боявся наро́ду, бо того за пророка вважали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 6, 'А як був день наро́дження Ірода, танцювала посеред гостей дочка Іродія́дина, та й Іродові догоди́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 7, 'Тому́ під прися́гою він обіцявся їй дати, чого тільки попросить вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 8, 'А вона, за намовою матері своєї: „Дай мені — проказала — отут на полу́миску голову Івана Христителя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 9, 'І цар засмутився, але́ через клятву та тих, хто сидів при столі з ним, звелів дати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 10, 'І послав стяти Івана в в\'язни́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 11, 'І прине́сли на полу́мискові його голову, та й дали́ дівчині, а та відне́сла її своїй матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 12, 'А учні його прибули́, взяли тіло, і поховали його, та прийшли й сповістили Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 13, 'Як Ісус те почув, Він відплив звідти чо́вном у місце пустинне й самотнє. І, прочувши, наро́д із міст пішов пі́шки за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 14, 'І, як вийшов Ісус, Він побачив багато наро́ду, — і змилосе́рдивсь над ними, і їхніх слаби́х уздоро́вив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 15, 'А коли настав вечір, підійшли Його учні до Нього й сказали: „ Тут місце пустинне, і година вже пі́зня; відпусти наро́д, — хай по селах розі́йдуться, і куплять пожи́ви собі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 16, 'А Ісус їм сказав: „Непотрібно відхо́дити їм, — нагодуйте їх ви!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 17, 'Вони ж кажуть Йому: „Не маємо чим тут, — тільки п\'я́теро хліба й дві рибі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 18, 'А Він відказав: „Принесіть Мені їх сюди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 19, 'І, звелівши на́товпові посідати на траві, Він узяв п\'ятеро хліба й дві рибі, спогля́нув на небо, поблагословив й поламав ті хліби́, і дав учням, а учні наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 20, 'І всі їли й наси́тились, а з кусків позосталих назбирали двана́дцятеро повних кошів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 21, 'Їдців же було мужа тисяч із п\'ять, крім жіно́к і дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 22, 'І зараз звелів Ісус учням до чо́вна сідати, і перепли́сти на той бік раніше Його, аж поки наро́д Він відпу́стить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 23, 'Відпусти́вши ж народ, Він на го́ру пішов помолитися насамоті́; і як вечір настав, був там Сам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 24, 'А чо́вен вже був на сере́дині моря, і кидали хвилі його, бо вітер зірвавсь супроти́вний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 25, 'А о четвертій сторо́жі нічній Ісус підійшов до них, іду́чи по морю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 26, 'Як побачили ж учні, що йде Він по морю, то настра́шилися та й казали: „Мара́!“І від стра́ху вони закричали...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 27, 'А Ісус до них зараз озвався й сказав: „Заспокойтесь, — це Я, не лякайтесь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 28, 'Петро ж відповів і сказав: „Коли, Господи, Ти́ це, то звели, щоб прийшов я до Тебе по воді“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 29, 'А Він відказав йому: „Іди“. І, вилізши з чо́вна, Петро став іти по воді, і пішов до Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 30, 'Але, бачачи велику бурю, злякався, і зачав потопа́ти, і скричав: „Рятуй мене, Господи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 31, 'І зараз Ісус простяг руку й схопи́в його, і каже до нього: „Маловірний, чого́ усумни́вся?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 32, 'Як до чо́вна ж вони ввійшли, буря вщу́хнула.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 33, 'А приявні в чо́вні вклонились Йому та сказали: „Ти справді Син Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 34, 'Перепливши ж вони, прибули́ в землю Генісаре́тську.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 35, 'А люди тієї місцевости, пізнавши Його, сповістили по всій тій око́лиці, і до Нього прине́сли всіх хворих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 36, 'І благали Його, щоб бодай доторкнутися кра́ю одежі Його. А хто доторкавсь, — уздоро́влений був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 1, 'Тоді до Ісуса прийшли фарисеї та книжники з Єрусалиму н сказали:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 2, '„Чого Твої учні ламають переда́ння старших? Бо не миють вони своїх рук, коли хліб споживають“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 3, 'А Він відповів і промовив до них: „А чого й ви порушуєте Божу заповідь ради переда́ння вашого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 4, 'Бо Бог заповів: „Шануй ба́тька та матір“, та: „Хто злорі́чить на ба́тька чи матір, — хай смертю помре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 5, 'А ви кажете: Коли скаже хто ба́тьку чи матері: „Те, чим би ви скористатись від мене хотіли, то дар Богові “,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 6, 'то може вже й не шанувати той ба́тька свого або матір свою. Так ви ради переда́ння вашого зні́вечили Боже Слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 7, 'Лицеміри! Про вас добре Ісая пророкував, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 8, '„Оці люди уста́ми шанують Мене, серце ж їхнє дале́ко від Мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 9, 'Та однак надаре́мне шанують Мене, бо навчають наук — лю́дських за́повідей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 10, 'І Він покликав наро́д, і промовив до нього: „Послухайте та зрозумійте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 11, 'Не те, що вхо́дить до уст, люди́ну скверни́ть, але те, що виходить із уст, те люди́ну скверни́ть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 12, 'Тоді учні Його приступили й сказали Йому: „Чи Ти знаєш, що фарисеї, почуши це слово, спокуси́лися?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 13, 'А Він відповів і сказав: „Усяка росли́на, яку насадив не Отець Мій Небесний, буде вирвана з коренем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 14, 'Залишіть ви їх: це сліпі повода́тарі для сліпих. А коли сліпий водить сліпого, — обо́є до ями впаду́ть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 15, 'А Петро відповів і до Нього сказав: „Поясни нам цю при́тчу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 16, 'А Він відказав: „Чи ж і ви розумі́ння не маєте?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 17, 'Чи ж ви не розумієте, що все те, що́ входить до уст, вступає в живіт, та й назовні виходить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 18, 'Що ж виходить із уст, те походить із серця, — і воно опога́нює люди́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 19, 'Бо з серця виходять лихі думки́, душогубства, пере́люби, розпуста, крадіж, неправдиві засвідчення, богознева́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 20, 'Оце те, що люди́ну опога́нює. А їсти руками невмитими, — не опога́нює це люди́ни!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 21, 'І, вийшовши звідти, Ісус відійшов у землі ти́рські й сидо́нські.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 22, 'І ось жінка одна ханане́янка, із тих околиць прийшовши, заголосила до Нього й сказала: „Змилуйся надо мною, Господи, Сину Давидів, — де́мон тяжко дочку́ мою мучить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 23, 'А Він їй не казав ані слова. Тоді учні Його, підійшовши, благали Його та казали: „Відпусти її, бо кричить услід за нами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 24, 'А Він відповів і сказав: „Я по́сланий тільки до овечок загинулих дому Ізраїлевого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 25, 'А вона, підійшовши, уклонилась Йому та й сказала: „Господи, допоможи мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 26, 'А Він відповів і сказав: „Не годи́ться взяти хліб у дітей, і кинути щеня́там“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 27, 'Вона ж відказала: „Так, Господи! Але ж і щеня́та їдять ті кришки́, що спадають зо сто́лу їхніх панів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 28, 'Тоді відповів і сказав їй Ісус: „О жінко, твоя віра велика, — нехай буде тобі, я́к ти хочеш“! І тієї години дочка́ її ви́дужала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 29, 'І, відійшовши звідти, Ісус прибув до Галіле́йського моря, і, зійшовши на го́ру, сів там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 30, 'І приступило до Нього багато наро́ду, що мали з собою кривих, калік, сліпих, німих і інших багато, і клали їх до Ісусових ніг. І Він уздоро́влював їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 31, 'А наро́д не вихо́див із дива, бо бачив, що говорять німі, каліки стаю́ть здорові, криві ходять, і бачать сліпі, — і сла́вив він Бога Ізраїлевого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 32, 'А Ісус Своїх у́чнів покликав і сказав: „Жаль Мені цих людей, що вже три́ дні зо Мною знахо́дяться, але їсти не мають чого́; відпустити їх без їжі не хо́чу, щоб вони не ослабли в дорозі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 33, 'А учні Йому відказали: „Де́ нам узяти стільки хліба в пустині, щоб нагодувати стільки наро́ду?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 34, 'А Ісус запитав їх: „Скільки маєте хліба?“Вони ж відказали: „Семеро, та трохи рибок“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 35, 'І Він ізвелів на землі посідати наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 36, 'І, взявши сім хлібів і риби, віддавши Богу подяку, поламав і дав у́чням Своїм, а учні наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 37, 'І всі їли й наси́тилися, а з позосталих кусків назбирали сім ко́шиків по́вних...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 38, 'Їдців же було чотири тисячі мужа, окрім жінок та дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 39, 'І, відпустивши наро́д, усів Він до чо́вна, і прибув до землі Магдали́нської.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 1, 'І підійшли фарисеї та саддукеї, і, випробо́вуючи, просили Його показати ознаку їм із неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 2, 'А Він відповів і промовив до них: „Ви зве́чора кажете: „Буде пого́да, — червоні́є бо небо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 3, 'А ра́нком: „Сьогодні него́да, — червоніє бо небо похмуре“. Розпізна́ти небесне обличчя ви вмієте, ознак ча́су ж не можете!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 4, 'Рід лукавий і перелю́бний шукає озна́ки, та ознаки йому не дадуть, окрім озна́ки пророка Йони“. І, їх полишивши, Він відійшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 5, 'А учні Його, перейшовши на то́й бік, забули взяти хліба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 6, 'Ісус же промовив до них: „Стережіться ува́жливо фарисе́йської та саддуке́йської ро́зчини“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 7, 'Вони ж міркува́ли собі й говорили: „Ми ж хлібі́в не взяли́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 8, 'А Ісус, знавши те, запита́в: „Чого між собою міркуєте ви, маловірні, що хлібі́в не взяли́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 9, 'Чи ж ви ще́ не розумієте й не пам\'ятаєте про п\'ять хлібів на п\'ять тисяч, — і скільки коші́в ви зібрали?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 10, 'Ані про сім хлібів на чотири тисячі, — і скільки кошиків ви назбирали?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 11, 'Як ви не розумієте, що Я не про хліб вам сказав? Стережіться но ро́зчини фарисейської та саддукейської!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 12, 'Тоді зрозуміли вони, що Він не казав стерегтися їм ро́зчини хлібної, але фарисе́йської та саддуке́йської науки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 13, 'Прийшовши ж Ісус до землі Кесарі́ї Пили́пової, питав Своїх учнів і казав: „За ко́го наро́д уважає Мене́, Сина Лю́дського?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 14, 'Вони ж відповіли́: „Одні за Івана Христителя, одні за Іллю́, інші ж за Єремі́ю або за одного з пророків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 15, 'Він каже до них: „А ви за ко́го Мене маєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 16, 'А Си́мон Петро відповів і сказав: „Ти — Христос, Син Бога Живого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 17, 'А Ісус відповів і до ньо́го промовив: „Блаженний ти, Си́моне, сину Йо́нин, бо не тіло і кров тобі оце ви́явили, але Мій Небесний Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 18, 'I кажу Я тобі, що Петро ти, і на скелі оцій побудую Я Церкву Свою, — і сили а́дові не переможуть її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 19, 'І ключі тобі дам від Царства Небесного, і що́ на землі ти зв\'яжеш, те зв\'язане буде на небі, а що́ на землі ти розв\'яжеш, те розв\'язане буде на небі“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 20, 'Тоді наказав Своїм учням, щоб ніко́му не казали, що Він — Христо́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 21, 'Із того ча́су Ісус став виказувати Своїм у́чням, що Він мусить іти до Єрусалиму, і постраждати багато від старших, і первосвящеників, і книжників, і вбитому бути, — і воскреснути третього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 22, 'І, на́бік відвівши Його, Петро став Йому́ докоря́ти й казати: „Змилуйся, Господи, — такого Тобі хай не бу́де!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 23, 'А Він обернувся й промовив Петрові: „Відступися від Мене, сатано́, — ти спокуса Мені, бо ду́маєш не про Боже, а про лю́дське!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 24, 'Промовив тоді Ісус у́чням Своїм: „Коли хоче хто йти вслід за Мною, — хай зречеться самого себе, і хай ві́зьме свого хреста, та й іде вслід за Мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 25, 'Бо хто хоче спасти́ свою душу, той погубить її, хто ж за Мене свою душу погубить, той зна́йде її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 26, 'Яка ж ко́ристь люди́ні, що здобуде ввесь світ, але душу свою занапа́стить? Або що́ дасть люди́на взамін за душу свою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 27, 'Бо при́йде Син Лю́дський у славі Свого Отця з ангола́ми Своїми, і тоді „віддасть кожному згідно з діла́ми його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 28, 'Поправді кажу́ вам, що деякі з тут-о прия́вних не скушту́ють смерти, аж поки не побачать Сина Лю́дського, що йде в Царстві Своїм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 1, 'А через шість день забирає Ісус Петра, і Якова, і Івана, брата його, та й веде їх осі́бно на го́ру високу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 2, 'І Він перед ними переобрази́вся: обличчя Його, як те сонце, зася́ло, а одежа Його стала біла, як світло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 3, 'І ось з\'явились до них Мойсей та Ілля́, і розмовляли із Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 4, 'І озвався Петро та й сказав до Ісуса: „Господи, до́бре бути нам тут! Коли хочеш, поста́влю оту́т три шатра: для Тебе одне, і одне для Мойсея, і одне для Іллі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 5, 'Як він ще говорив, ось хмара ясна заслони́ла їх, і ось голос із хмари почувсь, що казав: „Це Син Мій Улю́блений, що Його Я вподо́бав. Його слухайтеся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 6, 'А почувши, попа́дали учні долі́лиць, і полякалися сильно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 7, 'А Ісус підійшов, доторкнувся до них і промовив: „Уставайте й не бійтесь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 8, 'Звівши ж очі свої, ніко́го вони не побачили, окрім Само́го Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 9, 'А коли з гори схо́дили, заповів їм Ісус і сказав: „Не кажіть ніко́му про це виді́ння, аж поки Син Лю́дський із мертвих воскре́сне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 10, 'І запитали Його учні, говорячи: „Що́ це книжники кажуть, ніби треба Іллі́ перш прийти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 11, 'А Він відповів і сказав: „Ілля́, правда, при́йде, і все приготу́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 12, 'Але́ кажу вам, що Ілля́ вже прийшов був, — та його не пізнали, але з ним зробили, що тільки хотіли. Так і Син Лю́дський має страждати від них“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 13, 'Учні тоді зрозуміли, що Він їм говорив про Івана Христителя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 14, 'І як вони до наро́ду прийшли, то до Нього один чоловік приступив, і навко́лішки впав перед Ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 15, 'і сказав: „Господи, змилуйсь над сином моїм, що біснується у новомі́сяччі, і мучиться тяжко, бо почасту падає він ув огонь, і почасту в воду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 16, 'Я його був привів до учнів Твоїх, — та вони не могли вздорови́ти його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 17, 'А Ісус відповів і сказав: „О роде невірний і розбе́щений, доки бу́ду Я з вами? Доки вас Я терпітиму? Приведіть до Мене сюди його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 18, 'Пото́му Ісус погрози́в йому, і де́мон вийшов із нього. І видужав хлопець тієї години!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 19, 'Тоді підійшли учні насамоті́ до Ісуса й сказали: „Чому ми́ не могли його вигнати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 20, 'А Він їм відповів: „Через ваше невірство. Бо поправді кажу́ вам: коли будете ви мати віру, хоч як зе́рно гірчи́чне, і горі оцій скажете: „Перейди́ звідси туди“, то й пере́йде вона, і нічо́го не матимете неможливого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 21, 'Цей же рід не вихо́дить інакше, як тільки молитвою й по́стом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 22, 'Коли пробува́ли вони в Галіле́ї, то сказав їм Ісус: „Людський Син буде ви́даний лю́дям до рук,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 23, 'і вони Його вб\'ють, але третього дня Він воскре́сне“. І тяжко вони зажурились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 24, 'Як прийшли ж вони в Капернау́м, до Петра підійшли збирачі́ дидра́хм на храм, та й сказали: „Чи не запла́тить ваш Учитель дидра́хми?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 25, 'Він відказує: „Так“. І як він увійшов до дому, то Ісус попере́див його та сказав: „Як ти ду́маєш, Си́моне: царі зе́мні з кого беру́ть мито або пода́тки: від синів своїх, чи чужих?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 26, 'А як той відказав: „Від чужих“, то промовив до нього Ісус: „Тож вільні сини!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 27, 'Та щоб їх не спокуси́ти, піди над море, та ву́дку закинь, і яку першу рибу ізло́виш, візьми, і рота відкрий їй, — і зна́йдеш стати́ра; візьми ти його, — і віддай їм за Мене й за себе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 1, 'Підійшли до Ісуса тоді Його учні, питаючи: „Хто найбільший у Царстві Небеснім?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 2, 'Він же дитину покликав, і поставив її серед них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 3, 'та й сказав: „Поправді кажу́ вам: коли не наве́рнетесь, і не станете, як ті діти, — не вві́йдете в Царство Небесне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 4, 'Отже, хто впоко́риться, як дитина оця, той найбільший у Царстві Небеснім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 5, 'І хто при́йме таку дитину одну в Моє Ймення, той приймає Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 6, 'Хто ж споку́сить одне з цих мали́х, що вірують в Мене, то краще б тако́му було, коли б жо́рно млино́ве на шию йому почепи́ти, — і його потопи́ти в морські́й глибині́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 7, 'Від споку́с горе світові, — бо мусять спокуси прийти; надто горе люди́ні, що від неї прихо́дить споку́са!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 8, 'Коли тільки рука твоя, чи нога твоя спокуша́є тебе, — відітни її й кинь від себе: краще тобі увійти в життя одноруким або одноногим, ніж з обома руками чи з обома ногами бути вкиненому в огонь вічний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 9, 'І коли твоє око тебе́ спокушає — його ви́бери й кинь від себе: краще тобі однооким ввійти в життя, ніж з обома очима бути вкиненому до геєнни огне́нної.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 10, 'Стережіться, щоб ви не погордували ані одним із мали́х цих; кажу́ бо Я вам, що їхні Анголи́ повсякчасно бачать у небі обличчя Мого Отця, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 11, 'Син бо Лю́дський прийшов, щоб спасти́ загинуле.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 12, 'Як вам здається: коли має який чоловік сто овець, а одна з них заблу́дить, то чи він не покине дев\'ятдесятьо́х і дев\'ятьо́х у гора́х, і не пі́де шукати заблу́длої?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 13, 'І коли пощасти́ть відшукати її, поправді кажу́ вам, що радіє за неї він більше, аніж за дев\'ятдесятьо́х і дев\'ятьо́х незаблудлих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 14, 'Так волі нема Отця вашого, що на небі, щоб загинув один із цих мали́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 15, 'А коли прогріши́ться твій брат проти тебе, іди й йому ви́кажи поміж тобою та ним самим; як тебе він послухає, — ти придбав свого брата.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 16, 'А коли не послухає він, то візьми з собою ще одно́го чи двох, щоб „справа всіляка стверди́лась уста́ми двох чи трьох свідків.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 17, 'А коли не послухає їх, — скажи Церкві; коли ж не послухає й Церкви, — хай бу́де тобі, як пога́нин і ми́тник!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 18, 'Поправді кажу вам: Що́ тільки зв\'яжете на землі, зв\'я́зане буде на небі, і що тільки розв\'я́жете на землі, розв\'язане буде на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 19, 'Ще поправді кажу́ вам, що коли б двоє з вас на землі погоди́лись про всяку річ, то коли вони будуть просити за неї, — станеться їм від Мого Отця, що на небі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 20, 'Бо де двоє чи троє в Ім\'я́ Моє зі́брані, — там Я серед них“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 21, 'Петро приступив тоді та запитався Його: „Господи, — скільки разів брат мій може згріши́ти проти мене, а я маю прощати йому? Чи до семи раз?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 22, 'Ісус промовляє до нього: „Не кажу тобі — до семи раз, але аж до семидесяти раз по семи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 23, 'Тим то Царство Небесне подібне одно́му царе́ві, що захотів обраху́нок зробити з своїми рабами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 24, 'Коли ж він почав обрахо́вувати, то йому привели́ одно́го, що винен був десять тисяч тала́нтів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 25, 'А що він не мав із чо́го віддати, наказав пан продати його, і його дружи́ну та діти, і все, що́ він мав, — і заплатити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 26, 'Тоді раб той упав до ніг, і вклонявся йому та благав: „Потерпи мені, — я віддам тобі все!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 27, 'І змилосе́рдився пан над рабом тим, — і звільнив його, і простив йому борг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 28, 'А як вийшов той раб, то спіткав він одно́го з своїх співтова́ришів, що був винен йому сто динаріїв. І, схопи́вши його, він душив та казав: „Віддай, що ти винен!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 29, 'А товариш його впав у ноги йому, і благав його, кажучи: „Потерпи мені, — і я віддам тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 30, 'Та той не схотів, а пішов і всадив до в\'язни́ці його, — аж поки він боргу не ве́рне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 31, 'Як побачили ж товариші його те, що сталося, то засмутилися дуже, і прийшли й розповіли своє́му панові все, що було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 32, 'Тоді пан його кличе його, та й говорить до нього: „Рабе лукавий, — я простив був тобі ввесь той борг, бо просив ти мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 33, 'Чи й тобі не нале́жало зми́луватись над своїм співтова́ришем, як і я над тобою був зми́лувався?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 34, 'І прогнівався пан його, — і ката́м його видав, аж поки йому не віддасть всього боргу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 35, 'Так само й Отець Мій Небесний учинить із вами, коли кожен із вас не про́стить своєму братові з серця свого їхніх про́гріхів “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 1, 'І сталось, як Ісус закінчи́в ці слова́, то Він ви́рушив із Галілеї, і прибув до країни Юдейської, на то́й бік Йорда́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 2, 'А за Ним ішла бе́зліч наро́ду, — і Він уздоро́вив їх тут.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 3, 'І підійшли фарисеї до Нього, і, випробо́вуючи, запитали Його: „Чи дозволено дружи́ну свою відпускати з причини всякої?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 4, 'А Він відповів і сказав: „Чи ви не читали, що Той, Хто створив споконві́ку людей, „створив їх чоловіком і жінкою?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 5, 'І сказав: „Покине тому́ чоловік батька й матір, і пристане до дружи́ни своєї, — і стануть обо́є вони одним тілом“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 6, 'тому́ то немає вже двох, але́ одне тіло. Тож, що Бог спарува́в, — людина нехай не розлу́чує!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 7, 'Вони кажуть Йому: „А чому́ ж Мойсей заповів дати листа розводо́вого, та й відпускати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 8, 'Він говорить до них: „То за ваше жорстокосе́рдя дозволив Мойсей відпускати дружи́н ваших, споча́тку ж так не було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 9, 'А Я вам кажу́: Хто дружи́ну відпустить свою не з причини пере́любу, і одру́житься з іншою, той чинить пере́люб. І хто одру́житься з розве́деною, той чинить пере́люб“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 10, 'Учні говорять Йому: „Коли справа така чоловіка із дружи́ною, то не добре одру́жуватись“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 11, 'А Він їм відказав: „Це слово вміщають не всі, але ті, кому да́но.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 12, 'Бо бувають скопці, що з утро́би ще матерньої народилися так; є й скопці, що їх люди оскопи́ли, і є скопці, що самі оскопи́ли себе ради Царства Небесного. Хто може вмістити, — нехай вмістить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 13, 'Тоді привели Йому ді́ток, щоб поклав на них руки, і за них помолився, учні ж їм докоряли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 14, 'Ісус же сказав: „Пустіть ді́ток, і не бороніть їм прихо́дити до Мене, — бо Царство Небесне належить таким“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 15, 'І Він руки на них покла́в, та й пішов звідтіля́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 16, 'І підійшов ось один, і до Нього сказав: „Учителю Добрий, що маю зробити я доброго, щоб мати життя вічне?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 17, 'Він же йому відказав: „Чого звеш Мене Добрим? Ніхто не є Добрий, крім Бога Само́го. Коли ж хочеш ввійти до життя, то виконай заповіді“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 18, 'Той питає Його: „Які саме!“А Ісус відказав: „Не вбивай, не чини пере́любу, не кради́, не свідкуй неправдиво.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 19, 'Шануй батька та матір“, і: „Люби свого ближнього, як само́го себе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 20, 'Говорить до Нього юна́к: „Це я виконав все. Чого́ ще бракує мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 21, 'Ісус каже йому: „Коли хочеш бути досконалим, — піди, продай до́бра свої та й убогим роздай, — і матимеш скарб ти на небі. Пото́му приходь та й іди вслід за Мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 22, 'Почувши ж юна́к таке слово, відійшов, зажурившись, — бо великі маєтки він мав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 23, 'Ісус же сказав Своїм учням: Поправді кажу вам, що багатому трудно ввійти в Царство Небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 24, 'Іще вам кажу́: Верблю́дові легше пройти через го́лчине ву́шко, ніж багатому в Боже Царство ввійти́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 25, 'Як учні ж Його це зачули, здивувалися дуже й сказали: „Хто́ ж тоді може спасти́ся?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 26, 'А Ісус позирнув і сказав їм: „Неможливе це лю́дям, та можливе все Богові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 27, 'Тоді відізвався Петро та до Нього сказав: „От усе ми покинули, та й пішли за Тобою слідом; що́ ж нам буде за це?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 28, 'А Ісус відказав їм: „Поправді кажу́ вам, що коли, при відно́вленні світу, Син Лю́дський засяде на престолі слави Своєї, тоді сядете й ви, що за Мною пішли, на дванадцять престолів, щоб судити дванадцять племе́н Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 29, 'І кожен, хто за Йме́ння Моє кине дім, чи братів, чи сесте́р, або ба́тька, чи матір, чи діти, чи зе́млі, — той багатокротно одержить і успадку́є вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 30, 'І багато-хто з перших останніми стануть, а останні — першими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 1, 'Бо Царство Небесне подібне одно́му госпо́дареві, що вдо́світа вийшов згодити робітників у свій виноградник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 2, 'Згодившися ж він із робі́тниками по дина́рію за день, послав їх до свого виноградника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 3, 'А вийшовши коло години десь третьої, побачив він інших, що стояли без праці на ринку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 4, 'та й каже до них: „Ідіть і ви до мого виноградника, і що́ буде належати, дам вам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 5, 'Вони ж відійшли. І вийшов він знов о годині десь шостій й дев\'ятій, і те саме зробив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 6, 'А вийшовши коло години одина́дцятої, знайшов інших, що стояли без праці, та й каже до них: „Чого тут стоїте́ цілий день безробітні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 7, 'Вони кажуть до нього: „Бо ніхто не найняв нас“. Відказує їм: „Ідіть і ви в виноградник“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 8, 'Коли ж вечір настав, то говорить тоді до свого управителя пан виноградника: „Поклич робі́тників, і дай їм заплату, почавши з останніх до перших“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 9, 'І прийшли ті, що з години одинадцятої, і взяли по дина́рію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 10, 'Коли ж прийшли перші, то ду́мали, що вони візьмуть більше. Та й вони по динару взяли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 11, 'А взявши, вони почали́ наріка́ти на господаря,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 12, 'кажучи: „Ці останні годину одну працювали, а ти прирівняв їх до нас, що витерпіли тягар дня та спеко́ту“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 13, 'А він відповів і сказав до одно́го із них: „Не кривджу я, друже, тебе, — хіба не за динарія згодився зо мною?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 14, 'Візьми ти своє та й іди. Але я хочу дати й цьому́ ось останньому, як і тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 15, 'Чи ж не вільно мені зо своїм, що я хо́чу, зробити? Хіба око твоє за́здре від того, що я добрий?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 16, 'Отак будуть останні першими, а перші — останніми!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 17, 'Побажавши ж піти до Єрусалиму, Ісус взяв осібно Дванадцятьо́х, і на дорозі їм сповістив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 18, '„Оце в Єрусалим ми йдемо́, — і первосвященикам і книжникам ви́даний буде Син Лю́дський, — і засудять на смерть Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 19, 'І поганам Його вони видадуть — на нару́гу та на катува́ння, і на розп\'яття́, — але третього дня Він воскресне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 20, 'Тоді приступила до Нього мати синів Зеведеєвих, і вклонилась, і просила від Нього чогось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 21, 'А Він їй сказав: „Чого хочеш?“Вона каже Йому́: „Скажи, щоб оби́два сини мої ці сіли в Царстві Твоїм — право́руч один, і ліво́руч від Тебе один“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 22, 'А Ісус відповів і сказав: „Не знаєте, чого просите. Чи ж можете ви пити чашу, що Я її питиму (або христи́тися хрищенням, що я ним хрищу́ся)?“„Вони кажуть Йому: „Можемо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 23, 'Він говорить до них: „Ви питимете Мою чашу (і бу́дете христитися хрищенням, що Я ним хрищуся). А сидіти право́руч Мене та ліво́руч — не Моє це давати, а кому від Мого Отця те вгото́вано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 24, 'Як почули це де́сятеро, стали гніватися на обох тих братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 25, 'А Ісус їх покликав і промовив: „Ви знаєте, що князі наро́дів панують над ними, а вельможі їх тиснуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 26, 'Не так буде між вами, але́ хто великим із вас хоче бути, — хай буде слугою він вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 27, 'А хто з вас бути першим бажає, — нехай буде він вам за раба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 28, 'Так само й Син Лю́дський прийшов не на те, щоб служили Йому, а щоб послужити, і душу Свою дати на викуп за багатьох!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 29, 'Як вони ж з Єрихо́ну вихо́дили, за Ним ішов на́товп великий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 30, 'І ось двоє сліпих, що сиділи при дорозі, почувши, що переходить Ісус, стали кричати, благаючи: „Змилуйсь над нами, Господи, Сину Давидів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 31, 'Наро́д же сварився на них, щоб мовчали, вони ж іще більше кричали, благаючи: „Змилуйсь над нами, Господи, Сину Давидів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 32, 'Ісус же спинився, — покликав їх та й сказав: „Що́ хочете, щоб Я вам зробив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 33, 'Вони Йому кажуть: „Господи, — нехай нам розкриються очі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 34, 'І змилосе́рдивсь Ісус, доторкнувся до їхніх оче́й, — і зараз прозріли їм очі, і вони подалися за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 1, 'А коли вони набли́зились до Єрусалиму, і прийшли до Вітфагі́ї, до гори до Оли́вної, тоді Ісус вислав двох учнів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 2, 'до них, кажучи: „Ідіть у село, яке перед вами, і зна́йдете зараз ослицю прив\'язану та з нею осля́; відв\'яжіть, і Мені приведіть їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 3, 'А як хто вам що́ скаже, відкажіть, що їх потребує Госпо́дь, — і він зараз пошле їх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 4, 'А це сталось, щоб спра́вдилось те, що сказав був пророк, промовляючи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 5, '„Скажіте Сіонській доньці́: Ось до тебе йде Цар твій! Він покі́рливий, і всів на осла, — на осля, під\'яре́мної сина“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 6, 'А учні пішли та й зробили, як звелів їм Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 7, 'Вони привели́ до Ісуса ослицю й осля́, і одежу поклали на них, — і Він сів на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 8, 'І багато народу стелили одежу свою по дорозі, інші ж різали віття з дерев і стели́ли дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 9, 'А наро́д, що йшов перед Ним і поза́ду, викрикував, кажучи: „Оса́нна Сину Давидовому! Благословенний, хто йде у Господнє Ім\'я́! Осанна на висоті!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 10, 'А коли увійшов Він до Єрусалиму, то здвигнулося ціле місто, питаючи: „Хто́ це такий?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 11, 'А наро́д говорив: „Це Пророк, — Ісус із Назаре́ту Галілейського!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 12, 'Потому Ісус увійшов у храм Божий, і вигнав усіх продавців і покупців у храмі, і попереверта́в грошомінам столи, та осло́ни — продавцям голубів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 13, 'І сказав їм: „Написано: „Дім Мій — буде домом молитви,“а ви робите з нього „печеру розбійників“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 14, 'I приступили у храмі до Нього сліпі та криві, — і Він їх уздоро́вив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 15, 'А первосвященики й книжники, бачивши чуда, що Він учинив, і дітей, що в храмі викрикували: „Осанна Сину Давидовому“, обурилися,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 16, 'та й сказали Йому: „Чи ти чуєш, що кажуть вони?“А Ісус відказав їм: „Так. Чи ж ви не читали нікол́и: „Із уст немовлят, і тих, що ссуть, учинив Ти хвалу“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 17, 'І покинувши їх, Він вийшов за місто в Віфа́нію, — і там ніч перебув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 18, 'А вранці, до міста вертаючись, Він зголоднів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 19, 'І побачив Він при дорозі одне фі́ґове дерево, і до нього прийшов, та нічого, крім листя само́го, на нім не знайшов. І до нього Він каже: „Нехай пло́ду із тебе не буде ніко́ли повіки!“І фіґове дерево зараз усохло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 20, 'А учні, побачивши це, дивувалися та говорили: „Як швидко всохло це фіґове дерево!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 21, 'Ісус же промовив у відповідь їм: „Поправді кажу́ вам: Коли б мали ви віру, і не мали су́мніву, то вчинили б не тільки як із фіговим деревом, а якби й цій горі ви сказали: „Порушся та кинься до моря“, — то й станеться те!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 22, 'І все, чого ви в молитві попросите з вірою, — то одержите“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 23, 'А коли Він прийшов у храм і навчав, поприхо́дили первосвященики й старші наро́ду до Нього й сказали: „Якою Ти вла́дою чиниш оце? І хто Тобі вла́ду цю дав?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 24, 'Ісус же промовив у відповідь їм: „Запитаю й Я вас одне слово. Як про нього дасте Мені відповідь, то й Я вам скажу́, якою вла́дою Я це чиню́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 25, 'Іванове хрищення звідки було: із неба, чи від людей?“Вони ж міркували собі й говорили: „Коли скажемо: „Із неба“, відкаже Він нам: „Чого ж ви йому не повірили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 26, 'А як скажемо: „Від людей“, — боїмося наро́ду, бо Івана вважають усі за пророка“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 27, 'І сказали Ісусові в відповідь: „Ми не знаємо“. Відказав їм і Він: „То й Я вам не скажу́, якою владою Я це чиню́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 28, 'А як вам здається? Один чоловік мав двох синів. Прийшовши до першого, він сказав: „Піди но, дитино, сьогодні, працюй у винограднику!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 29, 'А той відповів і сказав: „Готовий, панотче“, — і не пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 30, 'І, прийшовши до другого, так само сказав. А той відповів і сказав: „Я не хочу“. А потім покаявся, і пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 31, 'Котрий же з двох учинив волю батькову?“Вони кажуть: „Останній“. Ісус промовляє до них: „Поправді кажу вам, що ми́тники та блудоді́йки випере́джують вас у Боже Царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 32, 'Бо прийшов був до вас дорогою праведности Іван, та йому не повірили ви, а ми́тники та блудоді́йки йняли йому віри. А ви бачили, та проте не покаялися й опісля́, щоб повірити йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 33, 'Послухайте іншої притчі. Був госпо́дар один. Насадив виноградника він, обгородив його муром, ви́довбав у ньому чави́ло, башту поставив, — і віддав його винаря́м, та й пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 34, 'Коли ж надійшов час плоді́в, він до винарів послав рабів своїх, щоб прийняти плоди́ свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 35, 'Винарі ж рабів його похапали, — і одно́го побили, а другого замордували, а того вкаменува́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 36, 'Знов послав він інших рабів, більш як перше, — та й їм учинили те саме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 37, 'Нарешті послав до них сина свого́ і сказав: „Посоро́мляться сина мого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 38, 'Але́ винарі́, як побачили сина, міркувати собі стали: „Це спадкоє́мець; ходім, замордуймо його, — і заберемо його спа́дщину!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 39, 'І, схопи́вши його, вони вивели за виноградник його, та й убили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 40, 'Отож, як прибу́де той пан виноградника, що́ зробить він тим винаря́м?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 41, 'Вони кажуть Йому: „Злочинців погубить жорсто́ко, виноградника ж віддасть іншим винаря́м, що будуть плоди́ віддавати йому своєча́сно“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 42, 'Ісус промовляє до них: „Чи ви не читали ніко́ли в Писа́нні: Камінь, що його будівничі відкинули, — той наріжним став каменем; від Господа сталося це, і дивне воно в очах наших!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 43, 'Тому́ кажу вам, що від вас Царство Боже відійметься, і дасться наро́дові, що плоди́ його буде прино́сити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 44, 'І хто впаде́ на цей камінь — розі́б\'ється, а на кого він сам упаде — то розча́вить його́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 45, 'А як первосвященики та фарисеї почули ці притчі Його, то вони зрозуміли, що про них Він гово́рить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 46, 'І намага́лись схопи́ти Його, але́ побоялись людей, бо вважали Його за Пророка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 1, 'А Ісус, відповідаючи, знов почав говорити їм при́тчами, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 2, '„Царство Небесне подібне одно́му царе́ві, що весі́лля справляв був для сина свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 3, 'І послав він своїх рабів покликати тих, хто був на весі́лля запрошений, — та ті не хотіли прийти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 4, 'Зно́ву послав він інших рабів, наказуючи: „Скажіть запрошеним: Ось я приготува́в обід свій, закололи бики й відгодо́ване, — і все готове. Ідіть на весі́лля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 5, 'Та вони злегковажили та порозхо́дились, — той на поле своє, а той на свій торг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 6, 'А останні, похапавши рабів його́, знущалися, та й повбивали їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 7, 'І розгнівався цар, і послав своє ві́йсько, — і вигубив тих убійників, а їхнє місто спалив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 8, 'Тоді каже рабам своїм: „Весі́лля готове, але́ недостойні були́ ті покликані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 9, 'Тож підіть на роздорі́жжя, і кого тільки спіткаєте, — кличте їх на весі́лля“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 10, 'І вийшовши раби ті на роздоріжжя, зібрали всіх, кого тільки спіткали, — злих і добрих. І весільна кімна́та гістьми́ перепо́внилась.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 11, 'Як прийшов же той цар на гостей подивитись, побачив там чоловіка, в одежу весі́льну не вбра́ного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 12, 'та й каже йому: „Як ти, друже, ввійшов сюди, не мавши одежі весільної?“Той же мовчав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 13, 'Тоді́ цар сказав своїм слу́гам: „Зв\'яжіть йому ноги та руки, та й киньте до зо́внішньої те́мряви, — буде плач там і скрегіт зубів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 14, 'Бо багато покли́каних, — та ви́браних мало“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 15, 'Тоді фарисеї пішли й умовлялись, я́к зловити на слові Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 16, 'І посилають до Нього своїх учнів із іродія́нами, і кажуть: „Учителю, знаємо ми, що Ти справедливий, і наставляєш на Божу дорогу правдиво, і не зважаєш ні на кого, бо на лю́дське обличчя не дивишся Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 17, 'Скажи ж нам, як здається Тобі: чи годиться давати податок для ке́саря, чи ні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 18, 'А Ісус, знавши їхнє лукавство, сказав: „Чого ви, лицеміри, Мене випробо́вуєте?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 19, 'Покажіть Мені гріш податко́вий“. І прине́сли динарія Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 20, 'А Він каже до них: „Чий це образ і напис?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 21, 'Ті відказують: „Ке́сарів“. Тоді каже Він їм: „Тож віддайте кесареве — кесареві, а Богові — Боже“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 22, 'А почувши таке, вони диву далися. І, лишивши Його, відійшли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 23, 'Того дня приступили до Нього саддуке́ї, що твердять, ніби нема воскресіння, і запитали Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 24, 'та й сказали: „Учителю, Мойсей наказав: „Коли хто помре, не мавши дітей, то нехай його брат візьме вдову́ його, — і відно́вить насіння для брата свого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 25, 'Було ж у нас сім братів. І перший, одружи́вшись, умер, і, не мавши насіння, зоставив дружи́ну свою братові своєму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 26, 'Так само і другий, і третій, — аж до сьомого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 27, 'А по всіх вмерла й жінка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 28, 'Отож, у воскре́сенні котро́му з сімох вона дружи́ною буде? Бо всі мали її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 29, 'Ісус же промовив у відповідь їм: „Помиляєтесь ви, не знавши Писа́ння, ні Божої сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 30, 'Бо в воскресінні ні женяться, ані заміж виходять, але як Анголи́ ті на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 31, 'А про воскресіння померлих хіба не читали проре́ченого вам від Бога, що каже:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 32, '„Я Бог Авраамів, і Бог Ісаків, і Бог Яковів; Бог не є Богом мертвих, а живих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 33, 'А наро́д, чувши це, дивувався науці Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 34, 'Фарисеї ж, почувши, що Він у́ста замкнув саддуке́ям, зібралися ра́зом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 35, 'І спитався один із них, учитель Зако́ну, Його випробо́вуючи й кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 36, '„Учителю, котра́ заповідь найбільша в Зако́ні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 37, 'Він же промовив йому́: „Люби Господа Бога свого всім серцем своїм, і всією душею своєю, і всією своєю думкою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 38, 'Це найбільша й найперша заповідь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 39, 'А друга одна́кова з нею: „Люби свого ближнього, як само́го себе́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 40, 'На двох оцих заповідях увесь Зако́н і Пророки стоять“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 41, 'Коли ж фарисеї зібрались, Ісус їх запитав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 42, 'і сказав: „Що́ ви думаєте про Христа? Чий Він син?“Вони Йому кажуть: „Давидів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 43, 'Він до них промовляє: „Як же то силою Духа Давид Його Господом зве, коли каже:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 44, '„Промовив Господь Господе́ві моєму: сядь право́руч Мене, доки не покладу Я Твоїх ворогів підніжком ногам Твоїм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 45, 'Тож, коли Давид зве Його Господом, — як же Він йому син?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 46, 'І ніхто не спромігся відпові́сти Йому ані сло́ва... І ніхто з того дня не наважувався більш питати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 1, 'Тоді промовив Ісус до народу й до учнів Своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 2, 'і сказав: „На сиді́нні Мойсеєвім усілися книжники та фарисеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 3, 'Тож усе, що́ вони скажуть вам, — робіть і виконуйте; та за вчинками їхніми не робіть, бо говорять вони — та не роблять того́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 4, 'Вони ж в\'яжуть тяжкі тягарі, і кладуть їх на лю́дські раме́на, самі ж навіть пальцем своїм не хотять їх пору́шити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 5, 'Усі ж учинки свої вони роблять, щоб їх бачили люди, і богомі́лля свої розширяють, і здовжують ки́тиці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 6, 'І люблять вони передніші місця на бенке́тах, і передніші лавки́ в синагогах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 7, 'і привіти на ринках, і щоб звали їх люди: Учителю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 8, 'А ви вчителями не звіться, — бо один вам Учитель, а ви всі брати́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 9, 'І не називайте нікого отцем на землі, — бо один вам Отець, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 10, 'І не звіться наста́вниками, — бо один вам Наста́вник, — Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 11, 'Хто між вами найбільший, хай слугою вам буде!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 12, 'Хто бо підно́ситься, — буде понижений, хто ж понижується, той піднесе́ться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 13, 'Горе ж вам, книжники та фарисеї, лицеміри, що перед людьми́ зачиняєте Царство Небесне, — бо й самі ви не вхо́дите, ані тих, хто хоче ввійти, увійти не пускаєте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 14, '(Горе ж вам, книжники та фарисеї, лицеміри, що вдови́ні хати поїдаєте, і напо́каз молитесь довго, — через те осуд тяжчий ви при́ймете!)');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 15, 'Горе вам, книжники та фарисеї, лицеміри, що обходите море та землю, щоб придбати нововірця одно́го; а коли те стається, то робите його сином геє́нни, вдвоє гіршим від вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 16, 'Горе вам, проводирі́ ви сліпі, що говорите: „Коли хто поклянеться храмом, то нічого; а хто поклянеться золотом храму, то той винуватий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 17, 'Нерозумні й сліпі, — що бо більше: чи золото, чи той храм, що освячує золото?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 18, 'І: „Коли хто поклянеться же́ртівником, — то нічого, а хто поклянеться жертвою, що на нім, то він винуватий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 19, 'Нерозумні й сліпі, — що́ бо більше: чи жертва, чи той же́ртівник, що освячує жертву?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 20, 'Отож, хто клянеться же́ртівником, — клянеться ним та всім, що на ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 21, 'І хто храмом клянеться, — клянеться ним та Тим, Хто живе в нім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 22, 'І хто небом клянеться, — клянеться Божим престолом і Тим, Хто на ньому сидить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 23, 'Горе вам, книжники та фарисеї, лицеміри, що даєте десятину із м\'я́ти, і га́нусу й кми́ну, але найважливіше в Зако́ні поки́нули: суд, милосе́рдя та віру; це треба робити, і того не ки́дати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 24, 'Проводирі́ ви сліпі, що відціджуєте комаря́, а верблю́да ковтаєте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 25, 'Горе вам, книжники та фарисеї, лицеміри, що чистите зовнішність ку́хля та миски, а всере́дині повні вони здирства й кривди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 26, 'Фарисею сліпий, — очисти перше сере́дину кухля, щоб чистий він був і назо́вні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 27, 'Горе вам, книжники та фарисеї, лицеміри, що подібні до гробі́в побі́лених, які гарними зверху здаються, а всере́дині повні трупних кісто́к та всякої нечи́стости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 28, 'Так і ви, — назовні здаєтеся лю́дям за праведних, а всере́дині повні лицемі́рства та беззаконня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 29, 'Горе вам, книжники та фарисеї, лицеміри, що пророкам надгро́бники ставите, і праведникам прикраша́єте пам\'ятники,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 30, 'та говорите: „Якби ми жили́ за днів наших батьків, то ми не були б спільника́ми їхніми в крові пророків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 31, 'Тим самим на себе свідкуєте, що сини ви убивців пророків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 32, 'Доповніть і ви міру провини ваших батьків!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 33, 'О змії, о ро́де гадю́чий, — я́к ви втечете від за́суду до геє́нни?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 34, 'І ось тому́ посилаю до вас Я пророків, і мудрих, і книжників; частину їх ви повбиваєте та розіпне́те, а частину їх ви бичува́тимете в синагогах своїх, і будете гнати з міста до міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 35, 'Щоб спала на вас уся праведна кров, що пролита була на землі, від крови Авеля праведного, аж до крови Заха́рія, Варахі́їного сина, що ви замордували його між храмом і же́ртівником!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 36, 'Поправді кажу вам: Оце все спаде на рід цей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 37, 'Єрусалиме, Єрусалиме, що вбиваєш пророків та каменуєш посланих до те́бе! Скільки разів Я хотів зібрати діти твої, як квочка збирає під крила курчаток своїх, — та ви не захотіли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 38, 'Ось ваш дім залиша́ється порожній для вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 39, 'Говорю́ бо Я вам: Відтепер ви Мене не побачите, аж поки не скажете: „Благословенний, Хто йде у Господнє їм\'я́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 1, 'І вийшов Ісус і від храму пішов. І підійшли Його учні, щоб Йому показати будинки храмо́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 2, 'Він же промовив у відповідь їм: „Чи бачите ви все оце? Поправді кажу́ вам: Не зали́шиться тут навіть камінь на камені, який не зруйнується!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 3, 'Коли ж Він сидів на Оли́вній горі, підійшли Його учні до Нього само́тньо й спитали: „Скажи нам, — коли станеться це? І яка буде ознака прихо́ду Твого й кінця віку?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 4, 'Ісус же промовив у відповідь їм: „Стережіться, щоб вас хто не звів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 5, 'Бо багато хто при́йде в Ім\'я́ Моє, кажучи: „Я Христос“. І зведуть багатьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 6, 'Ви ж про війни почуєте, і про воєнні чутки́, — глядіть, не лякайтесь, бо „статись належить тому“. Але це не кінець ще.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 7, 'Бо „повстане наро́д на народ, і царство на царство“, і голод, мор та землетруси настануть місця́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 8, 'А все це — поча́ток терпінь породільних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 9, 'На муки тоді видаватимуть вас, і вбиватимуть вас, і вас будуть нена́видіти всі народи за Ймення Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 10, 'І багато-хто в той час спокусяться, і видавати один о́дного будуть, і один о́дного будуть нена́видіти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 11, 'Постане багато фальшивих пророків, — і зведу́ть багатьо́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 12, 'І через розрі́ст беззаконства любов багатьох охоло́не.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 13, 'А хто витерпить аж до кінця, — той буде спасе́ний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 14, 'І проповідана буде ця Євангелія Царства по ці́лому світові, на свідо́цтво наро́дам усім. І тоді при́йде кінець!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 15, 'Тож, коли ви побачите ту „гидоту спусто́шення“, що про неї звіщав був пророк Даниїл, на місці святому, — хто читає, нехай розуміє, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 16, 'тоді ті, хто в Юдеї, нехай в го́ри втікають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 17, 'Хто на покрівлі, нехай той не сходить узяти речі з дому свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 18, 'І хто на полі, — хай назад не вертається взяти одежу свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 19, 'Горе ж вагі́тним і тим, хто годує грудьми́, за днів тих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 20, 'Моліться ж, щоб ваша втеча не сталась зимою, ані в суботу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 21, 'Бо скорбо́та велика настане тоді, „якої не було́ з первопо́чину світу аж досі“й не бу́де.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 22, 'І коли б не вкороти́лись ті дні, не спаслася б ніяка люди́на; але через ви́браних дні ті вкоро́тяться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 23, 'Тоді, як хто скаже до вас: „Ото, Христос тут\" чи „Отам“, — не йміть віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 24, 'Бо постануть христи́ неправдиві, і неправдиві пророки, і будуть чинити великі ознаки та чуда, що звели́ б, коли б можна, і ви́браних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 25, 'Оце Я наперед вам сказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 26, 'А коли скажуть вам: „Ось Він у пустині“— не виходьте, „Ось Він у криївках“— не вірте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 27, 'Бо як бли́скавка та вибігає зо схо́ду, і з\'являється аж до за́ходу, так буде і при́хід Сина Лю́дського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 28, 'Бо де труп, — там зберуться орли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 29, 'І зараз, по скорботі тих днів, „сонце затьми́ться, і місяць не дасть свого світла“, і зорі попа́дають з неба, і сили небесні пору́шаться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 30, 'І того ча́су на небі з\'я́виться знак Сина Лю́дського, і тоді „заголосять всі зе́мні племе́на“, і побачать вони „Сина Лю́дського, що йтиме на хмарах небесних\" із великою поту́гою й славою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 31, 'І пошле анголі́в Своїх Він із голосним сурмови́м гуком, і зберуть Його ви́браних — „від вітрі́в чотирьох, від кінців неба аж до кі́нців його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 32, 'Від дерева ж фіґового навчіться при́кладу: коли віття його вже розпу́кується, і ки́неться листя, то ви знаєте, що близько вже літо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 33, 'Так і ви: коли все це побачите, знайте, що бли́зько, — під дверима!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 34, 'Поправді кажу́ вам: не пере́йде цей рід, аж усе оце станеться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 35, 'Небо й земля промине́ться, але не минуться слова́ Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 36, 'А про день той й годину не знає ніхто: ані анголи́ небесні, ані Син, — лише́ Сам Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 37, 'Як було за днів Но́євих, так буде і при́хід Сина Лю́дського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 38, 'Бо так само, як за днів до пото́пу всі їли й пили, женилися й заміж вихо́дили, аж до дня, „коли Ной увійшов до ковче́гу“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 39, 'і не знали, аж поки пото́п прийшов та й усіх забрав, — так буде і при́хід Сина Лю́дського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 40, 'Будуть двоє на полі тоді, — один ві́зьметься, а другий поли́шиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 41, 'Дві будуть молоти на жо́рнах, — одна ві́зьметься, а друга полишиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 42, 'Тож пильнуйте, бо не знаєте, котрого дня при́йде Господь ваш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 43, 'Знайте ж це, що коли б знав госпо́дар, о котрі́й сторожі при́йде зло́дій, то він пильнував би, і підкопа́ти свого дому не дав би.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 44, 'Тому бу́дьте готові й ви, — бо при́йде Син Лю́дський тієї години, коли ви не ду́маєте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 45, 'Хто ж вірний і мудрий раб, якого пан поставив над своїми челя́дниками давати своєчасно поживу для них?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 46, 'Блаженний той раб, що пан його при́йде та зна́йде, що робить він так!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 47, 'Поправді кажу́ вам, що над ці́лим маєтком своїм він поставить його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 48, 'А як той злий раб скаже у серці своїм: „Заба́риться пан мій прийти“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 49, 'і зачне бити товаришів своїх, а їсти та пити з п\'яни́цями,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 50, 'то пан того раба при́йде дня, якого він не сподівається, і о годині, якої не знає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 51, 'І він пополови́ні розі́тне його́, і визначить долю йому з лицемірами, — буде плач там і скре́гіт зубів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 1, 'Тоді Царство Небесне буде подібне до десяти дів, що побрали каганці́ свої, та й пішли зустріча́ти молодого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 2, 'П\'ять же з них нерозумні були, а п\'ять мудрі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 3, 'Нерозумні ж, узявши каганці́, не взяли́ із собою оливи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 4, 'А мудрі набрали оливи в посудинки ра́зом із своїми каганця́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 5, 'А коли забари́всь молодий, то всі задрімали й поснули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 6, 'А опі́вночі крик залуна́в: „Ось молодий, — виходьте назу́стріч!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 7, 'Схопи́лись тоді всі ті діви, і каганці́ свої наготува́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 8, 'Нерозумні ж сказали до мудрих: „Дайте нам із своєї оливи, бо наші каганці́ ось гаснуть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 9, 'Мудрі ж відповіли та сказали: „Щоб, бува, нам і вам не забракло, — краще вдайтеся до продавців, і купіть собі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 10, 'І як вони купувати пішли, то прибув молодий; і готові ввійшли на весі́лля з ним, — і за́мкнені двері були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 11, 'А по́тім прийшла й решта дів і казала: „Пане, пане, — відчини нам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 12, 'Він же в відповідь їм проказав: „Поправді кажу вам, — не знаю я вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 13, 'Тож пильнуйте, бо не знаєте ні дня, ні години, коли при́йде Син Лю́дський!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 14, 'Так само ж один чоловік, як відходив, покликав своїх рабів і передав їм добро своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 15, 'І одно́му він дав п\'ять талантів, а другому два, а тому один, — кожному за спромо́жністю його. І відійшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 16, 'А той, що взяв п\'ять талантів, негайно пішов і орудував ними, — і набув він п\'ять і́нших талантів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 17, 'Так само ж і той, що взяв два — і він ще два і́нших набув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 18, 'А той, що одно́го взя́в, пішов та й закопав його в землю, — і сховав срі́бло пана свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 19, 'По довгому ж часі вернувся пан тих рабів, та й від них зажадав обрахунку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 20, 'І прийшов той, що взяв п\'ять талантів, — приніс іще п\'ять талантів і сказав: „Пане мій, п\'ять талантів мені передав ти, — ось я здобу́в інші п\'ять талантів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 21, 'Сказав же йому його пан: „Гаразд, рабе добрий і вірний! Ти в мало́му був вірний, над великим поставлю тебе, — увійди до радощів пана свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 22, 'Підійшов же й той, що взяв два таланти, і сказав: „Два таланти мені передав ти, — ось іще два тала́нти здобу́в я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 23, 'Сказав йому пан його: „Гаразд, рабе добрий і вірний! Ти в мало́му був вірний, над великим поставлю тебе, — увійди до радощів пана свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 24, 'Підійшов же і той, що одного таланта взяв, і сказав: „Я знав тебе, па́не, що тверда́ ти люди́на, — ти жнеш, де не сіяв, і збираєш, де не розси́пав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 25, 'І я побоявся, — пішов і таланта твого сховав у землю. Ото маєш своє“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 26, 'І відповів його пан і сказав йому: „Рабе лукавий і лінивий! Ти знав, що я жну, де не сіяв, і збираю, де не розси́пав?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 27, 'Тож тобі було треба віддати гроші мої грошомінам, і, вернувшись, я взяв би з прибу́тком своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 28, 'Візьміть же від нього таланта, і віддайте тому́, що десять талантів він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 29, 'Бо кожному, хто має, дасться йому та й додасться, хто ж не має, — забереться від нього й те, що він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 30, 'А раба непотрібного вкиньте до зо́внішньої темряви, — буде плач там і скрегіт зубів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 31, 'Коли ж при́йде Син Лю́дський у славі Своїй, і всі анголи́ з Ним, тоді Він засяде на престолі слави Своєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 32, 'І перед Ним усі наро́ди зберуться, і Він відді́лить одного від о́дного їх, як відділя́є вівчар овець від козлів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 33, 'І поставить Він вівці право́руч Себе, а козлята — ліво́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 34, 'Тоді скаже Цар тим, хто право́руч Його: „Прийдіть, благословенні Мого Отця, посядьте Царство, уготоване вам від закла́дин світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 35, 'Бо Я голодував був — і ви нагодували Мене, пра́гнув — і ви напоїли Мене, мандрівником Я був — і Мене прийняли́ ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 36, 'Був наги́й — і Мене зодягли ви, слабував — і Мене ви відвідали, у в\'язни́ці Я був — і прийшли ви до Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 37, 'Тоді відповідя́ть Йому праведні й скажуть: „Господи, коли то Тебе ми голодного бачили — і нагодували, або спрагненого — і напоїли?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 38, 'Коли то Тебе мандрівником ми бачили — і прийняли́, чи наги́м — і зодягли?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 39, 'Коли то Тебе ми недужого бачили, чи в в\'язниці — і до Тебе прийшли?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 40, 'Цар відповість і промовить до них: „Поправді кажу́ вам: що́ тільки вчинили ви одно́му з найменших братів Моїх цих, — те Мені ви вчинили“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 41, 'Тоді скаже й тим, хто ліво́руч: „Ідіть ви від Мене, прокля́ті, у вічний огонь, що дияволові та його посланця́м пригото́ваний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 42, 'Бо Я голодував був — і не нагодували Мене, пра́гнув — і ви не напоїли Мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 43, 'мандрівником Я був — і не прийняли́ ви Мене, був наги́й — і не зодягли ви Мене, слабий і в в\'язниці — і Мене не відвідали ви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 44, 'Тоді відповідять і вони, промовляючи: „Господи, коли то Тебе ми голодного бачили, або спра́гненого, або мандрівником, чи наго́го, чи недужого, чи в в\'язниці — і не послужили Тобі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 45, 'Тоді Він відповість їм і скаже: „Поправді кажу вам: чого тільки одному з найменших цих ви не вчинили, — Мені не вчинили!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 46, 'І ці пі́дуть на вічную муку, а праведники — на вічне життя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 1, 'І сталось, коли закінчи́в Ісус усі ці слова, Він сказав Своїм учням:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 2, '„Ви знаєте, що через два дні буде Па́сха, — і Лю́дський Син буде виданий на розп\'я́ття“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 3, 'Тоді первосвященики, і книжники, і старші народу зібралися в домі первосвященика, званого Кайя́фою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 4, 'і радилися, щоб пі́дступом взяти Ісуса й забити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 5, 'І вони говорили: „Та не в свято, щоб бува колотнеча в наро́ді не сталась“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 6, 'Коли ж Ісус був у Віфа́нії, у домі Си́мона прокаже́ного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 7, 'підійшла одна жінка до Нього, маючи аляба́строву пляшечку дорогоцінного ми́ра, — і вилила на Його голову, як сидів при столі Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 8, 'Як побачили ж учні це, то обурилися та й сказали: „На́що таке марнотра́тство?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 9, 'Бо дорого можна було б це продати, і віддати убогим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 10, 'Зрозумівши Ісус, промовив до них: „Чого при́крість ви робите жінці? Вона ж добрий учинок зробила Мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 11, 'Бо вбогих ви маєте за́вжди з собою, а Мене не постійно ви маєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 12, 'Бо, виливши миро оце на тіло Моє, вона те вчинила на по́хорон Мій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 13, 'Поправді кажу́ вам: де тільки оця Єва́нгелія проповідувана буде в цілому світі, — на пам\'ятку їй буде сказане й те, що зробила вона!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 14, 'Тоді один із Дванадцятьох, званий Юдою Іскаріотським, подався до первосвящеників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 15, 'і сказав: „Що́ хочете дати мені, — і я вам Його видам?“І вони йому виплатили тридцять срібняків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 16, 'І він відтоді шукав слу́шного ча́су, щоб видати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 17, 'А першого дня Опрі́сноків учні підійшли до Ісуса й сказали Йому: „Де́ хочеш, щоб ми приготува́ли пасху спожити Тобі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 18, 'А Він відказав: „Ідіть до такого то в місто, і перекажіть йому: каже Вчитель: час Мій близьки́й, — справлю Пасху з Своїми учнями в тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 19, 'І учні зробили, як звелів їм Ісус, і зачали́ пасху готува́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 20, 'А коли настав вечір, Він із дванадцятьма учнями сів за стіл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 21, 'І, як вони споживали, Він сказав: „Поправді кажу вам, що один із вас видасть Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 22, 'А вони засмутилися тяжко, і кожен із них став питати Його: „Чи не я то, о Господи?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 23, 'А Він відповів і промовив: „Хто руку свою вмочить у миску зо Мною, той видасть Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 24, 'Людський Син справді йде, як про Нього написано; але горе тому чоловікові, що видасть Лю́дського Сина! Було́ б краще йому, коли б той чоловік не родився!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 25, 'Юда ж, зрадник Його, відповів і сказав: „Чи не я то, Учителю?“Відказав Він йому: „Ти сказав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 26, 'Як вони ж споживали, Ісус узяв хліб, і́ поблагословив, поламав, і давав Своїм учням, і сказав: „Прийміть, споживайте, це — тіло Моє“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 27, 'А взявши чашу, і подяку вчинивши, Він подав їм і сказав: „Пийте з неї всі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 28, 'бо це — кров Моя Ново́го Заповіту, що за багатьох проливається на відпу́щення гріхів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 29, 'Кажу́ ж вам, що віднині не питиму Я від оцього плоду виноградного аж до дня, коли з вами його нови́м питиму в Царстві Мого Отця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 30, 'А коли відспівали вони, то на го́ру Оливну пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 31, 'Промовляє тоді їм Ісус: „Усі ви через Мене споку́ситеся ночі цієї. Бо написано: „Уражу́ Па́стиря, — і розпоро́шаться вівці отари“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 32, 'По воскре́сенні ж Своїм Я вас ви́переджу в Галілеї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 33, 'А Петро відповів і сказав Йому: „Якби й усі спокуси́лись про Тебе, — я не спокушу́ся ніко́ли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 34, 'Промовив до нього Ісус: „Поправді кажу́ тобі, що ночі цієї, перше ніж заспіває півень, — відречешся ти тричі від Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 35, 'Говорить до Нього Петро: „Коли б мені навіть умерти з Тобою, — я не відречуся від Тебе!“Так сказали й усі учні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 36, 'Тоді з ними приходить Ісус до місцевости, званої Гефсима́нія, і промовляє до учнів: „Посидьте ви тут, аж поки піду́ й помолюся отам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 37, 'І, взявши Петра й двох синів Зеведе́євих, зачав сумувати й тужити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 38, 'Тоді промовляє до них: „Обго́рнена сумом смертельним душа Моя! Залиші́ться тут, і попильнуйте зо Мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 39, 'І, трохи далі пройшовши, упав Він долі́лиць, та молився й благав: „Отче Мій, коли можна, нехай обмине ця чаша Мене. Та проте, — не як Я хо́чу, а як Ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 40, 'І, вернувшись до учнів, знайшов їх, що спали, і промовив Петрові: „Отак, — не змогли ви й однієї години попильнувати зо Мною?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 41, 'Пильнуйте й моліться, щоб не впасти на спробу, — бадьо́рий бо дух, але немічне тіло“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 42, 'Відійшовши ще вдруге, Він молився й благав: „Отче Мій, як ця чаша не може минути Мене, щоб не пити її, — нехай станеться воля Твоя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 43, 'І, прийшовши, знову знайшов їх, що спали, бо зважні́ли їм очі були.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 44, 'І, залиши́вши їх, знов пішов, і помолився втре́тє, те саме слово промовивши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 45, 'Потому приходить до учнів і їм промовляє: „Ви ще далі спите й спочиваєте? Ось година набли́зилась, — і до рук грішникам виданий буде Син Лю́дський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 46, 'Уставайте, ходім, — ось наблизи́вся Мій зра́дник!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 47, 'І коли Він іще говорив, аж ось прийшов Юда, один із Дванадцятьо́х, а з ним люду багато від первосвящеників і старших наро́ду з мечами та ки́ями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 48, 'А зрадник Його дав був знака їм, кажучи: „Кого поцілую, то Він, — беріть Його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 49, 'І зараз Він підійшов до Ісуса й сказав: Раді́й, Учителю!“І поцілував Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 50, 'Ісус же йому відказав: „Чого, друже, прийшов ти?“Тоді приступили та руки наклали на Ісуса, — і схопи́ли Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 51, 'А ось один із тих, що з Ісусом були́, витягнув руку, і меча свого ви́хопив та й рубону́в раба первосвященика, — і відтяв йому вухо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 52, 'Тоді промовляє до нього Ісус: „Сховай свого меча в його місце, бо всі, хто ві́зьме меча, — від меча і загинуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 53, 'Чи ти ду́маєш, що не мо́жу тепер упросити Свого Отця, — і Він дасть Мені зараз більше дванадцяти леґіо́нів анголі́в?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 54, 'Але як має збутись Писа́ння, що так статися мусить?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 55, 'Тієї години промовив Ісус до наро́ду: „Немов на розбійника вийшли з мечами та ки́ями, щоб узяти Мене! Я щоденно у храмі сидів і навчав, — і Мене не взяли́ ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 56, 'Це ж сталось усе, щоб збулися писа́ння пророків“. Усі учні тоді залишили Його й повтікали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 57, 'А вони схопи́ли Ісуса, і повели́ до первосвященика Кайяфи, де зібралися книжники й старші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 58, 'Петро ж зда́лека йшов услід за Ним аж до дво́ру первосвященика, і, ввійшовши всере́дину, сів із слу́жбою, щоб бачити кінець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 59, 'А первосвященики та ввесь синедріо́н шукали на Ісуса неправдивого свідчення, щоб смерть заподіяти Йому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 60, 'і не знахо́дили, хоч кривосвідків багато підхо́дило. Аж ось накінець з\'явилися двоє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 61, 'і сказали: „Він говорив: Я можу зруйнувати храм Божий, — і за три дні збудувати його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 62, 'Тоді первосвященик устав і до Нього сказав: „Ти нічого не відповідаєш на те, що свідчать су́проти Тебе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 63, 'Ісус же мовчав. І первосвященик сказав Йому: „Заприсягаю Тебе Живим Богом, щоб нам Ти сказав, — чи Христос Ти, Син Божий?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 64, 'Промовляє до нього Ісус: „Ти сказав... А навіть повім вам: відтепе́р ви побачите Лю́дського Сина, що сидітиме право́руч сили Божої, і на хмарах небесних прихо́дитиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 65, 'Тоді первосвященик розде́р одежу свою та й сказав: „Він богознева́жив! На́що нам іще свідки потрібні? Ось ви чули тепер Його богознева́гу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 66, 'Як вам здається?“Вони ж відповіли та сказали: „Повинен умерти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 67, 'Тоді стали плювати на обличчя Йому, та бити по що́ках Його, інші ж ки́ями били,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 68, 'і казали: „Пророкуй нам, Христе́, хто́ то вдарив Тебе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 69, 'А Петро перед домом сидів на подвір\'ї. І приступила до Нього служни́ця одна та й сказала: „І ти був з Ісусом Галіле́янином!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 70, 'А він перед всіма́ відрікся, сказавши: „Не відаю я, що ти кажеш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 71, 'А коли до воріт він підхо́див, побачила інша його та й сказала приявним там людям: „Оцей був з Ісусом Назаряни́ном!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 72, 'І він зно́ву відрікся та став присягатись: „Не знаю Цього Чоловіка!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 73, 'Підійшли ж трохи згодом присутні й сказали Петрові: „І ти справді з отих, та й мова твоя виявляє тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 74, 'Тоді він став клясти́сь та божитись: „Не знаю Цього́ Чоловіка!“І заспівав півень хвилі тієї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 75, 'І згадав Петро сказане слово Ісусове: „Перше ніж заспіває півень, — відречешся ти тричі від Мене“. І, вийшовши звідти, він гірко заплакав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 1, 'А коли настав ра́нок, усі первосвященики й старші наро́ду зібрали нараду супроти Ісуса, щоб Йому заподіяти смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 2, 'І, зв\'язавши Його, повели́, та й По́нтію Пилату намісникові віддали́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 3, 'Тоді Юда, що ви́дав Його, як побачив, що Його засудили, розкаявся, і вернув тридцять срібнякі́в первосвященикам і старшим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 4, 'та й сказав: „Я згрішив, невинну кров ви́давши“. Вони ж відказали: „А нам що до того? Дивись собі сам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 5, 'І, кинувши в храм срібняки́, відійшов, а потому пішов, — та й повісився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 6, 'А первосвященики, як взяли срібняки́, то сказали: „Цього не годи́ться покласти до сховку церковного, — це ж бо заплата за кров“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 7, 'А порадившись, купили на них поле ганча́рське, щоб мандрівників ховати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 8, 'чому й зветься те поле „полем крови“аж до сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 9, 'Тоді справдилось те, що сказав був пророк Єремі́я, промовляючи: „І взяли вони тридцять срібнякі́в, заплату Оціненого, що Його оцінили сини Ізраїлеві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 10, 'і дали́ їх за поле ганча́рське, як Господь наказав був мені“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 11, 'Ісус же став перед намісником. І намі́сник Його запитав і сказав: „Чи Ти Цар Юдейський?“Ісус же йому відказав: „Ти кажеш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 12, 'Коли ж первосвященики й старші Його винуватили, Він нічо́го на те не відказував.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 13, 'Тоді каже до Нього Пила́т: „Чи не чуєш, — як багато на Тебе свідку́ють?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 14, 'А Він ні на одне слово йому не відказував, так що намісник був ду́же здивований.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 15, 'Мав же намісник звича́й відпускати на свято наро́дові в\'я́зня одно́го, котро́го хотіли вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 16, 'Був тоді в\'я́зень відо́мий, що звався Вара́вва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 17, 'І, як зібрались вони, то сказав їм Пилат: „Котрого бажаєте, щоб я вам відпустив: Варавву, чи Ісуса, що зветься Христос?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 18, 'Бо він знав, що Його через за́здрощі видали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 19, 'Коли ж він сидів на судде́вім сиді́нні, його дружи́на прислала сказати йому: „Нічо́го не май з отим Праведником, бо сьогодні вві сні я багато терпіла з-за Нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 20, 'А первосвященики й старші попідмовля́ли наро́д, щоб просити за Варавву, а Ісусові смерть заподі́яти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 21, 'Намісник тоді відповів і сказав їм: „Котро́го ж із двох ви бажаєте, щоб я вам відпустив?“Вони ж відказали: „Варавву“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 22, 'Пилат каже до них: „А що́ ж маю зробити з Ісусом, що зветься Христос?“Усі закричали: „Нехай ро́зп\'ятий бу́де!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 23, 'А намісник спитав: „Яке ж зло Він зробив?“Вони ж зачали́ ще сильніше кричати й казати: „Нехай ро́зп\'ятий буде!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 24, 'І, як побачив Пила́т, що нічо́го не вдіє, а неспо́кій ще більший стається, набрав він води, та й перед народом умив свої руки й сказав: „Я невинний у крові Його! Самі ви побачите“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 25, 'А ввесь наро́д відповів і сказав: „На нас Його кров і на наших дітей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 26, 'Тоді відпустив їм Варавву, а Ісуса, збичувавши, він видав, щоб ро́зп\'ятий був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 27, 'Тоді то намісникові вояки́, до прето́рія взявши Ісуса, зібрали на Нього ввесь відділ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 28, 'І, роздягнувши Його, багряни́цю наділи на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 29, 'І, сплівши з терни́ни вінка, покла́ли Йому на голову, а трости́ну в прави́цю Його. І, навко́лішки падаючи перед Ним, сміялися з Нього й казали: „Раді́й, Ца́рю Юдейський!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 30, 'І, плювавши на Нього, хапали тростину, та й по голові Його били.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 31, 'А коли назнущалися з Нього, зняли́ з Нього плаща́, і зодягнули в одежу Його. І повели́ Його на розп\'яття́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 32, 'А виходячи, стріли одного кіріне́янина, — Си́мон на йме́ння, — його змусили не́сти для Нього хреста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 33, 'І, прибувши на місце, що зветься Голго́фа, цебто сказати „Черепо́вище“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 34, 'дали́ Йому пити вина, із гірко́тою змішаного, — та, покуштувавши, Він пити не схотів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 35, 'А розп\'я́вши Його, вони поділили одежу Його, кинувши же́реба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 36, 'І, посідавши, стерегли́ Його там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 37, 'І напис провини Його помістили над Його головою: „Це Ісус, Цар Юдейський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 38, 'Тоді ро́зп\'ято з Ним двох розбійників: одного право́руч, а одного ліво́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 39, 'А хто побіч прохо́див, Його лихосло́вили та головами своїми хитали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 40, 'і казали: „Ти, що храма руйнуєш та за три дні будуєш, — спаси Само́го Себе! Коли Ти Божий Син, то зійди з хреста!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 41, 'Так само ж і первосвященики з книжниками та старши́ми, насміхаючися, говорили:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 42, '„Він інших спасав, — а Само́го Себе не може спасти́! Коли Цар Він Ізраїлів, нехай зі́йде тепер із хреста, — і ми повіримо Йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 43, 'Покладав Він надію на Бога, — нехай Той Його тепер визволить, якщо Він угодний Йому́. Бо Він говорив: „Я — Син Божий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 44, 'Також насміхалися з Нього й розбійники, що з Ним були ро́зп\'яті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 45, 'А від години шостої аж до години дев\'ятої — те́мрява сталась по ці́лій землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 46, 'А коло години дев\'ятої скрикнув Ісус гучни́м голосом, кажучи: „Елі́, Елі́, лама́ савахта́ні?“цебто: „Боже Мій, Боже Мій, на́що Мене Ти покинув?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 47, 'Дехто ж із тих, що стояли там, це почули й казали, що Він кличе Іллю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 48, 'А один із них зараз побіг і взяв гу́бку та, оцтом її напо́внивши, настромив на трости́ну й давав Йому пити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 49, 'Інші казали: „Чекай но, поба́чмо, — чи при́йде Ілля визволяти Його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 50, 'А Ісус знову голосом гучним скрикнув, — і духа віддав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 51, 'І ось заві́са у храмі роздерлась надво́є — від ве́рху аж додолу, і земля потрясла́ся, і зачали́ розпада́тися скелі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 52, 'і повідкривались гроби́, і повставало багато тіл спочилих святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 53, 'а з гробів повиходивши, по Його воскресінні, до міста святого ввійшли, і багатьо́м з\'явились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 54, 'А сотник та ті, що Ісуса з ним стерегли́, як землетруса побачили, і те, що там сталося, налякалися ду́же й казали: „Він був справді Син Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 55, 'Було там багато й жінок, що дивилися зда́лека, і що за Ісусом прийшли з Галілеї, і Йому прислуго́вували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 56, 'Між ними була́ Марія Магдалина, і Марія, мати Якова й Йо́сипа, і мати синів Зеведе́євих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 57, 'А коли настав вечір, то прийшов муж багатий із Аримате́ї, на ім\'я́ Йо́сип, що й сам був навчався в Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 58, 'Він прийшов до Пилата й просив тіла Ісусового. Пилат ізвелів тоді видати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 59, 'І взяв Йосип Ісусове тіло, обгорнув його в чисте полотно́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 60, 'і поклав його в гробі ново́му своїм, що був висік у скелі. До дверей гробови́х привалив він великого каменя, та й відійшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 61, 'Була́ ж там Марія Магдалина та інша Марія, що сиділи насу́проти гро́бу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 62, 'А наступного дня, що за п\'ятницею, до Пилата зібралися первосвященики та фарисеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 63, 'і сказали: „Пригадали ми, пане, собі, що обма́нець отой, як живий іще був, то сказав: „По трьох днях Я воскре́сну“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 64, 'Звели ж гріб стерегти аж до третього дня, щоб учні Його не прийшли, та й не вкрали Його, і не сказали наро́дові: Він із мертвих воскрес! І буде остання обмана гірша за першу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 65, 'Відказав їм Пилат: „Сторо́жу ви маєте, — ідіть, забезпечте, як знаєте“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 66, 'І вони відійшли, і, запеча́тавши каменя, біля гро́бу сторожу поставили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 1, 'Як минула ж субота, на світанку дня першого в тижні, прийшла Марія Магдалина та інша Марія побачити гріб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 2, 'І великий ось ставсь землетру́с, бо зійшов із неба Ангол Господній, і, приступивши, відвалив від гробу ка́меня, та й сів на ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 3, 'Його ж постать була́, як та бли́скавка, а шати його були білі, як сніг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 4, 'І від стра́ху перед ним затряслася сторо́жа, та й стала, як мертва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 5, 'А ангол озвався й промовив жінка́м: „Не лякайтеся, бо я знаю, що Ісуса розп\'я́того це ви шукаєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 6, 'Нема Його тут, — бо воскрес, як сказав. Підійдіть, — подивіться на місце, де знахо́дився Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 7, 'Ідіть же хутко, і скажіть Його у́чням, що воскрес Він із мертвих, і ото випере́джує вас в Галілеї, — там Його ви побачите. Ось, вам я звістив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 8, 'І пішли вони хутко від гро́бу, зо стра́хом і великою радістю, і побігли, щоб учнів Його сповістити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 9, 'Аж ось перестрів їх Ісус і сказав: „Ра́ді́йте!“Вони ж підійшли, обняли Його ноги і вклонились Йому до землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 10, 'Промовляє тоді їм Ісус: „Не лякайтесь! Ідіть, повідо́мте братів Моїх, — нехай вони йдуть у Галілею, — там побачать Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 11, 'Коли ж вони йшли, ось дехто зо сторожі до міста прийшли та й первосвященикам розповіли́ все, що́ сталось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 12, 'І, зібравшись зо старшими, вони врадили раду, і дали́ сторожі чимало срібняків,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 13, 'і сказали: „Розповідайте: Його учні вночі прибули́, — і вкрали Його, як ми спали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 14, 'Як почує ж намісник про це, то його ми перекона́ємо, і від клопоту ви́зволимо вас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 15, 'І, взявши вони срібняки́, зробили, як на́вчено їх. І проне́слося слово оце між юдеями, і трима́ється аж до сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 16, 'Одина́дцять же учнів пішли в Галілею на го́ру, куди звелів їм Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 17, 'І як вони Його вгледіли, поклонились Йому до землі, а дехто вагався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 18, 'А Ісус підійшов і промовив до них та й сказав: „Да́на Мені всяка вла́да на небі й на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 19, 'Тож ідіть, і навчі́ть всі наро́ди, христячи їх в їм\'я́ Отця, і Сина, і Святого Духа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 20, 'навчаючи їх зберігати все те, що Я вам заповів. І ото, Я перебува́тиму з вами повсякде́нно аж до кінця віку“! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Поча́ток Єва́нгелії Ісуса Христа, Сина Божого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Як у пророка Ісаї написано: „Ось перед обличчя Твоє посилаю Свого посланця́, який перед Тобою дорогу Твою приготу́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Голос того, хто кличе: У пустині готуйте дорогу для Господа, рівняйте стежки́ Йому!“—');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'виступив був так Іван, що в пустині христив та проповідував хрищення на покая́ння — для про́щення гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'І до нього прихо́дила вся країна Юдейська та всі єрусали́мляни, і в річці Йорда́ні від нього христились вони, і визнава́ли гріхи свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'А Іван зодягався в одежу з верблю́жого во́лосу, і мав пояс ремі́нний на сте́гнах своїх, а їв сарану́ та мед польови́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'І він проповідував, кажучи: „Услід за мною йде Поту́жніший від мене, що Йому я негідний, нагнувшись, розв\'язати ремінця́ від узуття Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Я христив вас водою, а Той вас христи́тиме Духом Святим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'І сталося тими днями, — прийшов Ісус з Назаре́ту Галілейського, і від Івана христився в Йорда́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'І зараз, коли Він виходив із води, то побачив Іван небо розкрите, і Духа, як голуба, що схо́див на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'І голос із неба почувся: „Ти Син Мій Улю́блений, що Я вподо́бав Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'І зараз повів Його Дух у пустиню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'І Він був сорок днів у пустині, випробо́вуваний від сатани́, і перебував зо звірино́ю. І служили Йому анголи́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'А коли Іван ви́даний був, то прийшов Ісус до Галілеї, і проповідував Божу Єва́нгелію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'і говорив: „Збулися часи, — і Боже Царство набли́зилось. Покайтеся, і віруйте в Єва́нгелію!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'А коли Він проходив біля Галіле́йського моря, то побачив Си́мона та Андрія, брата Си́монового, що не́вода в море закида́ли, — бо риба́лки були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'I сказав їм Ісус: „Ідіть услід за Мною, — і зроблю́, що станете ви ловця́ми людей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'І зараз вони свого не́вода кинули, — та й пішли вслід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, 'А коли недалеко прийшов, то побачив Він Якова Зеведе́євого та брата його Івана, що й вони в чо́вні не́вода ла́годили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, 'І зараз покликав Він їх. І вони залишили батька свого Зеведе́я в чо́вні з робі́тниками, — і пішли вслід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, 'І приходять вони в Капернау́м. І негайно в суботу ввійшов Він у синагогу, і навчати зачав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, 'І дивувались науці Його, бо навчав Він їх, як можновла́дний, а не як ті книжники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, 'І зараз у їхній синагозі знайшовся один чоловік, що мав духа нечистого, і він закричав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, 'і сказав: „Що́ Тобі до нас, Ісусе Назаряни́не? Ти прийшов погубити нас. Я знаю Тебе, хто́ Ти, — Божий Святий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 25, 'Ісус же йому заказав: „Замовчи, і вийди з нього!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 26, 'І затряс дух нечистий того, і, скрикнувши голосом гучни́м, вийшов із нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 27, 'І жахну́лися всі, — аж питали вони один о́дного, кажучи: „Що це таке? Нова наука із потугою! Навіть ду́хам нечистим наказує Він, — і вони Його слухають“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 28, 'І чутка про Нього пішла хвилі тієї по всій Галіле́йській країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 29, 'І вийшли вони із синагоги неба́вом, і прийшли з Яковом та Іваном до дому Си́монового й Андрієвого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 30, 'А те́ща Си́монова лежала в гаря́чці; і зараз сказали про неї Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 31, 'І Він підійшов і підвів її, узявши за руку, — і гаря́чка покинула ту, — і вона зачала́ прислуго́вувати їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 32, 'А як вечір настав, коли сонце зайшло, то стали прино́сити до Нього недужих усіх та біснува́тих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 33, 'І все місто зібралося перед двери́ма.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 34, 'І Він уздоро́вив багатьох, на різні хвороби недужих, і багатьох де́монів повиганяв. А демонам не дозволяв Він казати, що знають Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 35, 'А над ранком, як дуже ще темно було́, уставши, Він вийшов і пішов у місце самі́тне, і там молився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 36, 'А Си́мон та ті, що були з ним, поспішили за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 37, 'І, знайшовши Його, вони кажуть Йому: „Усі шукають Тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 38, 'А Він промовляє до них: „Ходім в інше місце, до сіл та око́лишніх міст, щоб і там проповідувати, бо на те Я прийшов“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 39, 'І пішов, і проповідував в їхніх синаго́гах по всій Галілеї. І демонів Він виганяв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 40, 'І приходить до Нього прокаже́ний, благає Його, і на коліна впадає та й каже Йому: „Коли хочеш, — Ти можеш очи́стити мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 41, 'І змилосе́рдився Він, — простяг руку Свою, і доторкнувся до нього, та й каже йому: „Хо́чу, — будь чистий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 42, 'І проказа зійшла з нього хвилі тієї, — і чистим він став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 43, 'А Він, погрози́вши йому, зараз вислав його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 44, 'і йому́ наказав: „Гляди, — не оповіда́й нічо́го ніко́му. Але йди, покажися священикові, і принеси за своє очи́щення, що Мойсей заповів, їм на свідо́цтво“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 45, 'А він, вийшовши, став багато оповіда́ти й говори́ти про поді́ю, так що Він не міг явно ввійти вже до міста, але перебува́в віддалік по самі́тних місцях. І схо́дилися звідусюди до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Коли ж Він по кількох днях прийшов знов до Капернау́му, то чутка пішла, що Він удома.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'І зібралось багато, аж вони не вміщалися навіть при две́рях. А Він їм виголошував слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'І прийшли ось до Нього, несучи розсла́бленого, якого не́сли четверо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'А що через наро́д до Ньо́го набли́зитися не могли, то стелю розкри́ли, де Він був, і пробравши, звісили ложе, що на ньому лежав розсла́блений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'А Ісус, віру їхню побачивши, каже розсла́бленому: „Відпускаються, сину, гріхи тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Там же сиділи дехто з книжників, і в серцях своїх ду́мали:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, '„Чого Він говорить отак? Зневажає Він Бога. Хто може прощати гріхи, окрім Бога Само́го?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'І зараз Ісус відчув Духом Своїм, що вони так міркують собі, і сказав їм: „Що́ таке ви в серцях своїх ду́маєте?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Що́ легше: сказати розсла́бленому: „Гріхи відпускаються тобі“, чи сказати: „Уставай, візьми ложе своє та й ходи“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Але щоб ви знали, що Син Лю́дський має вла́ду прощати гріхи на землі“, — каже розсла́бленому:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, '„Тобі Я наказую: Уставай, візьми ложе своє, та й іди у свій дім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'І той устав, і негайно взяв ложе, — і вийшов перед усіма́, так що всі дивувались і сла́вили Бога, й казали: „Ніко́ли такого не бачили ми!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'І вийшов над море Він знов. А ввесь на́товп до Нього прихо́див, — і Він їх навчав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'А коли Він прохо́див, то побачив Леві́я Алфі́євого, що сидів на ми́тниці, і каже йому: „Іди за Мною!“Той устав, і пішов услід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Коли ж Він сидів при столі́ в його домі, то багато ми́тників і грішників сиділи з Ісусом та з у́чнями Його; бо було їх багато, і вони ходили за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Як побачили ж книжники та фарисеї, що Він їсть із грішниками та з ми́тниками, то сказали до учнів Його: „Чому́ то Він їсть із ми́тниками та з грішниками?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'А Ісус, як почув, промовляє до них: „Лі́каря не потребують здорові, а слабі. Я не прийшов кликати праведних, але грішників (на покая́ння).“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'А учні Іванові та фарисейські по́стили. І приходять вони, та й говорять до Нього: „Чому́ учні Іванові та фарисейські по́стять, а учні Твої не по́стять?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Ісус же промовив до них: „Хіба по́стити можуть гості весільні, поки з ними ще є молоди́й? Доки мають вони молодо́го з собою, то по́стити не можуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Але при́йдуть ті дні, коли заберуть молодо́го від них, — то й по́стити бу́дуть вони за тих днів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'І не пришива́є ніхто до старої одежі ла́тки з сукна сирово́го, а як ні, то край ла́тки ново́ї оді́рветься там від старо́го, — і дірка стане ще гірша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'І ніхто не вливає вина молодого в старі бурдюки́, а то попрориває вино бурдюки, — і вино й бурдюки пропаду́ть, а вливають вино молоде до нови́х бурдюкі́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'І сталось, як Він перехо́див лана́ми в суботу, Його учні дорогою йшли, та й стали коло́сся зривати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Фарисеї ж казали Йому: Подивись, чому́ роблять у суботу вони, чого не годи́ться?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'А Він їм відказав: „Чи ж ви не читали ніко́ли, що зробив був Давид, як потребу він мав та сам зголоднів був і ті, що були з ним?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Як він увійшов був до Божого дому — за первосвященика Авіята́ра, — і спожив хліби показні́, яких їсти не можна було́, — тільки священикам, — і дав він і тим, хто був із ним?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 27, 'І сказав Він до них: „Субота постала для чоловіка, а не чоловік для суботи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 28, 'а тому то Син Лю́дський Господь і суботі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'І Він зно́ву до синагоги ввійшов. І був там один чоловік, який мав суху руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'І, щоб обвинуватити Його, наглядали за Ним, чи Він у суботу того не вздоро́вить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'І говорить Він до чоловіка з сухою рукою: „Стань посере́дині!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'А до них промовляє: „У суботу годи́ться робити добре, чи робити лихе, життя зберегти, чи погуби́ти?“Вони ж мовчали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'І спогля́нув Він із гнівом на них, засму́чений закам\'яні́лістю їхніх серде́ць, і сказав чоловікові: „Простягни свою руку!“І той простяг, — і рука йому стала здорова!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Фарисеї ж негайно пішли та з іродія́нами раду зробили на Нього, — як Його погубити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'А Ісус із Своїми у́чнями вийшов над море. І на́товп великий ішов вслід за Ним із Галілеї й з Юдеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'і з Єрусалиму, і з Ідуме́ї, і з-за Йорда́ння, і з Ти́ру й Сидо́ну. На́товп великий, прочувши, як багато чинив Він, зібрався до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'І сказав Він до у́чнів Своїх нагото́вити чо́вна Йому, через натовп, щоб до Нього не ти́снулись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Бо Він багатьох уздоро́вив, так що хто тільки не́мочі мав, то ти́слись до Нього, щоб Його доторкну́тись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'І ду́хи нечисті, як тільки вбачали Його, то падали ницьма перед Ним, і кричали й казали: „Ти Син Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'А Він їм суво́ро наказував, щоб вони Його не виявля́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'І Він вийшов на го́ру, і покликав, кого Сам хотів; вони ж приступили до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'І визначив Дванадцятьо́х, щоб із Ним перебува́ли, і щоб послати на проповідь їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'і щоб мали вони вла́ду вздоровля́ти неду́ги й виго́нити де́монів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'І визначив Він оцих Дванадцятьо́х: Си́мона, і дав йому ймення Петро,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'і Якова Зеведе́євого, і Івана, брата Якова, і дав їм імена Воанерге́с, цебто „сини гро́мові“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 18, 'і Андрія, і Пилипа, і Вартоломі́я, і Матві́я, і Хому́, і Якова Алфі́євого, і Таде́я, і Си́мона Канані́та');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 19, 'та Юду Іскаріо́тського, що й видав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 20, 'І приходять до дому вони. І знову зібралось наро́ду, що вони не могли навіть хліба з\'їсти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 21, 'І коли Його ближчі почули, то вийшли, щоб узяти Його, бо говорено, ніби Він несамови́тий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 22, 'А книжники, що поприхо́дили з Єрусалиму, казали: Має Він Вельзеву́ла, і виганяє де́монів силою князя де́монів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 23, 'І, закликавши їх, Він у при́тчах до них промовляв: „Як може сатана́ сатану́ виганяти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 24, 'І коли царство поділиться супроти себе, — не може всто́яти те царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 25, 'І коли дім поділиться супроти себе, — не може всто́яти той дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 26, 'І коли б сатана сам на се́бе повстав і поділився, то не зможе всто́яти він, але згине.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 27, 'Ніхто бо не може вде́ртись у дім дужого, та й пограбувати добро його, якщо перше не зв\'яже дужого, і аж тоді пограбує госпо́ду його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 28, 'Поправді кажу́ вам, що про́стяться лю́дським синам усі про́гріхи та богозневаги, хоч би як вони богозневажали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 29, 'Але, хто богознева́жить Духа Святого, — повіки йому не відпуститься, але́ гріху вічному він підпадає“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 30, 'Бож казали вони: „Він духа нечистого має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 31, 'І поприхо́дили мати Його та брати Його, і, о́сторонь ставши, послали до Нього і Його виклика́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 32, 'А наро́д кругом Нього сидів. І сказали Йому: „Ото мати Твоя, і брати Твої, і се́стри Твої он про Тебе питаються о́сторонь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 33, 'А Він їм відповів і сказав: „Хто́ Моя мати й брати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 34, 'І поглянув на тих, що круг Нього сиділи, і промовив: „Ось мати Моя та бра́ття Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 35, 'Бо хто Божу волю чинитиме, то́й Мені брат, і сестра, і мати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'І знову почав Він навчати над морем. І зібралось до Нього багато наро́ду, так що Сам Він до чо́вна на морі ввійшов і сидів, а наро́д увесь був на землі покрай моря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'І багато навчав Він їх при́тчами, і в науці Своїй їм казав:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, '„Слухайте, — вийшов сіяч ось, щоб сі́яти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'І як сі́яв, упало зе́рно одне край дороги, — і налетіли пташки́, і його́ повидзьо́бували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Друге ж упало на ґрунт кам\'яни́стий, де не мало багато землі, — і негайно зійшло, бо земля неглибока була́;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'а як сонце зійшло — то зів\'я́ло, і, коріння не мавши, усохло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'А інше впало між те́рен, і ви́гнався терен, і його поглуши́в, — і пло́ду воно не дало́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Інше ж упало на добрую землю, — і дало плід, що посхо́див і ріс; і видало втри́дцятеро, у шістдеся́т і в сто раз “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'І сказав: „Хто має ву́ха, щоб слухати, — нехай слухає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'І, як остався Він насамоті, Його запитали найближчі з Дванадцятьма́ про цю при́тчу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'І Він їм відповів: „Вам да́но пізнати таємни́ці Божого Царства, а тим, що за вами, усе відбувається в при́тчах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'щоб „оком дивились вони — і не бачили, ву́хом слухали — і не зрозуміли, щоб коли вони не наверну́лися, і відпу́щені бу́дуть гріхи їм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'І Він їх запитав: „Ви не розумієте притчі цієї? І як вам зрозуміти всі притчі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Сіяч сіє слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'А котрі́ край дороги, де сіється слово, — це ті, що як тільки почують, то зараз приходить до них сатана, і забирає слово, посіяне в них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Так само й посіяні на кам\'яни́стому ґрунті, — вони, як почують те слово, то з радістю зараз приймають його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'та коріння не мають у собі й непостійні; а зго́дом, як у́тиск або переслі́дування наступає за слово, вони спокушаються зараз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'А між терен посіяне, — це ті, що слухають слово,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'але кло́поти цьогосві́тні й омана багатства та різні бажа́ння ввіходять, та й заглушують слово, — і пло́ду воно не дає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'А посіяне в добрую землю — це ті, що слухають слово й приймають, — і родять утри́дцятеро, у шістдеся́т і в сто раз “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'І сказав Він до них: „Чи світло прино́сять на те, щоб поставити його під посу́дину, чи може під ліжко? А не щоб поставити на світи́льнику?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Бо немає нічого захованого, що не ви́явиться, і немає таємного, що не вийде ная́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 23, 'Хто має ву́ха, щоб слухати, — нехай слухає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 24, 'І сказав Він до них: „Уважайте, що чуєте: Якою мірою будете міряти, такою відмі́ряють вам, і додаду́ть вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 25, 'Бо хто має, то дасться йому, хто ж не має, — забереться від нього й те, що він має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 26, 'І сказав Він: „Так і Боже Царство, як той чоловік, що кидає в землю насі́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 27, 'і чи спить, чи встає він удень та вночі, а насіння пускає па́ростки та росте, хоч не знає він, я́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 28, 'Бо родить земля сама з себе: перше вру́на, потім ко́лос, а тоді повне збіжжя на колосі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 29, 'А коли плід доспіє, зараз він „посилає серпа́, бо настали жнива́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 30, 'І сказав Він: „До чого прирівняємо Царство Боже? Або в якій притчі предста́вим його́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 31, 'Воно — як те зе́рно гірчи́чне, яке, коли сіється в землю, найдрібніше за всі зе́мні насіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 32, 'Як посіяне ж буде, вироста́є, і стає над усі зілля́ більше, і ві́ття пускає велике таке́, що ку́блитись може в тіні його птаство небесне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 33, 'І такими притчами багатьома́ Він їм слово звіщав, поскільки вони могли слухати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 34, 'І без притчі нічого Він їм не казав, а учням Своїм самотою вияснював усе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 35, 'І сказав Він до них того дня, коли вечір настав: „Перепли́ньмо на той бік“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 36, 'І, лишивши наро́д, узяли із собою Його, як у чо́вні Він був; і інші човни́ були з Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 37, 'І зняла́ся ось буря велика, а хвилі вливалися в чо́вен, аж чо́вен водою вже був перепо́внився!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 38, 'А Він спав на кормі́ на подушці... І вони розбудили Його та й сказали Йому: „Учителю, чи Тобі байдуже́, що ми гинемо?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 39, 'Тоді Він устав, і вітрові заборонив, і до моря сказав: „Мовчи, перестань!“І стих вітер, — і тиша велика настала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 40, 'І сказав Він до них: „Чого́ ви такі полохливі? Чому віри не маєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 41, 'А вони налякалися стра́хом великим, і говорили один до одно́го: „Хто ж це такий, що вітер і море слухня́ні Йому?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 1, 'І на другий бік моря вони прибули́, до землі Гадари́нської.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 2, 'І як вийшов Він із чо́вна, то зараз Його перестрів чоловік із могильних пече́р, що мав духа нечистого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 3, 'Він ме́шкання мав у гроба́х, і ніхто й ланцюга́ми зв\'язати не міг його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 4, 'бо часто кайда́нами та ланцюга́ми в\'язали його, але він розривав ланцюги́ та кайда́ни торо́щив, — і ніхто не міг угамува́ти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 5, 'І він повсякча́с перебува́в день і ніч у гроба́х та в гора́х, — і кричав, і бився об камі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 6, 'А коли він Ісуса побачив здале́ка, то прибіг, і вклонився Йому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 7, 'і закричав гучни́м голосом, кажучи: „Що до мене Тобі, Ісусе, Сину Бога Всеви́шнього? Богом Тебе заклинаю, — не муч Ти мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 8, 'Бо сказав Він йому: „Вийди, ду́ше нечистий, із люди́ни!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 9, 'І запитав Він його: „Як тобі на ім\'я́?“А той відповів: „Леґіо́н мені йме́ння — багато бо нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 10, 'І він Його ду́же просив, щоб їх не висилав із тієї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 11, 'Пасся ж там на горі гурт великий свине́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 12, 'І просилися де́мони, кажучи: „Пошли нас у свине́й, щоб у них ми ввійшли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 13, 'І дозволив Він їм. І повихо́дили духи нечисті, і в свиней увійшли́. І гурт кинувся з кручі до моря, — а було зо дві тисячі їх — і вони потопилися в морі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 14, 'А їхні пастухи повтікали та в місті й по селах звістили. І повихо́дили люди побачити, що́ сталось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 15, 'І прийшли до Ісуса й побачили, що той біснуватий, що мав леґіо́на, убра́ний сидів, і при умі, — і полякались вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 16, 'Самови́дці ж їм розповіли́, що́ сталося з тим біснуватим, також про свиней.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 17, 'І вони стали благати Його, щоб пішов Собі з їхнього кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 18, 'А як Він сів до чо́вна, то біснуватий став просити Його, щоб залиши́тися з Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 19, 'Ісус же йому не дозволив, а промовив до нього: „Іди до дому свого, до своїх, і їм розпові́ж, які речі великі Госпо́дь учинив тобі, і як змилувався над тобою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 20, 'І пішов він та в Десятимісті зачав пропові́дувати, які речі великі Ісус учинив йому. І всі дивувались!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 21, 'І коли переплив Ісус чо́вном на то́й бік ізнов, то до Нього зібралось багато наро́ду. І був Він над морем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 22, 'І приходить один із старши́х синагоги, на ймення Яі́р, і, як побачив Його, припадає до ніг Йому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 23, 'і ду́же благає Його та говорить: „Моя дочка́ кінча́ється. Прийди ж, поклади Свої руки на неї, щоб видужала та жила́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 24, 'І пішов Він із ним. За Ним на́товп великий ішов, і тиснувсь до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 25, 'А жінка одна, що дванадцять ро́ків хворою на кровоте́чу була́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 26, 'що чимало нате́рпілася від багатьох лікарів, і витратила все добро своє, та ніякої помочі з того не мала, а прийшла ще до гіршого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 27, 'як зачула вона про Ісуса, підійшла через на́товп ізза́ду, і доторкну́лась до одежі Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 28, 'Бо вона говорила про себе: „Коли хоч доторкнусь до одежі Його, то оду́жаю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 29, 'І висохло хвилі тієї джерело́ кровотечі її, і тілом відчула вона, що видужала від неду́ги!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 30, 'І в ту мить Ісус вичув у Собі, що вийшла з Нього сила. І Він до наро́ду звернувся й спитав: „Хто́ доторкнувсь до Моєї одежі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 31, 'І відказали Йому Його учні: „Ти бачиш, що тисне на Тебе наро́д, а питаєшся: Хто́ доторкнувся до Мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 32, 'А Він навкруги́ поглядав, щоб побачити ту, що зробила оце.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 33, 'І жінка злякалась та затрусилась, бо знала, що сталося їй. І вона підійшла, і впала ницьма перед Ним, — і всю правду Йому розпові́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 34, 'А Він їй сказав: „Твоя віра, о до́чко, спасла тебе; іди з ми́ром, і здоровою будь від своєї неду́ги!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 35, 'Як Він ще говорив, приходять ось від старшини́ синагоги та й кажуть: „Дочка́ твоя вмерла; чого ще турбуєш Учителя?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 36, 'А Ісус, як почув слово сказане, промовляє до старшини́ синагоги: „Не лякайсь, — тільки віруй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 37, 'І Він не дозволив іти за Собою ніко́му, тільки Петрові та Якову, та Іванові, братові Якова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 38, 'І приходять у дім старшини́ синаго́ги, і Він бачить метушню́ та людей, що плакали та голоси́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 39, 'А ввійшовши, сказав Він до них: „Чого ви мету́шитеся та плачете? Не вмерло дівча́, але спить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 40, 'І вони насміхалися з Нього. А Він усіх ви́провадив, узяв батька дівчати та матір, та тих, хто був із Ним, і ввійшов, де лежало дівча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 41, 'І взяв Він за руку дівча та й промовив до нього: „Таліта́, ку́мі“що значить: „Дівча́тко, кажу́ тобі — встань!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 42, 'І в ту мить підвелося й ходило дівча́; а ро́ків мало з дванадцять. І всі зараз жахнулися з дива великого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 43, 'А Він наказав їм суво́ро, щоб ніхто не довідавсь про це. І дати їй їсти звелів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 1, 'І, вийшовши звідти, Він прийшов до Своєї ба́тьківщини, а за Ним ішли учні Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 2, 'Як настала ж субота, Він навчати почав у синаго́зі. І багато-хто, чувши, дивуватися стали й питали: „Звідки в Нього оце? І що за мудрість, що да́на Йому? І що за чуда, що стаються руками Його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 3, 'Хіба ж Він не те́сля, син Маріїн, брат же Якову, і Йо́сипу, і Юді та Си́монові? А се́стри Його хіба тут не між нами?“І вони спокуша́лися Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 4, 'А Ісус їм сказав: „Пророка нема без пошани, — хіба тільки в вітчи́зні своїй, та в родині своїй, та в домі своїм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 5, 'І Він тут учинити не міг чуда жодного, тільки деяких хворих, руки поклавши на них, уздорови́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 6, 'І Він дивувавсь їх невірству. І ходив Він по се́лах навкру́г та навчав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 7, 'І, закликавши Дванадцятьо́х, зачав їх по двох посилати, і вла́ду їм дав над нечистими ду́хами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 8, 'І звелів їм нічого в дорогу не брати, крім па́лиці тільки самої: ні то́рби, ні хліба, ані мідякі́в у свій че́рес,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 9, 'а ходити в санда́лях, „і двох убрань не носити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 10, 'І промовив до них: „Коли ви де вві́йдете в дім, залиша́йтеся там, аж поки не вийдете звідти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 11, 'А як місто яке вас не при́йме, і не послухають вас, то, виходячи звідти, обтрусіть порох, що в вас під ногами, на сві́дчення супроти них. Поправді кажу́ вам, — легше бу́де Содо́му й Гомо́ррі дня судного, аніж місту тому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 12, 'І вийшли вони, і проповідували, щоб ка́ялися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 13, 'І багато виго́нили де́монів, і оливою хворих багато нама́щували — і вздоровляли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 14, 'І прочув про Ісуса цар І́род, — бо ім\'я́ Його стало зага́льно відо́ме, — і сказав, що то Іван Христитель із мертвих воскрес, і тому тво́ряться чу́да від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 15, 'Інші впевня́ли, що Ілля Він, а знов інші казали, що пророк, або як один із пророків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 16, 'А Ірод, прочувши, сказав: „Іван, якому я голову стяв був, — оце він воскрес!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 17, 'Той бо Ірод, пославши, схопи́в був Івана, і в в\'язниці закув його, через Іродія́ду, дружи́ну брата свого Пилипа, бо він одружи́вся був із нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 18, 'Бо Іван казав Іродові: „Не годи́ться тобі мати за дружину жінку брата свого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 19, 'А Іродія́да лю́тилась на нього, і хотіла йому смерть заподіяти, та не могла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 20, 'Бо Ірод боявся Івана, знавши, що він муж праведний і святий, і беріг його. І, його слухаючи, він дуже бенте́жився, але слухав його залюбки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 21, 'Та настав день догі́дний, коли дня наро́дження Ірод справляв був бенке́та вельмо́жам своїм, і тисячникам, і галілейській старши́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 22, 'і коли прийшла дочка́ тієї Іродіяди, і танцювала, і сподо́балася Іродові та присутнім із ним при столі, — тоді цар промовив до дівчини: „Проси в мене, чого хочеш, — і дам я тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 23, 'І поклявся він їй: „Чого тільки від ме́не попросиш, то дам я тобі, — хоча б і півцарства мого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 24, 'Вона ж вийшла, і спиталася матері своєї: „Чого маю просити?“А та відказала: „Голови Івана Христителя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 25, 'І зараз квапли́во вернулась вона до царя, і просила, говорячи: „Я хочу, щоб дав ти негайно мені на полу́миску голову Івана Христителя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 26, 'І засмутився цар, але через клятву й з-за тих, що з ним були́ при столі́, не схотів їй відмовити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 27, 'І цар зараз послав вояка́, і звелів прине́сти Іванову голову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 28, 'І пішов він, і стяв у в\'язниці Івана, і приніс його го́лову на полу́мискові, і дівчаті віддав, а дівча віддало́ її своїй матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 29, 'А коли його учні зачули, то прийшли, і взяли його тіло, і до гро́бу поклали його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 30, 'І посхо́дилися до Ісуса апо́столи, і розповіли́ Йому все, — як багато зробили вони, і як багато навчили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 31, 'І сказав Він до них: „Ідіть осібно самі до безлю́дного місця, та трохи спочиньте“. Бо багато народу прихо́дило та відбувало, аж навіть не мали коли й поживитись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 32, 'І відпливли́ вони чо́вном окремо до місця безлю́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 33, 'І побачили їх, коли пли́нули, і багато-хто їх розпізнали. І пі́шки побігли туди з усіх міст, та й їх ви́передили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 34, 'І, як вийшов Ісус, Він побачив багато наро́ду, — і зми́лувався над ними, бо були, „немов вівці, що не мають пастуха“. І зачав їх багато навчати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 35, 'І, як минуло вже ча́су доволі, підійшли Його учні до Нього та й кажуть: „ Це місце безлю́дне, а година вже пізня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 36, 'Відпусти їх, — нехай пі́дуть в оса́ди та се́ла близькі́, і куплять собі чого їсти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 37, 'А Він відповів і сказав їм: „Дайте їсти їм ви́“. Вони ж відказали Йому: „Чи ми маємо піти та хліба купити на двісті дина́ріїв, і дати їм їсти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 38, 'А Він їх запитав: „Скільки маєте хліба? Ідіть, побачте!“І розізнавши, сказали: „П\'ять хлібі́в та дві рибі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 39, 'І звелів їм усіх на зеленій траві посадити один біля о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 40, 'І розсілись рядами вони, по сто та по п\'ятдеся́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 41, 'І Він узяв п\'ять хлібів та дві риби, споглянув на небо, поблагословив, і поламав ті хліби́, і дав учням, щоб клали перед ними, і дві риби на всіх поділив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 42, 'І всі їли й наїлися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 43, 'А з кусків позосталих та з риб назбирали дванадцять повних кошів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 44, 'А тих, хто хліб споживав, було тисяч із п\'ять чоловіка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 45, 'І зараз звелів Своїм у́чням до чо́вна сідати, і на то́й бік попли́нути до Віфсаїди, раніше Його, поки Сам Він відпустить наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 46, 'І Він їх відпустив, та й пішов помолитись на го́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 47, 'А як вечір настав, чо́вен був серед моря, а Він Сам один на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 48, 'Коли ж Він побачив, як вони веслува́нням мордуються, — бо вітер їм був супроти́вний, — о четвертій сторо́жі вночі підійшов Він до них, по морю йдучи́, і хотів їх минути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 49, 'А вони, як побачили, що йде Він по морю, поду́мали, що то мара́, та й стали кричати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 50, 'бо Його всі побачили та налякались. А Він зараз до них обізвався й сказав їм: „Будьте смілі, — це Я, не лякайтесь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 51, 'І ввійшов Він у чо́вен до них, і вітер затих. А вони здивувалися ду́же в собі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 52, 'бо не зрозуміли чуда про хліби́, бо серце їхнє було затверділе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 53, 'Перепливши ж вони, прибули́ в землю Генісаре́тську й прича́лили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 54, 'І, як вони повихо́дили з чо́вна, люди зараз пізнали Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 55, 'і порозбігались по всій тій околиці, і стали на ложах недужих прино́сити, де тільки прочули були, що Він є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 56, 'І куди тільки Він прибував — до сіл, чи до міст, чи до осе́ль, — клали недужих на майда́нах, і благали Його, щоб могли доторкну́тись хоч краю одежі Його. І хто тільки до Нього дото́ркувався, той був уздоро́влений!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 1, 'І зібрались до Нього фарисеї та деякі з книжників, які прибули́ із Єрусалиму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 2, 'і побачили, що деякі з учнів Його їли хліб руками „нечистими“, цебто невмитими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 3, 'Бо фарисеї й усі юдеї, зберігаючи переда́ння старших, не їдять, як старанно не вимиють рук;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 4, 'а вернувшися з ринку, вони не їдять, поки не вмиються. Багато є й іншого, що вони прийняли́, щоб доде́ржувати: миття чаш, і глеків, і мідяно́го по́суду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 5, 'І запитали Його фарисеї та книжники: „Чому учні Твої не живуть за переда́нням старших, але хліб споживають руками нечистими?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 6, 'А Він їм відказав: „Добре пророкував про вас, лицемірів, Ісая, як написано: „Оці люди устами шанують Мене, серце ж їхнє далеко від Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 7, 'Та однак надаре́мне шанують Мене, бо навчають наук — лю́дських за́повідей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 8, 'Занеха́явши заповідь Божу, передань людськи́х ви трима́єтесь: обмиваєте глеки та чаші, і багато такого подібного й іншого робите ви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 9, 'І сказав Він до них: „Спритно відкидаєте ви заповідь Божу, аби зберегти своє переда́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 10, 'Бо Мойсей наказав: „Шануй батька свого та матір свою“, та: „Хто злорічить на батька чи матір, нехай смертю помре“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 11, 'А ви кажете: „Коли скаже хто батьку чи матері: Корва́н, чи дар Богові те, чим би ти скориста́тись від мене хотів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 12, 'то вже вільно йому не робити нічого для батька чи матері,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 13, 'порушуючи Боже Слово вашим переда́нням, що його ви самі встановили. І багато такого ви іншого робите“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 14, 'І Він зно́ву покликав наро́д і промовив до нього: „Послухайте Мене всі, і зрозумійте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 15, 'Немає нічого назо́вні люди́ни, що, увіходячи в неї, могло б опога́нити її; що ж із неї виходить, — те люди́ну опога́нює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 16, 'Коли має хто ву́ха, щоб слухати, — нехай слу́хає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 17, 'А коли від наро́ду ввійшов Він до дому, тоді учні Його запиталися в Нього про при́тчу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 18, 'І Він їм відказав: „Чи ж і ви розумі́ння не маєте? Хіба ж не розумієте ви, що все те, що входить іззо́вні в люди́ну, — не може опога́нити її?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 19, 'Бо не входить до серця йому, але до живота́, і виходить назо́вні, очищуючи всяку ї́жу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 20, 'А далі сказав Він: „Що з люди́ни виходить, — те́ люди́ну опога́нює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 21, 'Бо зсере́дини, із лю́дського серця виходять лихі думки́, розпуста, краді́ж, душогу́бства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 22, 'пере́люби, зди́рства, лукавства, пі́дступ, безстидства, завидю́щеє око, богозневага, го́рдощі, бе́зум.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 23, 'Усе зле це виходить зсере́дини, — і люди́ну опога́нює!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 24, 'І встав Він, і звідти пішов у землю ти́рську й сидонську. І, ввійшовши до дому, Він хотів, щоб ніхто не довідавсь, та не міг утаїтись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 25, 'Негайно бо жінка одна, якої дочка мала духа нечистого, прочула про Нього, і прийшла, та й припала до ніг Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 26, 'А ця жінка греки́ня була́, родом сирофінікі́янка. Вона стала благати Його, щоб із дочки́ її де́мона вигнав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 27, 'А Він їй сказав: „Дай, щоб перше наїлися діти, — не годиться бо хліб забирати в дітей, і кинути щеня́там!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 28, 'А вона Йому в відповідь каже: „Так, Господи! Але навіть щеня́та їдять під столом від дитячих кришо́к“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 29, 'І Він їй сказав: „За слово оце йди собі, — де́мон вийшов із твоєї дочки́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 30, 'А коли вона в дім свій верну́лась, то знайшла, що дочка́ на постелі лежала, а демон вийшов із неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 31, 'І вийшов Він знов із країв ти́рських і сидо́нських, і́ подався шляхом на Сидо́н над море Галілейське, через око́лиці Десятимі́стя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 32, 'І приводять до Нього глухого немову, і благають Його, щоб руку на нього поклав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 33, 'І взяв Він його від наро́ду само́го, і вклав пальці Свої йому в ву́ха, і, сплюнувши, доторкнувся його язика́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 34, 'І, на небо спогля́нувши, Він зідхнув і промовив до нього: „Еффата́“; цебто: „Відкрийся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 35, 'І відкрилися ву́ха йому, і путо його язика розв\'яза́лось негайно, — і він став говорити вира́зно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 36, 'А Він їм звелів, щоб нікому цього не розповіда́ли. Та що більше наказував їм, то ще більш розголо́шували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 37, 'І ду́же всі дивувалися та говорили: „Він добре все робить: глухим дає чути, а німим — говорити!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 1, 'Тими днями, коли було зно́ву багато наро́ду, а їсти не мали чого́, покликав Він у́чнів Своїх та й промовив до них:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 2, '„Жаль мені тих людей, що вже три дні зо Мною знахо́дяться, та їсти не мають чого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 3, 'А коли відпущу́ їх голодних до їхніх домівок, то осла́бнуть у дорозі, бо деякі з них поприхо́дили зда́лека“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 4, 'І відказали Йому Його у́чні: „Звідки зможе хто нагодувати їх хлібом отут у пустині?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 5, 'А Він їх запитав: „Скільки маєте хліба?“Вони ж повідо́мили: „Се́меро“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 6, 'Тоді Він народу звелів на землі посідати. І, взявши се́меро хліба, віддавши подяку, Він поламав і дав учням Своїм, щоб роздати. А вони роздавали наро́дові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 7, 'І мали вони трохи ри́бок; і Він їх поблагословив, і роздати звелів також їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 8, 'І всі їли й наїлися, а з позосталих кусків сім коші́в назбирали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 9, 'А їдців було тисяч з чотири!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 10, 'І всів Він негайно до чо́вна з Своїми у́чнями, та й прибув до землі далману́тської.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 11, 'І вийшли фарисеї, і почали́ сперечатися з Ним, і, Його випробо́вуючи, хотіли від Нього озна́ки із неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 12, 'А Він тяжко зідхнув у Своїм дусі й промовив: „Якої ознаки цей рід вимагає? Поправді кажу́ вам, що родові цьому ознака не буде дана!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 13, 'І покинув Він їх, усів знову до чо́вна, і на то́й бік відбу́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 14, 'І забули вони взяти хліба, і крім одно́го буханця́, у чо́вні не мали з собою нічого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 15, 'А Він їм наказував та говорив: „Стережіться уважливо фарисейської розчи́ни й розчини Іродової!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 16, 'Вони ж міркували й казали один до одного, що хліба не мають вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 17, 'А Ісус, знавши те, промовляє до них: „Чого́ ви міркуєте, що хліба не маєте? Чи ви ще не знаєте й не розумієте? Чи ще маєте серце своє затверді́лим?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 18, '„Мавши очі — не бачите, і мавши ву́ха — не чуєте?“І не пам\'ятаєте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 19, 'коли п\'ять хлібів Я ламав на п\'ять тисяч, — скільки повних коші́в із кусків ви зібрали?“Вони кажуть до Нього: „Дванадцять“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 20, '„А як сім на чотири тисячі, — скільки кошиків повних з кусків ви зібрали?“І відказують: „Сім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 21, 'І сказав Він до них: „Ви ще не розумієте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 22, 'І приходять вони в Віфсаї́ду. І приводять до Нього сліпого, і благають Його, щоб доторкну́вся до нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 23, 'І взяв Він сліпого за руку, та й вивів його за село. І посли́нивши очі йому, поклав руки на нього, і питався його, чи що бачить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 24, 'І, зиркнувши, сказав той: „Я бачу людей, які ходять, немов би дере́ва“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 25, 'Потім знов Він поклав Свої руки на очі йому, — і прозрі́в той, і одужав, і вира́зно став бачити все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 26, 'І послав Він додому його й наказав: „До села й не заходь, і ніко́му в селі не розповіда́й!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 27, 'Потому пішов Ісус й у́чні Його до сіл Кесарі́ї Пилипової, а в дорозі питав Своїх у́чнів, говорячи їм: „За кого Мене люди вважають?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 28, 'Вони ж відповіли́ Йому, кажучи: „За Івана Христителя, другі — за Іллю́, а інші — за одно́го з пророків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 29, 'І Він запитав їх: „А ви за кого Мене маєте?“Петро Йому в відповідь каже: „Ти — Христос!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 30, 'І Він заборонив їм, щоб ніко́му про Нього вони не казали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 31, 'І почав їх навчати, що Синові Лю́дському треба багато страждати, і Його відцураються старші, і первосвященики, і книжники, і Він буде вбитий, — але третього дня Він воскресне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 32, 'І те слово казав Він відкрито. А Петро узяв на́бік Його, і Йому́ став перечити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 33, 'А Він обернувся й поглянув на у́чнів Своїх, та й Петру докори́в і сказав: „Відступись, сатано, від Мене, бо ду́маєш ти не про Боже, а про лю́дське!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 34, 'І Він покликав народ із Своїми у́чнями, та й промовив до них: „Коли хоче хто йти вслід за Мною, хай зречеться самого себе, і хай ві́зьме свого хреста та й за Мною йде!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 35, 'Бо хто хоче душу свою́ зберегти, той погубить її, а хто згубить душу свою ради Мене та Єва́нгелії, той її збереже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 36, 'Яка ж ко́ристь люди́ні, що здобу́де ввесь світ, але душу свою занапа́стить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 37, 'Або що́ назамі́н дасть люди́на за душу свою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 38, 'Бо хто буде Мене та Моєї науки соро́митися в роді цім перелю́бнім та грішнім, того посоро́миться також Син Лю́дський, як при́йде у славі Свого Отця з ангола́ми святими“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 1, 'І сказав Він до них: „Поправді кажу́ вам, що деякі з тут-о прия́вних не скушту́ють смерти, аж поки не ба́читимуть Царства Божого, що прийшло́ воно в силі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 2, 'А через шість день забирає Ісус Петра, і Якова, і Івана, та й веде їх осібно на го́ру високу самих. І Він переобрази́всь перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 3, 'І стала одежа Його осяйна́, дуже біла, як сніг, якої біли́льник не зміг би так ви́білити на землі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 4, 'І з\'явивсь їм Ілля́ та Мойсей, і розмовляли з Ісусом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 5, 'І озвався Петро та й сказав до Ісуса: „Учителю, до́бре бути нам тут! Поставмо ж собі три шатра: для Тебе одне, і одне для Мойсея, і одне для Іллі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 6, 'Бо не знав, що́ казати, бо були́ перелякані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 7, 'Та хмара ось їх заслони́ла, і голос почувся із хмари: „Це Син Мій Улю́блений, — Його слухайтеся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 8, 'І зараз, звівши очі свої, вони вже ніко́го з собою не бачили, крім Самого Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 9, 'А коли з гори схо́дили, Він їм наказав, щоб ніко́му того не казали, що́ бачили, аж поки Син Лю́дський із мертвих воскресне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 10, 'І вони заховали те слово в собі, сперечаючися, що́ то є: „воскреснути з мертвих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 11, 'І вони запитали Його та сказали: „Що́ це книжники кажуть, ніби треба Іллі перш прийти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 12, 'А Він відказав їм: „Тож Ілля́, коли при́йде попе́реду, усе приготу́є. Та я́к же про Лю́дського Сина написано, що мусить багато Він ви́терпіти, і буде знева́жений?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 13, 'Але вам кажу́, що й Ілля́ був прийшов, — та зробили йому, що́ тільки хотіли, як про нього написано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 14, 'А коли поверну́лись до учнів, коло них вони вгле́діли бе́зліч наро́ду та книжників, що сперечалися з ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 15, 'І негайно ввесь на́товп, як побачив Його, сполохну́вся із дива, і назу́стріч побіг, і став вітати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 16, 'І запитався Він їх: „Про що спереча́єтесь з ними?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 17, 'І Йому відповів один із на́товпу: „Учителю, привів я до Тебе ось сина свого́, що духа німого він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 18, 'А як він де схо́пить його, то о́б землю кидає ним, — і він пі́ну пускає й зубами скрегоче та сохне. Я казав Твоїм у́чням, щоб прогнали його, — та вони не змогли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 19, 'А Він їм у відповідь каже: „О, роде невірний, — доки буду Я з вами? Доки вас Я терпітиму? Приведіть до Мене його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 20, 'І до Нього того привели́. І як тільки побачив Його, то дух зараз затряс ним. А той, повалившись на землю, став качатися та заливатися пі́ною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 21, 'І Він запитав його ба́тька: „Як давно́ йому сталося це?“Той сказав: „Із дити́нства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 22, 'І по́часту кидав він ним і в огонь, і до води, щоб його погубити. Але коли можеш що Ти, то змилуйсь над нами, і нам поможи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 23, 'Ісус же йому відказав: „Щодо того твого „коли можеш“, — то тому́, хто вірує, все можливе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 24, 'Зараз ба́тько хлоп\'я́ти з слізьми́ закричав і сказав: „Вірую, Господи, — поможи недовірству моє́му!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 25, 'А Ісус, як побачив, що на́товп збігається, то нечистому духові заказав, і сказав йому: „Ду́ше німий і глухий, тобі Я наказую: вийди з нього, і більше у нього не входь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 26, 'І, закричавши та мі́цно затрясши, той вийшов. І він став, немов мертвий, — аж багато-хто стали казати, що помер він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 27, 'А Ісус узяв за руку його та й підвів його, — і той устав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 28, 'Коли́ ж Він до дому прийшов, то учні питали Його самото́ю: „Чому ми́ не могли його вигнати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 29, 'А Він їм сказав: „Цей рід не вихо́дить інакше, як тільки від молитви та по́сту“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 30, 'І вони вийшли звідти, і прохо́дили по Галілеї. А Він не хотів, щоб довідався хто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 31, 'Бо Він Своїх учнів навчав і казав їм: „Людський Син буде ви́даний лю́дям до рук, і вони Його вб\'ють, але вбитий, — воскресне Він третього дня!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 32, 'Вони ж не зрозуміли цього сло́ва, та боялись Його запитати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 33, 'І прибули́ вони в Капернау́м. А як був Він у домі, то їх запитав: „Про що́ міркува́ли в дорозі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 34, 'І мовчали вони, — сперечалися бо проміж себе в дорозі, хто́ найбільший.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 35, 'А як сів, то покликав Він Дванадцятьо́х, і промовив до них: „Коли хто бути першим бажає, — нехай буде найменшим із усіх і слуга всім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 36, 'І взяв Він дитину, і поставив її серед них. І, обнявши її, Він промовив до них:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 37, '„Коли хто в Ім\'я́ Моє при́йме одне з дітей таких, той приймає Мене. Хто ж приймає Мене, — не Мене він приймає, а Того, Хто послав Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 38, 'Обізвався до нього Іван: „Учителю, ми бачили одно́го чоловіка, який з нами не ходить, що виганя́є Ім\'я́м Твоїм де́монів; і ми заборонили йому, бо він із нами не ходить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 39, 'А Ісус відказав: „Не забороняйте йому, бо немає такого, що Ім\'я́м Моїм чудо зробив би, і зміг би неба́ром лихосло́вити Мене́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 40, 'Хто бо не супроти нас, — той за нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 41, 'І коли хто напо́їть вас ку́хлем води в Ім\'я́ Моє ради того, що ви Христові, поправді кажу́ вам: той не згубить своєї нагоро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 42, 'Хто ж споку́сить одно́го з мали́х цих, що вірять, то краще б такому було, коли б жо́рно млино́ве на шию йому почепити, та й кинути в море!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 43, 'І коли рука твоя спокуша́є тебе, — відітни її: краще тобі ввійти до життя однору́ким, ніж з обома руками ввійти до геєнни, до огню невгаси́мого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 44, 'де „їхній червяк не вмирає, і не гасне огонь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 45, 'І коли нога твоя спокуша́є тебе, — відітни її: краще тобі ввійти до життя одноно́гим, ніж з обома ногами бути вкиненому до геєнни, [до огню невгаси́мого],');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 46, 'де „їхній червяк не вмирає, і не гасне огонь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 47, 'І коли твоє око тебе́ спокуша́є, — вибери його: краще тобі одноо́ким ввійти в Царство Боже, ніж з обома очима бути вкиненому до геєнни огне́нної,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 48, 'де „їхній червяк не вмирає, і не гасне огонь“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 49, 'Бо посо́литься кожен огнем, і кожна жертва посо́литься сіллю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 50, 'Сіль — добра річ. Коли ж сіль несолоною стане, — чим поправити її? Майте сіль у собі, майте й мир між собою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 1, 'І, вийшовши звідти, Він приходить у землю Юдейську, на той бік Йорда́ну. І знову зібралися ю́рби до Нього, і знов Він навчав їх, звича́єм Своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 2, 'І підійшли фарисеї й спитали, Його випробо́вуючи: „Чи дозволено чолові́кові дружи́ну свою відпустити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 3, 'А Він відповів і сказав їм: „Що Мойсей заповів вам?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 4, 'Вони ж відказали: „Мойсей заповів написати листа розводо́вого, та й відпустити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 5, 'Ісус же промовив до них: „То за ваше жорстокосе́рдя він вам написав оцю заповідь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 6, 'Бог же з поча́тку творіння „створив чоловіком і жінкою їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 7, 'Покине тому́ чоловік свого ба́тька та матір,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 8, 'і стануть обо́є вони одним тілом“, — тим то немає вже двох, але́ одне тіло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 9, 'Тож, що Бог спарува́в, — люди́на нехай не розлу́чує!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 10, 'А вдома про це учні знов запитали Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 11, 'І Він їм відказав: „Хто дружи́ну відпустить свою, та й одру́житься з іншою, той чинить пере́люб із нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 12, 'І коли дружи́на покине свого чоловіка, і вийде заміж за іншого, то чинить пере́люб вона“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 13, 'Тоді поприно́сили ді́ток до Нього, щоб Він доторкнувся до них, учні ж їм докоря́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 14, 'А коли спостеріг це Ісус, то обу́рився, та й промовив до них: „Пустіть ді́ток до Ме́не прихо́дити, і не бороніть їм, — бо таких Царство Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 15, 'Попра́вді кажу вам: Хто Божого Царства не при́йме, немов те дитя, той у нього не вві́йде“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 16, 'І Він їх пригорну́в, і поблагословив, на них руки поклавши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 17, 'І коли вирушав Він у путь, то швидко набли́зивсь один, упав перед Ним на коліна, і спитався Його: „Учителю Добрий, — що робити мені, щоб вічне життя вспадкува́ти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 18, 'Ісус же йому відказав: „Чого звеш Мене Добрим? Ніхто не є Добрий, крім Бога Самого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 19, 'Знаєш заповіді: „Не вбивай, не чини пере́любу, не кради́, не свідкуй неправдиво“, не кривди́, „шануй свого ба́тька та матір“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 20, 'А він відказав Йому: „Учителю, — це все виконав я ще зма́лку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 21, 'Ісус же поглянув на нього з любов\'ю, і промовив йому: „Одно́го бракує тобі: іди, розпро́дай, що маєш, та вбогим роздай, — і матимеш скарб ти на небі! Потому приходь та й іди вслід за Мною, узявши хреста“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 22, 'А він засмутився тим словом, і пішов, зажурившись, — бо великі маєтки він мав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 23, 'І поглянув довко́ла Ісус, та й сказав Своїм учням: „Як тяжко отим, хто має бага́тство, увійти в Царство Боже!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 24, 'І учні жахнулись від слів Його. А Ісус знов у відповідь каже до них: „ Мої діти, як тяжко отим, хто наді́ю кладе на багатство, увійти в Царство Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 25, 'Верблю́дові легше пройти через го́лчине ву́шко, ніж багатому в Боже Царство ввійти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 26, 'А вони здивувалися дуже, і казали один до одно́го: „Хто ж тоді може спастися?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 27, 'Ісус же поглянув на них і промовив: „Неможливе це лю́дям, а не Богові. Бо „для Бога можливе все!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 28, 'А Петро став казати Йому: „От усе ми покинули, та й пішли за Тобою слідо́м“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 29, 'Ісус відказав: „Поправді кажу вам: Немає такого, щоб дім полишив, чи братів, чи сесте́р, або матір, чи ба́тька, або діти, чи поля́ ради Мене та ради Єва́нгелії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 30, 'і не одержав би в сто раз більше тепер, цього ча́су, серед переслідувань, — домів, і братів, і сесте́р, і матері́в, і дітей, і піль, а в віці насту́пному — вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 31, 'І багато-хто з перших стануть останніми, а останні — першими“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 32, 'Були ж у дорозі вони, простуючи в Єрусали́м. А Ісус ішов попе́реду них, — аж дуже вони дивувались, а ті, що йшли вслід за Ним, боялись. І, взявши знов Дванадцятьо́х, почав їм розповідати, що́ з Ним статися має:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 33, '„Оце в Єрусали́м ми йдемо́, і первосвященикам і книжникам ви́даний буде Син Лю́дський, і засудять на смерть Його, і поганам Його видадуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 34, 'і насміхатися бу́дуть із Нього, і бу́дуть плювати на Нього, і будуть Його бичува́ти, і вб\'ють, — але третього дня Він воскресне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 35, 'І підхо́дять до Нього Яків та Іван, сини Зеведе́єві, та й кажуть Йому: „Учителю, — ми хочемо, щоб Ти зробив нам, про що бу́демо просити Тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 36, 'А Він їх поспитав: „Чого ж хочете, щоб Я вам зробив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 37, 'Вони ж відказали Йому: „Дай нам, щоб у славі Твоїй ми сиділи право́руч від Тебе один, і ліво́руч один“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 38, 'А Ісус відказав їм: „Не знаєте, чого просите. Чи ж можете ви пити чашу, що Я її п\'ю, і христитися хрищенням, що Я ним хрищуся?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 39, 'Вони відказали Йому: „Можемо“. А Ісус їм сказав: „Чашу, що Я її п\'ю, ви питимете, і хрищенням, що Я ним хрищусь, ви охриститеся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 40, 'А сидіти право́руч Мене та ліво́руч — не Моє це давати, а кому угото́вано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 41, 'Як почули ж це Де́сятеро, то обурились на Якова та на Івана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 42, 'А Ісус їх покликав, і промовив до них: „Ви знаєте, що ті, що вважають себе за князів у народів, панують над ними, а їхні вельможі їх тиснуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 43, 'Не так буде між вами, але хто з вас великим бути хоче, — нехай буде він вам за слугу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 44, 'А хто з вас бути першим бажає, — нехай буде всім за раба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 45, 'Бо Син Лю́дський прийшов не на те, щоб служили Йому, але щоб послужити, і душу Свою дати на викуп за багатьох“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 46, 'І приходять вони в Єрихо́н. А коли з Єрихо́ну вихо́див Він ра́зом із Своїми у́чнями й з бе́зліччю люду, сидів і просив при дорозі сліпий Вартиме́й, син Тиме́їв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 47, 'І, прочувши, що то Ісус Назаряни́н, почав кликати та говорити: „Сину Давидів, Ісусе, — змилуйся надо мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 48, 'І сварились на нього багато-хто, щоб мовча́в, а він іще більше кричав: „Сину Давидів, — змилуйся надо мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 49, 'І спинився Ісус та й сказав: „Покличте його!“І кличуть сліпого та й кажуть йому: „Будь бадьо́рий, устань, — Він кличе тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 50, 'А той скинув плаща свого, і скочив із місця, — і прибіг до Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 51, 'А Ісус відповів і сказав йому: „Що́ ти хочеш, щоб зробив Я тобі?“Сліпий же Йому відказав: „Учителю, — нехай я прозрю́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 52, 'Ісус же до нього промовив: „Іди, — твоя віра спасла тебе!“І той зараз прозрі́в, і пішов за Ісусом дорогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 1, 'І коли вони набли́зились до Єрусалиму, до Вітфагі́ї й Віфа́нії, на Оливній горі, тоді Він посилає двох учнів Своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 2, 'і каже до них: „Ідіть у село, яке перед вами, і, входячи в нього, ви зна́йдете зараз прив\'язане осля́, що на нього ніхто ще з людей не сідав. Відв\'яжіть його, і приведіть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 3, 'Коли ж скаже хто вам: „Що́ це ви робите?“відкажіть: „Господь потребу́є його, — і віді́шле його сюди зараз“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 4, 'І вони відійшли, і знайшли те осля, що прив\'я́зане коло воріт ізнадво́ру було при дорозі, — і відв\'язали його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 5, 'А деякі з тих, що стояли там, сказали до них: „Що́ ви робите? По́що осля ви відв\'я́зуєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 6, 'Вони ж їм відказали, як звелів їм Ісус, — і відпущено їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 7, 'І вони привели́ до Ісуса осля́, і поклали на нього плащі свої, а Він сів на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 8, 'Багато ж наро́ду стелили одежу свою по дорозі, а інші стелили дорогою зе́лень, натя́ту в полях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 9, 'А ті, що йшли перед Ним і поза́ду, викрикували: „Оса́нна! Благослове́нний, хто йде у Господнє Ім\'я́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 10, 'Благословенне Царство, що надходить, Отця нашого Давида! Оса́нна на висоті!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 11, 'Потому ввійшов Він до Єрусалиму, і в храм. А оглянувши все, як година вже пізня була, Він пішов у Віфа́нію з Дванадцятьма́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 12, 'А назавтра, коли вони вийшли з Віфа́нії, Він зголодні́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 13, 'І, побачивши зда́лека фіґове дерево, вкрите листями, Він підійшов, чи не зна́йде на ньому чого́. І, прийшовши до нього, не знайшов нічого, крім листя само́го, — не пора бо на фіґи була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 14, 'І озвався Ісус і промовив до нього: „Щоб більше ніхто твого пло́ду не з\'їв аж повіки!“А учні Його все те чули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 15, 'І прийшли вони в Єрусалим. А як Він у храм увійшов, то став виганяти продавців і покупців у храмі, і попереверта́в столи грошомі́нам та осло́ни — продавцям голубів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 16, 'І Він не дозволяв, щоб хто річ яку носив через храм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 17, 'І Він їх навчав і казав їм: „Хіба не написано: „Дім Мій — бу́де домом молитви в наро́дів усіх“, ви ж із нього зробили „печеру розбійників!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 18, 'І почули це первосвященики й книжники, і шукали, як Його погубити, бо боялись Його, — увесь бо наро́д дивувався науці Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 19, 'А як пізно ставало, вони поза місто вихо́дили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 20, 'А прохо́дячи вранці, побачили фіґове дерево, усохле від кореня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 21, 'І, згадавши, Петро гово́рить Йому: „Учителю, глянь — фіґове дерево, що прокляв Ти, усохло!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 22, 'А Ісус їм у відповідь каже: „Майте віру Божу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 23, 'Поправді кажу вам: Як хто скаже горі цій: „Порушся та й кинься до моря“, і не матиме сумніву в серці своїм, але матиме віру, що станеться так, як гово́рить, — то буде йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 24, 'Через це говорю вам: Усе, чого ви в молитві попро́сите, вірте, що одержите, і спо́вниться вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 25, 'І коли стоїте́ на молитві, то прощайте, як маєте що проти кого, щоб і Отець ваш Небесний пробачив вам про́гріхи ваші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 26, 'Коли ж не прощаєте ви, то й Отець ваш Небесний не простить вам про́гріхів ваших“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 27, 'І зно́ву прийшли вони в Єрусалим. Коли ж Він у храмі ходив, поприхо́дили первосвященики й книжники, і старши́ни до Нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 28, 'і сказали Йому: „Якою Ти вла́дою все оце чиниш? І хто Тобі вла́ду цю дав, щоб Ти це робив?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 29, 'А Ісус відказав їм: „Запитаю й Я вас одне слово, і відповідайте Мені, то й Я відкажу́ вам, якою Я вла́дою це все чиню́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 30, 'Іванове хрищення з неба було, чи від людей? Відповідайте Мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 31, 'Вони ж міркували собі й говорили: Коли скажемо: „Із неба“, відкаже: „Чого ж ви йому не повірили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 32, 'А як скажемо: „Від людей“, — то боялись наро́ду, бо всі вважали, що Іван був поправді пророк.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 33, 'І сказали Ісусові в відповідь: „Не знаємо“. А Ісус їм відказує: „То й Я не скажу́ вам, якою Я вла́дою це все чиню́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 1, 'І почав Він у при́тчах до них промовляти: „Насадив був один чоловік виноградника, муром обгородив, ви́довбав у ньому чави́ло, башту поставив, — і віддав його винаря́м, та й пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 2, 'А певного ча́су послав він раба до своїх винарі́в, щоб прийняти частину плоду з виноградинка в тих винарі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 3, 'Та вони схопи́ли його та й побили, і відіслали ні з чим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 4, 'І зно́ву послав він до них раба іншого, — та й того вони зранили в голову та знева́жили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 5, 'Тоді вислав він іншого, — і того вони вбили. І багатьо́х іще інших, — набили одни́х, а одни́х повбивали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 6, 'І він мав ще одно́го, — сина улю́бленого. Наоста́нок послав і того́ він до них і сказав: „Посоромляться сина мого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 7, 'А ті винарі міркували собі: „Це спадкоємець; ходім, заморду́ймо його, — і нашою спа́дщина бу́де!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 8, 'І вони схопи́ли його та й убили, і викинули його за виноградник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 9, 'Отож, що́ пан виноградинка зробить? — Він прибуде та й вигубить тих винарів, і віддасть виноградинка іншим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 10, 'Чи ви не читали в Писа́нні: „Камінь, що його будівни́чі відкинули, — той нарі́жним став ка́менем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 11, 'Від Господа сталося це, — і дивне воно в оча́х наших“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 12, 'І шукали Його, щоб схопи́ти, але побоялись наро́ду. Бо вони зрозуміли, що про них Він цю при́тчу сказав. І, лишивши Його, відійшли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 13, 'I вони вислали деяких із фарисеїв та іродія́нів до Нього, щоб зловити на слові Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 14, 'Ті ж прийшли та й говорять Йому: „Учителю, знаємо ми, що Ти справедливий, і не зважаєш зовсі́м ні на ко́го, бо на лю́дське обличчя не дивишся, а наставляєш на Божу дорогу правдиво. Чи годи́ться давати податок для кесаря, чи ні? Давати нам, чи не давати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 15, 'А Ісус, знавши їх лицемірство, сказав їм: „Чого ви Мене випробо́вуєте? Принесіть Мені гріш податковий, щоб бачити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 16, 'І прине́сли вони. А Він каже до них: „Чий це образ і напис?“Ті ж Йому відказали: „Кесарів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 17, 'Ісус тоді каже в відповідь їм: „Віддайте кесареве — кесареві, а Богові — Боже!“І дивувалися з Нього вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 18, 'І прийшли до Нього ті саддукеї, що твердять, ніби нема воскресіння, і запитали Його та сказали:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 19, '„Учителю, Мойсей написав нам: „Як помре кому брат, і полишить дружи́ну, а дитини не лишить, то нехай його брат візьме дружи́ну його́, та й відновить насіння для брата свого́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 20, 'Було сім братів. І перший взяв дружи́ну й умер, не лишивши дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 21, 'Другий теж її взяв та й помер, — і він не лиши́в дітей. Так само і третій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 22, 'І всі семеро не полишили дітей. А по всіх вмерла й жінка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 23, 'А в воскресінні, як воскреснуть вони, то котро́му із них вона дружи́ною буде? Бо семеро мали за дружи́ну її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 24, 'Ісус їм відказав: „Чи ви не тому помиляєтесь, що не знаєте ані Писа́ння, ані Божої сили?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 25, 'Бо як із мертвих воскреснуть, то не бу́дуть женитись, ані заміж вихо́дити, але будуть, немов анголи́ ті на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 26, 'Що ж до мертвих, що воскреснуть, чи ж ви не читали в Мойсеєвій книзі, як — при кущі́ — сказав йому Бог, промовляючи: „Я Бог Авраамів, і Бог Ісаків, і Бог Яковів“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 27, 'Бо Він є Бог не мертвих, а живих! Тим то ви помиляєтесь ду́же“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 28, 'А один із тих книжників, що чув, як вони сперечались, та бачив, як добре Він відповідав їм, приступив та й спитався Його: „Котра́ заповідь перша з усіх?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 29, 'Ісус відповів: Перша: „Слухай, Ізраїлю: наш Господь Бог — Бог єдиний“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 30, 'І: „Люби Господа, Бога свого, усім серцем своїм, і всією душею своєю, і всім своїм розумом, і з ці́лої сили своєї!“(Це за́повідь перша!)');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 31, 'А друга (одна́кова з нею): „Люби свого ближнього, як само́го себе!“Нема іншої більшої заповіді над оці!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 32, 'І сказав Йому книжник: „Добре, Учителю! Ти поправді сказав, що „Один Він, і нема іншого, окрім Нього“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 33, 'і що „Любити Його всім серцем, і всім розумом, (і всією душе́ю), і з ці́лої сили“, і що „Любити свого ближнього, як само́го себе“, — це важливіше за всі цілопа́лення й жертви!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 34, 'Ісус же, побачивши, що розумно той відповідь дав, промовив до нього: „Ти недалеко від Божого Царства!“І ніхто не насмілювався вже питати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 35, 'Пото́му Ісус відповів і промовив, у храмі навчаючи: „Як то книжники кажуть, що ніби Христос — син Давидів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 36, 'Адже той Давид Святим Духом сказав: „Промовив Господь Господе́ві моєму: сядь право́руч Мене, доки не покладу́ Я Твоїх ворогів підніжком ногам Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 37, 'Сам Давид Його Господом зве, — як же Він йому син?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 38, 'Він же казав у науці Своїй: „Стережіться тих книжників, що люблять у довгих одежах прохо́джуватись, і привіти на ринках,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 39, 'і перші лавки́ в синагогах, і перші місця на прийняття́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 40, 'що вдови́ні хати поїдають, і моляться довго напо́каз, — вони тяжче осу́дження при́ймуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 41, 'І сів Він навпроти скарбни́ці, і дививсь, як наро́д мідяки́ до скарбниці вкидає. І багато заможних укида́ли багато.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 42, 'І підійшла одна вбога вдови́ця, і поклала дві ле́пти, цебто гріш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 43, 'І покликав Він учнів Своїх та й промовив до них: „Поправді кажу вам, що ця вбога вдовиця поклала найбільше за всіх, хто клав у скарбницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 44, 'Бо всі клали від ли́шка свого, а вона покла́ла з убо́зтва свого все, що мала, — свій прожиток увесь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 1, 'І коли Він виходив із храму, говорить Йому один із учнів Його: „Подивися, Учителю — яке́ то каміння та що́ за будівлі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 2, 'Ісус же до нього сказав: „Чи ти бачиш великі будинки оці? — Не зали́шиться тут навіть камінь на камені, який не зруйнується!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 3, 'Коли ж Він сидів на Оливній горі, проти храму, питали Його насамоті Петро, і Яків, і Іван, і Андрій:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 4, '„Скажи нам, коли станеться це? І яка буде озна́ка, коли все те ви́конатись має?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 5, 'Ісус же почав промовляти до них: „Стережіться, щоб вас хто не звів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 6, 'Бо багато-хто при́йдуть в Ім\'я́ Моє, кажучи: „Це Я“. І зведу́ть багатьо́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 7, 'І як про ві́йни почуєте ви, і про воєнні чутки́, — не лякайтесь, бо статись належить тому́ “. Та це ще не кінець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 8, '„Бо повстане наро́д на наро́д, і царство на царство“, будуть землетруси місця́ми, буде голод. Це поча́ток терпінь породільних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 9, 'Пильнуйте ж самі, бо вас на суди видаватимуть, і бичуватимуть вас у синагогах, і поведуть до правителів та до царів ради Мене, на сві́дчення їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 10, 'Але перше Єва́нгелія мусить бути наро́дам усім проповідувана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 11, 'Коли ж видадуть вас і поведуть, — не турбуйтеся заздалегі́дь, що́ вам говорити, — а що́ дане вам буде тієї години, то те говоріть: бо не ви промовлятимете, але Дух Святий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 12, 'І видасть на смерть брата брат, а ба́тько — дитину. І „діти повстануть навпроти батьків“, — і їм смерть заподіють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 13, 'І за Ім\'я́ Моє будуть усі вас нена́видіти. А хто витерпить аж до кінця, той буде спасе́ний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 14, 'Коли ж ви побачите ту „гидоту спусто́шення“, — що про неї звіщав пророк Даниїл, — що вона залягла́, де не слід, — хто читає, нехай розуміє, — тоді ті, хто в Юдеї, нехай в го́ри втікають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 15, 'І хто на покрівлі, нехай той не сходить, і нехай не входить узяти щось із дому свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 16, 'І хто на полі, — хай назад не вертається взяти одежу свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 17, 'Горе ж вагітним і тим, хто годує грудьми́, у ті дні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 18, 'Моліться ж, щоб не трапилося це зимою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 19, 'Будуть бо ті дні такою „скорбо́тою, що її не було з первопо́чину світу“, що його Бог створив, „аж досі“, і не буде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 20, 'І коли б Госпо́дь не вкоротив тих днів, — не спаслася б ніяка люди́на; але ради ви́браних, кого вибрав, укороти́в Він ті дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 21, 'Тоді ж, як хто скаже до вас: „Ото, Христос тут“, „Ото там“, — не йміть віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 22, 'Бо повстануть христи́ неправдиві, і неправдиві пророки, і будуть чинити озна́ки та чу́да, щоб спокуси́ти, як можна, і ви́браних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 23, 'Але ви стережіться! Я сказав вам усе напере́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 24, 'Але за тих днів, по скорбо́ті отій, „сонце затьми́ться, і місяць не дасть свого світла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 25, 'і зо́рі спада́тимуть з неба, і сили небесні пору́шаться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 26, 'І побачать тоді „Сина Лю́дського, що йтиме на хмарах“із великою поту́гою й славою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 27, 'І тоді Він пошле Анголів і зберуть Його ви́браних „від вітрі́в чотирьо́х, від кра́ю землі до крайнеба“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 28, 'Від дерева ж фіґового навчіться при́кладу: коли віття його вже розпу́кується, і кинеться листя, то знаєте, що близько літо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 29, 'Так і ви: коли тільки побачите, що діється це, то знайте, що близько, — під дверима.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 30, 'Поправді кажу́ вам: не пере́йде цей рід, аж усе оце станеться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 31, 'Небо й земля промину́ться, але не мину́ться слова́ Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 32, 'Про день же той чи про годину не знає ніхто: ні анголи́ на небі, ні Син, — тільки Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 33, 'Уважайте, чува́йте й моліться: бо не знаєте, коли час той настане!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 34, 'Як той чоловік, що від\'їхав, і залиши́в свій дім, і дав рабам своїм вла́ду й кожному працю свою, а воротаре́ві звелів пильнувати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 35, 'Тож пильнуйте, — не знаєте бо, коли при́йде пан дому: уве́чорі, чи опі́вночі, чи як півні співатимуть, чи ра́нком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 36, 'Щоб вас не застав, що спите́, коли ве́рнеться він несподі́вано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 37, 'А що вам Я кажу́, те всім Я кажу́: Пильнуйте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 1, 'За два ж дні була Пасха й Опрі́сноки. А первосвященики й книжники стали шукати, я́к би пі́дступом взяти Його та забити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 2, 'Вони говорили: „Та не в свято, щоб бува́ колотне́ча в наро́ді не сталась“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 3, 'Коли ж Ісус був у Віфанії, у домі Си́мона, на проказу слабого, і сидів при столі, підійшла одна жінка, аляба́строву пляшечку маючи щирого на́рдового дуже ці́нного мира. І розбила вона аляба́строву пляшечку, і вилила миро на голову Йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 4, 'А дехто обу́рювались між собою й каза́ли: „На́що таке марнотра́тство на миро?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 5, 'Бо можна було б це миро продати більше, як за три сотні динаріїв, і вбогим роздати“. І нарікали на неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 6, 'Ісус же сказав: „Залиші́ть її! Чого при́крість їй робите? Вона добрий учинок зробила Мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 7, 'Бо вбогих ви маєте за́вжди з собою, і коли схочете, можете їм робити добро, — Мене ж не постійно ви маєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 8, 'Що могла, те зробила вона: заздалегі́дь намасти́ла Моє тіло на по́хорон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 9, 'Поправді кажу́ вам: де тільки ця Єва́нгелія проповідувана буде в ці́лому світі, — на пам\'ятку їй буде сказане й те, що́ зробила вона!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 10, 'Юда ж Іскаріо́тський, один із Дванадцятьо́х, подався до первосвящеників, щоб їм Його видати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 11, 'А вони, як почули, зраділи, і обіцяли йому срібнякі́в за те дати. І він став вишукувати, я́к би слушного ча́су їм видати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 12, 'А першого дня Опрі́сноків, коли пасху приношено в жертву, сказали Йому Його учні: „Куди хочеш, щоб пішли й приготува́ли ми Тобі пасху спожити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 13, 'І посилає Він двох із Своїх учнів, і каже до них: „Підіть до міста, і стріне вас чоловік, що не́стиме в гле́кові воду, — то йдіть за ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 14, 'І там, куди він уві́йде, скажіть до госпо́даря дому: „Учитель питає: „Де кімна́та Моя, в якій Я споживу́ зо Своїми у́чнями пасху?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 15, 'І він вам покаже велику го́рницю, ви́стелену та готову: там приготуйте для нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 16, 'І учні пішли, і до міста прийшли, і знайшли, як Він їм сказав, — і зачали́ вони пасху готува́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 17, 'А коли настав вечір, Він приходить із Дванадцятьма́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 18, 'І як сиділи вони при столі й споживали, промовив Ісус: „Поправді кажу вам, що один з-поміж вас, „який споживає зо Мною“, видасть Мене́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 19, 'Вони зачали́ сумувати, і один по одно́му питати Його: „Чи не я?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 20, 'А Він їм сказав: „Один із Дванадцятьо́х, що в миску мача́є зо Мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 21, 'Людський Син справді йде, як про Нього написано; та горе тому́ чоловікові, що видасть він Лю́дського Сина! Було б краще тому чоловікові, коли б він не родився!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 22, 'Як вони ж споживали, Ісус узяв хліб, і поблагословив, поламав, і дав їм, і сказав: „Прийміть, споживайте, це — тіло Моє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 23, 'І взяв Він чашу, і, вчинивши подяку, подав їм, — і пили́ з неї всі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 24, 'І промовив до них: „Це — кров Моя Ново́го Заповіту, що за багатьох проливається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 25, 'Поправді кажу́ вам, що віднині не пи́тиму Я від плоду виноградного до того дня, як нови́м буду пити його в Царстві Божім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 26, 'А коли відспівали вони, на го́ру Оливну пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 27, 'Промовляє тоді їм Ісус: „Усі ви споку́ситесь ночі цієї, як написано: „Уражу́ Па́стиря, — і розпоро́шаться вівці!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 28, 'По воскресінні ж Своїм Я вас ви́переджу в Галілеї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 29, 'І відізвався до Нього Петро: „Хоч спокусяться й усі, — та не я!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 30, 'Ісус же йому відказав: „Поправді кажу́ тобі, що сьогодні, цієї ось ночі, перше ніж заспіває півень дві́чі, — відречешся ти три́чі від Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 31, 'А він ще сильніш запевняв: „Коли б мені й умерти з Тобою, — я не відречу́ся Тебе!“Так же само сказали й усі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 32, 'І приходять вони до місцевости, на ім\'я́ Гефсима́нія, і каже Він у́чням Своїм: „Посидьте ви тут, поки Я помолюся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 33, 'І, взявши з Собою Петра, і Якова та Івана, Він зачав сумувати й тужи́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 34, 'І сказав Він до них: „Обго́рнена сумом смерте́льним душа Моя! Залиші́ться тут і пильнуйте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 35, 'І Він відійшов трохи далі, припав до землі, та й благав, щоб, як можна, минула Його ця година.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 36, 'І благав Він: „Авва -Отче, — Тобі все можливе: пронеси мимо Мене цю чашу! А проте, — не чого хочу Я, але чого Ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 37, 'І вернувся, і знайшов їх, що спали, та й каже Петрові: „Симоне, спиш ти? Однієї години не зміг попильнува́ти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 38, 'Пильнуйте й моліться, щоб не впасти в спокусу, — бадьо́рий бо дух, але не́мічне тіло!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 39, 'І зно́ву пішов і молився, те саме промовивши слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 40, 'А вернувшись, ізнову знайшов їх, що спали, бо зважні́ли їм очі були́. І не знали вони, що́ Йому відказати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 41, 'І вернувсь Він утретє, та й каже до них: „Ви ще далі спите́ й спочиваєте? Скі́нчено, — надійшла та година: у руки грішникам ось видається Син Лю́дський!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 42, 'Уставайте, ходім, — ось набли́зивсь Мій зрадник“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 43, 'І зараз, як Він ще говорив, прийшов Юда, один із Дванадцятьо́х, а з ним люди з мечами та ки́ями від первосвящеників, і книжників, і старших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 44, 'А зрадник Його дав був знака їм, кажучи: „Кого я поцілую, то Він, — беріть Його, і обере́жно ведіть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 45, 'І, прийшовши, підійшов він негайно та й каже: „Учителю!“І поцілував Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 46, 'Вони ж руки свої накла́ли на Нього, — і схопи́ли Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 47, 'А один із тих, що стояли навко́ло, меча ви́хопив та й рубону́в раба́ первосвященика, — і відтяв йому вухо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 48, 'А Ісус їм промовив у відповідь: „Немов на розбійника вийшли з мечами та ки́ями, щоб узяти Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 49, 'Я щодня був із вами у храмі, навчаючи, — і Мене не взяли́ ви. Але, щоб збулися Писа́ння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 50, 'Тоді всі полиши́ли Його й повтікали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 51, 'Один же юна́к, по наго́му заго́рнений у покрива́ло, ішов услід за Ним. І хапа́ють його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 52, 'Але він, покрива́ло поки́нувши, утік наги́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 53, 'А Ісуса вони повели́ до первосвященика. І зійшлися всі первосвященики й старші та книжники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 54, 'Петро ж зда́лека йшов услід за Ним до сере́дини дво́ру первосвященика; і сидів він із службою, і грівсь при огні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 55, 'А первосвященики та ввесь синедріо́н шукали посві́дчення на Ісуса, щоб Йому заподіяти смерть, — і не знахо́дили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 56, 'Бо багато-хто свідчив фальши́во на Нього, але́ не було́ згідних сві́дчень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 57, 'Тоді деякі встали, і кривосві́дчили супроти Нього й казали:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 58, '„Ми чули, як Він говорив: Я зруйную цей храм рукотво́рний, — і за три дні збудую інший, нерукотво́рний“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 59, 'Але й так не було́ їхнє свідчення згідне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 60, 'Тоді встав насере́дині первосвященик, та й Ісуса спитав і сказав: „Ти нічо́го не відповідаєш, що свідчать вони проти Тебе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 61, 'Він же мовчав, і нічого не відповідав. Первосвященик ізно́ву спитав Його, до Нього говорячи: „Чи Христос Ти, Син Благослове́нного?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 62, 'А Ісус відказав: „Я! І побачите ви Сина Лю́дського, що сидітиме по прави́ці сили Божої, і на хмарах небесних прихо́дитиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 63, 'Роздер тоді первосвященик одежу свою та й сказав: „На що́ нам ще свідки потрібні?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 64, 'Ви чули цю богозневагу. Як вам здається?“Вони ж усі присудили, що Він умерти повинен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 65, 'Тоді деякі стали плювати на Нього, і закривати обличчя Йому, і бити Його та казати Йому: „Пророкуй!“Служба теж Його била по що́ках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 66, 'А коли Петро був на подві́р\'ї надо́лі, приходить одна із служниць первосвященика,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 67, 'і як Петра вона вгледіла, що грівся, подивилась на нього та й каже: „І ти був із Ісусом Назаряни́ном!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 68, 'Він же відрікся, говорячи: „Не відаю, і не розумію, що́ кажеш“. І вийшов назо́вні, на нереддвір\'я. І заспівав тоді півень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 69, 'Служниця ж, коли його вгледіла, стала знов говорити прия́вним: „Цей із них!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 70, 'І він зно́ву відрікся. Незаба́ром же знов говорили прия́вні Петрові: „Поправді, ти з них, — бо ти галіле́янин. Та й мо́ва твоя́ така са́ма“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 71, 'А він став клясти́сь та божитись: „Не знаю Цього Чоловіка, про Якого говорите ви!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 72, 'І заспівав півень хвилі тієї подруге. І згадав Петро слово, що Ісус був промовив йому: „Перше ніж заспіває півень дві́чі, — відречешся ти тричі від Мене“. І кинувся він, та й плакати став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 1, 'А первосвященики з ста́ршими й книжниками, та ввесь синедріо́н, зараз уранці, нараду вчинивши, зв\'язали Ісуса, повели́ та й Пилатові видали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 2, 'А Пила́т запитався Його: „Чи Ти Цар Юдейський?“А Він йому в відповідь каже: „Сам ти кажеш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 3, 'А первосвященики мі́цно Його винува́тили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 4, 'Тоді Пилат зно́ву Його запитав і сказав: „Ти нічого не відповідаєш? Дивись, — як багато проти Тебе свідку́ють!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 5, 'А Ісус більш нічого не відповідав, так що Пилат дивувався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 6, 'На свято ж він їм відпускав був одно́го із в\'я́знів, котро́го просили вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 7, 'Був же один, що звався Вара́вва, ув\'я́знений ра́зом із повста́нцями, які за повста́ння вчинили були душогубство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 8, 'Коли ж на́товп зібрався, він став просити Пила́та зробити, як він за́вжди робив їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 9, 'Пилат же сказав їм у відповідь: „Хочете, — відпущу́ вам Царя Юдейського?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 10, 'Бо він знав, що Його через за́здрощі видали первосвященики.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 11, 'А первосвященики на́товп підмовили, щоб краще пустив їм Вара́вву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 12, 'Пилат же промовив знов їм у відповідь: „А що ж я чинитиму з Тим, що Його ви Юдейським Царем називаєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 13, 'Вони ж стали кричати знов: „Розіпни́ Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 14, 'Пилат же сказав їм: „Яке ж зло вчинив Він?“А вони ще сильніше кричали: „Розіпни́ Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 15, 'Пилат же хотів догодити наро́дові, — і відпустив їм Вара́вву. І видав Ісуса, збичува́вши, щоб ро́зп\'ятий був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 16, 'Вояки ж повели́ Його до сере́дини двору, цебто в преторій, і цілий відділ скликають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 17, 'І вони зодягли Його в багряни́цю і, сплівши з терни́ни вінка, поклали на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 18, 'І вітати Його зачали́: „Раді́й, Ца́рю Юдейський!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 19, 'І трости́ною по голові Його били, і плювали на Нього. І навколішки кидалися та вклонялись Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 20, 'І коли назнущалися з Нього, зняли́ з Нього багряни́цю, і наділи на Нього одежу Його. І Його повели́, щоб розп\'я́сти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 21, 'І одного перехо́жого, що з поля вертався, Си́мона Кіріне́янина, батька Олександра та Ру́фа, змусили, щоб хреста Йому ніс.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 22, 'І Його привели́ на місце Голго́фу, що значить „Черепо́вище“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 23, 'І давали Йому пити вина, із ми́ррою змішаного, але Він не прийня́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 24, 'І Його розп\'яли́, і „поділили одежу Його, кинувши же́реб про неї“, хто що ві́зьме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 25, 'Була́ ж третя година, як Його розп\'яли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 26, 'І був написаний на́пис провини Його: „Цар Юдейський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 27, 'Тоді ро́зп\'ято з Ним двох розбійників, — одно́го право́руч, і одно́го ліво́руч Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 28, 'І збулося Писа́ння, що каже: „До злочи́нців Його зарахо́вано!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 29, 'А хто побіч прохо́див, то Його лихосло́вили, „голова́ми своїми хитали“й казали: „Отак! Ти, що храма руйнуєш та за три дні будуєш, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 30, 'зійди із хреста, та спаси Самого Себе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 31, 'Теж і первосвященики з книжниками глузува́ли й один до одного казали: „Він інших спасав, — а Самого Себе не може спасти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 32, 'Христос, Цар Ізраїлів, — нехай зі́йде тепер із хреста, щоб побачили ми та й увірували“. Навіть ті, що ра́зом із Ним були ро́зп\'яті, насміхалися з Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 33, 'А як шоста година настала, то аж до години дев\'ятої те́мрява стала по ці́лій землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 34, 'О годині ж дев\'ятій Ісус скрикнув голосом гучни́м та й вимовив: „Елої́, Елої́, — лама́ савахта́ні“, що в перекладі значить: „Боже Мій, Боже Мій, — на́що Мене Ти покинув?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 35, 'Дехто ж із тих, що стояли навколо, це почули й казали: „Ось Він кличе Іллю́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 36, 'А один із них побіг, намочив губку о́цтом, настроми́в на трости́ну, і давав Йому пити й казав: „Чекайте, побачим, — чи при́йде Ілля́ Його зняти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 37, 'А Ісус скрикнув голосом гучни́м, — і духа віддав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 38, 'І в храмі завіса розде́рлась надво́є, — від ве́рху аж додолу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 39, 'А сотник, що насу́проти Нього стояв, як побачив, що Він отак духа віддав, то промовив: „Чоловік Цей був справді Син Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 40, 'Були ж і жінки́, що дивились здалека, між ними Марі́я Магдали́на, і Марія, мати Якова Молодшого та Йосі́ї, і Саломі́я,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 41, 'що вони, як Він був у Галілеї, ходили за Ним та Йому прислуго́вували; і інших багато, що до Єрусалиму прийшли з Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 42, 'А коли настав вечір, — через те, що було́ Пригото́влення, цебто перед суботою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 43, 'прийшов Йо́сип із Аримате́ї, радник поважний, що сам сподівавсь Царства Божого, і сміливо ввійшов до Пилата, — і просив тіла Ісусового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 44, 'А Пила́т здивувався, щоб Він міг уже вмерти. І, покликавши сотника, запитався його, чи давно вже Розп\'я́тий помер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 45, 'І, дізнавшись від сотника, він подарував тіло Йо́сипові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 46, 'А Йо́сип купив полотно, і, знявши Його, обгорнув полотном та й покла́в Його в гро́бі, що в скелі був ви́січений. І каменя привалив до моги́льних дверей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 47, 'Марія ж Магдали́на й Марія, мати Йосієва, дивилися, де́ ховали Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 1, 'Як минула ж субота, Марія Магдали́на, і Марія Яковова, і Саломі́я накупили па́хощів, щоб піти й намастити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 2, 'І на світа́нку дня першого в тижні, як схо́дило сонце, до гро́бу вони прибули́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 3, 'і говорили одна о́дній: „Хто відвалить нам каменя від могильних дверей?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 4, 'А зиркну́вши, побачили, що камінь відва́лений; був же він дуже великий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 5, 'І, ввійшовши до гро́бу, побачили там юнака́, що право́руч сидів, і був одя́гнений в білу одежу, — і жахнулись вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 6, 'А він промовляє до них: „Не жахайтесь! Ви шукаєте Розп\'я́того, Ісуса Назаряни́на. Він воскрес, — нема Його тут! Ось місце, де Його поховали були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 7, 'Але йдіть, скажіть у́чням Його та Петрові: Він іде в Галілею попе́реду вас, — там Його ви побачите, як Він вам говорив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 8, 'А як вийшли вони, то побігли від гро́бу, бо їх тре́пет та страх обгорнув. І не сказали ніко́му нічо́го, — бо боялись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 9, 'Як воскрес Він уранці дня першого в тижні, то з\'явився найперше Марїї Магдали́ні, із якої був вигнав сім демонів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 10, 'Пішовши вона, повідомила тих, що були з Ним, які сумували та плакали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 11, 'А вони, як почули, що живий Він, і вона Його бачила, не йняли́ тому віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 12, 'По цьому з\'явився Він двом із них у по́статі іншій в дорозі, як ішли вони на село.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 13, 'А вони, як вернулися, інших про те сповістили, але не повірено й їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 14, 'Наре́шті, Він з\'явився Одинадцятьо́м, як сиділи вони при столі, і докоряв їм за недові́рство їхнє та твердосе́рдя, що вони не йняли́ віри тим, хто воскреслого бачив Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 15, 'І казав Він до них: „Ідіть по ці́лому світові, та всьому створінню Єва́нгелію проповідуйте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 16, 'Хто увірує й охри́ститься, — буде спасе́ний, а хто не ввірує — засу́джений буде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 17, 'А тих, хто ввірує, супрово́дити будуть озна́ки такі: у Ім\'я́ Моє де́монів будуть виго́нити, говоритимуть мовами нови́ми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 18, 'братимуть змій; а коли смертоді́йне що вип\'ють, — не буде їм шко́дити; кластимуть руки на хворих, — і добре їм буде!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 19, 'Господь же Ісус, по розмові із ними, возні́сся на небо, — і сів по Божій прави́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 20, 'І пішли вони, і скрізь проповідували. А Господь помагав їм, і стве́рджував слово ознаками, що його супрово́дили. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Через те, що багато-хто брались складати опо́вість про спра́ви, які стались між нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'як нам ті розповіли, хто споча́тку були самови́дцями й слу́гами Сло́ва,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'тому й я, все від першої хвилі докладно розвідавши, забажав описати за порядком для тебе, високодосто́йний Тео́філе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'щоб пізнав ти істо́ту науки, якої навчився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'За днів царя юдейського Ірода був один священик, на ім\'я́ Заха́рій, з денної черги́ Аві́я, та дружина його із дочо́к Ааро́нових, а ім\'я́ їй Єлисавета.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'І обо́є вони були праведні перед Богом, бездоганно сповня́ючи заповіді й постанови Господні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'А дитини не мали вони, бо Єлисавета неплідна була, — та й віку старого обо́є були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'І ось раз, як у порядку своєї черги́ він служив перед Богом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'за звича́єм свяще́нства, жеребко́м йому випало до Господнього храму ввійти й покади́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Під час же каді́ння вся бе́зліч народу молилась знадво́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'І з\'явивсь йому ангол Господній, ставши право́руч кадильного же́ртівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'І стриво́живсь Захарій, побачивши, і о́страх на нього напав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'А ангол до нього промовив: „Не бійся, Захаріє, бо почута молитва твоя, і дружи́на твоя Єлисавета сина породить тобі, ти ж даси йому йме́ння Іван.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'І він буде на радість та втіху тобі, і з його наро́дження багато-хто втішаться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Бо він бу́де великий у Господа, „ні вина, ні п\'янко́го напо́ю не питиме“, і напо́вниться Духом Святим ще з утро́би своєї матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'І багато синів із Ізраїля він наве́рне до їхнього Господа Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 17, 'І він сам перед Ним буде йти в духу й силі Іллі, „щоб серця́ батьків приверну́ти до дітей“, і неслухняних — до мудрости праведних, щоб готових людей споряди́ти для Господа“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 18, 'І промовив Захарій до Ангола: „Із чо́го пізнаю я це? Я ж старий, та й дружина моя вже похи́лого віку“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 19, 'А ангол прорік йому в відповідь: „Я Гавриїл, що стою перед Богом; мене по́слано, щоб говорити з тобою, і звістити тобі про цю Добру Нови́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 20, 'І замовкнеш ось ти, і говорити не зможеш аж до дня, коли станеться це, за те, що ти віри не йняв був словам моїм, які збудуться ча́су свого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 21, 'А люди чекали Захарія, та й дивувались, чого́ забаривсь він у храмі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 22, 'Коли ж вийшов, не міг говорити до них, і вони зрозуміли, що видіння він бачив у храмі. А він тільки знаки́ їм давав, — і залиши́вся німий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 23, 'І як дні його служби скінчи́лись, він вернувся до дому свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 24, 'А після тих днів зачала́ його дружи́на Єлисавета, і таїлась п\'ять місяців, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 25, '„Так для мене Господь учинив за тих днів, коли згля́нувся Він, щоб зняти наругу мою між людьми́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 26, 'А шостого місяця від Бога був по́сланий ангол Гавриїл у галілейське місто, що йому на ім\'я́ Назаре́т,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 27, 'до діви, що заручена з мужем була́, на ім\'я́ йому Йо́сип, із дому Давидового, а ім\'я́ діві — Марі́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 28, 'І, ввійшовши до неї, промовив: „Раді́й, благода́тная, Госпо́дь із тобою! Ти благослове́нна між жо́нами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 29, 'Вона ж затриво́жилась словом, та й стала розду́мувати, що́ б то значило це привіта́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 30, 'А ангол промовив до неї: „Не бійся, Маріє, — бо в Бога благода́ть ти знайшла́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 31, 'І ось ти в утро́бі зачне́ш, і Сина породиш, і даси Йому йме́ння Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 32, 'Він же буде Великий, і Сином Всеви́шнього зва́ний, і Господь Бог дасть Йому престола Його ба́тька Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 33, 'І повік царюватиме Він у домі Якова, і царюва́нню Його не буде кінця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 34, 'А Марія озвалась до ангола: „Як же станеться це, коли мужа не знаю?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 35, 'І ангол промовив у відповідь їй: „Дух Святий зли́не на тебе, і Всеви́шнього сила обго́рне тебе, через те то й Святе, що наро́диться, бу́де Син Божий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 36, 'А ото твоя родичка Єлисаве́та — і вона зачала́ в своїй старості сина, і оце шостий місяць для неї, яку звуть неплідною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 37, 'Бо „для Бога нема неможливої жодної речі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 38, 'А Марія промовила: „Я ж Господня раба: нехай буде мені згідно з словом твоїм!“І відійшов а́нгол від неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 39, 'Тими днями зібралась Марія й пішла, поспішаючи, у гірську око́лицю, у місто Юдине.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 40, 'І ввійшла вона в дім Захарія, та й поздоро́вила Єлисавету.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 41, 'Коли ж Єлисавета зачула Маріїн привіт, затріпота́ла дитина в утро́бі її. І Єлисавета напо́внилась Духом Святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 42, 'і скрикнула голосом гучним, та й прорекла́: „Благослове́нна Ти між жо́нами, і благослове́нний Плід утро́би твоєї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 43, 'І звідкіля́ мені це, що до мене прийшла мати мого Господа?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 44, 'Бо як тільки в ву́хах моїх голос привіту твого забрині́в, — від ра́дощів затріпота́ла дитина в утробі моїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 45, 'Блаженна ж та, що повірила, бо спо́вниться проре́чене їй від Господа!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 46, 'А Марія промовила: „Велича́є душа моя Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 47, 'і радіє мій дух у Бозі, Спасі моїм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 48, 'що зглянувся Він на поко́ру Своєї раби, бо ось від ча́су цього́ всі ро́ди мене за блаженну вважатимуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 49, 'бо велике вчинив мені Поту́жний! Його ж Іме́ння святе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 50, 'і милість Його́ з роду в рід на тих, хто боїться Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 51, 'Він показує міць Свого раме́на, розпорошує тих, хто пиша́ється думкою серця свого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 52, 'Він могутніх скидає з престолів, підіймає покі́рливих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 53, 'удовольняє голодних добром, а багатих пускає ні з чи́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 54, 'Пригорну́в Він Ізраїля, Свого слугу, щоб ми́лість згадати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 55, 'як прорік був Він нашим отця́м, — Аврааму й насінню його аж повіки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 56, 'І залиша́лась у неї Марія щось місяців зо́ три, та й вернулась до дому свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 57, 'А Єлисаветі настав час родити, — і сина вона породила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 58, 'І почули сусіди й роди́на її, що Господь Свою милість велику на неї послав, — та й утішалися ра́зом із нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 59, 'І сталося во́сьмого дня, прийшли, щоб обрізати дитя, і хотіли назвати його йме́нням ба́тька його — Заха́рій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 60, 'І озвалася мати його та й сказала: „Ні, — нехай на́званий буде Іван!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 61, 'А до неї сказали: „Таж у роди́ні твоїй нема жодного, який на́званий був тим ім\'я́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 62, 'І кива́ли до батька його, — як хотів би назвати його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 63, 'Попросивши ж табличку, написав він слова́: „Іван імення йому“. І всі дивувались.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 64, 'І в тій хвилі уста та язик розв\'язались йому, — і він став говорити, благословляючи Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 65, 'І страх обгорнув усіх їхніх сусідів, і по всіх верхови́нах юдейських проне́слася чутка про це все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 66, 'А всі, що почули, розважали у серці своїм та казали: „Чим то буде дитина оця?“І Господня рука була з нею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 67, 'Його ж батько Захарій напо́внився Духом Святим, та й став пророкувати й казати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 68, '„Благослове́нний Госпо́дь, Бог Ізраїлів, що зглянувся й визволив люд Свій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 69, 'Він ріг спасі́ння підні́с нам у домі Давида, Свого слуги,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 70, 'як був заповів відвіку уста́ми святих пророків Своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 71, 'що від ворогі́в наших визволить нас, та з руки всіх наших ненависників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 72, 'що вчинить Він милість нашим отцям, і буде пригадувати Свій святий заповіт,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 73, 'що дотримає й нам ту прися́гу, якою Він присягавсь Авраамові, отцю́ нашому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 74, 'щоб ми, ви́зволившись із руки ворогів, служили безстрашно Йому');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 75, 'у святості й праведності перед Ним по всі дні життя нашого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 76, 'Ти ж, дитино, станеш пророком Всеви́шнього, бо будеш ходи́ти перед Господом, щоб дорогу Йому приготува́ти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 77, 'щоб наро́ду Його дати пізнати спасі́ння у відпу́щенні їхніх гріхів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 78, 'через велике милосердя нашого Бога, що ним Схід із висоти нас відвідав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 79, 'щоб світити всім тим, хто перебуває в те́мряві й тіні смерте́льній, щоб спрямува́ти наші ноги на дорогу спокою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 80, 'А дитина росла, і скріплялась на дусі, і перебува́ла в пустинях до дня свого з\'я́влення перед Ізраїлем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'І трапилося тими днями, — вийшов нака́з царя А́вгуста переписати всю землю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Цей пе́репис перший відбувся тоді, коли вла́ду над Си́рією мав Квірі́ній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'І всі йшли записатися, кожен у місто своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Пішов теж і Йо́сип із Галілеї, із міста Назарету, до Юдеї, до міста Давидового, що зветься Вифлеє́м, бо похо́див із дому та з роду Давидового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'щоб йому записатись із Марією, із ним зару́ченою, що була́ вагітна́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'І сталось, як були́ вони там, то настав їй день породити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'І породила вона свого Пе́рвенця Сина, і Його сповила́, і до я́сел поклала Його́, — бо в за́їзді місця не стало для них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'А в тій стороні були́ пастухи, які пильнували на полі, і нічно́ї пори вартували отару свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Аж ось а́нгол Господній з\'явивсь коло них, і слава Господня ося́яла їх. І вони перестра́шились стра́хом великим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Та а́нгол промовив до них: „Не лякайтесь, бо я ось благовіщу́ вам радість велику, що станеться лю́дям усім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Бо сьогодні в Давидовім місті народився для вас Спаситель, Який є Христос Господь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'А ось вам ознака: Дитину сповиту ви зна́йдете, що в я́слах лежатиме“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'І ось ра́птом з\'явилася з а́нголом сила велика небесного війська, що Бога хвалили й казали:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, '„Слава Богу на висоті, і на землі спокій, у людях добра воля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'І сталось, коли анголи́ відійшли від них в небо, пастухи зачали́ говори́ти один о́дному: „Ходім до Вифлеєму й побачмо, що́ сталося там, про що́ сповістив нас Господь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 16, 'І прийшли, поспішаючи, і знайшли там Марію та Йо́сипа, та Дитинку, що в я́слах лежала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 17, 'А побачивши, розповіли́ про все те, що́ про Цю Дитину було́ їм зві́щено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 18, 'І всі, хто почув, дивувались тому, що́ їм пастухи говорили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 19, 'А Марія оці всі слова́ зберігала, розважаючи, у серці своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 20, 'Пастухи ж повернулись, прославляючи й хвалячи Бога за все, що почули й побачили, так як їм було сказано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 21, 'Коли ж ви́повнились вісім день, щоб обрізати Його, то Ісусом назвали Його, як був а́нгол назвав, перше ніж Він в утро́бі зачався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 22, 'А коли — за Зако́ном Мойсея — минулися дні їхнього очи́щення, то до Єрусалиму прине́сли Його, щоб поставити Його перед Господом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 23, 'як у Зако́ні Господнім написано: „Кожне дитя чоловічої ста́ті, що розкриває утро́бу, має бути посвя́чене Господу“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 24, 'і щоб жертву скла́сти, як у Зако́ні Господньому сказано, — „пару горлича́т або двоє голубеня́т“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 25, 'І ото був в Єрусалимі один чоловік, йому ймення Семе́н, — люди́на праведна та благочести́ва, — що потіхи чекав для Ізраїля. І Святий Дух був на ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 26, 'І від Духа Святого йому було зві́щено смерти не бачити, перше ніж побачить Христа Господнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 27, 'І Дух у храм припрова́див його. І як внесли Дитину Ісуса батьки́, щоб за Нього вчинити звича́єм зако́нним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 28, 'тоді взяв він на руки Його, хвалу Богу віддав та й промовив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 29, '„Нині відпускаєш раба Свого́, Владико, за словом Твоїм із ми́ром,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 30, 'бо побачили очі мої Спасі́ння Твоє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 31, 'яке Ти приготува́в перед всіма наро́дами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 32, 'Світло на просвіту поганам і на славу наро́ду Твого Ізраїля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 33, 'І дивувалися ба́тько Його й мати тим, що про Нього було́ розповіджене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 34, 'А Семен їх поблагословив та й прорік до Марії, Його матері: „Ось призначений Цей багатьо́м на падіння й устава́ння в Ізраїлі, і на знак спереча́ння, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 35, 'і меч душу проши́є самій же тобі, — щоб відкрились думки́ сердець багатьох!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 36, 'Була й Анна пророчиця, дочка́ Фануїлова з племени Аси́рового, — вона дожила́ до глибокої старости, живши з мужем сім ро́ків від свого дівува́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 37, 'удова ро́ків вісімдесяти й чотирьох, що не відлучалась від храму, служачи Богові вдень і вночі поста́ми й моли́твами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 38, 'І години тієї вона надійшла, Бога сла́вила та говорила про Нього всім, хто визво́лення Єрусалиму чекав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 39, 'А як виконали за Зако́ном Господнім усе, то вернулись вони в Галілею, до міста свого Назарету.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 40, 'А Дитина росла та зміцнялася духом, набираючись мудрости. І благодать Божа на Ній пробува́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 41, 'А батьки́ Його щорічно ходили до Єрусалиму на свято Пасхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 42, 'І коли мав Він дванадцять ро́ків, вони за звича́єм на свято пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 43, 'Як дні ж свята скінчи́лись були, і вертались вони, молодий Ісус в Єрусалимі лиши́вся, а Йо́сип та мати Його не знали того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 44, 'Вони ду́мали, що Він із подорожніми йде; пройшли день дороги, та й стали шукати Його поміж ро́дичами та знайо́мими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 45, 'Але, не знайшовши, вернулися в Єрусалим, та й шукали Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 46, 'І сталось, що третього дня відшукали у храмі Його, як сидів серед учителів, і вислу́хував їх, і запитував їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 47, 'Усі ж, хто слухав Його, дивувалися розумові та Його відповідям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 48, 'І як вони Його вгледіли, то здивувались, а мати сказала до Нього: „Дитино, — чому так Ти зробив нам? Ось Твій батько та я із журбо́ю шукали Тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 49, 'А Він їм відказав: „Чого ж ви шукали Мене? Хіба ви не знали, що повинно Мені бути в тому, що належить Моєму Отцеві?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 50, 'Та не зрозуміли вони того сло́ва, що Він їм говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 51, 'І пішов Він із ними, і прибув у Назарет, і був їм слухня́ний. А мати Його зберігала оці всі слова́ в своїм серці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 52, 'А Ісус зростав мудрістю, і віком та благодаттю, у Бога й людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'У п\'ятнадцятий рік панува́ння Тиве́рія ке́саря, коли По́нтій Пила́т панував над Юдеєю, коли в Галілеї тетра́рхом був І́род, а Пилип, його брат, був тетра́рхом Ітуре́ї й землі Трахоні́тської, за тетра́рха Ліса́нія в Авілі́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'за первосвящеників Анни й Кайя́фи було Боже слово в пустині Іванові, сину Захарія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'І він перейшов усю землю Йорда́нську, проповідуючи хрищення покая́ння для про́щення гріхів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'як написано в книзі пророцтва пророка Ісаї: „Голос того, хто кличе: У пустині готуйте дорогу для Господа, рівняйте стежки́ Йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Нехай кожна долина напо́вниться, гора ж кожна та при́горок зни́зиться, що нерівне, нехай випросто́вується, а доро́ги вибо́їсті стануть гладе́нькі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'і кожна люди́на побачить Боже спасі́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'А Іван говорив до людей, хто прихо́див, христитися в ньо́го: Ро́де зміїний, — хто навчив вас тікати від гніву майбу́тнього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Отож, учиніть гідний плід покая́ння. І не починайте казати в собі: „Маємо ба́тька Авраама“. Бо кажу вам, що Бог може підне́сти дітей Авраамові з цьо́го каміння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Бо вже он до корі́ння дере́в і сокира прикла́дена: кожне ж дерево, що доброго пло́ду не родить, буде зрубане та до огню буде вкинене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'А люди питали його й говорили: „Що́ ж нам робити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'І сказав він у відповідь їм: „У кого дві сорочці, — нехай дасть немаючому; а хто має поживу, — нехай робить так само“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'І прихо́дили й ми́тники, щоб христитись від нього, і питали його: „Учителю, що́ ми маємо робити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'А він їм казав: „Не стягайте нічого над те, що вам зве́лено“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Питали ж його й вояки́ й говорили: „А нам що робити?“І він їм відповів: „Ніко́го не кривдьте, ані не оскаржайте фальшиво, удовольня́йтесь платнею своєю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Коли ж усі люди чекали, і в серцях своїх ду́мали всі про Івана, чи то він не Христос,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 16, 'Іван відповідав усім, кажучи: „Я хрищу́ вас водою, але йде ось Поту́жніший за мене, що Йому́ розв\'язати ремінця́ від Його взуття́ я негідний, — Він христитиме вас Святим Духом й огнем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 17, 'У руці Своїй має Він ві́ячку, — і перечистить Свій тік: пшеницю збере до засі́ків Своїх, а полову попа́лить ув огні невгаси́мім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 18, 'Тож багато навчав він і іншого, звіщаючи Добру Нови́ну народові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 19, 'А Ірод тетра́рх, що Іван докоря́в йому за Іродія́ду, дружи́ну брата свого, і за все зло, яке заподі́яв був Ірод,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 20, 'до всього додав іще й те, що Івана замкнув до в\'язни́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 21, 'І сталося, як христились усі люди, і як Ісус, охристившись, молився, розкрилося небо,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 22, 'і Дух Святий зли́нув на Нього в тілесному ви́гляді, як голуб, і голос із неба почувся, що мовив: „Ти Син Мій Улю́блений, що Я вподо́бав Тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 23, 'А Сам Ісус, розпочинаючи, мав ро́ків із тридцять, бувши, як думано, сином Йо́сипа, Ілія,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 24, 'сина Маттатового, сина Леві́їного, сина Мелхіїного, сина Яннаєвого, сина Йо́сипового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 25, 'сина Маттатієвого, сина Амосова, сина Наумового, сина Еслієвого, сина Наггеєвого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 26, 'сина Маатового, сина Маттатієвого, сина Семенієвого, сина Йосихового, сина Йодаєвого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 27, 'сина Йоананового, сина Рисаєвого, сина Зоровавелевого, сина Салатіїлового, сина Нирієвого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 28, 'сина Мелхієвого, сина Аддієвого, сина Косамового, сина Елмадамового, сина Ірового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 29, 'сина Ісуєвого, сина Еліезерового, сина Йоримового, сина Маттатієвого, сина Левієвого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 30, 'сина Семенового, сина Юдиного, сина Йо́сипового, сина Йонамового, сина Еліякимового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 31, 'сина Мелеаєвого, сина Меннаєвого, сина Маттатаєвого, сина Натамового, сина Давидового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 32, 'сина Єссеєвого, сина Йовидового, сина Воозового, сина Салаєвого, сина Наассонового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 33, 'сина Амінадавого, сина Адмінієвого, сина Арнієвого, сина Есромового, сина Фаресового, сина Юдиного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 34, 'сина Яковлевого, сина Ісакового, сина Авраамового, сина Тариного, сина Нахорового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 35, 'сина Серухового, сина Рагавового, сина Фалекового, сина Еверового, сина Салиного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 36, 'сина Каїнамового, сина Арфаксадового, сина Симового, сина Но́євого, сина Ламе́хового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 37, 'сина Матусалового, сина Ено́хового, сина Яретового, сина Малелеїлового, сина Каїнамового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 38, 'сина Еносового, сина Ситового, сина Ада́мового, — Сином Божим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 1, 'А Ісус, повний Духа Святого, вернувсь з-над Йорда́ну, і Дух на пустиню Його попрова́див.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 2, 'Сорок день там диявол Його спокуша́в, і за тих днів Він нічого не їв, а коли закінчи́лись вони, то вкінці зголодні́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 3, 'І диявол до Нього сказав: „Якщо Ти Син Божий, — скажи цьому ка́меневі, щоб хлі́бом він став!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 4, 'А Ісус відповів йому: „Написано: Не хлібом самим буде жити люди́на, але кожним Словом Божим!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 5, 'І він вивів Його на го́ру високу, і за хвилину ча́су показав Йому всі царства на світі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 6, 'І диявол сказав Йому: „Я дам Тобі всю оцю вла́ду та їхню славу, бо мені це пере́дане, і я даю, кому хочу, її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 7, 'Тож коли Ти покло́нишся передо мною, то все буде Твоє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 8, 'І промовив Ісус йому в відповідь: „Написано: Господеві Богові своєму вклоняйся, і служи Одно́му Йому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 9, 'І повів Його в Єрусалим, і на нарі́жнику храму поставив, та й каже Йому: „Як Ти Син Божий, — кинься звідси додолу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 10, 'Бо написано: „Він накаже про Тебе Своїм Ангола́м, щоб Тебе берегли!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 11, 'і: „Вони на руках понесуть Тебе, щоб коли не спіткнув Ти об камінь Своєї ноги!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 12, 'А Ісус відказав йому в відповідь: „Сказано: Не спокуша́й Господа Бога свого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 13, 'І диявол, скінчи́вши все цеє споку́шування, відійшов від Нього до ча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 14, 'А Ісус у силі Духа вернувся до Галілеї, і чутка про Нього розне́слась по всій тій країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 15, 'І Він їх навчав по їхніх синагогах, і всі Його сла́вили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 16, 'І прибув Він до Назаре́ту, де був ви́хований. І звича́єм Своїм Він прийшов дня суботнього до синаго́ги, і встав, щоб читати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 17, 'І подали́ Йому книгу пророка Ісаї. Розгорнувши ж Він книгу, знайшов місце, де було так написано:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 18, '„На Мені Дух Господній, бо Мене Він пома́зав, щоб Добру Нови́ну звіщати вбогим. Послав Він Мене проповідувати полоне́ним визво́лення, а незрячим прозрі́ння, відпустити на волю пому́чених,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 19, 'щоб проповідувати рік Господнього зми́лування“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 20, 'І, книгу згорнувши, віддав службі й сів. А очі всіх у синагозі звернулись на Ньо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 21, 'І почав Він до них говорити: „Сьогодні збуло́ся Писа́ння, яке ви почули!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 22, 'І всі Йому стверджували й дивувались словам благода́ті, що ли́нули з уст Його. І казали вони: „Чи ж то Він не син Йо́сипів?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 23, 'Він же промовив до них: „Ви Мені конче скажете при́казку: „Лікарю, — уздоров самого себе! Учини те й тут, у вітчи́зні Своїй, що́ сталося — чули ми — у Капернау́мі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 24, 'І сказав Він: „Поправді кажу вам: Жоден пророк не буває приємний у вітчи́зні своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 25, 'Та правдиво кажу́ вам: Багато вдовиць перебува́ло за днів Іллі серед Ізраїля, коли на три роки й шість місяців небо було́ зачинилося, так що голод великий настав був по всій тій землі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 26, 'а Ілля́ не до жодної з них не був посланий, тільки в Саре́пту Сидо́нську до овдові́лої жінки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 27, 'І багато було́ прокаже́них за Єлисе́я пророка в Ізраїлі, але жоден із них не очи́стився, крім Неєма́на сирі́янина“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 28, 'І всі в синагозі, почувши оце, перепо́внились гнівом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 29, 'І, вставши, вони Його вигнали за місто, і повели́ аж до кра́ю гори, на якій їхнє місто було побудо́ване, щоб скинути додолу Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 30, 'Але Він перейшов серед них, і віддали́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 31, 'І прийшов Він у Капернау́м, галілейське місто, і там їх навчав по суботах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 32, 'І дивувались науці Його, бо слово Його було вла́дне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 33, 'І був чоловік у синагозі, що мав духа нечистого де́мона, і він закричав гучни́м голосом:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 34, '„Ах, що нам до Тебе, Ісусе Назаряни́не? Ти прийшов погубити нас. Я знаю Тебе, хто Ти, — Божий Святий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 35, 'А Ісус заборони́в йому, кажучи: „Замовчи, і вийди з нього!“І, кинувши де́мон того насере́дину, вийшов із нього, нічо́го йому не пошко́дивши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 36, 'І всіх жах обгорнув, і питали вони один о́дного, кажучи: „Що́ то за наука, що ду́хам нечистим наказує з вла́дою й силою, — і виходять вони?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 37, 'І не́слася чутка про Нього по всіх місцях кра́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 38, 'А як вийшов Він із синагоги, увійшов у дім Си́мона. Теща ж Си́монова в великій гарячці лежала. І просили за неї Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 39, 'І, ставши над нею, Він заборони́в тій гарячці, — і вона полишила її. І, зараз уставши, теща їм прислуго́вувала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 40, 'Коли ж сонце захо́дило, то всі, хто мав яких хворих на різні неду́ги, до Нього приво́дили їх. Він же клав Свої руки на кожного з них, — та їх уздоровля́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 41, 'Із багатьох же вихо́дили й де́мони, кричачи́ та гово́рячи: „Ти Син Божий!“Та Він їм забороня́в, і не давав говорити, що знали вони, що Христос Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 42, 'Коли ж настав день, Він вийшов, і подавсь до самотнього місця. А люди шукали Його. І прийшовши до Нього, Його затримували, щоб від них не відхо́див.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 43, 'Він же промовив до них: „І іншим містам Я повинен звіщати Добру Нови́ну про Боже Царство, — бо на те Мене по́слано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 44, 'І Він проповідував по синагогах Галілеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 1, 'І сталось, як ти́снувся на́товп до Нього, щоб почути Слово Боже, Він стояв біля озера Генісаре́тського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 2, 'І Він побачив два чо́вни, що стояли край о́зера. А риба́лки, відійшовши від них, полоска́ли не́вода.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 3, 'І Він увійшов до одно́го з човні́в, що був Си́монів, і просив, щоб він тро́хи відплив від землі. І Він сів, та й навчав наро́д із чо́вна.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 4, 'А коли перестав Він навчати, промовив до Си́мона: „Попливи на глибі́нь, — і закиньте на по́лов свій не́від“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 5, 'А Си́мон сказав Йому в відповідь: „Наставнику, — цілу ніч ми працюва́ли, і не вловили нічо́го, — та за словом Твоїм укину не́вода“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 6, 'А зробивши оце, вони бе́зліч риби набрали — і їхній не́від почав прорива́тись...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 7, 'І кива́ли вони до товаришів, що були в другім чо́вні, щоб прийшли помогти їм. Ті прийшли, та й напо́внили оби́два човни́, — аж стали вони потопа́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 8, 'А як Си́мон Петро це побачив, то припав до колін Ісусових, кажучи: „Господи, — вийди від мене, бо я грішна люди́на!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 9, 'Бо від по́лову риби, що зловили вони, обгорнув жах його та й усіх, хто з ним був,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 10, 'також Якова й Івана, синів Зеведе́євих, що були спільника́ми Си́мона. І сказав Ісус Си́монові: „Не лякайсь, — від цього ча́су ти будеш ловити людей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 11, 'І вони повитяга́ли на землю човни́, покинули все, — та й пішли вслід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 12, 'А як Він перебува́в в одно́му з міст, ось один чоловік, увесь укритий проказою, Ісуса побачивши, упав ницьма, та й благав Його, кажучи: „Господи, коли хочеш, — Ти можеш очи́стити мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 13, 'А Він руку простяг, доторкнувся до нього й сказав: „Хо́чу, — будь чистий!“І зараз із нього проказа зійшла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 14, 'І звелів Він йому не казати ніко́му про це. „Але йди, покажися священикові, і принеси за своє очи́щення, як Мойсей наказав, на сві́дчення їм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 15, 'А чутка про Нього ще більше пішла, і багато наро́ду прихо́дило слухати та вздоровлятись від Нього з неду́гів своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 16, 'Він же відходив на місце самотнє й молився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 17, 'І сталось одного із днів, коли Він навчав, і сиділи фарисеї й законовчи́телі, що посхо́дилися зо всіх сіл Галілеї й Юдеї та з Єрусалиму, а сила Господня готова була вздоровляти їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 18, 'і ось люди на ложі прине́сли чоловіка, що розсла́блений був, і намагалися вне́сти його, і перед Ним покла́сти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 19, 'Не знайшовши ж кудою проне́сти його з-за наро́ду, злізли на дім, і крізь стелю спустили із ложем його на сере́дину перед Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 20, 'І, побачивши їхню віру, сказав Він йому: „Чоловіче, прощаються тобі гріхі твої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 21, 'А книжники та фарисеї почали міркувати й казати: „Хто ж Оцей, що богознева́гу говорить? Хто може прощати гріхи, окрім Бога Самого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 22, 'Відчувши ж Ісус думки́ їхні, промовив у відповідь їм: „Що́ міркуєте ви в серцях ваших?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 23, 'Що́ легше: сказати: „Прощаються тобі гріхи твої“, чи сказати: „Уставай та й ходи“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 24, 'Але́ щоб ви знали, що Син Лю́дський має вла́ду на землі прощати гріхи́“, — тож каже Він розсла́бленому: „Кажу́ Я тобі: Уставай, візьми ложе своє, та й іди у свій дім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 25, 'І той зараз устав перед ними, узявши те, на чому лежав, і пішов у свій дім, прославляючи Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 26, 'І всіх жах обгорнув, — і сла́вили Бога вони. І перепо́внились стра́хом, говорячи: „Дивні речі сьогодні ми бачили!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 27, 'Після цього ж Він вийшов, і побачив ми́тника, на йме́ння Леві́я, що сидів на ми́тниці, та й промовив йому: „Іди за Мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 28, 'І, покинувши все, той устав, і пішов услід за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 29, 'І справив Леві́й у своїм домі велику гости́ну для Нього. І був на́товп великий ми́тників й інших, що сиділи з Ним при столі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 30, 'Фарисеї ж та книжники їхні нарікали на Нього, та учням Його говорили: „Чому́ з ми́тниками та із грішниками ви їсте́ та п\'єте́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 31, 'А Ісус відповів і промовив до них: „Лікаря не потребують здорові, а слабі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 32, 'Не прийшов Я, щоб праведних кликати до покая́ння, а грішних“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 33, 'Вони ж відказали до Нього: „ Чому́ учні Іванові часто по́стять та моляться, також і фарисейські, а Твої споживають та п\'ють?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 34, 'Ісус же промовив до них: „Чи ж ви можете змусити, щоб по́стили гості весільні, поки з ними ще є молоди́й?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 35, 'Але при́йдуть ті дні, коли заберуть молодого від них, — тоді й по́стити будуть тих днів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 36, 'Розповів же і при́казку їм: „Ніхто ла́тки з одежі ново́ї в одежу стару не вставляє, а то подере́ й нову́, а латка з ново́ї старій не надасться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 37, 'І ніхто не вливає вина молодого в старі бурдюки́, а то попрорива́є вино молоде бурдюки́, — і вино розіллє́ться, і бурдюки́ пропадуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 38, 'Але треба вливати вино молоде до нови́х бурдюкі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 39, 'І ніхто, старе пивши, молодого не схоче, бо каже: „Старе ліпше!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 1, 'І сталось, як Він перехо́див лана́ми, у суботу, Його учні зривали коло́сся та їли, розтерши руками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 2, 'А деякі з фарисеїв сказали: „На́що робите те, чого не годи́ться робити в суботу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 3, 'І промовив Ісус їм у відповідь: „Хіба ви не читали того, що зробив був Давид, коли сам зголодні́в, також ті, хто був із ним?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 4, 'Як він увійшов був до Божого дому, і, взявши хліби́ показні́, яких їсти не можна було́, тільки самим священикам, споживав, і дав тим, хто був із ним?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 5, 'І сказав Він до них: „Син Лю́дський — Господь і суботі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 6, 'І сталось, як в іншу суботу зайшов Він до синагоги й навчав, знахо́дився там чоловік, що прави́ця йому була всохла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 7, 'А книжники та фарисеї вважали, чи в суботу того не вздоро́вить, щоб знайти проти Нього оска́рження.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 8, 'А Він знав думки їхні, і сказав чоловікові, що мав суху руку: „Підведися, і стань посере́дині!“Той підвівся — і став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 9, 'Ісус же промовив до них: „Запитаю Я вас: Що годи́ться в суботу — робити добре, чи робити лихе, душу спасти́, чи згубити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 10, 'І, позирну́вши на всіх них, сказав чоловікові: „Простягни свою руку!“Той зробив, — і рука його стала здорова!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 11, 'А вони перепо́внились лютістю, і один з о́дним змовля́лись, що́ робити з Ісусом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 12, 'І сталось, що ча́су того Він вийшов на го́ру молитися, і перебув цілу ніч на молитві до Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 13, 'А коли настав день, покликав Він у́чнів Своїх, і обрав із них Дванадцятьо́х, яких і апо́столами Він назвав:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 14, 'Си́мона, якого й Петром Він назвав, і Андрія, брата його, Якова й Івана, Пилипа й Варфоломі́я,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 15, 'Матвія й Хому́, Якова Алфі́євого й Си́мона, зва́ного Зило́том,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 16, 'Юду Якового, й Юду Іскаріо́тського, що й зрадником став.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 17, 'Як зійшов Він із ними, то спинився на рівному місці, також на́товп густий Його у́чнів, і бе́зліч людей з усіє́ї Юдеї та з Єрусалиму, і з примо́рського Тиру й Сидо́ну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 18, 'що посхо́дилися, щоб послухати Його та вздорови́тися із неду́гів своїх, також ті, хто від ду́хів нечистих стражда́в, — і вони вздоровля́лися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 19, 'Увесь же наро́д намагався бода́й доторкну́тись до Ньо́го, бо від Ньо́го вихо́дила сила, і всіх вздоровляла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 20, 'А Він, звівши очі на у́чнів Своїх, говорив: „Блаженні убогі, — Царство Боже бо ваше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 21, 'Блаженні голодні тепер, бо ви нагодо́вані бу́дете. Блаженні засму́чені зараз, бо вті́шитесь ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 22, 'Блаженні ви бу́дете, коли люди знена́видять вас, і коли прожену́ть вас, і ганьби́тимуть, і знесла́влять, як зле, ім\'я́ ваше за Лю́дського Сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 23, 'Ра́ді́йте того дня й веселіться, нагоро́да бо ваша велика на небеса́х. Бо так само чинили пророкам батьки́ їхні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 24, 'Горе ж вам, багатія́м, бо втіху свою ви вже маєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 25, 'Горе вам, тепер ситим, бо зазнаєте го́лоду ви. Горе вам, що тепер потішаєтеся, бо бу́дете ви сумувати та плакати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 26, 'Горе вам, як усі люди про вас говоритимуть добре, бо так само чинили фальшивим пророкам батьки́ їхні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 27, 'А вам, хто слухає, Я кажу́: „Любіть своїх ворогів, добро робіть тим, хто нена́видить вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 28, 'Благословляйте тих, хто вас проклинає, і моліться за тих, хто кривду вам чинить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 29, 'Хто вдарить тебе по щоці́, підстав йому й другу, а хто хоче плаща твого взяти, — не забороняй і сорочки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 30, 'І кожному, хто в тебе просить — подай, а від того, хто твоє забирає, — назад не жадай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 31, 'І як бажаєте, щоб вам люди чинили, так само чиніть їм і ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 32, 'А коли любите тих, хто любить вас, — яка вам за те ла́ска? Люблять бо й грішники тих, хто їх любить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 33, 'І коли добре чините тим, хто добро чинить вам, — яка вам за те ла́ска? Бо те саме і грішники роблять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 34, 'А коли позичаєте тим, що й від них сподіваєтесь взяти, — яка вам за те ла́ска? Позичають бо й грішники грішникам, щоб оде́ржати стільки ж.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 35, 'Тож любіть своїх ворогів, робіть добро, позичайте, не ждучи нічого назад, — і ваша за це нагоро́да великою буде, і синами Всеви́шнього станете ви, — добрий бо Він до невдячних і злих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 36, 'Будьте ж милосердні, як і Отець ваш милосердний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 37, 'Також не судіть, щоб не су́джено й вас; і не осуджуйте, щоб і вас не осу́джено; прощайте, то простять і вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 38, 'Давайте — і дадуть вам; мірою доброю, нато́птаною, стру́снутою й перепо́вненою вам у подо́лок дадуть. Бо якою ви мірою міряєте, такою відмі́ряють вам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 39, 'Розповів також при́казку їм: „Чи ж може водити сліпого сліпий? Хіба не оби́два в яму впаду́ть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 40, 'Учень не більший за вчителя; але, удоскона́лившись, кожен буде, як учитель його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 41, 'Чого́ ж в оці брата свого ти за́скалку бачиш, коло́ди ж у вла́сному оці не чуєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 42, 'Як ти можеш сказати до брата свого: Давай, брате, я за́скалку вийму із ока твого́, сам колоди, що в оці твоїм, не вбача́ючи? Лицеміре, — вийми перше колоду із вла́сного ока, а потім побачиш, як вийняти за́скалку з ока брата твого́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 43, 'Нема доброго дерева, що родило б злий плід, ані дерева злого, що родило б плід добрий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 44, 'Кожне ж дерево з пло́ду свого́ пізнає́ться. Не збирають бо фіґ із терни́ни, винограду ж на гло́ду не рвуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 45, 'Добра люди́на із доброї скарбни́ці серця добре вино́сить, а лиха із лихої вино́сить лихе. Бо чим серце напо́внене, те говорять уста́ його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 46, 'Що звете́ ви Мене: „Господи, Господи“, та не робите того, що Я говорю́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 47, 'Скажу́ вам, до ко́го подібний усякий, хто до Мене приходить та слів Моїх слухає, і виконує їх:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 48, 'Той подібний тому чоловікові, що, будуючи дім, він гли́боко ви́копав, і основу на камінь поклав. Коли ж зли́ва настала, вода кинулася на той дім, — та однак не змогла захитати його, бо збудований добре він був!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 49, 'А хто слухає та не виконує, той подібний тому́ чоловікові, що свій дім збудував на землі без основи. І напе́рла на нього ріка, — і зараз упав він, і велика була́ того дому руїна!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 1, 'А коли Він скінчи́в усі слова́ Свої до наро́ду, що слухав Його, то ввійшов у Капернау́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 2, 'У одного ж сотника тяжко раб занедужав, що був дорогий йому́, і вмирати вже мав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 3, 'А коли про Ісуса почув, то послав він до Нього юдейських старши́х, і благав Його, щоб прийшов, і вздоро́вив раба́ його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 4, 'Вони ж прибули́ до Ісуса, та й ревно благали Його й говорили: „Він достойний, щоб Ти це зробив йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 5, 'Бо він любить наро́д наш, та й для нас синагогу поставив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 6, 'І пішов Ісус із ними. І коли недале́ко від дому вже був, сотник друзів послав, щоб сказати Йому: „Не турбу́йся, о Господи, бо я недостойний, щоб зайшов Ти під стрі́ху мою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 7, 'Тому́ то й себе не вважав я за гідного, щоб до Тебе прийти. Та промов тільки слово, — і раб мій одужає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 8, 'Бо й я — люди́на підвладна, і вояків під собою я маю; і одному кажу: піди, — то йде він, а тому: прийди, — і прихо́дить, а своєму рабо́ві: зроби теє — і зробить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 9, 'Почувши ж таке, Ісус здивувався йому, і, звернувшись до на́товпу, що йшов слідо́м за Ним, промовив: „Кажу вам: навіть серед Ізраїля Я не знайшов був такої великої віри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 10, 'А коли посланці́ повернулись додому, то знайшли, що одужав той раб!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 11, 'І сталось, — насту́пного дня Він відправивсь у місто, що зветься Наї́н, а з Ним ішли учні Його та багато наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 12, 'І ось, як до брами місько́ї набли́зився Він, вино́сили вмерлого, одинака́ в своєї матері, що вдовою була. І з нею був на́товп великий із міста.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 13, 'Як Господь же побачив її, то змилосе́рдивсь над нею, і до неї промовив: „Не плач!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 14, 'І Він підійшов, і доторкнувся до мар, носії ж зупинились. Тоді Він сказав: „Юначе, кажу́ тобі: встань!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 15, 'І мертвий устав, і почав говорити. І його Він віддав його матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 16, 'А всіх о́страх пройняв, і Бога хвалили вони й говорили: „Великий Пророк з\'явився між нами, і згля́нувся Бог над наро́дом Своїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 17, 'І розійшлася ця чутка про Нього по ці́лій Юдеї, і по всій тій країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 18, 'Про все ж те сповістили Івана учні його. І покликав Іван двох із у́чнів своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 19, 'і послав їх до Господа з за́питом: „Чи Ти Той, Хто має прийти, чи чекати нам Іншого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 20, 'А мужі, прийшовши до Нього, сказали: „Іван Христитель послав нас до Тебе, питаючи: Чи Ти Той, Хто має прийти, чи чекати нам Іншого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 21, 'А саме тоді багатьох уздоро́вив був Він від неду́гів і мук, і від ду́хів злих, і сліпим багатьо́м вернув зір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 22, 'І промовив Ісус їм у відповідь: „Ідіть, і перекажіть Іванові, що́ ви бачили й чули: „Сліпі прозрівають“, криві ходять, очищуються слабі на проказу, і чують глухі, воскресають померлі, „убогим звіщається Добра Нови́на“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 23, 'І блаженний, хто через Мене споку́си не матиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 24, 'А коли відійшли посланці́ Іванові, Він почав говорити про Івана наро́дові: „На що́ ви дивитись ходили в пустиню? Чи на очере́т, що вітер гойда́є його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 25, 'Та на що́ ви дивитись ходили? Може на чоловіка, у м\'які шати одя́гненого? Аджеж ті, хто одягається славно, і розкішно живе, — по палатах царськи́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 26, 'На що́ ж ви ходили дивитись? На пророка? Так, кажу вам, — навіть більше, аніж на пророка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 27, 'Це той, що про нього написано: „Ось перед обличчя Твоє посилаю Свого посланця́, який перед Тобою дорогу Твою приготу́є!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 28, 'Кажу вам: Між наро́дженими від жінок нема більшого понад Івана. Та найменший у Божому Царстві — той більший за нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 29, 'І всі люди, що слухали, і ми́тники визнали Божу волю за слушну, — і охристились Івановим хрищенням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 30, 'А фарисеї й зако́нники відкинули Божу волю про себе, — і не христились від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 31, 'І промовив Госпо́дь: „До кого ж уподо́блю людей цього роду? І до ко́го подібні вони?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 32, 'Подібні вони до дітей, що на ринку сидять й один о́дного кличуть та кажуть: „Ми вам грали були, а ви не танцювали, ми співали вам жа́лібно, та не плакали ви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 33, 'Бо прийшов Іван Христитель, що хліба не їсть і вина не п\'є, а ви кажете: „Має він де́мона“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 34, 'Прийшов же Син Лю́дський, що їсть і п\'є, а ви кажете: „Чоловік Цей ласу́н і п\'яни́ця, Він при́ятель ми́тників і грішників“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 35, 'І ви́правдалася мудрість усіма́ своїми діла́ми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 36, 'А один із фарисеїв просив Його, щоб спожив Він із ним. І, прийшовши до дому того фарисея, Він сів при столі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 37, 'І ось жінка одна, що була в місті, грішниця, як дізналась, що, Він у фарисеєвім домі засів при столі, аляба́строву пляшечку мира принесла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 38, 'і, припавши до ніг Його зза́ду, плачучи́, почала обливати слізьми́ Йому ноги, і воло́ссям своїм витирала, но́ги Йому цілувала та миром масти́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 39, 'Побачивши це, фарисей, що покликав Його, міркував собі, ка́жучи: „Коли б був Він пророк, Він би знав, хто́ ото й яка жінка до Нього торкається, — бож то грішниця!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 40, 'І озвався Ісус та й говорить до нього: „Маю, Си́моне, дещо сказати тобі“. А той відказав: „Кажи, Учителю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 41, 'І промовив Ісус: „Були два боржники́ в одно́го віри́теля; один був винен п\'ятсо́т динаріїв, а другий — п\'ятдеся́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 42, 'Як вони ж не могли заплатити, простив він обо́м. Скажи ж, котри́й із них більше полюбить його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 43, 'Відповів Си́мон, говорячи: „Ду́маю, — той, кому більше простив“. І сказав Він йому: „Розсудив ти правдиво“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 44, 'І, оберну́вшись до жінки, Він промовив до Си́мона: „Чи ти бачиш цю жінку? Я прибув у твій дім, — ти на ноги Мої не подав і води, а вона окропи́ла слізьми́ Мої ноги й обтерла воло́ссям своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 45, 'Поцілунку не дав ти Мені, — а вона, відко́ли ввійшов Я, Мої но́ги цілує невпинно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 46, 'Голови ти Моєї оливою не намастив, — а вона миром но́ги мої намастила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 47, 'Ось тому говорю́ Я тобі: „Числе́нні гріхи її про́щені, бо багато вона полюбила. Кому́ ж мало прощається, такий мало любить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 48, 'А до неї промовив: „Прощаються тобі гріхи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 49, 'А ті, що сиділи з Ним при столі, почали гомоніти про себе: „Хто́ ж це Таки́й, що прощає й гріхи?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 50, 'А до жінки сказав Він: „Твоя віра спасла тебе, — іди з ми́ром собі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 1, 'І сталось, що Він після того прохо́див містами та се́лами, проповідуючи та звіщаючи Добру Нови́ну про Боже Царство. Із ним Дванадцять були́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 2, 'та дехто з жіно́к, що були́ вздоро́влені від злих ду́хів і хвороб: Марія, Магдали́ною звана, що з неї сім де́монів вийшло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 3, 'і Іва́нна, дружи́на Ху́дзи, урядника Іродового, і Суса́нна, і інших багато, що маєтком своїм їм служили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 4, 'І, як зібралось багато наро́ду, і з міста до Нього поприхо́дили, то Він промовляти став притчею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 5, '„Ось вийшов сіяч, щоб посіяти зе́рно своє. І, як сіяв, упало одне край дороги, — і було повито́птуване, а птахи небесні його повидзьо́бували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 6, 'Друге ж упало на ґрунт кам\'яни́стий, — і, зійшовши, усохло, не мало бо во́гкости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 7, 'А інше упало між те́рен, — і вигнався те́рен, і його поглуши́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 8, 'Інше ж упало на добру землю, — і, зійшовши, уродило стокро́тно“. Це сказавши, закликав: „Хто має ву́ха, щоб слухати, — нехай слухає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 9, 'Запитали ж Його Його у́чні, гово́рячи: „Що́ визначає ця притча?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 10, 'А Він відказав: „Вам дано пізнати таємни́ці Божого Царства, а іншим у при́тчах, щоб „дивились вони — і не бачили, слухали — і не розуміли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 11, 'Ось що́ означає ця притча: Зе́рно — це Боже Слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 12, 'А котрі́ край дороги, — це ті, хто слухає, але по́тім приходить диявол, і забирає слово з їхнього серця, щоб не ввірували й не спаслися вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 13, 'А що на кам\'яни́стому ґрунті, — це ті, хто тільки почує, то слово приймає з радістю; та кореня не мають вони, вірують доча́сно, — і за час випробо́вування відпадають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 14, 'А що впало між те́рен, — це ті, хто слухає слово, але, хо́дячи, бувають придушені кло́потами, та багатством, та життєви́ми розко́шами, — і пло́ду вони не дають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 15, 'А те, що на добрій землі, — це оті, хто як слово почує, береже його в щирому й доброму серці, — і плід приносять вони в терпеливості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 16, 'А сві́тла засвіченого ніхто не покриває посу́диною, і не ставить під ліжко, але ставить його на світильни́к, щоб бачили світло, хто входить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 17, 'Немає нічого захо́ваного, що не виявиться, ні таємного, що воно не пізнається, і не ви́йде ная́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 18, 'Тож пильнуйте, як слухаєте! Бо хто має, то дасться йому́, хто ж не має, — забереться від нього і те, що, здається йому́, ніби має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 19, 'До Нього ж прийшли були мати й брати Його, та через наро́д не могли доступи́тись до Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 20, 'І сповістили Йому: „Твоя мати й брати Твої он стоять о́сторонь, і бажають побачити Тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 21, 'А Він відповів і промовив до них: „Моя мати й брати Мої — це ті, хто слухає Боже Слово, і виконує!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 22, 'І сталось, одно́го з тих днів увійшов Він до чо́вна, а з Ним Його у́чні. І сказав Він до них: „Перепли́ньмо на другий бік озера“. І відча́лили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 23, 'А коли вони пли́вли, Він заснув. І зняла́ся на озері буря велика, аж вода заливати їх стала, і були в небезпе́ці вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 24, 'І вони підійшли, і розбудили Його та й сказали: „Учителю, Учителю, гинемо!“Він же встав, наказав бурі й хвилям, — і вони вщу́хнули, і тиша настала!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 25, 'А до них Він сказав: „Де ж ваша віра?“І дивувались вони, перестра́шені, і говорили один до одно́го: „Хто ж це такий, що вітра́м і воді Він наказує, а вони Його слухають?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 26, 'І вони припливли́ до землі Гадари́нської, що навпроти Галілеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 27, 'І, як на землю Він вийшов, перестрів Його один чоловік із міста, що довгі ро́ки мав він де́монів, не вдягався в одежу, і мешкав не в домі, а в гроба́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 28, 'А коли він Ісуса побачив, то закричав, повали́всь перед Ним, і голосом гучним закликав: „Що до мене Тобі, Ісусе, Сину Бога Всеви́шнього? Благаю Тебе, — не муч мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 29, 'Бо звелів Він нечистому духові вийти з люди́ни. Довгий час він хапа́в був його́, — і в\'язали його ланцюга́ми й кайда́нами, і стерегли його, але він розривав ланцюги́, — і демон гнав по пустині його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 30, 'А Ісус запитався його: „Як тобі на ім\'я́?“І той відказав: „Леґіо́н“, бо багато ввійшло в нього де́монів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 31, 'І благали Його, щоб Він їм не звелів іти в безо́дню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 32, 'Пасся ж там на горі гурт великий свине́й. І просилися демони ті, щоб дозволив піти їм у них. І дозволив Він їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 33, 'А як де́мони вийшли з того́ чоловіка, то в свиней увійшли. І череда кинулась із кручі до озера, — і потопи́лась.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 34, 'Пастухи ж, як побачили теє, що сталось, повтікали, та в місті й по се́лах звістили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 35, 'І вийшли побачити, що́ сталось. І прийшли до Ісуса й знайшли, що той чоловік, що де́мони вийшли із нього, сидів при нога́х Ісусових вдя́гнений та при умі, — і полякались.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 36, 'Самови́дці ж їм розповіли́, як видужав той біснуватий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 37, 'І ввесь наро́д Гадари́нського кра́ю став благати Його, щоб пішов Він від них, — великий бо страх обгорнув їх. Він же до чо́вна ввійшов і вернувся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 38, 'А той чоловік, що де́мони вийшли із нього, став благати Його, щоб бути при Ньому. Та Він відпустив його, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 39, '„Вернися до дому свого́, і розпові́ж, які речі великі вчинив тобі Бог!“І той пішов, і по ці́лому місту звістив, які речі великі для нього Ісус учинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 40, 'А коли повернувся Ісус, то люди Його прийняли́, бо всі чека́ли Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 41, 'Аж ось прийшов муж, Яір на ім\'я́, що був старши́м синагоги. Він припав до Ісусових ніг, та й став благати Його завітати до дому його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 42, 'Бо він мав одиначку дочку́, років десь із дванадцять, — і вмирала вона. А коли Він ішов, наро́д тиснув Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 43, 'А жінка одна, що дванадцять ро́ків хворою на кровоте́чу була́, що ніхто вздорови́ти не міг її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 44, 'підійшовши зза́ду, доторкнулась до кра́ю одежі Його, — і хвилі тієї спинилася їй кровоте́ча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 45, 'А Ісус запитав: „Хто доторкнувся до Мене?“Коли ж відмовлялися всі, то Петро відказав: „Учителю, наро́д коло Тебе он то́впиться й тисне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 46, 'Ісус же промовив: „Доторкнувсь хтось до Мене, бо Я відчув силу, що вийшла з Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 47, 'А жінка, побачивши, що вона не втаї́лась, трясучи́сь, підійшла та й упала перед Ним, і призналася перед усіма людьми́, чому доторкнулась до Нього, і як хвилі тієї одужала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 48, 'Він же промовив до неї: „До́чко, твоя віра спасла тебе; іди з ми́ром собі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 49, 'Як Він ще промовляв, приходить ось від старшини́ синагоги один та й говорить: „Дочка твоя вмерла, — не турбуй же Вчителя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 50, 'Ісус же, почувши, йому відповів: „Не лякайсь, тільки віруй, — і буде спасе́на вона“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 51, 'Прийшовши ж до дому, не пустив Він ніко́го з Собою ввійти, крім Петра, та Івана, та Якова, та батька дівча́ти, та матері.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 52, 'А всі плакали та голосили за нею. Він же промовив: „Не плачте, — не вмерла вона, але спить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 53, 'І насміхалися з Нього, бо знали, що вмерла вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 54, 'А Він узяв за руку її та й скрикнув, говорячи: „Дівчатко, вставай!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 55, 'І вернувся їй дух, — і хвилі тієї вона ожила́. І звелів дать їй їсти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 56, 'І здивувались батьки її. А Він наказав їм ніко́му не розповідати, що́ сталось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 1, 'І скликав Він Дванадцятьо́х, і дав їм силу та вла́ду над усіма де́монами, і вздоровля́ти неду́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 2, 'І послав їх проповідувати Царство Боже та вздоровляти недужих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 3, 'І промовив до них: „Не беріть нічо́го в дорогу: ані па́лиці, ані торби, ні хліба, ні срі́бла, ані майте по двоє убра́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 4, 'І в який дім уві́йдете, — зоставайтеся там, і звідти відходьте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 5, 'А як хто вас не при́йме, то, вихо́дячи з міста того, обтрусіть від ніг ваших по́рох на сві́дчення су́проти них“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 6, 'І вийшли вони, та й ходили по селах, звіщаючи Добру Нови́ну та всюди вздоровля́ючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 7, 'А І́род тетра́рх прочув усе, що сталось було, і вагався, бо дехто казали, що Іван це із мертвих устав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 8, 'а інші, що Ілля́ то з\'явився, а знов інші, що ожив це один із стародавніх пророків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 9, 'Тоді Ірод сказав: „Іванові стяв я голову; хто ж Оцей, що я чую про Нього речі такі?“І він намагався побачити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 10, 'А коли повернулись апо́столи, вони розповіли Йому, що́ зробили. І Він їх узяв, та й пішов самото́ю на місце безлюдне, біля міста, що зветься Віфсаі́да.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 11, 'А як люди дові́далися, то пішли вслід за Ним. І Він їх прийняв, і розповідав їм про Боже Царство, та тих уздоровля́в, хто потребува́в уздоро́влення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 12, 'А день став схилятися. І Двана́дцятеро підійшли та й сказали Йому: „Відпусти вже людей, — нехай вони йдуть у довко́лишні села й оселі спочити й здобути поживи, бо ми тут у місці безлю́дному!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 13, 'А Він їм сказав: „Дайте їсти їм ви“. Вони ж відказали: „Немає в нас більше, як п\'я́теро хліба й дві риби. Хіба пі́демо та купимо поживи для всього наро́ду цього́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 14, 'Бо було чоловіків десь тисяч із п\'ять. І сказав Він до у́чнів Своїх: „Розсадіть їх рядами — по п\'ятидесяти́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 15, 'І зробили отак, і всіх їх розсади́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 16, 'I Він узяв п\'ять хлібі́в та дві риби, споглянув на небо, поблагословив їх, і поламав, і дав учням, щоб клали наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 17, 'І всі їли й наси́тились! А з кусків позосталих зібрали дванадцять коші́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 18, 'І сталось, як насамоті Він молився, з Ним учні були́. І спитав Він їх, кажучи: „За кого Мене люди вважають?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 19, 'Вони ж відповіли́ та сказали: „За Івана Христителя, а ті за Іллю́, а інші, — що воскрес один із давніх пророків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 20, 'А Він запитав їх: „А ви за кого Мене маєте?“Петро ж відповів та сказав: „За Христа Божого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 21, 'Він же їм заказав, і звелів не казати ніко́му про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 22, 'І сказав Він: „Синові Лю́дському треба багато страждати, і Його відцураються старші, і первосвященики, і книжники, і буде Він убитий, — але третього дня Він воскресне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 23, 'А до всіх Він промовив: „Коли хоче хто йти вслід за Мною, хай зрече́ться само́го себе, і хай ві́зьме щоденно свого́ хреста, та й за Мною йде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 24, 'Бо хто хоче душу свою́ зберегти, той погубить її, а хто ради Мене згубить душу свою́, той її збереже́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 25, 'Яка ж ко́ристь люди́ні, що здобу́де ввесь світ, але́ занапа́стить чи згубить себе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 26, 'Бо хто буде Мене та Моєї науки соро́митися, того посоро́миться також Син Лю́дський, як при́йде у славі Своїй, і Отчій, і святих анголі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 27, 'Правдиво ж кажу́ вам, що деякі з тут-о прия́вних не скуштують смерти, аж поки не побачать Царства Божого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 28, 'І сталось після оцих слів днів за вісім, узяв Він Петра, і Івана, і Якова, та й пішов помолитись на го́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 29, 'І коли Він молився, то вигляд лиця Його переобрази́вся, а одежа Його стала біла й блиску́ча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 30, 'І ось два му́жі з Ним розмовляли, — були то Мойсей та Ілля́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 31, 'що з\'явилися в славі, і говорили про кінець Його, який в Єрусалимі Він мав докінчи́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 32, 'А Петро та прия́вні з ним були змо́рені сном, але, пробуди́вшись, бачили славу Його й обох му́жів, що стояли при Ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 33, 'І сталось, як із Ним розлучались вони, то промовив Петро до Ісуса: „Учителю, добре нам бути отут! Поставмо ж отут три шатра: для Тебе одне, і Мойсею одне, і одне для Іллі!“Він не знав, що говорить...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 34, 'А як він говорив це, насу́нула хмара та їх заслони́ла. І вони полякались, як стали ті вхо́дити в хмару.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 35, 'І почувся ось голос із хмари, який промовляв: „Це Син Мій Улю́блений, — Його слухайтеся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 36, 'А коли оцей голос лунав, Ісус Сам позостався. А вони промовча́ли, і ніко́му нічо́го тих днів не казали, що́ бачили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 37, 'А наступного дня, як спустились з гори, перестрів Його на́товп великий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 38, 'І закричав ось один чоловік із наро́ду й сказав: Учителю, благаю Тебе, — зглянься над сином моїм, бо одина́к він у мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 39, 'А ото дух хапає його, і він нагло кричить, і трясе ним, аж той пі́ну пускає. І, вимучивши він його, насилу відхо́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 40, 'І у́чнів Твоїх я благав його вигнати, та вони не змогли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 41, 'А Ісус відповів і промовив: „О, роде невірний й розбе́щений, — доки бу́ду Я з вами, і терпітиму вас? Приведи́ свого сина сюди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 42, 'А як той іще йшов, де́мон кинув його та затряс. Та Ісус заказав тому духу нечистому, — і вздоро́вив дитину, і віддав її батькові її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 43, 'І всі дивувалися ве́личі Божій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 44, '„Вкладіть до вух своїх ці ось слова: Людський Син буде виданий людям до рук“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 45, 'Проте́ не зрозуміли вони цього слова, було бо закрите від них, щоб його не збагнули, та боялись Його запита́ти про це слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 46, 'І прийшло їм на думку: хто б найбільший з них був?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 47, 'А Ісус, думку серця їх знавши, узяв дитину, і поставив її біля Себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 48, 'І промовив до них: „Як хто при́йме дитину оцю в Ім\'я́ Моє, Мене він приймає, а як хто Мене при́йме, приймає Того, Хто послав Мене. Хто бо найменший між вами всіма́, — той великий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 49, 'А Іван відповів і сказав: „Учителю, ми бачили одно́го чоловіка, що Ім\'я́м Твоїм де́монів виганяв, і ми заборонили йому, бо він з нами не ходить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 50, 'Ісус же йому́ відказав: „Не забороняйте, — бо хто не проти вас, той за вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 51, 'І сталось, коли дні вознесіння Його наближались, Він постановив піти в Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 52, 'І Він посланців вислав перед Собою. І пішли вони, та й прибули́ до села самарянського, щоб ночі́влю Йому пригото́вити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 53, 'А ті не прийняли Його, бо йшов Він у на́прямі Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 54, 'Як побачили ж те учні Яків й Іван, то сказали: „Господи, — хочеш, то ми скажемо, „щоб огонь зійшов з неба та винищив“їх, як і Ілля був зробив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 55, 'А Він оберну́вся до них, їм докорив та й сказав: „Ви не знаєте, якого ви духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 56, 'Бо Син Лю́дський прийшов не губи́ть душі лю́дські, а спасати!“І пішли вони в інше село.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 57, 'І сталось, як дорогою йшли, сказав був до Нього один: „Я піду́ за Тобою, хоч би куди Ти пішов“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 58, 'Ісус же йому́ відказав: „Мають но́ри лисиці, а гні́зда — небесні пташки́, — Син же Лю́дський не має ніде́ й голови прихили́ти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 59, 'I промовив до другого Він: „Іди за Мною“. А той відказав: „Дозволь мені перше піти, і батька свого́ похова́ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 60, 'Він же йому відказав: „Зостав мертвим ховати мерці́в своїх. А ти йди та звіщай Царство Боже“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 61, 'А інший сказав був: „Господи, я піду́ за Тобою, та дозволь мені перш попрощатись із своїми дома́шніми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 62, 'Ісус же промовив до нього: „Ніхто з тих, хто кладе́ свою руку на плуга та назад озира́ється, не надається до Божого Царства!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 1, 'Після того призна́чив Господь і інших Сімдеся́т, і послав їх по двох перед Себе до кожного міста та місця, куди Сам мав іти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 2, 'І промовив до них: „Хоч жни́во велике, та робі́тників мало; тож благайте Господаря жни́ва, щоб робі́тників вислав на жни́во Своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 3, 'Ідіть! Оце посилаю Я вас, як ягнят між вовки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 4, 'Не носіть ні кали́тки, ні торби, ні санда́ль, і не вітайте в дорозі ніко́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 5, 'Як до дому ж якого ви вві́йдете, то найперше кажіть: „Мир дому цьому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 6, 'І коли син миру там буде, то спочи́не на ньому ваш мир, коли ж ні — до вас ве́рнеться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 7, 'Зоставайтеся ж у домі тім самім, споживайте та пийте, що є в них, — бо вартий робі́тник своєї заплати. Не ходіть з дому в дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 8, 'А як при́йдете в місто яке, і вас при́ймуть, — споживайте, що вам подадуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 9, 'Уздоро́влюйте хворих, що в нім, промовляйте до них: „Набли́зилося Царство Боже до вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 10, 'А як при́йдете в місто яке, і вас не приймуть, то вийдіть на вулиці його та й кажіть:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 11, '„Ми обтру́шуємо вам навіть порох, що прилип до нас із вашого міста. Та знайте оце, що набли́зилося Ца́рство Боже!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 12, 'Кажу вам: того дня легше буде содо́млянам, аніж місту тому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 13, '„Горе тобі, Хоразі́не, горе тобі, Віфсаїдо! Бо коли б то у Тирі й Сидоні були відбули́ся ті чу́да, що сталися в вас, то давно б вони покаялися в волосяни́ці та в попелі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 14, 'Але на суді відрадніш буде Тиру й Сидону, як вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 15, 'А ти, Капернау́ме, що „до неба піднісся, — аж до аду ти зійдеш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 16, 'Хто слухає вас — Мене слухає, хто ж погорджує вами — погорджує Мною, хто ж погорджує Мною — погорджує Тим, Хто послав Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 17, 'А ті Сімдеся́т повернулися з радістю, кажучи: „Господи, — навіть де́мони ко́ряться нам у Ім\'я́ Твоє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 18, 'Він же промовив до них: „Я бачив того сатану, що з неба спадав, немов блискавка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 19, 'Ось Я вла́ду вам дав наступати на змій та скорпіо́нів, і на всю силу ворожу, — і ніщо вам не зашко́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 20, 'Та не тіштеся тим, що вам ко́ряться духи, але тіштесь, що ваші ймення записані в небі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 21, 'Того ча́су Ісус звеселився був Духом Святим і промовив: „Прославляю Тебе, Отче, Господи неба й землі, що втаїв Ти оце від премудрих і розумних, та його немовлятам відкрив. Так, Отче, бо Тобі так було до вподоби!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 22, 'Передав Мені все Мій Отець. І не знає ніхто, хто є Син, — тільки Отець, і хто Отець — тільки Син, та кому Син захоче відкрити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 23, 'І, звернувшись до учнів, наодинці їм сказав: „Блаженні ті очі, що бачать, що́ бачите ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 24, 'Кажу ж вам, що багато пророків і царів бажали побачити, що бачите ви — та й не бачили, і почути, що́ чуєте ви — і не чули!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 25, 'І підвівсь ось зако́нник один, і сказав, Його випробо́вуючи: „Учителю, що́ робити мені, щоб вічне життя осягну́ти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 26, 'Він же йому відказав: „Що́ в Зако́ні написано, як ти читаєш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 27, 'А той відповів і сказав: „Люби Господа Бога свого́ всім серцем своїм, і всією душею своєю, і всією силою своєю, і всім своїм розумом“, і свого ближнього, як само́го себе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 28, 'Він же йому́ відказав: „Правильно ти відповів. Роби це, — і будеш жити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 29, 'А той бажав сам себе ви́правдати, та й сказав до Ісуса: „А хто то мій ближній?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 30, 'А Ісус відповів і промовив: „Один чоловік ішов з Єрусалиму до Єрихо́ну, і попався розбійникам, що обдерли його, і завдали́ йому рани, та й утекли́, покинувши ле́две живого його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 31, 'Прохо́див випа́дком тією дорогою священик один, побачив його, — і проминув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 32, 'Так само й Левит надійшов на те місце, поглянув, — і теж проминув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 33, 'Прохо́див же там якийсь самаряни́н, та й натра́пив на нього, і, побачивши, змилосе́рдився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 34, 'І він підійшов, і обв\'язав йому рани, наливши оливи й вина. Потому його посадив на худо́бину власну, і приставив його до гостиниці, та й клопота́вся про нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 35, 'А другого дня, від\'їжджавши, вийняв він два динарії, та й дав їх госпо́дареві й проказав: „Заопікуйся ним, а як більше що витратиш, — заплачу́ тобі, як верну́ся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 36, 'Котри́й же з цих трьох — на думку твою — був ближній тому, хто попався розбійникам?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 37, 'А він відказав: „Той, хто вчинив йому ми́лість“. Ісус же сказав йому: „Іди, — і роби так і ти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 38, 'І сталось, коли вони йшли, Він прийшов до одно́го села. Одна ж жінка, Марта їй на ім\'я́, прийняла Його в дім свій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 39, 'Була ж в неї сестра, що звалась Марія; вона сіла в ногах у Ісуса, та й слухала сло́ва Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 40, 'А Марта великою по́слугою клопота́лась, а спинившись, сказала: „Господи, чи байду́же Тобі, що на мене саму́ полишила служити сестра моя? Скажи ж їй, щоб мені помогла“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 41, 'Госпо́дь же промовив у відповідь їй: „Марто, Марто, — турбуєшся й жу́ришся ти про багато чого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 42, 'а потрібне одне. Марія ж обрала найкращу ча́стку, яка не відбереться від неї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 1, 'І сталось, як молився Він у місці одно́му, і коли перестав, озвався до Нього один із Його у́чнів: „Господи, навчи нас молитися, як і Іван навчив своїх учнів.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 2, 'Він же промовив до них: „Коли молитеся, говоріть: „Отче наш, що на небі! Нехай святиться Ім\'я́ Твоє, нехай при́йде Царство Твоє, нехай бу́де воля Твоя, як на небі, так і на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 3, 'Хліба нашого щоденного дай нам на кожний день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 4, 'І прости нам наші гріхи́, бо й самі ми прощаємо кожному боржнико́ві нашому. І не введи нас у випробо́вування, але визволи нас від лукавого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 5, 'І сказав Він до них: „Хто з вас матиме при́ятеля, і пі́де до нього опі́вночі, і скаже йому: „Позич мені, друже, три хліби́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 6, 'бо прийшов із дороги до мене мій при́ятель, я ж не маю, що́ дати йому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 7, 'А той із сере́дини в відповідь скаже: „Не роби мені кло́поту, — уже за́мкнені двері, і мої діти зо мною на ліжкові. Не можу я встати та дати тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 8, 'Кажу вам: коли він не встане, і не дасть ради дружби йому, то за докуча́ння його він устане та й дасть йому, скільки той потребу́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 9, 'І Я вам кажу́: просіть, — і буде вам да́но, шукайте — і знайдете, стукайте — і відчинять вам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 10, 'Бо кожен, хто просить — одержує, хто шукає — знахо́дить, а тому́, хто стукає — відчинять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 11, 'І котри́й з вас, батьків, як син хліба проси́тиме, подасть йому каменя? Або, як проситиме риби, замість риби подасть йому га́дину?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 12, 'Або, як яйця́ він проситиме, дасть йому скорпіо́на?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 13, 'Отож, коли ви, бувши злі, потра́пите добрі дари́ своїм дітям давати, — скільки ж більше Небесний Отець подасть Духа Святого всім тим, хто проситиме в Нього?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 14, 'Раз виго́нив Він де́мона, який був німий. І коли демон вийшов, німий заговорив. А наро́д дивувався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 15, 'А деякі з них гомоніли: „Виганяє Він де́монів силою Вельзеву́ла, князя де́монів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 16, 'А інші, випробовуючи, хотіли від Нього ознаки із неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 17, 'Він же знав думки їхні, і промовив до них: „Кожне царство, само проти себе поді́лене, запусті́є, і дім на дім упаде́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 18, 'А коли й сатана́ поділився сам супроти себе, — як стоятиме царство його? А ви кажете, що Вельзеву́лом виго́ню Я демонів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 19, 'Коли ж Вельзеву́лом виго́ню Я демонів, то чим виганяють їх ваші сини? Тому вони стануть вам су́ддями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 20, 'А коли пальцем Божим виго́ню Я де́монів, то справді прийшло до вас Боже Царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 21, 'Коли сильний збройно свій двір стереже, то в безпе́ці маєток його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 22, 'Коли ж дужчий від нього його нападе́ й переможе, то всю збро́ю йому забере́, на яку покладався був той, і роздасть свою здо́бич.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 23, 'Хто не зо Мною, той проти Мене; і хто не збирає зо Мною, той розкидає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 24, 'Коли дух нечистий виходить з люди́ни, то блукає місцями безві́дними, відпочинку шукаючи, але, не знахо́дячи, каже: „Верну́ся до хати своєї, звідки я вийшов“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 25, 'А як ве́рнеться він, то хату знахо́дить заме́тену й при́брану.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 26, 'Тоді він іде та й приводить сімох інших духів, лютіших за себе, — і входять вони та й живуть там. І буде останнє люди́ні тій гірше за перше!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 27, 'І сталось, як Він це говорив, одна жінка з народу свій голос підне́сла й сказала до Нього: „Блаженна утро́ба, що носила Тебе, і груди, що Ти ссав їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 28, 'А Він відказав: „Так. Блаженні ж і ті, хто слухає Божого Слова і його береже́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 29, 'А як люди збира́лися, Він почав промовляти: „Рід цей — рід лукавий: він ознаки шукає, та ознаки йому не дадуть, крім ознаки проро́ка Йо́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 30, 'Бо як Йо́на ознакою був для ніневі́тян, так буде й Син Лю́дський для роду цього́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 31, 'Цариця півде́нна на суд стане з му́жами роду цього́, — і їх засудить, бо вона з кінця світу прийшла Соломо́нову мудрість послухати. А тут ось Хтось більший, аніж Соломо́н!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 32, 'Ніневі́тяни стануть на суд із цим родом, — і засудять його, вони бо пока́ялися через Йонину проповідь. А тут ось Хтось більший, ніж Йона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 33, 'Засвіченого світла ніхто в схо́вок не ставить, ані під посу́дину, але на світи́льника, щоб бачили світло, хто входить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 34, 'Око твоє — то світи́льник для тіла; тому́, як око твоє буде дуже, то й усе тіло твоє буде світле. А коли б твоє око нездатне було́, то й усе тіло твоє буде темне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 35, 'Отож, уважай, щоб те світло, що в тобі, не сталося те́мрявою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 36, 'Бо коли твоє тіло все світле, і не має жа́дної темної частини, то все буде світле, неначе б світильник ося́яв блиском тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 37, 'Коли Він говорив, то один фарисей став благати Його пообідати в нього. Він же прийшов та й сів при столі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 38, 'Фарисей же, побачивши це, здивувався, що перед обідом Він перш не обмився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 39, 'Господь же промовив до нього: „Тепер ви, фарисеї, он чистите зо́внішність ку́хля та миски, а ваше нутро́ повне зди́рства та кривди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 40, 'Нерозумні, — чи ж Той, Хто створив оте зо́внішнє, не створив Він і внутрішнє?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 41, 'Тож милостиню подавайте з унутрішнього, — і ось все буде вам чисте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 42, 'Горе вам, фарисеям, — бо ви десятину даєте з м\'яти та рути й усякого зілля, але обминаєте суд та Божу любов; це треба робити, і того́ не лишати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 43, 'Горе вам, фарисеям, що любите перші лавки́ в синагогах та привіти на ри́нках!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 44, 'Горе вам, — бо ви як гроби́ непомітні, — люди ж ходять по них і не знають того“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 45, 'Озвався ж один із зако́нників, і каже Йому: „Учителю, кажучи це, Ти і нас ображаєш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 46, 'А Він відказав: „Горе й вам, зако́нникам, бо ви на людей тягарі́ накладаєте, які важко носити, а самі й одним пальцем своїм не дото́ркуєтесь тягарі́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 47, 'Горе вам, бо надгро́бки пророкам ви ставите, — ваші ж батьки́ були їх повбивали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 48, 'Так, — визнаєте ви й хвалите вчинки батьків своїх: бо вони їх повбивали, а ви їм надгро́бки будуєте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 49, 'Через те й мудрість Божа сказала: „Я пошлю їм пророків й апо́столів, — вони ж декого з них повбивають, а декого ви́женуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 50, 'щоб на роді оцім відомстилася кров усіх пророків, що пролита від ство́рення світу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 51, 'від крови Авеля аж до крови Заха́рія, що загинув між же́ртівником і храмом“! Так, кажу вам, — відомсти́ться це все на цім роді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 52, 'Горе вам, зако́нникам, бо взяли́ ви ключа́ розумі́ння: самі не ввійшли, і тим, хто хотів увійти, борони́ли!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 53, 'А коли Він вихо́див ізвідти, стали книжники та фарисеї сильно тиснути та від Нього допитуватись про багато речей, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 54, 'вони чатува́ли на Нього, щоб зловити що з уст Його (і щоб оска́ржити Його́).');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 1, 'Того ча́су, як зібралися десятитисячні на́товпи наро́ду, — аж топтали вони один о́дного, — Він почав промовляти перш до учнів Своїх: „Стережіться ро́зчини фарисейської, що є лицемі́рство!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 2, 'Бо немає нічо́го захо́ваного, що не відкриється, ні таємного, що не ви́явиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 3, 'Тому все, що́ казали ви по́темки, — при світлі почується, що́ ж шептали на вухо в коморах, — на даха́х проповідане бу́де.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 4, 'Кажу́ ж вам, Своїм друзям: Не бійтеся тих, хто тіло вбиває, а потім більш нічого не може вчинити!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 5, 'Але вкажу вам, кого треба боятися: Бійтесь того́, хто має вла́ду, убивши, укинути в геє́нну. Так, кажу́ вам: Того бійтеся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 6, 'Чи ж не п\'ять горобців продають за два гро́ші? Та проте перед Богом із них ні один не забутий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 7, 'Але навіть воло́сся вам на голові порахо́ване все. Не бійтесь: вартніші ви за багатьох горобців!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 8, 'Кажу ж вам: Кожного, хто перед людьми́ Мене визнає, того визнає й Син Лю́дський перед Ангола́ми Божими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 9, 'Хто ж Мене відцурається перед людьми́, того відцураються перед ангола́ми Божими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 10, 'І кожному, хто скаже слово на Лю́дського Сина, йому про́ститься; а хто зневажа́тиме Духа Святого, — не про́ститься.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 11, 'А коли вас водитимуть до синагог, і до уря́дів, і до влад, — не турбуйтеся, я́к або що́ відповідати чи що́ говорити, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 12, 'Дух бо Святий вас навчи́ть тієї години, що́ потрібно казати!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 13, 'І озвався до Нього один із наро́ду: „Учителю, скажи братові моєму, щоб він спа́дщиною поділився зо мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 14, 'А Він відказав йому: „Чоловіче, хто поставив над вами Мене за суддю або за поді́льника?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 15, 'І промовив до них: „Глядіть, остерігайтеся всякої заже́рливости, — бо життя чоловіка не залежить від достатку маєтку його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 16, 'I Він розповів їм притчу, говорячи: „В одного багача гойно нива вродила була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 17, 'І міркував він про себе й казав: „Що́ робити, що не маю куди зібрати пло́дів своїх?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 18, 'І сказав: „Оце я зроблю́, — порозва́люю клу́ні свої, і просторні́ші поставлю, і позбираю туди пашню́ свою всю та свій достаток.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 19, 'І скажу́ я душі своїй: „Душе́, маєш багато добра, на багато ро́ків скла́деного. Спочивай, їж та пий, і веселися!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 20, 'Бог же до нього прорік: „Нерозумний, — но́чі цієї ось душу твою зажадають від тебе, і кому позоста́неться те, що ти був наготовив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 21, 'Так буває і з тим, хто збирає для себе, та не багатіє в Бога“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 22, 'І промовив Він у́чням Своїм: „Через це кажу вам: Не журіться про життя, — що́ ви будете їсти, і ні про тіло, — у що́ ви зодя́гнетеся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 23, 'Бо більше від ї́жі життя, а тіло від одягу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 24, 'Погляньте на га́йвороння, що не сіють, не жнуть, нема в них комори, ні клуні, — проте Бог їх годує. Скільки ж більше за птахів ви варті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 25, 'Хто ж із вас, коли жу́риться, добавити зможе до зросту свого бодай ліктя одно́го?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 26, 'Тож коли ви й найменшого не подола́єте, то чого ж ви про інше клопо́четеся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 27, 'Погляньте на ті он ліле́ї, як вони не пряду́ть, ані тчуть. Але́ говорю́ вам, що й сам Соломон у всій славі своїй не вдягався отак, як одна з них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 28, 'І коли он траву, що сьогодні на полі, а взавтра до пе́чі вкидається, Бог так зодягає, скільки ж краще зодя́гне Він вас, маловірні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 29, 'І не шукайте, що́ будете їсти, чи що́ будете пити, і не клопочіться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 30, 'Бо всього цього́ й люди світу оцьо́го шукають, Отець же ваш знає, що того́ вам потрібно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 31, 'Шукайте отож Його Царства, а це вам додасться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 32, 'Не лякайся, черідко мала́, бо сподо́балося Отцю вашому дати вам Царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 33, 'Продавайте достатки свої та ми́лостиню подавайте. Робіть кали́тки собі не старі́ючі, — неви́черпний скарб той у небі, куди не закрадається зло́дій, і міль де не то́чить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 34, 'Бо де скарб ваш, там буде й серце ваше!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 35, 'Нехай підпере́зані будуть вам сте́гна, а світла ручні́ позасвічувані!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 36, 'І будьте подібними до людей, що очікують пана свого́, коли ве́рнеться він із весі́лля, щоб, як при́йде й застукає, відчинити негайно йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 37, 'Блаженні раби ті, що пан, коли при́йде, то зна́йде, що пильнують вони! Поправді кажу́ вам: підпере́жеться він і їх посадо́вить, і, підійшовши, буде їм послуго́вувати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 38, 'І коли при́йде о другій чи при́йде о третій сторо́жі, та зна́йде так само, — блаженні вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 39, 'Знайте ж це, що коли б знав госпо́дар, о котрі́й то годині підкра́деться злодій, то він пильнував би, і́ свого б дому не дав підкопати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 40, 'Тому будьте готові і ви, — бо при́йде Син Лю́дський тієї години, коли ви не ду́маєте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 41, 'Озвався ж Петро: „Господи, чи до нас кажеш при́тчу оцю, чи до всіх?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 42, 'А Господь відказав: „Хто ж тоді вірний і мудрий домоправи́тель, що пан настано́вить його над своїми челя́дниками, щоб давати харч ви́значену своєчасно?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 43, 'Блаженний той раб, що пан його при́йде та зна́йде, що робить він так!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 44, 'Поправді кажу́ вам, що над всім маєтком своїм він поставить його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 45, 'А коли раб той скаже у серці своїм: „Заба́риться пан мій прийти“, і зачне бити слуг та служниць, їсти та пити та напиватися,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 46, 'то при́йде раба того пан за дня, якого він не сподівається, і о годині, якої не знає, — і розі́тне його пополовині, і визначить долю йому з невірними!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 47, 'А раб той, що знав волю свого госпо́даря, але не приготува́в, ані не вчинив згідно волі його, буде тяжко побитий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 48, 'Хто ж не знав, а вчинив каригі́дне, буде мало він битий. Тож від кожного, кому да́но багато, багато від нього й жадатимуть. А кому багато пові́рено, від того ще більше жадатимуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 49, 'Я прийшов огонь кинути на землю, — і як Я пра́гну, щоб він уже запала́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 50, 'Я ж маю христитися хрищенням, — і як Я мучуся, поки те спо́вниться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 51, 'Чи ви ду́маєте, що прийшов Я мир дати на землю? Ні, кажу вам, але по́діл!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 52, 'Віднині бо п\'ятеро в домі одно́му поді́лені бу́дуть: троє супроти двох, і двоє супроти трьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 53, 'Стане ба́тько на сина, а син проти батька, мати проти дочки́, а дочка́ проти матері, свекруха навпроти невістки своєї, а невістка навпроти свекрухи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 54, 'Промовив же Він і до наро́ду: „Як побачите хмару, що з за́ходу суне, то кажете за́раз: Зближається дощ“, — і так і буває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 55, 'А коли віє вітер півде́нний, то кажете: „Буде спеко́та“, — і́ буває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 56, 'Лицеміри, — лице неба й землі розпізна́ти ви вмієте, чому ж не розпізна́єте часу цього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 57, 'Чого ж і самі по собі ви не судите, що́ справедливе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 58, 'Бо коли до уря́ду ти йдеш зо своїм супроти́вником, попильнуй з ним зала́годити по дорозі, щоб тебе до судді не потяг він, а суддя щоб прислужникові не віддав тебе, а прислужник щоб не посадив до в\'язниці тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 59, 'Поправді кажу́ тобі: Не ви́йдеш ізвідти, поки не віддаси й останнього ше́ляга!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 1, 'Того ча́су прийшли були дехто, та й розповіли́ Йому про галіле́ян, що їхню кров Пила́т змішав був із їхніми жертвами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 2, 'Ісус же сказав їм у відповідь: „Чи ви ду́маєте, що оці галіле́яни, що так постраждали, грішніші були від усіх галіле́ян?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 3, 'Ні, кажу́ вам; та коли не покаєтеся, то загинете всі так!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 4, 'Або ті вісімнадцять, що ба́шта на них завалилась була́ в Сілоа́мі й побила їх, — чи ду́маєте, що ті винні були більш за всіх, що в Єрусалимі живуть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 5, 'Ні, кажу вам; та коли не покаєтеся, то загинете всі так!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 6, 'І Він розповів оцю притчу: „Один чоловік у своїм винограднику мав поса́джене фіґове дерево. І прийшов він шукати на ньому плоду, але не знайшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 7, 'І сказав винаре́ві: „Оце́ третій рік, відко́ли прихо́джу шукати плоду на цім фіґовім дереві, але не знахо́джу; зрубай його, — нащо й землю марну́є воно?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 8, 'А той йому в відповідь каже: „Позостав його, пане, і на цей рік, аж поки його обкопа́ю довко́ла, і обкладу його гноєм, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 9, 'чи року наступного пло́ду не вродить воно. Коли ж ні, то зрубаєш його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 10, 'І навчав Він в одній з синагог у суботу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 11, 'І ось там була́ одна жінка, що вісімнадцять ро́ків мала духа не́мочі, і була скорчена, і не могла ніяк ви́простатись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 12, 'А Ісус, як побачив її, то покликав до Себе. І сказав їй: „Жінко, — звільнена ти від неду́ги своєї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 13, 'І Він руки на неї поклав, — і вона зараз ви́просталась, — і стала сла́вити Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 14, 'Озвався ж старши́й синагоги, обу́рений, що Ісус уздоро́вив у суботу, і сказав до наро́ду: „Є шість день, коли працювати належить, — приходьте тоді та вздоро́влюйтеся, а не дня суботнього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 15, 'А Госпо́дь відповів і промовив до нього: „Лицеміре, — хіба́ ж не відв\'язує кожен із вас у суботу свого́ вола чи осла від я́сел, і не веде напоїти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 16, 'Чи ж цю дочку́ Авраамову, яку сатана був зв\'язав вісімнадцять ось ро́ків, не належить звільни́ти її суботнього дня від цих пут?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 17, 'А як Він говорив це, — засоро́милися всі Його супротивники. І тішився ввесь наро́д всіма славними вчинками, які Він чинив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 18, 'Він же промовив: „До чо́го подібне Царство Боже, і до чо́го його прирівняю?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 19, 'Подібне воно до гірчи́чного зе́рна, що взяв чоловік і посіяв його в своїм са́ді. І воно виросло, і деревом стало, і „ку́блилось птаство небесне на ві́ттях його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 20, 'І зно́ву сказав Він: „Із чим порівняю Я Боже Царство?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 21, 'Подібне до ро́зчини, що її бере жінка, і кладе на три мірки муки, аж поки все вки́сне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 22, 'І прохо́див містами та се́лами Він і навчав, до Єрусалиму просту́ючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 23, 'І озвався до Нього один: „Господи, — хіба буде мало спасе́них?“А Він відказав їм:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 24, '„Силку́йтеся ввійти тісни́ми ворі́тьми, бо кажу́ вам, — багато-хто будуть намага́тися ввійти, — та не зможуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 25, 'Як устане Госпо́дар та двері замкне́, ви зачне́те висто́ювати ізнадво́ру, та стукати в двері й казати: „Господи, — відчини нам!“А Він вам у відповідь скаже: „Не знаю Я вас, звідки ви!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 26, 'Тоді станете ви говорити: „Ми їли й пили перед Тобою і на вулицях наших навчав Ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 27, 'А Він вам відкаже: „Говорю́ вам, — не знаю Я, звідки ви. „Відійдіть від Мене всі, хто чинить неправду!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 28, 'Буде плач там і скре́гіт зубів, як побачите ви Авраама, та Ісака та Якова, та пророків усіх в Царстві Божім, себе ж — вигнаних геть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 29, 'І при́йдуть інші від сходу й захо́ду, і пі́вночі й пі́вдня, і при столі́ в Царстві Божім засядуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 30, 'І ось, є останні, що стануть за перших, і є перші, що стануть останніми!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 31, 'Тієї години підійшли дехто з фарисеїв, і сказали Йому: „Вийди собі, і піди звідси, — хоче бо І́род убити Тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 32, 'А Він відказав їм: „Ідіть і скажіть тому ли́сові: Ось де́монів Я виганяю, і чиню вздоро́влення, — сьогодні та взавтра, а третього дня закінчу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 33, 'Однак, Мені треба ходити сьогодні та взавтра, і ча́су найближчого, бо згинути не може пророк поза Єрусалимом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 34, 'Єрусалиме, Єрусалиме, що вбиваєш пророків та камену́єш посла́них до тебе! Скільки раз Я хотів позбирати дітей твоїх, як та квочка збирає під крила курча́ток своїх, — та ви не захотіли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 35, 'Ось „ваш дім зостається порожній для вас!“Говорю́ бо Я вам: Ви мене не побачите, аж поки не наста́не, що скажете: „Благослове́нний, Хто йде в Господнє Ім\'я́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 1, 'І сталось, що Він у суботу ввійшов був до дому одно́го з фарисейських старши́н, щоб хліба спожити, а вони назира́ли за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 2, 'І ото перед Ним був один чоловік, слабий на водя́нку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 3, 'Ісус же озвався й сказав до зако́нників та фарисеїв: „Чи вздоровляти в суботу годи́ться чи ні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 4, 'Вони ж мовчали. А Він, доторкну́вшись, уздоровив його та відпустив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 5, 'І сказав Він до них: „Коли осел або віл котро́гось із вас упаде́ до крини́ці, то хіба він не витягне зараз його дня суботнього?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 6, 'І вони не могли відповісти на це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 7, 'А як Він спостері́г, як вони собі перші місця вибирали, то сказав до запро́шених притчу:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 8, '„Коли́ хто покличе тебе на весі́лля, не сідай на першому місці, щоб не трапився хто поважні́ший за тебе з покли́каних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 9, 'і щоб той, хто покликав тебе та його, не прийшов і тобі не сказав: „Поступи́ся цьому місцем!“І тоді ти із соромом станеш займати місце останнє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 10, 'Але як ти будеш запро́шений, то приходь, і сідай на останньому місці, щоб той, хто покликав тебе, підійшов і сказав тобі: „При́ятелю, — сідай вище!“Тоді буде честь тобі перед покли́каними з тобою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 11, 'Хто́ бо підно́ситься — буде впоко́рений, а хто впокоря́ється — той піднесе́ться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 12, 'А тому́, хто Його був покликав, сказав Він: „Коли ти справляєш обід чи вече́рю, не клич дру́зів своїх, ні братів своїх, ані своїх ро́дичів, ні сусідів багатих, щоб так само й вони коли не запросили тебе, — і буде взає́мна ві́дплата тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 13, 'Але, як справляєш гости́ну, клич убогих, калік, кривих та сліпих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 14, 'і бу́деш блаженний, бо не мають вони чим віддати тобі, — віддасться ж тобі за воскресі́ння праведних!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 15, 'Як почув це один із отих, що сиділи з Ним при столі, то до Нього сказав: „Блаженний, хто хліб споживатиме в Божому Царстві!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 16, 'Він же промовив до нього: „Один чоловік споряди́в був велику вече́рю, і запросив багатьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 17, 'І послав він свого раба ча́су вече́рі сказати запро́шеним: „Ідіть, бо вже все нагото́вано“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 18, 'І зараз усі почали́ відмовлятися. Перший сказав йому: „Поле купив я, і маю потребу піти та оглянути його. Прошу́ тебе, — вибач мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 19, 'А другий сказав: „Я купив собі п\'ять пар волів, — і йду спро́бувати їх. Прошу́ тебе, — вибач мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 20, 'І знов інший сказав: „Одружився ось я, і через те я не мо́жу прибути“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 21, 'І вернувся той раб і па́нові своєму про все розпо́вів. Розгнівавсь госпо́дар тоді, та й сказав до свого раба: „Піди швидко на вулиці та на завулки міські́, і приведи́ сюди вбогих, і калік, і сліпих, і кривих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 22, 'І згодом раб повідо́мив: „Пане, сталося так, як звелів ти, та мі́сця є ще“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 23, 'І сказав пан рабові: „Піди на дороги й на за́городи, та й си́луй прийти, щоб напо́внився дім мій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 24, 'Кажу́ бо я вам, що жоден із запрошених му́жів тих не покушту́є моєї вечері. Бо багато покли́каних, та ви́браних мало!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 25, 'Ішло ж з Ним багато людей. І, звернувшись, сказав Він до них:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 26, '„Коли хто прихо́дить до Мене, і не знена́видить свого батька та матері, і дружи́ни й дітей, і братів і сесте́р, а до того й своє́ї душі́, — той не може буть учнем Моїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 27, 'І хто свого хреста не несе, і не йде вслід за Мною, — той не може бути учнем Моїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 28, 'Хто бо з вас, коли башту поставити хоче, перше не сяде й вида́тків не ви́рахує, — чи має потрібне на ви́конання,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 29, 'щоб, коли покладе він основу, але докінчи́ти не зможе, усі, хто побачить, не стали б сміятися з нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 30, 'говорячи: „Чоловік цей почав будувати, але докінчи́ти не міг“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 31, 'Або який цар, ідучи́ на війну супроти царя іншого, перше не сяде порадитися, чи спромо́жен він із десятьма́ тисячами стріти того, хто йде з двадцятьма́ тисячами проти нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 32, 'Коли ж ні, то, як той ще дале́ко, шле посольство до нього та й просить про мир.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 33, 'Так ото й кожен із вас, який не зречеться усьо́го, що має, не може бути учнем Моїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 34, 'Сіль — добра річ. Коли ж сіль несолоною стане, чим приправити її?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 35, 'Ні на землю, ні на гній не потрібна вона, — її геть викидають. Хто має ву́ха, щоб слухати, — нехай слу́хає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 1, 'Наближа́лись до Нього всі ми́тники й грі́шники, щоб послу́хати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 2, 'Фарисеї ж та книжники нарікали й казали: „Приймає Він грішників та з ними їсть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 3, 'А Він їм розповів оцю притчу, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 4, '„Котрий з вас чоловік, мавши сотню овець і загубивши одну з них, не покине в пустині тих дев\'ятидесяти́ й дев\'яти́, та й не пі́де шукати загинулої, аж поки не зна́йде її?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 5, 'А знайшовши, кладе на раме́на свої та радіє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 6, 'І, прийшовши додому, скликає він дру́зів і сусідів, та й каже до них: „Радійте зо мною, бо знайшов я вівцю свою тую загу́блену“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 7, 'Говорю вам, що так само на небі радітимуть більш за одно́го грішника, що кається, аніж за дев\'ятдесятьо́х і дев\'ятьо́х праведників, що не потребу́ють покая́ння!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 8, 'Або яка жінка, що має десять драхм, коли згубить драхму одну, не засвічує світла, і не мете хати, і не шукає уважно, аж поки не зна́йде?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 9, 'А знайшовши, кличе при́ятельок та сусідок та каже: „Радійте зо мною, бо знайшла я загу́блену дра́хму!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 10, 'Так само, кажу вам, радість буває в Божих анголі́в за одного грішника, який кається“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 11, 'І Він оповів: „У чоловіка одно́го було́ два сини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 12, 'І молодший із них сказав ба́тькові: „Дай мені, батьку, належну частину маєтку!“І той поділив поміж ними маєток.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 13, 'А по небагатьох днях зібрав син молодший усе, та й подавсь до далекого кра́ю, і розтратив маєток свій там, живучи́ марнотра́тно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 14, 'А як він усе прожив, настав голод великий у тім кра́ї, — і він став бідува́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 15, 'І пішов він тоді і пристав до одно́го з мешка́нців тієї землі, а той вислав його на поля́ свої па́сти свине́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 16, 'I бажав він напо́внити шлунка свого хоч стручка́ми, що їли їх свині, та ніхто не давав їх йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 17, 'Тоді він спам\'ята́вся й сказав: „Скільки в батька мого наймиті́в мають хліба аж на́дмір, а я отут з голоду гину!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 18, 'Устану, і піду́ я до батька свого, та й скажу йому: „Прогрішився я, отче, против неба та су́проти тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 19, 'Недостойний я вже зватись сином твоїм; прийми ж мене, як одно́го з своїх наймитів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 20, 'І, вставши, пішов він до ба́тька свого́. А коли він далеко ще був, його ба́тько вгледів його, — і перепо́внився жа́лем: і побіг він, і кинувсь на шию йому, і зачав цілувати його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 21, 'І озвався до нього той син: „Прогрішився я, отче, против неба та супроти тебе, і недостойний вже зватися сином твоїм“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 22, 'А батько рабам своїм каже: „Принесіть негайно одежу найкращу, і його зодягні́ть, і персня подайте на руку йому, а санда́лі на но́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 23, 'Приведіть теля відгодо́ване та заколіть, — будемо їсти й радіти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 24, 'бо цей син мій був мертвий — і ожив, був пропав — і знайшовся!“І почали веселитись вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 25, 'А син ста́рший його був на полі. І коли він ішов й наближа́вся до дому, почув музи́ки та танці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 26, 'І покли́кав одно́го зо слуг, та й спитав: „Що це таке?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 27, 'А той каже йому: „То вернувся твій брат, і твій ба́тько звелів заколоти теля відгодо́ване, — бож здоровим його він прийняв“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 28, 'І розгнівався той, — і ввійти не хотів. Тоді вийшов батько його й став просити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 29, 'А той відповів і до батька сказав: „Ото, стільки ро́ків служу́ я тобі, і ніко́ли нака́зу твого не пору́шив, — ти ж ніко́ли мені й козеняти не дав, щоб із при́ятелями своїми поті́шився я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 30, 'Коли ж син твій вернувся оцей, що проїв твій маєток із блудни́цями, — ти для нього звелів заколоти теля відгодо́ване“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 31, 'І сказав він йому: „Ти за́вжди зо мною, дитино, і все моє — то твоє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 32, 'Веселитись та тішитись треба було́, бо цей брат твій був мертвий — і ожив, був пропав — і знайшовся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 1, 'Оповів же Він й учням Своїм: „Один чоловік був багатий, і мав управи́теля, що оска́ржений був перед ним, ніби він перево́дить маєток його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 2, 'І він покликав його, і до нього сказав: „Що́ це чую про тебе? Дай звіт про своє управи́тельство, бо більше не зможеш рядити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 3, 'І управи́тель почав міркувати собі: „Що́ я маю робити, коли пан управи́тельство відійме від мене? Копати не можу, просити соромлюсь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 4, 'Знаю, що́ я зроблю́, щоб мене прийняли́ до домів своїх, коли буду я ски́нений із управи́тельства“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 5, 'І закликав він на́різно кожного з боржників свого пана, та її питається першого: „Скільки винен ти панові моєму?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 6, 'А той відказав: „Сто кадок оливи“. І сказав він йому: „Візьми ось розписку свою, швидко сідай та й пиши: п\'ятдеся́т“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 7, 'А потім питається другого: „А ти скільки винен?“І той відказав: „Сто кірців пшениці“. І сказав він йому: „Візьми ось розписку свою й напиши: вісімдеся́т“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 8, 'І пан похвалив управи́теля цього невірного, що він мудро вчинив. Бо сини цього світу в своїм поколінні мудріші, аніж сини світла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 9, 'І Я вам кажу́: „Набувайте дру́зів собі від багатства неправедного, щоб, коли промине́ться воно, прийняли вас до вічних осель.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 10, 'Хто вірний в найменшому, — і в великому вірний; і хто несправедливий в найменшому, — і в великому несправедливий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 11, 'Отож, коли в несправедливім багатстві ви не були вірні, — хто вам правдиве довірить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 12, 'І коли ви в чужому не були́ вірні, — хто ваше вам дасть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 13, 'Жа́ден раб не може служи́ть двом панам, — бо або одно́го знена́видить, а другого буде любити, або буде триматись одного, а другого зне́хтує. Не можете Богові й мамо́ні служити!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 14, 'Чули все це й фарисеї, що були́ сріблолюбці, та й стали сміятися з Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 15, 'Він же промовив до них: „Ви себе видаєте за праведних перед людьми́, але ваші серця знає Бог. Що бо високе в людей, те перед Богом гидо́та.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 16, 'Зако́н і Пророки були до Івана; відтоді Царство Боже благовісти́ться, і кожен силку́ється втиснутись в ньо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 17, 'Легше небо й земля промине́ться, аніж одна риса з Зако́ну загине.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 18, 'Кожен, хто дружи́ну свою відпускає, і бере собі іншу, той чинить пере́люб. І хто побереться з тією, яку хто відпустив, той чинить пере́люб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 19, 'Один чоловік був багатий, і зодягався в порфі́ру й віссо́н, і щоденно розкішно бенкетува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 20, 'Був і вбогий один, на ім\'я́ йому Ла́зар, що лежав у воріт його, стру́пами вкритий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 21, 'і бажав годува́тися кри́шками, що зо сто́лу багатого падали; пси ж прихо́дили й рани лизали йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 22, 'Та ось сталось, що вбогий умер, — і на Авраамове ло́но відне́сли його анголи́. Умер же й багатий, — і його поховали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 23, 'І, те́рплячи муки в аду́, звів він очі свої, та й побачив здаля Авраама та Лазаря на лоні його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 24, 'І він закричав та сказав: „Змилуйся, отче Аврааме, надо мною, і пошли мені Ла́заря, — нехай умочить у воду кінця свого пальця, і мого язика́ прохоло́дить, бо я мучуся в по́лум\'ї цім!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 25, 'Авраам же промовив: „Згадай, сину, що ти вже прийняв за життя свого добре своє, а Лазар так само — лихе; тепер він тут ті́шиться, а ти мучишся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 26, 'А крім того всього́, поміж нами та вами велика безо́дня поста́влена, так що ті, що хо́чуть, перехо́дити не можуть ізвідси до вас, ані не переходять ізвідти до нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 27, 'А він відказав: „Отож, отче, благаю тебе, щоб його ти послав у дім ба́тька мого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 28, 'бо п\'ятьох братів маю, — хай він їм засві́дчить, щоб і вони не прийшли на це місце стражда́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 29, 'Авраам же сказав: „Вони мають Мойсея й Пророків, — нехай слухають їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 30, 'А він відказав: „Ні ж бо, отче Аврааме, — але коли при́йде хто з мертвих до них, то покаються“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 31, 'Йому ж він відказав: „Як Мойсея й Пророків не слухають, то коли хто й із мертвих воскресне, — не йня́тимуть віри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 1, 'І сказав Він до учнів Своїх: „Неможливо, щоб спокуси не мали прийти; але горе тому́, через кого приходять вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 2, 'Краще б такому було́, коли б жо́рно млино́ве на шию йому почепити та й кинути в море, аніж щоб спокусив він одно́го з мали́х цих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 3, 'Уважайте на себе! Коли провини́ться твій брат, докори́ йому, а коли він покається, то вибач йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 4, 'І хоча б сім раз денно він провинивсь проти тебе, і сім раз звернувся до тебе, говорячи: „Каюся“, — вибач йому́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 5, 'І сказали апо́столи Господу: „Дода́й Ти нам віри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 6, 'А Господь відказав: „Коли б мали ви віру, хоч як зе́рно гірчи́чне, і сказали шовко́виці цій: „Ви́рвися з коренем і посадися до моря“, — то й послухала б вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 7, 'Хто ж із вас, мавши раба, що оре́ чи пасе, скаже йому, як він ве́рнеться з поля: „Негайно йди та сідай до столу“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 8, 'Але чи ж не скаже йому: „Приготуй що вече́ряти, і підпережись, і мені прислуго́вуй, аж поки я їстиму й питиму, а пото́му ти сам будеш їсти та пити“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 9, 'Чи ж він дякує тому рабові, що наказане виконав?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 10, 'Так і ви, коли зробите все вам нака́зане, то кажіть: „Ми — нікчемні раби, бо зробили лиш те, що повинні зробити були́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 11, 'І сталось, коли Він ішов до Єрусалиму, то прохо́див поміж Самарі́єю та Галілеєю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 12, 'І, коли вхо́див до одно́го села, перестріли Його десять мужів, слаби́х на проказу, що стали здалека.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 13, 'І голос піднесли вони та й казали: „Ісусе, Наставнику, — змилуйсь над нами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 14, 'І, побачивши їх, Він промовив до них: „Підіть і покажіться священикам!“І сталось, коли вони йшли, то очи́стились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 15, 'Один же з них, як побачив, що видужав, то верну́вся, і почав гучни́м голосом сла́вити Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 16, 'І припав він обличчям до ніг Його, складаючи дяку Йому. А то самаряни́н був...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 17, 'Ісус же промовив у відповідь: „Чи не десять очи́стилось, — а дев\'ять же де́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 18, 'Чому́ не вернулись вони хвалу́ Богові віддати, крім цього́ чужинця?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 19, 'І сказав Він йому: „Підведися й іди: твоя віра спасла тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 20, 'А як фарисеї спитали Його, коли Царство Боже при́йде, то Він їм відповів і сказав: „Царство Боже не при́йде помітно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 21, 'і не скажуть: „Ось тут“, або: „Там“. Бо Боже Царство всере́дині вас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 22, 'І сказав Він до учнів: „Прийдуть дні, коли побажаєте бачити один з днів Сина Лю́дського, — та не побачите.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 23, 'І скажуть до вас: „Ось тут“, чи: „Ось там“, — не йдіть, і за ним не біжіть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 24, 'Бо як бли́скавка, бли́снувши, світить із о́дного кра́ю під небом до другого кра́ю під небом, так буде Свого дня й Син Лю́дський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 25, 'А перше належить багато страждати Йому, і відцурається рід цей від Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 26, 'І, як було за днів Но́євих, то буде так само й за днів Сина Лю́дського:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 27, 'їли, пили, женилися, заміж вихо́дили, аж до того дня, коли „Ной увійшов до ковче́гу“; прийшов же потоп, — і всіх вигубив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 28, 'Так само, як було за днів Ло́тових: їли, пили, купували, продавали, садили, будували;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 29, 'того ж дня, як Лот вийшов із Содо́му, — огонь із сіркою з неба лину́в, і всіх погубив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 30, 'Так буде й того дня, як Син Лю́дський з\'я́виться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 31, 'Хто буде того дня на домі, а речі його будуть у домі, нехай їх забрати не зла́зить. Хто ж на полі, так само нехай назад не верта́ється, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 32, 'пам\'ятайте про Ло́тову дружи́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 33, 'Хто дба́тиме зберегти свою душу, — той погубить її, а коли хто погубить, — той оживить її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 34, 'Кажу вам: удвох будуть ночі тієї на о́дному ліжкові: один ві́зьметься, а другий поли́шиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 35, 'Дві моло́тимуть ра́зом, — одна ві́зьметься, а друга полишиться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 36, 'Двоє будуть на полі, — один ві́зьметься, а другий полишиться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 17, 37, 'І казали вони Йому в відповідь: „Де, Господи?“А Він відказав їм: „Де труп, там зберуться й орли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 1, 'І Він розповів їм і притчу про те, що треба молитися за́вжди, і не занепада́ти духом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 2, 'говорячи: „У місті якомусь суддя був один, що Бога не боявся, і людей не соро́мився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 3, 'У тому ж місті вдова перебува́ла, що до нього ходила й казала: „Оборони мене від мого супроти́вника!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 4, 'Але він довгий час не хотів. А зго́дом сказав сам до се́бе: „Хоч і Бога я не боюся, і людей не соро́млюся,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 5, 'але через те, що вдовиця оця докучає мені, то візьму́ в оборону її, щоб вона без кінця не ходила, і не докучала мені“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 6, 'І промовив Господь: „Чи чуєте, що́ говорить суддя цей неправедний?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 7, 'А чи ж Бог в оборону не ві́зьме обра́них Своїх, що голосять до Нього день і ніч, хоч і ба́риться Він щодо них?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 8, 'Кажу вам, що Він їм незаба́ром подасть оборону! Та Син Лю́дський, як при́йде, чи Він на землі зна́йде віру?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 9, 'А для деяких, що були себе певні, що вони ніби праведні, і за ніщо́ мали інших, Він притчу оцю розповів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 10, '„Два чоловіки до храму ввійшли помолитись, — один фарисе́й, а другий був ми́тник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 11, 'Фарисей, ставши, так молився про себе: „Дякую, Боже, Тобі, що я не такий, як інші люди: зди́рщики, неправедні, перелю́бні, або як цей ми́тник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 12, 'Я по́щу два ра́зи на тиждень, даю десятину з усьо́го, що тільки надба́ю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 13, 'А ми́тник здалека стояв, та й очей навіть звести до неба не смів, але бив себе в груди й казав: „Боже, будь милости́вий до мене грішного!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 14, 'Говорю́ вам, що цей повернувся до дому свого більш виправданий, аніж той. Бо кожен, хто підно́ситься, — буде пони́жений, хто ж понижа́ється, — той піднесе́ться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 15, 'До Нього ж прино́сили й немовлят, щоб до них доторкнувся, а учні, побачивши, їм докоряли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 16, 'А Ісус їх покликав та й каже: „Пустіте дітей, щоб до Мене прихо́дили, і не забороняйте їм, — бо таких Царство Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 17, 'Поправді кажу́ вам: Хто Божого Царства не при́йме, як дитя, той у нього не вві́йде!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 18, 'І запитався Його один і́з нача́льникі́в, говорячи: „Учителю Добрий, що робити мені, щоб вспадкува́ти вічне життя?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 19, 'Ісус же йому відказав: „Чого звеш Мене Добрим? Ніхто не є Добрий, — тільки Сам Бог!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 20, 'Знаєш заповіді: „Не чини пере́любу, не вбивай, не кради́, не свідку́й неправдиво, шануй свого батька та матір“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 21, 'А він відказав: „Усе́ це я виконав від юна́цтва свого́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 22, 'Як почув це Ісус, то промовив до нього: Одно́го тобі ще бракує: Розпро́дай усе, що ти маєш, і вбогим роздай, — і матимеш скарб свій на небі. Вертайся тоді, та й іди вслід за Мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 23, 'А він, коли почув це, то засумував, бо був ве́льми багатий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 24, 'Як побачив Ісус, що той засумував, то промовив: „Як тяжко багатим увійти в Царство Боже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 25, 'Бо верблю́дові легше пройти через го́лчине ву́шко, ніж багатому в Боже Царство ввійти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 26, 'Ті ж, що чули, спитали: „Хто́ ж тоді може спасти́ся?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 27, 'А Він відповів: „Неможливе лю́дям — можливе для Бога!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 28, 'І промовив Петро: „От усе ми покинули, — та й пішли за Тобою слідо́м“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 29, 'А Ісус відказав їм: „Поправді кажу́ вам: Немає такого, щоб покинув свій дім, або дружи́ну, чи братів, чи батьків, чи дітей ради Божого Царства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 30, 'і не одержав би значно більш цього́ ча́су, а в віці наступнім — життя вічне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 31, 'І, взявши Дванадцятьо́х, промовив до них: „Оце в Єрусалим ми йдемо́, і все здійсни́ться, що́ писали Пророки про Лю́дського Сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 32, 'Бо Він ви́даний буде поганам, і буде осмі́яний, і покривджений, і опльо́ваний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 33, 'і, збичува́вши, уб\'ють Його, — але третього дня Він воскресне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 34, 'Та з цього нічо́го вони не збагну́ли, і ця річ перед ними закрита була́, і ска́заного вони не розуміли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 35, 'І сталось, як Він наближа́вся був до Єрихо́ну, один невидю́щий сидів при дорозі й просив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 36, 'А коли він прочув, що проходить наро́д, то спитався: „Що́ це таке?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 37, 'А йому відказали, що проходить Ісус Назаряни́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 38, 'І став він кричати й казати: „Ісусе, Сину Давидів, — змилуйся надо мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 39, 'А ті, що попе́реду йшли, сварились на нього, щоб він замо́вк, а він іще більше кричав: „Сину Давидів, — змилуйся надо мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 40, 'І спинився Ісус, і привести його до Себе звелів. А коли той набли́зивсь до Нього, то Він запитався його:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 41, '„Що́ ти хочеш, щоб зробив Я тобі?“А той відповів: „Господи, — нехай стану видю́щим!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 42, 'Ісус же до нього сказав. „Стань видющий! Твоя віра спасла тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 18, 43, 'І зараз видю́щим той став, і пішов вслід за Ним, прославляючи Бога. А всі люди, бачивши це, віддали́ хвалу Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 1, 'І, ввійшовши Ісус, переходив через Єрихо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 2, 'І ось чоловік, що звався Закхе́й, — він був старши́й над ми́тниками, і був багатий, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 3, 'бажав ба́чити Ісуса, хто Він, але з-за наро́ду не міг, — бо мали́й був на зріст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 4, 'І, забігши вперед, він виліз на фіґове дерево, щоб бачити Його, бо Він мав побіч нього прохо́дити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 5, 'А коли на це місце Ісус підійшов, то поглянув уго́ру до нього й промовив: „Закхе́ю, — зійди за́раз додо́лу, бо сьогодні потрібно Мені бути в домі твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 6, 'І той зараз додо́лу ізліз, і прийняв Його з радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 7, 'А всі, як побачили це, почали нарікати, і казали: „Він до грішного мужа в гости́ну зайшов!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 8, 'Став же Закхе́й та й промовив до Господа: „Господи, половину маєтку свого́ я віддам ось убогим, а коли кого скри́вдив був чим, — верну вче́тверо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 9, 'Ісус же промовив до нього: „Сьогодні на дім цей спасі́ння прийшло, бо й він син Авраамів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 10, 'Син бо Лю́дський прийшов, щоб знайти та спасти, що загинуло!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 11, 'Коли ж вони слухали це, розповів Він іще одну при́тчу, бо Він був недалеко від Єрусалиму, вони ж ду́мали, що об\'я́виться Боже Царство тепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 12, 'Отож Він сказав: „Один чоловік, роду славного, відправлявся в далеку країну, щоб царство прийняти й вернутись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 13, 'І покликав він десятьох своїх рабів, дав їм десять мін, і сказав їм: „Торгуйте, аж поки верну́ся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 14, 'Та його громадяни його нена́виділи, і послали посланців услід за ним, кажучи: „Не хочемо, щоб він був над нами царем“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 15, 'І сталось, коли він верну́вся, як царство прийняв, то звелів посклика́ти рабів, яким срі́бло роздав, щоб довідатися, хто́ що набув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 16, 'І перший прийшов і сказав: „Пане, міна твоя принесла́ десять мін“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 17, 'І відказав він йому: „Гаразд, рабе добрий! Ти в мало́му був вірний, — володій десятьма́ містами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 18, 'І другий прийшов і сказав: „Пане, твоя міна п\'ять мін принесла́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 19, 'Він же сказав і тому́: „Будь і ти над п\'ятьма́ містами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 20, 'І ще інший прийшов і сказав: „Пане, ось міна твоя, що я мав її сховану в хустці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 21, 'Я бо боявся тебе, — ти ж бо люди́на жорсто́ка: береш, чого не поклав, і жнеш, чого не посіяв“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 22, 'І відказав той йому: „Уста́ми твоїми, злий рабе, суджу́ я тебе! Ти знав, що я — жорстока люди́на, беру́, чого не поклав, і жну, чого не посіяв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 23, 'Чому́ ж не віддав ти міня́льникам срі́бла мого, — і я, повернувшись, узяв би своє із прибу́тком?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 24, 'І сказав він присутнім: „Візьміть міну від нього, та дайте тому́, хто десять мін має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 25, 'І відказали йому: „Пане, — він десять мін має“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 26, 'Говорю́ бо я вам: „Кожному, хто має, то дасться йому, хто ж не має, — забереться від нього і те, що він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 27, 'А тих ворогів моїх, які не хотіли, щоб царював я над ними, приведіте сюди, — і на оча́х моїх їх повбивайте“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 28, 'А як це оповів, Він далі пішов, простуючи в Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 29, 'І ото, як набли́зився до Вітфагі́ї й Віфа́нії, на горі, що Оли́вною зветься, Він двох учнів послав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 30, 'наказуючи: „Ідіть у село, яке перед вами; увійшовши до нього, зна́йдете прив\'язане осля́, що на нього ніко́ли ніхто із людей не сідав. Відв\'яжіть його, і приведіть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 31, 'Коли ж вас хто спитає: „На́що відв\'язуєте?“, відкажіть тому так: „Госпо́дь потребу́є його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 32, 'Посланці́ ж відійшли, — і знайшли, як Він їм був сказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 33, 'А коли осля стали відв\'язувати, хазяї́ його їх запитали: „На́що осля ви відв\'язуєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 34, 'Вони ж відказали: „Господь потребу́є його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 35, 'І вони привели́ до Ісуса його, і, поклавши одежу свою на осля, посадили Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 36, 'Коли ж Він їхав, вони простила́ли одежу свою по дорозі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 37, 'А як Він наближався вже до сходу з гори Оливної, то ввесь на́товп учнів, радіючи, почав гучним голосом Бога хвалити за всі чуда, що бачили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 38, 'кажучи: „Благослове́нний Цар, що йде у Господнє Ім\'я́! Мир на небеса́х, і слава на висоті!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 39, 'А деякі фарисеї з народу сказали до Нього: „Учителю, — заборони́ Своїм учням!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 40, 'А Він їм промовив у відповідь: „Кажу вам, що коли ці замо́вкнуть, то каміння кричатиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 41, 'І коли Він набли́зився, і місто побачив, то заплакав за ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 42, 'і сказав: „О, якби й ти хоч цього дня пізнало, що потрібне для миру тобі! Та тепер від очей твоїх сховане це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 43, 'Бо при́йдуть на тебе ті дні, і твої вороги тебе ва́лом ото́чать, і обля́жуть тебе, і стиснуть тебе звідусю́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 44, 'І зрівняють з землею тебе, і поб\'ють твої діти в тобі, і не позоста́влять у тобі каменя на камені, бо не зрозуміло ти ча́су відвідин твоїх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 45, 'А коли Він у храм увійшов, то почав виганяти продавці́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 46, 'до них кажучи: „Написано: „Дім Мій — дім молитви“, а ви з нього зробили „пече́ру розбійників“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 47, 'І Він кожного дня у храмі навчав. А первосвященики й книжники й найважні́ші з наро́ду шукали, щоб Його погубити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 19, 48, 'але не знахо́дили, що вчинити Йому, бо ввесь наро́д горнувся до Нього та слухав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 1, 'І сталось одно́го з тих днів, як навчав Він у храмі людей, та Добру Нови́ну звіщав, прийшли первосвященики й книжники з старшими,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 2, 'та й до Нього промовили, кажучи: „Скажи нам, якою вла́дою Ти чиниш оце? Або хто Тобі вла́ду цю дав?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 3, 'І промовив до них Він у відповідь: „Запитаю й Я вас одну річ, — і відповідайте Мені:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 4, 'Іванове хрищення з неба було́, чи від людей?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 5, 'Вони ж міркували собі й говорили: „Коли скажемо: „З неба“, відкаже: „Чого ж ви йому не повірили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 6, 'А як скажемо: „Від людей“, то всі люди камінням поб\'ють нас, бо були переко́нані, що Іван — то пророк“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 7, 'І вони відповіли, що не знають, ізвідки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 8, 'А Ісус відказав їм: „То й Я не скажу́ вам, якою вла́дою Я це чиню́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 9, 'І Він розповідати почав людям при́тчу оцю. „Один чоловік насадив виноградника, і віддав його винаря́м, та й відбув на час довший.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 10, 'А певного ча́су послав він раба до своїх винарі́в, щоб дали йому частку з плоді́в виноградника. Та побили його винарі, і відіслали ні з чим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 11, 'І знову послав він до них раба і́ншого, а вони й того збили й знева́жили, — та й відіслали ні з чим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 12, 'І послав він ще третього, а вони й того зранили й вигнали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 13, 'Сказав тоді пан виноградника: „Що́ маю робити? Пошлю свого сина улю́бленого, — може його посоро́мляться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 14, 'Винарі́ ж, як його вгледіли, міркували собі та казали: „Це спадкоє́мець; ходім, замордуймо його, щоб спа́дщина наша була́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 15, 'І вони його вивели за виноградника, та й убили... Що́ ж зробить їм пан виноградника?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 16, 'Він при́йде та й вигубить цих винарів, виноградника ж іншим віддасть“. Слухачі ж повіли́: „Нехай цього не станеться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 17, 'А Він глянув на них та й сказав: „Що ж оце, що написане: „Камінь, що його будівничі відкинули, той нарі́жним став каменем!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 18, 'Кожен, хто впаде́ на цей камінь — розі́б\'ється, а на кого він сам упаде́, — то розчавить його́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 19, 'А книжники й первосвященики руки на Нього хотіли накласти тієї години, але побоялись наро́ду. Бо вони розуміли, що про них Він цю притчу сказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 20, 'І вони слідкували за Ним, і підіслали підгля́дачів, які праведних із себе вдавали, щоб зловити на слові Його, і Його видати урядові й вла́ді намісника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 21, 'І вони запитали Його та сказали: „Учителю, знаємо ми, що Ти добре говориш і навчаєш, і не дивишся на обли́ччя, але наставляєш на Божу дорогу правдиво.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 22, 'Чи годи́ться давати податок для ке́саря, чи ні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 23, 'Знаючи ж їхню хитрість, сказав Він до них: „Чого ви Мене випробо́вуєте?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 24, 'Покажіте дина́рія Мені. Чий образ і напис він має?“Вони відказали: „Кесарів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 25, 'А Він їм відказав: „Тож віддайте ке́сареве — ке́сареві, а Богові — Боже!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 26, 'І не могли вони перед людьми́ зловити на слові Його. І дивува́лись вони з Його відповіді, та й замовкли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 27, 'І підійшли дехто із саддукеїв, що твердять, ніби немає воскресі́ння, і запитали Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 28, 'та сказали: „Учителю, Мойсей написав нам: „Як умре кому брат, який має дружи́ну, а помре бездітний, — то нехай його брат візьме дружи́ну, і відно́вить насіння для брата свого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 29, 'Було ж сім братів. І перший, узявши дружи́ну, бездітний умер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 30, 'І другий узяв був ту дружи́ну, та й той вмер бездітний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 31, 'І третій узяв був її, так само й усі се́меро, — і вони дітей не позоставили, та й повмирали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 32, 'А по всіх умерла й жінка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 33, 'А в воскресі́нні котро́му із них вона дружи́ною буде? Бо семеро мали за дружину її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 34, 'Ісус же промовив у відповідь їм: „Женяться й заміж виходять сини цього віку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 35, 'А ті, що будуть достойні того віку й воскресі́ння з мертвих, — не будуть ні женитись, ні заміж вихо́дити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 36, 'ні вмерти вже не можуть, бо рівні вони ангола́м, і вони сини Божі, синами воскресі́ння бувши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 37, 'А що мертві встають, то й Мойсей показав — при кущі, — коли він назвав Господа „Богом Авраамовим, і Богом Ісаковим, і Богом Якововим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 38, 'Бог же не є Богом мертвих, а живих, бо всі в Нього живуть.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 39, 'Дехто ж із книжників відповіли та сказали: „Учителю, — Ти добре сказав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 40, 'І вже не насмілювалися питати Його ні про що́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 41, 'І сказав Він до них: „Як то кажуть, що Христос син Давидів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 42, 'Таж Давид сам говорить у книзі Псалмів: „Промовив Господь Господе́ві моєму: сядь право́руч Мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 43, 'поки не покладу́ Я Твоїх ворогів підніжком ногам Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 44, 'Отже, Давид Його Господом зве, — як же Він йому син?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 45, 'І, як увесь наро́д слухав, Він промовив до учнів Своїх:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 46, '„Стережіться книжників, що хочуть у довгих одежах ходити, і люблять привіти на ринках, і перші лавки́ в синагогах, і перші місця на бенке́тах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 20, 47, 'що вдови́ні хати́ поїдають, і моляться довго напо́каз, — вони тяжче осу́дження при́ймуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 1, 'І поглянув Він уго́ру, і побачив заможних, що кидали да́ри свої до скарбни́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 2, 'Побачив і вбогу вдовицю одну, що дві ле́пти туди вона вки́нула.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 3, 'І сказав Він: „Поправді кажу вам, що ця вбога вдовиця вкинула більше за всіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 4, 'Бо всі клали від лишка свого в дар Богові, а вона покла́ла з убозтва свого ввесь прожиток, що мала“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 5, 'Коли ж дехто казав про храм, що прикрашений дорогоцінним камінням та дарами, тоді Він прорік:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 6, '„Наді́йдуть ті дні, коли з того, що́ бачите, не зоста́неться й каменя на камені, який не зруйнується“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 7, 'І запитали Його та сказали: „Учителю, коли ж оце станеться? І, яка буде ознака, коли має початися це?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 8, 'Він же промовив: „Стережіться, щоб вас хто не звів. Бо багато-хто при́йдуть в Ім\'я́ Моє, кажучи: „Це Я“, і „Час набли́зився“. Та за ними не йдіть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 9, 'І, як про ві́йни та ро́зрухи почуєте ви, — не лякайтесь, бо перш „статись належить тому́“. Але це не кінець ще“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 10, 'Тоді промовляв Він до них: „Повстане наро́д на наро́д, і царство на царство“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 11, 'І будуть землетруси великі та голод, та по́мір місцями, і страшні та великі ознаки на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 12, 'Але перед усім тим накладуть на вас руки свої, і переслідувати будуть, і видаватимуть вас у синагоги й в\'язни́ці, і поведуть вас до царів та правителів — через Ім\'я́ Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 13, 'Але це стане вам на свідо́цтво.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 14, 'Отож, покладіть у серця свої — наперед не гада́ти, що́ будете відповідати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 15, 'бо дам Я вам мову та мудрість, що не зможуть противитись чи супере́чити їй всі противники ваші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 16, 'І будуть вас видавати і батьки, і брати, і рідня, і дру́зі, а декому з вас заподі́ють і смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 17, 'І за Ім\'я́ Моє будуть усі вас нена́видіти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 18, 'Але й волосина вам із голови не загине!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 19, 'Терпеливістю вашою ду́ші свої ви здобу́дете.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 20, 'А коли ви побачите Єрусалим, військом ото́чений, тоді знайте, що до нього набли́зилося спусто́шення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 21, 'Тоді ті, хто в Юдеї, нехай у го́ри втікають; хто ж у сере́дині міста, нехай вийдуть; хто ж в околицях, — хай не вертаються в нього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 22, 'Бо то будуть дні помсти, щоб ви́коналося все написане.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 23, 'Горе ж вагітним та тим, хто годує грудьми́, у ті дні, бо буде велика нужда́ на землі та гнів над цим лю́дом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 24, 'І поляжуть під гострим мечем, і заберуть до неволі поміж усі наро́ди, і погани топтатимуть Єрусалим, аж поки не скі́нчиться час тих поган.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 25, 'І будуть ознаки на сонці, і місяці, і зорях, і тривога людей на землі, і збенте́ження від шуму моря та хвиль,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 26, 'коли люди будуть мертвіти від стра́ху й чека́ння того, що йде на ввесь світ, бо сили небесні пору́шаться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 27, 'І побачать тоді „Сина Лю́дського, що йтиме на хмарах “із си́лою й великою славою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 28, 'Коли ж стане збуватися це, то ви́простуйтесь, і підійміть свої голови, — бо зближається ваше визво́лення!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 29, 'І розповів Він їм притчу: „Погляньте на фі́ґове дерево, і на всілякі дере́ва:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 30, 'як вони вже розпу́куються, то, бачивши це, самі знаєте, що близько вже літо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 31, 'Так і ви, як побачите, що діється це, то знайте, що Боже Царство вже близько!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 32, 'Поправді кажу вам: Не пере́йде цей рід, аж усе оце станеться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 33, 'Небо й земля промину́ться, але не минуться слова́ Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 34, 'Уважайте ж на себе, щоб ваші серця не обтя́жувалися ненаже́рством та п\'янством, і життє́вими кло́потами, і щоб день той на вас не прийшов несподівано,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 35, 'немов сітка; бо він при́йде на всіх, що живуть на пове́рхні всієї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 36, 'Тож пильнуйте, і кожного ча́су моліться, щоб змогли ви уни́кнути всього того, що має відбутись, та стати перед Сином Лю́дським!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 37, 'За дня ж Він у храмі навчав, а на́ ніч виходив та перебува́в на горі, що зветься Оли́вна.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 21, 38, 'А зра́нку всі люди до Нього прихо́дили в храм, щоб послухати Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 1, 'Наближа́лося ж свято Опрі́сноків, що Па́схою зветься.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 2, 'А первосвященики й книжники стали шукати, я́к би вбити Його, та боялись наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 3, 'Сатана ж увійшов у Юду, зва́ного Іскаріо́т, одно́го з Дванадцятьо́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 4, 'І він пішов, і почав умовлятися з первосвящениками та начальниками, я́к він видасть Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 5, 'Ті ж зраділи, і погодилися дати йому срібнякі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 6, 'І він обіцяв, і шукав відповідного ча́су, щоб їм видати Його без наро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 7, 'І настав день Опрі́сноків, коли пасху прино́сити в жертву нале́жало.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 8, 'І послав Він Петра та Івана, говорячи: „Підіть, і приготуйте нам пасху, щоб її спожили́ ми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 9, 'А вони запитали Його: „Де́ Ти хочеш, щоб ми приготува́ли?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 10, 'А Він їм відказав: „Ось, як бу́дете вхо́дити в місто, стріне вас чоловік, воду несучи у глекові, — ідіть за ним аж до дому, куди він уві́йде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 11, 'І скажіть до госпо́даря дому: Учитель питає тебе: „Де кімна́та, в якій споживу́ зо Своїми учнями пасху?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 12, 'I він вам покаже велику го́рницю вистелену: там приготуйте“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 13, 'І вони відійшли, і знайшли, як Він їм говорив, — і зачали́ там готува́ти пасху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 14, 'А коли настав час, сів до сто́лу, і апо́столи з Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 15, 'І промовив до них: „Я ду́же бажав спожи́ти цю пасху із вами, перш ніж муки прийму́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 16, 'Бо кажу́ вам, що вже споживати не буду її, поки спо́вниться в Божому Царстві вона“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 17, 'Узявши ж чашу, і вчинивши подяку, Він промовив: „Візьміть її, і поділіть між собою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 18, 'Кажу́ ж вам, що віднині не питиму Я від оцього пло́ду виноградного, доки Боже Царство не при́йде“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 19, 'Узявши ж хліб і вчинивши подяку, поламав і дав їм, проказуючи: „Це тіло Моє, що за вас віддається. Це чиніть на спо́мин про Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 20, 'По вече́рі так само ж і чашу, говорячи: „Оця чаша — Нови́й Заповіт у Моїй крові, що за вас проливається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 21, 'Та однак, — за столом ось зо Мною рука Мого зра́дника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 22, 'Бо Син Лю́дський іде, як призна́чено; але горе тому чоловікові, хто Його видає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 23, 'А вони почали́ між собою питати, котри́й з них мав би це вчинити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 24, 'І сталось між ними й змагання, котрий з них уважатися має за більшого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 25, 'Він же промовив до них: „Царі народів панують над ними, а ті, що ними володіють, доброчи́нцями звуться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 26, 'Але не так ви: хто найбільший між вами, нехай буде, як менший, а начальник — як слуга,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 27, 'Бо хто більший: чи той, хто сидить при столі, чи хто прислуго́вує? Чи не той, хто сидить при столі? А Я серед вас, як слуга.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 28, 'Ви ж оті, що перетривали зо Мною в споку́сах Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 29, 'і Я вам запові́тую Царство, як Отець Мій Мені заповів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 30, 'щоб ви в Царстві Моїм споживали й пили за столом Моїм, і щоб ви на престолах засіли судити дванадцять племе́н Ізраїлевих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 31, 'І промовив Господь: „Си́моне, Си́моне, — ось сатана жадав вас, щоб вас пересі́яти, мов ту пшеницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 32, 'Я ж молився за тебе, щоб не зме́ншилась віра твоя; ти ж колись, як наве́рнешся, зміцни браттю свою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 33, 'А той відказав Йому: „Господи, я з Тобою готовий іти до в\'язниці й на смерть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 34, 'Він же прорік: „Говорю́ тобі, Петре, — півень не заспіває сьогодні, як ти тричі зречешся, що не знаєш Мене“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 35, 'І Він їм сказав: „Як Я вас посилав без кали́тки, і без торби, і без санда́ль, — чи вам бракувало чого?“Вони ж відказали: „Нічо́го“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 36, '„А тепер — каже їм — хто має калитку, нехай ві́зьме, теж і торбу; хто ж не має, нехай продасть одіж свою та й купить меча.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 37, 'Говорю бо Я вам, що ви́конатися на Мені має й це ось написане: „До злочинців Його зарахо́вано“. Бо те, що про Мене, вико́нується“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 38, 'І сказали вони: „Господи, ось тут два мечі“. А Він їм відказав: „До́сить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 39, 'І Він вийшов, і пішов за звича́єм на го́ру Оливну. А за Ним пішли учні Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 40, 'А прийшовши на місце, сказав їм: „Моліться, щоб не впасти в спокусу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 41, 'А Він Сам, відійшовши від них, як докинути ка́менем, на коліна припав та й молився,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 42, 'благаючи: „Отче, як волієш, — пронеси́ мимо Мене цю чашу! Та проте — не Моя, а Твоя нехай станеться воля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 43, 'І Ангол із неба з\'явився до Нього, — і додавав Йому сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 44, 'А як був у смерте́льній тривозі, ще пильніш Він молився. І піт Його став, немов каплі крови, що спливали на землю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 45, 'І, підвівшись з молитви, Він до учнів прийшов, і знайшов їх, що спали з журби́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 46, 'І промовив до них: „Чого́ ви спите? Уставайте й моліться, щоб не впасти в спокусу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 47, 'І, коли Він іще говорив, ось наро́д з\'явився, і один із Дванадцятьо́х, що Юдою зветься, ішов перед ними. І він підійшов до Ісуса, щоб поцілувати Його. [Бо він знака їм дав був: кого я поцілую, то Він!“].');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 48, 'Ісус же промовив до нього: „Чи оце поцілу́нком ти, Юдо, видаєш Сина Лю́дського?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 49, 'А ті, що були́ з Ним, як побачили, що́ має статись, сказали Йому: „Господи, — чи мече́м нам не вдарити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 50, 'І, один із них рубону́в раба первосвященикового, — та й відтяв праве вухо йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 51, 'Та Ісус відізвався й сказав: „Лишіть, — уже до́сить!“І, доторкнувшись до вуха його, у здоро́вив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 52, 'А до первосвящеників і вла́ди сторожі храму та старших, що прийшли проти Нього, промовив Ісус: „Немов на розбійника вийшли з меча́ми та ки́ями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 53, 'Як щоденно Я з вами у храмі бував, не підне́сли на Мене ви рук. Та це ваша година тепер, і влада те́мряви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 54, 'А схопи́вши Його, повели́ й привели́ у дім первосвященика. Петро ж зда́лека йшов слідкома́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 55, 'Як розклали ж огонь серед дво́ру, і вкупі сиділи, сидів і Петро поміж ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 56, 'А служни́ця одна його вгледіла, як сидів коло світла, і, придивившись до нього, сказала: „І цей був із Ним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 57, 'І відрікся від Нього він, тве́рдячи: „Не знаю я, жінко, Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 58, 'Незаба́ром же другий побачив його та й сказав: „І ти від отих“. А Петро відказав: „Ні, чоловіче!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 59, 'І як ча́су минуло з годину, хтось інший твердив і казав: „Поправді, — і цей був із Ним, бо він галіле́янин“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 60, 'А Петро відказав: „Чоловіче, — не відаю, про що́ ти говориш“... І зараз, як іще говорив він, півень заспівав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 61, 'І Господь обернувся й подививсь на Петра. А Петро згадав слово Господнє, як сказав Він йому: „Перше, ніж заспіває півень, — відречешся ти тричі від Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 62, 'І, вийшовши звідти, він гірко заплакав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 63, 'А люди, які ув\'язни́ли Ісуса, знуща́лися з Нього та били.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 64, 'І, закривши Його, вони били Його по обличчі, і питали Його, приговорюючи: „Пророкуй, хто́ то вдарив Тебе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 65, 'І багато інших богознева́г говорили на Нього вони...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 66, 'А коли настав день, то зібралися старші наро́ду, первосвященики й книжники, і повели́ Його в синедріо́н свій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 67, 'і казали: „Коли Ти Христос, скажи нам“. А Він їм відповів: „Коли Я вам скажу́, — не повірите ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 68, 'А коли й поспитаю вас Я, — не дасте Мені відповіді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 69, 'Незаба́ром Син Лю́дський сидітиме по прави́ці сили Божої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 70, 'Тоді всі запитали: „То Ти Божий Син?“А Він їм відповів: „Самі кажете ви, що то Я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 22, 71, 'А вони відказали: „На́що потрібні ще свідки для нас? Бо ми чули самі з Його уст!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 1, 'І зняли́ся всі їхні збори, і повели до Пилата Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 2, 'І зачали оскаржа́ти Його й говорити: „Ми стверди́ли, що Цей ворохо́бить народ наш, і забороняє податок давати кесареві, та й говорить, що Він, — Христос Цар“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 3, 'І Пила́т запитав Його, кажучи: „Чи Ти Цар Юдейський?“А Він відказав йому в відповідь: „Сам ти кажеш“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 4, 'І Пилат сказав первосвященикам та до народу: „Я не знахо́джу жо́дної провини в Цій Люди́ні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 5, 'А вони намагались, говорячи: „Він бунтує наро́д, навчаючи в усій Юдеї, від Галілеї почавши аж посі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 6, 'А Пилат, вчувши про Галілею, спитав: „Хіба Він галіле́янин?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 7, 'І, дізнавшись, що Він із влади Ірода, відіслав Його Іродові, бо той в Єрусалимі також перебува́в тими днями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 8, 'Коли ж Ірод побачив Ісуса, то дуже зрадів, бо він від давнього ча́су бажав Його бачити, — багато за Нього чував, і сподівався побачити чудо яке, що буває від Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 9, 'І багато питався Його, та нічого не відповідав Він йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 10, 'І стояли тут первосвященики й книжники, та завзя́то Його оскаржували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 11, 'Тоді Ірод із ві́йськом своїм ізневажив Його й насміявся, зодягнувши Його в яснобі́лу одіж, і відіслав до Пилата Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 12, 'І того дня стали Ірод із Пилатом за при́ятелів між собою, бо давніш ворожне́ча між ними була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 13, 'А Пилат скликав первосвящеників, і старшин, і наро́д,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 14, 'і промовив до них: „Привели́ ви мені Чоловіка Цього́, як того́, що бунтує наро́д. А ось я перед вами розвідав, — і не знахо́джу в Люди́ні Оцій ані однієї провини такої, про що ви оскаржуєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 15, 'Також Ірод, бо він відіслав Його нам. І ось нічого, що на смерть заслуго́вувало б, Він не вчинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 16, 'Отже я покараю Його й відпущу́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 17, 'Бо пови́нен був їм відпустити одно́го на свято.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 18, 'А наро́д став кричати й казати: Візьми Цього́, — відпусти ж нам Вара́вву!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 19, 'А той за повста́ння одне, яке сталося в місті, і за вбивство посаджений був до в\'язни́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 20, 'І зно́ву сказав їм Пилат, хотячи́ відпустити Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 21, 'Та кричали вони й говорили: „Розіпни, розіпни Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 22, 'Він же втретє промовив до них: „Яке ж зло вчинив Він? Я нічого, що на смерть заслуго́вувало б, на Нім не знайшов. Отже я покараю Його й відпущу́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 23, 'А вони сильним криком свого домага́лися, та вимагали розп\'я́сти Його. І взяв го́ру крик їхній та первосвящеників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 24, 'І Пилат присудив, щоб було́, як просили вони:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 25, 'відпустив їм Вара́вву, поса́дженого за повста́ння та вбивство в в\'язницю, за якого просили вони, а Ісуса віддав їхній волі...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 26, 'І як Його повели́, то схопи́ли якогось Си́мона із Кіріне́ї, що з поля вертався, і поклали на нього хреста, щоб він ніс за Ісусом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 27, 'А за Ним ішов на́товп великий людей і жінок, які плакали та голосили за Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 28, 'А Ісус обернувся до них та й промовив: „Дочки єрусалимські, не ридайте за Мною, — за собою ридайте й за ді́тьми своїми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 29, 'Бо ось дні настають, коли скажуть: „Блаженні неплідні, та утро́би, які не родили, і груди, що не годували“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 30, 'Тоді стануть казати гора́м: „Поспадайте на нас“, а узгі́р\'ям: „Покрийте нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 31, 'Бо коли таке роблять зеленому дереву, то що́ буде сухому?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 32, 'І вели́ з Ним також двох злочинників інших, щоб убити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 33, 'А коли прибули́ на те місце, що звуть „Черепо́вище“, розп\'яли́ тут Його та злочинників, — одно́го право́руч, а одного ліво́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 34, 'Ісус же промовив: „Отче, відпусти їм, — бо не знають, що чинять вони!“А як Його одіж ділили, то кидали же́реба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 35, 'А люди стояли й дивились... Насміхалися з ними й старши́ни, говорячи: „Він інших спасав, — нехай Сам Себе ви́зволить, коли Він Христос, Божий Обра́нець!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 36, 'І вояки́ глузували з Нього: приступаючи, о́цет Йому подавали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 37, 'і казали: „Коли Цар Ти Юдейський, — спаси Себе Сам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 38, 'Був же й напис над Ним письмом грецьким, латинським і гебрейським написаний: „Це — Цар Юдейський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 39, 'А один із розп\'я́тих злочинників став зневажати Його й говорити: „Чи Ти не Христос? То спаси Себе й нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 40, 'Обізвався ж той другий, і докоряв йому, кажучи: „Чи не боїшся ти Бога, коли й сам на те саме засуджений?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 41, 'Але ми справедливо засу́джені, і належну заплату за вчинки свої беремо́, — Цей же жодного зла не вчинив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 42, 'І сказав до Ісуса: „Спогада́й мене, Господи, коли при́йдеш у Царство Своє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 43, 'І промовив до нього Ісус: „Попра́вді кажу́ тобі: ти бу́деш зо Мною сьогодні в раю́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 44, 'Наближалася шоста година, — і те́мрява стала по ці́лій землі аж до години дев\'ятої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 45, 'І сонце затьми́лось, і в храмі завіса роздерлась надво́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 46, 'І, скрикнувши голосом гучним, промовив Ісус: „Отче, у руки Твої віддаю Свого духа!“І це прорікши, Він духа віддав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 47, 'Коли ж сотник побачив, що́ сталось, він Бога просла́вив, говорячи: „Дійсно праведний був Чоловік Цей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 48, 'І ввесь на́товп, який зійшовсь на видо́вище це, як побачив, що́ сталось, — бив у гру́ди себе та вертався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 49, 'Усі ж знайо́мі Його й ті жінки́, що прийшли були з Ним із Галілеї, здалека стояли й дивились на це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 50, 'І ось муж, на ім\'я́ йому Йо́сип, що був радником синедріону, люди́на шановна і праведна, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 51, 'не пристав він до ради та чину їх, — із Аримате́ї, юдейського міста, що й сам сподівався Божого Царства, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 52, 'цей прийшов до Пилата, і тіла Ісусового став просити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 53, 'І Йо́сип, знявши Його, обгорнув у полотно, і покла́в Його в гро́бі, що в скелі був ви́січений, і що в ньому ніко́ли ніхто не лежав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 54, 'День той був Приготува́ння, і наставала субота.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 55, 'А жінки́, що прийшли були з Ним із Галілеї, ішли слідо́м, і вони бачили гро́ба, і як покладене тіло Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 23, 56, 'Повернувшись, вони наготува́ли па́хощів і мира, а в суботу, за заповіддю, спочивали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 1, 'А дня першого в тижні прийшли вони рано вранці до гро́бу, несучи́ нагото́вані па́хощі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 2, 'та й застали, що камінь від гро́бу відва́лений був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 3, 'А ввійшовши, вони не знайшли тіла Господа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 4, 'І сталось, як безрадні були вони в цім, ось два мужі́ в одежах блискучих з\'явились при них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 5, 'А коли налякались вони й посхиляли обличчя додолу, ті сказали до них: „Чого ви шукаєте Живого між мертвими?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 6, 'Нема Його тут, бо воскрес! Пригадайте собі, як Він вам говорив, коли ще перебува́в в Галілеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 7, 'Він казав: „Сину Лю́дському треба бути ви́даному до рук грішних людей, і розп\'я́тому бути, і воскре́снути третього дня“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 8, 'І згадали вони ті слова́ Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 9, 'А вернувшись від гро́бу, про все те сповістили Одинадцятьох та всіх інших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 10, 'То були́: Марія Магдали́на, і Іванна, і Марія, мати Яковова, і інші з ними, — і вони розповіли апо́столам це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 11, 'Та слова́ їхні здалися їм вигадкою, — і не повірено їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 12, 'Петро ж устав та до гро́бу побіг, і, нахилившися, бачить — лежать самі тільки покривала. І вернувсь він до себе, і дивувався, що́ сталось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 13, 'І ото, двоє з них того ж дня йшли в село, на ім\'я́ Еммау́с, що від Єрусалиму лежало на стадій із шістдеся́т.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 14, 'І розмовляли вони між собою про все те, що́ сталося.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 15, 'І ото, як вони розмовляли, і розпитували один о́дного, підійшов Сам Ісус, — і пішов разом із ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 16, 'Очі ж їхні були стри́мані, щоб Його не пізнали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 17, 'І спитався Він їх: „Що́ за речі такі, що про них між собою в дорозі міркуєте, і чого ви сумні́?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 18, 'І озвався один, йому йме́ння Клео́па, та й промовив до Нього: „Ти хіба тут у Єрусалимі єдиний захожий, що не знає, що́ сталося в нім цими днями?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 19, 'І спитався Він їх: „Що таке?“А вони розпові́ли Йому: „Про Ісуса Назаряни́на, що Пророк був, могутній у ділі й у слові перед Богом і всім наро́дом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 20, 'Як первосвященики й наша старши́на Його віддали́ на суд смертний, — і Його розп\'яли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 21, 'А ми сподівались були́, що Це Той, що має Ізраїля ви́зволити. І до того, оце третій день вже сьогодні, як усе оте сталося.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 22, 'А дехто з наших жінок, що рано були́ коло гро́бу, нас здивували:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 23, 'вони тіла Його не знайшли, та й вернулися й оповідали, що бачили й з\'я́влення анголі́в, які кажуть, що живий Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 24, 'І пішли дехто з наших до гро́бу, і знайшли так, як казали й жінки́; та Його не побачили“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 25, 'Тоді Він сказав їм: „О, безумні й запеклого серця, щоб повірити всьому, про що́ сповіщали Пророки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 26, 'Чи ж Христові не це перете́рпіти треба було, і ввійти в Свою славу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 27, 'І Він почав від Мойсея, і від Пророків усіх, і виясня́в їм зо всього Писа́ння, що́ про Нього було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 28, 'І набли́зились вони до села, куди йшли. А Він удавав, ніби хоче йти далі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 29, 'А вони не пускали Його й намовляли: „Зостанься з нами, бо вже вечорі́є, і кінча́ється день“. І Він увійшов, щоб із ними побути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 30, 'І ото, коли сів Він із ними до столу, то взяв хліб, поблагословив, і, ламаючи, їм подавав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 31, 'Тоді очі відкрилися їм, — і пізнали Його́. Але Він став для них невиди́мий...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 32, 'І говорили вони один о́дному: „Чи не пала́ло нам серце обом, коли промовляв Він до нас по дорозі, і коли виясняв нам Писа́ння?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 33, 'І зараз устали вони, і повернулись до Єрусалиму, і знайшли там у зборі Одинадцятьо́х, і і тих, що з ними були́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 34, 'які розповідали, що Госпо́дь дійсно воскрес, і з\'явився був Си́монові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 35, 'А вони розпо́віли, що́ сталось було на дорозі, і як пізнали Його в лама́нні хліба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 36, 'І, як вони говорили оце, Сам Ісус став між ними, і промовив до них: „Мир вам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 37, 'А вони налякалися та перестра́шились, і ду́мали, що бачать духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 38, 'Він же промовив до них: „Чого́ ви стриво́жились? І пощо́ ті думки до серде́ць ваших входять?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 39, 'Погляньте на руки Мої та на ноги Мої, — це ж Я Сам! Доторкніться до Мене й дізнайтесь, — бо не має дух тіла й косте́й, а Я, бачите, маю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 40, 'І, промовивши це, показав Він їм руки та но́ги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 41, 'І, як ще не йняли вони віри з радощів та дивувались, Він сказав їм: „Чи не маєте тут чогось їсти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 42, 'Вони ж подали́ Йому ку́сника риби печеної та стільника́ медово́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 43, 'І, взявши, Він їв перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 44, 'І промовив до них: „Це слова́, що казав Я до вас, коли був іще з вами: Потрібно, щоб ви́коналось усе, що про Мене в Зако́ні Мойсеєвім, та в Пророків, і в Пса́лмах написане“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 45, 'Тоді розум розкрив їм, щоб вони розуміли Писа́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 46, 'І сказав Він до них: „Так написано є, і так потрібно було́ постраждати Христові, і воскре́снути з мертвих дня третього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 47, 'і щоб у Йме́ння Його проповідувалось покая́ння, і про́щення гріхів між наро́дів усіх, від Єрусалиму почавши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 48, 'А ви свідки того́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 49, 'І ось Я посилаю на вас обі́тницю Мого Отця; а ви позоста́ньтеся в місті, аж поки зодя́гнетесь силою з висоти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 50, 'І Він вивів за місто їх аж до Віфа́нії; і, знявши руки Свої, поблагословив їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 51, 'І сталось, як Він благословляв їх, то зачав відступа́ти від них, і на небо возно́ситись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 52, 'А вони поклонились Йому, і повернулись до Єрусалиму з великою радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 24, 53, 'І постійно вони перебува́ли в храмі, переславля́ючи й хва́лячи Бога. Амінь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'На початку було Слово, а Слово в Бога було́, і Бог було Слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Воно в Бога було на поча́тку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Усе через Нього повста́ло, і ніщо, що повста́ло, не повстало без Ньо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'І життя було в Нім, а життя було Світлом людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'А Світло у те́мряві світить, і те́мрява не обгорну́ла його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Був один чоловік, що від Бога був по́сланий, — йому йме́ння Іван.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Він прийшов на свідо́цтво, щоб засві́дчити про Світло, щоб повірили всі через нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Він тим Світлом не був, але сві́дчити мав він про Світло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Світлом правдивим був Той, Хто просвічує кожну люди́ну, що прихо́дить на світ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Воно в світі було, і світ через Нього повстав, але світ не пізнав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'До свого Воно прибуло́, — та свої відцура́лись Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'А всім, що Його прийняли́, їм вла́ду дало́ дітьми́ Божими стати, тим, що вірять у Йме́ння Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'що не з крови, ані з пожадли́вости тіла, ані з пожадливости мужа, але народились від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'І Слово сталося тілом, і перебува́ло між нами, повне благодаті та правди, і ми бачили славу Його, славу як Одноро́дженого від Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Іван сві́дчить про Нього, і кликав, говорячи: „Це був Той, що про Нього казав я: Той, Хто прийде за мною, існував передо мною, бо був перше, ніж я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'А з Його повноти́ ми оде́ржали всі, — а то благода́ть на благода́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Зако́н бо через Мойсея був да́ний, а благода́ть та правда з\'явилися через Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Ніхто Бога ніко́ли не бачив, — Одноро́джений Син, що в лоні Отця, Той Сам виявив був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'А це ось свідо́цтво Іванове, як юдеї послали були з Єрусалиму священиків та Левитів, щоб спитали його: „Хто́ ти такий?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'І він визнав, і не зрікся, а визнав: „Я — не Христос“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'І запитали його: „А хто ж? Чи Ілля́?“І відказує: „Ні!“„Чи пророк?“І дав відповідь: „Ні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Сказали ж йому: „Хто́ ж ти такий, щоб дати відповідь тим, хто послав нас? Що́ ти кажеш про себе самого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Відказав: „Я голос того, хто кличе: В пустині рівняйте дорогу Господню“, як Іса́я пророк заповів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Посланці ж із фарисеїв були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'І вони запитали його та сказали йому́: „Для чого ж ти христиш, коли ти не Христос, ні Ілля, ні пророк?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 26, 'Відповів їм Іван, промовляючи: „Я водою хрищу́, а між вами стоїть, що Його ви не знаєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 27, 'Він Той, Хто за мною йде, Хто до мене був, Кому розв\'яза́ти ремінця́ від узуття́ Його я негідний“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 28, 'Це в Віфа́нії ді́ялося, на тім боці Йорда́ну, де христив був Іван.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 29, 'Наступного дня Іван бачить Ісуса, що до нього йде, та й каже: „Оце А́гнець Божий, що на Се́бе гріх світу бере!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 30, 'Це Той, що про Нього казав я: За мною йде Муж, що передо мною Він був, бо був перше, ніж я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 31, 'І не знав я Його́; та для того прийшов я, христивши водою, щоб Ізраїлеві Він з\'явився“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 32, 'І сві́дчив Іван, промовляючи: „Бачив я Духа, що сходив, як голуб, із неба, та зоставався на Ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 33, 'І не знав я Його, але Той, Хто христити водою послав мене, мені оповів: „Над Ким Духа побачиш, що сходить і зостається на Ньому, — це Той, Хто христитиме Духом Святим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 34, 'І я бачив, і засві́дчив, що Він — Божий Син!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 35, 'Наступного дня стояв зно́ву Іван та двоє з учнів його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 36, 'І, поглянувши на Ісуса, що проходив, він сказав: „Ото А́гнець Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 37, 'І почули два у́чні, як він говорив, та й пішли за Ісусом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 38, 'А Ісус обернувся й побачив, що вони йшли за Ним, та й каже до них: „Чого́ ви шукаєте?“А вони відказали Йому: „Равві́ — перекладене це визначає: „Учителю“, — де Ти живеш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 39, 'Він говорить до них: „Ходіть і побачте!“Ті пішли та й побачили, де́ Він жив, і в Нього той день перебули́. Було ж коло години десятої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 40, 'А один із тих двох, що чули від Івана та йшли вслід за Ним, був Андрій, брат Си́мона Петра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 41, 'Він знайшов перше Си́мона, брата свого, та й говорить до нього: „Знайшли ми Месі́ю, що визначає: Христос“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 42, 'І привів він його до Ісуса. На нього ж спогля́нувши, промовив Ісус: „Ти — Си́мон, син Йо́нин; будеш званий ти Ки́фа, що визначає: камінь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 43, 'Наступного дня захотів Він піти в Галілею. І знайшов Він Пилипа та й каже йому: „Іди за Мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 44, 'А Пилип із Віфсаїди похо́див, із міста Андрія й Петра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 45, 'Пилип Натанаї́ла знахо́дить та й каже йому: „Ми знайшли Того, що про Нього писав був Мойсей у Зако́ні й Пророки, — Ісуса, сина Йо́сипового, із Назаре́ту“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 46, 'І сказав йому Натанаї́л: „Та хіба ж може бути з Назаре́ту що добре?“Пилип йому каже: „Прийди та побач“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 47, 'Ісус, угледівши Натанаїла, що до Нього Йде, говорить про нього: „Ото справді ізра́їльтянин, що немає в нім пі́дступу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 48, 'Говорить Йому Натанаїл: „Звідки знаєш мене?“Ісус відповів і до нього сказав: „Я бачив тебе ще давніш, ніж Пилип тебе кликав, як під фіґовим деревом був ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 49, 'Відповів Йому Натанаїл: „Учителю, Ти — Син Божий, Ти — Цар Ізраїлі́в!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 50, 'Ісус відповів і до нього сказав: „Через те віриш ти, що сказав Я тобі, що під фіґовим деревом бачив тебе? Більш від цього побачиш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 51, 'І Він каже йому: „Поправді, поправді кажу́ вам: Відтепе́р ви побачите небо відкрите та анголів Божих, що на Лю́дського Сина підіймаються та спускаються“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 52, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'А третього дня весі́лля справляли в Кані́ Галілейській, і була там Ісусова мати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'На весілля запрошений був теж Ісус та учні Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'Як забракло ж вина, то мати Ісусова каже до Нього: „Не мають вина!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'Ісус же відказує їй: „Що тобі, жо́но, до Мене? Не прийшла ще година Моя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'А мати Його до слуг каже: „Зробіть усе те, що́ Він вам скаже!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, 'Було тут шість камінних посу́дин на воду, що стояли для очи́щення юдейського, що відер по дві чи по три вміщали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'Ісус каже до слуг: „Напо́вніть водою посу́дини“. І їх поналива́ли вще́рть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'І Він каже до них: „Тепер зачерпні́ть, і занесіть до весільного ста́рости“. І занесли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Як весільний же ста́роста скуштува́в воду, що сталась вином, а він не знав, звідки воно, — знали ж слу́ги, що води наливали, — то староста кличе тоді молодо́го');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'та й каже йому: „Кожна люди́на подає перше добре вино, а як понапива́ються, тоді гірше; а ти добре вино аж на досі зберіг“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'Такий поча́ток чудам зробив Ісус у Кані́ Галілейській, — і виявив славу Свою. І ввірували в Нього учні Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Після цього відправивсь Він Сам, і мати Його, і брати Його, і Його учні до Капернау́му, і там перебули небагато днів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'А зближалася Пасха юдейська, і до Єрусалиму подався Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'І знайшов Він, що продавали у храмі волів, і овець, і голубів, та сиділи міня́льники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'І, зробивши бича́ з мотузкі́в, Він вигнав із храму всіх, — вівці й воли, а міня́льникам гроші розси́пав, і попереверта́в їм столи́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'І сказав продавця́м голубів: „Заберіть оце звідси, і не робіть із дому Отця Мого дому торго́вого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Тоді учні Його згадали, що написано: „Ревність до дому Твого з\'їдає Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, 'І обізва́лись юдеї й сказали Йому: „Яке нам знаме́но покажеш, що Ти можеш робити таке?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Ісус відповів і промовив до них: „Зруйнуйте цей храм, — і за три дні Я поставлю його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'Відказали ж юдеї: „Сорок шість літ будувався цей храм, а Ти за три́ дні поставиш його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'А Він говорив про храм тіла Свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'Коли ж Він із мертвих воскрес, то учні Його згадали, що Він говорив це, і ввірували в Писа́ння та в слово, що сказав був Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'А як в Єрусалимі Він був у свято Пасхи, то багато-хто ввірували в Його Йме́ння, побачивши чуда Його, що чинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 24, 'Але Сам Ісус їм не звіря́вся, бо Сам знав усіх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 25, 'і потреби не мав, щоб хто сві́дчив Йому про люди́ну, — бо знав Сам, що в люди́ні було.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Був один чоловік із фарисеїв Никоди́м на ім\'я́, начальник юдейський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'Він до Нього прийшов уночі, та й промовив Йому: „Учителю, знаємо ми, що прийшов Ти від Бога, як Учитель, — бо не може ніхто таких чуд учинити, які чиниш Ти, коли Бог із ним не буде“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Ісус відповів і до нього сказав: „Поправді, поправді кажу́ Я тобі: Коли хто не наро́диться згори́, то не може побачити Божого Царства“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'Никоди́м Йому каже: „Як може люди́на родитися, бувши старою? Хіба може вона ввійти до утро́би своїй матері зно́ву й родитись?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'Ісус відповів: „Поправді, поправді кажу́ Я тобі: Коли хто не ро́диться з води й Духа, той не може ввійти в Царство Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'Що вродилося з тіла — є тіло, що ж уродилося з Духа — є Дух.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Не дивуйся тому́, що сказав Я тобі: Вам необхі́дно родитись згори́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Вітер віє, де хоче, і його голос ти чуєш, та не відаєш, звідкіля́ він приходить, і куди він іде. Так буває і з кожним, хто від Духа наро́джений“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'Відповів Никоди́м і до Нього сказав: „Як це статися може?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'Ісус відповів і до нього сказав: „Ти — учитель ізра́їльський, — то чи ж цього не знаєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'Поправді, поправді кажу́ Я тобі: Ми говоримо те, що ми знаємо, а сві́дчимо про те, що́ ми бачили, але сві́дчення нашого ви не приймаєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Коли Я говорив вам про зе́мне, та не вірите ви, то я́к же повірите ви, коли Я говоритиму вам про небесне?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'І не схо́див на небо ніхто, тільки Той, Хто з неба зійшов, — Людський Син, що на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'І, як Мойсей підні́с змі́я в пустині, так мусить піднесений бути й Син Лю́дський,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'щоб кожен, хто вірує в Нього, мав вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Так бо Бог полюбив світ, що дав Сина Свого Одноро́дженого, щоб кожен, хто вірує в Нього, не згинув, але мав життя вічне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Бо Бог не послав Свого Сина на світ, щоб Він світ засуди́в, але щоб через Нього світ спасся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 18, 'Хто вірує в Нього, не буде засу́джений; хто ж не вірує, — той вже засуджений, що не повірив в Ім\'я́ Одноро́дженого Сина Божого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 19, 'Суд же такий, що світло на світ прибуло́, люди ж те́мряву більш полюбили, як світло, — лихі бо були́ їхні вчинки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 20, 'Бо кожен, хто робить лихе, нена́видить світло, і не приходить до світла, щоб не зганено вчинків його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 21, 'А хто робить за правдою, той до світла йде, щоб діла його виявились, бо зроблені в Бозі вони“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 22, 'По цьому прийшов Ісус та учні Його до країни Юдейської, і з ними Він там проживав та христив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 23, 'А Іван теж христив в Ено́ні побли́зу Сали́му, бо було там багато води; і прихо́дили люди й христились,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 24, 'бо Іван до в\'язниці не був ще поса́джений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 25, 'І зчинилось змага́ння Іванових учнів з юдеями — про очи́щення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 26, 'І прийшли до Івана вони та й сказали йому: „Учителю, Той, Хто був із тобою по то́й бік Йорда́ну, про Якого ти свідчив, — ото христить і Він, і до Нього всі йдуть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 27, 'Іван відповів і сказав: „Люди́на нічого приймати не може, як їй з неба не дасться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 28, 'Ви самі мені свідчите, що я говорив: я — не Христос, але по́сланий я перед Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 29, 'Хто має заручену, той молодий. А дружко́ молодого, що стоїть і його слухає, дуже тішиться з голосу молодого. Така радість моя оце здійснилась!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 30, 'Він має рости, я ж — малі́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 31, 'Хто зве́рху приходить, — Той над усіма́. Хто походить із землі, то той зе́мний, і говорить по-зе́мному. Хто приходить із неба, Той над усіма́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 32, 'і що бачив і чув, те Він свідчить, — та свідо́цтва Його не приймає ніхто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 33, 'Хто ж прийняв свідо́цтво Його, той стверди́в тим, що Бог правдивий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 34, 'Бо Кого Бог послав, Той Божі слова́ промовляє, — бо Духа дає Бог без міри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 35, 'Отець любить Сина, і дав усе в Його руку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 36, 'Хто вірує в Сина, той має вічне життя; а хто в Сина не вірує, той життя не побачить — а гнів Божий на нім перебува́є“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Як Господь же довідався, що почули фарисеї, що Ісус учнів більше збирає та христить, як Іван,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'хоч Ісус не христив Сам, а учні Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Він покинув Юде́ю та зно́ву пішов у Галіле́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'І потрібно було́ Самарі́ю Йому перехо́дити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Отож, прибуває Він до самарі́йського міста, що зветься Сіха́р, недалеко від поля, яке Яків був дав своєму синові Йо́сипові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'Там же була Яковова криниця. І Ісус, дорогою змо́рений, сів отак край криниці. Було коло години десь шостої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Надхо́дить ось жінка одна з Самарії набрати води. Ісус каже до неї: „Дай напитись Мені!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Бо учні Його відійшли були в місто, щоб купити пожи́ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'Тоді каже Йому самаря́нка: „Як же Ти, юде́янин бувши, та просиш напитись від мене, самаря́нки?“Бо юдеї не сходяться із самарянами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Ісус відповів і промовив до неї: „Коли б знала ти Божий дар, і Хто Той, Хто говорить тобі: „Дай напитись Мені“, — ти б у Нього просила, і Він тобі дав би живої води“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Каже жінка до Нього: „І черпака́ в Тебе, Пане, нема, а криниця глибока, — звідки ж маєш Ти воду живу?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Чи Ти більший за нашого отця Якова, що нам дав цю криницю, і він сам із неї пив, і сини його, і худоба його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Ісус відповів і сказав їй: „Кожен, хто воду цю п\'є, буде пра́гнути зно́ву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'А хто питиме воду, що Я йому дам, пра́гнути не буде повік, бо вода, що Я йому дам, стане в нім джерелом тієї води, що тече в життя вічне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, 'Каже жінка до Нього: „Дай мені, Пане, цієї води, щоб я пити не хотіла, і сюди не прихо́дила брати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'Говорить до неї Ісус: „Іди, поклич чоловіка свого та й вертайся сюди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Жінка відповіла та й сказала: „Чоловіка не маю“. Відказав їй Ісус: „Ти добре сказала: Чоловіка не маю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Бо п\'ятьох чоловіків ти мала, а той, кого маєш тепер, — не муж він тобі. Це ти правду сказала“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'Каже жінка до Нього: „Бачу, Пане, що Пророк Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Отці наші вклоня́лися Богу на цій ось горі, а ви тве́рдите, що в Єрусалимі те місце, де потрібно вклонятись“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'Ісус промовляє до неї: „Повір, жінко, Мені, що надхо́дить година, коли ні на горі цій, ані в Єрусалимі вклоня́тись Отцеві не бу́дете ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Ви вклоняєтесь тому, чого ви не знаєте, ми вклоняємось тому, що знаємо, бо спасіння — від юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Але наступає година, і тепер вона є, коли богомі́льці правдиві вклонятися бу́дуть Отцеві в дусі та в правді, бо Отець Собі прагне таких богомі́льців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 24, 'Бог є Дух, і ті, що Йому вклоняються, повинні в дусі та в правді вклоня́тись“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 25, 'Відказує жінка Йому: „Я знаю, що при́йде Месі́я, що зветься Христо́с, — як Він прийде, то все розпові́сть нам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 26, 'Промовляє до неї Ісус: „Це Я, що розмовляю з тобою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 27, 'І тоді надійшли Його учні, і дивувались, що з жінкою Він розмовляв. Проте жоден із них не спитав: „Чого хочеш?“або: „Про що з нею гово́риш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 28, 'Покинула жінка тоді водоно́са свого, і побігла до міста, та й людям гово́рить:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 29, '„Ходіть но, побачте Того Чоловіка, що сказав мені все, що́ я вчинила. Чи Він не Христос?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 30, 'І вони повихо́дили з міста, і до Нього прийшли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 31, 'Тим ча́сом же учні просили Його та й казали: „Учителю, їж!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 32, 'А Він їм відказав: „Я маю пожи́ву на ї́дження, якої не знаєте ви“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 33, 'Питали тоді один о́дного учні: „Хіба хто приніс Йому їсти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 34, 'Ісус каже до них: „Пожива Моя — чинити волю Того, Хто послав Мене, і справу Його доверши́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 35, 'Чи не кажете ви: „Ще чотири от місяці, — і наста́нуть жнива́?“А Я вам кажу́: Підійміть свої очі, та гляньте на ни́ви, — як для жнив уже пополові́ли вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 36, 'А хто жне, той заплату бере, та збирає врожай в життя вічне, щоб хто сіє й хто жне — ра́зом раділи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 37, 'Бо про це погові́рка правдива: „Хто інший сіє, а хто інший жне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 38, 'Я вас жати послав, де ви не працюва́ли: працюва́ли інші, ви ж до їхньої праці ввійшли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 39, 'З того ж міста багато-хто із самаря́н в Нього ввірували через слово жінки, що сві́дчила: „Він сказав мені все, що я вчинила була́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 40, 'А коли самаря́ни до Нього прийшли, то благали Його, щоб у них позостався. І Він перебув там два дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 41, 'Значно ж більш вони ввірували через слово Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 42, 'А до жінки казали вони: „Не за слово твоє ми вже віруємо, — самі бо ми чули й пізна́ли, що справді Спаси́тель Він світу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 43, 'Як минуло ж два дні, Він ізвідти пішов в Галілею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 44, 'Сам бо сві́дчив Ісус, що не має пошани пророк у вітчи́зні своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 45, 'А коли Він прийшов в Галілею, Його прийняли́ галіле́яни, побачивши все, що вчинив Він в Єрусалимі на святі, бо ходили на свято й вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 46, 'Тоді зно́ву прийшов Ісус у Кану́ Галілейську, де перемінив був Він воду на вино. І був там один царедво́рець, що син його хво́рів у Капернау́мі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 47, 'Він, почувши, що Ісус із Юдеї прибув в Галілею, до Нього прийшов і благав Його, щоб пішов і сина йому вздоровив, бо мав той умерти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 48, 'Ісус же промовив до нього: „Як знаме́н тих та чуд не побачите, — не ввіруєте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 49, 'Царедво́рець говорить до Нього: „Піди, Господи, поки не вмерла дитина моя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 50, 'Промовляє до нього Ісус: „Іди, — син твій живе!“І повірив той слову, що до нього промовив Ісус, — і пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 51, 'А коли ще в дорозі він був, то раби́ його перестріли його й сповістили, говорячи: „Син твій живе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 52, 'А він їх запитав про годину, о котрі́й стало легше йому. Вони ж відказали до нього: „Учора о сьомій годині гаря́чка поки́нула його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 53, 'Зрозумів тоді ба́тько, що була́ то година, о котрі́й до нього промовив Ісус: „Син твій живе“. І ввірував сам і ввесь його дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 54, 'Це знов друге знаме́но Ісус учинив, як вернувся до Галілеї з Юдеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 1, 'Після того юдейське Свято було, і до Єрусалиму Ісус відійшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 2, 'А в Єрусалимі, біля брами Овечої, є купальня, Віфесда́ по-єврейському зветься, що мала п\'ять ґа́нків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 3, 'У них лежало багато слабих, сліпих, кривих, сухих, що чекали, щоб воду пору́шено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 4, 'Бо ангол Господній часами спускавсь до купальні, і порушував воду, і хто перший ула́зив, як воду пору́шено, той здоровим ставав, хоч би яку мав хворо́бу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 5, 'А був там один чоловік, що тридцять і вісім ро́ків був недужим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 6, 'Як Ісус його вгледів, що лежить, та, відаючи, що багато він ча́су слабує, говорить до нього: „Хочеш бути здоровим?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 7, 'Відповів Йому хворий: „Пане, я не маю люди́ни, щоб вона, як порушено воду, до купа́льні всадила мене. А коли я прихо́джу, то передо мною вже інший ула́зить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 8, 'Говорить до нього Ісус: „Уставай, візьми ложе своє — та й ходи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 9, 'І зараз одужав оцей чоловік, і взяв ложе своє — та й ходив. Того ж дня субота була́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 10, 'тому́ то сказали юдеї вздоро́вленому: „Є субота, і не годиться тобі брати ложа свого“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 11, 'А він відповів їм: „Хто мене вздоро́вив, Той до мене сказав: Візьми ложе своє — та й ходи“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 12, 'А вони запитали його: „Хто Той Чоловік, що до тебе сказав: Візьми ложе своє — та й ходи?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 13, 'Та не знав уздоро́влений, Хто то Він, бо Ісус ухиливсь від наро́ду, що був на тім місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 14, 'Після того Ісус стрів у храмі його, та й промовив до нього: „Ось ви́дужав ти. Не гріши ж уже більше, щоб не сталось тобі чого гіршого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 15, 'Чоловік же пішов і юдеям звістив, що Той, Хто вздоро́вив його, то Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 16, 'І тому́ зачали́ юдеї переслідувати Ісуса, що таке Він чинив у суботу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 17, 'А Ісус відповів їм: „Отець Мій працює аж досі, — працюю і Я“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 18, 'І тому́ то юдеї ще більш намагалися вбити Його, що не тільки суботу пору́шував Він, але й Бога Отцем Своїм звав, тим ро́блячись Богові рівним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 19, 'Відповів же Ісус і сказав їм: „Поправді, поправді кажу́ вам: Син нічо́го робити не може Сам від Себе, тільки те, що Він бачить, що ро́бить Отець; бо що робить Він, те так само й Син ро́бить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 20, 'Бо Отець любить Сина, і показує все, що Сам робить, Йому. І покаже Йому діла більші від цих, щоб ви дивува́лись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 21, 'Бо як мертвих Отець воскрешає й ожи́влює, так і Син, кого хоче, ожи́влює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 22, 'Бо Отець і не судить ніко́го, а ввесь суд віддав Синові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 23, 'щоб усі шанували і Сина, як шанують Отця. Хто не шанує Сина, — не шанує Отця, що послав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 24, 'Поправді, поправді кажу вам: Хто слухає сло́ва Мого, і вірує в Того, Хто послав Мене, — життя вічне той має, і на суд не прихо́дить, але перейшов він від смерти в життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 25, 'Поправді, поправді кажу́ вам: Наступає година, і тепер уже є, коли голос Божого Сина почують померлі, а ті, що почують, оживуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 26, 'Бо як має Отець життя Сам у Собі, так і Синові дав життя мати в Самому Собі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 27, 'І Він дав Йому силу чинити і суд, бо Він — Людський Син.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 28, 'Не дивуйтесь цьому́, бо надхо́дить година, коли всі, хто в гроба́х, — Його голос почують,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 29, 'і повихо́дять ті, що чинили добро, на воскре́сення життя, а котрі́ зло чинили, на воскре́сення Су́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 30, 'Я нічого не мо́жу роби́ти Сам від Себе. Як Я чую, суджу́, і Мій суд справедливий, — не шукаю бо волі Своєї, але волі Отця, що послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 31, 'Коли сві́дчу про Себе Я Сам, то свідо́цтво Моє неправдиве.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 32, 'Є Інший, Хто сві́дчить про Мене, і Я знаю, що правдиве свідо́цтво, яким сві́дчить про Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 33, 'Ви послали були́ до Івана, і він сві́дчив про правду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 34, 'Та Я не від людини свідо́цтва приймаю, але це говорю́, щоб були ви спасені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 35, 'Він світильником був, що горів і світив, та ви тільки хвилю хотіли поті́шитись світлом його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 36, 'Але Я маю свідчення більше за Іванове, бо ті справи, що Отець Мені дав, щоб Я виконав їх, ті справи, що Я їх чиню́, самі сві́дчать про Мене, що Отець Мене послав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 37, 'Та й Отець, що послав Мене, Сам засві́дчив про Мене; але ви ані голосу Його не чули ніко́ли, ані виду Його не бачили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 38, 'Навіть сло́ва Його ви не маєте, щоб у вас перебува́ло, бо не вірите в То́го, Кого Він послав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 39, 'Дослідіть но Писа́ння, бо ви ду́маєте, що в них маєте вічне життя, — вони ж сві́дчать про Мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 40, 'Та до Мене прийти ви не хочете, щоб мати життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 41, 'Від людей не приймаю Я слави,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 42, 'але вас Я пізнав, що любови до Бога в собі ви не маєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 43, 'Я прийшов у Йме́ння Свого Отця, та Мене не приймаєте ви. Коли ж при́йде інший у йме́ння своє, того при́ймете ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 44, 'Як ви можете вірувати, коли славу один від одно́го приймаєте, а слави тієї, що від Бога Єдиного, не пра́гнете ви?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 45, 'Не думайте, що Я перед Отцем буду вас винуватити, — є, хто вас винуватити бу́де, — Мойсей, що на нього наді́єтесь ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 46, 'Коли́ б ви Мойсеєві вірили, то й Мені б ви повірили, бо про Мене писав він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 47, 'Якщо писа́нням його ви не вірите, то як віри поймете словам Моїм?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 1, 'Після того Ісус перейшов на той бік Галілейського чи Тіверія́дського моря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 2, 'А за Ним ішла бе́зліч народу, бо бачили чу́да Його, що чинив над недужими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 3, 'Ісус же на го́ру зійшов, і сидів там зо Своїми учнями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 4, 'Наближа́лася ж Пасха, свято юдейське.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 5, 'А Ісус, звівши очі Свої та побачивши, яка бе́зліч наро́ду до Нього йде, говорить Пилипові: „Де́ ми купимо хліба, щоб вони поживи́лись?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 6, 'Він же це говорив, його випробо́вуючи, бо знав Сам, що́ Він має робити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 7, 'Пилип Йому відповідь дав: „І за двісті дина́ріїв їм хліба не стане, щоб кожен із них бодай тро́хи дістав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 8, 'Говорить до Нього Андрій, один з учнів Його, брат Си́мона Петра:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 9, '„Є тут хлопчи́на один, що має п\'ять я́чних хлібів та дві риби, але що́ то на бе́зліч таку!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 10, 'А Ісус відказав: „Скажіть лю́дям сідати!“А була на тім місці велика трава. І засіло чоловіка числом із п\'ять тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 11, 'А Ісус узяв хліби́, і, подяку вчинивши, роздав тим, хто сидів. Так само і з риб, скільки хотіли вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 12, 'І, як наїлись вони, Він говорить до учнів Своїх: „Позбирайте куски позоста́лі, щоб ніщо не загинуло“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 13, 'І зібрали вони. І дванадцять повних кошів наклали кусків, що лишились їдця́м із п\'яти я́чних хлібів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 14, 'А люди, що бачили чудо, яке Ісус учинив, гомоніли: „Це Той справді Пророк, що повинен прибути на світ!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 15, 'Спостерігши ж Ісус, що вони мають за́мір прийти та забрати Його, щоб настанови́ти царем, знов на го́ру пішов Сам один.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 16, 'А як вечір настав, то зійшли Його учні над море.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 17, 'І, ввійшовши до чо́вна, на другий бік моря вони попливли́, до Капернау́му. І те́мрява вже наступила була́, а Ісус ще до них не прихо́див.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 18, 'Від великого ж вітру, що віяв, хвилюва́лося море.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 19, 'Як вони ж пропливли́ стадій із двадцять п\'ять або з тридцять, то Ісуса побачили, що йде Він по морю, і до чо́вна зближається, — і їх страх обгорну́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 20, 'Він же каже до них: „Це Я, — не лякайтесь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 21, 'І хотіли вони взяти до чо́вна Його; та чо́вен зараз пристав до землі, до якої пливли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 22, 'А наступного дня той наро́д, що на тім боці моря стояв, побачив, що там іншого чо́вна, крім одно́го того́, що до нього ввійшли були учні Його, не було́, і що до чо́вна не вхо́див Ісус із Своїми учнями, але відпливли́ самі учні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 23, 'А тим ча́сом із Тіверія́ди припливли́ човни́ інші близько до місця того, де вони їли хліб, як Господь учинив був подяку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 24, 'Отож, як побачили люди, що Ісуса та учнів Його там нема, то в човни́ посідали самі й прибули́ до Капернауму, — і шукали Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 25, 'І, на тім боці моря знайшовши Його, сказали Йому: „Коли Ти прибув сюди, Учителю?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 26, 'Відповів їм Ісус і сказав: „Поправді, поправці кажу́ вам: Мене не тому ви шукаєте, що бачили чуда, а що їли з хлібів і наси́тились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 27, 'Пильнуйте не про пожи́ву, що гине, але про поживу, що зостається на вічне життя, яку дасть вам Син Лю́дський, бо запечатав Його Бог Отець“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 28, 'Сказали ж до Нього вони: „Що́ ми маємо почати, щоб роби́ти діла Божі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 29, 'Ісус відповів і сказав їм: „Оце діло Боже, — щоб у Того ви вірували, Кого Він послав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 30, 'А вони відказали Йому: „Яке ж знаме́но Ти чиниш, щоб побачили ми й поняли́ Тобі віри? Що Ти робиш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 31, 'Наші отці́ їли ма́нну в пустині, як написано: „Хліб із неба їм дав на поживу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 32, 'А Ісус їм сказав: „Поправді, поправді кажу́ вам: Не Мойсей хліб із неба вам дав, — Мій Отець дає вам хліб правдивий із неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 33, 'Бо хліб Божий є Той, Хто сходить із неба й дає життя світові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 34, 'А вони відказали до Нього: „Давай, Господи, хліба такого нам за́вжди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 35, 'Ісус же сказав їм: „Я — хліб життя. Хто до Мене прихо́дить, — не голодува́тиме він, а хто вірує в Мене, — ніко́ли не пра́гнутиме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 36, 'Але Я вам сказав, що Мене хоч ви й бачили, та не віруєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 37, 'Усе при́йде до Мене, що Отець дає Мені, а того, хто до Мене приходить, Я не вижену геть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 38, 'Бо Я з неба зійшов не на те, щоб волю чинити Свою, але волю Того, Хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 39, 'Оце ж воля Того, Хто послав Мене, — щоб з усього, що дав Мені Він, Я нічого не стратив, але воскреси́в те останнього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 40, 'Оце ж воля Мого Отця, — щоб усякий, хто Сина бачить та вірує в Нього, мав вічне життя, — і того воскрешу́ Я останнього дня“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 41, 'Тоді стали юдеї ре́мствувати на Нього, що сказав: „Я той хліб, що з неба зійшов“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 42, 'І казали вони: „Хіба Він не Ісус, син Йо́сипів, що ми знаємо батька та матір Його? Як же Він каже: Я з неба зійшов?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 43, 'А Ісус відповів і промовив до них: „Не ремствуйте ви між собою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 44, 'Ніхто бо не може до Мене прийти, як Отець, що послав Мене, не притягне його, — і того воскрешу́ Я останнього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 45, 'У Пророків написано: „І всі бу́дуть від Бога навче́ні.“Кожен, хто від Бога почув і навчився, приходить до Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 46, 'Це не значить, щоб хтось Отця бачив, — тільки Той Отця бачив, Хто походить від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 47, 'Поправді, поправді кажу́ Вам: Хто вірує в Мене, — життя вічне той має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 48, 'Я — хліб життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 49, 'Отці ваші в пустині їли манну, — і померли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 50, 'То є хліб, Який сходить із неба, — щоб не вмер, хто Його споживає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 51, 'Я — хліб живий, що з неба зійшов: коли хто споживатиме хліб цей, той повік буде жити. А хліб, що дам Я, то є тіло Моє, яке Я за життя світу дам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 52, 'Тоді між собою змагатися стали юдеї, говорячи: „Як же Він може дати нам тіла спожити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 53, 'І сказав їм Ісус: „Поправді, поправді кажу вам: Якщо ви споживати не будете тіла Сина Лю́дського й пити не будете крови Його, то в собі ви не будете мати життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 54, 'Хто тіло Моє споживає та кров Мою п\'є, той має вічне життя, — і того воскрешу́ Я останнього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 55, 'Бо тіло Моє — то правдиво пожива, Моя ж кров — то правдиво пиття.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 56, 'Хто тіло Моє споживає та кров Мою п\'є, той в Мені перебува́є, а Я в ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 57, 'Як Живий Отець послав Мене, і живу Я Отцем, так і той, хто Мене споживає, і він житиме Мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 58, 'То є хліб, що з неба зійшов. Не як ваші отці їли ма́нну й померли, — хто цей хліб споживає, той жити буде пові́к!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 59, 'Оце Він говорив, коли в Капернаумі навчав у синагозі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 60, 'А багато-хто з учнів Його, як почули оце, гомоніли: „Жорстока це мова! Хто́ слухати може її?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 61, 'А Ісус, Сам у Собі знавши це, що учні Його на те ре́мствують, промовив до них: „Чи оце вас споку́шує?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 62, 'А що ж, як побачите Лю́дського Сина, що сходить туди, де перше Він був?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 63, 'То Дух, що ожи́влює, тіло ж не помагає нічого. Слова́, що їх Я говорив вам, то дух і життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 64, 'Але є дехто з вас, хто не вірує“. Бо Ісус знав споча́тку, хто ті, хто не вірує, і хто видасть Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 65, 'І сказав Він: „Я тому́ й говорив вам, що до Мене прибути не може ніхто, як не буде йому від Отця да́не те “.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 66, 'Із того ча́су відпали багато-хто з учнів Його, і не ходили вже з Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 67, 'І сказав Ісус Дванадцятьо́м: „Чи не хочете й ви́ відійти?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 68, 'Відповів Йому Си́мон Петро: „До ко́го ми пі́демо, Господи? Ти маєш слова́ життя вічного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 69, 'Ми ж увірували та пізнали, що Ти — Христос, Син Бога Живого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 70, 'Відповів їм Ісус: „Чи не Дванадцятьо́х Я вас вибрав? Та один із вас дия́вол“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 71, 'Це сказав Він про Юду, сина Си́монового, Іскаріо́та. Бо цей мав Його видати, хоч він був один із Дванадцятьо́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 1, 'Після цього Ісус ходив по Галілеї, не хотів бо ходи́ти по Юдеї, бо юдеї шукали наго́ди, щоб убити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 2, 'А надхо́дило свято юдейське — Ку́чки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 3, 'І сказали до Нього брати Його: „Піди звідси, і йди до Юдеї, щоб і учні Твої побачили вчинки Твої, що Ти робиш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 4, 'Тайкома́ бо не робить нічо́го ніхто, але сам прагне бути відо́мий. Коли Ти таке чиниш, то з\'яви́ Себе світові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 5, 'Бо не вірували в Нього навіть брати Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 6, 'А Ісус промовляє до них: „Не настав ще Мій час, але за́вжди готовий час ваш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 7, 'Вас нена́видіти світ не може, а Мене він нена́видить, бо Я сві́дчу про нього, що діла́ його злі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 8, 'Ідіть на це свято, Я ж іще не піду́ на це свято, бо не ви́повнився ще Мій час“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 9, 'Це сказавши до них, Він зоставсь у Галілеї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 10, 'Коли ж вийшли на свято брати Його, тоді й Сам Він пішов, — не відкрито, але́ ніби по́тай.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 11, 'А юдеї за свята шукали Його та питали: „Де Він?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 12, 'І поголо́ска велика про Нього в наро́ді була. Одні говорили: „Він добрий“, а інші казали: „Ні, — Він зводить з дороги наро́д“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 13, 'Та відкрито про Нього ніхто не казав, — бо боялись юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 14, 'У половині вже свята Ісус у храм увійшов і навчав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 15, 'І дивувались юдеї й казали: „Як Він знає Писа́ння, не вчившись?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 16, 'Відповів їм Ісус і сказав: „Наука Моя — не Моя, а Того, Хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 17, 'Коли хоче хто волю чинити Його, той довідається про науку, чи від Бога вона, чи від Себе Самого кажу́ Я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 18, 'Хто говорить від себе самого, той власної слави шукає, а Хто слави шукає Того, Хто послав Його, Той правдивий, — і в Ньому неправедности нема.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 19, 'Чи ж Зако́на вам дав не Мойсей? Та ніхто з вас Зако́на того не виконує. На́що хочете вбити Мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 20, 'Наро́д відповів: „Чи Ти де́мона маєш? Хто Тебе хоче вбити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 21, 'Ісус відповів і сказав їм: „Одне ді́ло зробив Я, — і всі ви дивуєтесь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 22, 'Через це Мойсей дав обрі́зання вам, — не тому́, що воно від Мойсея, але від отців, — та ви й у суботу обрізуєте чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 23, 'Коли ж чоловік у суботу приймає обрі́зання, щоб Зако́ну Мойсеєвого не порушити, чого ж ре́мствуєте ви на Мене, що Я всю люди́ну в суботу вздоро́вив?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 24, 'Не судіть за обличчям, але суд справедливий чиніть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 25, 'Дехто ж з єрусали́млян казали: „Хіба́ це не Той, що Його шукають убити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 26, 'Бо говорить відкрито ось Він, — і нічого не кажуть Йому. Чи то справді дізналися старші, що Він дійсно Христос?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 27, 'Та ми знаєм Цього, звідки Він. Про Христа ж, коли при́йде, ніхто знати не бу́де, звідки Він“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 28, 'І скликнув у храмі Ісус, навчаючи й кажучи: „І Мене знаєте ви, і знаєте, звідки Я. А Я не прийшов Сам від Себе; правдивий же Той, Хто послав Мене, що Його ви не знаєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 29, 'Я знаю Його, — Я бо від Нього, і послав Мене Він!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 30, 'Тож шукали вони, щоб схопи́ти Його, та ніхто не наклав рук на Нього, — бо то ще не настала година Його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 31, 'А багато з наро́ду в Нього ввірували та казали: „Коли при́йде Христос, чи ж Він чу́да чинитиме більші, як чинить Оцей?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 32, 'Фарисеї прочули такі поголо́ски про Нього в наро́ді. Тоді первосвященики та фарисеї послали свою́ службу, щоб схопи́ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 33, 'Ісус же сказав: „Ще недовго побу́ду Я з вами, та й до Того піду́, Хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 34, 'Ви бу́дете шукати Мене, — і не зна́йдете; а туди, де Я є, ви прибути не можете“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 35, 'Тоді говорили юдеї між собою: „Куди це Він хоче йти, що не зна́йдемо Його? Чи не хоче йти до виселе́нців між греки, та й греків навчати?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 36, 'Що за слово, яке Він сказав: „Ви бу́дете шукати Мене, — і не знайдете; а туди, де Я є, ви прибути не можете?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 37, 'А останнього великого дня свята Ісус стояв і кликав, говорячи: „Коли прагне хто з вас — нехай при́йде до Мене та й п\'є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 38, 'Хто вірує в Мене, як каже Писа́ння, то ріки живої води потечуть із утро́би його́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 39, 'Це ж сказав Він про Духа, що мали прийняти Його, хто ввірував у Нього. Не було́ бо ще Духа на них, — не був бо Ісус ще просла́влений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 40, 'А багато з наро́ду, почувши слова́ ті, казали: „Він справді пророк!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 41, 'Інші казали: „Він Христос“. А ще інші казали: „Хіба при́йде Христос із Галілеї?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 42, 'Чи ж не каже Писа́ння, що Христос при́йде з роду Давидового, і з села Вифлеє́му, звідкіля́ був Давид?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 43, 'Так повстала незгода в наро́ді з-за Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 44, 'А де́котрі з них мали замір схопи́ти Його́, — та ніхто не поклав рук на Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 45, 'І вернулася слу́жба до первосвящеників та фарисеїв, а ті їх запитали: „Чому не привели́ ви Його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 46, 'Відказала та слу́жба: „Чоловік ще ніко́ли так не промовляв, як Оцей Чоловік“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 47, 'А їм відповіли́ фарисеї: „Чи й вас із дороги не зве́дено?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 48, 'Хіба́ хто з старши́х або з фарисеїв увірував у Нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 49, 'Та прокля́тий народ, що не знає Зако́ну!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 50, 'Говорить до них Никоди́м, що приходив до Ньо́го вночі, і що був один із них:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 51, '„Хіба судить Зако́н наш люди́ну, як перше її не вислухає, і не дізнається, що́ вона робить?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 52, 'Йому відповіли та сказали вони: „Чи й ти не з Галілеї? Досліди та побач, що не при́йде Пророк із Галілеї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 53, 'І до дому свого́ пішов кожен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 1, 'Ісус же на гору Оли́вну пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 2, 'А над ранком прийшов знов у храм, — і всі люди збігались до Нього. А Він сів і навчав їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 3, 'І ось книжники та фарисеї приводять до Нього в пере́любі схо́плену жінку, і посере́дині ставлять її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 4, 'та й говорять Йому: „Оцю жінку, Учителю, зло́влено на гарячому вчинку пере́любу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 5, 'Мойсей же в Зако́ні звелів нам таких побива́ти камінням. А Ти що гово́риш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 6, 'Це ж казали вони, Його споку́шуючи, та щоб мати на Нього оска́рження. А Ісус, нахилившись додо́лу, по землі писав пальцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 7, 'А коли ті не переставали питати Його, Він підвівся й промовив до них: „Хто з вас без гріха́, — нехай перший на неї той каменем кине!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 8, 'І Він знов нахили́вся додо́лу, і писав по землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 9, 'А вони, це почувши й сумлінням доко́рені, стали один по одно́му вихо́дити, почавши з найстарших та аж до останніх. І зоставсь Сам Ісус і та жінка, що стояла всере́дині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 10, 'І підвівся Ісус, і ніко́го, крім жінки, не бачивши, промовив до неї: „Де́ ж ті, жінко, що тебе оскаржа́ли? Чи ніхто тебе не засудив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 11, 'А вона відказала: „Ніхто, Господи“. І сказав їй Ісус: „Не засуджую й Я тебе. Іди собі, але більш не гріши!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 12, 'І зно́ву Ісус промовляв до них, кажучи: „Я Світло для світу. Хто йде вслід за Мною, не бу́де ходити у те́мряві той, але́ матиме світло життя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 13, 'Фарисеї ж Йому відказали: „Ти Сам сві́дчиш про Себе, — тим свідо́цтво Твоє неправдиве“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 14, 'Відповів і сказав їм Ісус: „Хоч і сві́дчу про Себе Я Сам, — та правдиве свідо́цтво Моє, бо Я знаю, звідкіля Я прийшов і куди Я йду. Ви ж не ві́даєте, відкіля Я прихо́джу, і куди Я йду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 15, 'Ви за тілом судите, — Я не суджу́ ніко́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 16, 'А коли Я суджу́, то правдивий Мій суд, бо не Сам Я, а Я та Отець, що послав Він Мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 17, 'Та й у вашім Зако́ні написано, що сві́дчення двох чоловіків правдиве.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 18, 'Я Сам свідчу про Себе Самого, і сві́дчить про Мене Отець, що послав Він Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 19, 'I сказали до Нього вони: „Де Отець Твій?“Ісус відповів: „Не знаєте ви ні Мене, ні Мого Отця. Якби знали Мене, то й Отця Мого знали б“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 20, 'Ці слова́ Він казав при скарбни́ці, у храмі навчаючи. І ніхто не схопи́в Його, бо то ще не настала година Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 21, 'І сказав Він їм зно́ву: „Я відхо́джу, ви ж шукати Мене бу́дете, і помрете в гріху своїм. Куди Я йду, туди ви прибути не можете“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 22, 'А юдеї казали: „Чи не вб\'є Він Сам Себе, коли каже: Куди Я йду, туди ви прибу́ти не можете?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 23, 'І сказав Він до них: „Ви — від до́лу, Я — звисо́ка, і ви зо світу цього, Я не з цього світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 24, 'Тому́ Я сказав вам, що помре́те в своїх гріхах. Бо коли не ввіруєте, що то Я, то помре́те в своїх гріхах“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 25, 'А вони запитали Його: „Хто Ти такий?“І Ісус відказав їм: „ Той, Хто споча́тку, як і говорю́ Я до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 26, 'Я маю багато про вас говорити й судити; правдивий же Той, Хто послав Мене, і Я світові те говорю́, що від Нього почув“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 27, 'Але не зрозуміли вони, що то Він про Отця говорив їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 28, 'Тож Ісус їм сказав: „Коли ви піді́ймете Лю́дського Сина, тоді зрозумієте, що то Я, і що Сам Я від Себе нічого не ді́ю, але те говорю́, як Отець Мій Мене був навчив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 29, 'А Той, Хто послав Мене, перебува́є зо Мною; Отець не зоставив Само́го Мене, бо Я за́вжди чиню́, що Йому до вподо́би“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 30, 'Коли Він говорив це, то багато-хто в Нього увірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 31, 'Тож промовив Ісус до юдеїв, що в Нього ввірували: „Як у слові Моїм позоста́нетеся, тоді справді Моїми у́чнями бу́дете,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 32, 'і пізна́єте правду, — а правда вас вільними зробить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 33, 'Вони відказали Йому́: „Авраамів ми рід, і нічиїми невільниками не були́ ми ніко́ли. То як же Ти кажеш: „Ви станете вільні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 34, 'Відповів їм Ісус: „Поправді, поправді кажу́ вам, що кожен, хто чинить гріх, той раб гріха́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 35, 'І не зостається раб у домі повік, але Син зостається повік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 36, 'Коли Син отже зробить вас вільними, то справді ви будете вільні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 37, 'Знаю Я, що ви рід Авраамів, але хочете смерть заподі́яти Мені, бо наука Моя не вміщається в вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 38, 'Я те говорю́, що Я бачив в Отця, та й ви робите те, що ви бачили в ба́тька свого́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 39, 'Сказали вони Йому в відповідь: „Наш отець — Авраам“. Відказав їм Ісус: „Коли б ви Авраамові діти були, то чинили б діла́ Авраамові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 40, 'А тепер ось ви хочете вбити Мене, Чоловіка, що вам казав правду, яку чув Я від Бога. Цього Авраам не робив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 41, 'Ви робите діла батька свого“. Вони ж відказали Йому: „Не родилися ми від пере́любу, — одного ми маєм Отця — то Бога“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 42, 'А Ісус їм сказав: „Якби Бог був Отець ваш, — ви б любили Мене, бо від Бога Я вийшов і прийшов, — не від Себе ж Самого прийшов Я, а Мене Він послав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 43, 'Чому мови Моєї ви не розумієте? Бо не можете чути ви сло́ва Мого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 44, 'Ваш ба́тько — диявол, і пожадли́вості батька свого ви виконувати хочете. Він був душогу́б споконві́ку, і в правді не всто́яв, бо правди нема в нім. Як гово́рить неправду, то говорить зо сво́го, — бо він неправдомо́вець і ба́тько неправді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 45, 'А Мені ви не вірите, бо Я правду кажу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 46, 'Хто з вас може Мені докори́ти за гріх? Коли ж правду кажу́, чом Мені ви не вірите?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 47, 'Хто від Бога, той слухає Божі слова́; через те ви не слухаєте, що ви не від Бога“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 48, 'Відізвались юдеї й сказали Йому́: „Чи ж не добре ми кажемо, що Ти самаряни́н і де́мона маєш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 49, 'Ісус відповів: „Не маю Я де́мона, та шаную Свого Отця, ви ж Мене зневажа́єте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 50, 'Не шукаю ж Я власної слави, — є Такий, Хто шукає та судить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 51, 'Поправді, поправді кажу́ вам: Хто слово Моє берегти́ме, не побачить той смерти повік!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 52, 'І сказали до Нього юдеї: „Тепер ми дізнались, що де́мона маєш: умер Авраам і пророки, а Ти кажеш: Хто науку Мою берегтиме, не скуштує той смерти повік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 53, 'Чи ж Ти більший, аніж отець наш Авраам, що помер? Та повмирали й пророки. Ким Ти робиш Само́го Себе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 54, 'Ісус відповів: „Як Я сла́влю Самого Себе, то ніщо Моя слава. Мене прославляє Отець Мій, про Якого ви кажете, що Він Бог ваш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 55, 'І ви не пізнали Його, а Я знаю Його. А коли Я скажу́, що не знаю Його, — буду неправдомо́вець, подібний до вас. Та Я знаю Його, — і слово Його зберігаю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 56, 'Отець ваш Авраам прагнув із радістю, щоб побачити день Мій, — і він бачив, і тішився“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 57, 'А юдеї ж до Нього сказали: „Ти й п\'ятидесяти́ ро́ків не маєш іще, — і Авраама Ти бачив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 58, 'Ісус їм відказав: „Поправді, поправді кажу́ вам: Перш, ніж був Авраам, — Я є“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 59, 'І схопи́ли каміння вони, щоб кинути на Нього. Та схова́вся Ісус, і з храму пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 1, 'А коли Він прохо́див, побачив чоловіка, що сліпим був з наро́дження.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 2, 'І спитали Його учні Його, говорячи: „Учителю, хто згрішив: чи він сам, чи батьки його, що сліпим він родився?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 3, 'Ісус відповів: „Не згрішив ані він, ні батьки його, а щоб діла Божі з\'явились на ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 4, 'Ми мусимо виконувати діла Того, Хто послав Мене, аж поки є день. Надхо́дить он ніч, коли жоден нічо́го не зможе виконувати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 5, 'Доки Я в світі, — Я Світло для світу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 6, 'Промовивши це, Він сплюнув на землю, і з сли́ни грязи́во зробив, і очі сліпому пома́зав грязи́вом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 7, 'і до нього промовив: „Піди, умийся в ставку́ Сілоа́м“(визначає це „По́сланий“). Тож пішов той і вмився, — і вернувся видю́щим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 8, 'А сусіди та ті, що бачили перше його, як був він сліпий, говорили: „Чи ж не той це, що сидів та просив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 9, 'Говорили одні, що це він, а інші казали: „Ні, — подібний до нього“. А він відказав: „Це я!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 10, 'І питали його: „Як же очі відкрились тобі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 11, 'А той опові́да́в: „Чоловік, що Його звуть Ісусом, грязи́во зробив, і очі помазав мені, і до мене сказав: „Піди в Сілоа́м та й умийся“. Я ж пішов та й умився, — і став бачити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 12, 'І сказали до нього: „Де Він?“Відказує той: „Я не знаю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 13, 'Ведуть тоді до фарисеїв того, що був перше незрячий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 14, 'А була то субота, як грязи́во Ісус учинив і відкрив йому очі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 15, 'І знов запитали його й фарисеї, я́к видющим він став. А він розповів їм: „Грязи́во поклав Він на очі мені, а я вмився, — та й бачу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 16, 'Тоді деякі з фарисеїв казали: „Не від Бога Оцей Чоловік, — бо суботи не де́ржить“. А інші казали: „Як же чу́да такі може грішна люди́на чинити?“І незгода між ними була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 17, 'Тому зно́ву говорять сліпому: „Що́ ти кажеш про Нього, коли очі відкрив Він тобі?“А той відказав: „Він Пророк!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 18, 'Юдеї проте́ йому не повірили, що незрячим він був і прозрів, аж поки не покликано батькі́в того прозрілого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 19, 'І запитали їх, кажучи: „Чи ваш оце син, про якого ви кажете, ніби родився сліпим? Як же він тепер бачить?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 20, 'А батьки його відповіли́ та сказали: „Ми знаєм, що цей — то наш син, і що він народився сліпим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 21, 'Але я́к тепер бачить, — не знаємо, або хто йому очі відкрив, — ми не відаємо. Поспитайте його, — він дорослий, хай сам скаже про себе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 22, 'Таке говорили батьки його, бо боялись юдеїв: юдеї бо вже були змо́вились, — як хто за Христа Його визнає, щоб той був відлучений від синагоги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 23, 'Ось тому говорили батьки його: „Він дорослий, — його поспитайте“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 24, 'І покликали вдруге того чоловіка, що був сліпим, і сказали йому: „Віддай хвалу Богові. Ми знаємо, що грішний Отой Чоловік“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 25, 'Але він відповів: „Чи Він грішний — не знаю. Одне тільки знаю, що я був сліпим, а тепер бачу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 26, 'І спитали його: „Що тобі Він зробив? Як відкрив тобі очі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 27, 'Відповів він до них: „Я вже вам говорив, — та не слухали ви. Що́ бажаєте зно́ву почути? Може й ви Його учнями хочете стати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 28, 'А вони його вилаяли та й сказали: „То ти Його учень, а ми учні Мойсеєві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 29, 'Ми знаємо, що Бог говорив до Мойсея, — звідки ж узявся Оцей, ми не відаємо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 30, 'Відповів чоловік і сказав їм: „То́ ж воно й дивно, що не знаєте ви, звідки Він, — а Він мені очі відкрив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 31, 'Та ми знаємо, що грішників Бог не послухає; хто ж богобійний, і виконує волю Його, — того слухає Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 32, 'Відвіку не чу́вано, щоб хто очі відкрив був сліпому з наро́дження.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 33, 'Коли б не від Бога був Цей, Він нічого не міг би чинити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 34, 'Вони відповіли́ та й сказали йому: „Ти ввесь у гріхах народився, — і чи тобі нас учити?“І геть його вигнали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 35, 'Дізнався Ісус, що вони того вигнали геть, і, знайшовши його, запитав: „Чи віруєш ти в Сина Божого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 36, 'Відповів той, говорячи: „Хто ж то, Пане, Такий, щоб я вірував у Нього?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 37, 'Промовив до нього Ісус: „І ти бачив Його, і Той, Хто говорить з тобою — то Він!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 38, 'А він відказав: „Я вірую, Господи!“І вклонився Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 39, 'І промовив Ісус: „На суд Я прийшов у цей світ, щоб бачили темні, а видю́щі щоб стали незрячі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 40, 'І почули це деякі з тих фарисеїв, що були з Ним, та й сказали Йому: „Чи ж і ми невидю́щі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 41, 'Відказав їм Ісус: „Якби ви невидю́щі були, то не мали б гріха́; а тепер ви говорите: „Бачимо“, — то й ваш гріх зостається при вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 1, 'Поправді, поправді кажу́ вам: Хто не входить двери́ма в коша́ру, але перела́зить деі́нде, — той зло́дій і розбійник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 2, 'А хто входить двери́ма, — той вівцям пастух.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 3, 'Ворота́р відчиняє йому, і його голосу слухають вівці; і свої вівці він кличе по йме́нню, і випрова́джує їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 4, 'А як вижене всі свої вівці, він іде перед ними, і вівці слідо́м за ним ідуть, бо знають голос його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 5, 'За чужим же не пі́дуть вони, а будуть утікати від нього, — бо не знають вони чужого голосу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 6, 'Оцю при́тчу повів їм Ісус, але не зрозуміли вони́, про що їм говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 7, 'І зно́ву промовив Ісус: „Поправді, поправді кажу́ вам, що Я — двері ві́вцям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 8, 'Усі, скільки їх перше Мене прихо́дило, — то злодії й розбійники, але вівці не слухали їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 9, 'Я — двері: коли через Мене хто вві́йде, спасеться, і той вві́йде та ви́йде, і пасо́висько зна́йде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 10, 'Зло́дій тільки на те закрада́ється, щоб красти й убивати та нищити. Я прийшов, щоб ви мали життя, і подоста́тком щоб мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 11, 'Я — Пастир Добрий! Пастир добрий кладе́ життя власне за вівці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 12, 'А наймит, і той, хто не вівча́р, кому вівці не свої, коли бачить, що вовк наближа́ється, то ки́дає вівці й тікає, а вовк їх хапає й поло́шить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 13, 'А на́ймит утікає тому́, що він наймит, і не дбає про вівці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 14, 'Я — Пастир Добрий, і знаю Своїх, і Свої Мене знають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 15, 'Як Отець Мене знає, так і Я Отця знаю, і власне життя Я за вівці кладу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 16, 'Також маю Я інших овець, які не з цієї коша́ри, — Я повинен і їх припрова́дити. І Мій голос почують вони, — і бу́де ота́ра одна й Один Па́стир!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 17, 'Через те Отець любить Мене, що Я власне життя віддаю, щоб ізно́ву прийняти його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 18, 'Ніхто в Мене його не бере́, але Я Сам від Себе кладу́ його. Маю вла́ду віддати його, і маю вла́ду прийняти його зно́ву, — Я цю заповідь взяв від Свого Отця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 19, 'З-за цих слів між юдеями зно́ву незгода зняла́ся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 20, 'І багато-хто з них говорили: „Він де́мона має, і несамови́тий. Чого слухаєте ви Його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 21, 'Інші казали: „Ці слова́ не того, хто демона має. Хіба де́мон може очі сліпим відкривати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 22, 'Було тоді свято Відно́влення в Єрусалимі. Стояла зима.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 23, 'А Ісус у храмі ходив, у Соломоновім ґа́нку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 24, 'Юдеї тоді обступили Його та й казали Йому: „Доки будеш тримати в непе́вності нас? Якщо́ Ти Христос, — то відкрито скажи нам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 25, 'Відповів їм Ісус: „Я вам був сказав, — та не вірите ви. Ті діла, що чиню́ їх у Йме́ння Свого Отця, — вони свідчать про Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 26, 'Та не вірите ви, — не з Моїх бо овець ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 27, 'Мого голосу слухають вівці Мої, і знаю Я їх, і за Мною слідко́м вони йдуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 28, 'І Я життя вічне даю їм, і вони не загинуть повік, і ніхто їх не ви́хопить із Моєї руки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 29, 'Мій Отець, що дав їх Мені, Він більший за всіх, — і ви́хопити ніхто їх не може Отцеві з руки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 30, 'Я й Отець — Ми одне!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 31, 'Знов каміння схопи́ли юдеї, щоб укаменува́ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 32, 'Відповів їм Ісус: „Від Отця показав Я вам добрих учинків багато, — за котри́й же з тих учинків хочете Мене каменувати?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 33, 'Юдеї Йому відказали: „Не за добрий учинок хочемо Тебе вкаменувати, а за богозневагу, — бо Ти, бувши люди́ною, за Бога Себе видаєш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 34, 'Відповів їм Ісус: „Хіба не написано в вашім Зако́ні: „Я сказав: ви боги\"?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 35, 'Коли тих Він богами назвав, що до них слово Боже було́, — а Писа́ння не може порушене бути,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 36, 'то Тому́, що Отець освятив і послав Його в світ, закидаєте ви: „Зневажаєш Ти Бога“, через те, що сказав Я: „Я — Син Божий“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 37, 'Коли Я не чиню́ діл Свого Отця, то не вірте Мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 38, 'А коли Я чиню́, то хоч ви Мені віри й не йме́те, повірте ділам, щоб пізнали й повірили ви, що Отець у Мені, а Я — ув Отці!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 39, 'Тоді зно́ву шукали вони, щоб схопи́ти Його, але вийшов із рук їхніх Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 40, 'І Він знову на то́й бік Йорда́ну пішов, на те місце, де Іван найперше христив, та й там перебува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 41, 'І багато до Нього прихо́дили та говорили, що хоч жа́дного чуда Іван не вчинив, але все, що про Нього Іван говорив, правдиве було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 42, 'І багато-хто ввірували в Нього там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 1, 'Був же хворий один, Ла́зар у Віфа́нії, із села Марії й сестри її Марти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 2, 'А Марія, що брат її Лазар був хворий, була та, що помазала Господа миром, і воло́ссям своїм Йому но́ги обте́рла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 3, 'Тоді се́стри послали до Нього, говорячи: „Ось незду́жає, Господи, той, що любиш його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 4, 'Як почув же Ісус, то промовив: „Не на смерть ця недуга, а на Божу славу, — щоб Син Божий прославився нею“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 5, 'А Ісус любив Марту, і сестру її, і Лазаря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 6, 'А коли Він почув, що нездужає той, то зостався два дні на тім місці, де був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 7, 'Після ж того говорить до учнів: „Ходімо зно́ву в Юдею“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 8, 'Йому учні сказали: „Учителю, таж допі́ру юдеї хотіли камінням побити Тебе, а Ти знов туди пі́деш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 9, 'Ісус відповів: „Хіба дня не дванадцять годин? Як хто ходить за дня, не спіткне́ться, — цьогосвітнє бо світло він бачить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 10, 'А хто ходить нічно́ї пори, той спіткнеться, — бо немає в нім світла“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 11, 'Оце Він сказав, а по то́му говорить до них: „Друг наш Лазар заснув, — та піду́ розбудити Його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 12, 'А учні сказали Йому: „Як заснув, то він, Господи, ви́дужає“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 13, 'Та про смерть його мовив Ісус, вони ж ду́мали, що про сонний спочи́нок Він каже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 14, 'Тоді просто сказав їм Ісус: „Умер Лазар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 15, 'І Я тішусь за вас, що там Я не був, щоб повірили ви. Та ходімо до нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 16, 'Сказав же Хома, називаний Близню́к, до співучнів: „Ходімо й ми, щоб із Ним повмирати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 17, 'Як прибув же Ісус, то знайшов, що чотири вже дні той у гро́бі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 18, 'А Віфа́нія поблизу Єрусалиму була́, яких стадій з п\'ятнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 19, 'І багато з юдеїв до Марти й Марії прийшли, щоб за брата розва́жити їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 20, 'Тоді Марта, почувши, що надхо́дить Ісус, побігла зустріти Його, Марія ж удома сиділа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 21, 'І Марта сказала Ісусові: „Коли б, Господи, був Ти отут, — то не вмер би мій брат.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 22, 'Та й тепер, — знаю я, — що чого тільки в Бога попросиш, то дасть Тобі Бог!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 23, 'Промовляє до неї Ісус: „Воскресне твій брат!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 24, 'Відказує Марта Йому: „Знаю, що в воскресіння останнього дня він воскресне“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 25, 'Промовив до неї Ісус: „Я воскресіння й життя. Хто вірує в мене, — хоч і вмре, буде жити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 26, 'І кожен, хто живе та хто вірує в Мене, — повіки не вмре. Чи ти віруєш в це?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 27, 'Вона каже Йому: „Так, Господи! Я вірую, що Ти Христос, Син Божий, що має прийти на цей світ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 28, 'І промовивши це, відійшла, та й покликала нишком Марі́ю, сестру свою, ка́жучи: „Учитель тут, і Він кличе тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 29, 'А та, як зачула, квапли́во встала й до Нього пішла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 30, 'А Ісус не ввійшов був іще до села, а знахо́дивсь на місці, де Марта зустріла Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 31, 'Юдеї тоді, що були з нею в домі й її розважали, як побачили, що Марія квапли́во встала й побігла, подали́ся за нею, гадаючи, що до гро́бу пішла вона, — плакати там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 32, 'Як Марія ж прийшла туди, де був Ісус, і Його вгледіла, то припала до ніг Йому та й говорила до Нього: „Коли б, Господи, був Ти отут, то не вмер би мій брат!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 33, 'А Ісус, як побачив, що плаче вона, і плачуть юдеї, що з нею прийшли, то в дусі розжа́лобився та й звору́шився Сам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 34, 'і сказав: „Де його ви поклали?“Говорять Йому́: „Іди, Господи, та подивися!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 35, 'I заплакав Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 36, 'А юдеї казали: „Дивись, як любив Він його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 37, 'А з них дехто сказали: „Чи не міг же зробити Отой, Хто очі сліпому відкрив, щоб і цей не помер?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 38, 'Ісус же розжа́лобивсь знову в Собі, і до гро́бу прийшов. Була ж то печера, і камінь на ній наляга́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 39, 'Промовляє Ісус: „Відваліть цього каменя!“Сестра вмерлого Марта говорить до Нього: „Уже, Господи, чути, — бо чотири вже дні він у гро́бі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 40, 'Ісус каже до неї: „Чи тобі не казав Я, що як бу́деш ти вірувати, — славу Божу побачиш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 41, 'І зняли́ тоді каменя. А Ісус ізвів очі до неба й промовив: „Отче, дяку прино́шу Тобі, що Мене Ти почув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 42, 'Та Я знаю, що Ти за́вжди почуєш Мене, але ради наро́ду, що довкола стоїть, Я сказав, щоб увірували, що послав Ти Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 43, 'І, промовивши це, Він скричав гучни́м голосом: „Ла́зарю, — вийди сюди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 44, 'І вийшов померлий, по рука́х і нога́х обв\'я́заний па́сами, а обличчя у нього було́ перев\'я́зане хусткою. Ісус каже до них: „Розв\'яжіть його та й пустіть, щоб ходив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 45, 'І багато з юдеїв, що посхо́дилися до Марії, та бачили те, що Він учинив, у Нього ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 46, 'А деякі з них пішли до фарисеїв, і їм розповіли, що́ Ісус учинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 47, 'Тоді первосвященики та фарисеї скли́кали раду й казали: „Що́ маємо робити, бо Цей Чоловік пребагато чуд чинить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 48, 'Якщо так позоставимо Його, то всі в Нього ввірують, — і при́йдуть римля́ни, та й ві́зьмуть нам і край, і наро́д!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 49, 'А один із них, Кайя́фа, що був первосвящеником року того́, промовив до них: „Ви нічо́го не знаєте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 50, 'і не поміркуєте, що краще для вас, щоб один чоловік прийняв смерть за людей, аніж щоб увесь наро́д мав загинути!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 51, 'А того не сказав сам від себе, але, первосвящеником бувши в тім році, пророкував, що Ісус за наро́д мав умерти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 52, 'і не лише за наро́д, але й щоб сполучити в одне́ розпоро́шених Божих дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 53, 'Отож, від того дня вони змо́вилися, щоб убити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 54, 'І тому́ не ходив більш Ісус між юдеями явно, але звідти вдавсь до околиць поближче пустині, до міста, що зветься Єфре́м, — і тут залишався з Своїми учнями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 55, 'Наближалася ж Пасха юдейська, і багато-хто з кра́ю вдались перед Пасхою в Єрусалим, щоб очи́стити себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 56, 'І шукали Ісуса вони, а в храмі стоявши, гомоніли один до одно́го: „А як вам здається? Хіба Він не при́йде на свято?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 57, 'А первосвященики та фарисеї нака́за дали́: як дізнається хто, де Він перебува́тиме, нехай донесе, — щоб схопи́ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 1, 'Ісус же за шість день до Пасхи прибув до Віфа́нії, де жив Лазар, що його воскресив Ісус із мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 2, 'І для Нього вече́рю там спра́вили, а Марта прислуго́вувала. Був же й Лазар одним із тих, що до столу з Ним сіли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 3, 'А Марія взяла літру мира, — з найдоро́жчого на́рду паху́чого, і намасти́ла Ісусові но́ги, і воло́ссям своїм Йому но́ги обтерла. І пахощі мира наповнили дім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 4, 'І говорить один з Його учнів, Юда Іскаріо́тський, що мав Його видати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 5, '„Чому мира оцього за триста дина́рів не про́дано, та й не ро́здано вбогим?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 6, 'А це він сказав не тому́, що про вбогих журився, а тому́, що був зло́дій: він мав скриньку на гроші, — і крав те, що вкида́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 7, 'І промовив Ісус: „Позостав її ти, — це вона на день по́хорону заховала Мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 8, 'Бо вбогих ви маєте за́вжди з собою, а Мене не постійно ви маєте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 9, 'А на́товп великий юдеїв довідався, що Він там, та й поприхо́дили не з-за Ісуса Само́го, але щоб побачити й Лазаря, що його воскресив Він із мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 10, 'А первосвященики змо́вилися, щоб і Лазареві смерть заподіяти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 11, 'бо багато з юдеїв з-за нього відхо́дили, та в Ісуса ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 12, 'А другого дня, коли бе́зліч наро́ду, що зібрався на свято, прочула, що до Єрусалиму надходить Ісус,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 13, 'то взяли́ вони па́льмове ві́ття, і вийшли назу́стріч Йому та й кричали: „Оса́нна! Благослове́нний, хто йде у Господнє Ім\'я́! Цар Ізраїлів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 14, 'Ісус же, знайшовши осля, сів на нього, як написано:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 15, '„Не бійся, до́чко Сіонська! Ото Цар твій іде, сидячи́ на ослі молодому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 16, 'А учні Його спочатку́ того не зрозуміли були́, але, як прославивсь Ісус, то згадали тоді, що про Нього було так написано, і що цеє вчинили Йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 17, 'Тоді свідчив наро́д, який був із Ним, що Він викликав Лазаря з гро́бу, і воскресив його з мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 18, 'Через це й зустрів на́товп Його, бо почув, що Він учинив таке чудо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 19, 'Фарисеї тоді між собою казали: „Ви бачите, що нічо́го не вдієте: ось пішов увесь світ услід за Ним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 20, 'А між тими, що в свято прийшли поклонитись, були й деякі ге́ллени.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 21, 'І вони підійшли до Пилипа, що з Віфсаї́ди Галілейської, і просили його та казали: „Ми хочемо, пане, побачити Ісуса“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 22, 'Іде Пилип та Андрієві каже; іде Андрій і Пилип та Ісусові розповідають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 23, 'Ісус же їм відповідає, говорячи: „Надійшла́ година, щоб Син Лю́дський просла́вивсь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 24, 'Поправді, поправді кажу́ вам: коли зе́рно пшеничне, як у землю впаде́, не помре, то одне зостається; як умре ж, плід рясни́й принесе́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 25, 'Хто кохає душу свою, той погубить її; хто ж нена́видить душу свою на цім світі, — збереже її в вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 26, 'Як хто служить Мені, хай іде той за Мною, і де Я, там буде й слуга Мій. Як хто служить Мені, того пошану́є Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 27, 'Затривожена зараз душа Моя. І що Я пові́м? Заступи Мене, Отче, від цієї години! Та на те Я й прийшов на годину оцю́...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 28, 'Прослав, Отче, Ім\'я́ Своє!“Залуна́в тоді голос із неба: „І прославив, — і зно́ву прославлю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 29, 'А наро́д, що стояв і почув, говорив: „Загреміло\"! Інші казали: „ Це ангол Йому говорив“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 30, 'Ісус відповів і сказав: „Не для Мене цей голос луна́в, а для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 31, 'Тепер суд цьому світові. Князь світу цього буде ви́гнаний звідси тепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 32, 'І, як буду підне́сений з землі, то до Себе Я всіх притягну́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 33, 'А Він це говорив, щоб зазна́чити, якою то смертю Він має померти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 34, 'А наро́д відповів Йому́: „Ми чули з Зако́ну, що Христос перебуває повік, то чого ж Ти говориш, що Лю́дському Сину потрібно підне́сеному бути? Хто такий Цей Син Лю́дський?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 35, 'І сказав їм Ісус: „Короткий ще час світло з вами. Ходіть, поки маєте світло, щоб вас те́мрява не обгорну́ла. А хто в те́мряві ходить, не знає, куди він іде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 36, 'Аж доки ви маєте світло, то віруйте в світло, щоб синами світла ви стали“. Промовивши це, Ісус відійшов, і схова́вся від них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 37, 'І хоч Він стільки чуд перед ними вчинив був, та в Нього вони не ввірували,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 38, 'щоб спра́вдилось слово пророка Ісаї, який провіща́в: „Хто повірив тому́, що ми, Господи, чули, а Господнє раме́но кому́ об\'яви́лось?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 39, 'Тому́ не могли вони вірити, що зно́ву Ісая прорік:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 40, '„Засліпив їхні очі, і скам\'янив їхнє серце, щоб очима не бачили, ані серцем щоб не зрозуміли, і не наверну́лись, щоб Я їх уздоро́вив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 41, 'Це Ісая сказав, коли бачив славу Його, і про Нього звіща́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 42, 'Проте́ багато-хто навіть із старших у Нього ввірували, та не признавались через фарисеїв, — щоб не вигнано їх із синагоги.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 43, 'Бо любили вони славу людську більше, аніж славу Божу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 44, 'А Ісус підняв голос, та й промовляв: „Хто вірує в Мене, не в Мене він вірує, але в Того, Хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 45, 'А хто бачить Мене, той бачить Того, хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 46, 'Я, Світло, на світ прийшов, щоб кожен, хто вірує в Мене, у те́мряві не зоставався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 47, 'Коли б же хто слів Моїх слухав та не вірував, Я того не суджу́, бо Я не прийшов світ судити, але щоб спасти світ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 48, 'Хто цурається Мене, і Моїх слів не приймає, той має для себе суддю́: те слово, що Я говорив, — останнього дня воно бу́де судити його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 49, 'Бо від Себе Я не говорив, а Отець, що послав Мене, — то Він Мені заповідь дав, що́ Я маю казати та що́ говорити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 50, 'І відаю Я, що Його ота заповідь — то вічне життя. Тож що́ Я говорю́, то так говорю́, як Отець Мені розповіда́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 1, 'Перед святом же Пасхи Ісус, знавши, що настала годи́на Йому́ перейти до Отця з цього світу, полюбивши Своїх, що на світі були́, до кінця полюбив їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 2, 'Під час же вече́рі, як диявол уже був укинув у серце синові Си́мона — Юді Іскаріотському, щоб він видав Його́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 3, 'то Ісус, знавши те, що Отець віддав все Йому в руки, і що від Бога прийшов Він, і до Бога відходить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 4, 'устає від вечері, і здіймає одежу, бере рушника́ й підпері́зується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 5, 'Пото́му налив Він води до вмива́льниці, та й зачав обмивати ноги учням, і витирати рушнико́м, що ним був підпере́заний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 6, 'І підходить до Си́мона Петра, а той каже Йому: „Ти, Господи, ми́тимеш но́ги мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 7, 'Ісус відказав і промовив йому: „Що́ Я роблю́, ти не знаєш тепер, але опісля́ зрозумієш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 8, 'Говорить до Нього Петро: „Ти повік мені ніг не обмиєш!“Ісус відповів йому: „Коли́ Я не вмию тебе, — ти не матимеш частки зо Мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 9, 'До Нього проказує Си́мон Петро: „Господи, — не самі мої но́ги, а й руки та го́лову!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 10, 'Ісус каже йому: „Хто обмитий, тільки но́ги обмити потребу́є, бо він чистий увесь. І ви чисті, — та не всі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 11, 'Бо Він знав Свого зра́дника, тому то сказав: „Ви чисті не всі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 12, 'Коли ж пообмива́в їхні но́ги, і одежу Свою Він надів, засів зно́ву за стіл і промовив до них: „Чи знаєте ви, що́ Я зробив вам?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 13, 'Ви Мене називаєте: Учитель і Госпо́дь, — і добре ви кажете, бо Я є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 14, 'А коли обмив ноги вам Я, Госпо́дь і Вчитель, то повинні й ви один о́дному ноги вмивати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 15, 'Бо то Я вам при́клада дав, щоб і ви те чинили, як Я вам учинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 16, 'Поправді, поправді кажу́ вам: Раб не більший за пана свого́, послане́ць же не більший від того, хто вислав його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 17, 'Коли знаєте це, то блаженні ви, якщо таке чините!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 18, 'Не про всіх вас кажу́. Знаю Я, кого вибрав, але щоб збуло́ся Писа́ння: „Хто хліб споживає зо Мною, підняв той на Мене п\'яту́ свою!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 19, 'Уже тепер вам кажу́, перше ніж те настане, щоб як станеться, ви ввірували, що то Я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 20, 'Поправді, поправді кажу́ вам: Хто приймає Мого посланця́, той приймає Мене; хто ж приймає Мене, той приймає Того, Хто послав Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 21, 'Промовивши це, затривожився духом Ісус, і осві́дчив, говорячи: „Поправді, поправді кажу́ вам, що один із вас видасть Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 22, 'І озиралися учні один на одно́го, непевними бувши, про кого Він каже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 23, 'При столі, при Ісусовім лоні, був один з Його учнів, якого любив Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 24, 'От цьому кивну́в Си́мон Петро та й шепну́в: „Запитай, — хто б то був, що про нього Він каже?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 25, 'І, пригорну́вшись до ло́ня Ісусового, той говорить до Нього: „Хто́ це, Господи?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 26, 'Ісус же відказує: „Це той, кому, умочивши, подам Я куска́“. І, вмочивши куска́, подав синові Си́мона, — Юді Іскаріо́тському!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 27, 'За тим же куско́м тоді в нього ввійшов сатана́. А Ісус йому каже: „Що́ ти робиш — роби швидше“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 28, 'Але жоден із тих, хто був при столі, того не зрозумів, до чо́го сказав Він йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 29, 'А тому́, що тримав Юда скриньку на гроші, то деякі ду́мали, ніби каже до нього Ісус: „Купи, що потрібно на свято для нас“, або щоб убогим подав що.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 30, 'А той, узявши кусок хліба, зараз вийшов. Була ж ніч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 31, 'Тоді, як він вийшов, промовляє Ісус: „Тепер ось просла́вивсь Син Лю́дський, і в Ньому просла́вився Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 32, 'Коли в Ньому прославився Бог, то і Його Бог просла́вить у Собі, і зараз прославить Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 33, 'Мої дітоньки, не довго вже бути Мені з вами! Ви шукати Мене будете, але́ — як сказав Я юдеям: „Куди Я йду, туди ви прибути не можете“, — те й вам говорю́ Я тепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 34, 'Нову́ заповідь Я вам даю: Любіть один о́дного! Як Я вас полюбив, так любіть один о́дного й ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 35, 'По то́му пізнають усі, що ви учні Мої, як бу́дете мати любов між собою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 36, 'А Симон Петро Йому каже: „Куди, Господи, ідеш Ти?“Ісус відповів: „Куди Я йду, туди ти́ тепер іти за Мною не можеш, але по́тім ти підеш за Мною“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 37, 'Говорить до Нього Петро: „Чому, Господи, іти за Тобою тепер я не мо́жу? За Те́бе я душу свою́ покладу́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 38, 'Ісус відповідає: За Ме́не покладе́ш ти душу свою́? Поправді, поправді кажу́ Я тобі: Півень не заспіває, як ти тричі зречешся Мене́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 1, 'Неха́й серце вам не тривожиться! Віруйте в Бога, і в Мене віруйте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 2, 'Багато осе́ль у домі Мого Отця; а коли б то не так, то сказав би Я вам, що йду приготува́ти місце для вас?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 3, 'А коли́ відійду́ й приготу́ю вам місце, Я зно́ву прийду́ й заберу́ вас до Себе, щоб де Я — були й ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 4, 'А куди Я йду — дорогу ви знаєте“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 5, 'Говорить до Нього Хома́: „Ми не знаємо, Господи, куди йдеш; як же можемо знати дорогу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 6, 'Промовляє до нього Ісус: „Я — дорога, і правда, і життя. До Отця не приходить ніхто, якщо не через Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 7, 'Коли б то були ви пізна́ли Мене, ви пізнали були б і Мого Отця. Відтепе́р Його знаєте ви, і Його бачили“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 8, 'Говорить до Нього Пилип: „Господи, покажи нам Отця, — і ви́стачить нам“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 9, 'Промовляє до нього Ісус: „Стільки ча́су Я з вами, ти ж не знаєш, Пилипе, Мене? Хто бачив Мене, той бачив Отця, то як же ти кажеш: „Покажи нам Отця?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 10, 'Чи не віруєш ти, що Я — в Отці, а Отець — у Мені? Слова́, що Я вам говорю́, говорю не від Се́бе, а Отець, що в Мені перебуває, Той чинить діла ті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 11, 'Повірте Мені, що Я — в Отці, а Отець — у Мені! Коли ж ні, то повірте за вчинки самі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 12, 'Поправді, поправді кажу́ вам: Хто вірує в Мене, той учинить діла, які чиню Я, і ще більші від них він учи́нить, бо Я йду до Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 13, 'І коли що просити ви бу́дете в Іме́ння Моє, те вчиню́, щоб у Сині прославивсь Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 14, 'Коли бу́дете в Мене просити чого в Моє Йме́ння, то вчиню́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 15, 'Якщо Ви Мене любите, — Мої заповіді зберігайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 16, 'І вблагаю Отця Я, — і Втіши́теля іншого дасть вам, щоб із вами повік перебува́в, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 17, 'Духа правди, що Його світ прийняти не може, бо не бачить Його та не знає Його. Його знаєте ви, бо при вас перебува́є, і в вас буде Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 18, 'Я не кину вас си́ротами, — Я прибу́ду до вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 19, 'Ще недовго, і вже світ Мене не побачить, але ви́ Мене бачити бу́дете, бо живу Я — і ви жити бу́дете!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 20, 'Того дня пізна́єте ви, що в Своїм Я Отці, а ви в Мені, і Я в вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 21, 'Хто заповіді Мої має та їх зберігає, той любить Мене. А хто любить Мене, то полюбить його Мій Отець, і Я полюблю́ Його, і об\'явлюсь йому Сам“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 22, 'Запитує Юда, не Іскаріотський, Його: „Що то, Господи, що Ти нам об\'явитися маєш, а не світові?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 23, 'Ісус відповів і до нього сказав: „Як хто любить Мене, той слово Моє берегти́ме, і Отець Мій полюбить його, і Ми при́йдемо до нього, і оселю закладе́мо в нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 24, 'Хто не любить Мене, той не береже́ Моїх слів. А слово, що чуєте ви, не Моє, а Отця, що послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 25, 'Говорив це Я вам, бувши з вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 26, 'Утіши́тель же, Дух Святий, що Його Отець пошле в Ім\'я́ Моє, Той навчить вас усього, і пригадає вам усе, що Я вам говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 27, 'Зоставляю вам мир, мир Свій вам даю! Я даю вам не так, як дає світ. Серце ваше нехай не триво́житься, ані не лякається!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 28, 'Чули ви, що Я вам говори́в: „Я відхо́джу, і вернуся до вас“. Якби́ ви любили Мене, то ви б ті́шилися, що Я йду до Отця, — бо більший за Мене Отець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 29, 'І тепер Я сказав вам, передніше, ніж сталося, щоб ви вірували, коли станеться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 30, 'Небагато вже Я говори́тиму з вами, бо надхо́дить князь світу цього, а в Мені він нічого не має,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 31, 'та щоб світ зрозумів, що люблю́ Я Отця, і як Отець наказав Мені, так роблю́. Уставайте, — ходім звідсіля́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 1, 'Я правдива Виногра́дина, а Отець Мій — Виногра́дар.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 2, 'Усяку галу́зку в Мене, що плоду не прино́сить, Він відтина́є, але всяку, що плід родить, обчища́є її, щоб рясніше родила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 3, 'Через Слово, що Я вам говорив, ви вже чисті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 4, 'Перебува́йте в Мені, а Я в вас! Як та вітка не може вродити плоду сама з себе, коли не позоста́неться на виногра́дині, так і ви, як в Мені перебува́ти не будете.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 5, 'Я — Виноградина, ви — галу́ззя! Хто в Мені перебува́є, а Я в ньому, той рясно заро́джує, бо без Мене нічого чинити не можете ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 6, 'Коли хто перебува́ти не буде в Мені, той буде відкинений геть, як галу́зка, і всохне. І грома́дять їх, і кладуть на огонь, — і згорять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 7, 'Коли ж у Мені перебува́ти ви будете, а слова́ Мої позоста́нуться в вас, то просіть, чого хочете, — і станеться вам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 8, 'Отець Мій просла́виться в то́му, якщо рясно заро́дите й бу́дете учні Мої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 9, 'Як Отець полюбив Мене, так і Я полюбив вас. Перебувайте в любові Моїй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 10, 'Якщо бу́дете ви зберігати Мої заповіді, то в любові Моїй перебува́тимете, як і Я зберіг Заповіді Свого Отця, і перебуваю в любові Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 11, 'Це Я вам говорив, щоб радість Моя була в вас, і щоб повна була́ ваша радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 12, 'Оце Моя заповідь, — щоб любили один о́дного ви, як Я вас полюбив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 13, 'Ніхто більшої любови не має над ту, як хто свою душу поклав би за дру́зів своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 14, 'Ви дру́зі Мої, якщо чините все, що Я вам заповідую.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 15, 'Я вже більше не бу́ду раба́ми вас звати, бо не відає раб, що пан його чинить. А вас назвав дру́зями Я, бо Я вам об\'явив усе те, що почув від Мого Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 16, 'Не ви Мене вибрали, але Я вибрав вас, і вас настанови́в, щоб ішли ви й прино́сили плід, і щоб плід ваш зостався, щоб дав вам Отець, чого тільки попро́сите в Імення Моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 17, 'Це Я вам заповідую, — щоб любили один о́дного ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 18, 'Коли вас світ нена́видить, знайте, що Мене він знена́видів перше, як вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 19, 'Коли б ви зо світу були́, то своє світ любив би. А що ви не зо світу, але Я вас зо світу обрав, тому світ вас нена́видить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 20, 'Пригадайте те слово, яке Я вам сказав: „Раб не більший за пана свого“. Як Мене переслі́дували, — то й вас переслідувати бу́дуть; як слово Моє зберігали, — берегти́муть і ваше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 21, 'Але все це робитимуть вам за Ім\'я́ Моє, бо не знають Того, хто послав Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 22, 'Коли б Я не прийшов і до них не казав, то не мали б гріха́, а тепер вимо́вки не мають вони за свій гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 23, 'Хто Мене нена́видить, — і Мого Отця той нена́видить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 24, 'Коли б Я серед них не вчинив був тих діл, яких не чинив ніхто інший, то не мали б гріха́. Та тепер вони бачили, — і знена́виділи і Мене, і Мого Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 25, 'Та щоб спра́вдилось слово, що в їхнім Зако́ні написане: „Мене безпідставно знена́виділи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 26, 'А коли Втіши́тель прибуде, що Його від Отця Я пошлю вам, — Той Дух правди, що походить від Отця, Він засвідчить про Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 27, 'Та засві́дчте і ви, бо ви від початку зо Мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 1, 'Оце Я сказав вам, щоб ви не спокуси́лись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 2, 'Вас виженуть із синагог. Прийде навіть година, коли кожен, хто вам смерть заподі́є, то ду́матиме, ніби службу приносить він Богові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 3, 'А це́ вам учинять, бо вони не пізнали Отця, ні Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 4, 'Але Я це сказав вам, щоб згадали про те, про що́ говорив був Я вам, як настане година. Цього вам не казав Я споча́тку, бо з вами Я був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 5, 'Тепер же до Того Я йду, Хто послав Мене, — і ніхто з вас Мене не питає: „Куди йдеш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 6, 'Та від того, що це Я сказав вам, серце ваше напо́внилось смутком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 7, 'Та Я правду кажу́ вам: Краще для вас, щоб пішов Я, бо як Я не піду́, Утіши́тель не при́йде до вас. А коли Я піду́, то пошлю вам Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 8, 'А як при́йде, Він світові виявить про гріх, і про праведність і про суд:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 9, 'тож про гріх, — що не вірують у Мене;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 10, 'а про праведність, — що Я до Отця Свого йду, і Мене не побачите вже;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 11, 'а про суд, — що засу́джений князь цього світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 12, 'Я ще маю багато сказати вам, та тепер ви не можете знести.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 13, 'А коли при́йде Він, Той Дух правди, Він вас попрова́дить до ці́лої правди, бо не буде казати Сам від Себе, а що тільки почує, — казатиме, і що має настати, — звістить вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 14, 'Він прославить Мене, бо Він ві́зьме з Мого та й вам сповісти́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 15, 'Усе, що має Отець, то Моє; через те Я й сказав, що Він ві́зьме з Мого та й вам сповісти́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 16, 'Незаба́ром, — і Мене вже не бу́дете бачити, і знов незабаром — і Мене ви побачите, бо Я йду до Отця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 17, 'А деякі з учнів Його говорили один до одно́го: „Що таке, що сказав Він до нас: „Незабаром, — і Мене вже не бу́дете бачити, і знов незаба́ром — і Мене ви побачите“, та: „Я йду до Отця“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 18, 'Гомоніли також: „Що таке, що говорить: „Незаба́ром“? Про що каже, не знаємо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 19, 'Ісус же пізнав, що хочуть поспитати Його, і сказав їм: „Чи про це між собою міркуєте ви, що сказав Я: „Незаба́ром, — і вже Мене бачити не будете ви, і знов незаба́ром — і Мене ви побачите“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 20, 'Поправді, поправді кажу́ вам, що ви бу́дете плакати та голосити, а світ буде радіти. Сумувати ви бу́дете, але сум ваш обе́рнеться в радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 21, 'Жу́риться жінка, що ро́дить, — бо настала година її. Як дитинку ж поро́дить вона, то вже не пам\'ятає терпіння з-за ра́дощів, що людина зроди́лась на світ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 22, 'Так сумуєте й ви ось тепер, та побачу вас зно́ву, — і серце ваше радітиме, і ніхто радости вашої вам не віді́йме!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 23, 'Ні про що ж того дня ви Мене не спитаєте. Поправді, поправді кажу́ вам: Чого тільки попросите ви від Отця в Моє Йме́ння, — Він дасть вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 24, 'Не просили ви досі нічо́го в Ім\'я́ Моє. Просіть — і отримаєте, щоб повна була ваша радість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 25, 'Оце все Я в при́тчах до вас говорив. Настає́ година, коли при́тчами Я вже не бу́ду до вас промовляти, але явно звіщу́ про Отця вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 26, 'Того дня ви проси́тимете в Моє Ймення, і Я вам не кажу́, що вблагаю Отця Я за вас, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 27, 'бо Отець любить Сам вас за те, що ви полюбили Мене та й увірували, що Я вийшов від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 28, 'Від Отця вийшов Я, і на світ Я прийшов. І знов покидаю Я світ та й іду до Отця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 29, 'Його учні відказують: „Ось тепер Ти говориш відкрито, і жодної притчі не кажеш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 30, 'Тепер ві́даємо ми, що Ти знаєш усе, і потреби не маєш, щоб Тебе хто питав. Тому віруємо, що Ти вийшов від Бога!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 31, 'Ісус їм відповів: „Тепер віруєте?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 32, 'Ото настає́ година, і вже настала, що ви розпоро́шитесь кожен у власне своє, а Мене ви Само́го покинете. Та не Сам Я, бо зо Мною Отець!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 33, 'Це Я вам розповів, щоб мали ви мир у Мені. Стражда́ння зазна́єте в світі, — але бу́дьте відважні: Я світ переміг!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 1, 'По мові оцій Ісус очі Свої звів до неба й промовив: „Прийшла, Отче, година, — прослав Сина Свого, щоб і Син Твій прославив Тебе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 2, 'бо Ти дав Йому вла́ду над тілом усяким, щоб Він дав життя вічне всім їм, яких дав Ти Йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 3, 'Життя ж вічне — це те, щоб пізнали Тебе, єдиного Бога правдивого, та Ісуса Христа, що послав Ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 4, 'Я прославив Тебе на землі, — доверши́в Я те ді́ло, що Ти дав Мені ви́конати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 5, 'І тепер прослав, Отче, Мене Сам у Себе тією славою, яку в Тебе Я мав, поки світ не постав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 6, 'Я Ім\'я́ Твоє виявив лю́дям, що Мені Ти із світу їх дав. Твоїми були вони, і Ти дав їх Мені, і вони зберегли́ Твоє слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 7, 'Тепер пізнали вони, що все те, що Ти Мені дав, від Тебе похо́дить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 8, 'бо слова́, що дав Ти Мені, Я їм передав, — і вони прийняли й зрозуміли правдиво, що Я вийшов від Тебе, і ввірували, що послав Ти Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 9, 'Я благаю за них. Не за світ Я благаю, а за тих, кого дав Ти Мені, — Твої бо вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 10, 'Усе бо Моє — то Твоє, а Твоє — то Моє, і просла́вивсь Я в них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 11, 'І не на світі вже Я, а вони ще на світі, а Я йду до Тебе. Святий Отче, — заховай в Ім\'я́ Своє їх, яких дав Ти Мені, щоб як Ми, єдине були!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 12, 'Коли з ними на світі Я був, Я беріг їх у Йме́ння Твоє, тих, що дав Ти Мені, і зберіг, і ніхто з них не згинув, крім призна́ченого на загибіль, щоб збуло́ся Писа́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 13, 'Тепер же до Тебе Я йду, але це говорю́ Я на світі, щоб мали вони в собі радість Мою доскона́лу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 14, 'Я їм дав Твоє слово, але світ їх знена́видів, бо вони не від світу, як і Я не від світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 15, 'Не благаю, щоб Ти їх зо світу забрав, але щоб зберіг їх від злого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 16, 'Не від світу вони, як і Я не від світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 17, 'Освяти Ти їх правдою! Твоє слово — то правда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 18, 'Як на світ Ти послав Мене, так і Я на світ послав їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 19, 'А за них Я посвячую в жертву Само́го Себе, щоб освячені правдою стали й вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 20, 'Та не тільки за них Я благаю, а й за тих, що ради їхнього сло́ва ввірують у Мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 21, 'щоб були всі одно: як Ти, Отче, в Мені, а Я — у Тобі, щоб одно́ були в Нас і вони, — щоб увірував світ, що Мене Ти послав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 22, 'А ту славу, що дав Ти Мені, Я їм передав, щоб єдине були, як єдине і Ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 23, 'Я — у них, а Ти — у Мені, щоб були́ досконалі в одно, і щоб пізнав світ, що послав Мене Ти, і що їх полюбив Ти, як Мене полюбив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 24, 'Бажаю Я, Отче, щоб і ті, кого дав Ти Мені, там зо Мною були́, де знахо́джуся Я, щоб бачили славу Мою, яку дав Ти Мені, — бо Ти полюбив Мене перше закла́дин світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 25, 'Отче Праведний! Хоча́ не пізнав Тебе світ, та пізнав Тебе Я. І пізнали вони, що послав Мене Ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 26, 'Я ж Ім\'я Твоє́ їм об\'явив й об\'явля́тиму, щоб любов, що Ти нею Мене полюбив, була́ в них, а Я в них!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 1, 'Промовивши це, Ісус вийшов із учнями Своїми на то́й бік потоку Кедро́ну, де був сад, до якого ввійшов Він та учні Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 2, 'Але й Юда, що видав Його, знав те місце, бо там часто збирались Ісус й Його учні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 3, 'Отож Юда, узявши відділ ві́йська та службу від первосвящеників і фарисеїв, приходить туди із смолоски́пами, та з ліхтарями, та з зброєю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 4, 'А Ісус, усе ві́давши, що́ з Ним статися має, виходить та й каже до них: „Кого́ ви шукаєте?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 5, 'Йому відповіли: „Ісуса Назаряни́на“. Він говорить до них: „Це Я“! А стояв із ними й Юда, що видав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 6, 'I як тільки сказав їм: „Це Я“, вони подали́ся назад, та й на землю попа́дали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 7, 'І Він знов запитав їх: „Кого́ ви шукаєте?“Вони ж відказали: „Ісуса Назаряни́на“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 8, 'Ісус відповів: „Я сказав вам, що це Я. Отож, як Мене ви шукаєте, то дайте оцим відійти “, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 9, 'щоб збулося те слово, що Він був сказав: „Я не втратив ніко́го із тих, кого дав Ти Мені“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 10, 'Тоді Си́мон Петро, меча мавши, його ви́хопив, і рубону́в раба́ первосвященика, — і відтя́в праве́ вухо йому́. А рабу́ на ім\'я́ було Малх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 11, 'Та промовив Ісус до Петра: Всунь у пі́хви меча! Чи ж не мав би Я пити ту чашу, що Отець дав Мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 12, 'Відділ же війська та тисяцький і служба юдейська схопи́ли Ісуса, і зв\'язали Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 13, 'і повели Його перше до Анни, бо тестем доводивсь Кайяфі, що первосвящеником був того року.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 14, 'Це ж був той Кайя́фа, що порадив юдеям, що ліпше померти люди́ні одній за наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 15, 'А Симон Петро й інший учень ішли за Ісусом слідо́м. Той же учень відо́мий був первосвященикові, і ввійшов у двір первосвящеників із Ісусом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 16, 'А Петро за ворітьми стояв. Тоді вийшов той учень, що відо́мий був первосвященикові, і сказав ворота́рці, — і впровадив Петра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 17, 'І питає Петра ворота́рка служни́ця: „Ти хіба не з учнів Цього Чоловіка?“Той відказує: „Ні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 18, 'А раби й служба, розклавши огонь, стояли та й грілися, бо був холод. І Петро стояв із ними та грівся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 19, 'А первосвященик спитався Ісуса про учнів Його, і про науку Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 20, 'Ісус Йому відповідь дав: „Я світові явно казав. Я постійно навчав у синагозі й у храмі, куди всі юдеї збираються, а таємно нічо́го Я не говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 21, 'Чого ти питаєш Мене? Поспитайся тих, що чули, що́ Я їм говорив. Отже, знають вони, про що Я говорив“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 22, 'А як Він це сказав, то один із присутньої там служби вдарив Ісуса в щоку́, говорячи: „То так відповідаєш первосвященикові?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 23, 'Ісус йому відповідь дав: „Якщо зле Я сказав, — покажи, що то зле; коли ж добре, — за що́ Мене б\'єш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 24, 'І відіслав Його Анна зв\'язаним первосвященикові Кайяфі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 25, 'А Си́мон Петро стояв, гріючись. І сказали до нього: „Чи й ти не з учнів Його?“Він відрікся й сказав: „Ні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 26, 'Говорить один із рабів первосвященика, родич тому́, що йому Петро вухо відтя́в: „Чи тебе я не бачив у саду́ з Ним?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 27, 'І зно́ву відрікся Петро, — і заспівав півень хвилі тієї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 28, 'А Ісуса ведуть від Кайяфи в прето́рій. Був же ра́нок. Та вони не ввійшли до прето́рія, щоб не опога́нитись, а щоб їсти пасху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 29, 'Тоді вийшов Пилат назо́вні до них і сказав: „Яку ска́ргу приносите ви на Цього Чоловіка?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 30, 'Вони відповіли та й сказали йому: „Коли́ б Цей злочи́нцем не був, ми б Його тобі не видавали“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 31, 'А Пилат їм сказав: „Візьміть Його, та й за вашим Зако́ном судіть Його“. Юдеї сказали йому: „Нам не вільно нікого вбивати“, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 32, 'щоб збулося Ісусове слово, що його Він прорік, зазначаючи, якою то смертю Він має померти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 33, 'Тоді зно́ву Пилат увійшов у прето́рій, і покликав Ісуса, і до Нього сказав: „Чи Ти Цар Юдейський?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 34, 'Ісус відповів: „Чи від себе самого питаєш ти це, чи то інші тобі говорили про Мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 35, 'Пилат відповів: „Чи ж юде́янин я? Твій наро́д та первосвященики мені Тебе видали. Що таке Ти вчинив?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 36, 'Ісус відповів: „Моє Царство не із світу цього́. Якби із цього світу було́ Моє Царство, то служба Моя́ воювала б, щоб не ви́даний був Я юдеям. Та тепер Моє Царство не звідси“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 37, 'Сказав же до Нього Пила́т: „Так Ти Цар?“Ісус відповів: „Сам ти кажеш, що Цар Я. Я на те народився, і на те прийшов у світ, щоб засві́дчити правду. І кожен, хто з правди, той чує Мій голос“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 38, 'Говорить до Нього Пила́т: „Що є правда?“І сказавши оце, до юдеїв знов вийшов, та й каже до них: „Не знахо́джу Я в Ньому провини нія́кої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 39, 'Та ви маєте зви́чай, щоб я випустив вам одно́го на Пасху. Чи хочете отже, — відпущу́ вам Царя Юдейського?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 40, 'Та зно́ву вони зняли крик, вимагаючи: „Не Його, а Вара́вву!“А Вара́вва був злочи́нець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 1, 'От тоді взяв Ісуса Пилат, та й звелів збичува́ти Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 2, 'Вояки́ ж, сплівши з те́рну вінка, Йому покла́ли на голову, та багряни́цю наділи на Нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 3, 'і приступали до Нього й казали: „Раді́й, Ца́рю Юдейський!“І били по щоках Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 4, 'Тоді вийшов назо́вні ізно́ву Пилат та й говорить до них: „Ось Його я виво́джу назо́вні до вас, щоб ви перекона́лись, що провини нія́кої в Нім не знахо́джу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 5, 'І вийшов назо́вні Ісус, у терно́вім вінку та в багря́нім плащі. А Пилат до них каже: „Оце Чоловік!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 6, 'Як зобачили ж Його первосвященики й служба, то закричали, говорячи: „Розіпни́, розіпни́!“Пилат каже до них: „То візьміть Його ви й розіпні́ть, — бо провини я в Нім не знахо́джу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 7, 'Відказали юдеї йому: „Ми маємо Зако́на, а за Зако́ном Він мусить умерти, — бо за Божого Сина Себе видавав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 8, 'Як зачув же Пилат оце слово, налякався ще більш,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 9, 'і вернувся в прето́рій ізно́ву, і питає Ісуса: „Звідки Ти?“Та Ісус йому відповіді не подав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 10, 'І каже до Нього Пилат: „Не говориш до мене? Хіба ж Ти не знаєш, що маю я вла́ду розп\'я́сти Тебе, і маю вла́ду Тебе відпустити?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 11, 'Ісус відповів: „Надо Мною ти жодної вла́ди не мав би, коли б тобі зве́рху не да́но було́; тому більший гріх має той, хто Мене тобі ви́дав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 12, 'Після цього Пилат намагався пустити Його, та юдеї кричали, говорячи: „Якщо Його пустиш, то не ке́сарів при́ятель ти! Усякий, хто себе за царя видає, противиться ке́сареві“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 13, 'Як зачув же Пилат оце слово, то вивів назо́вні Ісуса, і засів на судде́ве сиді́ння, на місці, що зветься літострото́н, по-гебрейському ж гавва́та.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 14, 'Був то ж день Пригото́влення Пасхи, година була — близько шостої. І він каже юдеям: „Ось ваш Цар!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 15, 'Та вони закричали: „Геть, геть із Ним! Розіпни́ Його!“Пилат каже до них: „Царя вашого маю розп\'я́сти?“Первосвященики відповіли: „Ми не маєм царя, окрім ке́саря!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 16, 'Ось тоді він їм видав Його, щоб розп\'я́сти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 17, 'І, нісши Свого хреста, Він вийшов на місце, Черепо́вищем зване, по-гебрейському Голго́фа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 18, 'Там Його розп\'яли́, а з Ним ра́зом двох інших, з одно́го та з другого боку, а Ісуса всере́дині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 19, 'А Пилат написав і на́писа, та й умістив на хресті. Було ж там написано: „Ісус Назаряни́н, Цар Юдейський“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 20, 'І багато з юдеїв читали цього написа, бо те місце, де Ісус був розп\'я́тий, було близько від міста. А було по-гебрейському, по-грецькому й по-римському написано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 21, 'Тож сказали Пилатові юдейські первосвященики: „Не пиши: Цар Юдейський, але що Він Сам говорив: Я — Цар Юдейський.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 22, 'Пилат відповів: „Що я написав — написав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 23, 'Розп\'я́вши ж Ісуса, вояки́ взяли одіж Його, та й поділили на чотири частини, по частині для кожного вояка́, теж і хіто́на. А хіто́н був не шитий, а ви́тканий ці́лий відве́рху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 24, 'Тож сказали один до одно́го: „Не будемо дерти його, але же́реба киньмо на нього, — кому припаде́“. Щоб збуло́ся Писа́ння: „Поділили одежу Мою між собою, і метну́ли про шату Мою жеребка́“. Вояки ж це й зробили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 25, 'Під хрестом же Ісуса стояли — Його мати, і сестра Його матері, Марія Клео́пова, і Марія Магдали́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 26, 'Як побачив Ісус матір та учня, що стояв тут, якого любив, то каже до матері: „Оце, жоно, твій син!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 27, 'Потім каже до учня: „Оце мати твоя!“І з тієї години той учень узяв її до себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 28, 'Потім, знавши Ісус, що вже все довершилось, щоб збулося Писа́ння, проказує: „Пра́гну!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 29, 'Тут стояла посу́дина, повна оцту. Вояки ж, губку оцтом напо́внивши, і на трости́ну її настромивши, підне́сли до уст Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 30, 'А коли Ісус оцту прийняв, то промовив: „Звершилось!“І, голову схиливши, віддав Свого духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 31, 'Був же день Приго́товлення, тож юдеї, щоб тіла́ на хресті не зосталися в суботу, — був бо Великдень тієї суботи — просили Пилата зламати голі́нки розп\'я́тим, і зняти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 32, 'Тож прийшли вояки́ й поламали голі́нки першому й другому, що розп\'я́тий з Ним був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 33, 'Коли ж підійшли до Ісуса й побачили, що Він уже вмер, то голі́нок Йому не зламали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 34, 'та один з воякі́в списом бо́ка Йому проколов, — і зараз витекла звідти кров та вода.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 35, 'І самовидець засвідчив, і правдиве свідо́цтво його; і він знає, що правду говорить, щоб повірили й ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 36, 'Бо це сталось тому́, щоб збулося Писа́ння: „Йому кості ламати не бу́дуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 37, 'І знов друге Писа́ння говорить: „Дивитися будуть на Того, Кого́ проколо́ли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 38, 'Потім Йо́сип із Арімате́ї, що був учень Ісуса, але потайни́й, — бо боявся юдеїв, — став просити Пилата, щоб тіло Ісусове взяти. І дозволив Пилат. Тож прийшов він, і взяв тіло Ісусове.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 39, 'Прибув також і Никоди́м, — що давніше прихо́див вночі до Ісуса, — і сми́рну приніс, із ало́єм помішану, щось літрів із сто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 40, 'Отож, узяли вони тіло Ісусове, та й обгорнули його у полотно́ із па́хощами, як є зви́чай ховати в юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 41, 'На тім місці, де Він був розп\'я́тий, знахо́дився сад, а в саду́ новий гріб, що в ньому ніко́ли ніхто не лежав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 42, 'Тож отут, — з-за юдейського дня Пригото́влення — вони покла́ли Ісуса, бо побли́зу був гріб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 1, 'А дня першого в тижні, рано вранці, як ще темно було́, прийшла Марія Магдали́на до гро́бу, та й бачить, що камінь від гро́бу відва́лений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 2, 'Тож біжить вона та й прибуває до Си́мона Петра, та до другого учня, що Ісус його любив, та й каже до них: „Взяли́ Господа з гро́бу, і ми не знаємо, де́ покла́ли Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 3, 'Тоді вийшов Петро й другий учень, і до гро́бу пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 4, 'Вони ж бігли оби́два укупі, але другий той учень попе́реду біг, хутчіш від Петра, і перший до гробу прибув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 5, 'І, нахили́вшися, бачить — лежить полотно... Але він не ввійшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 6, 'Прибува́є і Си́мон Петро, що слідко́м за ним біг, і входить до гробу, і полотно оглядає, що лежало,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 7, 'і хустка, що була на Його голові, лежить не з плащани́цею, але о́сторонь, зго́рнена, в іншому місці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 8, 'Тоді ж увійшов й інший учень, що перший до гробу прибув, і побачив, — і ввірував.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 9, 'Бо ще не розуміли з Писа́ння вони, що Він має воскре́снути з мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 10, 'І учні верну́лися знову до се́бе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 11, 'А Марія стояла при гро́бі назо́вні та й плакала. Плачучи́, нахилилась до гробу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 12, 'І бачить два Анголи́, що в білім сиділи, — один у голова́х, а другий у ніг, де лежало Ісусове тіло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 13, 'І говорять до неї вони: „Чого плачеш ти, жінко?“Та відказує їм: „Узяли́ мого Господа, і я не знаю, де Його покла́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 14, 'І, сказавши оце, оберну́лась назад, і бачить Ісуса, що стояв, та вона не пізнала, що то Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 15, 'Промовляє до неї Ісус: „Чого плачеш ти, жінко? Кого ти шукаєш?“Вона ж, думаючи, що то садівни́к, говорить до Нього: „Якщо, пане, узяв ти Його, то скажи мені, де́ покла́в ти Його, — і Його я візьму́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 16, 'Ісус мовить до неї: „Маріє!“А вона обернулася та по-єврейському каже Йому: „Раббуні́!“цебто: „Учителю мій!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 17, 'Говорить до неї Ісус: „Не торкайся до Мене, бо Я ще не зійшов до Отця. Але йди до братів Моїх та їм розпові́ж: Я йду до Свого Отця й Отця вашого, і до Бога Мого й Бога вашого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 18, 'Іде Марія Магдалина, та й учням звіща́є, що бачила Господа, і Він це їй сказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 19, 'Того ж дня — дня першого в тижні, — коли вечір настав, а двері, де учні зібрались були́, були за́мкнені, — бо боялись юдеїв, — з\'явився Ісус, і став посере́дині, та й промовляє до них: „Мир вам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 20, 'І, сказавши оце, показав Він їм ру́ки та бо́ка. А учні зраділи, побачивши Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 21, 'Тоді зно́ву сказав їм Ісус: „Мир вам! Як Отець послав Мене, і Я вас посилаю!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 22, 'Сказавши оце, Він дихну́в, і говорить до них: „Прийміть Духа Святого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 23, 'Кому гріхи про́стите, — про́стяться їм, а кому затри́маєте, — то затри́маються!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 24, 'А Хома́, один з Дванадцятьох, званий Близню́к, із ними не був, як прихо́див Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 25, 'Інші ж учні сказали йому: „Ми бачили Господа!“А він відказав їм: „Коли на руках Його зна́ку відцвя́шного я не побачу, і пальця свого́ не вкладу́ до відцвя́шної рани, і своєї руки не вкладу́ до боку Його, — не ввірую!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 26, 'За вісім же день знов удома були Його учні, а з ними й Хома́. І, як за́мкнені двері були́, прийшов Ісус, і став посере́дині та й проказав: „Мир вам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 27, 'Потім каже Хомі: „Простягни́ свого пальця сюди, та на руки Мої подивись. Простягни й свою руку, і вклади́ до бо́ку Мого. І не будь ти невіруючий, але віруючий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 28, 'А Хома відповів і сказав Йому: „Господь мій і Бог мій!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 29, 'Промовляє до нього Ісус: „Тому ввірував ти, що побачив Мене? Блаженні, що не бачили й увірували!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 30, 'Багато ж і інших озна́к учинив був Ісус у присутності учнів Своїх, що в книзі оцій не записані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 31, 'Це ж написано, щоб ви ввірували, що Ісус є Христос, Божий Син, і щоб, віруючи, життя мали в Ім\'я́ Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 1, 'Після цього з\'явивсь Ісус знов Своїм учням над морем Тіверія́дським. А з\'явився отак.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 2, 'Укупі були Си́мон Петро, і Хома́, званий Близню́к, і Натанаїл, із Кани́ Галілейської, і оби́два сини Зеведе́єві, і двоє інших із учнів Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 3, 'Говорить їм Си́мон Петро: „Піду риби влови́ти“. Вони кажуть до нього: „І ми піде́мо з тобою“. І пішли вони, і всіли до чо́вна. Та ночі тієї нічого вони не влови́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 4, 'А як ра́нок настав, то Ісус став над берегом, але учні не знали, що то́ був Ісус.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 5, 'Ісус тоді каже до них: „Чи не маєте, діти, якоїсь поживи?“— „Ні“, вони відказали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 6, 'А Він їм сказав: „Закиньте не́вода право́руч від чо́вна, то й зна́йдете!“Вони кинули, — і вже не могли його витягнути із-за бе́злічі риби.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 7, 'Тоді учень, якого любив був Ісус, говорить Петрові: „Це ж Госпо́дь!“А Си́мон Петро, як зачув, що Господь то, накинув на себе оде́жину, — бо він був наги́й, — та й кинувся в море.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 8, 'Інші ж учні, що були недалеко від берега — якихось ліктів з двісті — припливли чо́вником, тягнучи не́вода з рибою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 9, 'А коли вони вийшли на землю, то бачать розло́жений жар, а на нім рибу й хліб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 10, 'Ісус каже до них: „Принесіть тієї риби, що оце ви влови́ли!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 11, 'Пішов Си́мон Петро та й на землю ви́тягнув не́вода, повного риби великої, — сто п\'ятдесят три. І хоч стільки було її, — не продерся проте не́від.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 12, 'Ісус каже до учнів: „Ідіть, сні́дайте!“А з учнів ніхто не нава́жився спитати Його: „Хто Ти такий?“Бо знали вони, що Госпо́дь то.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 13, 'Тож підходить Ісус, бере хліб і дає їм, так само ж і рибу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 14, 'Це вже втретє з\'явився Ісус Своїм учням, як із мертвих воскре́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 15, 'Як вони вже посні́дали, то Ісус промовляє до Си́мона Петра: „Си́моне, сину Йо́нин, — чи ти лю́биш мене́ бі́льше цих?“Той каже Йому́: „Так, Го́споди, — ві́даєш Ти, що кохаю Тебе!“Промовляє йому: „Паси ягнята Мої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 16, 'І говорить йому Він удруге: „Си́моне, сину Йо́нин, — чи ти любиш Мене?“Той каже Йому: „Так, Господи, — ві́даєш Ти, що кохаю Тебе!“Промовляє йому: „Паси ві́вці Мої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 17, 'Утретє Він каже йому́: „Си́моне, сину Йо́нин, — чи кохаєш Мене?“Засмутився Петро, що спитав його втретє: „Чи кохаєш Мене?“І він каже Йому: „Ти все ві́даєш, Господи, — ві́даєш Ти, що кохаю Тебе!“Промовляє до нього Ісус: „Паси вівці Мої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 18, 'Поправді, поправді кажу́ Я тобі: Коли був ти молодший, то ти сам підпері́зувався, і ходив, куди́ ти бажав. А коли постарі́єш, — свої руки простя́гнеш, і інший тебе підпере́же, і поведе́, куди не захочеш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 19, 'А оце Він сказав, щоб зазначити, якою то смертю той Бога просла́вить. Сказавши таке, Він говорить йому: „Іди за Мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 20, 'Обернувся Петро, та й ось бачить, що за ним слідкома́ йде той учень, якого любив Ісус, який на вечері до ло́ня Йому був схилився й спитав: „Хто, Господи, видасть Тебе?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 21, 'Петро, як побачив того, говорить Ісусові: „Господи, — цей же що?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 22, 'Промовляє до нього Ісус: „Якщо Я схотів, щоб він позоста́вся, аж поки прийду́, — що до то́го тобі? Ти йди за Мною!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 23, 'І це слово розне́слось було́ між брата́ми, що той учень не вмре. Проте́ Ісус не сказав йому, що не вмре, а: „Якщо Я схотів, щоб він позоста́вся, аж поки прийду́, — що до то́го тобі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 24, 'Це той учень, що сві́дчить про це, що й оце написав. І знаємо ми, що правдиве свідо́цтво його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 25, 'Багато є й іншого, що Ісус учинив. Але ду́маю, що коли б написати про все те зокре́ма про кожне, то й сам світ не вмістив би написаних книг! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Першу книгу я був написав, о Тео́філе, про все те, що Ісус від поча́тку чинив та навчав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'аж до дня, коли через Духа Святого подав Він нака́зи апо́столам, що їх вибрав, і возні́сся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'А по муці Своїй Він ставав перед ними живий із засві́дченнями багатьма́, і сорок день їм з\'являвся та про Боже Царство казав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'А зібравшися з ними, Він звелів, щоб вони не відхо́дили з Єрусалиму, а чекали обі́тниці Отчої, „що про неї — казав — ви чули від Мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Іван бо водою христив, — ви ж охрищені будете Духом Святим через кілька тих днів!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'А вони, зійшовшись, питали Його й говорили: „Чи не ча́су цього відбуду́єш Ти, Господи, царство Ізраїлеві?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'А Він їм відказав: „То не ваша справа знати час та добу́, що Отець покла́в у вла́ді Своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Та ви при́ймете силу, як Дух Святий злине на вас, і Моїми ви свідками бу́дете в Єрусалимі, і в усій Юдеї та в Самарії, та аж до останнього кра́ю землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'І, прорікши оце, як дивились вони, Він уго́ру возно́ситись став, а хмара забра́ла Його сперед їхніх оче́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'А коли вони пильно дивились на небо, як Він віддалявся, то два мужі́ у білій одежі ось стали при них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'та й сказали: „Галілейські мужі, — чого стоїте́ й задивля́єтесь на небо? Той Ісус, що вознісся на небо від вас, при́йде так, як бачили ви, як ішов Він на небо!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Тоді вони повернулись до Єрусалиму з гори, що Оливною зветься, і що знахо́диться по́близько Єрусалиму, на віддаль дороги суботнього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'А прийшовши, увійшли вони в го́рницю, де й перебували: Петро та Іван, та Яків та Андрій, Пилип та Фома, Варфоломі́й та Матвій, Яків Алфе́їв та Си́мон Зило́т, та Юда Яковів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Вони всі однодушно були на невпинній молитві, із жінка́ми, і з Марією, матір\'ю Ісусовою, та з братами Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'Тими ж днями Петро став посеред братів — а наро́ду було поіменно до ста двадцяти — та й промовив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, '„Мужі-браття! Нале́жало збутись Писа́нню тому́, що устами Давидовими Дух Святий був прорік про Юду, який показав дорогу для тих, хто Ісуса схопи́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'бо він був зарахований з нами, і же́реб служі́ння оцього прийняв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'І він поле набув за заплату злочи́нства, а впавши сторчма́, він тріснув надво́є, і все нутро́ його вилилось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'І стало відо́ме це всім, хто замешкує в Єрусалимі, тому й поле те на́зване їхнього мовою Акелдама́, що є: Поле крови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Бо написано в книзі Псалмів: „Нехай пусткою стане мешка́ння його, і нехай пожильця́ в нім не бу́де“, а також: „А служі́ння його забере́ нехай інший“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Отже треба, щоб один із тих мужів, що схо́дились з нами повсякча́с, як Господь Ісус вхо́див і вихо́див між нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'зачавши від хрищення Іванового аж до дня, коли Він вознісся від нас, щоб той ра́зом із нами був свідком Його воскресіння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'І поставили двох: Йо́сипа, що Варса́вою зветься, і що Юстом був на́званий, та Матті́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'А молившись, казали: „Ти, Господи, знавче всіх серде́ць, покажи з двох одно́го, котро́го Ти вибрав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'щоб він зайняв місце тієї служби й апо́стольства, що Юда від нього відпав, щоб іти в своє місце“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'І дали́ жеребки́ їм, — і впав жеребо́к на Матті́я, і він зарахований був до одинадцятьо́х апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Коли ж поча́вся день П\'ятдесятниці, всі вони однодушно знахо́дилися вкупі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'І на́гло зчинився шум із не́ба, ніби буря рапто́ва зірва́лася, і перепо́внила ввесь той дім, де сиділи вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'І з\'явилися їм язи́ки поді́лені, немов би огне́нні, та й на кожному з них по одно́му осів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Усі ж вони спо́внились Духом Святим, і почали́ говорити іншими мо́вами, як їм Дух промовляти давав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Перебува́ли ж в Єрусалимі юдеї, люди побожні, від усякого наро́ду під небом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'А коли оцей го́мін зчинився, зібралася бе́зліч наро́ду, — та й диву далися, бо кожен із них тут почув, що вони розмовляли їхньою власною мовою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Усі ж побенте́жилися та дивувалися, та й казали один до одно́го: „Хіба ж не галіле́яни всі ці, що гово́рять?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Як же кожен із нас чує свою́ власну мову, що ми в ній народи́лись?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Парфя́ни та мі́дяни та еламі́ти, також ме́шканці Месопота́мії, Юдеї та Каппадокі́ї, Понту та Азії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'і Фрі́ґії та Памфі́лії, Єгипту й лівійських земель край Кіре́ни, і захожі римля́ни,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'юдеї й нововірці, крі́тяни й араби, — усі чуємо ми, що говорять вони про великі діла Божі мовами нашими!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'І всі не вихо́дили з дива, і безрадні були, і говорили один до одно́го: „Що ж то статися має?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'А інші казали глузу́ючи: „Вони повпива́лись вином молодим!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ставши ж Петро із Одинадцятьма́, свій голос підніс та й промовив до них: „Мужі юдейські та ме́шканці Єрусалиму! Нехай вам оце стане відо́ме, і послухайте слів моїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Бо не п\'я́ні вони, як ви ду́маєте, — бо третя година дня,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'а це те, що пророк Йоі́л передрік:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, '„І буде останніми днями, говорить Госпо́дь: Я виллю від Духа Свого на всяке тіло, — і будуть пророкува́ти сини ваші та ваші до́ньки, юнаки́ ж ваші бачити будуть виді́ння, а старим вашим сни будуть сни́тися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'І на рабів Моїх і на рабинь Моїх за тих днів Я також виллю від Духа Свого, — і пророкувати вони бу́дуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'І дам чуда на небі вгорі, а внизу на землі ці знаме́на: кров, і огонь, і ку́ряву диму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Переміниться сонце на те́мряву, а місяць на кров, перше ніж день Господній настане, великий та славний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'І станеться, що кожен, хто покличе Господнє Ім\'я́, той спасеться“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Мужі ізраїльські, послухайте ви оцих слів: Ісуса Назаряни́на, Мужа, що Його Бог прославив вам силою, і чудами, і тими знаме́нами, що Бог через Нього вчинив серед вас, як самі ви те знаєте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'Того, що був ви́даний певною волею та передба́ченням Божим, ви руками беззаконників розп\'яли́ та забили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 24, 'Та Бог воскресив Його, пута смерти усунувши, — вона бо тримати Його не могла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 25, 'Бо каже про Нього Давид: „Мав я Господа за́всіди перед очима своїми, бо Він по правиці моїй, щоб я не захитався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 26, 'Тому серце моє звеселилось, і зрадів мій язик, і тіло моє відпочи́не в надії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 27, 'Бо не позоставши Ти в аду́ моєї душі, і не даси Ти Своєму Святому побачити тління!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 28, 'Ти дороги життя об\'явив мені, Ти мене перепо́вниш утіхою перед обличчям Своїм“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 29, 'Мужі-браття! Нехай буде вільно мені сміло сказати вам про патріярха Давида, що помер і похований, і знахо́диться гріб його в нас аж до цього дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 30, 'А бувши ж пророком, та відаючи, що „Бог клятвою клявся йому посади́ти на престолі його від плоду його сте́гон“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 31, 'у передба́ченні він говорив про Христове воскре́сення, що „не буде зоставлений в аду́“, ані тіло Його „не зазнає зотління“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 32, 'Бог Ісуса Цього воскресив, чого свідки всі ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 33, 'А отож, як правицею Божою був Він возне́сений, і обі́тницю Духа Святого прийняв від Отця, то й злив Він оте, що ви бачите й чуєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 34, 'Не зійшов бо на небо Давид, але сам він говорить: „Промовив Госпо́дь Господе́ві моєму: Сядь право́руч Мене,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 35, 'доки не покладу́ Я Твоїх ворогів підніжком ногам Твоїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 36, 'Ото ж, нехай ввесь Ізраїлів дім твердо знає, що і Господом, і Христом учинив Бог Його, Того Ісуса, що Його розп\'яли́ ви!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 37, 'Як почули ж оце, вони серцем розжа́лобились, та й сказали Петрові та іншим апо́столам: „Що ж ми маємо робити, мужі-браття?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 38, 'А Петро до них каже: „Покайтеся, і нехай же охриститься кожен із вас у Ім\'я́ Ісуса Христа на відпу́щення ваших гріхів, — і да́ра Духа Святого ви при́ймете!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 39, 'Бо для вас ця обі́тниця, і для ваших дітей, і для всіх, що „дале́ко знаходяться, кого б тільки покликав Госпо́дь, Бог наш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 40, 'І іншими багатьома́ словами він засвідчував та вмовляв їх, говорячи: „Рятуйтесь від цього лукавого роду!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 41, 'Отож ті, хто прийняв його слово, охристилися. І пристало до них того дня душ тисяч зо три!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 42, 'І вони перебува́ли в науці апо́стольській, та в спільно́ті брате́рській, і в лама́нні хліба, та в моли́твах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 43, 'І був о́страх у кожній душі, бо багато чинили апо́столи чуд та знаме́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 44, 'А всі віруючі були вкупі, і мали все спі́льним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 45, 'І вони продавали маєтки та до́бра, і всім їх ділили, як кому чого треба було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 46, 'І кожного дня перебува́ли вони однодушно у храмі, і, ломлячи хліб по домах, поживу приймали із радістю та в сердечній просто́ті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 47, 'вихваляючи Бога та маючи ласку в усього народу. І щоденно до Церкви Госпо́дь додава́в тих, що спасалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'А Петро та Іван на дев\'яту годину молитви йшли ра́зом у храм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'І не́сено там чоловіка одно́го, що кривий був з утро́би своєї матері. Його садови́ли щоденно в воро́тях храму, що Красними звалися, просити ми́лостині від тих, хто до храму йшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Як побачив же він, що Петро та Іван хочуть у храм увійти, став просити в них милостині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Петро ж із Іваном поглянув на нього й сказав: „Подивися на нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'І той подивився на них, сподіваючися щось дістати від них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Та промовив Петро: „Срібла й золота в мене нема, але що я маю, даю тобі: У Ім\'я́ Ісуса Христа Назаряни́на — устань та й ходи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'І, узявши його за прави́цю, він підвів його. І хвилі тієї зміцни́лися но́ги й сугло́бці його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'І, зірвавшись, він устав та й ходив, і з ними у храм увійшов, ходячи та підскакуючи, і хвалячи Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Наро́д же ввесь бачив, як ходив він та Бога хвалив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'І пізнали його, що це той, що при Красних воро́тях храму сидів ради милостині. І вони перепо́внились жа́хом та по́дивом із того, що́ сталось йому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'А тому́, що тримався він Петра та Івана, увесь наро́д зачудований збігся до них на той ґанок, який Соломоновим зветься.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'І, побачивши це, промовив Петро до наро́ду: „Мужі ізраїльські! Чого ви дивуєтесь цим, та чого ви на нас позира́єте так, ніби те, що він ходить, ми зробили своєю силою чи благоче́стям?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, '„Бог Авраамів, та Ісаків, та Яковів, Бог наших батьків, Сина Свого прославив“, Ісуса, Якого ви ви́дали, і відцуралися перед Пилатом, як він присудив був пустити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Але ви відцура́лись Святого та Праведного, і домагалися видати вам душогубця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Начальника ж життя ви забили, та Його воскресив Бог із мертвих, чого свідками — ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'І через віру в Ім\'я́ Його вздоро́вило Ім\'я́ Його того, кого бачите й знаєте. І віра, що від Нього, прине́сла йому вздоро́влення це перед вами всіма́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'А тепер, браття, знаю, що вчинили ви це з несвідо́мости, як і ваші начальники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'А Бог учинив так, як Він провіщав був уста́ми Своїх усіх пророків, щоб терпіти Христові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Покайтеся ж та наверні́ться, щоб Він змилувався над вашими гріхами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'щоб часи́ відпочинку прийшли від обличчя Господнього, і щоб послав запові́дженого вам Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'що Його небо мусить прийняти аж до ча́су відно́влення всього, про що провіщав Бог від віку устами всіх святих пророків Своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Бо Мойсей провіща́в: „Господь Бог вам Пророка піді́йме від ваших братів, як мене; у всім Його слухайтеся, про що тільки Він вам говоритиме!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, '„І станеться, що кожна душа, яка не послухала б того Пророка, зни́щена буде з наро́ду“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'Так само всі пророки від Самуї́ла й наступних, скільки їх говорило, також провіщали ці дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Сини ви пророків і того заповіту, що Бог вашим батька́м заповів, промовляючи до Авраама: „І в насінні твоїм усі народи землі благосло́влені будуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 26, 'Воскресивши Свого Слугу, Бог послав Його перше до вас, щоб вас поблагослови́ти, щоб кожен із вас відвернувся від злих своїх учинків!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'А коли промовляли вони до наро́ду оце́, до них приступили священики, і вла́да сторожі храму й саддукеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'обурюючись, що навчають наро́д та звіщають в Ісусі воскресі́ння з мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'І руки наклали на них, і до в\'язниці всадили до ра́нку, бо вже вечір настав був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'І багато-хто з тих, хто слухав слово, увірували; число ж мужів таки́х було тисяч із п\'ять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'І сталось, що ра́нком зібралися в Єрусалимі начальники їхні, і старші та книжники,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'і Анна первосвященик, і Кайя́фа, і Іван, і Олександер, і скільки було їх із роду первосвященичого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'І, поставивши їх посере́дині, запиталися: „Якою ви силою чи яким ви ім\'я́м те робили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Тоді Петро, переповнений Духом Святим, промовив до них: „Начальники люду та старши́ни Ізраїлеві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Як сьогодні беруть нас на до́пит про те доброді́йство недужій люди́ні, як вона вздоро́влена, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'нехай буде відо́мо всім вам, і всім лю́дям Ізраїлевим, що Ім\'я́м Ісуса Христа Назаряни́на, що Його розп\'яли́ ви, та Його воскресив Бог із мертвих, — Ним поставлений він перед вами здоровий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Він „камінь, що ви, будівни́чі, відкинули, але каменем став Він нарі́жним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'І нема ні в кім іншім спасі́ння. Бо під небом нема іншого Йме́ння, даного людям, що ним би спасти́ся ми мали“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'А бачивши сміли́вість Петра та Івана, і спостерігши, що то люди оби́два невчені та про́сті, дивувалися, і пізнали їх, що вони з Ісусом були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Та бачивши, що вздоро́влений чоловік стоїть з ними, нічого навпро́ти сказати не могли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'І, звелівши їм вийти із синедріо́ну, зачали радитися між собою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'говорячи: „Що́ робити нам із цими людьми́? Бож усім ме́шканцям Єрусалиму відо́мо, що вчинили вони явне чудо, і не можемо того заперечити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'Та щоб більш не поши́рювалось це в наро́ді, то з погрозою заборонімо їм, щоб ніко́му з людей вони не говорили про Це Ім\'я́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'І, закли́кавши їх, наказали їм не говорити, і взагалі не навчати про Ісусове Йме́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'І відповіли́ їм Петро та Іван, та й сказали: „Розсудіть, чи це справедливе було б перед Богом, щоб слухатись вас більш, як Бога?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'Бо не можемо ми не казати про те, що́ ми бачили й чули!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'А вони пригрози́ли їм ще, і відпустили їх, не знайшовши нічо́го, щоб їх покарати, через людей, бо всі сла́вили Бога за те, що сталось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Бо ро́ків більш сорока мав той чоловік, що на нім відбулося це чудо вздоро́влення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, 'Коли ж їх відпустили, вони до своїх прибули́ й сповістили, про що́ первосвященики й старші до них говорили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Вони ж, вислухавши, однодушно свій голос до Бога підне́сли й промовили: „Владико, що небо, і землю, і море, і все, що в них є, Ти створив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'Ти уста́ми Давида, Свого слуги́, отця нашого, сказав Духом Святим: „Чого люди бунтуються, а наро́ди задумують ма́рне?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 26, 'Повстають царі зе́мні, і збираються старші докупи на Господа та на Христа Його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 27, 'Бо справді зібралися в місці оцім проти Отрока Святого Твого Ісуса, що Його намастив Ти, Ірод та По́нтій Пилат із поганами та з наро́дом Ізраїлевим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 28, 'учинити оте, що рука Твоя й воля Твоя наперед встановили були, щоб збуло́ся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 29, 'І тепер споглянь, Господи, на їхні погрози, і дай Своїм рабам із повною сміли́вістю слово Твоє повіда́ти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 30, 'коли руку Свою простягатимеш Ти на вздоро́влення, і щоб знаме́на та чуда чинились Ім\'я́м Твого Святого Отрока Ісуса“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 31, 'Як вони ж помолились, затряслося те місце, де зібрались були, і перепо́внилися всі Святим Духом, — і зачали говори́ти Слово Боже з сміли́вістю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 32, 'А люди, що ввірували, мали серце одне й одну душу, і жоден із них не вважав що з маєтку свого́ за своє, але в них усе спі́льним було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 33, 'І апо́столи з вели́кою силою свідчили про воскресіння Ісуса Господа, і благода́ть велика на всіх них була!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 34, 'Бо жоден із них не терпів недостачі: бо, хто мав поле чи дім, продавали, і заплату за про́даж прино́сили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 35, 'та й клали в ногах у апо́столів, — і роздавалося кожному, хто потре́бу в чім мав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 36, 'Так, Йо́сип, що Варна́вою — що в перекладі є „син потіхи“— був про́званий від апо́столів, Левит, родом кі́прянин,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 37, 'мавши поле, продав, а гроші приніс, та й поклав у ногах у апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'А один чоловік, на йме́ння Ана́ній, із своєю дружи́ною Сапфі́рою, продав маєток,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'та й з ві́дома дружи́ни своєї присво́їв частину з заплати, а якусь там частину приніс та й поклав у ногах у апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'І промовив Петро: „Ана́нію, чого сатана́ твоє серце напо́внив, щоб ти Духу Святому неправду сказав та присво́їв із заплати за землю?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Хіба те, що́ ти мав, не твоє все було, а про́дане не в твоїй вла́ді було? Чого ж в серце своє ти цю справу поклав? Ти не лю́дям неправду сказав, але Богові!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Як Ана́ній зачу́в ці слова́, то впав та й умер. І обгорнув жах великий усіх, що це чули!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Юнаки́ ж повставали, обгорну́ли його, і винесли та й поховали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'І сталось, годин через три прийшла й дружи́на його, про випа́док нічо́го не знавши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'І промовив до неї Петро: „Скажи мені, чи за стільки ви землю оту продали́?“Вона ж відказала: „Так, за стільки“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'До неї ж Петро: „Чому це ви змо́вилися споку́шувати Господнього Духа? Он ті входять у двері, що чоловіка твого поховали, — і тебе вони винесуть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'І вона зараз упала до ніг його, та й умерла. Як ввійшли ж юнаки́, то знайшли її мертвою, і, винісши, біля мужа її поховали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'І обгорнув страх великий всю Церкву та всіх, що чули про це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'А руками апо́столів стались знаме́на та чуда великі в наро́ді. І були́ однодушно всі в Соломоновім ґанку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'А з сторонніх ніхто приставати не важивсь до них, але люд прославляв їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'І все збі́льшувалось тих, хто вірує в Господа, бе́зліч чолові́ків і жінок,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'так що хворих стали вино́сити на вулиці, та й клали на ложа та ноші, щоб, як ітиме Петро, то хоч тінь його впала б на ко́го із них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'І бе́зліч люду збиралась до Єрусалиму з довко́лишніх міст, і не́сли недужих та хворих від ду́хів нечистих, — і були́ вони всі вздоро́влювані!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, 'А первосвященик, уставши, та й усі, хто був із ним, хто належав до саддуке́йської єресі, перепо́внились за́здрощами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'і руки наклали вони на апо́столів, і до в\'язниці грома́дської вкинули їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Але Ангол Господній вночі відчинив для них двері в\'язничні, і, вивівши їх, проказав:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, '„Ідіть, і, ставши, говоріть до наро́ду у храмі всі слова́ цього життя“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, 'Як це вчули вони, то в храм рано ввійшли і навчали. А первосвященик і ті, хто був із ним, прийшовши, скликали синедріо́н і всіх старших з Ізраїлевих синів. І послали в в\'язницю, щоб їх привели́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'А служба, прийшовши, не знайшла́ їх у в\'язниці, а вернувшись, сповістила,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'говорячи: „В\'язницю знайшли ми з великою пильністю за́мкнену, і сторо́жу, що при две́рях стояла; а коли відчинили, то ніко́го всере́дині ми не знайшли!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'Як почули слова ці начальник сторожі храму та первосвященики, не могли зрозуміти вони, що́ б то сталося.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Та прийшовши один, сповістив їх, говорячи: „Ось ті мужі, що ви їх до в\'язниці всадили були, у храмі стоять та й навчають наро́д“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'Пішов тоді старши́й сторо́жі зо слу́жбою, та й привів їх без насильства, бо боялись наро́ду, щоб їх не побили камінням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 27, 'Припровадивши ж їх, поставили перед синедріоном. І спитався їх первосвященик, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 28, '„Чи ми не заборонили з погрозою вам, щоб про Те Ім\'я́ не навчати? І ото, ви своєю наукою перепо́внили Єрусалим, і хочете кров Чоловіка Того припрова́дити на нас“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 29, 'Відповів же Петро та сказали апо́столи: „Бога повинно слухатися більш, як людей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 30, 'Бог наших отців воскресив нам Ісуса, Якому ви смерть були заподі́яли, повісивши на дереві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 31, 'Його Бог підвищив Своєю прави́цею — на Начальника й Спаса, щоб дати Ізраїлеві покая́ння і про́щення гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 32, 'А тих справ Йому свідками ми й Святий Дух, що Його Бог дав тим, хто слухня́ний Йому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 33, 'Як зачули ж оце, запалилися гнівом вони, та й ра́дилися, я́к їм смерть заподі́яти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 34, 'І встав у синедріо́ні один фарисей, Гамалії́л на ймення, учитель Зако́ну, поважаний від усього наро́ду, та й звелів на часи́нку апо́столів ви́вести.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 35, 'І промовив до них: „Мужі ізраїльські! Поміркуйте собі про людей цих, що́ з ними робити ви маєте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 36, 'Бо перед цими днями повстав був Те́вда та й казав, що великий він хтось, і до нього пристало з чотириста люда. Він забитий, а всі ті, хто слухав його, розпоро́шились та оберну́лись в ніщо́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 37, 'Після нього повстав, під час пе́репису, Галіле́янин Юда, та й багато людей потягнув за собою. Загинув і він, а всі ті, хто слухав його, розпоро́шились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 38, 'І тепер кажу́ вам: Відступіться від цих людей, і занеха́йте їх! Бо коли від людей оця рада чи справа ця бу́де, — розпаде́ться вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 39, 'А коли те від Бога, то того зруйнувати не зможете, щоб випа́дком не стати і вам богобо́рцями!“І послухались ради його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 40, 'І, покликавши зно́в апо́столів, вибили їх, наказали їм не говори́ти про Ісусове Йме́ння, та й їх відпустили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 41, 'А вони поверта́лися з синедріо́ну, радіючи, що сподоби́лись прийняти знева́гу за Йме́ння Го́спода Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 42, 'І щоденно у храмі й домах безупинно навчали, і звіщали Єва́нгелію Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Тими ж днями, як учнів намно́жилось, зачали́ нарікати на євреїв огре́чені, що в щоденному служі́нні їхні вдовиці зане́дбані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Тоді ті Дванадцять покликали багатьо́х учнів та й сказали: „Нам не ли́чить покинути Боже Слово, і служити при стола́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Отож, браття, ви́глядіть із-поміж себе сімох мужів доброї слави, повних Духа Святого та мудрости, — їх поставимо на службу оцю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'А ми перебува́тимемо за́вжди в молитві та в служі́нні слову“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'І всім лю́дям сподо́балося оце слово, і обрали Степа́на, мужа повного віри та Духа Святого, і Пилипа, і Про́хора та Никано́ра, і Ти́мона та Парме́на, і нововірця Миколу з Антіохії, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'їх поставили перед апо́столів, і, помолившись, вони руки поклали на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'І росло Слово Боже, і ду́же мно́жилося число учнів у Єрусалимі, і дуже багато священиків були слухня́ні вірі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'А Степан, повний віри та сили, чинив між наро́дом великі знаме́на та чуда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Тому дехто повстав із синагоги, що зветься ліберти́нська, і кірінейська, і олександрійська, та з тих, хто походить із Кілікі́ї та з Азії, і зачали́ сперечатись із Степа́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Але всто́яти вони не могли проти мудрости й Духа, що він Ним говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Тоді вони підмовили людей, що казали, ніби чули, як він богозневажні слова́ говорив на Мойсея та Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'І людей попідбу́рювали, і старших та книжників, і, напавши, схопи́ли його, і припрова́дили в синедріо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Також свідків фальшивих поставили, які говорили: „Чоловік оцей богознева́жні слова́ безпере́стань говорить на це святе місце та проти Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Бо ми чули, як він говорив, що Ісус Назаряни́н зруйнує це місце та змінить звича́ї, які передав нам Мойсей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Коли всі, хто в синедріоні сидів, на нього споглянули, то бачили лице його, — як лице Ангола!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Запитав тоді первосвященик: „Чи це так?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Степан же промовив: „Послухайте, мужі-браття й отці! Бог слави з\'явивсь Авраамові, отцеві нашому, як він у Месопота́мії був, перше ніж оселився в Хара́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'і промовив до нього: „Вийди із своєї землі та від роду свого, та й піди до землі, що тобі покажу́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Тоді він вийшов із землі халдейської, та й оселився в Хара́ні. А звідти, як умер йому ба́тько, Він переселив його в землю оцю, що на ній ви живе́те тепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Та спа́дщини на ній Він не дав йому навіть на крок, але обіцяв „дати її на володі́ння йому й його ро́дові по нім“, хоч дитини не мав він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'І сказав Бог отак, що насіння його буде прихо́дьком у кра́ї чужому, і понево́лять його, і будуть гноби́ти чотириста ро́ків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, '„Але Я — сказав Бог — буду судити наро́д, що його понево́лить. Опісля́ ж вони вийдуть, і будуть служити Мені на цім місці“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'І дав Він йому заповіта обрі́зання. І породив так Ісака, і во́сьмого дня він обрізав його. А Ісак породив Якова, а Яків — дванадцятьо́х патріярхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'А ті патріярхи поза́здрили Йо́сипові, і продали́ його до Єгипту. Але Бог був із ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'і його визволив від усіх його у́тисків, і дав йому благода́ть та мудрість перед фараоном, царем єгипетським, а він настановив його за правителя над Єгиптом та всім своїм домом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'А як голод прийшов на всю землю єгипетську та ханаа́нську, та велика біда, то пожи́ви тоді не знахо́дили наші батьки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Коли ж Яків зачув, що в Єгипті є збіжжя, то послав батьків наших уперше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'А як удруге посла́в, то був пі́знаний Йо́сип братами своїми́, і фараонові знаний став Йо́сипів рід.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Тоді Йо́сип послав, щоб покликати Якова, ба́тька свого, та всю родину свою — сімдеся́т і п\'ять душ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'І пода́вся Яків в Єгипет, та й умер там він сам та наші батьки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'І їх перене́сли в Сихе́м, і покла́ли до гробу, що Авраам був купив за ці́ну срібла від синів Еммора Сихемового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'А коли наближа́всь час обі́тниці, що нею Бог клявсь Авраамові, розрісся наро́д і намно́жився в Єгипті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'аж поки настав інший цар ув Єгипті, що не знав уже Йо́сипа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Він хитро наш люд обманив, і силою змушував наших отців викидати дітей своїх, щоб вони не лишались живі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Того ча́су родився Мойсей, і га́рний він був перед Богом. Він годо́ваний був у домі батька свойо́го три місяці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'А коли він був ви́кинений, то дочка фараона забрала його, та й за сина собі його викохала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'І Мойсей був навче́ний всієї премудрости єгипетської, і був міцни́й у словах та в ділах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'А коли йому спо́внилося сорок ро́ків, йому спало на серце відві́дати братів своїх, синів Ізраїлевих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Як угле́дів же він, що одно́му з них ді́ється кривда, заступився, і відомсти́в за окри́вдженого, убивши єги́птянина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Він же ду́мав, що брати́ розуміють, що рукою його Бог дає їм визво́лення, та не зрозуміли вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'А наступного дня, як сварились вони, він з\'явився й хотів погоди́ти їх, кажучи: „Люди, ви — браття, чого один о́дного кривдите?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'А той, що ближнього кривдив, його відіпхну́в та сказав: „Хто наставив над нами тебе за старшо́го й суддю?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Чи хочеш убити й мене, як учора вбив ти єги́птянина?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 29, 'І втік Мойсей через слово оце, і стався прихо́дьком у землі мадія́мській, де зродив двох синів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 30, 'А коли сорок ро́ків проминуло, то з\'явивсь йому Ангол Господній у по́лум\'ї куща́ огняно́го в пустині Сінайської гори.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 31, 'А Мойсей, як побачив, дивувався з видіння. А коли підійшов, щоб розглянути, був голос Господній до нього:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 32, '„Я Бог отців твоїх, — Бог Авраамів, і Бог Ісаків, і Бог Яковів!“І затрусився Мойсей, і не відваживсь погля́нути...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 33, 'І промовив до нього Господь: „Скинь взуття́ з своїх ніг, бо те місце, на якому стоїш, то святая земля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 34, 'Добре бачив Я у́тиск наро́ду Свого, що в Єгипті, і стогін його Я почув, і зійшов, щоб їх ви́зволити. Тепер ось іди, — Я пошлю до Єгипту тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 35, 'Цього Мойсея, що його відцурались вони, сказавши: „Хто наставив тебе за старшо́го й суддю“, цього Бог через Ангола, якому з\'явився в кущі, послав за старшо́го й визво́льника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 36, 'Він їх вивів, чуда й знаме́на вчинивши в землі єгипетській, і на Червоному морі, і сорок ро́ків у пустині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 37, 'Це той Мойсей, що прорік Ізраїлевим синам: „Госпо́дь Бог вам підійме Пророка від ваших братів, як мене, — Його слухайте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 38, 'Це той, що в пустині на зборах був з Анголом, який промовляв йому на Сінайській горі, та з отцями нашими, і що прийняв він живі слова́, щоб їх нам передати;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 39, 'що його не хотіли отці наші слу́хати, але відіпхнули, і звернулися серцем своїм до Єгипту,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 40, 'промовивши до Ааро́на: „Зроби нам богів, які йшли б перед нами, бо не знаємо, що́ сталося з тим Мойсеєм, який вивів нас із кра́ю єгипетського“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 41, 'І зробили вони тими днями теля, — і бовва́нові жертви прино́сили та веселилися з діл своїх рук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 42, 'Але Бог відвернувся від них, і попусти́в їх вклонятися силі небесній, як написано в книзі Пророків: „Чи зако́лення й жертви Мені ви прино́сили сорок ро́ків у пустині, о доме Ізраїлів?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 43, 'Ви ж носили наме́та Моло́хового, і зорю вашого бога Ромфа́на, зображення, що їх ви зробили, щоб вклонятися їм. Через те запрова́джу вас аж за Вавилон!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 44, 'У наших отців на пустині була скинія свідо́цтва, як Той ізвелів, Хто Мойсею казав, щоб зробив її за зразком, якого він бачив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 45, 'Її наші отці й узяли, і вне́сли з Ісусом у землю наро́дів, яких вигнав Бог з-перед обличчя наших отців, аж до ча́су Давида.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 46, 'Він у Бога знайшов благода́ть, і просив, щоб оселю знайти для Бога Якова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 47, 'І Соломон збудував Йому дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 48, 'Але не в рукотворнім Всевишній живе, як говорить пророк:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 49, '„Мені небо — престол, а земля — то підніжок ногам Моїм! Який Мені дім ви збудуєте, — говорить Господь, — або місце яке для Мого відпочинку?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 50, 'Хіба не рука Моя все́ це створила?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 51, 'О ви, твердошиї, люди серця й вух необрізаних! Ви за́вжди противитесь Духові Святому, як ваші батьки, так і ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 52, 'Котро́го з пророків батьки ваші не переслідували? Вони ж тих повбивали, хто звіщав прихід Праведного, Якому тепер ви сталися зрадниками та убійниками,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 53, 'ви, що Зако́на оде́ржали через зарядження Анголів, та не зберігали його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 54, 'Як зачули ж оце, вони запали́лися гнівом у серцях своїх, і скрегота́ли зубами на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 55, 'А Степан, повний Духа Святого, на небо споглянув, — і побачив Божу славу й Ісуса, що по Божій правиці стояв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 56, 'і промовив: „Ось я бачу відчи́нене небо, і Сина Лю́дського, що по Божій правиці стоїть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 57, 'Та вони гучни́м голосом стали кричати та ву́ха собі затуляти, та й кинулися однодушно на нього!...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 58, 'І за місто вони його ви́вели, і зачали́ побивати камінням його. А свідки плащі свої склали в ногах юнака́, який звався Са́влом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 59, 'І побивали камінням Степа́на, що молився й казав: „Господи Ісусе, — прийми духа мого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 60, 'Упавши ж навко́лішки, скрикнув голосом гучни́м: „Не залічи́ їм, о Господи, цього гріха́!“І, промовивши це, він спочив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'А Савл похваляв його вби́вство. І утиск великий постав того дня проти єрусалимської Церкви, і всі, крім апо́столів, розпоро́шилися по краях юдейських та самарійських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'І поховали Степа́на му́жі побожні, і плакали ревно за ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'А Савл нищив Церкву, — вдирався в доми́, витягав чоловіків і жінок та давав до в\'язниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Ходили тоді розпоро́шенці, та Боже Слово благовісти́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Ось Пилип прийшов до самарійського міста, і проповідував їм про Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'А люди вважали на те, що Пилип говорив, і згідно слухали й бачили чу́да, які він чинив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Із багатьох бо, що мали їх, ду́хи нечисті вихо́дили з криком великим, і багато розсла́блених та кривих уздорови́лися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'І радість велика в тім місті була́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Був один чоловік, на ім\'я́ йому́ Си́мон, що до того в цім місті займавсь ворожби́тством та дурив самарійський наро́д, видаючи себе за якогось великого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Його слухали всі, — від найменшого аж до найбільшого, кажучи: „Він — сила Божа, що зветься велика!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Його ж слухалися, бо він їх довший час дивував ворожби́тством.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Та коли йняли віри Пилипові, що благовістив про Боже Царство й Ім\'я́ Ісуса Христа, чоловіки й жінки охристи́лися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Увірував навіть сам Си́мон, і, охристившись, тримався Пилипа; а бачивши чуда й знаме́на великі, він дуже дивувався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 14, 'Як зачули ж апо́столи, які в Єрусалимі були, що Боже Слово прийняла́ Самарі́я, то послали до них Петра та Івана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 15, 'А вони, як прийшли, помолились за них, щоб Духа Святого вони прийняли́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 16, 'бо ще ні на о́дного з них Він не схо́див, а були вони тільки охрищені в Ім\'я́ Господа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 17, 'Тоді на них руки поклали, і прийняли́ вони Духа Святого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 18, 'Як побачив же Си́мон, що через наклада́ння апо́стольських рук Святий Дух подається, то приніс він їм гроші,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 19, 'і сказав: „Дайте й мені таку вла́ду, щоб той, на кого́ покладу́ свої руки, одержав би Духа Святого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 20, 'Та промовив до нього Петро: „Нехай згине з тобою те срібло твоє, бо ти ду́мав набути дар Божий за гроші!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 21, 'У цім ділі нема тобі частки ні уділу, бо серце твоє перед Богом не слушне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 22, 'Тож покайся за це лихе ді́ло своє, і проси Господа, — може про́щений буде тобі за́мір серця твого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 23, 'Бо я бачу, що ти пробува́єш у жо́вчі гіркі́й та в пу́тах неправди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 24, 'А Си́мон озвався й сказав: „Помоліться за мене до Господа, щоб мене не спіткало нічого з того, про що ви говорили“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 25, 'А вони ж, засвідчивши, і Слово Господнє звістивши, повернулись до Єрусалиму, і звіщали Єва́нгелію в багатьох самарійських осе́лях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 26, 'А ангол Господній промовив Пилипові, кажучи: „Устань та на пі́вдень іди, на дорогу, що від Єрусалиму до Га́зи спускається, — порожня вона“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 27, 'І, вставши, пішов він. І ось муж етіо́пський, скопе́ць, вельможа Канда́ки, цариці етіопської, що був над усіма́ її ска́рбами, що до Єрусалиму прибув поклонитись,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 28, 'вертався, і, сидючи́ на пово́зі своїм, читав пророка Ісаю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 29, 'А Дух до Пилипа промовив: „Підійди, та й пристань до цього пово́зу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 30, 'Пилип же підбіг і почув, що той читає пророка Ісаю, та й спитав: „Чи розумієш, що́ ти читаєш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 31, 'А той відказав: „Як же мо́жу, як ніхто не напу́тить мене?“І впросив він Пилипа піднятись та сісти з ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 32, 'А слово Писа́ння, що його він читав, було це: „Як вівцю́ на заріз Його ве́дено, і як ягня супроти стрижія́ безголосе, так Він не відкрив Своїх уст!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 33, 'У прини́женні суд Йому віднятий був, а про рід Його хто розповість? Бо життя Його із землі забирається“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 34, 'Відізвався ж скопе́ць до Пилипа й сказав: „Благаю тебе, — це про ко́го говорить пророк? Чи про себе, чи про іншого кого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 35, 'А Пилип відкрив у́ста свої, і, зачавши від цього Писа́ння, благовістив про Ісуса йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 36, 'І, як шляхо́м вони їхали, прибули́ до якоїсь води. І озвався скопець: „Ось вода. Що мені заважає христитись?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 37, 'А Пилип відказав: „Якщо віруєш із повного серця свого, то можна“. А той відповів і сказав: „Я вірую, що Ісус Христос — то Син Божий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 38, 'І звелів, щоб по́віз спинився. І оби́два — Пилип та скопе́ць — увійшли до води, і охристив він його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 39, 'А коли вони вийшли з води, Дух Господній Пилипа забрав, і скопе́ць уже більше не бачив його. І він їхав, радіючи, шляхом своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 40, 'А Пилип опинився в Азо́ті, і, переходячи, звіщав Єва́нгелію всім містам, аж поки прийшов у Кесарі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'А Савл, іще дишучи грізьбою й убивством на учнів Господніх, приступивши до первосвященика,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'попросив від нього листи́ у Дама́ск синагогам, щоб, коли зна́йде яких чоловіків та жінок, що тієї дороги вони, то зв\'язати й приве́сти до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'А коли він ішов й наближа́вся до Дамаску, то ось нагло ося́яло світло із неба його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'а він повали́вся на землю, і голос почув, що йому говорив: „Са́вле, Са́вле, — чому́ ти Мене переслідуєш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'А він запитав: „Хто Ти, Пане?“А Той: „Я Ісус, що Його переслідуєш ти. Трудно тобі бити ногою колючку! “');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'А він, затрусившися та налякавшися, каже: „Чого, Господи, хочеш, щоб я вчинив?“А до нього Господь: „Уставай, та до міста подайся, а там тобі скажуть, що́ маєш робити!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'А люди, що йшли з ним, онімілі стояли, бо вони чули голос, та ніко́го не бачили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Тоді Савл підвівся з землі, і хоч очі розплю́щені мав, ніко́го не бачив... І за руку його повели́ й привели́ до Дамаску.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'І три дні невидю́щий він був, і не їв, і не пив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'А в Дама́ску був учень один, на йме́ння Ана́ній. І Господь у видінні промовив до нього: „ Ана́нію!“А він відказав: „Ось я, Господи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Господь же до нього: „Устань, і піди на вулицю, що Про́стою зветься, і пошукай в домі Юдовім Са́вла на йме́ння, тарся́нина, ось бо він мо́литься,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'і мужа в видінні він бачив, на йме́ння Ананія, що до нього прийшов і руку на нього поклав, щоб став він видю́щий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Відповів же Ана́ній: „Чув я, Господи, від багатьох про цього́ чоловіка, скільки зла він учинив в Єрусалимі святим Твоїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'І тут має вла́ду від первосвящеників, щоб в\'язати усіх, хто кли́че Ім\'я́ Твоє“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'І промовив до нього Господь: „Іди, бо для Мене — посу́дина ви́брана він, щоб носити Ім\'я́ Моє перед наро́дами, і царями, і синами Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Бо Я покажу́ йому, скільки має він витерпіти за Ім\'я́ Моє“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'І Ананій пішов, і до дому ввійшов, і руки поклавши на нього, промовив: „Са́вле брате, Господь Ісус, що з\'явився тобі на дорозі, якою ти йшов, послав ось мене, щоб став ти видю́щий, і напо́внився Духа Святого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'І хвилі тієї відпала з очей йому ніби луска́, і зараз видю́щий він став... І, вставши, охристився,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'і, прийнявши поживу, на силах зміцнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'І він зараз зачав у синагогах звіщати про Ісуса, що Він — Божий Син,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'І дивом усі дивувалися, хто чув, і говорили: „Хіба це не той, що переслідував в Єрусалимі визна́вців оцього Ім\'я́, та й сюди не на те він прибув, щоб отих пов\'язати й приве́сти до первосвящеників?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'А Савл іще більше зміцнявся, і непокоїв юдеїв, що в Дамаску жили, удово́днюючи, що Той — то Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'А як ча́су минуло доволі, юдеї змовилися його вбити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'та Са́влові стала відо́ма їхня змова. А вони день і ніч чатува́ли в воро́тях, щоб убити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Тому учні забрали його вночі, та й із муру спустили в коші́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'А коли він до Єрусалиму прибув, то силкува́вся пристати до учнів, та його всі ляка́лися, не вірячи, що він учень.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Варнава тоді взяв його та й привів до апо́столів, і їм розповів, як дорогою той бачив Господа, і як Він йому промовляв, і як сміли́во навчав у Дамаску в Ісусове Йме́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'І він із ними входив і вихо́див до Єрусалиму, і відважно звіщав в Ім\'я́ Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 29, 'Він також розмовляв й сперечався з огре́ченими, а вони намагалися вбити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 30, 'Тому браття, довідавшися, відвели́ його до Кесарі́ї, і до Та́рсу його відіслали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 31, 'А Церква по всій Юдеї, і Галілеї, і Самарі́ї мала мир, будуючись і ходячи в стра́сі Господньому, і сповня́лася втіхою Духа Святого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 32, 'І сталося, як Петро всіх обходив, то прибув і до святих, що ме́шкали в Лі́дді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 33, 'Знайшов же він там чоловіка одно́го, на йме́ння Ене́й, що на ліжку лежав вісім років, — він розсла́блений був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 34, 'І промовив до нього Петро: „Енею, тебе вздоровляє Ісус Христос. Уставай, і постели́ собі сам!“І той зараз устав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 35, 'І його оглядали усі, хто мешкав у Лі́дді й Саро́ні, які навернулися до Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 36, 'А в Йоппі́ї була одна у́чениця, на ймення Таві́та, що в перекладі Са́рною зветься. Вона повна була добрих вчинків та ми́лостині, що чинила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 37, 'І трапилося тими днями, що вона занедужала й умерла. Обмили ж її й покла́ли в го́рниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 38, 'А що Лі́дда лежить недалеко Йоппі́ї, то учні, прочувши, що в ній пробуває Петро, послали до нього двох му́жів, що благали: „Не гайся прибути до нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 39, 'І, вставши Петро, пішов із ними. А коли він прибув, то ввели його в го́рницю. І обступили його всі вдови́ці, плачучи та показуючи йому су́кні й плащі, що їх Сарна робила, як із ними була́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 40, 'Петро ж із кімна́ти всіх ви́провадив, і, ставши навко́лішки, помолився, і, звернувшись до тіла, промовив: „Тавіто, вставай!“А вона свої очі розплю́щила, і сіла, уздрівши Петра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 41, 'Він же руку подав їй, і підвів її, і закли́кав святих і вдовиць, та й поставив живою її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 42, 'А це стало відо́ме по ці́лій Йоппі́ї, і багато-хто в Господа ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 43, 'І сталось, що він багато днів пробув у Йоппі́ї, в одно́го гарбарника Си́мона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Проживав же один чоловік у Кесарі́ї, на йме́ння Корни́лій, сотник по́лку, що звавсь Італійським.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'З усім домом своїм він побожний був та богобійний, подавав людям щедру ми́лостиню, і за́вжди Богові молився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Явно він у видінні, десь коло години дев\'ятої дня, бачив Ангола Божого, що до нього зійшов і промовив йому: „Корни́лію!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Він поглянув на нього й жахнувся, й сказав: „Що, Господи?“Той же йому відказав: „Моли́тви твої й твоя ми́лостиня перед Богом згадалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Тепер же пошли до Йоппі́ї людей, та й приклич Си́мона, що зветься Петром.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Він гостює в одно́го гарбарника Си́мона, що дім має при морі. Він скаже тобі, що́ ти маєш робити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Коли ж Ангол, що йому говорив, відійшов, той закликав двох із своїх слуг домо́вих, і вояка́ богобійного з тих, що служили при ньому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'і розповів їм усе та й послав їх в Йоппі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'А наступного дня, як у дорозі були́ вони та наближа́лись до міста, Петро вийшов на го́рницю, щоб помолитись, о годині десь шостій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'І став він голодний, і їсти схотів. Як йому ж готували, захо́плення на нього найшло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'і бачить він небо відкрите, і якуюсь посу́дину, що схо́дила, немов простира́ло велике, яка, за чотири кінці прив\'язана, спускалась додолу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'У ній же знахо́дились чотириногі всілякі, і зе́мне гаддя, і небесні пташки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'І голос почувся до нього: „Устань, заколи, Петре, і їж!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'А Петро відказав: „Жа́дним способом, Господи, — бо ніко́ли не їв я нічого оги́дного чи то нечистого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'І знов голос удруге до нього: „Що від Бога очи́щене, не вважай за оги́дне того́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'І це сталося тричі, і посу́дина знов була взята на небо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Як Петро ж у собі бенте́жився, що́ б то значило те видіння, що бачив, то ось посланці́ від Корнилія, розпитавши про Си́монів дім, спинилися перед ворі́тьми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'і спиталися, крикнувши: „Чи то тут сидить Си́мон, що зветься Петро?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Як Петро ж над видінням роздумував, Дух промовив до нього: „Онде три чоловіки шукають тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Але встань і зійди, і піди з ними без жодного су́мніву, бо то Я їх послав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'І зійшовши Петро до тих му́жів, промовив: „Ось я той, що його ви шукаєте. З якої причини прийшли ви?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'А вони відказали: „Сотник Корни́лій, муж праведний та богобійний, слави доброї в усього люду юдейського, святим а́нголом був у видінні наставлений, щоб до дому свого покли́кати тебе та послухати слів твоїх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Тоді він покликав й гостинно прийняв їх. А другого дня він устав та й із ними пішов; також дехто з братів із Йоппі́ї пішли з ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'І назавтра прийшли вони до Кесарі́ї. А Корнилій чекав їх, рідню й близьких дру́зів покликавши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'А як увіходив Петро, Корнилій зустрінув його, і до ніг йому впав і вклонився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Та Петро його підвів, промовляючи: „Устань, бо й сам я люди́на!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'І, розмовляючи з ним, увійшов, і знайшов багатьох, що зібралися,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'і промовив до них: „Ви знаєте, що не вільно юдеєві приставати й прихо́дити до чужани́ці. Та відкрив мені Бог, щоб я жодну люди́ну не мав за огидну чи то за нечисту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Тому я без вага́ння прибув, як покликано. Тож питаю я вас: З якої причини ви слали по мене?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'А Корни́лій сказав: „Четвертого дня аж до цієї години я по́стив, а о дев\'ятій годині молився я в домі своїм. І ото, перед мене став муж у блискучій одежі');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'й сказав: „Корнилію, почута молитва твоя, і твої ми́лостині перед Богом згадалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Тож пошли до Йоппі́ї, і приклич Си́мона, що зветься Петром. Він гостює в гарба́рника Си́мона, у госпо́ді край моря, — він при́йде й розпові́сть тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Я зараз по тебе послав, — ти добре зробив, що прийшов. Тож тепер перед Богом ми всі стоїмо́, щоб почути все те, що Господь наказав був тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'А Петро відкрив у́ста свої та й промовив: „Пізнаю́ я поправді, що „не дивиться Бог на обличчя“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'але в кожнім наро́ді приємний Йому, хто боїться Його й чинить праведність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Він слово послав для Ізраїлевих синів, благові́стячи мир через Ісуса Христа, що Госпо́дь Він усім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Ви знаєте справу, що по всій Юдеї була й зачала́сь з Галілеї, після хрищення, що Іван проповідував,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Ісуса, що був із Назаре́ту, як помазав Його Святим Духом і силою Бог. І ходив Він, добро чинячи й усіх уздоро́влюючи, кого поневолив диявол, бо Бог був із Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'І ми свідки всьому, що́ Він учинив у Юдейському кра́ї та в Єрусалимі, — та вбили Його, на дереві повісивши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 40, 'Але Бог воскресив Його третього дня, і дав Йому, щоб з\'явився,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 41, 'не всьому наро́дові, але наперед Богом вибраним свідкам, нам, що з Ним їли й пили, як воскрес Він із мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 42, 'І Він нам звелів, щоб наро́дові ми проповідували та засві́дчили, що то Він є призначений Богом Суддя для живих і для мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 43, 'Усі пророки свідку́ють про Нього, що кожен, хто вірує в Нього, одержить про́щення гріхів Його Йме́нням“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 44, 'Як Петро говорив ще слова́ ці, зли́нув Святий Дух на всіх, хто слухав слова́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 45, 'А обрі́зані віруючі, що з Петром прибули́, здивувалися дивом, що дар Духа Святого пролився також на пога́н!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 46, 'Бо чули вони, що мовами різними ті розмовляли та Бога звели́чували... Петро тоді відповів:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 47, '„Чи хто може заборонити христитись водою оцим, що оде́ржали Духа Святого, як і ми?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 48, 'І звелів охриститися їм у Йме́ння Ісуса Христа. Тоді просили його позостатися в них кілька днів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Почули ж апо́столи й браття, що в Юдеї були, що й погани прийняли́ Слово Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'І, як Петро повернувся до Єрусалиму, з ним стали змагатися ті, хто з обрі́зання,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'кажучи: „Чого́ ти ходив до людей необрі́заних та споживав із ними?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Петро ж розпочав і їм розповів за порядком, говорячи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, '„Був я в місті йоппі́йськім і молився, і бачив в захо́пленні видіння: якась посу́дина схо́дила, немов простира́ло велике, яка, за чотири кінці прив\'я́зана, спускалася з неба й підійшла аж до мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Зазирнувши до неї, я поглянув, і побачив там чотириногих землі, і звірів, і гаддя, і небесних пташок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'І голос почув я, що мені промовляв: „Устань, Петре, заколи та й їж!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'А я відказав: „Жодним способом, Господи, — бо ніко́ли нічого оги́дного чи то нечистого в у́ста мої не вхо́дило!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'І відповів мені голос із неба вдруге: „Що від Бога очищене, не вважай за оги́дне того́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'І це сталося тричі, і все знов було взяте на небо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'І ось три чоловіки, посланці з Кесарі́ї до мене, перед домом, де був я, спинилися за́раз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'І сказав мені Дух іти з ними без жодного сумніву. Зо мною ж пішли й оці шестеро браття, і ввійшли ми до дому того чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'І він нам розповів, як у домі своїм бачив ангола, який став і сказав: „Пошли до Йоппі́ї, та приклич того Си́мона, що зветься Петром,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'він слова́ тобі скаже, якими спасешся і ти, і ввесь дім твій“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'А як я промовляв, зли́нув на них Святий Дух, як споча́тку й на нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'І я згадав слово Господнє, як Він говорив: „Іван ось водою христив, ви ж охрищені будете Духом Святим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Отож, коли Бог дав одна́ковий дар їм, як і нам, що ввірували в Господа Ісуса Христа, то хто́ ж я такий, щоб міг заперечити Богові?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'І, почувши таке, замовкли вони, і Бога хвалили, говорячи: „Отож, і поганам Бог дав покая́ння в життя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'А ті, хто розпоро́шився від переслідування, що зняло́ся було через Степа́на, перейшли навіть до Фінікі́ї, і Кі́пру, і Антіохі́ї, не звіщаючи сло́ва ніко́му, крім юдеїв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'А між ними були мужі деякі з Кіпру та з Кіріне́ї, що до Антіохі́ї прийшли, і промовляли й до греків, благові́стячи про Господа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'І Господня рука була з ними; і велике число їх увірувало, і навернулось до Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'І вістка про них досягла́ до вух єрусали́мської Церкви, і до Антіохі́ї послали Варнаву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'А він, як прийшов і благодать Божу побачив, звеселився, і всіх став просити, щоб серцем рішучим трималися Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Бо він добрий був муж, повний Духа Святого та віри. І прилучилось багато наро́ду до Господа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Після того подався Варна́ва до Та́рсу, щоб Са́вла шукати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'А знайшовши, привів в Антіохі́ю. І збирались у Церкві вони цілий рік, і навчали багато народу, і в Антіохі́ї найперш християнами на́звано учнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Прибули́ ж тими днями пророки від Єрусалиму до Антіохі́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'І встав один з них, на йме́ння Ага́в, і Духом прорік, що голод великий у ці́лому світі настане, як за Кла́вдія був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Тоді учні, усякий із своєї спроможности, постановили послати допомогу братам, що в Юдеї жили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Що й зробили, через руки Варнави та Са́вла, пославши до старших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'А Цар І́род тоді підні́с руки, щоб декого з Церкви гноби́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'І мечем він стяв Якова, брата Іванового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'А бачивши, що подо́балося це юдеям, він задумав схопи́ти й Петра. Були ж дні Опрі́сноків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'І, схопи́вши його, посадив до в\'язниці, і передав чотирьом чвіркам воякі́в, щоб його стерегли, бажаючи вивести людям його по Па́сці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Отож, у в\'язниці Петра стерегли, а Церква ре́вно молилася Богові за нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'А як Ірод хотів його ви́вести, Петро спав тієї ночі між двома́ вояка́ми, закутий у два ланцюги́, і сторо́жа пильнувала в\'язницю при две́рях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'І ось ангол Господній з\'явився, і в в\'язниці засяяло світло. І, доторкнувшись до боку Петрового, він збудив його, кажучи: „Мерщі́й встава́й!“І ланцюги́ йому з рук поспада́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'А ангол до нього промовив: „Підпережи́ся, і взуй санда́лі свої“. І він так учинив. І каже йому: „Зодягнися в плаща свого, та й за мною йди“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'І, вийшовши, він ішов услід за ним, і не знав, чи то правда, що робилось від ангола, бо ду́мав, що видіння він бачить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Як сторо́жу минули вони першу й другу, то прийшли до залізної брами, що до міста веде, — і вона відчинилась сама ім. І, вийшовши, пройшли одну вулицю, — і відступив ангол зараз від нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Сказав же Петро, оприто́мнівши: „Тепер знаю правдиво, що Господь послав Свого ангола, і видер мене із рук Іродових та від усього чека́ння народу юдейського“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'А зміркувавши, він прийшов до сади́би Марії, матері Івана, званого Ма́рком, де багато зібралося й молилося.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'І як Петро в фіртку брами постукав, то вийшла послухати служни́ця, що звалася Ро́да,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'та голос Петрів розпізнавши, вона з радощів не відчинила воріт, а прибігши, сказала, що Петро при воро́тях стоїть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'А вони їй сказали: „Чи ти навісна́?“Та вона запевняла своє́, що є так. Вони ж говорили: „То ангол його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'А Петро й далі стукав. Коли ж відчинили, вони його вгледіли та й дивувалися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Махнувши ж рукою до них, щоб мовчали, він їм розповів, як Господь його вивів із в\'язниці. І сказав: „Сповістіть про це Якова й браттю“. І, вийшовши, він до іншого місця пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Коли ж настав день, поміж вояка́ми зчинилась велика тривога, що́ то сталось з Петром.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'А Ірод, пошукавши його й не знайшовши, віддав варту під суд, і звелів їх стра́тити. А сам із Юдеї відбув в Кесарі́ю, і там перебува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'А І́род розгніваний був на тиря́н та сидо́нян. І вони однодушно до нього прийшли, і вблагали царсько́го постельника Вла́ста, та й миру просили, бо їхня земля годувалась з царсько́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Дня ж призначеного І́род убрався в одежу царську́, і на підвищенні сів та й до ни́х говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'А на́товп кричав: „Голос Божий, а не лю́дський!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'І ангол Господній ура́зив знена́цька його, бо він не віддав слави Богові. І черва́ його з\'їла, і він умер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Слово ж Боже росло та помно́жувалось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'А Варнава та Савл, службу виконавши, повернулись із Єрусалиму, узявши з собою Івана, що про́званий Ма́рком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'А в Антіохі́ї, у та́мошній Церкві були ці пророки та вчителі́: Варнава й Семен, званий Ні́ґер, і кіріне́янин Луцій, і Манаї́л, що був вигодуваний із тетра́рхом Іродом, та ще Савл.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Як служили ж вони Господе́ві та по́стили, прорік Святий Дух: „Відділіть Варнаву та Са́вла для Мене на справу, до якої покликав Я їх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Тоді, попо́стивши та помолившись, вони руки поклали на них, і відпустили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Вони ж, послані бувши від Духа Святого, прийшли в Селевкі́ю, а звідти до Кіпру відпли́нули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Як були ж в Саламі́ні, то звіщали вони Слово Боже по синагогах юдейських; до по́слуг же мали й Івана.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'А коли перейшли аж до Па́фи ввесь о́стрів, то знайшли ворожби́та одно́го, лжепророка юде́янина, йому на ім\'я́ Варісу́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Він був при проко́нсулі Сергії Па́влі, чоловіку розумнім. Той закликав Варнаву та Са́вла, і прагнув послухати Божого Слова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Але їм опирався Елі́ма ворожби́т той, — бо ім\'я́ його перекладається так, — і намагавсь відвернути від віри проко́нсула.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Але Савл, що й Павло він, перепо́внився Духом Святим і на нього споглянув,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'і промовив: „О сину дияволів, повний всякого пі́дступу та всілякої злости, ти во́рогу всякої правди! Чи не перестанеш ти плутати про́стих Господніх доріг?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'І тепер ось на тебе Господня рука, — ти станеш сліпий, і сонця бачити не будеш до ча́су!“І миттю обняв того мо́рок та те́мрява, і став він ходити навпо́мацки та шукати повода́тора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Тоді той проко́нсул, як побачив, що́ сталося, увірував, і дивувався науці Господній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'І, як від Па́фа Павло й ті, хто з ним був, відпливли́, то вони прибули́ в Памфілійську Пергі́ю. А Іван, відлучившись від них, повернувся до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'А вони, пішовши з Пергії, прийшли до Пісідійської Антіохії, і дня суботнього до синагоги ввійшли й посідали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'А по відчита́нні Зако́ну й Пророків, старші́ синагоги послали до них, переказуючи: „Мужі-браття, якщо маєте слово потіхи для люду, промовте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Тоді Павло встав, і давши знака рукою, промовив: „Послухайте, мужі ізра́їльтяни, та ви, богобійні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Бог цих Ізраїлевих людей вибрав Собі отців наших, і підвищив наро́д, як він перебува́в у єгипетськім кра́ї, і рукою поту́жною вивів їх із нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'і літ із сорок Він їх годував у пустині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'а вигубивши сім наро́дів в землі ханаа́нській, поділив жеребко́м їхню землю між ними,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'ма́йже що по чотириста й п\'ятидесяти ро́ках. Після того аж до Самуїла пророка Він їм суддів дава́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'А потім забажали царя, і Бог дав їм Сау́ла, сина Кі́сового, мужа з Веніями́нового племени, на чотири десятки років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'А його віддаливши, поставив царем їм Дави́да, про якого й сказав, засвідчуючи: „Знайшов Я Давида, сина Єссе́євого, чоловіка за серцем Свої́м, що всю волю Мою він виконувати бу́де“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'За обітницею, із його насіння підняв Бог Ісуса, як спасі́ння Ізраїлеві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'як Іван — перед самим прихо́дом Його — усьо́му наро́дові Ізраїлевому проповідував хрищення на покая́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'А коли свою путь Іван виконав, то він промовляв: „Я не Той, за Кого́ ви мене вважаєте, але йде он за мною, що Йому розв\'язати ремінця́ від узуття́ Його я недостойний“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 26, 'Мужі-браття, сини роду Авраамового, та хто богобоя́зний із вас! Для вас було по́слане слово спасі́ння цього́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 27, 'Бо ме́шканці Єрусалиму та їхня старши́на Його не пізнали, а пророчі слова — які щосуботи читаються — вони спо́внили при́судом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 28, 'і хоч жа́дної провини смерте́льної в Ісусі вони не знайшли, все ж просили Пилата вбити Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 29, 'Коли ж усе ви́повнилось, що про Нього написане, то зняли Його з дерева, та й до гробу поклали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 30, 'Але Бог воскресив Його з мертвих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 31, 'Він з\'являвся багато днів тим, що були поприхо́дили з Ним із Галілеї до Єрусалиму, і що тепер вони свідки Його перед лю́дьми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 32, 'І ми благовістимо́ вам ту обі́тницю, що да́на була нашим отцям,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 33, 'що її нам, їхнім дітям, Бог виконав, воскресивши Ісуса, як написано в другім псалмі: „Ти Мій Син, — Я сьогодні Тебе породив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 34, 'А що Він воскресив Його з мертвих, щоб більш не вернувся в зотлі́ння, те так заповів: „Я дам вам ті милості, що обіцяні вірно Давиду були!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 35, 'Тому́ то й деінде говорить: „Не даси Ти Своєму Святому побачити тлі́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 36, 'Бо Давид, що ча́су свого послужив волі Божій, спочив, і злучився з отцями своїми, і тлі́ння побачив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 37, 'Але Той, що Бог воскресив Його з мертвих, тлі́ння не побачив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 38, 'Отже, мужі-браття, хай відо́мо вам буде, що про́щення гріхів через Нього звіщається вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 39, 'І в усім, у чому ви не могли ви́правдатись Зако́ном Мойсеєвим, через Нього випра́вдується кожен віруючий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 40, 'Отож, стережіться, щоб на вас не прийшло, що в Пророків провіщене:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 41, '„Дивіться, погордю́щі, і дивуйтеся та пощезайте, бо Я ді́ло роблю́ за днів ваших, те ді́ло, що йому не повірите ви, якби хто розповів вам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 42, 'А як стали вихо́дити вони, то їх про́шено, щоб на другу суботу до них говорили ті самі слова́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 43, 'А коли розійшлась синагога, то багато з юдеїв та й із нововірців побожних пішли за Павло́м та Варнавою, а вони промовляли до них і намовляли їх перебувати в благодаті Божій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 44, 'А в наступну суботу зібралося майже все місто послухати Божого Сло́ва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 45, 'Як юдеї ж побачили на́товп, то напо́внились за́здрощів, і стали перечити мові Павла та богозневажати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 46, 'Тоді Павло та Варнава мужньо промовили: „До вас перших потрібно було говорить Слово Боже; та коли ви його відкидаєте, а себе вважаєте за недостойних вічного життя, то ось до поган ми зверта́ємось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 47, 'Бо так заповів нам Господь: „Я світлом поставив Тебе для поган, щоб спасі́нням Ти був аж до кра́ю землі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 48, 'А погани, почувши таке, раділи та Слово Господнє хвалили. І всі ті, хто призначений був в життя вічне, увірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 49, 'І ширилось Сло́во Господнє по ці́лій країні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 50, 'Юдеї ж підбили побожних впливових жінок та значніших у місті, і зняли́ переслі́дування на Павла та Варнаву, та й вигнали їх із своєї землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 51, 'Вони ж, обтрусивши із ніг своїх порох на них, подалися в Іконі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 52, 'А учні сповня́лися радощів і Духа Святого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 1, 'І трапилось, що в Іконі́ї вкупі ввійшли вони до синагоги юдейської, і промовили так, що бе́зліч юдеїв й огре́чених увірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 2, 'Невірні ж юдеї підбу́рили та роз\'ятри́ли душі поган на братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 3, 'Та проте довгий час пробули́ вони там, промовляючи мужньо про Господа, що свідо́цтво давав слову благода́ті Своєї і робив, щоб знаме́на та чу́да чинились їхніми руками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 4, 'А в місті наро́д поділився, — і пристали одні до юдеїв, а інші тримались апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 5, 'Коли ж кинулися ті погани й юдеї з своїми старши́ми, щоб зневажити їх та камінням побити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 6, 'то, дізнавшись про це, вони повтікали до міст лікао́нських, до Лі́стри та Де́рвії, та в околиці їхні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 7, 'і Єва́нгелію там звіща́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 8, 'А в Лі́стрі сидів один чоловік, безвладний на ноги, що кривий був з утроби своєї матері, і ніко́ли ходити не міг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 9, 'Він слухав, як Павло́ говорив, який пильно на нього споглянув, і побачив, що має він віру вздоровленим бути,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 10, 'то голосом гучни́м промовив: „Устань просто на ноги свої!“А той скочив, і ходити почав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 11, 'А люди, побачивши, що́ Павло́ вчинив, підне́сли свій голос, говорячи по-лікао́нському: „Боги людям вподі́бнились, та до нас ось зійшли!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 12, 'І Варнаву вони звали Зе́всом, а Герме́сом Павла, бо він провід мав у слові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 13, 'А жрець Зе́вса, що святиня його перед містом була, припрова́див бики та вінки до воріт, та й з наро́дом прино́сити жертву хотів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 14, 'Та коли про це почули апо́столи Варнава й Павло, то роздерли одежі свої, та й кинулися між наро́д, кричачи');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 15, 'та говорячи: „Що́ це робите, люди? Таж і ми такі самі смерте́льні, подібні вам люди, і благовістимо́ вам, — від оцих ось марно́т наверну́тись до Бога Живого, що створив небо й землю, і море, і все, що в них є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 16, 'За минулих родів попустив Він усім народам, щоб ходили стежка́ми своїми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 17, 'але́ не зоставив Себе Він без свідчення, добро чинячи: подавав нам із неба дощі та врожайні часи́, та напо́внював їжею й радощами серця наші“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 18, 'І, говорячи це, зале́две спинили наро́д не приносити їм же́ртов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 19, 'А з Антіохі́ї та з Іконі́ї посхо́дились юдеї, і, підбуривши на́товп, камінням побили Павла, та й за місто геть виволікли, мавши думку, що вмер він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 20, 'Коли ж учні його оточили, то він устав, та й вернувся до міста. А наступного дня він відбув із Варнавою в Де́рвію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 21, 'І, як звістили Єва́нгелію тому містові, і учнів багато придбали, вони повернулися в Лі́стру, та в Іконі́ю, та в Антіохі́ю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 22, 'душі учнів зміцняючи, просячи перебувати в вірі, та навча́ючи, що через великі у́тиски треба нам вхо́дити у Боже Царство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 23, 'І рукопокла́ли їм пресві́терів по Церквах, і помолилися з по́стом та й їх передали Господе́ві, в Якого ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 24, 'Як вони ж перейшли Пісіді́ю, прибули в Памфілі́ю;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 25, 'і, звістивши Господнє Слово в Пергі́ї, вони в Атталі́ю ввійшли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 26, 'а звідти поплинули в Антіохі́ю, звідки були благода́ті Божій віддані на ді́ло, що його й закінчи́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 27, 'А прибувши та скликавши Церкву, вони розповіли, як багато вчинив Бог із ними, і що відкрив двері віри поганам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 28, 'І перебува́ли вони немали́й час із учнями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 1, 'А дехто, що з Юдеї прийшли, навчали братів: „Якщо ви не обріжетеся за звича́єм Мойсеєвим, то спастися не можете“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 2, 'Коли ж суперечка повстала й чимале змага́ння в Павла́ та в Варнави з ними, то постановили, щоб Павло́ та Варнава, та дехто ще інший із них, пішли в справі цій до апо́столів й старших у Єрусалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 3, 'Тож вони, відпроваджені Церквою, ішли через Фінікі́ю та Самарі́ю, розповідаючи про поганське наве́рнення, і радість велику чинили всім браттям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 4, 'Коли ж в Єрусалим прибули́ вони, були прийняті Церквою, та апо́столами, та старши́ми, і вони розповіли́, як багато вчинив Бог із ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 5, 'Але дехто, що вві́рували з фарисейської партії, устали й сказали, що потрібно поганів обрі́зувати й наказати, щоб Зако́на Мойсеєвого берегли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 6, 'І зібрались апо́столи й старші, щоб розглянути справу оцю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 7, 'Як велике ж змага́ння повстало, Петро встав і промовив до них: „Мужі-браття, ви знаєте, що з давнішніх днів вибрав Бог поміж нами мене́, щоб погани почули слово Єва́нгелії через у́ста мої, та й увірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 8, 'І засві́дчив їм Бог Серцезнавець, давши їм Духа Святого, як і нам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 9, 'і між нами та ними різни́ці Він жодної не вчинив, очистивши вірою їхні серця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 10, 'Отож, чого Бога тепер споку́шуєте, щоб учням на шию покласти ярмо́, якого ані наші отці, ані ми не здола́ли поне́сти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 11, 'Та ми віруємо, що спасе́мося благода́ттю Господа Ісуса так само, як і вони“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 12, 'І вся громада замовкла, і слухали пильно Варнаву й Павла, що розповідали, які то знаме́на та чу́да вчинив через них Бог між поганами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 13, 'Як замовкли ж вони, то Яків озвався й промовив: „Мужі-браття, послухайте також мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 14, 'Си́мон ось розповів, як зглянувся Бог від поча́тку, щоб вибрати люд із поганів для Йме́ння Свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 15, 'І пророчі слова́ з цим погоджуються, як написано:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 16, '„Пото́му вернуся, і відбуду́ю Давидову ски́нію занепалу, і відбудую руїни її, і наново поставлю її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 17, 'щоб шукали Господа люди зосталі та всі наро́ди, над якими Ім\'я́ Моє кликано, — говорить Господь, що чинить це все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 18, 'Господе́ві відвіку відо́мі всі вчинки Його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 19, 'Тому ду́маю я, щоб не турбувати поган, що до Бога наверта́ються,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 20, 'але написати до них, щоб стри́мувались від занечи́щення і́дольського, та від блу́ду, і задушени́ни, і від кро́ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 21, 'Бо своїх проповідників має Мойсей по містах здавенда́вна, і щосуботи читають його в синагогах“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 22, 'Тоді постановили апо́столи й старші з ці́лою Церквою вибрати му́жів із них, і послати до Антіохі́ї з Павло́м та Варна́вою Юду, що зветься Варса́вва, і Силу, му́жів проводирів між братами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 23, 'написавши свої́ми руками оце́: „Апостоли й старші брати до братів, що з поган в Антіохі́ї, і Си́рії, і Кілікі́ї: Вітаємо вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 24, 'Через те, що ми чули, що деякі з вас, яким ми того не дору́чували, стурбували наукою вас, і захитали вам душі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 25, 'то ми постановили однодушно, зібравшися, щоб о́браних мужів послати до вас із коханими нашими — Варнавою та Павло́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 26, 'людьми́ тими, що ду́ші свої віддали́ за Ім\'я́ Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 27, 'Тож ми Юду та Силу послали, що вияснять усно те саме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 28, 'Бо зво́лилось Духові Святому і нам, — тягару́ вже нія́кого не наклада́ти на вас, окрім цього необхідного:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 29, 'стри́муватися від ідольських жертов та крови, і задушени́ни, та від блу́ду. Оберегаючися від того, ви зробите добре. Бувайте здорові!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 30, 'Посланці́ ж прийшли в Антіохі́ю, і, зібравши наро́д, доручили листа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 31, 'А перечитавши, раділи з поті́шення того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 32, 'А Юда та Сила, самі бувши пророками, частим словом підбадьо́рували та зміцняли братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 33, 'А як перебули́ вони там якийсь час, то брати їх відпустили з миром до тих, хто їх вислав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 34, 'Але Сила схотів лиши́тися там, а Юда вернувся до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 35, 'А Павло з Варнавою в Антіохії жили́, навчаючи та благові́стячи ра́зом із іншими багатьома́ Слово Господнє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 36, 'А по декількох днях промовив Павло́ до Варнави: „Ходімо знов, і відвідаймо наших братів у кожному місті, де ми провіщали Слово Господнє, — як вони пробува́ють“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 37, 'А Варнава хотів був узяти з собою Івана, що зва́ний був Ма́рком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 38, 'Та Павло́ вважав за потрібне не брати з собою того, хто від них відлучився з Памфілії, та з ними на працю не йшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 39, 'І повстала незгода, і розлучились вони між собою. Тож Варнава взяв Ма́рка, і попли́нув до Кіпру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 40, 'А Павло вибрав Силу й пішов, Божій благода́ті братами доручений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 41, 'І проходив він Си́рію та Кілікі́ю, Церкви́ зміцнюючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 1, 'І прибув він у Де́рвію й Лі́стру. І ото був там один учень, на ім\'я́ Тимофій, син наве́рненої однієї юде́янки, а ба́тько був ге́ллен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 2, 'Добре свідо́цтво про нього давали брати, що були в Лі́стрі та в Іконі́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 3, 'Павло захотів його взяти з собою, — і, взявши, обрізав його через юдеїв, що були в тих місцях, бо всі знали про батька його, що був ге́ллен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 4, 'Як міста ж перехо́дили, то їм передавали, щоб вони берегли оті постано́ви, які видали в Єрусалимі апо́столи та старші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 5, 'А Церкви́ змі́цнювалися в вірі, і щоденно зростали кі́лькістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 6, 'А що Дух Святий їм не звелів провіщати слово в Азії, то вони перейшли через Фрігію та через країну гала́тську.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 7, 'Дійшовши ж до Мі́зії, хотіли піти до Віті́нії, та їм не дозволив Дух Ісусів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 8, 'Обминувши ж Мі́зію, прибули́ до Троа́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 9, 'І Павлові з\'явилось видіння вночі: якийсь македо́нянин став перед ним і благав його, кажучи: „Прийди в Македо́нію, і нам поможи!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 10, 'Як побачив він це видіння, то ми зараз хотіли піти в Македо́нію, зрозумівши, що Госпо́дь нас покликав звіщати їм Єва́нгелію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 11, 'Тож відпливши з Троа́ди, прибули́ ми навпрост у Самотра́кію, а другого дня до Неа́поля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 12, 'звідтіля ж у Фили́пи, що є перше місто-осада в тій частині Македонії. І пробули́ ми в цім місті днів кілька.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 13, 'Дня ж суботнього вийшли ми з міста над річку, де, за звича́єм, було місце молитви, і, посідавши, розмовляли з жінками, що посхо́дились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 14, 'Прислуха́лася й жінка одна, що звалася Лі́дія, купчиха кармази́ном з міста Тіяті́р, що Бога вона шанувала. Господь же їй серце відкрив, щоб уважати на те, що Павло говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 15, 'А коли охристилась вона й її дім, то благала нас, кажучи: „Якщо ви признали, що вірна я Господе́ві, то прийдіть до госпо́ди моєї й живіть“. І змусила нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 16, 'І сталось, як ми йшли на молитву, то нас перестріла служни́ця одна, що мала віщу́нського духа, яка ворожби́тством давала великий прибу́ток панам своїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 17, 'Вона йшла слідкома́ за Павлом та за нами, і кричала, говорячи: „Оці люди — це раби Всеви́шнього Бога, що вам провіщають дорогу спасі́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 18, 'І багато днів вона це робила. І обуривсь Павло, і, обернувшись, промовив до духа: „У Ім\'я́ Ісуса Христа велю я тобі — вийди з неї!“І того ча́су той вийшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 19, 'А пани її, бачивши, що пропала надія на їхній прибу́ток, схопи́ли Павла й Силу, і потягли їх на ринок до старши́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 20, 'Коли ж їх привели́ до начальників, то сказали: „Ці люди, юдеї, наше місто бунтують,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 21, 'і навчають звича́їв, яких нам, римля́нам, не годиться приймати, ані вико́нувати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 22, 'І на́товп піднявся на них. А начальники здерли одежу із них, та звеліли їх рі́зками сі́кти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 23, 'І, завдавши багато їм ран, посадили в в\'язницю, наказавши в\'язничному дозо́рцеві, щоб їх пильно стеріг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 24, 'Одержавши такого нака́за, той їх повкида́в до внутрішньої в\'язниці, а їхні но́ги забив у коло́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 25, 'А півні́чної пори Павло й Сила молилися, і Богові співали, а ув\'я́знені слухали їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 26, 'І ось на́гло повстало велике трясі́ння землі, аж основи в\'язни́чні були захита́лися! І повідчинялися зараз усі двері, а кайда́ни з усіх поспада́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 27, 'Як прокинувся ж сторож в\'язничний, і побачив відчинені двері в\'язниці, то витяг меча та й хотів себе вбити, мавши думку, що повтікали ув\'я́знені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 28, 'А Павло́ скрикнув голосом гучни́м, говорячи: „Не чини собі жодного зла, бо всі ми ось тут!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 29, 'Зажадавши ж той світла, уско́чив, і тремтячий припав до Павла та до Сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 30, 'І вивів їх звідти й спитав: „Добро́дії! Що треба робити мені, щоб спасти́ся?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 31, 'А вони відказали: „Віруй в Господа Ісуса, — і будеш спасе́ний ти сам та твій дім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 32, 'І Слово Господнє звіщали йому та й усім, хто був у домі його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 33, 'І сторож забрав їх того ж ча́су вночі, їхні рани обмив, — і охристився негайно він сам та його всі домашні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 34, 'І він їх запровадив до дому свого, і поживу поставив, і радів із усім домом своїм, що ввірував у Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 35, 'А коли настав день, то прислали начальники слуг поліційних, наказуючи: „Відпусти тих людей!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 36, 'І сказав той в\'язничний дозорець слова́ ці Павлові: що прислали начальники, щоб вас відпустити. „Отож, вийдіть тепер та й з ми́ром ідіть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 37, 'А Павло відказав їм: „Нас, римля́н, незасуджених, рі́зками сікли прилю́дно, і до в\'язниці всадили, а тепер нас таємно виводять? Але ні! Хай вони самі при́йдуть, та й виведуть нас!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 38, 'Ці ж слова поліційні слуги доне́сли начальникам. А ті налякались, почувши, що римля́ни вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 39, 'І прийшли, та їх перепросили, а вивівши, благали, щоб із міста пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 40, 'І, вийшовши з в\'язниці, прибули́ вони до Лі́дії, а з братами побачившись, потішили їх та й пішли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 1, 'Як вони перейшли Амфіпо́ль й Аполло́нію, то прийшли до Солу́ня, де була синагога юдейська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 2, 'І Павло, за звича́єм своїм, до них увійшов, і з ними змагавсь три суботи з Писа́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 3, 'виказуючи та доводячи, що мусів Христос постраждати й воскре́снути з мертвих, і що Христос Той — Ісус, про Якого „я вам проповідую“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 4, 'І ввірували дехто з них і до Павла та до Сили пристали, — безліч побожних із ге́лленів та немало з шляхе́тних жінок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 5, 'А невірні юдеї були запалилися за́здрістю, і якихсь негідних людей назбирали на вулицях, учинили збіго́висько та й бунтували те місто, а набі́гши на хату Ясо́нову, шукали апо́столів, щоб до на́товпу вивести їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 6, 'А як їх не знайшли, потягли до начальників міста Ясо́на та декого з братті, кричачи́: „Ті, що світ сколотили, — і сюди ось вони поприхо́дили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 7, 'А Ясон їх до себе прийняв. Вони всі проти наказів кесаря чинять, гово́рячи, ніби інший є цар — Ісус“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 8, 'І вони зворохо́били наро́д та начальників міста, що слухали це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 9, 'Але, узявши поруку з Ясо́на та з інших, вони їх відпустили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 10, 'А брати відіслали негайно вночі Павла й Силу до Ве́рії. І, прибувши, вони пішли в синагогу юдейську.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 11, 'Ці були шляхетні́ші за солу́нян, — і слова́ прийняли з повним за́палом, і Писа́ння досліджували день-у-день, чи та́к воно є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 12, 'Тож багато із них тоді ввірували, і з почесних ге́лленсьих жінок та немало із му́жів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 13, 'Як солунські ж юдеї довідалися, що Павло проповідує Боже Слово й у Ве́рії, прибули́ вони, і там баламутили та бунтували наро́д.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 14, 'Тоді браття негайно Павла відпустили, щоб до моря йшов; а Сила та Тимофій позоста́лися там.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 15, 'А ті, що Павла́ відпроваджували, провели́ його аж до Ате́н, а прийнявши нака́за про Силу та Тимофія, щоб до нього вернулися якнайшвидше, відбули́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 16, 'Як Павло ж їх чекав у в Ате́нах, у ньо́му кипів його дух, як бачив це місто, повне ідолів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 17, 'Тож він розмовляв у синагозі з юдеями та з богобійними, і на ринку щоденно зі стрі́чними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 18, 'А дехто з філо́софів епікуре́їв та сто́їків сперечалися з ним. Одні говорили: „Що́ то хоче сказати оцей пустомо́в?“А інші: „Здається, він проповідник чужих богів“, бо він їм звіща́в Єва́нгелію про Ісуса й воскре́сення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 19, 'І, взявши його, повели в ареопа́г та й казали: „Чи можемо знати, що́ то є ця наука нова́, яку проповідуєш ти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 20, 'Бо чудне́ щось вкладаєш до наших вух. Отже хочемо знати, що́ то значити має?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 21, 'А всі ате́няни та захожі чужи́нці нічим іншим радніш не займалися, як аби щось нове́ говорити чи слухати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 22, 'Тоді Павло став посе́редині ареопа́гу й промовив: „Му́жі ате́нські! Із усьо́го я бачу, що ви дуже побожні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 23, 'Бо, проходячи та оглядаючи свя́тощі ваші, я знайшов також же́ртівника, що на ньому написано: „Незнаному Богові“. Ось Того, Кого навмання́ ви шануєте, Того я проповідую вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 24, 'Бог, що створив світ і все, що в ньому, бувши Господом неба й землі, проживає не в хра́мах, рукою збудова́них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 25, 'і Він не вимагає служі́ння рук лю́дських, ніби в чо́мусь Він мав би потребу, бо Сам дає всім і життя, і дихання, і все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 26, 'І ввесь лю́дський рід Він з одно́го створив, щоб замешкати всю поверхню землі, і призна́чив окреслені до́би й границі заме́шкання їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 27, 'щоб Бога шукали вони, чи Його не відчують і не зна́йдуть, хоч Він недалеко від кожного з нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 28, 'Бо ми в Нім живемо́, і рухаємось, і існуємо, як і деякі з ваших поетів казали: „Навіть рід ми Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 29, 'Отож, бувши Божим тим родом, не повинні ми ду́мати, що Божество́ подібне до золота, або срі́бла, чи до каменю, твору мистецтва чи лю́дської ви́гадки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 30, 'Не зважаючи ж Бог на часи невідо́мости, ось тепер усім лю́дям наказує, щоб скрізь ка́ялися,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 31, 'бо Він ви́значив день, коли хоче судити поправді ввесь світ через Мужа, що Його наперед Він поставив, і Він подав до́каза всім, із мертвих Його воскресивши“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 32, 'Як почули ж вони про воскре́сення мертвих, то одні насміхатися стали, а інші казали: „Про це бу́демо слухати тебе іншим ра́зом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 33, 'Так вийшов Павло з-поміж них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 17, 34, 'А деякі мужі пристали до нього й увірували, серед них і Діонисій Ареопагі́т, і жінка, Дама́ра ім\'я́м, та інші із ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 1, 'Після цього він вийшов з Ате́н і прибув до Кори́нту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 2, 'І знайшов він одного юде́я, на йме́ння Аки́лу, родом із По́нту, що недавно прибув із Італії, та Приски́ллу, його дружи́ну, — бо Кла́вдій звелів усім юдеям, щоб покинули Рим. І до них він прийшов,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 3, 'а що був він того ж ремесла́, то в них позостався та працював; ремесло́ ж їхнє було — виробляти наме́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 4, 'І він щосуботи розмову точив у синагозі, переконуючи юдеїв та ге́лленів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 5, 'А коли прибули́ Сила та Тимофій з Македонії, Павло слову віддався, і він свідчив юдеям, що Ісус — то Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 6, 'Як вони ж спротивля́лися та богозневажа́ли, то він обтрусив одежу свою та промовив до них: „Ваша кров — на голову вашу! Я чистий. Відтепе́р я піду́ до поган“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 7, 'І, вийшовши звідти, він прибув до госпо́ди одно́го, на ім\'я Тита Юста, що був богобійний, його ж дім межува́в із синагогою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 8, 'А Крисп, старши́й синагоги, увірував в Господа з усім домом своїм; і багато з кори́нтян, почувши, увірували й охристились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 9, 'Сказав же Павло́ві Госпо́дь у видінні вночі: „Не бійся, але говори й не мовчи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 10, 'бо з тобою ось Я, і на тебе ніхто не накинеться, щоб тобі заподі́яти зло, — бо Я маю в цім місті багато людей“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 11, 'І позостався він рік і шість місяців, навчаючи в них Сло́ва Божого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 12, 'А коли Галліо́н був в Аха́ї проко́нсулом, то проти Павла́ однодушно повстали юдеї, і на суд привели́ його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 13, 'кажучи: „Цей людей намовляє, щоб Богові честь віддавали незгідно з Зако́ном!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 14, 'Як Павло ж хотів у́ста відкрити, сказав Галліо́н до юдеїв: „О юдеї, якби сталася кривда яка, або злий учинок, то я б справедливо вас вислухав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 15, 'Та коли спір іде про слово та йме́ння й Зако́н ваш, то самі́ доглядайте, — я суддею цього бути не хо́чу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 16, 'I прогнав їх від су́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 17, 'Тоді́ всі схопи́ли Состе́на, начальника над синагогою, та й перед судо́м його били. Галліо́н же на те зовсі́м не зважав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 18, 'А Павло́, перебувши доволі ще днів, попрощався з братами, і попли́нув у Си́рію, і з ним Приски́лла й Аки́ла; він у Кенхре́ях обстриг собі голову, бо обі́тницю дав був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 19, 'І прибув він в Ефе́с, і там їх позоста́вив, а сам у синагогу ввійшов і розмовляв із юде́ями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 20, 'Як просили ж його довший час позостатися в них, то він не згодився,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 21, 'але попрощався й сказав: „Знов вернуся до вас, коли буде на те воля Божа!“І відплив із Ефе́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 22, 'І, побувши в Кесарі́ї, він підня́вся, і, привіт склавши Церкві, відбув в Антіохі́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 23, 'І, пробувши там деякий час, він вибрався в подорож знову, за поря́дком прохо́дячи через країну гала́тську та Фріґію, та всіх учнів зміцняючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 24, 'Один же юдей, на ім\'я́ Аполло́с, родом з Олександрі́ї, красномо́вець та сильний в Писа́нні, прибув до Ефе́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 25, 'Він був навче́ний дороги Господньої, і, пала́ючи духом, промовляв і про Господа пильно навчав, знаючи тільки Іванове хрищення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 26, 'І він сміливо став промовляти в синагозі. Як Аки́ла й Приски́лла почули його, то його прийняли́, і докладніш розповіли́ йому про дорогу Господню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 27, 'А коли він схотів перейти до Аха́ї, брати написали до учнів, нагадуючи, щоб його прийняли́. А прибувши, помагав він багато тим, хто ввірував благода́ттю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 18, 28, 'бо він переконував пильно юдеїв, Писа́нням прилюдно дово́дячи, що Ісус — то Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 1, 'І сталося, що коли Аполло́с перебував у Кори́нті, то Павло, перейшовши горі́шні країни, прибув до Ефе́су, і деяких учнів знайшов,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 2, 'та й спитав їх: „Чи ви Духа Святого одержали, як увірували?“А вони відказали йому: „Та ми навіть не чули, чи є Дух Святий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 3, 'І він запитав: „Тож у що́ ви христились?“Вони ж відказали: В Іванове хрищення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 4, 'І промовив Павло: „Таж Іван христив хрищенням на покая́ння, говорячи лю́дям, щоб вірили в Того, Хто при́йде по ньому, цебто в Ісуса“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 5, 'Як почули ж ́, то христились вони в Ім\'я́ Господа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 6, 'А коли Павло руки на них покла́в, то зійшов на них Дух Святий, — і різними мовами стали вони промовляти та пророкувати!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 7, 'А всіх їх було́ чоловіка з двана́дцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 8, 'А до синагоги ввійшовши, промовляв він відважно, три місяці про Боже Царство навчаючи та переконуючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 9, 'А коли опиралися дехто й не вірували, і дорогу Господню лихосло́вили перед наро́дом, то він їх покинув і виділив учнів, і щодня проповідував у школі одно́го Тира́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 10, 'Це ж два роки продовжувалось, так що всі, хто замешкував в Азії, юдеї та ге́ллени, слухали слово про Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 11, 'І Бог чуда чинив надзвича́йні руками Павловими,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 12, 'так що навіть хустки́ й пояси́ з його тіла прино́сили хворим, — і хвороби їх кидали, і ду́хи лукаві вихо́дили з них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 13, 'Дехто ж із мандрівни́х ворожби́тів юдейських зачали́ закликати Ім\'я́ Господа Ісуса над тими, хто мав злих духів, проказуючи: Заклинаємо вас Ісусом, Якого Павло́ проповідує!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 14, 'Це ж робили якісь сім синів юдейського первосвященика Ске́ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 15, 'Відповів же злий дух і сказав їм: „Я знаю Ісуса, і знаю Павла, а ви хто такі?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 16, 'І ско́чив на них чоловік, що в ньому злий дух був, і, перемігші обох, поду́жав їх так, що втекли вони з дому нагі́ та пора́нені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 17, 'І це стало відо́ме юдеям та ге́лленам, усім, що в Ефесі замешкують, — і о́страх напав на всіх їх, і сла́вилося Ім\'я́ Господа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 18, 'І багато-хто з тих, що ввірували, прихо́дили, визнаваючи та відкриваючи вчинки свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 19, 'І багато-хто з тих, що займалися ча́рами, позно́сили книги свої та й перед усіма́ попалили. І злічили ціну́ їх, і вийшло на срібло п\'ятдесят тисяч драхм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 20, 'Так могуче росло та зміцнялося Вожеє Слово!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 21, 'А як спо́внилось це, Павло в Дусі задумав перейти Македо́нію та Ахаю, та й удатись у Єрусалим, говорячи: „Як побу́ду я там, то треба мені й Рим побачити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 22, 'Тож він послав у Македо́нію двох із тих, що служили йому, Тимофі́я й Ера́ста, а сам позостався якийсь час ув Азії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 23, 'І ро́зрух чималий був стався там ча́су того за Господню дорогу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 24, 'Бо один золота́р, Дмитро на ім\'я́, що робив срібляні́ Артемі́дині храмки, та ремісникам заробі́ток чималий давав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 25, 'згромадив він їх і ще інших подібних робі́тників, та й промовив: „Ви знаєте, мужі, що з цього ремесла́ заробі́ток ми маємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 26, 'І ви бачите й чуєте, що не тільки в Ефе́сі, але мало не в усій Азії — цей Павло збаламу́тив і відвернув багате́нно наро́ду, говорячи, ніби то не боги, що руками поро́блені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 27, 'І не тільки оце нам загрожує, що при́йде зайняття в упадок, а й храм богині великої Артемі́ди в ніщо́ зарахується, і буде зруйнована й ве́лич тієї, що шанує її ціла Азія та цілий світ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 28, 'Почувши ж оце, вони перепо́внились гнівом, та й стали кричати, говорячи: „Артемі́да ефе́ська велика!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 29, 'І місто напо́внилось за́колотом. І кинулися однодушно до видо́вища, схопи́вши Павло́вих супу́тників — Гая та Ариста́рха, македо́нян.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 30, 'Як Павло ж хотів у наро́д увійти, то учні його не пустили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 31, 'Також дехто з азі́йських начальників, що були йому при́ятелі, послали до нього й просили, щоб він не вдава́всь на видо́вище.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 32, 'І кожен що інше кричав, бо збори бурхли́ві були, і багате́нно з них навіть не знали, чого ради зібралися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 33, 'А з наро́ду взяли Олександра, бо юдеї його висували. І Олекса́ндер дав знака рукою, і хотів ви́правдатися перед наро́дом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 34, 'А коли розпізнали, що юде́янин він, то злилися всі в один голос, і годин зо дві гукали: „Артеміда ефеська велика!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 35, 'А як писар міськи́й заспоко́їв наро́д, то промовив: „Мужі ефеські, яка ж то люди́на не знає, що місто Ефес — то храмо́вий догля́дач Артеміди великої й її образу, упалого з неба?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 36, 'Коли ж цьому перечити не можна, то потрібно вам бути спокійними, і не роби́ти необачно нічо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 37, 'А ви ж привели́ цих людей, що ані святокрадці, ані вашої богині не знева́жили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 38, 'Отож, як Дмитро та його ремісники мають справу на ко́го, то суди є на ринку й проконсули, — один о́дного хай позивають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 39, 'А коли чогось іншого допомина́єтеся, то те вирішиться на зако́ннім зібра́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 40, 'Бо ось є небезпека, що нас за сьогоднішній ро́зрух оскаржити можуть, і немає жа́дної причини, якою могли б виправдати це зборище“. І, промовивши це, розпустив він громаду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 19, 41, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 1, 'А як за́колот стих, то Павло скликав учнів, і, потішивши та попрощавшись із ними, вибрався йти в Македо́нію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 2, 'Перейшовши ж ті сто́рони та підбадьо́ривши їх довгим словом, прибув до Гелла́ди,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 3, 'і прожив там три місяці. А як він захотів був відпли́нути в Си́рію, то змову на нього вчинили юдеї, тому він узяв думку вертатись через Македонію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 4, 'Ра́зом із ним пішов Со́патер Піррів із Верії, Аристарх та Секунд із Солу́ня, і Гай дерв\'яни́н, і Тимофій, а з азійців — Ти́хик та Трохим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 5, 'Вони відбули́ напере́д, і нас дожидали в Троаді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 6, 'А ми відпливли́ із Филипів по святах Опрі́сноків, і прибули́ днів за п\'ять у Троа́ду до них, де сім день прожили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 7, 'А дня першого в тижні, як учні зібралися на лама́ння хліба, Павло мав промову до них, бо вранці збирався відбути, і затягнув своє слово до пі́вночі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 8, 'А в го́рниці, де зібралися ми, було багато світел.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 9, 'Юнак же один, Євти́х на ім\'я́, сидів на вікні. Його обгорнув міцний сон, бо задовго Павло промовляв, і він сонний хитну́вся, і додолу упав із третього поверху, — і підняли́ його мертвого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 10, 'Зійшов же Павло та до нього припав, і, обнявши його, проказав: „Заспокойтесь, бо душа його в ньому!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 11, 'А вернувшись, він хліб переломив і спожив, і бе́сіду довго точив, — аж до до́світку, потім відбув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 12, 'А хлопця живим привели́, — і зраділи немало.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 13, 'А ми наперед пішли до корабля, та в Асс попливли́, щоб звідти забрати Павла, — бо він так ізвелів, сам бажаючи пішки піти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 14, 'А коли він із нами зійшовся в Ассі, ми взяли його та прибули́ в Мітіле́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 15, 'І, відплинувши звідти, ми назавтра пристали навпро́ти Хіо́су, а другого дня припливли́ до Само́су, наступного ж ми прибули́ до Мілету.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 16, 'Бо Павло захотів поминути Ефе́с, щоб йому не бари́тися в Азії, бо він ква́пився, коли буде можливе, бути в Єрусалимі на день П\'ятдесятниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 17, 'А з Мілету послав до Ефесу, і прикликав пресвітерів Церкви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 18, 'І, як до нього вони прибули́, він промовив до них: „Ви знаєте, як із першого дня, відколи прибув в Азію, я з вами ввесь час перебува́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 19, 'і служив Господе́ві з усією покорою, і з рясни́ми слізьми́ та напа́стями, що спіткали мене від юдейської змови,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 20, 'як нічо́го кори́сного я не минув, щоб його вам звістити й навчити вас прилюдно і в дома́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 21, 'І я сві́дчив юдеям та ге́лленам, щоб вони перед Богом покаялись, та вві́рували в Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 22, 'І ось тепер, побуджений Духом, подаю́сь я в Єрусалим, не ві́даючи, що там трапитись має мені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 23, 'тільки Дух Святий в кожному місті засвідчує, кажучи, що кайда́ни та муки чекають мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 24, 'Але я ні про що не турбуюсь, і свого життя не вважаю для себе цінним, аби но скінчи́ти доро́гу свою та служі́ння, яке я оде́ржав від Господа Ісуса, — щоб засві́дчити Єва́нгелію благода́ті Божої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 25, 'І ось я знаю тепер, що обличчя мого́ більш не будете бачити всі ви, між якими ходив я, проповідуючи Царство Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 26, 'Тому́ дня сьогоднішнього вам свідку́ю, що я чистий від крови всіх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 27, 'бо я не вхилявсь об\'являти вам усю волю Божу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 28, 'Пильнуйте себе та всієї ота́ри, в якій Святий Дух вас поставив єпи́скопами, щоб пасти́ Церкву Божу, яку власною кров\'ю набув Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 29, 'Бо я знаю, що як я відійду́, то вві́йдуть між вас вовки люті, що ота́ри щадити не бу́дуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 30, 'Із вас самих навіть мужі постануть, що будуть казати перекру́чене, аби тільки учнів тягну́ти за собою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 31, 'Тому́ то пильнуйте, пам\'ятаючи, що я кожного з вас день і ніч безпере́стань навчав зо слізьми́ ось три роки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 32, 'А тепер доручаю вас Богові та слову благода́ті Його, Який має силу будувати та дати спа́дщину, серед усіх освячених.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 33, 'Ні срібла, ані золота, ні одежі чиєїсь я не побажав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 34, 'Самі знаєте, що ці руки мої послужили потребам моїм та отих, хто був зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 35, 'Я вам усе показав, що, працюючи так, треба поміч давати слаби́м, та пам\'ятати слова́ Господа Ісуса, бо Він Сам проказав: „Блаже́нніше давати, ніж брати!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 36, 'Проказавши ж оце, він навко́лішки впав, та й із ними всіма́ помолився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 37, 'І знявсь між усіма́ плач великий, і вони припадали на Па́влову шию, і його цілували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 20, 38, 'А найтяжче вони сумували з-за сло́ва, яке він прорік, що не ба́читимуть більш обличчя його́. І вони провели́ його до корабля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 1, 'А як ми розлучи́лися з ними й відпли́нули, то дорогою про́стою в Кос прибули́, а другого дня до Родо́су, а звідти в Пата́ру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 2, 'І знайшли корабля́, що плив у Фінікі́ю, увійшли та й попли́нули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 3, 'А коли показався нам Кіпр, ми лишили ліво́руч його та й попливли в Си́рію. І пристали ми в Тирі, бо там корабель вантажа́ мав скласти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 4, 'І, учнів знайшовши, перебули́ тут сім день. Вони через Духа казали Павло́ві, щоб до Єрусалиму не йшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 5, 'І, як дні побуту скінчи́лися, то ми вийшли й пішли, а всі нас прово́дили з дружи́нами й дітьми́ аж за місто. І, ставши навко́лішки, помолились на бе́резі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 6, 'І, попрощавшись один із одним, ми ввійшли в корабель, а вони повернулись додому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 7, 'А ми, закінчи́вши від Тиру плавбу́, пристали до Птолемаїди, і, братів привітавши, один день перебули́ в них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 8, 'А назавтра в дорогу ми вибрались, і прийшли в Кесарі́ю. І ввійшли до госпо́ди благові́сника Пилипа, одно́го з семи, і позосталися в нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 9, 'Він мав чотири панні дочки́, що пророкували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 10, 'І коли ми багато днів у них зоставались, то прибув із Юдеї якийсь пророк, Ага́в на ім\'я́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 11, 'І прийшов він до нас, і взяв пояса Па́влового, та й зв\'язав свої руки та ноги й сказав: „Дух Святий так звіщає: Отак зв\'яжуть в Єрусалимі юдеї того мужа, що цей пояс його, і видадуть в руки поган“...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 12, 'Як почули ж оце, то благали ми та тамте́шні Павла, щоб до Єрусалиму не йшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 13, 'А Павло відповів: „Що́ робите ви, плачучи́ та серце мені розрива́ючи? Бо за Ім\'я́ Господа Ісуса я готовий не тільки зв\'я́заним бути, а й померти в Єрусалимі“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 14, 'І не могли ми його вмо́вити, і замовкли, сказавши: „Нехай діється Божа воля!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 15, 'А після оцих днів приготува́лись ми, та до Єрусалиму ви́рушили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 16, 'А з нами пішли й деякі учні із Кесарі́ї, ведучи́ якогось кіпрянина Мнасо́на, давнього учня, що ми в нього спинитися мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 17, 'А коли ми прийшли в Єрусалим, то брати́ прийняли́ нас гости́нно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 18, 'А другого дня Павло з нами пода́вся до Якова. І всі старші посхо́дились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 19, 'Поздоро́вивши ж їх, розповів він докладно, що́ Бог через служі́ння його вчинив між поганами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 20, 'Як вони ж це почули, то сла́вили Бога, а до нього промовили: „Бачиш, брате, скільки тисяч серед юдеїв увірувало, і всі вони — ревні оборонці Зако́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 21, 'Вони ж чули про тебе, ніби ти всіх юдеїв, що живуть між поганами, навчаєш відсту́плення від Мойсея, говорячи, щоб дітей не обрізували й не тримались звича́їв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 22, 'Що ж почати? Люд збереться напевно, бо почують, що прибув ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 23, 'Отже, зроби це, що порадимо тобі. Ми маємо чотирьох му́жів, що обі́тницю склали на себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 24, 'Візьми їх, та й із ними очисться, і вида́тки за них заплати́, щоб постри́гли їм голови. І пізнають усі, що неправда про тебе їм сказане, та й що сам ти Зако́на пильнуєш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 25, 'А про тих із поган, що ввірували, ми писали, розсудивши, щоб вони береглися від ідольських жертов та крови й задушени́ни, та від блу́ду“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 26, 'Тоді взяв Павло мужів отих, і назавтра очи́стився з ними, і ввійшов у храм, і звістив про ви́конання днів очи́щення, так, аж за кожного з них була́ жертва прине́сена.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 27, 'А коли ті сім день закінчи́тися мали, то азійські юдеї, як побачили в храмі його, підбу́рили ввесь наро́д, та руки на нього наклали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 28, 'кричачи́: „Ізраїльські мужі, рятуйте! Це люди́на ота, що проти народу й Зако́ну та місця цього всіх усюди навчає! А до того у храм упровадив і ге́лленів, — і занечи́стив це місце святе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 29, 'Бо перед тим вони бачили в місті з ним ра́зом Трохима ефе́сянина, і гадали про нього, що Павло то його ввів у храм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 30, 'І порушилося ціле місто, і повстало збіго́висько люду. І, схопи́вши Павла, потягли його поза храм, а двері негайно зачинено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 31, 'Як хотіли ж забити його, то вістка досталась до полково́го тисяцього, що ввесь Єфусалим збунтувався!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 32, 'І він зараз узяв воякі́в та сотників, і подався до них. А вони, як угледіли тисяцького й вояків, то бити Павла перестали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 33, 'Приступив тоді ти́сяцький, та й ухопи́в його, і двома́ ланцюга́ми зв\'язати звелів, і допитувати став: хто такий він і що́ він зробив?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 34, 'Але кожен що інше викрикував у нато́впі. І, не мігши довідатись певного через за́колот, він звелів відпрова́дити його до форте́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 35, 'А коли він до сходів прийшов, то трапилося, що мусіли не́сти його вояки із-за на́товпу лю́дського,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 36, 'бо бе́зліч народу йшла слідкома́ та кричала: „Геть із ним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 37, 'А коли Павло вхо́див до фортеці, то тисяцького поспитався: „Чи можна мені щось сказати тобі?“А той відказав: „То ти вмієш по-грецькому?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 38, 'Чи не той ти єги́птянин, що перед цими днями призвів був до бунту, і ви́провадив до пустині чотири тисячі потаємних убійників?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 39, 'А Павло відказав: „Я юде́янин із Та́рсу, громадя́нин відо́мого міста в Кілікі́ї. Благаю тебе, — дозволь мені до наро́ду промовити!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 21, 40, 'А коли той дозволив, то Павло став на сходах, і дав знака рукою наро́дові. А як тиша велика настала, промовив єврейською мовою, ка́жучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 1, '„Мужі-браття й батьки! Послухайте ось тепер ви́правда́ння мого перед вами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 2, 'Як зачули ж вони, що до них він говорить єврейською мовою, то тиша ще більша настала. А він промовляв:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 3, '„Я юде́янин, що родився в кілікі́йському Та́рсі, а ви́хований у цім місті, у ніг Гамалії́ла докладно навчений Зако́ну отці́в; горли́вець я Божий, як і всі ви сьогодні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 4, 'Переслідував я аж до смерти цю путь, і в\'язав, і до в\'язниці вкидав чоловіків і жінок,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 5, 'як засві́дчить про мене первосвященик та вся старши́на. Я від них був узяв навіть листи́ на братів, і пішов до Дама́ску, щоб тамте́шніх зв\'язати й приве́сти до Єрусалиму на кару.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 6, 'І сталося, як у дорозі я був, і наближа́всь до Дамаску опі́вдня, то ось мене нагло осяяло світло велике з неба!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 7, 'І я повалився на землю, і голос почув, що мені говорив: „Савле, Савле, — чому́ ти Мене переслідуєш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 8, 'А я запитав: „Хто Ти, Господи?“А Він мені відказав: „Я Ісус Назаряни́н, що Його переслідуєш ти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 9, 'А ті, що зо мною були́, правда, бачили світло, але не почули вони того голосу, що мені говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 10, 'А я запитав: „Що́ я, Господи, маю робити?“Господь же до мене промовив: „Уставай та й іди до Дамаску, а там тобі скажуть про все, що тобі призна́чено робити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 11, 'А від ясности світла того невидю́щим я став. І присутні зо мною за руку мене повели́, і до Дамаску прибув я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 12, 'А один муж Ана́ній, у Зако́ні побожний, що добре свідо́цтво про нього дають усі юдеї в Дамаску,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 13, 'до мене прибув, і, ставши, промовив мені: „Савле брате, — стань видю́щий!“І я хвилі тієї побачив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 14, 'І озвавсь він до мене: „Бог отців наших вибрав тебе, щоб ти волю Його зрозумів, і щоб бачив ти Праведника, і почув голос із уст Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 15, 'Бо бу́деш ти свідком Йому перед усіма людьми́ про оте, що ти бачив та чув!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 16, 'А тепер чого гаєшся? Уставай й охристися, і обмий гріхи свої, прикликавши Ймення Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 17, 'І сталось, як вернувся я в Єрусалим, і молився у храмі, то в захо́плення впав я,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 18, 'і побачив Його, що до мене сказав: „Поспіши, і піди хутчій з Єрусалиму, бо не приймуть свідо́цтва твого про Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 19, 'А я відказав: „Самі вони, Господи, знають, що я до в\'язниць садови́в та бив по синагогах отих, хто вірував у Тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 20, 'А коли лилась кров Твого свідка Степа́на, то сам я стояв та вбивство його похваляв, і одежу вбивців його сторожи́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 21, 'Але Він до мене промовив: „Іди, бо пошлю Я далеко тебе, — до поган!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 22, 'І аж до слова цього його слухали. Аж ось підне́сли вони голос свій, гукаючи: „Геть такого з землі, бо жити йому не годи́ться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 23, 'І як вони верещали, і одежу шпурля́ли, і кидали порох у повітря,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 24, 'то звелів тисяцький у фортецю його відвести́, і звелів бичува́нням його допитати, щоб довідатися, з якої причини на нього вони так кричали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 25, 'І як його розтягли́ для ремінних бичів, то Павло сказав сотникові, що стояв: „Хіба бичува́ти дозволено вам громадянина римського та ще й незасу́дженого?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 26, 'Якже сотник це почув, то подався до тисяцького, і завідо́мив, говорячи: „Що́ хочеш робити? Бож ри́млянин цей чоловік!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 27, 'Підійшов тоді тисяцький, та й поспитався його: „Скажи мені, чи ти ри́млянин?“А він: „Так!“відказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 28, 'Відповів на те тисяцький: „За великі гро́ші громадянство оце я набув“. А Павло відказав: „А я в нім і родився!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 29, 'І відступили негайно від нього оті, що хотіли допи́тувати його. І злякався тисяцький, довідавшись, що той ри́млянин, і що він ізв\'язав був його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 22, 30, 'А другого дня, бажавши довідатись правди, у чо́му юдеї його оскаржа́ють, він звільнив його та звелів, щоб зібра́лися первосвященики та ввесь синедріо́н. І він вивів Павла, і поставив його перед ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 1, 'І вп\'явся очима Павло на той синедріо́н і промовив: „Мужі-браття, я аж по сьогоднішній день жив для Бога всім добрим сумлі́нням!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 2, 'Але первосвященик Ана́ній звелів тим, що стояли при ньому, щоб били його по уста́х.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 3, 'Тоді промовив до нього Павло: „Тебе битиме Бог, ти сті́но побілена... Ти ж сидиш, щоб судити мене за Зако́ном, а наказуєш бити мене проти Зако́ну?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 4, 'А присутні сказали: „То ти Божому первосвященикові лихосло́виш?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 5, 'І промовив Павло: „Не знав я, брати, що то первосвященик. Бо написано: На начальника люду твого не лихосло́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 6, 'І Павло, спостерігши, що частина одна — саддуке́ї, а друга — фарисеї, покликнув у синедріоні: „Мужі-браття, — я фарисей, і син фарисея. За наді́ю на воскресіння мертвих мене судять!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 7, 'Якже він це промовив, колотне́ча постала поміж саддуке́ями та фарисеями, — і розділи́лась юрба́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 8, 'Саддуке́ї бо тве́рдять, що немає воскресіння, ані а́нгола, ані духа, фарисеї ж оце визнають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 9, 'І галас великий зчинився. А деякі книжники, із фарисейської групи, уставши, почали́ сперечатися, кажучи: „У чоловікові цьому ми жодного ли́ха не знаходимо! А коли промовляв Дух до нього, чи ангол, не противмося Богові“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 10, 'А коли колотне́ча велика зчинилась, то тисяцький, боячись, щоб Павла не роздерли, звелів вояка́м увійти та забрати його з-поміж них, і відве́сти в форте́цю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 11, 'А наступної ночі став Господь перед ним і промовив: „Будь бадьорий! Бо як в Єрусалимі про Мене ти свідчив, так треба тобі свідкува́ти й у Римі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 12, 'А коли настав день, то дехто з юдеїв зібрались, та клятву скла́ли, говорячи, що ні їсти, ні пити не бу́дуть, аж доки Павла́ не заб\'ють!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 13, 'А тих, що закляття таке покла́ли, було більш сорока́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 14, 'І вони приступили до первосвящеників та старших і сказали: „Ми клятву скла́ли нічого не їсти, аж поки заб\'ємо Павла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 15, 'Отож разом із синедріоном передайте тисяцькому, щоб до вас він привів його, ніби хочете ви докладніш розізнати про нього. А ми, перше ніж він набли́зиться, готові забити його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 16, 'Як зачув же сестрі́нець Павлів про цю змову, то прибув, і ввійшов у форте́цю, і Павла́ завідо́мив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 17, 'Павло ж зараз покликав одно́го з сотників, та й сказав: „Цього юнака́ запровадь до тисяцького, бо він має йому щось сказати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 18, 'Той же взяв його, та й запровадив до тисяцького та сказав: „Павло в\'язень покликав мене, і просив запрова́дити до тебе цього юнака́, що має тобі щось сказати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 19, 'І взяв тисяцький того за руку, і на́бік відвів і спитав: „Що́ ти маєш звістити мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 20, 'А той розповів: „Змову склали юдеї, — просити тебе, щоб ти взавтра до синедріо́ну Павла припрова́див, ніби хочуть вони докладніш розпізнати про нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 21, 'Отож, не послухайся їх, бо чигає на нього їх більш сорока чоловіка, що клятву скла́ли ні їсти, ні пити, аж доки його не заб\'ють. І тепер он готові вони, і чекають твого прире́чення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 22, 'Тоді тисяцький відпустив юнака́, наказавши йому — „не розповіда́ти ані о́дному, що мені ти це ви́явив.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 23, 'І він закли́кав якихось двох із сотників, і наказав: „Пришикуйте на третю годину вночі дві сотні вояків, щоб іти до Кесарії, і кіннотників сімдеся́т, та дві сотні стрільців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 24, 'Приготуйте також в\'ючаків і Павла посадіть, і здоровим його проведіть до намісника Фе́лікса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 25, 'І листа написав він такого ось змісту:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 26, '„Кла́вдій Лі́сій намісникові вседостойному Фе́ліксові — поздоро́влення!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 27, 'Цього мужа, що його юдеї схопи́ли були́ та хотіли забити, урятував я, із вояка́ми прийшовши, довідавшися, що він ри́млянин.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 28, 'І хотів я довідатися про причину, що за неї його оскаржа́ли, та й привів був його до їхнього синедріо́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 29, 'Я знайшов, що його винуватять у спірних речах їхнього Зако́ну, і що провини не має він жа́дної, ва́ртої смерти або ланцюгі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 30, 'Як доне́сли ж мені про ту змову, що юдеї вчинили на мужа цього, я зараз до тебе його відіслав, наказавши також позива́льникам, щоб перед тобою сказали, що́ мають на нього. Будь здоровий!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 31, 'Отож вояки, як наказано їм, забрали Павла́, і вночі попровадили в Антипатри́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 32, 'А другого дня, полишивши кінно́тчиків, щоб ішли з ним, у форте́цю вони повернулись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 33, 'А ті прибули́ в Кесарі́ю, і, листа передавши намісникові, поставили також Павла перед ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 34, 'Намісник листа прочитав і спитав, із якого він кра́ю. А довідавшись, що з Кілікії, промовив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 23, 35, '„Я тебе переслухаю, як при́йдуть і твої позива́льники“. І звелів стерегти його в Іродовому Прето́рії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 1, 'А по п\'яти днях прибув первосвященик Ана́ній з якимись старши́ми, та з промовцем якимсь Терти́лом, що перед намісником ска́ржилися на Павла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 2, 'Коли ж він був покликаний, то Тертил оскаржати зачав, промовляючи: „Через тебе великий мир маємо ми, і для наро́ду цього добрі речі впроваджено через дбайливість твою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 3, 'це ми за́вжди і скрізь визнаємо з подякою щирою, вседостойний наш Фе́ліксе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 4, 'Та щоб довго тебе не турбува́ти, то благаю тебе, щоб ти коротко вислухав нас зо своєї ласка́вости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 5, 'Ми переконались, що цей чоловік — то зара́за, і що він колотнечу викли́кує між усіма юдеями в ці́лому світі, і що він провідни́к Назорейської єресі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 6, 'Він відважився навіть збезчестити храм, і його ми схопи́ли були, і судити хотіли за нашим Зако́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 7, 'Але тисяцький Лі́сій прибув, і з великим наси́льством видер його з наших рук,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 8, 'а його винува́льникам звелів йти до тебе. Ти сам зможеш від нього, розпитавши, дізнатись про все, у чо́му його ми вину́ємо“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 9, 'Юдеї також прилучились до того, говорячи, що то так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 10, 'І як намісник дав знака йому говорити, то Павло відповів: „Я знаю, що від літ багатьох ти суддя для наро́ду цього, — тому буду сміліш боронитись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 11, 'Ти можеш довідатися, що нема більш дванадцяти день, як прийшов я до Єрусалиму вклонитися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 12, 'І вони ані в храмі, ані в синагогах, ні в місті мене не здиба́ли, щоб я з ким сперечався, або колотнечу в наро́ді здіймав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 13, 'І не можуть вони дове́сти тобі того, у чо́му тепер оскаржа́ють мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 14, 'Але признаю́сь тобі, що в дорозі оцій, яку звуть вони єрессю, я Богові отців служу́ так, що вірую всьому, що в Зако́ні й у Пророків написане.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 15, 'І маю надію я в Бозі, — чого й самі вони сподіва́ються, — що настане воскресіння праведних і неправедних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 16, 'І я пильно дба́ю про те, щоб за́всіди мати сумління невинне, щодо Бога й людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 17, 'А по довгих рока́х я прибув, щоб подати моєму наро́дові ми́лостиню та при́носи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 18, 'Ось при цьо́му знайшли мене дехто з юдеїв азійських очищеного в храмі, а не з на́товпом чи з колотнечею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 19, 'Їм належало б ось перед тебе прибути й казати, коли мають вони що на мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 20, 'Або самі ці нехай скажуть, чи якусь неправду знайшли на мені, як я в синедріоні стояв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 21, 'крім отого єдиного виразу, що я його крикнув, стоячи́ серед них: „За воскресіння мертвих приймаю від вас суд сьогодні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 22, 'Але Фе́лікс, дуже добре дорогу цю знавши, відро́чив їм справу, говорячи: „Розсуджу́ вашу справу, коли тисяцький Лісій прибу́де“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 23, 'І він сотникові наказав сторожити Павла́, але мати полегшу, і не боронити ніко́му з близьки́х його, щоб служили йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 24, 'А по декількох днях прийшов Фе́лікс із дружи́ною своєю Друзі́ллою, що була юде́янка, і покликав Павла, та слухав від нього про віру в Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 25, 'І як розповідав він про праведність, і про здержливість, та про майбу́тній суд, то Фе́лікса страх обгорнув, і він відповів: „Тепер іди собі, відповідного ж ча́су покличу тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 26, 'Разом із тим і сподіва́вся він, що дасть Павло грошей йому, тому й часто його приклика́в і розмову з ним вів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 24, 27, 'Як минуло ж два роки, то Фе́лікс одержав наступника, — По́рція Фе́ста. А Фелікс бажав догодити юдеям, — і в в\'язниці Павла́ залиши́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 1, 'А коли прибув Фест до свого намісництва, то він по трьох днях відійшов із Кесарі́ї до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 2, 'І поскаржилися йому на Павла первосвященики та головніші з юдеїв, і благали його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 3, 'і ніби милости просили для нього, щоб до Єрусалиму його припровадив, — вони змову вчинили, щоб смерть заподі́яти йому по дорозі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 4, 'А Фест відповів, що Павла стережуть у Кесарії, і він сам незаба́ром туди подає́ться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 5, '„Отже, — сказав він, — хто спроможен із вас, нехай ті вируша́ють ра́зом зо мною, і коли є неправда яка в чоловікові цьому, нехай оскаржа́ють його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 6, 'І, пробувши в них днів не більше як вісім чи десять, він поверну́вся до Кесарії. А другого дня він засів на суддевім сидінні, і звелів, щоб приве́сти Павла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 7, 'Як його ж привели́, то стали навколо юдеї, що поприхо́дили з Єрусалиму, і Павлу закидали багато тяжки́х винувачень, що їх не могли дове́сти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 8, 'бо Павло боронився: „Я не провинився ні в чім ані проти Зако́ну юдейського, ані проти храму, ані супроти ке́саря“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 9, 'Тоді Фест, що бажав догодити юдеям, промовив Павло́ві на відповідь: „Чи ти хочеш до Єрусалиму піти, і там суд прийняти від мене про це?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 10, 'Та Павло відказав: „Я стою перед судом ке́саревим, де належить мені суд прийняти. Юдеїв нічим я не скри́вдив, як і ти дуже добре те знаєш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 11, 'Бо коли допустився я кривди, або гідне смерти вчинив що, то не відмовляюся вмерти. Як нема ж нічого того, у чім вони винуватять мене, то не може ніхто мене видати їм. Відкликаюсь до ке́саря!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 12, 'Тоді Фест, побалакавши з радою, відповідь дав: „Ти відкли́кавсь до ке́саря, — до ке́саря пі́деш!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 13, 'Як минуло ж днів кілька, цар Агрі́ппа й Верні́ка приїхали до Кесарії, щоб Феста вітати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 14, 'А що там багато днів вони пробули́, то Фест ви́клав справу Павлову цареві й промовив: „Є один чоловік — від Фелікса лишений в\'язень,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 15, 'на якого, як в Єрусалимі я був, первосвященики й старші юдейські прине́сли скаргу, домагаючись його о́суду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 16, 'Я їм відповів, що римля́ни не мають звича́ю люди́ну якусь видавати на згубу, поки пізваний перед собою не матиме обвинувачі́в, і не буде йому дано можности для оборони від закидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 17, 'І як зійшлись вони тут, то я, зволіка́ння не роблячи жодного, сів наступного дня на сидіння судде́ве, і звелів привести́ цього мужа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 18, 'І винувальники стали круг нього, проте́ не вказали вини ані жодної з тих, яких я сподівався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 19, 'Та мали вони проти нього якісь суперечки про власне своє марновірство, і про якогось Ісуса померлого, про Якого Павло твердив, що живий Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 20, 'І я був непевний у цьо́му змага́нні й спитав, чи не хоче піти він до Єрусалиму, і там суд прийняти про це?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 21, 'Через те ж, що Павло заявив, щоб зали́шений був він на ке́сарів ро́зсуд, я звелів сторожити його, аж поки його не відправлю до ке́саря“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 22, 'А Агріппа промовив до Феста: „Хотів би і я цього му́жа послухати!“„Узавтра — сказав той — почуєш його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 23, 'А назавтра Агрі́ппа й Верні́ка прийшли з превеликою пишно́тою, і на залю судо́ву ввійшли разом з тисяцькими та значнішими му́жами міста. І як Фест наказав, то Павло був приве́дений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 24, 'І сказав до них Фест: „О ца́рю Агріппо, та з нами присутні всі му́жі! Ви бачите того, що за нього ввесь люд юдейський мені докучав в Єрусалимі та тут, кричачи́, що йому не повинно більш жити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 25, 'Я ж дізнавсь, що нічого, ва́ртого смерти, він не вчинив; а що сам він відкликавсь до Августа, розсудив я послати його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 26, 'Нічого не маю я певного, що міг би про нього писати до пана. Тому я припровадив його перед вас, а найбільш перед тебе, ца́рю Агріппо, щоб після переслу́хання мав що писати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 25, 27, 'Бо здається мені нерозва́жливим ув\'я́зненого посилати, і не озна́чити обвинува́чень на нього“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 1, 'А Агріппа сказав до Павла: „Дозволяємо тобі говорити про себе само́го“. Павло тоді простягнув руку, і промовив у своїй обороні:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 2, '„О ца́рю Агріппо! Уважаю себе за щасливого, що сьогодні я перед тобою боронитися маю з усьо́го, у чім мене винуватять юдеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 3, 'особливо ж тому́, що ти знаєш усі юдейські звича́ї та супере́чки. Тому я прошу́ мене вислухати терпля́че.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 4, 'А життя моє зма́лку, що споча́тку точилося в Єрусалимі серед наро́ду мого, знають усі юдеї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 5, 'які відають зда́вна мене, аби тільки схотіли засві́дчити, — що я жив фарисеєм за найдокладнішою сектою нашої віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 6, 'І тепер я стою отут су́джений за надію обі́тниці, що Бог дав ії нашим отцям,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 7, 'а її викона́ння чекають побачити наші дванадцять племен, слу́жачи Богові безперестанно вдень та вночі. За цю надію, о ца́рю, мене винуватять юдеї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 8, 'Чому ви вважаєте за неймовірне, що Бог воскрешає померлих?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 9, 'Правда, ду́мав був я, що мені нале́жить чинити багато ворожого проти Ймення Ісуса Назаряни́на,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 10, 'що я в Єрусалимі й робив, і багато кого зо святих до в\'язниць я замкнув, як отримав був вла́ду від первосвящеників; а як їх убивали, я голос давав проти них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 11, 'І часто по всіх синагогах караючи їх, до богозневаги примушував я, а лютуючи ве́льми на них, переслідував їх навіть по закордонних містах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 12, 'Коли в цих справах я йшов до Дамаску зо вла́дою та припору́ченням первосвящеників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 13, 'то опі́вдні, о ца́рю, на дорозі побачив я світло із неба, ясніше від світлости сонця, що ося́яло мене та тих, хто разом зо мною йшов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 14, 'І як ми всі повалились на землю, я голос почув, що мені говорив єврейською мовою: „Савле, Савле, — чому ти Мене переслідуєш? Трудно тобі бити ногою колю́чку!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 15, 'А я запитав: „Хто Ти, Господи?“А Він відказав: „Я Ісус, що Його переслідуєш ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 16, 'Але підведи́ся, і стань на ноги свої. Бо на те Я з\'явився тобі, щоб тебе вчинити слугою та свідком того, що ти бачив та що Я відкрию тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 17, 'Визволяю тебе від твого наро́ду та від поган, до яких Я тебе посилаю, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 18, 'відкрити їм очі, щоб вони наверну́лись від те́мряви в світло та від сатани́ної вла́ди до Бога, щоб вірою в Мене отримати їм дарува́ння гріхів і насліддя з освяченими“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 19, 'Через це я, о ца́рю Агріппо, не був супротивний видінню небесному,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 20, 'але ме́шканцям перше Дамаску, потім Єрусалиму й усякого кра́ю юдейського та поганам я проповідував, щоб пока́ялися й наверну́лись до Бога, і чинили діла, гі́дні покая́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 21, 'Через це юдеї в святині схопи́ли мене та й хотіли роздерти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 22, 'Але, поміч від Бога одержавши, я стою́ аж до дня сьогоднішнього та свідкую мало́му й великому, нічого не розповідаючи, окрім того, що сказали Пророки й Мойсей, що статися має, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 23, 'що має Христос постраждати, що Він, як перший воскреснувши з мертвих, проповідувати буде світло народові й поганам!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 24, 'Коли ж він боронився отак, то Фест проказав гучни́м голосом: „Дурієш ти, Павле! Велика наука доводить тебе до нерозуму“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 25, 'А Павло: „Не дурію — сказав, — о Фесте достойний, але провіщаю слова правди та щирого розуму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 26, 'Цар бо знає про це, — до нього з відвагою я й промовляю. Бо не гада́ю я, щоб із цього щобудь схова́лось від нього, — бо не в за́кутку ді́ялось це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 27, 'Чи віруєш, ца́рю Агріппо, Пророкам? Я знаю, що віруєш“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 28, 'Агріппа ж Павлові: „Ти малощо не намовляєш мене, щоб я став християни́ном“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 29, 'А Павло: „Благав би я Бога, щоб чи мало, чи багато, — не тільки но ти, але й усі, хто чує сьогодні мене, зробились такими, як і я, крім оцих ланцюгів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 30, 'І встав цар та намісник, і Верні́ка та ті, хто з ними сидів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 31, 'І на́бік вони відійшли, і розмовляли один до одно́го й казали: „Нічого, ва́ртого смерти або ланцюгів, чоловік цей не робить!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 26, 32, 'Агріппа ж до Феста сказав: „Міг би бути відпу́щений цей чоловік, якби не відкликавсь був до ке́саря“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 1, 'А коли постановлено, щоб відпли́нули ми до Італії, то віддано Павла та ще деяких інших ув\'я́знених сотникові, Юлієві на ім\'я́, з полку Августа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 2, 'І посідали ми на корабля адрамі́тського, що пливти́ мав біля місць азійських, та й відча́лили. Із нами був Аріста́рх македо́нець із Солу́ня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 3, 'А другого дня ми пристали в Сидо́ні. До Павла ж Юлій ставивсь по-лю́дському, і дозволив до друзів піти, та їхньої опіки зазнати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 4, 'А ви́рушивши звідти, припливли́ ми до Кіпру, бо вітри́ супроти́вні були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 5, 'Коли ж перепли́нули море, що біля Кілікі́ї й Памфі́лії, то ми прибули́ до Лікі́йської Міри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 6, 'І там сотник знайшов корабля олександрійського, що пли́в в Італію, і всадив нас на нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 7, 'І днів багато помалу пливли́ ми, і насилу насупроти Кніду припли́нули, а що вітер нас не допускав, попливли́ ми додолу на Кріт при Салмо́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 8, 'І коли ми насилу минули його, то припливли́ до одно́го місця, що зветься Доброю При́станню, недалеко якого знахо́диться місто Ласе́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 9, 'А як ча́су минуло багато, і була вже плавба́ небезпечна, бо минув уже й піст, то зачав Павло радити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 10, 'говорячи їм: „О мужі! Я бачу, що буде плавба́ з перешкодами та з великим ущербком не лиш для вантажу́ й корабля, але й для наших душ“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 11, 'Та сотник довіря́в більше стерни́чому та власнико́ві корабля, ніж тому, що Павло говорив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 12, 'А що при́стань була на зимівлю неви́гідна, то більшість давала пораду відпли́нути звідти, щоб, як можна, дістатись до Фініка, і перезимувати в пристані крітській, неприступній західнім вітра́м із пі́вдня та з пі́вночі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 13, 'А як вітер півде́нний повіяв, то поду́мали, що бажа́ння вони досягли́, тому витягли кітви й попливли покрай Кріту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 14, 'Але незаба́ром ударив на них рвучкий вітер, що зветься евроклі́дон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 15, 'А коли корабель був підхо́плений, і не міг противитись вітрові, то йому віддались ми й поне́слися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 16, 'І наїхали ми на один остріве́ць, що Кла́вдою зветься, і чо́вна насилу затримати змогли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 17, 'Коли ж його витягли, то за́собів допомічни́х добирали й корабля підв\'язали. А боявшись, щоб не впасти на Сірт, поспускали вітри́ла, і носилися так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 18, 'А коли зачала́ буря мі́цно нас ки́дати, то другого дня стали ми розванта́жуватись,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 19, 'а третього дня корабельне знаря́ддя ми повикидали власно́руч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 20, 'А коли довгі дні не з\'являлось ні сонце, ні зо́рі, і буря чимала на нас напирала, то останню наді́ю ми втратили, щоб нам урятуватись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 21, 'А як довго не їли вони, то Павло став тоді серед них і промовив: „О мужі, тож треба було мене слухатися та не відпливати від Кріту, — і обминули б були ці терпіння та шкоди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 22, 'А тепер вас благаю триматись на дусі, бо ні о́дна душа з вас не згине, окрім корабля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 23, 'Бо ночі цієї з\'явився мені Ангол Бога, Якому належу й Якому служу́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 24, 'та і прорік: „Не бійся, Па́вле, бо треба тобі перед ке́сарем стати, і ось Бог дарував тобі всіх, хто з тобою пливе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 25, 'Тому́ то тримайтесь на дусі, о мужі, бо я вірую Богові, що станеться так, як було мені сказано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 26, 'І ми мусимо наткнутись на о́стрів якійсь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 27, 'А коли надійшла чотирнадцята ніч, і ми носились по Адріяти́цькому морю, то десь коло пі́вночі стали доми́слюватись моряки, що наближуються до якоїсь землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 28, 'І, запустивши оли́вницю, двадцять сяжнів знайшли. А від \'їхавши трохи, запустити оли́вницю знову, — і знайшли сяжнів п\'ятнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 29, 'І боявшись, щоб не натрапити нам на скеля́сті місця́, ми закинули чотири кі́тві з корми́, і благали, щоб настав день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 30, 'А коли моряки намага́лись утекти́ з корабля́, і чо́вна спускали до моря, вдаючи́, ніби кі́тви закинути з носа хо́чуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 31, 'то сказав Павло сотникові й воякам: „Як вони в кораблі не зоста́нуться, то спасти́сь ви не зможете!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 32, 'Тоді вояки́ перерізали мо́тузи в чо́вна, і дали́ йому впасти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 33, 'А коли розвиднятися стало, то благав Павло всіх, щоб поживу прийняти, і казав: „Чотирна́дцятий день ось сьогодні без їжі ви перебуваєте, очікуючи та нічого не ївши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 34, 'Тому́ то благаю вас ї́жу прийняти, бо це на рятунок вам буде, — бо жодному з вас не спаде з голови й волоси́на!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 35, 'А промовивши це, узяв хліб та подякував Богові перед усіма́, і, поламавши, став їсти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 36, 'Тоді всі підне́слись на дусі, і, стали поживу приймати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 37, 'А всіх душ нас було в кораблі — двісті сімдесят шість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 38, 'І як наїлись вони, то стали полегшувати корабля, викидаючи збіжжя до моря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 39, 'А коли настав день, то вони не могли розпізнати землі, одначе зато́ку якусь там угледіли, що берега пла́ского мала, до якого й ви́рішили, як можна, приплисти́ з кораблем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 40, 'Підняли тоді кі́тви, і повкидали до моря, і порозв\'язували поворо́зки в стерна́, і вітри́ло мале за вітром поставили, — та й покерува́ли до берега.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 41, 'Та ось ми натра́пили на місце, що мало з обох сторін море, і корабель опинивсь на мілко́му: ніс загруз й позоставсь нерухо́мий, а корма́ розбивалася силою хвиль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 42, 'Вояки́ ж були змовилися повбивати в\'язнів, щоб котри́йсь не поплив і не втік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 43, 'Але сотник хотів урятувати Павла, і заборонив їхній на́мір, і звелів усім тим, хто пли́вати вміє, щоб скакали та перші на берег вихо́дили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 27, 44, 'а інші — хто на до́шках, а хто на чімбудь з корабля. І таким чином сталось, що всі врятувались на землю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 1, 'А коли врятувалися ми, то довідалися, що о́стрів той зветься Мелі́та.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 2, 'Тубі́льці ж нам виявили надзвичайну лю́дяність, бо вони запалили огонь, — ішов бо дощ і був холод, — і прийняли́ нас усіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 3, 'Як Павло ж назбирав купу хмизу та й покла́в на огонь, змія́ вискочила через жар, — і почепилась на руку йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 4, 'Як тубільці ж угледіли, що змія́ почепилась на руку йому, зачали́ говори́ти один о́дному: „Либонь цей чоловік душогуб, що йому, від моря врятованому, По́мста жити не дозволила!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 5, 'Він струснув ту звірюку в огонь, — і ніякої шко́ди не зазнав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 6, 'А вони сподівалися, що він спухне або впаде́ мертвий уми́ть. Коли ж довго чекали того та побачили, що нія́кого лиха не сталося з ним, думку змінили й казали, що він бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 7, 'Навкруги ж того місця знахо́дились до́бра начальника о́строва, на ім\'я́ Пу́блія, — він прийняв нас, і три дні ласка́во гости́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 8, 'І сталось, що Пу́бліїв ба́тько лежав, слабий на пропа́сницю та на черві́нку. До нього Павло ввійшов і помолився, і, руки на нього поклавши, уздоро́вив його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 9, 'Якже трапилось це, то й інші на о́строві, що мали хвороби, прихо́дили та вздоровля́лись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 10, 'Вони нас вшанували й великими по́честями, а як ми від\'їжджали, понаклада́ли, чого було треба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 11, 'А по трьох місяцях ми відпливли́ на олександрійському кораблі, що мав знака братів Діоску́рів, і що на о́строві він перези́мував.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 12, 'І, як ми допливли́ в Сіраку́зи, пробули там три дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 13, 'А звідти, пливучи́ понад берегом, прибули́ ми до Ре́ґії, а що вітер південний повіяв за день, то другого дня прибули в Путео́лі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 14, 'де знайшли ми братів, вони ж нас ублагали сім день позостатися в них. І ось так прибули́ ми до Риму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 15, 'А звідти брати, прочувши про нас, назустріч нам вийшли аж до Аппіфо́ру та до Тритаве́рни. Побачивши їх, Павло дякував Богові та посмілі́шав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 16, 'А коли прибули́ ми до Риму, Павло́ві дозволено жити осібно, ураз із вояко́м, що його сторожи́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 17, 'І сталось, по трьох днях Павло скликав знатніших з юдеїв. Як зійшлися ж вони, він промовив до них: „Мужі-браття! Не вчинив я нічого проти люду чи звича́їв отцівських, та проте́ мене ви́дано з Єрусалиму ув\'я́зненого в руки римля́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 18, 'Вони мене вислухали та й хотіли пустити, бож провини смертельної ні однієї в мені не було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 19, 'Та юдеї противилися, тому змушений був я відкли́катися на суд ке́сарів, але не для того, щоб наро́д свій у чо́мусь оска́ржити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 20, 'Тож із цієї причини покликав я вас, щоб побачити й порозмовляти, — бо то за надію Ізраїлеву я обку́тий цими кайда́нами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 21, 'А вони відказали йому: „Не оде́ржали ми ні листів із Юдеї про тебе, ані жоден із братів не прийшов, і не звістив, і не казав чого злого про тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 22, 'Але прагнемо ми, щоб почути від тебе, яку думку ти маєш, бо відо́мо про секту цю нам, що їй скрізь спротивляються“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 23, 'А коли вони визначили йому день, то дуже багато прийшло їх до нього в госпо́ду. А він їм від ра́нку до вечора розповідав, та про Божеє Царство свідо́цтва давав, і переконував їх про Ісуса Зако́ном Мойсея й Пророками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 24, 'І одні вірили в те, про що він говорив, а інші не вірили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 25, 'Вони між собою незгідні були́ й повихо́дили, як промовив Павло одне слово, що добре прорік Дух Святий отцям нашим через пророка Ісаю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 26, 'промовляючи: „Піди до наро́ду цього та й скажи: Ви вухом почуєте, та розуміти не бу́дете, дивитися бу́дете оком, але не побачите!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 27, 'Затовсті́ло бо серце людей цих, тяжко чують на ву́ха вони, і зажмурили очі свої, щоб якось не побачити очима, і не почути ву́хами, і не зрозуміти їм серцем, і не навернутись, щоб Я їх уздоро́вив!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 28, 'Тож нехай для вас буде відо́ме, що послано Боже спасіння оце до поган, — і почують вони!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 29, 'Як промовив він це, розійшлися юдеї, велику суперечку провадивши поміж собою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 30, 'І ці́лих два роки Павло пробув у найнятім домі своїм, і приймав усіх, хто прихо́див до нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 28, 31, 'і проповідував він Боже Царство, та з відвагою повною беззаборо́нно навчав про Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Павло, раб Ісуса Христа, покликаний апо́стол, вибраний для звіща́ння Єва́нгелії Божої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'яку Він перед тим приобіцяв через Своїх пророків у святих Писа́ннях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'про Сина Свого, що тілом був із насіння Давидового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'і об\'явився Сином Божим у силі, за Ду́хом святости, через воскресіння з мертвих, про Ісуса Христа, Господа нашого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'що через Нього прийняли ми благода́ть і апо́стольство на по́слух віри через Ім\'я́ Його між усіма́ народами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'між якими й ви, покликані Ісуса Христа, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'усім, хто знаходиться в Римі, улю́бленим Божим, покликаним святим, — благода́ть вам та мир від Бога, Отця нашого, і Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Отже, насамперед дякую Богові моєму через Ісуса Христа за всіх вас, що віра ваша звіщається по всьому світові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Бо свідок мені Бог, Якому служу́ духом своїм у звіща́нні Єва́нгелії Його Сина, що я безпереста́нно згадую про вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'і в моли́твах своїх за́вжди молюся, щоб воля Божа щасливо попрова́дила мене коли прийти до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Бо прагну вас бачити, щоб подати вам якого дара духовного для змі́цнення вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'цебто потішитись ра́зом між вами спі́льною вірою — і вашою, і моєю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Не хочу ж, щоб ви не знали, браття, що багато разів мав я за́мір прийти до вас, але мені перешко́джувано аж досі, щоб мати який плід і в вас, як і в інших наро́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'А ге́лленам і чужоземцям, розумним і немудрим — я боржни́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Отже, щодо мене, я готовий і вам, хто знаходиться в Римі, звіщати Єва́нгелію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Бо я не соромлюсь Єва́нгелії, бож вона — сила Божа на спасі́ння кожному, хто вірує, перше ж юдеєві, а потім ге́лленові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Праведність бо Божа з\'являється в ній з віри в віру, як написано: „А праведний житиме вірою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Бо гнів Божий з\'являється з неба на всяку безбожність і неправду людей, що правду гаму́ють неправдою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'тому, що те, що можна знати про Бога, явне для них, бо їм Бог об\'явив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Бо Його невиди́ме від створення світу, власне Його вічна сила й Божество, ду́манням про твори стає види́ме. Так що нема їм виправдання,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'бо, пізнавши Бога, не прославляли Його, як Бога, і не дякували, але знікчемні́ли своїми думка́ми, і запа́морочилось нерозумне їхнє серце.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Називаючи себе мудрими, вони потумані́ли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'і славу нетлінного Бога змінили на подобу образа тлінної люди́ни, і птахів, і чотириногих, і га́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Тому́ то й видав їх Бог у пожадливостях їхніх сердець на нечи́стість, щоб вони самі знеславляли тіла свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Вони Божу правду замінили на неправду, і честь віддавали, і служили створінню більш, як Творце́ві, що благослове́нний навіки, амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Через це Бог їх видав на пожадливість гане́бну, — бо їхні жінки замінили природне єдна́ння на протиприродне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Так само й чоловіки, позоставивши природне єдна́ння з жіночою статтю, розпали́лися своєю пожадливістю один до о́дного, і чоловіки з чоловіками сором чинили. І вони прийняли́ в собі відплату, відповідну їхньому блу́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 28, 'А що вони не вважали за потрібне мати Бога в пізна́нні, видав їх Бог на розум переве́рнений, — щоб чинили непристойне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 29, 'Вони повні всякої неправедности, лукавства, заже́рливости, зло́би, повні заздрости, убивства, суперечки, омани, лихих звича́їв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 30, 'обмовники, наклепники, богонена́видники, напасники́, чваньки, пишні, винахідники зла, неслухня́ні батькам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 31, 'нерозумні, зрадники, нелюбовні, немилости́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 32, 'Вони знають при́суд Божий, що ті, хто чинить таке, ва́рті смерти, а проте не тільки самі чинять, але й хвалять тих, хто робить таке.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Ось тому без виправдання ти, кожний чоловіче, що судиш, бо в чо́му осуджуєш іншого, сам себе осуджуєш, бо чиниш те саме й ти, що судиш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'А ми знаємо, що суд Божий поправді на тих, хто чинить таке.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Чи ти ду́маєш, чоловіче, судячи тих, хто чинить таке, а сам робиш таке саме, — що ти втечеш від суду Божого?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Або пого́рджуєш багатством Його до́брости, ла́гідности та довготерпіння, не знаючи, що Божа до́брість провадить тебе до покая́ння?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Та через жорстокість свою й нерозкаяність серця збираєш собі гнів на день гніву та об\'я́влення справедливого суду Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'що „кожному віддасть за його вчинками“:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'тим, хто витривалістю в добрім ділі шукає слави, і чести, і нетління, — життя вічне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'а сварливим та тим, хто противиться правді, але кориться неправді, — лютість та гнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Недоля та у́тиск на всяку душу людини, хто чинить зле, юдея ж перше та ге́ллена,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'а слава, і честь, і мир усякому, хто чинить добре, юдеєві ж перше та ге́лленові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Бо не дивиться Бог на обличчя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Котрі бо згрішили без Зако́ну, без Зако́ну й загинуть, а котрі згрішили в Зако́ні, при́ймуть суд за Зако́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Бо не слухачі Зако́ну справедливі перед Богом, але виконавці Закону ви́правдані бу́дуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Бо коли погани, що не мають Зако́ну, з природи чинять зако́нне, вони, не мавши Зако́ну, самі собі Зако́н,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'що виявляють ді́ло Зако́ну, написане в серця́х своїх, як свідчить їм сумлі́ння та їхні думки́, що то осуджують, то виправдують одна о́дну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'дня, коли Бог, згідно з моїм благові́стям, буде судити таємні речі людей через Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Ось ти звешся юдеєм, і спираєшся на Зако́на, і хвалишся Богом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'і знаєш волю Його, і розумієш, що́ краще, навчившись із Зако́ну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'і маєш певність, що ти провідни́к для сліпих, світло для тих, хто знахо́диться в те́мряві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'вихо́вник нерозумним, учитель дітям, що ти маєш зразок знання́ й правди в Зако́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Отож, ти, що іншого навчаєш, себе самого не вчиш! Проповідуєш не кра́сти, а сам кра́деш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Наказуючи не чинити пере́любу, чиниш пере́люб! Гиду́ючи і́долами, чиниш святокрадство!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Ти, що хва́лишся Зако́ном, зневажаєш Бога пере́ступом Зако́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Бо „через вас зневажається Боже Ймення в поган“, як написано.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Обрі́зання кори́сне, коли виконуєш Зако́на; а коли ти пересту́пник Зако́ну, то обрі́зання твоє стало необрі́занням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Отож, коли необрізаний зберігає постанови Зако́ну, то чи не порахується його необрізання за обрізання?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 27, 'І необрізаний з природи, виконуючи Зако́на, чи не осудить тебе, переступника Закону з Писа́нням і обрі́занням?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 28, 'Бо не той юдей, що є ним назовні, і не то обрізання, що назовні на тілі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 29, 'але той, що є юдей потаємно, духо́во, і обрі́зання — серця духом, а не за буквою; і йому похвала́ не від людей, а від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Отож, що́ має більшого юдей, або яка ко́ристь від обрі́зання?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Багато, на всякий спосіб, а насамперед, що їм довірені були́ Слова́ Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Бо що ж, що не вірували деякі? Чи ж їхнє недовірство знищить вірність Божу?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Зо́всім ні! Бож Бог правдивий, а кожна люди́на неправдива, як написано: „Щоб був Ти ви́правданий у словах Своїх, і переміг, коли будеш судитися“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'А коли наша неправедність виставляє праведність Божу, то що скажемо? Чи ж Бог несправедгливий, коли гнів виявляє? Говорю́ по-лю́дському.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Зо́всім ні! Бож як Бог судитиме світ?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Бо коли Божа правда через мою неправду збі́льшилась на славу Йому, пощо судити ще й мене, як грішника?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'І чи не так, як нас лають, і як деякі гово́рять, ніби ми кажемо: „Робімо зле, щоб вийшло добре?“Справедливий о́суд на таких!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'То що ж? Маємо перевагу? Анітро́хи! Бож ми перед тим довели́, що юдеї й ге́ллени — усі під гріхом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'як написано: „Нема праведного ані о́дного;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'нема, хто розумів би; немає, хто Бога шукав би, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'усі повідступа́ли, ра́зом стали непотрібні, нема доброчинця, нема ні одно́го!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Гріб відкритий — їхнє горло, язиком своїм кажуть неправду, отрута зміїна на їхніх губа́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'уста́ їхні повні прокляття й гірко́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Швидкі їхні ноги, щоб кров проливати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'руїна та злидні на їхніх дорогах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'а дороги миру вони не пізнали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Нема страху Божого перед очима їхніми“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'А ми знаємо, що скільки гово́рить Зако́н, він говорить до тих, хто під Зако́ном, щоб замкнути всякі уста́, і щоб став увесь світ винний Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, 'Бо жодне тіло ділами Зако́ну не ви́правдається перед Ним, — Зако́ном бо гріх пізнається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'А тепер, без Зако́ну, праведність Божа з\'вилась,про яку свідчать Зако́н і Пророки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 22, 'А Божа праведність через віру в Ісуса Христа в усіх і на всіх, хто вірує, бо різниці немає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 23, 'бо всі згрішили, і позбавлені Божої слави,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 24, 'але дарма́ виправдуються Його благода́ттю, через відку́плення, що в Ісусі Христі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 25, 'що Його Бог дав у жертву прими́рення в крові Його через віру, щоб виявити Свою праведність через відпу́щення давніше вчинених гріхів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 26, 'за довготерпі́ння Божого, щоб виявити Свою праведність за теперішнього ча́су, щоб бути Йому праведним, і виправдувати того, хто вірує в Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 27, 'Тож де похвальба́? Виключена. Яким зако́ном? Законом діл? Ні, але зако́ном віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 28, 'Отож, ми визнаємо, що люди́на виправдується вірою, — без діл Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 29, 'Хіба ж Бог тільки для юдеїв, а не й для поган? Так, і для поган,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 30, 'бо є один тільки Бог, що ви́правдає обрізання з віри й необрізання через віру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 31, 'Тож чи не нищимо ми Зако́на вірою? Зо́всім ні, — але зміцнюємо Зако́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Що ж, скажемо, знайшов Авраа́м, наш отець за тілом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Бо коли Авраам ви́правдався діла́ми, то він має похвалу, та не в Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Що бо Писа́ння говорить? „Увірував Авраам Богові, і це йому залічено в праведність“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'А заплата викона́вцеві не рахується з милости, але з обов\'язку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'А тому́, хто не виконує, але вірує в Того, Хто виправдує нечестивого, віра його порахується в праведність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Як і Давид називає блаженною люди́ну, якій рахує Бог праведність без діл:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, '„Блаженні, кому прощені беззаконня, і кому прикриті гріхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Блаженна людина, якій Господь не порахує гріха́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Чи ж це блаже́нство з обрізання чи з необрізання? Бо говоримо, що „віра залічена Авраамові в праведність“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Як же залічена? Як був в обрізанні, чи в необрізанні? Не в обрізанні, але в необрізанні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'І прийняв він ознаку обрізання, — печать праведности через віру, що її в необрізанні мав, щоб йому бути отцем усіх віруючих, хоч були необрізані, щоб і їм залічено праведність,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'і отцем обрізаних, не тільки тих, хто з обрізання, але й тих, хто ходить по слідах віри, що її в необрізанні мав наш отець Авраам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Бо обі́тницю Авраамові чи його насінню, що бути йому спадкоємцем світу, дано не Зако́ном, але праведністю віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Бо коли спадкоємці ті, хто з Зако́ну, то спорожніла віра й зні́вечилась обі́тниця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Бо Зако́н чинить гнів; де ж немає Закону, немає й пере́ступу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Через це з віри, щоб було з милости, щоб обі́тниця певна була всім нащадкам, не тільки тому́, хто з Закону, але й тому́, хто з віри Авраама, що отець усім нам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'як написано: „Отцем багатьох наро́дів Я поставив тебе,“— перед Богом, Якому він вірив, Який оживляє мертвих і кличе неіснуюче, як існуюче.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Він — проти надії — увірував у надії, що стане батьком багатьох народів, за сказаним: „Таке числе́нне буде насіння твоє!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'І не знеміг він у вірі, і не вважав свого тіла за вже омертвіле, бувши майже сторічним, ні утро́би Сариної за змертвілу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'і не мав сумніву в обі́тницю Божу через недові́рство, але зміцни́вся в вірі, і віддав славу Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, 'і був зовсім певний, що Він має силу й виконати те, що обіцяв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'Тому й „залічено це йому в праведність“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'Та не написано за нього одно́го, що залічено йому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'а за нас, — залі́читься й нам, що віруємо в Того, Хто воскресив із мертвих Ісуса, Господа нашого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'що був виданий за наші гріхи, і воскрес для ви́правдання нашого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Отож, ви́правдавшись вірою, майте мир із Богом через Господа нашого Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'через Якого ми вірою одержали доступ до тієї благода́ті, що в ній стоїмо́, і хва́лимось наді́єю слави Божої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'І не тільки нею, але й хвалимося в утисках, знаючи, що утиски приносять терпели́вість,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'а терпеливість — до́свід, а досвід — надію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'а надія не засоро́мить, бо любов Божа вилилася в наші серця Святим Духом, даним нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Бо Христос, коли ми були́ ще недужі, своєї пори помер за нечестивих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Бо навряд чи помре хто за праведника, ще бо за доброго може хто й відважиться вмерти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'А Бог дово́дить Свою любов до нас тим, що Христос умер за нас, коли ми були́ ще грішниками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Тож тим більше спасемося Ним від гніву тепер, коли кров\'ю Його ми ви́правдані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Бо коли ми, бувши ворогами, примирилися з Богом через смерть Сина Його, то тим більше, примирившися, спасе́мося життя́м Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'І не тільки це, але й хва́лимося в Бозі через Господа нашого Ісуса Христа, що через Нього оде́ржали ми тепер прими́рення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Тому́ то, як через одно́го чоловіка ввійшов до світу гріх, а гріхом смерть, так прийшла й смерть в усіх людей через те, що всі згрішили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Гріх бо був у світі й до Зако́ну, але гріх не ста́виться в прови́ну, коли немає Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Та смерть панувала від Ада́ма аж до Мойсея і над тими, хто не згрішив, подібно переступу Ада́ма, який є образ майбу́тнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Але не такий дар благода́ті, як пере́ступ. Бо коли за пере́ступ одно́го померло багато, то тим більш благода́ть Божа й дар через благода́ть однієї Люди́ни, Ісуса Христа, щедро спливли́ на багатьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'І дар не такий, як те, що сталось від одно́го, що згрішив; бо суд за оди́н про́гріх — на о́суд, а дар благода́ті — на ви́правдання від багатьох про́гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Бо коли за пере́ступ одно́го смерть панувала через одно́го, то тим більше ті, хто приймає рясноту́ благода́ті й дар праведности, запанують у житті через одно́го Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Ось тому́, як через пере́ступ одно́го на всіх людей прийшов о́суд, так і через праведність Одно́го прийшло ви́правдания для життя на всіх людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Бо як через непо́слух одно́го чоловіка багато-хто стали грішними, так і через по́слух Одно́го багато-хто стануть праведними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Зако́н же прийшов, щоб збільши́вся пере́ступ. А де збільши́вся гріх, там зарясніла благодать,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'щоб, як гріх панував через смерть, так само й благода́ть запанувала через праведність для життя вічного Ісусом Христом, Господом нашим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, 'Що ж скажемо? Позоста́немся в гріху́, щоб благодать примно́жилась? Зо́всім ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, 'Ми, що вмерли для гріха, як ще будемо жити в нім?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, 'Чи ви не знаєте, що ми всі, хто христився у Христа Ісуса, у смерть Його христилися?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'Отож, ми поховані з Ним хрищенням у смерть, щоб, як воскрес Христос із мертвих славою Отця, так щоб і ми стали ходити в обно́вленні життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Бо коли ми з\'єдна́лися подо́бою смерти Його, то з\'єднаємось і подобою воскре́сення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'знаючи те, що наш давній чоловік розп\'я́тий із Ним, щоб зни́щилось тіло гріхо́вне, щоб не бути нам більше рабами гріха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'бо хто вмер, той звільни́всь від гріха!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'А коли ми померли з Христом, то віруємо, що й жити з Ним бу́демо,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'знаючи, що Христос, воскре́снувши з мертвих, уже більш не вмирає, — смерть над Ним не панує вже більше!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Бо що вмер Він, то один раз умер для гріха, а що живе, то для Бога живе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Так само ж і ви вважайте себе за мертвих для гріха й за живих для Бога в Христі Ісусі, Господі нашім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Тож нехай не панує гріх у смерте́льному вашому тілі, щоб вам слухатись його пожадли́востей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'і не віддавайте членів своїх гріхові за знаря́ддя неправедности, але віддайте себе Богові, як ожилих із мертвих, а члени ваші — Богові за знаря́ддя праведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, 'Бо хай гріх не панує над вами, — ви бо не під Законом, а під благода́ттю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'Що ж? Чи бу́демо грішити, бо ми не під Законом, а під благода́ттю? Зо́всім ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'Хіба ви не знаєте, що кому віддаєте себе за рабів на по́слух, то ви й раби того, кого слухаєтесь, — або гріха на смерть, або послуху на праведність?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, 'Тож дяка Богові, що ви, бувши рабами гріха, від серця послухались того роду науки, якому ви себе віддали́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'А звільни́вшися від гріха́, стали рабами праведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'Говорю́ я по-лю́дському, через неміч вашого тіла. Бо як ви віддавали були члени ваші за рабів нечи́стості й беззако́нню на беззако́ння, так тепер віддайте члени ваші за рабів праведности на освя́чення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'Бо коли були́ ви рабами гріха, то були вільні від праведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Який же плід ви мали тоді? Такі речі, що ними соромитесь тепер, бо кінець їх — то смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'А тепер, звільни́вшися від гріха й ставши рабами Богові, маєте плід ваш на освячення, а кінець — життя вічне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Бо заплата за гріх — смерть, а дар Божий — вічне життя в Христі Ісусі, Господі нашім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 1, 'Чи ви не знаєте, браття, — бо говорю́ тим, хто знає Закона, — що Зако́н панує над люди́ною, поки вона живе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 2, 'Бо замі́жня жінка, поки живе чоловік, прив\'язана до нього Законом; а коли помре чоловік, вона звільняється від закону чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 3, 'Тому то, поки живе чоловік, вона буде вважатися перелю́бницею, якщо стане дружи́ною іншому чоловікові; коли ж чоловік помре, вона вільна від Зако́ну, і не буде перелю́бницею, якщо стане за дружи́ну іншому чоловікові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 4, 'Так, мої браття, і ви вмерли для Зако́ну через тіло Христове, щоб належати вам іншому, Воскре́слому з мертвих, щоб прино́сити плід Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 5, 'Бо коли ми жили за ті́лом, то при́страсті гріховні, що похо́дять від Закону, ді́яли в наших членах, щоб прино́сити плід смерти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 6, 'А тепер ми звільни́лись від Закону, умерши для того, чим були зв\'язані, щоб служити нам обно́вленням духа, а не старістю букви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 7, 'Що ж скажемо? Чи Зако́н — то гріх? Зо́всім ні! Але я не пізнав гріха, як тільки через Зако́н, бо я не знав би пожадливости, коли б Закон не наказував: „Не пожада́й“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 8, 'Але гріх, узявши при́від від заповіді, зробив у мені всяку пожадливість, бо без Закону гріх мертвий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 9, 'А я колись жив без Закону, але, коли прийшла заповідь, то гріх ожив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 10, 'а я вмер; і сталася мені та заповідь, що для життя, на смерть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 11, 'бо гріх, узявши причину від заповіді, звів мене, і нею вмертви́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 12, 'Тому́ то Зако́н святий, і заповідь свята, і праведна, і добра.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 13, 'Тож чи добре стало мені смертю? Зо́всім ні! Але гріх, щоб стати гріхом, приніс мені смерть добром, щоб гріх став мі́цно грі́шний через за́повідь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 14, 'Бо ми знаємо, що Зако́н духовний, а я тіле́сний, про́даний під гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 15, 'Бо що́ я виконую, не розумію; я бо чиню не те, що́ хочу, але що́ нена́виджу, те я роблю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 16, 'А коли роблю́ те, чого я не хо́чу, то згоджуюсь із Законом, що він добрий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 17, 'а тому вже не я це виконую, але гріх, що живе в мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 18, 'Знаю бо, що не живе в мені, цебто в тілі моїм, добре; бо бажа́ння лежить у мені, але щоб виконати добре, того не знахо́джу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 19, 'Бо не роблю́ я доброго, що хочу, але зле, чого не хочу, це чиню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 20, 'Коли ж я роблю́ те, чого не хочу, то вже не я це виконую, але гріх, що живе в мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 21, 'Тож знахо́джу зако́на, коли хочу робити добро, — що зло лежить у мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 22, 'Бо маю задово́лення в Законі Божому за вну́трішнім чолові́ком,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 23, 'та бачу інший зако́н у членах своїх, що воює проти закону мого розуму, і поло́нить мене законом гріховним, що знахо́диться в членах моїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 24, 'Нещасна я люди́на! Хто мене ви́зволить від тіла цієї смерти?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 25, 'Дякую Богові через Ісуса Христа, Господа нашого. Тому́ то я сам служу́ розумом Законові Божому, але тілом — закону гріховному.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 1, 'Тож немає тепер жодного о́суду тим, хто ходить у Христі Ісусі не за тілом, а за Духом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 2, 'бо зако́н Духа життя в Христі Ісусі визволив мене від зако́ну гріха й смерти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 3, 'Бо що було неможливе для Закону, у чо́му був він безсилий тілом, — Бог послав Сина Свого в подобі гріховного тіла, і за гріх осудив гріх у тілі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 4, 'щоб ви́коналось ви́правдання Закону на нас, що ходимо не за тілом, а за Духом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 5, 'Бо ті, хто ходить за тілом, ду́мають про тілесне, а хто за Духом — про духовне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 6, 'Бо думка тілесна — то смерть, а думка духовна — життя та мир,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 7, 'думка бо тілесна — ворожне́ча на Бога, бо не ко́риться Законові Божому, та й не може.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 8, 'І ті, хто хо́дить за тілом, не можуть догодити Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 9, 'А ви не в тілі, але в Дусі, бо Дух Божий живе в вас. А коли хто не має Христового Духа, той не Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 10, 'А коли Христос у вас, то хоч тіло мертве через гріх, але дух живий через праведність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 11, 'А коли живе в вас Дух Того, Хто воскресив Ісуса з мертвих, то Той, хто підняв Христа з мертвих, ожи́вить і смертельні тіла ваші через Свого Духа, що живе в вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 12, 'Тому́ то, браття, ми не боржники́ тіла, щоб жити за тілом;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 13, 'бо коли живе́те за тілом, то маєте вмерти, а коли Духом умертвля́єте тілесні вчинки, то бу́дете жити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 14, 'Бо всі, хто водиться Духом Божим, вони сини Божі;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 15, 'бо не взяли́ ви духа неволі знов на страх, але взяли ви Духа сині́вства, що через Нього кличемо: „Авва, Отче!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 16, 'Сам Цей Дух сві́дчить ра́зом із духом нашим, що ми — діти Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 17, 'А коли діти, то й спадкоємці, спадкоємці ж Божі, а співспадкоємці Христові, коли тільки ра́зом із Ним ми терпимо́, щоб разом із Ним і просла́витись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 18, 'Бо я ду́маю, що страждання тепе́рішнього ча́су нічого не варті супроти тієї слави, що має з\'явитися в нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 19, 'Бо чека́ння створі́ння очікує з\'я́влення синів Божих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 20, 'бо створі́ння покорилось марно́ті не добровільно, але через того, хто скори́в його, в надії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 21, 'що й саме створіння ви́зволиться від неволі тління на волю слави синів Божих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 22, 'Бо знаємо, що все створі́ння ра́зом зідхає й ра́зом мучиться аж досі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 23, 'Але не тільки воно, але й ми самі, маючи зача́ток Духа, і ми самі в собі зідхаємо, очікуючи синівства, відкуплення нашого тіла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 24, 'Надією бо ми спасли́ся. Надія ж, коли бачить, не є надія, бо хто що́ бачить, чому б того й наді́явся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 25, 'А коли сподіва́ємось, чого не бачимо, то очікуємо того з терпеливістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 26, 'Так само ж і Дух допомагає нам у наших не́мочах; бо ми не знаємо, про що маємо молитись, як належить, але Сам Дух заступається за нас невимо́вними зідха́ннями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 27, 'А Той, Хто досліджує серця́, знає, яка думка Духа, бо з волі Божої заступається за святих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 28, 'І знаємо, що тим, хто любить Бога, хто покликаний Його постановою, усе допомагає на добре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 29, 'Бо кого Він передба́чив, тих і призна́чив, щоб були подібні до о́бразу Сина Його, щоб Він був перворі́дним поміж багатьма́ братами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 30, 'А кого Він призначив, тих і покликав, а кого покликав, тих і ви́правдав, а кого ви́правдав, тих і просла́вив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 31, 'Що ж скажем на це? Коли за нас Бог, то хто проти нас?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 32, 'Той же, Хто Сина Свого не пожалів, але видав Його за всіх нас, — як же не дав би Він нам із Ним і всього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 33, 'Хто оска́ржувати буде Божих вибранців? Бог Той, що виправдує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 34, 'Хто ж той, що засу́джує? Христос Ісус є Той, що вмер, надто й воскрес, — Він право́руч Бога, і Він і заступається за нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 35, 'Хто нас розлучить від любови Христової? Чи недоля, чи утиск, чи переслі́дування, чи голод, чи нагота́, чи небезпека, чи меч?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 36, 'Як написано: „За Тебе нас цілий день умертвля́ють, нас уважають за овець, прирече́них на зако́лення“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 37, 'Але в цьому всьому ми перемагаємо Тим, Хто нас полюбив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 38, 'Бо я пересві́дчився, що ні смерть, ні життя, ні анголи́, ні вла́ди, ні тепе́рішнє, ні майбу́тнє, ні сили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 39, 'ні вишина́, ні глибина́, ані інше яке створіння не зможе відлучити нас від любови Божої, яка в Христі Ісусі, Господі нашім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 1, 'Кажу́ правду в Христі, не обманюю, як сві́дчить мені моє сумлі́ння через Духа Святого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 2, 'що маю велику скорбо́ту й невпинну му́ку для серця свого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 3, 'Бо я бажав би сам бути відлу́чений від Христа замість братів моїх, рідних мені тілом;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 4, 'вони ізра́їльтяни, що їм належить сині́вство, і слава, і заповіти, і законода́вство, і богослужба, і обі́тниці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 5, 'що їхні й отці, і від них же тілом Христос, що Він над усіма́ Бог, благослове́нний, навіки, амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 6, 'Не так, щоб Слово Боже не збуло́ся. Бо не всі ті ізра́їльтяни, хто від Ізраїля,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 7, 'і не всі діти Авраамові, хто від насіння його, але: „в Ісаку буде насіння тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 8, 'Цебто, не тілесні діти — то діти Божі, але діти обі́тниці признаю́ться за насіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 9, 'А слово обі́тниці таке: „На той час прийду́, і бу́де син у Сари“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 10, 'І не тільки це, але й Реве́кка зачала́ дітей від одно́го ложа отця нашого Ісака,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 11, 'бо коли вони ще не народились, і нічо́го доброго чи злого не вчинили, — щоб позоста́лась постанова Божа у вибра́нні');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 12, 'не від учинків, але́ від То́го, Хто кличе, — сказано їй: „Більший служитиме меншому“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 13, 'як і написано: „Полюбив Я Якова, а Ісава знена́видів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 14, 'Що ж скажемо? Може в Бога неправда? Зо́всім ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 15, 'Бо Він каже Мойсеєві: „Помилую, кого хочу помилувати, і змилосе́рджуся, над ким хочу змилосе́рдитись“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 16, 'Отож, не залежить це ні від то́го, хто хоче, ні від того, хто біжить, але від Бога, що милує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 17, 'Бо Писа́ння говорить фараонові: „Власне на те Я поставив тебе, щоб на тобі показати Свою силу, і щоб звістилось по ці́лій землі Моє Йме́ння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 18, 'Отож, кого хоче — Він милує, і кого хоче — ожорсто́чує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 19, 'А ти скажеш мені: „Чого ж іще Він докоря́є, бо хто може проти́витись волі Його?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 20, 'Отже, хто́ ти, чоловіче, що ти спереча́єшся з Богом? Чи скаже тво́риво творце́ві: Пощо ти зробив мене так?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 21, 'Чи ганча́р не має вла́ди над глиною, щоб із того самого міси́ва зробити одну посу́дину на честь, а одну на нечесть?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 22, 'Тож Бог, бажаючи показати гнів і виявити могутність Свою, щади́в із великим терпінням посу́дини гніву, що готові були на погибіль,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 23, 'і щоб виявити багатство слави Своєї на посудинах милосердя, що їх приготува́в на славу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 24, 'на нас, що їх і покликав не тільки від юдеїв, але й від поган.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 25, 'Як і в Осії Він говорить: „Назву Своїм наро́дом не людей Моїх, і не улю́блену — улю́бленою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 26, 'і на місці, де сказано їм: Ви не Мій наро́д, там на́звані будуть синами Бога Живого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 27, 'А Ісая взиває про Ізраїля: „Коли б число синів Ізра́їлевих було, як мо́рський пісок, то тільки останок спасеться,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 28, 'бо вирок закінчений та скорочений у праведності учинить Господь на землі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 29, 'І як Ісая віщував: „Коли б Госпо́дь Савао́т не лишив нам насіння, то ми стали б, як Содо́м, і подібні були б до Гомо́рри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 30, 'Що ж скажемо? Що погани, які не шукали праведности, досягли праведности, тієї праведности, що від віри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 31, 'а Ізраїль, що шукав Закона праведности, не досяг Закону праведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 32, 'Чому́? Бо шукали не з віри, але якби з учинків Зако́ну; вони бо спіткнулись об камінь спотика́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 33, 'як написано: „Ось Я кладу́ на Сіоні камінь спотика́ння та скелю спокуси, і кожен, хто вірує в Нього, не посоро́миться!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 1, 'Браття, бажа́ння мого серця й молитва до Бога за Ізраїля на спасі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 2, 'Бо я свідчу їм, що вони мають ре́вність про Бога, але не за розумом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 3, 'Вони бо, не розуміючи праведности Божої, і силкуючись поставити власну праведність, не покорились праведності Божій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 4, 'Бо кінець Зако́ну — Христос на праведність кожному, хто вірує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 5, 'Мойсей бо пише про праведність, що від Закону, що „люди́на, яка його виконує, буде ним жити“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 6, 'А про праведність, що від віри, говорить так: „Не кажи в своїм серці: Хто вийде на небо?“цебто зве́сти додолу Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 7, 'або: „Хто зі́йде в безодню?“цебто ви́вести з мертвих Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 8, 'Але що каже ще? „Бли́зько тебе слово, — в устах твоїх і в серці твоїм“, цебто слово віри, що його проповідуємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 9, 'Бо коли ти уста́ми своїми визнаватимеш Ісуса за Господа, і будеш вірувати в своїм серці, що Бог воскресив Його з мертвих, то спасешся,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 10, 'бо серцем віруємо для праведности, а устами іспові́дуємо для спасі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 11, 'Каже бо Писа́ння: „Кожен, хто вірує в Нього, не буде засоро́млений“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 12, 'Бо нема різниці поміж юдеєм та ге́лленом, бо той же Госпо́дь є Господом усіх, багатий для всіх, хто кличе Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 13, 'Бо „кожен, хто покличе Господнє Ім\'я, буде спасе́ний“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 14, 'Але як покличуть Того, в Кого не ввірували? А як увірують у Того, що про Нього не чули? А як почують без проповідника?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 15, 'І як будуть проповідувати, коли не будуть по́слані? Як написано: „Які гарні ноги благовісників миру, благовісників добра́“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 16, 'Але не всі послухались Єва́нгелії. Бо Ісая каже: „Господи, хто повірив тому, що почув був від нас?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 17, 'Тож віра від слу́хання, а слу́хання через Слово Христо́ве.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 18, 'Та кажу́: Чи не чули вони? Отож: „По всій землі їхній голос пішов, і їхні слова́ в кінці світу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 19, 'Але кажу́: Чи Ізраїль не знав? Перший Мойсей говорить: „Я викличу заздрість у вас ненаро́дом, — роздражню́ вас нерозумним народом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 20, 'А Ісая сміли́во говорить: „Знайшли Мене ті, хто Мене не шукав, відкрився Я тим, хто не питався про Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 21, 'А про Ізраїля каже: „Я руки Свої цілий день простягав до людей неслухня́них і суперечних!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 1, 'Отож я питаю: Чи ж Бог відкинув наро́да Свого́? Зо́всім ні! Бо й я ізра́їльтянин, із насіння Авраамового, Веніями́нового племени.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 2, 'Не відкинув Бог наро́да Свого́, що його перше знав. Чи ви не знаєте, що гово́рить Писа́ння „про Іллю“, як він ска́ржиться Богові на Ізраїля, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 3, '„Господи, вони повбивали пророків Твоїх, і Твої же́ртівники поруйнували, і лишився я сам, і шукають моєї душі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 4, 'Та що каже йому Божа відповідь: „Я для Себе зоставив сім тисяч мужа, що перед Ваа́лом колін не схилили“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 5, 'Також і тепе́рішнього ча́су залиши́вся останок за ви́бором благодаті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 6, 'А коли за благода́ттю, то не з учинків, інакше благода́ть не була́ б благода́ттю. А коли з учинків, то це більше не благода́ть, інакше вчи́нок не є вже вчинок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 7, 'Що ж? Чого Ізраїль шукає, того не оде́ржав, та оде́ржали ви́брані, а останні затверді́ли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 8, 'як написано: „Бог дав їм духа засипа́ння, очі, щоб не бачили, і ву́ха, щоб не чули, аж до сього́днішнього дня“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 9, 'А Дави́д каже: „Нехай станеться стіл їхній за сітку й за па́стку, і на спокусу, та їм на заплату;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 10, 'нехай потемні́ють їхні очі, щоб не бачили, хай наза́вжди зігне́ться хребе́т їхній!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 11, 'Тож питаю: Чи ж спіткну́лись вони, щоб упасти? Зо́всім ні! Але з їхнього зане́паду — спасі́ння поганам, щоб ви́кликати за́здрість у них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 12, 'А коли їхній зане́пад — багатство для світу, а їхнє упоко́рення — багатство поганам, — скільки ж більш повнота́ їхня?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 13, 'Кажу́ бо я вам, поганам: через те, що я апо́стол поганів, я хвалю́ свою службу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 14, 'може як викличу за́здрість у своїх за тілом, і спасу́ де́кого з них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 15, 'Коли ж відки́нення їх — то прими́рення світу, то що́ їхнє прийняття́, як не життя з мертвих?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 16, 'А коли святий пе́рвісток, то й тісто святе; а коли святий корінь, то й ві́ття святе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 17, 'Коли ж деякі з галу́зок відломи́лися, а ти, бувши дике оливне дерево, прищепи́вся між них і став спільнико́м то́вщу оли́вного ко́реня,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 18, 'то не вихваляйся перед галу́зками; а коли вихваля́єшся, то знай, що не ти носиш кореня, але корінь тебе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 19, 'Отже скажеш: „Галу́зки відломи́лися, щоб я прищепи́вся“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 20, 'Добре. Вони відломились невірством, а ти тримаєшся вірою; не величайся, але бійся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 21, 'Бо коли Бог природних галу́зок не пожалував, то Він і тебе не пожа́лує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 22, 'Отже, бач до́брість і суво́рість Божу, — на відпалих суворість, а на тебе до́брість Божа, коли перебу́деш у до́брості, коли ж ні, то й ти бу́деш відтя́тий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 23, 'Та й вони, коли не зоста́нуться в невірстві, прище́пляться, бо має Бог силу їх знов прищепи́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 24, 'Бо коли ти відтя́тий з оливки, дикої з природи, і проти природи заще́плений до доброї оливки, то скільки ж більше ті, що природні, прище́пляться до своєї власної оливки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 25, 'Бо не хо́чу я, браття, щоб ви не знали цієї таємниці, — щоб не були́ ви високої думки про себе, що жорстокість ста́лась Ізраїлеві поча́сти, аж поки не вві́йде повне число поган,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 26, 'і так увесь Ізраїль спасеться, як написано: „При́йде з Сіо́ну Спаситель, і відве́рне безбожність від Якова,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 27, 'і це запові́т їм від Мене, коли відійму́ гріхи їхні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 28, 'Тож вони за Єва́нгелією вороги ради вас, а за вибором — улю́блені ради отців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 29, 'Бо да́ри й покли́кання Божі невідмінні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 30, 'Бо як і ви були́ колись неслухняні Богові, а тепер поми́лувані через їхній непо́слух,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 31, 'так і вони тепер спроти́вились для поми́лування вас, щоб і самі були помилувані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 32, 'Бо замкнув Бог усіх у непо́слух, щоб помилувати всіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 33, 'О глиби́но багатства, і премудрости, і знання́ Божого! Які недовідо́мі при́суди Його, і недослі́джені дороги Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 34, '„Бо хто розум Господній пізнав? Або хто був дорадник Йому?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 35, 'Або хто давніш Йому дав, і йому бу́де відда́но?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 36, 'Бо все з Нього, через Нього і для Нього! Йому слава навіки. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 1, 'Тож благаю вас, браття, через Боже милосердя, — повіддавайте ваші тіла на жертву живу, святу, приємну Богові, як розумну службу вашу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 2, 'і не стосу́йтесь до віку цього, але перемініться відно́вою вашого розуму, щоб пізнати вам, що́ то є воля Божа, — добро, приємність та доскона́лість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 3, 'Через да́ну мені благода́ть кажу́ кожному з вас не ду́мати про себе більш, ніж належить ду́мати, але ду́мати скромно, у міру віри, як кожному Бог наділи́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 4, 'Бо як в однім тілі маємо багато членів, а всі члени мають не однакове ді́яння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 5, 'так багато нас є одне тіло в Христі, а зосібна ми один о́дному члени.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 6, 'І ми маємо різні да́ри, згідно з благода́ттю, да́ною нам: коли пророцтво — то виконуй його́ в міру віри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 7, 'а коли служіння — будь на служі́ння, коли вчитель — на навча́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 8, 'коли втіши́тель — на потіша́ння, хто подає — у простоті, хто голову́є — то з пильністю, хто милосе́рдствує — то з привітністю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 9, 'Любов нехай буде нелицемірна; нена́видьте зло та тулі́ться до доброго!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 10, 'Любіть один о́дного братньою любов\'ю; випереджа́йте один о́дного пошаною!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 11, 'У ре́вності не лінуйтеся, духом палайте, служіть Господе́ві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 12, 'тіштесь надією, утиски терпіть, перебувайте в молитві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 13, 'беріть у́діл у потребах святих, будьте гостинні до чужи́нців!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 14, 'Благословляйте тих, хто вас переслідує; благословляйте, а не проклинайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 15, 'Тіштеся з тими, хто тішиться, і плачте з отими, хто плаче!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 16, 'Ду́майте між собою одна́ково; не величайтеся, але́ наслідуйте слухня́них; „не вважайте за мудрих себе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 17, 'Не платіть ніко́му злом за зло, дбайте про добре перед усіма́ людьми́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 18, 'Коли можливо, якщо це залежить від вас — живіть у мирі зо всіма́ людьми́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 19, 'Не мстіться самі, улю́блені, але дайте місце гніву Божому, бо написано: „Мені помста належить, Я відплачу́, говорить Господь“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 20, 'Отож, як твій ворог голодний, — нагодуй його; як він пра́гне, — напій його, бо, роблячи це, ти згорта́єш розпа́лене ву́гілля йому на голову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 21, 'Не будь переможений злом, але перемагай зло добром!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 1, 'Нехай кожна люди́на ко́риться вищій вла́ді, бо немає вла́ди, як не від Бога, і вла́ди існуючі встановлені від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 2, 'Тому той, хто противиться вла́ді, противиться Божій постанові; а ті, хто противиться, самі ві́зьмуть о́суд на себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 3, 'Бо володарі — по́страх не на добрі діла, а на злі. Хочеш не боятися вла́ди? Роби добро, і матимеш похвалу́ від неї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 4, 'бо володар — Божий слуга, тобі на добро. А як чиниш ти зле, то бійся, бо неда́рмо він носить меча́, він бо Божий слуга, ме́сник у гніві злочи́нцеві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 5, 'Тому треба кори́тися не тільки ради стра́ху кари, але й ради сумління.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 6, 'Через це ви й пода́тки даєте, бо вони служи́телі Божі, саме тим за́вжди зайняті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 7, 'Тож віддайте належне усім: кому податок — податок, кому ми́то — мито, кому страх — страх, кому честь — честь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 8, 'Не будьте винні ніко́му нічо́го, крім того, щоб любити один о́дного. Бо хто іншого любить, той виконав Зако́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 9, 'Бо заповіді: „Не чини пере́любу“, „Не вбивай“, „Не кради́“, „Не свідку́й неправдиво“, „Не пожада́й“й які інші, вони мі́стяться всі в цьому слові: „Люби свого бли́жнього, як самого себе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 10, 'Любов не чинить зла ближньому, тож любов — викона́ння Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 11, 'І це тому́, що знаєте час, що пора нам уже пробуди́тись від сну. Бо тепер спасі́ння ближче до нас, аніж тоді, коли ми ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 12, 'Ніч минула, а день набли́зився, тож відкиньмо вчинки те́мряви й зодягнімось у зброю світла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 13, 'Як удень, поступаймо доброчесно, не в гульні та п\'я́нстві, не в пере́любі та розпусті, не в сварні́ та за́здрощах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 14, 'але зодягні́ться Господом Ісусом Христо́м, а дого́дження тілу не обе́ртайте на пожадли́вість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 1, 'Слабо́го в вірі приймайте, але не для суперечок про погляди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 2, 'Один бо вірує, що можна їсти все, а не́мічний споживає ярину́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 3, 'Хто їсть, нехай не погорджує тим, хто не їсть. А хто не їсть, нехай не осуджує того, хто їсть, — Бог бо прийняв його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 4, 'Ти хто такий, що судиш чужого раба? Він для пана свого стоїть або падає; але він усто́їть, бо має Бог силу поставити його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 5, 'Один вирі́знює день від дня, інший же про кожен день судить одна́ково. Нехай кожен за власною думкою тримається свого переко́нання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 6, 'Хто вважає на день, — для Господа вважає, а хто не вважає на день, — для Господа не вважає. Хто їсть, — для Господа їсть, бо дякує Богові. А хто не їсть, — для Господа не їсть, і дякує Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 7, 'Бо ніхто з нас не живе сам для себе, і не вмирає ніхто сам для себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 8, 'Бо коли живемо́ — для Господа живемо́, і коли вмира́ємо — для Господа вмираємо. І чи живемо́, чи вмира́ємо — ми Господні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 9, 'Бо Христос на те й умер, і ожив, щоб панувати і над мертвими, і над живими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 10, 'А ти на́що осуджуєш брата свого́? Чи чого ти пого́рджуєш братом своїм? Бо всі станемо перед судним престолом Божим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 11, 'Бо написано: „Я живу, каже Госпо́дь, і схи́литься кожне коліно передо Мною, і ви́знає Бога кожен язик!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 12, 'Тому кожен із нас сам за себе дасть відповідь Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 13, 'Отож, не будемо більше осуджувати один о́дного, але краще судіть про те, щоб не давати братові спотика́ння та спокуси.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 14, 'Я знаю, і пересвідчений у Господі Ісусі, що нема нічо́го нечистого в само́му собі; тільки коли хто вважає що за нечисте, тому́ воно нечисте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 15, 'Коли ж через поживу сумує твій брат, то вже не за любов\'ю пово́дишся ти, — не губи своєю поживою того́, за кого Христос був умер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 16, 'Нехай ваше добре не зневажа́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 17, 'Бо Царство Боже не пожи́ва й питво́, але праведність, і мир, і радість у Дусі Святім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 18, 'Хто цим служить Христові, той Богові милий і шано́ваний поміж людьми́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 19, 'Отож, пильнуймо про мир, та про те, що на збудува́ння один о́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 20, 'Не руйнуй діла Божого ради поживи, — усе бо чисте, але зле люди́ні, що їсть на спотика́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 21, 'Добре не їсти м\'яса, ані пити вина, ані робити такого, від чого брат твій гірши́ться, або споку́шується, або слабне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 22, 'Ти маєш віру? Май її сам про себе перед Богом. Блаженний той, хто не осуджує самого себе за те, про що випробо́вується!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 23, 'А хто має сумнів, коли їсть, буде осу́джений, бо не робить із віри, а що не від віри, те гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 24, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 25, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 26, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 1, 'Ми, сильні, повинні не́сти слабості безсилих, а не собі догоджати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 2, 'Кожен із нас нехай догоджа́є ближньому на добро для збудува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 3, 'Бо й Христос не Собі догоджав, але як написано: „Зневаги тих, хто Тебе зневажає, упали на Мене“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 4, 'А все, що давніше написане, написане нам на науку, щоб терпінням і потіхою з Писа́ння ми мали надію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 5, 'А Бог терпеливости й потіхи нехай дасть вам бути однодумними між собою за Христом Ісусом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 6, 'щоб ви однодушно, одними у́стами сла́вили Бога й Отця Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 7, 'Приймайте тому́ один о́дного, як і Христос прийняв нас до Божої слави.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 8, 'Кажу́ ж, що Христос для обрі́заних став за слу́жку ради Божої правди, щоб отцям потвердити обі́тниці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 9, 'а для поган — щоб сла́вили Бога за милосердя, як написано: „Тому́ я хвали́тиму Тебе, Господи, серед поган, і Ім\'я́ Твоє буду виспівувати!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 10, 'І ще каже: „Тіштесь, погани, з наро́дом Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 11, 'І ще: „Хваліть, усі погани, Господа, виславляйте Його, усі люди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 12, 'І ще каже Ісая: „Буде корінь Єссе́їв, що постане, щоб панува́ти над поганами, — погани на Нього надіятись бу́дуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 13, 'Бог же надії нехай вас напо́внить усякою радістю й миром у вірі, щоб ви збагати́лись надією, силою Духа Святого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 14, 'І я про вас сам пересві́дчений, браття мої, що й самі ви повні до́брости, напо́внені всяким знання́м, і можете й один о́дного навчати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 15, 'А писав я вам почасти трохи сміліше, якби вам нагадуючи благода́ттю, що да́на мені від Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 16, 'щоб був я слугою Христа Ісуса між поганами, і виконував святу службу Єва́нгелії Божої, щоб прино́шення поган стало приємне й освячене Духом Святим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 17, 'Тож маю я чим похвалитись у Христі Ісусі, щодо Божих речей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 18, 'бо не смію казати того, чого не зробив через мене Христос на по́слух поган, словом і чином,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 19, 'силою ознак і чудес, силою Духа Божого, так що я поши́рив Єва́нгелію Христову від Єрусалиму й околиць аж до Іллі́ріка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 20, 'При то́му пильнував я звіщати Єва́нгелію не там, де Христове Ім\'я́ було знане, щоб не будувати на основі чужій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 21, 'але як написано: „Кому не звіщалось про Нього, побачать, і ті, хто не чув, зрозуміють!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 22, 'Тому́ часто я мав перешкоди, щоб прибути до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 23, 'А тепер, не маючи більше місця в країнах оцих, але з давніх літ мавши бажа́ння прибути до вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 24, 'коли тільки піду́ до Еспа́нії, прибу́ду до вас. Бо маю надію, як бу́ду прохо́дити, побачити вас, і що ви проведе́те мене туди, коли перше почасти матиму я задово́лення з вами побути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 25, 'А тепер я йду до Єрусалиму послужити святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 26, 'бо Македо́нія й Аха́я ви́знали за добре подати деяку поміч незаможним святим, що в Єрусалимі живуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 27, 'Бо ви́знали за добре, та й боржники́ вони їхні. Бо коли погани стали спільника́ми в їх духовнім, то повинні й у тілеснім послужити їм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 28, 'Як це докінчу́ та достачу їм плід цей, тоді через ваше місто я піду́ до Еспа́нії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 29, 'І знаю, що коли прийду́ до вас, то прийду́ в повноті́ Христового благослове́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 30, 'Благаю ж вас, браття, Господом нашим Ісусом Христом і любов\'ю Духа, — помагайте мені в моли́твах за мене до Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 31, 'щоб мені ви́зволитися від неслухня́них в Юдеї, і щоб служба моя в Єрусалимі була́ приємна святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 32, 'щоб із волі Божої з радістю прийти до вас і відпочи́ти з вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 33, 'А Бог миру нехай буде зо всіма́ вами. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 1, 'Поручаю ж вам сестру́ нашу Фі́ву, служе́бницю Церкви в Кенхре́ях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 2, 'щоб ви прийняли́ її в Господі, як личить святим, і допомагайте їй, у якій речі бу́де вона чого потребува́ти від вас, бо й вона опіку́нка була багатьом і самому мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 3, 'Вітайте Приски́ллу й Аки́лу, співробітників моїх у Христі Ісусі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 4, 'що голови свої за душу мою клали, яким не я сам дякую, але й усі Церкви́ з поган, — і їхню домашню Це́ркву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 5, 'Вітайте улю́бленого мого Епене́та, — він пе́рвісток Азії для Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 6, 'Вітайте Марію, що напрацювалася багато для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 7, 'Вітайте Андро́ніка й Юнія, родичів моїх і співв\'язнів моїх, що славні вони між апо́столами, що й у Христі були перше мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 8, 'Вітайте Амплія, мого улю́бленого в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 9, 'Вітайте Урба́на, співробітника нашого в Христі, і улюбленого мого Стахі́я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 10, 'Вітайте Апелле́са, ви́пробуваного в Христі. Вітайте Аристову́лових.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 11, 'Вітайте мого ро́дича Іродіо́на. Вітайте Нарки́сових, що в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 12, 'Вітайте Трифе́ну й Трифо́су, що працюють у Господі. Вітайте улю́блену Перси́ду, що багато попрацювала в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 13, 'Вітайте ви́браного в Господі Ру́фа, і матір його та мою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 14, 'Вітайте Асинкри́та, Фле́гонта, Єрма, Патро́ва, Єрмі́я і братів, що з ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 15, 'Вітайте Філоло́га та Юлію, Ніре́я й сестру́ його, і Олімпія́на, і всіх святих, що з ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 16, 'Вітайте один о́дного святим поцілунком. Вітають вас усі Церкви́ Христові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 17, 'Благаю ж вас, браття, щоб ви остерігалися тих, хто чинить розді́лення й згі́ршення проти науки, якої ви навчилися, і уникайте їх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 18, 'бо такі не служать Господеві нашому Ісусу Христу, але власному череву; вони добрими та гарними словами зво́дять серця простодушних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 19, 'Ваша ж слухня́ність дійшла до всіх. І я тішусь за вас, але хо́чу, щоб були ви мудрі в доброму, а про́сті в злому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 20, 'А Бог миру потопче незаба́ром сатану під ваші но́ги. Благода́ть Господа нашого Ісуса Христа нехай буде з вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 21, 'Вітає вас мій співробі́тник Тимофі́й, і Лукі́й, і Ясон, і Сосипа́тр, мої родичі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 22, 'Вітаю вас у Господі й я, Те́ртій, що цього листа написав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 23, 'Вітає вас Гай, гости́нний для ме́не й ці́лої Церкви. Вітає вас міськи́й доморя́дник Ера́ст і брат Кварт.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 24, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 25, 'А Тому́, хто може поставити вас міцно згідно з моєю Єва́нгелією й проповіддю Ісуса Христа, за об\'я́вленням таємни́ці, що від вічних часі́в була замо́вчана,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 26, 'а тепер ви́явлена, і через пророцькі писа́ння, з нака́зу вічного Бога, на по́слух вірі по всіх наро́дах прові́щена, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 27, 'єдиному мудрому Богові, через Ісуса Христа, слава навіки! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Павло́, волею Божою покликаний за апо́стола Ісуса Христа, і брат Состе́н,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Божій Церкві, що в Кори́нті, посвяченим у Христі Ісусі, покли́каним святим, зо всіма́, що на всякому місті приклика́ють Ім\'я́ Господа нашого Ісуса Христа, їхнього і нашого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'благода́ть вам і мир від Бога Отця нашого й Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Я за́вжди дякую моєму Богові за вас, через Божу благода́ть, що була вам да́на в Христі Ісусі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'бо ви всім збагати́лися в Ньому, — словом усяким і всяким знання́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'бо свідо́цтво Христове між вами утверди́лось,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'так що не маєте недоста́чі в жоднім да́рі благода́ті ви, що очікуєте з\'я́влення Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Він вас утвердить до кінця неповинними бути дня Господа нашого Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Вірний Бог, що ви через Нього покли́кані до спільноти́ Сина Його Ісуса Христа, Господа нашого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Тож благаю вас, браття, Ім\'я́м Господа нашого Ісуса Христа, щоб ви всі говорили те саме, і щоб не було поміж вами поді́лення, але щоб були́ ви поєднані в однім розумінні та в думці одній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Бо стало відо́мо мені про вас, мої браття, від Хло́їних, що між вами супере́чки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'А кажу́ я про те, що з вас кожен говорить: я ж Па́влів, а я Аполло́сів, а я Ки́фин, а я Христів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Чи ж Христос поділився? Чи ж Павло був розп\'я́тий за вас? Чи в Павло́ве ім\'я́ ви христились?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Дякую Богові, що я ані одно́го з вас не христив, окрім Крі́спа та Га́я,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'щоб ніхто не сказав, ніби я охристив був у йме́ння своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Охристив же був я й дім Степанів; більш не знаю, чи христив кого іншого я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Бо Христос не послав мене, щоб христити, а звіщати Єва́нгелію, і то не в мудрості слова, щоб безсилим не став хрест Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Бож слово про хреста тим, що гинуть, — то глупо́та, а для нас, що спасаємось, — Сила Божа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Бо написано: „Я погублю́ мудрість премудрих, а розум розумних відки́ну!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Де мудрий? Де книжник? Де дослі́дувач віку цього́? Хіба Бог мудрість світу цього́ не змінив на глупо́ту?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Через те ж, що світ мудрістю не зрозумів Бога в мудрості Божій, то Богові вгодно було́ спасти віруючих через ду́рість проповіді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Бо й юдеї жадають ознак, і греки пошу́кують мудрости,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'а ми проповідуємо Христа розп\'я́того, — для юдеїв згі́ршення, а для греків — безу́мство,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'а для самих покликаних юдеїв та греків — Христа, Божу силу та Божу мудрість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Бо Боже й немудре — розумніше воно від людей, а Боже не́мічне — сильніше воно від людей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, 'Дивіться бо, браття, на ваших покликаних, що небагато-хто мудрі за ті́лом, небагато-хто сильні, небагато-хто шляхе́тні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'Але Бог вибрав немудре світу, щоб засоро́мити мудрих, і не́мічне світу Бог вибрав, щоб засоромити сильне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'і про́стих світу, і погорджених, і незначни́х вибрав Бог, щоб значне́ зні́вечити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'так щоб не хвалилося перед Богом жодне тіло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'А з Нього ви в Христі Ісусі, що став нам мудрістю від Бога, — пра́ведністю ж, і освя́ченням, і відку́пленням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 31, 'щоб було, як написано: „Хто хва́литься, нехай хва́литься Господом!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'А я, як прийшов до вас, браття, не прийшов вам звіщати про Боже свідо́цтво з добі́рною мовою або мудрістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'бо я наду́мавсь нічого між вами не знати, крім Ісуса Христа, і Того розп\'я́того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'І я в вас був у немочі, і в страху́, і в великім тремті́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'І слово моє й моя проповідь — не в слова́х переко́нливих лю́дської мудрости, але́ в до́казі Духа та сили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'щоб була́ віра ваша не в мудрості лю́дській, але в силі Божій!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'А ми гово́римо про мудрість між досконалими, але мудрість не віку цього, ані володарів цього віку, що гинуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'але́ ми гово́римо Божу мудрість у таємниці, прихо́вану, яку Бог перед віками призна́чив нам на славу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'яку ніхто з володарів цього віку не пізнав; коли б бо пізнали були́, то не розп\'яли́ б вони Господа слави!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Але, як написано: „Чого око не бачило й вухо не чуло, і що на серце люди́ні не впало, те Бог приготува́в був тим, хто любить Його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'А нам Бог відкрив це Своїм Духом, — усе бо досліджує Дух, навіть Божі глиби́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Хто бо з людей знає речі лю́дські, окрім лю́дського духа, що в нім проживає? Так само не знає ніхто й речей Божих, окрім Духа Божого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'А ми прийняли́ духа не світу, але Духа, що з Бога, щоб знати про речі, від Бога даро́вані нам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'що й говоримо не ви́вченими словами лю́дської мудрости, але ви́вченими від Духа Святого, порі́внюючи духовне до духовного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'А люди́на тіле́сна не приймає речей, що від Божого Духа, бо їй це глупо́та, і вона зрозуміти їх не може, бо вони розуміються тільки духовно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Духовна ж люди́на су́дить усе, а її судити не може ніхто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Бо „хто розум Господній пізнав, який би його міг навчати?“А ми маємо розум Христів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'І я, браття, не міг говорити до вас, як до духовних, але як до тіле́сних, як до немовля́т у Христі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Я вас годува́в молоком, а не твердо́ю ї́жею, бо ви не могли її їсти, та й тепер ще не можете,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'бо ви ще тіле́сні. Бо коли за́здрість та суперечки між вами, то чи ж ви не тілесні, і хіба не по-лю́дському робите?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Бо коли хто каже: „Я ж Павлів“, а інший: „Я Аполло́сів“, то чи ж ви не тіле́сні?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Бо хто ж Аполло́с? Або хто то Павло? Вони тільки служи́телі, що ви ввірували через них, і то скільки кому́ дав Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Я посадив, Аполло́с поливав, Бог же зрости́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'тому́ ані той, хто са́дить, ані хто полива́є, є щось, але Бог, що ро́дить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'І хто са́дить, і хто поливає — одне, і кожен оде́ржить свою нагоро́ду за працею сво́єю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Бо ми співробі́тники Божі, а ви — Боже поле, Божа буді́вля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Я за благодаттю Божою, що да́на мені, як мудрий будівни́чий, основу поклав, а інший будує на ній; але нехай кожен пильнує, я́к він будує на ній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Ніхто бо не може покла́сти іншої основи, окрім покла́деної, а вона — Ісус Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'А коли хто на цій основі будує з золота, срібла, дорогоцінного камі́ння, із дерева, сіна, соломи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'то буде ви́явлене ді́ло кожного, бо виявить день, тому що він огнем об\'явля́ється, і огонь ді́ло кожного ви́пробує, яке воно є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'І коли чиє ді́ло, яке збудував хто, усто́їть, то той нагороду оде́ржить;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'коли ж ді́ло згорить, той матиме шкоду, та сам він спасе́ться, але́ так, як через огонь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Чи не знаєте ви, що ви — Божий храм, і Дух Божий у вас пробува́є?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Як хто ні́вечить Божого храма, того зні́вечить Бог, бо храм Божий святий, а храм той — то ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Хай не зво́дить ніхто сам себе́. Як кому з вас здається, що він мудрий в цім віці, нехай стане нерозумним, щоб бути премудрим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Цьогосві́тня бо мудрість — у Бога глупо́та, бо написано: „Він ловить премудрих у хи́трощах їхніх!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'І зно́ву: „Знає Госпо́дь думки мудрих, що марно́тні вони!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Тож нехай ніхто не хва́литься людьми́, бо все ваше:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'чи Павло, чи Аполло́с, чи Ки́фа, чи світ, чи життя, чи смерть, чи тепе́рішнє, чи майбутнє — усе ваше,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 23, 'ви ж Христові, а Христос — Божий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Нехай кожен нас так уважає, якби служи́телів Христових і доморя́дників Божих таємни́ць;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'а що́ ще шукається в доморя́дниках, — щоб кожен був зна́йдений вірним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'А для мене то найменше, щоб судили мене ви чи суд лю́дський, бо я й сам не суджу́ себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Я бо проти себе нічого не знаю, але цим не випра́вдуюсь; Той же, Хто судить мене, то Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Тому́ не судіть передчасно нічо́го, аж поки не при́йде Госпо́дь, що й ви́світлить таємниці те́мряви та виявить за́думи серде́ць, і тоді кожному бу́де похвала́ від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Оце ж усе, браття, приклав я до себе й Аполло́са ради вас, щоб від нас ви навчилися ду́мати „не більш, як написано“, щоб ви не чва́нились один за о́дним перед іншим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Хто бо тебе вирізня́є? Що́ ти маєш, чого б ти не взяв? А коли ж бо ти взяв, чого чва́нишся, ніби не взяв?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Ви вже нагодовані, ви вже збагати́лися, без нас ви царюєте. І коли б то ви стали царюва́ти, щоб і ми царювали з вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Бо я ду́маю, що Бог нас, апо́столів, поставив за найоста́нніших, мов на смерть засу́джених, бо ми стали диво́вищем світові, — і ангола́м, і лю́дям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Ми нерозумні Христа ради, а ви мудрі в Христі; ми слабі, ви ж міцні́; ви славні, а ми безчесні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Ми до цього ча́су і голодуємо, і пра́гнемо, і нагі́ ми, і като́вані, і тиняємось,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'і тру́димось, працюючи своїми руками. Коли нас лихосло́влять, ми благословляємо; як нас переслідують, ми те́рпимо;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'як лають, ми молимось; ми стали, як сміття́ те для світу, аж досі ми всім, як ті ви́кидки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Не пишу́ це для то́го, щоб вас осоро́мити, але остерігаю, як своїх лю́бих дітей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Бо хоч би ви мали десять тисяч наста́вників у Христі, та отців не багато; а я вас породив у Христі Ісусі через Єва́нгелію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Тож благаю я вас: будьте наслі́дувачами мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Для цього послав я до вас Тимофі́я, що для мене улю́блений і вірний син у Господі, — він вам нагадає шляхи мої в Христі Ісусі, як навчаю я скрізь у кожній Церкві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Деякі згорділи, так немов би не мав я прийти до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Та неба́вом прийду́ до вас, як захоче Господь, і пізна́ю не слово згорділих, але силу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Бо Царство Боже не в слові, а в силі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Чого хочете? Чи прийти до вас з києм, чи з любов\'ю та з духом ла́гідности?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Всюди чути, що між вами пере́люб, і то такий пере́люб, який і між поганами незна́ний, — що хтось має за дружи́ну собі дружину ба́тькову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'І ви завелича́лися, а не засмутились радніш, щоб був вилучений з-поміж вас, хто цей учинок зробив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Отож я, відсутній тілом, та присутній духом, уже розсудив, як присутній між вами: того, хто так учинив це,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'у Ім\'я́ Господа Ісуса, як зберетеся ви та мій дух, із силою Господа нашого Ісуса, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'віддати такого сатані на погибіль тіла, щоб дух спасся Господнього дня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Велича́ння ваше не добре. Хіба ви не знаєте, що мала ро́зчина все тісто заква́шує?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Отож, очистьте стару́ ро́зчину, щоб стати вам нови́м тістом, бо ви прісні́, бо наша Пасха, Христос, за нас у жертву прине́сений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Тому́ святкуймо не в давній ро́зчині, ані в ро́зчині злоби́ й лука́вства, але в опрі́сноках чистости та правди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Я писав вам у листі не єдна́тися з перелю́бниками, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'але не взагалі з цьогосвітніми перелю́бниками, чи з користолю́бцями, чи з хижака́ми, чи з ідоля́нами, бо ви мусіли були б відійти від світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'А тепер я писав вам не єднатися з тим, хто зветься братом, та є перелю́бник, чи користолю́бець, чи ідоля́нин, чи злоріка, чи п\'яни́ця, чи хижа́к, — із такими навіть не їсти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Бо що ж мені судити й чужих? Чи ви не судите своїх?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'А чужих судить Бог. Тож ви́лучіть лукавого з-поміж себе сами́х!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 1, 'Чи посміє хто з вас, маючи справу до іншого, су́дитися в неправедних, а не в святих?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 2, 'Хіба ви не знаєте, що святі світ судитимуть? Коли ж бу́дете ви світ судити, то чи ж ви негі́дні судити незначні справи?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 3, 'Хіба ви не знаєте, що ми будем судити анголі́в, а не тільки життє́ве?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 4, 'А ви, коли маєте суд за життєве, то ставите суддями тих, хто нічо́го не значить у Церкві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 5, 'Я на сором це вам говорю́. Чи ж між вами немає ні о́дного мудрого, щоб він міг розсуди́ти між братами своїми?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 6, 'Та брат су́диться з братом, — і то перед невірними!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 7, 'Тож уже для вас сором зовсі́м, що суди́ між собою ви маєте. Чому краще не те́рпите кривди? Чому краще не маєте шкоди?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 8, 'Але ви самі кривду чините та обдираєте, та ще братів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 9, 'Хіба ви не знаєте, що неправедні не вспадку́ють Божого Царства? Не обманюйте себе: ні розпу́сники, ні ідоля́ни, ні перелю́бники, ні блудоді́йники, ні мужоло́жники,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 10, 'ні злоді́ї, ні користолю́бці, ні п\'яни́ці, ні злорі́ки, ні хижаки́ — Царства Божого не вспадку́ють вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 11, 'І такими були́ дехто з вас, але ви обмились, але́ освятились, але́ виправдались Іменем Господа Ісуса Христа й Духом нашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 12, 'Усе мені можна, та не все на пожи́ток. Усе мені можна, але мною, ніщо володіти не повинно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 13, 'Ї́жа для че́рева, і че́рево для їжі, але Бог одне й друге пони́щить. А тіло не для розпусти, але для Господа, і Господь для тіла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 14, 'Бог же й Господа воскресив, воскреси́ть Він і нас Своєю силою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 15, 'Хіба ви не знаєте, що ваші тіла́ — то члени Христові? Отож, узявши члени Христові, зроблю́ їх членами розпу́сниці? Зо́всім ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 16, 'Хіба ви не знаєте, що той, хто злучується з розпу́сницею, стає одним тілом із нею? Бо каже: „Оби́два ви будете тілом одним“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 17, 'А хто з Господом злучується, стає одним духом із Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 18, 'Утікайте від розпусти. Усякий бо гріх, що його чинить люди́на, є поза тілом. А хто чинить розпусту, той грішить проти власного тіла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 19, 'Хіба ви не знаєте, що ваше тіло — то храм Духа Святого, що живе Він у вас, Якого від Бога ви маєте, і ви не свої?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 20, 'Бо дорого ку́плені ви. Отож прославляйте Бога в тілі своє́му та в дусі своє́му, що Божі вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 1, 'А про що ви писали мені, то добре було б чоловікові не дотикатися жінки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 2, 'Але щоб уни́кнути розпусти, нехай кожен муж має дружи́ну свою, і кожна жінка хай має свого чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 3, 'Нехай віддає́ чоловік своїй дружи́ні потрібну любов, так же само й чоловікові дружи́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 4, 'Дружи́на не володіє над тілом своїм, але чоловік; так же само й чоловік не володіє над тілом своїм, але дружи́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 5, 'Не вхиляйтесь одне від о́дного, хібащо дочасно за згодою, щоб бути в пості́ та молитві, та й схо́дьтеся зно́ву докупи, щоб вас сатана́ не споку́шував вашим нестри́манням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 6, 'А це говорю́ вам як раду, а не як нака́за.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 7, 'Бо хо́чу, щоб усі чоловіки були, як і я; але кожен має від Бога свій дар, — один так, інший так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 8, 'Говорю́ ж неодруженим і вдо́вам: добре їм, як вони позостануться так, як і я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 9, 'Коли ж не втри́маються, — нехай одружуються, бо краще женитися, ніж розпаля́тися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 10, 'А тим, що побрались, наказую не я, а Госпо́дь: Нехай не розлуча́ється дружи́на з своїм чоловіком!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 11, 'А коли ж і розлу́читься, хай зостається незамі́жня, або з чоловіком своїм хай поми́риться, — і не відпускати чоловікові дружи́ни!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 12, 'Іншим же я говорю́, не Госпо́дь: коли який брат має дружи́ну невіруючу, і згідна вона жити з ним, — нехай він не лишає її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 13, 'І жінка, як має чоловіка невіруючого, а той згоден жити з нею, — нехай не лишає його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 14, 'Чоловік бо невіруючий освячується в дружи́ні, а дружи́на невіруюча освячується в чоловікові. А інакше нечисті були́ б ваші діти, тепер же святі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 15, 'А як хоче невіруючий розлучи́тися, хай розлу́читься, — не нево́литься брат чи сестра в такім разі, бо покликав нас Бог до миру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 16, 'Звідки знаєш ти, дружи́но, чи не спасеш чоловіка? Або звідки знаєш, чоловіче, чи не спасеш дружи́ни?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 17, 'Нехай тільки так ходить кожен, як кому Бог призна́чив, як Госпо́дь покликав його. І так усім Церква́м я наказую.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 18, 'Хто покликаний був в обрі́занні, — нехай він того не цурається; чи покликаний хто в необрі́занні, — нехай не обрі́зується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 19, 'Обрі́зання ніщо, і ніщо необрі́зання, а важли́ве — дотри́мування Божих заповідей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 20, 'Нехай кожен лишається в стані такому, в якому покли́каний був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 21, 'Чи покликаний був ти рабом? Не турбуйся про те. Але коли й можеш стати вільним, то ви́користай краще це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 22, 'Бо покликаний в Господі раб — визволе́нець Господній; так само покликаний і визволе́нець — він раб Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 23, 'Ви дорого ку́плені, — тож не ставайте рабами людей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 24, 'Браття, кожен із вас, в якім стані покли́каний був, хай у тім перед Богом лишається!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 25, 'Про дівчат же не маю нака́зу Господнього, але даю раду як той, хто одержав від Господа милість бути вірним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 26, 'Отож за суча́сного утиску добрим уважаю я те, що чоловікові добре лишатися так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 27, 'Ти зв\'язаний з дружи́ною? Не шукай розв\'я́зання. Розв\'язався від дружи́ни? Не шукай дружи́ни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 28, 'А коли ти й оже́нишся, то не згрішив; і як дівчина заміж пі́де, — вона не згрішить. Та муку тілесну такі будуть мати, а мені шкода вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 29, 'А це, браття, кажу́ я, бо час позосталий короткий, щоб і ті, що мають дружи́н, були, як ті, що не мають,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 30, 'а хто плаче, — як ті, хто не плаче, а хто тішиться, — як ті, хто не тішиться; і хто купує, — як би не набули́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 31, 'а хто цьогосвітнім кори́стується, — як би не кори́стувались, бо минає стан світу цього́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 32, 'А я хо́чу, щоб ви безклопі́тні були́. Неодру́жений про речі Господні клопо́четься, як догодити Господе́ві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 33, 'а одру́жений про речі життє́ві клопочеться, як догодити своїй дружи́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 34, 'і він поділений. Незамі́жня ж жінка та дівчина про речі Господні клопо́четься, щоб бути святою і тілом, і духом. А замі́жня про речі життєві клопочеться, як догодити чоловікові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 35, 'А це я кажу́ вам самим на пожиток, а не щоб сильце́ вам накинути, але щоб пристойно й горли́во держались ви Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 36, 'А як ду́має хто про дівчину свою, що со́ромно, як вона переросте́, і так мала б лишатись, нехай робить, що хоче, — не згрішить: нехай за́між вихо́дять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 37, 'А хто в серці своїм стоїть міцно, не має конечности, вла́ду ж має над своєю волею, і це постановив він у серці своєму — берегти свою дівчину, той робить добре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 38, 'Тому́ й той, хто віддає свою дівчину за́між, добре робить, а хто не віддає — робить краще.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 39, 'Дружи́на зако́ном прив\'язана, поки живе чоловік її; коли ж чоловік її вмре, вона вільна вихо́дити заміж, за ко́го захоче, аби тільки в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 40, 'Блаженніша вона, коли так позоста́неться за моєю порадою, бо мірку́ю, що й я маю Божого Духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 1, 'А щодо і́дольських жертов, то ми знаємо, що всі маємо знання́. Знання́ ж надимає, любов же будує!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 2, 'Коли хто ду́має, ніби щось знає, той нічого не знає ще так, як знати повинно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 3, 'Коли ж любить хто Бога, той пі́знаний Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 4, 'Тож про спожива́ння і́дольських же́ртов ми знаємо, що і́дол у світі ніщо, і що іншого Бога нема, окрім Бога Одно́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 5, 'Бо хоч і існують так звані „боги“чи на небі, чи то на землі, як існує багато богів і багато панів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 6, 'та для нас один Бог — Отець, що з Нього походить усе, ми ж для Нього, і один Госпо́дь — Ісус Христос, що все сталося Ним, і ми Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 7, 'Та не всі таке мають знання́, бо де́які мають призвича́єння до ідола й досі, і їдять, як ідольську жертву, — і їхнє сумління, бувши недуже, спога́нюється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 8, 'Їжа ж нас до Бога не збли́жує: бо коли не їмо, то нічого не тратимо, а коли ми їмо, то не набуваєм нічо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 9, 'Але стережіться, щоб ця ваша воля не стала якось за спотика́ння слаби́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 10, 'Коли бо хто бачить тебе, маю́чого знання́, як ти в і́дольській божни́ці сидиш за столом, чи ж сумління його, бувши слабе́, не буде спону́кане їсти ідольські жертви?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 11, 'І через знання́ твоє згине недужий твій брат, що за нього Христос був умер!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 12, 'Грі́шачи так проти братів та вражаючи їхнє слабе сумління, ви проти Христа грішите́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 13, 'Ось тому́, коли їжа споку́шує брата мого, то повік я не їстиму м\'яса, щоб не спокусити брата свого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 1, 'Хіба ж я не вільний? Чи ж я не апо́стол? Хіба я не бачив Ісуса Христа, Господа нашого? Хіба ви, — то не справа моя перед Господом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 2, 'Коли я не апо́стол для інших, то для вас я апостол, — ви бо печа́ть мого апо́стольства в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 3, 'Оце оборона моя перед тими, хто судить мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 4, 'Чи ми права не маємо їсти та пити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 5, 'Чи ми права не маємо водити з собою сестру́, дружи́ну, як і інші апо́столи, і Господні брати, і Ки́фа?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 6, 'Хіба я один і Варна́ва не маємо права, щоб не працювати?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 7, 'Хто коштом своїм коли служить у ві́йську? Або хто виноградинка садить, — і не їсть з його плоду? Або хто ота́ру пасе, — і не їсть молока від ота́ри?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 8, 'Чи я тільки по-лю́дському це говорю́? Хіба ж і Зако́н не говорить цього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 9, 'Бо в Зако́ні Мойсеєвім писано: „Не в\'яжи рота волові, що молотить“. Хіба за волів Бог турбується?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 10, 'Чи говорить Він зо́всім для нас? Для нас, бо написано, що з надією мусить орати ора́ч, а моло́тник — молотити з надією мати частку в своїм сподіва́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 11, 'Коли ми сіяли вам духовне, чи ж велика то річ, як пожнемо́ ми ваше тілесне?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 12, 'Як право на вас мають інші, то тим більше ми. Але ми не вжили́ цього права, та все те́рпимо, аби перешкоди якої Христовій Єва́нгелії ми не вчинили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 13, 'Хіба ви не знаєте, що священнослужителі від святині годуються? Що ті, хто служить вівтаре́ві, із вівтаря́ мають частку?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 14, 'Так і Госпо́дь наказав проповідникам Єва́нгелії жити з Єва́нгелії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 15, 'Але з того нічого не вжив я. А цього́ не писав я для того, щоб для мене так було́. Бо мені краще вмерти, аніж щоб хто зні́вечив хвалу мою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 16, 'Бо коли я звіщаю Єва́нгелію, то нема чим хвалитись мені, — це бо повинність моя. І горе мені, коли я не звіщаю Єва́нгелії!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 17, 'Тож коли це роблю́ добровільно, я маю нагоро́ду; коли ж недобровільно, то виконую службу дору́чену.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 18, 'Яка ж нагорода мені? — Та, що, благові́стячи, я безкори́сливо проповідував Христову Єва́нгелію, не використо́вуючи особистих прав щодо благові́стя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 19, 'Від усіх бувши вільний, я зробився рабом для всіх, щоб найбільше придбати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 20, 'Для юдеїв я був, як юдей, щоб юдеїв придбати; для підзако́нних — був, як підзако́нний, хоч сам підзако́нним не бувши, щоб придбати підзако́нних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 21, 'Для тих, хто без Зако́ну, — я був беззако́нний, не бувши беззаконний Богові, а законний Христові, щоб придбати беззаконних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 22, 'Для слаби́х, — як слаби́й, щоб придбати слабих. Для всіх я був усе, щоб спасти бодай деяких.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 23, 'А це я роблю́ для Єва́нгелії, щоб стати її спільником.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 24, 'Хіба ви не знаєте, що ті, хто на перегонах біжить, усі біжать, але нагороду приймає один? Біжіть так, щоб оде́ржали ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 25, 'І кожен змагу́н від усього стримується; вони ж — щоб тлінний прийняти вінок, але ми — щоб нетлінний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 26, 'Тож біжу́ я не так, немов на непевне, борюся не так, немов би повітря б\'ючи́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 27, 'Але вмертвляю й неволю я тіло своє, щоб, звіщаючи іншим, не стати само́му негі́дним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 1, 'Не хо́чу я, браття, щоб ви не знали, що під хмарою всі отці наші були́, — і всі перейшли через море,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 2, 'і всі охристилися в хмарі та в морі в Мойсея,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 3, 'і всі їли ту саму пожи́ву духовну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 4, 'і пили́ всі той самий духовний напі́й, бо пили від духовної скелі, що йшла вслід за ними, а та скеля — був Христос!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 5, 'Але їх багатьох не вподо́бав був Бог, бо „понищив Він їх у пустині“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 6, 'А це були при́клади нам, щоб ми пожадливі на зле не були́, як були пожадливі й вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 7, 'Не будьте також ідоля́нами, як деякі з них, як написано: „Люди сіли, щоб їсти та пити, і встали, щоб грати“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 8, 'Не станьмо чинити блу́ду, як деякі з них блудоді́яли, — і полягло їх одно́го дня двадцять три тисячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 9, 'Ані не випробо́вуймо Христа, як деякі з них випробо́вували, — та й від змі́їв загинули.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 10, 'Ані не нарікайте, як деякі з них нарікали, — і загинули від погуби́теля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 11, 'Усе це трапилось з ними, як при́клади, а написане нам на науку, бо за нашого ча́су кінець віку прийшов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 12, 'Тому́ то, хто ду́має, ніби стоїть він, нехай стережеться, щоб не впасти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 13, 'Досягла́ вас спроба не інша, тільки лю́дська; але вірний Бог, Який не попу́стить, щоб ви випробо́вувалися більше, ніж можете, але при спробі й поле́гшення дасть, щоб зне́сти могли ви її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 14, 'Тому, мої любі, утікайте від служі́ння ідолам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 15, 'Кажу́, як розумним; судіть самі, що кажу́ я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 16, 'Чаша благослове́ння, яку благословляємо, — чи не спільно́та то крови Христової? Хліб, який ломимо, чи не спільно́та він тіла Христового?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 17, 'Тому́ що один хліб, тіло одне — нас багато, бо ми всі спільники хліба одного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 18, 'Погляньте на Ізраїля за тілом: чи ж ті, що жертви їдять, не спільники́ вівтаря́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 19, 'Тож що́ я кажу́? Що ідольська жертва є щось? Чи що ідол є щось?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 20, 'Ні, але те, що в жертву приносять, „де́монам, а не Богові в жертву приносять“. Я ж не хо́чу, щоб ви спільника́ми для де́монів стали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 21, 'Бо не можете пити чаші Господньої та чаші де́монської; не можете бути спільника́ми Господнього сто́лу й столу де́монського.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 22, 'Чи ми дратува́тимем Господа? Хіба ми поту́жніші за Нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 23, 'Усе мені можна, — та не все на пожи́ток. Усе мені можна, — та буду́є не все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 24, 'Нехай не шукає ніхто свого власного, але кожен — для ближнього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 25, 'Їжте все, що на я́тках м\'ясних продається, за сумління зовсім не турбуючись, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 26, 'Бо „Господня земля, і все, що на ній“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 27, 'Як покличе вас хтось із невіруючих, і ви захочете піти́, — їжте все, що дадуть вам, за сумління зовсім не турбуючись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 28, 'Коли ж скаже вам хтось: „Це і́дольська жертва“, — не їжте тоді через того, хто сказав, та через сумління!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 29, 'Говорю́ ж не про власне сумління, але іншого, — чого б моя воля судилась сумлінням чужим?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 30, 'Коли я стаю спільником їжі з подякою, чому мене зневажають за те, за що́ дякую я?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 31, 'Тож, коли ви їсте, чи коли ви п\'єте́, або коли інше що робите, — усе на Божу славу робіть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 32, 'Не робіть спокуси юдеям та ге́лленам, та Церкві Божій,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 33, 'як дого́джую й я всім у всьо́му, не шукаючи в тому пожи́тку свого́, але пожи́тку для багатьох, щоб спасли́ся вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 1, 'Будьте наслідувачами мене, як і я Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 2, 'Похваляю ж вас, браття, що ви все моє пам\'ятаєте, і захо́вуєте так переда́ння, як я вам передав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 3, 'Хо́чу ж я, щоб ви знали, що всякому чоловікові голова — Христос, а жінці голова — чоловік, голова ж Христові — Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 4, 'Кожен чоловік, що молиться чи пророкує з головою покритою, — осоромлює він свою го́лову.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 5, 'І кожна жінка, що молиться чи пророкує з головою відкритою, осоромлює тим свою го́лову, бо це є те саме, як була́ б вона виголена.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 6, 'Бо коли жінка не покривається, хай стрижеться вона; коли ж жінці сором стри́гтися чи голитися, нехай покривається!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 7, 'Отож, чоловік покривати голови не повинен, бо він образ і слава Бога, а жінка — чоловікові слава.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 8, 'Бо чоловік не походить від жінки, але жінка від чоловіка,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 9, 'не ство́рений бо чоловік ради жінки, але жінка ради чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 10, 'Тому жінка повина мати на голові знака вла́ди над нею, ради анголів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 11, 'Одначе в Господі ані чоловік без жінки, ані жінка без чоловіка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 12, 'Бо як жінка від чоловіка, так і чоловік через жінку; а все — від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 13, 'Поміркуйте самі між собою, чи присто́йне воно, щоб жінка молилася Богові непокрита?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 14, 'Чи ж природа сама вас не вчить, що коли чоловік запускає воло́сся, то безчестя для нього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 15, 'Коли ж жінка ко́су запускає, — це слава для неї, бо замість покрива́ла да́на коса́ їй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 16, 'Коли ж хто сперечатися хоче, — ми такого звича́ю не маємо, ані Церкви́ Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 17, 'Пропонуючи це вам, я не хвалю́, що збираєтесь ви не на ліпше, а на гірше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 18, 'Бо найперше, я чую, що як схо́дитесь ви на збо́ри, то між вами бувають поді́лення, у що почасти я й вірю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 19, 'Бо мусять між вами й поділи бути, щоб відкрились між вами й досвідчені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 20, 'А далі, коли ви збираєтесь ра́зом, то не на те, щоб їсти Господню Вече́рю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 21, 'Бо кожен спішить з\'їсти власну вече́рю, і один голодує, а другий впивається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 22, 'Хіба ж ви не маєте хат, щоб їсти та пити? Чи ви зневажаєте Божу Церкву, і осоромлюєте немаю́чих? Що маю сказати вам? Чи за це похвалю́ вас? Не похвалю́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 23, 'Бо прийняв я від Господа, що й вам передав, що Господь Ісус ночі тієї, як ви́даний був, узяв хліб,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 24, 'подяку віддав, і переломив, і сказав: „Прийміть, споживайте, це тіло Моє, що за вас лома́ється. Це робіть на спомин про Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 25, 'Так само і чашу взяв Він по Вечері й сказав: „Ця чаша — Нови́й Заповіт у Моїй крові. Це робіть, коли тільки бу́дете пити, на спомин про Мене!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 26, 'Бо кожного ра́зу, як будете їсти цей хліб та чашу цю пити, — смерть Господню звіщаєте, аж доки Він при́йде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 27, 'Тому то, хто їстиме хліб цей чи питиме чашу Господню негідно, — буде винний супроти тіла та крови Господньої!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 28, 'Нехай же люди́на випробо́вує себе, і так нехай хліб їсть і з чаші хай п\'є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 29, 'Бо хто їсть і п\'є негі́дно, не розважаючи про тіло, той суд собі їсть і п\'є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 30, 'Через це поміж вами багато недужих та хворих, і багато-хто засну́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 31, 'Бо коли б ми самі судили себе, то засу́джені ми не були́ б.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 32, 'Та засу́джені від Господа, караємося, щоб нас не засу́джено з світом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 33, 'Ось тому́, мої браття, схо́дячись на поживу, чека́йте один о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 34, 'А коли хто голодний, нехай вдома він їсть, щоб не схо́дилися ви на о́суд. А про інше, як прийду́, заряджу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 1, 'А щодо духовних да́рів, то не хо́чу я, браття, щоб не відали ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 2, 'Знаєте, що коли ви поганами були́, то ходили до німих ідолів, ніби воджено вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 3, 'Тому́ то кажу́ вам, що ніхто, хто говорить Духом Божим, не скаже: „Нехай ана́тема буде на Ісуса“, і не може сказати ніхто: „Ісус — то Госпо́дь“, як тільки Духом Святим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 4, 'Є різниця між да́рами ми́лости, Дух же той Самий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 5, 'Є й різниця між служі́ннями, та Господь той же Самий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 6, 'Є різниця й між ді́ями, але Бог той же Самий, що в усіх робить усе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 7, 'І кожному дається ви́явлення Духа на ко́ристь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 8, 'Одно́му бо Духом дається слово мудрости, а дру́гому слово знання́ тим же Духом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 9, 'а іншому віра тим же Духом, а іншому да́ри вздоро́влення тим же Духом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 10, 'а іншому ро́блення чуд, а іншому пророкува́ння, а іншому розпізнава́ння ду́хів, а тому різні мови, а іншому вия́снення мов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 11, 'А все оце чинить один і той Самий Дух, уділя́ючи кожному осібно, як Він хоче.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 12, 'Бо як тіло одне, але має членів багато, усі ж чле́ни ті́ла, хоч їх багато, то тіло одне, — так і Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 13, 'Бо ми всі одним Духом охрищені в тіло одне, — чи то юдеї, чи ге́ллени, чи раби, чи то вільні, — і всі ми напо́єні Духом одним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 14, 'Бо тіло не є один член, а багато.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 15, 'Коли скаже нога, що я не від тіла, бо я не рука, — то хіба через це не від тіла вона?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 16, 'І коли скаже вухо, що я не від тіла, бо я не око, — то хіба через це не від тіла воно?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 17, 'Коли б оком було ці́ле тіло, то де був би слух? А коли б усе слух, то де був би нюх?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 18, 'Та нині Бог розкла́в чле́ни в тілі, кожного з них, як хотів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 19, 'Якби всі одним чле́ном були́, — то де тіло було б?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 20, 'Отож, тепер чле́нів багато, — та тіло одне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 21, 'Бо око не може сказати руці: „Ти мені непотрібна“; або голова знов нога́м: „Ви мені непотрібні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 22, 'Але чле́ни тіла, що здаються слабіші, значно більше потрібні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 23, 'А тим, що вважаємо їх за зовсім нешановані в тілі, таким честь найбільшу приносимо, і бридкі наші члени отримують пристойність найбільшу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 24, 'а нашим пристойним того не — потрібно. Та Бог змішав тіло, і честь більшу дав нижчому членові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 25, 'щоб поді́лення в тілі не було́, а щоб чле́ни одна́ково дбали один про о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 26, 'І коли те́рпить один член, то всі чле́ни з ним те́рплять; і коли один член пошано́ваний, то всі члени з ним тішаться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 27, 'І ви — тіло Христове, а зосібна — ви чле́ни!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 28, 'А інших поставив Бог у Церкві поперше — апо́столами, подруге — проро́ками, потрете — учителя́ми, потім дав сили, також да́ри вздоро́влення, допомо́ги, управлі́ння, різні мови.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 29, 'Чи ж усі апо́столи? Чи ж усі пророки? Чи ж усі вчителі? Чи ж усі сили чудодійні?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 30, 'Чи ж усі мають да́ри вздоро́влення? Чи ж мовами всі розмовляють? Чи ж усі виясня́ють?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 31, 'Тож дбайте ре́вно про ліпші да́ри́, а я вам покажу́ путь іще кращу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 1, 'Коли я говорю́ мовами лю́дськими й а́нгольськими, та любови не маю, — то став я як мідь та дзвінка́ або бу́бон гудя́чий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 2, 'І коли маю дара пророкува́ти, і знаю всі таємни́ці й усе знання́, і коли маю всю віру, щоб навіть гори переставля́ти, та любови не маю, — то я ніщо!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 3, 'І коли я роздам усі маєтки свої, і коли я відда́м своє тіло на спа́лення, та любови не маю, — то пожитку не матиму жа́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 4, 'Любов довготе́рпить, любов милосе́рдствує, не за́здрить, любов не величається, не надима́ється,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 5, 'не пово́диться нечемно, не шукає тільки свого, не рветься до гніву, не ду́має лихо́го,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 6, 'не радіє з неправди, але тішиться правдою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 7, 'усе зно́сить, вірить у все, сподіва́ється всього, усе те́рпить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 8, 'Ніко́ли любов не перестає! Хоч пророцтва й існують, — та припи́няться, хоч мови існують, — замо́вкнуть, хоч існує знання́, — та скасу́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 9, 'Бо ми знаємо части́нно, і пророкуємо частинно;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 10, 'коли ж досконале настане, тоді зупиниться те, що частинне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 11, 'Коли я дити́ною був, то я говорив, як дити́на, як дити́на я ду́мав, розумів, як дитина. Коли ж мужем я став, то відкинув дитя́че.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 12, 'Отож, тепер бачимо ми ніби у дзе́ркалі, у за́гадці, але по́тім — обличчям в обличчя; тепер розумію частинно, а по́тім пізна́ю, як і пі́знаний я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 13, 'А тепер залиша́ються віра, надія, любов, — оці три. А найбільша між ними — любов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 1, 'Дбайте про любов, і про духовне пильнуйте, а найбільше — щоб пророкува́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 2, 'Як гово́рить хто чужою мовою, той не лю́дям говорить, а Богові, бо ніхто його не розуміє, і він духом говорить таємне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 3, 'А хто пророку́є, той лю́дям говорить на збудува́ння, і на умо́влений, і на розраду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 4, 'Як говорить хто чужою мовою, той будує тільки самого себе, а хто пророкує, той Церкву будує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 5, 'Я ж хо́чу, щоб мовами говорили всі, а ліпше — щоб пророкува́ли: більший бо той, хто пророкує, аніж той, хто говорить мовами, хібащо пояснює, щоб будува́лася Церква.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 6, 'А тепер, як прийду́ я до вас, браття, і до вас говорити буду чужою мовою, то який вам пожи́ток зроблю́, коли не поясню́ вам чи то відкриття́м, чи знання́м, чи пророцтвом, чи наукою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 7, 'Бо навіть і речі бездушні, що звук видають, як сопілка чи лю́тня, коли б не видавали вони різних звуків, — як пізнати б тоді, що́ бринить або грає?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 8, 'Бо коли сурма́ звук невира́зний дає, — хто до бо́ю гото́витись бу́де?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 9, 'Так і ви, коли мовою не подасте́ зрозумілого слова, — як пізнати, що́ кажете? Ви говоритимете на вітер!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 10, 'Як багато, напри́клад, різних мов є на світі, — і жа́дна з них не без зна́чення!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 11, 'І коли я не знатиму зна́чення слів, то я буду чужи́нцем промовцеві, і промо́вець чужи́нцем мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 12, 'Так і ви, що пильнуєте про духовні дари, — дбайте, щоб збагачуватись через них на збудува́ння Церкви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 13, 'Ось тому́, хто говорить чужою мовою, нехай молиться, щоб умів виясняти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 14, 'Бо коли я молюся чужою мовою, то молиться дух мій, а мій розум без пло́ду!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 15, 'Ну, то що ж? Буду молитися духом, і буду молитися й розумом, співатиму духом, і співатиму й розумом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 16, 'Бо коли благословля́тимеш духом, то як той, що займає місце про́стої людини, промовить „амі́нь“на подяку твою? Не знає бо він, що́ ти кажеш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 17, 'Ти дякуєш добре, але не будується інший.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 18, 'Дякую Богові моєму, — розмовляю я мовами більше всіх вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 19, 'Але в Церкві волію п\'ять слів зрозумілих сказати, щоб і інших навчити, аніж десять тисяч слів чужою мовою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 20, 'Браття, не будьте дітьми́ своїм розумом, — будьте в лихо́му дітьми́, а в розумі доскона́лими будьте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 21, 'У Зако́ні написано: „Іншими мовами й іншими устами Я говоритиму лю́дям оцим, та Мене вони й так не послухають“, каже Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 22, 'Отож, мови існують на знак не для віруючих, але для невіруючих, а пророцтво — для віруючих, а не для невіруючих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 23, 'А як зі́йдеться Церква вся ра́зом, і всі говоритимуть чужими мовами, і ввійдуть туди й сторонні чи невіруючі, — чи ж не скажуть вони, що біснуєтесь ви?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 24, 'Коли ж усі пророкують, а вві́йде якийсь невіруючий чи сторонній, то всі докоряють йому, усі судять його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 25, 'і так таємни́ці серця його виявляються, і так він падає ницьма́ і вклоняється Богові й каже: „Бог справді між вами!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 26, 'То що ж, браття? Коли схо́дитесь ви, то кожен із вас псало́м має, має науку, має мову, об\'я́влення має, має вия́снення, — нехай буде все це на збудува́ння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 27, 'Як говорить хто чужою мовою, говоріть по двох, чи найбільше по трьох, і то за черго́ю, а один нехай перекладає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 28, 'А коли б не було перекла́дача, то нехай він у Церкві мовчить, а говорить нехай собі й Богові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 29, 'А пророки нехай промовляють по двох чи по трьох, а інші нехай розпізнаю́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 30, 'Коли ж відкриття́ буде іншому з тих, хто сидить, — нехай перший замовкне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 31, 'Бо можете пророкувати ви всі по одно́му, — щоб училися всі й усі ті́шилися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 32, 'І ко́ряться духи пророчі пророкам,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 33, 'бо Бог не є Богом бе́зладу, але миру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 34, 'нехай у Церкві мовчать жінки ваші! Бо їм говорити не позволено, — тільки кори́тись, як каже й Зако́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 35, 'Коли ж вони хочуть навчитись чогось, нехай вдома питають своїх чоловіків, — непристойно бо жінці говорити в Церкві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 36, 'Хіба вийшло від вас Слово Боже? Чи прийшло воно тільки до вас?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 37, 'Коли хто вважає себе за пророка або за духовного, нехай розуміє, що́ я пишу́ вам, — бо Господня це заповідь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 38, 'Коли б же хто не розумів, — нехай не розуміє!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 39, 'Отож, браття мої, майте ревність пророкувати, та не бороніть говорити й мовами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 40, 'Але все нехай буде добропристо́йно і стате́чно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 1, 'Звіщаю ж вам, браття, Єва́нгелію, яку я вам благовісти́в, і яку прийняли́ ви, в якій і стоїте́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 2, 'Якою й спасаєтесь, коли пам\'ятаєте, яким словом я благовісти́в вам, якщо тільки ви ввірували не нао́сліп.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 3, 'Бо я передав вам найперш, що й прийняв, - що Христос був умер ради наших гріхів за Писа́нням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 4, 'і що Він був похо́ваний, і що третього дня Він воскрес за Писа́нням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 5, 'і що з\'явився Він Ки́фі, потім Дванадцятьо́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 6, 'А по́тім з\'явився нара́з більше як п\'ятистам браттям, що більшість із них живе й досі, а дехто й спочи́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 7, 'Пото́му з\'явився Він Якову, опісля - усім апо́столам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 8, 'А по всіх Він з\'явився й мені, мов якому недо́родкові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 9, 'Я бо найменший з апо́столів, що негі́дний зватись апо́столом, бо я переслідував був Божу Церкву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 10, 'Та благода́ттю Божою я те, що є, і благода́ть Його, що в мені, не даремна була́, але я працював більше всіх їх, правда - не я, але Божа благода́ть, що зо мною вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 11, 'Тож чи я, чи вони, - ми так проповідуємо, і так ви ввірували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 12, 'Коли ж про Христа проповідується, що воскрес Він із мертвих, - як же дехто між вами гово́рять, що немає воскресіння мертвих?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 13, 'Як немає ж воскресіння мертвих, то й Христос не воскрес!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 14, 'Коли ж бо Христос не воскрес, то проповідь наша даремна, даремна також віра ваша!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 15, 'Ми знайшлися б тоді неправдивими свідками Божими, бо про Бога ми сві́дчили, що воскреси́в Він Христа, Якого Він не воскресив, якщо не воскресають померлі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 16, 'Бо як мертві не воскресають, то й Христос не воскрес!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 17, 'Коли ж бо Христос не воскрес, тоді віра ваша даремна, - ви в своїх ще гріхах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 18, 'тоді то загинули й ті, що в Христі упоко́їлись!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 19, 'Коли ми наді́ємося на Христа тільки в цьому житті, то ми найнещасні́ші від усіх людей!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 20, 'Та нині Христос воскрес із мертвих, - пе́рвісток серед покі́йних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 21, 'Смерть бо через люди́ну, і через Люди́ну воскресіння мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 22, 'Бо так, як в Ада́мі вмирають усі, так само в Христі всі оживуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 23, 'кожен у своєму порядку: пе́рвісток Христос, по́тім ті, що Христові, під час Його при́ходу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 24, 'А пото́му кінець, коли Він передасть царство Богові й Отцеві, коли Він зруйнує всякий уря́д, і вла́ду всяку та силу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 25, 'Бо належить Йому царювати, аж доки Він не „покладе всіх Своїх ворогів під ногами Своїми!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 26, 'Як ворог останній - смерть зни́щиться,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 27, 'бо „під ноги Його Він усе впокори́в“. Коли ж каже, що впоко́рено все, то ясно, що все, окрім Того, Хто впокори́в Йому все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 28, 'А коли Йому все Він упоко́рить, тоді й Сам Син упоко́риться Тому́, Хто все впокори́в Йому, щоб Бог бу́в у всьому все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 29, 'Бо що зроблять ті, хто христяться ради мертвих? Коли мертві не воскресають зовсім, то на́що вони ради мертвих і христяться?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 30, 'Для чого й ми повсякча́с наражаємось на небезпе́ки?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 31, 'Я щодень умираю. Так свідчу, браття, вашою хвалою, що маю її в Христі Ісусі, Господі нашім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 32, 'Коли я зо звіра́ми боровся в Ефе́сі, яка мені по-лю́дському ко́ристь, коли мертві не воскресають? „Будем їсти та пити, бо ми взавтра вмрем!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 33, 'Не дайте себе зве́сти, — товари́ство лихе псує добрі звича́ї!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 34, 'Протверезі́ться правдиво, та й не грішіть, бо деякі Бога не знають, — говорю́ вам на сором!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 35, 'Але дехто скаже: „Як мертві воскреснуть? І в якім тілі при́йдуть?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 36, 'Нерозумний, — що́ ти сієш, те не оживе, як не вмре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 37, 'І коли сієш, то сієш не тіло майбутнє, але голе зе́рно, яке тра́питься, — пшениці або чого іншого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 38, 'і Бог йому тіло дає, як захоче, і кожному зе́рняті тіло його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 39, 'Не кожне тіло однакове тіло, але ж інше в люде́й, та інше тіло в скотини, та інше тіло в пташо́к, та інше у риб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 40, 'Є небесні тіла й тіла зе́мні, але ж інша слава небесним, а інша зе́мним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 41, 'Інша слава для сонця, та інша слава для місяця, та інша слава для зір, — бо зоря́ від зорі́ відрізня́ється славою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 42, 'Так само й воскресіння мертвих: сіється в тління, — в нетління встає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 43, 'сіється в неславу, — у славі встає, сіється в немочі, — у силі встає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 44, 'сіється тіло звичайне, — встає тіло духовне. Є тіло звичайне, є й тіло духовне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 45, 'Так і написано: „Перша люди́на Ада́м став душею живою“, а останній Ада́м — то дух оживляючий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 46, 'Та не перше духовне, але звичайне, а потім духовне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 47, 'Перша люди́на — з землі, зе́мна, друга Люди́на — із неба Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 48, 'Який зе́мний, такі й земні, і Який небесний, такі й небесні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 49, 'І, як носили ми образ зе́много, так і образ небесного бу́демо носити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 50, 'І це скажу́, браття, що тіло й кров посісти Божого Царства не можуть, ані тління нетління не посяде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 51, 'Ось кажу́ я вам таємни́цю: не всі ми засне́мо, та всі перемінимось, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 52, 'раптом, як оком змигну́ти, при останній сурмі́: бо засурми́ть вона — і мертві воскреснуть, а ми перемінимось!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 53, 'Мусить бо тлінне оце зодягну́тись в нетління, а смертне оце зодягтися в безсмертя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 54, 'А коли оце тлінне в нетління зодя́гнеться, і оце смертне в безсмертя зодя́гнеться, тоді збудеться слово написане: „Поглинута смерть перемогою“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 55, 'Де, смерте, твоя перемога? Де твоє, смерте, жало́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 56, 'Жало́ ж смерти — то гріх, а сила гріха — то Зако́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 57, 'А Богові дяка, що Він Господом нашим Ісусом Христом перемогу нам дав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 58, 'Отож, брати любі мої, будьте міцні, непохитні, збагачуйтесь за́вжди в Господньому ділі, знаючи, що ваша праця не марно́тна у Господі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 1, 'А щодо складо́к на святих, то й ви робіть так, як я постановив для Церков галаті́йських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 2, 'А першого дня в тижні нехай кожен із вас відкладає собі та збирає, згідно з тим, як ведеться йому, щоб складо́к не робити тоді, аж коли я прийду́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 3, 'А коли я прийду́, тоді тих, кого виберете, тих пошлю я з листами, щоб вони ваш дар любови відне́сли до Єрусалиму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 4, 'А коли ж і мені випада́тиме йти, то зо мною піду́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 5, 'Я прибуду до вас, коли перейду́ Македо́нію, бо прохо́джу через Македонію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 6, 'А в вас, коли трапиться, я поживу́ або й перези́мую, щоб мене провели́ ви, куди я піду́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 7, 'Не хо́чу я бачитись з вами тепер мимохі́дь, але сподіва́юся деякий час перебути у вас, як дозволить Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 8, 'А в Ефе́сі пробу́ду я до П\'ятдеся́тниці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 9, 'бо двері великі й широкі мені відчинилися, та багато противників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 10, 'Коли ж при́йде до вас Тимофі́й, то пильнуйте, щоб він був безпечний у вас, бо ді́ло Господнє він робить, як і я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 11, 'Тому́ то нехай ним ніхто не пого́рджує, але відпровадьте його з миром, щоб прийшов він до мене, бо чека́ю його з брата́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 12, 'А щодо брата Аполло́са, то я ду́же благав був його, щоб прийшов до вас з брата́ми, та охоти не мав він прибути тепер, але при́йде, як матиме час відповідний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 13, 'Пильнуйте, стійте у вірі, будьте мужні, будьте міцні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 14, 'хай з любов\'ю все робиться у вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 15, 'Благаю ж вас, браття, — знаєте ви дім Степанів, що в Аха́ї він пе́рвісток, і що службі святим присвяти́лись вони, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 16, 'і ви підкоряйтесь таким, також кожному, хто помагає та працю́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 17, 'Я тішусь з при́ходу Степана, і Фортуна́та, і Аха́їка, бо вашу відсутність вони заступили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 18, 'бо вони заспоко́їли духа мого й вашого. Тож шануйте таких!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 19, 'Вітають вас азійські Церкви́; Аки́ла й Приски́лла з домашньою Церквою їхньою гаряче вітають у Господі вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 20, 'Вітають вас усі брати. Вітайте один о́дного святим поцілунком.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 21, 'Привіта́ння моєю рукою Павловою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 22, 'Коли хто не любить Господа, нехай буде про́клятий! Мара́на та́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 23, 'Благода́ть Господа нашого Ісуса нехай буде з вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 24, 'Любов моя з вами всіма́ у Христі Ісусі, амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Павло, з волі Божої апо́стол Христа Ісуса, та брат Тимофій, до Божої Церкви в Коринті, з усіма́ святими в ці́лій Аха́ї, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'благода́ть вам і мир від Бога Отця нашого й Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Благословенний Бог і Отець Господа нашого Ісуса Христа, Отець милосердя й Бог потіхи всілякої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'що в усякій скорбо́ті Він нас потішає, щоб змогли потішати й ми тих, що в усякій скорбо́ті знахо́дяться, тією потіхою, якою потішує Бог нас самих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Бо поскільки намно́жуються в нас терпіння Христові, — так через Христа й поті́шення наше намножується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Бо як те́рпимо скорбо́ти, то на вашу потіху й спасі́ння; коли потішаємось, то на вашу потіху в терпінні тих самих стражда́нь, які те́рпимо й ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'А наша надія певна про вас, бо ми знаємо, що ви спільники як у терпіннях, так само і в потісі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Бо не хочемо, браття, щоб не відали ви про нашу скорбо́ту, що в Азії трапилась нам, бо над міру й над силу були́ ми обтяжені, так що ми не наді́ялися навіть жити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Та самі ми в собі мали при́суд на смерть, щоб нам не покладати надії на себе, а на Бога, що воскрешує мертвих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'що від смерти такої нас визволив і визволяє, і на Нього й поклада́ємося, що й ще визволить Він,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'як поможете ра́зом і ви молитвою за нас, щоб за дар ласки, що нам виявлений багатьма́, багато-хто дяку складали за нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Бо це нам хвала́, — сві́дчення нашого сумління, що в святості й чистості Божій, не в тілесній мудрості, але в Божій благода́ті жили́ ми на світі, особливо ж у вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Бо іншого вам ми не пишемо, тільки те, що читаєте та розумієте, а сподіва́юсь, що ви й до кінця зрозумієте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'як части́нно нас ви й зрозуміли, що ми вам похвала́, як і ви нам, у день Господа нашого Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'І з певністю цією хотів я давніше прибути до вас, щоб мали ви благода́ть удру́ге,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'і через вас перейти в Македонію, а з Македонії зно́ву прибути до вас, а ви щоб в Юдею мене відпрова́дили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Маючи за́дум такий, чи я чини́в легковажно? Чи те, що заду́мую, за тілом задумую, щоб було в мене і „Так, так“, і „Ні, ні?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Але вірний Бог, що наше слово до вас не було „Так“і „Ні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Бо Син Божий Ісус Христос, що ми Його вам проповідували, я й Силуа́н, і Тимофій, не був „Так“і „Ні“, але в Нім було „Так“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Скільки бо Божих обі́тниць, то в Ньому „Так“, і в Ньому „Амінь“, — Богові на славу через нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'А Той, Хто нас із вами в Христа утверджує, і Хто нас намасти́в, — то Бог,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'Який і запечатав нас, і в наші серця дав завда́ток Духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'А я кличу Бога на свідка на душу мою, що я, щадячи́ вас, не прийшов у Кори́нт дотепе́р,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, 'не тому́, ніби ми беремо́ вла́ду над вашою вірою, але вашої радости помічники ми, — бо ви всто́яли вірою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'А я постановив у собі те, щоб до вас не прийти знов у смутку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Бо коли я засму́чую вас, то хто той, хто потішить мене, як не той, кого я засмути́в?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'І це саме писав я до вас, щоб, прийшовши, я смутку не мав би від тих, що від них мені тішитися нале́жало, про всіх вас бувши певний, що радість моя — то радість усіх вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Бо з великого горя та з ту́ги сердечної я написав вам з рясни́ми слізьми́ не на те, щоб були ви засму́чені, але щоб пізнали любов, що в мене її пребагато до вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'А як хто засмутив, не мене засмутив, а поча́сти — щоб не пригніти́ти — і всіх вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'До́сить такому кара́ння того, що від багатьох,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'через те навпаки́, — краще простити й поті́шити, щоб смуток великий його не поже́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Через те вас благаю: зміцніть до нього любов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Бо на це я й писав, щоб пізнати ваш до́свід, чи в усім ви слухня́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'А кому ви прощаєте що, тому й я; бо й я, як простив що кому, то кому я простив, зробив те через вас від Особи Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'щоб нас сатана не перехитрував, — відо́мі бо нам його задуми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'А коли я прийшов до Троа́ди звіщати Христову Єва́нгелію, і були двері для мене відчинені в Господі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'не мав я споко́ю для духа свого, бо я не знайшов був свого брата Тита; але, попрощавшися з ними, я пішов в Македонію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'А Богові подяка, що Він постійно чинить нас переможцями в Христі, і запа́шність знання́ про Себе через нас виявляє на всякому місці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Ми бо для Бога Христова запа́шність серед тих, хто спасається, і тих, які гинуть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'для одних бо смертельна запа́шність на смерть, а для других запа́шність життє́ва в життя. І хто здатен на це?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Бо ми не такі, як багато-хто, що Боже Слово фальшують, але ми провіщаємо, як із щирости, як від Бога, перед Богом, у Христі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Чи нам знов зачинати дору́чувати самих себе́? Чи ми потребуємо, як дехто, листів доруча́льних до вас чи від вас?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Ви наш лист, написаний у наших серцях, якого всі люди знають і читають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Виявляєте ви, що ви — лист Христів, нами вислужений, що написаний не чорнилом, але Духом Бога Живого, не на табли́цях камінних, але на тіле́сних табли́цях серця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Таку ж певність до Бога ми маємо через Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'не тому́, що ми здібні поми́слити щось із се́бе, як від себе, але наша здібність від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'І Він нас зробив бути здатними служи́телями Ново́го Заповіту, не букви, а Духа, — бо буква вбиває, а Дух оживля́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Коли ж служі́ння смерті, вирізане на каменях буквами, було таке славне, що Ізра́їлеві сини не могли дивитись на обличчя Мойсея, через славу мину́щу обличчя його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'скільки ж більш буде в славі те служі́ння Духа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Бо як служі́ння о́суду — слава, то служіння праведности тим більше багате на славу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Не просла́вилося бо прославлене, у цій частині, ради слави, що вона переважує,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'бо коли славне те, що минає, то багато більш у славі те, що триває!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Тож, мавши надію таку, ми вживаємо великої сміли́вости,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'а не як Мойсей, що покрива́ло клав на обличчя своє, щоб Ізраїлеві сини не дивилися на кінець того, що минає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Але засліпилися їхні думки́, бо те саме покрива́ло аж до сьогодні лишилось незняте в чита́нні Старо́го Заповіту, бо зникає воно Христо́м.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Але аж до сьогодні, як читають Мойсея, на їхньому серці лежить покрива́ло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, '„коли ж вони наве́рнуться до Господа, тоді покрива́ло здіймається“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Госпо́дь же — то Дух, а де Дух Господній, — там воля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Ми ж відкритим обличчям, як у дзеркало, дивимося всі на славу Господню, і зміняємося в той же образ від слави на славу, як від Духа Господнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Ось тому́, мавши за милосердям Божим таке служі́ння, ми не тратимо відваги,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'але ми відреклися тайного со́рому, не хо́дячи в хитрості та не перекручуючи Божого Слова, але з\'я́вленням правди доручуємо себе кожному сумлінню лю́дському перед Богом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'Коли ж наша Єва́нгелія й закрита, то закрита для тих, хто гине, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'для невіруючих, яким бог цього віку засліпив розум, щоб для них не зася́яло світло Єва́нгелії слави Христа, а Він — образ Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Бо ми не себе самих проповідуємо, але Христа Ісуса, Господа, ми ж самі — раби ваші ради Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'Бо Бог, що звелів був світлу зася́яти з те́мряви, у серцях наших зася́яв, щоб просвітити нам знання́ слави Божої — в Особі Христовій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'А ми маємо скарб цей у посу́динах гли́няних, щоб ве́лич сили була Божа, а не від нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'У всьому нас тиснуть, та не поти́снені ми; ми в важки́х обставинах, але не впадаємо в ро́зпач.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Переслідують нас, але ми не полишені; ми повалені, та не погублені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'Ми за́всіди носимо в тілі ме́ртвість Ісусову, щоб з\'явилося в нашому тілі й життя Ісусове.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Бо за́всіди нас, що живемо́, віддають на смерть за Ісуса, щоб з\'явилось Ісусове в нашому смертельному тілі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Тому́ то смерть діє в нас, а життя — у вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Та мавши того ж духа віри, за написаним: „Вірував я, через те говорив“, і ми віруємо, тому то й говоримо,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'знавши, що Той, Хто воскресив Господа Ісуса, воскреси́ть з Ісусом і нас, і поставить із вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Усе бо для вас, щоб благода́ть, розмножена через багатьох, збагати́ла подяку на Божу славу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'Через те ми відваги не тратимо, бо хоч ни́щиться зовнішній наш чоловік, зате день-у-день відновля́ється внутрішній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Бо тепе́рішнє легке наше горе достачає для нас у безмірнім багатстві славу вічної ваги,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'коли ми не дивимося на види́ме, а на невиди́ме. Бо види́ме - дочасне, невиди́ме ж - вічне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Знаємо бо, коли зе́мний мешка́льний наме́т наш зруйнується, то маємо будівлю від Бога на небі, - дім нерукотво́рний та вічний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'Тому́ то й зідхаємо, бажаючи приодягти́ся будівлею нашею, що з неба,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'коли б тільки й одя́гнені ми не знайшлися нагі́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Бо ми, знахо́дячися в цьому наметі, зідхаємо під тягаре́м, бо не хочемо роздягти́ся, але одягти́ся, щоб смертне поже́рлось життям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'А Той, Хто на це саме й створив нас, то Бог, що й дав нам завда́ток Духа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Отож, бувши відважні постійно, та знаючи, що, мавши дім у тілі, ми не перебуваємо в домі Господньому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'бо хо́димо вірою, а не виді́нням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'ми ж відважні, і бажаємо краще покинути дім тіла й мати дім у Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Тому́ ми й пильнуємо, - чи зостаємося в домі тіла, чи вихо́димо з дому, - бути Йому лю́бими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'Бо мусимо всі ми з\'явитися перед судо́вим престолом Христовим, щоб кожен прийняв згідно з тим, що́ в тілі робив він, - чи добре, чи лихе́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Отже, відаючи страх Господній, ми людей переконуємо, а Богові явні; але маю надію, що й у ваших сумліннях ми явні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'Бо не зно́ву себе ми дору́чуємо вам, але даємо вам привід хвали́тися нами, щоб мали ви що проти тих, що хва́ляться обличчям, а не серцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'Коли бо ми з розуму сходимо, - то Богові, коли ж при здоровому розумі, - то для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Бо Христова любов спону́кує нас, що ду́мають так, що коли вмер Один за всіх, то всі померли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'А вмер Він за всіх, щоб ті, хто живе, не жили вже для себе самих, а для Того, Хто за них був умер і воскрес.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Через те відтепе́р ми ніко́го не знаємо за тілом; коли ж і знали за тілом Христа, то тепер ми не знаємо вже!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Тому́ то, коли хто в Христі, той створі́ння нове́, - стародавнє минуло, ото сталось нове́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'Усе ж від Бога, що нас примирив із Собою Ісусом Христом і дав нам служі́ння прими́рення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'бо Бог у Христі примирив світ із Собою Самим, не зважа́вши на їхні провини, і поклав у нас слово прими́рення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, 'Оце ми як посли замість Христа, ніби Бог благає через нас, благаємо замість Христа: примиріться з Богом!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Бо Того́, Хто не відав гріха, Він учинив за нас гріхом, щоб стали ми Божою праведністю в Нім!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'А ми, як співробі́тники, благаємо, щоб ви Божої благода́ті не брали надармо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Бо каже: „Приємного ча́су почув Я тебе, - і поміг Я тобі в день спасі́ння!“Ось тепер час приємний, ось тепер день спасіння!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Ні в чому ніякого спотика́ння не робимо, щоб служі́ння було бездога́нне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'а в усьому себе виявляємо, як служи́телів Божих, у великім терпінні, у скорбо́тах, у бідах, у тісно́тах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'у вда́рах, у в\'язницях, у ро́зрухах, у пра́цях, у недосипа́ннях, у поста́х,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'у чи́стості, у розумі, у ла́гідності, у до́брості, у Дусі Святім, у нелицемі́рній любові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'у слові правди, у силі Божій, зо зброєю праведности в прави́ці й ліви́ці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'через славу й безчестя, через га́ньбу й хвалу́, як обманці, але ми правдиві;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'як незнані, та по́знані, як умираючі, та ось ми живі; як ка́рані, та не забиті;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'як сумні, але за́вжди веселі; як убогі, але багатьох ми збага́чуємо; як ті, що нічого не мають, але всім володіємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Уста наші відкрились до вас, кори́нтяни, серце наше розши́рене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'У нас вам не тісно, але тісно вам у ваших серцях!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Такою ж відплатою — говорю́, немов дітям — розширені будьте й ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'До чужого ярма́ не впрягайтесь з невірними; бо що спільного між праведністю та беззако́нням, або яка спільність у світла з те́мрявою?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'Яка згода в Христа з белійяа́ром? Або яка частка вірного з невірним?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 16, 'Або яка згода поміж Божим храмом та ідолами? Бо ви храм Бога Живого, як Бог прорік: „Поселюсь серед них і ходитиму, і буду їм Богом, — а вони бу́дуть наро́дом Моїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 17, 'Вийдіть тому́ з-поміж них та й відлучі́ться, — каже Госпо́дь, — і не торкайтесь нечистого, — і Я вас прийму́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 18, 'і буду Я вам за Отця, а ви за синів і дочо́к Мені бу́дете, — говорить Господь Вседержи́тель!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 1, 'Отож, мої любі, мавши ці обі́тниці, очистьмо себе від усякої не́чисти тіла та духа, — і творімо святиню у Божім страху́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 2, 'Дайте місце для нас! Ми ніко́го не скривдили, ніко́го не зіпсували, нікого не ошука́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 3, 'Говорю́ не на о́суд, бо я перед тим був сказав, що ви в серцях наших, щоб нам із вами чи померти чи жити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 4, 'У мене велика сміли́вість до вас, велика мені похвала́ з вас, я повний потіхи, збагачаюся радістю при всякому нашому горі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 5, 'Бо коли ми прийшли в Македо́нію, тіло наше не мало спочинку нія́кого, у всьому бідуючи: назовні — бої, страхіття — всере́дині.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 6, 'Але Бог, що тішить прини́жених, потішив нас при́ходом Тита,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 7, 'і не тільки його прибуття́м, а й поті́шенням, що ним він потішився з вас, коли розповідав нам про вашу журбу́, про ваш смуток, про вашу горли́вість до мене, так що я більше тішився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 8, 'Коли я й засмутив вас листом, то не каюся, хоч і каявся був, бо бачу, що той лист засмутив вас, хоч і часово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 9, 'Я радію тепер не тому́, що ви засмутились, а що ви засмутилися на покая́ння, бо ви засмутились для Бога, щоб ні в чо́му не мати втрати від нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 10, 'Бо смуток для Бога чинить каяття́ на спасі́ння, а про нього не жалуємо, а смуток світськи́й — чинить смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 11, 'Бо ось саме це, що ви засмутились для Бога, яку пильність велику воно вам зробило, яку оборону, яке обурення, який страх, яке бажа́ння, яку горливість, яку по́мсту! Ви в усім показали, що чисті ви в справі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 12, 'А коли я й писав вам, то не через того, хто кри́вдить, і не через покри́вдженого, а щоб виявилася для вас наша пильність про вас перед Богом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 13, 'Тому́ то потіхою вашою вті́шились ми, а ще більше зраділи ми радістю Тита, що ви всі заспоко́їли духа його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 14, 'Бо коли я про вас йому чим похвалився, то не осоро́мився; але як ми вам говорили все правду, так і наша хвала́ перед Титом правдива була́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 15, 'І серце його прихильніше до вас, коли згадує він про покору всіх вас, як його прийняли́ ви були зо стра́хом і тремті́нням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 16, 'Отож, тішуся я, що мо́жу покластись у всьому на вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 1, 'Повідомляємо ж вас, браття, про Божу благода́ть, що да́на Церква́м македо́нським,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 2, 'що серед великого досвіду горя вони мають радість рясну́, і глибоке їхнє убо́зтво збага́тилось багатством їхньої щирости;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 3, 'бо вони добровільні в мі́ру сил своїх, і над силу, засвідчую, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 4, 'із ревним блага́нням вони нас просили, щоб ми прийняли́ дар та спільність служіння святим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 5, 'І не так, як наді́ялись ми, але віддали́ себе перш Господе́ві та нам із волі Божої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 6, 'щоб ми благали Тита, щоб він, як був перше зачав, так і скінчи́в би в вас оце добре ді́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 7, 'А ви, як у всім, збагачуєтесь: вірою, і словом, і розумом, і всякою пильністю, і вашою любов\'ю до нас, — щоб збагачувались ви і в благода́ті оцій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 8, 'Не кажу́ це, як нака́за, але́ пильністю інших досві́дчую щирість любови й вашої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 9, 'Бо ви знаєте благода́ть Господа нашого Ісуса Христа, Який, бувши багатий, збіднів ради вас, щоб ви збагатились Його убо́зтвом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 10, 'І раду даю вам про це, бо це вам на пожи́ток, що не тільки чинили, але перші ви стали й бажати з минулого ро́ку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 11, 'А тепер закінчі́ть роботу, щоб ви, як горли́во бажали, так і виконали б у міру можности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 12, 'Бо коли є охота, то приємна вона згідно з тим, що́ хто має, а не з тим, чого хто не має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 13, 'Хай не буде для інших полегша, а тягар для вас, але рівність для всіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 14, 'Ча́су тепе́рішнього ваш достаток нехай неста́ткові їхньому допоможе, щоб і їхній достаток був на ваш неста́ток, щоб рівність була́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 15, 'як написано: „Хто мав багато, той не мав зайвини́, а хто мало, — не мав недостачі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 16, 'Та Богові дяка, що Він таку пильність про вас дав у Ти́тове серце,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 17, 'бо блага́ння прийняв він, але́, бувши горли́вий, удався до вас добровільно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 18, 'А з ним ра́зом послали ми брата, якого по всіх Церква́х хвалять за Єва́нгелію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 19, 'і не тільки оце, але ви́браний був від Церко́в бути товаришем нашим у дорозі для благода́ті тієї, якій служимо ми на хвалу́ Само́го Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 20, 'остерігаючись того, щоб хто не дорікав нам цим достатком, що ним служимо ми,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 21, 'дба́ючи про добро не тільки перед Богом, але й перед людьми́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 22, 'А ми з ними послали були́ брата нашого, про пильність якого ми часто досвідчувались у речах багатьо́х, який ще пильніший тепер — через велике довір\'я до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 23, 'Щодо Тита, то він мій това́риш, а ваш співробі́тник; щождо наших братів — вони посланці від Церко́в, вони слава Христова!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 24, 'Отож, дайте їм доказа своєї любови й нашого хвалі́ння вас перед Церква́ми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 1, 'А про службу святим мені зайво писати до вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 2, 'бо відаю вашу охоту, і нею хвалюся за вас македо́нянам, що Аха́я готова з минулого року, а ваша ре́вність заохо́тила багатьох.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 3, 'А я послав братів, щоб моя похвала́, щодо вас, не даремна була в цім випа́дкові, але, як казав, щоб були ви пригото́ва́ні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 4, 'щоб, коли македо́няни при́йдуть зо мною та зна́йдуть, що ви неготові, щоб не осоро́митись нам — не кажемо вам — у цій речі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 5, 'Отож, я наду́мався, що треба вблагати братів, щоб пішли перше до вас та приготува́ли заздалегі́дь оголошений ваш щедрий дар, щоб був він пригото́ваний, як щедрий дар, а не річ примусова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 6, 'А до цього кажу́: Хто скупо сіє, — той скупо й жатиме, а хто сіє щедро, — той щедро й жатиме!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 7, 'Нехай кожен дає, як серце йому призволя́є, — не в смутку й не з примусу, бо Бог любить того, хто з радістю дає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 8, 'А Бог має силу всякою благода́ттю вас збагати́ти, щоб ви, мавши за́вжди в усьому всілякий достаток, збага́чувалися всяким добрим учинком,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 9, 'як написано: „Розси́пав та вбогим роздав, — Його праведність триває навіки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 10, 'А Той, Хто насіння дає сіяче́ві та хліб на поживу, — нехай дасть і примно́жить ваше насіння, і нехай Він зрости́ть плоди праведности вашої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 11, 'щоб усім ви збагачувались на всіляку щирість, яка через нас чинить Богові дяку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 12, 'Бо ді́ло служі́ння цього не тільки випо́внює недостачі святих, але й багатіє багатьма́ подяками Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 13, 'Досвідченням цього служі́ння вони хвалять Бога за по́слух Христовій Єва́нгелії, що ви визнаєте її, та за щирість учасництва з ними й усіма́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 14, 'вони за вас моляться й тужать по вас із-за дуже великої Божої благода́ті на вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 15, 'Дяка Богові за невимо́вний дар Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 1, 'А я сам, Павло, благаю вас ла́гідністю й ласка́вістю Христовою; я, коли присутній — слухня́ний між вами, а не бувши між вами — сміли́вий я супроти вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 2, 'І благаю, щоб я, прибувши, не осмі́лився надією, що нею я ду́маю сміли́вим бути проти деяких, що про нас вони гада́ють, ніби ми поступаємось за тілом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 3, 'Бо хо́дячи в тілі, не за тілом воюємо ми, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 4, 'зброя бо нашого воюва́ння не тілесна, але міцна́ Богом на зруйнува́ння тверди́нь, — ми руйнуємо за́думи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 5, 'і всяке ви́несення, що підіймається проти пізна́ння Бога, і поло́нимо всяке знання́ на по́слух Христові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 6, 'і покарати ми готові всякий непо́слух, коли зді́йсниться послух ваш.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 7, 'Чи на обличчя ви дивитеся? Як хто певний про себе, що Христовий він, нехай ду́має знов по собі, що як сам він Христовий, так само Христові й ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 8, 'Бо коли б я ще більш став хвалитися нашою вла́дою, яку дав нам Господь на збудува́ння, а не на зруйнува́ння ваше, то не осоро́млюсь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 9, 'Та щоб не здавалось, ніби хочу лякати вас листами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 10, '„Бо листи його — кажуть — важкі́ та міцні́, але особисто присутній — слабий, а мова його незначна́“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 11, 'такий нехай знає оце, що які ми на слові в листах, неприсутніми бувши, такі ми й на ді́лі, присутніми бувши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 12, 'Бо не сміємо вважати себе чи рівняти до інших, що самі себе хвалять, — вони нерозумно самі себе міряють собою, і рівняють з собою себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 13, 'Ми ж не будем хвалитись над міру, а в міру міри́ла, що його Бог призна́чив на міру для нас, щоб і до нас досягти́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 14, 'Бо ми не розтягуємося над міру, ніби не досягли́ ми до вас, бо ми досягли́ аж до вас із Єва́нгелією Христовою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 15, 'Ми не хвалимось над міру у чужих працях, але маємо надію, що як буде рости ваша віра, то за нашим міри́лом сильно звели́чимося ми між вами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 16, 'щоб і в дальших за вами країнах звіщати Єва́нгелію, а не хвалитись готовим, як це чужі тве́рдять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 17, 'А „хто хва́литься, нехай хва́литься в Господі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 18, 'Бо достойний не той, хто сам себе хва́лить, але кого хвалить Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 1, 'О, коли б потерпі́ли ви трохи безу́мство моє! Але й те́рпите ви мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 2, 'Бо пильную про вас пильністю Божою, заручив бо я вас одно́му чоловікові, щоб Христові приве́сти вас чистою дівою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 3, 'Та боюсь я, — як змій звів був Єву лука́вством своїм, щоб так не попсувалися ваші думки́, і ви не вхилилися від простоти́ й чи́стости, що в Христі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 4, 'Коли бо хто при́йде й зачне пропові́дувати про Ісуса іншого, про якого ми не проповідували, або при́ймете іншого Духа, якого ви не прийняли, або іншу Єва́нгелію, якої ви не прийняли́, — то радо терпіли б ви те!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 5, 'Та ду́маю я, що нічим не лишаюсь позад передні́ших апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 6, 'Хоч і неук я словом, але не знання́м, та всюди в усьому ми ви́явлені поміж вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 7, 'Чи я гріх учинив, себе впокоря́ючи, щоб підвищити вас, бо я Божу Єва́нгелію благовістив для вас дармо?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 8, 'Оббирав я інші Церкви́, приймаючи плату для служіння вам. А коли я прийшов до вас і терпів недостачу, то ніко́го я не обтя́жив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 9, 'Бо мій нестаток попо́внили бра́ти, що прийшли з Македонії; і в усьому беріг я себе, щоб не бути для вас тягаре́м, і збережу́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 10, 'Як правда Христова в мені, так оця похвала́ не замо́вчана буде про мене в країнах Ахаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 11, 'Для чо́го? Тому́, що я вас не люблю́? Відо́мо те Богові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 12, 'А що я роблю́, те й робитиму, щоб відтя́ти причину для тих, хто шукає причини, щоб у то́му, чим хва́ляться, показались такі, як і ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 13, 'Такі бо фальшиві апо́столи, лукаві робітники́, що підро́блюються на Христових апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 14, 'І не дивно, бо сам сатана́ прикидається а́нголом світла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 15, 'Отож, не велика це річ, якщо й слуги його прикидаються слу́гами праведности. Буде їхній кінець згідно з учинками їхніми!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 16, 'Зно́ву кажу́: хай ніхто не вважає мене за безумного! А як ні, то прийміть мене бодай як безумного, щоб хоч трохи й я похвалився!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 17, 'А що я кажу́, не кажу́ того в Господі, але ніби в безу́мстві — у цій частині хвали́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 18, 'Через те ж, що тілом багато-хто хваляться, то й я похвалюся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 19, 'Бо ви те́рпите радо безумних, самі мудрими бувши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 20, 'Бо ви терпите, коли вас хто нево́лить, коли хто об\'їдає, коли хто обдирає, коли хто підвищується, коли хто по що́ках вас б\'є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 21, 'На безчестя кажу́, що ми ніби стратили сили. Коли хто відва́житься чим, то — скажу́ нерозумно — відважуюся й я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 22, 'Євреї вони? — То й я. Ізра́їльтяни вони? — То й я. Насіння вони Авраамове? — То й я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 23, 'Слу́ги Христові вони? — Говорю́ нерозумне: більш я! Я був більш у пра́цях, у ранах над міру, частіш у в\'язницях, часто при смерті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 24, 'Від юдеїв п\'ять раз я прийняв був по сорок уда́рів без о́дного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 25, 'тричі ки́ями бито мене, один раз мене каменува́ли, тричі розбивсь корабель, ніч і день я пробу́в у глибині́ морській;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 26, 'у мандрі́вках я часто бува́в, бував у небезпеках на річках, у небезпеках розбійничих, у небезпеках свого наро́ду, у небезпеках поган, у небезпеках по міста́х, у небезпеках на пустині, у небезпеках на морі, у небезпеках між братами фальшивими,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 27, 'у висна́жуванні та в праці, часто в недосипа́нні, у голоді й спразі, часто в по́сті, у холоді та в наготі́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 28, 'Окрім зо́внішнього, налягають на мене денні повинності й журба про всі Церкви́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 29, 'Хто слабує, а я не слабую? Хто споку́шується, а я не палю́ся?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 30, 'Коли треба хвалитись, то неміччю я похвалюся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 31, 'Знає Бог і Отець Господа нашого Ісуса Христа, — а Він благослове́нний навіки, — що я не говорю́ неправди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 32, 'У Дама́ску намі́сник царя Аре́ти стеріг місто Дама́ск, щоб схопи́ти мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 33, 'але́ по мурі мене спу́щено в коші́ віко́нцем, — і я з рук його втік!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 1, 'Не кори́сно хвалитись мені, бо я прийду́ до видінь і об\'я́влень Господніх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 2, 'Я знаю чоловіка в Христі, що він чотирна́дцять ро́ків тому — чи в тілі, не знаю, чи без тіла, не знаю, знає Бог — був узятий до третього неба.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 3, 'І чоловіка я знаю такого, — чи в тілі, чи без тіла, не знаю, знає Бог, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 4, 'що до ра́ю був узятий, і чув він слова́ невимо́вні, що не можна люди́ні їх висловити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 5, 'Отаким похвалюся, а собою хвалитись не буду, — хіба тільки своїми не́мочами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 6, 'Бо коли я захо́чу хвалитись, то безумний не бу́ду, бо правду казатиму; але стримуюсь я, щоб про мене хто більш не поду́мав, ніж бачить у мені або чує від мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 7, 'А щоб я через пребагато об\'я́влень не велича́вся, то да́но мені в тіло колючку, — посланця́ сатани, щоб бив в обличчя мене, щоб я не велича́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 8, 'Про нього три ра́зи благав я Господа, щоб він відступився від мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 9, 'І сказав Він мені: „До́сить тобі Моєї благодаті, — бо сила Моя здійснюється в немочі“. Отож, краще я буду хвалитись своїми не́мочами, щоб сила Христова вселилася в мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 10, 'Тому любо мені перебува́ти в неду́гах, у при́кростях, у бі́дах, у переслідуваннях, в утисках через Христа. Коли бо я слаби́й, тоді я сильни́й.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 11, 'Хва́лячися, я став нерозумний, — до того мене ви примусили. Бо хвалити мене мали б ви, — бо ні в чо́му я не залиши́вся позад від найперших апо́столів, хоч я й ніщо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 12, 'А ознаки апо́стола виявилися між вами в усякім терпінні, у знаме́нах і чу́дах та в силах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 13, 'Що бо є, що ним ви пони́зилися більше від інших Церков? Хіба те, що я сам тягаре́м вам не був? Даруйте мені цю провину!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 14, 'Ось утре́тє готовий прийти я до вас, і не буду для вас тягаре́м, — не шукаю бо вашого я, тільки вас. Не діти повинні збирати маєток батька́м, але дітям батьки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 15, 'Я ж з охотою ви́трачуся й себе ви́трачу за душі ваші, хоч що більше люблю́ вас, то менше я лю́блений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 16, 'Та нехай буде так, — тягара́ я на вас не поклав, але, бувши хитрий, я лукавством від вас брав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 17, 'Чи я використо́вував вас через когось із тих, кого́ до вас посилав?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 18, 'Ублагав я був Тита, і з ним послав брата. Чи Тит ви́користав вас чим? Хіба ми ходили не в одно́му дусі? Хіба не одни́ми стопа́ми?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 19, 'Чи ви зно́ву не ду́маєте, що виправдуємось перед вами? Перед Богом, у Христі ми говоримо, а все, любі, на вашу будову!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 20, 'Я ж боюся, щоб, прийшовши, не знайшов вас такими, якими не хо́чу, і щоб мене не знайшли ви таким, якого не хочете, — хай не будуть між вами суперечка, заздрість, гніви, обмани, сва́ри, на́шепти, пихи́, безладдя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 21, 'щоб зно́ву, коли я прийду́, не прини́зив мене поміж вами мій Бог, і щоб мені не оплакувати багатьох, що перше згрішили були, і не покаялися в нечи́стості, і в пере́любі, і в розпусті, що ко́їли їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 1, 'Оце втретє до вас я йду. „Кожна справа хай станеться ви́роком двох чи трьох свідків“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 2, 'Попере́джував я й попере́джу́ю, — як у вас був удру́ге, так тепер неприсутній, — отих, що згрішили перед тим, і всіх інших, що коли прийду знову, то я не помилую,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 3, 'через те, що шукаєте доказу, що в мені промовляє Христос, Який не безсилий до вас, але сильний у вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 4, 'Бо хоч Він був і розп\'я́тий в не́мочі, та живий із сили Божої. Так і ми, — хоча не́мічні в Нім, та з Ним бу́демо жити з Божої сили у вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 5, 'Випробо́вуйте самих себе, чи ви в вірі, пізнавайте самих себе. Хіба ви не знаєте самих себе, що Ісус Христос у вас? Хіба тільки, що ви не такі, якими мали б бути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 6, 'Але маю надію, що пізнаєте ви, що ми такі, якими мали б бути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 7, 'І ми молимо Бога, щоб ви не чинили нія́кого ли́ха, не для то́го, щоб виявились ми досвідчені, а щоб учинили ви добре, а ми бу́дем немов негі́дні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 8, 'Бо нічо́го не можемо ми проти правди, а за правду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 9, 'Ми тішимося, коли ми слабі, а ви сильні. Про це й мо́лимось — щоб були досконалими ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 10, 'Ось тому́ то, відсутній, пишу́ це, щоб прийшовши, не мав я вчинити суворо за вла́дою, якої Госпо́дь мені дав на будува́ння, а не на руйнува́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 11, 'А накінець, браття, радійте, удосконалюйтесь, тіштеся, будьте однодумні, майте мир, — і Бог любови та ми́ру буде з вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 12, 'Вітайте один одного святим поцілунком! Усі святі вас вітають!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 13, 'Благода́ть Господа нашого Ісуса Христа, і любов Бога й Отця, і спільність Святого Духа нехай буде зо всіма́ вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 14, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Апо́стол Павло́, поставлений ні від людей, ані від чоловіка, але́ від Ісуса Христа й Бога Отця, що з мертвих Його воскресив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'і присутня зо мною вся браття, до Церко́в галаті́йських:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'благодать вам і мир від Бога, Отця нашого, і Господа Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'що за наші гріхи дав Само́го Себе, щоб від злого сучасного віку нас визволити, за волею Бога й Отця нашого, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Йому слава на віки́ вічні, амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Дивуюся я, що ви так скоро відхи́люєтесь від того, хто покликав Христовою благодаттю вас, на іншу Єва́нгелю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'що не інша вона, але деякі є, що вас непокоять, і хочуть перевернути Христову Єва́нгелію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Але якби й ми або а́нгол із неба зачав благовісти́ти вам не те, що ми вам благовісти́ли, — нехай буде прокля́тий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Як ми перше казали, і тепер знов кажу́: коли хто вам не те благовісти́ть, що ви прийняли́, — нехай буде прокля́тий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Бо тепер чи я в людей шукаю призна́ння чи в Бога? Чи лю́дям дба́ю я догоджа́ти? Бо коли б догоджав я ще лю́дям, я не був би рабо́м Христовим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'Звіщаю ж вам, браття, що Єва́нгелія, яку я благовісти́в, — вона не від людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'Бо я не прийняв, ні навчився її від люди́ни, але об\'явленням Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Чули бо ви про моє поступо́вання перше в юдействі, що Божу Церкву жорсто́ко я переслідував та руйнував її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'І я перевищував в юдействі багатьох своїх рове́сників роду мого, бувши запе́клим прихильником моїх отці́вських переда́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'Коли ж Бог, що вибрав мене від утро́би матері моєї і покликав благода́ттю Своєю, уподобав');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'виявити мною Сина Свого, щоб благовістив я Його між поганами, — я не радився зараз із тілом та кров\'ю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'і не відправився в Єрусалим до апо́столів, що передо мною були, а пішов я в Ара́бію, і зно́ву вернувся в Дама́ск.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'По трьох ро́ках пото́му пішов я в Єрусалим побачити Ки́фу, і в нього пробув днів із п\'ятнадцять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 19, 'А іншого з апо́столів я не бачив, крім Якова, брата Господнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 20, 'А що вам пишу́, ось кажу́ перед Богом, що я не обманюю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 21, 'Пото́му пішов я до си́рських та кілікі́йських країн.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 22, 'Церква́м же Христовим в Юдеї я знаний не був особисто, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 23, 'тільки чули вони, що той, що колись переслідував їх, благовісти́ть тепер віру, що колись руйнував був її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 24, 'І сла́вили Бога вони через мене!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Пото́му, по чотирнадцяти́ роках, я зно́ву ходив в Єрусалим із Варнавою, взявши й Тита з собою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'А пішов я за об\'явленням. І подав їм Єва́нгелію, що її проповідую між поганами, особливо знатнішим, чи не дарма́ змагаюся я чи змагався.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Але й Тит, що зо мною, бувши греком, не був до обрі́зання змушений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'А щодо прибулих фальшивих братів, що прийшли підгляда́ти нашу вільність, яку маємо в Христі Ісусі, щоб нас понево́лити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'то ми їх не послухали ані на хвилю, і не піддали́ся були, щоб тривала в вас правда Єва́нгелії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Що ж до тих, що за що́сь уважають себе, та якими колись вони були, то ні в чо́му різниці для мене нема, — не дивиться Бог на осо́бу люди́ни! Бо ті, що за щось уважають себе, нічого мені не додали́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'але навпаки́, — побачивши, що мені припору́чена Єва́нгелія для необрізаних, як Петрові для обрізаних, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'бо Той, хто помагав Петрові в апо́стольстві між обрізаними, помагав і мені між поганами, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'і, пізнавши ту благода́ть, що да́на мені, Яків, і Кифа, і Іван, що стовпа́ми вважаються, подали мені та Варна́ві прави́ці спільно́ти, щоб ми для поган працювали, вони ж — для обрізаних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'тільки щоб ми пам\'ята́ли про вбогих, що я й пильнував був чинити таке.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Коли ж Ки́фа прийшов був до Антіохі́ї, то відкрито я виступив супроти нього, — заслуго́вував бо він на о́суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Бо він перед тим, як прийшли були дехто від Якова, споживав із поганами. А коли прибули́, став ховатися та відлучатися, боячи́ся обрі́заних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'А з ним лицемі́рили й інші юдеї, так що навіть Варна́ва пристав був до їхнього лицемірства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'А коли я побачив, що не йдуть вони рівно за єва́нгельською правдою, то перед усіма сказав Кифі: „Коли ти, бувши юдеєм, живеш по-поганському, а не по-юдейському, то на́що поган ти примушуєш жити по-юдейському“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Ми юдеї природою, а не грішники з поган...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'А коли ми дізнались, що люди́на не може бути виправдана ділами Зако́ну, але тільки вірою в Христа Ісуса, то ми ввірували в Христа Ісуса, щоб нам виправдатися вірою в Христа, а не ділами Зако́ну. Бо жодна люди́на ділами Зако́ну не буде випра́вдана!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Коли ж, шукаючи виправда́ння в Христі, ми й самі показалися грішниками, то хіба Христос слуга гріху? Зовсім ні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Бо коли я будую знов те, що був зруйнував, то самого себе роблю́ злочинцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Бо Зако́ном я вмер для Зако́ну, щоб жити для Бога. Я розп\'я́тий з Христом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'І живу вже не я, а Христос проживає в мені. А що я живу в тілі тепер, — живу вірою в Божого Сина, що мене полюбив, і видав за мене Само́го Себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Божої благода́ті я не відкидаю. Бо коли набувається праведність Зако́ном, то Христос нада́рмо умер!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'О, ви нерозумні гала́ти! Хто вас звів не кори́тися правді, вас, яким перед очима Ісус Христос переднакре́слений був, як ніби між вами розп\'я́тий?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Це одне хочу знати від вас: чи ви прийняли́ Духа ділами Зако́ну, чи із про́повіді про віру?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Чи ж ви аж такі нерозумні? Духом почавши, кінчите́ тепер тілом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Чи ви так багато терпіли нада́рмо? Коли б тільки надармо!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Отже, Той, Хто вам Духа дає й чуда чинить між вами, — чи чинить ділами Зако́ну, чи із про́повіді про віру?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Так як Авраа́м „був увірував в Бога, — і це залічено за праведність йому“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Тож знайте, що ті, хто від віри, — то сини Авраа́мові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'І Писа́ння, передбачивши, що вірою Бог виправдає поган, благовісти́ло Авраамові: „Благосло́вляться в тобі всі наро́ди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Тому́ ті, хто від віри, бу́дуть поблагосло́влені з вірним Авраамом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'А всі ті, хто на діла Зако́ну покладається, — вони під прокля́ттям. Бо написано:, Прокля́тий усякий, хто не триває в усьому, що написано в книзі Зако́ну, щоб чинити оте!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'А що перед Богом Зако́ном ніхто не виправдується, то це ясно, бо „праведний житиме вірою“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'А Зако́н не від віри, але „хто чинитиме те, той житиме ним“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Христос відкупив нас від прокля́ття Зако́ну, ставши прокля́ттям за нас, бо написано: „Прокля́тий усякий, хто ви́сить на дереві“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'щоб Авраамове благослове́ння в Ісусі Христі поши́рилося на поган, щоб обі́тницю Духа прийняти нам вірою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Браття, кажу́ я по-лю́дському: навіть лю́дського затве́рдженого заповіту ніхто не відкидає та до нього не додає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'А обі́тниці да́ні були Авраамові й насінню його. Не говориться: „і насінням“, як про багатьох, але як про одно́го: „і Насінню твоєму“, яке є Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'А я кажу́ це, що заповіту, від Бога затве́рдженого, Зако́н, що прийшов по чотириста тридцяти роках, не відкидає, щоб обі́тницю він зруйнував.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Бо коли від Зако́ну спадщина, то вже не з обі́тниці; Авраамові ж Бог дарував із обі́тниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Що ж Зако́н? Він був даний з причини пере́ступів, аж поки при́йде Насіння, якому обі́тниця да́на була́; він учинений був анголами рукою посере́дника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Але посере́дник не є для одно́го, Бог же один.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Отож, чи ж Зако́н проти Божих обі́тниць? Зо́всім ні! Якби бо був да́ний Зако́н, щоб він міг оживляти, то праведність справді була б від Зако́ну!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Та все зачинило Писа́ння під гріх, щоб віруючим була да́на обі́тниця з віри в Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Але поки прийшла віра, під Зако́ном стере́жено нас, за́мкнених до при́ходу віри, що мала об\'яви́тись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Тому то Зако́н вихо́вником був до Христа, щоб нам виправдатися вірою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 25, 'А як віра прийшла, то вже ми не під вихо́вником.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 26, 'Бо ви всі сини Божі через віру в Христа Ісуса!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 27, 'Бо ви всі, що в Христа охристилися, у Христа зодягну́лися!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 28, 'Нема юдея, ні грека, нема раба, ані вільного, нема чоловічої статі, ані жіночої, — бо всі ви один у Христі Ісусі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 29, 'А коли ви Христові, то ви Авраамове насіння й за обі́тницею спадкоємці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Тож кажу́ я: поки спадкоє́мець дити́на, — він нічим від раба не різни́ться, хоч він пан над усім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'але під опікуна́ми та керівника́ми знаходиться він аж до ча́су, що визначив ба́тько.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Так і ми, — поки дітьми́ були, то були поневолені стихі́ями світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Як настало ж ви́повнення ча́су, Бог послав Свого Сина, що родився від жони, та став під Зако́ном,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'щоб викупити підзако́нних, щоб усино́влення ми прийняли́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'А що ви сини́, Бог послав у ваші серця Духа Сина Свого, що викликує: „Авва, Отче!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Тому ти вже не раб, але син. А як син, то й спадкоє́мець Божий через Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Та тоді, не знаючи Бога, служили ви тим, що з істоти бога́ми вони не були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'А тепер, як пізнали ви Бога, чи краще — як Бог вас пізнав, — як вертаєтесь знов до слаби́х та вбогих стихі́й, яким хочете знов, як давніше, служити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Ви вважаєте пильно на дні та на місяці, і на по́ри та ро́ки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Я боюся за вас, чи не да́рмо я працював коло вас?..');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Прошу́ я вас, браття, — будьте, як я, бо й я такий самий, як ви. Нічим ви мене не покри́вдили!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'І знаєте ви, що в не́мочі тіла я перше звіщав вам Єва́нгелію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'ви ж моєю спокусою в тілі моїм не пого́рдували, і мене не відкинули, але, немов а́нгола Божого, ви прийняли́ мене, як Христа Ісуса!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Тож де ваше тодішнє блаже́нство? Свідкую бо вам, що якби було можна, то ви вибрали б очі свої та мені віддали́ б!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Чи ж я став для вас ворогом, правду гово́рячи вам?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Недобре пильнують про вас, але вас відлучити хо́чуть, щоб ви пильнували про них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'То добре, — пильнувати про добре постійно, а не тільки тоді, як прихо́джу до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Ді́тки мої, — я зно́ву для вас терплю́ муки поро́ду, поки образ Христа не віді́б\'ється в вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Я хотів би тепер бути в вас та змінити свій голос, бо маю я су́мнів за вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Скажіть мені ви, що хочете бути під Зако́ном: чи не слухаєтесь ви Зако́ну?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Бо написано: „Мав Авраам двох синів, одно́го від рабині, а другого від вільної“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 23, 'Але той, хто був від рабині, народився за тілом, а хто був від вільної, — за обі́тницею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 24, 'Розуміти це треба інакше, бо це два заповіти: один від гори Сіна́й, що в ра́бство народжує, а він — то Аґа́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 25, 'Бо Аґа́р — то гора Сіна́й в Ара́бії, а відповідає сучасному Єрусалимові, який у ра́бстві з своїми дітьми́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 26, 'А ви́шній Єрусали́м — вільний, він мати всім нам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 27, 'Бо написано: „Звеселися, неплідна, ти, що не родиш! Гукай та викликуй ти, що в поро́ді не мучилась, бо в полишеної значно більше дітей, ніж у тієї, що має вона чоловіка!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 28, 'А ви, браття, діти обі́тниці за Ісаком!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 29, 'Але як і тоді, — хто родився за тілом, переслідував тих, хто родився за духом, так само й тепер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 30, 'Та що каже Писа́ння? „Прожени рабиню й сина її, бо не буде спадкува́ти син рабині ра́зом із сином вільної“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 31, 'Тому́, браття, не сини́ ми рабині, але вільної!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Христос для волі нас визволив. Тож стійте в ній та не піддавайтеся зно́ву в ярмо ра́бства!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Ось я, Павло, кажу вам, що коли ви обрізуєтесь, — то нема вам тоді жодної ко́ристи від Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'І свідкую я зно́ву всякому чоловікові, який обрізується, що повинен він ви́конати ввесь Зако́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Ви, що Зако́ном виправдуєтесь, — полишилися без Христа, відпали від благодаті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Бо ми в Дусі з віри чекаємо надії пра́ведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Бо сили не має в Христі Ісусі ані обрі́зання, ані необрі́зання, — але віра, що чинна любов\'ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Бігли ви добре. Хто заборонив вам кори́тися правді?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Таке переко́нання не від Того, Хто вас покликав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Трохи ро́зчини квасить усе тісто!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Я в Господі маю надію на вас, що нічого іншого ду́мати не будете ви. А хто вас непоко́їть, осуджений буде, хоч би він хто був!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Чого ж, браття, мене ще переслідують, коли я обрі́зання ще проповідую? Тоді споку́са хреста в ніщо оберта́ється!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'О, коли б були навіть відсі́чені ті, хто підбурює вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Бо ви, браття, на волю покликані, але щоб ваша воля не стала при́водом догоджати тілу, а любов\'ю служи́ти один о́дному!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Бо ввесь Зако́н в однім слові місти́ться: „Люби свого ближнього, як само́го себе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Коли ж ви гризете́ та їсте один о́дного, то глядіть, щоб не знищили ви один о́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'І кажу́: ходіть у Дусі, — і не вчи́ните пожадливости тіла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'бо тіло бажає противного Духові, а Дух противного тілу, і супротивні вони один о́дному, щоб ви чинили не те, чого хочете.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Коли ж Дух вас провадить, то ви не під Зако́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Учинки тіла явні, то є: пере́люб, нечистість, розпу́ста,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'ідолослу́ження, ча́ри, ворожнечі, сварка, заздрість, гнів, суперечки, незгоди, єресі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'за́видки, п\'я́нство, гу́лянки й подібне до цього. Я про це попере́джую вас, як і попереджа́в був, що хто чинить таке, не вспадку́ють вони Царства Божого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 22, 'А плід Духа: любов, радість, мир, довготерпіння, ла́гідність, до́брість, вірність,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 23, 'тихість, здержливість: — Зако́ну нема на таких!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 24, 'А ті, що Христові Ісусові, розп\'яли́ вони тіло з пожадли́востями та з по́хотями.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 25, 'Коли Духом живемо, то й Духом ході́мо!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 26, 'Не будьмо чванли́ві, не дражнімо один о́дного, не зави́дуймо один о́дному!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 1, 'Браття, як люди́на й упаде́ в якій про́гріх, то ви, духовні, виправляйте такого духом ла́гідности, сам себе доглядаючи, щоб не спокусився й ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 2, 'Носіть тягарі́ один о́дного, і так виконаєте зако́на Христового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 3, 'Коли бо хто ду́має, що він що́сь, бувши ніщо́, сам себе той обманює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 4, 'Нехай кожен досліджує ді́ло своє, і тоді матиме тільки в собі похвалу́, а не в іншому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 5, 'Бо кожен не́стиме свій власний тяга́р!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 6, 'А хто сло́ва навчається, нехай ділиться всяким добром із навчаючим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 7, 'Не обманюйтеся, — Бог осміяний бути не може. Бо що тільки люди́на посіє, те саме й пожне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 8, 'Бо хто сіє для власного тіла свого, той від тіла тління пожне. А хто сіє для Духа, той від Духа пожне життя вічне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 9, 'А роблячи добре, не зну́джуймося, бо ча́су свого пожнемо́, коли не ослабнемо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 10, 'Тож тому́, поки маємо час, усім робімо добро, а найбільш одновірним!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 11, 'Погляньте, якими великими буквами я написав вам своєю рукою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 12, 'Усі ті, хто бажає хвалитися тілом, змушують вас обрізуватись, щоб тільки вони не були переслідувані за хреста Христового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 13, 'Бо навіть і ті, хто обрізується, самі не зберігають Зако́на, а хочуть, щоб ви обрізувались, щоб хвалитися їм вашим тілом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 14, 'А щодо мене, то нехай нічим не хвалюся, хіба тільки хрестом Господа нашого Ісуса Христа, що ним розп\'я́тий світ для мене, а я для світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 15, 'Бо сили немає ані обрі́зання, ані необрізання, а створі́ння нове́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 16, 'А всі ті, хто пі́де за цим пра́вилом, — мир та милість на них, і на Ізраїля Божого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 17, 'Зре́штою, хай ніхто не турбує мене, бо ношу́ я Ісусові рани на тілі своїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 18, 'Благодать Господа нашого Ісуса Христа нехай буде з духом вашим, браття! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Павло, з волі Божої апо́стол Христа Ісуса, святим, що в Ефе́сі, і вірним у Христі Ісусі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'нехай буде вам благода́ть та мир від Бога, Отця нашого, і Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Благословенний Бог і Отець Господа нашого Ісуса Христа, що нас у Христі поблагословив усяким благослове́нням духовним у небесах,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'так як вибрав у Ньому Він нас перше зало́ження світу, щоб були перед Ним ми святі й непорочні, у любові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'призна́чивши напере́д, щоб нас усинови́ти для Себе Ісусом Христом, за вподо́банням волі Своєї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'на хвалу́ слави благода́ті Своєї, якою Він обдарував нас в Улю́бленім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'що маємо в Ньому відку́плення кров\'ю Його, про́щення провин, через багатство благода́ті Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'яку Він намно́жив у нас у всякій премудрості й розва́жності,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'об\'явивши нам таємни́цю волі Своєї за Своїм уподо́банням, яке постановив у Самому Собі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'для уря́дження ви́повнення часів, щоб усе об\'єднати в Христі, — що на небі, і що́ на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'У Нім, що в Нім стали ми й спадкоє́мцями, бувши призначені наперед постановою Того, Хто все чинить за радою волі Своєї,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'щоб на хвалу́ Його слави були ми, що перше надіялися на Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'У Ньому й ви, як почули були слово правди, Єва́нгелію спасі́ння свого, та в Нього й увірували, запечатані стали Святим Духом обі́тниці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'Який є завда́ток нашого спа́дку, на викуп здобутого, на хвалу́ Його слави!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'Тому й я, прочувши про вашу віру в Господа Ісуса, і про любов до всіх святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'не перестаю за вас дя́кувати, і в моли́твах своїх за вас згадую,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 17, 'щоб Бог Господа нашого Ісуса Христа, Отець слави, дав вам Духа премудрости та об\'явлення для пізна́ння Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 18, 'просвітив очі вашого серця, щоб ви зрозуміли, до якої надії Він вас закликає, і який багатий Його славний спа́док у святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 19, 'і яка безмірна ве́лич Його сили в нас, що віруємо за ви́явленням поту́жної сили Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 20, 'яку виявив Він у Христі, воскресивши із мертвих Його, і посадивши на небі право́руч Себе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 21, 'вище від усякого уря́ду, і вла́ди, і сили, і панува́ння, і всякого йме́ння, що на́зване не тільки в цім віці, але й у майбу́тньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 22, 'І все впокорив Він під ноги Йому́, і Його дав найвище за все — за Голову Церкви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 23, 'а вона — Його тіло, по́вня Того, що все всім наповня́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'І вас, що мертві були через ваші провини й гріхи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'в яких ви колись проживали за звича́єм віку цього́, за волею князя, що панує в повітрі, духа, що працює тепер у неслухня́них,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'між якими й усі ми проживали колись у пожадливостях нашого тіла, як чинили волю тіла й думо́к, і з природи були дітьми́ гніву, як і інші, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'Бог же, багатий на милосердя, через Свою превелику любов, що нею Він нас полюбив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'і нас, що мертві були через прогріхи, оживив ра́зом із Христом, — спасені ви благода́ттю, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'і ра́зом із Ним воскресив, і ра́зом із Ним посадив на небесних місцях у Христі Ісусі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'щоб у наступних віках показати безмірне багатство благода́ті Своєї в до́брості до нас у Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'Бо спасені ви благода́ттю через віру, а це не від вас, то дар Божий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'не від діл, щоб ніхто не хвалився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'Бо ми — Його тво́риво, ство́рені в Христі Ісусі на добрі діла, які Бог наперед приготува́в, щоб ми в них перебува́ли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Отож, пам\'ятайте, що ви, колись тілом погани, що вас так звані рукотворно „обрізані“на тілі звуть „необрізаними“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'що ви того ча́су були́ без Христа, відлучені від громади ізра́їльської, і чужі заповітам обі́тниці, не мавши надії й без Бога на світі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'А тепер у Христі Ісусі ви, що колись далекі були́, стали близькі́ Христовою кров\'ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Він бо наш мир, що вчинив із двох одне й зруйнував середи́нну перегороду, ворожнечу, Своїм тілом, -');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'Він Своєю наукою знищив Зако́на заповідей, щоб з обох збудувати Собою одно́го ново́го чоловіка, мир чинивши,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'і хрестом примирити із Богом обох в однім тілі, ворожнечу на ньому забивши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 17, 'І, прийшовши, „Він благовісти́в мир вам, далеким, і мир близьки́м“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 18, 'бо обоє Ним маємо при́ступ у Дусі однім до Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 19, 'Отже, ви вже не чужі й не прихо́дьки, а співгорожа́ни святим, і домашні для Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 20, 'збудовані на основі апо́столів і пророків, де наріжним каменем є Сам Ісус Христос,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 21, 'що на ньому вся буді́вля, улад побудована, росте в святий храм у Господі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 22, 'що на ньому і ви ра́зом будуєтеся Духом на оселю Божу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Через це я, Павло, є в\'я́зень Ісуса Христа за вас, поган, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'якщо ви тільки чули про заря́дження Божої благодаті, що для вас мені да́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Бо мені об\'я́вленням дано пізнати таємницю, як писав я вам коротко вище,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'з чого можете ви, читаючи, пізнати моє розумі́ння таємни́ці Христової.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'А вона за інших поколінь не була оголошена лю́дським сина́м, як об\'явилась тепер через Духа Його святим апо́столам і пророкам, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'що погани співспадкоємці, і одне тіло, і співучасники Його обі́тниці в Христі́ Ісусі через Єва́нгелію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'якій служи́телем я став через дар благода́ті Божої, що дана мені чином сили Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Мені, найменшому від усіх святих, да́на була оця благода́ть, — благовісти́ти поганам недосліджене багатство Христове,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'та ви́світлити, що́ то є заря́дження таємни́ці, яка від віків захована в Бозі, Який створив усе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'щоб тепер через Церкву була оголошена початкам та владам на небі найрізніша мудрість Божа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'за відвічної постанови, яку Він учинив у Христі Ісусі, Господі нашім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'в Якім маємо відвагу та доступ у надії через віру в Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'Тому́ то благаю я вас не занепада́ти духом через терпіння моє через вас, бо воно — ваша слава.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Для того схиляю коліна свої перед Отцем,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'що від Нього має йме́ння кожен рід на небі й на землі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'щоб Він дав вам за багатством слави Своєї силою зміцни́тися через Духа Його в чоловікові вну́трішнім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'щоб Христос через віру заме́шкав у ваших серця́х, щоб ви, закорі́нені й основані в любові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, 'змогли зрозуміти зо всіма́ святими, що́ то ширина́ й довжина́, і глибина́ й вишина́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 19, 'і пізнати Христову любов, яка перевищує знання́, щоб були ви напо́внені всякою повното́ю Божою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 20, 'А Тому́, Хто може зробити значно більш над усе, чого просимо або ду́маємо, силою, що діє в нас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 21, 'Тому слава в Церкві та в Христі Ісусі на всі покоління на вічні віки. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 1, 'Отож, благаю вас я, в\'я́зень у Господі, щоб ви пово́дилися гі́дно покли́кання, що до нього покликано вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 2, 'зо всякою покорою та ла́гідністю, з довготерпінням, у любові те́рплячи один о́дного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 3, 'пильнуючи зберігати єдність Духа в союзі спокою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 4, 'Одне тіло, один Дух, як і були ви покликані в одній надії вашого покли́кання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 5, 'Один Госпо́дь, одна віра, одне хрищення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 6, 'один Бог і Отець усіх, що Він над усіма́, і через усіх, і в усіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 7, 'А кожному з нас да́на благода́ть у міру дару Христового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 8, 'Тому́ й сказано: „Піднявшися на висоту́, Ти полоне́них набрав і лю́дям дав да́ри!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 9, 'А те, що „піднявся був“, що́ то, як не те, що перше й зійшов був до найнижчих місць землі?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 10, 'Хто зійшов був, Той саме й піднявся ви́соко над усі небеса́, щоб напо́внити все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 11, 'І Він, отож, настанови́в одних за апо́столів, одних за пророків, а тих за благові́сників, а тих за па́стирів та вчителі́в,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 12, 'щоб приготува́ти святих на ді́ло служби для збудува́ння тіла Христового,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 13, 'аж поки ми всі не дося́гнемо з\'єднання віри й пізна́ння Сина Божого, Мужа досконалого, у міру зросту Христової повноти́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 14, 'щоб більш не були́ ми малолі́тками, що хитаються й захоплюються від усякого вітру науки за лю́дською ома́ною та за лукавством до хитрого блу́ду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 15, 'щоб були ми правдомовні в любові, і в усьому зростали в Нього, а Він — Голова, Христос.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 16, 'А з Нього все тіло, скла́дене й зв\'язане всяким допомічни́м сугло́бом, у міру чинности кожного окремого члена, чи́нить зріст тіла на будува́ння самого себе любов\'ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 17, 'Отже, говорю я це й свідку́ю в Господі, щоб ви більш не пово́дилися, як пово́дяться погани в марно́ті свого розуму, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 18, 'вони запа́морочені розумом, відчу́жені від життя Божого за не́уцтво, що в них, за стверділість їхніх серде́ць,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 19, 'вони отупіли й віддали́ся розпусті, щоб чинити всяку не́чисть із заже́рливістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 20, 'Але ви не так пізнали Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 21, 'якщо ви чули про Нього, і навчилися в Нім, бо правда в Ісусі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 22, 'щоб відкинути, за першим поступо́ванням, старо́го чоловіка, який зотліває в звабли́вих пожадливостях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 23, 'та відновлятися духом вашого розуму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 24, 'і зодягнутися в ново́го чоловіка, ство́реного за Богом у праведності й святості правди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 25, 'Тому́ то, неправду відкинувши, говоріть кожен правду до свого ближнього, бо ми члени один для о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 26, 'Гнівайтеся, та не грішіть, — сонце нехай не заходить у вашому гніві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 27, 'і місця дия́волові не давайте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 28, 'Хто крав, нехай більше не кра́де, а краще нехай працює та чинить руками своїми добро, щоб мати подати нужде́нному.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 29, 'Нехай жодне слово гниле не виходить із уст ваших, але тільки таке, що добре на потрібне збудува́ння, щоб воно подало́ благода́ть тим, хто чує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 30, 'І не засму́чуйте Духа Святого Божого, Яким ви запечатані на день ви́купу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 31, 'Усяке подратува́ння, і гнів, і лютість, і крик, і лайка нехай буде взято від вас ра́зом із уся́кою злобо́ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 32, 'А ви один до о́дного будьте ласка́ві, милости́ві, прощаючи один о́дному, як і Бог через Христа вам простив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 1, 'Отже, будьте наслідувачами Богові, як улю́блені діти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 2, 'і поводьтеся в любові, як і Христос полюбив вас, і видав за нас Само́го Себе, як дар і жертву Богові на приємні па́хощі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 3, 'А розпуста та не́чисть усяка й заже́рливість нехай навіть не згадуються поміж вами, як ли́чить святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 4, 'і гидо́та, і марносло́вство або жарти, що непристойні вам, але краще дя́кування.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 5, 'Знайте бо це, що жоден розпу́сник, чи нечистий, або заже́рливий, що він ідоля́нин, не має спа́дку в Христовому й Божому Царстві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 6, 'Нехай вас не зво́дить ніхто словами марно́тними, бо гнів Божий приходить за них на неслухня́них, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 7, 'тож не будьте їм спільниками!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 8, 'Ви бо були колись те́мрявою, тепер же ви світло в Господі, — поводьтеся, як діти світла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 9, 'бо плід світла знахо́диться в кожній добрості́, і праведності, і правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 10, 'Допевня́йтеся, що приємне для Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 11, 'і не беріть участи в неплідних ділах те́мряви, а краще й докоряйте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 12, 'Бо соромно навіть казати про те, що роблять вони потає́мно!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 13, 'Усе ж те, що світлом докоряється, стає явне, бо все, що явне стає, то світло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 14, 'Через це то й говорить: „Сплячий, вставай, і воскре́сни із мертвих, — і Христос осві́тлить тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 15, 'Отож, уважайте, щоб поводитися обере́жно, не як немудрі, але як мудрі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 16, 'використо́вуючи час, — дні бо лукаві!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 17, 'Через це не будьте нерозумні, але розумійте, що́ є воля Господня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 18, 'І не впивайтесь вином, в якому розпуста, але краще напо́внюйтесь Духом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 19, 'розмовляючи поміж собою псалма́ми, і гі́мнами, і пісня́ми духовними, співаючи й граючи в серці своєму для Господа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 20, 'дякуючи за́вжди за все Богові й Отцеві в Ім\'я́ Господа нашого Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 21, 'ко́рячися один о́дному у Христовім страху́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 22, 'Дружи́ни, — корі́ться своїм чоловікам, як Господе́ві, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 23, 'бо чоловік — голова дружи́ни, як і Христос — Голова Церкви, Сам Спаситель тіла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 24, 'І як ко́риться Церква Христові, так і дружи́ни своїм чоловікам у всьо́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 25, 'Чоловіки, — любіть своїх дружи́н, як і Христос полюбив Церкву, і віддав за неї Себе,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 26, 'щоб її освятити, очистивши водяним ку́пелем у слові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 27, 'щоб поставити її Собі славною Церквою, що не має плями чи вади, чи чогось такого, але щоб була́ свята й непорочна!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 28, 'Чоловіки повинні любити дружи́н своїх так, як власні тіла, бо хто любить дружи́ну свою, той любить самого себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 29, 'Бо ніко́ли ніхто не знена́видів власного тіла, а годує та гріє його, як і Христос Церкву,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 30, 'бо ми — члени Тіла Його від тіла Його й від косте́й Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 31, '„Покине тому́ чоловік батька й матір, і пристане до дружи́ни своєї, — і бу́дуть обоє вони одним тілом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 32, 'Ця таємниця велика, — а я говорю́ про Христа та про Церкву!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 33, 'Отже, нехай кожен зокре́ма із вас любить так свою дружи́ну, як самого себе, а дружи́на нехай боїться свого чоловіка!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 1, 'Діти, — слухайтеся своїх батьків у Господі, бо це справедливе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 2, '„Шануй свого батька та матір“— це перша заповідь з обі́тницею, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 3, '„щоб добре вело́ся тобі, і щоб ти був на землі довголітній!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 4, 'А батьки, — не дратуйте дітей своїх, а виховуйте їх в напомина́нні й остере́женні Божому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 5, 'Раби, — слухайтеся тілесних панів зо стра́хом і тремті́нням у простоті́ серця вашого, як Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 6, 'Не працюйте тільки про лю́дське око, немов чоловіковго́дники, а як раби Христові, чиніть від душі волю Божу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 7, 'служіть із зичли́вістю, немов Господе́ві, а не лю́дям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 8, 'Знайте, що кожен, коли зробить що добре, те саме оде́ржить від Господа, чи то раб, чи то вільний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 9, 'А пани, — чиніть їм те са́ме, занеха́юйте погро́зи, знайте, що для вас і для них є на небі Госпо́дь, а Він на обличчя не дивиться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 10, 'Наре́шті, мої брати, зміцняйтеся Господом та могу́тністю сили Його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 11, 'Зодягніться в повну Божу зброю, щоб могли ви стати проти хи́трощів диявольських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 12, 'Бо ми не маємо боротьби проти крови та тіла, але проти початків, проти вла́ди, проти світоправителів цієї те́мряви, проти піднебесних ду́хів зло́би.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 13, 'Через це візьміть повну Божу збро́ю, щоб могли ви дати о́пір дня злого, і, все виконавши, витримати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 14, 'Отже, стійте, підперезавши сте́гна свої правдою, і зодягнувшись у броню́ праведности,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 15, 'і взувши ноги в готовість Єва́нгелії миру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 16, 'А найбільш над усе візьміть щита́ віри, яким зможете погасити всі огне́нні стрі́ли лукавого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 17, 'Візьміть і шоло́ма спасіння, і меча духовного, який є Слово Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 18, 'Усякою молитвою й благанням кожного ча́су моліться у Дусі, а для того пильнуйте з повною витрива́лістю та молитвою за всіх святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 19, 'і за мене, щоб да́не було́ мені слово відкрити уста́ свої, і зо сміливістю провіщати таємницю Єва́нгелії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 20, 'для якої посо́л я в кайда́нах, щоб сміли́во про неї звіщати, як належить мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 21, 'А щоб знали і ви щось про мене, та що́ я роблю́, то все вам розпові́сть Тихи́к, улю́блений брат і в Господі вірний служи́тель,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 22, 'якого послав я до вас на це са́ме, щоб довідалися ви про нас, і щоб ваші серця він поті́шив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 23, 'Мир брата́м і любов із вірою від Бога Отця й Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 24, 'Благода́ть зо всіма́, що незмінно люблять Господа нашого Ісуса Христа! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Павло й Тимофі́й, раби Христа Ісуса, до всіх святих у Христі Ісусі, що знаходяться в Фили́пах, з єпи́скопами та диякона́ми:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'благода́ть вам і мир від Бога, Отця нашого, і Господа Ісуса Христа́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Дякую Богові своєму при кожній згадці про вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'і за́вжди в усякій молитві своїй за всіх вас чиню́ я молитву з ра́дощами, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'за участь вашу в Єва́нгелії від першого дня аж дотепе́р.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Я певний того, що той, хто в вас розпочав добре ді́ло, виконає його аж до дня Христа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Бо то справедливо мені ду́мати це про всіх вас, бо я маю вас у серці, а ви всі в кайда́нах моїх, і в обороні, і в утве́рдженні Єва́нгелії — спільники мої в благодаті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Бо Бог мені свідок, що тужу́ я за вами всіма́ в сердечній любові Христа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'І молюсь я про те, щоб ваша любов примножа́лась ще більше та більше в пізна́нні й усякім дослі́дженні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'щоб ви досліджували те, що краще, щоб чисті та ці́лі були Христового дня,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'напо́внені плодів праведности через Ісуса Христа, на славу та на хвалу Божу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Бажаю ж я, браття, щоб ві́дали ви, що те, що сталось мені, вийшло більше на успіх Єва́нгелії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'бо в усій прето́рії та всім іншим стали відо́мі кайда́ни мої за Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'А багато братів у Господі через кайда́ни мої посміліли та ще більше відва́жилися Слово Боже звіщати безстрашно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Одні, правда, і через за́здрощі та колотне́чу, другі ж із доброї волі Христа проповідують;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'а інші з любови, зна́ючи, що я поставлений на оборону Єва́нгелії;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'а інші через пі́дступ звіщають Христа нещиро, ду́маючи, що додаду́ть тягару́ до кайда́нів моїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Але що ж? У всякому разі, чи облудно, чи щиро, Христос проповідується, а тим я радію та й бу́ду радіти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Бо знаю, що це бу́де мені на спасі́ння через вашу молитву й допомогу Духа Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'через чека́ння й надію мою, що я ні в чо́му не бу́ду посоро́млений, але ці́лою сміли́вістю, як за́вжди, так і тепер Христос буде звели́чений у тілі моїм, чи то життям, чи то смертю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Бо для мене життя — то Христос, а смерть — то надба́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'А коли життя в тілі — то для мене плід ді́ла, то не знаю, що́ вибрати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Тягнуть мене одне й друге, хоч маю я бажа́ння померти та бути з Христом, бо це значно ліпше.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'А щоб полишатися в тілі, то це потрібніш ради вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 25, 'І оце знаю певно, що зали́шусь я, і пробува́тиму з вами всіма́ вам на ко́ристь та на ра́дощі в вірі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 26, 'щоб ваша хвала́ через мене примно́жилася в Христі Ісусі, коли зно́ву прийду́ я до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 27, 'Тільки живіть згідно з Христовою Єва́нгелією, щоб, — чи прийду́ я й побачу вас, чи й не бувши — почув я про вас, що ви стоїте́ в однім дусі, бо́рючись однодушно за віру єва́нгельську,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 28, 'і ні в чо́му не боячи́ся противників; це їм доказ загибелі, вам же спасі́ння. А це від Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 29, 'Бо вчинено вам за Христа доброді́йство, — не тільки вірувати в Нього, але і страждати за Нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 30, 'маючи таку саму боротьбу́, яку ви бачили в мені, а тепер чуєте про мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, 'Отож, коли є в Христі яка заохо́та, коли є яка потіха любови, коли є яка спільно́та духа, коли є яке серце та милосердя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'то допо́вніть радість мою: щоб ду́мали ви одне й те, щоб мали ту саму любов, одну згоду й один розум!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'Не робіть нічого пі́дступом або з чванли́вости, але в покорі майте один о́дного за більшого від себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'Нехай кожен дбає не про своє, але кожен і про інших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'Нехай у вас будуть ті самі думки́, що й у Христі Ісусі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, 'Він, бувши в Божій подо́бі, не вважав за захва́т бути Богові рівним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'але Він ума́лив Самого Себе, прийнявши вигляд раба, ставши подібним до люди́ни; і подобою ставши, як люди́на,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'Він упоко́рив Себе, бувши слухня́ний аж до смерти, і то смерти хресної.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'Тому й Бог повищив Його, та дав Йому Ім\'я́, що вище над кожне ім\'я́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'щоб перед Ісусовим Ім\'я́м вклонялося кожне коліно небесних, і зе́мних, і підзе́мних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'і щоб кожен язик визнавав: Ісус Христос — то Госпо́дь, на славу Бога Отця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'Отож, мої лю́бі, як ви за́вжди слухня́ні були не тільки в моїй присутності, але значно більше тепер, у моїй відсутності, зо стра́хом і тремті́нням виконуйте своє спасі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'Бо то Бог викликає в вас і хоті́ння, і чин за доброю волею Своєю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, 'Робіть усе без наріка́ння та сумніву,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'щоб були ви бездоганні та щирі, „невинні діти Божі серед лукавого та розпусного роду“, що в ньому ви сяєте, як світла в світі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 16, 'додержуючи слово життя на похвалу́ мені в день Христа, що я біг не нада́рмо, що я працював не нада́рмо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 17, 'Та хоч і стаю я жертвою при жертві і при службі вашої віри, я радію та тішуся ра́зом із вами всіма́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 18, 'Тіштесь тим самим і ви, і тіштеся ра́зом зо мною!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 19, 'Надіюся в Господі Ісусі незаба́ром послати до вас Тимофія, щоб і я зміцнів духом, розізнавши про вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 20, 'Бо я одноду́мця не маю ні о́дного, щоб щиріше подбав він про вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 21, 'Усі бо шукають свого́, а не Христового Ісусового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 22, 'Та ви знаєте до́свід його, бо він, немов ба́тькові син, зо мною служив для Єва́нгелії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 23, 'Отже, маю надію негайно послати цього́, як тільки довідаюся, що бу́де зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 24, 'Але в Господі маю надію, що й сам незаба́ром прибу́ду до вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 25, 'Але я вважав за потрібне послати до вас брата Епафроди́та, свого співробітника та співбойовника́, вашого апо́стола й служи́теля в потребі моїй,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 26, 'бо він побивався за вами всіма́, і сумував через те, що ви чули, що він хворува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 27, 'Бо смертельно він був хворував. Але змилувався Бог над ним, і не тільки над ним, але й надо мною, щоб я смутку на смуток не мав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 28, 'Отож, тим швидше послав я його, щоб тішились ви, його зно́ву побачивши, і щоб без смутку я був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 29, 'Тож прийміть його в Господі з повною радістю, і майте в пошані таких,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 30, 'бо за діло Христове набли́зився був аж до смерти, наражаючи на небезпеку життя, щоб допо́внити ваш неста́ток служі́ння для мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, 'Зрештою, браття мої, радійте у Господі! Писати вам те саме не прикро мені, а для вас це навча́льне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'Стережіться собак, — стережіться працівникі́в лихих, стережіться обрі́зання!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'Бо обрі́зання — то ми, що слу́жимо Богові духом, а хвалимося Христом Ісусом, і не кладемо надії на тіло,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'хоч і я міг би мати надію на тіло. Як хто інший на тіло надіятись ду́має, то тим більше я, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, 'обрізаний восьмого дня, з роду Ізраїля, з племени Веніяминового, єврей із євреїв, фарисей за Законом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'Через горли́вість я був переслідував Церкву, бувши невинний, щодо праведности в Законі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Але те, що́ для мене було́ за надба́ння, те ради Христа я за втрату вважав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'Тож усе я вважаю за втрату ради переважного позна́ння Христа Ісуса, мого Господа, що я ради Нього відмовився всьо́го, і вважаю все за сміття́, щоб придбати Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, 'щоб знайтися в Нім не з власною праведністю, яка від Зако́ну, але з тією, що з віри в Христа, праведністю від Бога за вірою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, 'щоб пізнати Його й силу Його воскресіння, та участь у му́ках Його, уподо́блюючись Його смерті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'аби досягнути я́кось воскресіння з мертвих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Не тому́, що я вже досягнув, або вже вдоскона́лився, але пра́гну, чи не досягну́ я того, чим і Христос Ісус досягнув був мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'Браття, я себе не вважаю, що я досягну́в. Та тільки, забуваючи те, що поза́ду, і спішачи́ до того, що попе́реду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'я женусь до мети за нагородою високого по́клику Божого в Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'Тож усі, хто досконалий, ду́маймо це; коли ж ду́маєте ви щось інше, то Бог вам відкриє й це.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, 'Та до чо́го дійшли ми, поступаймо в тім самім далі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 17, 'Будьте до мене подібні, браття, і дивіться на тих, хто пово́диться так, як маєте ви за взір нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 18, 'Багато бо хто, що про них я вам часто казав, а тепер говорю́ навіть пла́чучи, пово́дяться, як вороги хреста Христового.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 19, 'Їхній кінець — то загибіль, шлу́нок — їхній бог, а слава — в їхньому соромі... Вони ду́мають тільки про зе́мне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 20, 'Життя ж наше на небі, звідки ждемо́ й Спаси́теля, Господа Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 21, 'Який перемінить тіло нашого пони́ження, щоб стало подібне до славного тіла Його, силою, якою Він може і все підкорити Собі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, 'Отож, мої браття улю́блені, за якими так сильно тужу́, моя радосте й ві́нче, — так у Господі стійте, улю́блені!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'Благаю Ево́дію, благаю й Синти́хію — ду́мати однаково в Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Так, благаю й тебе, това́ришу вірний, допомагай тим, хто в боротьбі за Єва́нгелію помагали мені та Кли́ментові й іншим моїм співробі́тникам, яких іме́ння записані в Книзі Життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'Радійте в Господі за́всіди, і зно́ву кажу́: раді́йте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'Ваша ла́гідність хай буде відо́ма всім лю́дям. Господь близько!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, 'Ні про що не турбуйтесь, а в усьо́му нехай виявля́ються Богові ваші бажа́ння молитвою й проха́нням з подякою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'І мир Божий, що вищий від усякого розуму, хай береже серця ваші та ваші думки́ у Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, 'Наоста́нку, браття, що́ тільки правдиве, що́ тільки чесне, що тільки праведне, що́ тільки чисте, що тільки любе, що́ тільки гі́дне хвали́, коли яка чесно́та, коли яка похвала́, — ду́майте про це!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'Чого ви від мене й навчилися, і прийняли́, і чули та бачили, — робіть те! І Бог миру буде з вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'Я ве́льми потішився в Господі, що справді ви вже нови́х сил набули́ піклува́тись про мене; ви й давніш піклува́лись, та ча́су сприя́тливого ви не мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Не за нестатком кажу́, бо навчився я бути задово́леним із то́го, що маю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'Умію я й бути в упоко́ренні, умію бути й у достатку. Я привчився до всьо́го й у всім: насища́тися й голод терпіти, мати достаток і бути в недостачі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'Я все мо́жу в Тім, Хто мене підкріпляє, — в Ісусі Христі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, 'Тож ви добре зробили, що участь узяли́ в моїм горі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'І знаєте й ви, филип\'я́ни, що на поча́тку благові́стя, коли я з Македонії вийшов, не прилучилась була́ жо́дна Церква до справи дава́ння й прийма́ння для мене, самі тільки ви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'що і раз, і вдруге мені на потреби мої посилали й до Солу́ня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 17, 'Кажу́ це не тому́, щоб шукав я дава́ння, — я шукаю плоду, що примно́жується на річ вашу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 18, 'Та все я одержав, і маю достаток. Маю повно, прийнявши від Епафроди́та, що́ ви послали, як па́хощі запашні́, жертву приємну, Богові вгодну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 19, 'А мій Бог нехай ви́повнить вашу всяку потребу за Своїм багатством у Славі, у Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 20, 'А Богові й нашому Отцеві слава на віки віків. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 21, 'Вітайте кожного святого у Христі Ісусі. Вітають вас браття, присутні зо мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 22, 'Вітають вас усі святі, а найбільше ті, хто з ке́саревого дому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 23, 'Благода́ть Господа Ісуса Христа зо всіма́ вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Павло, із волі Божої апо́стол Христа Ісуса, і брат Тимофі́й');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'до святих і вірних братів у Христі, що в Коло́сах: благода́ть вам і мир від Бога, Отця нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Ми дякуємо Богові, Отцеві Господа нашого Ісуса Христа, за́вжди за вас мо́лячись,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'прочувши про вашу віру в Христа Ісуса та про любов, яку маєте до всіх святих');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'через надію, пригото́вану в небі для вас, що про неї давніше ви чули в слові правди Єва́нгелії,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'що до вас прибула́, і на ці́лому світі плодоно́сна й росте, як і в вас, з того дня, коли ви почули й пізнали благодать Божу в правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Отак ви і навчилися від Епа́фра, улю́бленого співробі́тника нашого, що за вас він вірний служитель Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'що й виявив нам про вашу духовну любов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Через це то й ми з того дня, як почули, не перестаємо молитись за вас та просити, щоб для пізна́ння волі Його були́ ви напо́внені всякою мудрістю й розумом духовним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'щоб ви пово́дилися нале́жно щодо Господа в усякому дого́дженні, в усякому доброму ді́лі прино́сячи плід і зростаючи в пізна́нні Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'зміцняючись усякою силою за могутністю слави Його для всякої витрива́лости й довготерпі́ння з радістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'дя́куючи Отцеві, що вчинив нас достойними участи в спа́дщині святих у світлі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'що визволив нас із вла́ди те́мряви й переставив нас до Царства Свого улю́бленого Сина,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'в Якім маємо відку́плення і про́щення гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Він є образ невиди́мого Бога, ро́джений перш усякого тво́рива.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Бо то Ним ство́рено все на небі й на землі, види́ме й невиди́ме, чи то престоли, чи то госпо́дства, чи то влади, чи то начальства, — усе через Нього й для Нього створено!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'А Він є перший від усього, і все в Нім стоїть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'І Він — Голова тіла, Церкви. Він початок, перворо́джений з мертвих, щоб у всьому Він мав пе́ршенство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Бо вгодно було́, щоб у Нім перебува́ла вся повнота́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'і щоб Ним поєднати з Собою все, примиривши кров\'ю хреста Його, через Нього, чи то зе́мне, чи то небесне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'І вас, що були́ колись відчужені й вороги думкою в злих учинках,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'тепер же примирив смертю в лю́дськім тілі Його, щоб учинити вас святими, і непорочними, і неповинними перед Собою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'якщо тільки пробува́єте в вірі тверді́ та ста́лі, і не відпадаєте від надії Єва́нгелії, що ви чули її, яка проповідана всьому створі́нню під небом, якій я, Павло, став служи́телем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Тепер я радію в стражда́ннях своїх за вас, і доповнюю недостачу скорбо́ти Христової і тілі своїм за тіло Його, що воно — Церква;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'якій я став служи́телем за Божим заря́дженням, що для вас мені дане, щоб виконати Слово Боже, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 26, 'Таємницю, захо́вану від віків і поколінь, а тепер виявлену Його святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 27, 'що їм Бог захотів показати, яке багатство слави цієї таємниці між поганами, а вона — Христос у вас, надія слави!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 28, 'Його ми проповідуємо, нагадуючи кожній люди́ні й навчаючи кожну люди́ну всякої мудрости, щоб учинити кожну люди́ну досконалою в Христі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 29, 'У то́му й працюю я, борючи́ся силою Його, яка сильно діє в мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Я хо́чу, щоб ви знали, яку велику боротьбу я маю за вас і за тих, хто в Лаодикі́ї, і за всіх, хто не бачив мого тіле́сного обличчя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Хай потішаться їхні серця́, у любові поє́днані, для всякого багатства повного розуміння, для пізна́ння таємниці Бога, Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'в Якому всі скарби премудрости й пізна́ння заховані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'А це говорю́, щоб ніхто вас не звів фальшивими доводами при суперечці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'Бо хоч тілом я й неприсутній, та духом я з вами, і з радістю бачу ваш порядок та твердість вашої віри в Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Отже, як ви прийняли́ були Христа Ісуса Господа, так і в Ньому ходіть,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'бувши вкорі́нені й збудо́вані на Ньому, та зміцнені в вірі, як вас на́вчено, збагачуючись у ній з подякою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'Стережіться, щоб ніхто вас не звів філосо́фією та марно́ю ома́ною за переда́нням лю́дським, за стихі́ями світу, а не за Христом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'бо в Ньому тілесно живе вся повнота́ Божества́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'І ви маєте в Нім повноту́, а Він — Голова всякої влади й начальства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Ви в Ньому були́ й обрізані нерукотво́рним обрі́занням, скинувши лю́дське тіло гріховне в Христовім обрі́занні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'Ви були з Ним поховані у хрищенні, у Ньому ви й ра́зом воскресли через віру в силу Бога, що Він з мертвих Його воскресив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'І вас, що мертві були́ в гріхах та в необрізанні вашого тіла, Він оживив ра́зом із Ним, простивши усі гріхи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'знищивши рукописа́ння на нас, що нака́зами було проти нас, — Він із сере́дини взяв його та й прибив його на хресті,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'роззброївши вла́ди й начальства, сміли́во їх вивів на посміхо́висько, — перемігши їх на хресті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'Тож, хай ніхто вас не судить за їжу, чи за питво́, чи за чергове свято, чи за новомі́сяччя, чи за суботи, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'бо це — тінь майбу́тнього, а тіло — Христове.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'Нехай вас не зводить ніхто уда́ваною покорою та службою ангола́м, вдаючися до того, чого не бачив, нерозважно надимаючись своїм тілесним розумом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 19, 'а не тримаючись Голови, від Якої все тіло, сугло́бами й зв\'я́зями з\'є́днане й змі́цнене, росте зростом Божим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 20, 'Отож, як ви вмерли з Христом для стихі́й світу, то чого ви, немов ті, хто в світі живе, пристаєте на постанови:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 21, 'не дотикайся, ані їж, ані рухай,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 22, 'бо то все зни́щиться, як уживати його, — за при́казами та наукою лю́дською.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 23, 'Воно ж має вид мудрости в самовільній службі й покорі та в знеси́люванні тіла, та не має якогось зна́чення, хіба щодо наси́чення тіла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Отож, коли ви воскре́сли з Христом, то шукайте того, що вгорі, де сидить Христос по Божій прави́ці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'Ду́майте про те, що вгорі, а не про те, що на землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Бож ви вмерли, а життя ваше сховане в Бозі з Христом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Коли з\'я́виться Христос, наше життя, тоді з\'явитеся з Ним у славі і ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Отож, умертвіть ваші земні члени: розпусту, не́чисть, при́страсть, лиху пожадли́вість та заже́рливість, що вона ідолослу́ження,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'бо гнів Божий приходить за них на неслухня́них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'І ви поміж ними ходили колись, як жили поміж ними.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'Тепер же відкиньте і ви все оте: гнів, лютість, злобу́, богозневагу, безсоромні слова́ з ваших уст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Не кажіть неправди один на о́дного, якщо скинули з себе люди́ну старода́вню з її вчинками,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'та зодягнулися в нову́, що відновлюється для пізна́ння за образом Створителя її,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'де нема ані ге́ллена, ані юдея, обрі́зання та необрі́зання, ва́рвара, ски́та, раба, вільного, — але все та в усьому Христос!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Отож, зодягніться, як Божі вибра́нці, святі та улю́блені, у щире милосердя, добротли́вість, покору, ла́гідність, довготерпіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Терпіть один о́дного, і прощайте собі, коли б мав хто на ко́го оска́рження. Як і Христос вам простив, робіть так і ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'А над усім тим — зодягніться в любов, що вона — союз доскона́лости!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'І нехай мир Божий панує у ваших серцях, до якого й були ви покликані в одно́му тілі. І вдячними будьте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Слово Христове нехай пробуває в вас рясно, у всякій премудрості. Навчайте та напоумля́йте самих себе! Вдячно співайте у ваших серцях Господе́ві псалми́, гі́мни, духовні пісні́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'І все, що тільки робите словом чи ділом, — усе робіть у Ім\'я́ Господа Ісуса, дякуючи через Нього Богові й Отцеві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Дружи́ни, — слухайтеся чоловіків своїх, як лицює то в Господі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'Чоловіки, — любіть дружи́н своїх, і не будьте суво́рі до них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 20, 'Діти, — будьте слухня́ні в усьому батька́м, бо це Господе́ві приємне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 21, 'Батьки́, — не драту́йте дітей своїх, щоб на дусі не впали вони!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 22, 'Раби, — слухайтеся в усьому тілесних панів, і не працюйте тільки про лю́дське око, немов підле́щуючись, але в простоті серця, боячи́ся Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 23, 'І все, що тільки чините, робіть від душі, немов Господе́ві, а не лю́дям!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 24, 'Знайте, що від Господа при́ймете в нагороду спа́дщину, бо служите ви Господе́ві Христові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 25, 'А хто кривдить, той одержить за свою кривду. Бо не дивиться Бог на осо́бу!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Пани, — виявляйте до рабів справедливість та рівність, і знайте, що й для вас є на небі Госпо́дь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'Будьте тривалі в молитві, і пильнуйте з подякою в ній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Моліться ра́зом і за нас, щоб Бог нам відчинив двері слова, — звіщати таємницю Христову, що за неї я й зв\'я́заний,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'щоб звістив я її, як звіщати належить мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'Пово́дьтеся мудро з чужими, використовуючи час.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Слово ваше нехай буде за́вжди ласка́ве, припра́влене сіллю, щоб ви знали, як ви маєте кожному відповідати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Що́ зо мною, то все вам розпові́сть Тихи́к, улю́блений брат, і вірний служи́тель і співробі́тник у Господі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Я саме на те його вислав до вас, щоб довідались ви про нас, і щоб ваші серця він поті́шив,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'із Они́симом, вірним та улю́бленим братом, який з-поміж вас. Вони все вам розповідя́ть, що́ діється тут.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'Поздоровлює вас Ариста́рх, ув\'я́знений ра́зом зо мною, і Ма́рко, небіж Варна́вин, — що про нього ви дістали нака́зи; як при́йде до вас, то прийміть його, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'теж Ісус, на прізвище Юст, — вони із обрі́заних. Для Божого Царства — єдині вони співробі́тники, що були́ мені втіхою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Поздоровлює вас Епафра́с, що з ваших, раб Христа Ісуса. Він за́вжди обстоює вас у молитвах, щоб ви досконалі були та напо́внені всякою Божою волею.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'І я сві́дчу за нього, що він має велику горли́вість про вас та про тих, що знахо́дяться в Лаодикі́ї та в Гієрапо́лі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Вітає вас Лука́, улю́блений лі́кар, та Дима́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Привітайте братів, що в Лаодикі́ї, і Німфа́на, і Церкву домашню його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'І як бу́де прочи́таний лист цей у вас, то зробіть, щоб прочитаний був він також у Церкві Лаодикі́йській, а того, що написаний з Лаодикі́ї, прочитайте і ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Та скажіть Архі́пові: „Доглядай того служі́ння, що прийняв його в Господі, щоб ти його ви́конав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'Привітання моєю рукою Павловою. Пам\'ятайте про пу́та мої! Благодать Божа нехай буде з вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Павло й Силуа́н та Тимофій до Церкви Солу́нської в Бозі Отці й Господі Ісусі Христі: благода́ть вам і мир!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Ми дякуємо Богові за́вжди за всіх вас, згадуючи вас у наших моли́твах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Ми згадуємо безпереста́нку про ваше ді́ло віри, і про працю любови, і про терпіння надії на Господа нашого Ісуса Христа, перед Богом і Отцем нашим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'зна́ючи, Богом улю́блені браття, про ваше обра́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Бо наша Єва́нгелія не була́ для вас тільки у слові, а й у силі, і в Дусі Святім, і з великим упе́вненням, як знаєте ви, які ми були́ поміж вами для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'І ви стали наслідувачі нам і Господе́ві, слово прийнявши в великому утискові з радістю Духа Святого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'так що ви стали взірце́м для всіх віруючих у Македонії та в Ахаї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Бо проне́слося Слово Господнє від вас не тільки в Македонії та в Ахаї, а й до кожного міста прийшла ваша віра в Бога, так що вам непотрібно казати чого́сь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Вони бо звіщають про нас, який був при́хід наш до вас, і як ви наверну́лись до Бога від і́долів, щоб служити живому й правдивому Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'і з неба очікувати Сина Його, що Його воскресив Він із мертвих, Ісуса, що визволює нас від майбу́тнього гніву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Самі бо ви знаєте, браття, прихід наш до вас, що не марни́й він був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Та хоч ми нате́рпілися перед тим, і дізнали зневаги в Фили́пах, як знаєте, проте ми відва́жилися в нашім Бозі звіщати вам Божу Єва́нгелію з великою боротьбою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Бо покли́кання наше було не з обмани, ані з нечи́стости, ані від лука́вства,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'але, як Бог визнав нас гідними, щоб нам доручити Єва́нгелію, ми говоримо так, не лю́дям дого́джуючи, але Богові, що випробо́вує наші серця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Ми сло́ва підле́сливого не вживали ніко́ли, як знаєте, і не винні в заже́рливості. Бог свідок тому́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Не шукаємо ми слави в людей, ані в вас, ані в інших.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Хоч могли ми поту́жними бути, як Христові апо́столи, але ми серед вас були тихі, немов годува́льниця та, яка доглядає дітей своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Так бувши ласка́ві до вас, хотіли ми вам передати не тільки Божу Єва́нгелію, але й ду́ші свої, бо були́ ви улю́блені нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Бо ви пам\'ятаєте, браття, наше стру́днення й уто́му: день і ніч ми робили, щоб жодного з вас не обтя́жити, і проповідували вам Божу Єва́нгелію.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ви свідки та Бог, як свято, і праведно, і бездога́нно пово́дилися ми між вами, віруючими!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Бож знаєте ви, як кожного з вас, немов ба́тько дітей своїх власних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'просили ми вас, і намо́влювали та показували, щоб ви гідно пово́дилися перед Богом, що покликав вас у Своє Царство та в славу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Тому́ то й ми дякуємо Богові безпереста́нку, що, прийнявши почуте від нас Сло́во Боже, прийняли́ ви не як слово лю́дське, але — як правдиво то є — Слово Боже, що й діє в вас, віруючих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Бо стали ви, бра́ття, наслідувачами Церквам Божим, що в Юдеї в Христі Ісусі, бо те саме і ви були ви́терпіли від своїх землякі́в, як і ті від юдеїв,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'що вбили вони й Господа Ісуса, і пророків Його, і вигнали нас, і Богові не догоджа́ють, і супротивні всім лю́дям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Вони забороняють нам говорити поганам, щоб спаслися, щоб тим доповня́ти їм за́вжди провини свої. Але Божий гнів їх спіткає вкінці!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'А ми, браття, на короткий часо́к розлучившися з вами лицем, а не серцем, тим із більшим бажа́нням силкува́лись побачити ваше лице.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Тим то до вас ми хотіли прийти, я, Павло, раз і двічі, але сатана́ перешкодив був нам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Бо хто нам надія, чи радість, чи вінок похвали́? Хіба ж то й не ви перед Господом нашим Ісусом в Його прихо́ді?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Бо ви наша слава та радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Тому́ то, не сте́рпівши більше, ми схотіли зостатися в Ате́нах самі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'і послали Тимофі́я, нашого брата й служи́теля Божого в Христовій Єва́нгелії, щоб упе́внити вас та потішити в вашій вірі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'щоб ані один не хитався в цім горі. Самі бо ви знаєте, що на те нас призначено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Бо коли ми були́ в вас, то казали вам напере́д, що маємо страждати, як і сталось, і знаєте ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Тому́ й я, не сте́рпівши більше, послав довідатись про вашу віру, щоб ча́сом споку́сник вас не спокусив, і труд наш не стався б даре́мний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'А тепер, як вернувся від вас Тимофій і приніс нам радісну звістку про віру та вашу любов, і що за́вжди ви маєте добру пам\'ять про нас, і бажаєте бачити нас, як і ми вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'через те ми потішились, бра́ття, за вас, у всякому горі та в нашій ну́жді, ради вашої віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Бо тепер ми живемо́, якщо в Господі ви стоїте́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Яку бо подяку ми мо́жемо Богові дати за вас, за всю радість, що нею ми ті́шимося ради вас перед нашим Богом?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ми вдень та вночі ревно мо́лимося, щоб побачити ваше лице та допо́внити те, чого не вистача́є вашій вірі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Сам же Бог і Отець наш, і Господь наш Ісус нехай ви́рівняє нашу дорогу до вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'А в вас хай примно́жить Госпо́дь, і нехай збагати́ть вашу любов один до о́дного, і до всіх, як і наша є до вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Нехай Він зміцни́ть серця́ ваші невинними в святості перед Богом і нашим Отцем, при прихо́ді Господа нашого Ісуса з усіма́ святими Його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'А далі, бра́ття, просимо вас та благаємо в Господі Ісусі, щоб, як прийняли́ ви від нас, як належить поводитись вам та дого́джувати Богові, — як ви й поводитеся, — щоб у тому ще більше зроста́ли!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Бо ви знаєте, які вам нака́зи дали ми Господом Ісусом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Бо це воля Божа, — освя́чення ваше: щоб ви береглись від розпусти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'щоб кожен із вас умів тримати начи́ння своє в святості й честі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'а не в при́страсній по́хоті, як і „погани, що Бога не знають“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Щоб ніхто не кривдив і не визи́скував брата свого в якійбудь справі, бо ме́сник Госпо́дь за все це, як і перше казали ми вам та засві́дчили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Бо покликав нас Бог не на нечи́стість, але на освя́чення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Отож, хто оце відкида́є, зневажає не люди́ну, а Бога, що нам також дав Свого Духа Святого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'А про братолюбство немає потреби писати до вас, бо самі ви від Бога на́вчені люби́ти один о́дного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'бо чините те всім брата́м у всій Македонії. Благаємо ж, браття, ми вас, щоб у цьому ще більш ви зростали,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'і пильно дбали жити спокійно, займатися своїми справами та заробляти своїми руками, як ми вам наказували,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'щоб ви перед чужими пристойно пово́дилися, і щоб ні від ко́го не залежали!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'Не хо́чу ж я, браття, щоб не відали ви про покі́йних, щоб ви не сумували, як і інші, що надії не мають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'Коли бо ми віруємо, що Ісус був умер і воскрес, так і покі́йних через Ісуса приведе́ Бог із Ним.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Бо це ми вам кажемо словом Господнім, що ми, хто живе, хто полишений до прихо́ду Господнього, — ми не попередимо покі́йних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'Сам бо Господь із нака́зом, при голосі арха́нгола та при Божій сурмі́ зійде з неба, і перше воскре́снуть умерлі в Христі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'потім ми, що живемо́ й зоста́лись, бу́демо схо́плені ра́зом із ними на хмарах на зу́стріч Господню на повітрі, і так за́всіди бу́демо з Господом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 18, 'Отож, потішайте один о́дного цими словами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'А про часи́ та про по́ри, брати, не потрібно писати до вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'бо самі ви докладно те знаєте, що при́йде день Господній так, як злодій вночі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Бо коли говоритимуть: „Мир і безпечність“, тоді несподівано при́йде заги́біль на них, як му́ка тієї, що носить в утро́бі, — і вони не втечуть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'А ви, браття, не в те́мряві, щоб той день захопи́в вас, як злодій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Бо ви всі сини світла й сини дня. Не належимо ми ночі, ні те́мряві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Тож не бу́демо спати, як інші, а пильнуймо та будьмо твере́зі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Ті бо, що сплять — сплять уночі, а ті, що напиваються — вночі напиваються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'А ми, що належимо дневі, будьмо тверезі, зодягнувшися в броню́ віри й любови, та в шоло́м надії спасі́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'бо Бог нас не призна́чив на гнів, але щоб спасі́ння оде́ржали Господом нашим Ісусом Христом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'що помер був за нас, щоб, чи пильнуємо ми чи спимо́, укупі з Ним ми жили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Утішайте тому́ один о́дного, і збудо́вуйте один о́дного, — як і чините ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Благаємо ж, бра́ття, ми вас, — шануйте тих, що працюють між вами, і в вас старшину́ють у Господі, і навчають вас вони,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'і в великій любові їх майте за їхню працю. Між собою заховуйте мир!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Благаємо ж, бра́ття, ми вас: напоумля́йте непорядних, потішайте малодушних, підтримуйте слаби́х, усім довготерпіть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'Глядіть, щоб ніхто ніко́му не віддавав злом за зло, але за́вжди дбайте про добро один для о́дного й для всіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'За́вжди радійте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Безперестанку моліться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Подяку складайте за все, бо така Божа воля про вас у Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'Духа не вгаша́йте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'Не горду́йте пророцтвами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 21, 'Усе досліджуючи, тримайтеся доброго!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 22, 'Стережіться лихого в усякому ви́гляді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 23, 'А Сам Бог миру нехай освя́тить вас цілко́м доскона́ло, а непору́шений дух ваш, і душа, і тіло нехай непорочно збере́жені бу́дуть на при́хід Господа нашого Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 24, 'Вірний Той, Хто вас кличе, — Він і вчинить оте!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 25, 'Бра́ття, моліться за нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 26, 'Привітайте всю бра́ттю святим поцілунком!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 27, 'Заклинаю вас Господом, — цього листа прочитати перед усіма́ братами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 28, 'Благода́ть Господа нашого Ісуса Христа нехай буде з вами. Амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Павло, і Силуа́н, і Тимофій до Солунської Церкви в нашім Бозі Отці й Господі Ісусі Христі:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'благода́ть вам і мир від Бога Отця й Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Ми за́вжди повинні подяку складати за вас Богові, бра́ття, як і годи́ться, бо сильно росте віра ваша, і примно́жується любов кожного з усіх вас один до о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'Так що ми самі хва́лимось вами по Божих Церквах за ваші стражда́ння та віру в усіх переслі́дуваннях ваших та в у́тисках, що їх переносите ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'А це доказ праведного Божого су́ду, щоб стали ви гідні Божого Царства, що за нього й страждаєте ви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'Бо то справедливе в Бога — віддати утиском тим, хто вас утискає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'а вам, хто утиски терпить, відпочи́нок із нами, коли з\'я́виться з неба Господь Ісус з а́нголами сили Своєї, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, '„в огні полум\'я́ному, що даватиме помсту на тих, хто Бога не знає, і не слухає“Єва́нгелії Господа нашого Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'Вони кару при́ймуть, — вічну поги́біль від лиця Господнього та від слави поту́ги Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'як Він при́йде того дня просла́витися в Своїх святих, і стати дивним у всіх віруючих, бо сві́дчення наше знайшло віру між вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'За це ми й молимось за́вжди за вас, щоб наш Бог учинив вас гідними покли́кання, і міццю напо́внив усю добру волю до́брости й ді́ло віри,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'щоб просла́вилося Ім\'я́ Господа нашого Ісуса в вас, а ви в Ньому, за благода́ттю Бога нашого й Господа Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Благаємо ж, бра́ття, ми вас, щодо прихо́ду Господа нашого Ісуса Христа й нашого згрома́дження до Нього,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'щоб ви не хвилювалися зараз умом та не жахались ані через духа, ані через слово, ані через листа, що він ніби від нас, — ніби вже настав день Господній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'Хай ніхто жодним способом вас не зведе́! Бо той день не настане, аж перше при́йде відсту́плення, і ви́явиться беззако́нник, призна́чений на погибіль,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'що противиться та несеться над усе, зване Богом чи свя́тощами, так що в Божому храмі він сяде, як Бог, і за Бога себе видаватиме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'Чи ви не пам\'ятаєте, як, ще в вас живши, я це вам говорив?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'І тепер ви знаєте, що́ саме не допускає з\'явитись йому своєчасно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'Бо вже діється таємни́ця беззако́ння; тільки Той, Хто трима́є тепер, буде тримати, аж поки не бу́де усу́нений Він із сере́дини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'І тоді то з\'явиться той беззаконник, що його Госпо́дь Ісус заб\'є Духом уст Своїх і знищить з\'я́вленням прихо́ду Свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'Його прихід — за чином сатани — буде з усякою силою й зна́ками та з неправдивими чу́дами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'і з усякою обманою неправди між тими, хто гине, бо любови правди вони не прийняли́, щоб їм спастися.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'І за це Бог пошле їм дію обмани, щоб у неправду повірили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'щоб стали засу́джені всі, хто не вірив у правду, але полюбив неправедність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'А ми за́вжди повинні дякувати Богові за вас, улю́блені Господом бра́ття, що Бог вибрав вас споча́тку на спасі́ння освя́ченням Духа та вірою в правду,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'до чого покликав Він вас через нашу Єва́нгелію, щоб отримати славу Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'Отже, бра́ття, стійте й тримайтеся переда́нь, яких ви навчились чи то словом, чи нашим посла́нням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'Сам же Госпо́дь наш Ісус Христос і Бог Отець наш, що нас полюбив і дав у благода́ті вічну потіху та добру надію, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'нехай ваші серця Він поті́шить, і нехай Він зміцнить вас у всякому доброму ділі та в слові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'Наостанку, моліться, бра́ття, за нас, щоб ши́рилось Слово Господнє та сла́вилось, як і в вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'і щоб ми ви́зволилися від злих та лукавих людей, бо віра — не в усіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'І вірний Господь, що зміцнить вас і збереже від лукавого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'А про вас покладаємо надію на Господа, що й чините ви, і чинити бу́дете те, що наказуємо вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'Госпо́дь же нехай серця ваші спряму́є на Божу любов та терпеливість Христову!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'А ми вам наказуємо, браття, Ім\'я́м Господа Ісуса Христа, щоб ви цура́лися кожного брата, що живе по-леда́чому, а не за переда́нням, яке прийняли́ ви від нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Самі бо ви знаєте, як належить наслідувати нас. Бо ми поміж вами не си́дні справля́ли,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'і хліба не їли ні в ко́го даремно, але в перевто́мі й напру́женні день і ніч працювали, щоб не бути ніко́му із вас тягаре́м,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'не тому́, щоб ми вла́ди не мали, але щоб себе за взірця́ дати вам, щоб нас ви наслідували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'Бо коли ми в вас перебува́ли, то це вам наказували, що як хто працювати не хоче, — нехай той не їсть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'Бо ми чуємо, що дехто між вами живуть по-леда́чому, — нічого не роблять, а тільки вдають, ніби роблять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'Таким ми наказуємо та благаємо Господом нашим Ісусом Христом, щоб мо́вчки вони працювали та власний хліб їли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'А ви, бра́ття, не вто́млюйтеся, коли чините добре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'Коли ж хто не послухає нашого слова через цього листа, заува́жте того, і не майте з ним зносин, щоб він був посоромлений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Та не майте його за неприятеля, а навчайте, як брата.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'А Сам Госпо́дь миру нехай за́вжди дасть вам мир усяким способом. Госпо́дь з вами всіма́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Привіт вам моєю рукою Павловою, — це править за знака в усякім листі. Так пишу́ я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Благодать Господа нашого Ісуса Христа нехай буде з вами всіма́! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Павло, апо́стол Христа Ісуса, з волі Бога, Спасителя нашого й Христа Ісуса, надії нашої,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'до Тимофі́я, щирого сина за вірою: благода́ть, милість, мир від Бога Отця і Христа Ісуса, Господа нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Як я йшов у Македо́нію, я тебе вблага́в був позостатися в Ефе́сі, щоб ти декому наказав не навчати іншої науки,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'і не зверта́ти уваги на ви́гадки й на родоводи безкраї, що викликують більше сварки́, ніж збудува́ння Боже, що в вірі воно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'Ціль же нака́зу — любов від чистого серця, і доброго сумління, і нелукавої віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'Дехто в тім прогрішили були та вдалися в пустомо́вність, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'вони забажали бути вчителями Зако́ну, — та не розуміли ні того, що́ говорять, ні про що запевня́ють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'А ми знаємо, що добрий Зако́н, коли хто зако́нно вживає його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'та ві́дає те, що Зако́н не покладений для праведного, але для беззако́нних та для неслухня́них, нечестивих і грішників, безбожних та нечистих, для знева́жників батька та зневажників матері, для душогубців,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'розпусників, мужоложників, розбійників, неправдомовців, кривоприсяжників, і для всього іншого, що противне здоровій науці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'за славною Єва́нгелією блаженного Бога, яка мені зві́рена.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'Я дяку складаю Тому, Хто зміцнив мене, — Христу Ісусу, Господу нашому, що мене за вірного визнав і поставив на службу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'мене, що давніше був богознева́жник, і гноби́тель, і напасни́к, але був помилуваний, бо я те чинив нетяму́чий у невірстві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'І бага́то збільши́лась у мені благодать Господа нашого з вірою та з любов\'ю в Христі Ісусі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'Вірне це слово, і гі́дне всякого прийняття́, що Христос Ісус прийшов у світ спасти́ грішних, із яких перший — то я.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Але я тому́ був помилуваний, щоб Ісус Христос на першім мені показав усе довготерпіння, для при́кладу тим, що мають увірувати в Нього на вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'А Цареві віків, нетлінному, невиди́мому, єдиному Богові честь і слава на вічні віки. Амінь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Цього нака́за я передаю тобі, сину мій Тимофіє, за тими пророцтвами, що про тебе давніше були, щоб ними провадив ти добру війну,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'маючи віру та добре сумління, якого дехто відкинулися та й розбилися в вірі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'Серед них Гімене́й та Олександер, яких я передав сатані, щоб навчились вони не зневажати Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Отже, перш над усе я благаю чинити молитви, блага́ння, проха́ння, подяки за всіх людей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'за царі́в та за всіх, хто при вла́ді, щоб могли ми прова́дити тихе й мирне життя в усякій побожності та чистості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'Бо це добре й приємне Спасителеві нашому Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'що хоче, щоб усі люди спаслися, і прийшли до пізна́ння пра́вди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Один бо є Бог, і один Посере́дник між Богом та людьми́, — люди́на Христос Ісус,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'що дав Само́го Себе на ви́куп за всіх. Таке було свідо́цтво ча́су свого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'на що я поста́влений був за проповідника та за апо́стола, — правду кажу́, не обманюю, — за вчителя поганів у вірі та в правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'Отож, хо́чу я, щоб му́жі чинили моли́тви на кожному місці, підіймаючи чисті руки без гніву та сумніву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Так само й жінки́, — у скромнім убра́нні, з соромли́вістю та неви́нністю, — нехай прикрашають себе не плеті́нням воло́сся, не кошто́вними ша́тами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'але добрими вчинками, як то ли́чить жінка́м, що присвячуються на побожність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'Нехай жінка навчається мо́вчки в повній покорі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'А жінці навчати я не дозволяю, ані панувати над мужем, але бути в мовча́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'Ада́м бо був створений перше, а Єва потому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'І Ада́м не був зве́дений, але, зведена бувши, жінка попала в пере́ступ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Та спасеться вона діторо́дженням, якщо пробува́тиме в вірі й любові, та в посвяті з розвагою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Вірне це слово: коли хто єпи́скопства хоче, — доброго діла він пра́гне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'А єпи́скоп має бути бездога́нний, муж однієї дружи́ни, тверезий, невинний, че́сний, гостинний до при́ходнів, здібний навчати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'не п\'яни́ця, не заводія́ка, але тихий, несварли́вий, не сріблолюбець,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'щоб добре ряди́в власним домом, що має дітей у слухня́ності з повною чесністю, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'бо хто власним домом ряди́ти не вміє, я́к він зможе пильнува́ти про Божу Церкву? —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'не новонаве́рнений, щоб він не запишався, і не впав у ворожий о́суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'Треба, щоб мав він і добре засві́дчення від чужи́нців, щоб не впасти в догану та в сітку диявольську.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Так само диякони́ мають бути поважні, не двомовці, не багато відда́ні вину, не соромнозахла́нні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'такі, що мають таємни́цю віри при чистім сумлінні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'Отже, і вони нехай перш випробо́вуються, а потому хай служать, якщо бу́дуть бездога́нні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Так само жінки́ нехай будуть поважні, не обмовли́ві, тверезі та вірні в усьому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'Диякони́ мусять бути мужі однієї дружи́ни, що добре рядя́ть дітьми́ й своїми домами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Бо хто добре виконує службу, той до́брий ступі́нь набуває собі та велику відвагу в вірі через Христа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Це пишу́ я тобі, і сподіваюсь до тебе прийти незаба́ром.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'А коли я спізнюся, то щоб знав ти, як треба пово́дитися в Божому домі, що ним є Церква Бога Живого, стовп і підвалина пра́вди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Безсумнівно, велика це таємни́ця благоче́стя: Хто в тілі з\'яви́вся, Той оправданий Духом, а́нгола́м показався, проповіданий був між наро́дами, увірувано в Нього в світі, Він у славі вознісся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'А Дух ясно говорить, що від віри відступляться дехто в останні часи́, ті, хто слухає духів підступних і наук де́монів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, 'хто в лицемірстві гово́рить неправду, і спалив сумління своє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, 'хто одру́жуватися забороняє, наказує стри́муватися від їжі, яку Бог створив на поживу з подякою віруючим та тим, хто правду пізнав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, 'Кожне бо Боже тво́риво добре, і ніщо не негідне, що приймаємо з подякою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'воно бо освячується Божим! Словом і молитвою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Як бу́деш оце подавати братам, то будеш ти добрий служи́тель Христа Ісуса, годований словами віри та доброї науки, що за нею слідо́м ти пішов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Цурайся нечистих та ба́бських байо́к, а вправляйся в благоче́сті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, 'Бо вправа тілесна мало кори́сна, а благоче́стя кори́сне на все, бо має обі́тницю життя тепе́рішнього та майбу́тнього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'Вірне це слово, і гі́дне всякого прийняття́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, 'Бо на це ми й працюємо і зно́симо га́ньбу, що надію кладемо на Бога Живого, Який усім лю́дям Спаси́тель, найбільше ж для вірних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'Наказуй оце та навчай!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Нехай молодим твоїм віком ніхто не горду́є, але будь зразко́м для вірних у слові, у житті, у любові, у дусі, у вірі, у чистості!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'Поки прийду́ я, пильнуй чита́ння, нага́дування та науки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Не зане́дбуй благода́тного дара в собі, що був да́ний тобі за пророцтвом із покла́денням рук пресвітерів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, 'Про це піклуйся, у цім пробувай, щоб у́спіх твій був явний для всіх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'Уважай на самого себе та на науку, тримайся цього. Бо чи́нячи так, ти спасеш і самого себе, і тих, хто тебе слухає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 1, 'Старшого не докоря́й, але вмовляй, немов ба́тька, а молодших — як братів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 2, 'старших жіно́к — немов матіро́к, молодших — як сесте́р, зо всякою чистістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 3, 'Шануй вді́в, уді́в правдивих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 4, 'А як має вдови́ця яка дітей чи внучат, нехай у́чаться перше побожно шанувати роди́ну свою, і віддячуватися батькам, бо це Богові вгодно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 5, 'А вдови́ця правдива й само́тня надію складає на Бога, та перебуває день і ніч у молитвах і блага́ннях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 6, 'А котра́ у розко́шах живе, — та живою померла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 7, 'І це наказуй, щоб були́ непорочні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 8, 'Коли ж хто про своїх, особливо ж про дома́шніх не дбає, той вирікся віри, і він гірший від невірного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 9, 'А вдову вно́сити до спи́ску не менше, як шістдесятлітню, що була́ за дружи́ну одно́му чоловікові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 10, 'засвідчену в добрих ділах, якщо дітей ви́ховала, якщо подорожніх приймала, якщо но́ги святим умивала, якщо помагала обездо́леним, якщо всякий добрий учинок виконувала.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 11, 'Але вдів молодих не приймай, бо вони, розпали́вшися, хо́чуть, наперекі́р Христові, заміж вихо́дити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 12, 'через що мають о́суд, бо від першої віри відкинулись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 13, 'А ра́зом із тим неробі́тні вони, бо вчаться ходити по домах, і не тільки неробітні, але й лепетли́ві, і занадто цікаві, і гово́рять, чого не годи́ться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 14, 'Отож бо, я хочу, щоб молодші заміж вихо́дили, родили дітей, домом ря́дили, не давали противникові ані жодного по́воду для лихомовства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 15, 'Бо вже дехто пішли слідом за сатаною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 16, 'А коли має вдів який вірний, нехай їх утримує, а Церква нехай не обтяжується, щоб могла вона втримувати вдів правдивих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 17, 'А пресвітери, які добре пильнують діла, нехай будуть наділені подвійною честю, а надто ті, хто працює у слові й науці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 18, 'Бо каже Писа́ння: „Не в\'яжи рота волові, що молотить“, та: „Вартий працівни́к своєї нагоро́ди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 19, 'Не приймай скарги проти пресві́тера, хібащо при двох чи трьох свідках.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 20, 'А тих, хто грішить, картай перед усіма́, щоб і інші страх мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 21, 'Заклинаю тебе перед Богом й Ісусом Христом та ви́браними а́нголами, щоб ти заховав це без лицемі́рства, нічого не ро́блячи з упере́дженням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 22, 'Не рукопоклада́й скоро ніко́го, і не приставай до чужих гріхів. Бережи себе чистим!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 23, 'Води більше не пий, але трохи вина заживай ради шлу́нка твого́ та частих неду́гів твоїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 24, 'У інших людей гріхи явні і йдуть перед ними на о́суд, а за іншими йдуть слідкома́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 25, 'Явні так само й добрі діла, а ті, що інші, сховатись не можуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 1, 'Усі раби, які під ярмом, нехай уважають панів своїх гідними всякої чести, щоб не зневажа́лися Боже Ім\'я́ та наука.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 2, 'А ті, хто має панів віруючих, не повинні недбати про них через те, що бра́ття вони, але нехай служать їм тим більше, що вони віруючі та улю́блені, що вони добродійства Божі приймають. Оцього навчай та нагадуй!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 3, 'А коли хто навчає інакше, і не приступає до здорових слів Господа нашого Ісуса Христа та до науки, що вона за правдивою вірою, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 4, 'той згорді́в, нічого не знає, але захво́рів на суперечки й змага́ння, що від них повстають заздрість, сварки́, богозневаги, лукаві здогади,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 5, 'постійні сварні між людьми́ зіпсутого розуму й позбавлених правди, які ду́мають, ніби благоче́стя — то зиск. Цурайся таких!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 6, 'Великий же зиск — то благоче́стя із задоволенням.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 7, 'Бо ми не прине́сли в світ нічого, то нічого не можемо й ви́нести.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 8, 'А як маєм поживу та одяг, то ми задово́лені бу́дьмо з того.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 9, 'А ті, хто хоче багаті́ти, упадають у спокуси та в сітку, та в числе́нні нерозумні й шкідливі пожадливості, що втручають людей на загла́ду й загибіль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 10, 'Бо корень усього лихого — то грошолюбство, якому віддавшись, дехто відбились від віри й поклали на себе великі стражда́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 11, 'Але ти, о Божа люди́но, утікай від такого, а женися за праведністю, благоче́стям, вірою, любов\'ю, терпеливістю, ла́гідністю!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 12, 'Змагай добрим зма́гом віри, ухопися за вічне життя, до якого й покликаний ти, і визнав був добре визна́ння перед свідками багатьма́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 13, 'Наказую перед Богом, що ожи́влює все, і перед Христом Ісусом, Який добре визна́ння засві́дчив за По́нтія Пила́та,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 14, 'щоб доде́ржав ти заповідь чистою та бездога́нною аж до з\'я́влення Господа нашого Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 15, 'що його свого ча́су покаже блаженний і єдиний міцний, Цар над царями та Пан над панами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 16, 'Єдиний, що має безсмертя, і живе в неприступному світлі, Якого не бачив ніхто із людей, ані бачити не може. Честь Йому й вічна влада, амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 17, 'Наказуй багатим за віку тепе́рішнього, щоб не не́слися ви́соко, і щоб надії не клали на багатство непевне, а на Бога Живого, що щедро дає нам усе на спожи́ток,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 18, 'щоб робили добро, багати́лися в добрих ділах, були щедрі та пильні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 19, 'щоб збирали собі скарб, як добру основу в майбу́тньому, щоб прийняти правдиве життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 20, 'О Тимофі́ю, бережи переда́ння, стережися марно́го базі́кання та супере́чок знання́, неправдиво названого так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 6, 21, 'Дехто віддався йому, та й від віри відпав. Благода́ть з тобою. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Павло, з волі Божої апо́стол Христа Ісуса, за обі́тницею життя, що в Христі Ісусі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'до Тимофія, сина улю́бленого: благода́ть, милість, мир від Бога Отця й Христа Ісуса, Господа нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'Дякую Богові, Якому служу́ від предків чистим сумлінням, що тебе пам\'ятаю я за́вжди в молитвах своїх день і ніч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'Я бажаю побачити тебе, пам\'ята́ючи сльо́зи твої, щоб напо́внитись радістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'Я приво́джу на пам\'ять собі твою нелицемірну віру, що перше була́ осели́лася в бабі твоїй Лоі́ді та в твоїй матері Евні́кії; певен же я, що й у тобі вона осели́лась.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'З цієї причини я нагадую тобі, щоб ти розгрівав Божого дара, який у тобі через покла́дання рук моїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'Бо не дав нам Бог духа стра́ху, але сили, і любови, і здорового розуму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Тож, не соромся засві́дчення Господа нашого, ні мене, Його в\'я́зня, але страждай з Єва́нгелією за силою Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'що нас спас і покликав святим по́кликом, — не за наші діла, але з волі Своєї та з благодаті, що нам да́на в Христі Ісусі попе́реду вічних часі́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'А тепер об\'яви́лась через з\'я́влення Спасителя нашого Христа Ісуса, що й смерть зруйнував, і вивів на світло життя та нетління Єва́нгелією.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 11, 'що для неї я був настано́влений за проповідника, апо́стола й учителя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 12, 'З цієї причини й терплю́ я оце, але не соро́млюсь, бо знаю, в Кого я ввірував та впе́внився, що має Він силу заховати на той день заста́ву мою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 13, 'Май же за взір здорових слів ті, які від мене почув ти у вірі й любові, що в Христі Ісусі вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 14, 'Добро припору́чене стережи Святим Духом, що в нас пробува́є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 15, 'Ти знаєш оце, що відверну́лись від мене всі, хто в А́зії, а між ними Фіге́л та Гермоге́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 16, 'Хай Госпо́дь подасть милосердя Ониси́форовому дому, бо він часто мене підкріпляв і кайда́нів моїх не соро́мився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 17, 'А коли він до Риму прибув, шукав мене пильно й знайшов, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 18, 'хай Госпо́дь йому дасть знайти милість від Господа в день той, — скільки ж він послужив був в Ефе́сі мені, ти ві́даєш краще!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Отож, сину мій, зміцняйся в благода́ті, що в Христі Ісусі вона!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'А що чув ти від мене при багатьо́х свідках, те передай вірним лю́дям, що будуть спроможні й інших навчити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'А ти терпи лихо, як добрий воя́к Христа Ісуса!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Бо жоден воя́к не в\'яжеться в справи життя, аби догодити тому, хто ві́йсько збирає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'А як хто йде на зма́ги, то вінка́ не одержує, якщо незако́нно змага́ється.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Трудящому хліборо́бові нале́житься першому покуштувати з плоду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'Розумій, що́ я говорю́. А Госпо́дь нехай дасть тобі розум у всьому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'Пам\'ятай про Ісуса Христа з насіння Дави́дового, що воскрес із мертвих, за моєю Єва́нгелією,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'за яку я терплю́ муки аж до ув\'я́знення, як той злочи́нець. Але Сло́ва Божого не ув\'язни́ти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'Через це перено́шу я все ради ви́браних, щоб і вони доступили спасі́ння, що в Христі Ісусі, зо славою вічною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'Вірне слово: коли ра́зом із Ним ми померли, то й жи́тимемо ра́зом із Ним!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'А коли терпимо́, то будемо ра́зом тако́ж царюва́ти. А коли відцураємось, то й Він відцурається нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'А коли ми невірні, зостається Він вірним, бо не може зректися Само́го Себе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'Нагадуй про це й заклинай перед Богом, щоб не спереча́лись словами, бо ніна́що воно, хіба слухача́м на руїну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'Силку́йся поставити себе перед Богом гідним, працівнико́м бездоганним, що вірно навчає науки правди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'Стережися ж базі́кань марни́х, бо вони ще більше провадять до безбожности,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'а їхнє слово, як рак, буде ши́ритися. Від таких Гімене́й і Філі́т,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'що вони погрішилися в правді, казавши, що воскресі́ння було вже, і віру деяких руйнують.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Та однако стоїть міцна́ Божа основа та має печатку оцю: „Господь знає тих, хто Його“, та: „Нехай від неправди відсту́питься всякий, хто Господнє Ім\'я́ називає!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'А в великому домі знахо́диться по́суд не тільки золотий та срібний, але й дерев\'яний та гли́няний, і одні посу́дини на честь, а другі на не́честь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 21, 'Отож, хто від цього очистить себе, буде по́суд на честь, освя́чений, потрібний Володареві, приготова́ний на всяке добре ді́ло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 22, 'Стережися молодечих пожадли́востей, трима́йся праведности, віри, любови, миру з тими, хто Господа кличе від чистого серця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 23, 'А від нерозумних та від невче́них змага́нь ухиляйся, знавши, що вони родять сварки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 24, 'А раб Господній не повинен свари́тись, але бути привітним до всіх, навча́льним, до ли́ха терпля́чим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 25, 'що навчав би противників із ла́гідністю, чи Бог їм не дасть покая́ння, щоб правду пізнати,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 26, 'щоб визволитися від сітки диявола, що він уловив їх для ро́блення волі своєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Знай же ти це, що останніми днями настануть тяжкі́ часи́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'Будуть бо люди тоді самолюбні, грошолюбні, зарозумілі, горді, богозневажники, батькам неслухня́ні, невдячні, непобожні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'нелюбовні, запеклі, осу́дливі, нестримливі, жорстокі, нена́висники добра,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'зрадники, нахабні, бундю́чні, що більше люблять розкоші, аніж люблять Бога, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'вони мають вигляд благоче́стя, але сили його́ відреклися. Відверта́йсь від таких!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'До них бо належать і ті, хто пролазить до хат та зводить жінок, гріхами обтяжених, ведених усякими пожадливостями,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'що вони за́вжди вчаться, та ніко́ли не можуть прийти до пізна́ння правди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Як Янній та Ямврій протиставилися були Мойсеєві, так і ці протиста́вляться правді, люди зіпсутого розуму, не́уки щодо віри.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Та більше не матимуть у́спіху, — бо всім виявиться їхній бе́зум, як і з тими було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Ти ж пішов услід за мною наукою, поступо́ванням, за́міром, вірою, витрива́лістю, любов\'ю, терпеливістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'переслідуваннями та стражда́ннями, що спіткали були мене в Антіохі́ї, в Іконі́ї, у Лі́страх, — такі переслі́дування переніс я, та Госпо́дь від усіх мене визволив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Та й усі, хто хоче жити побожно у Христі Ісусі, — будуть переслідувані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'А люди лихі та дури́світи матимуть у́спіх у злому, зво́дячи й зве́дені бувши.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 14, 'А ти в тім пробува́й, чого́ тебе на́вчено, і що тобі звірено, ві́даючи тих, від ко́го навчився був ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 15, 'І ти знаєш з дити́нства Писа́ння святе, що може зробити тебе мудрим на спасі́ння вірою в Христа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 16, 'Усе Писа́ння Богом на́дхнене, і кори́сне до навча́ння, до докору, до направи, до вихова́ння в праведності,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 17, 'щоб Божа люди́на була досконала, до всякого доброго ді́ла готова.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Отже, я свідкую тобі перед Богом і Христом Ісусом, що Він має судити живих і мертвих за Свого прихо́ду та за Свого Царства.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'Проповідуй Слово, допоминайся вча́сно-невча́сно, докоряй, забороняй, переконуй з терпеливістю та з наукою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'Настане бо час, коли здорової науки не будуть триматись, але за своїми пожадливостями виберуть собі вчителі́в, щоб вони їхні ву́ха вле́щували.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'Вони слух свій від правди відвернуть та до байо́к нахи́ляться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'Але ти будь пи́льний у всьому, терпи лихо, виконуй працю благові́сника, сповня́й свою службу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'Бо я вже за жертву стаю, і час відхо́ду мого вже настав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Я змагався добрим зма́гом, свій біг закінчи́в, віру зберіг.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Наостанку мені призначається вінок праведности, якого мені того дня дасть Господь, Суддя праведний; і не тільки мені, але й усім, хто при́хід Його полюбив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'Подба́й незаба́ром прибути до мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'Бо Дима́с мене кинув, цей вік полюбивши, і пішов до Солу́ня, Кри́скент до Гала́тії, Тит до Далма́тії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'Зо мною сам тільки Лука́. Візьми Ма́рка, і приведи з собою, бо мені він потрібний для служби.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'А Тихи́ка послав я в Ефе́с.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Як будеш іти, то плаща́ принеси́, що його я в Троа́ді зоставив у Ка́рпа, і книжки́, особливо пергамено́ві.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Котля́р Олександер нако́їв був лиха чимало мені... Нехай Госпо́дь йому віддасть за його вчинками!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Стережись його й ти, бо він мі́цно противився нашим словам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'При першій моїй обороні жоден не був при мені, але всі поки́нули мене... Хай Госпо́дь їм того не полічить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'Але Госпо́дь став при мені та й мене підкріпи́в, щоб проповідь виконалась через мене, та щоб усі погани почули її. І я ви́зволився з пащі ле́в\'ячої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'А від усякого вчинку лихого Господь мене ви́зволить та збереже для Свого Небесного Царства. Йому слава на віки вічні, амі́нь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 19, 'Поздоров Приски́ллу й Аки́лу та дім Ониси́фора.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 20, 'Ера́ст позоставси в Кори́нті, а Трохи́ма лишив я слабо́го в Міле́ті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 21, 'Попильну́й прийти до зими́. Вітає тебе Евву́л, і Пуд, і Лин, і Кла́вдія, і вся бра́ття.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 22, 'Господь з твоїм духом! Благода́ть з вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Павло́, раб Божий, а апо́стол Ісуса Христа, по вірі ви́браних Божих і пізна́нні правди, що за благоче́стям,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'в надії вічного життя, яке обіцяв був від вічних часів необма́нливий Бог,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'і ча́су свого з\'явив Слово Своє в пропові́данні, що дору́чене було мені з наказу Спасителя нашого Бога, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'до Тита, щирого сина за спільною ві́рою: благодать, милість та мир від Бога Отця й Христа Ісуса, Спасителя нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'Я для того тебе полиши́в був у Кріті, щоб ти впорядкував недокінчене та пресвітерів настанови́в по містах, як тобі я звелів, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'коли хто бездога́нний, муж єдиної дружи́ни, має вірних дітей, недокорених за блуд або неслухня́ність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'Бо єпи́скоп мусить бути бездоганний, як Божий доморя́дник, не самолюбний, не гнівли́вий, не п\'яни́ця, не заводія́ка, не кори́сливий,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'але гостинний до при́ходнів, добролюбець, поміркований, справедливий, побожний, стри́маний,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'що трима́ється вірного слова згідно з наукою, щоб мав силу й навчати в здоровій науці, і переконувати противних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'Багато бо є неслухня́них, марносло́вців, зводників, особливо ж з обрізаних, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'їм треба уста́ затуляти: вони ці́лі доми баламу́тять, навчаючи, чого не належить, для зиску брудно́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'Сказав один з них, їхній власний пророк: „Крітяни за́вжди брехливі, люті звірі, черева́ні ліниві“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 13, 'Це свідоцтво правдиве. Ради цієї причини докоряй їм суворо, щоб у вірі здорові були́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 14, 'і на юдейські байки́ не вважали, ані на нака́зи людей, що від правди відверта́ються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 15, 'Для чистих все чисте, а для занечищених та для невірних не чисте ніщо, але занечи́стилися і розум їхній, і сумління.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 16, 'Вони тве́рдять, немов знають Бога, але відкидаються вчинками, бувши бридкі́ й неслухняні, і до всякого доброго діла нездатні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, 'А ти говори, що відповідає здоровій науці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'Щоб старі чоловіки твере́зі були, поважні, помірковані, здорові у вірі, у любові, у терпеливості.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Щоб старі жінки́ в своїм стані так само були, як належить святим, — не обмо́вниці, не відда́ні п\'янству, навчали добра,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'щоб навчали жіно́к молодих любити своїх чоловіків, любити дітей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'щоб були помірковані, чисті, господа́рні, добрі, слухня́ні своїм чоловікам, щоб не зневажалося Боже Слово.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'Так само благай юнакі́в, щоб були помірковані.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'У всім сам себе подавай за зразка добрих діл, у навча́нні непорушеність, повагу,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'слово здорове, неосу́дливе, щоб противник був засоромлений, не мавши нічого лихого казати про нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, 'Раби щоб корилися панам своїм, щоб догоджали, не пере́чили,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'не крали, але виявляли всяку добру вірність, щоб у всьому вони прикрашали науку Спасителя нашого Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'Бо з\'явилася Божа благода́ть, що спасає всіх людей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'і навчає нас, щоб ми, відцуравшись безбожности та світських пожадли́востей, жили́ помірковано та праведно, і побожно в тепе́рішнім віці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, 'і чекали блаженної надії та з\'явлення слави великого Бога й Спаса нашого Христа Ісуса,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'що Само́го Себе дав за нас, щоб нас визволити від усякого беззако́нства та очи́стити Собі людей ви́браних, у добрих ділах запопа́дливих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'Оце говори та нагадуй, та з усяким нака́зом карта́й. Хай тобою ніхто не погорду́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, 'Нагадуй їм, щоб слухали вла́ди верховної та кори́лися їй, і до всякого доброго ді́ла готові були́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'щоб не зневажали ніко́го, щоб були́ не сварли́ві, а тихі, виявляючи повну ла́гідність усім лю́дям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'Бо колись були й ми нерозсудні, неслухня́ні, зве́дені, служили різним пожадли́востям та розкошам, жили в злобі та в за́здрощах, бридки́ми були, нена́виділи один о́дного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'А коли з\'явилась благодать та люди́нолюбство Спасителя, нашого Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Він нас спас не з діл праведности, що ми їх учинили були́, а з Своєї милости через обмиття відро́дження й обно́влення Духом Святим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, 'Якого Він щедро вилив на нас через Христа Ісуса, Спасителя нашого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'щоб ми виправдались Його благодаттю, і стали спадкоє́мцями за надією на вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'Вірне слово, і я хочу, щоб ти і про це впевня́в, щоб ті, хто ввірував у Бога, дба́ли про добрі діла пильнувати. Для людей оце добре й кори́сне!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'Вистерігайсь нерозумних змага́нь, і родоводів, і спорів, і супере́чок про Зако́н, — бо вони некори́сні й марні́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Люди́ни єретика, по першім та другім наставленні, відрікайся,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, 'знавши, що зіпсувся такий та грішить, і він сам себе засудив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'Як пришлю я до тебе Арте́ма або Тихи́ка, поква́пся прибути до мене в Нікопо́ль, бо думаю там перези́мувати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'Зако́нника Зи́ну та Аполло́са вишли ква́пливо вперед, щоб для них не забракло нічо́го.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 14, 'Нехай же навчаються й наші дбати про добрі діла при конечних потребах, щоб безплодні вони не були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 15, 'Вітають тебе всі, хто зо мною. Вітай тих, хто любить нас у вірі. Благода́ть з вами всіма́! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Павло, в\'я́зень Христа Ісуса, та брат Тимофій, улю́бленому Филимо́нові й співробі́тникові нашому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'і сестрі любій Апфі́ї, і співвойо́вникові нашому Архи́пові, і Церкві домашній твоїй:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'благодать вам і мир від Бога Отця нашого й Господа Ісуса Христа!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'Я за́всіди дякую Богові моє́му, коли тебе згадую в молитвах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Бо я чув про любов твою й віру, яку маєш до Господа Ісуса, і до всіх святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'щоб спільність віри твоєї дія́льна була в пізна́нні всякого добра, що в нас для Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'Бо ми маємо радість велику й потіху в любові твоїй, серця́ бо святих заспоко́їв ти, брате.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Через це, хоч я маю велику відвагу в Христі подавати нака́зи тобі про потрібне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'але більше з любови благаю я, як Павло, стари́й, тепер же ще й в\'язень Христа Ісуса.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'Благаю тебе про сина свого, про Они́сима, що його породив я в кайда́нах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Колись то для тебе він був непотрібний, тепер же для тебе й для мене він дуже потрібний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Тобі я вертаю його, того, хто є неначе серце моє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'Я хотів був тримати його при собі, щоб він замість тебе мені послужив у кайда́нах за Єва́нгелію,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'та без волі твоєї нічо́го робити не хотів я, щоб твій добрий учинок не був ніби ви́мушений, але добровільний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, 'Бо може для того він був розлучився на час, щоб навіки прийняв ти його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 16, 'і вже не як раба, але вище від раба, — як брата улю́бленого, особливо для мене, а тим більше для тебе, — і за ті́лом, і в Го́споді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 17, 'Отож, коли маєш за друга мене, то прийми його, як мене.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 18, 'Коли ж він чим скри́вдив тебе або винен тобі, — полічи це мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 19, 'Я, Павло, написав це рукою своєю: „Я віддам“, щоб тобі не казати, що ти навіть само́го себе мені винен.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 20, 'Так, брате, — нехай я оде́ржу те, що від тебе прохаю в Го́споді. Заспокой моє серце в Христі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 21, 'Пересвідчений я про слухня́ність твою, і тобі написав оце, відаючи, що ти зробиш і більше, ніж я говорю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 22, 'А ра́зом мені приготуй і поме́шкання, бо наді́юся я, що за ваші моли́тви я буду дарований вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 23, 'Вітає тебе Епафра́с, мій співв\'я́зень у Христі Ісусі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 24, 'Ма́рко, Ариста́рх, Дима́с, Лука́, — мої співробі́тники.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 25, 'Благода́ть Господа Ісуса Христа з вашим духом! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Багато разі́в і багатьма́ способа́ми в давнину́ промовляв був Бог до отців через пророків,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'а в останні ці дні промовляв Він до нас через Сина, що Його настанови́в за Наслідника всього, що Ним і віки́ Він створив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Він був сяєвом слави та образом істоти Його, трима́в усе словом сили Своєї, учинив Собою очи́щення наших гріхів, — і засів на прави́ці величности на висоті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Він остільки був ліпший понад анголі́в, оскільки славніше за них успадкува́в Ім\'я́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Кому́ бо коли з анголів Він промовив: „Ти Мій Син, — Я сьогодні Тебе породив“! І зно́ву: „Я буду Йому за Отця, а Він Мені буде за Сина“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'І коли знов Він уводить на світ Перворі́дного, то гово́рить: „І нехай Йому вкло́няться всі анголи Божі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'А про анголів Він говорить: „Ти чиниш духів ангола́ми Своїми, а палю́чий огонь — Своїми слугами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'А про Сина: „Престол Твій, о Боже, навік віку; бе́рло Твого царюва́ння — бе́рло праведности.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'Ти полюбив праведність, а беззако́ння знена́видів; через це намасти́в Тебе, Боже, Твій Бог оливою радости більше, ніж дру́зів Твоїх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'І: „Ти, Господи, землю колись закла́в, а небо — то чин Твоїх рук.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'Загинуть вони, а Ти будеш стояти, — всі вони, як той одяг, поста́ріють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Як одежу, їх змі́ниш, — і минуться вони, а Ти за́вжди Той Са́мий, і роки Твої не закі́нчаться“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'Кому з анголів Він промовив коли: „Сядь право́руч Мене, доки не покладу́ Я Твоїх ворогів підніжком ногам Твоїм“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Чи не всі вони ду́хи служебці, що їх посилають на службу для тих, хто має спасіння вспадкувати?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 1, 'Через це подобає нам більше вважати на почуте, шоб ми не відпали коли.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 2, 'Коли бо те слово, що сказали його анголи́, було певне, а всякий пере́ступ та непо́слух прийняли́ справедливу заплату,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 3, 'то як ми втечемо́, коли ми не дбали про таке велике спасі́ння? Воно проповідувалося споча́тку від Го́спода, стве́рдилося нам через тих, хто почув,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 4, 'коли Бог був засві́дчив озна́ками й чу́дами, і різними силами та обдарува́нням Духом Святим із волі Своє́ї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 5, 'Бо Він не піддав ангола́м світ майбутній, що про нього говоримо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 6, 'Але хтось десь засві́дчив був, кажучи: „Що́ є чолові́к, що Ти пам\'ята́єш про ньо́го, і син лю́дський, якого відвідуєш?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 7, 'Ти його вчинив мало меншим від анголів, і честю й вели́чністю Ти вінчаєш його, і поставив його́ над діла́ми рук Своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 8, 'усе піддав Ти під ноги йому́“! А коли Він піддав йому все, то не залиши́в нічого йому непідда́ного. А тепер ще не бачимо, щоб підда́не було йому все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 9, 'Але бачимо Ісуса, мало чим уменшеним від анголі́в, що за перете́рплення смерти Він уві́нчаний честю й вели́чністю, щоб за благода́ттю Божою смерть скуштува́ти за всіх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 10, 'Бо належало, щоб Той, що все ради Нього й усе від Нього, Хто до слави привів багато синів, Провідника їхнього спасі́ння вчинив досконалим через стражда́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 11, 'Бо Хто освячує, і ті, хто освя́чується — усі від Одно́го. З цієї причини не соромиться Він звати братами їх, кажучи:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 12, '„Сповіщу́ про Ім\'я́ Твоє бра́ттям Своїм, буду хвалити Тебе серед Церкви“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 13, 'І ще: „На Нього я бу́ду надіятися“! І ще: „Ото Я та діти, яких Бог Мені дав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 14, 'А що ді́ти стали спільниками тіла та крови, то й Він став уча́сником їхнім, щоб смертю знищити того, хто має вла́ду смерти, цебто диявола,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 15, 'та визволити тих усіх, хто все життя стра́хом смерти тримався в неволі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 16, 'Бо приймає Він не Анголі́в, але Авраамове насіння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 17, 'Тому́ мусів бути Він у всьому подібний брата́м, щоб стати милости́вим та вірним Первосвящеником у Божих справах, для вблага́ння за гріхи людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 18, 'Бо в чо́му був Сам постраждав, ви́пробовуваний, у тому Він може й випробо́вуваним помогти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 1, 'Отож, святі брати́, учасники небесного покли́кання, уважайте на Апо́стола й Первосвященика нашого ісповідання, Ісуса,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 2, 'що вірний Тому́, Хто настанови́в Його, як був і Мойсей у всім домі Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 3, 'бо гідний Він вищої слави понад Мойсея, поскільки будівни́чий має більшу честь, аніж дім.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 4, 'Усякий бо дім хтось будує, а Той, хто все збудував, — то Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 5, 'І Мойсей вірний був у всім домі Його, як слуга, на свідоцтво того, що сказати повинно було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 6, 'Христос же, як Син, у Його домі. А дім Його — ми, коли тільки відвагу й похвалу́ надії доде́ржимо певними аж до кінця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 7, 'Тому́ то, як каже Дух Святий: „Сьогодні, як голос Його ви почуєте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 8, 'не робіть затверді́лими ваших серде́ць, як під час наріка́нь, за дня випробо́вування на пустині,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 9, 'де Мене випробо́вували отці ваші, Мене випробо́вували, і бачили працю Мою сорок років.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 10, 'Через це Я розгнівався був на той рід і сказав: Постійно вони блу́дять серцем, вони не пізнали доріг Моїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 11, 'тому́ Я присягнув у гніві Своїм, що вони до Мого́ відпочинку не вві́йдуть“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 12, 'Стережіться, брати́, щоб у комусь із вас не було злого серця невірства, що воно відступало б від Бога Живого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 13, 'Але кожного дня заохочуйте один о́дного, доки зветься „Сьогодні“, щоб запеклим не став котри́й з вас через підступ гріха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 14, 'Бо ми стали учасниками Христа, коли тільки почате життя ми затри́маємо певним аж до кінця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 15, 'аж поки говориться: „Сьогодні, як голос Його ви почуєте, не робіть затверділими ваших серде́ць, як під час наріка́нь“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 16, 'Котрі бо, почувши, розгнівали Бога? Чи не всі, хто з Єгипту вийшов з Мойсеєм?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 17, 'На ко́го ж Він „гнівався був сорок ро́ків?“Хіба не на тих, хто згрішив, що їхні „кості в пустині полягли?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 18, 'Проти ко́го Він „був присягався, що не вві́йдуть вони до Його відпочинку, „як не проти неслухняних?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 19, 'І ми бачимо, що вони не змогли ввійти за невірство.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 1, 'Отже, біймося, коли зостається обітниця вхо́ду до Його́ відпочинку, щоб не виявилось, що хтось із вас опізни́вся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 2, 'Бо Єва́нгелія була звіщена нам, як і тим. Але не прине́сло пожитку їм слово почуте, бо воно не злучилося з вірою слухачів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 3, 'Бо до Його́ відпочинку вхо́димо ми, що ввірували, як Він провістив: „Я присяг був у гніві Своїм, що до місця Мого відпочинку не вві́йдуть вони“, хоч діла Його були вчи́нені від закла́дин світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 4, 'Бо колись про день сьомий сказав Він отак: „І Бог відпочив сьомого дня від усієї праці Своєї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 5, 'А ще тут: „До Мого відпочинку не вві́йдуть вони“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 6, 'Коли ж залиша́ється ото, що деякі ввійдуть до нього, а ті, кому Єва́нгелія була перше зві́щена, не ввійшли за непо́слух,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 7, 'то ще призначає Він деякий день, — „сьогодні“, бо через Давида говорить по такім довгім ча́сі, як вище вже сказано: „Сьогодні, як голос Його ви почуєте, не робіть затверді́лими ваших серде́ць“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 8, 'Бо коли б Ісус (Навин) дав їм відпочинок, то про інший день не казав би по цьо́му.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 9, 'Отож, людові Божому залиша́ється субо́тство, спочи́нок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 10, 'Хто бо ввійшов був у Його відпочинок, то й той відпочив від учинків своїх, як і Бог від Своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 11, 'Отож, попильнуймо ввійти до того відпочинку, щоб ніхто не потра́пив у непо́слух за при́кладом тим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 12, 'Бо Боже Слово живе та дія́льне, гостріше від усякого меча обосічного, — прохо́дить воно аж до поділу душі й духа, сугло́бів та мо́зків, і спосібне судити думки́ та на́міри се́рця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 13, 'I немає створі́ння, щоб сховалось перед Ним, але́ все наге́ та відкрите перед очима Його, — Йому дамо звіт!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 14, 'Отож, мавши великого Первосвященика, що небо перейшов, Ісуса, Сина Божого, трима́ймося визнання нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 15, 'Бо ми маємо не такого Первосвященика, що не міг би співчувати слабостям нашим, але ви́пробуваного в усьому, подібно до нас, окрім гріха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 16, 'Отож, приступаймо з відвагою до престолу благода́ті, щоб прийняти милість та для своєчасної допомо́ги знайти благода́ть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 1, 'Кожен бо первосвященик, що з-між людей вибирається, настановляється для людей на служі́ння Богові, щоб прино́сити да́ри та жертви за гріхи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 2, 'і щоб міг співчува́ти недосві́дченим та заблу́дженим, бо й сам він пере́йнятий слабістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 3, 'І тому́ він повинен як за людей, так само й за себе само́го прино́сити жертви за гріхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 4, 'А чести цієї ніхто не бере сам собою, а покликаний Богом, як і Ааро́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 5, 'Так і Христос, — не Сам Він просла́вив Себе, щоб Первосвящеником стати, а Той, що до Нього сказав: „Ти Мій Син, Я сьогодні Тебе породи́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 6, 'Як і на іншому місці гово́рить: „Ти Священик навіки за чином Мелхиседе́ковим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 7, 'Він за днів тіла Свого з голосі́нням великим та слізьми́ приніс був блага́ння й молитви до Того, Хто від смерти Його міг спасти, — і був вислуханий за побожність Свою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 8, 'І хоч Сином Він був, проте́ навчився по́слуху з того, що вистраждав був.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 9, 'А вдоскона́лившися, Він для всіх, хто слухня́ний Йому, спричини́вся для вічного спасі́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 10, 'і від Бога був на́званий Первосвящеником за чином Мелхиседе́ковим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 11, 'Про це нам би треба багато казати, та ви́словити важко його, бо нездібні ви стали, щоб слухати.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 12, 'Ви бо за віком повинні б бути вчителя́ми, але ви потребуєте ще, щоб хтось вас навчав перших поча́тків Божого Сло́ва. І ви стали такими, яким потрібне молоко, а не стра́ва тверда́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 13, 'Бо хто молока вживає, той недосві́дчений у слові праведности, — бо він немовля́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 5, 14, 'А страва тверда́ — для дорослих, що мають чуття, при́вчені звичкою розрізняти добро й зло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 1, 'Тому́ полиші́мо поча́тки науки Христа, та й звернімося до досконалости, і не кладімо зно́ву засади покая́ння від мертвих учинків та про віру в Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 2, 'Науки про хрищення, про поклада́ння рук, про воскресі́ння мертвих та вічний суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 3, 'Зробимо й це, коли Бог дозволить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 4, 'Не можна бо тих, що раз просвітились були, і скуштували небесного да́ру, і стали уча́сниками Духа Святого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 5, 'і скуштували доброго Божого Слова та сили майбу́тнього віку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 6, 'та й відпали, знов відновляти покая́нням, коли вдруге вони розпинають у собі Сина Божого та зневажають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 7, 'Бо земля, що п\'є дощ, який падає часто на неї, і родить рослини, добрі для тих, хто їх і виро́щує, — вона благословення від Бога приймає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 8, 'Але та, що приносить те́рня й будя́ччя, — непотрібна вона та близька́ до прокля́ття, а кінець її — спа́лення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 9, 'Та ми сподіва́ємось, любі, кращого про вас, що спасі́ння тримаєтеся, хоч говоримо й так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 10, 'Та не є Бог несправедливий, щоб забути ді́ло ваше та працю любови, яку показали в Ім\'я́ Його ви, що святим послужили та служите.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 11, 'Ми ж бажаємо, щоб кожен із вас виявляв таку саму завзятість на певність надії аж до кінця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 12, 'щоб ви не розлінились, але переймали від тих, хто обі́тниці вспадко́вує вірою та терпеливістю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 13, 'Бо Бог, обі́тницю давши Авраамові, як не міг ніким вищим покля́стися, поклявся Сам Собою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 14, 'говорячи: „Поблагословити — Я ко́нче тебе поблагословлю́, та розмножити — розмножу тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 15, 'І, терплячи довго отак, Авраа́м оде́ржав обі́тницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 16, 'Бо люди клянуться вищим, і клятва на стве́рдження кінчає всяку їхню суперечку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 17, 'Тому й Бог, хотівши перева́жно показати спадкоє́мцям обі́тниці незмінність волі Своєї, учинив те при помочі клятви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 18, 'щоб у двох тих незмінних реча́х, що в них не можна сказати неправди Богові, мали потіху міцну ми, хто прибіг прийняти надію, що лежить перед нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 19, 'що вони для душі як котви́ця, міцна та безпечна, що аж до сере́дини входить за заслону,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 6, 20, 'куди, як предте́ча, за нас увійшов був Ісус, ставши навіки Первосвящеником за чином Мелхиседе́ковим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 1, 'Бо цей Мелхиседе́к, цар Сали́му, священик Бога Всеви́шнього, що був стрів Авраама, як той вертався по пора́зці царів, і його поблагослови́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 2, 'Авраам відділив йому й десяти́ну від усього, — найперше бо він визначає „цар праведности“, а потім „цар Сали́му“, цебто „цар миру“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 3, 'Він без ба́тька, без матері, без родово́ду, не мав ані поча́тку днів, ані кінця життя, уподо́бився Божому Сину, — пробуває священиком за́вжди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 4, 'Побачте ж, який він великий, що йому й десятину з добичі найліпшої дав патріярх Авраам!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 5, 'Ті з синів Леві́євих, що свяще́нство приймають, мають заповідь — брати за Зако́ном десятину з наро́ду, цебто з братів своїх, хоч і вийшли вони з Авраамових сте́гон.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 6, 'Але цей, що не похо́дить з їхнього роду, десятину одержав від Авраама, і поблагословив того, хто обі́тницю мав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 7, 'І без усякої супере́чки більший меншого благословляє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 8, 'І тут люди смерте́льні беруть десяти́ну, а там той, про якого засвідчується, що живе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 9, 'І, щоб сказати отак, через Авраама і Леві́й, що бере десятини, дав сам десятини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 10, 'Бо ще в ба́тькових сте́гнах він був, коли стрів його Мелхиседе́к.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 11, 'Отож, коли б досконалість була через свяще́нство леви́тське, — бо люди Зако́на оде́ржали з ним, — то яка ще потреба була, щоб Інший Священик повстав за чином Мелхиседе́ковим, а не зватися за чином Ааро́новим?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 12, 'Коли бо свяще́нство зміняється, то з потреби буває переміна й Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 13, 'Бо Той, що про Нього говориться це, належав до іншого племени, з якого ніхто не ставав був до же́ртівника.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 14, 'Бож відо́мо, що Госпо́дь наш походить від Юди, а про це плем\'я́, про свяще́нство його, нічого Мойсей не сказав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 15, 'І ще більше відо́мо, коли повстає на подобу Мелхиседе́ка Інший Священик,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 16, 'що був не за зако́ном тілесної заповіді, але з сили незнища́льного життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 17, 'Бо свідчить: „Ти Священик навіки за чином Мелхиседе́ковим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 18, 'Попере́дня бо заповідь відкладається через не́міч її та некори́сність.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 19, 'Бо не вдоскона́лив нічого Зако́н. Запроваджена ж краща надія, що нею ми наближуємось до Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 20, 'І поскільки воно не без клятви, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 21, 'вони бо без клятви були́ священиками, Цей же з клятвою через Того, Хто говорить до Нього: „Клявся Госпо́дь — і не буде Він каятися: Ти Священик навіки за чином Мелхиседе́ковим“, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 22, 'то постільки Ісус став запорукою кращого Заповіту!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 23, 'І багато було їх священиків, бо смерть боронила лишатися їм,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 24, 'але Цей, що навіки лишається, безперестанне Свяще́нство Він має.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 25, 'Тому може Він за́вжди й спасати тих, хто через Нього до Бога приходить, бо Він за́вжди живий, щоб за них заступи́тись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 26, 'Отакий бо потрібний нам Первосвященик: святий, незлоби́вий, невинний, відлучений від грішників, що вищий над небеса́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 27, 'що потреби не має щодня, як ті первосвященики, перше прино́сити жертви за власні гріхи, а потому за лю́дські гріхи, — бо Він це раз наза́вжди вчинив, принісши Само́го Себе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 7, 28, 'Зако́н бо людей ставить первосвящениками, що немочі мають, але слово клятви, що воно за Зако́ном, ставить Сина, Який досконалий навіки!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 1, 'Головна ж річ у то́му, про що я говорю: маємо Первосвященика, що засі́в на небеса́х, по прави́ці престолу величности,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 2, 'що Він Священнослужи́тель святині й правдивої скинії, що її збудував був Госпо́дь, а не люди́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 3, 'Усякий бо первосвященик настановляється, щоб прино́сити да́ри та жертви, а тому було треба, щоб і Цей щось мав, що принести.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 4, 'Бо коли б на землі перебува́в, то не був би Він священиком, бо тут пробувають священики, що да́ри приносять за Зако́ном.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 5, 'Вони служать о́бразові й тіні небесного, як Мойсеєві сказано, коли мав докінчи́ти скинію: „Дивись бо, сказав, зроби все за зразко́м, що тобі на горі був показаний!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 6, 'А тепер оде́ржав Він краще служі́ння, поскільки Він посередник і кращого заповіту, який на кращих обітницях був узаконений.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 7, 'Бо коли б отой перший був бездоганний, не шукалося б місця для другого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 8, 'Бо їм докоряючи, каже: „Ото дні надхо́дять, говорить Господь, коли з домом Ізраїля й з Юдиним домом Я складу́ Заповіта Ново́го,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 9, 'не за заповітом, що його Я склав був з отцями їхніми дня, коли взяв їх за руку, щоб вивести їх із землі єгипетської. А що вони не залишилися в Моїм заповіті, то й Я їх покинув, говорить Господь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 10, 'Оце Заповіт, що його Я складу́ по тих днях із домом Ізраїлевим, говорить Господь: Покладу Я Зако́ни Свої в їхні думки́, і на їхніх серцях напишу́ їх, і буду їм Богом, вони ж будуть наро́дом Моїм!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 11, 'І кожен не буде навчати свого ближнього, і кожен брата свого, промовляючи: „Пізнай Господа“! Усі бо вони будуть знати Мене від мало́го та аж до великого з них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 12, 'Буду бо Я милости́вий до їхніх неправд, і їхніх гріхів не згадаю Я більш“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 8, 13, 'Коли ж каже „Нови́й Заповіт “, то тим назвав перший стари́м. А що́ порохня́віє й старі́є, те близьке́ до зотління.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 1, 'Мав же і перший заповіт постанови богослужби та земну святиню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 2, 'Була́ бо уряджена перша скинія, яка зветься „Святе“, а в ній був світильни́к, і стіл, і жертовні хліби.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 3, 'А за другою засло́ною скинія, що зветься „Святе́ Святих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 4, 'Мала вона золоту кадильницю й ковче́га заповіту, усюди обку́того золотом, а в нім золота посу́дина з ма́нною, і розцві́ле жезло́ Ааро́нове та табли́ці заповіту.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 5, 'А над ним херуви́ми слави, що затінювали престола благодаті, про що говорити докладно тепер не потрібно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 6, 'При такому ж уря́дженні до першої скинії вхо́дили за́вжди священики, пра́влячи служби Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 7, 'а до другої раз на рік сам первосвященик, не без крови, яку він прино́сить за себе й за лю́дські провини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 8, 'Святий Дух виявляє оцим, що ще не відкрита дорога в святиню, коли ще стоїть перша скинія.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 9, 'Вона образ для ча́су теперішнього, за якого прино́сяться да́ри та жертви, що того не можуть вдоскона́лити, щодо сумління того, хто служить,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 10, 'що тільки в потравах та в напо́ях, та в різних обмива́ннях, в уставах тілесних, — установлено їх аж до ча́су направи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 11, 'Але́ Христос, Первосвященик майбутнього доброго, прийшов із більшою й досконалішою скинією, нерукотво́рною, цебто не цього втво́рення,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 12, 'і не з кров\'ю козлів та телят, але з власною кров\'ю увійшов до святині один раз, та й набу́в вічне відку́плення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 13, 'Бо коли кров козлів та телят та попіл із я́лівок, як покро́пить нечистих, освячує їх на очи́щення тіла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 14, 'скільки ж більш кров Христа, що Себе непорочного Богу приніс Вічним Духом, очистить наше сумління від мертвих учинків, щоб служити нам Богові Живому!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 15, 'Тому Він — Посере́дник Ново́го Заповіту, щоб через смерть, — що була́ для відку́плення від пере́ступів, учинених за першого заповіту, — покликані прийняли́ обі́тницю вічного спа́дку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 16, 'Бо де заповіт, там має відбутися смерть заповітника,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 17, 'заповіт бо важливий по мертвих, бо нічого не варт він, як живе заповітник.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 18, 'Тому й перший заповіт освячений був не без крови:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 19, 'Коли бо Мойсей сповістив усі заповіді за Зако́ном усьому наро́дові, він узяв кров козлів та телят із водою й червоною вовною та з ісопом, та й покропив і саму оту книгу, і людей,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 20, 'проказуючи: „Це кров заповіту, що його наказав для вас Бог!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 21, 'Так само і скинію, і ввесь по́суд служебний покропи́в він кров\'ю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 22, 'І майже все за Зако́ном кров\'ю очищується, а без пролиття́ крови немає відпу́щення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 23, 'Отож, треба було́, щоб образи небесного очищалися цими, а небесне саме кращими від оцих же́ртвами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 24, 'Бо Христос увійшов не в рукотво́рну святиню, що була на взір правдивої, але в саме небо, щоб з\'явитись тепер перед Божим лицем за нас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 25, 'і не тому́, щоб часто прино́сити в жертву Себе, як первосвященик входить у святиню кожнорічно з кров\'ю чужою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 26, 'бо інакше Він мусів би часто страждати ще від закла́дин світу, а тепер Він з\'явився один раз на схи́лку віків, щоб власною жертвою знищити гріх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 27, 'І як лю́дям призна́чено вмерти один раз, потім же суд,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 9, 28, 'так і Христос один раз був у жертву прине́сений, щоб „поне́сти гріхи багатьох“, і не в справі гріха другий раз з\'явитися тим, хто чекає Його на спасі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 1, 'Бо Зако́н, мавши тільки тінь майбутнього добра́, а не самий о́браз речей, тими самими жертвами, що за́вжди щороку прино́сяться, не може ніко́ли вдоскона́лити тих, хто приступає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 2, 'Інакше вони перестали б прино́ситись, бо ті, хто служить, очищені раз, уже б не мали жодної свідо́мости гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 3, 'Але в них спо́мин про гріхи буває щороку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 4, 'бо тож неможливе, щоб кров биків та козлів здіймала гріхи!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 5, 'Тому́ то, вхо́дячи в світ, Він говорить: „Жертви й прино́шення Ти не схотів, але тіло Мені приготува́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 6, 'Цілопа́лення й жертви поку́тної Ти не жадав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 7, 'Тоді Я сказав: Ось іду́, — в звої книжки про Мене написано, щоб волю чини́ти Твою, Боже“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 8, 'Він вище сказав, що „жертви й при́носу, та цілопа́лення й жертви поку́тної, — які за Зако́ном прино́сяться, — Ти не жадав і Собі не вподо́бав“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 9, 'Пото́му сказав: „Ось іду, щоб волю Твою чини́ти, Боже“. Відміняє Він перше, щоб друге поставити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 10, 'У цій волі ми освячені жертвоприно́шенням тіла Ісуса Христа один раз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 11, 'І кожен священик щоденно стоїть, слу́жачи, і часто приносить жертви ті самі, що ніко́ли не можуть зняти гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 12, 'А Він за гріхи світу приніс жертву один раз, і наза́вжди „по Божій правиці засів“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 13, 'далі чекаючи, „аж вороги Його бу́дуть покладені за підніжка Його ніг“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 14, 'Бо жертвоприно́шенням одним вдоскона́лив Він тих, хто освячується.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 15, 'Свідкує ж і Дух Святий нам, як говорить:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 16, '„Оце заповіт, що його по цих днях встановля́ю Я з ними, говорить Господь, — Закони Свої Я дам в їхні серця́, і в їхніх думка́х напишу́ їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 17, 'А їхніх гріхів та несправедливостей їхніх Я більш не згадаю“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 18, 'А де їхнє відпущення, там нема вже жертвоприно́шення за гріхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 19, 'Отож, браття, ми маємо відвагу вхо́дити до святині кров\'ю Ісусовою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 20, 'ново́ю й живою дорогою, яку нам обнови́в Він через завісу, цебто через тіло Своє,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 21, 'маємо й Великого Священика над домом Божим, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 22, 'то приступі́мо з щирим серцем, у повноті́ віри, окропи́вши серця́ від сумління лукавого та обмивши тіла́ чистою водою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 23, 'Трима́ймо непохи́тне визна́ння надії, вірний бо Той, Хто обіцяв.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 24, 'І уважаймо один за одни́м для заохо́ти до любови й до добрих учинків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 25, 'Не кидаймо збору свого, як то зви́чай у деяких, але заохочуймося, і тим більше, скільки більше ви бачите, що зближається день той.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 26, 'Бо як ми грішимо́ самові́льно, одержавши пізна́ння правди, то вже за гріхи не знахо́диться жертви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 27, 'а страшливе якесь сподіва́ння су́ду та гнів палю́чий, що має пожерти противників.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 28, 'Хто відкидає Зако́на Мойсея, такий немилосердно вмирає „при двох чи трьох свідках“, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 29, 'скільки ж більшої му́ки, — доду́муєтеся? — заслуговує той, хто потоптав Сина Божого, і хто кров заповіту, що нею освячений, за звичайну вважав, і хто Духа благодаті зневажив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 30, 'Бо знаємо Того, Хто сказав: „Мені помста належить, Я відплачу́, говорить Господь“. І ще: „Господь буде судити наро́да Свого“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 31, 'Страшна́ річ — упасти в руки Бога Живого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 32, 'Згадайте ж про перші дні ваші, як ви просвітилися й витерпіли запеклу боротьбу стражда́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 33, 'Ви були́ то видо́вищем зневаги й знуща́ння, то були́ учасниками тих, що жили́ так.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 34, 'Ви бо страждали й з ув\'язненими, і грабу́нок свого майна́ прийняли́ з потіхою, відаючи, що маєте в небі для себе майно немину́ще та краще.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 35, 'Тож не відкидайте відваги своєї, бо має велику нагоро́ду вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 36, 'Бо вам терпеливість потрібна, щоб Божу волю вчинити й прийняти обітницю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 37, 'Бо ще „мало, дуже мало, і Той, хто має прийти, при́йде й бари́тись не бу́де!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 38, 'А „праведний житиме вірою“. І: „Коли захитається він, то душа Моя його не вподо́бає“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 10, 39, 'Ми ж не з тих, хто хитається на заги́біль, але віруємо на спасі́ння душі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 1, 'А віра — то підста́ва споді́ваного, доказ неба́ченого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 2, 'Бо нею засвідчені ста́рші були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 3, 'Вірою ми розуміємо, що віки́ Словом Божим збудовані, так що з невидимого сталось видиме.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 4, 'Вірою Авель приніс Богові жертву кращу, як Ка́їн; нею засвідчений був, що він праведний, як Бог сві́дчив про да́ри його; нею, і вмерши, він ще промовляє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 5, 'Вірою Ено́х був перене́сений на небо, щоб не бачити смерти; і його не знайшли, бо Бог переніс його. Бо раніш, як його перенесено, він був засвідчений, що „Богові він догоди́в“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 6, 'Догоди́ти ж без віри не можна. І той, хто до Бога приходить, мусить вірувати, що Він є, а тим, хто шукає Його, Він дає нагороду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 7, 'Вірою Ной, як дістав об\'я́влення про те, чого́ ще не бачив, побоявшись, зробив ковчега, щоб дім свій спасти́; нею світ засудив він, і став спадкоє́мцем праведности, що з віри вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 8, 'Вірою Авраа́м, покликаний на місце, яке мав прийняти в спа́дщину, послухався та й пішов, не відаючи, куди йде.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 9, 'Вірою він перебува́в на Землі Обі́цяній, як на чужій, і проживав у наме́тах з Іса́ком та Яковом, співспадкоє́мцями тієї ж обі́тниці,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 10, 'бо чекав він міста, що має підва́лини, що Бог його будівни́чий та творе́ць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 11, 'Вірою й Са́ра сама дістала силу прийняти насіння, і породила понад час свого віку, бо вірним вважала Того, Хто обі́тницю дав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 12, 'Тому́ й від одно́го, та ще змертвілого, народилось так багато, як зо́рі небесні й пісок незчисле́нний край моря.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 13, 'Усі вони повмирали за вірою, не оде́ржавши обі́тниць, але зда́лека бачили їх, і повітали, і ві́рували в них, та визнавали, що „вони на землі чужани́ці й прихо́дьки“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 14, 'Бо ті, що говорять таке, виявляють, що шукають ба́тьківщини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 15, 'І коли б вони пам\'ятали ту, що вийшли з неї, то мали б час повернутись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 16, 'Та бажають вони тепер кращої, цебто небесної, тому́ й Бог не соро́миться їх, щоб звати Себе їхнім Богом, бо Він приготува́в їм місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 17, 'Вірою Авраа́м, випробо́вуваний, привів на жертву Ісака, і, мавши обі́тницю, приніс одноро́дженого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 18, 'що йому було сказано: „В Ісакові буде насіння тобі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 19, 'Бо він розумі́в, що Бог має силу й воскресити з мертвих, тому й одержав його на проо́браз.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 20, 'Вірою в майбу́тнє поблагословив Іса́к Якова та Іса́ва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 21, 'Вірою Яків, умираючи, поблагословив кожного сина Йо́сипового, і „схилився на верх свого́ жезла.“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 22, 'Вірою Йо́сип, умираючи, згадав про ви́хід синів Ізра́їлевих та про кості свої запові́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 23, 'Вірою Мойсе́й, як родився, перехо́вувався батьками своїми три місяці, бо вони бачили, що гарне дитя, і не злякались нака́зу царе́вого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 24, 'Вірою Мойсе́й, коли виріс, відрікся зватися сином дочки́ фарао́нової.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 25, 'Він хотів краще страждати з наро́дом Божим, аніж мати доча́сну гріховну потіху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 26, 'Він наругу Христову вважав за більше багатство, ніж ска́рби єгипетські, бо він озирався на Божу нагороду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 27, 'Вірою він покинув Єгипет, не злякавшися гніву царе́вого, бо він був непохитний, як той, хто Невиди́мого бачить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 28, 'Вірою справив він Пасху й покро́плення крови, щоб їх не торкнувся той, хто погубив первороджених.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 29, 'Вірою вони перейшли Червоне море, немов суходо́лом, на що спокусившись єги́птяни, потопились.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 30, 'Вірою впали єрихо́нські му́ри по семиденнім обхо́дженні їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 31, 'Вірою блудни́ця Раха́в не згинула з невірними, коли з миром прийняла́ виві́дувачів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 32, 'І що ще скажу́? Бо не стане ча́су мені, щоб оповіда́ти про Гедео́на, Вара́ка, Самсо́на, Ефта́я, Дави́да й Самуї́ла та про пророків,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 33, 'що вірою ца́рства побива́ли, правду чинили, оде́ржували обі́тниці, пащі левам загороджували,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 34, 'силу огне́нну гасили, утікали від ві́стря меча, зміцнялись від слабости, хоробрі були́ на війні, оберта́ли в розтіч полки́ чужоземців;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 35, 'жінки діставали поме́рлих своїх із воскресі́ння; а інші бували скатовані, не прийнявши визво́лення, щоб отримати краще воскресі́ння;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 36, 'а інші дізнали наруги та рани, а також кайда́ни й в\'язниці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 37, 'Камінням побиті бува́ли, допитувані, перепи́лювані, умирали, зару́бані мече́м, тинялися в овечих та ко́зячих шкурах, збідовані, засумовані, витерпілі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 38, 'Ті, що світ не вартий був їх, тинялися по пустинях та го́рах, і по печерах та прова́ллях зе́мних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 39, 'І всі вони, одержавши засвідчення вірою, обі́тниці не прийняли́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 11, 40, 'бо Бог передбачив щось краще про нас, — щоб вони не без нас досконалість оде́ржали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 1, 'Тож і ми, мавши навколо себе велику таку хмару свідків, скиньмо всякий тяга́р та гріх, що обплутує нас, та й біжім з терпеливістю до боротьби, яка перед нами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 2, 'дивлячись на Ісуса, на Начальника й Виконавця віри, що замість радости, яка була перед Ним, перете́рпів хреста, не звертавши уваги на сором, і сів по правиці престолу Божого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 3, 'Тож подумайте про Того, хто перете́рпів такий перекір проти Себе від грішних, щоб ви не знемоглись, і не впали на душах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 4, 'Ви ще не змага́лись до крови, борю́чись проти гріха,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 5, 'і забули на́гад, що говорить до вас, як синів: „Мій сину, — не нехтуй Господньої кари, і не знемагай, коли Він докоря́є тобі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 6, 'Бо Господь, кого любить, того Він карає, і б\'є кожного сина, якого приймає“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 7, 'Коли те́рпите кару, то ро́бить Бог вам, як синам. Хіба є такий син, що ба́тько його не карає?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 8, 'А коли ви без кари, що спільна для всіх, то ви діти з пере́любу, а не сини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 9, 'А до того, ми мали батьків, що карали наше тіло, — і боялися їх, то чи ж не далеко більше повинні кори́тися ми Отцеві ду́хів, щоб жити?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 10, 'Ті нас за короткого ча́су карали, як їм до вподоби було́, Цей же на ко́ристь, щоб ми стали учасниками Його святости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 11, 'Усяка кара в тепе́рішній час не здається потіхою, але смутком, та згодом для на́вчених нею приносить ми́рний плід праведности!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 12, 'Тому́ то „опущені руки й коліна знемо́жені ви́простуйте“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 13, 'і „чиніть прості стежки́ ногам вашим“, щоб кульгаве не збо́чило, але краще ви́правилось.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 14, 'Пильнуйте про мир зо всіма, і про святість, без якої ніхто не побачить Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 15, 'Дивіться, щоб хто не зостався без Божої благода́ті, щоб „не виріс який гіркий корінь і не наробив непоко́ю“, і щоб багато-хто не опога́нились тим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 16, 'Щоб не був хто блудник чи безбожник, немов той Ісав, що своє перворі́дство віддав за поживу саму́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 17, 'Бо знаєте ви, що й після, як схотів він успадкува́ти благослове́ння, відкинутий був, — не знайшов бо був можливости до покая́ння, хоч його з слі́зьми шукав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 18, 'Бо ви не приступили до гори дотика́льної та до палю́чого огню, і до хмари, і до те́мряви, та до бурі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 19, 'і до сурмо́вого звуку, і до голосу слів, що його ті, хто чув, просили, щоб більше не мовилось слово до них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 20, 'Не могли бо вони того витримати, що наказано: „Коли й звірина́ до гори доторкне́ться, то буде камінням побита“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 21, 'І таке страшне́ те видіння було́, що Мойсей проказав: „Я боюся й тремчу́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 22, 'Але ви приступили до гори Сіонської, і до міста Бога Живого, до Єрусалиму небесного, і до десятків тисяч анголів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 23, 'і до Церкви первороджених, на небі написаних, і до Судді всіх — до Бога, і до духів удоскона́лених праведників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 24, 'і до Посере́дника Ново́го Заповіту — до Ісуса, і до покро́плення крови, що краще промовляє, як А́велева.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 25, 'Глядіть, не відверта́йтеся від того, хто промовляє. Бо як не повтікали вони, що зреклися того, хто звіщав на землі, то тим більше ми, якщо зрікаємся Того, Хто з неба звіщає,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 26, 'що голос Його захитав тоді землю, а тепер обіцяв та каже: „Ще раз захитаю не тільки землею, але й небом“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 27, 'А „ще раз“визначає заміну захитаного, як ство́реного, щоб зосталися ті, хто непохитний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 28, 'Отож ми, що приймаємо царство непохитне, нехай маємо благода́ть, що нею приємно служитимемо Богові з побожністю й зо стра́хом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 12, 29, 'Бо наш Бог — то „палю́чий огонь“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 1, 'Братолю́бство нехай пробува́є між вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 2, 'Не забувайте любови до при́ходнів, бо деякі нею, на́віть не ві́даючи, гостинно прийняли а́нголів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 3, 'Пам\'ятайте про в\'я́знів, немов із ними були б ви пов\'язані, про тих, хто страждає, як такі, що й самі ви знахо́дитесь в тілі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 4, 'Нехай буде в усіх че́сний шлюб та ложе непоро́чне, а блу́дників та пере́любів судитиме Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 5, 'Будьте життям не грошолюбні, задовольняйтеся тим, що́ маєте. Сам бо сказав: „Я тебе не покину, ані не відступлю́ся від тебе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 6, 'Тому́ то ми сміливо говоримо: „Господь — мені Помічни́к, і я не злякаюсь ніко́го: що зробить люди́на мені?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 7, 'Спогадуйте наставників ваших, що вам говорили Слово Боже; і, дивлячися на кінець їхнього життя, переймайте їхню віру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 8, 'Ісус Христос учора, і сьогодні, і навіки Той Са́мий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 9, 'Не захоплюйтеся всілякими та чужими науками. Бо річ добра зміцняти серця благода́ттю, а не стра́вами, що ко́ристи від них не оде́ржали ті, хто за ними ходив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 10, 'Маємо же́ртівника, що від нього годуватися права не мають ті, хто скинії служить, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 11, 'бо котри́х звірят кров первосвященик уносить до святині за гріхи, тих м\'ясо па́литься поза табо́ром, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 12, 'тому́ то Ісус, щоб кров\'ю Своєю людей освятити, постраждав поза брамою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 13, 'Тож виходьмо до Нього поза та́бір, і наругу Його понесімо,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 14, 'бо постійного міста не маємо тут, а шукаємо майбутнього!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 15, 'Отож, за́вжди приносьмо Богові жертву хвали́, цебто плід уст, що Ім\'я́ Його славлять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 16, 'Не забувайте ж і про доброчинність та спільність, бо жертви такі вгодні Богові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 17, 'Слухайтесь ваших наставників та коріться їм, — вони бо пильнують душ ваших, як ті, хто має здати справу. Нехай вони роблять це з радістю, а не зідхаючи, — бо це для вас не кори́сне.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 18, 'Моліться за нас, бо наді́ємося, що ми маємо добре сумління, бо хочемо добре в усьому пово́дитись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 19, 'А надто прошу́ це робити, щоб шви́дше до вас мене ве́рнено.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 20, 'Бог же миру, що з мертвих підняв великого Па́стиря вівцям кров\'ю вічного заповіту, Господа нашого Ісуса,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 21, 'нехай вас удоскона́лить у кожному доброму ділі, щоб волю чинити Його, чинячи в вас любе перед лицем Його через Ісуса Христа, Якому слава на віки вічні. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 22, 'Благаю ж вас, браття, прийміть слово поті́хи, бо коротко я написав вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 23, 'Знайте, що наш брат Тимофі́й вже ви́пущений, і я з ним; коли незаба́ром він при́йде, я вас побачу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 24, 'Вітайте всіх ваших наставників та всіх святих. Вітають вас ті, хто в Італії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 13, 25, 'Благодать зо всіма́ вами! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Яків, раб Бога й Господа Ісуса Христа, дванадцятьом племена́м, які в Розпоро́шенні, — вітаю я вас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'Майте, бра́ти мої, повну радість, коли впадаєте в усілякі випробо́вування,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'знаючи, що досвідчення вашої віри дає терпеливість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'А терпеливість нехай має чин доскона́лий, щоб ви досконалі та бездоганні були́, і недостачі ні в чому не мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'А якщо кому з вас не стачає мудрости, нехай просить від Бога, що всім дає просто, та не докоряє, — і бу́де вона йому да́на.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'Але нехай просить із вірою, без жодного су́мніву. Бо хто має су́мнів, той подібний до морської хвилі, яку жене й кидає вітер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Нехай бо така люди́на не гадає, що дістане що́ від Господа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'Двоєдушна люди́на непостійна на всіх дорогах своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'А понижений брат нехай хвалиться висо́кістю своєю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'а багатий — пони́женням своїм, бо він промине, як той цвіт трав\'яни́й, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'бо сонце зійшло зо спеко́тою, і траву посушило, — і відпав цвіт її, і зникла краса́ її виду. Так само зів\'яне й багатий у дорогах своїх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Блаженна люди́на, що ви́терпить пробу, бо, бувши ви́пробувана, дістане вінця життя, якого Господь обіцяв тим, хто любить Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Ви́пробовуваний, хай не каже ніхто: „Я від Бога споку́шуваний“. Бо Бог злом не спокушується, і нікого Він Сам не спокушує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'Але кожен спокушується, як на́диться й зво́диться пожадливістю власною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'Пожадли́вість пото́му, зачавши, народжує гріх, а зроблений гріх народжує смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'Не обма́нюйтесь, брати мої любі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 17, 'Усяке добре дава́ння та дар досконалий похо́дить згори від Отця світил, що в Нього нема переміни чи тіні відміни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 18, 'Захотівши, Він нас породив словом правди, щоб ми стали якимсь первопло́дом творів Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 19, 'Отож, мої брати́ любі, нехай буде кожна людина швидка́ послухати, забарна́ говорити, повільна на гнів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 20, 'Бо гнів лю́дський не чинить праведности Божої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 21, 'Тому́ то відкиньте всіляку нечисть та залишок злоби́, і прийміть із ла́гідністю всіяне слово, що може спасти ваші душі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 22, 'Будьте ж викона́вцями слова, а не слухачами самими, що себе самих обманюють.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 23, 'Бо хто слуха́ч слова, а не викона́вець, той подібний люди́ні, що риси обличчя свого розглядає у дзе́ркалі, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 24, 'бо розгляне себе та й віді́йде, і зараз забуде, яка вона є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 25, 'А хто заглядає в зако́н досконалий, закон волі, і в нім пробуває, той не буде забу́дько слухач, але виконавець ді́ла, — і він буде блаженний у дія́нні своїм!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 26, 'Коли ж хто гада́є, що він побожний, і свого язика не вгамо́вує, та своє серце обманює, — марна́ побожність того́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 27, 'Чиста й непорочна побожність перед Богом і Отцем оця: згля́нутися над си́ротами та вдови́цями в утисках їхніх, себе берегти чистим від світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Брати́ мої, не зважаючи на обличчя, майте віру в нашого Господа слави, Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Бо коли до вашого зібра́ння ввійде чоловік із золотим перснем, у шаті блискучій, увійде й біда́р у вбогім вбранні́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'і ви поглянете на то́го, хто в шаті блискучій, і скажете йому: „Ти сідай вигі́дно отут,“а бідаре́ві прокажете: „Ти стань там, чи сідай собі тут на підніжку моїм“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'то чи не стало між вами поді́лення, і не стали ви злоду́мними суддями?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Послухайте, мої брати любі, — чи ж не вибрав Бог бідарі́в цього світу за багатих вірою й за спадкоє́мців Царства, яке обіцяв Він тим, хто любить Його?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'А ви бідаря́ зневажили! Хіба не багачі переслідують вас, хіба не вони тягнуть вас на суди́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Хіба не вони зневажають те добре ім\'я́, що ви ним називаєтесь?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'Коли ви Зако́на Царсько́го виконуєте, за Писа́нням: „Люби свого ближнього, як самого себе“, то ви робите добре.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Коли ж дивитеся на обличчя, то чините гріх, бо Зако́н удоводнює, що ви винуватці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Бо хто всього Зако́на виконує, а згрішить в одно́му, той винним у всьому стає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Бо Той, Хто сказав: „Не чини перелю́бства“, також наказав: „Не вбивай“. А хоч ти перелю́бства не чиниш, а вб\'єш, то ти переступник Зако́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'Отак говоріть і отак чиніть, як такі, що будете суджені зако́ном волі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'Бо суд немилосердний на того, хто не вчинив милосердя. Милосердя бо ставиться вище за суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'Яка ко́ристь, брати мої, коли хто говорить, що має віру, але діл не має? Чи може спасти його віра?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Коли ж брат чи сестра будуть нагі, і позбавлені денного по́корму,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 16, 'а хтонебудь із вас до них скаже: „Ідіть з миром, грійтесь та їжте“, та не дасть їм потрібного тілу, — що ж то поможе?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 17, 'Так само й віра, коли діл не має, — ме́ртва в собі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 18, 'Але скаже хтоне́будь: „Маєш ти віру, а я маю діла; покажи мені віру свою без діл твоїх, а я покажу тобі віру свою від діл моїх“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 19, 'Чи віруєш ти, що Бог один? Добре робиш! Та й де́мони вірують, — і тремтять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 20, 'Чи хочеш ти знати, о марна́ люди́но, що віра без діл — ме́ртва?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 21, 'Авраам, отець наш, — чи він не з діл виправданий був, як поклав був на же́ртівника свого сина Ісака?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 22, 'Чи ти бачиш, що віра помогла його ділам, і вдоскона́лилась віра із діл?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 23, 'І зді́йснилося Писа́ння, що каже: „Авраам же ввірував Богові, і це йому зараховане в праведність, і був на́званий він другом Божим“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 24, 'Отож, чи ви бачите, що люди́на виправдується від діл, а не тільки від віри?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 25, 'Чи так само і блудни́ця Раха́в не з діл виправдалась, коли прийняла́ посланці́в, і дорогою іншою випустила?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 26, 'Бо як тіло без духа ме́ртве, так і віра без діл — мертва!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Не багато-хто ставайте, брати мої, учителями, знавши, що більший о́суд при́ймемо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'Бо багато ми всі помиляємось. Коли хто не помиляється в слові, то це муж досконалий, спроможний прибо́ркувати й усе тіло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'От і ко́ням вкладаєм узде́чки до ро́та, щоб корилися нам, і ми всім їхнім тілом керуємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'От і кораблі, хоч які величезні та гнані вітра́ми жорсто́кими, проте найменшим сте́рном скеро́вуються, куди хоче стерни́чий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'Так само й язик, — малий член, але хва́литься ве́льми! Ось маленький огонь, а запалює величезного ліса!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'І язик — то огонь. Як світ неправости, поста́влений так поміж нашими членами, язик скверни́ть усе тіло, запалює круг життя, і сам запалюється від геєнни.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'Бо всяка природа звірі́в і пташо́к, гадів і мо́рських потвор прибо́ркується, і прибо́ркана буде природою лю́дською,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'та не може ніхто із людей язика вгамува́ти, — він зло безупи́нне, він повний отрути смерте́льної!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Ним ми благословляємо Бога й Отця, і ним проклинаєм людей, що створені на Божу подобу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'Із тих самих уст виходить благослове́ння й прокля́ття. Не повинно, брати́ мої, щоб так це було́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'Хіба з одно́го отвору виходить вода солодка й гірка́?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Хіба може, бра́ти мої, фіґове дерево родити оливки, або виноград — фіґи? Солодка вода не тече з солонця́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Хто мудрий і розумний між вами, нехай він покаже діла́ свої в ла́гідній мудрості добрим поводженням!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Коли ж гірку́ заздрість та сварку ви маєте в серці своєму, то не величайтесь та не говоріть неправди на правду, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'це не мудрість, що ніби зве́рху походить вона, але земна, тілесна та де́монська.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 16, 'Бо де за́здрість та сварка, там бе́злад та всяка зла річ!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 17, 'А мудрість, що зверху вона, насамперед чиста, а потім спокійна, ла́гідна, покірлива, повна милосердя та добрих пло́дів, безстороння та нелукава.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 18, 'А плід праведности сіється творцями миру.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 1, 'Звідки ві́йни та свари між вами? Чи не звідси, — від ваших пожадливостей, які в ваших членах воюють?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 2, 'Бажаєте ви — та й не маєте, убиваєте й за́здрите — та досягнути не можете, сва́ритеся та воюєте — та не маєте, бо не проха́єте,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 3, 'прохаєте — та не одержуєте, бо прохаєте на зле, щоб ужити на розко́ші свої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 4, 'Перелю́бники та перелю́бниці, чи ж ви не знаєте, що дружба зо світом — то ворожнеча супроти Бога? Бо хто хоче бути світові при́ятелем, той ворогом Божим стається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 5, 'Чи ви ду́маєте, що даремно Писа́ння говорить: „Жада́є аж до за́здрости Дух, що в нас пробуває“?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 6, 'Та ще більшу благода́ть дає, через що й промовляє: „Бог противиться гордим, а смиренним дає благода́ть“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 7, 'Тож підкоріться Богові та спротивляйтесь дияволові, — то й утече він від вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 8, 'Набли́зьтесь до Бога, то й Бог набли́зиться до вас. Очистьте руки, грішні, та серця освятіть, двоєдушні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 9, 'Журіться, сумуйте та плачте! Хай обернеться сміх ваш у плач, а радість у сум!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 10, 'У покорі́ться перед Господнім лицем, — і Він вас підійме!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 11, 'Не обмовляйте, брати, один о́дного! Бо хто брата свого обмовляє або судить брата, той Зако́на обмовляє та судить Зако́на. А коли ти Зако́на осуджуєш, то ти не викона́вець Закона, але суддя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 12, 'Один Законода́вець і Суддя, що може спасти й погубити. А ти хто такий, що осуджуєш ближнього?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 13, 'А ну тепер ви, що говорите: „Сьогодні чи взавтра ми пі́дем у те чи те місто, і там рік проживе́мо, та бу́демо торгувати й заробляти“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 14, 'ви, що не відаєте, що́ трапиться взавтра, — яке ваше життя? Бо це пара, що на хвильку з\'явля́ється, а потім зникає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 15, 'Замість того, щоб вам говорити: „Як схоче Госпо́дь та бу́демо живі, то зробимо це або те“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 16, 'А тепер ви хва́литеся в своїх го́рдощах, — лиха́ всяка подібна хвальба́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 17, 'Отож, хто знає, як чинити добро, та не чинить, — той має гріх!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 1, 'А ну ж тепер ви, багачі́, — плачте й ридайте над лихом своїм, що вас має спіткати:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 2, 'ваше багатство згнило, а ваші вбрання́ міль поїла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 3, 'Золото ваше та срі́бло поіржа́віло, а їхня іржа буде сві́дчити проти вас, і поїсть ваше тіло, немов той огонь! Ви скарби зібрали собі на останні дні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 4, 'Ось голосить заплата, що ви затримали в робі́тників, які жали на ваших полях, — і голосі́ння женці́в досягли́ вух Господа Савао́та!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 5, 'Ви розкошували на землі й насолоджувались, серця свої ви́годували, немов би на день зако́лення.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 6, 'Ви Праведного засудили й убили, — Він вам не проти́вився!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 7, 'Отож, браття, довготерпіть аж до при́ходу Господа! Ось чекає рільни́к дорогоцінного пло́ду землі, довготе́рпить за нього, аж поки оде́ржить дощ ранній та пізній.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 8, 'Довготерпі́ть же й ви, зміцніть серця ваші, бо набли́зився при́хід Господній!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 9, 'Не нарікайте один на о́дного, браття, щоб вас не засу́джено, — он Суддя стоїть перед дверима!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 10, 'Візьміть, браття, пророків за при́клад стражда́ння та довготерпі́ння, — вони промовляли Господнім Ім\'я́м!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 11, 'Отож, за блаженних ми маємо тих, хто витерпів. Ви чули про Йо́вове терпі́ння та бачили Господній кінець його́, що „ве́льми Господь милости́вий та щедрий“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 12, 'А найперше, браття мої, не кляніться ні небом, ані землею, і ніякою іншою клятвою! Слово ж ваше хай буде: „Так, так“та „Ні, ні“, щоб не впасти вам в о́суд.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 13, 'Чи страждає хто з вас? Нехай молиться! Чи тішиться хтось? Хай співає псалми́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 14, 'Чи хворі́є хто з вас? Хай покличе пресвітерів Церкви, і над ним хай помоляться, намасти́вши його оливою в Господнє Ім\'я́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 15, 'і молитва віри вздоро́вить недужого, і Господь його піді́йме, а коли він гріхи був учинив, то вони йому простяться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 16, 'Отже, признава́йтесь один перед о́дним у своїх про́гріхах, і моліться один за о́дного, щоб вам уздоро́витись. Бо дуже могутня ре́вна молитва праведного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 17, 'Ілля́ був люди́на, подібна до нас при́страстями, і він помолився молитвою, щоб дощу́ не було́, — і дощу не було́ на землі аж три роки й шість місяців...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 18, 'І він знов помолився, — і дощу́ дало́ небо, а земля вродила свій плід!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 19, 'Бра́ття мої, — коли хто з-поміж вас заблудить від правди, і його хто наверне,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 20, 'хай знає, що той, хто грішника навернув від його блу́дної дороги, той душу його спасає від смерти та бе́зліч гріхів покриває!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, 'Петро, апо́стол Ісуса Христа, захожа́нам Розпоро́шення: По́нту, Гала́тії, Каппадокі́ї, Азії й Віфі́нії, ви́браним');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'із передба́чення Бога Отця, посвя́ченням Духа, на покору й окро́плення кров\'ю Ісуса Христа: нехай примно́житься вам благодать та мир!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'Благословенний Бог і Отець Господа нашого Ісуса Христа, що великою Своєю милістю відродив нас до живої надії через воскре́сення з мертвих Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'на спа́дщину нетлінну й непорочну та нев\'яну́чу, заховану в небі для вас,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, 'що ви бережені силою Божою через віру на спасі́ння, яке готове з\'явитися останнього ча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'Тіштеся з того, засмучені тро́хи тепер, якщо треба, всілякими випробо́вуваннями,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'щоб досвідчення вашої віри було дорогоцінніше за золото, яке гине, хоч і огнем випробо́вується, на похвалу́, і честь, і славу при з\'я́вленні Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'Ви Його любите, не бачивши, і віруєте в Нього, хоч тепер не бачите, а вірувавши, радієте невимо́вною й славною радістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'бо досяга́єте мети́ віри вашої — спасі́ння ду́шам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, 'Про це спасі́ння розвідували та допитувалися пророки, що звіщали про благода́ть, призначену вам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'Вони досліджували, на котри́й чи на який час показував Дух Христів, що в них був, коли Він сповіщав про Христові стражда́ння та славу, що при́йдуть по них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'Їм відкрито було́, що вони не для себе сами́х, а для вас служили тим, що тепер звіщено вам через благові́сників Духом Святим, із неба посланим, на що бажають дивитися анголи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Тому́ то, підперезавши сте́гна свого розуму та бувши тверезі, майте досконалу надію на благода́ть, що прино́ситься вам в з\'я́вленні Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'Як слухняні, не застосовуйтеся до попередніх пожадливо́стей вашого неві́дання,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'але за Святим, що покликав вас, будьте й самі святі в усім вашім пово́дженні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, 'бо написано: „Будьте святі, — Я бо святий“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 17, 'І коли ви Отцем звете Того, Хто кожного, не зважаючи на особу, судить за вчинок, то в страху́ провадьте час вашого тимчасового заме́шкання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 18, 'I знайте, що не тлінним сріблом або золотом відкуплені ви були від марно́го вашого життя, що передане вам від батьків,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 19, 'але дорогоцінною кров\'ю Христа, як непорочного й чистого Ягняти,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 20, 'що призначений був іще перед закла́динами світу, але був з\'явлений вам за останнього ча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 21, 'Через Нього ви віруєте в Бога, що з мертвих Його воскресив та дав славу Йому, щоб була ваша віра й надія на Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 22, 'По́слухом правді очистьте душі свої через Духа на нелицемірну братерську любов, і ревно від щирого серця любіть один о́дного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 23, 'бо народжені ви не з тлінного насіння, але з нетлінного, — Словом Божим живим та тривалим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 24, 'Бо „кожне тіло — немов та трава, і всяка слава люди́ни — як цвіт трав\'яни́й: засохне трава — то й цвіт опаде,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 25, 'а Слово Господнє повік пробуває“! А це те Слово, яке звіщене вам у Єва́нгелії.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 1, 'Отож, відкладіть усяку зло́бу, і всякий пі́дступ, і лицемірство, і заздрість, і всякі обмови,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 2, 'і, немов новонароджені немовлята, жадайте щирого духовного молока, щоб ним вирости вам на спасі́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 3, 'якщо ви спро́бували, що добрий Госпо́дь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 4, 'Приступайте до Нього, до Каменя живого, дорогоцінного, що відкинули люди Його, але вибрав Бог.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 5, 'І самі, немов те каміння живе, будуйтеся в дім духовий, на священство святе, щоб прино́сити жертви духовні, приємні для Бога через Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 6, 'Бо стоїть у Писа́нні: „Ось кладу́ Я на Сіоні Каменя вибраного, наріжного, дорогоцінного, і хто вірує в Нього, той не буде осоро́млений“!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 7, 'Отож бо, для вас, хто вірує, Він коштовність, а для тих, хто не вірує — „камінь, що його занедба́ли були будівничі, той наріжним став каменем“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 8, 'і „камінь спотика́ння, і скеля спокуси“, — і об нього вони спотика́ються, не вірячи слову, на що й призначені були.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 9, 'Але ви — ви́браний рід, свяще́нство царське́, наро́д святий, люд власности Божої, щоб звіщали чесно́ти Того, Хто покликав вас із те́мряви до дивного світла Свого́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 10, 'колись „ненаро́д,“а тепер наро́д Божий, колись „непомилувані,“а тепер ви помилувані!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 11, 'Благаю вас, любі, як прихо́дьків та подорожніх, щоб ви зде́ржувались від тілесних пожадли́востей, що воюють проти душі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 12, 'Поводьтеся поміж поганами добре, щоб за те, за що́ вас обмовляють вони, немов би злочинців, побачивши добрі діла, сла́вили Бога в день відві́дання.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 13, 'Отож, коріться кожному лю́дському творі́нню ради Господа, — чи то цареві, як найвищому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 14, 'чи то володарям, як від нього по́сланим для кара́ння злочинців та для похвали́ доброчинців.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 15, 'Бо така Божа воля, щоб доброчинці гамували не́уцтво нерозумних людей, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 16, 'як вільні, а не як ті, що мають волю на прикриття́ лихого, але як раби Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 17, 'Шануйте всіх, бра́тство любіть, Бога бійтеся, царя поважайте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 18, 'Раби, — коріться панам із повним стра́хом, не тільки добрим та тихим, але й прикрим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 19, 'Бо то вгодне, коли хто, через сумління перед Богом, те́рпить недолю, непоправді страждаючи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 20, 'Бо яка похвала́, коли те́рпите ви, як вас б\'ють за провини? Але коли з му́кою те́рпите за добрі вчинки, то це вгодне Богові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 21, 'Бо на це ви покликані. Бо й Христос постраждав за нас, і залиши́в нам при́клада, щоб пішли ми сліда́ми Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 22, '„Не вчинив Він гріха, і не знайшлося в устах Його пі́дступу!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 23, 'Коли був лихосло́влений, Він не лихословив взає́мно, а коли Він страждав, не погро́жував, але передав Тому, Хто судить справедливо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 24, 'Він тілом Своїм Сам підніс гріхи наші на дерево, щоб ми вмерли для гріхів та для праведности жили; Його „ранами ви вздоро́вилися“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 25, 'Ви бо були як ті вівці заблу́кані, та ви повернулись до Пастиря й Опікуна ваших душ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 1, 'Так само дружи́ни, — корі́ться своїм чоловікам, щоб і деякі, хто не ко́риться слову, були приєднані без слова пово́дженням дружи́н,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 2, 'як побачать ваше пово́дження чисте в страху́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 3, 'А окрасою їм нехай буде не зовнішнє, — запліта́ння волосся та наві́шання золота або вбира́ння одеж,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 4, 'але захо́вана люди́на серця в нетлінні ла́гідного й мовчазно́го духа, що дорогоцінне перед Богом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 5, 'Бо так само колись прикраша́ли себе й святі ті жінки́, що клали надію на Бога й кори́лись своїм чоловікам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 6, 'Так Сара корилась Авраамові, і паном його називала. А ви — її діти, коли добро робите та не лякаєтесь жа́дного стра́ху.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 7, 'Чоловіки, — так само живіть ра́зом із дружи́нами за розумом, як зо слабішою жіночою посудиною, і виявляйте їм честь, бо й вони є співспадкоє́миці благода́ті життя, щоб не спинялися ваші моли́тви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 8, 'Наре́шті ж, будьте всі одноду́мні, спочутливі, братолюбні, милосердні, покірливі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 9, 'Не платіть злом за зло, або лайкою за лайку, навпаки, — благословляйте, знавши, що на це вас покликано, щоб ви вспадкува́ли благослове́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 10, '„Бо хто хоче любити життя та бачити добрі дні, нехай здержить свого язика́ від лихого та у́ста свої від гово́рення пі́дступу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 11, 'Ухиляйся від злого та добре чини, шукай миру й женися за ним!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 12, 'Бо очі Господні — до праведних, а ву́ха Його — до їхніх прохань, а Господнє лице проти тих, хто чинить лихе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 13, 'І хто заподі́є вам зле, коли будете ви оборонцями доброго?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 14, 'А коли ви за праведність і страждаєте, то ви блаженні! „А їхнього стра́ху не бійтеся, і не тривожтеся!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 15, 'А Господа Христа освятіть у ваших серцях, і за́вжди готовими будьте на відповідь кожному, хто в вас запитає рахунку про надію, що в вас, із ла́гідністю та зо стра́хом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 16, 'Майте добре сумління, щоб тим, за що́ вас обмовляють, немов би злочинців, були посоромлені лихосло́вники вашого пово́дження в Христі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 17, 'Бо ліпше страждати за добрі діла, — коли хоче того Божа воля, — аніж за лихі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 18, 'Бо й Христос один раз постраждав був за наші гріхи, щоб приве́сти нас до Бога, Праведний за неправедних, хоч уме́ртвлений тілом, але Духом ожи́влений,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 19, 'Яким Він і ду́хам, що в в\'язниці були, зійшовши, звіщав;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 20, 'вони колись непокі́рливі були́, як їх Боже довготерпіння чекало за Но́євих днів, коли будувався ковче́г, що в ньому мало, цебто вісім душ, спаслось від води.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 21, 'Того образ, хрищення — не тілесної нечистости позбуття́, але обі́тниця Богові доброго сумління, — спасає тепер і нас воскресінням Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 22, 'що, зійшовши на небо, пробуває по Божій правиці, а Йому підкорилися анголи, влади та сили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 1, 'Отож, коли тілом Христос постраждав за нас, то озбройтеся й ви тією самою думкою, бо хто тілом постраждав, той перестав грішити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 2, 'щоб решту ча́су в тілі жити вже не для пожадливостей людських, а для Божої волі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 3, 'Бо до́сить минулого ча́су, коли ви чинили волю поган, ходили в розпусті, у пожадливостях, у пияцтві, у гу́лянках, у пия́тиках, у беззако́нних ідолослужбах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 4, 'Вони з того дивуються, що ви ра́зом із ними не берете участи в розпусті, та зневажають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 5, 'Вони дадуть відповідь Тому, Хто судитиме живих та мертвих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 6, 'Бо на те й мертвим зві́щувано Єва́нгелію, щоб вони прийняли́ суд по-лю́дському тілом, але жили́ по-Бо́жому духом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 7, 'Кінець же всьому набли́зився. Отже, будьте мудрі й пильнуйте в молитвах!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 8, 'Найперше майте щиру любов один до о́дного, бо любов покриває багато гріхів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 9, 'Будьте гостинні один до о́дного без не́хоті!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 10, 'Служіть один о́дному, кожен тим даром, якого отримав, як доморя́дники всілякої Божої благода́ті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 11, 'Коли хто говорить, говори, як Божі слова. Коли хто служить, то служи, як від сили, яку дає Бог, щоб Бог прославлявся в усьому Ісусом Христом, що Йому слава та вла́да на віки вічні, амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 12, 'Улюблені, не дивуйтесь огневі, що вам посилається на випробо́вування, немов би чужому випа́дку для вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 13, 'Але через те, що берете ви участь у Христових стражда́ннях, то тіштеся, щоб і в з\'я́вленні слави Його раділи ви й звеселялись.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 14, 'Коли ж вас ганьбля́ть за Христове Ім\'я́, то ви блаженні, бо на вас спочиває Дух слави й Дух Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 15, 'Ніхто з вас хай не страждає, як душогуб, або злодій, або злочинець, або ворохо́бник,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 16, 'а коли — як християни́н, то нехай не соро́миться він, але хай прославляє Бога за те.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 17, 'Бо час уже суд розпочати від Божого дому; а коли він почнеться перше з нас, то який кінець тих, хто противиться Божій Єва́нгелії?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 18, 'А коли „праведний ле́две спасеться, то безбожний та грішний де зможе з\'явитись?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 19, 'Тому й ті, хто з Божої волі страждає, нехай душі свої віддадуть в доброчинстві Йому, як Створителю вірному.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 1, 'Тож благаю між вами пресві́терів, співпресві́тер та свідок Христових стражда́нь, співучасник слави, що повинна з\'явитись:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 2, 'пасіть стадо Боже, що у вас, наглядайте не з примусу, але добровільно по-Божому, не для брудної наживи, а ревно,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 3, 'не пануйте над спа́дком Божим, але будьте для стада за взір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 4, 'А коли Архипа́стир з\'я́виться, то одержите ви нев\'яну́чого вінка́ слави.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 5, 'Також молоді, — коріться ста́ршим! А всі майте покору один до о́дного, бо „Бог проти́виться гордим, а смиренним дає благода́ть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 6, 'Тож покоріться під міцну́ Божу руку, щоб Він вас Свого ча́су пови́щив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 7, 'Покладіть на Нього всю вашу журбу́, бо Він опікується вами!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 8, 'Будьте твере́зі, пильнуйте! Ваш супроти́вник — диявол — ходить, ричучи́, як лев, що шукає пожерти кого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 9, 'Противтесь йому́, тверді в вірі, знавши, що ті самі му́ки трапляються й вашому братству по світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 10, 'А Бог усякої благодаті, що покликав вас до вічної слави Своєї в Христі, нехай Сам удоскона́лить вас, хто трохи поте́рпів, хай упе́внить, зміцни́ть, уґрунтує.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 11, 'Йому слава та вла́да на вічні віки, амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 12, 'Я коротко вам написав через Силуя́на, як гада́ю — вірного брата. Закликаю та свідчу, що це Божа благода́ть правдива, що ви в ній стоїте́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 13, 'Вітає вас ра́зом ви́брана Церква в Вавилоні, і Ма́рко, мій син.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 14, 'Вітайте один о́дного поцілунком любови. Мир вам усім у Христі! Амінь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, 'Симеон Петро, раб та апо́стол Ісуса Христа, до тих, хто одержав із нами рівноці́нну віру в праведності Бога нашого й Спасителя Ісуса Христа:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'благодать вам та мир нехай примно́житься в пізна́нні Бога й Ісуса, Господа нашого!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'Усе, що потрібне для життя та побожности, подала́ нам Його Божа сила пізна́нням Того, Хто покликав нас славою та чесно́тою.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, 'Через них даро́вані нам цінні та великі обі́тниці, щоб ними ви стали уча́сниками Божої Істо́ти, утікаючи від пожадливого світового тління.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'Тому́ докладіть до цього всю пильність, і покажіть у вашій вірі чесно́ту, а в чесно́ті — пізна́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'а в пізнанні — стри́мання, а в стри́манні — терпеливість, а в терпеливості — благоче́стя,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'а в благочесті — брате́рство, а в братерстві — любов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, 'Бо коли це в вас є та примно́жується, то воно зробить вас нелінивими, ані безплідними для пізна́ння Господа нашого Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'А хто цього не має, той сліпий, короткозо́рий, він забув про очи́щення з своїх давніх гріхів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'Тому́, браття, тим більше дба́йте чинити міцни́м своє покли́кання та ви́брання, бо, ро́блячи так, ви ніко́ли не спіткне́тесь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'Бо щедро відкриється вам вхід до вічного Царства Господа нашого й Спасителя Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'Тому то ніко́ли я не зане́дбую про це вам нагадувати, хоч ви й знаєте, і впе́внені в тепе́рішній правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'Бо вважаю я за справедливе, доки я в цій оселі, спону́кувати вас нага́дуванням,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'знаючи, що я незаба́ром повинен покинути оселю свою, як і Госпо́дь наш Ісус Христос об\'явив мені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 15, 'А я пильнуватиму, щоб ви й по моє́му відхо́ді за́вжди мали це в пам\'яті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 16, 'Бо ми сповістили вам силу та прихід Господа нашого Ісуса Христа, не йдучи за хитро видуманими байка́ми, але бувши самови́дцями Його ве́личі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 17, 'Бо Він честь та славу прийняв від Бога Отця, як до Нього прийшов від величної слави голос такий: „Це Син Мій Улю́блений, що Його Я вподо́бав!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 18, 'І цей голос, що з неба зійшов, ми чули, як із Ним були на святій горі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 19, 'І ми маємо слово пророче певніше. І ви добре робите, що на нього вважаєте, як на світильника, що світить у темному місці, аж поки зачне розвидня́тися, і світова́ зірни́ця засяє у ваших серцях,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 20, 'бо ви знаєте перше про те, що жодне проро́цтво в Писа́нні від власного ви́яснення не залежить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 21, 'Бо проро́цтва ніко́ли не було з волі лю́дської, а звіщали його святі Божі му́жі, прова́джені Духом Святим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 1, 'А між людом були́ й неправдиві пророки, як і бу́дуть між вас учителі неправдиві, що впрова́дять згубні єресі, відречу́ться від Влади́ки, що викупив їх, і стягнуть на себе самі скору погибіль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 2, 'І багато-хто пі́дуть за пожадливістю їхньою, а через них доро́га правдива знева́житься.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 3, 'І в заже́рливості вони бу́дуть ловити вас словами обле́сними. Суд на них відда́вна не ба́риться, а їхня загибіль не дрімає!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 4, 'Бо як Бог анголі́в, що згрішили, не помилував був, а в кайда́нах те́мряви вкинув до а́ду, і передав зберігати на суд;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 5, 'і Він не помилував першого світу, а зберіг само во́сьмого Но́я, проповідника праведности, і навів пото́п на світ безбожних;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 6, 'і міста́ Содо́м і Гомо́рру спопели́в, засудивши на зни́щення, і дав при́клада для майбутніх безбожників,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 7, 'а врятував праведного Ло́та, змученого поводженням розпусних людей, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 8, 'бо цей праведник, живши між ними, день-у-день мучив свою праведну душу, ба́чачи й чуючи вчинки безбожні, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 9, 'то вміє Господь рятувати побожних від спокуси, а неправедних берегти на день суду для кари,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 10, 'а надто тих, хто ходить за нечистими пожадли́востями тіла та погорджує вла́дою; зухвалі свавільці, що не бояться зневажати слави,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 11, 'хоч анголи́, бувши міццю та силою більші за них, не несуть до Господа знева́жливого суду на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 12, 'Вони, немов звірина́ нерозумна, зроджена природою на зло́влення та загибіль, зневажають те, чого не розуміють, і в тлінні своїм будуть знищені,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 13, 'і при́ймуть запла́ту за лихі вчинки. Вони повсякденну розпусту вважають за ро́зкіш; самі бруд та неслава, вони насолоджуються своїми оманами, бенкету́ючи з вами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 14, 'Їхні очі напо́внені пере́любом та гріхом безупинним; вони зва́блюють душі незмі́цнені; вони, діти прокляття, мають серце, привче́не до заже́рливости.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 15, 'Вони покинули про́сту дорогу та й заблудили, і пішли слідо́м за Валаа́мом Бео́ровим, що полюбив нагороду несправедливости,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 16, 'але був докорений у своїм беззако́нні: німа під\'яре́мна ослиця проговорила лю́дським голосом, та й бе́зум пророка спинила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 17, 'Вони — джере́ла безводні, хмари, бурею гнані; для них пригото́ваний мо́рок те́мряви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 18, 'Бо, висло́влюючи марне́ базі́кання, вони зваблюють пожадливістю ті́ла й розпустою тих, хто ледве втік від тих, хто живе в розпусті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 19, 'Вони волю обіцюють їм, самі бувши рабами тління. Бо хто ким переможений, той тому й раб.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 20, 'Бо коли хто втече від нечистости світу через пізна́ння Господа й Спасителя Ісуса Христа, а пото́му знов заплутуються ними та перемагаються, — то останнє буває для них гірше першого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 21, 'Бо краще було б не пізнати їм дороги праведности, аніж, пізнавши, вернутись назад від пере́даної їм святої заповіді!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 22, 'Бо їм трапилося за правдивою при́казкою: „Вертається пес до своєї блюво́тини“, та: „Помита свиня йде валятися в калюжу“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 1, 'Це вже другого листа пишу́ я до вас, улюблені. У них нага́дуванням я буджу́ вашу чисту думку,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 2, 'щоб ви пам\'ятали слова́, що святі пророки давніше звістили їх вам, і заповідь Господа й Спасителя, що оде́ржали через ваших апо́столів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 3, 'Насампере́д знайте оце, що в останні дні при́йдуть із на́смішками глузії́, що ходитимуть за своїми пожадливостями,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 4, 'та й скажуть: „Де обі́тниця Його прихо́ду? Бо від того ча́су, як позасинали наші батьки, усе залиша́ється так від поча́тку творі́ння“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 5, 'Бо сховане від тих, хто хоче цього, що небо було напоча́тку, а земля із води та водою скла́дена словом Божим,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 6, 'тому́ тодішній світ, водою пото́плений, згинув.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 7, 'А теперішні небо й земля заховані тим самим словом, і зберігаються для огню на день суду й загибелі безбожних людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 8, 'Нехай же одне це не буде заховане від вас, улю́блені, що в Господа один день — немов тисяча ро́ків, а тисяча ро́ків — немов один день!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 9, 'Не ба́риться Госпо́дь із обі́тницею, як деякі вважають це барі́нням, але вам довготе́рпить, бо не хоче, щоб хто загинув, але щоб усі наверну́лися до каяття́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 10, 'День же Господній прибу́де, як злодій вночі, коли з гу́ркотом небо мине, а стихі́ї, розпе́чені, ру́нуть, а земля та діла, що на ній, погорять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 11, 'А коли все оце поруйнується, то якими мусите бути в святому житті та в побожності ви,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 12, 'що чекаєте й прагнете скорого прихо́ду Божого дня, в якім небо, палючися, зникне, а розпа́лені стихії розтопляться?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 13, 'Але за Його обі́тницею ми чекаємо неба ново́го й ново́ї землі, що праведність на них пробуває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 14, 'Тож, улю́блені, чека́ючи цього, попильнуйте, щоб ви знайшлися для Нього нескверні та чисті у мирі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 15, 'А довготерпіння Господа нашого вважайте за спасі́ння, як і улю́блений брат наш Павло написав був до вас за даною йому мудрістю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 16, 'як і по всіх посла́ннях, що в них він говорить про це. У них є дещо тя́жко зрозуміле, що не́уки та незміцнені перекручують, як і інші Писа́ння, на власну загибіль свою́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 17, 'Тож ви, улю́блені, знаючи це напере́д, стережіться, щоб не були ви зве́дені блу́дом безбожних і не відпали від свого вґрунтува́ння,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 18, 'але щоб зростали в благода́ті й пізна́нні Господа нашого й Спасителя Ісуса Христа. Йому слава і тепер, і дня вічного! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, 'Що́ було́ від поча́тку, що́ ми чули, що́ бачили власними очима, що́ розглядали, і чого руки наші торкалися, — про Слово життя, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'а життя з\'явилось, і ми бачили, і сві́дчимо, і звіщаємо вам життя вічне, що в Отця перебува́ло й з\'явилося нам, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'що́ ми бачили й чули — про те ми звіщаємо вам, щоб і ви мали спільність із нами. Спільність же наша з Отцем і Сином Його Ісусом Христом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'А це пишемо вам, щоб повна була́ ваша радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, 'А це звістка, що ми її чули від Нього і звіщаємо вам: Бог є світло, і немає в Нім жа́дної те́мряви!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'Коли ж кажемо, що маємо спільність із Ним, а ходимо в те́мряві, то неправду говоримо й правди не чинимо!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'Коли ж ходимо в світлі, як Сам Він у світлі, то маємо спільність один із о́дним, і кров Ісуса Христа, Його Сина, очищує нас від усякого гріха.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, 'Коли ж кажемо, що не маєм гріха́, то себе обманюємо, і немає в нас правди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Коли ми свої гріхи визнаємо, то Він вірний та праведний, щоб гріхи нам простити, та очистити нас від неправди всілякої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'А як кажемо, що ми не згрішили, то чинимо з Нього неправдомовця, і сло́ва Його нема в нас!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, 'Діточки мої, — це пишу́ я до вас, щоб ви не грішили! А коли хто згріши́ть, то маємо Заступника перед Отцем, — Ісуса Христа, Праведного.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Він ублага́ння за наші гріхи, і не тільки за наші, але й за гріхи всього світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'А що ми пізнали Його, пізнає́мо це з того, коли заповіді Його доде́ржуємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'Хто говорить: „Пізнав я Його“, але не доде́ржує Його заповідів, той неправдомовець, і немає в нім правди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, 'А хто доде́ржує Його слово, у тому Божа любов справді вдоскона́лилась. Із того ми пізнає́мо, що в Нім пробува́ємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'А хто каже, що в Нім пробува́є, той повинен пово́дитись так, як пово́дився Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Улю́блені, — не пишу́ я для вас нову́ заповідь, але заповідь давню, яку мали від поча́тку: заповідь давня, — то слово, що чули його від поча́тку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, 'Але нову́ заповідь я вам пишу́, що справді вона в Нім та в вас, — що минається те́мрява, і світло правдиве вже світить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'Хто говорить, що він пробува́є у світлі, та нена́видить брата свого, той у те́мряві досі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, 'А хто любить брата свого́, той пробува́є у світлі, і в ньому спотика́ння немає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Хто ж нена́видить брата свого, пробуває той у те́мряві й ходить у те́мряві, і не знає, куди він іде, бо те́мрява очі йому осліпила.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, 'Пишу́ я вам, ді́тоньки, що гріхи вам прощаються ради Йме́ння Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Пишу́ вам, батьки, бо ви пізнали Того, Хто від поча́тку. Пишу́ вам, юнаки́, бо перемогли ви лукавого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, 'Пишу́, діти, вам, бо ви пізнали Отця. Я писав вам, батьки, бо ви пізнали Того, Хто від поча́тку. Писав я до вас, юнаки́, бо міцні́ ви, і Слово Боже в вас пробуває, і лукавого перемогли ви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'Не любіть світу, ані того, що́ в світі. Коли любить хто світ, у тім немає любови Отцівської,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'бо все, що в світі: пожадливість тілесна, і пожадливість оча́м, і пиха́ життє́ва, — це не від Отця, а від світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Минається і світ, і його пожадли́вість, а хто Божу волю виконує, той повік пробува́є!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, 'Діти, — остання година! А що чули були́, що анти́христ іде, — а тепер з\'явилось багато анти́христів, — з цього ми пізнає́мо, що остання година настала!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 19, 'Із нас вони вийшли, та до нас не належали. Коли б були належали до нас, то залиши́лися б з нами; але вийшли, щоб відкрилось, що не всі вони наші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 20, 'А ви маєте пома́зання від Святого, і знаєте все.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 21, 'Я не писав вам, немов ви не знаєте правди, але що знаєте її, і що всяка лжа не від правди.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 22, 'Хто неправдомо́вець, як не той, хто відкидає, що Ісус є Христос? Це анти́христ, що відрікається Отця й Сина!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 23, 'Кожен, хто відрікається Сина, не має Отця; хто визнає́ Сина, той має Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 24, 'Тож, що́ ви чули з поча́тку, нехай в вас пробуває воно; якщо в вас пробува́тиме те, що́ ви чули з поча́тку, то й ви пробува́тимете в Сині й Отці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 25, 'А оце та обі́тниця, яку Він Сам обіцяв нам: вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 26, 'Це я написав вам про тих, хто обманює вас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 27, 'А пома́зання, яке прийняли́ ви від Нього, — воно в вас залиша́ється, і ви не потребу́єте, щоб вас хто навчав. А що те пома́зання само вас навчає про все, — воно бо правдиве и нехи́бне, — то я́к вас навчило воно, у тім пробувайте.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 28, 'А тепер, діточки, залишайтеся в Нім, щоб, як з\'явиться Він, то щоб ми мали відвагу та не були засоро́млені Ним під час Його прихо́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 29, 'Коли знаєте, що Він праведний, то знайте, що всякий, хто чинить праведність, народився від Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, 'Подивіться, яку любов дав нам Отець, щоб ми були дітьми́ Божими, і ними ми є. Світ нас не знає тому́, що Його не пізнав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'Улю́блені, — ми тепер Божі діти, але ще не виявилось, що́ ми будемо. Та знаємо, що, коли з\'я́виться, то бу́дем подібні до Нього, бо бу́демо бачити Його, як Він є.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'І кожен, хто має на Нього наді́ю оцю, очищає себе так же само, як чистий і Він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Кожен, хто чинить гріх, чинить і беззако́ння. Бо гріх — то беззако́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'І ви знаєте, що Він був з\'явився, щоб гріхи наші взяти, а гріха в Нім нема.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, 'Кожен, хто в Нім пробува́є, не грішить; усякий, хто грішить, не бачив Його, і не пізнав Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, 'Діточки, хай ніхто вас не зво́дить! Хто чинить праведність, той праведний, як праведний Він!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'Хто чинить гріх, той від диявола, бо диявол грішить від поча́тку. Тому́ то з\'явився Син Божий, щоб зни́щити справи диявола.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'Кожен, хто родився від Бога, не чинить гріха, бо в нім пробуває насіння Його. І не може грішити, бо від Бога наро́джений він.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'Цим пізнаю́ться діти Божі та діти дияволові: Кожен, хто нраведности не чинить, той не від Бога, як і той, хто брата свого не любить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'Бо це та звістка, яку від початку ви чули, — щоб любили один о́дного,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'не так, як той Каїн, що був від лукавого, і брата свого́ забив. А за що він забив його? Бо лукаві були його вчинки, а брата його — праведні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Не дивуйтеся, бра́ття мої, коли світ вас нена́видить!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, 'Ми знаємо, що ми перейшли від смертн в життя, бо любимо братів. А хто брата не любить, пробуває той в смерті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Кожен, хто нена́видить брата свого, той душогу́б. А ви знаєте, що жоден душогуб не має вічного життя, що в нім перебувало б.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'Ми з того пізнали любов, що ду́шу Свою́ Він покла́в був за нас. І ми мусимо класти ду́ші за братів!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'А хто має достаток на світі, і бачить брата свого в недостачі, та серце своє зачиняє від нього, то як Божа любов пробуває в такому?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'Ді́точки, — любімо не словом, ані язико́м, але ді́лом та правдою!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 19, 'Із цього дові́дуємось, що ми з правди, і впокорюєм наші серця́ перед Ним,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 20, 'бо коли винуватить нас серце, то Бог більший від нашого серця та ві́дає все!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 21, 'Улю́блені, — коли не винуватить нас серце, то маємо відвагу до Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 22, 'і чого́ тільки попро́симо, одержимо від Нього, бо виконуємо Його заповіді та чинимо любе для Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 23, 'І оце Його заповідь, щоб ми вірували в Ім\'я́ Сина Його — Ісуса Христа, і щоб любили один о́дного, як Він нам заповідь дав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 24, 'А хто Його заповіді береже́, той у Нім пробуває, а Він у ньому. А що в нас пробуває, пізнає́мо це з того Духа, що Він нам Його дав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, 'Улю́блені, — не кожному духові вірте, але випробо́вуйте духів, чи від Бога вони, бо неправдивих пророків багато з\'явилося в світ.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'Духа Божого цим пізнавайте: кожен дух, який ви́знає, що Ісус Христос прийшов був у тілі, той від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'А кожен дух, який не визнає́ Ісуса, той не від Бога, але́ він анти́христів, про якого ви чули, що йде, а тепер уже він у світі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'Ви від Бога, дітки́, і ви перемогли їх, — більший бо Той, Хто в вас, аніж той, хто в світі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'Вони від світу, тому́ то говорять від світу, а світ слухає їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, 'Ми від Бога, — хто знає Бога, той слухає нас, хто не від Бога, той не слухає нас. Цим пізнає́мо Духа правди та духа обмани.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'Улю́блені, — любім один о́дного, бо від Бога любов, і кожен, хто любить, родився від Бога та ві́дає Бога!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Хто не любить, той Бога не пізнав, бо Бог є любов!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Любов Божа до нас з\'явилася тим, що Бог Сина Свого Одноро́дженого послав у світ, щоб ми через Нього жили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'Не в то́му любов, що ми полюбили Бога, а що Він полюбив нас, і послав Свого Сина вблага́нням за наші гріхи.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, 'Улю́блені, — коли Бог полюбив нас отак, то повинні любити і ми один о́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 12, 'Бога не бачив ніко́ли ніхто. Коли один о́дного любимо, то Бог в нас пробуває, а любов Його в нас удоскона́лилась.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 13, 'Що ми пробуваємо в Ньому, а Він у нас, пізнає́мо це тим, що Він дав нам від Духа Свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 14, 'І ми бачили й сві́дчимо, що Отець послав Сина Спасителем світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 15, 'Коли хто визнає́, що Ісус — то Син Божий, то в нім Бог пробува́є, а він у Бозі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 16, 'Ми пізнали й увірували в ту любов, що Бог її має до нас. Бог є любов, і хто пробуває в любові, пробуває той в Бозі, і в нім Бог пробуває!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 17, 'Любов удоскона́люється з нами так, що ми маємо відвагу на день судний, бо який Він, такі й ми на цім світі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 18, 'Стра́ху немає в любові, але досконала любов проганяє страх геть, бо страх має му́ку. Хто ж боїться, той не досконалий в любові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 19, 'Ми любимо Його, бо Він перше нас полюбив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 20, 'Як хто скаже: „Я Бога люблю́“, та нена́видить брата свого́, той неправдомо́вець. Бо хто не любить брата свого, якого бачить, як може він Бога любити, Якого не бачить?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 21, 'І ми оцю заповідь маємо від Нього, щоб, хто любить Бога, той і брата свого любив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, 'Кожен, хто вірує, що Ісус — то Христос, той родився від Бога. І кожен, хто любить Того, Хто породив, любить і Того, Хто народився від Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'Що ми любимо Божих дітей, дізнає́мося з того, коли любимо Бога і Його заповіді доде́ржуємо.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'Бо то любов Божа, щоб ми доде́ржували Його заповіді, Його ж заповіді не тяжкі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Бо кожен, хто родився від Бога, перемагає світ. А оце перемога, що світ перемогла, — віра наша.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, 'А хто світ перемагає, як не той, хто вірує, що Ісус — то Син Божий?');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'То Той, що прийшов був водою та кров\'ю, — Ісус Христос. І не тільки водою, а водою та кров\'ю. І Дух свідчить, бо Дух — то правда.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Бо троє свідкують на небі: Отець, Слово й Святий Дух, і ці Троє — Одно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'І троє свідкують на землі: дух, і вода, і кров, і троє — в одно.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'Коли ми приймаємо сві́дчення лю́дське, то свідчення Боже вартніше, бо це свідчення Бога, яким сві́дчив про Сина Свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'Хто вірує в Божого Сина, той сві́дчення має в собі. Хто не вірує Богові, той учинив Його неправдомовцем, бо не вірив у свідчення, яким Бог сві́дчив про Сина Свого́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, 'А це сві́дчення, що Бог життя вічне нам дав, а життя це — у Сині Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'Хто має Сина, той має життя; хто не має Сина Божого, той не має життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Оце написав я до вас, що віруєте в Ім\'я́ Божого Сина, щоб ви знали, що ви віруючи в Ім\'я Божого Сина, маєте вічне життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'І оце та відвага, що ми маємо до Нього, — що коли чого просимо згі́дно волі Його, то Він слухає нас.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 15, 'А як знаємо, що Він слухає нас, чого тільки ми просимо, то знаємо, що оде́ржуємо те, чого просимо від Нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 16, 'Коли хто бачить брата свого́, що грішить гріхом не на смерть, нехай мо́литься за нього, — і Він життя йому дасть, тим, хто грішить не на смерть. Є й гріх на смерть, — не про нього кажу́, щоб молився.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 17, 'Усяка неправда — то гріх. Та є гріх не на смерть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 18, 'Ми знаємо, що кожен, хто народився від Бога, не грішить, — бо хто народився від Бога, той себе береже, і лукавий його не торкається.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 19, 'Ми знаємо, що ми від Бога, і що ввесь світ лежить у злі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 20, 'Ми знаємо, що Син Божий прийшов, і розум нам дав, щоб пізнати Правдивого, і щоб бути в правдивому Сині Його, Ісусі Христі. Він — Бог правдивий і вічне життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 21, 'Ді́тоньки, — бережіться від і́долів! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 1, 'Ста́рець — вибраній пані та ді́тям її, яких я поправці люблю́, і не тільки я, але й усі, хто правду пізнав,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 2, 'за правду, що в нас пробував й повік буде з нами:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 3, 'нехай буде з вами благодать, милість, мир від Бога Отця та Ісуса Христа́, Сина Отцевого, у правді та в любові!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 4, 'Я дуже зрадів, що між ді́тьми твоїми знайшов таких, що ходять у правді, як заповідь ми прийняли́ від Отця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 5, 'І тепер я благаю тебе, пані, не так, ніби пишу́ тобі нову́ заповідь, але ту, яку маємо від поча́тку, — щоб ми любили один о́дного!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 6, 'А любов ця — щоб ми жили згідно з Його заповідями. Це та заповідь, яку ви чули від поча́тку, щоб ви згідно з нею жили́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 7, 'Бо в світ увійшло багато обма́нців, які не визнаю́ть Ісуса Христа, що прийшов був у тілі. Такий — то обманець та анти́христ!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 8, 'Пильнуйте себе, щоб ви не згубили того, над чим працювали, але щоб прийняли́ повну нагоро́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 9, 'Кожен, хто робить пере́ступ та не пробуває в науці Христовій, той Бога не має. А хто пробуває в науці Його́, той має і Отця, і Сина.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 10, 'Коли хто приходить до вас, але не приносить науки цієї, не приймайте до дому його́, і не вітайте його́!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 11, 'Хто бо вітає його́, той у́часть бере в лихи́х учинках його́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 12, 'Багато я мав написати до вас, але не схотів на папері й чорнилом. Та маю надію прибути до вас, і говорити уста́ми до уст, щоб повна була́ ваша радість!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 13, 'Вітають тебе діти ви́браної сестри твоєї. Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 1, 'Ста́рець — улю́бленому Гаєві, якого я направду люблю́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 2, 'Улю́блений, — я молюся, щоб добре вело́ся в усьому тобі, і щоб був ти здоровий, як добре веде́ться душі твоїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 3, 'Бо я дуже зрадів, як прийшли були браття, і засві́дчили правду твою, як ти живеш у правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 4, 'Я не маю більшої радости від цієї, щоб чути, що діти мої живуть у правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 5, 'Улю́блений, — вірно ти чи́ниш, як що робиш для братті та для чужи́нців, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 6, 'вони про любов твою свідчили Церкві; добре ти зробиш, як їх ви́провадиш, як достойно для Бога,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 7, 'бо вийшли вони ради Йме́ння Його, нічого не взявши від поган.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 8, 'Отож, ми повинні приймати таких, щоб бути співробі́тниками правді.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 9, 'Я до Церкви писав був, але Діотре́ф, що любить бути першим у них, нас не приймає.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 10, 'Тому́ то, коли я прийду́, то згадаю про вчинки його, що їх ро́бить, словами лихими обмовля́ючи нас. І він тим не задово́льнюється, — а й сам не приймає братів, і тим, що бажають приймати, боронить, і виго́нить із Церкви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 11, 'Улюблений, — не робися подібним до лихо́го, а до доброго: доброчинець від Бога, а злочинець Бога не бачив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 12, 'Про Димитрія сві́дчили всі й сама правда. І сві́дчимо й ми, а ви знаєте, що свідчення наше правдиве.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 13, 'Багато хотів я писати, та не хочу писати до тебе чорнилом та очерети́нкою,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 14, 'але маю надію побачити тебе незаба́ром, і говорити уста́ми до уст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 15, 'Мир тобі! Друзі вітають тебе. Привітай друзів пойменно! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 1, 'Юда, раб Ісуса Христа, а брат Якова, — покликаним, улю́бленим у Бозі Отці та збереженим Ісусом Христом:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 2, 'милість вам, і мир, і любов хай примно́житься!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 3, 'Улюблені, всяке дбання́ чинивши писати до вас про наше спільне спасі́ння, я признав за потрібне писати до вас, благаючи боротись за віру, раз дану святим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 4, 'Бо крадькома́ повхо́дили деякі люди, на цей о́суд віддавна призначені, безбожні, що благода́ть нашого Бога оберта́ють у розпусту, і відкидаються єдиного Владики і Господа нашого — Ісуса Христа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 5, 'А я хо́чу нагадати вам, що раз усе знаєте, що Госпо́дь ви́зволив людей від землі єгипетської, а згодом вигубив тих, хто не вірував.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 6, 'І анголі́в, що не зберегли початкового стану свого, але кинули жи́тло своє, Він зберіг у вічних кайда́нах під те́мрявою на суд великого дня.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 7, 'Як Содо́м і Гомо́рра та міста́ коло них, що таким самим способом чинили пере́люб та ходили за іншим тілом, поне́сли кару вічного огню, і поставлені в при́клад, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 8, 'так само буде й цим снови́дам, що опоганюють тіло, пого́рджують вла́дами, зневажають слави.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 9, 'І сам арха́нгол Михаїл, коли сперечався з дияволом і говорив про Мойсеєве тіло, не нава́жився винести суду зневажливого, а сказав: „Хай Господь доко́рить тобі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 10, 'А ці зневажають, чого не знають; а що знають із природи, як німа звірина́, то й у тому псуються.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 11, 'Горе їм, бо пішли вони дорогою Каїновою, і попали в обману Валаа́мової заплати, і загинули в бунті Коре́я!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 12, 'Вони скелі підводні на ваших вече́рях любови, бо з вами без стра́ху їдять та себе попаса́ють; хмари безводні, що носяться вітром; осінні дере́ва безплідні, двічі померлі, ви́корінені;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 13, 'люті хвилі мо́рські, що з піною викидають власний сором; зорі блудні́, що для них морок те́мряви береже́ться повік.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 14, 'Про них же звіщав був Ено́х, сьомий від Ада́ма, і казав: „Ось іде Госпо́дь зо Своїми десятками тисяч святих,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 15, 'щоб суд учинити над усіма́, і винуватити всіх безбожних за всі вчинки безбожности їхньої, що безбожно нако́їли, та за всі жорстокі слова, що їх говорили на Нього безбожні грішники“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 16, 'Це ре́мствувачі, незадоволені з долі своєї, що ходять у своїх пожадливостях, а уста їхні говорять чванли́ве; вони вихваляють особи для зи́ску!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 17, 'А ви, улюблені, згадуйте слова́, що їх давніше казали апо́столи Господа нашого Ісуса Христа,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 18, 'які вам говорили: „За останнього ча́су будуть глузії́, що ходитимуть за своїми пожадливостями та безбожністю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 19, 'Це ті, хто відлу́чується від єдности, тілесні, що духа не мають.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 20, 'А ви, улюблені, будуйте себе найсвятішою вашою вірою, моліться у Дусі Святім,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 21, 'бережіть себе сами́х у Божій любові, і чекайте милости Господа на́шого Ісуса Христа для вічного життя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 22, 'І до одних, хто вагається, будьте милости́ві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 23, 'спасайте і виривайте з огню, а до інших будьте милосердні зо стра́хом, і нена́видьте навіть одежу, опоганену від тіла!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 24, 'А Тому́, Хто може вас зберегти від упадку, і поставити перед Своєю славою непорочними в радості,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 25, 'Єдиному премудрому Богові, Спасителеві нашому через Ісуса Христа, Господа нашого, слава, могутність, сила та вла́да перше всього віку, і тепер, і на всі віки! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 1, 'Об\'я́влення Ісуса Христа, яке дав Йому Бог, щоб показати Своїм рабам, що́ незабаром статися має. І Він показав, і послав Своїм а́нголом рабові Своєму Іванові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 2, 'який сві́дчив про Слово Боже, і про свідчення Ісуса Христа, і про все, що́ він бачив.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 3, 'Блаженний, хто читає, і ті, хто слухає слова пророцтва та доде́ржує написане в ньому, — час бо близьки́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 4, 'Іван до семи Церков, що в Азії: благода́ть вам і мир від Того, Хто є, Хто був і Хто має прийти; і від семи Ду́хів, що перед престолом Його,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 5, 'та від Ісуса Христа, а Він „Свідок вірний, Пе́рвенець з мертвих і Влади́ка зе́мних царів“. Йому, що нас полюбив і кров\'ю Своєю обмив нас від наших гріхів,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 6, 'що вчинив нас „царями, священиками Богові“й Отцеві Своєму, — Тому слава та сила на вічні віки! Амі́нь.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 7, '„Ото Він із хмарами йде“, і побачить Його кожне око, і ті, що Його „прокололи були, і всі племе́на землі будуть плакати за Ним“. Так, амінь!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 8, 'Я Альфа й Оме́га, говорить Госпо́дь, Бог, Той, Хто є, і Хто був, і Хто має прийти, Вседержи́тель!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 9, 'Я, Іван, ваш брат і спільник у біді, і в царстві, і в терпінні в Ісусі, був на о́строві, що зветься Патмо́с, за Слово Боже і за сві́дчення Ісуса Христа́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 10, 'Я був у Дусі Господнього дня, і почув за собою голос гучни́й, немов сурми́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 11, 'який говорив: „Що́ бачиш, — напиши те до книги, і пошли до сімох Церков: до Ефе́су, і до Смі́рни, і до Перга́му, і до Тіяти́рів, і до Сард, і до Філяде́льфії і до Лаодикі́ї“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 12, 'І я огля́нувся, щоб побачити голос, що говорив зо мною. І, огля́нувшись, я побачив сім світильників золотих;');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 13, 'а посеред семи світильників „Подібного до Лю́дського Сина, одя́гненого в до́вгу оде́жу і підпере́заного“по гру́дях золотим поясом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 14, 'А „Його голова та волосся — білі, немов біла во́вна, як сніг; а очі Його — немов по́лум\'я огняне́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 15, 'А ноги Його подібні до міді“, розпа́лені, наче в печі́; а „голос Його — немов шум великої води“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 16, 'І сім зір Він держав у правиці Своїй, а з уст Його меч обосі́чний виходив, а обличчя Його, немов сонце, що світить у силі своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 17, 'І коли я побачив Його, то до ніг Йому впав, немов мертвий. І поклав Він на мене правицю Свою та й промовив мені: „Не лякайся! Я Перший і Останній,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 18, 'і Живий. І був Я мертвий, а ось Я Живий на вічні віки. І маю ключі Я від смерти й від а́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 19, 'Отже, напиши, що́ ти бачив, і що́ є, і що́ має бути по цьо́му!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 20, 'Таємниця семи зір, що бачив ти їх на правиці Моїй, і семи світильників золотих: сім зір, — то анголи́ семи Церков, а сім світильників, що ти бачив, — то сім Церков“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 1, 'До ангола Церкви в Ефе́сі напиши: „Оце каже Той, Хто трима́є сім зір у правиці Своїй, Хто ходить серед семи світильників золотих:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 2, 'Я знаю діла твої, і працю твою, і твою терпеливі́сть, і що не можеш терпіти лихих, і ви́пробував тих, хто себе називає апо́столами, але ними не є, і знайшов, що фальшиві вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 3, 'І ти маєш терпіння, і працюва́в для Йме́ння Мого, але не знемігся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 4, 'Але маю на тебе, що ти покинув свою першу любов.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 5, 'Отож, пам\'ятай, звідки ти впав, і покайся, і вчинки давніші роби. Коли ж ні, то до тебе прийду́ незаба́ром, і зру́шу твого світильника́ з його місця, якщо не покаєшся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 6, 'Але маєш оце, що нена́видиш учинки Николаї́тів, яких і Я нена́виджу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 7, 'Хто має вухо, хай чує, що Дух промовляє Церква́м: переможцеві дам їсти від дерева життя, яке в раю́ Божім“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 8, 'А до ангола Церкви в Смірні напиши: „Оце каже Перший й Останній, що був мертвий й ожив:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 9, 'Я знаю діла твої, і біду́, і убозтво, — але ти багатий, — і зневагу тих, що говорять про себе, ніби юдеї вони, та ними не є, але вони — зборище сатани.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 10, 'Не бійся того, що маєш страждати! Ось диявол вкидатиме декого з вас до в\'язниць, щоб вас ви́пробувати. І будете мати біду́ десять день. Будь вірний до смерти, і Я тобі дам вінця́ життя!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 11, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м: переможець не буде пошко́джений від другої смерти“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 12, 'А до ангола Церкви в Перга́мі напиши: „Оце каже Той, що має меча обосі́чного:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 13, 'Я знаю діла твої, і що де ти живеш, там престол сатани. І трима́єш ти Йме́ння Моє, і ти не відкинувся від віри Моєї навіть за днів, коли в вас, де живе сатана́, був убитий Анти́па, свідок Мій вірний.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 14, 'Але трохи Я маю на тебе, бо маєш там тих, хто трима́ється науки Валаа́ма, що навчав був Бала́ка покласти спотика́ння перед синами Ізраїля, щоб їли ідольські жертви й розпу́сту чинили.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 15, 'Так маєш і ти таких, що трима́ються науки Николаїтської так само.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 16, 'Тож покайся! Коли ж ні, то до тебе прийду́ незаба́ром, і воюватиму з ними мечем Своїх уст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 17, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м: переможцеві дам їсти прихо́вану манну, і дам йому білого каменя, а на камені написане ймення нове́, якого не знає ніхто, — тільки той, хто приймає його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 18, 'І до ангола Церкви в Тіяти́рах напиши: „Оце каже Син Божий, що має очі Свої, як по́лум\'я огняне́, а ноги Його подібні до міді:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 19, 'Я знаю діла твої, і любов, і віру, і службу, і твою терпеливість, і останні вчинки твої, що більші за перші.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 20, 'Але маю на тебе, що жінці Єзаве́лі, яка каже, ніби вона пророки́ня, ти попускаєш навчати та зводити рабів Моїх, чинити розпусту та їсти і́дольські жертви.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 21, 'І Я дав був їй ча́су, щоб пока́ялася, — та вона не схотіла покаятися в розпусті своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 22, 'Ось Я кину її на ложе, а тих, що чинять із нею розпусту, у велику біду, коли тільки в учинках своїх не покаються,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 23, 'а діти її поб\'ю́ смертю. І пізнають усі Церкви́, що Я Той, Хто нирки й серця вивіря́є, і Я кожному з вас дам за вчинками вашими.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 24, 'А вам, та іншим, що в Тіяти́рах, що не мають науки цієї, і — як кажуть — не розуміють так зва́них глиби́н сатани́, кажу́: не накладу́ на вас іншого тягара,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 25, 'тільки те, що ви маєте, трима́йте, аж поки прийду́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 26, 'А переможцеві, і тому́, хто аж до кінця доде́ржує Мої вчинки, Я дам йому вла́ду „над поганами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 27, 'і буде пасти́ їх залізним жезлом; вони, немов гли́няний по́суд, покру́шаться“, як і Я оде́ржав вла́ду від Свого́ Отця,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 28, 'і дам Я йому зо́рю досві́тню.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 2, 29, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 1, 'А до ангола Церкви в Са́рдах напиши: „Оце каже Той, Хто має сім Божих Ду́хів і сім зір: Я знаю діла твої, що маєш ім\'я́, ніби живий, а ти мертвий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 2, 'Будь чуйни́й та решту зміцняй, що мають померти. Бо Я не знайшов твоїх діл закі́нченими перед Богом Моїм.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 3, 'Отож, пам\'ятай, як ти взяв і почув, і бережи, і покайся. А коли ти не чуйни́й, то на тебе прийду́, немов злодій, і ти знати не бу́деш, якої години на тебе прийду́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 4, 'Та ти маєш і в Са́рдах кілька імен, що одежі своєї вони не опога́нили, і в білій зо Мною ходитимуть, бо гі́дні вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 5, 'Переможець зодя́гнеться в білу одежу, а йме́ння його Я не змию із книги життя, і ймення його ви́знаю перед Отцем Своїм і перед Його алгола́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 6, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 7, 'І до ангола Церкви в Філяде́льфії напиши: „Оце каже Святий, Правдивий, що має „ключа Давидового, що Він відчиняє, — і ніхто не зачинить, що Він зачиняє, — і ніхто не відчинить“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 8, 'Я знаю діла твої. Ось Я перед тобою дверей не зачинив, — і їх зачинити не може ніхто. Хоч малу маєш силу, але слово Моє ти зберіг, і від Йме́ння Мого не відкинувся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 9, 'Ось Я зроблю́, що декого з зборища сатани, із тих, що себе називають юдеями, та ними не є, але кажуть неправду, — ось Я зроблю́, що вони „при́йдуть та вклоняться перед ногами твоїми“, і пізнають, що „Я полюбив тебе“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 10, 'А що ти зберіг слово терпіння Мого, то й Я тебе збережу́ від години випробо́вування, що має прийти на ввесь світ, щоб ви́пробувати ме́шканців землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 11, 'Я прийду́ незабаром. Тримай, що́ ти маєш, щоб твого вінця ніхто не забрав.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 12, 'Переможця зроблю́ Я стовпом у храмі Бога Мого, і він вже не вийде назовні, і на нім напишу́ Ім\'я́ Бога Мого й ім\'я міста Бога Мого, Єрусалиму Ново́го, що з неба сходить від Бога Мого, та нове Ім\'я́ Своє.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 13, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 14, 'І до ангола Церкви в Лаодикі́ї напиши: „Оце каже Амі́нь, Свідок вірний і правдивий, поча́ток Божого тво́рива:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 15, 'Я знаю діла твої, що ти не холодний, ані гарячий. Якби то холодний чи гарячий ти був!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 16, 'А що ти лі́теплий, і ні гарячий, ані холодний, то ви́плюну тебе з Своїх уст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 17, 'Бо ти кажеш: „Я багатий, і збагатів, і не потребу́ю нічого“. А не знаєш, що ти нужде́нний, і мізерний, і вбогий, і сліпий, і голий!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 18, 'Раджу тобі купити в Мене золота, в огні перечищеного, щоб збагати́тись, і білу одежу, щоб зодягтися, і щоб га́ньба наготи́ твоєї не видна була, а ма́стю на очі намасти́ свої очі, щоб бачити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 19, 'Кого Я люблю́, тому докоряю й караю того. Будь же ревний і покайся!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 20, 'Ось Я стою під дверима та стукаю: коли хто почує Мій голос і двері відчинить, Я до нього ввійду́, і буду вече́ряти з ним, а він зо Мною.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 21, 'Переможцеві сісти Я дам на Моєму престолі зо Мною, як і Я переміг був, і з Отцем Своїм сів на престолі Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 3, 22, 'Хто має вухо, хай чує, що́ Дух промовляє Церква́м!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 1, 'По цьому я поглянув, — і ось двері на небі відчинені, і перший голос, що я чув його, як сурму́, що зо мною говорив, сказав: „Іди сюди, і Я тобі покажу́, що́ статися має по цьо́му!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 2, 'І зараз у Дусі я був. І ось престол стояв на небі, а на престолі Сидячий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 3, 'А Сидячий подібний був з ви́гляду до каменя я́спіса й сарди́са, а весе́лка навколо престолу видом подібна була до смара́гду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 4, 'А навколо престолу — двадцять чотири престоли, а на престолах я бачив двадцятьох чотирьох ста́рців, що сиділи, у шати білі одя́гнені, а на головах своїх мали вінці́ золоті.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 5, 'А від престолу вихо́дили бли́скавки, і голоси, і громи. А перед престолом горіли сім світильників огняни́х, а вони — сім Духів Божих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 6, 'І перед престолом — як море скляне, до кришта́лю подібне. А серед престолу й навколо престолу четверо тварин, повні очей спе́реду й зза́ду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 7, 'І перша твари́на подібна до лева, а друга тварина подібна до теляти, а третя тварина мала лице, як люди́на, а четверта тварина подібна до орла, що летить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 8, 'І ті чотири тварини, — кожна з них мала навколо по шість крил, а всере́дині повна очей. І споко́ю не мають вони день і ніч, промовляючи: „Свят, свят, свят Господь, Бог Вседержи́тель, що Він був, і що є, і що має прийти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 9, 'І коли ті тварини складають славу, і честь, і подяку Тому, Хто сидить на престолі й живе віки вічні,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 10, 'тоді падають двадцять чотири ста́рці перед Тим, Хто сидить на престолі, і вклоняються Тому, Хто живе віки вічні, і складають вінці́ свої перед престолом та кажуть:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 4, 11, '„Достойний Ти, Господи й Боже наш, прийняти славу, і честь, і силу, бо все Ти створив, і з волі Твоєї існує та створене все!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 1, 'І я бачив в правиці Того, Хто сидить на престолі, книгу, написану всере́дині й назо́вні, і запечатану сімома́ печатками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 2, 'І бачив я поту́жного ангола, який гучним голосом кликав: „Хто гі́дний розгорну́ти книгу, і зламати печа́тки її?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 3, 'І не міг ніхто ні на небі, ні на землі, ані під землею розгорнути книги, ані навіть зазирнути в неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 4, 'І плакав я гірко, що не знайшовся ані один гі́дний розгорнути й прочитати книгу, ані навіть зазирнути в неї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 5, 'А один із ста́рців промовив до мене: „Не плач! Ось Лев, що з племени Юдиного, корінь Давидів, переміг так, що може розгорнути книгу, і зламати сім печаток її“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 6, 'І я глянув, — і ось серед престолу й чотирьох тварин і серед ста́рців стоїть А́гнець, як зако́лений, що має сім рогів і сім очей, а це — сім Божих Ду́хів, по́сланих на всю землю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 7, 'І Він підійшов, і взяв книгу з правиці Того, Хто сидить на престолі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 8, 'А коли Він узяв книгу, то чотири тварини й двадцять чотири старці попа́дали перед Агнцем, а кожен мав гу́сла й золоті чаші, повні пахощів, а вони — моли́тви святих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 9, 'І нову́ пісню співають вони, промовляючи: „Ти достойний узяти цю книгу, і розкрити печатки її, бо Ти був зако́лений, і кров\'ю Своєю Ти викупив людей Богові з усякого пле́мени, і язика, і наро́ду, і люду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 10, 'І Ти їх зробив для нашого Бога царями, і священиками, — і вони на землі царюватимуть!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 11, 'І я бачив, і чув голос багатьох анголів навколо престолу, і тварин, і ста́рців, — і число їх було десятки тисяч раз по десять тисяч і тисячі тисяч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 12, 'І казали вони гучним голосом: „Достойний Агнець, що заколений, прийняти силу, і багатство, і мудрість, і міць, і честь, і славу, і благослове́ння!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 13, 'І кожне створіння, що воно на небі, і на землі, і під землею, і на морі, і все, що в них, чув я, говорило: „Тому, Хто сидить на престолі, і Агнцеві — благослове́ння, і честь, і слава, і сила на вічні віки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 5, 14, 'А чотири тварини казали: „Амі́нь!“І двадцять чотири ста́рці попа́дали та поклонились Тому, Хто живе повік віку!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 1, 'І я бачив, що Агнець розкрив одну з семи печаток, і почув я одну з чотирьох тих тварин, яка говорила, як голосом грому: „Підійди́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 2, 'І я глянув, — і ось кінь білий, а той, хто на ньому сидів, мав лука. І вінця́ йому да́но, і він вийшов, немов переможець, і щоб перемогти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 3, 'І коли другу печатку розкрив, я другу тварину почув, що казала: „Підійди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 4, 'І вийшов кінь другий, — червоний. А тому, хто на ньому сидів, було да́но взяти мир із землі та щоб убивали один о́дного. І меч великий був да́ний йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 5, 'І коли третю печатку розкрив, я третю тварину почув, що казала: „Підійди!“І я глянув, — і ось кінь ворони́й. А той, хто на ньому сидів, мав вагу́ в своїй руці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 6, 'І я ніби голос почув посеред чотирьох тих тварин, що казав: „Ківш пшениці за динарія, і три ковші ячменю за динарія, а оливи й вина не марнуй!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 7, 'А коли Він четверту печатку розкрив, я четверту тварину почув, що казала: „Підійди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 8, 'І я глянув, — і ось кінь ча́лий. А той, хто на ньому сидів, на ім\'я́ йому Смерть, за ним же слідом ішов Ад. І да́на їм вла́да була на четвертій частині землі забивати мечем, і голодом, і мором, і земни́ми звірми́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 9, 'І коли п\'яту печатку розкрив, я побачив під же́ртівником душі побитих за Боже Слово, і за свідчення, яке вони мали.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 10, 'І кли́кнули вони гучним голосом, кажучи: „Аж доки, Владико святий та правдивий, не будеш судити, і не мститимеш тим, хто живе на землі, за кров нашу?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 11, 'І кожному з них да́но білу одежу, і сказано їм іще трохи спочити, аж поки допо́внять число їхні співслуги, і брати́ їхні, що будуть побиті, як і вони.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 12, 'І коли шосту печатку розкрив, я поглянув, — і ось сталось велике трясіння землі, і сонце зчорніло, як міх волося́ний, і ввесь місяць зробився, як кров.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 13, 'І на землю попа́дали зорі небесні, як фіґове дерево ро́нить свої недозрілі плоди́, коли потрясе сильний вітер.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 14, 'І небо сховалось, згорнувшись, немов той сувій перга́мену, і кожна гора, і кожен о́стрів порушилися з своїх місць.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 15, 'І зе́мні царі, і вельможі та тисячники, і багаті та сильні, і кожен раб та кожен вільний, — поховались у печери та в скелі гірські́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 16, 'та й кажуть до гір та до скель: „Поспадайте на нас, і позакривайте ви нас від лиця Того, Хто сидить на престолі, і від гніву А́гнця!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 6, 17, 'Бо прийшов це великий день гніву Його, і хто всто́яти може?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 1, 'А по цьому я бачив чотирьох алголі́в, що стояли на чотирьох ку́тах землі та тримали чотири земні вітри́, щоб вітер не віяв на землю, ані на море, ані на жодне дерево.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 2, 'І бачив я іншого ангола, що від схід сонця вихо́див, і мав печа́тку Бога Живого. І він гучним голосом крикнув до чотирьох алголів, що їм да́но пошкодити землі́ та морю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 3, 'говорячи: „Не шкодьте ані землі́, ані морю, ані дереву, аж поки ми покладе́мо печа́тки рабам Бога нашого на їхніх чо́лах!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 4, 'І почув я число попеча́таних: сто сорок чотири тисячі попечатаних від усіх племен Ізраїлевих синів:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 5, 'з племени Юдиного — дванадцять тисяч попеча́таних, з племени Руви́мового — дванадцять тисяч, з племени Ґа́дового — дванадцять тисяч,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 6, 'з пле́мени Аси́рового — дванадцять тисяч, з племени Нефтали́мового — дванадцять тисяч, з племени Манасі́їного — дванадцять тисяч,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 7, 'з племени Симео́нового — дванадцять тисяч, з племени Леві́їного — дванадцять тисяч, з племени Іссаха́рового — дванадцять тисяч,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 8, 'з племени Завуло́нового — дванадцять тисяч, з племени Йо́сипового — дванадцять тисяч, з племени Веніями́нового — дванадцять тисяч попеча́таних.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 9, 'Пото́му я глянув, — і ось на́товп великий, що його зрахувати не може ніхто, з усякого люду, і племе́н, і наро́дів, і язи́ків, стояв перед престолом і перед Агнцем, зодя́гнені в білу одежу, а в їхніх руках було па́льмове ві́ття.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 10, 'І взива́ли вони гучним голосом, кажучи: „Спасіння нашому Богові, що сидить на престолі, і Агнцеві!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 11, 'А всі анголи́ стояли навко́ло престолу та ста́рців і чотирьох тих тварин. І вони на обличчя попадали перед престолом, і вклонилися Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 12, 'кажучи: „Амі́нь! Благослове́ння, і слава, і мудрість, і хвала́, і честь, і сила, і міць — нашому Богу на вічні віки! Амі́нь!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 13, 'І відповів один із ста́рців, і до мене сказав: „Оці, що зодя́гнені в білу одежу, — хто вони й звідкіля́ поприхо́дили?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 14, 'І сказав я йому: „Мій пане, ти знаєш!“Він же мені відказав: „Це ті, що прийшли від великого горя, і випрали одіж свою, та вибілили її в крові Агнця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 15, 'Тому́ то вони перед Божим престолом, і в храмі Його день і ніч Йому служать. А „Той, Хто сидить на престолі, розтя́гне наме́та над ними“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 16, '„Вони голоду й спраги терпіти не бу́дуть уже, і не буде палити їх сонце, ані спека яка“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 7, 17, 'Бо Агнець, що серед престолу, „буде їх па́сти, і водитиме їх до джере́л вод життя. І Бог кожну сльозу́ з очей їхніх зітре!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 1, 'І коли сьому печатку розкрив, німа ти́ша настала на небі десь на півгодини.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 2, 'І я бачив сімох анголів, що стояли перед Богом. І да́но було їм сім су́рем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 3, 'І прийшов другий ангол, та й став перед же́ртівником із золотою кадильницею. І було йому да́но багато кадила, щоб до молито́в усіх святих додав на золотого же́ртівника, що перед престолом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 4, 'І знявся дим кадильний з моли́твами святих від руки ангола перед Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 5, 'А ангол кадильницю взяв, і напо́внив її огнем із же́ртівника, та й кинув на землю. І зчинилися гро́ми, і гурко́тнява, і бли́скавиці та трясіння землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 6, 'І сім анголів, що мали сім су́рем, приготува́лися, щоб сурми́ти.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 7, 'І засурми́в перший ангол, — і вчинилися град та огонь, перемішані з кров\'ю, і впали на землю. І спалилась третина землі, і згоріла третина дерев, і всіляка зелена трава погоріла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 8, 'І засурми́в другий ангол, — і немов би велика гора, розпа́лена огнем, була вкинена в море. І третина мо́ря зробилася кров\'ю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 9, 'і померла третина морського створіння, що мають життя, і загинула третина кораблів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 10, 'І засурми́в третій ангол, — і велика зоря́ спала з неба, пала́ючи, як смолоски́п. І спала вона на третину річок та на водні джере́ла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 11, 'А йме́ння зорі тій Поли́н. І стала третина води, як поли́н, і багато з людей повмирали з води, бо згі́ркла вона.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 12, 'І засурми́в ангол четвертий, — і вда́рено третину сонця, і третину місяця, і третину зір, щоб затьми́лася їхня третина, щоб третина дня не світила, так само ж і ніч.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 8, 13, 'І бачив, і чув я одно́го орла, що летів серед неба і кли́кав гучним голосом: „Горе, горе, горе тим, хто живе на землі, від голосів сурмови́х позосталих трьох анголів, що мають сурми́ти!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 1, 'І засурмив п\'ятий ангол, — і я бачив зо́рю, що спала із неба додолу. І їй да́ний був ключ від криниці безо́дньої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 2, 'І вона відімкнула криницю безо́дню, — і дим повалив із криниці, мов дим із великої пе́чі. І затьми́лося сонце й повітря від криничного диму.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 3, 'А з диму на землю вийшла сарана́, і да́но їй міць, як мають міць скорпіо́ни земні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 4, 'І наказано їй, щоб вона не шкодила земній траві́, ані жа́дному зі́ллю, ані жа́дному дереву, але тільки тим людям, які на чо́лах не мають печатки Божої.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 5, 'І було да́но їй, щоб їх не вбивати, але мучити п\'ять місяців; а му́ка від неї, як му́ка від скорпіо́на, коли вкусить люди́ну.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 6, 'І в ті дні люди смерти шукатимуть, — та не зна́йдуть її! Померти вони захотять, — та втече від них смерть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 7, 'А вигляд сарани́ був подібний до ко́ней, на війну приготованих; а на головах у неї — немов би вінки́, подібні на золото, а обличчя її — немов лю́дські обличчя.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 8, 'І мала волосся — як волосся жіноче, а її зуби були́ — немов ле́в\'ячі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 9, 'І мала вона па́нцери, немов панцери залізні; а шум її крил — немов шум колесни́ць, коли ко́ней багато біжить на війну́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 10, 'І мала хвости, подібні до скорпіонових, та жа́ла, а в неї в хвостах її вла́да — п\'ять місяців шкодити лю́дям.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 11, 'І мала вона над собою царя, ангола безодні; йому по-єврейському ім\'я Аваддо́н, а по-грецькому звався він Аполліо́н!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 12, 'Одне горе минуло! Ось за ним ще два горя надходять!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 13, 'I засурми́в шостий Ангол, — і я почув один голос із чотирьох ро́гів золотого же́ртівника, який перед Богом,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 14, 'що казав шостому Анголові, який мав сурму́: „Розв\'яжи чотирьох Анголів, що пов\'язані при великій річці Ефра́ті“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 15, 'I були порозв\'я́зувані чотири Анголи́, пригото́вані на годину, і на день, і на місяць, і на рік, щоб убили третину людей.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 16, 'А число кі́нного ві́йська — двадцять тисяч раз по десять тисяч; і я чув їхнє число.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 17, 'І так бачив я ко́ней в виді́нні, а на них верхівці́в, що па́нцери мали огняні́, і гіяци́нтові, і сірчані́. А го́лови в ко́ней — немов голови ле́в\'ячі, а з їхнього рота виходив огонь, і дим, і сірка.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 18, 'І побита була́ третина людей від цих трьох пора́зок, — від огню́, і від диму, і від сірки, що вихо́дили з їхніх роті́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 19, 'Сила бо ко́ней була в їхнім роті та в їхніх хвоста́х. А хвости́ їхні подібні до вужі́в, що мають го́лови, і ними вони шкоду чинять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 20, 'А решта людей, що не вбита була́ цими пора́зками, не пока́ялася за діла своїх рук, щоб не кланятись де́монам, ані і́долам золотим, і срібним, і мідяним, і кам\'яни́м, і дерев\'яним, що не можуть вони ані бачити, ані чути, ані ходити.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 9, 21, 'І вони не покаялися в своїх убивствах, ані в чарах своїх, ні в розпусті своїй, ні в краді́жках своїх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 1, 'І бачив я іншого поту́жного Ангола, що сходив із неба. Був одя́гнений в хмару, і над його головою весе́лка була, а обличчя його — немов сонце, а ноги його — як стовпи́ огняні́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 2, 'і мав у руці своїй книжку розго́рнену. І він поставив свою праву ногу на море, а ліву — на землю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 3, 'і закричав гучним голосом, як лев той ричить. І як він закричав, то заговори́ли сім гро́мів голосами своїми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 4, 'А як заговорили сім гро́мів голосами своїми, я хотів був писати. Та я почув голос із неба, що до мене казав: „Запечатай оте, що сім гро́мів казали, і того не пиши!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 5, 'А Ангол, що я бачив його, як стояв він на морі й землі, зняв до неба прави́цю свою');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 6, 'та й поклявся Живучим по вічні віки, Який створив небо та те, що на ньому, і землю та те, що на ній, і море й що в нім, — що вже ча́су не бу́де,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 7, 'а дня голосу сьомого Ангола, коли він засу́рмить, доверши́ться Божа таємни́ця, як Він благовісти́в був Своїм рабам пророкам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 8, 'І голос, що я чув його з неба, став знов говорити зо мною й казати: „Піди, та візьми розго́рнену книжку з руки Ангола, що стоїть на морі й землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 9, 'І пішов я до Ангола та й промовив йому, щоб дав мені книжку. А він мені каже: „Візьми, і з\'їж її! І гі́ркість учинить вона для твого живота, та в устах твоїх буде солодка, як мед“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 10, 'І я взяв з руки Ангола книжку та й з\'їв її. І була́ вона в устах моїх, немов мед той, солодка. Та коли її з\'їв, вона гі́ркість зробила в моїм животі...');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 10, 11, 'І сказали мені: „Ти мусиш зно́ву пророкувати про наро́ди, і поган, і язи́ки, і про багато царів“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 1, 'І да́но трости́ну мені, подібну до па́лиці, і сказано: „Устань, і зміряй храма Божого й же́ртівника, і тих, хто вклоняється в ньому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 2, 'А двір, що за храмом, лиши та не міряй його, бо він да́ний поганам, — і сорок два місяці бу́дуть топтати вони святе місто.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 3, 'І звелю́ Я двом свідкам Своїм, і бу́дуть вони пророкувати тисячу двісті й шістдеся́т день, зодя́гнені в волосяни́цю.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 4, 'Воні — дві оливки і два світильники́, що стоять перед Богом землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 5, 'І коли б хто схотів учинити їм кривду, то вийде огонь з їхніх уст, — і поїсть ворогів їхніх. А коли хто захоче вчинити їм кривду, — той отак мусить бути забитий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 6, 'Вони мають вла́ду небо замкнути, щоб за днів їхнього пророцтва не йшов дощ. І мають вла́ду вони над водою, — у кров оберта́ти її, і вдарити землю всілякою карою, скільки разі́в вони схочуть.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 7, 'А коли вони скі́нчать свідо́цтво своє, то звірина́, що з безодні виходить, із ними війну поведе́, — і вона їх переможе та їх повбиває.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 8, 'І їхні трупи полишить на майда́ні великого міста, що зветься духовно Содо́м і Єгипет, де й Госпо́дь наш був розп\'я́тий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 9, 'І багато з наро́дів, і з племен, і з язи́ків, і з поган бу́дуть дивитися пі́вчверта дні на їхні трупи, не дозволять покласти в гроби́ їхніх тру́пів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 10, 'А ме́шканці землі будуть тішитися та радіти над ними, і дару́нки пошлють один о́дному, бо мучили ці два пророки ме́шканців землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 11, 'А по пі́вчверта днях дух життя ввійшов у них від Бога, — і вони повставали на ноги свої. І напав жах великий на тих, хто дивився на них!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 12, 'І почули вони гучний голос із неба, що їм говорив: „Зійдіть сюди!“І на небо зійшли вони в хмарі, і вороги їхні дивились на них.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 13, 'І тієї години зчинився страшни́й землетру́с, і десята частина міста того завали́лась... І в цім трусі загинуло сім тисяч лю́дських іме́н, а решта обго́рнена жахом була́, — і вони віддали́ славу Богу Небесному!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 14, 'Друге горе минуло! Ото незабаром настане за ним третє горе!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 15, 'І засурмив сьо́мий ангол, — і на небі зчинились гучні голоси́, що казали: „Перейшло панува́ння над світом до Господа нашого та до Христа Його, — і Він зацарює на вічні віки́!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 16, 'І двадцять чотири ста́рці, що на престолах своїх перед Богом сидять, попа́дали на обличчя свої, та й уклонилися Богові,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 17, 'кажучи: „Дяку складаємо Тобі, Господи, Боже Вседержителю, що Ти є й що Ти був, що прийняв Свою силу велику та й зацарюва́в!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 18, 'А погани розлю́тилися, та гнів Твій прийшов, і час настав мертвих судити, і дати заплату рабам Твоїм, пророкам і святим, і тим, хто Йме́ння Твого боїться малим і великим, і знищити тих, хто нищить землю“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 11, 19, 'І розкрився храм Божий на небі, — і ковче́г заповіту Його в Його храмі з\'явився. І зчинилися бли́скавки, і гу́ркіт, і гро́ми, і землетру́с, і великий град.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 1, 'І з\'явилась на небі велика ознака: Жі́нка, зодя́гнена в сонце, а під ногами її місяць, а на її голові вінок із дванадцяти́ зір.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 2, 'І вона мала в утробі, і кричала від болю, та му́ки терпіла від по́роду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 3, 'І з\'явилася інша ознака на небі, — ось змій червоноогняни́й, великий, що мав сім голів та десять ро́гів, а на його го́ловах сім вінці́в.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 4, 'Його хвіст змів третину зір із неба та й кинув додолу. І змій стояв перед жінкою, що мала вродити, щоб з\'їсти дитину її, коли вро́дить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 5, 'І дитину вроди́ла вона чоловічої ста́ті, що всі наро́ди має па́сти залі́зним жезлом. І дитина її була взята до Бога, і до престолу Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 6, 'А жінка втекла́ на пустиню, де вона мала місце, від Бога для неї вгото́ване, щоб там годува́ли її тисячу двісті шістдеся́т день.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 7, 'І сталась на небі війна: Михаїл та його анголи́ вчинили зо змієм війну́. І змій воював та його анголи,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 8, 'та не втрималися, і вже не знайшлося їм місця на небі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 9, 'І ски́нений був змій великий, вуж стародавній, що зветься диявол і сатана́, що зво́дить світ, і скинений був він додолу, а з ним і його анголи́ були скинені.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 10, 'І я почув гучний голос на небі, який говорив: „Тепер настало спасі́ння, і сила, і царство нашого Бога, і вла́да Христа Його, бо скинений той, хто братів наших ска́ржив, хто перед нашим Богом оска́ржував їх день і ніч!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 11, 'І вони його перемогли кров\'ю Агнця та словом свого засві́дчення, і не полюбили життя свого навіть до смерти!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 12, 'Через це звесели́ся ти, небо, та ті, хто на нім пробуває! Горе землі та морю, до вас бо диявол зійшов, маючи лютість велику, знаючи, що короткий час має!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 13, 'А коли змій побачив, що додолу він ски́нений, то став переслі́дувати жінку, що вродила хлоп\'я́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 14, 'І жінці да́ні були два крила великого орла, щоб від змі́я летіла в пустиню до місця свого, де будуть її годувати час, і часи́, і півча́су.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 15, 'I пустив змій за жінкою з уст своїх во́ду, як рі́чку, щоб річка схопи́ла її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 16, 'Та жінці земля помогла, — і розкрила земля свої у́ста, та й випила річку, яку змій пустив із своїх уст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 17, 'І змій розлютува́вся на жінку, і пішов воювати з останком насіння її, що вони бережуть Божі заповіді та мають свідо́цтво Ісусове.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 12, 18, 'І я став на морсько́му піску́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 1, 'І я бачив звіри́ну, що виходила з моря, яка мала десять ро́гів та сім голів, а на ро́гах її було десять вінці́в, а на її го́ловах богознева́жні імена́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 2, 'А звіри́на, що я її бачив, подібна до ри́ся була́, а но́ги її — як ведме́жі, а паща її — немов ле́в\'яча паща. І змій дав їй свою силу, і престола свого́, і вла́ду велику.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 3, 'А одна з її голів була ніби забита на смерть, але рана смерте́льна її вздоро́вилась. І вся земля дивувалась, слідкуючи за звіри́ною!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 4, 'І вклонилися змієві, що дав вла́ду звіри́ні. І вклонились звірині, говорячи: „Хто до звіри́ни подібний, і хто воювати з нею може?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 5, 'І їй да́но уста, що говорили зухва́ле та богознева́жне. І їй да́но вла́ду ді́яти сорок два місяці.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 6, 'І відкрила вона свої у́ста на зневагу проти Бога, щоб богозневажа́ти Ім\'я́ Його й оселю Його, та тих, хто на небі живе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 7, 'І їй да́но прова́дити війну зо святими, та їх перемогти. І їй да́на вла́да над кожним племенем, і наро́дом, і язи́ком, і людом.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 8, 'І їй вкло́няться всі, хто живе на землі, що їхні імена не написані в книгах життя Агнця, зако́леного від закла́дин світу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 9, 'Коли має хто вухо, нехай слухає:');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 10, 'Коли хто до поло́ну веде́, — сам пі́де в поло́н. Коли хто мечем убиває, — такий мусить сам бути вбитий мече́м! Отут терпеливість та віра святих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 11, 'І бачив я іншу звіри́ну, що вихо́дила з землі. І вона мала два роги, подібні ягня́чим, та говорила, як змій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 12, 'І вона виконувала всю вла́ду першої звіри́ни перед нею, і робила, щоб земля та ті, хто живе на ній, вклонилися першій звіри́ні, що в неї вздоро́влена була її рана смерте́льна.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 13, 'І чинить вона великі ознаки, так що й огонь зводить з неба додолу перед людьми́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 14, 'І зводить вона ме́шканців землі через ознаки, що їх да́но їй чинити перед звіри́ною, намовляючи ме́шканців землі зробити о́браза звіри́ни, що має рану від меча, та живе.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 15, 'І да́но їй вкла́сти духа о́бразові звіри́ни, щоб заговорив образ звірини, і зробити, щоб усі, хто не покло́ниться о́бразові звіри́ни, побиті були́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 16, 'І зробить вона, щоб усім — малим і великим, багатим і вбогим, вільним і рабам — було да́но знаме́но на їхню прави́цю або на їхні чо́ла,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 17, 'щоб ніхто не міг ані купити, ані продати, якщо він не має знаме́на ймення звіри́ни, або числа ймення його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 13, 18, 'Тут мудрість! Хто має розум, нехай порахує число звірини, бо воно число лю́дське. А число її — шістсот шістдеся́т шість.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 1, 'І я глянув, — і ось Агнець стоїть на Сіонській горі, а з Ним сто сорок чотири тисячі, що мають Ім\'я́ Його й Ім\'я́ Отця Його, написане на своїх чо́лах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 2, 'І почув я голос із неба, немов шум великої води, і немов гук міцно́го грому. І почув я голос гуслярі́в, що грали на гу́слах своїх,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 3, 'і співали, як пісню нову́ перед престолом і перед чотирьома́ тваринами й ста́рцями. І ніхто не міг навчитися пісні, окрім цих ста сорока чотирьох тисяч, ви́куплених від землі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 4, 'Це ті, хто не оскверни́вся з жінками, бо чисті вони. Вони йдуть за Агнцем, куди Він іде. Вони ви́куплені від людей, пе́рвістки Богові й Агнцеві,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 5, 'не знайшлося бо пі́дступу в їхніх уста́х, бо вони непорочні!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 6, 'І побачив я іншого ангола, що летів серед неба, і мав благовісти́ти вічну Єва́нгелію ме́шканцям землі, і кожному людові, і племені, і язи́ку, і наро́дові.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 7, 'І він говорив гучним голосом: „Побійтеся Бога та славу віддайте Йому, бо настала година суду Його, і вклоніться Тому, Хто створи́в небо, і землю, і море, і водні джере́ла!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 8, 'А інший, другий ангол леті́в слідо́м і казав: „Упав, упав Вавило́н, місто великий, бо лютим вином розпусти своєї він напоїв усі наро́ди!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 9, 'А інший, третій а́нгол летів услід за ним, гучним голосом кажучи: „Коли хто вклоняється звіри́ні та о́бразу її, і приймає знаме́но на чолі́ своїм чи на руці своїй,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 10, 'то той питиме з вина Божого гніву, вина незмішаного в чаші гніву Його, і буде му́чений в огні й сірці перед ангола́ми святими та перед А́гнцем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 11, 'А дим їхніх мук підійматиметься вічні віки́. І не мають споко́ю день і ніч усі ті, хто вклоняється звіри́ні та о́бразу її, і приймає знаме́но йме́ння його“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 12, 'Тут терпеливість святих, що доде́ржують заповіді Божі та Ісусову віру!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 13, 'І почув я голос із неба, що до мене казав: „Напиши: Блаженні ті мертві, хто з цього ча́су вмирає в Господі! Так, каже Дух, — вони від праць своїх заспоко́яться, бо їхні діла йдуть за ними слідо́м“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 14, 'І я глянув, — і ото біла хмара, а на хмарі сидить подібний до Лю́дського Сина. Він мав на Своїй голові золотого вінця́, а в руці Його гострий серп.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 15, 'І інший ангол вийшов із храму, і гучним голосом кликнув до Того, Хто на хмарі сидів: „Пошли серпа свого й жни, бо настала година пожати, дозріло бо жни́во землі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 16, 'I Той, Хто на хмарі сидів, скинув додолу серпа свого, — і земля була вижата.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 17, 'І інший Ангол вийшов із храму, що на небі, — і він мав гострого серпа.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 18, 'І інший ангол, що мав вла́ду над огнем, вийшов від же́ртівника. І він гучним голосом кли́кнув до того, що мав гострого серпа, говорячи: „Пошли свого гострого серпа, і позбирай гро́на зе́мної виноградини, бо гро́на її вже доспіли“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 19, 'І ангол кинув додо́лу серпа свого, і зібрав виноград на землі, і вкинув в велике чави́ло Божого гніву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 14, 20, 'І пото́вчене було чави́ло за містом, і потекла кров із чави́ла аж до кі́нських вузде́чок, на тисячу шістсот стадій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 1, 'І бачив я інше знаме́но на небі, велике та дивне, — сім анголі́в, що сім кар вони мали, бо ними кінча́вся гнів Божий.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 2, 'І я бачив щось, ніби як море скляне́, з огнем перемішане. А ті, що перемогли́ звіри́ну та о́браза його, і знаме́но його, і число його ймення, — стояли на морі склянім, та мали гу́сла Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 3, 'І співали вони пісню Мойсея, раба Божого, і пісню Агнця, говорячи: „Великі та дивні діла Твої, о Господи, Боже Вседержи́телю! Справедливі й правдиві дороги Твої, о Ца́рю святих!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 4, 'Хто́ Тебе, Господи, не побоїться, та Йме́ння Твого не просла́вить? Бо один Ти святий, бо наро́ди всі при́йдуть та вкло́няться перед Тобою, бо з\'явилися су́ди Твої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 5, 'А по цьому я глянув, — і ось відчинився храм ски́нії сві́дчення в небі,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 6, 'і сім анголі́в вийшли з храму, і сім кар вони мали. Вони були вдягнені в ша́ти льняні́, чисті й ясні́, і підпере́зані довкола грудей золотими пояса́ми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 7, 'І одна з чотирьох тих тварин дала́ сімом ангола́м сім чаш золотих, напо́внених гніву Бога, що живе повік віку.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 8, 'І храм перепо́внився димом від Божої слави, і від сили Його. Та до храму ніхто не спромігся ввійти, аж поки не скінчи́лися ті сім кар сімох а́нголів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 15, 9, '');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 1, 'І я почув гучний голос із храму, що казав до семи анголів: „Ідіть, і вилийте на землю сім чаш гніву Божого!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 2, 'I пішов перший ангол, і вилив на землю чашу свою. І шкідливі та люті болячки обсіли людей, хто мав знаме́но звіри́ни й вклонявсь її о́бразу.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 3, 'А другий ангол вилив свою чашу до моря. І сталася кров, немов у мерця́, — і кожна істота жива вмерла в морі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 4, 'Третій же ангол вилив чашу свою на річки́ та на водні джере́ла, — і сталася кров.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 5, 'І почув я ангола вод, який говорив: „Ти праведний, що Ти є й що Ти був, і святий, що Ти це присудив!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 6, 'Бо вони пролили́ кров святих та пророків, — і Ти дав їм напитися крови. Вони варті того!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 7, 'І я чув, як же́ртівник говорив: „Так, Господи, Боже Вседержи́телю! Правдиві й справедливі суди Твої!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 8, 'А ангол четвертий вилив свою чашу на сонце. І да́но йому палити людей огнем.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 9, 'І спека велика палила людей, і зневажа́ли вони Ім\'я Бога, що має вла́ду над карами тими, — і вони не покаялися, щоб славу віддати Йому́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 10, 'А п\'ятий ангол вилив чашу свою на престола звіри́ни. І затьми́лося царство її, і люди від болю кусали свої язики́,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 11, 'і Бога Небесного вони зневажа́ли від болю свого й від своїх болячо́к, — та в учинках своїх не пока́ялись!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 12, 'Шостий же ангол вилив чашу свою на річку велику Ефра́т, — і вода її висохла, щоб пригото́вити дорогу царям, які від схід сонця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 13, 'І я бачив, що вихо́дили з уст змі́я, і з уст звіри́ни, і з уст неправдивого пророка три ду́хи нечисті, як жа́би, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 14, 'це духи де́монські, що чинять озна́ки. Вони виходять до царів усього світу, щоб зібрати їх на війну того великого дня Вседержителя Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 15, 'Ось іду, немов злодій! Блаженний, хто чуйни́й, і одежу свою береже, щоб наги́м не ходити, і щоб не бачили га́ньби його!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 16, 'І зібрав їх на місце, яке по-єврейському зветься Армагеддо́н.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 17, 'Сьомий же ангол вилив чашу свою на повітря. І голос гучни́й залунав від небесного храму з престолу, говорячи: „Сталося!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 18, 'I сталися бли́скавки й гу́ркіт та гро́ми, і сталось велике трясі́ння землі, якого не було́, відко́ли люди́на живе на землі. Великий такий землетру́с, такий міцний!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 19, 'І місто велике розпа́лося на три частини, і попадали лю́дські міста́. І великий Вавилон був згаданий перед Богом, щоб дати йому чашу вина Його лютого гніву.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 20, 'І зник кожен о́стрів, і не зна́йдено гір!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 16, 21, 'І великий град, як важкі тягарі́, падав із неба на людей. І люди зневажали Бога за покара́ння градом, — бо кара Його була дуже велика!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 1, 'І прийшов один із семи анголі́в, що мають сім чаш, і говорив зо мною, ка́жучи: „Підійди, — я покажу́ тобі засу́дження великої розпусниці, що сидить над багатьма во́дами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 2, 'З нею розпусту чинили зе́мні царі, і вином розпусти її впивались ме́шканці землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 3, 'І в дусі повів він мене на пустиню. І побачив я жінку, що сиділа на червоній звіри́ні, переповненій імена́ми богознева́жними, яка мала сім голів і десять ро́гів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 4, 'А жінка була одягнена в порфіру й кармази́н, і приоздо́блена золотом і дорогоцінним камі́нням та пе́рлами. У руці своїй мала вона золоту чашу, повну гидо́ти та не́чести розпусти її.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 5, 'А на чолі́ її було написане ім\'я́, таємниця: „Великий Вавилон, — мати розпусти й гидо́ти землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 6, 'І бачив я жінку, п\'яну́ від крови святих і від крови мучеників Ісусових, і, бачивши її, дивува́вся я дивом великим.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 7, 'А ангол промовив до мене: „Чого ти диву́єшся? Я скажу́ тобі таємницю жінки й звірини, яка носить її, яка має сім голів і десять ро́гів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 8, 'Звіри́на, яку бачив я, була — і нема, і має вийти з безо́дні — і пі́де вона на погибіль. А ме́шканці землі, що їхні імена не записані в книгу життя від закла́дин світу, дивуватися будуть, як побачать, що звіри́на була — і нема, і з\'я́виться.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 9, 'Тут розум, що має він мудрість. Сім голів — це сім гір, що на них сидить жінка. І сім царів, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 10, 'п\'ять їх упало, один є, другий іще не прийшов, а як при́йде, то мусить він трохи пробути.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 11, 'І звіри́на, що була́ — і нема, і вона — сама во́сьма й з сімох, і йде на погибіль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 12, 'А десять тих рогів, що бачив ти їх, — то десять царів, що ще не прийняли́ царства, але при́ймуть вла́ду царську́ із звіри́ною на одну годину.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 13, 'Вони мають одну думку, а силу та вла́ду свою віддадуть звіри́ні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 14, 'Вони воюватимуть проти Агнця та Агнець переможе їх, бо Він — „Господь над панами та Цар над царями“. А ті, хто з Ним, покликані, і вибрані, і вірні“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 15, 'І говорить до мене: „Во́ди, що бачив ти їх, де сидить та розпу́сниця, то наро́ди та люди, і племе́на та язи́ки.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 16, 'А десять рогів, що ти бачив їх, та звіри́на, — вони знена́видять розпусницю, спусто́шать її й обнажа́ть, і з\'їдять її тіло, і огнем її спалять.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 17, 'Бо Бог дав їм до серця, щоб волю чинили Його, маючи одну думку, і щоб царство своє віддали́ звіри́ні, аж поки не ви́повняться слова́ Божі.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 17, 18, 'А жінка, яку ти бачив, то місто велике, що панує над царями земними“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 1, 'Після цього побачив я іншого ангола, що схо́див із неба, і що вла́ду велику він мав. І земля освітилась від слави його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 2, 'І він гучним голосом кликнув, говорячи: „Упав, упав великий Вавилон! Став він оселею де́монів, і схо́вищем усякому ду́хові нечистому, і схо́вищем усіх пта́хів нечистих та нена́видних,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 3, 'бо лютим вином розпусти своєї він напоїв всі наро́ди! І зе́мні царі з ним розпусту чинили, а земні купці збагатіли від сили розко́ші його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 4, 'І почув я інший голос із неба, який говорив: „Вийдіть із нього, люди мої, щоб не сталися ви спільника́ми гріхів його, і щоб не потра́пили в кара́ння його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 5, 'Гріхи бо його досягли́ аж до неба, і Бог згадав про неправди його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 6, 'Відплатіть ви йому, як і він вам платив, і вдвоє подвойте йому за вчинки його! Удвоє налийте до чаші, що нею він вам наливав!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 7, 'Скільки він сла́вив себе та розкошува́в, стільки му́ки та смутку завдайте йому! Бо в серці своєму гово́рить: „Сиджу́, як цариця, і я не вдова, і бачити смутку не бу́ду!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 8, 'Через це одного дня при́йдуть кари його, смерть, і плач, і голод, і спа́лений буде огнем, бо міцни́й Господь, Бог, що судить його!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 9, 'І будуть плакати та голосити за ним царі земні, що з ним розпусту чинили та розкошува́ли, коли побачать дим пожежі його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 10, 'Вони через страх його мук стоятимуть зда́лека та говоритимуть: „Горе, горе, о місто велике, Вавилоне, місто могутнє, бо суд твій прийшов однієї години!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 11, 'І земні купці́ будуть плакати та голосити за ним, бо ніхто не купує вже їхнього вантажу́, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 12, 'вантажу́ золота, і срі́бла, і камі́ння дорогоцінного, і пе́рел, і віссо́ну, і порфі́ри, і шовку, і кармази́ну, і всякого дерева запашно́го, і всякого по́суду з слоно́вої кости, і всякого по́суду з дорогоцінного дерева, і мідяного, і залізного, і мармуро́вого,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 13, 'і кори́ці, і шафра́ну, і па́хощів, і мирри, і лива́ну, і вина, і оливи, і тонко́ї муки́, і пшениці, і товару, і овець, і ко́ней, і возів, і рабів, і душ лю́дських.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 14, 'І плоди́ пожадли́вости душі твоєї відійшли від тебе, і все сите та світле пропало для тебе, — і вже їх ти не зна́йдеш!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 15, 'Купці цими реча́ми, що вони збагати́лися з нього, від стра́ху мук його стануть здалека, і бу́дуть плакати та голосити,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 16, 'і казати: „Горе, горе, місто велике, зодягнене в віссо́н і порфіру та в кармази́н, і прикрашене золотом і дорогоцінним камі́нням та пе́рлами,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 17, 'бо за одну годину згинуло таке велике багатство“. І кожен стерни́к, і кожен, хто пливає на кораблях, і моряки, і всі, хто працює на морі, — стали здалека,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 18, 'і, бачивши дим від пожежі його, кричали й казали: „Котре до великого міста подібне?“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 19, 'І вони поси́пали по́рохом го́лови свої, і закричали, пла́чучи та голо́сячи, і ка́жучи: „Горе, горе, місто велике, що в ньому з його дорогоцінностей збагати́лися всі, хто має кораблі на морі, бо за одну годину воно спорожні́ло!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 20, 'Радій з цього, небо, і святі апо́столи та пророки, бо Бог виконав суд ваш над ним!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 21, 'І один сильний ангол узяв великого каменя, як жо́рно, і кинув до моря, говорячи: „З таким розго́ном буде кинений Вавило́н, місто велике, — і вже він не зна́йдеться!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 22, 'І голос гуслярі́в, і співакі́в, і сопі́льників, і сурмачі́в уже не буде чутий в тобі! І вже не зна́йдеться в тобі жодного мистця́ й ніякого мисте́цтва, і шум жо́рен уже не буде чутий в тобі!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 23, 'І світло свічника́ вже не буде світити в тобі, і голос молодого й молодої вже не буде чутий в тобі. Бо купці твої були зе́мні вельможі, бо твоїм ворожби́тством були зведені всі наро́ди!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 18, 24, 'Бо в нім зна́йдена кров пророків, і святих, і побитих усіх на землі“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 1, 'По цьому почув я на́че гучни́й голос великого на́товпу в небі, який говорив: „Алілу́я! Спасі́ння, і слава, і сила Господе́ві нашому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 2, 'правдиві бо та справедливі суди́ Його, бо Він засудив ту велику розпусницю, що землю зіпсула своєю розпустою, і помстив за кров Своїх рабів з її рук!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 3, 'І вдруге сказали вони: „Алілуя! І з неї дим виступає на вічні віки!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 4, 'І попа́дали двадцять чотири ста́рці й чотири твари́ни, і поклонилися Богові, що сидить на престолі, говорячи: „Амінь, алілуя!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 5, 'А від престолу вийшов голос, що кли́кав: „Хваліть Бога нашого, усі раби Його, і всі, хто боїться Його, і малі, і великі!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 6, 'І почув я ніби голос великого на́товпу, і на́че шум великої води, і мов голос громів гучних, що вигукували: „Алілуя, бо запанував Господь, наш Бог Вседержи́тель!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 7, 'Радіймо та тішмося, і даймо славу Йому́, бо весі́лля Агнця настало, і жона Його себе приготува́ла!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 8, 'І їй да́но було зодягнутися в чистий та світлий вісо́н, бо вісо́н — то праведність святих.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 9, 'І сказав він мені: „Напиши: Блаженні покликані на весільну вечерю Агнця!“І сказав він мені: „Це правдиві Божі слова!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 10, 'І я впав до його ніг, щоб вклонитись йому. А він каже мені: „Таж ні! Я співслуга твій та братів твоїх, хто має засві́дчення Ісусове, — Богові вклонися!“Бо засві́дчення Ісусове, — то дух пророцтва.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 11, 'І побачив я небо відкрите. І ось білий кінь, а Той, Хто на ньому сидів, зветься Вірний і Правдивий, і Він праведно судить і воює.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 12, 'Очі Його — немов по́лум\'я огняне́, а на голові Його — багато вінців. Він ім\'я́ мав написане, якого не знає ніхто, тільки Він Сам.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 13, 'I зодя́гнений був Він у шату, покра́шену кров\'ю. А Йому на ім\'я: Слово Боже.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 14, 'А війська́ небесні, зодягнені в білий та чистий вісо́н, їхали вслід за Ним на білих ко́нях.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 15, 'А з Його уст виходив гострий меч, щоб ним бити наро́ди. І Він па́стиме їх залізним жезлом, і Він буде топтати чави́ло вина лютого гніву Бога Вседержи́теля!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 16, 'I Він має на шаті й на сте́гнах Своїх написане ймення: „Цар над царями, і Господь над панами“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 17, 'І бачив я одного ангола, що на сонці стояв. І він гучним голосом кли́кнув, ка́жучи до всіх птахів, що серед неба літали: „Ходіть, — і зберіться на велику Божу вечерю,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 18, 'щоб ви їли тіла царів, і тіла ти́сячників, і тіла сильних, і тіла ко́ней і тих, хто сидить на них, і тіла всіх вільних і рабів, і мали́х, і великих“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 19, 'І я побачив звіри́ну, і зе́мних царів, і війська́ їхні, зібрані, щоб учинити війну з Тим, Хто сидить на коні, та з ві́йськом Його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 20, 'І схо́плена була звіри́на, а з нею неправдивий пророк, що ознаки чинив перед нею, що ними звів тих, хто знаме́но звіри́ни прийняв і поклонився був о́бразові її. Обоє вони були вкинені живими до огняно́го озера, що сіркою горіло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 19, 21, 'А решта побита була мечем Того, Хто сидів на коні, що виходив із уст Його. І все пта́ство наїлося їхніми трупами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 1, 'І бачив я ангола, що схо́див із неба, що мав ключа від безодні, і кайда́ни великі в руці своїй.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 2, 'І схопи́в вій змі́я, вужа́ стародавнього, що диявол він і сатана́, і зв\'язав його на тисячу ро́ків, —');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 3, 'та й кинув його до безо́дні, і замкнув його, і печатку над ним поклав, щоб наро́ди не зво́див уже, аж поки не скі́нчиться тисяча ро́ків. А по цьо́му він розв\'я́заний буде на короткий час.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 4, 'І бачив я престоли та тих, хто сидів на них, — і суд їм був да́ний, — і душі стятих за сві́дчення про Ісуса й за Слово Боже, які не вклонились звіри́ні, ані о́бразові її, і не прийняли́ знаме́на на чо́ла свої та на руку свою. І вони ожили́, і царювали з Христом тисячу ро́ків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 5, 'А інші померлі не ожили́, аж поки не скі́нчиться тисяча ро́ків. Це перше воскресі́ння.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 6, 'Блаженний і святий, хто має частку в першому воскресі́нні! Над ними друга смерть не матиме вла́ди, але вони будуть священиками Бога й Христа, і царюватимуть з Ним тисячу ро́ків.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 7, 'Коли ж скінчиться тисяча ро́ків, сатана́ буде ви́пущений із в\'язниці своєї.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 8, 'І ви́йде він зво́дити наро́ди, що вони на чотирьох края́х землі, Ґо́ґа й Маґо́ґа, щоб зібрати їх до бо́ю, а число їхнє — як мо́рський пісок.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 9, 'І вийшли вони на ширину́ землі, і оточи́ли та́бір святих та улю́блене місто. І зійшов огонь з неба, — і пожер їх.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 10, 'А диявол, що зво́див їх, був укинений в озеро огняне́ та сірча́не, де звіри́на й пророк неправдивий. І мучені будуть вони день і ніч на вічні віки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 11, 'І я бачив престола великого білого, і Того, Хто на ньому сидів, що від лиця Його втекла земля й небо, і місця для них не знайшло́ся.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 12, 'І бачив я мертвих малих і великих, що стояли перед Богом. І розгорну́лися книги, і розгорнулась інша книга, — то книга життя. І су́джено мертвих, як написано в книгах, за вчинками їхніми.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 13, 'І дало́ море мертвих, що в ньому, і смерть і ад дали мертвих, що в них, — і су́джено їх згідно з їхніми вчинками.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 14, 'Смерть же та ад були вкинені в озеро огняне́. Це друга смерть, — озеро огняне́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 20, 15, 'А хто не знайшовся написаний в книзі життя, той уки́нений буде в озеро огняне́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 1, 'І бачив я небо нове́ й нову́ землю, перше бо небо та перша земля проминули, і моря вже не було́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 2, 'І я, Іван, бачив місто святе, Нови́й Єрусали́м, що схо́див із неба від Бога, що був пригото́ваний, як неві́ста, прикра́шена для чоловіка свого.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 3, 'I почув я гучний голос із престолу, який кли́кав: „Оце́ оселя Бога з людьми́, і Він житиме з ними! Вони бу́дуть наро́дом Його, і Сам Бог буде з ними“,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 4, '„і Бог кожну сльозу з очей їхніх зітре́“, і не буде вже смерти. Ані смутку, ані крику, ані болю вже не бу́де, бо перше минулося!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 5, 'І сказав Той, Хто сидить на престолі: „Ось нове́ все творю́!“І говорить: „Напиши, що слова́ ці правдиві та вірні!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 6, 'І сказав Він мені: „Сталося! Я Альфа й Оме́га, Поча́ток і Кінець. Хто прагне, тому дармо Я дам від джере́ла живої води.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 7, 'Переможець наслідить усе, і Я бу́ду Богом для нього, а він Мені буде за сина!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 8, 'А лякливим, і невірним, і мерзки́м, і душогубам, і розпусникам, і чарівника́м, і ідоля́нам, і всім неправдомовцям, — їхня частина в озері, що горить огнем та сіркою“, а це — друга смерть!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 9, 'І прийшов до мене один із семи анголі́в, що мають сім чаш, напо́внених сімома́ останніми карами, та й промовив до мене, говорячи: „Ходи, покажу́ я тобі невісту, жону Агнця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 10, 'І заніс мене духом на го́ру велику й високу, і місто велике мені показав, — святий Єрусали́м, що сходив із неба від Бога.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 11, 'Славу Божу він має. А світлість його подібна до каменя дорогоцінного, як каменя я́списа, що блищить, як кришта́ль.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 12, 'Мур воно мало великий і високий, мало дванадцять брам, а на брамах дванадцять анголів та ймення написані, а вони — імення дванадцятьо́х племе́н синів Ізраїля.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 13, 'Від схо́ду три брами, і від пі́вночі три брами, і від півдня три брами, і від захо́ду три брами.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 14, 'І міськи́й мур мав дванадцять підвалин, а на них дванадцять імен дванадцяти апо́столів Агнця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 15, 'А той, хто зо мною говорив, мав міру, — золоту трости́ну, щоб змі́ряти місто, і брами його і його мур.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 16, 'А місто чотирикутне, а довжина́ його така, як і ширина́. І він зміряв місто трости́ною на дванадцять тисяч стадій; довжина́, і ширина́, і вишина́ його рівні.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 17, 'І зміряв він мура його на сто сорок чотири лі́кті міри лю́дської, яка й міра ангола.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 18, 'Його мур був збудо́ваний з я́спису, а місто було — щире золото, подібне до чистого скла.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 19, 'Підвалини муру місько́го прикра́шені були всяким дорогоцінним камі́нням. Перша підва́лина — я́спис, друга — сапфі́р, третя — халкидо́н, четверта — смара́гд,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 20, 'п\'ята — сардо́нікс, шоста — са́рдій, сьома — хризолі́т, восьма — бери́л, дев\'ята — топа́з, десята — хрисопра́с, одинадцята — яки́нт, дванадцята — амети́ст.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 21, 'А дванадцять брам — то дванадцять перли́н, і кожна брама зокре́ма була́ з однієї перли́ни. А вулиці міста — щире золото, прозо́рі, як скло.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 22, 'А храму не бачив я в ньому, бо Госпо́дь, Бог Вседержи́тель — то йому храм і Агнець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 23, 'І місто не має потреби ні в сонці, ні в місяці, щоб у ньому світили, — слава бо Божа його освітила, а світильник для нього — А́гнець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 24, 'І наро́ди ходитимуть у світлі його, а зе́мні царі принесу́ть свою славу до нього.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 25, 'А брами його зачиня́тись не бу́дуть удень, бо там но́чі не бу́де.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 26, 'І принесу́ть до нього славу й честь наро́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 21, 27, 'І не вві́йде до нього ніщо нечисте, ані той, хто чинить гидо́ту й неправду, але тільки ті, хто записаний у книзі життя Агнця“.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 1, 'І показав він мені чисту ріку́ живої води, ясну́, мов кришта́ль, що випливала з престолу Бога й Агнця.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 2, 'Посеред його вулиці, і по цей бік і по той бік ріки́ — дерево життя, що родить дванадцять раз плоди, кожного місяця прино́сячи плід свій. А листя дерев — на вздоро́влення наро́дів.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 3, 'І жодного прокля́ття більше не бу́де. І бу́де в ньому престол Бога та Агнця, а раби Його будуть служити Йому,');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 4, 'і побачать лице Його, а Ймення Його — на їхніх чо́лах.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 5, 'А но́чі вже більше не бу́де, і не бу́де потреби в світлі світильника, ані в світлі сонця, бо освітлює їх Господь, Бог, а вони царюватимуть вічні віки́.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 6, 'І сказав він до мене: „Це вірні й правдиві слова, — а Госпо́дь, Бог ду́хів пророчих, послав Свого а́нгола, щоб він показав своїм рабам, що́ незаба́ром статися мусить.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 7, 'Ото, незаба́ром прихо́джу. Блаженний, хто зберігає пророчі слова цієї книги!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 8, 'І я, Іван, чув і бачив оце. А коли я почув та побачив, я впав до ніг ангола, що мені це показував, щоб вклонитись йому.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 9, 'І сказав він до мене: „Таж ні! Бо я співслуга твій і братів твоїх пророків, і тих, хто зберігає слова цієї книги. Богові вклонися!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 10, 'І сказав він до мене: „Не запеча́туй слів пророцтва цієї книги. Час бо близьки́й!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 11, 'Неправедний — хай чинить неправедні́сть ще, і поганий — хай ще опога́нюється. А праведний — хай ще чинить праведність, а святий — нехай ще освячується!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 12, 'Ото, незаба́ром прихо́джу, і зо Мною заплата Моя, щоб кожному віддати згідно з діла́ми його.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 13, 'Я Альфа й Оме́га, Перший і Останній, Поча́ток і Кінець.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 14, 'Блаженні, хто випере ша́ти свої, щоб мати право на дерево життя, і ввійти бра́мами в місто!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 15, 'А поза ним будуть пси, і чарівники́, і розпу́сники, і душогуби, і ідоля́ни, і кожен, хто любить та чинить неправду.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 16, 'Я, Ісус, послав Свого Ангола, щоб засві́дчити вам це у Церква́х. Я корінь і рід Дави́дів, зоря ясна́ і досві́тня!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 17, 'А Дух і неві́ста говорять: „Прийди!“А хто чує, хай каже: „Прийди!“І хто пра́гне, хай при́йде, і хто хоче, хай воду життя бере да́рмо!“');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 18, 'Свідкую я кожному, хто чує слова пророцтва цієї книги: Коли хто до цього додасть що, та накладе́ на нього Бог кари, що написані в книзі оцій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 19, 'А коли хто що віді́йме від слів книги пророцтва цього, то відійме Бог частку його від дерева життя, і від міста святого, що написане в книзі оцій.');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 20, 'Той, Хто свідку́є, говорить оце: „Так, — незаба́ром прийду́!“Амінь. Прийди, Господи Ісусе!');
INSERT INTO `UkrOgienko_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 22, 21, 'Благода́ть Господа нашого Ісуса Христа зо всіма́ вами! Амі́нь.');
